SET local check_function_bodies = off;

CREATE SCHEMA "api";

CREATE SCHEMA "better_supabase";

CREATE SCHEMA "rbac";

CREATE TABLE "better_supabase"."access_requests" (
  "id"             uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"      uuid                     NOT NULL,
  "user_id"        uuid                     NOT NULL,
  "role"           text,
  "target"         text                     NOT NULL DEFAULT 'role'::text,
  "subject_type"   text,
  "subject_id"     text,
  "action"         text,
  "emergency"      boolean                  NOT NULL DEFAULT false,
  "member_id"      uuid,
  "review_verdict" text,
  "review_note"    text,
  "reviewed_by"    uuid,
  "reviewed_at"    timestamp with time zone,
  "previous_role"  text,
  "reason"         text,
  "duration"       interval,
  "approval_id"    uuid,
  "granted_at"     timestamp with time zone,
  "expires_at"     timestamp with time zone,
  "ended_at"       timestamp with time zone,
  "created_at"     timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "access_requests_pkey" PRIMARY KEY (id),
  CONSTRAINT "bsb_access_requests_action_check" CHECK (((length(action) >= 1) AND (length(action) <= 200))),
  CONSTRAINT "bsb_access_requests_duration_check" CHECK (((duration IS NULL) OR (duration > '00:00:00'::interval))),
  CONSTRAINT "bsb_access_requests_reason_check" CHECK (((reason IS NULL) OR (length(reason) <= 2000))),
  CONSTRAINT "bsb_access_requests_review_note_check" CHECK ((length(review_note) <= 2000)),
  CONSTRAINT "bsb_access_requests_review_verdict_check" CHECK ((review_verdict = ANY (ARRAY['justified'::text, 'unjustified'::text]))),
  CONSTRAINT "bsb_access_requests_role_check" CHECK (((length(role) >= 1) AND (length(role) <= 200))),
  CONSTRAINT "bsb_access_requests_subject_id_check" CHECK (((length(subject_id) >= 1) AND (length(subject_id) <= 200))),
  CONSTRAINT "bsb_access_requests_subject_type_check" CHECK (((length(subject_type) >= 1) AND (length(subject_type) <= 200))),
  CONSTRAINT "bsb_access_requests_target_check" CHECK ((target = ANY (ARRAY['role'::text, 'record'::text])))
);

ALTER TABLE "better_supabase"."access_requests"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_account_roles" (
  "tenant_id"  uuid                     NOT NULL,
  "role"       text                     NOT NULL,
  "account_id" uuid                     NOT NULL,
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "accounting_account_roles_pkey" PRIMARY KEY (tenant_id, ROLE),
  CONSTRAINT "bsb_accounting_account_roles_role_check"
    CHECK
    ((role = ANY (ARRAY['receivable'::text, 'payable'::text, 'bank'::text, 'revenue'::text, 'cogs'::text, 'inventory'::text, 'work_in_progress'::text, 'tax_payable'::text,
    'tax_receivable'::text,
    'deferred_revenue'::text,
    'retained_earnings'::text,
    'fx_gain'::text,
    'fx_loss'::text,
    'fixed_asset'::text, 'accumulated_depreciation'::text, 'depreciation_expense'::text, 'disposal_gain'::text, 'disposal_loss'::text, 'expense'::text, 'suspense'::text])))
);

ALTER TABLE "better_supabase"."accounting_account_roles"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_accounts" (
  "id"                  uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"           uuid                     NOT NULL,
  "code"                text                     NOT NULL,
  "name"                text                     NOT NULL,
  "type"                text                     NOT NULL,
  "subtype"             text,
  "parent_id"           uuid,
  "currency"            text,
  "reconcilable"        boolean                  NOT NULL DEFAULT false,
  "normal_side"         text                     NOT NULL DEFAULT 'debit'::text,
  "level"               smallint                 NOT NULL DEFAULT 1,
  "default_tax_code_id" uuid,
  "active"              boolean                  NOT NULL DEFAULT true,
  "archived_at"         timestamp with time zone,
  "created_at"          timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"          timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "accounting_accounts_pkey" PRIMARY KEY (id),
  CONSTRAINT "accounting_accounts_tenant_id_code_key" UNIQUE (tenant_id, code),
  CONSTRAINT "bsb_accounting_accounts_code_check" CHECK (((length(code) >= 1) AND (length(code) <= 50))),
  CONSTRAINT "bsb_accounting_accounts_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "bsb_accounting_accounts_level_check" CHECK ((level >= 1)),
  CONSTRAINT "bsb_accounting_accounts_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "bsb_accounting_accounts_normal_side_check" CHECK ((normal_side = ANY (ARRAY['debit'::text, 'credit'::text]))),
  CONSTRAINT "bsb_accounting_accounts_type_check" CHECK ((type = ANY (ARRAY['asset'::text, 'liability'::text, 'equity'::text, 'income'::text, 'expense'::text])))
);

ALTER TABLE "better_supabase"."accounting_accounts"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_budget_lines" (
  "id"            uuid     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"     uuid     NOT NULL,
  "budget_id"     uuid     NOT NULL,
  "account_id"    uuid     NOT NULL,
  "period_number" smallint NOT NULL,
  "dimensions"    jsonb    NOT NULL DEFAULT '{}'::jsonb,
  "amount"        bigint   NOT NULL,
  CONSTRAINT "accounting_budget_lines_budget_id_account_id_period_number__key" UNIQUE (budget_id, account_id, period_number, dimensions),
  CONSTRAINT "accounting_budget_lines_pkey" PRIMARY KEY (id),
  CONSTRAINT "bsb_accounting_budget_lines_dimensions_check" CHECK ((jsonb_typeof(dimensions) = 'object'::text)),
  CONSTRAINT "bsb_accounting_budget_lines_period_number_check" CHECK (((period_number >= 1) AND (period_number <= 12)))
);

ALTER TABLE "better_supabase"."accounting_budget_lines"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_budgets" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"   uuid                     NOT NULL,
  "name"        text                     NOT NULL,
  "fiscal_year" integer                  NOT NULL,
  "status"      text                     NOT NULL DEFAULT 'draft'::text,
  "created_by"  uuid,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "accounting_budgets_pkey" PRIMARY KEY (id),
  CONSTRAINT "accounting_budgets_tenant_id_fiscal_year_name_key" UNIQUE (tenant_id, fiscal_year, name),
  CONSTRAINT "bsb_accounting_budgets_fiscal_year_check" CHECK (((fiscal_year >= 1900) AND (fiscal_year <= 9999))),
  CONSTRAINT "bsb_accounting_budgets_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "bsb_accounting_budgets_status_check" CHECK ((status = ANY (ARRAY['draft'::text, 'approved'::text, 'archived'::text])))
);

ALTER TABLE "better_supabase"."accounting_budgets"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_dimension_values" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"    uuid                     NOT NULL,
  "dimension_id" uuid                     NOT NULL,
  "code"         text                     NOT NULL,
  "name"         text                     NOT NULL,
  "archived_at"  timestamp with time zone,
  CONSTRAINT "accounting_dimension_values_dimension_id_code_key" UNIQUE (dimension_id, code),
  CONSTRAINT "accounting_dimension_values_pkey" PRIMARY KEY (id),
  CONSTRAINT "bsb_accounting_dimension_values_code_check" CHECK (((length(code) >= 1) AND (length(code) <= 100))),
  CONSTRAINT "bsb_accounting_dimension_values_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200)))
);

ALTER TABLE "better_supabase"."accounting_dimension_values"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_dimensions" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"  uuid                     NOT NULL,
  "key"        text                     NOT NULL,
  "name"       text                     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "accounting_dimensions_pkey" PRIMARY KEY (id),
  CONSTRAINT "accounting_dimensions_tenant_id_key_key" UNIQUE (tenant_id, key),
  CONSTRAINT "bsb_accounting_dimensions_key_check" CHECK ((key ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
  CONSTRAINT "bsb_accounting_dimensions_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200)))
);

ALTER TABLE "better_supabase"."accounting_dimensions"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_entries" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"       uuid                     NOT NULL,
  "journal_id"      uuid                     NOT NULL,
  "fiscal_year"     integer,
  "sequence"        integer,
  "number"          text,
  "entry_date"      date                     NOT NULL,
  "period_id"       uuid,
  "status"          text                     NOT NULL DEFAULT 'draft'::text,
  "reference"       text,
  "source_type"     text,
  "source_id"       text,
  "reverses_id"     uuid,
  "memo"            text,
  "posted_at"       timestamp with time zone,
  "posted_by"       uuid,
  "created_by"      uuid,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "legal_entity_id" uuid,
  CONSTRAINT "accounting_entries_pkey" PRIMARY KEY (id),
  CONSTRAINT "bsb_accounting_entries_check1" CHECK (((status = 'draft'::text) OR ((number IS NOT NULL) AND (period_id IS NOT NULL) AND (posted_at IS NOT NULL)))),
  CONSTRAINT "bsb_accounting_entries_check" CHECK (((source_type IS NULL) = (source_id IS NULL))),
  CONSTRAINT "bsb_accounting_entries_memo_check" CHECK (((memo IS NULL) OR (length(memo) <= 2000))),
  CONSTRAINT "bsb_accounting_entries_reference_check" CHECK (((reference IS NULL) OR (length(reference) <= 200))),
  CONSTRAINT "bsb_accounting_entries_source_type_check" CHECK (((source_type IS NULL) OR (source_type ~ '^[a-z][a-z0-9_]{0,62}$'::text))),
  CONSTRAINT "bsb_accounting_entries_status_check" CHECK ((status = ANY (ARRAY['draft'::text, 'posted'::text, 'reversed'::text])))
);

ALTER TABLE "better_supabase"."accounting_entries"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_entry_lines" (
  "id"              uuid     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"       uuid     NOT NULL,
  "entry_id"        uuid     NOT NULL,
  "position"        smallint NOT NULL DEFAULT 0,
  "account_id"      uuid     NOT NULL,
  "debit"           bigint   NOT NULL DEFAULT 0,
  "credit"          bigint   NOT NULL DEFAULT 0,
  "currency"        text     NOT NULL,
  "amount_currency" bigint   NOT NULL,
  "fx_rate"         numeric,
  "tax_code_id"     uuid,
  "tax_amount"      bigint   NOT NULL DEFAULT 0,
  "party_id"        uuid,
  "dimensions"      jsonb    NOT NULL DEFAULT '{}'::jsonb,
  "description"     text,
  CONSTRAINT "accounting_entry_lines_pkey" PRIMARY KEY (id),
  CONSTRAINT "bsb_accounting_entry_lines_check1" CHECK ((tax_amount <= (debit + credit))),
  CONSTRAINT "bsb_accounting_entry_lines_check" CHECK (((debit = 0) <> (credit = 0))),
  CONSTRAINT "bsb_accounting_entry_lines_credit_check" CHECK ((credit >= 0)),
  CONSTRAINT "bsb_accounting_entry_lines_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "bsb_accounting_entry_lines_debit_check" CHECK ((debit >= 0)),
  CONSTRAINT "bsb_accounting_entry_lines_description_check" CHECK (((description IS NULL) OR (length(description) <= 500))),
  CONSTRAINT "bsb_accounting_entry_lines_dimensions_check" CHECK ((jsonb_typeof(dimensions) = 'object'::text)),
  CONSTRAINT "bsb_accounting_entry_lines_fx_rate_check" CHECK (((fx_rate IS NULL) OR (fx_rate > (0)::numeric))),
  CONSTRAINT "bsb_accounting_entry_lines_tax_amount_check" CHECK ((tax_amount >= 0))
);

ALTER TABLE "better_supabase"."accounting_entry_lines"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_fx_rates" (
  "tenant_id"  uuid                     NOT NULL,
  "base"       text                     NOT NULL,
  "quote"      text                     NOT NULL,
  "on_date"    date                     NOT NULL,
  "rate"       numeric                  NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "accounting_fx_rates_pkey" PRIMARY KEY (tenant_id, base, quote, on_date),
  CONSTRAINT "bsb_accounting_fx_rates_base_check" CHECK ((base ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "bsb_accounting_fx_rates_check" CHECK ((base <> quote)),
  CONSTRAINT "bsb_accounting_fx_rates_quote_check" CHECK ((quote ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "bsb_accounting_fx_rates_rate_check" CHECK ((rate > (0)::numeric))
);

ALTER TABLE "better_supabase"."accounting_fx_rates"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_journals" (
  "id"                 uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"          uuid                     NOT NULL,
  "code"               text                     NOT NULL,
  "name"               text                     NOT NULL,
  "type"               text                     NOT NULL,
  "default_account_id" uuid,
  "currency"           text,
  "contra_account_id"  uuid,
  "bank_account_id"    uuid,
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "legal_entity_id"    uuid,
  CONSTRAINT "accounting_journals_pkey" PRIMARY KEY (id),
  CONSTRAINT "accounting_journals_tenant_id_code_key" UNIQUE (tenant_id, code),
  CONSTRAINT "bsb_accounting_journals_code_check" CHECK ((code ~ '^[A-Z0-9][A-Z0-9_-]{0,15}$'::text)),
  CONSTRAINT "bsb_accounting_journals_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "bsb_accounting_journals_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "bsb_accounting_journals_type_check" CHECK ((type = ANY (ARRAY['sales'::text, 'purchase'::text, 'bank'::text, 'cash'::text, 'general'::text])))
);

ALTER TABLE "better_supabase"."accounting_journals"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_opening_balances" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"   uuid                     NOT NULL,
  "fiscal_year" integer                  NOT NULL,
  "account_id"  uuid                     NOT NULL,
  "party_id"    uuid,
  "amount"      bigint                   NOT NULL,
  "source"      text                     NOT NULL DEFAULT 'imported'::text,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "accounting_opening_balances_pkey" PRIMARY KEY (id),
  CONSTRAINT "bsb_accounting_opening_balances_amount_check" CHECK ((amount <> 0)),
  CONSTRAINT "bsb_accounting_opening_balances_fiscal_year_check" CHECK (((fiscal_year >= 1900) AND (fiscal_year <= 9999))),
  CONSTRAINT "bsb_accounting_opening_balances_source_check" CHECK ((source = ANY (ARRAY['imported'::text, 'carried'::text])))
);

ALTER TABLE "better_supabase"."accounting_opening_balances"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_periods" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"   uuid                     NOT NULL,
  "fiscal_year" integer                  NOT NULL,
  "number"      smallint                 NOT NULL,
  "starts_on"   date                     NOT NULL,
  "ends_on"     date                     NOT NULL,
  "status"      text                     NOT NULL DEFAULT 'open'::text,
  "closed_at"   timestamp with time zone,
  "closed_by"   uuid,
  "locked_at"   timestamp with time zone,
  "locked_by"   uuid,
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "accounting_periods_pkey" PRIMARY KEY (id),
  CONSTRAINT "accounting_periods_tenant_id_fiscal_year_number_key" UNIQUE (tenant_id, fiscal_year, number),
  CONSTRAINT "bsb_accounting_periods_check" CHECK ((ends_on >= starts_on)),
  CONSTRAINT "bsb_accounting_periods_fiscal_year_check" CHECK (((fiscal_year >= 1900) AND (fiscal_year <= 9999))),
  CONSTRAINT "bsb_accounting_periods_number_check" CHECK (((number >= 1) AND (number <= 12))),
  CONSTRAINT "bsb_accounting_periods_status_check" CHECK ((status = ANY (ARRAY['open'::text, 'closed'::text, 'locked'::text])))
);

ALTER TABLE "better_supabase"."accounting_periods"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_recognition_rows" (
  "id"          uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "schedule_id" uuid                     NOT NULL,
  "tenant_id"   uuid                     NOT NULL,
  "due_on"      date                     NOT NULL,
  "amount"      bigint                   NOT NULL,
  "status"      text                     NOT NULL DEFAULT 'pending'::text,
  "entry_id"    uuid,
  "posted_at"   timestamp with time zone,
  CONSTRAINT "accounting_recognition_rows_pkey" PRIMARY KEY (id),
  CONSTRAINT "bsb_accounting_recognition_rows_amount_check" CHECK ((amount > 0)),
  CONSTRAINT "bsb_accounting_recognition_rows_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'posted'::text])))
);

ALTER TABLE "better_supabase"."accounting_recognition_rows"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_recognition_schedules" (
  "id"                uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"         uuid                     NOT NULL,
  "source_type"       text                     NOT NULL,
  "source_id"         text                     NOT NULL,
  "line_ref"          text                     NOT NULL DEFAULT ''::text,
  "amount"            bigint                   NOT NULL,
  "currency"          text                     NOT NULL,
  "starts_on"         date                     NOT NULL,
  "ends_on"           date                     NOT NULL,
  "deferral_entry_id" uuid,
  "created_at"        timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "accounting_recognition_schedu_tenant_id_source_type_source__key" UNIQUE (tenant_id, source_type, source_id, line_ref),
  CONSTRAINT "accounting_recognition_schedules_pkey" PRIMARY KEY (id),
  CONSTRAINT "bsb_accounting_recognition_schedules_amount_check" CHECK ((amount > 0)),
  CONSTRAINT "bsb_accounting_recognition_schedules_check" CHECK ((ends_on >= starts_on)),
  CONSTRAINT "bsb_accounting_recognition_schedules_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "bsb_accounting_recognition_schedules_line_ref_check" CHECK ((length(line_ref) <= 200)),
  CONSTRAINT "bsb_accounting_recognition_schedules_source_id_check" CHECK (((length(source_id) >= 1) AND (length(source_id) <= 200))),
  CONSTRAINT "bsb_accounting_recognition_schedules_source_type_check" CHECK (((length(source_type) >= 1) AND (length(source_type) <= 100)))
);

ALTER TABLE "better_supabase"."accounting_recognition_schedules"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."accounting_settings" (
  "tenant_id"               uuid                     NOT NULL,
  "functional_currency"     text                     NOT NULL,
  "fiscal_year_start_month" smallint                 NOT NULL DEFAULT 1,
  "lock_date"               date,
  "created_at"              timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"              timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "accounting_settings_pkey" PRIMARY KEY (tenant_id),
  CONSTRAINT "bsb_accounting_settings_fiscal_year_start_month_check" CHECK (((fiscal_year_start_month >= 1) AND (fiscal_year_start_month <= 12))),
  CONSTRAINT "bsb_accounting_settings_functional_currency_check" CHECK ((functional_currency ~ '^[A-Z]{3}$'::text))
);

ALTER TABLE "better_supabase"."accounting_settings"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."acknowledgement_assignments" (
  "id"             uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"      uuid                     NOT NULL,
  "subject_type"   text                     NOT NULL,
  "subject_id"     text                     NOT NULL,
  "principal_type" text                     NOT NULL,
  "principal_id"   text                     NOT NULL,
  "due_in_days"    integer,
  "created_at"     timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "acknowledgement_assignments_pkey" PRIMARY KEY (id),
  CONSTRAINT "acknowledgement_assignments_tenant_id_subject_type_subject__key" UNIQUE (tenant_id, subject_type, subject_id, principal_type, principal_id),
  CONSTRAINT "bsb_acknowledgement_assignments_due_in_days_check" CHECK (((due_in_days IS NULL) OR ((due_in_days >= 1) AND (due_in_days <= 365)))),
  CONSTRAINT "bsb_acknowledgement_assignments_principal_id_check" CHECK (((length(principal_id) >= 1) AND (length(principal_id) <= 200))),
  CONSTRAINT "bsb_acknowledgement_assignments_principal_type_check" CHECK ((principal_type = ANY (ARRAY['user'::text, 'team'::text, 'role'::text]))),
  "created_by"     uuid                     DEFAULT auth.uid()
);

ALTER TABLE "better_supabase"."acknowledgement_assignments"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."acknowledgement_notices" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"    uuid                     NOT NULL,
  "subject_type" text                     NOT NULL,
  "subject_id"   text                     NOT NULL,
  "version_id"   uuid                     NOT NULL,
