  CONSTRAINT "acknowledgement_notices_pkey" PRIMARY KEY (id),
  CONSTRAINT "acknowledgement_notices_subject_type_subject_id_version_id__key" UNIQUE (subject_type, subject_id, version_id, user_id)
);

ALTER TABLE "better_supabase"."acknowledgement_notices"
