  CONSTRAINT "acknowledgements_subject_type_subject_id_version_id_user_id_key" UNIQUE (subject_type, subject_id, version_id, user_id),
  CONSTRAINT "bsb_acknowledgements_method_check" CHECK ((method = ANY (ARRAY['click'::text, 'signature'::text])))
);

ALTER TABLE "better_supabase"."acknowledgements"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."activities" (
  "id"                  uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"           uuid                     NOT NULL,
  "type"                text                     NOT NULL,
  "title"               text                     NOT NULL,
  "body"                text,
  "outcome"             text,
  "owner_id"            uuid,
  "due_at"              timestamp with time zone,
  "done_at"             timestamp with time zone,
  "duration_seconds"    integer,
  "external_ref"        text,
  "created_by"          uuid,
  "created_at"          timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"          timestamp with time zone NOT NULL DEFAULT now(),
  "audience"            text                     NOT NULL DEFAULT 'team'::text,
  "restricted_roles"    text[],
  "category"            text,
  "locked_at"           timestamp with time zone,
  "amends_id"           uuid,
  "goal_id"             uuid,
  "marked_error_at"     timestamp with time zone,
  "marked_error_by"     uuid,
  "marked_error_reason" text,
  CONSTRAINT "activities_pkey" PRIMARY KEY (id),
  CONSTRAINT "bsb_activities_audience_check" CHECK ((audience = ANY (ARRAY['team'::text, 'subject'::text, 'restricted'::text]))),
  CONSTRAINT "bsb_activities_category_check" CHECK (((length(category) >= 1) AND (length(category) <= 63))),
  CONSTRAINT "bsb_activities_duration_seconds_check" CHECK ((duration_seconds >= 0)),
  CONSTRAINT "bsb_activities_marked_error_reason_check" CHECK (((length(marked_error_reason) >= 1) AND (length(marked_error_reason) <= 2000))),
  CONSTRAINT "bsb_activities_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 500)))
);

ALTER TABLE "better_supabase"."activities"
