  CONSTRAINT "bsb_ai_messages_metadata_check" CHECK ((jsonb_typeof(metadata) = 'object'::text)),
  CONSTRAINT "bsb_ai_messages_parts_check"
    CHECK
    (((jsonb_typeof(parts) = 'array'::text) AND (NOT jsonb_path_exists(parts,
    '$[*]?(!((((((((@."type" == "text" || @."type" == "reasoning") || @."type" == "file") || @."type" == "tool-call") || @."type" == "tool-result") || @."type" == "tool-approval") || @."type" == "source") || @."type" == "data") || @."type" == "step"))'::jsonpath)))),
  CONSTRAINT "bsb_ai_messages_role_check" CHECK ((role = ANY (ARRAY['system'::text, 'user'::text, 'assistant'::text, 'tool'::text]))),
  CONSTRAINT "bsb_ai_messages_status_check" CHECK ((status = ANY (ARRAY['complete'::text, 'aborted'::text, 'error'::text])))
);

