  "name"        text                                    NOT NULL,
  "code"        text,
  "address"     jsonb                                   NOT NULL DEFAULT '{}'::jsonb,
  "latitude"    double precision,
  "longitude"   double precision,
  "point"       extensions.geography(Point,4326)        GENERATED ALWAYS AS (
CASE
    WHEN (latitude IS NULL) THEN NULL::extensions.geography
    ELSE (extensions.st_setsrid(extensions.st_makepoint(longitude, latitude), 4326))::extensions.geography
END) STORED,
  "area"        extensions.geography(MultiPolygon,4326),
  "metadata"    jsonb                                   NOT NULL DEFAULT '{}'::jsonb,
  "archived_at" timestamp with time zone,
  "created_at"  timestamp with time zone                NOT NULL DEFAULT now(),
  "updated_at"  timestamp with time zone                NOT NULL DEFAULT now(),
  CONSTRAINT "asset_locations_pkey" PRIMARY KEY (id),
  CONSTRAINT "asset_locations_tenant_id_code_key" UNIQUE (tenant_id, code),
  CONSTRAINT "bsb_asset_locations_address_check" CHECK ((jsonb_typeof(address) = 'object'::text)),
  CONSTRAINT "bsb_asset_locations_check" CHECK (((latitude IS NULL) = (longitude IS NULL))),
  CONSTRAINT "bsb_asset_locations_code_check" CHECK (((code IS NULL) OR ((length(code) >= 1) AND (length(code) <= 100)))),
  CONSTRAINT "bsb_asset_locations_kind_check" CHECK ((kind ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
  CONSTRAINT "bsb_asset_locations_latitude_check" CHECK (((latitude >= ('-90'::integer)::double precision) AND (latitude <= (90)::double precision))),
  CONSTRAINT "bsb_asset_locations_longitude_check" CHECK (((longitude >= ('-180'::integer)::double precision) AND (longitude <= (180)::double precision))),
  CONSTRAINT "bsb_asset_locations_metadata_check" CHECK ((jsonb_typeof(metadata) = 'object'::text)),
  CONSTRAINT "bsb_asset_locations_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200)))
);

