CASE
    WHEN (latitude IS NULL) THEN NULL::extensions.geography
    ELSE (extensions.st_setsrid(extensions.st_makepoint(longitude, latitude), 4326))::extensions.geography
END) STORED,
  "metadata"              jsonb                            NOT NULL DEFAULT '{}'::jsonb,
