  CONSTRAINT "bsb_assets_assignee_type_check" CHECK (((assignee_type IS NULL) OR (assignee_type ~ '^[a-z][a-z0-9_-]{0,62}$'::text))),
  CONSTRAINT "bsb_assets_check1" CHECK (((latitude IS NULL) = (longitude IS NULL))),
  CONSTRAINT "bsb_assets_check" CHECK (((assignee_type IS NULL) = (assignee_id IS NULL))),
  CONSTRAINT "bsb_assets_currency_check" CHECK ((currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "bsb_assets_depreciation_method_check" CHECK ((depreciation_method = ANY (ARRAY['none'::text, 'straight_line'::text, 'declining_balance'::text]))),
  CONSTRAINT "bsb_assets_depreciation_rate_bps_check" CHECK (((depreciation_rate_bps >= 1) AND (depreciation_rate_bps <= 100000))),
  CONSTRAINT "bsb_assets_disposal_amount_check" CHECK ((disposal_amount >= 0)),
  CONSTRAINT "bsb_assets_kind_check" CHECK ((kind ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
  CONSTRAINT "bsb_assets_latitude_check" CHECK (((latitude >= ('-90'::integer)::double precision) AND (latitude <= (90)::double precision))),
  CONSTRAINT "bsb_assets_longitude_check" CHECK (((longitude >= ('-180'::integer)::double precision) AND (longitude <= (180)::double precision))),
  CONSTRAINT "bsb_assets_metadata_check" CHECK ((jsonb_typeof(metadata) = 'object'::text)),
  CONSTRAINT "bsb_assets_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "bsb_assets_ownership_check"
    CHECK (((ownership IS NULL) OR (ownership = ANY (ARRAY['customer'::text, 'stock'::text, 'trade_in'::text, 'loan'::text, 'rental'::text])))),
  CONSTRAINT "bsb_assets_residual_value_check" CHECK ((residual_value >= 0)),
  CONSTRAINT "bsb_assets_serial_number_check" CHECK (((serial_number IS NULL) OR (length(serial_number) <= 200))),
  CONSTRAINT "bsb_assets_status_check" CHECK ((status = ANY (ARRAY['active'::text, 'maintenance'::text, 'retired'::text]))),
  CONSTRAINT "bsb_assets_tag_check" CHECK (((tag IS NULL) OR ((length(tag) >= 1) AND (length(tag) <= 100)))),
  CONSTRAINT "bsb_assets_useful_life_months_check" CHECK (((useful_life_months >= 1) AND (useful_life_months <= 1200)))
);

