  CONSTRAINT "bsb_attachments_external_id_check" CHECK (((length(external_id) >= 1) AND (length(external_id) <= 500))),
  CONSTRAINT "bsb_attachments_external" CHECK (((source IS NULL) = (external_id IS NULL))),
