CREATE TABLE "better_supabase"."care_rules" (
  "id"             uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"      uuid                     NOT NULL,
  "kind"           text                     NOT NULL,
  "medication_ids" uuid[]                   NOT NULL DEFAULT '{}'::uuid[],
  "min_dose"       numeric,
  "max_dose"       numeric,
  "max_per_day"    numeric,
  "severity"       text                     NOT NULL DEFAULT 'warning'::text,
  "message"        text,
  "active"         boolean                  NOT NULL DEFAULT true,
  "created_at"     timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"     timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "bsb_care_rules_check" CHECK ((((kind = 'dose_range'::text) AND (cardinality(medication_ids) = 1) AND ((min_dose IS NOT NULL) OR (max_dose IS
    NOT NULL) OR (max_per_day IS
    NOT NULL))) OR ((kind = 'interaction'::text) AND (cardinality(medication_ids) = 2)) OR ((kind = 'duplicate_therapy'::text) AND (cardinality(medication_ids) >= 2)))),
  CONSTRAINT "bsb_care_rules_kind_check" CHECK ((kind = ANY (ARRAY['dose_range'::text, 'duplicate_therapy'::text, 'interaction'::text]))),
  CONSTRAINT "bsb_care_rules_max_dose_check" CHECK (((max_dose IS NULL) OR (max_dose > (0)::numeric))),
  CONSTRAINT "bsb_care_rules_max_per_day_check" CHECK (((max_per_day IS NULL) OR (max_per_day > (0)::numeric))),
  CONSTRAINT "bsb_care_rules_message_check" CHECK (((message IS NULL) OR (length(message) <= 1000))),
  CONSTRAINT "bsb_care_rules_min_dose_check" CHECK (((min_dose IS NULL) OR (min_dose >= (0)::numeric))),
  CONSTRAINT "bsb_care_rules_severity_check" CHECK ((severity = ANY (ARRAY['info'::text, 'warning'::text, 'critical'::text]))),
  CONSTRAINT "care_rules_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."care_rules"
  ENABLE ROW LEVEL SECURITY;

