  "archived_at"                 timestamp with time zone,
  "created_at"                  timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"                  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "bsb_cases_close_note_check" CHECK (((close_note IS NULL) OR (length(close_note) <= 4000))),
  CONSTRAINT "bsb_cases_description_check" CHECK (((description IS NULL) OR (length(description) <= 20000))),
