  CONSTRAINT "bsb_cases_number_check" CHECK (((length(number) >= 1) AND (length(number) <= 100))),
  CONSTRAINT "bsb_cases_rank_check" CHECK (((rank IS NULL) OR (rank ~ '^[0-9A-Za-z]*[1-9A-Za-z]$'::text))),
  CONSTRAINT "bsb_cases_reporter_contact_check" CHECK (((reporter_contact IS NULL) OR (jsonb_typeof(reporter_contact) = 'object'::text))),
  CONSTRAINT "bsb_cases_root_cause_check" CHECK (((root_cause IS NULL) OR (length(root_cause) <= 10000))),
  CONSTRAINT "bsb_cases_severity_check" CHECK (((severity IS NULL) OR ((length(severity) >= 1) AND (length(severity) <= 41)))),
  CONSTRAINT "bsb_cases_source_check" CHECK (((length(source) >= 1) AND (length(source) <= 41))),
  CONSTRAINT "bsb_cases_status_check" CHECK ((status = ANY (ARRAY['open'::text, 'closed'::text, 'canceled'::text]))),
  CONSTRAINT "bsb_cases_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 200))),
