CREATE TABLE "better_supabase"."data_exports" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "subject"      text                     NOT NULL,
  "user_id"      uuid,
  "tenant_id"    uuid,
  "status"       text                     NOT NULL DEFAULT 'pending'::text,
  "bucket"       text                     NOT NULL DEFAULT 'data-exports'::text,
  "files"        text[]                   NOT NULL DEFAULT '{}'::text[],
  "error"        text,
  "requested_at" timestamp with time zone NOT NULL DEFAULT now(),
  "completed_at" timestamp with time zone,
  "expires_at"   timestamp with time zone,
  "subject_type" text,
  "subject_id"   text,
  "format"       text,
  CONSTRAINT "bsb_data_exports_format" CHECK (((format IS NULL) OR (format = ANY (ARRAY['ndjson'::text, 'csv'::text])))),
  CONSTRAINT "bsb_data_exports_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'ready'::text, 'failed'::text]))),
  CONSTRAINT "bsb_data_exports_subject" CHECK (
CASE subject
    WHEN 'user'::text THEN ((user_id IS NOT NULL) AND (tenant_id IS NULL) AND (subject_type IS NULL) AND (subject_id IS NULL))
    WHEN 'organization'::text THEN ((tenant_id IS NOT NULL) AND (user_id IS NULL) AND (subject_type IS NULL) AND (subject_id IS NULL))
    WHEN 'record'::text THEN ((subject_type IS NOT NULL) AND (subject_id IS NOT NULL) AND (user_id IS NULL))
    ELSE false
END),
  CONSTRAINT "data_exports_pkey" PRIMARY KEY (id),
  "requested_by" uuid                     DEFAULT auth.uid()
);

ALTER TABLE "better_supabase"."data_exports"
  ENABLE ROW LEVEL SECURITY;

