  CONSTRAINT "bsb_invoices_dimensions_check" CHECK ((jsonb_typeof(dimensions) = 'object'::text)),
  CONSTRAINT "bsb_invoices_direction_check" CHECK ((direction = ANY (ARRAY['sales'::text, 'purchase'::text]))),
  CONSTRAINT "bsb_invoices_discount_amount_check" CHECK ((discount_amount >= 0)),
  CONSTRAINT "bsb_invoices_discount_amount_early_check" CHECK ((discount_amount_early >= 0)),
  CONSTRAINT "bsb_invoices_discount_bps_check" CHECK (((discount_bps >= 0) AND (discount_bps <= 10000))),
  CONSTRAINT "bsb_invoices_kind_check" CHECK ((kind = ANY (ARRAY['invoice'::text, 'credit_note'::text]))),
  CONSTRAINT "bsb_invoices_status_check" CHECK ((status = ANY (ARRAY['draft'::text, 'issued'::text, 'partially_paid'::text, 'paid'::text, 'void'::text, 'uncollectible'::text]))),
  CONSTRAINT "bsb_invoices_supplier_reference_check" CHECK ((length(supplier_reference) <= 200)),
  CONSTRAINT "bsb_invoices_terms_days_check" CHECK ((terms_days >= 0)),
  CONSTRAINT "bsb_invoices_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 300))),
