CREATE TABLE "better_supabase"."passes" (
  "id"           uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"    uuid                     NOT NULL,
  "kind"         text                     NOT NULL DEFAULT 'ticket'::text,
  "holder_id"    uuid,
  "holder_name"  text,
  "holder_email" text,
  "subject_type" text,
  "subject_id"   text,
  "booking_id"   uuid,
  "resource_id"  uuid,
  "uses_allowed" integer,
  "uses"         integer                  NOT NULL DEFAULT 0,
  "starts_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "expires_at"   timestamp with time zone,
  "status"       text                     NOT NULL DEFAULT 'active'::text,
  "nonce"        text                     NOT NULL,
  "issued_by"    uuid,
  "created_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"   timestamp with time zone NOT NULL DEFAULT now(),
  "revoked_at"   timestamp with time zone,
  CONSTRAINT "bsb_passes_check1" CHECK (((uses_allowed IS NULL) OR (uses <= uses_allowed))),
  CONSTRAINT "bsb_passes_check2" CHECK (((expires_at IS NULL) OR (expires_at > starts_at))),
  CONSTRAINT "bsb_passes_check" CHECK (((subject_type IS NULL) = (subject_id IS NULL))),
  CONSTRAINT "bsb_passes_holder_email_check"
    CHECK (((holder_email IS NULL) OR ((length(holder_email) >= 3) AND (length(holder_email) <= 320) AND (POSITION(('@'::text) IN (holder_email)) > 1)))),
  CONSTRAINT "bsb_passes_holder_name_check" CHECK (((holder_name IS NULL) OR ((length(holder_name) >= 1) AND (length(holder_name) <= 200)))),
  CONSTRAINT "bsb_passes_kind_check" CHECK ((kind ~ '^[a-z][a-z0-9_-]{0,39}$'::text)),
  CONSTRAINT "bsb_passes_status_check" CHECK ((status = ANY (ARRAY['active'::text, 'revoked'::text]))),
  CONSTRAINT "bsb_passes_subject_id_check" CHECK (((subject_id IS NULL) OR ((length(subject_id) >= 1) AND (length(subject_id) <= 200)))),
  CONSTRAINT "bsb_passes_subject_type_check" CHECK (((subject_type IS NULL) OR (subject_type ~ '^[a-z][a-z0-9_-]{0,62}$'::text))),
  CONSTRAINT "bsb_passes_uses_allowed_check" CHECK (((uses_allowed IS NULL) OR (uses_allowed > 0))),
  CONSTRAINT "bsb_passes_uses_check" CHECK ((uses >= 0)),
  CONSTRAINT "passes_nonce_key" UNIQUE (nonce),
  CONSTRAINT "passes_pkey" PRIMARY KEY (id)
);

