CREATE TABLE "better_supabase"."shipments" (
  "id"                  uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"           uuid                     NOT NULL,
  "reference"           text                     NOT NULL,
  "status"              text                     NOT NULL DEFAULT 'draft'::text,
  "from_address"        jsonb                    NOT NULL,
  "to_address"          jsonb                    NOT NULL,
  "direction"           text                     NOT NULL DEFAULT 'outbound'::text,
  "from_location_id"    uuid,
  "subject_type"        text,
  "subject_id"          text,
  "carrier"             text,
  "service"             text,
  "tracking_number"     text,
  "tracking_url"        text,
  "label_id"            text,
  "label_url"           text,
  "label_format"        text,
  "label_cost"          bigint,
  "currency"            text,
  "labeled_at"          timestamp with time zone,
  "delivered_at"        timestamp with time zone,
  "cancelled_at"        timestamp with time zone,
  "created_by"          uuid,
  "created_at"          timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"          timestamp with time zone NOT NULL DEFAULT now(),
  "delivered_to"        text,
  "proof_reference"     text,
  "proof_attachment_id" uuid,
  "proof_recorded_at"   timestamp with time zone,
  CONSTRAINT "bsb_shipments_carrier_check" CHECK (((carrier IS NULL) OR ((length(carrier) >= 1) AND (length(carrier) <= 100)))),
  CONSTRAINT "bsb_shipments_check1" CHECK (((label_cost IS NULL) = (currency IS NULL))),
  CONSTRAINT "bsb_shipments_check2" CHECK (((status = ANY (ARRAY['draft'::text, 'cancelled'::text])) OR ((carrier IS NOT NULL) AND (tracking_number IS NOT NULL)))),
  CONSTRAINT "bsb_shipments_check" CHECK (((subject_type IS NULL) = (subject_id IS NULL))),
  CONSTRAINT "bsb_shipments_currency_check" CHECK (((currency IS NULL) OR (currency ~ '^[A-Z]{3}$'::text))),
  CONSTRAINT "bsb_shipments_direction" CHECK ((direction = ANY (ARRAY['outbound'::text, 'inbound'::text]))),
  CONSTRAINT "bsb_shipments_from_address_check"
    CHECK
    (((jsonb_typeof(from_address) = 'object'::text) AND (COALESCE((from_address ->> 'country'::text), ''::text) ~ '^[A-Z]{2}$'::text) AND (length(btrim(COALESCE((from_address ->>
    'line1'::text), ''::text))) >= 1) AND (length(btrim(COALESCE((from_address ->> 'city'::text), ''::text))) >= 1) AND (length((from_address)::text) <= 4000))),
  CONSTRAINT "bsb_shipments_label_cost_check" CHECK (((label_cost IS NULL) OR (label_cost >= 0))),
  CONSTRAINT "bsb_shipments_label_format_check" CHECK (((label_format IS NULL) OR (label_format = ANY (ARRAY['pdf'::text, 'png'::text, 'zpl'::text])))),
  CONSTRAINT "bsb_shipments_label_id_check" CHECK (((label_id IS NULL) OR ((length(label_id) >= 1) AND (length(label_id) <= 200)))),
  CONSTRAINT "bsb_shipments_label_url_check" CHECK (((label_url IS NULL) OR ((label_url ~ '^https://'::text) AND (length(label_url) <= 2000)))),
  CONSTRAINT "bsb_shipments_reference_check" CHECK (((length(reference) >= 1) AND (length(reference) <= 100))),
  CONSTRAINT "bsb_shipments_service_check" CHECK (((service IS NULL) OR ((length(service) >= 1) AND (length(service) <= 100)))),
  CONSTRAINT "bsb_shipments_status_check"
    CHECK
    ((status = ANY (ARRAY['draft'::text, 'label_created'::text, 'in_transit'::text, 'out_for_delivery'::text, 'delivered'::text, 'exception'::text, 'returned'::text,
    'cancelled'::text]))),
  CONSTRAINT "bsb_shipments_subject_id_check" CHECK (((subject_id IS NULL) OR ((length(subject_id) >= 1) AND (length(subject_id) <= 200)))),
  CONSTRAINT "bsb_shipments_subject_type_check" CHECK (((subject_type IS NULL) OR (subject_type ~ '^[a-z][a-z0-9_-]{0,62}$'::text))),
  CONSTRAINT "bsb_shipments_to_address_check"
    CHECK
    (((jsonb_typeof(to_address) = 'object'::text) AND (COALESCE((to_address ->> 'country'::text), ''::text) ~ '^[A-Z]{2}$'::text) AND (length(btrim(COALESCE((to_address ->>
    'line1'::text), ''::text))) >= 1) AND (length(btrim(COALESCE((to_address ->> 'city'::text), ''::text))) >= 1) AND (length((to_address)::text) <= 4000))),
  CONSTRAINT "bsb_shipments_tracking_number_check" CHECK (((tracking_number IS NULL) OR ((length(tracking_number) >= 1) AND (length(tracking_number) <= 100)))),
  CONSTRAINT "bsb_shipments_tracking_url_check" CHECK (((tracking_url IS NULL) OR ((tracking_url ~ '^https://'::text) AND (length(tracking_url) <= 2000)))),
  CONSTRAINT "shipments_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."shipments"
  ENABLE ROW LEVEL SECURITY;

