CREATE TABLE "better_supabase"."stock_allocations" (
  "id"            uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"     uuid                     NOT NULL,
  "variant_id"    uuid                     NOT NULL,
  "location_id"   uuid                     NOT NULL,
  "document_type" text                     NOT NULL,
  "document_id"   text                     NOT NULL,
  "line_id"       text,
  "quantity"      numeric(20,6)            NOT NULL,
  "allocated"     numeric(20,6)            NOT NULL DEFAULT 0,
  "fulfilled"     numeric(20,6)            NOT NULL DEFAULT 0,
  "status"        text                     NOT NULL DEFAULT 'open'::text,
  "backordered"   numeric(20,6)            GENERATED ALWAYS AS (
CASE
    WHEN (status = 'open'::text) THEN ((quantity - allocated) - fulfilled)
    ELSE (0)::numeric
END) STORED,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"    timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "bsb_stock_allocations_allocated_check" CHECK ((allocated >= (0)::numeric)),
  CONSTRAINT "bsb_stock_allocations_check" CHECK (((allocated + fulfilled) <= quantity)),
  CONSTRAINT "bsb_stock_allocations_document_id_check" CHECK (((length(document_id) >= 1) AND (length(document_id) <= 200))),
  CONSTRAINT "bsb_stock_allocations_document_type_check" CHECK ((document_type ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
  CONSTRAINT "bsb_stock_allocations_fulfilled_check" CHECK ((fulfilled >= (0)::numeric)),
  CONSTRAINT "bsb_stock_allocations_quantity_check" CHECK ((quantity > (0)::numeric)),
  CONSTRAINT "bsb_stock_allocations_status_check" CHECK ((status = ANY (ARRAY['open'::text, 'fulfilled'::text, 'released'::text]))),
  CONSTRAINT "stock_allocations_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."stock_allocations"
  ENABLE ROW LEVEL SECURITY;

