  "id"                  uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"           uuid,
  "scope"               text                     NOT NULL DEFAULT 'tenant'::text,
  "key"                 text,
  "type"                text                     NOT NULL,
  "name"                text                     NOT NULL,
  "language"            text                     NOT NULL DEFAULT 'en'::text,
  "is_default"          boolean                  NOT NULL DEFAULT false,
  "settings"            jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "forked_from"         uuid,
  "forked_from_version" integer,
  "created_by"          uuid,
  "created_at"          timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"          timestamp with time zone NOT NULL DEFAULT now(),
  "brand"               text,
  CONSTRAINT "bsb_templates_brand_check" CHECK (((length(brand) >= 1) AND (length(brand) <= 100))),
  CONSTRAINT "bsb_templates_forked_from_version_check" CHECK ((forked_from_version > 0)),
  CONSTRAINT "bsb_templates_key_check" CHECK ((key ~ '^[a-z0-9][a-z0-9_.-]{0,99}$'::text)),
  CONSTRAINT "bsb_templates_language_check" CHECK ((language ~ '^[a-z]{2,3}(-[A-Za-z0-9]{1,8})*$'::text)),
  CONSTRAINT "bsb_templates_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "bsb_templates_scope_check" CHECK ((scope = ANY (ARRAY['tenant'::text, 'brand'::text, 'system'::text]))),
  CONSTRAINT "bsb_templates_settings_check" CHECK (((jsonb_typeof(settings) = 'object'::text) AND (pg_column_size(settings) <= 65536))),
  CONSTRAINT "bsb_templates_system_check" CHECK (
CASE scope
    WHEN 'tenant'::text THEN ((tenant_id IS NOT NULL) AND (brand IS NULL))
    WHEN 'brand'::text THEN ((tenant_id IS NULL) AND (brand IS NOT NULL))
    ELSE ((tenant_id IS NULL) AND (brand IS NULL))
END),
  CONSTRAINT "bsb_templates_type_check" CHECK ((type ~ '^[a-z][a-z0-9_.-]{0,63}$'::text)),
  CONSTRAINT "templates_pkey" PRIMARY KEY (id)
);

