  "tenant_id"     uuid                     NOT NULL,
  "work_order_id" uuid                     NOT NULL,
  "name"          text                     NOT NULL,
  "quantity"      numeric(14,3)            NOT NULL,
  "unit"          text,
  "asset_id"      uuid,
  "variant_id"    uuid,
  "location_id"   uuid,
  "recorded_by"   uuid,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "bsb_work_order_parts_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "bsb_work_order_parts_quantity_check" CHECK ((quantity > (0)::numeric)),
  CONSTRAINT "bsb_work_order_parts_unit_check" CHECK (((unit IS NULL) OR ((length(unit) >= 1) AND (length(unit) <= 20)))),
  CONSTRAINT "work_order_parts_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."work_order_parts"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."work_orders" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"       uuid                     NOT NULL,
  "title"           text                     NOT NULL,
  "description"     text,
  "priority"        text                     NOT NULL DEFAULT 'normal'::text,
  "status"          text                     NOT NULL DEFAULT 'unscheduled'::text,
  "technician_id"   uuid,
  "starts_at"       timestamp with time zone,
  "ends_at"         timestamp with time zone,
  "location_id"     uuid,
  "asset_id"        uuid,
  "booking_id"      uuid,
  "subject_type"    text,
  "subject_id"      text,
  "address"         text,
  "en_route_at"     timestamp with time zone,
  "arrived_at"      timestamp with time zone,
  "completed_at"    timestamp with time zone,
  "cancelled_at"    timestamp with time zone,
  "cancel_reason"   text,
  "completion_note" text,
  "created_by"      uuid,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "bsb_work_orders_address_check" CHECK (((address IS NULL) OR ((length(address) >= 1) AND (length(address) <= 500)))),
  CONSTRAINT "bsb_work_orders_cancel_reason_check" CHECK (((cancel_reason IS NULL) OR (length(cancel_reason) <= 1000))),
  CONSTRAINT "bsb_work_orders_check1" CHECK (((starts_at IS NULL) = (ends_at IS NULL))),
  CONSTRAINT "bsb_work_orders_check2" CHECK (((ends_at IS NULL) OR (ends_at > starts_at))),
  CONSTRAINT "bsb_work_orders_check3" CHECK (((status <> ALL (ARRAY['scheduled'::text, 'en_route'::text, 'on_site'::text])) OR ((technician_id IS NOT NULL) AND (starts_at IS
    NOT NULL)))),
  CONSTRAINT "bsb_work_orders_check" CHECK (((subject_type IS NULL) = (subject_id IS NULL))),
  CONSTRAINT "bsb_work_orders_completion_note_check" CHECK (((completion_note IS NULL) OR (length(completion_note) <= 10000))),
  CONSTRAINT "bsb_work_orders_description_check" CHECK (((description IS NULL) OR (length(description) <= 10000))),
  CONSTRAINT "bsb_work_orders_priority_check" CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))),
  CONSTRAINT "bsb_work_orders_status_check"
    CHECK ((status = ANY (ARRAY['unscheduled'::text, 'scheduled'::text, 'en_route'::text, 'on_site'::text, 'done'::text, 'cancelled'::text]))),
  CONSTRAINT "bsb_work_orders_subject_id_check" CHECK (((subject_id IS NULL) OR ((length(subject_id) >= 1) AND (length(subject_id) <= 200)))),
  CONSTRAINT "bsb_work_orders_subject_type_check" CHECK (((subject_type IS NULL) OR (subject_type ~ '^[a-z][a-z0-9_-]{0,62}$'::text))),
  CONSTRAINT "bsb_work_orders_title_check" CHECK (((length(title) >= 1) AND (length(title) <= 200))),
  CONSTRAINT "work_orders_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."work_orders"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."work_projects" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"       uuid                     NOT NULL,
  "key"             text                     NOT NULL,
  "name"            text                     NOT NULL,
  "owner_id"        uuid,
  "status"          text                     NOT NULL DEFAULT 'planned'::text,
  "start_on"        date,
  "target_on"       date,
  "archived_at"     timestamp with time zone,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "budget_amount"   bigint,
  "budget_currency" text,
  "budget_hours"    numeric(12,2),
  CONSTRAINT "bsb_work_projects_budget_amount_check" CHECK ((budget_amount >= 0)),
  CONSTRAINT "bsb_work_projects_budget_currency_check" CHECK ((budget_currency ~ '^[A-Z]{3}$'::text)),
  CONSTRAINT "bsb_work_projects_budget_hours_check" CHECK ((budget_hours >= (0)::numeric)),
  CONSTRAINT "bsb_work_projects_check" CHECK (((target_on IS NULL) OR (start_on IS NULL) OR (target_on >= start_on))),
  CONSTRAINT "bsb_work_projects_key_check" CHECK ((key ~ '^[A-Z][A-Z0-9]{0,9}$'::text)),
  CONSTRAINT "bsb_work_projects_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "bsb_work_projects_status_check" CHECK ((status = ANY (ARRAY['planned'::text, 'active'::text, 'paused'::text, 'completed'::text, 'canceled'::text]))),
  CONSTRAINT "work_projects_pkey" PRIMARY KEY (id),
  CONSTRAINT "work_projects_tenant_id_key_key" UNIQUE (tenant_id, key)
);

ALTER TABLE "better_supabase"."work_projects"
  ENABLE ROW LEVEL SECURITY;

