  CONSTRAINT "bsb_workflow_alerts_on_event_check" CHECK ((on_event = ANY (ARRAY['failed'::text, 'slow'::text]))),
  CONSTRAINT "bsb_workflow_alerts_threshold_check" CHECK (((on_event <> 'slow'::text) OR (threshold > '00:00:00'::interval))),
  CONSTRAINT "workflow_alerts_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."workflow_alerts"
