  CONSTRAINT "bsb_workflow_definition_grants_principal_id_check" CHECK (((length(principal_id) >= 1) AND (length(principal_id) <= 200))),
  CONSTRAINT "bsb_workflow_definition_grants_principal_kind_check" CHECK ((principal_kind = ANY (ARRAY['user'::text, 'team'::text, 'role'::text]))),
