  "restricted"          boolean                  NOT NULL DEFAULT false,
  "purpose"             text                     NOT NULL DEFAULT 'automation'::text,
  "is_default"          boolean                  NOT NULL DEFAULT false,
  CONSTRAINT "bsb_workflow_definitions_description_check" CHECK ((length(description) <= 2000)),
  CONSTRAINT "bsb_workflow_definitions_forked_from_version_check" CHECK ((forked_from_version > 0)),
  CONSTRAINT "bsb_workflow_definitions_name_check" CHECK (((length(name) >= 1) AND (length(name) <= 200))),
  CONSTRAINT "bsb_workflow_definitions_purpose_check" CHECK ((purpose = ANY (ARRAY['automation'::text, 'lifecycle'::text]))),
  CONSTRAINT "bsb_workflow_definitions_scope_check" CHECK ((scope = ANY (ARRAY['tenant'::text, 'system'::text]))),
  CONSTRAINT "bsb_workflow_definitions_slug_check" CHECK ((slug ~ '^[a-z0-9][a-z0-9-]{0,99}$'::text)),
  CONSTRAINT "bsb_workflow_definitions_subject_types_check" CHECK (((cardinality(subject_types) <= 50) AND (array_position(subject_types, NULL::text) IS NULL))),
  CONSTRAINT "bsb_workflow_definitions_system_check" CHECK (((scope = 'tenant'::text) OR (tenant_id IS NULL))),
  CONSTRAINT "workflow_definitions_pkey" PRIMARY KEY (id),
  CONSTRAINT "workflow_definitions_tenant_slug_key" UNIQUE NULLS NOT DISTINCT (tenant_id, slug)
);

