  CONSTRAINT "bsb_workflow_runs_definition_check" CHECK (((length(definition) >= 1) AND (length(definition) <= 200))),
  CONSTRAINT "bsb_workflow_runs_engine_check" CHECK (((length(engine) >= 1) AND (length(engine) <= 100))),
  CONSTRAINT "bsb_workflow_runs_external_id_check" CHECK (((length(external_id) >= 1) AND (length(external_id) <= 200))),
  CONSTRAINT "bsb_workflow_runs_idempotency_key_check" CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 500))),
  CONSTRAINT "bsb_workflow_runs_mode_check" CHECK ((mode = ANY (ARRAY['live'::text, 'test'::text]))),
  CONSTRAINT "bsb_workflow_runs_principal_id_check" CHECK (((length(principal_id) >= 1) AND (length(principal_id) <= 200))),
  CONSTRAINT "bsb_workflow_runs_principal_kind_check" CHECK ((principal_kind = ANY (ARRAY['user'::text, 'service_principal'::text, 'system'::text, 'external'::text]))),
  CONSTRAINT "bsb_workflow_runs_status_check"
    CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'waiting'::text, 'completed'::text, 'failed'::text, 'cancelled'::text]))),
  CONSTRAINT "bsb_workflow_runs_subject_check" CHECK (((subject_type IS NULL) = (subject_id IS NULL))),
  CONSTRAINT "bsb_workflow_runs_subject_id_check" CHECK (((length(subject_id) >= 1) AND (length(subject_id) <= 200))),
  CONSTRAINT "bsb_workflow_runs_subject_type_check" CHECK (((length(subject_type) >= 1) AND (length(subject_type) <= 100))),
  CONSTRAINT "bsb_workflow_runs_trigger_node_check" CHECK (((length(trigger_node) >= 1) AND (length(trigger_node) <= 100))),
