CREATE TABLE "public"."customers" (
  "id"                 uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "organization_id"    uuid                     NOT NULL,
  "name"               text                     NOT NULL,
  "kvk"                text,
  "status"             text                     NOT NULL DEFAULT 'lead'::text,
  "primary_contact_id" uuid,
  "metadata"           jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "updated_by"         uuid,
  "archived_at"        timestamp with time zone,
  "created_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"         timestamp with time zone NOT NULL DEFAULT now(),
  "logo_path"          text,
  "owner_team_id"      uuid,
  CONSTRAINT "customers_archived_check" CHECK (((status <> 'archived'::text) OR (archived_at IS NOT NULL))),
  CONSTRAINT "customers_id_organization_id_key" UNIQUE (id, organization_id),
  CONSTRAINT "customers_name_check" CHECK (((char_length(name) >= 1) AND (char_length(name) <= 200))),
  CONSTRAINT "customers_organization_id_kvk_key" UNIQUE (organization_id, kvk),
  CONSTRAINT "customers_pkey" PRIMARY KEY (id),
  CONSTRAINT "customers_status_check" CHECK ((status = ANY (ARRAY['lead'::text, 'active'::text, 'archived'::text]))),
  "created_by"         uuid                     DEFAULT auth.uid()
);

ALTER TABLE "public"."customers"
