CREATE OR REPLACE FUNCTION better_supabase.accepting_invitation()
  RETURNS uuid
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select nullif(current_setting('better_supabase.accepting_invitation', true), '')::uuid
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_account_level()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if tg_op = 'INSERT' or new."parent_id" is distinct from old."parent_id" then
    new."level" := coalesce((select y."level" from "better_supabase"."accounting_accounts" y where y."id" = new."parent_id"), 0) + 1;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_account_level_children()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  with recursive down (id, level) as (
    select y."id", new."level" + 1 from "better_supabase"."accounting_accounts" y where y."parent_id" = new."id"
    union all
    select y."id", down.level + 1 from "better_supabase"."accounting_accounts" y join down on y."parent_id" = down.id
  )
  update "better_supabase"."accounting_accounts" y set "level" = down.level from down where y."id" = down.id and y."level" <> down.level;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_asset_depreciation_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', y."tenant_id",
    'entryDate', (y."period_start" + interval '1 month' - interval '1 day')::date,
    'currency', a."currency",
    'reference', left(coalesce(a."tag" || ' ' || a."name", a."name"), 200),
    'memo', left('Depreciation of ' || a."name" || ' for ' || to_char(y."period_start", 'YYYY-MM'), 500),
    'lines', jsonb_build_array(
      jsonb_build_object('role', 'depreciation_expense', 'debit', y."amount"::text),
      jsonb_build_object('role', 'accumulated_depreciation', 'credit', y."amount"::text))
  )
  from "better_supabase"."asset_depreciations" y join "better_supabase"."assets" a on a."id" = y."asset_id"
  where y."id"::text = source_id
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_asset_disposal_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', a."tenant_id",
    'entryDate', a."disposed_on",
    'currency', a."currency",
    'reference', left(coalesce(a."tag" || ' ' || a."name", a."name"), 200),
    'memo', left('Disposal of ' || a."name", 500),
    'lines', jsonb_build_array(
      jsonb_build_object('role', 'bank', 'debit', a."disposal_amount"::text),
      jsonb_build_object('role', 'accumulated_depreciation', 'debit', q.total::text),
      jsonb_build_object('role', 'fixed_asset', 'credit', a."acquisition_cost"::text),
      jsonb_build_object('role', 'disposal_gain', 'credit', greatest(q.result, 0)::text),
      jsonb_build_object('role', 'disposal_loss', 'debit', greatest(-q.result, 0)::text))
  )
  from "better_supabase"."assets" a
  cross join lateral (
    select coalesce(sum(y."amount"), 0) as total,
      a."disposal_amount" + coalesce(sum(y."amount"), 0) - a."acquisition_cost" as result
    from "better_supabase"."asset_depreciations" y where y."asset_id" = a."id"
  ) q
  where a."id"::text = source_id and a."disposed_on" is not null and a."acquisition_cost" is not null
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_balance_sheet (
  tenant     uuid,
  as_of      date  DEFAULT NULL::date,
  dimensions jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with sums as (
    select y."account_id" as account, sum(y."debit") - sum(y."credit") as debit_balance
    from "better_supabase"."accounting_entry_lines" y join "better_supabase"."accounting_entries" z on z."id" = y."entry_id"
    where z."tenant_id" = accounting_balance_sheet.tenant and z."status" in ('posted', 'reversed')
      and y."dimensions" @> coalesce(accounting_balance_sheet.dimensions, '{}'::jsonb)
      and z."entry_date" <= coalesce(accounting_balance_sheet.as_of, current_date)
    group by y."account_id"
  ),
  kept as (
    select w.*, c.debit_balance from sums c join "better_supabase"."accounting_accounts" w on w."id" = c.account
    where c.debit_balance <> 0
  ),
  totals as (
    select
      coalesce(sum(w.debit_balance) filter (where w."type" = 'asset'), 0) as assets,
      coalesce(-sum(w.debit_balance) filter (where w."type" = 'liability'), 0) as liabilities,
      coalesce(-sum(w.debit_balance) filter (where w."type" = 'equity'), 0) as equity,
      coalesce(-sum(w.debit_balance) filter (where w."type" in ('income', 'expense')), 0) as earnings
    from kept w
  )
  select jsonb_build_object(
    'asOf', coalesce(accounting_balance_sheet.as_of, current_date),
    'assets', coalesce((select jsonb_agg(jsonb_build_object('accountId', w."id", 'code', w."code", 'name', w."name", 'type', w."type", 'subtype', w."subtype", 'amount', (w.debit_balance)::text) order by w."code") from kept w where w."type" = 'asset'), '[]'::jsonb),
    'liabilities', coalesce((select jsonb_agg(jsonb_build_object('accountId', w."id", 'code', w."code", 'name', w."name", 'type', w."type", 'subtype', w."subtype", 'amount', (-w.debit_balance)::text) order by w."code") from kept w where w."type" = 'liability'), '[]'::jsonb),
    'equity', coalesce((select jsonb_agg(jsonb_build_object('accountId', w."id", 'code', w."code", 'name', w."name", 'type', w."type", 'subtype', w."subtype", 'amount', (-w.debit_balance)::text) order by w."code") from kept w where w."type" = 'equity'), '[]'::jsonb),
    'currentEarnings', t.earnings::text,
    'totalAssets', t.assets::text,
    'totalLiabilities', t.liabilities::text,
    'totalEquity', (t.equity + t.earnings)::text,
    'balanced', t.assets = t.liabilities + t.equity + t.earnings
  )
  from totals t
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_bank_transaction_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', x."tenant_id",
    'entryDate', x."booked_on",
    'journalId', z."journal_id",
    'currency', x."currency",
    'reference', left(coalesce(x."end_to_end_id", x."external_id"), 200),
    'memo', left(coalesce(x."remittance", x."counterparty_name", y."name"), 2000),
    'lines', case when x."amount" > 0
      then jsonb_build_array(
        case when w."default_account_id" is not null
        then jsonb_build_object('accountId', w."default_account_id")
        else jsonb_build_object('role', 'bank') end || jsonb_build_object('debit', x."amount"::text),
        jsonb_strip_nulls(jsonb_build_object('accountId', y."account_id", 'partyId', y."party_id", 'dimensions', y."dimensions", 'description', y."name")) || jsonb_build_object('credit', x."amount"::text))
      else jsonb_build_array(
        jsonb_strip_nulls(jsonb_build_object('accountId', y."account_id", 'partyId', y."party_id", 'dimensions', y."dimensions", 'description', y."name")) || jsonb_build_object('debit', (-x."amount")::text),
        case when w."default_account_id" is not null
        then jsonb_build_object('accountId', w."default_account_id")
        else jsonb_build_object('role', 'bank') end || jsonb_build_object('credit', (-x."amount")::text))
      end
  )
  from "better_supabase"."bank_transactions" x
  join "better_supabase"."bank_accounts" z on z."id" = x."account_id"
  join "better_supabase"."bank_rules" y on y."id" = x."rule_id"
  left join "better_supabase"."accounting_journals" w on w."id" = z."journal_id"
  where x."id"::text = source_id and x."status" = 'matched' and y."account_id" is not null
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_budget_vs_actual (
  budget_id     uuid,
  period_number integer DEFAULT NULL::integer
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with budget as (
    select x.* from "better_supabase"."accounting_budgets" x where x."id" = accounting_budget_vs_actual.budget_id
  ),
  planned as (
    select y."account_id" as account, y."dimensions" as dimensions, sum(y."amount") as amount
    from "better_supabase"."accounting_budget_lines" y
    where y."budget_id" = accounting_budget_vs_actual.budget_id
      and (accounting_budget_vs_actual.period_number is null or y."period_number" = accounting_budget_vs_actual.period_number)
    group by y."account_id", y."dimensions"
  ),
  compared as (
    select q.account, q.dimensions, q.amount as budget, ac."code" as code, ac."name" as name, ac."type" as type,
      coalesce((
        select sum(case when ac."type" in ('liability', 'equity', 'income') then z."credit" - z."debit" else z."debit" - z."credit" end)
        from "better_supabase"."accounting_entry_lines" z
        join "better_supabase"."accounting_entries" w on w."id" = z."entry_id"
        join "better_supabase"."accounting_periods" v on v."id" = w."period_id"
        cross join budget g
        where z."account_id" = q.account and z."dimensions" @> q.dimensions
          and w."status" in ('posted', 'reversed') and w."source_type" is distinct from 'fiscal_year'
          and v."tenant_id" = g."tenant_id" and v."fiscal_year" = g."fiscal_year"
          and (accounting_budget_vs_actual.period_number is null or v."number" = accounting_budget_vs_actual.period_number)
      ), 0) as actual
    from planned q join "better_supabase"."accounting_accounts" ac on ac."id" = q.account
  )
  select jsonb_build_object(
    'budgetId', g."id",
    'name', g."name",
    'fiscalYear', g."fiscal_year",
    'periodNumber', accounting_budget_vs_actual.period_number,
    'lines', coalesce((select jsonb_agg(jsonb_build_object('accountId', c.account, 'code', c.code, 'name', c.name, 'type', c.type,
      'dimensions', c.dimensions, 'budget', c.budget::text, 'actual', c.actual::text, 'variance', (c.actual - c.budget)::text)
      order by c.code, c.dimensions::text) from compared c), '[]'::jsonb),
    'budget', coalesce((select sum(c.budget) from compared c), 0)::text,
    'actual', coalesce((select sum(c.actual) from compared c), 0)::text
  )
  from budget g
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_close_range (
  tenant    uuid,
  starts_on date,
  ends_on   date
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_id uuid;
begin
  select x."id" into v_id from "better_supabase"."accounting_periods" x
  where x."tenant_id" = accounting_close_range.tenant
    and x."starts_on" = accounting_close_range.starts_on
    and x."ends_on" = accounting_close_range.ends_on;
  if found then
    perform "better_supabase"."close_accounting_period"(v_id);
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_column_balance (
  tenant     uuid,
  since      date    DEFAULT NULL::date,
  until      date    DEFAULT NULL::date,
  dimensions jsonb   DEFAULT '{}'::jsonb,
  rollup     boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with recursive sums as (
    select y."account_id" as account,
      sum(case when z."entry_date" < accounting_column_balance.since then y."debit" - y."credit" else 0 end) as opening,
      sum(case when accounting_column_balance.since is null or z."entry_date" >= accounting_column_balance.since then y."debit" else 0 end) as debit,
      sum(case when accounting_column_balance.since is null or z."entry_date" >= accounting_column_balance.since then y."credit" else 0 end) as credit
    from "better_supabase"."accounting_entry_lines" y join "better_supabase"."accounting_entries" z on z."id" = y."entry_id"
    where z."tenant_id" = accounting_column_balance.tenant and z."status" in ('posted', 'reversed')
      and y."dimensions" @> coalesce(accounting_column_balance.dimensions, '{}'::jsonb)
      and (accounting_column_balance.until is null or z."entry_date" <= accounting_column_balance.until)
    group by y."account_id"
  ),
  tree (leaf, node) as (
    select w."id", w."id" from "better_supabase"."accounting_accounts" w where w."tenant_id" = accounting_column_balance.tenant
    union all
    select t.leaf, w."parent_id" from tree t join "better_supabase"."accounting_accounts" w on w."id" = t.node
    where w."parent_id" is not null and coalesce(accounting_column_balance.rollup, false)
  ),
  rolled as (
    select t.node as account, sum(c.opening) as opening, sum(c.debit) as debit, sum(c.credit) as credit
    from tree t join sums c on c.account = t.leaf group by t.node
  )
  select jsonb_build_object(
    'accounts', coalesce((
      select jsonb_agg(jsonb_build_object('accountId', w."id", 'code', w."code", 'name', w."name", 'type', w."type",
        'parentId', w."parent_id", 'level', w."level",
        'openingDebit', greatest(r.opening, 0)::text, 'openingCredit', greatest(-r.opening, 0)::text,
        'debit', r.debit::text, 'credit', r.credit::text,
        'closingDebit', greatest(r.opening + r.debit - r.credit, 0)::text, 'closingCredit', greatest(r.credit - r.debit - r.opening, 0)::text) order by w."code")
      from rolled r join "better_supabase"."accounting_accounts" w on w."id" = r.account), '[]'::jsonb),
    'totals', (select jsonb_build_object(
        'openingDebit', coalesce(sum(greatest(c.opening, 0)), 0)::text, 'openingCredit', coalesce(sum(greatest(-c.opening, 0)), 0)::text,
        'debit', coalesce(sum(c.debit), 0)::text, 'credit', coalesce(sum(c.credit), 0)::text,
        'closingDebit', coalesce(sum(greatest(c.opening + c.debit - c.credit, 0)), 0)::text,
        'closingCredit', coalesce(sum(greatest(c.credit - c.debit - c.opening, 0)), 0)::text)
      from sums c)
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_entry_guard()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if tg_op = 'DELETE' and current_setting('better_supabase.purge_tenant', true) = to_jsonb(old) ->> tg_argv[0] then
    if coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') and exists (
      select 1 from "better_supabase"."organization_deletions" x
      where x."tenant_id"::text = to_jsonb(old) ->> tg_argv[0]
        and x."cancelled_at" is null and x."purged_at" is null and x."purge_at" <= now()
    ) then
      return old;
    end if;
  end if;
  if tg_op = 'UPDATE' and old."status" = 'draft' then
    return new;
  end if;
  if tg_op = 'DELETE' and old."status" = 'draft' then
    return old;
  end if;
  if tg_op = 'UPDATE' and old."status" = 'posted' and new."status" = 'reversed'
    and (to_jsonb(new) - 'status' - 'updated_at')
      = (to_jsonb(old) - 'status' - 'updated_at') then
    return new;
  end if;
  raise exception 'a posted entry can''t be changed or deleted; reverse it' using errcode = '55000', hint = 'ACCOUNTING_ENTRY_POSTED';
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_entry_line_guard()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_entry uuid := case when tg_op = 'DELETE' then old."entry_id" else new."entry_id" end;
begin
  if tg_op = 'DELETE' and current_setting('better_supabase.purge_tenant', true) = to_jsonb(old) ->> tg_argv[0] then
    if coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') and exists (
      select 1 from "better_supabase"."organization_deletions" x
      where x."tenant_id"::text = to_jsonb(old) ->> tg_argv[0]
        and x."cancelled_at" is null and x."purged_at" is null and x."purge_at" <= now()
    ) then
      return old;
    end if;
  end if;
  if exists (select 1 from "better_supabase"."accounting_entries" y where y."id" = v_entry and y."status" <> 'draft')
    or (tg_op = 'UPDATE' and exists (select 1 from "better_supabase"."accounting_entries" y where y."id" = old."entry_id" and y."status" <> 'draft')) then
    raise exception 'the lines of a posted entry can''t change; reverse it' using errcode = '55000', hint = 'ACCOUNTING_ENTRY_POSTED';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_expense_reimbursement_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', v."tenant_id",
    'entryDate', (v."reimbursed_at" at time zone 'UTC')::date,
    'currency', v."currency",
    'reference', left(v."id"::text, 8),
    'memo', left('Reimbursed: ' || v."title", 500),
    'lines', jsonb_build_array(
      jsonb_build_object('role', 'payable', 'debit', (select coalesce(sum(y."amount"), 0) from "better_supabase"."expense_lines" y where y."report_id" = v."id")::text, 'partyId', v."user_id"::text),
      jsonb_build_object('role', 'bank', 'credit', (select coalesce(sum(y."amount"), 0) from "better_supabase"."expense_lines" y where y."report_id" = v."id")::text))
  )
  from "better_supabase"."expense_reports" v
  where v."id"::text = source_id and v."cancelled_at" is null and v."reimbursed_at" is not null
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_expense_report_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', v."tenant_id",
    'entryDate', (v."approved_at" at time zone 'UTC')::date,
    'currency', v."currency",
    'reference', left(v."id"::text, 8),
    'memo', left('Expenses: ' || v."title", 500),
    'lines', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('role', 'expense', 'debit', g.amount::text, 'description', v."title", 'dimensions', nullif(g.dim, '{}'::jsonb))) order by g.dim::text)
        from (select coalesce(y."dimensions", '{}'::jsonb) as dim, sum(y."amount") as amount from "better_supabase"."expense_lines" y where y."report_id" = v."id" group by 1) g),
      jsonb_build_array(jsonb_build_object('role', 'expense', 'debit', (select coalesce(sum(y."amount"), 0) from "better_supabase"."expense_lines" y where y."report_id" = v."id")::text, 'description', v."title")))
      || jsonb_build_array(jsonb_build_object('role', 'payable', 'credit', (select coalesce(sum(y."amount"), 0) from "better_supabase"."expense_lines" y where y."report_id" = v."id")::text, 'partyId', v."user_id"::text))
  )
  from "better_supabase"."expense_reports" v
  where v."id"::text = source_id and v."cancelled_at" is null and v."approved_at" is not null
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_fx_rate (
  tenant  uuid,
  base    text,
  quote   text,
  on_date date
)
  RETURNS numeric
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_base text := upper(trim(accounting_fx_rate.base));
  v_quote text := upper(trim(accounting_fx_rate.quote));
  v_rate numeric;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', accounting_fx_rate.tenant, 'accounting.read'), false)) then
    raise exception 'not allowed to read accounting' using errcode = '42501', hint = 'ACCOUNTING_FX_RATE_FORBIDDEN';
  end if;
  if v_base = v_quote then
    return 1;
  end if;
  select y."rate" into v_rate from "better_supabase"."accounting_fx_rates" y
  where y."tenant_id" = accounting_fx_rate.tenant and y."base" = v_base and y."quote" = v_quote and y."on_date" <= accounting_fx_rate.on_date
  order by y."on_date" desc limit 1;
  if v_rate is null then
    select 1 / y."rate" into v_rate from "better_supabase"."accounting_fx_rates" y
    where y."tenant_id" = accounting_fx_rate.tenant and y."base" = v_quote and y."quote" = v_base and y."on_date" <= accounting_fx_rate.on_date
    order by y."on_date" desc limit 1;
  end if;
  if v_rate is null then
    raise exception 'no exchange rate for the currency pair on or before the date' using errcode = 'P0002', hint = 'ACCOUNTING_FX_RATE_MISSING';
  end if;
  return v_rate;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_general_ledger (
  account_id uuid,
  since      date DEFAULT NULL::date,
  until      date DEFAULT NULL::date
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with account as (
    select w.* from "better_supabase"."accounting_accounts" w where w."id" = accounting_general_ledger.account_id
  ),
  booked as (
    select y.*, z."entry_date" as entry_date, z."number" as entry_number, z."journal_id" as journal_id, z."memo" as memo
    from "better_supabase"."accounting_entry_lines" y join "better_supabase"."accounting_entries" z on z."id" = y."entry_id"
    where y."account_id" = accounting_general_ledger.account_id and z."status" in ('posted', 'reversed')
      and (accounting_general_ledger.until is null or z."entry_date" <= accounting_general_ledger.until)
  ),
  opening as (
    select coalesce(sum(b."debit" - b."credit"), 0) as amount from booked b
    where b.entry_date < accounting_general_ledger.since
  ),
  period as (
    select b.*, (select o.amount from opening o) + sum(b."debit" - b."credit") over (order by b.entry_date, b.entry_number, b."position", b."id") as balance
    from booked b
    where accounting_general_ledger.since is null or b.entry_date >= accounting_general_ledger.since
  )
  select jsonb_build_object(
    'account', jsonb_build_object('id', w."id", 'code', w."code", 'name', w."name", 'type', w."type"),
    'opening', (select o.amount from opening o)::text,
    'lines', coalesce((select jsonb_agg(jsonb_build_object('entryId', b."entry_id", 'number', b.entry_number, 'entryDate', b.entry_date, 'journalId', b.journal_id,
      'description', coalesce(b."description", b.memo), 'partyId', b."party_id", 'debit', b."debit"::text, 'credit', b."credit"::text, 'balance', b.balance::text)
      order by b.entry_date, b.entry_number, b."position", b."id") from period b), '[]'::jsonb),
    'closing', ((select o.amount from opening o) + coalesce((select sum(b."debit" - b."credit") from period b), 0))::text
  )
  from account w
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_gift_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', v."tenant_id",
    'entryDate', v."received_on",
    'currency', v."currency",
    'memo', 'Gift',
    'lines', jsonb_build_array(
      jsonb_build_object('role', 'bank', 'debit', v."amount"::text),
      jsonb_build_object('role', 'revenue', 'credit', v."amount"::text, 'partyId', v."donor_id"))
  )
  from "better_supabase"."donations" v
  where v."id"::text = source_id and v."status" = 'posted' and v."amount" <> 0
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_invoice_charge_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', inv."tenant_id",
    'entryDate', (c."created_at" at time zone 'UTC')::date,
    'currency', inv."currency",
    'reference', inv."identifier",
    'memo', 'Charge on ' || coalesce(inv."identifier", inv."title"),
    'lines', jsonb_build_array(
      jsonb_strip_nulls(jsonb_build_object('role', 'receivable', 'debit', c."amount"::text, 'partyId', inv."company_id"::text)),
      jsonb_strip_nulls(jsonb_build_object('role', 'revenue', 'credit', c."amount"::text, 'description', c."description")))
  )
  from "better_supabase"."invoice_charges" c
  join "better_supabase"."invoices" inv on inv."id" = c."invoice_id"
  where c."id"::text = source_id and c."amount" <> 0 and not (inv."direction" = 'purchase')
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_invoice_discount_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', y."tenant_id",
    'entryDate', (y."effective_at" at time zone 'UTC')::date,
    'currency', inv."currency",
    'reference', inv."identifier",
    'memo', 'Early payment discount on ' || coalesce(inv."identifier", inv."title"),
    'lines', case when inv."direction" = 'purchase' then jsonb_build_array(
        jsonb_strip_nulls(jsonb_build_object('role', 'payable', 'debit', d.amount::text, 'partyId', inv."company_id"::text)),
        jsonb_build_object('role', 'expense', 'credit', d.amount::text, 'description', 'Early payment discount'))
      else jsonb_build_array(
        jsonb_build_object('role', 'revenue', 'debit', d.amount::text, 'description', 'Early payment discount'),
        jsonb_strip_nulls(jsonb_build_object('role', 'receivable', 'credit', d.amount::text, 'partyId', inv."company_id"::text))) end
  )
  from "better_supabase"."ledger_transactions" y
  join "better_supabase"."invoices" inv on inv."id"::text = y."metadata" ->> 'invoiceId'
  cross join lateral (
    select sum(e."amount") as amount from "better_supabase"."ledger_entries" e
    join "better_supabase"."ledger_accounts" a on a."id" = e."account_id"
    where e."transaction_id" = y."id" and a."code" like 'invoices:discount:%'
  ) d
  where y."id"::text = source_id and y."reference_type" = 'invoices'
    and y."kind" = 'invoice.discount' and d.amount > 0
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_invoice_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  with inv as (
    select x."id" as id, x."tenant_id" as tenant, x."issued_on" as issued_on, x."currency" as currency,
      x."identifier" as identifier, x."title" as title, x."subtotal" as subtotal, x."tax_total" as tax_total,
      x."total" as total, x."company_id"::text as party, x."prices_include_tax" as inclusive,
      case when x."kind" = 'credit_note' then -1 else 1 end as sign,
      x."direction" = 'purchase' as purchase, nullif(x."dimensions", '{}'::jsonb) as dimensions,
      x."purchase_order_id" is not null as ordered
    from "better_supabase"."invoices" x
    where x."id"::text = source_id and x."status" not in ('draft', 'void')
  ),
  groups as (
    select l."tax_rate_bps" as rate, l."tax_code" as code, (inv.purchase and inv.ordered and l."product_id" is not null) as clearing, case when inv.purchase then coalesce(l."dimensions", '{}'::jsonb) else '{}'::jsonb end as dim, sum(round(l."quantity" * l."unit_amount") - round(round(l."quantity" * l."unit_amount") * l."discount_bps" / 10000.0)) as net,
      sum((round(l."quantity" * l."unit_amount") - round(round(l."quantity" * l."unit_amount") * l."discount_bps" / 10000.0)) * l."tax_rate_bps" / case when inv.inclusive then 10000.0 + l."tax_rate_bps" else 10000.0 end) as tax
    from "better_supabase"."invoice_lines" l cross join inv
    where l."parent_id" = inv.id and true
    group by 1, 2, 3, 4
  ),
  shares as (
    select g.rate, g.code, g.clearing, g.dim,
      case when sum(g.net) over () = 0
        then case when row_number() over w = count(*) over () then inv.subtotal else 0 end
        else round(inv.subtotal * sum(g.net) over w / sum(g.net) over ()) - round(inv.subtotal * (sum(g.net) over w - g.net) / sum(g.net) over ())
      end as net,
      case when sum(g.tax) over () = 0
        then case when row_number() over w = count(*) over () then inv.tax_total else 0 end
        else round(inv.tax_total * sum(g.tax) over w / sum(g.tax) over ()) - round(inv.tax_total * (sum(g.tax) over w - g.tax) / sum(g.tax) over ())
      end as tax
    from groups g cross join inv
    window w as (order by g.rate, g.code nulls first, g.clearing, g.dim::text rows between unbounded preceding and current row)
  )
  select jsonb_build_object(
    'organizationId', inv.tenant,
    'entryDate', inv.issued_on,
    'currency', inv.currency,
    'reference', inv.identifier,
    'memo', inv.title,
    'lines', case when inv.purchase then jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('role', 'payable', 'credit', (inv.sign * inv.total)::text, 'partyId', inv.party)))
      || coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('role', case when s.clearing then 'payable' else 'expense' end, 'debit', (inv.sign * s.net)::text, 'taxCode', s.code, 'taxRateBps', s.rate, 'dimensions', case when not s.clearing then nullif(coalesce(inv.dimensions, '{}'::jsonb) || s.dim, '{}'::jsonb) end))) from shares s where s.net <> 0), '[]'::jsonb)
      || coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('role', 'tax_receivable', 'debit', (inv.sign * s.tax)::text, 'taxCode', s.code, 'taxRateBps', s.rate, 'partyId', inv.party))) from shares s where s.tax <> 0), '[]'::jsonb) else jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('role', 'receivable', 'debit', (inv.sign * inv.total)::text, 'partyId', inv.party)))
      || coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('role', 'revenue', 'credit', (inv.sign * s.net)::text, 'taxCode', s.code, 'taxRateBps', s.rate, 'partyId', inv.party))) from shares s where s.net <> 0), '[]'::jsonb)
      || coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('role', 'tax_payable', 'credit', (inv.sign * s.tax)::text, 'taxCode', s.code, 'taxRateBps', s.rate, 'partyId', inv.party))) from shares s where s.tax <> 0), '[]'::jsonb) end
  ) || case when inv.purchase then jsonb_build_object('journal', 'purchase') else '{}'::jsonb end
  from inv
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_invoice_party_payment_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', y."tenant_id",
    'entryDate', (y."effective_at" at time zone 'UTC')::date,
    'currency', y."metadata" ->> 'currency',
    'reference', y."metadata" ->> 'reference',
    'memo', 'Payment on account',
    'lines', jsonb_build_array(
      jsonb_build_object('role', 'bank', 'debit', p.amount::text),
      jsonb_build_object('role', 'receivable', 'credit', p.amount::text, 'partyId', y."metadata" ->> 'partyId'))
  )
  from "better_supabase"."ledger_transactions" y
  cross join lateral (
    select sum(e."amount") as amount from "better_supabase"."ledger_entries" e
    join "better_supabase"."ledger_accounts" a on a."id" = e."account_id"
    where e."transaction_id" = y."id" and a."code" = 'invoices:cash:' || (y."metadata" ->> 'currency')
  ) p
  where y."id"::text = source_id and y."reference_type" = 'invoices'
    and y."metadata" ? 'partyId' and not y."metadata" ? 'invoiceId' and p.amount <> 0
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_invoice_payment_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', inv."tenant_id",
    'entryDate', (y."effective_at" at time zone 'UTC')::date,
    'currency', inv."currency",
    'reference', coalesce(y."metadata" ->> 'reference', inv."identifier"),
    'memo', 'Payment of ' || coalesce(inv."identifier", inv."title"),
    'lines', jsonb_build_array(
      jsonb_build_object('role', 'bank', case when inv."direction" = 'purchase' then 'credit' else 'debit' end, p.amount::text),
      jsonb_strip_nulls(jsonb_build_object('role', case when inv."direction" = 'purchase' then 'payable' else 'receivable' end, case when inv."direction" = 'purchase' then 'debit' else 'credit' end, p.amount::text, 'partyId', inv."company_id"::text)))
  )
  from "better_supabase"."ledger_transactions" y
  join "better_supabase"."invoices" inv on inv."id"::text = y."metadata" ->> 'invoiceId'
  cross join lateral (
    select sum(e."amount") as amount from "better_supabase"."ledger_entries" e
    join "better_supabase"."ledger_accounts" a on a."id" = e."account_id"
    where e."transaction_id" = y."id" and a."code" = case when inv."direction" = 'purchase' then 'invoices:paid:' || inv."currency" else 'invoices:cash:' || inv."currency" end
  ) p
  where y."id"::text = source_id and y."reference_type" = 'invoices' and p.amount <> 0
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_invoice_write_off_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', inv."tenant_id",
    'currency', inv."currency",
    'reference', inv."identifier",
    'memo', 'Write-off of ' || coalesce(inv."identifier", inv."title"),
    'lines', jsonb_build_array(
      jsonb_build_object('role', 'expense', 'debit', b.balance::text),
      jsonb_strip_nulls(jsonb_build_object('role', 'receivable', 'credit', b.balance::text, 'partyId', inv."company_id"::text)))
  )
  from "better_supabase"."invoices" inv
  cross join lateral (select inv."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = inv."id"), 0) - inv."credited_total" - inv."paid_total" as balance) b
  where inv."id"::text = source_id and b.balance > 0 and not (inv."direction" = 'purchase')
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_journal_listing (
  tenant     uuid,
  since      date DEFAULT NULL::date,
  until      date DEFAULT NULL::date,
  journal_id uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object('journals', coalesce(jsonb_agg(jsonb_build_object(
      'journalId', g."id", 'code', g."code", 'name', g."name", 'type', g."type",
      'entries', g.entries, 'totalDebit', g.total_debit::text, 'totalCredit', g.total_credit::text) order by g."code"), '[]'::jsonb))
  from (
    select w.*,
      (select jsonb_agg(jsonb_build_object('id', z."id", 'number', z."number", 'entryDate', z."entry_date", 'status', z."status",
          'reference', z."reference", 'memo', z."memo",
          'lines', (select jsonb_agg(jsonb_build_object('accountId', y."account_id", 'accountCode', x."code", 'accountName', x."name",
              'debit', y."debit"::text, 'credit', y."credit"::text, 'taxAmount', y."tax_amount"::text, 'partyId', y."party_id",
              'description', y."description") order by y."position", y."id")
            from "better_supabase"."accounting_entry_lines" y join "better_supabase"."accounting_accounts" x on x."id" = y."account_id" where y."entry_id" = z."id"))
        order by z."entry_date", z."number", z."id")
        from "better_supabase"."accounting_entries" z
        where z."journal_id" = w."id" and z."status" in ('posted', 'reversed')
          and (accounting_journal_listing.since is null or z."entry_date" >= accounting_journal_listing.since)
          and (accounting_journal_listing.until is null or z."entry_date" <= accounting_journal_listing.until)) as entries,
      (select coalesce(sum(y."debit"), 0) from "better_supabase"."accounting_entry_lines" y join "better_supabase"."accounting_entries" z on z."id" = y."entry_id"
        where z."journal_id" = w."id" and z."status" in ('posted', 'reversed')
          and (accounting_journal_listing.since is null or z."entry_date" >= accounting_journal_listing.since)
          and (accounting_journal_listing.until is null or z."entry_date" <= accounting_journal_listing.until)) as total_debit,
      (select coalesce(sum(y."credit"), 0) from "better_supabase"."accounting_entry_lines" y join "better_supabase"."accounting_entries" z on z."id" = y."entry_id"
        where z."journal_id" = w."id" and z."status" in ('posted', 'reversed')
          and (accounting_journal_listing.since is null or z."entry_date" >= accounting_journal_listing.since)
          and (accounting_journal_listing.until is null or z."entry_date" <= accounting_journal_listing.until)) as total_credit
    from "better_supabase"."accounting_journals" w
    where w."tenant_id" = accounting_journal_listing.tenant
      and (accounting_journal_listing.journal_id is null or w."id" = accounting_journal_listing.journal_id)
  ) g
  where g.entries is not null
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_lease_payment_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', v."tenant_id",
    'entryDate', (y."effective_at" at time zone 'UTC')::date,
    'currency', v."currency",
    'reference', y."metadata" ->> 'reference',
    'memo', left('Rent payment: ' || coalesce(v."title", ''), 500),
    'lines', jsonb_build_array(
      jsonb_build_object('role', 'bank', 'debit', p.amount::text),
      jsonb_build_object('role', 'receivable', 'credit', p.amount::text, 'partyId', v."party_id"))
  )
  from "better_supabase"."ledger_transactions" y
  join "better_supabase"."leases" v on v."id"::text = y."reference_id"
  cross join lateral (
    select sum(e."amount") as amount from "better_supabase"."ledger_entries" e
    where e."transaction_id" = y."id" and e."amount" > 0
  ) p
  where y."id"::text = source_id and y."reference_type" = 'leases' and y."kind" = 'lease.payment'
    and p.amount <> 0
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_lease_rent_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', y."tenant_id",
    'entryDate', y."period_start",
    'currency', y."currency",
    'memo', left('Rent from ' || y."period_start"::text || ': ' || coalesce(v."title", ''), 500),
    'lines', jsonb_build_array(
      jsonb_build_object('role', 'receivable', 'debit', y."amount"::text, 'partyId', v."party_id"),
      jsonb_build_object('role', 'revenue', 'credit', y."amount"::text))
  )
  from "better_supabase"."lease_charges" y join "better_supabase"."leases" v on v."id" = y."lease_id"
  where y."id"::text = source_id and y."amount" <> 0
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_opening_posted (
  tenant      uuid,
  fiscal_year integer
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from "better_supabase"."accounting_entries" y
    where y."tenant_id" = accounting_opening_posted.tenant and y."source_type" = 'opening_balance'
      and y."source_id" = accounting_opening_posted.fiscal_year::text and y."status" <> 'reversed'
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_opening_write (
  tenant      uuid,
  fiscal_year integer,
  account_id  uuid,
  party_id    uuid,
  amount      bigint
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_id uuid;
begin
  if accounting_opening_write.fiscal_year is null or accounting_opening_write.fiscal_year < 1900 or accounting_opening_write.fiscal_year > 9999 then
    raise exception 'the fiscal year must be a year' using errcode = '22023', hint = 'ACCOUNTING_OPENING_INVALID';
  end if;
  if accounting_opening_write.amount is null or accounting_opening_write.amount = 0 then
    raise exception 'an opening balance needs a non-zero amount; a debit balance is positive' using errcode = '22023', hint = 'ACCOUNTING_OPENING_INVALID';
  end if;
  if not exists (
    select 1 from "better_supabase"."accounting_accounts" y where y."id" = accounting_opening_write.account_id and y."tenant_id" = accounting_opening_write.tenant
  ) then
    raise exception 'an opening balance''s account isn''t an account of the organization' using errcode = 'P0002', hint = 'ACCOUNTING_ACCOUNT_NOT_FOUND';
  end if;
  if "better_supabase"."accounting_opening_posted"(accounting_opening_write.tenant, accounting_opening_write.fiscal_year) then
    raise exception 'the opening entry of the fiscal year is posted; reverse it first' using errcode = '55000', hint = 'ACCOUNTING_OPENING_POSTED';
  end if;
  insert into "better_supabase"."accounting_opening_balances" ("tenant_id", "fiscal_year", "account_id", "party_id", "amount", "source")
  values (accounting_opening_write.tenant, accounting_opening_write.fiscal_year, accounting_opening_write.account_id, accounting_opening_write.party_id, accounting_opening_write.amount, 'imported')
  on conflict ("tenant_id", "fiscal_year", "account_id", coalesce("party_id", '00000000-0000-0000-0000-000000000000'::uuid))
  do update set "amount" = excluded."amount", "source" = 'imported', "updated_at" = now()
  returning "id" into v_id;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_period_close_blockers (
  period_id uuid
)
  RETURNS text[]
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  v_period "better_supabase"."accounting_periods"%rowtype;
  v_blockers text[] := '{}';
begin
  select * into v_period from "better_supabase"."accounting_periods" x where x."id" = accounting_period_close_blockers.period_id;
  if not found then
    return null;
  end if;
  if exists (
      select 1 from "better_supabase"."accounting_entries" y
      where y."tenant_id" = v_period."tenant_id" and y."status" = 'draft'
        and y."entry_date" >= v_period."starts_on" and y."entry_date" <= v_period."ends_on"
    ) then
    v_blockers := v_blockers || 'draft_entries'::text;
  end if;
  if exists (
    select 1 from "better_supabase"."bank_transactions" y
    where y."tenant_id" = v_period."tenant_id" and y."status" = 'unmatched'
      and y."booked_on" >= v_period."starts_on" and y."booked_on" <= v_period."ends_on"
  ) then
    v_blockers := v_blockers || 'unreconciled_bank_transactions'::text;
  end if;
  return v_blockers;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_period_trial_balance (
  period_id  uuid,
  dimensions jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select "better_supabase"."accounting_trial_balance"(y."tenant_id", y."starts_on", y."ends_on", accounting_period_trial_balance.dimensions)
  from "better_supabase"."accounting_periods" y where y."id" = accounting_period_trial_balance.period_id
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_post (
  entry_id uuid,
  closing  boolean DEFAULT false
)
  RETURNS better_supabase.accounting_entries
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."accounting_entries"%rowtype;
  v_settings "better_supabase"."accounting_settings"%rowtype;
  v_period "better_supabase"."accounting_periods"%rowtype;
  v_journal "better_supabase"."accounting_journals"%rowtype;
  v_total numeric;
  v_credits numeric;
  v_count integer;
  v_sequence integer;
begin
  select * into v_row from "better_supabase"."accounting_entries" y where y."id" = accounting_post.entry_id for update;
  if not found then
    raise exception 'entry not found' using errcode = 'P0002', hint = 'ACCOUNTING_ENTRY_NOT_FOUND';
  end if;
  if v_row."status" <> 'draft' then
    raise exception 'a posted entry can''t change; reverse it' using errcode = '55000', hint = 'ACCOUNTING_ENTRY_POSTED';
  end if;
  select * into v_settings from "better_supabase"."accounting_settings" st where st."tenant_id" = v_row."tenant_id";
  if not found then
    raise exception 'accounting isn''t set up for this organization; call setup_accounting first' using errcode = 'P0002', hint = 'ACCOUNTING_SETTING_NOT_FOUND';
  end if;
  select count(*), coalesce(sum(y."debit"), 0), coalesce(sum(y."credit"), 0) into v_count, v_total, v_credits
  from "better_supabase"."accounting_entry_lines" y where y."entry_id" = v_row."id";
  if v_count < 2 then
    raise exception 'an entry needs at least two lines' using errcode = '22023', hint = 'ACCOUNTING_ENTRY_INVALID';
  end if;
  if v_total <> v_credits then
    raise exception 'the debits and credits of the entry differ in the functional currency' using errcode = '23514', hint = 'ACCOUNTING_ENTRY_UNBALANCED';
  end if;
  if exists (
    select 1 from "better_supabase"."accounting_entry_lines" y join "better_supabase"."accounting_accounts" z on z."id" = y."account_id"
    where y."entry_id" = v_row."id" and (z."archived_at" is not null or not z."active")
  ) then
    raise exception 'an account of the entry is archived or inactive' using errcode = '22023', hint = 'ACCOUNTING_ACCOUNT_INVALID';
  end if;
  if exists (
    select 1 from "better_supabase"."accounting_entry_lines" y, jsonb_each(y."dimensions") dim
    where y."entry_id" = v_row."id"
      and (jsonb_typeof(dim.value) <> 'string' or not exists (
        select 1 from "better_supabase"."accounting_dimensions" z join "better_supabase"."accounting_dimension_values" w on w."dimension_id" = z."id"
        where z."tenant_id" = v_row."tenant_id" and z."key" = dim.key
          and w."code" = dim.value #>> '{}' and w."archived_at" is null
      ))
  ) then
    raise exception 'a line names a dimension or value that doesn''t exist or is archived' using errcode = '22023', hint = 'ACCOUNTING_DIMENSION_INVALID';
  end if;
  select * into v_period from "better_supabase"."accounting_periods" y
  where y."tenant_id" = v_row."tenant_id" and v_row."entry_date" >= y."starts_on" and v_row."entry_date" <= y."ends_on";
  if not found then
    raise exception 'no period covers the entry date; open its fiscal year first' using errcode = 'P0002', hint = 'ACCOUNTING_PERIOD_NOT_FOUND';
  end if;
  if v_period."status" = 'locked' then
    raise exception 'the entry date is in a locked period' using errcode = '55000', hint = 'ACCOUNTING_PERIOD_LOCKED';
  end if;
  if not coalesce(accounting_post.closing, false) and (
    (v_period."status" = 'closed' and better_supabase.import_run() is null)
    or (v_settings."lock_date" is not null and v_row."entry_date" <= v_settings."lock_date")
  ) then
    raise exception 'the entry date is in a closed period or on or before the lock date' using errcode = '55000', hint = 'ACCOUNTING_PERIOD_CLOSED';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_accounting_entry_post"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  select * into v_journal from "better_supabase"."accounting_journals" y where y."id" = v_row."journal_id";
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_journal."id"::text || ':' || v_period."fiscal_year"::text, 0));
  select coalesce(max(y."sequence"), 0) + 1 into v_sequence from "better_supabase"."accounting_entries" y
  where y."journal_id" = v_journal."id" and y."fiscal_year" = v_period."fiscal_year";
  update "better_supabase"."accounting_entries" y set "status" = 'posted', "fiscal_year" = v_period."fiscal_year", "sequence" = v_sequence,
    "number" = v_journal."code" || '-' || v_period."fiscal_year"::text || '-' || lpad(v_sequence::text, 5, '0'),
    "period_id" = v_period."id", "posted_at" = now(), "posted_by" = auth.uid(), "updated_at" = now()
  where y."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('accounting_entry.posted', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'journalId', v_row."journal_id", 'number', v_row."number", 'entryDate', v_row."entry_date", 'sourceType', v_row."source_type", 'sourceId', v_row."source_id", 'reversesId', v_row."reverses_id", 'total', v_total::text), 'accounting-entries/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/accounting');
  perform better_supabase.audit_event(
    event_type => 'accounting_entry.posted',
    category => 'data',
    target_type => 'accounting_entry',
    record_id => v_row."id"::text,
    target_label => v_row."number",
    summary => 'posted entry ' || v_row."number",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'journalId', v_row."journal_id", 'number', v_row."number", 'entryDate', v_row."entry_date", 'sourceType', v_row."source_type", 'sourceId', v_row."source_id", 'reversesId', v_row."reverses_id", 'total', v_total::text)
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_accounting_entry_post"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_post_source (
  source_type text,
  source_id   text
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_doc jsonb;
  v_kind text;
  v_tenant uuid;
  v_settings "better_supabase"."accounting_settings"%rowtype;
  v_journal "better_supabase"."accounting_journals"%rowtype;
  v_period "better_supabase"."accounting_periods"%rowtype;
  v_row "better_supabase"."accounting_entries"%rowtype;
  v_date date;
  v_line record;
  v_amount bigint;
  v_functional bigint;
  v_rate numeric;
  v_currency text;
  v_account uuid;
  v_tax "better_supabase"."tax_codes"%rowtype;
  v_diff bigint;
  v_largest integer;
  v_accounts uuid[] := '{}';
  v_functionals bigint[] := '{}';
  v_amounts bigint[] := '{}';
  v_currencies text[] := '{}';
  v_rates numeric[] := '{}';
  v_taxes uuid[] := '{}';
  v_parties uuid[] := '{}';
  v_dimensions jsonb[] := '{}';
  v_descriptions text[] := '{}';
begin
  if accounting_post_source.source_type is null or accounting_post_source.source_id is null
    or accounting_post_source.source_type not in ('stock_movement', 'invoice', 'invoice_payment', 'invoice_charge', 'invoice_discount', 'invoice_write_off', 'invoice_party_payment', 'asset_depreciation', 'asset_disposal', 'lease_rent', 'lease_payment', 'expense_report', 'expense_reimbursement', 'gift', 'production_order', 'bank_transaction', 'till_count', 'till_deposit') then
    raise exception 'no installed block books this source type' using errcode = '22023', hint = 'ACCOUNTING_SOURCE_INVALID';
  end if;
  v_doc := case accounting_post_source.source_type
    when 'stock_movement' then "better_supabase"."accounting_stock_movement_lines"(accounting_post_source.source_id)
    when 'invoice' then "better_supabase"."accounting_invoice_lines"(accounting_post_source.source_id)
    when 'invoice_payment' then "better_supabase"."accounting_invoice_payment_lines"(accounting_post_source.source_id)
    when 'invoice_charge' then "better_supabase"."accounting_invoice_charge_lines"(accounting_post_source.source_id)
    when 'invoice_discount' then "better_supabase"."accounting_invoice_discount_lines"(accounting_post_source.source_id)
    when 'invoice_write_off' then "better_supabase"."accounting_invoice_write_off_lines"(accounting_post_source.source_id)
    when 'invoice_party_payment' then "better_supabase"."accounting_invoice_party_payment_lines"(accounting_post_source.source_id)
    when 'asset_depreciation' then "better_supabase"."accounting_asset_depreciation_lines"(accounting_post_source.source_id)
    when 'asset_disposal' then "better_supabase"."accounting_asset_disposal_lines"(accounting_post_source.source_id)
    when 'lease_rent' then "better_supabase"."accounting_lease_rent_lines"(accounting_post_source.source_id)
    when 'lease_payment' then "better_supabase"."accounting_lease_payment_lines"(accounting_post_source.source_id)
    when 'expense_report' then "better_supabase"."accounting_expense_report_lines"(accounting_post_source.source_id)
    when 'expense_reimbursement' then "better_supabase"."accounting_expense_reimbursement_lines"(accounting_post_source.source_id)
    when 'gift' then "better_supabase"."accounting_gift_lines"(accounting_post_source.source_id)
    when 'production_order' then "better_supabase"."accounting_production_order_lines"(accounting_post_source.source_id)
    when 'bank_transaction' then "better_supabase"."accounting_bank_transaction_lines"(accounting_post_source.source_id)
    when 'till_count' then "better_supabase"."accounting_till_count_lines"(accounting_post_source.source_id)
    when 'till_deposit' then "better_supabase"."accounting_till_deposit_lines"(accounting_post_source.source_id)
  end;
  v_kind := case accounting_post_source.source_type
    when 'stock_movement' then 'general'
    when 'invoice' then 'sales'
    when 'invoice_payment' then 'bank'
    when 'invoice_charge' then 'sales'
    when 'invoice_discount' then 'general'
    when 'invoice_write_off' then 'general'
    when 'invoice_party_payment' then 'bank'
    when 'asset_depreciation' then 'general'
    when 'asset_disposal' then 'general'
    when 'lease_rent' then 'sales'
    when 'lease_payment' then 'bank'
    when 'expense_report' then 'purchase'
    when 'expense_reimbursement' then 'bank'
    when 'gift' then 'bank'
    when 'production_order' then 'general'
    when 'bank_transaction' then 'bank'
    when 'till_count' then 'cash'
    when 'till_deposit' then 'bank'
  end;
  if v_doc is null or jsonb_typeof(v_doc -> 'lines') is distinct from 'array' then
    return null;
  end if;
  v_tenant := (v_doc ->> 'organizationId')::uuid;
  select * into v_settings from "better_supabase"."accounting_settings" y where y."tenant_id" = v_tenant;
  if not found then
    return null;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'accounting-source:' || v_tenant::text || ':' || accounting_post_source.source_type || ':' || accounting_post_source.source_id, 0));
  select * into v_row from "better_supabase"."accounting_entries" y
  where y."tenant_id" = v_tenant and y."source_type" = accounting_post_source.source_type
    and y."source_id" = accounting_post_source.source_id and y."status" <> 'reversed';
  if found then
    return v_row."id";
  end if;
  v_date := coalesce((v_doc ->> 'entryDate')::date, current_date);
  v_kind := coalesce(v_doc ->> 'journal', v_kind);
  if coalesce(v_doc ->> 'journalId', '') ~ '^[0-9a-fA-F-]{36}$' then
    select * into v_journal from "better_supabase"."accounting_journals" y
    where y."tenant_id" = v_tenant and y."id" = (v_doc ->> 'journalId')::uuid;
  end if;
  if v_journal."id" is null then
    select * into v_journal from "better_supabase"."accounting_journals" y
    where y."tenant_id" = v_tenant and y."type" = v_kind order by y."code" limit 1;
  end if;
  if v_journal."id" is null then
    raise exception 'the organization has no journal of the type this document books in' using errcode = 'P0002', hint = 'ACCOUNTING_JOURNAL_NOT_FOUND';
  end if;
  for v_line in select q.value from jsonb_array_elements(v_doc -> 'lines') q loop
    v_amount := coalesce((v_line.value ->> 'debit')::bigint, 0) - coalesce((v_line.value ->> 'credit')::bigint, 0);
    continue when v_amount = 0;
    v_tax := null;
    if v_line.value ->> 'taxCode' is not null then
      select * into v_tax from "better_supabase"."tax_codes" y
      where y."tenant_id" = v_tenant and y."code" = v_line.value ->> 'taxCode' and y."archived_at" is null
      order by y."legal_entity_id" nulls first limit 1;
    end if;
    if v_tax."id" is null and coalesce(v_line.value ->> 'taxRateBps', '') ~ '^[0-9]{1,6}$' then
      select * into v_tax from "better_supabase"."tax_codes" y
      where y."tenant_id" = v_tenant and "better_supabase"."tax_rate_on"(y."id", v_date) = (v_line.value ->> 'taxRateBps')::integer
        and y."type" = case when v_journal."type" = 'purchase' then 'purchase' else 'sales' end
        and y."archived_at" is null
      order by y."legal_entity_id" nulls first, y."code" limit 1;
    end if;
    v_account := null;
    if v_line.value ->> 'role' in ('tax_payable', 'tax_receivable') and v_tax."id" is not null then
      v_account := case when v_tax."type" = 'purchase' then v_tax."purchase_account_id"
        else coalesce(v_tax."sales_account_id", v_tax."purchase_account_id") end;
    elsif coalesce(v_line.value ->> 'accountId', '') ~ '^[0-9a-fA-F-]{36}$' then
      select y."id" into v_account from "better_supabase"."accounting_accounts" y where y."id" = (v_line.value ->> 'accountId')::uuid and y."tenant_id" = v_tenant and y."archived_at" is null;
    elsif v_line.value ->> 'accountCode' is not null then
      select y."id" into v_account from "better_supabase"."accounting_accounts" y where y."code" = v_line.value ->> 'accountCode' and y."tenant_id" = v_tenant and y."archived_at" is null;
    elsif v_line.value ->> 'role' is not null then
      select y."id" into v_account from "better_supabase"."accounting_account_roles" z join "better_supabase"."accounting_accounts" y on y."id" = z."account_id"
      where z."tenant_id" = v_tenant and z."role" = v_line.value ->> 'role' and y."archived_at" is null;
    end if;
    if v_account is null then
      select y."id" into v_account from "better_supabase"."accounting_account_roles" z join "better_supabase"."accounting_accounts" y on y."id" = z."account_id"
      where z."tenant_id" = v_tenant and z."role" = 'suspense' and y."archived_at" is null;
    end if;
    if v_account is null then
      raise exception 'no account plays the role a document line needs, and no account plays suspense' using errcode = 'P0002', hint = 'ACCOUNTING_ROLE_UNMAPPED';
    end if;
    v_currency := upper(coalesce(v_line.value ->> 'currency', v_doc ->> 'currency', v_settings."functional_currency"));
    v_rate := null;
    v_functional := v_amount;
    if v_currency <> v_settings."functional_currency" then
      v_rate := "better_supabase"."accounting_fx_rate"(v_tenant, v_currency, v_settings."functional_currency", v_date);
      v_functional := round(v_amount * v_rate)::bigint;
      continue when v_functional = 0;
    end if;
    v_accounts := v_accounts || v_account;
    v_functionals := v_functionals || v_functional;
    v_amounts := v_amounts || v_amount;
    v_currencies := v_currencies || v_currency;
    v_rates := v_rates || v_rate;
    v_taxes := v_taxes || v_tax."id";
    v_parties := v_parties || case when coalesce(v_line.value ->> 'partyId', '') ~ '^[0-9a-fA-F-]{36}$' then (v_line.value ->> 'partyId')::uuid end;
    v_dimensions := v_dimensions || case when jsonb_typeof(v_line.value -> 'dimensions') = 'object' then v_line.value -> 'dimensions' else '{}'::jsonb end;
    v_descriptions := v_descriptions || left(nullif(trim(v_line.value ->> 'description'), ''), 500);
  end loop;
  if coalesce(array_length(v_accounts, 1), 0) < 2 then
    return null;
  end if;
  -- Converting each line rounds on its own; the difference goes to the
  -- largest line on the side that is short.
  select coalesce(sum(u), 0) into v_diff from unnest(v_functionals) u;
  if v_diff <> 0 then
    select q.n into v_largest from unnest(v_functionals) with ordinality q(amount, n)
    where sign(q.amount) = -sign(v_diff) order by abs(q.amount) desc limit 1;
    if v_largest is null then
      raise exception 'the document''s lines don''t balance' using errcode = '23514', hint = 'ACCOUNTING_ENTRY_UNBALANCED';
    end if;
    v_functionals[v_largest] := v_functionals[v_largest] - v_diff;
  end if;
  insert into "better_supabase"."accounting_entries" ("tenant_id", "journal_id", "entry_date", "reference", "source_type", "source_id", "memo", "created_by", "period_id")
  values (v_tenant, v_journal."id", v_date, left(nullif(trim(v_doc ->> 'reference'), ''), 200),
    accounting_post_source.source_type, accounting_post_source.source_id, left(nullif(trim(v_doc ->> 'memo'), ''), 2000), auth.uid(),
    (select y."id" from "better_supabase"."accounting_periods" y where y."tenant_id" = v_tenant and v_date >= y."starts_on" and v_date <= y."ends_on"))
  returning * into v_row;
  insert into "better_supabase"."accounting_entry_lines" ("tenant_id", "entry_id", "position", "account_id", "debit", "credit", "currency",
    "amount_currency", "fx_rate", "tax_code_id", "party_id", "dimensions", "description")
  select v_tenant, v_row."id", u.n, u.account, greatest(u.functional, 0), greatest(-u.functional, 0), u.currency,
    case when u.rate is null then u.functional else u.amount end, u.rate, u.tax, u.party, u.dimensions, u.description
  from unnest(v_accounts, v_functionals, v_amounts, v_currencies, v_rates, v_taxes, v_parties, v_dimensions, v_descriptions)
    with ordinality u(account, functional, amount, currency, rate, tax, party, dimensions, description, n);
  select * into v_period from "better_supabase"."accounting_periods" y where y."id" = v_row."period_id";
  if found and v_period."status" = 'open'
    and (v_settings."lock_date" is null or v_date > v_settings."lock_date") then
    perform "better_supabase"."accounting_post"(v_row."id");
  end if;
  return v_row."id";
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_production_order_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', x."tenant_id",
    'entryDate', (x."completed_at" at time zone 'UTC')::date,
    'currency', x."currency",
    'reference', x."number",
    'memo', 'Production labor ' || x."number",
    'lines', jsonb_build_array(
      jsonb_build_object('role', 'work_in_progress', 'debit', x."labor_cost"::text),
      jsonb_build_object('role', 'expense', 'credit', x."labor_cost"::text))
  )
  from "better_supabase"."production_orders" x
  where x."id"::text = source_id and x."status" = 'done' and x."labor_cost" > 0
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_profit_and_loss (
  tenant     uuid,
  since      date  DEFAULT NULL::date,
  until      date  DEFAULT NULL::date,
  dimensions jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with sums as (
    select y."account_id" as account, sum(y."credit") - sum(y."debit") as credit_balance
    from "better_supabase"."accounting_entry_lines" y join "better_supabase"."accounting_entries" z on z."id" = y."entry_id"
    where z."tenant_id" = accounting_profit_and_loss.tenant and z."status" in ('posted', 'reversed')
      and y."dimensions" @> coalesce(accounting_profit_and_loss.dimensions, '{}'::jsonb)
      and z."source_type" is distinct from 'fiscal_year'
      and (accounting_profit_and_loss.since is null or z."entry_date" >= accounting_profit_and_loss.since)
      and (accounting_profit_and_loss.until is null or z."entry_date" <= accounting_profit_and_loss.until)
    group by y."account_id"
  ),
  kept as (
    select w.*, c.credit_balance from sums c join "better_supabase"."accounting_accounts" w on w."id" = c.account
    where w."type" in ('income', 'expense') and c.credit_balance <> 0
  )
  select jsonb_build_object(
    'income', coalesce((select jsonb_agg(jsonb_build_object('accountId', w."id", 'code', w."code", 'name', w."name", 'type', w."type", 'subtype', w."subtype", 'amount', (w.credit_balance)::text) order by w."code") from kept w where w."type" = 'income'), '[]'::jsonb),
    'expenses', coalesce((select jsonb_agg(jsonb_build_object('accountId', w."id", 'code', w."code", 'name', w."name", 'type', w."type", 'subtype', w."subtype", 'amount', (-w.credit_balance)::text) order by w."code") from kept w where w."type" = 'expense'), '[]'::jsonb),
    'totalIncome', coalesce((select sum(w.credit_balance) from kept w where w."type" = 'income'), 0)::text,
    'totalExpenses', coalesce((select -sum(w.credit_balance) from kept w where w."type" = 'expense'), 0)::text,
    'netIncome', coalesce((select sum(w.credit_balance) from kept w), 0)::text
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_range_close_blockers (
  tenant    uuid,
  starts_on date,
  ends_on   date
)
  RETURNS text[]
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce("better_supabase"."accounting_period_close_blockers"(x."id"), '{}'::text[])
  from "better_supabase"."accounting_periods" x
  where x."tenant_id" = accounting_range_close_blockers.tenant
    and x."starts_on" = accounting_range_close_blockers.starts_on
    and x."ends_on" = accounting_range_close_blockers.ends_on
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_reverse (
  entry_id   uuid,
  entry_date date DEFAULT NULL::date
)
  RETURNS better_supabase.accounting_entries
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."accounting_entries"%rowtype;
  v_reversal "better_supabase"."accounting_entries"%rowtype;
begin
  select * into v_row from "better_supabase"."accounting_entries" y where y."id" = accounting_reverse.entry_id for update;
  if not found then
    raise exception 'entry not found' using errcode = 'P0002', hint = 'ACCOUNTING_ENTRY_NOT_FOUND';
  end if;
  if v_row."status" = 'reversed' then
    raise exception 'the entry is already reversed' using errcode = '55000', hint = 'ACCOUNTING_ENTRY_REVERSED';
  end if;
  if v_row."status" <> 'posted' then
    raise exception 'only a posted entry can be reversed; delete a draft instead' using errcode = '22023', hint = 'ACCOUNTING_ENTRY_INVALID';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_accounting_entry_reverse"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  insert into "better_supabase"."accounting_entries" ("tenant_id", "journal_id", "entry_date", "reference", "reverses_id", "memo", "created_by")
  values (v_row."tenant_id", v_row."journal_id", coalesce(accounting_reverse.entry_date, v_row."entry_date"), v_row."number",
    v_row."id", 'Reversal of ' || v_row."number", auth.uid())
  returning * into v_reversal;
  insert into "better_supabase"."accounting_entry_lines" ("tenant_id", "entry_id", "position", "account_id", "debit", "credit", "currency",
    "amount_currency", "fx_rate", "tax_code_id", "party_id", "dimensions", "description")
  select y."tenant_id", v_reversal."id", y."position", y."account_id", y."credit", y."debit", y."currency",
    -y."amount_currency", y."fx_rate", y."tax_code_id", y."party_id", y."dimensions", y."description"
  from "better_supabase"."accounting_entry_lines" y where y."entry_id" = v_row."id";
  v_reversal := "better_supabase"."accounting_post"(v_reversal."id");
  update "better_supabase"."accounting_entries" y set "status" = 'reversed', "updated_at" = now() where y."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('accounting_entry.reversed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'journalId', v_row."journal_id", 'number', v_row."number", 'sourceType', v_row."source_type", 'sourceId', v_row."source_id", 'reversalId', v_reversal."id"), 'accounting-entries/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/accounting');
  perform better_supabase.audit_event(
    event_type => 'accounting_entry.reversed',
    category => 'data',
    target_type => 'accounting_entry',
    record_id => v_row."id"::text,
    target_label => v_row."number",
    summary => 'reversed entry ' || v_row."number" || ' with ' || v_reversal."number",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'journalId', v_row."journal_id", 'number', v_row."number", 'sourceType', v_row."source_type", 'sourceId', v_row."source_id", 'reversalId', v_reversal."id")
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_accounting_entry_reverse"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return v_reversal;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_reverse_source (
  tenant      uuid,
  source_type text,
  source_id   text,
  entry_date  date DEFAULT NULL::date
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."accounting_entries"%rowtype;
begin
  select * into v_row from "better_supabase"."accounting_entries" y
  where y."tenant_id" = accounting_reverse_source.tenant and y."source_type" = accounting_reverse_source.source_type
    and y."source_id" = accounting_reverse_source.source_id and y."status" <> 'reversed'
  for update;
  if not found then
    return null;
  end if;
  if v_row."status" = 'draft' then
    delete from "better_supabase"."accounting_entries" y where y."id" = v_row."id";
    return null;
  end if;
  return ("better_supabase"."accounting_reverse"(v_row."id", coalesce(accounting_reverse_source.entry_date, current_date)))."id";
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_stock_movement_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', y."tenant_id",
    'entryDate', (y."effective_at" at time zone 'UTC')::date,
    'currency', a."unit",
    'reference', y."reference_id",
    'memo', 'Stock ' || (y."metadata" ->> 'reason'),
    'lines', jsonb_build_array(
      jsonb_build_object('role', 'inventory', 'debit', e."amount"::text),
      jsonb_build_object('role', case y."metadata" ->> 'reason' when 'receipt' then 'payable' when 'sale' then 'cogs' when 'return' then 'cogs'
        when 'consumption' then 'work_in_progress' when 'production' then 'work_in_progress' else 'expense' end,
        'credit', e."amount"::text))
  )
  from "better_supabase"."ledger_transactions" y
  join "better_supabase"."ledger_entries" e on e."transaction_id" = y."id"
  join "better_supabase"."ledger_accounts" a on a."id" = e."account_id" and a."kind" = 'stock_value'
  where y."id"::text = source_id and e."amount" <> 0
  limit 1
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_sync_dimension_value (
  tenant         uuid,
  dimension_key  text,
  dimension_name text,
  code           text,
  value_name     text,
  archived       boolean DEFAULT false
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_dimension uuid;
begin
  insert into "better_supabase"."accounting_dimensions" ("tenant_id", "key", "name")
  values (accounting_sync_dimension_value.tenant, accounting_sync_dimension_value.dimension_key, accounting_sync_dimension_value.dimension_name)
  on conflict ("tenant_id", "key") do nothing;
  select y."id" into v_dimension from "better_supabase"."accounting_dimensions" y
  where y."tenant_id" = accounting_sync_dimension_value.tenant and y."key" = accounting_sync_dimension_value.dimension_key;
  insert into "better_supabase"."accounting_dimension_values" as y ("tenant_id", "dimension_id", "code", "name", "archived_at")
  values (accounting_sync_dimension_value.tenant, v_dimension, accounting_sync_dimension_value.code, left(accounting_sync_dimension_value.value_name, 200),
    case when accounting_sync_dimension_value.archived then now() end)
  on conflict ("dimension_id", "code") do update
    set "name" = excluded."name",
      "archived_at" = case when accounting_sync_dimension_value.archived then coalesce(y."archived_at", now()) end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_tax_report (
  tenant uuid,
  since  date,
  until  date
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with booked as (
    select y."tax_code_id" as tax_code, y."account_id" as account, y."credit" - y."debit" as net
    from "better_supabase"."accounting_entry_lines" y join "better_supabase"."accounting_entries" z on z."id" = y."entry_id"
    where z."tenant_id" = accounting_tax_report.tenant and z."status" in ('posted', 'reversed')
      and y."tax_code_id" is not null
      and z."entry_date" >= accounting_tax_report.since and z."entry_date" <= accounting_tax_report.until
  ),
  codes as (
    select w."id" as id, w."code" as code, w."name" as name,
      (case when w."type" = 'purchase' then 'purchase' else 'sales' end) as kind,
      coalesce("better_supabase"."tax_rate_on"(w."id", accounting_tax_report.until), 0) as rate_bps, w."return_boxes" as boxes,
      (case when w."type" = 'purchase' then -1 else 1 end) * coalesce(sum(b.net) filter (where b.account is distinct from (case when w."type" = 'purchase' then w."purchase_account_id" else coalesce(w."sales_account_id", w."purchase_account_id") end)), 0) as base,
      (case when w."type" = 'purchase' then -1 else 1 end) * coalesce(sum(b.net) filter (where b.account = (case when w."type" = 'purchase' then w."purchase_account_id" else coalesce(w."sales_account_id", w."purchase_account_id") end)), 0) as tax
    from booked b join "better_supabase"."tax_codes" w on w."id" = b.tax_code
    group by w."id"
  )
  select jsonb_build_object(
    'organizationId', accounting_tax_report.tenant,
    'since', accounting_tax_report.since,
    'until', accounting_tax_report.until,
    'currency', (select st."functional_currency" from "better_supabase"."accounting_settings" st where st."tenant_id" = accounting_tax_report.tenant),
    'codes', coalesce((select jsonb_agg(jsonb_build_object('taxCodeId', c.id, 'code', c.code, 'name', c.name, 'kind', c.kind,
      'rateBps', c.rate_bps, 'reportBoxes', to_jsonb(c.boxes), 'base', c.base::text, 'tax', c.tax::text) order by c.code) from codes c), '[]'::jsonb),
    'boxes', coalesce((select jsonb_agg(jsonb_build_object('box', x.box, 'base', x.base::text, 'tax', x.tax::text) order by x.box)
      from (select q.box, sum(c.base) as base, sum(c.tax) as tax from codes c cross join unnest(c.boxes) q(box) group by q.box) x), '[]'::jsonb),
    'salesTax', coalesce((select sum(c.tax) from codes c where c.kind = 'sales'), 0)::text,
    'purchaseTax', coalesce((select sum(c.tax) from codes c where c.kind = 'purchase'), 0)::text,
    'netTax', coalesce((select sum(case when c.kind = 'sales' then c.tax else -c.tax end) from codes c), 0)::text
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_till_count_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', v."tenant_id",
    'entryDate', (v."counted_at" at time zone 'UTC')::date,
    'currency', x."currency",
    'reference', left(v."session_id"::text, 8),
    'memo', left('Till count: ' || x."name", 500),
    'lines', case when v."variance_amount" > 0 then jsonb_build_array(
      jsonb_build_object('accountId', x."account_id", 'debit', v."variance_amount"::text),
      jsonb_build_object('role', 'suspense', 'credit', v."variance_amount"::text))
    else jsonb_build_array(
      jsonb_build_object('role', 'suspense', 'debit', (-v."variance_amount")::text),
      jsonb_build_object('accountId', x."account_id", 'credit', (-v."variance_amount")::text))
    end
  )
  from "better_supabase"."till_counts" v
  join "better_supabase"."till_sessions" y on y."id" = v."session_id"
  join "better_supabase"."tills" x on x."id" = y."till_id"
  where v."id"::text = source_id and v."variance_amount" <> 0 and x."account_id" is not null
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_till_deposit_lines (
  source_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', v."tenant_id",
    'entryDate', v."deposited_on",
    'currency', x."currency",
    'reference', left(coalesce(v."reference", v."id"::text), 100),
    'memo', left('Cash deposit: ' || x."name", 500),
    'lines', jsonb_build_array(
      jsonb_build_object('role', 'bank', 'debit', v."amount"::text),
      jsonb_build_object('accountId', x."account_id", 'credit', v."amount"::text))
  )
  from "better_supabase"."till_deposits" v
  join "better_supabase"."till_sessions" y on y."id" = v."session_id"
  join "better_supabase"."tills" x on x."id" = y."till_id"
  where v."id"::text = source_id and x."account_id" is not null
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accounting_trial_balance (
  tenant     uuid,
  since      date  DEFAULT NULL::date,
  until      date  DEFAULT NULL::date,
  dimensions jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with sums as (
    select y."account_id" as account,
      sum(case when z."entry_date" < accounting_trial_balance.since then y."debit" - y."credit" else 0 end) as opening,
      sum(case when accounting_trial_balance.since is null or z."entry_date" >= accounting_trial_balance.since then y."debit" else 0 end) as debit,
      sum(case when accounting_trial_balance.since is null or z."entry_date" >= accounting_trial_balance.since then y."credit" else 0 end) as credit
    from "better_supabase"."accounting_entry_lines" y join "better_supabase"."accounting_entries" z on z."id" = y."entry_id"
    where z."tenant_id" = accounting_trial_balance.tenant and z."status" in ('posted', 'reversed')
      and y."dimensions" @> coalesce(accounting_trial_balance.dimensions, '{}'::jsonb)
      and (accounting_trial_balance.until is null or z."entry_date" <= accounting_trial_balance.until)
    group by y."account_id"
  )
  select jsonb_build_object(
    'accounts', coalesce(jsonb_agg(jsonb_build_object('accountId', w."id", 'code', w."code", 'name', w."name", 'type', w."type",
      'opening', c.opening::text, 'debit', c.debit::text, 'credit', c.credit::text, 'closing', (c.opening + c.debit - c.credit)::text) order by w."code"), '[]'::jsonb),
    'totals', jsonb_build_object('opening', coalesce(sum(c.opening), 0)::text, 'debit', coalesce(sum(c.debit), 0)::text, 'credit', coalesce(sum(c.credit), 0)::text,
      'closing', coalesce(sum(c.opening + c.debit - c.credit), 0)::text)
  )
  from sums c join "better_supabase"."accounting_accounts" w on w."id" = c.account
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accrue_commission (
  tenant       uuid,
  seller_id    uuid,
  source_type  text,
  source_id    text,
  basis        bigint,
  currency     text,
  occurred_on  date   DEFAULT NULL::date,
  subject_type text   DEFAULT NULL::text,
  subject_id   text   DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (accrue_commission.tenant is not null and coalesce(better_supabase.can('tenant', accrue_commission.tenant, 'commissions.write'), false))) then
    raise exception 'not allowed to accrue commissions' using errcode = '42501', hint = 'COMMISSION_FORBIDDEN';
  end if;
  return "better_supabase"."commission_accrue"(accrue_commission.tenant, accrue_commission.seller_id, accrue_commission.source_type, accrue_commission.source_id,
    accrue_commission.basis, accrue_commission.currency, accrue_commission.occurred_on, accrue_commission.subject_type, accrue_commission.subject_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.accrue_leave (
  tenant          uuid,
  type_id         uuid,
  amount          numeric DEFAULT NULL::numeric,
  period          integer DEFAULT NULL::integer,
  user_ids        uuid[]  DEFAULT NULL::uuid[],
  idempotency_key text    DEFAULT NULL::text,
  note            text    DEFAULT NULL::text
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_type "better_supabase"."leave_types"%rowtype;
  v_amount numeric;
  v_user uuid;
  v_count integer := 0;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', accrue_leave.tenant, 'leave.manage'), false)) then
    raise exception 'not allowed to accrue leave' using errcode = '42501', hint = 'LEAVE_FORBIDDEN';
  end if;
  select * into v_type from "better_supabase"."leave_types" t where t."id" = accrue_leave.type_id and t."tenant_id" = accrue_leave.tenant;
  if not found then
    raise exception 'leave type not found' using errcode = 'P0002', hint = 'LEAVE_TYPE_NOT_FOUND';
  end if;
  v_amount := coalesce(accrue_leave.amount, v_type."allowance");
  if v_amount is null or v_amount <= 0 then
    raise exception 'name an amount, or give the type an allowance' using errcode = '22023', hint = 'LEAVE_INVALID';
  end if;
  for v_user in
    select m."user_id" from "public"."memberships" m
    where m."organization_id" = accrue_leave.tenant
      and (accrue_leave.user_ids is null or m."user_id" = any (accrue_leave.user_ids))
  loop
    continue when accrue_leave.idempotency_key is not null
      and "better_supabase"."leave_posted"(accrue_leave.tenant, v_user, v_type."id", accrue_leave.idempotency_key);
    perform "better_supabase"."leave_post"(accrue_leave.tenant, v_user, v_type."id", 'accrual', v_amount,
      coalesce(accrue_leave.period, extract(year from current_date)::integer), null, accrue_leave.note, accrue_leave.idempotency_key);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.acknowledge (
  subject_type text,
  subject_id   text,
  version_id   uuid DEFAULT NULL::uuid,
  signature_id uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_me uuid := auth.uid();
  v_tenant uuid;
  v_version uuid;
  v_row "better_supabase"."acknowledgements"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if v_me is null then
    raise exception 'sign in to acknowledge' using errcode = '42501', hint = 'ACKNOWLEDGEMENT_FORBIDDEN';
  end if;
  select x."tenant_id" into v_tenant
    from "better_supabase"."acknowledgement_assignments" x
    join "public"."memberships" m on m."organization_id" = x."tenant_id" and m."user_id" = v_me
    where x."subject_type" = acknowledge.subject_type and x."subject_id" = acknowledge.subject_id
      and ((x."principal_type" = 'user' and x."principal_id" = m."user_id"::text)
      or (x."principal_type" = 'role' and x."principal_id" in ('*', (select r."key" from "better_supabase"."roles" r where r."id" = m."role")))
      or (x."principal_type" = 'team' and exists (
        select 1 from "better_supabase"."team_members" tm
        where tm."tenant_id" = m."organization_id"
          and tm."user_id" = m."user_id"
          and tm."team_id"::text = x."principal_id"
      )))
    limit 1;
  if v_tenant is null then
    raise exception 'you aren''t asked to acknowledge this record' using errcode = '42501', hint = 'ACKNOWLEDGEMENT_NOT_ASSIGNED';
  end if;
  if not (coalesce(better_supabase.can('tenant', v_tenant, 'acknowledgements.acknowledge'), false) and case acknowledge.subject_type
    when 'compliance_policy' then exists (select 1 from "better_supabase"."compliance_policies" s where s."id" = (acknowledge.subject_id)::uuid and s."tenant_id" = v_tenant) and coalesce(better_supabase.can('tenant', v_tenant, 'compliance.read'), false)
    when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = (acknowledge.subject_id)::uuid and s."tenant_id" = v_tenant and (coalesce(better_supabase.can('tenant', v_tenant, 'drive.read'), false) and coalesce("better_supabase"."drive_node_readable"(s."id"), false)))
    else false
  end) then
    raise exception 'not allowed to acknowledge this record' using errcode = '42501', hint = 'ACKNOWLEDGEMENT_FORBIDDEN';
  end if;
  v_version := "better_supabase"."current_acknowledgement_version"(v_tenant, acknowledge.subject_type, acknowledge.subject_id);
  if v_version is null then
    raise exception 'the record has no version to acknowledge' using errcode = '55000', hint = 'ACKNOWLEDGEMENT_NO_VERSION';
  end if;
  if acknowledge.version_id is not null and acknowledge.version_id <> v_version then
    raise exception 'the record has a newer version; acknowledge that one' using errcode = '55000', hint = 'ACKNOWLEDGEMENT_VERSION_STALE';
  end if;
  if acknowledge.signature_id is not null and not exists (
    select 1 from "better_supabase"."signatures" sg
    join "better_supabase"."signature_requests" sr on sr."id" = sg."request_id"
    where sg."id" = acknowledge.signature_id
      and sg."signer" = v_me
      and sr."status" = 'completed'
      and sr."tenant_id" = v_tenant
      and sr."subject_type" = acknowledge.subject_type
      and sr."subject_id" = acknowledge.subject_id
      and sr."version_id" = v_version
  ) then
    raise exception 'the signature isn''t your completed signature on this version' using errcode = '22023', hint = 'ACKNOWLEDGEMENT_SIGNATURE_INVALID';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_acknowledgement_create"(uuid, text, text, uuid, uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::text, $4::uuid, $5::uuid)', v_hook::oid::regproc)
        using v_tenant, acknowledge.subject_type, acknowledge.subject_id, v_version, v_me;
    end if;
  end;
  insert into "better_supabase"."acknowledgements" ("tenant_id", "subject_type", "subject_id", "version_id", "user_id", "method", "signature_id")
  values (v_tenant, acknowledge.subject_type, acknowledge.subject_id, v_version, v_me, case when acknowledge.signature_id is null then 'click' else 'signature' end, acknowledge.signature_id)
  on conflict ("subject_type", "subject_id", "version_id", "user_id") do nothing
  returning * into v_row;
  if found then
    perform "better_supabase".emit_event('acknowledgement.created', jsonb_build_object('organizationId', v_row."tenant_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'versionId', v_row."version_id", 'userId', v_row."user_id"), 'acknowledgements/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/acknowledgements');
  perform better_supabase.audit_event(
    event_type => 'acknowledgement.created',
    category => 'data',
    target_type => 'acknowledgement',
    record_id => v_row."id"::text,
    summary => 'acknowledged ' || v_row."subject_type" || ' ' || v_row."subject_id",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'versionId', v_row."version_id", 'userId', v_row."user_id")
  );
    declare
    v_hook regprocedure := to_regprocedure('"public"."after_acknowledgement_create"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  else
    select * into v_row from "better_supabase"."acknowledgements" x
    where x."subject_type" = acknowledge.subject_type and x."subject_id" = acknowledge.subject_id
      and x."version_id" = v_version and x."user_id" = v_me;
  end if;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'versionId', v_row."version_id", 'userId', v_row."user_id", 'method', v_row."method", 'signatureId', v_row."signature_id", 'acknowledgedAt', v_row."acknowledged_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.acknowledgement_status (
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := coalesce(
    (select x."tenant_id" from "better_supabase"."acknowledgement_assignments" x where x."subject_type" = acknowledgement_status.subject_type and x."subject_id" = acknowledgement_status.subject_id limit 1),
    (select x."tenant_id" from "better_supabase"."acknowledgements" x where x."subject_type" = acknowledgement_status.subject_type and x."subject_id" = acknowledgement_status.subject_id limit 1),
    (select x."tenant_id" from "better_supabase"."versions" x where x."subject_type" = acknowledgement_status.subject_type and x."subject_id" = acknowledgement_status.subject_id limit 1)
  );
  v_version uuid;
  v_created timestamptz;
begin
  if v_tenant is null then
    return jsonb_build_object('versionId', null, 'required', 0, 'acknowledged', 0, 'pending', '[]'::jsonb);
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (coalesce(better_supabase.can('tenant', v_tenant, 'acknowledgements.read'), false) and case acknowledgement_status.subject_type
    when 'compliance_policy' then exists (select 1 from "better_supabase"."compliance_policies" s where s."id" = (acknowledgement_status.subject_id)::uuid and s."tenant_id" = v_tenant) and coalesce(better_supabase.can('tenant', v_tenant, 'compliance.read'), false)
    when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = (acknowledgement_status.subject_id)::uuid and s."tenant_id" = v_tenant and (coalesce(better_supabase.can('tenant', v_tenant, 'drive.read'), false) and coalesce("better_supabase"."drive_node_readable"(s."id"), false)))
    else false
  end)) then
    raise exception 'not allowed to read acknowledgements of this record' using errcode = '42501', hint = 'ACKNOWLEDGEMENT_FORBIDDEN';
  end if;
  v_version := "better_supabase"."current_acknowledgement_version"(v_tenant, acknowledgement_status.subject_type, acknowledgement_status.subject_id);
  select x."created_at" into v_created from "better_supabase"."versions" x where x."id" = v_version;
  return (
    select jsonb_build_object(
      'versionId', v_version,
      'required', count(*),
      'acknowledged', count(k."id"),
      'pending', coalesce(jsonb_agg(jsonb_build_object(
        'userId', c.user_id,
        'dueOn', (v_created)::date + c.due_in_days,
        'overdue', coalesce((v_created)::date + c.due_in_days < current_date, false)
      ) order by (v_created)::date + c.due_in_days nulls last, c.user_id) filter (where k."id" is null), '[]'::jsonb)
    )
    from (select m."user_id" as user_id, min(x."due_in_days") as due_in_days
      from "better_supabase"."acknowledgement_assignments" x
      join "public"."memberships" m on m."organization_id" = x."tenant_id"
      where x."tenant_id" = v_tenant and x."subject_type" = acknowledgement_status.subject_type and x."subject_id" = acknowledgement_status.subject_id
        and ((x."principal_type" = 'user' and x."principal_id" = m."user_id"::text)
      or (x."principal_type" = 'role' and x."principal_id" in ('*', (select r."key" from "better_supabase"."roles" r where r."id" = m."role")))
      or (x."principal_type" = 'team' and exists (
        select 1 from "better_supabase"."team_members" tm
        where tm."tenant_id" = m."organization_id"
          and tm."user_id" = m."user_id"
          and tm."team_id"::text = x."principal_id"
      )))
      group by m."user_id") c
    left join "better_supabase"."acknowledgements" k on k."subject_type" = acknowledgement_status.subject_type and k."subject_id" = acknowledgement_status.subject_id
      and k."version_id" = v_version and k."user_id" = c.user_id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.acknowledgements_of (
  subject_type text,
  subject_id   text,
  version_id   uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_tenant uuid := coalesce(
    (select x."tenant_id" from "better_supabase"."acknowledgement_assignments" x where x."subject_type" = acknowledgements_of.subject_type and x."subject_id" = acknowledgements_of.subject_id limit 1),
    (select x."tenant_id" from "better_supabase"."acknowledgements" x where x."subject_type" = acknowledgements_of.subject_type and x."subject_id" = acknowledgements_of.subject_id limit 1),
    (select x."tenant_id" from "better_supabase"."versions" x where x."subject_type" = acknowledgements_of.subject_type and x."subject_id" = acknowledgements_of.subject_id limit 1)
  );
  v_version uuid;
begin
  if v_tenant is null then
    return '[]'::jsonb;
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (coalesce(better_supabase.can('tenant', v_tenant, 'acknowledgements.read'), false) and case acknowledgements_of.subject_type
    when 'compliance_policy' then exists (select 1 from "better_supabase"."compliance_policies" s where s."id" = (acknowledgements_of.subject_id)::uuid and s."tenant_id" = v_tenant) and coalesce(better_supabase.can('tenant', v_tenant, 'compliance.read'), false)
    when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = (acknowledgements_of.subject_id)::uuid and s."tenant_id" = v_tenant and (coalesce(better_supabase.can('tenant', v_tenant, 'drive.read'), false) and coalesce("better_supabase"."drive_node_readable"(s."id"), false)))
    else false
  end)) then
    raise exception 'not allowed to read acknowledgements of this record' using errcode = '42501', hint = 'ACKNOWLEDGEMENT_FORBIDDEN';
  end if;
  v_version := coalesce(acknowledgements_of.version_id, "better_supabase"."current_acknowledgement_version"(v_tenant, acknowledgements_of.subject_type, acknowledgements_of.subject_id));
  return (
    select coalesce(jsonb_agg(jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'subjectType', x."subject_type", 'subjectId', x."subject_id", 'versionId', x."version_id", 'userId', x."user_id", 'method', x."method", 'signatureId', x."signature_id", 'acknowledgedAt', x."acknowledged_at") order by x."acknowledged_at"), '[]'::jsonb)
    from "better_supabase"."acknowledgements" x
    where x."tenant_id" = v_tenant
      and x."subject_type" = acknowledgements_of.subject_type
      and x."subject_id" = acknowledgements_of.subject_id
      and x."version_id" = v_version
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.acquire_lease (
  key     text,
  seconds integer DEFAULT 60,
  scope   text    DEFAULT ''::text
)
  RETURNS uuid
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  token uuid := gen_random_uuid();
  taken uuid;
begin
  insert into "better_supabase"."idempotency_leases" as l ("scope", "key", "holder", "expires_at")
  values (scope, key, token, now() + make_interval(secs => greatest(seconds, 1)))
  on conflict ("scope", "key") do update
    set "holder" = excluded."holder", "expires_at" = excluded."expires_at"
    where l."expires_at" <= now()
  returning l."holder" into taken;
  return taken;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.acquire_workflow_semaphore (
  key    text,
  holder text,
  max    integer,
  ttl    interval DEFAULT '00:05:00'::interval
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_held integer;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('workflow_semaphore'), pg_catalog.hashtext(key));
  delete from "better_supabase"."workflow_semaphores" x where x."key" = key and x."expires_at" < now();
  update "better_supabase"."workflow_semaphores" x set "expires_at" = now() + coalesce(ttl, interval '5 minutes')
  where x."key" = key and x."holder" = holder;
  if found then
    return true;
  end if;
  select count(*) into v_held from "better_supabase"."workflow_semaphores" x where x."key" = key;
  if v_held >= greatest(coalesce(max, 1), 1) then
    return false;
  end if;
  insert into "better_supabase"."workflow_semaphores" ("key", "holder", "expires_at")
  values (key, holder, now() + coalesce(ttl, interval '5 minutes'));
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.acting_member()
  RETURNS uuid
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  header text;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    return null;
  end if;
  header := nullif(current_setting('request.headers', true), '')::jsonb ->> 'x-bsb-actor';
  return case when header ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then header::uuid end;
exception when others then
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.activate_bom (
  bom_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."boms";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."boms" x where x."id" = activate_bom.bom_id for update;
  if not found then
    raise exception 'no such bill of materials' using errcode = 'P0002', hint = 'BOM_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'manufacturing.manage'), false))) then
    raise exception 'not allowed to activate bills of materials' using errcode = '42501', hint = 'MANUFACTURING_FORBIDDEN';
  end if;
  if v_row."status" = 'active' then
    return (jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'variantId', v_row."variant_id", 'version', v_row."version", 'status', v_row."status", 'quantity', v_row."quantity"::text, 'note', v_row."note", 'activatedAt', v_row."activated_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at") || jsonb_build_object(
    'components', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'variantId', y."variant_id", 'quantity', y."quantity"::text,
      'scrapBps', y."scrap_bps", 'operationId', y."operation_id", 'position', y."position") order by y."position", y."id")
      from "better_supabase"."bom_components" y where y."bom_id" = v_row."id"), '[]'::jsonb),
    'operations', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'sequence', y."sequence", 'workCenterId', y."work_center_id",
      'title', y."title", 'setupMinutes', y."setup_minutes"::text, 'runMinutesPerUnit', y."run_minutes_per_unit"::text,
      'instructionsNodeId', y."instructions_node_id", 'inspectionTemplate', y."inspection_template") order by y."sequence")
      from "better_supabase"."bom_operations" y where y."bom_id" = v_row."id"), '[]'::jsonb)));
  end if;
  if exists (select 1 from "better_supabase"."bom_components" y where y."bom_id" = v_row."id"
    and "better_supabase"."bom_reaches"(y."variant_id", v_row."variant_id")) then
    raise exception 'a component is made from the variant itself' using errcode = '22023', hint = 'BOM_CYCLE';
  end if;
  update "better_supabase"."boms" x set "status" = 'archived', "updated_at" = now()
  where x."variant_id" = v_row."variant_id" and x."status" = 'active';
  update "better_supabase"."boms" x set "status" = 'active', "activated_at" = now(), "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('bom.activated', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'variantId', v_row."variant_id", 'version', v_row."version", 'status', v_row."status"), 'boms/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/manufacturing');
  perform better_supabase.audit_event(
    event_type => 'bom.activated',
    category => 'data',
    target_type => 'bom',
    record_id => v_row."id"::text,
    target_label => 'v' || v_row."version"::text,
    summary => 'bill of materials activated',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'variantId', v_row."variant_id", 'version', v_row."version", 'status', v_row."status")
  );
  return (jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'variantId', v_row."variant_id", 'version', v_row."version", 'status', v_row."status", 'quantity', v_row."quantity"::text, 'note', v_row."note", 'activatedAt', v_row."activated_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at") || jsonb_build_object(
    'components', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'variantId', y."variant_id", 'quantity', y."quantity"::text,
      'scrapBps', y."scrap_bps", 'operationId', y."operation_id", 'position', y."position") order by y."position", y."id")
      from "better_supabase"."bom_components" y where y."bom_id" = v_row."id"), '[]'::jsonb),
    'operations', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'sequence', y."sequence", 'workCenterId', y."work_center_id",
      'title', y."title", 'setupMinutes', y."setup_minutes"::text, 'runMinutesPerUnit', y."run_minutes_per_unit"::text,
      'instructionsNodeId', y."instructions_node_id", 'inspectionTemplate', y."inspection_template") order by y."sequence")
      from "better_supabase"."bom_operations" y where y."bom_id" = v_row."id"), '[]'::jsonb)));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.activate_lease (
  lease_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."leases"%rowtype;
  v_account uuid;
  v_hold "better_supabase"."ledger_holds"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."leases" x where x."id" = activate_lease.lease_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'leases.manage'), false)) then
    raise exception 'no such lease you can read' using errcode = 'P0002', hint = 'LEASE_NOT_FOUND';
  end if;
  if v_row."status" <> 'draft' then
    raise exception 'only a draft lease can be activated' using errcode = '55000', hint = 'LEASE_STATUS_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('leases.unit:' || v_row."unit_id"::text, 0));
  if exists (
    select 1 from "better_supabase"."leases" x
    where x."unit_id" = v_row."unit_id" and x."id" <> v_row."id" and x."status" = 'active'
      and daterange(x."starts_on", x."ends_on") && daterange(v_row."starts_on", v_row."ends_on")
  ) then
    raise exception 'another active lease of this unit overlaps these dates' using errcode = '23P01', hint = 'LEASE_OVERLAP';
  end if;
  if v_row."deposit" > 0 then
    v_account := "better_supabase"."ledger_account_for"(v_row."tenant_id", 'rent_deposit', 'leases.deposit:' || v_row."id"::text, 'Deposit ' || v_row."title",
      v_row."currency"::text, 0::smallint, 'lease', v_row."id"::text, null, false, 'leases.read', 'leases',
      jsonb_build_object('leaseId', v_row."id"));
    perform "better_supabase"."ledger_post"(v_row."tenant_id", 'lease.deposit',
      jsonb_build_array(
        jsonb_build_object('account', v_account, 'amount', v_row."deposit"),
        jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_row."tenant_id", 'rent_cash', 'leases.cash:' || v_row."currency", 'Rent received ' || v_row."currency",
      v_row."currency"::text, 0::smallint, null, null, null, true, 'leases.read', 'leases', null), 'amount', -v_row."deposit")),
      'leases', v_row."id"::text, 'Deposit received', 'leases.deposit:' || v_row."id"::text, null,
      jsonb_build_object('leaseId', v_row."id"));
    v_hold := "better_supabase"."ledger_hold"(v_account, v_row."deposit", 'leases', v_row."id"::text, null);
  end if;
  update "better_supabase"."leases" x set "status" = 'active', "deposit_hold_id" = v_hold."id", "updated_at" = now()
    where x."id" = v_row."id"
    returning * into v_row;
  perform "better_supabase".emit_event('lease.activated', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'unitId', v_row."unit_id", 'partyType', v_row."party_type", 'partyId', v_row."party_id", 'status', v_row."status", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'rent', v_row."rent"::text, 'currency', v_row."currency"), 'leases/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/leases');
  perform better_supabase.audit_event(
    event_type => 'lease.activated',
    category => 'billing',
    target_type => 'lease',
    record_id => v_row."id"::text,
    target_label => v_row."title",
    summary => 'activated a lease',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'unitId', v_row."unit_id", 'partyType', v_row."party_type", 'partyId', v_row."party_id", 'status', v_row."status", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'rent', v_row."rent"::text, 'currency', v_row."currency")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'unitId', v_row."unit_id", 'partyType', v_row."party_type", 'partyId', v_row."party_id", 'title', v_row."title", 'status', v_row."status", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'rent', v_row."rent"::text, 'currency', v_row."currency", 'frequency', v_row."frequency", 'deposit', v_row."deposit"::text, 'depositHoldId', v_row."deposit_hold_id", 'depositHeld', coalesce((select h."amount" from "better_supabase"."ledger_holds" h where h."id" = v_row."deposit_hold_id" and h."status" = 'active'), 0)::text, 'balanceDue', coalesce((select y."balance" from "better_supabase"."ledger_accounts" x join "better_supabase"."ledger_balances" y on y."account_id" = x."id"
      where x."tenant_id" = v_row."tenant_id" and x."code" = 'leases.rent:' || v_row."id"::text), 0)::text, 'renewedAt', v_row."renewed_at", 'terminatedOn', v_row."terminated_on", 'terminationReason', v_row."termination_reason", 'metadata', v_row."metadata", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.active_announcements (
  tenant uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_user uuid := auth.uid();
  v_tenant uuid := active_announcements.tenant;
  v_role text;
begin
  if v_tenant is not null then
    v_role := better_supabase.organization_member_role(v_tenant, v_user);
    if v_role is null and not coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then
      v_tenant := null;
    end if;
  end if;
  return (
    select coalesce(jsonb_agg(to_jsonb(x) - 'targets' order by x."starts_at" desc), '[]'::jsonb)
    from "better_supabase"."announcements" x
    where x."starts_at" <= now()
      and (x."ends_at" is null or x."ends_at" > now())
      and case x."audience"
        when 'all' then true
        when 'tenant' then v_tenant is not null and v_tenant::text = any (x."targets")
        when 'role' then v_role is not null and v_role = any (x."targets")
        when 'plan' then v_tenant is not null and x."targets" && better_supabase.tenant_entitlements(v_tenant)
        else false
      end
      and not exists (
        select 1 from "better_supabase"."announcement_dismissals" s
        where s."announcement_id" = x."id" and s."user_id" = v_user
      )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.activities_of (
  subject_type text,
  subject_id   text,
  types        text[],
  before       timestamp with time zone,
  page_size    integer
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_rows jsonb;
begin
  select coalesce(jsonb_agg(p.value order by p.at desc, p.id desc), '[]'::jsonb) into v_rows
  from (
    select to_jsonb(x) || jsonb_build_object('subjects', coalesce((select jsonb_agg(jsonb_build_object('type', sx."subject_type", 'id', sx."subject_id") order by sx."position") from "better_supabase"."activity_subjects" sx where sx."activity_id" = x."id"), '[]'::jsonb), 'overdue', x."done_at" is null and x."due_at" < now()) as value, coalesce(x."done_at", x."due_at", x."created_at") as at, x."id" as id
    from "better_supabase"."activities" x
    join "better_supabase"."activity_subjects" k on k."activity_id" = x."id"
    where k."subject_type" = activities_of.subject_type and k."subject_id" = activities_of.subject_id
      and (activities_of.types is null or x."type" = any (activities_of.types))
      and (activities_of.before is null or coalesce(x."done_at", x."due_at", x."created_at") < activities_of.before)
    order by at desc, id desc
    limit least(greatest(coalesce(activities_of.page_size, 50), 1), 200)
  ) p;
  if jsonb_array_length(v_rows) > 0 then
    perform "better_supabase"."record_subject_read"(activities_of.subject_type, activities_of.subject_id, null, 'activities', 'activities_of');
  end if;
  return v_rows;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.activity_guest_readable (
  activity uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from "better_supabase"."activities" x
    join "better_supabase"."activity_subjects" k on k."activity_id" = x."id"
    where x."id" = activity_guest_readable.activity
      and x."audience" = 'subject'
      and ((k."tenant_id")::text, (k."subject_type")::text, (k."subject_id")::text) in (select g.tenant, g.subject_type, g.subject_id from better_supabase.portal_subjects('read') g)
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.activity_notes (
  activity uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object('activityId', nx."activity_id", 'organizationId', nx."tenant_id", 'summary', nx."summary", 'actionTaskIds', coalesce((select jsonb_agg(ax."task_id" order by ax."created_at", ax."id") from "better_supabase"."activity_note_actions" ax where ax."activity_id" = nx."activity_id"), '[]'::jsonb), 'model', nx."model", 'source', nx."source", 'createdBy', nx."created_by", 'createdAt', nx."created_at", 'updatedAt', nx."updated_at") from "better_supabase"."activity_notes" nx where nx."activity_id" = activity_notes.activity
$function$;

CREATE OR REPLACE FUNCTION better_supabase.activity_recordings (
  activity uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', rx."id", 'organizationId', rx."tenant_id", 'activityId', rx."activity_id", 'fileId', rx."file_id", 'filename', rx."filename", 'mediaType', rx."media_type", 'status', rx."status", 'language', rx."language", 'durationSeconds', rx."duration_seconds", 'error', rx."error", 'model', rx."model", 'segmentCount', (select count(*)::integer from "better_supabase"."activity_transcript_segments" sc where sc."recording_id" = rx."id"), 'createdBy', rx."created_by", 'createdAt', rx."created_at", 'transcribedAt', rx."transcribed_at") order by rx."created_at", rx."id"), '[]'::jsonb)
  from "better_supabase"."activity_recordings" rx
  where rx."activity_id" = activity_recordings.activity
$function$;

CREATE OR REPLACE FUNCTION better_supabase.activity_subject_deliveries (
  tenant       uuid,
  subject_type text,
  subject_id   text,
  before       timestamp with time zone,
  max_rows     integer
)
  RETURNS TABLE (
    entry jsonb,
    at    timestamp with time zone,
    id    text
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return query
  select jsonb_build_object('id', d."id"::text, 'tenant_id', ev."tenant_id", 'event_id', null::text, 'type', 'delivery.' || d."status", 'actor_id', null::uuid, 'subject_type', activity_subject_deliveries.subject_type, 'subject_id', activity_subject_deliveries.subject_id, 'summary', ev."summary", 'data', jsonb_strip_nulls(jsonb_build_object('notificationId', ev."id", 'notificationType', ev."type", 'channel', d."channel", 'status', d."status", 'userId', rc."user_id", 'providerStatus', d."provider_status", 'templateKey', d."template_key", 'error', d."error", 'deliveredAt', d."delivered_at")), 'occurred_at', d."created_at", 'source', 'delivery'),
    d."created_at", d."id"::text
  from "better_supabase"."notification_deliveries" d
  join "better_supabase"."notification_recipients" rc on rc."id" = d."recipient_id"
  join "better_supabase"."notification_events" ev on ev."id" = rc."event_id"
  where activity_subject_deliveries.subject_type = any ('{message,conversation,channel,company,person,deal,course,post,activity,quote,work_item,employee,ledger_account,invoice,product,product_variant,rfq,till,order,calendar_event,booking,asset,asset_location,lease,expense_report,expense_line,donation_fund,warranty_claim,work_order,shipment,contract,control,compliance_policy,qualification_type,risk,case,inspection,inspection_program,inspection_finding,form,meeting,meeting_decision,maintenance_plan,dam_usage_right,lims_sample,tax_code,production_order,work_center,bank_account,care_plan,incident,content_entry,document,customer,drive_node,organization,application,change_request,project,task}'::text[])
    and ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin'))
      or (coalesce(better_supabase.can('tenant', activity_subject_deliveries.tenant, 'timeline.read'), false) and coalesce(better_supabase.can('tenant', activity_subject_deliveries.tenant, 'notifications.send'), false)))
    and ev."tenant_id" = activity_subject_deliveries.tenant
    and ev."subject_type" = activity_subject_deliveries.subject_type
    and ev."subject_id" = activity_subject_deliveries.subject_id
    and (activity_subject_deliveries.before is null or d."created_at" < activity_subject_deliveries.before)
  order by d."created_at" desc, d."id" desc
  limit least(greatest(coalesce(activity_subject_deliveries.max_rows, 50), 1), 500);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.activity_subject_readable (
  subject_type text,
  subject_id   text
)
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
begin
  return coalesce("better_supabase"."can_subject"(subject_type, subject_id, 'read'), false);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.activity_transcript (
  recording uuid,
  after     integer,
  page_size integer
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(p.value order by p.position), '[]'::jsonb)
  from (
    select jsonb_build_object('position', sx."position", 'speaker', sx."speaker", 'speakerUserId', sx."speaker_id", 'startMs', sx."starts_ms", 'endMs', sx."ends_ms", 'text', sx."text", 'confidence', sx."confidence") as value, sx."position" as position
    from "better_supabase"."activity_transcript_segments" sx
    where sx."recording_id" = activity_transcript.recording
      and sx."position" > coalesce(activity_transcript.after, 0)
    order by sx."position"
    limit least(greatest(coalesce(activity_transcript.page_size, 500), 1), 5000)
  ) p
$function$;

CREATE OR REPLACE FUNCTION better_supabase.activity_with_transcripts (
  activity uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'activity', to_jsonb(x) || jsonb_build_object('subjects', coalesce((select jsonb_agg(jsonb_build_object('type', sx."subject_type", 'id', sx."subject_id") order by sx."position") from "better_supabase"."activity_subjects" sx where sx."activity_id" = x."id"), '[]'::jsonb), 'overdue', x."done_at" is null and x."due_at" < now()),
    'segments', coalesce((
      select jsonb_agg(jsonb_build_object('position', sx."position", 'speaker', sx."speaker", 'speakerUserId', sx."speaker_id", 'startMs', sx."starts_ms", 'endMs', sx."ends_ms", 'text', sx."text", 'confidence', sx."confidence") || jsonb_build_object('recordingId', rx."id") order by rx."created_at", rx."id", sx."position")
      from "better_supabase"."activity_recordings" rx
      join "better_supabase"."activity_transcript_segments" sx on sx."recording_id" = rx."id"
      where rx."activity_id" = x."id"
    ), '[]'::jsonb)
  )
  from "better_supabase"."activities" x
  where x."id" = activity_with_transcripts.activity
$function$;

CREATE OR REPLACE FUNCTION better_supabase.actor_may_write()
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select case
    when auth.jwt() is null then true
    when auth.jwt() -> 'act' ->> 'kind' = 'support'
      then coalesce(auth.jwt() -> 'act' -> 'read_only' = 'false'::jsonb, false)
    when auth.jwt() -> 'act' ->> 'kind' = 'agent'
      then coalesce(auth.jwt() -> 'act' -> 'read_only', 'false'::jsonb) = 'false'::jsonb
    when auth.jwt() -> 'act' ->> 'kind' is not null then false
    when auth.jwt() -> 'act' ->> 'session_id' is not null
      and auth.jwt() -> 'act' ->> 'kind' is null then false
    else true
  end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_ai_chat_participant (
  chat             uuid,
  participant      uuid,
  participant_role text  DEFAULT 'viewer'::text,
  fields           jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_chat record;
  v_role text := coalesce(add_ai_chat_participant.participant_role, 'viewer');
  v_row "better_supabase"."ai_chat_participants";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."id" as id, x."owner_id" as owner, x."tenant_id" as tenant into v_chat
  from "better_supabase"."ai_chats" x where x."id" = add_ai_chat_participant.chat for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(v_chat.owner = (select auth.uid()), false)) then
    raise exception 'No chat %', add_ai_chat_participant.chat using errcode = 'P0002', hint = 'AI_CHAT_NOT_FOUND';
  end if;
  if not coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') and not coalesce(better_supabase.can('tenant', v_chat.tenant, 'ai_chat.share'), false) then
    raise exception 'You may not share chats here' using errcode = '42501', hint = 'AI_CHAT_FORBIDDEN';
  end if;
  if v_role not in ('viewer', 'editor') then
    raise exception 'A participant is a viewer or an editor, not %', v_role using errcode = '22023', hint = 'AI_CHAT_INVALID';
  end if;
  if add_ai_chat_participant.participant is null or add_ai_chat_participant.participant = v_chat.owner then
    raise exception 'The owner already takes part in chat %', add_ai_chat_participant.chat using errcode = '22023', hint = 'AI_CHAT_INVALID';
  end if;
  if v_chat.tenant is not null and not coalesce(better_supabase.can_user(add_ai_chat_participant.participant, 'tenant', v_chat.tenant, 'ai_chat.read'), false) then
    raise exception '% can''t read chats in the chat''s organization', add_ai_chat_participant.participant using errcode = '22023', hint = 'AI_CHAT_INVALID';
  end if;
  insert into "better_supabase"."ai_chat_participants" ("chat_id", "user_id", "kind", "role", "added_by")
  values (v_chat.id, add_ai_chat_participant.participant, 'user', v_role, auth.uid())
  on conflict ("chat_id", "user_id") where "kind" = 'user' do update set "role" = excluded."role"
  returning * into v_row;
  update "better_supabase"."ai_chats" c set "visibility" = 'shared', "updated_at" = now()
  where c."id" = v_chat.id and c."visibility" = 'private';
  perform "better_supabase"."ai_chat_notify"(v_chat.id, add_ai_chat_participant.participant, 'participant.added', jsonb_build_object('userId', add_ai_chat_participant.participant, 'role', v_role), true);
  return jsonb_build_object('id', v_row."id", 'chat_id', v_row."chat_id", 'user_id', v_row."user_id", 'kind', v_row."kind", 'team_id', v_row."team_id", 'customer_id', v_row."customer_id", 'email', v_row."email", 'role', v_row."role", 'added_by', v_row."added_by", 'created_at', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_ai_chat_party (
  chat             uuid,
  party_kind       text,
  party            text,
  participant_role text DEFAULT 'viewer'::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_chat record;
  v_role text := coalesce(add_ai_chat_party.participant_role, 'viewer');
  v_team uuid;
  v_row "better_supabase"."ai_chat_participants";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."id" as id, x."owner_id" as owner, x."tenant_id" as tenant into v_chat
  from "better_supabase"."ai_chats" x where x."id" = add_ai_chat_party.chat for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(v_chat.owner = (select auth.uid()), false)) then
    raise exception 'No chat %', add_ai_chat_party.chat using errcode = 'P0002', hint = 'AI_CHAT_NOT_FOUND';
  end if;
  if not coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') and not coalesce(better_supabase.can('tenant', v_chat.tenant, 'ai_chat.share'), false) then
    raise exception 'You may not share chats here' using errcode = '42501', hint = 'AI_CHAT_FORBIDDEN';
  end if;
  if v_role not in ('viewer', 'editor') then
    raise exception 'A participant is a viewer or an editor, not %', v_role using errcode = '22023', hint = 'AI_CHAT_INVALID';
  end if;
  if add_ai_chat_party.party_kind not in ('team', 'customer', 'external') or add_ai_chat_party.party is null then
    raise exception 'A party is a team, a customer or an external email, not %', add_ai_chat_party.party_kind using errcode = '22023', hint = 'AI_CHAT_INVALID';
  end if;
  if add_ai_chat_party.party_kind = 'team' then
    v_team := add_ai_chat_party.party::uuid;
    if v_chat.tenant is null then
      raise exception 'A chat outside an organization has no teams' using errcode = '22023', hint = 'AI_CHAT_INVALID';
    end if;
  elsif add_ai_chat_party.party_kind = 'customer' then
    if v_chat.tenant is null then
      raise exception 'A customer needs a chat in an organization' using errcode = '22023', hint = 'AI_CHAT_INVALID';
    end if;
    if add_ai_chat_party.party::uuid = v_chat.owner then
      raise exception 'The owner already takes part in chat %', add_ai_chat_party.chat using errcode = '22023', hint = 'AI_CHAT_INVALID';
    end if;
  elsif add_ai_chat_party.party !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception '% is not an email address', add_ai_chat_party.party using errcode = '22023', hint = 'AI_CHAT_INVALID';
  end if;
  if add_ai_chat_party.party_kind = 'team' then
    insert into "better_supabase"."ai_chat_participants" ("chat_id", "kind", "team_id", "role", "added_by")
    values (v_chat.id, 'team', add_ai_chat_party.party::uuid, v_role, auth.uid())
    on conflict ("chat_id", "team_id") where "kind" = 'team' do update set "role" = excluded."role"
    returning * into v_row;
  elsif add_ai_chat_party.party_kind = 'customer' then
    insert into "better_supabase"."ai_chat_participants" ("chat_id", "kind", "customer_id", "role", "added_by")
    values (v_chat.id, 'customer', add_ai_chat_party.party::uuid, v_role, auth.uid())
    on conflict ("chat_id", "customer_id") where "kind" = 'customer' do update set "role" = excluded."role"
    returning * into v_row;
  elsif add_ai_chat_party.party_kind = 'external' then
    insert into "better_supabase"."ai_chat_participants" ("chat_id", "kind", "email", "role", "added_by")
    values (v_chat.id, 'external', lower(btrim(add_ai_chat_party.party)), v_role, auth.uid())
    on conflict ("chat_id", lower("email")) where "kind" = 'external' do update set "role" = excluded."role"
    returning * into v_row;
  end if;
  update "better_supabase"."ai_chats" c set "visibility" = 'shared', "updated_at" = now()
  where c."id" = v_chat.id and c."visibility" = 'private';
  perform "better_supabase"."ai_chat_notify"(v_chat.id, v_chat.owner, 'participant.added', jsonb_build_object('kind', add_ai_chat_party.party_kind, 'role', v_role), true);
  return jsonb_build_object('id', v_row."id", 'chat_id', v_row."chat_id", 'user_id', v_row."user_id", 'kind', v_row."kind", 'team_id', v_row."team_id", 'customer_id', v_row."customer_id", 'email', v_row."email", 'role', v_row."role", 'added_by', v_row."added_by", 'created_at', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_booking_exception (
  resource  uuid,
  starts_at timestamp with time zone,
  ends_at   timestamp with time zone,
  available boolean,
  reason    text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_tenant uuid;
  v_id uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select "tenant_id" into v_tenant from "better_supabase"."booking_resources" where "id" = add_booking_exception.resource;
  if not found then
    raise exception 'resource not found' using errcode = 'P0002', hint = 'BOOKING_RESOURCE_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'bookings.manage'), false)) then
    raise exception 'not allowed to manage bookings' using errcode = '42501', hint = 'BOOKING_FORBIDDEN';
  end if;
  if add_booking_exception.ends_at is null or add_booking_exception.starts_at is null or add_booking_exception.ends_at <= add_booking_exception.starts_at then
    raise exception 'an exception needs a start before its end' using errcode = '22023', hint = 'BOOKING_RANGE_INVALID';
  end if;
  insert into "better_supabase"."booking_exceptions" ("tenant_id", "resource_id", "during", "available", "reason")
  values (v_tenant, add_booking_exception.resource, tstzrange(add_booking_exception.starts_at, add_booking_exception.ends_at), coalesce(add_booking_exception.available, false), add_booking_exception.reason)
  returning "id" into v_id;
  return jsonb_build_object('id', v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_care_plan_action (
  goal_id uuid,
  input   jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_plan "better_supabase"."care_plans";
  v_goal "better_supabase"."care_plan_goals";
  v_row "better_supabase"."care_plan_actions";
  v_kind text := coalesce(nullif(add_care_plan_action.input ->> 'kind', ''), 'intervention');
  v_title text := trim(add_care_plan_action.input ->> 'title');
  v_measure_kind text := nullif(trim(add_care_plan_action.input ->> 'measureKind'), '');
  v_starts_on date := nullif(add_care_plan_action.input ->> 'startsOn', '')::date;
  v_ends_on date := nullif(add_care_plan_action.input ->> 'endsOn', '')::date;
  v_last text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_goal from "better_supabase"."care_plan_goals" z where z."id" = add_care_plan_action.goal_id;
  if not found then
    raise exception 'no such goal on a care plan' using errcode = 'P0002', hint = 'CARE_PLAN_GOAL_NOT_FOUND';
  end if;
  select * into v_plan from "better_supabase"."care_plans" x where x."id" = v_goal."plan_id" for update;
  if not found then
    raise exception 'no such care plan' using errcode = 'P0002', hint = 'CARE_PLAN_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_plan."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_plan."tenant_id", 'care_plans.write'), false))) then
    raise exception 'not allowed to change this care plan' using errcode = '42501', hint = 'CARE_PLAN_FORBIDDEN';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce("better_supabase"."can_subject"(v_plan."subject_type", v_plan."subject_id", 'read'), false)) then
    raise exception 'not allowed to read this client' using errcode = '42501', hint = 'CARE_PLAN_FORBIDDEN';
  end if;
  if v_plan."status" = 'archived' then
    raise exception 'the care plan is archived' using errcode = '55000', hint = 'CARE_PLAN_ARCHIVED';
  end if;
  if v_plan."status" <> 'draft' then
    raise exception 'only a draft care plan changes this way' using errcode = '55000', hint = 'CARE_PLAN_NOT_DRAFT';
  end if;
  if jsonb_typeof(add_care_plan_action.input) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if coalesce(length(v_title), 0) not between 1 and 300 then
    raise exception 'an action needs a title of 1 to 300 characters' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if add_care_plan_action.input ? 'frequency' and jsonb_typeof(add_care_plan_action.input -> 'frequency') not in ('object', 'null') then
    raise exception 'frequency must be an object' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if add_care_plan_action.input ? 'rank' and (add_care_plan_action.input ->> 'rank') !~ '^[0-9A-Za-z]*[1-9A-Za-z]$' then
    raise exception 'rank must be a rank key' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if length(add_care_plan_action.input ->> 'instructions') > 10000 then
    raise exception 'instructions is at most 10000 characters' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if length(add_care_plan_action.input ->> 'teamRole') > 63 or length(add_care_plan_action.input ->> 'measureKind') > 63 then
    raise exception 'teamRole and measureKind are at most 63 characters' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if v_kind is null or v_kind not in ('intervention', 'appointment', 'task', 'measure') then
    raise exception 'kind is intervention, appointment, task or measure' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if v_kind <> 'measure' and v_measure_kind is not null then
    raise exception 'only a measure has a measureKind' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if v_ends_on < v_starts_on then
    raise exception 'endsOn can''t be before startsOn' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  select max(w."rank") into v_last from "better_supabase"."care_plan_actions" w
  where w."tenant_id" = v_goal."tenant_id" and w."plan_id" = v_goal."plan_id" and w."goal_id" = v_goal."id";
  insert into "better_supabase"."care_plan_actions" ("tenant_id", "plan_id", "goal_id", "kind", "title", "instructions", "frequency", "team_role", "measure_kind", "booking_series_id", "requires_approval", "review_every", "starts_on", "ends_on", "rank")
  values (v_goal."tenant_id", v_goal."plan_id", v_goal."id", v_kind, v_title,
    nullif(trim(add_care_plan_action.input ->> 'instructions'), ''),
    nullif(add_care_plan_action.input -> 'frequency', 'null'::jsonb),
    nullif(trim(add_care_plan_action.input ->> 'teamRole'), ''),
    v_measure_kind,
    nullif(add_care_plan_action.input ->> 'bookingSeriesId', '')::uuid,
    v_kind = 'measure' or coalesce((add_care_plan_action.input ->> 'requiresApproval')::boolean, false),
    nullif(add_care_plan_action.input ->> 'reviewEvery', '')::interval,
    v_starts_on, v_ends_on,
    coalesce(add_care_plan_action.input ->> 'rank', case
    when v_last is null then 'V'
    when length(substring(v_last from '^z*')) = length(v_last) then v_last || 'V'
    else left(v_last, length(substring(v_last from '^z*'))) || substr('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', (strpos('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', substr(v_last, length(substring(v_last from '^z*')) + 1, 1)) - 1 + 62) / 2 + 1, 1)
  end))
  returning * into v_row;
  update "better_supabase"."care_plans" x set "updated_at" = now() where x."id" = v_plan."id";
  return jsonb_build_object('id', v_row."id", 'planId', v_row."plan_id", 'goalId', v_row."goal_id", 'kind', v_row."kind", 'title', v_row."title", 'instructions', v_row."instructions", 'frequency', v_row."frequency", 'teamRole', v_row."team_role", 'measureKind', v_row."measure_kind", 'taskId', v_row."task_id", 'bookingSeriesId', v_row."booking_series_id", 'requiresApproval', v_row."requires_approval", 'approvalId', v_row."approval_id", 'reviewEvery', case when v_row."review_every" is null then null else format('P%sY%sM%sDT%sH%sM%sS', extract(year from v_row."review_every")::int, extract(month from v_row."review_every")::int, extract(day from v_row."review_every")::int, extract(hour from v_row."review_every")::int, extract(minute from v_row."review_every")::int, trim_scale(extract(second from v_row."review_every"))) end, 'reviewedAt', v_row."reviewed_at", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'status', v_row."status", 'startedAt', v_row."started_at", 'endedAt', v_row."ended_at", 'endReason', v_row."end_reason", 'rank', v_row."rank", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
exception when check_violation then
  raise exception 'reviewEvery must be a positive interval' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_care_plan_goal (
  problem_id uuid,
  input      jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_plan "better_supabase"."care_plans";
  v_problem "better_supabase"."care_plan_problems";
  v_row "better_supabase"."care_plan_goals";
  v_title text := trim(add_care_plan_goal.input ->> 'title');
  v_last text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_problem from "better_supabase"."care_plan_problems" y where y."id" = add_care_plan_goal.problem_id;
  if not found then
    raise exception 'no such problem on a care plan' using errcode = 'P0002', hint = 'CARE_PLAN_NOT_FOUND';
  end if;
  select * into v_plan from "better_supabase"."care_plans" x where x."id" = v_problem."plan_id" for update;
  if not found then
    raise exception 'no such care plan' using errcode = 'P0002', hint = 'CARE_PLAN_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_plan."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_plan."tenant_id", 'care_plans.write'), false))) then
    raise exception 'not allowed to change this care plan' using errcode = '42501', hint = 'CARE_PLAN_FORBIDDEN';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce("better_supabase"."can_subject"(v_plan."subject_type", v_plan."subject_id", 'read'), false)) then
    raise exception 'not allowed to read this client' using errcode = '42501', hint = 'CARE_PLAN_FORBIDDEN';
  end if;
  if v_plan."status" = 'archived' then
    raise exception 'the care plan is archived' using errcode = '55000', hint = 'CARE_PLAN_ARCHIVED';
  end if;
  if v_plan."status" <> 'draft' then
    raise exception 'only a draft care plan changes this way' using errcode = '55000', hint = 'CARE_PLAN_NOT_DRAFT';
  end if;
  if jsonb_typeof(add_care_plan_goal.input) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if coalesce(length(v_title), 0) not between 1 and 300 then
    raise exception 'a goal needs a title of 1 to 300 characters' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if add_care_plan_goal.input ? 'measure' and jsonb_typeof(add_care_plan_goal.input -> 'measure') not in ('object', 'null') then
    raise exception 'measure must be an object' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if add_care_plan_goal.input ? 'rank' and (add_care_plan_goal.input ->> 'rank') !~ '^[0-9A-Za-z]*[1-9A-Za-z]$' then
    raise exception 'rank must be a rank key' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  select max(z."rank") into v_last from "better_supabase"."care_plan_goals" z
  where z."tenant_id" = v_problem."tenant_id" and z."plan_id" = v_problem."plan_id" and z."problem_id" = v_problem."id";
  insert into "better_supabase"."care_plan_goals" ("tenant_id", "plan_id", "problem_id", "title", "target_on", "measure", "rank")
  values (v_problem."tenant_id", v_problem."plan_id", v_problem."id", v_title,
    nullif(add_care_plan_goal.input ->> 'targetOn', '')::date,
    nullif(add_care_plan_goal.input -> 'measure', 'null'::jsonb),
    coalesce(add_care_plan_goal.input ->> 'rank', case
    when v_last is null then 'V'
    when length(substring(v_last from '^z*')) = length(v_last) then v_last || 'V'
    else left(v_last, length(substring(v_last from '^z*'))) || substr('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', (strpos('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', substr(v_last, length(substring(v_last from '^z*')) + 1, 1)) - 1 + 62) / 2 + 1, 1)
  end))
  returning * into v_row;
  update "better_supabase"."care_plans" x set "updated_at" = now() where x."id" = v_plan."id";
  return jsonb_build_object('id', v_row."id", 'planId', v_row."plan_id", 'problemId', v_row."problem_id", 'title', v_row."title", 'targetOn', v_row."target_on", 'status', v_row."status", 'measure', v_row."measure", 'rank', v_row."rank", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_care_plan_problem (
  plan_id uuid,
  input   jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_plan "better_supabase"."care_plans";
  v_row "better_supabase"."care_plan_problems";
  v_system text;
  v_title text := trim(add_care_plan_problem.input ->> 'title');
  v_last text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_plan from "better_supabase"."care_plans" x where x."id" = add_care_plan_problem.plan_id for update;
  if not found then
    raise exception 'no such care plan' using errcode = 'P0002', hint = 'CARE_PLAN_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_plan."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_plan."tenant_id", 'care_plans.write'), false))) then
    raise exception 'not allowed to change this care plan' using errcode = '42501', hint = 'CARE_PLAN_FORBIDDEN';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce("better_supabase"."can_subject"(v_plan."subject_type", v_plan."subject_id", 'read'), false)) then
    raise exception 'not allowed to read this client' using errcode = '42501', hint = 'CARE_PLAN_FORBIDDEN';
  end if;
  if v_plan."status" = 'archived' then
    raise exception 'the care plan is archived' using errcode = '55000', hint = 'CARE_PLAN_ARCHIVED';
  end if;
  if v_plan."status" <> 'draft' then
    raise exception 'only a draft care plan changes this way' using errcode = '55000', hint = 'CARE_PLAN_NOT_DRAFT';
  end if;
  if jsonb_typeof(add_care_plan_problem.input) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  v_system := coalesce(nullif(add_care_plan_problem.input ->> 'codeSystem', ''), (array['custom']::text[])[1]);
  if not (v_system = any (array['custom']::text[])) then
    raise exception 'the code system is not one of options.codeSystems' using errcode = '22023', hint = 'CARE_PLAN_CODE_SYSTEM_UNKNOWN';
  end if;
  if coalesce(length(v_title), 0) not between 1 and 300 then
    raise exception 'a problem needs a title of 1 to 300 characters' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if length(add_care_plan_problem.input ->> 'code') > 100 then
    raise exception 'code is at most 100 characters' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if length(add_care_plan_problem.input ->> 'description') > 10000 then
    raise exception 'description is at most 10000 characters' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if add_care_plan_problem.input ? 'rank' and (add_care_plan_problem.input ->> 'rank') !~ '^[0-9A-Za-z]*[1-9A-Za-z]$' then
    raise exception 'rank must be a rank key' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  select max(y."rank") into v_last from "better_supabase"."care_plan_problems" y
  where y."tenant_id" = v_plan."tenant_id" and y."plan_id" = v_plan."id";
  insert into "better_supabase"."care_plan_problems" ("tenant_id", "plan_id", "code_system", "code", "title", "description", "rank")
  values (v_plan."tenant_id", v_plan."id", v_system,
    nullif(trim(add_care_plan_problem.input ->> 'code'), ''), v_title,
    nullif(trim(add_care_plan_problem.input ->> 'description'), ''),
    coalesce(add_care_plan_problem.input ->> 'rank', case
    when v_last is null then 'V'
    when length(substring(v_last from '^z*')) = length(v_last) then v_last || 'V'
    else left(v_last, length(substring(v_last from '^z*'))) || substr('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', (strpos('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', substr(v_last, length(substring(v_last from '^z*')) + 1, 1)) - 1 + 62) / 2 + 1, 1)
  end))
  returning * into v_row;
  update "better_supabase"."care_plans" x set "updated_at" = now() where x."id" = v_plan."id";
  return jsonb_build_object('id', v_row."id", 'planId', v_row."plan_id", 'codeSystem', v_row."code_system", 'code', v_row."code", 'title', v_row."title", 'description', v_row."description", 'status', v_row."status", 'rank', v_row."rank", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_collection_entries (
  collection   uuid,
  subject_ids  text[],
  subject_type text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."subject_collections";
  v_id text;
  v_last text;
  v_rank text;
  v_added text[] := '{}';
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  
  if cardinality(add_collection_entries.subject_ids) > 1000 then
    raise exception 'at most 1000 ids per call' using errcode = '22023', hint = 'COLLECTION_TOO_MANY';
  end if;
  
  select * into v_row from "better_supabase"."subject_collections" where "id" = add_collection_entries.collection for update;
  if not found or not (auth.role() = 'service_role' or (coalesce(better_supabase.can('tenant', v_row."tenant_id", 'collections.read'), false) and (
      (v_row."scope" = 'user' and coalesce(v_row."owner_id" = auth.uid(), false))
      or (v_row."scope" = 'team' and v_row."team_id" in (select t::text from "better_supabase"."team_ids_of"((select auth.uid())) t))
      or v_row."scope" = 'tenant'))) then
    raise exception 'collection not found' using errcode = 'P0002', hint = 'COLLECTION_NOT_FOUND';
  end if;
  
  if not (auth.role() = 'service_role' or ((auth.role() = 'service_role' or (coalesce(better_supabase.can('tenant', v_row."tenant_id", 'collections.read'), false) and (
      (v_row."scope" = 'user' and coalesce(v_row."owner_id" = auth.uid(), false))
      or (v_row."scope" = 'team' and v_row."team_id" in (select t::text from "better_supabase"."team_ids_of"((select auth.uid())) t))
      or v_row."scope" = 'tenant'))) and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'collections.write'), false))) then
    raise exception 'not allowed to change this collection''s entries' using errcode = '42501', hint = 'COLLECTION_FORBIDDEN';
  end if;
  if v_row."archived_at" is not null then
    raise exception 'the collection is archived' using errcode = '55000', hint = 'COLLECTION_ARCHIVED';
  end if;
  if add_collection_entries.subject_type is not null and add_collection_entries.subject_type <> v_row."subject_type" then
    raise exception 'the collection holds another subject type' using errcode = '22023', hint = 'COLLECTION_SUBJECT_TYPE_MISMATCH';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_collection_add"(uuid, text[])');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text[])', v_hook::oid::regproc)
        using v_row."id", add_collection_entries.subject_ids;
    end if;
  end;
  select max(e."rank") into v_last from "better_supabase"."subject_collection_entries" e where e."collection_id" = v_row."id";
  for v_id in
    select u.id from unnest(coalesce(add_collection_entries.subject_ids, '{}')) with ordinality u (id, n)
    where u.id is not null
    group by u.id order by min(u.n)
  loop
    if not (case v_row."subject_type"
      when 'message' then exists (select 1 from "better_supabase"."messages" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'conversation' then exists (select 1 from "better_supabase"."conversations" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'channel' then exists (select 1 from "better_supabase"."channels" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'company' then exists (select 1 from "better_supabase"."companies" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'person' then exists (select 1 from "better_supabase"."people" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'deal' then exists (select 1 from "better_supabase"."deals" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'course' then exists (select 1 from "better_supabase"."courses" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'post' then exists (select 1 from "better_supabase"."posts" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'activity' then exists (select 1 from "better_supabase"."activities" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'quote' then exists (select 1 from "better_supabase"."quotes" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'work_item' then exists (select 1 from "better_supabase"."work_items" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'employee' then exists (select 1 from "better_supabase"."employees" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'ledger_account' then exists (select 1 from "better_supabase"."ledger_accounts" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'invoice' then exists (select 1 from "better_supabase"."invoices" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'product' then exists (select 1 from "better_supabase"."products" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'product_variant' then exists (select 1 from "better_supabase"."product_variants" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'rfq' then exists (select 1 from "better_supabase"."rfqs" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'till' then exists (select 1 from "better_supabase"."tills" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'order' then exists (select 1 from "better_supabase"."orders" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'calendar_event' then exists (select 1 from "better_supabase"."calendar_events" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'booking' then exists (select 1 from "better_supabase"."bookings" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'asset' then exists (select 1 from "better_supabase"."assets" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'asset_location' then exists (select 1 from "better_supabase"."asset_locations" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'lease' then exists (select 1 from "better_supabase"."leases" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'expense_report' then exists (select 1 from "better_supabase"."expense_reports" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'expense_line' then exists (select 1 from "better_supabase"."expense_lines" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'donation_fund' then exists (select 1 from "better_supabase"."donation_funds" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'warranty_claim' then exists (select 1 from "better_supabase"."warranty_claims" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'work_order' then exists (select 1 from "better_supabase"."work_orders" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'shipment' then exists (select 1 from "better_supabase"."shipments" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'contract' then exists (select 1 from "better_supabase"."contracts" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'control' then exists (select 1 from "better_supabase"."controls" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'compliance_policy' then exists (select 1 from "better_supabase"."compliance_policies" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'qualification_type' then exists (select 1 from "better_supabase"."qualification_types" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'risk' then exists (select 1 from "better_supabase"."risks" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'case' then exists (select 1 from "better_supabase"."cases" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'inspection' then exists (select 1 from "better_supabase"."inspections" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'inspection_program' then exists (select 1 from "better_supabase"."inspection_programs" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'inspection_finding' then exists (select 1 from "better_supabase"."inspection_findings" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'form' then exists (select 1 from "better_supabase"."forms" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'meeting' then exists (select 1 from "better_supabase"."meetings" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'meeting_decision' then exists (select 1 from "better_supabase"."meeting_decisions" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'maintenance_plan' then exists (select 1 from "better_supabase"."maintenance_plans" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'dam_usage_right' then exists (select 1 from "better_supabase"."dam_usage_rights" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'lims_sample' then exists (select 1 from "better_supabase"."lims_samples" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'tax_code' then exists (select 1 from "better_supabase"."tax_codes" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'production_order' then exists (select 1 from "better_supabase"."production_orders" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'work_center' then exists (select 1 from "better_supabase"."work_centers" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'bank_account' then exists (select 1 from "better_supabase"."bank_accounts" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'care_plan' then exists (select 1 from "better_supabase"."care_plans" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'incident' then exists (select 1 from "better_supabase"."incidents" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'content_entry' then exists (select 1 from "better_supabase"."content_entries" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'document' then exists (select 1 from "better_supabase"."documents" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'customer' then exists (select 1 from "public"."customers" s where s."id" = (v_id)::uuid and s."organization_id"::text = v_row."tenant_id"::text)
      when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'organization' then exists (select 1 from "public"."organizations" s where s."id" = (v_id)::uuid and s."id"::text = v_row."tenant_id"::text)
      when 'application' then exists (select 1 from "better_supabase"."applications" s where s."id" = (v_id)::uuid and s."tenant_id"::text = v_row."tenant_id"::text)
      when 'change_request' then exists (select 1 from "public"."change_requests" s where s."id" = (v_id)::uuid and s."organization_id"::text = v_row."tenant_id"::text)
      when 'project' then exists (select 1 from "public"."projects" s where s."id" = (v_id)::uuid and s."organization_id"::text = v_row."tenant_id"::text)
      when 'task' then exists (select 1 from "public"."tasks" s where s."id" = (v_id)::uuid and s."organization_id"::text = v_row."tenant_id"::text)
      else false
    end and "better_supabase"."can_subject"(v_row."subject_type", v_id, 'read')) then
      raise exception 'a record is unknown or not readable in this organization' using errcode = '42501', hint = 'COLLECTION_SUBJECT_FORBIDDEN';
    end if;
    v_rank := case
    when v_last is null then 'V'
    when length(substring(v_last from '^z*')) = length(v_last) then v_last || 'V'
    else left(v_last, length(substring(v_last from '^z*'))) || substr('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', (strpos('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', substr(v_last, length(substring(v_last from '^z*')) + 1, 1)) - 1 + 62) / 2 + 1, 1)
  end;
    insert into "better_supabase"."subject_collection_entries" ("collection_id", "tenant_id", "subject_type", "subject_id", "rank", "added_by")
    values (v_row."id", v_row."tenant_id", v_row."subject_type", v_id, v_rank, auth.uid())
    on conflict ("collection_id", "subject_id") do nothing;
    if found then
      v_last := v_rank;
      v_added := v_added || v_id;
      perform "better_supabase".emit_event('collection.entry_added', jsonb_build_object('organizationId', v_row."tenant_id", 'collectionId', v_row."id", 'subjectType', v_row."subject_type", 'subjectId', v_id), 'collections/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/collections');
    end if;
  end loop;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_collection_add"(uuid, text[])');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text[])', v_hook::oid::regproc)
        using v_row."id", v_added;
    end if;
  end;
  return jsonb_build_object('added', to_jsonb(v_added));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_control_evidence (
  control_id    uuid,
  attachment_id uuid DEFAULT NULL::uuid,
  note          text DEFAULT NULL::text,
  valid_until   date DEFAULT NULL::date,
  task_id       uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_control "better_supabase"."controls"%rowtype;
  v_task "better_supabase"."evidence_tasks"%rowtype;
  v_row "better_supabase"."control_evidence"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_control from "better_supabase"."controls" x where x."id" = add_control_evidence.control_id;
  if not found then
    raise exception 'control not found' using errcode = 'P0002', hint = 'CONTROL_NOT_FOUND';
  end if;
  if add_control_evidence.task_id is not null then
    select * into v_task from "better_supabase"."evidence_tasks" x
      where x."id" = add_control_evidence.task_id and x."control_id" = v_control."id"
      for update;
    if not found then
      raise exception 'the evidence task isn''t a task of this control' using errcode = 'P0002', hint = 'EVIDENCE_TASK_NOT_FOUND';
    end if;
  end if;
  if not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_control."tenant_id", 'compliance.collect'), false)) or (v_task."assignee_id" is not null and coalesce(v_task."assignee_id" = auth.uid(), false))) then
    raise exception 'not allowed to collect evidence' using errcode = '42501', hint = 'CONTROL_FORBIDDEN';
  end if;
  if add_control_evidence.attachment_id is null and nullif(trim(add_control_evidence.note), '') is null then
    raise exception 'evidence needs an attachment or a note' using errcode = '22023', hint = 'CONTROL_INVALID';
  end if;
  if add_control_evidence.attachment_id is not null and not exists (
    select 1 from "better_supabase"."attachments" a
    where a."id" = add_control_evidence.attachment_id
      and a."tenant_id" = v_control."tenant_id"
  ) then
    raise exception 'the attachment isn''t a file in this organization' using errcode = '22023', hint = 'CONTROL_INVALID';
  end if;
  insert into "better_supabase"."control_evidence" ("tenant_id", "control_id", "task_id", "attachment_id", "note", "collected_by", "valid_until")
  values (v_control."tenant_id", v_control."id", v_task."id", add_control_evidence.attachment_id,
    nullif(trim(add_control_evidence.note), ''), auth.uid(),
    coalesce(add_control_evidence.valid_until, current_date + v_task."interval_days"))
  returning * into v_row;
  if v_task."id" is not null then
    update "better_supabase"."evidence_tasks" x set "due_on" = current_date + x."interval_days", "last_collected_at" = now(),
      "notified_for" = null, "updated_at" = now()
      where x."id" = v_task."id";
  end if;
  perform "better_supabase".emit_event('control.evidence_added', jsonb_build_object('organizationId', v_row."tenant_id", 'controlId', v_row."control_id", 'evidenceId', v_row."id", 'evidenceTaskId', v_row."task_id"), 'controls/' || v_row."control_id"::text, (v_row."tenant_id")::text, null, 'better-supabase/compliance');
  perform better_supabase.audit_event(
    event_type => 'control.evidence_added',
    category => 'data',
    target_type => 'control',
    record_id => v_row."control_id"::text,
    summary => 'collected evidence for control ' || v_control."code",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'controlId', v_row."control_id", 'evidenceId', v_row."id", 'evidenceTaskId', v_row."task_id")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'controlId', v_row."control_id", 'evidenceTaskId', v_row."task_id", 'attachmentId', v_row."attachment_id", 'note', v_row."note", 'collectedBy', v_row."collected_by", 'collectedAt', v_row."collected_at", 'validUntil', v_row."valid_until", 'valid', (v_row."valid_until" is null or v_row."valid_until" >= current_date));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_conversation_members (
  conversation uuid,
  users        uuid[]
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_conv "better_supabase"."conversations";
  v_user uuid;
  v_added integer := 0;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_conv from "better_supabase"."conversations" c where c."id" = add_conversation_members.conversation;
  if not found or not "better_supabase"."can_conversation"(v_conv."id", 'read') then
    raise exception 'no such conversation you can read' using errcode = 'P0002', hint = 'MESSAGING_NOT_FOUND';
  end if;
  if v_conv."kind" in ('dm', 'group_dm', 'subject') then
    raise exception 'this conversation''s members can''t change' using errcode = '22023', hint = 'MESSAGING_MEMBERS_FIXED';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')
    or "better_supabase"."can_conversation"(v_conv."id", 'moderate')
    or ("better_supabase"."can_conversation"(v_conv."id", 'send') and (v_conv."access" = 'members' or coalesce(add_conversation_members.users <@ array[auth.uid()], false)))
    or (v_conv."access" = 'tenant' and v_conv."archived_at" is null and coalesce(add_conversation_members.users <@ array[auth.uid()], false))) then
    raise exception 'not allowed to add members here' using errcode = '42501', hint = 'MESSAGING_FORBIDDEN';
  end if;
  for v_user in select distinct x from unnest(add_conversation_members.users) x where x is not null loop
    if not coalesce(better_supabase.can_user(v_user, 'tenant', v_conv."tenant_id", 'messages.read'), false) then
      raise exception 'every member must be able to read messages in the organization' using errcode = '22023', hint = 'MESSAGING_MEMBER_INVALID';
    end if;
    insert into "better_supabase"."conversation_members" ("conversation_id", "tenant_id", "user_id")
    values (v_conv."id", v_conv."tenant_id", v_user)
    on conflict do nothing;
    if found then
      v_added := v_added + 1;
      perform "better_supabase".emit_event('conversation.member_added', jsonb_build_object('organizationId', v_conv."tenant_id"::text, 'conversationId', v_conv."id", 'kind', v_conv."kind", 'subjectType', 'conversation', 'subjectId', v_conv."id"::text, 'userId', v_user), 'conversations/' || v_conv."id"::text, (v_conv."tenant_id"::text)::text, null, 'better-supabase/messaging');
    end if;
  end loop;
  return v_added;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_employee_contract (
  employee uuid,
  attrs    jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_employee "better_supabase"."employees";
  v_row "better_supabase"."employee_contracts";
  v_starts date;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_employee from "better_supabase"."employees" x where x."id" = add_employee_contract.employee;
  if v_employee."id" is null or not ((auth.role() = 'service_role') or (coalesce(better_supabase.can('tenant', v_employee."tenant_id", 'employees.write'), false) and coalesce(better_supabase.can('tenant', v_employee."tenant_id", 'employees.read_sensitive'), false))) then
    raise exception 'no such employee whose details you can see' using errcode = 'P0002', hint = 'EMPLOYEE_NOT_FOUND';
  end if;
  begin
    v_starts := (add_employee_contract.attrs ->> 'startsOn')::date;
    if v_starts is null then
      raise exception 'a contract needs a start date' using errcode = '22023', hint = 'EMPLOYEE_CONTRACT_INVALID';
    end if;
    if exists (select 1 from "better_supabase"."employee_contracts" x where x."employee_id" = v_employee."id" and x."starts_on" >= v_starts) then
      raise exception 'a new contract starts after the latest one' using errcode = '22023', hint = 'EMPLOYEE_CONTRACT_OVERLAP';
    end if;
    update "better_supabase"."employee_contracts" x set "ends_on" = v_starts - 1
    where x."employee_id" = v_employee."id" and (x."ends_on" is null or x."ends_on" >= v_starts);
    insert into "better_supabase"."employee_contracts" ("tenant_id", "employee_id", "starts_on", "ends_on", "hours_per_week", "salary", "currency", "salary_period", "note", "created_by")
    values (v_employee."tenant_id", v_employee."id", v_starts, (add_employee_contract.attrs ->> 'endsOn')::date, (add_employee_contract.attrs ->> 'hoursPerWeek')::numeric, (add_employee_contract.attrs ->> 'salary')::bigint, upper(add_employee_contract.attrs ->> 'currency'), add_employee_contract.attrs ->> 'salaryPeriod', nullif(trim(add_employee_contract.attrs ->> 'note'), ''), auth.uid())
    returning * into v_row;
  exception when check_violation or not_null_violation or invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then
    raise exception 'a contract field has an invalid value' using errcode = '22023', hint = 'EMPLOYEE_CONTRACT_INVALID';
  end;
  perform "better_supabase".emit_event('employee.updated', jsonb_build_object('organizationId', v_employee."tenant_id", 'employeeId', v_employee."id", 'subjectType', 'employee', 'subjectId', v_employee."id"::text, 'name', v_employee."name", 'userId', v_employee."user_id", 'fields', jsonb_build_array('contract')), 'employees/' || v_employee."id"::text, (v_employee."tenant_id"::text)::text, null, 'better-supabase/employees');
  return to_jsonb(v_row) || jsonb_build_object('salary', v_row."salary"::text);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_eval_items (
  dataset uuid,
  items   jsonb
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_count integer;
begin
  if not exists (select 1 from "better_supabase"."eval_datasets" x where x."id" = add_eval_items.dataset) then
    raise exception 'No eval dataset %', add_eval_items.dataset using errcode = 'P0002', hint = 'EVAL_DATASET_NOT_FOUND';
  end if;
  if jsonb_typeof(add_eval_items.items) is distinct from 'array' then
    raise exception 'items must be a JSON array' using errcode = '22023', hint = 'EVAL_INVALID';
  end if;
  if exists (select 1 from jsonb_array_elements(add_eval_items.items) e where jsonb_typeof(e.value) <> 'object' or not (e.value ? 'input')) then
    raise exception 'every item needs an input' using errcode = '22023', hint = 'EVAL_INVALID';
  end if;
  if (select count(*) from "better_supabase"."eval_items" x where x."dataset_id" = add_eval_items.dataset) + jsonb_array_length(add_eval_items.items) > 5000 then
    raise exception 'A dataset holds at most 5000 items' using errcode = '54000', hint = 'EVAL_DATASET_FULL';
  end if;
  insert into "better_supabase"."eval_items" ("dataset_id", "input", "expected", "metadata")
  select add_eval_items.dataset, e.value -> 'input', e.value -> 'expected', coalesce(e.value -> 'metadata', '{}'::jsonb)
  from jsonb_array_elements(add_eval_items.items) e;
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_eval_items_from_feedback (
  dataset  uuid,
  rating   integer                  DEFAULT '-1'::integer,
  since    timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  max_rows integer                  DEFAULT 100
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_dataset "better_supabase"."eval_datasets"%rowtype;
  v_count integer;
begin
  select x.* into v_dataset from "better_supabase"."eval_datasets" x where x."id" = add_eval_items_from_feedback.dataset;
  if not found then
    raise exception 'No eval dataset %', add_eval_items_from_feedback.dataset using errcode = 'P0002', hint = 'EVAL_DATASET_NOT_FOUND';
  end if;
  if add_eval_items_from_feedback.rating not in (-1, 1) then
    raise exception 'rating must be 1 or -1' using errcode = '22023', hint = 'EVAL_INVALID';
  end if;
  with picked as materialized (
    select fb."chat_id" as chat_id, fb."message_id"::text as message_id,
      (select string_agg(p.value ->> 'text', '' order by p.ordinality) from jsonb_array_elements(case when jsonb_typeof(q.parts) = 'array' then q.parts else '[]'::jsonb end) with ordinality as p(value, ordinality) where p.value ->> 'type' = 'text') as prompt,
      (select string_agg(p.value ->> 'text', '' order by p.ordinality) from jsonb_array_elements(case when jsonb_typeof(a.parts) = 'array' then a.parts else '[]'::jsonb end) with ordinality as p(value, ordinality) where p.value ->> 'type' = 'text') as reply,
      fb."reason" as reason,
      fb."comment" as comment
    from "better_supabase"."ai_message_feedback" fb
    join "better_supabase"."ai_messages" a on a."chat_id" = fb."chat_id" and a."id" = fb."message_id"
    join "better_supabase"."ai_messages" q on q."chat_id" = a."chat_id" and q."id" = a."parent_id"
    join "better_supabase"."ai_chats" ch on ch."id" = fb."chat_id"
    where fb."rating" = add_eval_items_from_feedback.rating
      and (v_dataset."tenant_id" is null or ch."tenant_id" = v_dataset."tenant_id")
      and (add_eval_items_from_feedback.since is null or fb."updated_at" >= add_eval_items_from_feedback.since)
    order by fb."updated_at" desc
    limit least(greatest(coalesce(add_eval_items_from_feedback.max_rows, 100), 1), 1000)
  ), added as (
    insert into "better_supabase"."eval_items" ("dataset_id", "input", "expected", "metadata", "source_chat_id", "source_message_id")
    select v_dataset."id", jsonb_build_object('prompt', p.prompt),
      case when add_eval_items_from_feedback.rating = 1 then jsonb_build_object('output', p.reply) end,
      jsonb_build_object('source', 'ai-chat-feedback', 'rating', add_eval_items_from_feedback.rating, 'reason', p.reason, 'comment', p.comment, 'reply', p.reply),
      p.chat_id::text, p.message_id
    from picked p
    where p.prompt is not null
    on conflict do nothing
    returning 1
  )
  select count(*) into v_count from added;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_expense_line (
  report_id   uuid,
  category_id uuid,
  spent_on    date,
  amount      bigint,
  description text,
  merchant    text   DEFAULT NULL::text,
  currency    text   DEFAULT NULL::text,
  dimensions  jsonb  DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."expense_reports"%rowtype;
  v_approval "better_supabase"."approval_requests"%rowtype;
  v_category "better_supabase"."expense_categories"%rowtype;
  v_line "better_supabase"."expense_lines"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."expense_reports" x where x."id" = add_expense_line.report_id for update;
  if not found then
    raise exception 'no such expense report' using errcode = 'P0002', hint = 'EXPENSE_REPORT_NOT_FOUND';
  end if;
  select * into v_approval from "better_supabase"."approval_requests" p where p."id" = v_row."approval_id";
  if not (coalesce(v_row."user_id" = auth.uid(), false) and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'expenses.submit'), false)) then
    raise exception 'only the member who owns the report can change it' using errcode = '42501', hint = 'EXPENSES_FORBIDDEN';
  end if;
  if (case when v_row."cancelled_at" is not null then 'cancelled' when v_row."reimbursed_at" is not null then 'reimbursed' when v_row."approved_at" is not null then 'approved' when v_approval."status" = 'pending' then 'submitted' when v_approval."status" in ('rejected', 'expired') then 'rejected' else 'draft' end) not in ('draft', 'rejected') then
    raise exception 'only a draft or rejected report can change' using errcode = '55000', hint = 'EXPENSE_REPORT_LOCKED';
  end if;
  select * into v_category from "better_supabase"."expense_categories" c
    where c."id" = add_expense_line.category_id and c."tenant_id" = v_row."tenant_id" and c."archived_at" is null;
  if not found then
    raise exception 'the category is unknown, archived or not in this organization' using errcode = '22023', hint = 'EXPENSE_CATEGORY_INVALID';
  end if;
  if v_category."currency" is not null and v_category."currency" <> v_row."currency" then
    raise exception 'the category''s policy is in another currency than the report' using errcode = '22023', hint = 'EXPENSE_CURRENCY_MISMATCH';
  end if;
  if add_expense_line.spent_on is null then
    raise exception 'a line needs spent_on' using errcode = '22023', hint = 'EXPENSE_LINE_INVALID';
  end if;
  if add_expense_line.currency is not null and add_expense_line.currency <> v_row."currency" then
    raise exception 'the amount is in another currency than the report' using errcode = '22023', hint = 'EXPENSE_CURRENCY_MISMATCH';
  end if;
  if add_expense_line.amount is null or add_expense_line.amount <= 0 then
    raise exception 'an amount is more than zero minor units' using errcode = '22023', hint = 'EXPENSE_LINE_INVALID';
  end if;
  if nullif(trim(add_expense_line.description), '') is null then
    raise exception 'a line needs a description' using errcode = '22023', hint = 'EXPENSE_LINE_INVALID';
  end if;
  if add_expense_line.dimensions is not null and jsonb_typeof(add_expense_line.dimensions) not in ('object', 'null') then
    raise exception 'dimensions is an object of dimension keys and value codes' using errcode = '22023', hint = 'EXPENSE_LINE_INVALID';
  end if;
  insert into "better_supabase"."expense_lines" ("tenant_id", "report_id", "category_id", "spent_on", "description", "merchant", "dimensions", "amount")
  values (v_row."tenant_id", v_row."id", v_category."id", add_expense_line.spent_on, trim(add_expense_line.description),
    nullif(trim(add_expense_line.merchant), ''), coalesce(nullif(add_expense_line.dimensions, 'null'::jsonb), '{}'::jsonb), add_expense_line.amount)
  returning * into v_line;
  update "better_supabase"."expense_reports" x set "updated_at" = now() where x."id" = v_row."id";
  return jsonb_build_object('id', v_line."id", 'reportId', v_line."report_id", 'categoryId', v_line."category_id", 'spentOn', v_line."spent_on", 'description', v_line."description", 'merchant', v_line."merchant", 'dimensions', v_line."dimensions", 'amount', v_line."amount"::text, 'currency', (select rc."currency" from "better_supabase"."expense_reports" rc where rc."id" = v_line."report_id"), 'receipts', (select count(*) from "better_supabase"."attachments" t where t."subject_type" = 'expense_line' and t."subject_id" = v_line."id"::text and t."uploaded_at" is not null and t."status" <> 'infected'), 'createdAt', v_line."created_at", 'updatedAt', v_line."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_hostname (
  tenant   uuid,
  hostname text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."hostnames";
  v_hostname text := lower(trim(trailing '.' from trim(add_hostname.hostname)));
  v_kind text := 'custom';
  v_label text;
  v_new boolean;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', add_hostname.tenant, 'domains.manage'), false)) then
    raise exception 'You may not manage this organization''s hostnames' using errcode = '42501', hint = 'HOSTNAME_FORBIDDEN';
  end if;
  if v_hostname is null or length(v_hostname) > 253 or v_hostname !~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?[.])+[a-z]{2,63}$' then
    raise exception 'Not a hostname: %', add_hostname.hostname using errcode = '22023', hint = 'HOSTNAME_INVALID';
  end if;
  select * into v_row from "better_supabase"."hostnames" x where x."tenant_id" = add_hostname.tenant and x."hostname" = v_hostname;
  if v_row."id" is not null then
    return (to_jsonb(v_row) - 'verification_token') || case when v_row."verified_at" is null then jsonb_build_object('record', jsonb_build_object('type', 'TXT', 'name', '_better-supabase.' || v_row."hostname", 'value', 'better-supabase-hostname-verification=' || v_row."verification_token")) else '{}'::jsonb end;
  end if;
  if v_kind = 'subdomain' and exists (select 1 from "better_supabase"."hostnames" x where x."hostname" = v_hostname and x."verified_at" is not null) then
    raise exception 'Another organization holds %', v_hostname using errcode = '23505', hint = 'HOSTNAME_TAKEN';
  end if;
  insert into "better_supabase"."hostnames" ("tenant_id", "hostname", "kind", "verified_at")
  values (add_hostname.tenant, v_hostname, v_kind, case when v_kind = 'subdomain' then now() end)
  returning * into v_row;
  perform "better_supabase".emit_event('hostname.added', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'hostnameId', v_row."id"::text, 'hostname', v_row."hostname"), 'hostnames/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/domains');
  perform better_supabase.audit_event(
    event_type => 'hostname.added',
    category => 'configuration',
    target_type => 'hostname',
    record_id => v_row."id"::text,
    target_label => v_row."hostname",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'hostnameId', v_row."id"::text, 'hostname', v_row."hostname"),
    actor_id => auth.uid()
  );
  if v_row."verified_at" is not null then
    perform "better_supabase".emit_event('hostname.verified', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'hostnameId', v_row."id"::text, 'hostname', v_row."hostname"), 'hostnames/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/domains');
  perform better_supabase.audit_event(
    event_type => 'hostname.verified',
    category => 'configuration',
    target_type => 'hostname',
    record_id => v_row."id"::text,
    target_label => v_row."hostname",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'hostnameId', v_row."id"::text, 'hostname', v_row."hostname"),
    actor_id => auth.uid()
  );
  end if;
  return (to_jsonb(v_row) - 'verification_token') || case when v_row."verified_at" is null then jsonb_build_object('record', jsonb_build_object('type', 'TXT', 'name', '_better-supabase.' || v_row."hostname", 'value', 'better-supabase-hostname-verification=' || v_row."verification_token")) else '{}'::jsonb end;
exception when unique_violation then
  raise exception 'Another organization holds %', v_hostname using errcode = '23505', hint = 'HOSTNAME_TAKEN';
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_incident_postmortem_action (
  postmortem_id uuid,
  title         text,
  assignee_id   uuid                     DEFAULT NULL::uuid,
  due_at        timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_post "better_supabase"."incident_postmortems"%rowtype;
  v_task uuid;
  v_id uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_post from "better_supabase"."incident_postmortems" x where x."id" = add_incident_postmortem_action.postmortem_id;
  if not found then
    raise exception 'the incident has no postmortem' using errcode = 'P0002', hint = 'INCIDENT_POSTMORTEM_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_post."tenant_id", 'incidents.write'), false)) then
    raise exception 'not allowed to write postmortems' using errcode = '42501', hint = 'INCIDENTS_FORBIDDEN';
  end if;
  v_task := ("better_supabase"."create_work_item"(
    v_post."tenant_id",
    jsonb_strip_nulls(jsonb_build_object('title', add_incident_postmortem_action.title, 'dueAt', add_incident_postmortem_action.due_at)),
    case when add_incident_postmortem_action.assignee_id is null then '{}'::uuid[] else array[add_incident_postmortem_action.assignee_id] end
  ) ->> 'id')::uuid;
  insert into "better_supabase"."incident_postmortem_actions" ("tenant_id", "postmortem_id", "task_id")
  values (v_post."tenant_id", v_post."id", v_task)
  returning "id" into v_id;
  return (select jsonb_build_object('id', x."id", 'postmortemId', x."postmortem_id", 'taskId', x."task_id", 'title', k."title", 'state', k."state", 'dueAt', k."due_at", 'closedAt', k."closed_at", 'createdAt', x."created_at") from "better_supabase"."incident_postmortem_actions" x join "better_supabase"."work_items" k on k."id" = x."task_id" where x."id" = v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_inspection_finding (
  inspection_id uuid,
  type          text,
  title         text,
  description   text DEFAULT NULL::text,
  clause        text DEFAULT NULL::text,
  control_id    uuid DEFAULT NULL::uuid,
  evidence      text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_inspection "better_supabase"."inspections";
  v_row "better_supabase"."inspection_findings";
  v_type text := add_inspection_finding.type;
  v_title text := trim(add_inspection_finding.title);
  v_number integer;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_inspection from "better_supabase"."inspections" x where x."id" = add_inspection_finding.inspection_id for update;
  if not found then
    raise exception 'no such inspection' using errcode = 'P0002', hint = 'INSPECTION_NOT_FOUND';
  end if;
  if not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_inspection."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_inspection."tenant_id", 'inspections.manage'), false))) or (auth.uid() is not null and coalesce(better_supabase.can('tenant', v_inspection."tenant_id", 'inspections.write'), false) and coalesce("better_supabase"."inspection_role"(v_inspection."id") in ('lead', 'auditor'), false))) then
    raise exception 'not allowed to add findings to this inspection' using errcode = '42501', hint = 'INSPECTION_FORBIDDEN';
  end if;
  if v_inspection."status" not in ('in_progress', 'reporting') then
    raise exception 'findings change while the inspection is in progress or reporting' using errcode = '55000', hint = 'INSPECTION_STATUS_INVALID';
  end if;
  if v_type is null or not (v_type = any (array['major_nonconformity', 'minor_nonconformity', 'observation', 'opportunity', 'positive']::text[])) then
    raise exception 'the type is not one of options.findingTypes' using errcode = '22023', hint = 'INSPECTION_FINDING_TYPE_UNKNOWN';
  end if;
  if coalesce(length(v_title), 0) not between 1 and 300 then
    raise exception 'a finding needs a title of 1 to 300 characters' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  if length(add_inspection_finding.description) > 10000 then
    raise exception 'description is at most 10000 characters' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  if length(add_inspection_finding.clause) > 200 then
    raise exception 'clause is at most 200 characters' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  if length(add_inspection_finding.evidence) > 10000 then
    raise exception 'evidence is at most 10000 characters' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  if add_inspection_finding.control_id is not null and not exists (
    select 1 from "better_supabase"."controls" y
    where y."id" = add_inspection_finding.control_id and y."tenant_id"::text = v_inspection."tenant_id"::text
  ) then
    raise exception 'the control is not a control of this organization' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_inspection_finding_create"(uuid, jsonb)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::jsonb)', v_hook::oid::regproc)
        using add_inspection_finding.inspection_id, jsonb_build_object('type', add_inspection_finding.type, 'title', add_inspection_finding.title, 'controlId', add_inspection_finding.control_id);
    end if;
  end;
  select coalesce(max(y."number"), 0) + 1 into v_number from "better_supabase"."inspection_findings" y where y."inspection_id" = v_inspection."id";
  insert into "better_supabase"."inspection_findings" ("tenant_id", "inspection_id", "number", "type", "title", "description", "clause", "evidence", "control_id", "created_by")
  values (v_inspection."tenant_id", v_inspection."id", v_number, v_type, v_title, nullif(trim(add_inspection_finding.description), ''), nullif(trim(add_inspection_finding.clause), ''), nullif(trim(add_inspection_finding.evidence), ''), add_inspection_finding.control_id, auth.uid())
  returning * into v_row;
  if v_row."control_id" is not null then
    insert into "better_supabase"."relations" ("tenant_id", "kind", "source_type", "source_id", "target_type", "target_id", "created_by")
    select v_row."tenant_id", 'assesses', 'inspection', v_row."inspection_id"::text, 'control', v_row."control_id"::text, auth.uid()
    where not exists (
      select 1 from "better_supabase"."relations" y
      where y."tenant_id" = v_row."tenant_id" and y."kind" = 'assesses' and y."source_type" = 'inspection'
        and y."source_id" = v_row."inspection_id"::text and y."target_type" = 'control' and y."target_id" = v_row."control_id"::text
    );
  end if;
  perform "better_supabase".emit_event('inspection_finding.created', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'inspectionId', v_row."inspection_id", 'number', v_row."number", 'type', v_row."type", 'title', v_row."title"), 'inspection-findings/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/inspections');
  perform better_supabase.audit_event(
    event_type => 'inspection_finding.created',
    category => 'data',
    target_type => 'inspection_finding',
    record_id => v_row."id"::text,
    target_label => v_row."title",
    summary => 'finding added',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'inspectionId', v_row."inspection_id", 'number', v_row."number", 'type', v_row."type", 'title', v_row."title")
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_inspection_finding_create"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'inspectionId', v_row."inspection_id", 'number', v_row."number", 'type', v_row."type", 'title', v_row."title", 'description', v_row."description", 'clause', v_row."clause", 'controlId', v_row."control_id", 'evidence', v_row."evidence", 'caseId', v_row."case_id", 'needsCase', v_row."type" = any (array['major_nonconformity', 'minor_nonconformity']::text[]), 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_invoice_charge (
  invoice     uuid,
  amount      bigint,
  currency    text,
  description text,
  actor       jsonb  DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."invoices";
  v_charge uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."invoices" x where x."id" = add_invoice_charge.invoice and ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', x."tenant_id", case when x."direction" = 'purchase' then 'invoices.purchase' else 'invoices.write' end), false)) for update;
  if v_row."id" is null then
    raise exception 'no such invoice you can edit' using errcode = 'P0002', hint = 'INVOICE_NOT_FOUND';
  end if;
  if v_row."kind" <> 'invoice' or v_row."status" not in ('issued', 'partially_paid', 'paid') then
    raise exception 'only an issued invoice takes charges' using errcode = '55000', hint = 'INVOICE_NOT_CHARGEABLE';
  end if;
  if coalesce(add_invoice_charge.amount, 0) <= 0 then
    raise exception 'a charge has a positive amount' using errcode = '22023', hint = 'INVOICE_CHARGE_INVALID';
  end if;
  if upper(add_invoice_charge.currency) is distinct from v_row."currency" then
    raise exception 'a charge must be in the invoice''s currency' using errcode = '22023', hint = 'INVOICE_CURRENCY_MISMATCH';
  end if;
  if add_invoice_charge.actor is not null then
    if jsonb_typeof(add_invoice_charge.actor) <> 'object' then
      raise exception 'actor must be an object of id, name, email, ip and userAgent' using errcode = '22023', hint = 'INVOICE_ACTOR_INVALID';
    end if;
    begin
      perform nullif(add_invoice_charge.actor ->> 'ip', '')::inet, nullif(add_invoice_charge.actor ->> 'id', '')::uuid;
    exception when invalid_text_representation then
      raise exception 'actor.ip must be an IP address and actor.id a user id' using errcode = '22023', hint = 'INVOICE_ACTOR_INVALID';
    end;
  end if;
  perform set_config('better_supabase.transition_actor', coalesce(add_invoice_charge.actor::text, ''), true);
  insert into "better_supabase"."invoice_charges" ("tenant_id", "invoice_id", "amount", "currency", "description", "created_by")
  values (v_row."tenant_id", v_row."id", add_invoice_charge.amount, v_row."currency", nullif(trim(add_invoice_charge.description), ''), auth.uid())
  returning "id" into v_charge;
  update "better_supabase"."invoices" x set
    "paid_total" = coalesce(-(select sum(e."amount") from "better_supabase"."ledger_entries" e where e."account_id" = (select a."id" from "better_supabase"."ledger_accounts" a where a."tenant_id" = x."tenant_id" and a."code" = 'invoice:' || x."id"::text)), 0),
    "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  update "better_supabase"."invoices" x set
    "status" = case
      when (x."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = x."id"), 0) - x."credited_total" - x."paid_total") <= 0 then 'paid'
      when x."paid_total" > 0 or x."credited_total" > 0 then 'partially_paid'
      else 'issued' end,
    "paid_at" = case when (x."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = x."id"), 0) - x."credited_total" - x."paid_total") <= 0 then coalesce(x."paid_at", now()) end
  where x."id" = v_row."id" and x."status" in ('issued', 'partially_paid', 'paid')
  returning * into v_row;
  if not better_supabase.import_run() is not null then
    perform "better_supabase"."accounting_post_source"('invoice_charge', v_charge::text);
  end if;
  perform "better_supabase".emit_event('invoice.charged', jsonb_build_object('organizationId', v_row."tenant_id", 'invoiceId', v_row."id", 'subjectType', 'invoice', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier", 'chargeId', v_charge, 'amount', add_invoice_charge.amount::text, 'balance', (v_row."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), 0) - v_row."credited_total" - v_row."paid_total")::text), 'invoices/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/invoices');
  perform better_supabase.audit_event(
    event_type => 'invoice.charged',
    category => 'billing',
    target_type => 'invoice',
    record_id => v_row."id"::text,
    target_label => v_row."identifier",
    summary => 'invoice charged',
    tenant => (v_row."tenant_id"::text)::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'invoiceId', v_row."id", 'subjectType', 'invoice', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier", 'chargeId', v_charge, 'amount', add_invoice_charge.amount::text, 'balance', (v_row."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), 0) - v_row."credited_total" - v_row."paid_total")::text)
  );
  return to_jsonb(v_row) || jsonb_build_object('number', v_row."number"::text, 'paid_total', v_row."paid_total"::text, 'credited_total', v_row."credited_total"::text, 'list_total', v_row."list_total"::text, 'discount_total', v_row."discount_total"::text, 'subtotal', v_row."subtotal"::text, 'tax_total', v_row."tax_total"::text, 'total', v_row."total"::text, 'deposit_amount', v_row."deposit_amount"::text, 'discount_amount', v_row."discount_amount"::text, 'discount_amount_early', v_row."discount_amount_early"::text) || jsonb_build_object(
      'balance', (v_row."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), 0) - v_row."credited_total" - v_row."paid_total")::text,
      'charged_total', coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), 0)::text,
      'charges', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'amount', y."amount"::text, 'description', y."description", 'createdAt', y."created_at") order by y."created_at") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), '[]'::jsonb),
      'overdue', v_row."status" in ('issued', 'partially_paid') and v_row."due_on" < current_date,
      'lines', coalesce((select jsonb_agg(jsonb_build_object('description', il."description", 'quantity', il."quantity", 'unitAmount', il."unit_amount"::text, 'discountBps', il."discount_bps", 'taxRateBps', il."tax_rate_bps", 'taxCode', il."tax_code", 'taxCodeId', il."tax_code_id", 'unitCost', il."unit_cost"::text, 'dimensions', il."dimensions") order by il."position") from "better_supabase"."invoice_lines" il where il."parent_id" = v_row."id"), '[]'::jsonb),
      'payments', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'amount', (-e."amount")::text, 'paidAt', y."effective_at", 'method', y."metadata" ->> 'method', 'reference', y."metadata" ->> 'reference', 'note', y."metadata" ->> 'note', 'recordedBy', y."actor_id") order by y."effective_at", y."created_at")
        from "better_supabase"."ledger_entries" e join "better_supabase"."ledger_transactions" y on y."id" = e."transaction_id"
        where e."account_id" = (select a."id" from "better_supabase"."ledger_accounts" a where a."tenant_id" = v_row."tenant_id" and a."code" = 'invoice:' || v_row."id"::text)), '[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_meeting_action_item (
  meeting_id     uuid,
  task           jsonb,
  assignees      uuid[] DEFAULT '{}'::uuid[],
  agenda_item_id uuid   DEFAULT NULL::uuid,
  decision_id    uuid   DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."meetings";
  v_task jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."meetings" x where x."id" = add_meeting_action_item.meeting_id for update;
  if not found or not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'meetings.read'), false))) or "better_supabase"."meeting_role"(v_row."id") is not null) then
    raise exception 'no such meeting' using errcode = 'P0002', hint = 'MEETING_NOT_FOUND';
  end if;
  if not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'meetings.manage'), false))) or (auth.uid() is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'meetings.write'), false) and (coalesce(v_row."created_by" = auth.uid(), false) or coalesce("better_supabase"."meeting_role"(v_row."id") in ('chair', 'secretary'), false)))) then
    raise exception 'not allowed to add action items to this meeting' using errcode = '42501', hint = 'MEETING_FORBIDDEN';
  end if;
  if add_meeting_action_item.agenda_item_id is not null and not exists (
    select 1 from "better_supabase"."meeting_agenda_items" y where y."id" = add_meeting_action_item.agenda_item_id and y."meeting_id" = v_row."id"
  ) then
    raise exception 'the agenda item belongs to another meeting' using errcode = '22023', hint = 'MEETING_INVALID';
  end if;
  if add_meeting_action_item.decision_id is not null and not exists (
    select 1 from "better_supabase"."meeting_decisions" y where y."id" = add_meeting_action_item.decision_id and y."meeting_id" = v_row."id"
  ) then
    raise exception 'the decision belongs to another meeting' using errcode = '22023', hint = 'MEETING_INVALID';
  end if;
  v_task := "better_supabase"."create_work_item"(v_row."tenant_id", add_meeting_action_item.task, coalesce(add_meeting_action_item.assignees, '{}'));
  insert into "better_supabase"."meeting_action_items" ("task_id", "tenant_id", "meeting_id", "agenda_item_id", "decision_id")
  values ((v_task ->> 'id')::uuid, v_row."tenant_id", v_row."id", add_meeting_action_item.agenda_item_id, add_meeting_action_item.decision_id);
  perform "better_supabase".emit_event('meeting_action_item.created', jsonb_build_object('organizationId', v_row."tenant_id", 'meetingId', v_row."id", 'taskId', (v_task ->> 'id')::uuid, 'title', v_task ->> 'title'), 'meetings/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/meetings');
  return v_task || jsonb_build_object('meetingId', v_row."id", 'agendaItemId', add_meeting_action_item.agenda_item_id, 'decisionId', add_meeting_action_item.decision_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_organization_domain (
  tenant uuid,
  domain text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."sso_domains";
  v_domain text := lower(trim(trailing '.' from trim(add_organization_domain.domain)));
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not coalesce(better_supabase.can('tenant', add_organization_domain.tenant, 'sso.manage'), false) then
    raise exception 'You may not manage this organization''s domains' using errcode = '42501', hint = 'SSO_FORBIDDEN';
  end if;
  if v_domain !~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?[.])+[a-z]{2,63}$' then
    raise exception 'Not a domain name: %', add_organization_domain.domain using errcode = '22023', hint = 'SSO_DOMAIN_INVALID';
  end if;
  insert into "better_supabase"."sso_domains" as x ("tenant_id", "domain") values (add_organization_domain.tenant, v_domain)
  on conflict ("tenant_id", "domain") do update set "domain" = x."domain"
  returning * into v_row;
  perform "better_supabase".emit_event('sso_domain.created', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'domainId', v_row."id", 'domain', v_row."domain", 'userId', auth.uid()), 'organizations/' || v_row."tenant_id"::text, (v_row."tenant_id")::text, null, 'better-supabase/sso');
  perform better_supabase.audit_event(
    event_type => 'sso_domain.created',
    category => 'security',
    target_type => 'domain',
    record_id => v_row."id"::text,
    target_label => v_row."domain",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'domainId', v_row."id", 'domain', v_row."domain", 'userId', auth.uid()),
    actor_id => auth.uid()
  );
  return to_jsonb(v_row) - 'verification_token' || jsonb_build_object('record', jsonb_build_object('type', 'TXT', 'name', '_better-supabase.' || v_row."domain", 'value', 'better-supabase-domain-verification=' || v_row."verification_token"));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_person_identity (
  person   uuid,
  channel  text,
  address  text,
  verified boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_channel text := nullif(trim(add_person_identity.channel), '');
  v_address text := nullif(trim(add_person_identity.address), '');
  v_holder uuid;
  v_row jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select p."tenant_id" into v_tenant from "better_supabase"."people" p
  where p."id" = add_person_identity.person and p."merged_into" is null;
  if v_tenant is null then
    raise exception 'person not found' using errcode = 'P0002', hint = 'PARTY_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'contacts.write'), false)) then
    raise exception 'not allowed to change companies and people' using errcode = '42501', hint = 'PARTY_FORBIDDEN';
  end if;
  if v_channel is null or v_address is null then
    raise exception 'an identity needs a channel and an address' using errcode = '22023', hint = 'PARTY_IDENTITY_INVALID';
  end if;
  select i."person_id" into v_holder from "better_supabase"."person_identities" i
  where i."tenant_id" = v_tenant and i."channel" = v_channel and i."address" = v_address;
  if v_holder is not null and v_holder <> add_person_identity.person then
    raise exception 'another person has this address' using errcode = '23505', hint = 'PARTY_IDENTITY_TAKEN';
  end if;
  insert into "better_supabase"."person_identities" ("tenant_id", "person_id", "channel", "address", "verified_at")
  values (v_tenant, add_person_identity.person, v_channel, v_address, case when add_person_identity.verified then now() end)
  on conflict do nothing;
  if add_person_identity.verified then
    update "better_supabase"."person_identities" i set "verified_at" = coalesce(i."verified_at", now())
    where i."tenant_id" = v_tenant and i."channel" = v_channel and i."address" = v_address;
  end if;
  select jsonb_build_object('id', i."id", 'tenant_id', i."tenant_id", 'person_id', i."person_id", 'channel', i."channel", 'address', i."address", 'verified_at', i."verified_at", 'created_at', i."created_at") into v_row from "better_supabase"."person_identities" i
  where i."tenant_id" = v_tenant and i."channel" = v_channel and i."address" = v_address;
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_product_media (
  product    uuid,
  attachment uuid,
  variant    uuid,
  alt        jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_position integer;
  v_id uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" into v_tenant from "better_supabase"."products" x where x."id" = add_product_media.product for update;
  if v_tenant is null then
    raise exception 'product not found' using errcode = 'P0002', hint = 'CATALOG_PRODUCT_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  if add_product_media.variant is not null and not exists (select 1 from "better_supabase"."product_variants" x where x."id" = add_product_media.variant and x."product_id" = add_product_media.product) then
    raise exception 'variant not found on this product' using errcode = 'P0002', hint = 'CATALOG_VARIANT_NOT_FOUND';
  end if;
  if not exists (
    select 1 from "better_supabase"."attachments" f
    where f."id" = add_product_media.attachment
      and f."tenant_id" = v_tenant
      and (
        (f."subject_type" = 'product' and f."subject_id" = add_product_media.product::text)
        or (f."subject_type" = 'product_variant' and f."subject_id" in (select w."id"::text from "better_supabase"."product_variants" w where w."product_id" = add_product_media.product))
      )
  ) then
    raise exception 'attach the file to the product or one of its variants first' using errcode = 'P0002', hint = 'CATALOG_MEDIA_ATTACHMENT_NOT_FOUND';
  end if;
  if add_product_media.alt is not null and (jsonb_typeof(add_product_media.alt) <> 'object' or exists (
    select 1 from jsonb_each(add_product_media.alt) e (key, value)
    where not (e.key = any ('{en}'::text[])) or jsonb_typeof(e.value) <> 'string' or length(e.value #>> '{}') not between 1 and 1000
  )) then
    raise exception 'alt maps configured locales to text of 1 to 1000 characters' using errcode = '22023', hint = 'CATALOG_MEDIA_ALT_INVALID';
  end if;
  select coalesce(max(x."position") + 1, 0) into v_position from "better_supabase"."product_media" x where x."product_id" = add_product_media.product;
  begin
    insert into "better_supabase"."product_media" ("tenant_id", "product_id", "variant_id", "attachment_id", "position", "alt")
    values (v_tenant, add_product_media.product, add_product_media.variant, add_product_media.attachment, v_position, coalesce(add_product_media.alt, '{}'::jsonb))
    returning "id" into v_id;
  exception when unique_violation then
    raise exception 'the file is already in the product''s media' using errcode = '23505', hint = 'CATALOG_MEDIA_TAKEN';
  end;
  return jsonb_build_object('id', v_id, 'position', v_position);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_qualification_requirement (
  type_id      uuid,
  target_type  text,
  target_value text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_type "better_supabase"."qualification_types"%rowtype;
  v_row "better_supabase"."qualification_requirements"%rowtype;
  v_value text := nullif(trim(add_qualification_requirement.target_value), '');
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_type from "better_supabase"."qualification_types" x where x."id" = add_qualification_requirement.type_id;
  if not found then
    raise exception 'qualification type not found' using errcode = 'P0002', hint = 'QUALIFICATION_TYPE_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_type."tenant_id", 'qualifications.manage'), false)) then
    raise exception 'not allowed to manage qualifications' using errcode = '42501', hint = 'QUALIFICATION_FORBIDDEN';
  end if;
  if add_qualification_requirement.target_type is null or add_qualification_requirement.target_type not in ('role', 'team', 'job_title', 'asset_kind', 'segment', 'holder') then
    raise exception 'target_type is one of role, team, job_title, asset_kind, segment, holder' using errcode = '22023', hint = 'QUALIFICATION_REQUIREMENT_INVALID';
  end if;
  if v_value is null or length(v_value) > 200 then
    raise exception 'a requirement needs a target value of at most 200 characters' using errcode = '22023', hint = 'QUALIFICATION_REQUIREMENT_INVALID';
  end if;
  if add_qualification_requirement.target_type = 'role' then
    if not ('member' = any(v_type."holder_types")) then
      raise exception 'role requirements apply to member holders' using errcode = '22023', hint = 'QUALIFICATION_REQUIREMENT_INVALID';
    end if;
  end if;
  if add_qualification_requirement.target_type = 'team' then
    if not ('member' = any(v_type."holder_types")) then
      raise exception 'team requirements apply to member holders' using errcode = '22023', hint = 'QUALIFICATION_REQUIREMENT_INVALID';
    end if;
    if not exists (select 1 from "better_supabase"."teams" o where o."id"::text = v_value and o."tenant_id" = v_type."tenant_id") then
      raise exception 'the team isn''t in this organization' using errcode = '22023', hint = 'QUALIFICATION_REQUIREMENT_INVALID';
    end if;
  end if;
  if add_qualification_requirement.target_type = 'job_title' then
    if not ('member' = any(v_type."holder_types")) then
      raise exception 'job_title requirements apply to member holders' using errcode = '22023', hint = 'QUALIFICATION_REQUIREMENT_INVALID';
    end if;
  end if;
  if add_qualification_requirement.target_type = 'asset_kind' then
    if not ('asset' = any(v_type."holder_types")) then
      raise exception 'asset_kind requirements apply to asset holders' using errcode = '22023', hint = 'QUALIFICATION_REQUIREMENT_INVALID';
    end if;
  end if;
  if add_qualification_requirement.target_type = 'segment' then
    if not ('company' = any(v_type."holder_types")) then
      raise exception 'segment requirements apply to company holders' using errcode = '22023', hint = 'QUALIFICATION_REQUIREMENT_INVALID';
    end if;
    if not exists (select 1 from "better_supabase"."segments" o where o."id"::text = v_value and o."tenant_id" = v_type."tenant_id") then
      raise exception 'the segment isn''t in this organization' using errcode = '22023', hint = 'QUALIFICATION_REQUIREMENT_INVALID';
    end if;
  end if;
  insert into "better_supabase"."qualification_requirements" ("tenant_id", "type_id", "target_type", "target_value")
  values (v_type."tenant_id", v_type."id", add_qualification_requirement.target_type, v_value)
  on conflict ("type_id", "target_type", "target_value") do nothing;
  select * into v_row from "better_supabase"."qualification_requirements" x
  where x."type_id" = v_type."id" and x."target_type" = add_qualification_requirement.target_type and x."target_value" = v_value;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'qualificationTypeId', v_row."type_id", 'targetType', v_row."target_type", 'targetValue', v_row."target_value", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_signing_key (
  owner_type  text,
  owner_id    text,
  kid         text,
  alg         text,
  public_jwk  jsonb,
  private_jwk text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_old "better_supabase"."signing_keys";
  v_row "better_supabase"."signing_keys";
  v_vault uuid;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role manages signing keys' using errcode = '42501', hint = 'SIGNING_KEYS_FORBIDDEN';
  end if;
  if add_signing_key.private_jwk is null or length(add_signing_key.private_jwk) = 0 then
    raise exception 'a signing key needs its private JWK' using errcode = '22023', hint = 'SIGNING_KEY_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'bs:signing:' || add_signing_key.owner_type || ':' || add_signing_key.owner_id, 0));
  update "better_supabase"."signing_keys" k set "state" = 'retired', "retired_at" = now()
  where k."owner_type" = add_signing_key.owner_type
    and k."owner_id" = add_signing_key.owner_id
    and k."state" = 'active'
  returning k.* into v_old;
  v_vault := vault.create_secret(
    add_signing_key.private_jwk,
    'bs:signing:' || add_signing_key.kid,
    'better-supabase signing key'
  );
  insert into "better_supabase"."signing_keys" ("owner_type", "owner_id", "kid", "alg", "public_jwk", "vault_secret_id")
  values (add_signing_key.owner_type, add_signing_key.owner_id, add_signing_key.kid, add_signing_key.alg,
    add_signing_key.public_jwk, v_vault)
  returning * into v_row;
  if v_old."kid" is not null then
    perform "better_supabase".emit_event('signing_key.retired', jsonb_build_object('ownerType', v_old."owner_type", 'ownerId', v_old."owner_id", 'kid', v_old."kid"), 'signing-keys/' || v_old."kid", null, null, 'better-supabase/signing-keys');
  perform better_supabase.audit_event(
    event_type => 'signing_key.retired',
    category => 'security',
    target_type => 'signing_key',
    record_id => v_old."kid",
    metadata => jsonb_build_object('ownerType', v_old."owner_type", 'ownerId', v_old."owner_id", 'kid', v_old."kid")
  );
  end if;
  perform "better_supabase".emit_event('signing_key.created', jsonb_build_object('ownerType', v_row."owner_type", 'ownerId', v_row."owner_id", 'kid', v_row."kid", 'alg', v_row."alg"), 'signing-keys/' || v_row."kid", null, null, 'better-supabase/signing-keys');
  perform better_supabase.audit_event(
    event_type => 'signing_key.created',
    category => 'security',
    target_type => 'signing_key',
    record_id => v_row."kid",
    metadata => jsonb_build_object('ownerType', v_row."owner_type", 'ownerId', v_row."owner_id", 'kid', v_row."kid", 'alg', v_row."alg")
  );
  return jsonb_build_object('kid', v_row."kid", 'alg', v_row."alg", 'retired', v_old."kid");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_subject_member (
  subject_type text,
  subject_id   text,
  user_id      uuid DEFAULT NULL::uuid,
  team_id      uuid DEFAULT NULL::uuid,
  role         text DEFAULT 'member'::text,
  starts_on    date DEFAULT NULL::date,
  ends_on      date DEFAULT NULL::date
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_tenant uuid;
  v_row "better_supabase"."subject_members";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (add_subject_member.subject_type = any (array['customer', 'drive_node']::text[])) then
    raise exception 'this subject type has no record team (subjects.<type>.team)' using errcode = '22023', hint = 'SUBJECT_MEMBER_INVALID';
  end if;
  if (add_subject_member.user_id is null) = (add_subject_member.team_id is null) then
    raise exception 'pass exactly one of user_id and team_id' using errcode = '22023', hint = 'SUBJECT_MEMBER_INVALID';
  end if;
  if add_subject_member.role is null or not (add_subject_member.role = any ('{lead,member}'::text[])) then
    raise exception 'role must be one of lead, member' using errcode = '22023', hint = 'SUBJECT_MEMBER_INVALID';
  end if;
  if add_subject_member.ends_on < add_subject_member.starts_on then
    raise exception 'ends_on is before starts_on' using errcode = '22023', hint = 'SUBJECT_MEMBER_INVALID';
  end if;
  begin
    case add_subject_member.subject_type
    when 'customer' then
      select s."organization_id" into v_tenant from "public"."customers" s
      where s."id" = (add_subject_member.subject_id)::uuid and s."archived_at" is null;
    when 'drive_node' then
      select s."tenant_id" into v_tenant from "better_supabase"."drive_nodes" s
      where s."id" = (add_subject_member.subject_id)::uuid and s."archived_at" is null;
      else
        v_tenant := null;
    end case;
  exception
    when invalid_text_representation then
      raise exception 'the subject id does not match its type''s id column' using errcode = '22023', hint = 'SUBJECT_MEMBER_INVALID';
  end;
  if v_tenant is null then
    raise exception 'subject not found' using errcode = 'P0002', hint = 'SUBJECT_MEMBER_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')
      or coalesce(better_supabase.can('tenant', v_tenant, 'subjects.manage'), false)
      or (add_subject_member.subject_type = any (array[]::text[]) and coalesce("better_supabase"."can_subject"(add_subject_member.subject_type, add_subject_member.subject_id, 'manage'), false))) then
    raise exception 'not allowed to manage this record''s team' using errcode = '42501', hint = 'SUBJECT_MEMBER_FORBIDDEN';
  end if;
  if add_subject_member.user_id is not null and not exists (
    select 1 from "public"."memberships" om
    where om."organization_id" = v_tenant
      and om."user_id" = add_subject_member.user_id
  ) then
    raise exception 'user is not a member of the record''s tenant' using errcode = '22023', hint = 'SUBJECT_MEMBER_INVALID';
  end if;
  if add_subject_member.team_id is not null and not exists (
    select 1 from "better_supabase"."teams" tt
    where tt."id" = add_subject_member.team_id
      and tt."tenant_id" = v_tenant
  ) then
    raise exception 'team is not in the record''s tenant' using errcode = '22023', hint = 'SUBJECT_MEMBER_INVALID';
  end if;
  if add_subject_member.user_id is not null then
    insert into "better_supabase"."subject_members" ("tenant_id", "subject_type", "subject_id", "user_id", "role", "starts_on", "ends_on", "created_by")
    values (v_tenant, add_subject_member.subject_type, add_subject_member.subject_id, add_subject_member.user_id, add_subject_member.role, add_subject_member.starts_on, add_subject_member.ends_on, auth.uid())
    on conflict ("subject_type", "subject_id", "user_id", "role") where "user_id" is not null
    do update set "starts_on" = excluded."starts_on", "ends_on" = excluded."ends_on"
    returning * into v_row;
  else
    insert into "better_supabase"."subject_members" ("tenant_id", "subject_type", "subject_id", "team_id", "role", "starts_on", "ends_on", "created_by")
    values (v_tenant, add_subject_member.subject_type, add_subject_member.subject_id, add_subject_member.team_id, add_subject_member.role, add_subject_member.starts_on, add_subject_member.ends_on, auth.uid())
    on conflict ("subject_type", "subject_id", "team_id", "role") where "team_id" is not null
    do update set "starts_on" = excluded."starts_on", "ends_on" = excluded."ends_on"
    returning * into v_row;
  end if;
  perform "better_supabase".emit_event('subject_member.added', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'userId', v_row."user_id", 'teamId', v_row."team_id", 'role', v_row."role", 'endsOn', v_row."ends_on"), 'subjects/' || v_row."subject_type" || '/' || v_row."subject_id", (v_row."tenant_id")::text, null, 'better-supabase/subjects');
  perform better_supabase.audit_event(
    event_type => 'subject_member.added',
    category => 'access',
    target_type => 'subject_member',
    record_id => v_row."id"::text,
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'userId', v_row."user_id", 'teamId', v_row."team_id", 'role', v_row."role", 'endsOn', v_row."ends_on")
  );
  return jsonb_build_object(
      'id', v_row."id", 'organizationId', v_row."tenant_id",
      'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id",
      'userId', v_row."user_id", 'teamId', v_row."team_id", 'role', v_row."role",
      'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'endsAt', v_row."ends_at",
      'emergency', v_row."emergency", 'reason', v_row."reason",
      'active', (v_row."starts_on" is null or v_row."starts_on" <= current_date)
        and (v_row."ends_on" is null or v_row."ends_on" >= current_date)
        and (v_row."ends_at" is null or v_row."ends_at" > now()),
      'createdBy', v_row."created_by", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_team_member (
  team     uuid,
  member   uuid DEFAULT NULL::uuid,
  employee uuid DEFAULT NULL::uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_user uuid := add_team_member.member;
  v_employee uuid := add_team_member.employee;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select "tenant_id" into v_tenant from "better_supabase"."teams" where "id" = add_team_member.team;
  if not found then
    raise exception 'team not found' using errcode = 'P0002', hint = 'TEAM_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'teams.manage'), false)) then
    raise exception 'not allowed to manage teams' using errcode = '42501', hint = 'TEAM_FORBIDDEN';
  end if;
  if (add_team_member.member is null) = (add_team_member.employee is null) then
    raise exception 'pass either a user or an employee' using errcode = '22023', hint = 'TEAM_MEMBER_INVALID';
  end if;
  if v_employee is null then
    if not exists (
    select 1 from "public"."memberships" m
    where m."organization_id" = v_tenant
      and m."user_id" = v_user
  ) then
    raise exception 'user is not a member of the tenant' using errcode = '22023', hint = 'TEAM_MEMBER_INVALID';
  end if;
    v_employee := (
      select x."id" from "better_supabase"."employees" x
      where x."tenant_id" = v_tenant and x."user_id" = v_user
    );
  else
    select x."user_id" into v_user from "better_supabase"."employees" x
    where x."id" = v_employee and x."tenant_id" = v_tenant;
    if not found then
      raise exception 'employee is not in the tenant' using errcode = '22023', hint = 'TEAM_MEMBER_INVALID';
    end if;
    if v_user is not null and not exists (
    select 1 from "public"."memberships" m
    where m."organization_id" = v_tenant
      and m."user_id" = v_user
  ) then
      v_user := null;
    end if;
  end if;
  if v_employee is not null and v_user is not null then
    delete from "better_supabase"."team_members" x
    where x."team_id" = add_team_member.team and x."user_id" = v_user and x."employee_id" is null
      and exists (
        select 1 from "better_supabase"."team_members" y
        where y."team_id" = add_team_member.team and y."employee_id" = v_employee
      );
    update "better_supabase"."team_members" set "user_id" = v_user
    where "team_id" = add_team_member.team and "employee_id" = v_employee and "user_id" is null;
    update "better_supabase"."team_members" set "employee_id" = v_employee
    where "team_id" = add_team_member.team and "user_id" = v_user and "employee_id" is null;
  end if;
  insert into "better_supabase"."team_members" ("team_id", "user_id", "employee_id", "tenant_id")
  values (add_team_member.team, v_user, v_employee, v_tenant)
  on conflict do nothing;
  perform "better_supabase".emit_event('team_member.added', jsonb_build_object('organizationId', v_tenant, 'id', add_team_member.team, 'userId', v_user, 'employeeId', v_employee), 'teams/' || (add_team_member.team)::text, (v_tenant)::text, null, 'better-supabase/teams');
  perform better_supabase.audit_event(
    event_type => 'team_member.added',
    category => 'membership',
    target_type => 'team',
    record_id => (add_team_member.team)::text,
    tenant => (v_tenant)::uuid,
    metadata => jsonb_build_object('organizationId', v_tenant, 'id', add_team_member.team, 'userId', v_user, 'employeeId', v_employee)
  );
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_to_cart (
  cart     uuid,
  variant  uuid,
  quantity integer
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_cart record;
  v_id uuid;
  v_quantity integer;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" as tenant, x."user_id" as owner, x."status" as status,
    x."currency" as currency, x."price_list_id" as price_list, x."shipping_address" as shipping_address
  into v_cart from "better_supabase"."carts" x where x."id" = add_to_cart.cart for update;
  if not found or not (auth.role() = 'service_role' or coalesce(v_cart.owner = auth.uid(), false)) then
    raise exception 'cart not found' using errcode = 'P0002', hint = 'ORDERS_CART_NOT_FOUND';
  end if;
  if v_cart.status <> 'open' then
    raise exception 'the cart is no longer open' using errcode = '55000', hint = 'ORDERS_CART_CLOSED';
  end if;
  if add_to_cart.quantity is null or add_to_cart.quantity < 1 then
    raise exception 'the quantity must be a positive whole number' using errcode = '22023', hint = 'ORDERS_QUANTITY_INVALID';
  end if;
  if not exists (
    select 1 from "better_supabase"."product_variants" cv join "better_supabase"."products" cp on cp."id" = cv."product_id"
    where cv."id" = add_to_cart.variant and cv."tenant_id" = v_cart.tenant and cp."status" = 'active'
  ) then
    raise exception 'this variant is not for sale' using errcode = 'P0002', hint = 'ORDERS_VARIANT_UNAVAILABLE';
  end if;
  select x."quantity" + add_to_cart.quantity into v_quantity from "better_supabase"."cart_lines" x
  where x."cart_id" = add_to_cart.cart and x."variant_id" = add_to_cart.variant;
  if coalesce(v_quantity, add_to_cart.quantity) > 10000 then
    raise exception 'a cart line holds at most 10000 units' using errcode = '22023', hint = 'ORDERS_QUANTITY_INVALID';
  end if;
  insert into "better_supabase"."cart_lines" as x ("tenant_id", "cart_id", "variant_id", "quantity")
  values (v_cart.tenant, add_to_cart.cart, add_to_cart.variant, add_to_cart.quantity)
  on conflict ("cart_id", "variant_id") do update
    set "quantity" = x."quantity" + excluded."quantity", "updated_at" = now()
  returning x."id", x."quantity" into v_id, v_quantity;
  update "better_supabase"."carts" x set "updated_at" = now() where x."id" = add_to_cart.cart;
  return jsonb_build_object('lineId', v_id, 'quantity', v_quantity);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.add_to_collection (
  collection uuid,
  product    uuid,
  rank       text
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_kind text;
  v_last text;
  v_rank text := add_to_collection.rank;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id", x."kind" into v_tenant, v_kind from "better_supabase"."product_collections" x where x."id" = add_to_collection.collection for update;
  if v_tenant is null then
    raise exception 'collection not found' using errcode = 'P0002', hint = 'CATALOG_COLLECTION_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  if v_kind <> 'manual' then
    raise exception 'a rule collection picks its products from its rule' using errcode = '22023', hint = 'CATALOG_COLLECTION_RULE';
  end if;
  if not exists (select 1 from "better_supabase"."products" x where x."id" = add_to_collection.product and x."tenant_id" = v_tenant) then
    raise exception 'product not found' using errcode = 'P0002', hint = 'CATALOG_PRODUCT_NOT_FOUND';
  end if;
  if v_rank is not null and v_rank !~ '^[0-9A-Za-z]*[1-9A-Za-z]$' then
    raise exception 'not a rank key' using errcode = '22023', hint = 'CATALOG_RANK_INVALID';
  end if;
  if v_rank is null then
    select max(x."rank" collate "C") into v_last from "better_supabase"."collection_products" x where x."collection_id" = add_to_collection.collection;
    v_rank := case
    when v_last is null then 'V'
    when length(substring(v_last from '^z*')) = length(v_last) then v_last || 'V'
    else left(v_last, length(substring(v_last from '^z*'))) || substr('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', (strpos('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', substr(v_last, length(substring(v_last from '^z*')) + 1, 1)) - 1 + 62) / 2 + 1, 1)
  end;
  end if;
  insert into "better_supabase"."collection_products" as x ("tenant_id", "collection_id", "product_id", "rank")
  values (v_tenant, add_to_collection.collection, add_to_collection.product, v_rank)
  on conflict ("collection_id", "product_id") do update set "rank" = excluded."rank";
  return v_rank;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.adjust_leave_balance (
  tenant  uuid,
  user_id uuid,
  type_id uuid,
  amount  numeric,
  period  integer DEFAULT NULL::integer,
  kind    text    DEFAULT 'adjustment'::text,
  note    text    DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_period integer := coalesce(adjust_leave_balance.period, extract(year from current_date)::integer);
  v_transaction uuid;
  v_entry uuid;
  v_row jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', adjust_leave_balance.tenant, 'leave.manage'), false)) then
    raise exception 'not allowed to adjust leave balances' using errcode = '42501', hint = 'LEAVE_FORBIDDEN';
  end if;
  if coalesce(adjust_leave_balance.kind, 'adjustment') not in ('grant', 'adjustment') then
    raise exception 'kind must be grant or adjustment' using errcode = '22023', hint = 'LEAVE_INVALID';
  end if;
  if adjust_leave_balance.amount is null or adjust_leave_balance.amount = 0 then
    raise exception 'amount must not be zero' using errcode = '22023', hint = 'LEAVE_INVALID';
  end if;
  if not exists (select 1 from "public"."memberships" m where m."organization_id" = adjust_leave_balance.tenant and m."user_id" = adjust_leave_balance.user_id) then
    raise exception 'the user is not a member of this organization' using errcode = '22023', hint = 'LEAVE_INVALID';
  end if;
  if not exists (select 1 from "better_supabase"."leave_types" t where t."id" = adjust_leave_balance.type_id and t."tenant_id" = adjust_leave_balance.tenant) then
    raise exception 'leave type not found' using errcode = 'P0002', hint = 'LEAVE_TYPE_NOT_FOUND';
  end if;
  v_transaction := "better_supabase"."leave_post"(adjust_leave_balance.tenant, adjust_leave_balance.user_id, adjust_leave_balance.type_id,
    coalesce(adjust_leave_balance.kind, 'adjustment'), adjust_leave_balance.amount, v_period, null, adjust_leave_balance.note);
  select y."id", jsonb_build_object('id', y."id", 'organizationId', x."tenant_id", 'userId', x."owner_id",
      'typeId', (x."metadata" ->> 'typeId')::uuid, 'kind', substr(r."kind", 7), 'amount', (y."amount"::numeric / 100)::numeric(10, 2)::text,
      'period', (x."metadata" ->> 'period')::integer,
      'requestId', case when r."reference_type" = 'leave-requests' then r."reference_id"::uuid end,
      'note', r."memo", 'createdAt', y."created_at") into v_entry, v_row
  from "better_supabase"."ledger_entries" y
    join "better_supabase"."ledger_accounts" x on x."id" = y."account_id" and x."managed_by" = 'leave' and x."kind" = 'leave'
    join "better_supabase"."ledger_transactions" r on r."id" = y."transaction_id"
  where y."transaction_id" = v_transaction and x."owner_id" = adjust_leave_balance.user_id;
  perform "better_supabase".emit_event('leave_balance.adjusted', jsonb_build_object('organizationId', adjust_leave_balance.tenant, 'id', v_entry, 'userId', adjust_leave_balance.user_id, 'typeId', adjust_leave_balance.type_id, 'kind', coalesce(adjust_leave_balance.kind, 'adjustment'), 'amount', adjust_leave_balance.amount::numeric(8, 2)::text, 'period', v_period), 'leave-ledger-entries/' || v_entry::text, (adjust_leave_balance.tenant)::text, null, 'better-supabase/leave');
  perform better_supabase.audit_event(
    event_type => 'leave_balance.adjusted',
    category => 'data',
    target_type => 'leave_balance',
    record_id => v_entry::text,
    summary => 'adjusted a leave balance by ' || adjust_leave_balance.amount::numeric(8, 2)::text,
    tenant => (adjust_leave_balance.tenant)::uuid,
    metadata => jsonb_build_object('organizationId', adjust_leave_balance.tenant, 'id', v_entry, 'userId', adjust_leave_balance.user_id, 'typeId', adjust_leave_balance.type_id, 'kind', coalesce(adjust_leave_balance.kind, 'adjustment'), 'amount', adjust_leave_balance.amount::numeric(8, 2)::text, 'period', v_period)
  );
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.adjust_stock (
  variant  uuid,
  location uuid,
  quantity numeric,
  reason   text,
  note     text,
  detail   jsonb   DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_active boolean;
  v_movement uuid;
  v_on_hand numeric;
  v_available numeric;
begin
  select x."tenant_id", x."active" into v_tenant, v_active from "better_supabase"."inventory_locations" x where x."id" = adjust_stock.location;
  if v_tenant is null then
    raise exception 'location not found' using errcode = 'P0002', hint = 'INVENTORY_LOCATION_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'inventory.manage'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  if not exists (select 1 from "better_supabase"."product_variants" cv where cv."id" = adjust_stock.variant and cv."tenant_id" = v_tenant) then
    raise exception 'variant not found in this organization' using errcode = 'P0002', hint = 'INVENTORY_VARIANT_NOT_FOUND';
  end if;
  if adjust_stock.quantity is null or adjust_stock.quantity = 0 then
    raise exception 'the quantity must not be zero' using errcode = '22023', hint = 'INVENTORY_QUANTITY_INVALID';
  end if;
  if adjust_stock.reason is null or adjust_stock.reason not in ('adjustment', 'damage', 'loss', 'return', 'receipt', 'scrap') then
    raise exception 'the reason must be one of adjustment, damage, loss, return, receipt, scrap' using errcode = '22023', hint = 'INVENTORY_REASON_INVALID';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_stock_adjust"(uuid, uuid, numeric, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::uuid, $3::numeric, $4::text)', v_hook::oid::regproc)
        using adjust_stock.variant, adjust_stock.location, adjust_stock.quantity, adjust_stock.reason;
    end if;
  end;
  v_movement := "better_supabase"."move_stock"(v_tenant, adjust_stock.variant, adjust_stock.location, adjust_stock.quantity, adjust_stock.reason, null, null, adjust_stock.note, adjust_stock.detail);
  select x."on_hand", x."available" into v_on_hand, v_available from "better_supabase"."stock_levels" x
  where x."variant_id" = adjust_stock.variant and x."location_id" = adjust_stock.location;
  perform "better_supabase".emit_event('stock.adjusted', jsonb_build_object('organizationId', v_tenant, 'id', v_movement, 'variantId', adjust_stock.variant, 'locationId', adjust_stock.location, 'quantity', adjust_stock.quantity::text, 'reason', adjust_stock.reason, 'available', v_available::text), 'stock-movements/' || v_movement::text, (v_tenant)::text, null, 'better-supabase/inventory');
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_stock_adjust"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_movement;
    end if;
  end;
  return jsonb_build_object('movementId', v_movement, 'onHand', v_on_hand, 'available', v_available);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.advance_schedule (
  job_name text,
  ran      timestamp with time zone,
  next_run timestamp with time zone
)
  RETURNS boolean
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select false;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.advance_workflow_schedule (
  schedule uuid,
  fired    timestamp with time zone,
  next_run timestamp with time zone
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
begin
  update "better_supabase"."workflow_schedules" x set "last_run_at" = fired, "next_run_at" = next_run, "lock_expires_at" = null
  where x."id" = schedule and x."next_run_at" = fired;
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_cache_delete (
  key    text DEFAULT NULL::text,
  tenant uuid DEFAULT NULL::uuid,
  model  text DEFAULT NULL::text
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  if ai_cache_delete.key is null and ai_cache_delete.tenant is null and ai_cache_delete.model is null then
    raise exception 'name a key, a tenant or a model' using errcode = '22023', hint = 'AI_CACHE_INVALID';
  end if;
  delete from "better_supabase"."ai_cache_entries" x
  where (ai_cache_delete.key is null or x."key" = ai_cache_delete.key)
    and (ai_cache_delete.tenant is null or x."tenant_id" = ai_cache_delete.tenant)
    and (ai_cache_delete.model is null or x."model" = ai_cache_delete.model);
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_cache_get (
  key text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."ai_cache_entries"%rowtype;
begin
  update "better_supabase"."ai_cache_entries" x set "hits" = x."hits" + 1, "last_hit_at" = now()
  where x."key" = ai_cache_get.key and x."expires_at" > now()
  returning * into v_row;
  if not found then
    return null;
  end if;
  return jsonb_build_object('key', v_row."key", 'tenant_id', v_row."tenant_id", 'kind', v_row."kind", 'model', v_row."model", 'value', v_row."value", 'hits', v_row."hits", 'created_at', v_row."created_at", 'last_hit_at', v_row."last_hit_at", 'expires_at', v_row."expires_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_cache_set (
  key    text,
  value  jsonb,
  ttl    integer,
  tenant uuid    DEFAULT NULL::uuid,
  kind   text    DEFAULT 'generate'::text,
  model  text    DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."ai_cache_entries"%rowtype;
begin
  if ai_cache_set.ttl is null or ai_cache_set.ttl < 1 then
    raise exception 'ttl must be at least one second' using errcode = '22023', hint = 'AI_CACHE_INVALID';
  end if;
  insert into "better_supabase"."ai_cache_entries" ("key", "tenant_id", "kind", "model", "value", "expires_at")
  values (ai_cache_set.key, ai_cache_set.tenant, coalesce(ai_cache_set.kind, 'generate'), ai_cache_set.model, ai_cache_set.value,
    now() + make_interval(secs => least(ai_cache_set.ttl, 604800)))
  on conflict ("key") do update set
    "tenant_id" = excluded."tenant_id",
    "kind" = excluded."kind",
    "model" = excluded."model",
    "value" = excluded."value",
    "hits" = 0,
    "created_at" = now(),
    "last_hit_at" = null,
    "expires_at" = excluded."expires_at"
  returning * into v_row;
  return jsonb_build_object('key', v_row."key", 'tenant_id', v_row."tenant_id", 'kind', v_row."kind", 'model', v_row."model", 'value', v_row."value", 'hits', v_row."hits", 'created_at', v_row."created_at", 'last_hit_at', v_row."last_hit_at", 'expires_at', v_row."expires_at") - 'value';
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_chat_can_read (
  chat uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from "better_supabase"."ai_chats" x
    where x."id" = ai_chat_can_read.chat
      and (
        coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')
        or x."owner_id" = (select auth.uid())
        or (x."visibility" = 'organization' and coalesce(better_supabase.can('tenant', x."tenant_id", 'ai_chat.read'), false))
        or (x."visibility" <> 'private' and exists (select 1 from "better_supabase"."ai_chat_participants" pa where pa."chat_id" = x."id" and ((((pa."kind"::text = 'user' and pa."user_id" = (select auth.uid())) or (pa."kind"::text = 'team' and exists (select 1 from "better_supabase"."team_members" tm where tm."team_id"::text = pa."team_id"::text and tm."user_id" = (select auth.uid())))) and (x."tenant_id" is null or x."tenant_id" in (select better_supabase.member_organization_ids()))) or (pa."kind"::text = 'customer' and pa."customer_id" = (select auth.uid()) and ((x."tenant_id")::text, ('ai-chat')::text, (x."id"::text)::text) in (select g.tenant, g.subject_type, g.subject_id from better_supabase.portal_subjects('read') g)))))
      )
  );
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_chat_notify (
  chat    uuid,
  owner   uuid,
  event   text,
  payload jsonb,
  list    boolean
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_payload jsonb := coalesce(payload, '{}'::jsonb) || jsonb_build_object('chatId', chat);
begin
  if to_regprocedure('realtime.send(jsonb, text, text, boolean)') is null then
    return;
  end if;
  perform realtime.send(v_payload, event, 'ai-chat:' || chat::text, true);
  if list and owner is not null then
    perform realtime.send(v_payload, event, 'ai-chats:' || owner::text, true);
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_chat_share_summaries (
  chats uuid[]
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'chat_id', x."id",
    'users', (
      select coalesce(jsonb_agg(jsonb_build_object('user_id', u.id, 'role', u.role) order by u.ord), '[]'::jsonb)
      from (
        select c."owner_id" as id, 'owner' as role, 0 as ord from "better_supabase"."ai_chats" c where c."id" = x."id"
        union all
        select pa."user_id", pa."role"::text, 1 from "better_supabase"."ai_chat_participants" pa
        where pa."chat_id" = x."id" and pa."kind"::text = 'user'
      ) u
    ),
    'team_count', (select count(*) from "better_supabase"."ai_chat_participants" pa where pa."chat_id" = x."id" and pa."kind"::text = 'team'),
    'has_link', exists (select 1 from "better_supabase"."ai_chat_links" l where l."chat_id" = x."id")
  )), '[]'::jsonb)
  from "better_supabase"."ai_chats" x
  where x."id" = any (coalesce(ai_chat_share_summaries.chats, '{}'::uuid[]))
    and "better_supabase"."ai_chat_can_read"(x."id");
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_document_purge_versions()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  delete from "better_supabase"."versions" x where x."subject_type" = 'ai_document' and x."subject_id" = old."id"::text;
  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_file_object_allowed (
  bucket text,
  path   text,
  action text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from "better_supabase"."ai_files" a
    where a."bucket" = ai_file_object_allowed.bucket and a."path" = ai_file_object_allowed.path
      and case ai_file_object_allowed.action
        when 'insert' then a."status" = 'pending' and a."owner_id" = auth.uid()
        when 'select' then a."owner_id" = auth.uid() or coalesce(better_supabase.can('tenant', a."tenant_id", 'ai_files.manage'), false) or (a."chat_id" is not null and "better_supabase"."ai_chat_can_read"(a."chat_id"))
        when 'delete' then a."owner_id" = auth.uid() or coalesce(better_supabase.can('tenant', a."tenant_id", 'ai_files.manage'), false)
        else false
      end
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_message_path (
  chat           uuid,
  leaf           text    DEFAULT NULL::text,
  include_native boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_leaf text;
begin
  if not "better_supabase"."ai_chat_can_read"(ai_message_path.chat) then
    raise exception 'No chat %', ai_message_path.chat using errcode = 'P0002', hint = 'AI_CHAT_NOT_FOUND';
  end if;
  select coalesce(ai_message_path.leaf, x."current_leaf_id"::text) into v_leaf from "better_supabase"."ai_chats" x where x."id" = ai_message_path.chat;
  if v_leaf is null then
    return '[]'::jsonb;
  end if;
  return "better_supabase"."ai_message_path_of"(ai_message_path.chat, v_leaf, coalesce(ai_message_path.include_native, false));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_message_path_of (
  chat           uuid,
  leaf           text,
  include_native boolean
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  with recursive up as (
    select x.*, 0 as depth from "better_supabase"."ai_messages" x
    where x."chat_id" = ai_message_path_of.chat and x."id" = ai_message_path_of.leaf
    union all
    select x.*, up.depth + 1 from "better_supabase"."ai_messages" x
    join up on x."chat_id" = up."chat_id" and x."id" = up."parent_id"
    where up.depth < 10000
  )
  select coalesce(jsonb_agg(
    jsonb_build_object('id', up."id", 'parent_id', up."parent_id", 'author_id', up."author_id", 'role', up."role", 'parts', up."parts", 'metadata', up."metadata", 'format', up."format", 'native', case when ai_message_path_of.include_native then up."native" end, 'model', up."model", 'status', up."status", 'created_at', up."created_at") || jsonb_build_object(
      'sibling_count', (select count(*) from "better_supabase"."ai_messages" sb where sb."chat_id" = up."chat_id" and sb."parent_id" is not distinct from up."parent_id"),
      'sibling_index', (select count(*) from "better_supabase"."ai_messages" sb where sb."chat_id" = up."chat_id" and sb."parent_id" is not distinct from up."parent_id" and sb."seq" < up."seq")
    )
    order by up.depth desc
  ), '[]'::jsonb)
  from up;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_message_siblings (
  chat       uuid,
  message_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_parent text;
begin
  if not "better_supabase"."ai_chat_can_read"(ai_message_siblings.chat) then
    raise exception 'No chat %', ai_message_siblings.chat using errcode = 'P0002', hint = 'AI_CHAT_NOT_FOUND';
  end if;
  select x."parent_id" into v_parent from "better_supabase"."ai_messages" x
  where x."chat_id" = ai_message_siblings.chat and x."id" = ai_message_siblings.message_id;
  if not found then
    raise exception 'No message %', ai_message_siblings.message_id using errcode = 'P0002', hint = 'AI_MESSAGE_NOT_FOUND';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object('id', x."id", 'role', x."role", 'created_at', x."created_at") order by x."seq"), '[]'::jsonb)
    from "better_supabase"."ai_messages" x
    where x."chat_id" = ai_message_siblings.chat and x."parent_id" is not distinct from v_parent
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_provider_keys_for (
  tenant    uuid,
  providers text[] DEFAULT NULL::text[]
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', x."id", 'tenant_id', x."tenant_id", 'provider', x."provider", 'name', x."name", 'credential_ref', x."credential_ref", 'settings', x."settings", 'enabled', x."enabled", 'created_by', x."created_by", 'created_at', x."created_at", 'updated_at', x."updated_at") order by x."provider", x."name"), '[]')
  from "better_supabase"."ai_provider_keys" x
  where x."tenant_id" = ai_provider_keys_for.tenant and x."enabled"
    and (ai_provider_keys_for.providers is null or x."provider" = any (ai_provider_keys_for.providers))
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_sandbox_for (
  chat_id  uuid,
  provider text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object('id', x."id", 'organization_id', x."tenant_id", 'user_id', x."user_id", 'chat_id', x."chat_id", 'harness_id', x."harness_id", 'provider', x."provider", 'sandbox_id', x."sandbox_id", 'container_id', x."container_id", 'status', x."status", 'metadata', x."metadata", 'idle_seconds', x."idle_seconds", 'error', x."error", 'last_used_at', x."last_used_at", 'expires_at', x."expires_at", 'stopped_at', x."stopped_at", 'created_at', x."created_at", 'updated_at', x."updated_at") from "better_supabase"."ai_sandboxes" x
  where x."chat_id" = ai_sandbox_for.chat_id and x."provider" = ai_sandbox_for.provider and x."status" = 'running'
    and (x."expires_at" is null or x."expires_at" > now())
  order by x."last_used_at" desc
  limit 1
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_tool_approval_approvable (
  approval_id text
)
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."ai_tool_approvals";
begin
  select * into v_row from "better_supabase"."ai_tool_approvals" x where x."approval_id" = ai_tool_approval_approvable.approval_id;
  return found and v_row."decision" is null and coalesce(v_row."owner_id" = (select auth.uid()), false);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ai_tool_policies_for (
  tenant uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', ai_tool_policies_for.tenant, 'ai_chat.read'), false)) then
    return '{}'::jsonb;
  end if;
  return (
    select coalesce(jsonb_object_agg(x."tool", x."policy"), '{}'::jsonb)
    from "better_supabase"."ai_tool_policies" x where x."tenant_id" = ai_tool_policies_for.tenant
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.allocate_existing (
  tenant       uuid,
  invoice      uuid,
  reference    text,
  amount       bigint,
  party        text,
  allocated_on date   DEFAULT CURRENT_DATE,
  ledger_entry uuid   DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."invoices";
  v_reference text := nullif(btrim(allocate_existing.reference), '');
  v_party text := nullif(btrim(allocate_existing.party), '');
  v_id uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', allocate_existing.tenant, 'invoices.write'), false)) then
    raise exception 'not allowed to record payments in this organization' using errcode = '42501', hint = 'INVOICE_FORBIDDEN';
  end if;
  if v_reference is null or v_party is null or coalesce(allocate_existing.amount, 0) <= 0 then
    raise exception 'an imported allocation needs a reference, a party and a positive amount' using errcode = '22023', hint = 'INVOICE_ALLOCATIONS_INVALID';
  end if;
  select * into v_row from "better_supabase"."invoices" x
  where x."id" = allocate_existing.invoice and x."tenant_id" = allocate_existing.tenant
  for update;
  if v_row."id" is null then
    raise exception 'no such invoice you can edit' using errcode = 'P0002', hint = 'INVOICE_NOT_FOUND';
  end if;
  select b."id" into v_id from "better_supabase"."invoice_allocations" b
  where b."tenant_id" = allocate_existing.tenant and b."reference" = v_reference and b."invoice_id" = v_row."id";
  if v_id is not null then
    return jsonb_build_object('id', v_id, 'invoiceId', v_row."id", 'reference', v_reference, 'created', false);
  end if;
  insert into "better_supabase"."invoice_allocations" ("tenant_id", "reference", "party_id", "invoice_id", "source", "amount", "payment_id", "allocated_on")
  values (allocate_existing.tenant, v_reference, v_party, v_row."id", 'import', allocate_existing.amount, allocate_existing.ledger_entry, coalesce(allocate_existing.allocated_on, current_date))
  returning "id" into v_id;
  update "better_supabase"."invoices" x set
    "paid_total" = x."paid_total" + allocate_existing.amount,
    "paid_at" = coalesce(x."paid_at", allocate_existing.allocated_on::timestamptz),
    "status" = case
      when x."paid_total" + allocate_existing.amount >= x."total" then 'paid'
      else 'partially_paid'
    end
  where x."id" = v_row."id";
  return jsonb_build_object('id', v_id, 'invoiceId', v_row."id", 'reference', v_reference, 'created', true);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.allocate_payment (
  tenant      uuid,
  payment     jsonb,
  allocations jsonb,
  actor       jsonb DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := allocate_payment.tenant;
  v_party text := nullif(trim(allocate_payment.payment ->> 'partyId'), '');
  v_side text := coalesce(allocate_payment.payment ->> 'side', 'customer');
  v_supplier boolean;
  v_use_credit boolean := coalesce(allocate_payment.payment ->> 'source', 'payment') = 'credit';
  v_currency text := upper(allocate_payment.payment ->> 'currency');
  v_reference text := nullif(trim(allocate_payment.payment ->> 'reference'), '');
  v_received date;
  v_amount bigint;
  v_allocations jsonb := coalesce(allocate_payment.allocations, '[]'::jsonb);
  v_sum bigint := 0;
  v_remainder bigint := 0;
  v_alloc record;
  v_row "better_supabase"."invoices";
  v_balance bigint;
  v_early bigint;
  v_due date;
  v_discount bigint;
  v_ref text;
  v_pay uuid;
  v_disc uuid;
  v_account uuid;
  v_credit uuid;
  v_was text;
  v_method text := coalesce(nullif(trim(allocate_payment.payment ->> 'method'), ''), 'allocation');
  v_note text := nullif(trim(allocate_payment.payment ->> 'note'), '');
  v_credited bigint := 0;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', allocate_payment.tenant, 'invoices.write'), false)) then
    raise exception 'not allowed to record payments in this organization' using errcode = '42501', hint = 'INVOICE_FORBIDDEN';
  end if;
  if jsonb_typeof(allocate_payment.payment) is distinct from 'object' then
    raise exception 'payment is an object of partyId, amount, currency and reference' using errcode = '22023', hint = 'INVOICE_ALLOCATIONS_INVALID';
  end if;
  if v_party is null or length(v_party) > 150 then
    raise exception 'a party id is a non-empty text of at most 150 characters' using errcode = '22023', hint = 'INVOICE_PARTY_INVALID';
  end if;
  if v_side not in ('customer', 'supplier') then
    raise exception 'side is customer or supplier' using errcode = '22023', hint = 'INVOICE_ALLOCATIONS_INVALID';
  end if;
  v_supplier := v_side = 'supplier';
  if v_supplier and v_use_credit then
    raise exception 'only a customer''s credit is drawn on' using errcode = '22023', hint = 'INVOICE_ALLOCATIONS_INVALID';
  end if;
  if v_currency is null or v_currency !~ '^[A-Z]{3}$' then
    raise exception 'currency is a three-letter ISO 4217 code' using errcode = '22023', hint = 'INVOICE_CURRENCY_INVALID';
  end if;
  if v_reference is null then
    raise exception 'a payment needs a reference, such as the bank transaction id' using errcode = '22023', hint = 'INVOICE_PAYMENT_REFERENCE_REQUIRED';
  end if;
  begin
    v_received := coalesce(nullif(allocate_payment.payment ->> 'receivedOn', '')::date, current_date);
  exception when others then
    raise exception 'receivedOn is a date' using errcode = '22023', hint = 'INVOICE_ALLOCATIONS_INVALID';
  end;
  if not v_use_credit then
    if coalesce(allocate_payment.payment ->> 'amount', '') !~ '^[0-9]{1,18}$' or (allocate_payment.payment ->> 'amount')::bigint = 0 then
      raise exception 'a payment has a positive amount' using errcode = '22023', hint = 'INVOICE_PAYMENT_INVALID';
    end if;
    v_amount := (allocate_payment.payment ->> 'amount')::bigint;
  end if;
  if jsonb_typeof(v_allocations) <> 'array' or jsonb_array_length(v_allocations) = 0 or exists (
    select 1 from jsonb_array_elements(v_allocations) x
    where jsonb_typeof(x.value) <> 'object'
      or coalesce(x.value ->> 'invoiceId', '') !~ '^[0-9a-fA-F-]{36}$'
      or coalesce(x.value ->> 'amount', '') !~ '^[0-9]{1,18}$'
      or (x.value ->> 'amount')::bigint = 0
      or (x.value ? 'takeDiscount' and jsonb_typeof(x.value -> 'takeDiscount') <> 'boolean')
  ) or (
    select count(*) <> count(distinct x.value ->> 'invoiceId') from jsonb_array_elements(v_allocations) x
  ) then
    raise exception 'allocations is a non-empty array of { invoiceId, amount, takeDiscount? } with a positive amount, one per invoice' using errcode = '22023', hint = 'INVOICE_ALLOCATIONS_INVALID';
  end if;
  if exists (select 1 from "better_supabase"."invoice_allocations" b where b."tenant_id" = v_tenant and b."reference" = v_reference) then
    if exists (select 1 from "better_supabase"."invoice_allocations" b where b."tenant_id" = v_tenant and b."reference" = v_reference and b."unallocated_at" is not null) then
      raise exception 'this payment reference was allocated and unallocated; allocate the payment again under a new reference' using errcode = '55000', hint = 'INVOICE_ALLOCATION_REFERENCE_USED';
    end if;
    return jsonb_build_object(
      'reference', v_reference,
      'currency', (select min(x."currency"::text) from "better_supabase"."invoices" x join "better_supabase"."invoice_allocations" b on b."invoice_id" = x."id" where b."tenant_id" = v_tenant and b."reference" = v_reference),
      'partyId', (select min(b."party_id") from "better_supabase"."invoice_allocations" b where b."tenant_id" = v_tenant and b."reference" = v_reference),
      'allocated', coalesce((select sum(b."amount") from "better_supabase"."invoice_allocations" b where b."tenant_id" = v_tenant and b."reference" = v_reference and b."unallocated_at" is null), 0)::text,
      'discount', coalesce((select sum(b."discount") from "better_supabase"."invoice_allocations" b where b."tenant_id" = v_tenant and b."reference" = v_reference and b."unallocated_at" is null), 0)::text,
      'allocations', coalesce((select jsonb_agg(jsonb_build_object('invoiceId', b."invoice_id", 'source', b."source", 'amount', b."amount"::text, 'discount', b."discount"::text,
          'paymentId', b."payment_id", 'discountPaymentId', b."discount_payment_id", 'allocatedOn', b."allocated_on", 'unallocatedAt', b."unallocated_at") order by b."created_at", b."id")
        from "better_supabase"."invoice_allocations" b where b."tenant_id" = v_tenant and b."reference" = v_reference), '[]'::jsonb)) || jsonb_build_object('credited', coalesce((
      select (y."metadata" ->> 'amount') from "better_supabase"."ledger_transactions" y
      where y."tenant_id" = v_tenant and y."idempotency_key" = 'invoice-party-payment:' || v_reference), '0'));
  end if;
  select coalesce(sum((x.value ->> 'amount')::bigint), 0) into v_sum from jsonb_array_elements(v_allocations) x;
  if v_use_credit then
    v_amount := v_sum;
  elsif v_sum > v_amount then
    raise exception 'the allocations add up to more than the payment' using errcode = '23514', hint = 'INVOICE_ALLOCATIONS_TOO_LARGE';
  end if;
  v_remainder := v_amount - v_sum;
  if v_supplier and v_remainder > 0 then
    raise exception 'a supplier payment is allocated in full; lower the payment or allocate the rest' using errcode = '23514', hint = 'INVOICE_ALLOCATIONS_REMAINDER';
  end if;
  if allocate_payment.actor is not null then
    if jsonb_typeof(allocate_payment.actor) <> 'object' then
      raise exception 'actor must be an object of id, name, email, ip and userAgent' using errcode = '22023', hint = 'INVOICE_ACTOR_INVALID';
    end if;
    begin
      perform nullif(allocate_payment.actor ->> 'ip', '')::inet, nullif(allocate_payment.actor ->> 'id', '')::uuid;
    exception when invalid_text_representation then
      raise exception 'actor.ip must be an IP address and actor.id a user id' using errcode = '22023', hint = 'INVOICE_ACTOR_INVALID';
    end;
  end if;
  perform set_config('better_supabase.transition_actor', coalesce(allocate_payment.actor::text, ''), true);
  for v_alloc in
    select (x.value ->> 'invoiceId')::uuid as invoice, (x.value ->> 'amount')::bigint as amount,
      coalesce((x.value ->> 'takeDiscount')::boolean, true) as take
    from jsonb_array_elements(v_allocations) with ordinality x
    order by x.ordinality
  loop
    select * into v_row from "better_supabase"."invoices" x
    where x."id" = v_alloc.invoice and x."tenant_id" = v_tenant
      and (x."company_id"::text = v_party or x."contact_id"::text = v_party) and (x."direction" = 'purchase') = v_supplier
    for update;
    if v_row."id" is null then
      raise exception 'an allocation names no invoice of this party and side' using errcode = 'P0002', hint = 'INVOICE_NOT_FOUND';
    end if;
    if v_row."kind" <> 'invoice' or v_row."status" not in ('issued', 'partially_paid') then
      raise exception 'only an open invoice takes an allocation' using errcode = '55000', hint = 'INVOICE_NOT_PAYABLE';
    end if;
    if v_row."currency"::text <> v_currency then
      raise exception 'an allocation must be in the invoice''s currency' using errcode = '22023', hint = 'INVOICE_CURRENCY_MISMATCH';
    end if;
    v_balance := (v_row."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), 0) - v_row."credited_total" - v_row."paid_total");
    if v_alloc.amount > v_balance then
      raise exception 'an allocation is more than the invoice''s balance' using errcode = '23514', hint = 'INVOICE_ALLOCATION_TOO_LARGE';
    end if;
    v_early := coalesce(v_row."discount_amount_early", 0);
    v_due := v_row."discount_due_on";
    v_discount := 0;
    if v_alloc.take and v_early > 0 and v_due is not null and v_received <= v_due
      and v_alloc.amount < v_balance and v_alloc.amount >= v_balance - v_early then
      v_discount := v_balance - v_alloc.amount;
    end if;
    v_ref := v_reference || '/' || v_alloc.invoice::text;
    v_was := v_row."status";
    if v_use_credit then
      select a."id" into v_account from "better_supabase"."ledger_accounts" a
      where a."tenant_id" = v_tenant and a."code" = 'invoices:credit:' || v_party || ':' || v_row."currency"
      for update;
      if v_account is null or v_alloc.amount > coalesce(-(select sum(e."amount") from "better_supabase"."ledger_entries" e where e."account_id" = v_account), 0) then
        raise exception 'the party doesn''t have this much credit in the invoice''s currency' using errcode = '23514', hint = 'INVOICE_CREDIT_INSUFFICIENT';
      end if;
      v_pay := "better_supabase"."ledger_post"(v_tenant, 'invoice.credit_applied',
        jsonb_build_array(
          jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_row."tenant_id", 'receivable',
      'invoice:' || v_row."id"::text, 'Receivable ' || coalesce(v_row."identifier", v_row."id"::text),
      v_row."currency"::text, 0::smallint, 'invoices', v_row."id"::text,
      null, true, 'invoices.read', 'invoices', null), 'amount', -v_alloc.amount),
          jsonb_build_object('account', v_account, 'amount', v_alloc.amount)),
        'invoices', v_row."id"::text, null, 'invoice-payment:' || v_ref, v_received::timestamptz,
        jsonb_strip_nulls(jsonb_build_object('invoiceId', v_row."id", 'method', 'credit', 'partyId', v_party, 'reference', v_ref)));
  update "better_supabase"."invoices" x set
    "paid_total" = coalesce(-(select sum(e."amount") from "better_supabase"."ledger_entries" e where e."account_id" = (select a."id" from "better_supabase"."ledger_accounts" a where a."tenant_id" = x."tenant_id" and a."code" = 'invoice:' || x."id"::text)), 0),
    "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  update "better_supabase"."invoices" x set
    "status" = case
      when (x."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = x."id"), 0) - x."credited_total" - x."paid_total") <= 0 then 'paid'
      when x."paid_total" > 0 or x."credited_total" > 0 then 'partially_paid'
      else 'issued' end,
    "paid_at" = case when (x."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = x."id"), 0) - x."credited_total" - x."paid_total") <= 0 then coalesce(x."paid_at", now()) end
  where x."id" = v_row."id" and x."status" in ('issued', 'partially_paid', 'paid')
  returning * into v_row;
    else
      perform "better_supabase"."record_invoice_payment"(v_row."id", v_alloc.amount, v_currency, v_received::timestamptz,
        v_method, v_ref, v_note, allocate_payment.actor, null);
      select y."id" into v_pay from "better_supabase"."ledger_transactions" y where y."tenant_id" = v_tenant and y."idempotency_key" = 'invoice-payment:' || v_ref;
      select * into v_row from "better_supabase"."invoices" x where x."id" = v_alloc.invoice;
    end if;
    if v_discount > 0 then
      v_disc := "better_supabase"."ledger_post"(v_tenant, 'invoice.discount',
        jsonb_build_array(
          jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_row."tenant_id", 'receivable',
      'invoice:' || v_row."id"::text, 'Receivable ' || coalesce(v_row."identifier", v_row."id"::text),
      v_row."currency"::text, 0::smallint, 'invoices', v_row."id"::text,
      null, true, 'invoices.read', 'invoices', null), 'amount', -v_discount),
          jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_tenant, 'discount',
      'invoices:discount:' || case when v_row."direction" = 'purchase' then 'purchase' else 'sales' end || ':' || v_row."currency"::text,
      'Early payment discount ' || v_row."currency"::text, v_row."currency"::text, 0::smallint, null, null,
      null, true, 'invoices.read', 'invoices', null), 'amount', v_discount)),
        'invoices', v_row."id"::text, null, 'invoice-discount:' || v_ref, v_received::timestamptz,
        jsonb_strip_nulls(jsonb_build_object('invoiceId', v_row."id", 'method', 'early_payment_discount', 'reference', v_ref, 'partyId', v_party)));
  update "better_supabase"."invoices" x set
    "paid_total" = coalesce(-(select sum(e."amount") from "better_supabase"."ledger_entries" e where e."account_id" = (select a."id" from "better_supabase"."ledger_accounts" a where a."tenant_id" = x."tenant_id" and a."code" = 'invoice:' || x."id"::text)), 0),
    "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  update "better_supabase"."invoices" x set
    "status" = case
      when (x."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = x."id"), 0) - x."credited_total" - x."paid_total") <= 0 then 'paid'
      when x."paid_total" > 0 or x."credited_total" > 0 then 'partially_paid'
      else 'issued' end,
    "paid_at" = case when (x."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = x."id"), 0) - x."credited_total" - x."paid_total") <= 0 then coalesce(x."paid_at", now()) end
  where x."id" = v_row."id" and x."status" in ('issued', 'partially_paid', 'paid')
  returning * into v_row;
      if not better_supabase.import_run() is not null then
    perform "better_supabase"."accounting_post_source"('invoice_discount', v_disc::text);
  end if;
      perform "better_supabase".emit_event('invoice.discount_applied', jsonb_build_object('organizationId', v_row."tenant_id", 'invoiceId', v_row."id", 'subjectType', 'invoice', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier", 'reference', v_reference, 'paymentId', v_disc, 'discount', v_discount::text, 'balance', (v_row."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), 0) - v_row."credited_total" - v_row."paid_total")::text), 'invoices/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/invoices');
  perform better_supabase.audit_event(
    event_type => 'invoice.discount_applied',
    category => 'billing',
    target_type => 'invoice',
    record_id => v_row."id"::text,
    target_label => v_row."identifier",
    summary => 'invoice discount_applied',
    tenant => (v_row."tenant_id"::text)::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'invoiceId', v_row."id", 'subjectType', 'invoice', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier", 'reference', v_reference, 'paymentId', v_disc, 'discount', v_discount::text, 'balance', (v_row."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), 0) - v_row."credited_total" - v_row."paid_total")::text)
  );
    else
      v_disc := null;
    end if;
    insert into "better_supabase"."invoice_allocations" ("tenant_id", "reference", "party_id", "invoice_id", "source", "amount", "discount", "payment_id", "discount_payment_id", "allocated_on", "created_by")
    values (v_tenant, v_reference, v_party, v_row."id", case when v_use_credit then 'credit' else 'payment' end, v_alloc.amount, v_discount, v_pay, v_disc, v_received, auth.uid());
    perform "better_supabase".emit_event('invoice.allocated', jsonb_build_object('organizationId', v_row."tenant_id", 'invoiceId', v_row."id", 'subjectType', 'invoice', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier", 'reference', v_reference, 'paymentId', v_pay, 'partyId', v_party, 'amount', v_alloc.amount::text, 'discount', v_discount::text, 'balance', (v_row."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), 0) - v_row."credited_total" - v_row."paid_total")::text), 'invoices/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/invoices');
  perform better_supabase.audit_event(
    event_type => 'invoice.allocated',
    category => 'billing',
    target_type => 'invoice',
    record_id => v_row."id"::text,
    target_label => v_row."identifier",
    summary => 'invoice allocated',
    tenant => (v_row."tenant_id"::text)::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'invoiceId', v_row."id", 'subjectType', 'invoice', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier", 'reference', v_reference, 'paymentId', v_pay, 'partyId', v_party, 'amount', v_alloc.amount::text, 'discount', v_discount::text, 'balance', (v_row."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), 0) - v_row."credited_total" - v_row."paid_total")::text)
  );
    if v_row."status" = 'paid' and v_was <> 'paid' and (v_use_credit or v_discount > 0) then
      perform "better_supabase".emit_event('invoice.paid', jsonb_build_object('organizationId', v_row."tenant_id", 'invoiceId', v_row."id", 'subjectType', 'invoice', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier", 'total', v_row."total"::text), 'invoices/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/invoices');
    end if;
  end loop;
  if v_remainder > 0 then
    v_credit := "better_supabase"."ledger_post"(v_tenant, 'invoice.party_payment',
      jsonb_build_array(
        jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_tenant, 'cash', 'invoices:cash:' || v_currency,
      'Invoice payments ' || v_currency, v_currency, 0::smallint, null, null,
      null, true, 'invoices.read', 'invoices', null), 'amount', v_remainder),
        jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_tenant, 'credit', 'invoices:credit:' || v_party || ':' || v_currency,
      'Credit ' || v_party || ' ' || v_currency, v_currency, 0::smallint, 'invoice_party', v_party,
      null, true, 'invoices.read', 'invoices', null), 'amount', -v_remainder)),
      'invoices', v_party, null, 'invoice-party-payment:' || v_reference, v_received::timestamptz,
      jsonb_strip_nulls(jsonb_build_object('partyId', v_party, 'currency', v_currency, 'method', v_method,
        'reference', v_reference, 'note', v_note, 'amount', v_remainder::text)));
    if not better_supabase.import_run() is not null then
    perform "better_supabase"."accounting_post_source"('invoice_party_payment', v_credit::text);
  end if;
    v_credited := v_remainder;
  end if;
  return jsonb_build_object(
      'reference', v_reference,
      'currency', (select min(x."currency"::text) from "better_supabase"."invoices" x join "better_supabase"."invoice_allocations" b on b."invoice_id" = x."id" where b."tenant_id" = v_tenant and b."reference" = v_reference),
      'partyId', (select min(b."party_id") from "better_supabase"."invoice_allocations" b where b."tenant_id" = v_tenant and b."reference" = v_reference),
      'allocated', coalesce((select sum(b."amount") from "better_supabase"."invoice_allocations" b where b."tenant_id" = v_tenant and b."reference" = v_reference and b."unallocated_at" is null), 0)::text,
      'discount', coalesce((select sum(b."discount") from "better_supabase"."invoice_allocations" b where b."tenant_id" = v_tenant and b."reference" = v_reference and b."unallocated_at" is null), 0)::text,
      'allocations', coalesce((select jsonb_agg(jsonb_build_object('invoiceId', b."invoice_id", 'source', b."source", 'amount', b."amount"::text, 'discount', b."discount"::text,
          'paymentId', b."payment_id", 'discountPaymentId', b."discount_payment_id", 'allocatedOn', b."allocated_on", 'unallocatedAt', b."unallocated_at") order by b."created_at", b."id")
        from "better_supabase"."invoice_allocations" b where b."tenant_id" = v_tenant and b."reference" = v_reference), '[]'::jsonb)) || jsonb_build_object('credited', v_credited::text);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.allocate_stock (
  tenant        uuid,
  variant       uuid,
  location      uuid,
  quantity      numeric,
  document_type text,
  document_id   text,
  line_id       text,
  backorder     boolean DEFAULT true
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_location uuid := allocate_stock.location;
  v_available numeric;
  v_take numeric;
  v_row record;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', allocate_stock.tenant, 'inventory.reserve'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  if not exists (select 1 from "better_supabase"."product_variants" cv where cv."id" = allocate_stock.variant and cv."tenant_id" = allocate_stock.tenant) then
    raise exception 'variant not found in this organization' using errcode = 'P0002', hint = 'INVENTORY_VARIANT_NOT_FOUND';
  end if;
  if allocate_stock.quantity is null or allocate_stock.quantity <= 0 then
    raise exception 'the quantity must be greater than zero' using errcode = '22023', hint = 'INVENTORY_QUANTITY_INVALID';
  end if;
  if allocate_stock.document_type is null or allocate_stock.document_id is null then
    raise exception 'an allocation names its document type and id' using errcode = '22023', hint = 'INVENTORY_DOCUMENT_INVALID';
  end if;
  if v_location is null then
    select y."id" into v_location from "better_supabase"."inventory_locations" y
    left join "better_supabase"."stock_levels" s on s."location_id" = y."id" and s."variant_id" = allocate_stock.variant
    where y."tenant_id" = allocate_stock.tenant and y."active"
    order by coalesce(s."available", 0) desc, y."code"
    limit 1;
    if v_location is null then
      raise exception 'the organization has no active location' using errcode = 'P0002', hint = 'INVENTORY_LOCATION_NOT_FOUND';
    end if;
  elsif not exists (select 1 from "better_supabase"."inventory_locations" y where y."id" = v_location and y."tenant_id" = allocate_stock.tenant and y."active") then
    raise exception 'location not found or inactive' using errcode = 'P0002', hint = 'INVENTORY_LOCATION_NOT_FOUND';
  end if;
  insert into "better_supabase"."stock_levels" ("tenant_id", "variant_id", "location_id")
  values (allocate_stock.tenant, allocate_stock.variant, v_location)
  on conflict ("variant_id", "location_id") do nothing;
  select x."available" into v_available from "better_supabase"."stock_levels" x
  where x."variant_id" = allocate_stock.variant and x."location_id" = v_location for update;
  v_take := least(allocate_stock.quantity, greatest(v_available, 0));
  if v_take < allocate_stock.quantity and not coalesce(allocate_stock.backorder, true) and exists (select 1 from "better_supabase"."product_variants" cv where cv."id" = allocate_stock.variant and cv."track_inventory" and not cv."allow_backorder") then
    raise exception 'not enough stock available' using errcode = '23514', hint = 'INVENTORY_INSUFFICIENT';
  end if;
  insert into "better_supabase"."stock_allocations" as x ("tenant_id", "variant_id", "location_id", "document_type", "document_id", "line_id", "quantity", "allocated")
  values (allocate_stock.tenant, allocate_stock.variant, v_location, allocate_stock.document_type, allocate_stock.document_id,
    allocate_stock.line_id, allocate_stock.quantity, v_take)
  returning x."id" as id, x."tenant_id" as tenant, x."variant_id" as variant, x."location_id" as location,
    x."document_type" as document_type, x."document_id" as document_id, x."quantity" as quantity
  into v_row;
  if v_take > 0 then
    update "better_supabase"."stock_levels" x set "reserved" = greatest(x."reserved" + v_take, 0), "updated_at" = now()
    where x."variant_id" = allocate_stock.variant and x."location_id" = v_location;
  end if;
  perform "better_supabase".emit_event('allocation.created', jsonb_build_object('organizationId', v_row.tenant, 'id', v_row.id, 'variantId', v_row.variant, 'locationId', v_row.location,
        'documentType', v_row.document_type, 'documentId', v_row.document_id, 'quantity', v_row.quantity::text, 'allocated', v_take::text), 'stock-allocations/' || v_row.id::text, (v_row.tenant)::text, null, 'better-supabase/inventory');
  return (select jsonb_build_object('id', x."id", 'variantId', x."variant_id", 'locationId', x."location_id",
    'documentType', x."document_type", 'documentId', x."document_id", 'lineId', x."line_id",
    'quantity', x."quantity"::text, 'allocated', x."allocated"::text, 'fulfilled', x."fulfilled"::text,
    'backordered', x."backordered"::text, 'status', x."status", 'createdAt', x."created_at") from "better_supabase"."stock_allocations" x where x."id" = v_row.id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.allocate_username (
  base    text,
  user_id uuid DEFAULT NULL::uuid
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  stem text := left(regexp_replace(lower(coalesce(base, '')), '[^a-z0-9_]+', '', 'g'), 28);
  candidate text;
  n integer := 0;
begin
  if stem !~ '^[a-z]' then
    stem := left('u' || stem, 28);
  end if;
  if length(stem) < 3 then
    stem := 'user';
  end if;
  candidate := stem;
  while candidate = any(array['admin', 'administrator', 'api', 'app', 'auth', 'billing', 'help', 'login', 'logout', 'me', 'null', 'root', 'settings', 'signup', 'support', 'system', 'www']) or exists (
    select 1 from "better_supabase"."profiles" p
    where lower(p."username") = candidate and p."id" is distinct from user_id
  ) loop
    n := n + 1;
    candidate := stem || n::text;
  end loop;
  return candidate;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.allowed_ai_models (
  tenant uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := allowed_ai_models.tenant;
begin
  if v_tenant is not null and not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_tenant, 'ai_chat.read'), false)) then
    v_tenant := null;
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object('model_id', x."model_id", 'provider', x."provider", 'name', x."name", 'pricing', x."pricing", 'capabilities', x."capabilities", 'plans', to_jsonb(x."plans"), 'enabled', x."enabled", 'refreshed_at', x."refreshed_at") order by x."provider", x."name"), '[]'::jsonb)
    from "better_supabase"."ai_model_catalog" x
    where x."enabled" and (cardinality(x."plans") = 0 or (v_tenant is not null and x."plans" && better_supabase.tenant_entitlements(v_tenant)))
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.amend_activity (
  activity uuid,
  body     text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_from "better_supabase"."activities";
  v_id uuid;
  v_body text := nullif(trim(amend_activity.body), '');
  v_subjects jsonb;
  v_first jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_from from "better_supabase"."activities" x
  where x."id" = amend_activity.activity and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or x."tenant_id" in (select better_supabase.tenant_ids_with('activities.read')) and (
  not exists (select 1 from "better_supabase"."activity_subjects" lx where lx."activity_id" = x."id")
  or exists (select 1 from "better_supabase"."activity_subjects" lx where lx."activity_id" = x."id" and "better_supabase"."can_subject"(lx."subject_type", lx."subject_id", 'read'))
) and (x."audience" <> 'restricted' or x."tenant_id" in (select better_supabase.tenant_ids_with('activities.read_restricted')) or x."owner_id" = (select auth.uid()) or x."created_by" = (select auth.uid()) or exists (select 1 from "better_supabase"."activity_subjects" nx where nx."activity_id" = x."id" and "better_supabase"."has_subject_role"(nx."subject_type", nx."subject_id", x."restricted_roles"))));
  if v_from."id" is null then
    raise exception 'no such activity you can read' using errcode = 'P0002', hint = 'ACTIVITY_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_from."tenant_id", 'activities.write'), false)) then
    raise exception 'not allowed to amend activities' using errcode = '42501', hint = 'ACTIVITY_FORBIDDEN';
  end if;
  if v_body is null then
    raise exception 'an addendum needs a body' using errcode = '23502', hint = 'ACTIVITY_BODY_REQUIRED';
  end if;
  insert into "better_supabase"."activities" ("tenant_id", "type", "title", "body", "owner_id", "amends_id", "audience", "restricted_roles", "category", "goal_id", "locked_at", "created_by")
  values (v_from."tenant_id", v_from."type", v_from."title", v_body, auth.uid(), v_from."id", v_from."audience", v_from."restricted_roles", v_from."category", v_from."goal_id", case when v_from."type"::text = any ('{note,report}'::text[]) then now() + interval '24 hours' end, auth.uid())
  returning "id" into v_id;
  insert into "better_supabase"."activity_subjects" ("tenant_id", "activity_id", "subject_type", "subject_id", "position")
  select k."tenant_id", v_id, k."subject_type", k."subject_id", k."position"
  from "better_supabase"."activity_subjects" k where k."activity_id" = v_from."id";
  v_subjects := coalesce((select jsonb_agg(jsonb_build_object('type', sx."subject_type", 'id', sx."subject_id") order by sx."position") from "better_supabase"."activity_subjects" sx where sx."activity_id" = v_id), '[]'::jsonb);
  v_first := v_subjects -> 0;
  perform "better_supabase".emit_event('activity.amended', jsonb_build_object('organizationId', v_from."tenant_id", 'activityId', v_id, 'type', v_from."type"::text, 'subjectType', v_first ->> 'type', 'subjectId', v_first ->> 'id', 'subjects', v_subjects, 'amendsId', v_from."id"), 'activities/' || v_id::text, (v_from."tenant_id"::text)::text, null, 'better-supabase/activities');
  return (select to_jsonb(x) || jsonb_build_object('subjects', coalesce((select jsonb_agg(jsonb_build_object('type', sx."subject_type", 'id', sx."subject_id") order by sx."position") from "better_supabase"."activity_subjects" sx where sx."activity_id" = x."id"), '[]'::jsonb), 'overdue', x."done_at" is null and x."due_at" < now()) from "better_supabase"."activities" x where x."id" = v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.amend_observation (
  observation_id uuid,
  changes        jsonb,
  reason         text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_old "better_supabase"."observations"%rowtype;
  v_row "better_supabase"."observations"%rowtype;
  v_def "better_supabase"."observation_definitions"%rowtype;
  v_changes jsonb := coalesce(amend_observation.changes, '{}'::jsonb);
  v_reason text := nullif(trim(amend_observation.reason), '');
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_old from "better_supabase"."observations" x where x."id" = amend_observation.observation_id for update;
  if not found then
    raise exception 'observation not found' using errcode = 'P0002', hint = 'OBSERVATION_NOT_FOUND';
  end if;
  if not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_old."tenant_id", 'observations.record'), false)) and (case when coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then coalesce((case v_old."subject_type"
      when 'message' then (select s."tenant_id"::text from "better_supabase"."messages" s where s."id" = (v_old."subject_id")::uuid)
      when 'conversation' then (select s."tenant_id"::text from "better_supabase"."conversations" s where s."id" = (v_old."subject_id")::uuid)
      when 'channel' then (select s."tenant_id"::text from "better_supabase"."channels" s where s."id" = (v_old."subject_id")::uuid)
      when 'company' then (select s."tenant_id"::text from "better_supabase"."companies" s where s."id" = (v_old."subject_id")::uuid)
      when 'person' then (select s."tenant_id"::text from "better_supabase"."people" s where s."id" = (v_old."subject_id")::uuid)
      when 'deal' then (select s."tenant_id"::text from "better_supabase"."deals" s where s."id" = (v_old."subject_id")::uuid)
      when 'course' then (select s."tenant_id"::text from "better_supabase"."courses" s where s."id" = (v_old."subject_id")::uuid)
      when 'post' then (select s."tenant_id"::text from "better_supabase"."posts" s where s."id" = (v_old."subject_id")::uuid)
      when 'activity' then (select s."tenant_id"::text from "better_supabase"."activities" s where s."id" = (v_old."subject_id")::uuid)
      when 'quote' then (select s."tenant_id"::text from "better_supabase"."quotes" s where s."id" = (v_old."subject_id")::uuid)
      when 'work_item' then (select s."tenant_id"::text from "better_supabase"."work_items" s where s."id" = (v_old."subject_id")::uuid)
      when 'employee' then (select s."tenant_id"::text from "better_supabase"."employees" s where s."id" = (v_old."subject_id")::uuid)
      when 'ledger_account' then (select s."tenant_id"::text from "better_supabase"."ledger_accounts" s where s."id" = (v_old."subject_id")::uuid)
      when 'invoice' then (select s."tenant_id"::text from "better_supabase"."invoices" s where s."id" = (v_old."subject_id")::uuid)
      when 'product' then (select s."tenant_id"::text from "better_supabase"."products" s where s."id" = (v_old."subject_id")::uuid)
      when 'product_variant' then (select s."tenant_id"::text from "better_supabase"."product_variants" s where s."id" = (v_old."subject_id")::uuid)
      when 'rfq' then (select s."tenant_id"::text from "better_supabase"."rfqs" s where s."id" = (v_old."subject_id")::uuid)
      when 'till' then (select s."tenant_id"::text from "better_supabase"."tills" s where s."id" = (v_old."subject_id")::uuid)
      when 'order' then (select s."tenant_id"::text from "better_supabase"."orders" s where s."id" = (v_old."subject_id")::uuid)
      when 'calendar_event' then (select s."tenant_id"::text from "better_supabase"."calendar_events" s where s."id" = (v_old."subject_id")::uuid)
      when 'booking' then (select s."tenant_id"::text from "better_supabase"."bookings" s where s."id" = (v_old."subject_id")::uuid)
      when 'asset' then (select s."tenant_id"::text from "better_supabase"."assets" s where s."id" = (v_old."subject_id")::uuid)
      when 'asset_location' then (select s."tenant_id"::text from "better_supabase"."asset_locations" s where s."id" = (v_old."subject_id")::uuid)
      when 'lease' then (select s."tenant_id"::text from "better_supabase"."leases" s where s."id" = (v_old."subject_id")::uuid)
      when 'expense_report' then (select s."tenant_id"::text from "better_supabase"."expense_reports" s where s."id" = (v_old."subject_id")::uuid)
      when 'expense_line' then (select s."tenant_id"::text from "better_supabase"."expense_lines" s where s."id" = (v_old."subject_id")::uuid)
      when 'donation_fund' then (select s."tenant_id"::text from "better_supabase"."donation_funds" s where s."id" = (v_old."subject_id")::uuid)
      when 'warranty_claim' then (select s."tenant_id"::text from "better_supabase"."warranty_claims" s where s."id" = (v_old."subject_id")::uuid)
      when 'work_order' then (select s."tenant_id"::text from "better_supabase"."work_orders" s where s."id" = (v_old."subject_id")::uuid)
      when 'shipment' then (select s."tenant_id"::text from "better_supabase"."shipments" s where s."id" = (v_old."subject_id")::uuid)
      when 'contract' then (select s."tenant_id"::text from "better_supabase"."contracts" s where s."id" = (v_old."subject_id")::uuid)
      when 'control' then (select s."tenant_id"::text from "better_supabase"."controls" s where s."id" = (v_old."subject_id")::uuid)
      when 'compliance_policy' then (select s."tenant_id"::text from "better_supabase"."compliance_policies" s where s."id" = (v_old."subject_id")::uuid)
      when 'qualification_type' then (select s."tenant_id"::text from "better_supabase"."qualification_types" s where s."id" = (v_old."subject_id")::uuid)
      when 'risk' then (select s."tenant_id"::text from "better_supabase"."risks" s where s."id" = (v_old."subject_id")::uuid)
      when 'case' then (select s."tenant_id"::text from "better_supabase"."cases" s where s."id" = (v_old."subject_id")::uuid)
      when 'inspection' then (select s."tenant_id"::text from "better_supabase"."inspections" s where s."id" = (v_old."subject_id")::uuid)
      when 'inspection_program' then (select s."tenant_id"::text from "better_supabase"."inspection_programs" s where s."id" = (v_old."subject_id")::uuid)
      when 'inspection_finding' then (select s."tenant_id"::text from "better_supabase"."inspection_findings" s where s."id" = (v_old."subject_id")::uuid)
      when 'form' then (select s."tenant_id"::text from "better_supabase"."forms" s where s."id" = (v_old."subject_id")::uuid)
      when 'meeting' then (select s."tenant_id"::text from "better_supabase"."meetings" s where s."id" = (v_old."subject_id")::uuid)
      when 'meeting_decision' then (select s."tenant_id"::text from "better_supabase"."meeting_decisions" s where s."id" = (v_old."subject_id")::uuid)
      when 'maintenance_plan' then (select s."tenant_id"::text from "better_supabase"."maintenance_plans" s where s."id" = (v_old."subject_id")::uuid)
      when 'dam_usage_right' then (select s."tenant_id"::text from "better_supabase"."dam_usage_rights" s where s."id" = (v_old."subject_id")::uuid)
      when 'lims_sample' then (select s."tenant_id"::text from "better_supabase"."lims_samples" s where s."id" = (v_old."subject_id")::uuid)
      when 'tax_code' then (select s."tenant_id"::text from "better_supabase"."tax_codes" s where s."id" = (v_old."subject_id")::uuid)
      when 'production_order' then (select s."tenant_id"::text from "better_supabase"."production_orders" s where s."id" = (v_old."subject_id")::uuid)
      when 'work_center' then (select s."tenant_id"::text from "better_supabase"."work_centers" s where s."id" = (v_old."subject_id")::uuid)
      when 'bank_account' then (select s."tenant_id"::text from "better_supabase"."bank_accounts" s where s."id" = (v_old."subject_id")::uuid)
      when 'care_plan' then (select s."tenant_id"::text from "better_supabase"."care_plans" s where s."id" = (v_old."subject_id")::uuid)
      when 'incident' then (select s."tenant_id"::text from "better_supabase"."incidents" s where s."id" = (v_old."subject_id")::uuid)
      when 'content_entry' then (select s."tenant_id"::text from "better_supabase"."content_entries" s where s."id" = (v_old."subject_id")::uuid)
      when 'document' then (select s."tenant_id"::text from "better_supabase"."documents" s where s."id" = (v_old."subject_id")::uuid)
      when 'customer' then (select s."organization_id"::text from "public"."customers" s where s."id" = (v_old."subject_id")::uuid)
      when 'drive_node' then (select s."tenant_id"::text from "better_supabase"."drive_nodes" s where s."id" = (v_old."subject_id")::uuid)
      when 'organization' then (select s."id"::text from "public"."organizations" s where s."id" = (v_old."subject_id")::uuid)
      when 'application' then (select s."tenant_id"::text from "better_supabase"."applications" s where s."id" = (v_old."subject_id")::uuid)
      when 'change_request' then (select s."organization_id"::text from "public"."change_requests" s where s."id" = (v_old."subject_id")::uuid)
      when 'project' then (select s."organization_id"::text from "public"."projects" s where s."id" = (v_old."subject_id")::uuid)
      when 'task' then (select s."organization_id"::text from "public"."tasks" s where s."id" = (v_old."subject_id")::uuid)
      else null::text
    end) = v_old."tenant_id"::text, false) else (case v_old."subject_type"
      when 'message' then exists (select 1 from "better_supabase"."messages" s where s."id" = (v_old."subject_id")::uuid and s."tenant_id"::text = v_old."tenant_id"::text)
      when 'conversation' then exists (select 1 from "better_supabase"."conversations" s where s."id" = (v_old."subject_id")::uuid and s."tenant_id"::text = v_old."tenant_id"::text)
      when 'channel' then exists (select 1 from "better_supabase"."channels" s where s."id" = (v_old."subject_id")::uuid and s."tenant_id"::text = v_old."tenant_id"::text)
      when 'company' then exists (select 1 from "better_supabase"."companies" s where s."id" = (v_old."subject_id")::uuid and s."tenant_id"::text = v_old."tenant_id"::text)
      when 'person' then exists (select 1 from "better_supabase"."people" s where s."id" = (v_old."subject_id")::uuid and s."tenant_id"::text = v_old."tenant_id"::text)
      when 'deal' then exists (select 1 from "better_supabase"."deals" s where s."id" = (v_old."subject_id")::uuid and s."tenant_id"::text = v_old."tenant_id"::text)
      when 'course' then exists (select 1 from "better_supabase"."courses" s where s."id" = (v_old."subject_id")::uuid and s."tenant_id"::text = v_old."tenant_id"::text)
      when 'post' then exists (select 1 from "better_supabase"."posts" s where s."id" = (v_old."subject_id")::uuid and s."tenant_id"::text = v_old."tenant_id"::text)
      when 'activity' then exists (select 1 from "better_supabase"."activities" s where s."id" = (v_old."subject_id")::uuid and s."tenant_id"::text = v_old."tenant_id"::text)
