    category => 'membership',
    target_type => 'team',
    record_id => (archive_team.team)::text,
    tenant => (v_tenant)::uuid,
    metadata => jsonb_build_object('organizationId', v_tenant, 'id', archive_team.team)
  );
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.archive_work_item (
  task     uuid,
  archived boolean
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."work_items";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  update "better_supabase"."work_items" x set "archived_at" = case when archive_work_item.archived then coalesce(x."archived_at", now()) end
  where x."id" = archive_work_item.task and ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', x."tenant_id", 'tasks.write'), false))
  returning * into v_row;
  if v_row."id" is null then
    return false;
  end if;
  if archive_work_item.archived then
    perform "better_supabase".emit_event('work_item.archived', jsonb_build_object('organizationId', v_row."tenant_id", 'workItemId', v_row."id", 'subjectType', 'work_item', 'subjectId', v_row."id"::text, 'title', v_row."title"), 'work_items/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/tasks');
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.archive_work_items (
  ids      uuid[],
  archived boolean DEFAULT true
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."work_items";
  v_ids uuid[] := '{}';
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  for v_row in
    with changed as (
      update "better_supabase"."work_items" x set "archived_at" = case when archive_work_items.archived then coalesce(x."archived_at", now()) end
      where x."id" = any (coalesce(archive_work_items.ids, '{}')) and ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', x."tenant_id", 'tasks.write'), false))
      returning x.*
    )
    select * from changed
  loop
    v_ids := array_append(v_ids, v_row."id");
    if archive_work_items.archived then
      perform "better_supabase".emit_event('work_item.archived', jsonb_build_object('organizationId', v_row."tenant_id", 'workItemId', v_row."id", 'subjectType', 'work_item', 'subjectId', v_row."id"::text, 'title', v_row."title"), 'work_items/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/tasks');
    end if;
  end loop;
  return jsonb_build_object(
    'ids', to_jsonb(v_ids),
    'skipped', to_jsonb(array(select distinct i from unnest(coalesce(archive_work_items.ids, '{}')) i where i is not null and not (i = any (v_ids)))));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.as_column_type (
  value  text,
  target anyelement
)
  RETURNS anyelement
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
begin
  return value;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.assert_document_template (
  document_type text,
  body          text,
  text_block    boolean DEFAULT false
)
  RETURNS void
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  v_issues jsonb;
  v_code text;
  v_message text;
begin
  v_issues := "better_supabase"."validate_document_template"(assert_document_template.document_type, assert_document_template.body, assert_document_template.text_block);
  if jsonb_array_length(v_issues) = 0 then
    return;
  end if;
  v_code := v_issues -> 0 ->> 'code';
  v_message := v_issues -> 0 ->> 'message';
  if v_code = 'DOCUMENT_TEMPLATE_UNKNOWN_VARIABLE' then
    raise exception '%', v_message using errcode = '22023', hint = 'DOCUMENT_TEMPLATE_UNKNOWN_VARIABLE';
  elsif v_code = 'DOCUMENT_TEMPLATE_UNKNOWN_FILTER' then
    raise exception '%', v_message using errcode = '22023', hint = 'DOCUMENT_TEMPLATE_UNKNOWN_FILTER';
  end if;
  raise exception '%', v_message using errcode = '22023', hint = 'DOCUMENT_TEMPLATE_SYNTAX';
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.assess_risk (
  risk_id             uuid,
  inherent_likelihood integer,
  inherent_impact     integer,
  residual_likelihood integer,
  residual_impact     integer,
  rationale           text    DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."risks";
  v_matrix "better_supabase"."risk_matrices";
  v_assessment uuid := gen_random_uuid();
  v_inherent integer;
  v_residual integer;
  v_inherent_band text;
  v_residual_band text;
  v_version jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."risks" x where x."id" = assess_risk.risk_id for update;
  if not found then
    raise exception 'no such risk' using errcode = 'P0002', hint = 'RISK_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'risks.assess'), false))) then
    raise exception 'not allowed to assess risks' using errcode = '42501', hint = 'RISK_FORBIDDEN';
  end if;
  if v_row."status" = 'closed' then
    raise exception 'the risk is closed' using errcode = '55000', hint = 'RISK_CLOSED';
  end if;
  if length(assess_risk.rationale) > 10000 then
    raise exception 'a rationale is at most 10000 characters' using errcode = '22023', hint = 'RISK_INVALID';
  end if;
  select * into v_matrix from "better_supabase"."risk_matrices" x where x."id" = v_row."matrix_id";
  if assess_risk.inherent_likelihood is null or assess_risk.inherent_impact is null
    or assess_risk.inherent_likelihood not between 1 and jsonb_array_length(v_matrix."likelihood_levels")
    or assess_risk.inherent_impact not between 1 and jsonb_array_length(v_matrix."impact_levels")
    or assess_risk.residual_likelihood is null or assess_risk.residual_impact is null
    or assess_risk.residual_likelihood not between 1 and jsonb_array_length(v_matrix."likelihood_levels")
    or assess_risk.residual_impact not between 1 and jsonb_array_length(v_matrix."impact_levels") then
    raise exception 'a likelihood or impact is not a level of the risk''s matrix' using errcode = '22023', hint = 'RISK_LEVEL_OUT_OF_RANGE';
  end if;
  v_inherent := (case when v_matrix."scoring" = 'sum' then assess_risk.inherent_likelihood + assess_risk.inherent_impact else assess_risk.inherent_likelihood * assess_risk.inherent_impact end);
  v_residual := (case when v_matrix."scoring" = 'sum' then assess_risk.residual_likelihood + assess_risk.residual_impact else assess_risk.residual_likelihood * assess_risk.residual_impact end);
  v_inherent_band := (select b ->> 'key' from jsonb_array_elements(v_matrix."bands") b where v_inherent between (b ->> 'min')::integer and (b ->> 'max')::integer limit 1);
  v_residual_band := (select b ->> 'key' from jsonb_array_elements(v_matrix."bands") b where v_residual between (b ->> 'min')::integer and (b ->> 'max')::integer limit 1);
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_risk_assess"(uuid, integer, integer)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::integer, $3::integer)', v_hook::oid::regproc)
        using v_row."id", v_inherent, v_residual;
    end if;
  end;
  v_version := "better_supabase"."version_insert"(v_row."tenant_id", 'risk', v_row."id"::text,
    jsonb_build_object('title', v_row."title", 'category', v_row."category", 'description', v_row."description", 'cause', v_row."cause", 'consequence', v_row."consequence", 'matrixId', v_row."matrix_id", 'assessmentId', v_assessment,
      'inherent', jsonb_build_object('likelihood', assess_risk.inherent_likelihood, 'impact', assess_risk.inherent_impact, 'score', v_inherent, 'band', v_inherent_band),
      'residual', jsonb_build_object('likelihood', assess_risk.residual_likelihood, 'impact', assess_risk.residual_impact, 'score', v_residual, 'band', v_residual_band),
      'rationale', assess_risk.rationale),
    null, 'assessment', 'manual', true, auth.uid());
  insert into "better_supabase"."risk_assessments" ("id", "tenant_id", "risk_id", "inherent_likelihood", "inherent_impact", "inherent_score", "inherent_band", "residual_likelihood", "residual_impact", "residual_score", "residual_band", "rationale", "version_id", "assessed_by")
  values (v_assessment, v_row."tenant_id", v_row."id", assess_risk.inherent_likelihood, assess_risk.inherent_impact, v_inherent, v_inherent_band, assess_risk.residual_likelihood, assess_risk.residual_impact, v_residual, v_residual_band, nullif(trim(assess_risk.rationale), ''), (v_version ->> 'id')::uuid, auth.uid());
  update "better_supabase"."risks" x set
    "inherent_likelihood" = assess_risk.inherent_likelihood,
    "inherent_impact" = assess_risk.inherent_impact,
    "inherent_score" = v_inherent,
    "inherent_band" = v_inherent_band,
    "residual_likelihood" = assess_risk.residual_likelihood,
    "residual_impact" = assess_risk.residual_impact,
    "residual_score" = v_residual,
    "residual_band" = v_residual_band,
    "current_assessment_id" = v_assessment,
    "status" = case when x."status" = 'identified' then 'assessed' else x."status" end,
    "next_review_on" = (current_date + make_interval(months => coalesce(x."review_interval_months", 12)))::date,
    "review_notified_for" = null,
    "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('risk.assessed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'title', v_row."title", 'status', v_row."status", 'assessmentId', v_assessment, 'inherentScore', v_inherent, 'inherentBand', v_inherent_band, 'residualScore', v_residual, 'residualBand', v_residual_band), 'risks/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/risks');
  perform better_supabase.audit_event(
    event_type => 'risk.assessed',
    category => 'data',
    target_type => 'risk',
    record_id => v_row."id"::text,
    target_label => v_row."title",
    summary => 'risk assessed',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'title', v_row."title", 'status', v_row."status", 'assessmentId', v_assessment, 'inherentScore', v_inherent, 'inherentBand', v_inherent_band, 'residualScore', v_residual, 'residualBand', v_residual_band)
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_risk_assess"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'number', v_row."number", 'matrixId', v_row."matrix_id", 'title', v_row."title", 'description', v_row."description", 'category', v_row."category", 'cause', v_row."cause", 'consequence', v_row."consequence", 'ownerId', v_row."owner_id", 'status', v_row."status", 'treatment', v_row."treatment", 'reviewIntervalMonths', v_row."review_interval_months", 'nextReviewOn', v_row."next_review_on", 'reviewedAt', v_row."reviewed_at", 'inherent', case when v_row."inherent_score" is null then null else jsonb_build_object('likelihood', v_row."inherent_likelihood", 'impact', v_row."inherent_impact", 'score', v_row."inherent_score", 'band', v_row."inherent_band") end, 'residual', case when v_row."residual_score" is null then null else jsonb_build_object('likelihood', v_row."residual_likelihood", 'impact', v_row."residual_impact", 'score', v_row."residual_score", 'band', v_row."residual_band") end, 'currentAssessmentId', v_row."current_assessment_id", 'closedAt', v_row."closed_at", 'archivedAt', v_row."archived_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.asset_assignment_history (
  asset_id  uuid,
  page_size integer DEFAULT 50
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."assets"%rowtype;
begin
  select * into v_row from "better_supabase"."assets" x where x."id" = asset_assignment_history.asset_id;
  if not found or not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'assets.read'), false)) or (v_row."assignee_type" = 'member' and coalesce(v_row."assignee_id" = auth.uid()::text, false))) then
    raise exception 'asset not found' using errcode = 'P0002', hint = 'ASSETS_NOT_FOUND';
  end if;
  return coalesce((
    select jsonb_agg(z.item order by z.assigned_at desc, z.id)
    from (
      select jsonb_build_object('id', y."id", 'assetId', y."asset_id", 'assigneeType', y."assignee_type", 'assigneeId', y."assignee_id", 'note', y."note", 'assignedBy', y."assigned_by", 'assignedAt', y."assigned_at", 'releasedAt', y."released_at") as item, y."assigned_at" as assigned_at, y."id" as id
      from "better_supabase"."asset_assignments" y where y."asset_id" = v_row."id"
      order by y."assigned_at" desc, y."id"
      limit least(greatest(coalesce(asset_assignment_history.page_size, 50), 1), 500)
    ) z
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.asset_depreciate (
  asset_id uuid,
  until    date
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_asset "better_supabase"."assets"%rowtype;
  v_row "better_supabase"."asset_depreciations"%rowtype;
  v_start date;
  v_month date;
  v_last date;
  v_booked bigint;
  v_base bigint;
  v_age integer;
  v_amount bigint;
  v_entry uuid;
  v_count integer := 0;
begin
  select * into v_asset from "better_supabase"."assets" x where x."id" = asset_depreciate.asset_id for update;
  if not found or v_asset."depreciation_method" = 'none'
    or v_asset."acquisition_cost" is null or v_asset."acquired_on" is null then
    return 0;
  end if;
  select max(y."period_start"), coalesce(sum(y."amount"), 0) into v_last, v_booked
  from "better_supabase"."asset_depreciations" y where y."asset_id" = v_asset."id";
  v_start := date_trunc('month', v_asset."acquired_on")::date;
  v_month := coalesce((v_last + interval '1 month')::date, v_start);
  v_base := v_asset."acquisition_cost" - v_asset."residual_value";
  while (v_month + interval '1 month' - interval '1 day')::date <= asset_depreciate.until
    and (v_asset."disposed_on" is null or v_month < date_trunc('month', v_asset."disposed_on")::date)
    and v_booked < v_base loop
    v_age := ((extract(year from v_month) - extract(year from v_start)) * 12 + extract(month from v_month) - extract(month from v_start))::integer + 1;
    if v_asset."depreciation_method" = 'straight_line' then
      v_amount := least(v_base, round(v_base::numeric * v_age / v_asset."useful_life_months")::bigint) - v_booked;
    elsif v_asset."useful_life_months" is not null and v_age >= v_asset."useful_life_months" then
      v_amount := v_base - v_booked;
    else
      v_amount := least(v_base - v_booked, round((v_asset."acquisition_cost" - v_booked)::numeric * v_asset."depreciation_rate_bps" / 120000)::bigint);
    end if;
    if v_amount > 0 then
      insert into "better_supabase"."asset_depreciations" ("tenant_id", "asset_id", "period_start", "amount")
      values (v_asset."tenant_id", v_asset."id", v_month, v_amount)
      returning * into v_row;
      v_entry := "better_supabase"."accounting_post_source"('asset_depreciation', v_row."id"::text);
      if v_entry is not null then
        update "better_supabase"."asset_depreciations" y set "entry_id" = v_entry where y."id" = v_row."id"
        returning * into v_row;
      end if;
      perform "better_supabase".emit_event('asset.depreciated', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'assetId', v_row."asset_id", 'periodStart', v_row."period_start", 'amount', v_row."amount"::text, 'currency', v_asset."currency", 'entryId', v_row."entry_id"), 'assets/' || v_asset."id"::text, (v_asset."tenant_id")::text, null, 'better-supabase/assets');
      v_booked := v_booked + v_amount;
      v_count := v_count + 1;
    end if;
    v_month := (v_month + interval '1 month')::date;
  end loop;
  return v_count;
end;
$function$;

