CREATE OR REPLACE FUNCTION better_supabase.authz_version (
  p_user uuid
)
  RETURNS bigint
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(
    (select v.version from better_supabase.user_authz_versions v where v.user_id = p_user),
    0
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.available_slots (
  service     uuid,
  range_start timestamp with time zone,
  range_end   timestamp with time zone,
  tz          text                     DEFAULT NULL::text,
  resource    uuid                     DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_tenant uuid;
begin
  select "tenant_id" into v_tenant from "better_supabase"."booking_services" where "id" = available_slots.service;
  if not found then
    raise exception 'service not found' using errcode = 'P0002', hint = 'BOOKING_SERVICE_NOT_FOUND';
  end if;
  if not ((auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'bookings.read'), false)) or (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'bookings.create'), false))) then
    raise exception 'not allowed to read bookings' using errcode = '42501', hint = 'BOOKING_FORBIDDEN';
  end if;
  if available_slots.tz is not null and not exists (select 1 from pg_catalog.pg_timezone_names z where z.name = available_slots.tz) then
    raise exception 'tz must be an IANA time zone' using errcode = '22023', hint = 'BOOKING_TZ_INVALID';
  end if;
  if available_slots.range_end - available_slots.range_start > interval '62 days' then
    raise exception 'ask for at most 62 days of slots' using errcode = '22023', hint = 'BOOKING_RANGE_INVALID';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('resourceId', t.resource_id, 'startsAt', t.starts_at, 'endsAt', t.ends_at, 'localStart', t.local_start, 'seats', t.seats) order by t.starts_at, t.resource_id) from "better_supabase"."booking_slots"(available_slots.service, available_slots.range_start, available_slots.range_end, available_slots.tz, available_slots.resource) t), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.award_rfq (
  rfq_id   uuid,
  quote_id uuid,
  location uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."rfqs";
  v_quote "better_supabase"."rfq_quotes";
  v_invitation "better_supabase"."rfq_suppliers";
  v_order uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."rfqs" x where x."id" = award_rfq.rfq_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'rfqs.read'), false))) then
    raise exception 'no such request for quotation' using errcode = 'P0002', hint = 'RFQ_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'rfqs.manage'), false))) then
    raise exception 'not allowed to award requests for quotation' using errcode = '42501', hint = 'RFQ_FORBIDDEN';
  end if;
  if v_row."status" not in ('open', 'closed') then
    raise exception 'only an open or closed request can be awarded' using errcode = '55000', hint = 'RFQ_STATUS';
  end if;
  select * into v_quote from "better_supabase"."rfq_quotes" y where y."id" = award_rfq.quote_id and y."rfq_id" = v_row."id" for update;
  if not found then
    raise exception 'no such quote' using errcode = 'P0002', hint = 'RFQ_QUOTE_NOT_FOUND';
  end if;
  if v_quote."status" <> 'submitted' then
    raise exception 'only a submitted quote can be awarded' using errcode = '55000', hint = 'RFQ_STATUS';
  end if;
  if (select count(*) from "better_supabase"."rfq_quote_lines" z where z."quote_id" = v_quote."id")
    <> (select count(*) from "better_supabase"."rfq_lines" ln where ln."rfq_id" = v_row."id") then
    raise exception 'only a quote that prices every line can be awarded' using errcode = '22023', hint = 'RFQ_INVALID';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_rfq_award"(uuid, uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::uuid)', v_hook::oid::regproc)
        using award_rfq.rfq_id, award_rfq.quote_id;
    end if;
  end;
  select * into v_invitation from "better_supabase"."rfq_suppliers" i where i."id" = v_quote."invitation_id";
  if award_rfq.location is not null then
    if exists (select 1 from "better_supabase"."rfq_lines" y where y."rfq_id" = v_row."id" and y."variant_id" is null) then
      raise exception 'every line needs a variantId to create a purchase order' using errcode = '22023', hint = 'RFQ_INVALID';
    end if;
    v_order := ("better_supabase"."save_purchase_order"(
      v_row."tenant_id", null, award_rfq.location, v_invitation."supplier_type", v_invitation."supplier_id",
      v_row."currency",
      case when v_quote."lead_time_days" is null then null else now() + make_interval(days => v_quote."lead_time_days") end,
      (select jsonb_agg(jsonb_build_object('variantId', y."variant_id", 'quantity', y."quantity", 'unitCost', z."unit_amount"::text) order by y."ordinal")
        from "better_supabase"."rfq_lines" y join "better_supabase"."rfq_quote_lines" z on z."line_id" = y."id" and z."quote_id" = v_quote."id"
        where y."rfq_id" = v_row."id"),
      v_row."number"
    ) ->> 'id')::uuid;
  end if;
  update "better_supabase"."rfq_quotes" y set "status" = case when y."id" = v_quote."id" then 'awarded' else 'rejected' end, "updated_at" = now()
  where y."rfq_id" = v_row."id" and y."status" = 'submitted';
  update "better_supabase"."rfqs" x set "status" = 'awarded', "awarded_quote_id" = v_quote."id", "purchase_order_id" = v_order,
    "awarded_at" = now(), "closed_at" = coalesce(x."closed_at", now()), "updated_at" = now()
  where x."id" = v_row."id" returning * into v_row;
  perform "better_supabase".emit_event('rfq.awarded', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'status', v_row."status", 'quoteId', v_row."awarded_quote_id", 'purchaseOrderId', v_row."purchase_order_id"), 'rfqs/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/rfqs');
  perform better_supabase.audit_event(
    event_type => 'rfq.awarded',
    category => 'data',
    target_type => 'rfq',
    record_id => v_row."id"::text,
    target_label => v_row."number",
    summary => 'request for quotation awarded',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'status', v_row."status", 'quoteId', v_row."awarded_quote_id", 'purchaseOrderId', v_row."purchase_order_id")
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_rfq_award"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'number', v_row."number", 'title', v_row."title", 'status', v_row."status", 'currency', v_row."currency", 'dueAt', v_row."due_at", 'notes', v_row."notes", 'awardedQuoteId', v_row."awarded_quote_id", 'purchaseOrderId', v_row."purchase_order_id", 'cancelReason', v_row."cancel_reason", 'openedAt', v_row."opened_at", 'closedAt', v_row."closed_at", 'awardedAt', v_row."awarded_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.backfill_profiles()
  RETURNS integer
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select count(*)::integer from auth.users u where "better_supabase"."sync_profile"(u.id)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ban_user (
  tenant     uuid,
  user_id    uuid,
  reason     text                     DEFAULT NULL::text,
  expires_at timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."moderation_bans";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', ban_user.tenant, 'moderation.ban'), false)) then
    raise exception 'not allowed to ban users' using errcode = '42501', hint = 'MODERATION_FORBIDDEN';
  end if;
  if ban_user.user_id is null or ban_user.user_id = auth.uid() then
    raise exception 'pick another user to ban' using errcode = '22023', hint = 'MODERATION_INVALID';
  end if;
  if ban_user.expires_at is not null and ban_user.expires_at <= now() then
    raise exception 'expires_at must be in the future' using errcode = '22023', hint = 'MODERATION_INVALID';
  end if;
  if length(ban_user.reason) > 1000 then
    raise exception 'reason must be at most 1000 characters' using errcode = '22023', hint = 'MODERATION_INVALID';
  end if;
  delete from "better_supabase"."moderation_bans" x where x."tenant_id" = ban_user.tenant and x."user_id" = ban_user.user_id and x."lifted_at" is null and x."expires_at" <= now();
  insert into "better_supabase"."moderation_bans" ("tenant_id", "user_id", "reason", "banned_by", "expires_at")
  values (ban_user.tenant, ban_user.user_id, nullif(trim(ban_user.reason), ''), auth.uid(), ban_user.expires_at)
  on conflict ("tenant_id", "user_id") where "lifted_at" is null do update
    set "reason" = excluded."reason", "banned_by" = excluded."banned_by", "expires_at" = excluded."expires_at"
  returning * into v_row;
  perform "better_supabase".emit_event('moderation_ban.created', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'userId', v_row."user_id", 'expiresAt', v_row."expires_at"), 'moderation-bans/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/moderation');
  perform better_supabase.audit_event(
    event_type => 'moderation_ban.created',
    category => 'security',
    target_type => 'user',
    record_id => v_row."user_id"::text,
    summary => 'banned a user',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'userId', v_row."user_id", 'expiresAt', v_row."expires_at")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'userId', v_row."user_id", 'reason', v_row."reason", 'bannedBy', v_row."banned_by", 'expiresAt', v_row."expires_at", 'liftedBy', v_row."lifted_by", 'liftedAt', v_row."lifted_at", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bank_mod97 (
  value text
)
  RETURNS integer
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
declare
  v_rem integer := 0;
  v_n integer;
  v_char text;
begin
  if value is null or value = '' then
    return null;
  end if;
  foreach v_char in array regexp_split_to_array(value, '') loop
    if v_char between '0' and '9' then
      v_rem := (v_rem * 10 + ascii(v_char) - 48) % 97;
    elsif v_char between 'A' and 'Z' then
      v_n := ascii(v_char) - 55;
      v_rem := (v_rem * 100 + v_n) % 97;
    else
      return null;
    end if;
  end loop;
  return v_rem;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bank_reconciliation_board (
  account_id uuid,
  line_limit integer DEFAULT 50
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with src as (
    select "better_supabase"."list_bank_transactions"(bank_reconciliation_board.account_id,
      jsonb_build_object('limit', bank_reconciliation_board.line_limit)) as payload
  )
  select jsonb_build_object(
    'status', "better_supabase"."bank_reconciliation_status"(bank_reconciliation_board.account_id, null),
    'lines', coalesce((
      select jsonb_agg(jsonb_build_object(
          'id', x.line -> 'id', 'bookedOn', x.line -> 'bookedOn', 'amount', x.line -> 'amount',
          'currency', x.line -> 'currency', 'counterpartyName', x.line -> 'counterpartyName',
          'counterpartyIban', x.line -> 'counterpartyIban', 'remittance', x.line -> 'remittance',
          'status', x.line -> 'status') order by x.position)
      from jsonb_array_elements(src.payload) with ordinality as x(line, position)
    ), '[]'::jsonb),
    'suggestions', coalesce((
      select jsonb_agg(best.s || jsonb_build_object('transactionId', x.line ->> 'id') order by x.position)
      from jsonb_array_elements(src.payload) with ordinality as x(line, position)
      cross join lateral (
        select s from jsonb_array_elements("better_supabase"."suggest_bank_matches"((x.line ->> 'id')::uuid)) s
        where x.line ->> 'status' = 'unmatched' and s ->> 'targetType' = 'invoice' limit 1) best
    ), '[]'::jsonb))
  from src;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bank_reconciliation_status (
  account_id uuid,
  as_of      date DEFAULT NULL::date
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_account "better_supabase"."bank_accounts"%rowtype;
  v_statement "better_supabase"."bank_statements"%rowtype;
  v_as_of date := coalesce(bank_reconciliation_status.as_of, current_date);
  v_total bigint;
  v_unmatched integer;
  v_unmatched_total bigint;
  v_ledger bigint;
begin
  select * into v_account from "better_supabase"."bank_accounts" x where x."id" = bank_reconciliation_status.account_id;
  if not found then
    raise exception 'no such bank account' using errcode = 'P0002', hint = 'BANK_ACCOUNT_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_account."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_account."tenant_id", 'banking.read'), false))) then
    raise exception 'not allowed to do this with bank accounts' using errcode = '42501', hint = 'BANKING_FORBIDDEN';
  end if;
  select * into v_statement from "better_supabase"."bank_statements" x
  where x."account_id" = v_account."id" and x."closing_balance" is not null
    and coalesce(x."until_on", x."created_at"::date) <= v_as_of
  order by coalesce(x."until_on", x."created_at"::date) desc, x."created_at" desc
  limit 1;
  select coalesce(sum(x."amount"), 0),
    count(*) filter (where x."status" = 'unmatched'),
    coalesce(sum(x."amount") filter (where x."status" = 'unmatched'), 0)
  into v_total, v_unmatched, v_unmatched_total
  from "better_supabase"."bank_transactions" x
  where x."account_id" = v_account."id" and x."booked_on" <= v_as_of;
  v_ledger := (select sum(y."amount_currency")
      from "better_supabase"."accounting_entry_lines" y
      join "better_supabase"."accounting_entries" z on z."id" = y."entry_id"
      join "better_supabase"."accounting_journals" w on w."id" = v_account."journal_id"
      where y."tenant_id" = v_account."tenant_id" and y."account_id" = w."default_account_id"
        and y."currency" = v_account."currency"
        and z."status" <> 'draft' and z."entry_date" <= v_as_of);
  return jsonb_build_object(
    'accountId', v_account."id",
    'asOf', v_as_of,
    'currency', v_account."currency",
    'statementId', v_statement."id",
    'statementBalance', v_statement."closing_balance"::text,
    'transactionTotal', v_total::text,
    'unmatchedCount', v_unmatched,
    'unmatchedTotal', v_unmatched_total::text,
    'ledgerBalance', v_ledger::text,
    'difference', (v_statement."closing_balance" - v_ledger)::text,
    'reconciled', v_unmatched = 0 and coalesce(v_statement."closing_balance" = v_ledger, true));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bank_reference (
  reference text
)
  RETURNS text
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
declare
  v_ref text := upper(regexp_replace(coalesce(reference, ''), '[^A-Za-z0-9]', '', 'g'));
  v_weights integer[] := array[2, 4, 8, 5, 10, 9, 7, 3, 6, 1, 2, 4, 8, 5, 10];
  v_sum integer := 0;
  v_check integer;
  v_i integer;
begin
  if v_ref ~ '^RF[0-9]{2}[A-Z0-9]{1,21}$' then
    if "better_supabase"."bank_mod97"(substr(v_ref, 5) || substr(v_ref, 1, 4)) = 1 then
      return substr(v_ref, 5);
    end if;
    return null;
  end if;
  if v_ref ~ '^[0-9]{16}$' then
    for v_i in 1..15 loop
      v_sum := v_sum + (ascii(substr(v_ref, 17 - v_i, 1)) - 48) * v_weights[v_i];
    end loop;
    v_check := 11 - v_sum % 11;
    v_check := case v_check when 10 then 1 when 11 then 0 else v_check end;
    if v_check = ascii(substr(v_ref, 1, 1)) - 48 then
      return nullif(ltrim(substr(v_ref, 2), '0'), '');
    end if;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bank_rule_condition (
  node    jsonb,
  payload jsonb
)
  RETURNS boolean
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
declare
  v_child jsonb;
  v_any boolean := false;
  v_all boolean := true;
  v_result boolean;
  v_op text;
  v_value jsonb;
  v_at jsonb;
  v_text text;
  v_other text;
  v_numeric boolean;
  v_empty boolean;
begin
  if jsonb_typeof(node) is distinct from 'object' then
    raise exception 'conditions must be a filter tree of known operators' using errcode = '22023', hint = 'BANK_RULE_INVALID';
  end if;
  if node ->> 'type' = 'group' then
    if jsonb_typeof(node -> 'rules') is distinct from 'array'
      or coalesce(node ->> 'combinator', 'and') not in ('and', 'or') then
      raise exception 'conditions must be a filter tree of known operators' using errcode = '22023', hint = 'BANK_RULE_INVALID';
    end if;
    for v_child in select e.value from jsonb_array_elements(node -> 'rules') e loop
      v_result := "better_supabase"."bank_rule_condition"(v_child, payload);
      v_any := v_any or v_result;
      v_all := v_all and v_result;
    end loop;
    return case when coalesce(node ->> 'combinator', 'and') = 'or' then v_any else v_all end;
  end if;
  if node ->> 'type' is distinct from 'rule' or jsonb_typeof(node -> 'path') is distinct from 'array' then
    raise exception 'conditions must be a filter tree of known operators' using errcode = '22023', hint = 'BANK_RULE_INVALID';
  end if;
  v_op := coalesce(node ->> 'operator', '');
  v_value := node -> 'value';
  v_at := coalesce(payload, '{}'::jsonb) #> array(select jsonb_array_elements_text(node -> 'path'));
  v_text := v_at #>> '{}';
  v_other := v_value #>> '{}';
  v_numeric := jsonb_typeof(v_value) = 'number' and v_text ~ '^-?[0-9]+(\.[0-9]+)?$';
  v_empty := v_at is null or v_at = 'null'::jsonb or v_text = '' or v_at = '[]'::jsonb;
  v_result := case
    when v_op = '' then true
    when v_op = 'empty' then v_empty
    when v_op = 'not_empty' then not v_empty
    when v_op in ('is', 'eq') then case when v_numeric then v_text::numeric = v_other::numeric else v_text = v_other end
    when v_op in ('is_not', 'neq') then not coalesce(case when v_numeric then v_text::numeric = v_other::numeric else v_text = v_other end, false)
    when v_op in ('gt', 'is_after') then case when v_numeric then v_text::numeric > v_other::numeric else v_text > v_other end
    when v_op in ('gte', 'is_on_or_after') then case when v_numeric then v_text::numeric >= v_other::numeric else v_text >= v_other end
    when v_op in ('lt', 'is_before') then case when v_numeric then v_text::numeric < v_other::numeric else v_text < v_other end
    when v_op in ('lte', 'is_on_or_before') then case when v_numeric then v_text::numeric <= v_other::numeric else v_text <= v_other end
    when v_op in ('between', 'not_between') then
      jsonb_typeof(v_value) = 'array' and (
        case when jsonb_typeof(v_value -> 0) = 'number' and v_text ~ '^-?[0-9]+(\.[0-9]+)?$'
          then v_text::numeric between (v_value ->> 0)::numeric and (v_value ->> 1)::numeric
          else v_text between v_value ->> 0 and v_value ->> 1 end
      ) = (v_op = 'between')
    when v_op in ('is_any_of', 'is_none_of') then
      jsonb_typeof(v_value) = 'array'
        and exists (select 1 from jsonb_array_elements_text(v_value) e where e = v_text) = (v_op = 'is_any_of')
    when v_op in ('contains', 'not_contains') then
      (case when jsonb_typeof(v_at) = 'array' then v_at @> jsonb_build_array(v_value)
        else strpos(lower(v_text), lower(v_other)) > 0 end) = (v_op = 'contains')
    when v_op = 'starts_with' then left(lower(v_text), length(v_other)) = lower(v_other)
    when v_op = 'ends_with' then right(lower(v_text), length(v_other)) = lower(v_other)
    when v_op in ('has_any_of', 'has_none_of') then
      jsonb_typeof(v_at) = 'array' and jsonb_typeof(v_value) = 'array'
        and exists (select 1 from jsonb_array_elements(v_value) e where v_at @> jsonb_build_array(e.value)) = (v_op = 'has_any_of')
    when v_op = 'has_all_of' then
      jsonb_typeof(v_at) = 'array' and jsonb_typeof(v_value) = 'array' and v_at @> v_value
  end;
  if v_op not in ('', 'empty', 'not_empty', 'is', 'eq', 'is_not', 'neq', 'gt', 'is_after', 'gte', 'is_on_or_after', 'lt', 'is_before',
    'lte', 'is_on_or_before', 'between', 'not_between', 'is_any_of', 'is_none_of', 'contains', 'not_contains', 'starts_with',
    'ends_with', 'has_any_of', 'has_none_of', 'has_all_of') then
    raise exception 'conditions must be a filter tree of known operators' using errcode = '22023', hint = 'BANK_RULE_INVALID';
  end if;
  v_result := coalesce(v_result, false);
  return case when coalesce((node ->> 'negated')::boolean, false) then not v_result else v_result end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.begin_idempotent (
  scope        text,
  key          text,
  request_hash text,
  ttl          interval DEFAULT '24:00:00'::interval,
  lock         interval DEFAULT '00:01:00'::interval
)
  RETURNS TABLE (
    state       text,
    status_code integer,
    response    jsonb,
    holder      uuid
  )
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  existing "better_supabase"."idempotency_keys";
  token uuid := gen_random_uuid();
begin
  delete from "better_supabase"."idempotency_keys" k
  where k."scope" = begin_idempotent.scope and k."key" = begin_idempotent.key and k."expires_at" < now();

  insert into "better_supabase"."idempotency_keys" ("scope", "key", "request_hash", "status", "lock_expires_at", "expires_at", "holder")
  values (scope, key, request_hash, 'running', now() + lock, now() + ttl, token)
  on conflict ("scope", "key") do nothing;
  if found then
    return query select 'started'::text, null::integer, null::jsonb, token;
    return;
  end if;

  select * into existing from "better_supabase"."idempotency_keys" k
  where k."scope" = begin_idempotent.scope and k."key" = begin_idempotent.key
  for update;
  if existing."request_hash" <> request_hash then
    return query select 'mismatch'::text, null::integer, null::jsonb, null::uuid;
  elsif existing."status" = 'completed' then
    return query select 'replay'::text, existing."status_code", existing."response", null::uuid;
  elsif existing."lock_expires_at" < now() then
    -- The holder's lock ran out: this request takes the key over, and the
    -- former holder's complete and release now return false.
    update "better_supabase"."idempotency_keys" k set "lock_expires_at" = now() + lock, "holder" = token
    where k."scope" = begin_idempotent.scope and k."key" = begin_idempotent.key;
    return query select 'started'::text, null::integer, null::jsonb, token;
  else
    return query select 'running'::text, null::integer, null::jsonb, null::uuid;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.begin_import_session (
  run uuid
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_status text;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role can begin an import session' using errcode = '42501', hint = 'IMPORT_FORBIDDEN';
  end if;
  select r."status"::text into v_status from "better_supabase"."import_runs" r where r."id" = begin_import_session.run;
  if not found then
    raise exception 'import not found' using errcode = 'P0002', hint = 'IMPORT_NOT_FOUND';
  end if;
  if v_status <> 'running' then
    raise exception 'the import is not running' using errcode = '55000', hint = 'IMPORT_RUN_NOT_RUNNING';
  end if;
  perform set_config('better_supabase.import_run', begin_import_session.run::text, true);
  perform set_config('better_supabase.correlation_id', 'import:' || begin_import_session.run::text, true);
  perform set_config('better_supabase.import_events', '{"customer.imported":"tag","customer.synced":"emit"}', true);
  perform set_config('better_supabase.import_audit', 'summary', true);
  return begin_import_session.run;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bill_usage_period (
  tenant       uuid,
  period_start date,
  period_end   date,
  currency     text  DEFAULT 'EUR'::text,
  attrs        jsonb DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_currency text := upper(coalesce(bill_usage_period.currency, 'EUR'));
  v_existing uuid;
  v_lines jsonb;
  v_invoice jsonb;
  v_title text;
begin
  if not coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then
    raise exception 'Only the service role bills usage' using errcode = '42501', hint = 'USAGE_FORBIDDEN';
  end if;
  if bill_usage_period.period_start is null or bill_usage_period.period_end is null or bill_usage_period.period_end <= bill_usage_period.period_start then
    raise exception 'The billing period must end after it starts' using errcode = '22023', hint = 'USAGE_PERIOD_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(bill_usage_period.tenant::text || bill_usage_period.period_start::text || bill_usage_period.period_end::text, 0));
  select b."invoice_id" into v_existing from "better_supabase"."usage_billed_periods" b
  where b."tenant_id" = bill_usage_period.tenant
    and b."period_start" = bill_usage_period.period_start
    and b."period_end" = bill_usage_period.period_end;
  if found then
    return jsonb_build_object('invoice_id', v_existing, 'created', false, 'lines', 0);
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'description', coalesce(p."label", u.meter) || ' ' || bill_usage_period.period_start::text || ' to ' || bill_usage_period.period_end::text,
      'quantity', round(u.total - p."included", 4),
      'unitAmount', p."unit_amount"
    ) order by u.meter), '[]'::jsonb)
  into v_lines
  from (
    select h."meter" as meter, sum(h."quantity") as total
    from "better_supabase"."usage_history" h
    where h."tenant_id" = bill_usage_period.tenant
      and h."recorded_at" >= (bill_usage_period.period_start::timestamp at time zone 'UTC')
      and h."recorded_at" < (bill_usage_period.period_end::timestamp at time zone 'UTC')
    group by h."meter"
  ) u
  join "better_supabase"."usage_meter_prices" p on p."meter" = u.meter and p."currency" = v_currency
  where round(u.total - p."included", 4) > 0;
  if jsonb_array_length(v_lines) = 0 then
    return jsonb_build_object('invoice_id', null, 'created', false, 'lines', 0);
  end if;
  v_title := 'Usage ' || bill_usage_period.period_start::text || ' to ' || bill_usage_period.period_end::text;
  v_invoice := "better_supabase"."create_invoice"(
    bill_usage_period.tenant,
    coalesce(bill_usage_period.attrs, '{}'::jsonb) || jsonb_build_object('title', v_title, 'currency', v_currency),
    v_lines
  );
  insert into "better_supabase"."usage_billed_periods" ("tenant_id", "period_start", "period_end", "invoice_id")
  values (bill_usage_period.tenant, bill_usage_period.period_start, bill_usage_period.period_end, (v_invoice ->> 'id')::uuid);
  return jsonb_build_object('invoice_id', (v_invoice ->> 'id')::uuid, 'created', true, 'lines', jsonb_array_length(v_lines));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.billable_time_guard()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not exists (select 1 from "better_supabase"."time_invoice_entries" d where d."entry_id" = old."id") then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;
  -- restrict_violation, so an organization purge retries the table later.
  if tg_op = 'DELETE' then
    raise exception 'this entry is on an invoice; void the invoice to delete it' using errcode = '23001', hint = 'TIME_ENTRY_INVOICED';
  end if;
  if old."started_at" is distinct from new."started_at" or old."ended_at" is distinct from new."ended_at" or old."billable" is distinct from new."billable" or old."rate" is distinct from new."rate" or old."rate_currency" is distinct from new."rate_currency" then
    raise exception 'this entry is on an invoice; void the invoice to change it' using errcode = '55000', hint = 'TIME_ENTRY_INVOICED';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.billable_time_release()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  delete from "better_supabase"."time_invoice_entries" d where d."invoice_id" = new."id";
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.billable_time_subject_merge (
  subject_table text,
  keep          text,
  drop          text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_type text;
  v_keep text := keep;
  v_drop text := drop;
begin
  for v_type in select unnest(case subject_table when 'better_supabase.messages' then array['message'] when 'better_supabase.conversations' then array['conversation'] when 'better_supabase.channels' then array['channel'] when 'better_supabase.companies' then array['company'] when 'better_supabase.people' then array['person'] when 'better_supabase.deals' then array['deal'] when 'better_supabase.courses' then array['course'] when 'better_supabase.posts' then array['post'] when 'better_supabase.activities' then array['activity'] when 'better_supabase.quotes' then array['quote'] when 'better_supabase.work_items' then array['work_item'] when 'better_supabase.employees' then array['employee'] when 'better_supabase.ledger_accounts' then array['ledger_account'] when 'better_supabase.invoices' then array['invoice'] when 'better_supabase.products' then array['product'] when 'better_supabase.product_variants' then array['product_variant'] when 'better_supabase.rfqs' then array['rfq'] when 'better_supabase.tills' then array['till'] when 'better_supabase.orders' then array['order'] when 'better_supabase.calendar_events' then array['calendar_event'] when 'better_supabase.bookings' then array['booking'] when 'better_supabase.assets' then array['asset'] when 'better_supabase.asset_locations' then array['asset_location'] when 'better_supabase.leases' then array['lease'] when 'better_supabase.expense_reports' then array['expense_report'] when 'better_supabase.expense_lines' then array['expense_line'] when 'better_supabase.donation_funds' then array['donation_fund'] when 'better_supabase.warranty_claims' then array['warranty_claim'] when 'better_supabase.work_orders' then array['work_order'] when 'better_supabase.shipments' then array['shipment'] when 'better_supabase.contracts' then array['contract'] when 'better_supabase.controls' then array['control'] when 'better_supabase.compliance_policies' then array['compliance_policy'] when 'better_supabase.qualification_types' then array['qualification_type'] when 'better_supabase.risks' then array['risk'] when 'better_supabase.cases' then array['case'] when 'better_supabase.inspections' then array['inspection'] when 'better_supabase.inspection_programs' then array['inspection_program'] when 'better_supabase.inspection_findings' then array['inspection_finding'] when 'better_supabase.forms' then array['form'] when 'better_supabase.meetings' then array['meeting'] when 'better_supabase.meeting_decisions' then array['meeting_decision'] when 'better_supabase.maintenance_plans' then array['maintenance_plan'] when 'better_supabase.dam_usage_rights' then array['dam_usage_right'] when 'better_supabase.lims_samples' then array['lims_sample'] when 'better_supabase.tax_codes' then array['tax_code'] when 'better_supabase.production_orders' then array['production_order'] when 'better_supabase.work_centers' then array['work_center'] when 'better_supabase.bank_accounts' then array['bank_account'] when 'better_supabase.care_plans' then array['care_plan'] when 'better_supabase.incidents' then array['incident'] when 'better_supabase.content_entries' then array['content_entry'] when 'better_supabase.documents' then array['document'] when 'public.customers' then array['customer'] when 'better_supabase.drive_nodes' then array['drive_node'] when 'public.organizations' then array['organization'] when 'better_supabase.applications' then array['application'] when 'public.change_requests' then array['change_request'] when 'public.projects' then array['project'] when 'public.tasks' then array['task'] else '{}'::text[] end) loop
    delete from "better_supabase"."time_rates" x where x."subject_type" = v_type and x."subject_id" = v_drop and exists (select 1 from "better_supabase"."time_rates" y where y."subject_type" = v_type and y."subject_id" = v_keep and y."tenant_id" is not distinct from x."tenant_id" and y."user_id" is not distinct from x."user_id" and y."effective_from" is not distinct from x."effective_from");
    update "better_supabase"."time_rates" x set "subject_id" = v_keep where x."subject_type" = v_type and x."subject_id" = v_drop;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bom_reaches (
  variant uuid,
  target  uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  with recursive walk(variant, depth) as (
    select bom_reaches.variant, 0
    union
    select y."variant_id", walk.depth + 1
    from walk
    join "better_supabase"."boms" x on x."variant_id" = walk.variant and x."status" = 'active'
    join "better_supabase"."bom_components" y on y."bom_id" = x."id"
    where walk.depth < 20
  )
  select exists (select 1 from walk where walk.variant = bom_reaches.target and walk.depth > 0);
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bom_where_used (
  variant_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (select cv."tenant_id" from "better_supabase"."product_variants" cv where cv."id" = bom_where_used.variant_id);
begin
  if v_tenant is null or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_tenant is not null and coalesce(better_supabase.can('tenant', v_tenant, 'manufacturing.read'), false))) then
    raise exception 'no such bill of materials' using errcode = 'P0002', hint = 'BOM_NOT_FOUND';
  end if;
  return coalesce((with recursive used(bom, variant, version, status, quantity, level, path) as (
    select x."id", x."variant_id", x."version", x."status", y."quantity", 1, array[y."variant_id", x."variant_id"]
    from "better_supabase"."bom_components" y join "better_supabase"."boms" x on x."id" = y."bom_id"
    where y."variant_id" = bom_where_used.variant_id and x."status" <> 'archived'
    union all
    select x."id", x."variant_id", x."version", x."status", y."quantity", used.level + 1, used.path || x."variant_id"
    from used
    join "better_supabase"."bom_components" y on y."variant_id" = used.variant
    join "better_supabase"."boms" x on x."id" = y."bom_id" and x."status" = 'active'
    where used.status = 'active' and used.level < 20 and not (x."variant_id" = any (used.path))
  )
  select jsonb_agg(jsonb_build_object('level', u.level, 'bomId', u.bom, 'variantId', u.variant, 'version', u.version,
    'status', u.status, 'quantity', u.quantity::text) order by u.level, u.variant, u.version desc) from used u), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.book_series (
  service        uuid,
  resource       uuid,
  starts_at      timestamp with time zone,
  rule           jsonb,
  customer       jsonb,
  skip_conflicts boolean                  DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_customer jsonb := coalesce(book_series.customer, '{}'::jsonb);
  v_user uuid := auth.uid();
  v_tenant uuid;
  v_tz text;
  v_series "better_supabase"."booking_series"%rowtype;
  v_at timestamptz;
  v_booking jsonb;
  v_booked jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select "tenant_id" into v_tenant from "better_supabase"."booking_services" where "id" = book_series.service and "active";
  if not found then
    raise exception 'service not found' using errcode = 'P0002', hint = 'BOOKING_SERVICE_NOT_FOUND';
  end if;
  if (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'bookings.manage'), false)) then
    v_user := coalesce(nullif(v_customer ->> 'userId', '')::uuid, v_user);
  elsif not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'bookings.create'), false)) then
    raise exception 'not allowed to book' using errcode = '42501', hint = 'BOOKING_FORBIDDEN';
  else
    v_customer := v_customer || jsonb_build_object('email', coalesce(v_customer ->> 'email', auth.email()));
  end if;
  select "tz" into v_tz from "better_supabase"."booking_resources" where "id" = book_series.resource and "tenant_id" = v_tenant and "active";
  if not found then
    raise exception 'resource not found' using errcode = 'P0002', hint = 'BOOKING_RESOURCE_NOT_FOUND';
  end if;
  v_tz := coalesce(nullif(book_series.rule ->> 'tz', ''), v_tz);
  insert into "better_supabase"."booking_series" ("tenant_id", "service_id", "resource_id", "rule", "starts_at", "tz", "customer_name", "customer_email", "customer_id", "created_by")
  values (v_tenant, book_series.service, book_series.resource, book_series.rule - 'tz', book_series.starts_at, v_tz, v_customer ->> 'name', lower(v_customer ->> 'email'), v_user, auth.uid())
  returning * into v_series;
  for v_at in select t from "better_supabase"."booking_series_starts"(book_series.rule, book_series.starts_at, v_tz) t loop
    begin
      v_booking := "better_supabase"."place_booking"(book_series.service, book_series.resource, v_at, v_customer, true, v_user);
      update "better_supabase"."bookings" set "series_id" = v_series."id" where "id" = (v_booking ->> 'id')::uuid;
      v_booked := v_booked || jsonb_build_array((v_booking - 'accessToken') || jsonb_build_object('seriesId', v_series."id"));
    exception when sqlstate '23P01' then
      if not coalesce(book_series.skip_conflicts, false) then
        raise exception 'an occurrence is not an open slot' using errcode = '23P01', hint = 'BOOKING_SERIES_CONFLICT';
      end if;
      v_skipped := v_skipped || jsonb_build_array(v_at);
    end;
  end loop;
  if jsonb_array_length(v_booked) = 0 then
    raise exception 'no occurrence is an open slot' using errcode = '23P01', hint = 'BOOKING_SERIES_CONFLICT';
  end if;
  update "better_supabase"."booking_series" set "ends_at" = ((v_booked -> -1) ->> 'endsAt')::timestamptz where "id" = v_series."id"
  returning * into v_series;
  return jsonb_build_object('series', jsonb_build_object('id', v_series."id", 'organizationId', v_series."tenant_id"::text, 'serviceId', v_series."service_id", 'resourceId', v_series."resource_id", 'rule', v_series."rule", 'startsAt', v_series."starts_at", 'tz', v_series."tz", 'customerName', v_series."customer_name", 'customerEmail', v_series."customer_email", 'customerUserId', v_series."customer_id", 'status', v_series."status", 'endsAt', v_series."ends_at", 'createdAt', v_series."created_at"), 'bookings', v_booked, 'skipped', v_skipped);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.book_with_credit (
  pass_id   uuid,
  service   uuid,
  resource  uuid,
  starts_at timestamp with time zone,
  customer  jsonb                    DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_pass "better_supabase"."passes"%rowtype;
  v_tenant uuid;
  v_booking jsonb;
  v_entry uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_pass from "better_supabase"."passes" x where x."id" = book_with_credit.pass_id for update;
  if not found or not (coalesce(v_pass."holder_id" = auth.uid(), false) or (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_pass."tenant_id", 'passes.manage'), false))) then
    raise exception 'pass not found' using errcode = 'P0002', hint = 'PASS_NOT_FOUND';
  end if;
  if v_pass."status" <> 'active' then
    raise exception 'the pass is revoked' using errcode = '55000', hint = 'PASS_REVOKED';
  end if;
  if v_pass."uses_allowed" is null or v_pass."booking_id" is not null then
    raise exception 'only a pass with a number of uses and no booking of its own pays for bookings' using errcode = '22023', hint = 'PASS_NOT_CREDITS';
  end if;
  if v_pass."resource_id" is not null and v_pass."resource_id" <> book_with_credit.resource then
    raise exception 'the pass is for another resource' using errcode = '22023', hint = 'PASS_WRONG_RESOURCE';
  end if;
  if book_with_credit.starts_at < v_pass."starts_at" or (v_pass."expires_at" is not null and book_with_credit.starts_at >= v_pass."expires_at") then
    raise exception 'the pass is not valid when the class starts' using errcode = '22023', hint = 'PASS_NOT_VALID';
  end if;
  if v_pass."uses" >= v_pass."uses_allowed" then
    raise exception 'the pass has no credits left' using errcode = '55000', hint = 'PASS_CREDITS_USED_UP';
  end if;
  select sv."tenant_id" into v_tenant from "better_supabase"."booking_services" sv where sv."id" = book_with_credit.service;
  if v_tenant is distinct from v_pass."tenant_id" then
    raise exception 'the service does not exist in the pass''s organization' using errcode = 'P0002', hint = 'PASS_BOOKING_NOT_FOUND';
  end if;
  v_booking := "better_supabase"."hold_booking"(book_with_credit.service, book_with_credit.resource, book_with_credit.starts_at,
    coalesce(book_with_credit.customer, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object('userId', v_pass."holder_id", 'name', v_pass."holder_name", 'email', v_pass."holder_email")), true);
  v_entry := "better_supabase"."ledger_post"(v_pass."tenant_id", 'pass.credit_used',
      jsonb_build_array(
        jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_pass."tenant_id", 'pass_credits', 'pass:' || v_pass."id"::text, 'Pass credits', 'credit', 0::smallint,
    'passes', v_pass."id"::text, v_pass."holder_id", true, 'passes.read', 'passes', jsonb_build_object('passId', v_pass."id")), 'amount', -1),
        jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_pass."tenant_id", 'pass_credits_pool', 'pass-credits:pool', 'Pass credits pool', 'credit', 0::smallint,
    null, null, null, true, 'passes.read', 'passes', null), 'amount', 1)),
      'bookings', (v_booking ->> 'id')::uuid::text, null, 'pass-credit:' || (v_booking ->> 'id')::uuid::text || ':booking', clock_timestamp(),
      jsonb_build_object('passId', v_pass."id", 'reason', 'booking'));
  update "better_supabase"."passes" x set "uses" = x."uses" + 1, "updated_at" = now()
  where x."id" = v_pass."id";
  perform "better_supabase".emit_event('pass.credit_used', jsonb_build_object('organizationId', v_pass."tenant_id"::text, 'id', v_pass."id", 'entryId', v_entry, 'bookingId', (v_booking ->> 'id')::uuid), 'passes/' || v_pass."id"::text, (v_pass."tenant_id")::text, null, 'better-supabase/passes');
  perform better_supabase.audit_event(
    event_type => 'pass.credit_used',
    category => 'access',
    target_type => 'pass',
    record_id => v_pass."id"::text,
    summary => 'booked with a credit of pass',
    tenant => (v_pass."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_pass."tenant_id"::text, 'id', v_pass."id", 'entryId', v_entry, 'bookingId', (v_booking ->> 'id')::uuid)
  );
  return (v_booking - 'accessToken') || jsonb_build_object('passId', v_pass."id", 'creditsLeft', v_pass."uses_allowed" - v_pass."uses" - 1);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.booking_series_starts (
  rule        jsonb,
  first_start timestamp with time zone,
  tz          text
)
  RETURNS SETOF timestamp WITH time zone
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_freq text := booking_series_starts.rule ->> 'freq';
  v_interval integer;
  v_days integer[];
  v_count integer;
  v_until timestamptz;
  v_local timestamp;
  v_week0 date;
  v_date date;
  v_at timestamptz;
  v_n integer := 0;
begin
  if jsonb_typeof(booking_series_starts.rule) is distinct from 'object' or v_freq is null or v_freq not in ('daily', 'weekly') then
    raise exception 'rule.freq is daily or weekly' using errcode = '22023', hint = 'BOOKING_RULE_INVALID';
  end if;
  if not exists (select 1 from pg_catalog.pg_timezone_names z where z.name = booking_series_starts.tz) then
    raise exception 'tz must be an IANA time zone' using errcode = '22023', hint = 'BOOKING_TZ_INVALID';
  end if;
  begin
    v_interval := coalesce((booking_series_starts.rule ->> 'interval')::integer, 1);
    v_count := (booking_series_starts.rule ->> 'count')::integer;
    v_until := (booking_series_starts.rule ->> 'until')::timestamptz;
    v_days := array(select jsonb_array_elements_text(coalesce(booking_series_starts.rule -> 'weekdays', '[]'::jsonb))::integer);
  exception when others then
    raise exception 'rule.interval and rule.count are integers, rule.until a timestamp and rule.weekdays a list of 1 to 7' using errcode = '22023', hint = 'BOOKING_RULE_INVALID';
  end;
  if v_interval not between 1 and 52 then
    raise exception 'rule.interval is between 1 and 52' using errcode = '22023', hint = 'BOOKING_RULE_INVALID';
  end if;
  if v_count is null and v_until is null then
    raise exception 'a rule needs count or until' using errcode = '22023', hint = 'BOOKING_RULE_INVALID';
  end if;
  if v_count is not null and v_count not between 1 and 366 then
    raise exception 'rule.count is between 1 and 366' using errcode = '22023', hint = 'BOOKING_RULE_INVALID';
  end if;
  if v_until is not null and v_until < booking_series_starts.first_start then
    raise exception 'rule.until is before the first occurrence' using errcode = '22023', hint = 'BOOKING_RULE_INVALID';
  end if;
  if exists (select 1 from unnest(v_days) d where d not between 1 and 7) then
    raise exception 'rule.weekdays are 1 (Monday) to 7 (Sunday)' using errcode = '22023', hint = 'BOOKING_RULE_INVALID';
  end if;
  v_local := booking_series_starts.first_start at time zone booking_series_starts.tz;
  if cardinality(v_days) = 0 then
    v_days := array[extract(isodow from v_local)::integer];
  end if;
  v_week0 := v_local::date - (extract(isodow from v_local)::integer - 1);
  for v_offset in 0..730 loop
    v_date := v_local::date + v_offset;
    if (v_freq = 'daily' and v_offset % v_interval = 0)
      or (v_freq = 'weekly' and extract(isodow from v_date)::integer = any (v_days) and ((v_date - v_week0) / 7) % v_interval = 0) then
      v_at := (v_date + v_local::time) at time zone booking_series_starts.tz;
      exit when v_until is not null and v_at > v_until;
      return next v_at;
      v_n := v_n + 1;
      exit when v_n >= coalesce(v_count, 366);
    end if;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.booking_slots (
  service       uuid,
  range_start   timestamp with time zone,
  range_end     timestamp with time zone,
  tz            text,
  only_resource uuid
)
  RETURNS TABLE (
    resource_id uuid,
    starts_at   timestamp with time zone,
    ends_at     timestamp with time zone,
    local_start timestamp without time zone,
    seats       integer
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_service record;
  v_resource record;
  v_open tstzmultirange;
  v_window tstzrange;
  v_floor timestamptz;
  v_step interval;
  v_at timestamptz;
  v_block tstzrange;
  v_free integer;
  v_busy tstzmultirange := '{}'::tstzmultirange;
begin
  select sv."tenant_id" as tenant, sv."duration" as duration, sv."buffer_before" as before, sv."buffer_after" as after,
      sv."resource_kinds" as kinds, sv."step" as step, sv."min_notice" as notice
    into v_service
    from "better_supabase"."booking_services" sv where sv."id" = booking_slots.service and sv."active";
  if not found or booking_slots.range_end is null or booking_slots.range_start is null then
    return;
  end if;
  v_step := coalesce(v_service.step, v_service.duration);
  v_floor := greatest(booking_slots.range_start, now() + v_service.notice);
  for v_resource in
    select rs."id" as id, rs."tz" as tz, rs."capacity" as capacity, case when rs."check_busy" then rs."host_id" end as host
    from "better_supabase"."booking_resources" rs
    where rs."tenant_id" = v_service.tenant and rs."active"
      and (cardinality(v_service.kinds) = 0 or rs."kind" = any (v_service.kinds))
      and (booking_slots.only_resource is null or rs."id" = booking_slots.only_resource)
    order by rs."name", rs."id"
  loop
    select coalesce(range_agg(tstzrange((d.day + a."starts_at") at time zone v_resource.tz, (d.day + a."ends_at") at time zone v_resource.tz)), '{}'::tstzmultirange)
      into v_open
      from (
        select g::date as day
        from generate_series((v_floor at time zone v_resource.tz)::date - 1, (booking_slots.range_end at time zone v_resource.tz)::date, interval '1 day') g
      ) d
      join "better_supabase"."booking_availability" a on a."resource_id" = v_resource.id and a."weekday" = extract(isodow from d.day)::integer;
    v_open := v_open + coalesce((select range_agg(e."during") from "better_supabase"."booking_exceptions" e where e."resource_id" = v_resource.id and e."available"), '{}'::tstzmultirange);
    v_open := v_open - coalesce((select range_agg(e."during") from "better_supabase"."booking_exceptions" e where e."resource_id" = v_resource.id and not e."available"), '{}'::tstzmultirange);
    v_busy := '{}'::tstzmultirange;
    if v_resource.host is not null then
      select coalesce(range_agg(tstzrange(bb.starts_at, bb.ends_at)), '{}'::tstzmultirange) into v_busy
      from "better_supabase"."calendar_busy_blocks"(v_service.tenant, array[v_resource.host], v_floor - v_service.before, booking_slots.range_end + v_service.after) bb
      where bb.starts_at < bb.ends_at and not exists (select 1 from "better_supabase"."bookings" bk where bk."calendar_event_id" = bb.event_id and bk."resource_id" = v_resource.id);
    end if;
    for v_window in select w from unnest(v_open) w loop
      v_at := lower(v_window);
      if v_at < v_floor then
        v_at := v_at + ceil(extract(epoch from (v_floor - v_at)) / extract(epoch from v_step)) * v_step;
      end if;
      while v_at + v_service.duration <= upper(v_window) and v_at + v_service.duration <= booking_slots.range_end loop
        v_block := tstzrange(v_at - v_service.before, v_at + v_service.duration + v_service.after);
        select count(*)::integer into v_free
        from generate_series(1, v_resource.capacity) seat
        where not exists (
          select 1 from "better_supabase"."bookings" bk
          where bk."resource_id" = v_resource.id and bk."seat" = seat.seat
            and (bk."status" = 'confirmed' or (bk."status" = 'hold' and bk."hold_expires_at" > now())) and bk."blocked" && v_block
        );
        if v_free > 0 and not (v_busy && v_block) then
          resource_id := v_resource.id;
          starts_at := v_at;
          ends_at := v_at + v_service.duration;
          local_start := v_at at time zone coalesce(booking_slots.tz, v_resource.tz);
          seats := v_free;
          return next;
        end if;
        v_at := v_at + v_step;
      end loop;
    end loop;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bootstrap_islands (
  args jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if not (select better_supabase.session_active()) then
    return jsonb_build_object(
      'session_active', false,
      'end_reason', better_supabase.session_end_reason(),
      'authz_version', auth.jwt() -> 'authz_ver',
      'token_authz_version', auth.jwt() -> 'authz_ver',
      'tenant', args ->> 'tenant',
      'data', null
    );
  end if;
  return jsonb_build_object(
    'session_active', true,
    'authz_version', to_jsonb(better_supabase.caller_authz_version()),
    'token_authz_version', auth.jwt() -> 'authz_ver',
    'tenant', args ->> 'tenant',
    'data', to_jsonb(public.island_counts(args))
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bootstrap_permissions()
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  with keys as (
    select coalesce(array_agg(distinct key order by key), '{}'::text[]) as keys
    from better_supabase.member_organization_ids(null) as tenant(id),
      lateral unnest(better_supabase.member_permissions(auth.uid(), tenant.id)) as key
    where auth.uid() is not null
  )
  select case
    when auth.uid() is null then jsonb_build_object(
      'apiVersion', 1, 'form', 'compact', 'keys', '[]'::jsonb, 'tenants', '{}'::jsonb
    )
    else jsonb_build_object(
      'apiVersion', 1,
      'form', 'compact',
      'keys', to_jsonb(keys.keys),
      'tenants', coalesce((
        select jsonb_object_agg(
          tenant.id::text,
          better_supabase.permission_bitset(
            keys.keys,
            better_supabase.member_permissions(auth.uid(), tenant.id)
          )
        )
        from better_supabase.member_organization_ids(null) as tenant(id)
      ), '{}'::jsonb)
    )
  end
  from keys
$function$;

CREATE OR REPLACE FUNCTION better_supabase.broadcast_announcement()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if to_regprocedure('realtime.send(jsonb, text, text, boolean)') is not null then
    perform realtime.send(
      jsonb_build_object('id', coalesce(new."id", old."id"), 'operation', lower(tg_op)),
      'announcement_changed',
      'announcements',
      true
    );
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.broadcast_authz_version()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if to_regprocedure('realtime.send(jsonb, text, text, boolean)') is not null then
    perform realtime.send(jsonb_build_object('user_id', new.user_id, 'version', new.version), 'changed', 'better_supabase:authz', true);
  end if;
  if to_regprocedure('realtime.send(jsonb, text, text, boolean)') is not null then
    perform realtime.send(jsonb_build_object('user_id', new.user_id, 'version', new.version), 'changed', 'authz:' || new.user_id::text, true);
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.broadcast_changes()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  base text := 'bsb:t:' || tg_table_schema || '.' || tg_table_name
    || case when tg_nargs > 1 and tg_argv[1] = 'user' then ':u' else '' end;
  payload jsonb := jsonb_build_object('schema', tg_table_schema, 'table', tg_table_name, 'operation', tg_op);
  source text;
  tenant text;
begin
  if tg_nargs = 0 or tg_argv[0] = '' then
    perform realtime.send(payload, 'change', base, true);
    return null;
  end if;
  source := case tg_op
    when 'INSERT' then format('select %1$I from new_rows', tg_argv[0])
    when 'DELETE' then format('select %1$I from old_rows', tg_argv[0])
    else format('select %1$I from new_rows union select %1$I from old_rows', tg_argv[0])
  end;
  for tenant in execute format('select distinct t.v::text from (%s) as t(v) where t.v is not null', source) loop
    perform realtime.send(payload, 'change', base || ':' || tenant, true);
  end loop;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.broadcast_notification()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  perform realtime.send(
    jsonb_build_object('id', new."id", 'event_id', new."event_id", 'operation', lower(tg_op), 'tenant', new."tenant_id"),
    case when tg_op = 'INSERT' then 'notification_created' else 'notification_updated' end,
    'notifications:' || new."user_id"::text,
    true
  );
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.broadcast_topic()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  topic text;
  event text := tg_op;
  private boolean := true;
  mode text := 'keys';
  cache_key text := 'bsb_topic.r' || tg_relid::text || '_' || md5(tg_name);
  stamp text := statement_timestamp()::text;
  plan jsonb;
  placeholder text;
  param text;
  col text;
  placeholders text[] := '{}';
  params text[] := '{}';
  cols text[] := '{}';
  keys text[];
  id_sql text;
  vals text[];
  value text;
  payload_vals jsonb := '{}';
  id jsonb;
begin
  if tg_level <> 'ROW' then
    raise exception 'better_supabase.broadcast_topic() runs for each row'
      using errcode = '39P01';
  end if;
  if tg_when <> 'AFTER' then
    raise exception 'better_supabase.broadcast_topic() runs after the write; as a % trigger it would cancel the write', lower(tg_when)
      using errcode = '39P01';
  end if;
  if tg_nargs = 0 or tg_argv[0] = '' then
    raise exception 'better_supabase.broadcast_topic() needs the topic as its first argument'
      using errcode = '39P01';
  end if;
  topic := tg_argv[0];
  if tg_nargs > 1 and tg_argv[1] <> '' then event := tg_argv[1]; end if;
  if tg_nargs > 2 and tg_argv[2] <> '' then private := tg_argv[2]::boolean; end if;
  if tg_nargs > 3 and tg_argv[3] <> '' then mode := tg_argv[3]; end if;
  if mode not in ('keys', 'row') then
    raise exception 'better_supabase.broadcast_topic() payload must be keys or row, not %', mode
      using errcode = '22023';
  end if;
  plan := nullif(current_setting(cache_key, true), '')::jsonb;
  if plan is null or plan ->> 'stamp' is distinct from stamp then
    for placeholder in select distinct m[1] from regexp_matches(tg_argv[0], '\{([^}]+)\}', 'g') as m loop
      param := split_part(placeholder, '=', 1);
      col := coalesce(nullif(split_part(placeholder, '=', 2), ''), param);
      if not exists (
        select 1 from pg_catalog.pg_attribute a
        where a.attrelid = tg_relid and a.attname = col and a.attnum > 0 and not a.attisdropped
      ) then
        raise exception '%.% has no column % for the topic %', tg_table_schema, tg_table_name, col, tg_argv[0]
          using errcode = '42703';
      end if;
      placeholders := placeholders || placeholder;
      params := params || param;
      cols := cols || col;
    end loop;
    select array_agg(a.attname::text order by array_position(i.indkey::int2[], a.attnum))
      into keys
      from pg_catalog.pg_index i
      join pg_catalog.pg_attribute a on a.attrelid = i.indrelid and a.attnum = any(i.indkey::int2[])
      where i.indrelid = tg_relid and i.indisprimary;
    id_sql := case
      when keys is null then 'null::jsonb'
      when cardinality(keys) = 1 then format('to_jsonb(($1).%I)', keys[1])
      else 'jsonb_build_object(' || (select string_agg(format('%L, ($1).%I', k, k), ', ') from unnest(keys) as k) || ')'
    end;
    plan := jsonb_build_object(
      'stamp', stamp,
      'placeholders', to_jsonb(placeholders),
      'params', to_jsonb(params),
      'cols', to_jsonb(cols),
      'sql', format(
        'select array[%s]::text[], %s',
        coalesce((select string_agg(format('($1).%I::text', c), ', ') from unnest(cols) as c), ''),
        id_sql
      )
    );
    perform set_config(cache_key, plan::text, true);
  end if;
  execute plan ->> 'sql' using case when tg_op = 'DELETE' then old else new end into vals, id;
  for i in 1 .. coalesce(cardinality(vals), 0) loop
    value := vals[i];
    if value is null then
      return null;
    end if;
    if value !~ '^[\w.@+=-]+$' then
      raise warning 'skipped the broadcast on %: topic value % of %.%.% contains characters topics do not allow', tg_argv[0], value, tg_table_schema, tg_table_name, plan -> 'cols' ->> (i - 1);
      return null;
    end if;
    payload_vals := payload_vals || jsonb_build_object(plan -> 'params' ->> (i - 1), value);
    topic := replace(topic, '{' || (plan -> 'placeholders' ->> (i - 1)) || '}', value);
  end loop;
  if mode = 'row' then
    perform realtime.send(
      jsonb_build_object('old_record', old, 'record', new, 'operation', tg_op, 'table', tg_table_name, 'schema', tg_table_schema),
      event, topic, private
    );
    return null;
  end if;
  perform realtime.send(
    jsonb_build_object('operation', tg_op, 'schema', tg_table_schema, 'table', tg_table_name, 'id', id, 'values', payload_vals),
    event, topic, private
  );
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bsb_application_guard()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if new."state" is not distinct from old."state" then
    new."updated_at" := now();
    return new;
  end if;
  new."hired_at" := case when new."state" = 'hired' then now() end;
  if new."state" <> 'rejected' then
    new."rejection_reason" := null;
  end if;
  case new."state"
    when 'hired' then perform "better_supabase".emit_event('application.hired', jsonb_build_object('organizationId', new."tenant_id", 'applicationId', new."id", 'subjectType', 'application', 'subjectId', new."id"::text, 'jobId', new."job_id", 'candidateType', new."candidate_type", 'candidateId', new."candidate_id"), 'applications/' || new."id"::text, (new."tenant_id"::text)::text, null, 'better-supabase/hiring');
    when 'rejected' then perform "better_supabase".emit_event('application.rejected', jsonb_build_object('organizationId', new."tenant_id", 'applicationId', new."id", 'subjectType', 'application', 'subjectId', new."id"::text, 'jobId', new."job_id", 'candidateType', new."candidate_type", 'candidateId', new."candidate_id", 'reason', new."rejection_reason"), 'applications/' || new."id"::text, (new."tenant_id"::text)::text, null, 'better-supabase/hiring');
    when 'withdrawn' then perform "better_supabase".emit_event('application.retracted', jsonb_build_object('organizationId', new."tenant_id", 'applicationId', new."id", 'subjectType', 'application', 'subjectId', new."id"::text, 'jobId', new."job_id", 'candidateType', new."candidate_type", 'candidateId', new."candidate_id"), 'applications/' || new."id"::text, (new."tenant_id"::text)::text, null, 'better-supabase/hiring');
    else null;
  end case;
  new."updated_at" := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bsb_booking_activity()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_ref text := 'booking:' || new."id"::text;
  v_tenant uuid := new."tenant_id";
  v_id uuid;
  v_inserted boolean;
  v_title text;
  v_owner uuid := new."created_by";
  v_person uuid;
  v_person_owner uuid;
  v_subjects jsonb;
  v_first jsonb;
begin
  if new."status" = 'confirmed' then
    if tg_op = 'UPDATE' and old."status" = 'confirmed' and old."during" = new."during" then
      return null;
    end if;
    select p."id", p."owner_id" into v_person, v_person_owner
    from "better_supabase"."people" p
    where p."tenant_id" = v_tenant and p."archived_at" is null and p."merged_into" is null
      and ((new."customer_id" is not null and p."user_id" = new."customer_id")
        or (new."customer_email" is not null and lower(p."email") = lower(new."customer_email")))
    order by (new."customer_id" is not null and p."user_id" = new."customer_id") desc, p."created_at"
    limit 1;
    v_owner := coalesce(v_owner, v_person_owner);
    select left(coalesce(sv."name", 'Booking') || coalesce(' with ' || nullif(trim(new."customer_name"), ''), ''), 500)
    into v_title
    from "better_supabase"."booking_services" sv where sv."id" = new."service_id";
    insert into "better_supabase"."activities" ("tenant_id", "type", "title", "body", "owner_id", "due_at", "duration_seconds", "external_ref", "created_by")
    values (v_tenant, 'meeting', coalesce(v_title, 'Booking'), new."notes", v_owner, lower(new."during"), extract(epoch from upper(new."during") - lower(new."during"))::integer, v_ref, new."created_by")
    on conflict ("tenant_id", "external_ref") where "external_ref" is not null do update set
      "due_at" = excluded."due_at", "duration_seconds" = excluded."duration_seconds",
      "done_at" = null, "outcome" = null, "updated_at" = now()
    returning "id", (xmax = 0) into v_id, v_inserted;
    if v_person is not null then
      insert into "better_supabase"."activity_subjects" ("tenant_id", "activity_id", "subject_type", "subject_id", "position")
      values (v_tenant, v_id, 'person', v_person::text, 1)
      on conflict do nothing;
      insert into "better_supabase"."activity_subjects" ("tenant_id", "activity_id", "subject_type", "subject_id", "position")
      select v_tenant, v_id, 'company', c."id"::text, 2
      from "better_supabase"."company_people" k
      join "better_supabase"."companies" c on c."id" = k."company_id"
      where k."person_id" = v_person and c."archived_at" is null
      order by k."is_primary" desc, k."created_at"
      limit 1
      on conflict do nothing;
    end if;
    v_subjects := coalesce((select jsonb_agg(jsonb_build_object('type', sx."subject_type", 'id', sx."subject_id") order by sx."position") from "better_supabase"."activity_subjects" sx where sx."activity_id" = v_id), '[]'::jsonb);
    v_first := v_subjects -> 0;
    if v_inserted then
      perform "better_supabase".emit_event('activity.logged', jsonb_build_object('organizationId', v_tenant, 'activityId', v_id, 'type', 'meeting', 'subjectType', v_first ->> 'type', 'subjectId', v_first ->> 'id', 'subjects', v_subjects), 'activities/' || v_id::text, (v_tenant::text)::text, null, 'better-supabase/activities');
    else
      perform "better_supabase".emit_event('activity.updated', jsonb_build_object('organizationId', v_tenant, 'activityId', v_id, 'type', 'meeting', 'subjectType', v_first ->> 'type', 'subjectId', v_first ->> 'id', 'subjects', v_subjects), 'activities/' || v_id::text, (v_tenant::text)::text, null, 'better-supabase/activities');
    end if;
  elsif new."status" = 'cancelled' and tg_op = 'UPDATE' and old."status" = 'confirmed' then
    update "better_supabase"."activities" x set
      "done_at" = coalesce(new."cancelled_at", now()),
      "outcome" = left('cancelled' || coalesce(': ' || nullif(trim(new."cancel_reason"), ''), ''), 500),
      "updated_at" = now()
    where x."tenant_id" = v_tenant and x."external_ref" = v_ref and x."done_at" is null
    returning x."id" into v_id;
    if v_id is not null then
    v_subjects := coalesce((select jsonb_agg(jsonb_build_object('type', sx."subject_type", 'id', sx."subject_id") order by sx."position") from "better_supabase"."activity_subjects" sx where sx."activity_id" = v_id), '[]'::jsonb);
    v_first := v_subjects -> 0;
      perform "better_supabase".emit_event('activity.completed', jsonb_build_object('organizationId', v_tenant, 'activityId', v_id, 'type', 'meeting', 'subjectType', v_first ->> 'type', 'subjectId', v_first ->> 'id', 'subjects', v_subjects), 'activities/' || v_id::text, (v_tenant::text)::text, null, 'better-supabase/activities');
    end if;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bsb_case_guard()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_outcome text;
  v_blockers text[];
begin
  if new."stage_id" is not distinct from old."stage_id" then
    return new;
  end if;
  v_outcome := (select s."outcome" from "better_supabase"."pipeline_stages" s where s."id" = new."stage_id");
  if v_outcome = 'success' then
    if old."status" <> 'closed' then
      v_blockers := "better_supabase"."case_blockers_of"(new);
      if cardinality(v_blockers) > 0 then
        raise exception 'the case can''t close yet' using errcode = '55000', hint = v_blockers[1], detail = jsonb_build_object('blockers', to_jsonb(v_blockers))::text;
      end if;
      new."status" := 'closed';
      new."closed_at" := now();
      new."closed_by" := auth.uid();
      perform "better_supabase"."version_insert"(new."tenant_id", 'case', new."id"::text,
        jsonb_build_object('id', new."id", 'organizationId', new."tenant_id", 'kindId', new."kind_id", 'number', new."number", 'title', new."title", 'description', new."description", 'severity', new."severity", 'source', new."source", 'reporterId', new."reporter_id", 'reporterContact', new."reporter_contact", 'ownerId', new."owner_id", 'occurredAt', new."occurred_at", 'detectedAt', new."detected_at", 'dueOn', new."due_on", 'pipelineId', new."pipeline_id", 'stageId', new."stage_id", 'stageEnteredAt', new."stage_entered_at", 'status', new."status", 'rootCause', new."root_cause", 'rootCauseSubmissionId', new."root_cause_submission_id", 'effective', new."effective", 'effectivenessDueOn', new."effectiveness_due_on", 'effectivenessNote', new."effectiveness_note", 'effectivenessSubmissionId', new."effectiveness_submission_id", 'closedAt', new."closed_at", 'closedBy', new."closed_by", 'closeNote', new."close_note", 'rank', new."rank", 'archivedAt', new."archived_at", 'createdBy', new."created_by", 'createdAt', new."created_at", 'updatedAt', new."updated_at"), null, 'Closed ' || new."number", 'manual', true, auth.uid());
    end if;
  elsif v_outcome = 'failure' then
    if old."status" <> 'canceled' then
      new."status" := 'canceled';
      new."closed_at" := now();
      new."closed_by" := auth.uid();
    end if;
  elsif old."status" <> 'open' then
    new."status" := 'open';
    new."closed_at" := null;
    new."closed_by" := null;
    new."close_note" := null;
  end if;
  new."updated_at" := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bsb_deal_guard()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_claims text;
begin
  if tg_op = 'INSERT' then
    new."closed_at" := case when new."outcome" <> 'open' then now() end;
    if new."owner_id" is not null then
      insert into "better_supabase"."notification_subscriptions" ("tenant_id", "user_id", "subject_type", "subject_id", "level")
    values (new."tenant_id", new."owner_id", 'deal', new."id"::text, 'participating')
    on conflict do nothing;
    end if;
    return new;
  end if;
  if old."locked" and not (auth.role() = 'service_role') and (
      new."name" is distinct from old."name"
      or new."company_type" is distinct from old."company_type"
      or new."company_id" is distinct from old."company_id"
      or new."motion" is distinct from old."motion"
      or new."priority" is distinct from old."priority"
      or new."owner_id" is distinct from old."owner_id"
      or new."product" is distinct from old."product"
      or new."seats" is distinct from old."seats"
      or new."amount" is distinct from old."amount"
      or new."existing_amount" is distinct from old."existing_amount"
      or new."currency" is distinct from old."currency"
      or new."value_period" is distinct from old."value_period"
      or new."pipeline_id" is distinct from old."pipeline_id"
      or new."stage_id" is distinct from old."stage_id"
      or new."probability" is distinct from old."probability"
      or new."forecast_category" is distinct from old."forecast_category"
      or new."expected_close_on" is distinct from old."expected_close_on"
      or new."next_step" is distinct from old."next_step"
      or new."next_at" is distinct from old."next_at"
      or new."next_kind" is distinct from old."next_kind"
      or new."flags" is distinct from old."flags"
      or new."source" is distinct from old."source"
      or new."lost_reason" is distinct from old."lost_reason"
    ) then
    raise exception 'the deal is locked; only its note can change' using errcode = '55000', hint = 'DEAL_LOCKED';
  end if;
  if new."opened_on" is distinct from old."opened_on" and not (auth.role() = 'service_role') then
    raise exception 'the open date never moves' using errcode = '22023', hint = 'DEAL_OPENED_ON_FIXED';
  end if;
  if new."expected_close_on" > old."expected_close_on" and old."outcome" = 'open' then
    new."slipped_from" := coalesce(old."slipped_from", old."expected_close_on");
    new."push_count" := old."push_count" + 1;
  end if;
  if new."forecast_category" is distinct from old."forecast_category" and new."outcome" <> 'open' and old."outcome" <> 'open' then
    raise exception 'a closed deal is called by its stage, not a forecast' using errcode = '22023', hint = 'DEAL_FORECAST_CLOSED';
  end if;
  if new."outcome" is distinct from old."outcome" then
    new."closed_at" := case when new."outcome" <> 'open' then now() end;
    if new."outcome" = 'open' then
      new."lost_reason" := null;
      perform "better_supabase".emit_event('deal.reopened', jsonb_build_object('organizationId', new."tenant_id", 'dealId', new."id", 'subjectType', 'deal', 'subjectId', new."id"::text, 'name', new."name"), 'deals/' || new."id"::text, (new."tenant_id"::text)::text, null, 'better-supabase/deals');
    else
      perform "better_supabase".emit_event('deal.closed', jsonb_build_object('organizationId', new."tenant_id", 'dealId', new."id", 'subjectType', 'deal', 'subjectId', new."id"::text, 'name', new."name", 'outcome', new."outcome", 'amount', new."amount"::text, 'currency', new."currency", 'reason', new."lost_reason"), 'deals/' || new."id"::text, (new."tenant_id"::text)::text, null, 'better-supabase/deals');
    end if;
    if better_supabase.import_run() is null then
      v_claims := current_setting('request.jwt.claims', true);
      perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
      perform "better_supabase"."notify"(jsonb_build_object(
      'type', 'deal.closed',
      'tenant', new."tenant_id",
      'actor', auth.uid(),
      'subject_type', 'deal',
      'subject_id', new."id"::text,
      'summary', new."name",
      'key', 'deal.outcome:' || new."id"::text || ':' || new."outcome" || ':' || extract(epoch from now())::text,
      'data', jsonb_build_object('dealId', new."id", 'outcome', new."outcome")
    ));
      perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
    end if;
  end if;
  if new."owner_id" is not null and new."owner_id" is distinct from old."owner_id" then
    insert into "better_supabase"."notification_subscriptions" ("tenant_id", "user_id", "subject_type", "subject_id", "level")
    values (new."tenant_id", new."owner_id", 'deal', new."id"::text, 'participating')
    on conflict do nothing;
  end if;
  new."updated_at" := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bsb_deal_lines_totals()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_parent uuid;
begin
  for v_parent in execute case tg_op
    when 'INSERT' then 'select distinct n."parent_id" from new_rows n order by 1'
    when 'DELETE' then 'select distinct o."parent_id" from old_rows o order by 1'
    else 'select parent from (
      select n."parent_id" as parent from new_rows n
      join old_rows o on o."id" = n."id"
      where n."quantity" is distinct from o."quantity"
        or n."unit_amount" is distinct from o."unit_amount"
      union
      select n."parent_id" from new_rows n
      where not exists (select 1 from old_rows o where o."id" = n."id")
      union
      select o."parent_id" from old_rows o
      where not exists (select 1 from new_rows n where n."id" = o."id")
    ) changed order by 1'
  end loop
    perform "better_supabase"."set_deal_lines_recount"(v_parent);
  end loop;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bsb_employee_manager_guard()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if new."manager_id" is null then
    return new;
  end if;
  if not exists (
    select 1 from "better_supabase"."employees" m
    where m."id" = new."manager_id" and m."tenant_id" = new."tenant_id"
  ) then
    raise exception 'the manager is not an employee of this organization' using errcode = '23503', hint = 'EMPLOYEE_MANAGER_NOT_FOUND';
  end if;
  if new."manager_id" = new."id" or exists (
    with recursive up (id) as (
      select m."manager_id" from "better_supabase"."employees" m where m."id" = new."manager_id"
      union
      select m."manager_id" from "better_supabase"."employees" m join up on m."id" = up.id
    )
    select 1 from up where up.id = new."id"
  ) then
    raise exception 'an employee can''t report to one of their own reports' using errcode = '22023', hint = 'EMPLOYEE_MANAGER_CYCLE';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bsb_employee_team_members()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_user uuid;
begin
  if new."user_id" is not null and exists (
    select 1 from "public"."memberships" m
    where m."organization_id" = new."tenant_id"
      and m."user_id" = new."user_id"
  ) then
    v_user := new."user_id";
  end if;
  if tg_op = 'INSERT' or new."user_id" is distinct from old."user_id" then
    if v_user is not null then
      delete from "better_supabase"."team_members" x
      where x."user_id" = v_user and x."employee_id" is null
        and exists (
          select 1 from "better_supabase"."team_members" y
          where y."team_id" = x."team_id" and y."employee_id" = new."id"
        );
      update "better_supabase"."team_members" set "employee_id" = new."id"
      where "tenant_id" = new."tenant_id" and "user_id" = v_user and "employee_id" is null;
    end if;
    update "better_supabase"."team_members" set "user_id" = v_user
    where "employee_id" = new."id" and "user_id" is distinct from v_user;
  end if;
  if new."team_id" is not null and (tg_op = 'INSERT' or new."team_id" is distinct from old."team_id") then
    insert into "better_supabase"."team_members" ("team_id", "user_id", "employee_id", "tenant_id")
    select t."id", v_user, new."id", new."tenant_id"
    from "better_supabase"."teams" t
    where t."id" = new."team_id" and t."tenant_id" = new."tenant_id"
    on conflict do nothing;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.bsb_employee_user_mirror()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
