CREATE OR REPLACE FUNCTION better_supabase.calendar_attendee_auto_decline()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_event record;
begin
  select x."tenant_id" as tenant, x."starts_at" as starts_at, x."ends_at" as ends_at
    into v_event
  from "better_supabase"."calendar_events" x
  where x."id" = new."event_id" and x."rrule" is null and x."kind" = 'event' and x."status" <> 'cancelled';
  if found and exists (
    select 1 from "better_supabase"."calendar_busy_blocks"(v_event.tenant, array[new."user_id"], v_event.starts_at, v_event.ends_at) b
    where b.declines and b.event_id is distinct from new."event_id"
  ) then
    new."response" := 'declined';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.calendar_block_auto_decline()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_owner uuid;
begin
  select case when k."owner_id" ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then k."owner_id"::uuid end
    into v_owner
  from "better_supabase"."calendars" k
  where k."id" = new."calendar_id" and k."owner_type" = 'user';
  if v_owner is null then
    return null;
  end if;
  update "better_supabase"."calendar_attendees" a set "response" = 'declined'
  from "better_supabase"."calendar_events" x
  where a."event_id" = x."id"
    and a."user_id" = v_owner
    and a."response" = 'needs-action'
    and x."tenant_id" = new."tenant_id"
    and x."id" <> new."id"
    and x."rrule" is null
    and x."kind" = 'event'
    and x."status" <> 'cancelled'
    and x."starts_at" < new."ends_at"
    and x."ends_at" > new."starts_at";
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.calendar_busy_blocks (
  tenant      uuid,
  user_ids    uuid[],
  range_start timestamp with time zone,
  range_end   timestamp with time zone
)
  RETURNS TABLE (
    user_id   uuid,
    kind      text,
    starts_at timestamp with time zone,
    ends_at   timestamp with time zone,
    event_id  uuid,
    declines  boolean
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
begin
  return query
  with sources as (
    select m.u as user_id, e."id" as event_id
    from unnest(calendar_busy_blocks.user_ids) m (u)
    join "better_supabase"."calendars" k on k."tenant_id" = calendar_busy_blocks.tenant and k."owner_type" = 'user' and k."owner_id" = m.u::text
    join "better_supabase"."calendar_events" e on e."calendar_id" = k."id"
    union
    select a."user_id" as user_id, e."id" as event_id
    from "better_supabase"."calendar_attendees" a
    join "better_supabase"."calendar_events" e on (e."id" = a."event_id" or e."recurrence_id" = a."event_id")
    where a."tenant_id" = calendar_busy_blocks.tenant
      and a."user_id" = any (calendar_busy_blocks.user_ids)
      and a."response" <> 'declined'
      and not exists (
        select 1 from "better_supabase"."calendar_attendees" d
        where d."event_id" = e."id" and d."user_id" = a."user_id" and d."response" = 'declined'
      )
  ),
  candidates as (
    select distinct s.user_id, e."id" as event_id, e."kind" as kind, e."starts_at" as starts_at, e."ends_at" as ends_at,
      e."tz" as tz, e."rrule" as rrule, e."recurrence_id" as recurrence, e."exdates" as exdates, (e."kind" <> 'event' and e."auto_decline") as declines
    from sources s
    join "better_supabase"."calendar_events" e on e."id" = s.event_id
    where e."tenant_id" = calendar_busy_blocks.tenant
      and e."status" <> 'cancelled'
      and e."transparency" <> 'transparent'
      and e."starts_at" < calendar_busy_blocks.range_end
  )
  select c.user_id, c.kind, c.starts_at, c.ends_at, c.event_id, c.declines
  from candidates c
  where c.rrule is null and c.starts_at < calendar_busy_blocks.range_end and c.ends_at > calendar_busy_blocks.range_start
  union all
  select c.user_id, c.kind, s.at, s.at + (c.ends_at - c.starts_at), c.event_id, c.declines
  from candidates c
  cross join lateral "better_supabase"."calendar_rule_starts"(c.starts_at, c.tz, c.rrule, calendar_busy_blocks.range_start - (c.ends_at - c.starts_at), calendar_busy_blocks.range_end) s (at)
  where c.rrule is not null and c.recurrence is null
    and c.starts_at < calendar_busy_blocks.range_end
    and s.at + (c.ends_at - c.starts_at) > calendar_busy_blocks.range_start
    and not (s.at = any (c.exdates))
    and not exists (
      select 1 from "better_supabase"."calendar_events" o
      where o."recurrence_id" = c.event_id and o."original_starts_at" = s.at
    )
  union all
  select r."user_id", 'out_of_office'::text, t.s, t.en, null::uuid, true
  from "better_supabase"."leave_requests" r
  cross join lateral (select coalesce((select h."tz" from "better_supabase"."calendar_working_hours" h where h."tenant_id" = calendar_busy_blocks.tenant and h."user_id" = r."user_id" limit 1), 'UTC') as tz) z
  cross join lateral (
    select
      (case when (case r."partial" when 'afternoon' then 'afternoon' when 'hours' then 'hours' else 'full' end) = 'afternoon' then r."starts_on" + time '12:00' else r."starts_on"::timestamp end) at time zone z.tz as s,
      (case when (case r."partial" when 'morning' then 'morning' when 'hours' then 'hours' else 'full' end) = 'morning' then r."ends_on" + time '12:00' else (r."ends_on" + 1)::timestamp end) at time zone z.tz as en
  ) t
  where r."tenant_id" = calendar_busy_blocks.tenant
    and r."user_id" = any (calendar_busy_blocks.user_ids)
    and r."approved_at" is not null
    and r."cancelled_at" is null
    and (case r."partial" when 'afternoon' then 'afternoon' when 'hours' then 'hours' else 'full' end) <> 'hours'
    and (case r."partial" when 'morning' then 'morning' when 'hours' then 'hours' else 'full' end) <> 'hours'
    and t.s < calendar_busy_blocks.range_end
    and t.en > calendar_busy_blocks.range_start;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.calendar_feed (
  token text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_link uuid;
  v_subject text;
  v_tenant uuid;
  v_calendar uuid;
  v_creator uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if calendar_feed.token is null or length(calendar_feed.token) < 32 then
    return null;
  end if;
  select l."id", l."subject_id", l."tenant_id", l."created_by" into v_link, v_subject, v_tenant, v_creator
  from "better_supabase"."share_links" l
  where l."token_hash" = encode(extensions.digest(convert_to(calendar_feed.token, 'utf8'), 'sha256'), 'hex')
    and l."subject_type" = 'calendar'
    and l."revoked_at" is null
    and (l."expires_at" is null or l."expires_at" > now())
    and (l."max_uses" is null or l."use_count" < l."max_uses")
    and l."password_hash" is null
  for update;
  if v_subject is null or v_subject !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return null;
  end if;
  v_calendar := v_subject::uuid;
  if v_creator is null or not coalesce(better_supabase.can_user(v_creator, 'tenant', v_tenant, 'calendar.read'), false) then
    return null;
  end if;
  update "better_supabase"."share_links" set "use_count" = "use_count" + 1, "last_used_at" = now() where "id" = v_link;
  return (
    select jsonb_build_object(
      'calendar', jsonb_build_object('id', k."id", 'name', k."name", 'tz', k."tz", 'color', k."color"),
      'organization', jsonb_build_object('id', v_tenant, 'name', (select g."name" from "public"."organizations" g where g."id" = v_tenant)),
      'createdBy', v_creator,
      'events', coalesce((
      select jsonb_agg(f.item order by f.starts)
      from (
        select (jsonb_build_object('id', e."id", 'calendarId', e."calendar_id", 'uid', e."uid", 'title', e."title", 'startsAt', e."starts_at", 'endsAt', e."ends_at", 'allDay', e."all_day", 'tz', e."tz", 'status', e."status", 'rrule', e."rrule", 'exdates', to_jsonb(e."exdates"), 'recurrenceId', e."recurrence_id", 'originalStart', e."original_starts_at", 'description', e."description", 'location', e."location", 'color', e."color", 'subjectType', e."subject_type", 'subjectId', e."subject_id") || jsonb_build_object('updatedAt', e."updated_at", 'kind', e."kind", 'transparency', e."transparency", 'autoDecline', e."auto_decline", 'attendees', coalesce((select jsonb_agg(jsonb_build_object('email', a."email", 'name', a."name", 'userId', a."user_id", 'role', a."role", 'response', a."response") order by a."email") from "better_supabase"."calendar_attendees" a where a."event_id" = e."id"), '[]'::jsonb), 'alarms', coalesce((select jsonb_agg(jsonb_build_object('id', l."id", 'method', l."method", 'offsetMinutes', l."offset_minutes", 'related', l."related_to", 'at', l."trigger_at", 'repeat', l."repeat_count", 'repeatMinutes', l."repeat_minutes", 'description', l."description", 'summary', l."summary") order by l."offset_minutes" nulls last, l."trigger_at", l."id") from "better_supabase"."calendar_event_alarms" l where l."event_id" = e."id" and (l."user_id" is null or l."user_id" = (select auth.uid()))), '[]'::jsonb)) - 'alarms') || jsonb_build_object('reminders', coalesce((select jsonb_agg(jsonb_build_object('id', l."id", 'method', l."method", 'offsetMinutes', l."offset_minutes", 'related', l."related_to", 'at', l."trigger_at", 'repeat', l."repeat_count", 'repeatMinutes', l."repeat_minutes", 'description', l."description", 'summary', l."summary") order by l."offset_minutes" nulls last, l."trigger_at", l."id") from "better_supabase"."calendar_event_alarms" l where l."event_id" = e."id" and (l."user_id" is null or l."user_id" = v_creator)), '[]'::jsonb) || coalesce((select jsonb_agg(jsonb_build_object('method', r."method", 'offsetMinutes', r."offset_minutes") order by r."offset_minutes") from "better_supabase"."reminders" r where r."subject_type" = 'calendar_event' and r."subject_id" = e."id"::text and r."user_id" = v_creator), '[]'::jsonb)) as item, e."starts_at" as starts
        from "better_supabase"."calendar_events" e
        join "better_supabase"."calendars" k on k."id" = e."calendar_id"
        where k."id" = v_calendar
          and (e."rrule" is not null or e."ends_at" > now() - interval '366 days')
          and true
        order by e."starts_at"
        limit 5000
      ) f
    ), '[]'::jsonb)
    )
    from "better_supabase"."calendars" k where k."id" = v_calendar and k."tenant_id" = v_tenant
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.calendar_free_busy (
  tenant      uuid,
  user_ids    uuid[],
  range_start timestamp with time zone,
  range_end   timestamp with time zone
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_window tstzrange;
begin
  if calendar_free_busy.range_start is null or calendar_free_busy.range_end is null
    or calendar_free_busy.range_end <= calendar_free_busy.range_start
    or calendar_free_busy.range_end - calendar_free_busy.range_start > interval '62 days' then
    raise exception 'the range must end after it starts and cover at most 62 days' using errcode = '22023', hint = 'CALENDAR_RANGE_INVALID';
  end if;
  if coalesce(cardinality(calendar_free_busy.user_ids), 0) not between 1 and 100 then
    raise exception 'ask for 1 to 100 members' using errcode = '22023', hint = 'CALENDAR_RANGE_INVALID';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', calendar_free_busy.tenant, 'calendar.read'), false)) then
    raise exception 'not allowed to read this calendar' using errcode = '42501', hint = 'CALENDAR_FORBIDDEN';
  end if;
  v_window := tstzrange(calendar_free_busy.range_start, calendar_free_busy.range_end);
  return (
    with blocks as (
      select b.user_id, b.kind, tstzrange(b.starts_at, b.ends_at) * v_window as during
      from "better_supabase"."calendar_busy_blocks"(calendar_free_busy.tenant, calendar_free_busy.user_ids, calendar_free_busy.range_start, calendar_free_busy.range_end) b
    ),
  hours as (
    select h."user_id" as user_id, h."tz" as tz,
      tstzrange((d.day + h."starts_at") at time zone h."tz", (d.day + h."ends_at") at time zone h."tz") * v_window as during
    from "better_supabase"."calendar_working_hours" h
    cross join lateral generate_series(
      ((calendar_free_busy.range_start at time zone h."tz")::date - 1)::timestamp,
      ((calendar_free_busy.range_end at time zone h."tz")::date)::timestamp,
      interval '1 day'
    ) d (day)
    where h."tenant_id" = calendar_free_busy.tenant
      and h."user_id" = any (calendar_free_busy.user_ids)
      and extract(isodow from d.day) = h."weekday"
  ),
    members as (
      select m.user_id, min(m.ord) as ord
      from unnest(calendar_free_busy.user_ids) with ordinality m (user_id, ord)
      where m.user_id is not null
      group by m.user_id
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'userId', u.user_id,
      'busy', coalesce((select jsonb_agg(jsonb_build_object('startsAt', lower(x), 'endsAt', upper(x)) order by lower(x)) from unnest((select range_agg(b.during) from blocks b where b.user_id = u.user_id)) x), '[]'::jsonb),
      'outOfOffice', coalesce((select jsonb_agg(jsonb_build_object('startsAt', lower(x), 'endsAt', upper(x)) order by lower(x)) from unnest((select range_agg(b.during) from blocks b where b.user_id = u.user_id and b.kind = 'out_of_office')) x), '[]'::jsonb),
      'focusTime', coalesce((select jsonb_agg(jsonb_build_object('startsAt', lower(x), 'endsAt', upper(x)) order by lower(x)) from unnest((select range_agg(b.during) from blocks b where b.user_id = u.user_id and b.kind = 'focus_time')) x), '[]'::jsonb),
      'tz', (select min(w.tz) from hours w where w.user_id = u.user_id),
      'workingHours', case when exists (select 1 from hours w where w.user_id = u.user_id)
        then coalesce((select jsonb_agg(jsonb_build_object('startsAt', lower(x), 'endsAt', upper(x)) order by lower(x)) from unnest((select range_agg(w.during) from hours w where w.user_id = u.user_id)) x), '[]'::jsonb) end
    ) order by u.ord), '[]'::jsonb)
    from members u
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.calendar_rule_starts (
  dtstart     timestamp with time zone,
  tz          text,
  rrule       text,
  range_start timestamp with time zone,
  range_end   timestamp with time zone
)
  RETURNS SETOF timestamp WITH time zone
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
begin
  if calendar_rule_starts.dtstart is null or calendar_rule_starts.range_start is null or calendar_rule_starts.range_end is null then
    return;
  end if;
  return query select o from better_supabase.rrule_occurrences(calendar_rule_starts.rrule, calendar_rule_starts.dtstart, calendar_rule_starts.tz, tstzrange(calendar_rule_starts.range_start, calendar_rule_starts.range_end, '[)')) o;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.calibrate_appraisal (
  appraisal_id uuid,
  rating       integer,
  reason       text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."appraisals";
  v_cycle "better_supabase"."appraisal_cycles";
  v_reason text := nullif(trim(calibrate_appraisal.reason), '');
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."appraisals" x where x."id" = calibrate_appraisal.appraisal_id for update;
  if not found then
    raise exception 'no such appraisal' using errcode = 'P0002', hint = 'APPRAISALS_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'appraisals.manage'), false))) then
    raise exception 'not allowed to calibrate appraisals' using errcode = '42501', hint = 'APPRAISALS_FORBIDDEN';
  end if;
  select * into v_cycle from "better_supabase"."appraisal_cycles" x where x."id" = v_row."cycle_id";
  if v_cycle."status" <> 'open' or v_row."status" not in ('reviewed', 'calibrated') then
    raise exception 'only a reviewed appraisal in an open cycle is calibrated' using errcode = '55000', hint = 'APPRAISALS_STATE';
  end if;
  if calibrate_appraisal.rating is null or calibrate_appraisal.rating not between 1 and 5 then
    raise exception 'the rating is a whole number from 1 to 5' using errcode = '22023', hint = 'APPRAISALS_INVALID';
  end if;
  if v_reason is null or length(v_reason) > 2000 then
    raise exception 'a calibration needs a reason of up to 2000 characters' using errcode = '22023', hint = 'APPRAISALS_INVALID';
  end if;
  insert into "better_supabase"."appraisal_calibrations" ("tenant_id", "appraisal_id", "from_rating", "to_rating", "reason", "calibrated_by")
  values (v_row."tenant_id", v_row."id", coalesce(v_row."calibrated_rating"::numeric, v_row."rating"), calibrate_appraisal.rating, v_reason, auth.uid());
  update "better_supabase"."appraisals" x
  set "calibrated_rating" = calibrate_appraisal.rating, "status" = 'calibrated', "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('appraisal.calibrated', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'cycleId', v_row."cycle_id", 'subjectUserId', v_row."appraisee_id", 'status', v_row."status", 'rating', v_row."calibrated_rating"), 'appraisals/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/appraisals');
  perform better_supabase.audit_event(
    event_type => 'appraisal.calibrated',
    category => 'data',
    target_type => 'appraisal',
    record_id => v_row."id"::text,
    summary => 'appraisal calibrated',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'cycleId', v_row."cycle_id", 'subjectUserId', v_row."appraisee_id", 'status', v_row."status", 'rating', v_row."calibrated_rating")
  );
  perform "better_supabase"."appraisal_step"(v_row."id", 'calibration');
  return "better_supabase"."appraisal_json"(v_row."id", true);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.calibrate_appraisal_competencies (
  appraisal_id uuid,
  competencies jsonb,
  reason       text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."appraisals";
  v_cycle "better_supabase"."appraisal_cycles";
  v_reason text := nullif(trim(calibrate_appraisal_competencies.reason), '');
  v_item record;
  v_merged jsonb;
  v_rating numeric;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."appraisals" x where x."id" = calibrate_appraisal_competencies.appraisal_id for update;
  if not found then
    raise exception 'no such appraisal' using errcode = 'P0002', hint = 'APPRAISALS_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'appraisals.manage'), false))) then
    raise exception 'not allowed to calibrate appraisals' using errcode = '42501', hint = 'APPRAISALS_FORBIDDEN';
  end if;
  select * into v_cycle from "better_supabase"."appraisal_cycles" x where x."id" = v_row."cycle_id";
  if v_cycle."status" <> 'open' or v_row."status" not in ('reviewed', 'calibrated') then
    raise exception 'only a reviewed appraisal in an open cycle is calibrated' using errcode = '55000', hint = 'APPRAISALS_STATE';
  end if;
  if jsonb_typeof(calibrate_appraisal_competencies.competencies) is distinct from 'object'
    or calibrate_appraisal_competencies.competencies = '{}'::jsonb then
    raise exception 'competencies is an object of competency ratings' using errcode = '22023', hint = 'APPRAISALS_INVALID';
  end if;
  if v_reason is null or length(v_reason) > 2000 then
    raise exception 'a calibration needs a reason of up to 2000 characters' using errcode = '22023', hint = 'APPRAISALS_INVALID';
  end if;
  for v_item in select e.key, e.value from jsonb_each(calibrate_appraisal_competencies.competencies) e loop
    if not exists (select 1 from "better_supabase"."appraisal_competencies" w where w."cycle_id" = v_cycle."id" and w."key" = v_item.key) then
      raise exception 'no such competency in this cycle''s rubric' using errcode = '22023', hint = 'APPRAISALS_INVALID';
    end if;
    if jsonb_typeof(v_item.value) <> 'number' or v_item.value::text !~ '^[1-5]$' then
      raise exception 'a competency rating is a whole number from 1 to 5' using errcode = '22023', hint = 'APPRAISALS_INVALID';
    end if;
  end loop;
  v_merged := v_row."calibrated_competencies" || calibrate_appraisal_competencies.competencies;
  v_rating := "better_supabase"."appraisal_score"(v_row."id", v_merged);
  insert into "better_supabase"."appraisal_calibrations" ("tenant_id", "appraisal_id", "from_rating", "to_rating", "competency_ratings", "reason", "calibrated_by")
  values (v_row."tenant_id", v_row."id", coalesce(v_row."calibrated_rating"::numeric, v_row."rating"), round(v_rating)::integer,
    calibrate_appraisal_competencies.competencies, v_reason, auth.uid());
  update "better_supabase"."appraisals" x
  set "calibrated_competencies" = v_merged, "calibrated_rating" = round(v_rating)::integer,
    "status" = 'calibrated', "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('appraisal.calibrated', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'cycleId', v_row."cycle_id", 'subjectUserId', v_row."appraisee_id", 'status', v_row."status", 'rating', v_row."calibrated_rating"), 'appraisals/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/appraisals');
  perform better_supabase.audit_event(
    event_type => 'appraisal.calibrated',
    category => 'data',
    target_type => 'appraisal',
    record_id => v_row."id"::text,
    summary => 'appraisal calibrated',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'cycleId', v_row."cycle_id", 'subjectUserId', v_row."appraisee_id", 'status', v_row."status", 'rating', v_row."calibrated_rating")
  );
  perform "better_supabase"."appraisal_step"(v_row."id", 'calibration');
  return "better_supabase"."appraisal_json"(v_row."id", true);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.caller_authz_version()
  RETURNS bigint
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if auth.uid() is null then
    return null;
  end if;
  return better_supabase.authz_version(auth.uid());
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.can (
  scope      text,
  scope_id   uuid,
  permission text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  COST 1000
  SET search_path TO ''
  AS $function$
  select case
    when can.scope = 'platform' then coalesce(better_supabase.platform_can(auth.uid(), can.permission), false)
    when can.scope in ('organization', 'tenant') then coalesce(better_supabase.member_can(auth.uid(), can.scope_id, can.permission), false)
    else false
  end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.can_assign (
  tenant uuid,
  role   text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(auth.jwt() ->> 'role', '') = 'service_role' or ((better_supabase.interactive_session() or not better_supabase.interactive_only_role(can_assign.role)) and better_supabase.can_assign_as(auth.uid(), can_assign.tenant, can_assign.role))
$function$;

CREATE OR REPLACE FUNCTION better_supabase.can_assign_as (
  member uuid,
  tenant uuid,
  role   text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select member is not null
    and exists (
      select 1 from "public"."memberships" m
      where m."organization_id" = can_assign_as.tenant and m."user_id" = can_assign_as.member
    )
      and exists (
        select 1 from "better_supabase"."roles" r
        where r."id"::text = can_assign_as.role and r."scope"::text = 'tenant'
      )
    and not exists (
      select 1
        from (
          select r."id" as "role", can_assign_as.tenant as "organization_id"
          from "better_supabase"."roles" r
          where r."id"::text = can_assign_as.role
        ) m
        cross join "better_supabase"."permissions" p
        cross join lateral (select p."key" as key) k
        where coalesce(
      (select bool_and(o."granted") from "better_supabase"."permission_overrides" o
        where o."tenant_id" = m."organization_id"
          and o."role_id" = m."role"
          and o."permission_id" = p."id"),
      exists (select 1 from "better_supabase"."role_permissions" rp where rp."role_id" = m."role" and rp."permission_id" = p."id")
    )
        and not coalesce(better_supabase.member_can(can_assign_as.member, can_assign_as.tenant, k.key), false)
    )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.can_conversation (
  conversation uuid,
  action       text
)
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  v_conv "better_supabase"."conversations";
begin
  select * into v_conv from "better_supabase"."conversations" c
  where c."id" = can_conversation.conversation
    and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (case when c."kind" = 'inbox'
    then "better_supabase"."inbox_conversation_allowed"(c."id"::text)
    else ((coalesce(better_supabase.can('tenant', c."tenant_id", 'messages.read'), false)
    or (c."access" = 'subject' and c."subject_type" in ('drive_node')))
    and case c."access"
      when 'tenant' then true
      when 'members' then "better_supabase"."is_conversation_member"(c."id")
      when 'subject' then coalesce("better_supabase"."can_subject"(c."subject_type", c."subject_id", 'read'), false)
      else false
    end)
    or (c."kind" = 'subject' and ((c."tenant_id")::text, (c."subject_type")::text, (c."subject_id")::text) in (select g.tenant, g.subject_type, g.subject_id from better_supabase.portal_subjects('read') g)) end));
  if not found then
    return false;
  end if;
  if coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then
    return true;
  end if;
  if v_conv."kind" = 'inbox' then
    return "better_supabase"."inbox_can_conversation"(v_conv."id", can_conversation.action);
  end if;
  case can_conversation.action
    when 'read' then
      return true;
    when 'send' then
      if v_conv."access" = 'subject' and v_conv."subject_type" in ('drive_node') then
        return v_conv."archived_at" is null and (v_conv."subject_type" in ('drive_node') and coalesce("better_supabase"."can_subject"(v_conv."subject_type", v_conv."subject_id", 'comment'), false));
      end if;
      return v_conv."archived_at" is null
        and ((coalesce(better_supabase.can('tenant', v_conv."tenant_id", 'messages.send'), false)
        and (v_conv."access" <> 'members' or "better_supabase"."is_conversation_member"(v_conv."id")))
    or (v_conv."kind" = 'subject' and ((v_conv."tenant_id")::text, (v_conv."subject_type")::text, (v_conv."subject_id")::text) in (select g.tenant, g.subject_type, g.subject_id from better_supabase.portal_subjects('comment') g)));
    when 'moderate' then
      return coalesce(better_supabase.can('tenant', v_conv."tenant_id", 'messages.moderate'), false);
    else
      return false;
  end case;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.can_subject (
  subject_type text,
  subject_id   text,
  action       text
)
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  COST 1000
  SET search_path TO ''
  AS $function$
begin
  case can_subject.subject_type
    when 'message' then
      return exists (
        select 1 from "better_supabase"."messages" s
        where s."id" = (can_subject.subject_id)::uuid and s."archived_at" is null
          and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or case can_subject.action
          when 'read' then coalesce(better_supabase.can('tenant', s."tenant_id", 'messages.read'), false)
          when 'write' then coalesce(better_supabase.can('tenant', s."tenant_id", 'messages.send'), false)
