  delete from "better_supabase"."scheduled_inbox_messages" where "id" = v_row."id";
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_inspection (
  inspection_id uuid,
  reason        text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."inspections";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."inspections" x where x."id" = cancel_inspection.inspection_id for update;
  if not found then
    raise exception 'no such inspection' using errcode = 'P0002', hint = 'INSPECTION_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'inspections.manage'), false))) then
    raise exception 'not allowed to cancel inspections' using errcode = '42501', hint = 'INSPECTION_FORBIDDEN';
  end if;
  if v_row."status" in ('closed', 'canceled') then
    raise exception 'the inspection can''t move from % to %', v_row."status", 'canceled' using errcode = '55000', hint = 'INSPECTION_STATUS_INVALID', detail = jsonb_build_object('from', v_row."status", 'to', 'canceled')::text;
  end if;
  if length(cancel_inspection.reason) > 4000 then
    raise exception 'reason is at most 4000 characters' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  update "better_supabase"."inspections" x set "status" = 'canceled', "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('inspection.cancelled', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'kind', v_row."kind", 'title', v_row."title", 'status', v_row."status", 'reason', nullif(trim(cancel_inspection.reason), '')), 'inspections/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/inspections');
  perform better_supabase.audit_event(
    event_type => 'inspection.cancelled',
    category => 'data',
    target_type => 'inspection',
    record_id => v_row."id"::text,
    target_label => v_row."title",
    summary => 'inspection canceled',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'kind', v_row."kind", 'title', v_row."title", 'status', v_row."status", 'reason', nullif(trim(cancel_inspection.reason), ''))
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'programId', v_row."program_id", 'number', v_row."number", 'kind', v_row."kind", 'title', v_row."title", 'scope', v_row."scope", 'criteria', v_row."criteria", 'auditee', case when v_row."auditee_type" is null then null else jsonb_build_object('type', v_row."auditee_type", 'id', v_row."auditee_id") end, 'leadId', v_row."lead_id", 'plannedStart', v_row."planned_start", 'plannedEnd', v_row."planned_end", 'startedAt', v_row."started_at", 'completedAt', v_row."completed_at", 'closedAt', v_row."closed_at", 'status', v_row."status", 'checklistFormId', v_row."checklist_form_id", 'checklistSubmissionId', v_row."checklist_submission_id", 'summary', v_row."summary", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_leave_request (
  request_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."leave_requests"%rowtype;
  v_approval "better_supabase"."approval_requests"%rowtype;
  v_manager boolean;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."leave_requests" x where x."id" = cancel_leave_request.request_id for update;
  if not found then
    raise exception 'leave request not found' using errcode = 'P0002', hint = 'LEAVE_REQUEST_NOT_FOUND';
  end if;
  v_manager := coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'leave.manage'), false);
  if not (v_manager or coalesce(v_row."user_id" = auth.uid(), false)) then
    raise exception 'not allowed to cancel this leave request' using errcode = '42501', hint = 'LEAVE_FORBIDDEN';
  end if;
  if v_row."cancelled_at" is not null then
    raise exception 'this leave request is already cancelled' using errcode = '55000', hint = 'LEAVE_REQUEST_CLOSED';
  end if;
  if not v_manager and v_row."approved_at" is not null and v_row."starts_on" <= current_date then
    raise exception 'leave that has started can only be cancelled by a manager' using errcode = '42501', hint = 'LEAVE_FORBIDDEN';
  end if;
  update "better_supabase"."approval_requests" p set "status" = 'cancelled', "decided_at" = now()
    where p."id" = v_row."approval_id" and p."status" = 'pending';
  if v_row."approved_at" is not null then
    perform "better_supabase"."leave_post"(v_row."tenant_id", v_row."user_id", v_row."type_id", 'taken', v_row."amount", extract(year from v_row."starts_on")::integer, v_row."id", 'cancelled')
    from "better_supabase"."leave_types" t where t."id" = v_row."type_id" and t."tracked";
  end if;
  update "better_supabase"."leave_requests" x set "cancelled_at" = now(), "cancelled_by" = auth.uid(), "updated_at" = now()
    where x."id" = v_row."id"
    returning * into v_row;
  select * into v_approval from "better_supabase"."approval_requests" x where x."id" = v_row."approval_id";
  perform "better_supabase".emit_event('leave_request.cancelled', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'userId', v_row."user_id", 'typeId', v_row."type_id", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'amount', v_row."amount"::text, 'approvalId', v_row."approval_id"), 'leave-requests/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/leave');
  perform better_supabase.audit_event(
    event_type => 'leave_request.cancelled',
    category => 'data',
    target_type => 'leave_request',
    record_id => v_row."id"::text,
    summary => 'cancelled leave' || ' from ' || v_row."starts_on"::text || ' to ' || v_row."ends_on"::text,
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'userId', v_row."user_id", 'typeId', v_row."type_id", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'amount', v_row."amount"::text, 'approvalId', v_row."approval_id")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'userId', v_row."user_id", 'typeId', v_row."type_id", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'partial', v_row."partial", 'amount', v_row."amount"::text, 'note', v_row."note", 'status', case when v_row."cancelled_at" is not null then 'cancelled' when v_row."approved_at" is not null then 'approved' when v_approval."status" in ('rejected', 'expired') then 'rejected' when v_approval."status" = 'cancelled' then 'cancelled' else 'pending' end, 'approvalId', v_row."approval_id", 'approvedAt', v_row."approved_at", 'cancelledAt', v_row."cancelled_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_meeting (
  meeting_id uuid,
  reason     text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."meetings";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."meetings" x where x."id" = cancel_meeting.meeting_id for update;
  if not found or not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'meetings.read'), false))) or "better_supabase"."meeting_role"(v_row."id") is not null) then
    raise exception 'no such meeting' using errcode = 'P0002', hint = 'MEETING_NOT_FOUND';
  end if;
  if not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'meetings.manage'), false))) or (auth.uid() is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'meetings.write'), false) and (coalesce(v_row."created_by" = auth.uid(), false) or coalesce("better_supabase"."meeting_role"(v_row."id") in ('chair', 'secretary'), false)))) then
    raise exception 'not allowed to cancel this meeting' using errcode = '42501', hint = 'MEETING_FORBIDDEN';
  end if;
  if v_row."status" in ('held', 'cancelled') then
    raise exception 'the meeting can''t move from % to %', v_row."status", 'cancelled' using errcode = '55000', hint = 'MEETING_STATUS_INVALID', detail = jsonb_build_object('from', v_row."status", 'to', 'cancelled')::text;
  end if;
  if length(cancel_meeting.reason) > 4000 then
    raise exception 'reason is at most 4000 characters' using errcode = '22023', hint = 'MEETING_INVALID';
  end if;
  update "better_supabase"."meetings" x set "status" = 'cancelled', "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('meeting.cancelled', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'kind', v_row."kind", 'title', v_row."title", 'status', v_row."status", 'reason', nullif(trim(cancel_meeting.reason), '')), 'meetings/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/meetings');
  perform better_supabase.audit_event(
    event_type => 'meeting.cancelled',
    category => 'data',
    target_type => 'meeting',
    record_id => v_row."id"::text,
    target_label => v_row."title",
    summary => 'meeting cancelled',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'kind', v_row."kind", 'title', v_row."title", 'status', v_row."status", 'reason', nullif(trim(cancel_meeting.reason), ''))
  );
  return (jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'kind', v_row."kind", 'title', v_row."title", 'location', v_row."location", 'startsAt', v_row."starts_at", 'endsAt', v_row."ends_at", 'status', v_row."status", 'startedAt', v_row."started_at", 'heldAt', v_row."held_at", 'summary', v_row."summary", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at") || jsonb_build_object('fields', jsonb_build_object('room_code', v_row."room_code")));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_order (
  order_id uuid,
  reason   text DEFAULT NULL::text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_order record;
begin
  select x."id" as id, x."tenant_id" as tenant, x."number" as number, x."customer_id" as customer, x."status" as status, x."currency" as currency, x."total" as total, x."paid_total" as paid_total, x."refunded_total" as refunded_total, x."tax_total" as tax_total, x."tax_inclusive" as tax_inclusive, x."invoice_number" as invoice_number, x."placed_at" as placed_at into v_order from "better_supabase"."orders" x where x."id" = cancel_order.order_id for update;
  if not found or not (auth.role() = 'service_role' or coalesce(v_order.customer = auth.uid(), false) or coalesce(better_supabase.can('tenant', v_order.tenant, 'orders.read'), false)) then
    raise exception 'order not found' using errcode = 'P0002', hint = 'ORDERS_ORDER_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(v_order.customer = auth.uid(), false) or coalesce(better_supabase.can('tenant', v_order.tenant, 'orders.manage'), false)) then
    raise exception 'not allowed to cancel this order' using errcode = '42501', hint = 'ORDERS_FORBIDDEN';
  end if;
  if v_order.status = 'cancelled' then
    return false;
  end if;
  if v_order.status::text not in ('draft', 'pending_payment', 'confirmed', 'on_hold') or exists (select 1 from "better_supabase"."order_fulfillments" y
    where y."order_id" = v_order.id and y."status" in ('shipped', 'delivered')) then
    raise exception 'only a draft, an order waiting for payment, a confirmed one or one on hold, with nothing shipped, can be cancelled; refund a paid one' using errcode = '55000', hint = 'ORDERS_TRANSITION_INVALID';
  end if;
  perform "better_supabase"."order_cancel"(v_order.id, cancel_order.reason);
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_organization_deletion (
  tenant uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."organization_deletions";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."organization_deletions" x
  where x."tenant_id" = cancel_organization_deletion.tenant and x."cancelled_at" is null and x."purged_at" is null
  for update;
  if v_row."tenant_id" is null then
    return null;
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(v_row."requested_by" = auth.uid(), false) or coalesce(better_supabase.member_can_while_deleting(auth.uid(), cancel_organization_deletion.tenant, 'organization.delete'), false)) then
    raise exception 'You may not cancel this deletion' using errcode = '42501', hint = 'ORGANIZATION_DELETION_FORBIDDEN';
  end if;
  update "better_supabase"."organization_deletions" x set "cancelled_at" = now()
  where x."tenant_id" = v_row."tenant_id"
  returning * into v_row;
  
  perform "better_supabase".emit_event('organization.deletion_cancelled', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'userId', auth.uid(), 'purgeAfter', v_row."purge_at"), 'organizations/' || v_row."tenant_id"::text, (v_row."tenant_id")::text, null, 'better-supabase/data-lifecycle');
  perform better_supabase.audit_event(
    event_type => 'organization.deletion_cancelled',
    category => 'data',
    target_type => 'organization',
    record_id => v_row."tenant_id"::text,
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'userId', auth.uid(), 'purgeAfter', v_row."purge_at")
  );
  return to_jsonb(v_row);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_payment_batch (
  batch_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_batch "better_supabase"."payment_batches"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_batch from "better_supabase"."payment_batches" x where x."id" = cancel_payment_batch.batch_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_batch."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_batch."tenant_id", 'banking.reconcile'), false))) then
    raise exception 'no such payment batch' using errcode = 'P0002', hint = 'PAYMENT_BATCH_NOT_FOUND';
  end if;
  if v_batch."status" not in ('draft', 'posted') then
    raise exception 'only a draft or posted batch is cancelled' using errcode = '55000', hint = 'PAYMENT_BATCH_STATUS_INVALID',
      detail = jsonb_build_object('status', v_batch."status")::text;
  end if;
  update "better_supabase"."payment_batch_items" y set "status" = 'cancelled' where y."batch_id" = v_batch."id";
  update "better_supabase"."payment_batches" y set "status" = 'cancelled' where y."id" = v_batch."id" returning * into v_batch;
  return jsonb_build_object('id', v_batch."id", 'organizationId', v_batch."tenant_id", 'accountId', v_batch."bank_account_id", 'reference', v_batch."reference", 'messageId', v_batch."message_id", 'currency', v_batch."currency", 'dueBy', v_batch."due_by", 'executionOn', v_batch."execution_on", 'total', v_batch."total"::text, 'itemCount', v_batch."item_count", 'status', v_batch."status", 'transactionId', v_batch."bank_transaction_id", 'createdBy', v_batch."created_by", 'createdAt', v_batch."created_at", 'postedAt', v_batch."posted_at", 'reconciledAt', v_batch."reconciled_at", 'items', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'invoiceId', y."invoice_id", 'partyId', y."party_id", 'creditorName', y."creditor_name", 'creditorIban', y."creditor_iban", 'creditorBic', y."creditor_bic", 'amount', y."amount"::text, 'discount', y."discount"::text, 'currency', y."currency", 'endToEndId', y."end_to_end_id", 'remittance', y."remittance", 'status', y."status") order by y."creditor_name", y."id") from "better_supabase"."payment_batch_items" y where y."batch_id" = v_batch."id"), '[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_pick_wave (
  wave_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."pick_waves";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."pick_waves" x where x."id" = cancel_pick_wave.wave_id for update;
  if not found then
    raise exception 'no such pick wave' using errcode = 'P0002', hint = 'WAREHOUSE_WAVE_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'warehouse.manage'), false))) then
    raise exception 'not allowed to manage pick waves' using errcode = '42501', hint = 'WAREHOUSE_FORBIDDEN';
  end if;
  if v_row."status" not in ('draft', 'released') then
    raise exception 'only a draft or released wave is cancelled' using errcode = '55000', hint = 'WAREHOUSE_STATE';
  end if;
  update "better_supabase"."pick_lines" y set "status" = 'cancelled'
  from "better_supabase"."pick_lists" x
  where y."pick_list_id" = x."id" and x."wave_id" = v_row."id" and x."status" = 'open' and y."status" = 'open';
  update "better_supabase"."pick_lists" x set "status" = 'cancelled' where x."wave_id" = v_row."id" and x."status" = 'open';
  update "better_supabase"."pick_waves" x set "status" = 'cancelled' where x."id" = v_row."id"
  returning * into v_row;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'name', v_row."name", 'locationId', v_row."location_id", 'status', v_row."status", 'releasedAt', v_row."released_at", 'completedAt', v_row."completed_at", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_prescription (
  prescription_id uuid,
  reason          text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."prescriptions";
  v_reason text := nullif(trim(cancel_prescription.reason), '');
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."prescriptions" x where x."id" = cancel_prescription.prescription_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'e_prescribing.read'), false))) then
    raise exception 'no such prescription' using errcode = 'P0002', hint = 'PRESCRIPTION_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'e_prescribing.manage'), false))) and not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'e_prescribing.write'), false))) and v_row."prescriber_id" is not distinct from auth.uid()) then
    raise exception 'only the prescriber or a manager cancels a prescription' using errcode = '42501', hint = 'PRESCRIPTION_FORBIDDEN';
  end if;
  if v_row."status" in ('dispensed', 'cancelled') then
    raise exception 'a dispensed or cancelled prescription cannot be cancelled' using errcode = '55000', hint = 'PRESCRIPTION_STATUS';
  end if;
  if v_reason is null and v_row."status" <> 'draft' then
    raise exception 'cancelling a signed or sent prescription needs a reason' using errcode = '22023', hint = 'PRESCRIPTION_INVALID';
  end if;
  if length(coalesce(v_reason, '')) > 1000 then
    raise exception 'a reason is up to 1000 characters' using errcode = '22023', hint = 'PRESCRIPTION_INVALID';
  end if;
  update "better_supabase"."prescriptions" x set "status" = 'cancelled', "cancelled_at" = now(), "cancel_reason" = v_reason, "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('prescription.cancelled', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'orderId', v_row."order_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status"), 'prescriptions/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/e-prescribing');
  perform better_supabase.audit_event(
    event_type => 'prescription.cancelled',
    category => 'data',
    target_type => 'prescription',
    record_id => v_row."id"::text,
    target_label => v_row."status",
    summary => 'prescription cancelled',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'orderId', v_row."order_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'orderId', v_row."order_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'prescriberId', v_row."prescriber_id", 'prescriberName', v_row."prescriber_name", 'status', v_row."status", 'order', v_row."snapshot", 'signedBy', v_row."signed_by", 'signedAt', v_row."signed_at", 'gateway', v_row."gateway", 'gatewayReference', v_row."gateway_reference", 'sentAt', v_row."sent_at", 'deliveryError', v_row."delivery_error", 'dispensedAt', v_row."dispensed_at", 'cancelledAt', v_row."cancelled_at", 'cancelReason', v_row."cancel_reason", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_production_order (
  order_id uuid,
  reason   text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."production_orders";
  v_consumption record;
  v_claims text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."production_orders" x where x."id" = cancel_production_order.order_id for update;
  if not found then
    raise exception 'no such production order' using errcode = 'P0002', hint = 'PRODUCTION_ORDER_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'manufacturing.write'), false))) then
    raise exception 'not allowed to cancel production orders' using errcode = '42501', hint = 'MANUFACTURING_FORBIDDEN';
  end if;
  if v_row."status" not in ('draft', 'released', 'in_progress') then
    raise exception 'the production order can''t move from % to %', v_row."status", 'canceled' using errcode = '55000', hint = 'PRODUCTION_ORDER_STATUS_INVALID', detail = jsonb_build_object('from', v_row."status", 'to', 'canceled')::text;
  end if;
  if cancel_production_order.reason is not null and length(cancel_production_order.reason) > 1000 then
    raise exception 'the reason is at most 1000 characters' using errcode = '22023', hint = 'PRODUCTION_ORDER_INVALID';
  end if;
  v_claims := current_setting('request.jwt.claims', true);
  perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
  perform "better_supabase"."release_allocations"(v_row."tenant_id", 'production_order', v_row."id"::text);
  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  for v_consumption in
    select z."variant_id" as variant, z."lot_id" as lot, z."currency" as currency,
      array_agg(z."serial") filter (where z."serial" is not null) as serials,
      sum(z."quantity") as quantity, sum(z."cost") as cost
    from "better_supabase"."production_consumptions" z where z."order_id" = v_row."id"
    group by z."variant_id", z."lot_id", z."currency"
  loop
    perform "better_supabase"."move_stock"(v_row."tenant_id", v_consumption.variant, v_row."location_id", v_consumption.quantity, 'consumption', 'production_order', v_row."id"::text, 'production order canceled', jsonb_strip_nulls(jsonb_build_object('lotId', v_consumption.lot, 'serials', to_jsonb(v_consumption.serials),
      'unitCost', case when v_consumption.currency is null then null else round(v_consumption.cost::numeric / v_consumption.quantity, 6)::text end,
      'currency', v_consumption.currency)));
  end loop;
  update "better_supabase"."production_orders" x set "status" = 'canceled', "canceled_at" = now(), "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('production_order.cancelled', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'variantId', v_row."variant_id", 'quantity', v_row."quantity"::text, 'status', v_row."status", 'reason', cancel_production_order.reason), 'production-orders/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/manufacturing');
  perform better_supabase.audit_event(
    event_type => 'production_order.cancelled',
    category => 'data',
    target_type => 'production_order',
    record_id => v_row."id"::text,
    target_label => v_row."number",
    summary => 'production order canceled',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'variantId', v_row."variant_id", 'quantity', v_row."quantity"::text, 'status', v_row."status", 'reason', cancel_production_order.reason)
  );
  return (jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'number', v_row."number", 'variantId', v_row."variant_id", 'bomId', v_row."bom_id", 'quantity', v_row."quantity"::text, 'locationId', v_row."location_id", 'dueOn', v_row."due_on", 'status', v_row."status", 'producedQuantity', v_row."produced_quantity"::text, 'scrapQuantity', v_row."scrap_quantity"::text, 'outputLotId', v_row."output_lot_id", 'materialCost', v_row."material_cost"::text, 'laborCost', v_row."labor_cost"::text, 'currency', v_row."currency", 'note', v_row."note", 'releasedAt', v_row."released_at", 'startedAt', v_row."started_at", 'completedAt', v_row."completed_at", 'canceledAt', v_row."canceled_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at") || jsonb_build_object(
    'operations', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'orderId', y."order_id", 'operationId', y."operation_id", 'sequence', y."sequence", 'workCenterId', y."work_center_id", 'title', y."title", 'plannedMinutes', y."planned_minutes"::text, 'status', y."status", 'startedAt', y."started_at", 'finishedAt', y."finished_at", 'operatorId', y."operator_id", 'minutes', y."minutes"::text, 'inspectionId', y."inspection_id") order by y."sequence")
      from "better_supabase"."production_order_operations" y where y."order_id" = v_row."id"), '[]'::jsonb),
    'components', coalesce((select jsonb_agg(jsonb_build_object('componentId', y."id", 'variantId', y."variant_id",
        'quantity', "better_supabase"."production_quantity"(y."variant_id", y."quantity" * v_row."quantity" / x."quantity" * (1 + y."scrap_bps" / 10000.0))::text,
        'allocated', coalesce(al."allocated", 0)::text, 'backordered', coalesce(al."backordered", 0)::text,
        'consumed', coalesce((select sum(z."quantity") from "better_supabase"."production_consumptions" z
          where z."order_id" = v_row."id" and z."variant_id" = y."variant_id"), 0)::text)
      order by y."position", y."id")
      from "better_supabase"."boms" x join "better_supabase"."bom_components" y on y."bom_id" = x."id"
      left join "better_supabase"."stock_allocations" al on al."tenant_id" = v_row."tenant_id"
        and al."document_type" = 'production_order' and al."document_id" = v_row."id"::text
        and al."line_id" = y."id"::text and al."status" = 'open'
      where x."id" = v_row."bom_id"), '[]'::jsonb),
    'consumptions', coalesce((select jsonb_agg(jsonb_build_object('id', z."id", 'variantId', z."variant_id", 'lotId', z."lot_id",
        'serial', z."serial", 'quantity', z."quantity"::text, 'cost', z."cost"::text, 'currency', z."currency",
        'movementId', z."movement_id", 'createdAt', z."created_at") order by z."created_at", z."id")
      from "better_supabase"."production_consumptions" z where z."order_id" = v_row."id"), '[]'::jsonb)));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_purchase_order (
  purchase_order uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row record;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" as tenant, x."location_id" as location, x."status" as status,
    x."supplier_type" as supplier_type, x."supplier_id" as supplier_id, x."currency" as currency
  into v_row from "better_supabase"."purchase_orders" x where x."id" = cancel_purchase_order.purchase_order for update;
  if not found then
    raise exception 'purchase order not found' using errcode = 'P0002', hint = 'INVENTORY_PURCHASE_ORDER_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_row.tenant, 'inventory.purchase'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  if v_row.status not in ('draft', 'ordered', 'partially_received') then
    raise exception 'the purchase order can''t do this in its current status' using errcode = '55000', hint = 'INVENTORY_PURCHASE_ORDER_STATUS';
  end if;
  if v_row.status <> 'draft' then
    update "better_supabase"."stock_levels" x set "incoming" = greatest(x."incoming" - (y."quantity_ordered" - y."quantity_canceled" - y."quantity_received"), 0), "updated_at" = now()
    from "better_supabase"."purchase_order_lines" y
    where y."purchase_order_id" = cancel_purchase_order.purchase_order
      and x."variant_id" = y."variant_id" and x."location_id" = v_row.location;
  end if;
  update "better_supabase"."purchase_orders" x set "status" = 'cancelled', "updated_at" = now()
  where x."id" = cancel_purchase_order.purchase_order;
  perform "better_supabase".emit_event('purchase_order.cancelled', jsonb_build_object('organizationId', v_row.tenant, 'id', cancel_purchase_order.purchase_order, 'locationId', v_row.location, 'status', 'cancelled', 'supplierType', v_row.supplier_type, 'supplierId', v_row.supplier_id), 'purchase-orders/' || cancel_purchase_order.purchase_order::text, (v_row.tenant)::text, null, 'better-supabase/inventory');
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_purchase_order_quantity (
  purchase_order uuid,
  lines          jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row record;
  v_line record;
  v_backordered numeric;
  v_received numeric;
  v_status text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" as tenant, x."location_id" as location, x."status" as status,
    x."supplier_type" as supplier_type, x."supplier_id" as supplier_id, x."currency" as currency
  into v_row from "better_supabase"."purchase_orders" x where x."id" = cancel_purchase_order_quantity.purchase_order for update;
  if not found then
    raise exception 'purchase order not found' using errcode = 'P0002', hint = 'INVENTORY_PURCHASE_ORDER_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_row.tenant, 'inventory.purchase'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  if v_row.status not in ('ordered', 'partially_received') then
    raise exception 'the purchase order can''t do this in its current status' using errcode = '55000', hint = 'INVENTORY_PURCHASE_ORDER_STATUS';
  end if;
  if jsonb_typeof(cancel_purchase_order_quantity.lines) is distinct from 'array' or jsonb_array_length(cancel_purchase_order_quantity.lines) = 0
    or exists (
      select 1 from jsonb_array_elements(cancel_purchase_order_quantity.lines) e
      where jsonb_typeof(e) <> 'object'
        or coalesce(e ->> 'lineId', '') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        or case when coalesce(e ->> 'quantity', '') ~ '^[0-9]{1,14}([.][0-9]{1,6})?$' then (e ->> 'quantity')::numeric <= 0 else true end
    )
    or (select count(distinct e ->> 'lineId') from jsonb_array_elements(cancel_purchase_order_quantity.lines) e) <> jsonb_array_length(cancel_purchase_order_quantity.lines) then
    raise exception 'lines must be a non-empty list with a unique lineId and a positive quantity each' using errcode = '22023', hint = 'INVENTORY_LINES_INVALID';
  end if;
  for v_line in
    select y."id" as id, y."variant_id" as variant,
      y."quantity_ordered" - y."quantity_canceled" - y."quantity_received" as owed, (e ->> 'quantity')::numeric as quantity
    from jsonb_array_elements(cancel_purchase_order_quantity.lines) e
    left join "better_supabase"."purchase_order_lines" y on y."id" = (e ->> 'lineId')::uuid and y."purchase_order_id" = cancel_purchase_order_quantity.purchase_order
  loop
    if v_line.id is null then
      raise exception 'a line isn''t on this purchase order' using errcode = 'P0002', hint = 'INVENTORY_LINE_NOT_FOUND';
    end if;
    if v_line.quantity > v_line.owed then
      raise exception 'a line would cancel more than it still owes' using errcode = '22023', hint = 'INVENTORY_OVER_CANCEL';
    end if;
    update "better_supabase"."purchase_order_lines" y set "quantity_canceled" = y."quantity_canceled" + v_line.quantity where y."id" = v_line.id;
    update "better_supabase"."stock_levels" x set "incoming" = greatest(x."incoming" - v_line.quantity, 0), "updated_at" = now()
    where x."variant_id" = v_line.variant and x."location_id" = v_row.location;
  end loop;
  select coalesce(sum(y."quantity_ordered" - y."quantity_canceled" - y."quantity_received"), 0), coalesce(sum(y."quantity_received"), 0)
  into v_backordered, v_received from "better_supabase"."purchase_order_lines" y where y."purchase_order_id" = cancel_purchase_order_quantity.purchase_order;
  v_status := case when v_backordered > 0 then v_row.status when v_received > 0 then 'received' else 'cancelled' end;
  update "better_supabase"."purchase_orders" x set "status" = v_status, "updated_at" = now()
  where x."id" = cancel_purchase_order_quantity.purchase_order;
  perform "better_supabase".emit_event('purchase_order.line_cancelled', jsonb_build_object('organizationId', v_row.tenant, 'id', cancel_purchase_order_quantity.purchase_order, 'locationId', v_row.location, 'status', v_status, 'supplierType', v_row.supplier_type, 'supplierId', v_row.supplier_id), 'purchase-orders/' || cancel_purchase_order_quantity.purchase_order::text, (v_row.tenant)::text, null, 'better-supabase/inventory');
  return jsonb_build_object('status', v_status, 'backordered', v_backordered);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_rfq (
  rfq_id uuid,
  reason text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."rfqs";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."rfqs" x where x."id" = cancel_rfq.rfq_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'rfqs.read'), false))) then
    raise exception 'no such request for quotation' using errcode = 'P0002', hint = 'RFQ_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'rfqs.manage'), false))) then
    raise exception 'not allowed to cancel requests for quotation' using errcode = '42501', hint = 'RFQ_FORBIDDEN';
  end if;
  if v_row."status" in ('awarded', 'cancelled') then
    raise exception 'an awarded or cancelled request cannot be cancelled' using errcode = '55000', hint = 'RFQ_STATUS';
  end if;
  if coalesce(trim(cancel_rfq.reason), '') = '' or length(cancel_rfq.reason) > 500 then
    raise exception 'a reason of 1 to 500 characters is required' using errcode = '22023', hint = 'RFQ_INVALID';
  end if;
  update "better_supabase"."rfqs" x set "status" = 'cancelled', "cancel_reason" = trim(cancel_rfq.reason), "updated_at" = now()
  where x."id" = v_row."id" returning * into v_row;
  perform "better_supabase".emit_event('rfq.cancelled', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'status', v_row."status", 'quoteId', v_row."awarded_quote_id", 'purchaseOrderId', v_row."purchase_order_id"), 'rfqs/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/rfqs');
  perform better_supabase.audit_event(
    event_type => 'rfq.cancelled',
    category => 'data',
    target_type => 'rfq',
    record_id => v_row."id"::text,
    target_label => v_row."number",
    summary => 'request for quotation cancelled',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'status', v_row."status", 'quoteId', v_row."awarded_quote_id", 'purchaseOrderId', v_row."purchase_order_id")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'number', v_row."number", 'title', v_row."title", 'status', v_row."status", 'currency', v_row."currency", 'dueAt', v_row."due_at", 'notes', v_row."notes", 'awardedQuoteId', v_row."awarded_quote_id", 'purchaseOrderId', v_row."purchase_order_id", 'cancelReason', v_row."cancel_reason", 'openedAt', v_row."opened_at", 'closedAt', v_row."closed_at", 'awardedAt', v_row."awarded_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_shift (
  shift_id uuid,
  reason   text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."shifts"%rowtype;
  v_assignment "better_supabase"."shift_assignments"%rowtype;
  v_users jsonb := '[]'::jsonb;
  v_claims text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."shifts" x where x."id" = cancel_shift.shift_id for update;
  if not found then
    raise exception 'shift not found' using errcode = 'P0002', hint = 'SHIFT_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'shifts.manage'), false)) then
    raise exception 'not allowed to cancel shifts' using errcode = '42501', hint = 'SHIFT_FORBIDDEN';
  end if;
  if v_row."status" <> 'canceled' then
    declare
    v_hook regprocedure := to_regprocedure('"public"."before_shift_cancel"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
    v_users := coalesce((select jsonb_agg(x."user_id") from "better_supabase"."shift_assignments" x where x."shift_id" = v_row."id" and x."status" = 'assigned'), '[]'::jsonb);
    update "better_supabase"."shifts" x set "status" = 'canceled', "canceled_at" = now(), "updated_at" = now()
    where x."id" = v_row."id"
    returning x.* into v_row;
    for v_assignment in
      update "better_supabase"."shift_assignments" x set "status" = 'released', "updated_at" = now()
      where x."shift_id" = v_row."id" and x."status" <> 'released'
      returning x.*
    loop
      perform "better_supabase".emit_event('shift_assignment.released', jsonb_build_object('organizationId', v_assignment."tenant_id", 'shiftId', v_assignment."shift_id", 'assignmentId', v_assignment."id", 'userId', v_assignment."user_id", 'startsAt', v_assignment."starts_at", 'endsAt', v_assignment."ends_at", 'reason', 'shift_canceled'), 'shifts/' || v_assignment."shift_id"::text, (v_assignment."tenant_id")::text, null, 'better-supabase/shifts');
  perform better_supabase.audit_event(
    event_type => 'shift_assignment.released',
    category => 'data',
    target_type => 'shift_assignment',
    record_id => v_assignment."id"::text,
    summary => 'Shift assignment released',
    tenant => (v_assignment."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_assignment."tenant_id", 'shiftId', v_assignment."shift_id", 'assignmentId', v_assignment."id", 'userId', v_assignment."user_id", 'startsAt', v_assignment."starts_at", 'endsAt', v_assignment."ends_at", 'reason', 'shift_canceled')
  );
    end loop;
    perform "better_supabase".emit_event('shift.cancelled', jsonb_build_object('organizationId', v_row."tenant_id", 'shiftId', v_row."id", 'teamId', v_row."team_id", 'startsAt', v_row."starts_at", 'endsAt', v_row."ends_at", 'reason', nullif(trim(cancel_shift.reason), '')), 'shifts/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/shifts');
  perform better_supabase.audit_event(
    event_type => 'shift.cancelled',
    category => 'data',
    target_type => 'shift',
    record_id => v_row."id"::text,
    summary => 'Shift canceled',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'shiftId', v_row."id", 'teamId', v_row."team_id", 'startsAt', v_row."starts_at", 'endsAt', v_row."ends_at", 'reason', nullif(trim(cancel_shift.reason), ''))
  );
    if jsonb_array_length(v_users) > 0 then
      if better_supabase.import_run() is null then
    v_claims := current_setting('request.jwt.claims', true);
    perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
    perform "better_supabase"."notify"(jsonb_build_object(
      'type', 'shift.cancelled',
      'tenant', v_row."tenant_id",
      'actor', (select auth.uid()),
      'subject_type', 'shift',
      'subject_id', v_row."id"::text,
      'summary', 'Your shift is canceled',
      'recipients', v_users,
      'key', 'shift.cancelled:' || v_row."id"::text,
      'data', jsonb_build_object('startsAt', v_row."starts_at", 'endsAt', v_row."ends_at")
    ));
    perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  end if;
    end if;
    declare
    v_hook regprocedure := to_regprocedure('"public"."after_shift_cancel"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  end if;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'templateId', v_row."template_id", 'teamId', v_row."team_id", 'locationId', v_row."location_id", 'startsAt', v_row."starts_at", 'endsAt', v_row."ends_at", 'breakMinutes', v_row."break_minutes", 'headcount', v_row."headcount", 'requiredQualifications', to_jsonb(v_row."required_qualifications"), 'status', v_row."status", 'note', v_row."note", 'publishedAt', v_row."published_at", 'canceledAt', v_row."canceled_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_shipment (
  shipment_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_ship "better_supabase"."shipments"%rowtype;
  v_line record;
  v_part record;
  v_movement uuid;
  v_claims text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_ship from "better_supabase"."shipments" x where x."id" = cancel_shipment.shipment_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_ship."tenant_id", 'shipments.manage'), false)) then
    raise exception 'shipment not found' using errcode = 'P0002', hint = 'SHIPMENT_NOT_FOUND';
  end if;
  if v_ship."status" not in ('draft', 'label_created') then
    raise exception 'only a draft or a shipment that hasn''t left gets cancelled' using errcode = '55000', hint = 'SHIPMENT_SHIPPED';
  end if;
  for v_line in
    select x."id" as id, x."variant_id" as variant, x."location_id" as location, x."quantity" as quantity,
      x."detail" as detail, x."allocation_id" as allocation
    from "better_supabase"."shipment_lines" x
    where x."shipment_id" = v_ship."id" and x."direction" = 'outbound' and x."movement_id" is not null
  loop
    for v_part in
      select nullif(p ->> 'lotId', '')::uuid as lot, (p ->> 'quantity')::numeric as quantity
      from jsonb_array_elements(coalesce(v_line.detail -> 'parts', jsonb_build_array(jsonb_build_object('quantity', v_line.quantity)))) p
    loop
      if v_line.allocation is not null then
        v_claims := current_setting('request.jwt.claims', true);
  perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
  perform "better_supabase"."restore_allocation"(v_line.allocation, v_part.quantity, jsonb_strip_nulls(jsonb_build_object('lotId', v_part.lot, 'serials', (select jsonb_agg(z."serial") from "better_supabase"."stock_serials" z
          where z."variant_id" = v_line.variant and z."serial" in (select jsonb_array_elements_text(v_line.detail -> 'serials'))
            and z."lot_id" is not distinct from v_part.lot))));
  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
      else
        perform "better_supabase"."move_stock"(v_ship."tenant_id", v_line.variant, v_line.location, v_part.quantity, 'return', 'shipment', v_ship."id"::text, null, jsonb_strip_nulls(jsonb_build_object('lotId', v_part.lot, 'serials', (select jsonb_agg(z."serial") from "better_supabase"."stock_serials" z
          where z."variant_id" = v_line.variant and z."serial" in (select jsonb_array_elements_text(v_line.detail -> 'serials'))
            and z."lot_id" is not distinct from v_part.lot))));
      end if;
    end loop;
    update "better_supabase"."shipment_lines" x set "movement_id" = null, "moved_at" = null where x."id" = v_line.id;
  end loop;
  update "better_supabase"."shipments" x set
    "status" = 'cancelled',
    "cancelled_at" = now(),
    "updated_at" = now()
  where x."id" = v_ship."id"
  returning * into v_ship;
  perform "better_supabase".emit_event('shipment.cancelled', jsonb_build_object('organizationId', v_ship."tenant_id"::text, 'id', v_ship."id", 'trackingNumber', v_ship."tracking_number"), 'shipments/' || v_ship."id"::text, (v_ship."tenant_id")::text, null, 'better-supabase/shipments');
  perform better_supabase.audit_event(
    event_type => 'shipment.cancelled',
    category => 'data',
    target_type => 'shipment',
    record_id => v_ship."id"::text,
    target_label => v_ship."reference",
    summary => 'cancelled shipment',
    tenant => (v_ship."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_ship."tenant_id"::text, 'id', v_ship."id", 'trackingNumber', v_ship."tracking_number")
  );
  return jsonb_build_object('id', v_ship."id", 'organizationId', v_ship."tenant_id"::text, 'reference', v_ship."reference", 'status', v_ship."status", 'from', v_ship."from_address", 'to', v_ship."to_address", 'direction', v_ship."direction", 'fromLocationId', v_ship."from_location_id", 'subjectType', v_ship."subject_type", 'subjectId', v_ship."subject_id", 'carrier', v_ship."carrier", 'service', v_ship."service", 'trackingNumber', v_ship."tracking_number", 'trackingUrl', v_ship."tracking_url", 'labelId', v_ship."label_id", 'labelUrl', v_ship."label_url", 'labelFormat', v_ship."label_format", 'labelCost', v_ship."label_cost"::text, 'currency', v_ship."currency", 'labeledAt', v_ship."labeled_at", 'deliveredAt', v_ship."delivered_at", 'deliveredTo', v_ship."delivered_to", 'proofReference', v_ship."proof_reference", 'proofAttachmentId', v_ship."proof_attachment_id", 'proofRecordedAt', v_ship."proof_recorded_at", 'cancelledAt', v_ship."cancelled_at", 'createdBy', v_ship."created_by", 'createdAt', v_ship."created_at", 'updatedAt', v_ship."updated_at", 'packages', (select coalesce(jsonb_agg(jsonb_build_object('id', pk."id", 'position', pk."position", 'weightGrams', pk."weight_grams", 'lengthMm', pk."length_mm", 'widthMm', pk."width_mm", 'heightMm', pk."height_mm", 'reference', pk."reference") order by pk."position"), '[]'::jsonb) from "better_supabase"."shipment_packages" pk where pk."shipment_id" = v_ship."id"), 'lines', (select coalesce(jsonb_agg(jsonb_build_object('id', sl."id", 'position', sl."position", 'direction', sl."direction",
    'variantId', sl."variant_id", 'locationId', sl."location_id", 'quantity', sl."quantity"::text, 'allocationId', sl."allocation_id",
    'detail', sl."detail", 'disposition', sl."disposition", 'movementId', sl."movement_id", 'movedAt', sl."moved_at")
    order by sl."position"), '[]'::jsonb) from "better_supabase"."shipment_lines" sl where sl."shipment_id" = v_ship."id"));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_signature_request (
  request_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_req "better_supabase"."signature_requests"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_req from "better_supabase"."signature_requests" x where x."id" = cancel_signature_request.request_id for update;
  if not found then
    raise exception 'signature request not found' using errcode = 'P0002', hint = 'SIGNATURE_REQUEST_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(v_req."requested_by" = auth.uid(), false) or coalesce(better_supabase.can('tenant', v_req."tenant_id", 'signatures.manage'), false)) then
    raise exception 'not allowed to cancel this request' using errcode = '42501', hint = 'SIGNATURE_FORBIDDEN';
  end if;
  if v_req."status" <> 'pending' then
    raise exception 'this request is no longer pending' using errcode = '22023', hint = 'SIGNATURE_REQUEST_CLOSED';
  end if;
  update "better_supabase"."signature_requests" x set "status" = 'cancelled', "completed_at" = now()
    where x."id" = v_req."id"
    returning * into v_req;
  perform "better_supabase".emit_event('signature_request.cancelled', jsonb_build_object('organizationId', v_req."tenant_id", 'subjectType', v_req."subject_type", 'subjectId', v_req."subject_id", 'id', v_req."id"), 'signature-requests/' || v_req."id"::text, (v_req."tenant_id")::text, null, 'better-supabase/signatures');
  perform better_supabase.audit_event(
    event_type => 'signature_request.cancelled',
    category => 'data',
    target_type => 'signature_request',
    record_id => v_req."id"::text,
    summary => 'cancelled a signature request',
    tenant => (v_req."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_req."tenant_id", 'subjectType', v_req."subject_type", 'subjectId', v_req."subject_id", 'id', v_req."id")
  );
  return jsonb_build_object('id', v_req."id", 'organizationId', v_req."tenant_id", 'subjectType', v_req."subject_type", 'subjectId', v_req."subject_id", 'versionId', v_req."version_id", 'contentHash', v_req."content_hash", 'signers', to_jsonb(v_req."signers"), 'order', v_req."sign_order", 'status', v_req."status", 'approvalRequestId', v_req."approval_request_id", 'message', v_req."message", 'meaning', v_req."meaning", 'requestedBy', v_req."requested_by", 'createdAt', v_req."created_at", 'completedAt', v_req."completed_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_stock_count (
  count uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_status text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id", x."status" into v_tenant, v_status from "better_supabase"."stock_counts" x where x."id" = cancel_stock_count.count for update;
  if v_tenant is null then
    raise exception 'stock count not found' using errcode = 'P0002', hint = 'INVENTORY_COUNT_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'inventory.manage'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  if v_status = 'cancelled' then
    return false;
  end if;
  if v_status <> 'open' then
    raise exception 'a posted count can''t be cancelled' using errcode = '22023', hint = 'INVENTORY_COUNT_CLOSED';
  end if;
  update "better_supabase"."stock_counts" x set "status" = 'cancelled', "updated_at" = now() where x."id" = cancel_stock_count.count;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cancel_transfer (
  transfer uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row record;
  v_line record;
  v_part record;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" as tenant, x."from_location_id" as from_location, x."to_location_id" as to_location, x."status" as status
  into v_row from "better_supabase"."stock_transfers" x where x."id" = cancel_transfer.transfer for update;
  if not found then
    raise exception 'transfer not found' using errcode = 'P0002', hint = 'INVENTORY_TRANSFER_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_row.tenant, 'inventory.manage'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  if v_row.status not in ('draft', 'in_transit') then
    raise exception 'the transfer can''t do this in its current status' using errcode = '55000', hint = 'INVENTORY_TRANSFER_STATUS';
  end if;
  if v_row.status = 'in_transit' then
    for v_line in
    select x."variant_id" as variant, x."quantity" as quantity, x."detail" as detail
    from "better_supabase"."stock_transfer_lines" x where x."transfer_id" = cancel_transfer.transfer
  loop
    for v_part in
      select nullif(p ->> 'lotId', '')::uuid as lot, (p ->> 'quantity')::numeric as quantity
      from jsonb_array_elements(coalesce(v_line.detail -> 'parts', jsonb_build_array(jsonb_build_object('quantity', v_line.quantity)))) p
    loop
      perform "better_supabase"."move_stock"(v_row.tenant, v_line.variant, v_row.from_location, v_part.quantity, 'transfer_in', 'transfer', cancel_transfer.transfer::text, null, jsonb_strip_nulls(jsonb_build_object('lotId', v_part.lot, 'serials', (select jsonb_agg(z."serial") from "better_supabase"."stock_serials" z
          where z."variant_id" = v_line.variant and z."serial" in (select jsonb_array_elements_text(v_line.detail -> 'serials'))
            and z."lot_id" is not distinct from v_part.lot))));
    end loop;
  end loop;
  end if;
  update "better_supabase"."stock_transfers" x set "status" = 'cancelled' where x."id" = cancel_transfer.transfer;
  perform "better_supabase".emit_event('transfer.cancelled', jsonb_build_object('organizationId', v_row.tenant, 'id', cancel_transfer.transfer, 'from', v_row.from_location, 'to', v_row.to_location, 'status', 'cancelled'), 'stock-transfers/' || cancel_transfer.transfer::text, (v_row.tenant)::text, null, 'better-supabase/inventory');
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cap_allows (
  permission text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select case
    when jwt is null then true
    when better_supabase.interactive_only(cap_allows.permission)
      and not better_supabase.interactive_session() then false
    when jsonb_typeof(cap) = 'array'
      and not exists (
        select 1 from jsonb_array_elements_text(cap) c(key)
        where better_supabase.permission_matches(c.key, cap_allows.permission)
      ) then false
    when jsonb_typeof(jwt -> 'api_key') = 'object' then exists (
      select 1
      from jsonb_array_elements_text(case jsonb_typeof(jwt -> 'api_key' -> 'scopes')
          when 'array' then jwt -> 'api_key' -> 'scopes'
          else '[]'::jsonb
        end) s(scope)
      cross join lateral unnest(better_supabase.scope_permissions(s.scope)) k(key)
      where better_supabase.permission_matches(k.key, cap_allows.permission)
    )
    when coalesce(jwt ->> 'client_id', '') = ''
      and (jwt -> 'act' is null
        or (jsonb_typeof(jwt -> 'act') = 'object'
          and jwt -> 'act' ->> 'kind' in ('support', 'impersonation'))) then true
    else exists (
      select 1
      from unnest(case jsonb_typeof(jwt -> 'scope')
          when 'string' then regexp_split_to_array(btrim(jwt ->> 'scope'), '\s+')
          when 'array' then array(select jsonb_array_elements_text(jwt -> 'scope'))
          else '{}'::text[]
        end) s(scope)
      cross join lateral unnest(better_supabase.scope_permissions(s.scope)) k(key)
      where s.scope <> ''
        and better_supabase.permission_matches(k.key, cap_allows.permission)
    )
  end
  from (select auth.jwt() as jwt) as token
  cross join lateral (
    select coalesce(jwt -> 'bsb_permission_cap', jwt -> 'bs_permission_cap') as cap
  ) as capped
$function$;

CREATE OR REPLACE FUNCTION better_supabase.capture_ledger_hold (
  hold_id    uuid,
  to_account uuid,
  amount     bigint DEFAULT NULL::bigint,
  kind       text   DEFAULT 'ledger.capture'::text,
  memo       text   DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."ledger_holds"%rowtype;
begin
  select * into v_row from "better_supabase"."ledger_holds" x where x."id" = capture_ledger_hold.hold_id;
  if not found then
    raise exception 'ledger hold not found' using errcode = 'P0002', hint = 'LEDGER_HOLD_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'ledger.post'), false)) then
    raise exception 'not allowed to post ledger transactions' using errcode = '42501', hint = 'LEDGER_FORBIDDEN';
  end if;
  if exists (select 1 from "better_supabase"."ledger_accounts" x where x."id" = capture_ledger_hold.to_account and x."managed_by" is not null) and not coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then
    raise exception 'this account belongs to another block' using errcode = '55000', hint = 'LEDGER_ACCOUNT_MANAGED';
  end if;
  v_row := "better_supabase"."ledger_capture"(v_row."id", capture_ledger_hold.to_account, capture_ledger_hold.amount, capture_ledger_hold.kind, capture_ledger_hold.memo);
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'accountId', v_row."account_id", 'amount', v_row."amount"::text, 'status', v_row."status", 'referenceType', v_row."reference_type", 'referenceId', v_row."reference_id", 'expiresAt', v_row."expires_at", 'transactionId', v_row."transaction_id", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.care_decision_context (
  tenant       uuid,
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (care_decision_context.tenant is not null and coalesce(better_supabase.can('tenant', care_decision_context.tenant, 'clinical_decision_support.read'), false))) then
    raise exception 'not allowed to read the decision context' using errcode = '42501', hint = 'CARE_ALERT_FORBIDDEN';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (case care_decision_context.subject_type
      when 'message' then exists (select 1 from "better_supabase"."messages" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'conversation' then exists (select 1 from "better_supabase"."conversations" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'channel' then exists (select 1 from "better_supabase"."channels" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'company' then exists (select 1 from "better_supabase"."companies" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'person' then exists (select 1 from "better_supabase"."people" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'deal' then exists (select 1 from "better_supabase"."deals" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'course' then exists (select 1 from "better_supabase"."courses" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'post' then exists (select 1 from "better_supabase"."posts" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'activity' then exists (select 1 from "better_supabase"."activities" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'quote' then exists (select 1 from "better_supabase"."quotes" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'work_item' then exists (select 1 from "better_supabase"."work_items" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'employee' then exists (select 1 from "better_supabase"."employees" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'ledger_account' then exists (select 1 from "better_supabase"."ledger_accounts" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'invoice' then exists (select 1 from "better_supabase"."invoices" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'product' then exists (select 1 from "better_supabase"."products" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'product_variant' then exists (select 1 from "better_supabase"."product_variants" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'rfq' then exists (select 1 from "better_supabase"."rfqs" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'till' then exists (select 1 from "better_supabase"."tills" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'order' then exists (select 1 from "better_supabase"."orders" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'calendar_event' then exists (select 1 from "better_supabase"."calendar_events" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'booking' then exists (select 1 from "better_supabase"."bookings" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'asset' then exists (select 1 from "better_supabase"."assets" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'asset_location' then exists (select 1 from "better_supabase"."asset_locations" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'lease' then exists (select 1 from "better_supabase"."leases" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'expense_report' then exists (select 1 from "better_supabase"."expense_reports" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'expense_line' then exists (select 1 from "better_supabase"."expense_lines" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'donation_fund' then exists (select 1 from "better_supabase"."donation_funds" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'warranty_claim' then exists (select 1 from "better_supabase"."warranty_claims" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'work_order' then exists (select 1 from "better_supabase"."work_orders" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'shipment' then exists (select 1 from "better_supabase"."shipments" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'contract' then exists (select 1 from "better_supabase"."contracts" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'control' then exists (select 1 from "better_supabase"."controls" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'compliance_policy' then exists (select 1 from "better_supabase"."compliance_policies" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'qualification_type' then exists (select 1 from "better_supabase"."qualification_types" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'risk' then exists (select 1 from "better_supabase"."risks" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'case' then exists (select 1 from "better_supabase"."cases" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'inspection' then exists (select 1 from "better_supabase"."inspections" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'inspection_program' then exists (select 1 from "better_supabase"."inspection_programs" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'inspection_finding' then exists (select 1 from "better_supabase"."inspection_findings" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'form' then exists (select 1 from "better_supabase"."forms" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'meeting' then exists (select 1 from "better_supabase"."meetings" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'meeting_decision' then exists (select 1 from "better_supabase"."meeting_decisions" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'maintenance_plan' then exists (select 1 from "better_supabase"."maintenance_plans" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'dam_usage_right' then exists (select 1 from "better_supabase"."dam_usage_rights" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'lims_sample' then exists (select 1 from "better_supabase"."lims_samples" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'tax_code' then exists (select 1 from "better_supabase"."tax_codes" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'production_order' then exists (select 1 from "better_supabase"."production_orders" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'work_center' then exists (select 1 from "better_supabase"."work_centers" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'bank_account' then exists (select 1 from "better_supabase"."bank_accounts" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'care_plan' then exists (select 1 from "better_supabase"."care_plans" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'incident' then exists (select 1 from "better_supabase"."incidents" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'content_entry' then exists (select 1 from "better_supabase"."content_entries" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'document' then exists (select 1 from "better_supabase"."documents" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'customer' then exists (select 1 from "public"."customers" s where s."id" = (care_decision_context.subject_id)::uuid and s."organization_id"::text = care_decision_context.tenant::text)
      when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'organization' then exists (select 1 from "public"."organizations" s where s."id" = (care_decision_context.subject_id)::uuid and s."id"::text = care_decision_context.tenant::text)
      when 'application' then exists (select 1 from "better_supabase"."applications" s where s."id" = (care_decision_context.subject_id)::uuid and s."tenant_id"::text = care_decision_context.tenant::text)
      when 'change_request' then exists (select 1 from "public"."change_requests" s where s."id" = (care_decision_context.subject_id)::uuid and s."organization_id"::text = care_decision_context.tenant::text)
      when 'project' then exists (select 1 from "public"."projects" s where s."id" = (care_decision_context.subject_id)::uuid and s."organization_id"::text = care_decision_context.tenant::text)
      when 'task' then exists (select 1 from "public"."tasks" s where s."id" = (care_decision_context.subject_id)::uuid and s."organization_id"::text = care_decision_context.tenant::text)
      else false
    end and "better_supabase"."can_subject"(care_decision_context.subject_type, care_decision_context.subject_id, 'read'))) then
    raise exception 'the context needs a record of the organization' using errcode = '22023', hint = 'CARE_ALERT_SUBJECT_INVALID';
  end if;
  return jsonb_build_object(
    'organizationId', care_decision_context.tenant,
    'subjectType', care_decision_context.subject_type,
    'subjectId', care_decision_context.subject_id,
    'medications', coalesce((select jsonb_agg(jsonb_build_object('orderId', o."id", 'medicationId', o."medication_id", 'name', mx."name", 'codeSystem', mx."code_system", 'code', mx."code", 'dose', o."dose", 'doseUnit', o."dose_unit", 'asNeeded', o."as_needed", 'maxPerDay', o."max_per_day", 'schedule', o."schedule", 'startsOn', o."starts_on", 'endsOn', o."ends_on") order by mx."name", o."id")
      from "better_supabase"."medication_orders" o join "better_supabase"."medications" mx on mx."id" = o."medication_id" and mx."tenant_id" = o."tenant_id"
    where o."tenant_id" = care_decision_context.tenant and o."subject_type" = care_decision_context.subject_type and o."subject_id" = care_decision_context.subject_id
      and o."status" = 'active' and o."starts_on" <= (now() at time zone 'UTC')::date and (o."ends_on" is null or o."ends_on" >= (now() at time zone 'UTC')::date)), '[]'::jsonb),
    'observations', coalesce((select jsonb_agg(jsonb_build_object('key', q."key", 'code', q."code", 'codeSystem', q."code_system", 'unit', q."unit", 'valueNumber', q."value_number", 'valueText', q."value_text", 'valueCode', q."value_code", 'flag', q."flag", 'observedAt', q."observed_at") order by q."key")
      from (select distinct on (od."id") od."key", od."code", od."code_system", od."unit", ox."value_number", ox."value_text", ox."value_code", ox."flag", ox."observed_at"
        from "better_supabase"."observations" ox join "better_supabase"."observation_definitions" od on od."id" = ox."definition_id"
        where ox."tenant_id" = care_decision_context.tenant and ox."subject_type" = care_decision_context.subject_type and ox."subject_id" = care_decision_context.subject_id and ox."status" <> 'entered_in_error'
        order by od."id", ox."observed_at" desc) q), '[]'::jsonb),
    'consents', coalesce((select jsonb_agg(jsonb_build_object('purpose', pu."key", 'status', cx."status", 'scope', cx."scope", 'grantedAt', cx."granted_at", 'validUntil', cx."expires_at") order by pu."key")
      from "better_supabase"."consents" cx join "better_supabase"."consent_purposes" pu on pu."id" = cx."purpose_id"
      where cx."tenant_id" = care_decision_context.tenant and cx."subject_type" = care_decision_context.subject_type and cx."subject_id" = care_decision_context.subject_id and cx."status" = 'granted'), '[]'::jsonb),
    'carePlan', (select jsonb_build_object('id', px."id", 'title', px."title", 'version', px."version", 'reviewOn', px."review_on")
      from "better_supabase"."care_plans" px
      where px."tenant_id" = care_decision_context.tenant and px."subject_type" = care_decision_context.subject_type and px."subject_id" = care_decision_context.subject_id and px."status" = 'active'
      order by px."version" desc limit 1));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.care_plan_action_approved (
  action_id uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if exists (
    select 1 from "better_supabase"."care_plan_actions" w join "better_supabase"."care_plans" x on x."id" = w."plan_id"
    where w."id" = care_plan_action_approved.action_id and x."status" = 'active'
  ) then
    perform "better_supabase"."care_plan_action_start"(care_plan_action_approved.action_id);
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.care_plan_action_end (
  action_id uuid,
  reason    text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."care_plan_actions";
  v_plan "better_supabase"."care_plans";
begin
  update "better_supabase"."care_plan_actions" w set "status" = 'ended', "ended_at" = now(), "end_reason" = care_plan_action_end.reason, "updated_at" = now()
  where w."id" = care_plan_action_end.action_id and w."status" <> 'ended'
  returning * into v_row;
  if not found then
    return;
  end if;
  select * into v_plan from "better_supabase"."care_plans" x where x."id" = v_row."plan_id";
  perform "better_supabase".emit_event('care_plan_action.ended', jsonb_build_object('organizationId', v_plan."tenant_id", 'planId', v_plan."id", 'subjectType', v_plan."subject_type", 'subjectId', v_plan."subject_id") || jsonb_build_object('actionId', v_row."id", 'kind', v_row."kind", 'title', v_row."title", 'reason', v_row."end_reason"), 'care-plans/' || v_plan."id"::text, (v_plan."tenant_id")::text, null, 'better-supabase/care-plans');
  perform better_supabase.audit_event(
    event_type => 'care_plan_action.ended',
    category => 'data',
    target_type => 'care_plan',
    record_id => v_plan."id"::text,
    target_label => v_plan."title",
    summary => 'care plan action ended',
    tenant => (v_plan."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_plan."tenant_id", 'planId', v_plan."id", 'subjectType', v_plan."subject_type", 'subjectId', v_plan."subject_id") || jsonb_build_object('actionId', v_row."id", 'kind', v_row."kind", 'title', v_row."title", 'reason', v_row."end_reason")
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.care_plan_action_request_approval (
  action_id uuid
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."care_plan_actions";
  v_payload jsonb;
  v_approval jsonb;
begin
  select * into v_row from "better_supabase"."care_plan_actions" w where w."id" = care_plan_action_request_approval.action_id;
  v_payload := jsonb_build_object('planId', v_row."plan_id", 'kind', v_row."kind", 'measureKind', v_row."measure_kind", 'title', v_row."title");
  v_approval := "better_supabase"."open_approval"(
    v_row."tenant_id", 'care_plan_action', v_row."id"::text, 'start',
    coalesce("better_supabase"."approval_effective_policy"(v_row."tenant_id", 'care_plan_action', 'start', v_payload), '{"steps":[{"approvers":{"permission":"care_plans.manage"},"required":1}],"selfApproval":false,"expiresIn":null,"run":null}'::jsonb),
    null, v_payload
  );
  update "better_supabase"."care_plan_actions" w set "approval_id" = (v_approval ->> 'id')::uuid, "updated_at" = now()
  where w."id" = v_row."id";
  return (v_approval ->> 'id')::uuid;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.care_plan_action_start (
  action_id uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."care_plan_actions";
  v_plan "better_supabase"."care_plans";
  v_task jsonb;
begin
  update "better_supabase"."care_plan_actions" w set "status" = 'active', "started_at" = now(), "updated_at" = now()
  where w."id" = care_plan_action_start.action_id and w."status" = 'planned'
  returning * into v_row;
  if not found then
    return;
  end if;
  select * into v_plan from "better_supabase"."care_plans" x where x."id" = v_row."plan_id";
  if v_row."kind" = 'task' and v_row."task_id" is null then
    v_task := "better_supabase"."create_work_item"(v_row."tenant_id",
      jsonb_strip_nulls(jsonb_build_object('title', v_row."title", 'body', v_row."instructions")),
      case when v_plan."owner_id" is null then '{}'::uuid[] else array[v_plan."owner_id"] end);
    update "better_supabase"."care_plan_actions" w set "task_id" = (v_task ->> 'id')::uuid where w."id" = v_row."id";
  end if;
  perform "better_supabase".emit_event('care_plan_action.started', jsonb_build_object('organizationId', v_plan."tenant_id", 'planId', v_plan."id", 'subjectType', v_plan."subject_type", 'subjectId', v_plan."subject_id") || jsonb_build_object('actionId', v_row."id", 'kind', v_row."kind", 'title', v_row."title"), 'care-plans/' || v_plan."id"::text, (v_plan."tenant_id")::text, null, 'better-supabase/care-plans');
  perform better_supabase.audit_event(
    event_type => 'care_plan_action.started',
    category => 'data',
    target_type => 'care_plan',
    record_id => v_plan."id"::text,
    target_label => v_plan."title",
    summary => 'care plan action started',
    tenant => (v_plan."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_plan."tenant_id", 'planId', v_plan."id", 'subjectType', v_plan."subject_type", 'subjectId', v_plan."subject_id") || jsonb_build_object('actionId', v_row."id", 'kind', v_row."kind", 'title', v_row."title")
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.care_plan_json (
  plan_id uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'subjectType', x."subject_type", 'subjectId', x."subject_id", 'title', x."title", 'status', x."status", 'version', x."version", 'startsOn', x."starts_on", 'reviewOn', x."review_on", 'ownerId', x."owner_id", 'signatureRequestId', x."signature_id", 'agreedAt', x."agreed_at", 'publishedVersionId', x."published_version_id", 'publishedAt', x."published_at", 'publishedBy', x."published_by", 'archivedAt', x."archived_at", 'createdBy', x."created_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at") || jsonb_build_object('problems', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'planId', y."plan_id", 'codeSystem', y."code_system", 'code', y."code", 'title', y."title", 'description', y."description", 'status', y."status", 'rank', y."rank", 'createdAt', y."created_at", 'updatedAt', y."updated_at") || jsonb_build_object('goals', coalesce((select jsonb_agg(jsonb_build_object('id', z."id", 'planId', z."plan_id", 'problemId', z."problem_id", 'title', z."title", 'targetOn', z."target_on", 'status', z."status", 'measure', z."measure", 'rank', z."rank", 'createdAt', z."created_at", 'updatedAt', z."updated_at") || jsonb_build_object('actions', coalesce((select jsonb_agg(jsonb_build_object('id', w."id", 'planId', w."plan_id", 'goalId', w."goal_id", 'kind', w."kind", 'title', w."title", 'instructions', w."instructions", 'frequency', w."frequency", 'teamRole', w."team_role", 'measureKind', w."measure_kind", 'taskId', w."task_id", 'bookingSeriesId', w."booking_series_id", 'requiresApproval', w."requires_approval", 'approvalId', w."approval_id", 'reviewEvery', case when w."review_every" is null then null else format('P%sY%sM%sDT%sH%sM%sS', extract(year from w."review_every")::int, extract(month from w."review_every")::int, extract(day from w."review_every")::int, extract(hour from w."review_every")::int, extract(minute from w."review_every")::int, trim_scale(extract(second from w."review_every"))) end, 'reviewedAt', w."reviewed_at", 'startsOn', w."starts_on", 'endsOn', w."ends_on", 'status', w."status", 'startedAt', w."started_at", 'endedAt', w."ended_at", 'endReason', w."end_reason", 'rank', w."rank", 'createdAt', w."created_at", 'updatedAt', w."updated_at") order by w."rank", w."created_at") from "better_supabase"."care_plan_actions" w where w."tenant_id" = z."tenant_id" and w."plan_id" = z."plan_id" and w."goal_id" = z."id"), '[]'::jsonb)) order by z."rank", z."created_at") from "better_supabase"."care_plan_goals" z where z."tenant_id" = y."tenant_id" and z."plan_id" = y."plan_id" and z."problem_id" = y."id"), '[]'::jsonb)) order by y."rank", y."created_at") from "better_supabase"."care_plan_problems" y where y."tenant_id" = x."tenant_id" and y."plan_id" = x."id"), '[]'::jsonb), 'evaluations', coalesce((select jsonb_agg(jsonb_build_object('id', v."id", 'planId', v."plan_id", 'goalId', v."goal_id", 'evaluatedAt', v."evaluated_at", 'status', v."status", 'outcome', v."outcome", 'submissionId', v."submission_id", 'authorId', v."author_id") order by v."evaluated_at" desc) from "better_supabase"."care_plan_evaluations" v where v."tenant_id" = x."tenant_id" and v."plan_id" = x."id"), '[]'::jsonb))
  from "better_supabase"."care_plans" x where x."id" = care_plan_json.plan_id
$function$;

CREATE OR REPLACE FUNCTION better_supabase.care_plan_signature_settled()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."care_plans";
begin
  for v_row in
    update "better_supabase"."care_plans" x set "agreed_at" = now(), "updated_at" = now()
    where x."signature_id" = new."id"
    returning *
  loop
    perform "better_supabase".emit_event('care_plan.agreed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'title', v_row."title", 'status', v_row."status", 'version', v_row."version", 'signatureRequestId', v_row."signature_id"), 'care-plans/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/care-plans');
  perform better_supabase.audit_event(
    event_type => 'care_plan.agreed',
    category => 'data',
    target_type => 'care_plan',
    record_id => v_row."id"::text,
    target_label => v_row."title",
    summary => 'care plan agreed',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'title', v_row."title", 'status', v_row."status", 'version', v_row."version", 'signatureRequestId', v_row."signature_id")
  );
  end loop;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.care_plans_subject_merge (
  subject_table text,
  keep          text,
  drop          text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_type text;
  v_keep text := keep;
  v_drop text := drop;
begin
  for v_type in select unnest(case subject_table when 'better_supabase.messages' then array['message'] when 'better_supabase.conversations' then array['conversation'] when 'better_supabase.channels' then array['channel'] when 'better_supabase.companies' then array['company'] when 'better_supabase.people' then array['person'] when 'better_supabase.deals' then array['deal'] when 'better_supabase.courses' then array['course'] when 'better_supabase.posts' then array['post'] when 'better_supabase.activities' then array['activity'] when 'better_supabase.quotes' then array['quote'] when 'better_supabase.work_items' then array['work_item'] when 'better_supabase.employees' then array['employee'] when 'better_supabase.ledger_accounts' then array['ledger_account'] when 'better_supabase.invoices' then array['invoice'] when 'better_supabase.products' then array['product'] when 'better_supabase.product_variants' then array['product_variant'] when 'better_supabase.rfqs' then array['rfq'] when 'better_supabase.tills' then array['till'] when 'better_supabase.orders' then array['order'] when 'better_supabase.calendar_events' then array['calendar_event'] when 'better_supabase.bookings' then array['booking'] when 'better_supabase.assets' then array['asset'] when 'better_supabase.asset_locations' then array['asset_location'] when 'better_supabase.leases' then array['lease'] when 'better_supabase.expense_reports' then array['expense_report'] when 'better_supabase.expense_lines' then array['expense_line'] when 'better_supabase.donation_funds' then array['donation_fund'] when 'better_supabase.warranty_claims' then array['warranty_claim'] when 'better_supabase.work_orders' then array['work_order'] when 'better_supabase.shipments' then array['shipment'] when 'better_supabase.contracts' then array['contract'] when 'better_supabase.controls' then array['control'] when 'better_supabase.compliance_policies' then array['compliance_policy'] when 'better_supabase.qualification_types' then array['qualification_type'] when 'better_supabase.risks' then array['risk'] when 'better_supabase.cases' then array['case'] when 'better_supabase.inspections' then array['inspection'] when 'better_supabase.inspection_programs' then array['inspection_program'] when 'better_supabase.inspection_findings' then array['inspection_finding'] when 'better_supabase.forms' then array['form'] when 'better_supabase.meetings' then array['meeting'] when 'better_supabase.meeting_decisions' then array['meeting_decision'] when 'better_supabase.maintenance_plans' then array['maintenance_plan'] when 'better_supabase.dam_usage_rights' then array['dam_usage_right'] when 'better_supabase.lims_samples' then array['lims_sample'] when 'better_supabase.tax_codes' then array['tax_code'] when 'better_supabase.production_orders' then array['production_order'] when 'better_supabase.work_centers' then array['work_center'] when 'better_supabase.bank_accounts' then array['bank_account'] when 'better_supabase.care_plans' then array['care_plan'] when 'better_supabase.incidents' then array['incident'] when 'better_supabase.content_entries' then array['content_entry'] when 'better_supabase.documents' then array['document'] when 'public.customers' then array['customer'] when 'better_supabase.drive_nodes' then array['drive_node'] when 'public.organizations' then array['organization'] when 'better_supabase.applications' then array['application'] when 'public.change_requests' then array['change_request'] when 'public.projects' then array['project'] when 'public.tasks' then array['task'] else '{}'::text[] end) loop
    update "better_supabase"."care_plans" x set "status" = 'archived', "archived_at" = now(), "updated_at" = now()
    where x."subject_type" = v_type and x."subject_id" = v_drop and x."status" = 'active'
      and exists (select 1 from "better_supabase"."care_plans" y where y."subject_type" = v_type and y."subject_id" = v_keep and y."status" = 'active');
    update "better_supabase"."care_plans" x set "subject_id" = v_keep where x."subject_type" = v_type and x."subject_id" = v_drop;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cart_discounts (
  p_cart  uuid,
  p_lines jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_cart record;
  v_promo record;
  v_reason text;
  v_eligible text[];
  v_base bigint;
  v_rem jsonb;
  v_disc jsonb := '{}';
  v_applied jsonb := '[]';
  v_problems jsonb := '[]';
  v_free boolean := false;
  v_stackable boolean := true;
  v_amount bigint;
  v_left bigint;
  v_share bigint;
  v_line_rem bigint;
  v_id text;
begin
  select x."tenant_id" as tenant, x."user_id" as owner, x."currency" as currency, x."email" as email
  into v_cart from "better_supabase"."carts" x where x."id" = p_cart;
  select coalesce(jsonb_object_agg(e ->> 'id', (e ->> 'subtotal')::bigint), '{}') into v_rem
  from jsonb_array_elements(p_lines) e;
  for v_promo in
    select x."id" as id, x."name" as name, x."kind" as kind, x."percent" as percent,
      x."currency" as currency, x."amount" as amount, x."min_subtotal" as min_subtotal,
      x."scope" as scope, x."target_ids" as targets, x."usage_limit" as usage_limit,
      x."per_customer_limit" as per_customer_limit, x."redemptions" as used, x."stackable" as stackable,
      x."automatic" as automatic,
      (x."active" and (x."starts_at" is null or x."starts_at" <= now())
        and (x."ends_at" is null or x."ends_at" > now())) as live,
      code.id as code_id, code.code as code, code.usage_limit as code_limit, code.used as code_used
    from "better_supabase"."promotions" x
    left join lateral (
      select k."id" as id, k."code" as code, k."usage_limit" as usage_limit, k."redemptions" as used
      from "better_supabase"."cart_promotion_codes" y join "better_supabase"."promotion_codes" k on k."id" = y."code_id"
      where y."cart_id" = p_cart and k."promotion_id" = x."id"
      order by y."created_at", k."id"
      limit 1
    ) code on true
    where x."tenant_id" = v_cart.tenant and (code.id is not null or (x."automatic" and x."active"))
    order by x."priority" desc, x."created_at", x."id"
  loop
    v_reason := null;
    if not v_promo.live then
      v_reason := 'expired';
    elsif (v_promo.usage_limit is not null and v_promo.used >= v_promo.usage_limit)
      or (v_promo.code_limit is not null and v_promo.code_used >= v_promo.code_limit)
      or (v_promo.per_customer_limit is not null
        and (select count(*) from "better_supabase"."promotion_redemptions" y where y."promotion_id" = v_promo.id and y."status" = 'redeemed'
      and (y."customer_id" = v_cart.owner or (v_cart.email is not null and lower(y."email") = lower(v_cart.email)))) >= v_promo.per_customer_limit) then
      v_reason := 'limit_reached';
    elsif v_promo.currency is not null and v_promo.currency <> v_cart.currency then
      v_reason := 'currency';
    else
      select coalesce(array_agg(e ->> 'id' order by n), '{}'), coalesce(sum((e ->> 'subtotal')::bigint), 0)
      into v_eligible, v_base
      from jsonb_array_elements(p_lines) with ordinality as l(e, n)
      where v_promo.scope = 'order'
      or (v_promo.scope = 'products' and (e ->> 'productId')::uuid = any (v_promo.targets))
      or (v_promo.scope = 'categories' and exists (
      with recursive d (id) as (
        select unnest(v_promo.targets)
        union
        select x."id" from "better_supabase"."catalog_categories" x join d on x."parent_id" = d.id
      )
      select 1 from "better_supabase"."product_categories" y where y."product_id" = (e ->> 'productId')::uuid and y."category_id" in (select id from d)
    ))
      or (v_promo.scope = 'collections' and exists (select 1 from "better_supabase"."collection_products" y where y."product_id" = (e ->> 'productId')::uuid and y."collection_id" = any (v_promo.targets)));
      if cardinality(v_eligible) = 0 then
        v_reason := 'not_applicable';
      elsif v_promo.min_subtotal is not null and v_base < v_promo.min_subtotal then
        v_reason := 'min_subtotal';
      elsif jsonb_array_length(v_applied) > 0 and not (v_stackable and v_promo.stackable) then
        v_reason := 'not_combinable';
      end if;
    end if;
    if v_reason is not null then
      if v_promo.code_id is not null then
        v_problems := v_problems || jsonb_build_array(jsonb_build_object('problem', 'promotion_unavailable',
          'promotionId', v_promo.id, 'code', v_promo.code, 'reason', v_reason));
      end if;
      continue;
    end if;
    v_amount := 0;
    if v_promo.kind = 'percentage' then
      foreach v_id in array v_eligible loop
        v_line_rem := (v_rem ->> v_id)::bigint;
        v_share := least("better_supabase"."round_half_even"(v_line_rem * v_promo.percent / 100), v_line_rem);
        v_rem := jsonb_set(v_rem, array[v_id], to_jsonb(v_line_rem - v_share));
        v_disc := jsonb_set(v_disc, array[v_id], to_jsonb(coalesce((v_disc ->> v_id)::bigint, 0) + v_share));
        v_amount := v_amount + v_share;
      end loop;
    elsif v_promo.kind = 'fixed' then
      select coalesce(sum((v_rem ->> e)::bigint), 0) into v_base from unnest(v_eligible) e;
      v_left := least(v_promo.amount, v_base);
      if v_base > 0 then
        foreach v_id in array v_eligible loop
          v_line_rem := (v_rem ->> v_id)::bigint;
          v_share := floor(least(v_promo.amount, v_base)::numeric * v_line_rem / v_base)::bigint;
          v_rem := jsonb_set(v_rem, array[v_id], to_jsonb(v_line_rem - v_share));
          v_disc := jsonb_set(v_disc, array[v_id], to_jsonb(coalesce((v_disc ->> v_id)::bigint, 0) + v_share));
          v_left := v_left - v_share;
        end loop;
        foreach v_id in array v_eligible loop
          exit when v_left = 0;
          if (v_rem ->> v_id)::bigint > 0 then
            v_rem := jsonb_set(v_rem, array[v_id], to_jsonb((v_rem ->> v_id)::bigint - 1));
            v_disc := jsonb_set(v_disc, array[v_id], to_jsonb(coalesce((v_disc ->> v_id)::bigint, 0) + 1));
            v_left := v_left - 1;
          end if;
        end loop;
        v_amount := least(v_promo.amount, v_base);
      end if;
    else
      v_free := true;
    end if;
    v_stackable := v_stackable and v_promo.stackable;
    v_applied := v_applied || jsonb_build_array(jsonb_build_object('promotionId', v_promo.id, 'name', v_promo.name,
      'kind', v_promo.kind, 'codeId', v_promo.code_id, 'code', v_promo.code, 'amount', v_amount::text));
  end loop;
  select coalesce(jsonb_object_agg(key, value #>> '{}'), '{}') into v_disc from jsonb_each(v_disc);
  return jsonb_build_object('lines', v_disc, 'applied', v_applied, 'freeShipping', v_free, 'problems', v_problems);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.cart_totals (
  p_cart uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_cart record;
  v_line record;
  v_rate record;
  v_amount bigint;
  v_lines jsonb := '[]';
  v_problems jsonb := '[]';
  v_subtotal bigint := 0;
  v_discount bigint := 0;
  v_shipping bigint := 0;
  v_weight bigint := 0;
  v_ships boolean := false;
  v_free boolean := false;
  v_promo jsonb;
  v_discounts jsonb := '{}';
  v_applied jsonb := '[]';
  v_snapshot jsonb;
  v_country text;
begin
  select x."tenant_id" as tenant, x."currency" as currency, x."price_list_id" as price_list,
    x."shipping_address" as shipping_address, x."shipping_rate_id" as shipping_rate,
    x."user_id" as owner, x."status" as status, x."email" as email, x."billing_address" as billing_address
  into v_cart from "better_supabase"."carts" x where x."id" = p_cart;
  for v_line in
    select l."id" as id, l."variant_id" as variant, l."quantity" as quantity, l."unit_amount" as unit_amount,
      cv."sku" as sku, concat_ws(' / ', cp."title", nullif(cv."title", '')) as title, cp."id" as product, cp."status" as status,
      cp."kind" as kind, cv."weight_grams" as weight
    from "better_supabase"."cart_lines" l
    join "better_supabase"."product_variants" cv on cv."id" = l."variant_id"
    join "better_supabase"."products" cp on cp."id" = cv."product_id"
    where l."cart_id" = p_cart
    order by l."created_at", l."id"
  loop
    v_amount := ("better_supabase"."variant_price"(v_line.variant, v_cart.currency, v_cart.price_list, null) ->> 'amount')::bigint;
    if v_line.status <> 'active' or v_amount is null then
      v_problems := v_problems || jsonb_build_array(jsonb_build_object('lineId', v_line.id, 'variantId', v_line.variant,
        'problem', case when v_line.status <> 'active' then 'unavailable' else 'unpriced' end));
      continue;
    end if;
    if v_line.unit_amount is distinct from v_amount then
      update "better_supabase"."cart_lines" x set "unit_amount" = v_amount, "updated_at" = now() where x."id" = v_line.id;
    end if;
    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'id', v_line.id, 'variantId', v_line.variant, 'productId', v_line.product, 'sku', v_line.sku, 'title', v_line.title,
      'quantity', v_line.quantity, 'unitAmount', v_amount::text, 'previousUnitAmount', v_line.unit_amount::text,
      'subtotal', (v_amount * v_line.quantity)::text, 'requiresShipping', v_line.kind = 'physical'));
    v_subtotal := v_subtotal + v_amount * v_line.quantity;
    if v_line.kind = 'physical' then
      v_ships := true;
      v_weight := v_weight + coalesce(v_line.weight, 0)::bigint * v_line.quantity;
    end if;
  end loop;
  if jsonb_array_length(v_lines) > 0 then
    v_promo := "better_supabase"."cart_discounts"(p_cart, v_lines);
    v_discounts := coalesce(v_promo -> 'lines', '{}'::jsonb);
    v_applied := coalesce(v_promo -> 'applied', '[]'::jsonb);
    v_free := coalesce((v_promo ->> 'freeShipping')::boolean, false);
    v_problems := v_problems || coalesce(v_promo -> 'problems', '[]'::jsonb);
  end if;
  select coalesce(jsonb_agg(e.l || jsonb_build_object(
      'discount', coalesce(v_discounts ->> (e.l ->> 'id'), '0'),
      'total', ((e.l ->> 'subtotal')::bigint - coalesce((v_discounts ->> (e.l ->> 'id'))::bigint, 0))::text) order by e.n), '[]'::jsonb),
    coalesce(sum(coalesce((v_discounts ->> (e.l ->> 'id'))::bigint, 0)), 0)
  into v_lines, v_discount
  from jsonb_array_elements(v_lines) with ordinality as e(l, n);
  v_country := v_cart.shipping_address ->> 'country';
  if v_ships and v_cart.shipping_rate is not null then
    select x."id" as id, x."name" as name, x."countries" as countries, x."kind" as kind,
      x."amount" as amount, x."amount_per_kg" as per_kg, x."free_over" as free_over
    into v_rate from "better_supabase"."order_shipping_rates" x
    where x."id" = v_cart.shipping_rate and x."active" and x."currency" = v_cart.currency;
    if not found or (cardinality(v_rate.countries) > 0 and (v_country is null or not v_country = any (v_rate.countries))) then
      v_problems := v_problems || jsonb_build_array(jsonb_build_object('problem', 'shipping_unavailable'));
    else
      v_shipping := v_rate.amount + case when v_rate.kind = 'weight' then (v_rate.per_kg * v_weight + 999) / 1000 else 0 end;
      if v_free or (v_rate.free_over is not null and v_subtotal - v_discount >= v_rate.free_over) then
        v_shipping := 0;
      end if;
      v_snapshot := jsonb_build_object('rateId', v_rate.id, 'name', v_rate.name, 'amount', v_shipping::text);
    end if;
  elsif v_ships and exists (
    select 1 from "better_supabase"."order_shipping_rates" x
    where x."tenant_id" = v_cart.tenant and x."active" and x."currency" = v_cart.currency
  ) then
    v_problems := v_problems || jsonb_build_array(jsonb_build_object('problem', 'shipping_required'));
  end if;
  return jsonb_build_object(
    'cartId', p_cart, 'organizationId', v_cart.tenant, 'customerId', v_cart.owner, 'status', v_cart.status,
    'email', v_cart.email, 'shippingAddress', v_cart.shipping_address, 'billingAddress', v_cart.billing_address,
    'currency', v_cart.currency, 'lines', v_lines,
    'subtotal', v_subtotal::text, 'discountTotal', v_discount::text, 'shippingTotal', v_shipping::text,
    'total', (v_subtotal - v_discount + v_shipping)::text, 'requiresShipping', v_ships,
    'weightGrams', v_weight::text, 'shipping', v_snapshot, 'promotions', v_applied, 'problems', v_problems);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.case_blockers_of (
  target better_supabase.cases
)
  RETURNS text[]
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_kind "better_supabase"."case_kinds";
  v_blockers text[] := '{}';
  v_policy jsonb;
begin
  select * into v_kind from "better_supabase"."case_kinds" y where y."id" = case_blockers_of.target."kind_id";
  if v_kind."requires_root_cause" and coalesce(trim(case_blockers_of.target."root_cause"), '') = '' then
    v_blockers := v_blockers || 'CASE_ROOT_CAUSE_REQUIRED'::text;
  end if;
  if v_kind."requires_actions" and not exists (
    select 1 from "better_supabase"."case_actions" x where x."case_id" = case_blockers_of.target."id" and x."required"
  ) then
    v_blockers := v_blockers || 'CASE_ACTIONS_REQUIRED'::text;
  end if;
  if exists (
    select 1 from "better_supabase"."case_actions" x
    join "better_supabase"."work_items" i on i."id" = x."task_id"
    where x."case_id" = case_blockers_of.target."id" and x."required"
      and i."state" not in ('completed', 'canceled')
  ) then
    v_blockers := v_blockers || 'CASE_ACTIONS_OPEN'::text;
  end if;
  if v_kind."requires_effectiveness" and case_blockers_of.target."effective" is not true then
    v_blockers := v_blockers || 'CASE_EFFECTIVENESS_REQUIRED'::text;
  end if;
  if v_kind."requires_revisions" and exists (
    select 1 from "better_supabase"."relations" r
    join "better_supabase"."drive_nodes" n on n."id"::text = r."target_id"
    where r."kind" = 'affects'
      and r."source_type" = 'case'
      and r."source_id" = case_blockers_of.target."id"::text
      and r."target_type" = 'drive_node'
      and (n."effective_at" is null or n."effective_at" <= case_blockers_of.target."created_at")
  ) then
    v_blockers := v_blockers || 'CASE_DOCUMENTS_NOT_REVISED'::text;
  end if;
  v_policy := "better_supabase"."approval_effective_policy"(case_blockers_of.target."tenant_id", 'case', 'close',
    jsonb_build_object('caseId', case_blockers_of.target."id", 'kind', v_kind."key", 'severity', case_blockers_of.target."severity"));
  if (coalesce(v_policy ->> 'mode', 'authorize') = 'confirm' or jsonb_array_length(coalesce(v_policy -> 'steps', '[]'::jsonb)) > 0)
    and not exists (
      select 1 from "better_supabase"."approval_requests" r
      where r."subject_type" = 'case'
        and r."subject_id" = case_blockers_of.target."id"::text
        and r."action" = 'close'
        and r."status" = 'approved'
    ) then
    v_blockers := v_blockers || 'CASE_APPROVAL_REQUIRED'::text;
  end if;
  return v_blockers;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.case_close_approved (
  case_id uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."cases";
  v_stage uuid;
begin
  select * into v_row from "better_supabase"."cases" x where x."id" = case_close_approved.case_id for update;
  if not found or v_row."status" <> 'open' or cardinality("better_supabase"."case_blockers_of"(v_row)) > 0 then
    return;
  end if;
  select s."id" into v_stage from "better_supabase"."pipeline_stages" s
  where s."pipeline_id" = v_row."pipeline_id" and s."outcome" = 'success' and s."archived_at" is null
  order by s."rank" collate "C"
  limit 1;
  if v_stage is not null then
    update "better_supabase"."cases" x set "stage_id" = v_stage where x."id" = v_row."id";
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.case_close_blockers (
  case_id uuid
)
  RETURNS text[]
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."cases";
begin
  select * into v_row from "better_supabase"."cases" x where x."id" = case_close_blockers.case_id;
  if not found then
    raise exception 'no such case' using errcode = 'P0002', hint = 'CASE_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'cases.read'), false))) then
    raise exception 'not allowed to read cases' using errcode = '42501', hint = 'CASE_FORBIDDEN';
  end if;
  return "better_supabase"."case_blockers_of"(v_row);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.case_from_submission (
  submission_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_tenant uuid;
  v_respondent uuid;
  v_answers jsonb;
  v_key text;
  v_kind "better_supabase"."case_kinds";
  v_input jsonb;
  v_row "better_supabase"."cases";
begin
  select x."tenant_id", x."respondent_id", coalesce(x."answers", '{}'::jsonb)
    into v_tenant, v_respondent, v_answers
  from "better_supabase"."form_submissions" x
  where x."id" = case_from_submission.submission_id;
  if not found then
    raise exception 'no such form submission' using errcode = 'P0002', hint = 'CASE_INVALID';
  end if;
  v_key := coalesce(nullif(v_answers ->> 'kind', ''), 'complaint');
  perform "better_supabase"."ensure_case_kinds"(v_tenant);
  select * into v_kind from "better_supabase"."case_kinds" x
  where x."tenant_id" = v_tenant and x."key" = v_key and x."archived_at" is null;
  if not found then
    raise exception 'no such case kind in this organization' using errcode = 'P0002', hint = 'CASE_KIND_NOT_FOUND';
  end if;
  v_input := jsonb_strip_nulls(jsonb_build_object(
    'title', coalesce(nullif(trim(v_answers ->> 'title'), ''), v_kind."name" || ' from a form'),
    'description', nullif(trim(v_answers ->> 'description'), ''),
    'severity', case when (v_answers ->> 'severity') = any (array['low', 'medium', 'high', 'critical']::text[]) then v_answers ->> 'severity' end,
    'source', case
      when (v_answers ->> 'source') = any (array['internal', 'customer', 'supplier', 'inspection', 'regulator', 'employee', 'anonymous']::text[]) then v_answers ->> 'source'
      when v_respondent is null and 'anonymous' = any (array['internal', 'customer', 'supplier', 'inspection', 'regulator', 'employee', 'anonymous']::text[]) then 'anonymous'
      when 'customer' = any (array['internal', 'customer', 'supplier', 'inspection', 'regulator', 'employee', 'anonymous']::text[]) then 'customer'
      else (array['internal', 'customer', 'supplier', 'inspection', 'regulator', 'employee', 'anonymous']::text[])[1]
    end,
    'occurredAt', v_answers ->> 'occurredAt',
    'reporterContact', nullif(jsonb_strip_nulls(jsonb_build_object(
      'name', nullif(trim(v_answers ->> 'name'), ''),
      'email', nullif(trim(v_answers ->> 'email'), ''),
      'phone', nullif(trim(v_answers ->> 'phone'), '')
    )), '{}'::jsonb)
  ));
  v_row := "better_supabase"."open_case_as"(v_kind."id", v_input, v_respondent);
  return jsonb_build_object('subjectType', 'case', 'subjectId', v_row."id"::text);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.case_stats (
  tenant   uuid,
  kind     text DEFAULT NULL::text,
  since    date DEFAULT NULL::date,
  until    date DEFAULT NULL::date,
  group_by text DEFAULT 'severity'::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (case_stats.tenant is not null and coalesce(better_supabase.can('tenant', case_stats.tenant, 'cases.read'), false))) then
    raise exception 'not allowed to read cases' using errcode = '42501', hint = 'CASE_FORBIDDEN';
  end if;
  if coalesce(case_stats.group_by, '') not in ('severity', 'source', 'stage', 'kind', 'root_cause') then
    raise exception 'group_by is severity, source, stage, kind or root_cause' using errcode = '22023', hint = 'CASE_INVALID';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('key', g.key, 'count', g.count) order by g.count desc, g.key nulls last)
    from (
      select case case_stats.group_by
          when 'severity' then x."severity"
          when 'source' then x."source"
          when 'stage' then (select s."key" from "better_supabase"."pipeline_stages" s where s."id" = x."stage_id")
          when 'kind' then y."key"
          else nullif(lower(trim(x."root_cause")), '')
        end as key,
        count(*) as count
      from "better_supabase"."cases" x
      join "better_supabase"."case_kinds" y on y."id" = x."kind_id"
      where x."tenant_id" = case_stats.tenant
        and x."archived_at" is null
        and (case_stats.kind is null or y."key" = case_stats.kind)
        and (case_stats.since is null or x."created_at" >= case_stats.since)
        and (case_stats.until is null or x."created_at" < case_stats.until + 1)
      group by 1
    ) g
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chain (
  target        regclass,
  tenant_column text     DEFAULT NULL::text
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_tenant text := coalesce(tenant_column, (
    select a.attname::text from pg_catalog.pg_attribute a
    where a.attrelid = target and a.attname = '"tenant_id"' and not a.attisdropped
  ), '');
begin
  if (select count(*) from pg_catalog.pg_attribute a
      where a.attrelid = target and a.attname in ('chain_seq', 'prev_hash', 'row_hash') and not a.attisdropped) <> 3 then
    raise exception 'chain needs the columns chain_seq bigint, prev_hash bytea and row_hash bytea on %', target
      using errcode = '42703', hint = 'CHAIN_COLUMNS';
  end if;
  execute format('drop trigger if exists bsb_chain on %s', target);
  execute format('create trigger bsb_chain before insert on %s for each row execute function better_supabase.chain_link(%L)', target, v_tenant);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chain_heads (
  target        regclass,
  tenant_column text     DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant text := case when tenant_column is null then 'null::text' else format('t.%I::text', tenant_column) end;
  v_heads jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'Only the service role reads chain heads' using errcode = '42501', hint = 'CHAIN_FORBIDDEN';
  end if;
  execute format($q$
    select coalesce(jsonb_agg(jsonb_build_object('tenant', h.tenant, 'seq', h.chain_seq, 'hash', encode(h.row_hash, 'hex')) order by h.tenant nulls first), '[]'::jsonb)
    from (
      select distinct on (%1$s) %1$s as tenant, t.chain_seq, t.row_hash
      from %2$s t where t.chain_seq is not null
      order by %1$s, t.chain_seq desc
    ) h
    where not exists (
      select 1 from better_supabase.chain_checkpoints k
      where k.table_name = %3$L and k.tenant is not distinct from h.tenant and k.chain_seq >= h.chain_seq
    )
  $q$, v_tenant, target, target::text) into v_heads;
  return v_heads;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chain_link()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  SET "TimeZone" TO 'UTC'
  AS $function$
declare
  v_column text := nullif(tg_argv[0], '');
  v_prev record;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('better_supabase.chain:' || tg_relid::text),
    pg_catalog.hashtext(coalesce(case when v_column is null then '' else pg_catalog.to_jsonb(new) ->> v_column end, ''))
  );
  if v_column is null then
    execute format('select p.chain_seq, p.row_hash from %s p where p.chain_seq is not null order by p.chain_seq desc limit 1', tg_relid::regclass)
      into v_prev;
  elsif pg_catalog.to_jsonb(new) ->> v_column is null then
    execute format('select p.chain_seq, p.row_hash from %s p where p.%I is null and p.chain_seq is not null order by p.chain_seq desc limit 1', tg_relid::regclass, v_column)
      into v_prev;
  else
    execute format('select p.chain_seq, p.row_hash from %s p where p.%I = ($1).%I and p.chain_seq is not null order by p.chain_seq desc limit 1', tg_relid::regclass, v_column, v_column)
      into v_prev using new;
  end if;
  new.chain_seq := coalesce(v_prev.chain_seq, 0) + 1;
  new.prev_hash := v_prev.row_hash;
  new.row_hash := better_supabase.chain_row_hash(pg_catalog.to_jsonb(new), v_prev.row_hash);
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chain_proof (
  target        regclass,
  tenant_column text,
  tenant        text,
  seq           bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  SET "TimeZone" TO 'UTC'
  AS $function$
declare
  v_where text := case
    when tenant_column is null then 'true'
    when tenant is null then format('t.%I is null', tenant_column)
    else format('t.%I::text = %L', tenant_column, tenant)
  end;
  v_checkpoint record;
  v_entries jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'Only the service role builds chain proofs' using errcode = '42501', hint = 'CHAIN_FORBIDDEN';
  end if;
  select k.chain_seq, k.row_hash, k.key_id, k.signature into v_checkpoint from better_supabase.chain_checkpoints k
  where k.table_name = target::text and k.tenant is not distinct from chain_proof.tenant and k.chain_seq >= chain_proof.seq
  order by k.chain_seq limit 1;
  execute format($q$
    select coalesce(jsonb_agg(jsonb_build_object(
      'seq', t.chain_seq, 'prevHash', encode(t.prev_hash, 'hex'), 'rowHash', encode(t.row_hash, 'hex'), 'entry', pg_catalog.to_jsonb(t),
      'hashed', pg_catalog.jsonb_strip_nulls(pg_catalog.to_jsonb(t) - 'prev_hash' - 'row_hash')::text
    ) order by t.chain_seq), '[]'::jsonb)
    from %1$s t where %2$s and t.chain_seq between $1 and coalesce($2, t.chain_seq)
  $q$, target, v_where) into v_entries using seq, v_checkpoint.chain_seq;
  return jsonb_build_object(
    'table', target::text,
    'tenant', tenant,
    'entries', v_entries,
    'checkpoint', case when v_checkpoint.chain_seq is null then null else jsonb_build_object(
      'seq', v_checkpoint.chain_seq, 'hash', encode(v_checkpoint.row_hash, 'hex'),
      'keyId', v_checkpoint.key_id, 'signature', v_checkpoint.signature) end
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chain_row_hash (
  entry jsonb,
  prev  bytea
)
  RETURNS bytea
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select pg_catalog.sha256(
    coalesce(prev, ''::bytea)
    || pg_catalog.convert_to(pg_catalog.jsonb_strip_nulls(entry - 'prev_hash' - 'row_hash')::text, 'UTF8')
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.change_booking (
  booking      uuid,
  to_status    text,
  reason       text,
  access_token text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_booking "better_supabase"."bookings"%rowtype;
  v_id uuid := change_booking.booking;
  v_calendar uuid;
  v_tz text;
  v_title text;
  v_event uuid;
begin
  select * into v_booking from "better_supabase"."bookings" bk where bk."id" = v_id for update;
  if not found then
    raise exception 'booking not found' using errcode = 'P0002', hint = 'BOOKING_NOT_FOUND';
  end if;
  if not (
    (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_booking."tenant_id", 'bookings.manage'), false))
    or (change_booking.access_token is not null and v_booking."access_hash" = encode(extensions.digest(convert_to(change_booking.access_token, 'utf8'), 'sha256'), 'hex'))
    or (change_booking.access_token is null and coalesce(v_booking."customer_id" = auth.uid(), false) and (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_booking."tenant_id", 'bookings.create'), false)))
  ) then
    raise exception 'not allowed to change this booking' using errcode = '42501', hint = 'BOOKING_FORBIDDEN';
  end if;
  if change_booking.to_status = 'confirmed' then
    if v_booking."status" = 'confirmed' then
      return jsonb_build_object('id', v_booking."id", 'resourceId', v_booking."resource_id", 'serviceId', v_booking."service_id", 'seat', v_booking."seat", 'startsAt', lower(v_booking."during"), 'endsAt', upper(v_booking."during"), 'status', v_booking."status", 'holdExpiresAt', v_booking."hold_expires_at", 'customerName', v_booking."customer_name", 'customerEmail', v_booking."customer_email", 'customerUserId', v_booking."customer_id", 'notes', v_booking."notes", 'seriesId', v_booking."series_id", 'createdAt', v_booking."created_at", 'cancelledAt', v_booking."cancelled_at", 'cancelReason', v_booking."cancel_reason");
    end if;
    if v_booking."status" <> 'hold' or v_booking."hold_expires_at" <= now() then
      raise exception 'the hold has expired or was cancelled' using errcode = '22023', hint = 'BOOKING_HOLD_EXPIRED';
    end if;
    update "better_supabase"."bookings" bk set "status" = 'confirmed', "hold_expires_at" = null, "updated_at" = now()
    where bk."id" = v_id returning * into v_booking;
    select r."calendar_id", r."tz", sv."name" into v_calendar, v_tz, v_title
  from "better_supabase"."booking_resources" r join "better_supabase"."booking_services" sv on sv."id" = v_booking."service_id"
  where r."id" = v_booking."resource_id";
  if v_calendar is not null then
    insert into "better_supabase"."calendar_events" ("tenant_id", "calendar_id", "uid", "title", "starts_at", "ends_at", "tz", "status", "subject_type", "subject_id")
    values (v_booking."tenant_id", v_calendar, 'booking-' || v_booking."id"::text, coalesce(v_booking."customer_name", v_title), lower(v_booking."during"), upper(v_booking."during"), v_tz, 'confirmed', 'booking', v_booking."id"::text)
    on conflict ("calendar_id", "uid", "original_starts_at") do update set "starts_at" = excluded."starts_at", "ends_at" = excluded."ends_at"
    returning "id" into v_event;
    update "better_supabase"."bookings" set "calendar_event_id" = v_event where "id" = v_booking."id";
  end if;
    delete from "better_supabase"."reminders" where "subject_type" = 'booking' and "subject_id" = v_booking."id"::text;
  delete from "better_supabase"."recurrence_rules" where "subject_type" = 'booking' and "subject_id" = v_booking."id"::text;
  insert into "better_supabase"."recurrence_rules" ("tenant_id", "subject_type", "subject_id", "dtstart", "tzid", "rrule")
  select v_booking."tenant_id", 'booking', v_booking."id"::text, lower(v_booking."during"), r."tz", 'FREQ=DAILY;COUNT=1'
  from "better_supabase"."booking_resources" r where r."id" = v_booking."resource_id";
  insert into "better_supabase"."reminders" ("tenant_id", "subject_type", "subject_id", "user_id", "offset_minutes")
  select v_booking."tenant_id", 'booking', v_booking."id"::text, v_booking."customer_id", o
  from "better_supabase"."booking_services" sv, unnest(sv."reminder_offsets") o
  where sv."id" = v_booking."service_id";
    perform "better_supabase".emit_event('booking.confirmed', jsonb_build_object('organizationId', v_booking."tenant_id", 'id', v_id, 'resourceId', v_booking."resource_id", 'serviceId', v_booking."service_id"), 'bookings/' || v_id::text, (v_booking."tenant_id")::text, null, 'better-supabase/bookings');
    declare
    v_hook regprocedure := to_regprocedure('"public"."after_booking_confirm"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_id;
    end if;
  end;
  elsif change_booking.to_status = 'cancelled' then
    if v_booking."status" = 'cancelled' then
      return jsonb_build_object('id', v_booking."id", 'resourceId', v_booking."resource_id", 'serviceId', v_booking."service_id", 'seat', v_booking."seat", 'startsAt', lower(v_booking."during"), 'endsAt', upper(v_booking."during"), 'status', v_booking."status", 'holdExpiresAt', v_booking."hold_expires_at", 'customerName', v_booking."customer_name", 'customerEmail', v_booking."customer_email", 'customerUserId', v_booking."customer_id", 'notes', v_booking."notes", 'seriesId', v_booking."series_id", 'createdAt', v_booking."created_at", 'cancelledAt', v_booking."cancelled_at", 'cancelReason', v_booking."cancel_reason");
    end if;
    update "better_supabase"."bookings" bk set "status" = 'cancelled', "hold_expires_at" = null, "cancelled_at" = now(), "cancel_reason" = change_booking.reason, "updated_at" = now()
    where bk."id" = v_id returning * into v_booking;
    if v_booking."calendar_event_id" is not null then
    delete from "better_supabase"."calendar_events" where "id" = v_booking."calendar_event_id";
  end if;
    delete from "better_supabase"."reminders" where "subject_type" = 'booking' and "subject_id" = v_booking."id"::text;
  delete from "better_supabase"."recurrence_rules" where "subject_type" = 'booking' and "subject_id" = v_booking."id"::text;
    perform "better_supabase".emit_event('booking.cancelled', jsonb_build_object('organizationId', v_booking."tenant_id", 'id', v_id, 'resourceId', v_booking."resource_id", 'serviceId', v_booking."service_id"), 'bookings/' || v_id::text, (v_booking."tenant_id")::text, null, 'better-supabase/bookings');
    declare
    v_hook regprocedure := to_regprocedure('"public"."after_booking_cancel"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_id;
    end if;
  end;
  else
    raise exception 'change a booking to confirmed or cancelled' using errcode = '22023', hint = 'BOOKING_STATUS_INVALID';
  end if;
  return jsonb_build_object('id', v_booking."id", 'resourceId', v_booking."resource_id", 'serviceId', v_booking."service_id", 'seat', v_booking."seat", 'startsAt', lower(v_booking."during"), 'endsAt', upper(v_booking."during"), 'status', v_booking."status", 'holdExpiresAt', v_booking."hold_expires_at", 'customerName', v_booking."customer_name", 'customerEmail', v_booking."customer_email", 'customerUserId', v_booking."customer_id", 'notes', v_booking."notes", 'seriesId', v_booking."series_id", 'createdAt', v_booking."created_at", 'cancelledAt', v_booking."cancelled_at", 'cancelReason', v_booking."cancel_reason");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.change_sequence_enrollment (
  enrollment_id uuid,
  action        text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."enrollments";
  v_status text;
begin
  select * into v_row from "better_supabase"."enrollments" x
  where x."id" = change_sequence_enrollment.enrollment_id and x."sequence_id" is not null
  for update;
  if v_row."id" is null or not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'sequences.read'), false))) or (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'sequences.enroll'), false)))) then
    raise exception 'sequence enrollment not found' using errcode = 'P0002', hint = 'SEQUENCE_ENROLLMENT_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'sequences.enroll'), false))) then
    raise exception 'not allowed to change sequence enrollments' using errcode = '42501', hint = 'SEQUENCE_FORBIDDEN';
  end if;
  v_status := (case when v_row."status" = 'cancelled' then 'exited' when v_row."status" = 'completed' then 'completed' when v_row."paused_at" is not null then 'paused' else 'active' end);
  case change_sequence_enrollment.action
    when 'pause' then
      if v_status <> 'active' then
        raise exception 'only an active run can be paused' using errcode = '22023', hint = 'SEQUENCE_INVALID';
      end if;
      perform "better_supabase"."enrollment_pause"(v_row."id", true, auth.uid());
    when 'resume' then
      if v_status <> 'paused' then
        raise exception 'only a paused run can be resumed' using errcode = '22023', hint = 'SEQUENCE_INVALID';
      end if;
      perform "better_supabase"."enrollment_pause"(v_row."id", false, auth.uid());
    when 'exit' then
      if v_status not in ('active', 'paused') then
        raise exception 'only an active or paused run can be exited' using errcode = '22023', hint = 'SEQUENCE_INVALID';
      end if;
      perform "better_supabase"."sequence_exit"(v_row."id", 'manual');
    else
      raise exception 'action must be pause, resume or exit' using errcode = '22023', hint = 'SEQUENCE_INVALID';
  end case;
  return "better_supabase"."sequence_member_json"(v_row."id");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.channel_price (
  channel uuid,
  variant uuid,
  as_of   timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select "better_supabase"."variant_price"($2, k."currency", k."price_list_id", $3)
  from "better_supabase"."catalog_channels" k
  where k."id" = $1 and k."currency" is not null
$function$;

CREATE OR REPLACE FUNCTION better_supabase.channel_products (
  channel   uuid,
  locale    text    DEFAULT NULL::text,
  page_size integer DEFAULT NULL::integer,
  after     text    DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(item order by slug collate "C"), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'id', p."id",
      'slug', p."slug",
      'status', p."status",
      'kind', p."kind",
      'locale', (case when $2 = any ('{en}'::text[]) then $2 when split_part($2, '-', 1) = any ('{en}'::text[]) then split_part($2, '-', 1) else 'en' end),
      'title', coalesce(t."title", p."title"),
      'description', coalesce(t."description", p."description"),
      'listedAt', l."listed_at"
    ) as item, p."slug" as slug
    from "better_supabase"."catalog_channel_products" l
    join "better_supabase"."products" p on p."id" = l."product_id"
    left join "better_supabase"."product_translations" t on t."product_id" = p."id" and t."locale" = (case when $2 = any ('{en}'::text[]) then $2 when split_part($2, '-', 1) = any ('{en}'::text[]) then split_part($2, '-', 1) else 'en' end)
    where l."channel_id" = $1
      and ($4 is null or p."slug" collate "C" > $4 collate "C")
    order by p."slug" collate "C"
    limit least(greatest(coalesce($3, 100), 1), 500)
  ) items
$function$;

CREATE OR REPLACE FUNCTION better_supabase.channels_for_record (
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(to_jsonb(x) || jsonb_build_object(
      'archivedAt', c."archived_at",
      'lastMessageAt', c."last_message_at",
      'role', (select k."role" from "better_supabase"."conversation_members" k where k."conversation_id" = c."id" and k."user_id" = auth.uid()),
      'memberCount', (select count(*) from "better_supabase"."conversation_members" k where k."conversation_id" = c."id")
    ) order by x."name"), '[]'::jsonb)
  from "better_supabase"."channels" x
  join "better_supabase"."conversations" c on c."id" = x."id"
  where x."subject_type" = channels_for_record.subject_type and x."subject_id" = channels_for_record.subject_id
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chat_install (
  adapter        text,
  external_id    text,
  tenant         uuid  DEFAULT NULL::uuid,
  credential_ref jsonb DEFAULT NULL::jsonb,
  installed_by   uuid  DEFAULT NULL::uuid,
  metadata       jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_previous jsonb;
  v_row "better_supabase"."chat_installations"%rowtype;
begin
  select "credential_ref" into v_previous from "better_supabase"."chat_installations"
  where "adapter" = chat_install.adapter and "external_id" = chat_install.external_id
  for update;
  insert into "better_supabase"."chat_installations" as i ("tenant_id", "adapter", "external_id", "credential_ref", "installed_by", "metadata")
  values (tenant, adapter, external_id, credential_ref, installed_by, coalesce(metadata, '{}'::jsonb))
  on conflict ("adapter", "external_id") do update
    set "tenant_id" = coalesce(excluded."tenant_id", i."tenant_id"),
        "credential_ref" = excluded."credential_ref",
        "installed_by" = coalesce(excluded."installed_by", i."installed_by"),
        "metadata" = i."metadata" || excluded."metadata",
        "installed_at" = clock_timestamp(),
        "uninstalled_at" = null
  returning * into v_row;
  return to_jsonb(v_row) || jsonb_build_object(
    'previous_credential_ref',
    case when v_previous is distinct from v_row."credential_ref" then v_previous end
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chat_installation (
  adapter     text,
  external_id text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select to_jsonb(i) from "better_supabase"."chat_installations" i
  where i."adapter" = chat_installation.adapter and i."external_id" = chat_installation.external_id;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chat_state_acquire_lock (
  prefix    text,
  thread_id text,
  token     text,
  ttl_ms    bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_lock "better_supabase"."chat_state_locks"%rowtype;
begin
  insert into "better_supabase"."chat_state_locks" as l ("key_prefix", "thread_id", "token", "expires_at")
  values (prefix, thread_id, token, clock_timestamp() + make_interval(secs => greatest(coalesce(ttl_ms, 0), 1) / 1000.0))
  on conflict ("key_prefix", "thread_id") do update
    set "token" = excluded."token", "expires_at" = excluded."expires_at", "updated_at" = clock_timestamp()
    where l."expires_at" <= clock_timestamp()
  returning * into v_lock;
  if not found then
    return null;
  end if;
  return jsonb_build_object('thread_id', v_lock."thread_id", 'token', v_lock."token", 'expires_at', v_lock."expires_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chat_state_append_to_list (
  prefix     text,
  key        text,
  value      jsonb,
  max_length integer DEFAULT NULL::integer,
  ttl_ms     bigint  DEFAULT NULL::bigint
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_expires timestamptz;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('chat_state_list:' || prefix || ':' || key));
  v_expires := coalesce(
    case when ttl_ms is null or ttl_ms <= 0 then null else clock_timestamp() + make_interval(secs => ttl_ms / 1000.0) end,
    (select max(k."expires_at") from "better_supabase"."chat_state_lists" k
     where k."key_prefix" = chat_state_append_to_list.prefix and k."list_key" = chat_state_append_to_list.key)
  );
  insert into "better_supabase"."chat_state_lists" ("key_prefix", "list_key", "value", "expires_at")
  values (prefix, key, value, v_expires);
  if max_length is not null and max_length > 0 then
    delete from "better_supabase"."chat_state_lists" l
    where l."key_prefix" = chat_state_append_to_list.prefix and l."list_key" = chat_state_append_to_list.key
      and l."id" < (
        select k."id" from "better_supabase"."chat_state_lists" k
        where k."key_prefix" = chat_state_append_to_list.prefix and k."list_key" = chat_state_append_to_list.key
        order by k."id" desc
        offset max_length - 1 limit 1
      );
  end if;
  if ttl_ms is not null and ttl_ms > 0 then
    update "better_supabase"."chat_state_lists" l set "expires_at" = v_expires
    where l."key_prefix" = chat_state_append_to_list.prefix and l."list_key" = chat_state_append_to_list.key
      and l."expires_at" is distinct from v_expires;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chat_state_delete (
  prefix text,
  key    text
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  delete from "better_supabase"."chat_state_cache" c where c."key_prefix" = chat_state_delete.prefix and c."cache_key" = chat_state_delete.key;
  delete from "better_supabase"."chat_state_lists" l where l."key_prefix" = chat_state_delete.prefix and l."list_key" = chat_state_delete.key;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chat_state_dequeue (
  prefix    text,
  thread_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_value jsonb;
begin
  delete from "better_supabase"."chat_state_queues" q
  where q."id" = (
    select k."id" from "better_supabase"."chat_state_queues" k
    where k."key_prefix" = chat_state_dequeue.prefix and k."thread_id" = chat_state_dequeue.thread_id
    order by k."id"
    limit 1
    for update skip locked
  )
  returning q."value" into v_value;
  return v_value;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chat_state_enqueue (
  prefix     text,
  thread_id  text,
  entry      jsonb,
  expires_at timestamp with time zone,
  max_size   integer                  DEFAULT NULL::integer
)
  RETURNS integer
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_depth integer;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('chat_state_queue:' || prefix || ':' || thread_id));
  delete from "better_supabase"."chat_state_queues" q
  where q."key_prefix" = chat_state_enqueue.prefix and q."thread_id" = chat_state_enqueue.thread_id
    and q."expires_at" <= clock_timestamp();
  insert into "better_supabase"."chat_state_queues" ("key_prefix", "thread_id", "value", "expires_at")
  values (prefix, thread_id, entry, expires_at);
  if max_size is not null and max_size > 0 then
    delete from "better_supabase"."chat_state_queues" q
    where q."key_prefix" = chat_state_enqueue.prefix and q."thread_id" = chat_state_enqueue.thread_id
      and q."id" < (
        select k."id" from "better_supabase"."chat_state_queues" k
        where k."key_prefix" = chat_state_enqueue.prefix and k."thread_id" = chat_state_enqueue.thread_id
        order by k."id" desc
        offset max_size - 1 limit 1
      );
  end if;
  select count(*)::integer into v_depth from "better_supabase"."chat_state_queues" q
  where q."key_prefix" = chat_state_enqueue.prefix and q."thread_id" = chat_state_enqueue.thread_id
    and q."expires_at" > clock_timestamp();
  return v_depth;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chat_state_extend_lock (
  prefix    text,
  thread_id text,
  token     text,
  ttl_ms    bigint
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  update "better_supabase"."chat_state_locks" l
  set "expires_at" = clock_timestamp() + make_interval(secs => greatest(coalesce(ttl_ms, 0), 1) / 1000.0), "updated_at" = clock_timestamp()
  where l."key_prefix" = chat_state_extend_lock.prefix
    and l."thread_id" = chat_state_extend_lock.thread_id
    and l."token" = chat_state_extend_lock.token
    and l."expires_at" > clock_timestamp();
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chat_state_force_release_lock (
  prefix    text,
  thread_id text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  delete from "better_supabase"."chat_state_locks" l
  where l."key_prefix" = chat_state_force_release_lock.prefix
    and l."thread_id" = chat_state_force_release_lock.thread_id;
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.chat_state_get (
  prefix text,
