$function$;

CREATE OR REPLACE FUNCTION better_supabase.column_default (
  relation text,
  name     text,
  target   anyelement
)
  RETURNS anyelement
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  result alias for $0;
  v_default text;
begin
  select pg_catalog.pg_get_expr(d.adbin, d.adrelid) into v_default
  from pg_catalog.pg_attribute a
  join pg_catalog.pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum
  where a.attrelid = pg_catalog.to_regclass(column_default.relation) and a.attname = column_default.name and not a.attisdropped;
  if v_default is not null then
    execute 'select ' || v_default into result;
  end if;
  return result;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.comment_conversation (
  tenant       uuid,
  subject_type text,
  subject_id   text
)
  RETURNS uuid
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  v_id uuid;
begin
  select c."id" into v_id from "better_supabase"."conversations" c
  where c."tenant_id" = comment_conversation.tenant and c."kind" = 'subject'
    and c."subject_type" = comment_conversation.subject_type and c."subject_id" = comment_conversation.subject_id;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.comment_count_rows (
  conversations uuid[]
)
  RETURNS TABLE (
    id uuid,
    n  bigint
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return query
  select x."conversation_id", count(*) from "better_supabase"."messages" x
  where x."conversation_id" = any (array(
      select c."id" from "better_supabase"."conversations" c
      where c."id" = any (comment_count_rows.conversations) and c."kind" = 'subject'
        and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (case when c."kind" = 'inbox'
    then "better_supabase"."inbox_conversation_allowed"(c."id"::text)
    else ((coalesce(better_supabase.can('tenant', c."tenant_id", 'messages.read'), false)
    or (c."access" = 'subject' and c."subject_type" in ('drive_node')))
    and case c."access"
      when 'tenant' then true
      when 'members' then "better_supabase"."is_conversation_member"(c."id")
      when 'subject' then coalesce("better_supabase"."can_subject"(c."subject_type", c."subject_id", 'read'), false)
      else false
    end)
    or (c."kind" = 'subject' and ((c."tenant_id")::text, (c."subject_type")::text, (c."subject_id")::text) in (select g.tenant, g.subject_type, g.subject_id from better_supabase.portal_subjects('read') g)) end))
    ))
    and x."sent_at" is not null and x."archived_at" is null
  and (x."kind" = 'message' or "better_supabase"."inbox_note_readable"(x."conversation_id"))
  group by x."conversation_id";
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.comment_counts (
  tenant       uuid,
  subject_type text,
  subject_ids  text[]
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
begin
  return (
    with c as materialized (
      select c."id" as id, c."subject_id" as subject_id
      from "better_supabase"."conversations" c
      where c."tenant_id" = comment_counts.tenant and c."kind" = 'subject'
        and c."subject_type" = comment_counts.subject_type
        and c."subject_id" = any (comment_counts.subject_ids)
    )
    select coalesce(jsonb_object_agg(c.subject_id, n.n), '{}'::jsonb)
    from c
    join "better_supabase"."comment_count_rows"(array(select c.id from c)) n on n.id = c.id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.comment_message_readable (
  message uuid,
  tenant  uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
begin
  return exists (
    select 1 from "better_supabase"."messages" x
    where x."id" = comment_message_readable.message and x."tenant_id" = comment_message_readable.tenant
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.comment_page (
  conversation    uuid,
  after           timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  max_rows        integer                  DEFAULT 100,
  skip            integer                  DEFAULT 0,
  after_id        uuid                     DEFAULT NULL::uuid,
  include_deleted boolean                  DEFAULT true
)
  RETURNS uuid[]
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not exists (
    select 1 from "better_supabase"."conversations" c
    where c."id" = comment_page.conversation and c."kind" = 'subject'
      and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (case when c."kind" = 'inbox'
    then "better_supabase"."inbox_conversation_allowed"(c."id"::text)
    else ((coalesce(better_supabase.can('tenant', c."tenant_id", 'messages.read'), false)
    or (c."access" = 'subject' and c."subject_type" in ('drive_node')))
    and case c."access"
      when 'tenant' then true
      when 'members' then "better_supabase"."is_conversation_member"(c."id")
      when 'subject' then coalesce("better_supabase"."can_subject"(c."subject_type", c."subject_id", 'read'), false)
      else false
    end)
    or (c."kind" = 'subject' and ((c."tenant_id")::text, (c."subject_type")::text, (c."subject_id")::text) in (select g.tenant, g.subject_type, g.subject_id from better_supabase.portal_subjects('read') g)) end))
  ) then
    return '{}'::uuid[];
  end if;
  return array(
    select x."id" from "better_supabase"."messages" x
    where x."conversation_id" = comment_page.conversation and x."sent_at" is not null
  and (x."kind" = 'message' or "better_supabase"."inbox_note_readable"(x."conversation_id"))
      and (coalesce(comment_page.include_deleted, true) or x."archived_at" is null)
      and (comment_page.after is null
        or (x."sent_at", x."id") > (comment_page.after, coalesce(comment_page.after_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
    order by x."sent_at", x."id"
    limit least(greatest(coalesce(comment_page.max_rows, 100), 1), 500)
    offset greatest(coalesce(comment_page.skip, 0), 0)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.comment_sent (
  message uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_msg record;
  v_conv record;
  v_user uuid;
  v_claims text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_msg from "better_supabase"."messages" x
  where x."id" = comment_sent.message and x."author_id" = auth.uid()
    and x."sent_at" is not null and x."archived_at" is null;
  if not found then
    return;
  end if;
  select * into v_conv from "better_supabase"."conversations" c
  where c."id" = v_msg."conversation_id" and c."kind" = 'subject';
  if not found then
    return;
  end if;
  foreach v_user in array array(select distinct x from unnest(array[v_msg."author_id"] || v_msg."mentions") x where x = v_msg."author_id" or coalesce(better_supabase.can_user(x, 'tenant', v_msg."tenant_id", 'messages.read'), false)) loop
    insert into "better_supabase"."notification_subscriptions" ("tenant_id", "user_id", "subject_type", "subject_id", "level")
    values (v_conv."tenant_id", v_user, v_conv."subject_type", v_conv."subject_id", 'participating')
    on conflict do nothing;
  end loop;
  if (exists (
      select 1 from "better_supabase"."notification_subscriptions" s
      where s."subject_type" = v_conv."subject_type" and s."subject_id" = v_conv."subject_id" and s."tenant_id" = v_conv."tenant_id"
        and s."level" in ('all', 'participating')
        and not s."user_id" = any (array[v_msg."author_id"] || v_msg."mentions")
    ) or to_regprocedure('"public"."notification_audience"(jsonb)') is not null) then
    if better_supabase.import_run() is null then
      v_claims := current_setting('request.jwt.claims', true);
      perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
      perform "better_supabase"."notify"(jsonb_build_object(
      'type', 'comment.posted',
      'tenant', v_msg."tenant_id",
      'actor', v_msg."author_id",
      'subject_type', v_conv."subject_type",
      'subject_id', v_conv."subject_id",
      'subject_label', "better_supabase"."subject_title"(v_conv."subject_type", v_conv."subject_id"),
      'summary', left(v_msg."body", 140),
      'recipients', '[]'::jsonb,
      'exclude', to_jsonb(v_msg."mentions"),
      'key', 'comment.posted:' || v_msg."id"::text,
      'data', jsonb_build_object('messageId', v_msg."id", 'conversationId', v_msg."conversation_id")
    ));
      perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
    end if;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.comments_json (
  ids uuid[]
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
begin
  return (
    with e as materialized (
      select x.row, x.n from jsonb_array_elements("better_supabase"."messaging_messages_json"(comments_json.ids)) with ordinality x(row, n)
    ),
    c as materialized (
      select c."id" as id, c."subject_type" as subject_type, c."subject_id" as subject_id
      from "better_supabase"."conversations" c
      where c."id" = any (array(select distinct (e.row ->> 'conversation_id')::uuid from e))
    ),
    t as materialized (
      select t."message_id" as message, t."task_id" as task from "better_supabase"."comment_tasks" t
      where t."message_id" = any (comments_json.ids)
    )
    select coalesce(jsonb_agg(e.row || jsonb_build_object(
      'subject_type', c.subject_type,
      'subject_id', c.subject_id,
      'task_id', t.task
    ) order by e.n), '[]'::jsonb)
    from e
    join c on c.id = (e.row ->> 'conversation_id')::uuid
    left join t on t.message = (e.row ->> 'id')::uuid
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.comments_subject_deleted_product()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_type text := 'product';
  v_id text := old."id"::text;
  v_tenant text := old."tenant_id"::text;
begin
  if v_tenant is null then
    delete from "better_supabase"."conversations" c where c."kind" = 'subject' and c."subject_type" = v_type and c."subject_id" = v_id;
  else
    delete from "better_supabase"."conversations" c where c."kind" = 'subject' and c."subject_type" = v_type and c."subject_id" = v_id and c."tenant_id" = v_tenant::uuid;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.comments_subject_deleted_product_variant()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_type text := 'product_variant';
  v_id text := old."id"::text;
  v_tenant text := old."tenant_id"::text;
begin
  if v_tenant is null then
    delete from "better_supabase"."conversations" c where c."kind" = 'subject' and c."subject_type" = v_type and c."subject_id" = v_id;
  else
    delete from "better_supabase"."conversations" c where c."kind" = 'subject' and c."subject_type" = v_type and c."subject_id" = v_id and c."tenant_id" = v_tenant::uuid;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.commission_accrue (
  tenant       uuid,
  seller_id    uuid,
  source_type  text,
  source_id    text,
  basis        bigint,
  currency     text,
  occurred_on  date   DEFAULT NULL::date,
  subject_type text   DEFAULT NULL::text,
  subject_id   text   DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_entry "better_supabase"."commissions";
  v_plan "better_supabase"."commission_plans";
  v_on date := coalesce(commission_accrue.occurred_on, current_date);
  v_currency text := upper(commission_accrue.currency);
  v_prior bigint;
  v_amount bigint;
  v_tx uuid;
begin
  if commission_accrue.seller_id is null or nullif(trim(commission_accrue.source_type), '') is null
    or nullif(trim(commission_accrue.source_id), '') is null or coalesce(commission_accrue.basis, 0) <= 0
    or v_currency !~ '^[A-Z]{3}$' then
    raise exception 'a commission needs a seller, a source, a positive basis and a currency code' using errcode = '22023', hint = 'COMMISSION_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(commission_accrue.tenant::text || commission_accrue.seller_id::text, 0));
  select * into v_entry from "better_supabase"."commissions" x
  where x."tenant_id" = commission_accrue.tenant and x."source_type" = commission_accrue.source_type
    and x."source_id" = commission_accrue.source_id and x."seller_id" = commission_accrue.seller_id;
  if found then
    return jsonb_build_object('id', v_entry."id", 'organizationId', v_entry."tenant_id", 'planId', v_entry."plan_id", 'sellerId', v_entry."seller_id", 'sourceType', v_entry."source_type", 'sourceId', v_entry."source_id", 'basis', v_entry."basis"::text, 'amount', v_entry."amount"::text, 'currency', v_entry."currency", 'occurredOn', v_entry."occurred_on", 'status', v_entry."status", 'statementId', v_entry."statement_id", 'ledgerTransactionId', v_entry."ledger_transaction_id", 'reversedAt', v_entry."reversed_at", 'createdAt', v_entry."created_at");
  end if;
  select y.* into v_plan from "better_supabase"."commission_plans" y
  where y."id" = "better_supabase"."commission_plan_for"(commission_accrue.tenant, commission_accrue.seller_id, commission_accrue.subject_type, commission_accrue.subject_id, v_on);
  if not found then
    return null;
  end if;
  select coalesce(sum(x."basis"), 0) into v_prior from "better_supabase"."commissions" x
  where x."tenant_id" = commission_accrue.tenant and x."seller_id" = commission_accrue.seller_id
    and x."plan_id" = v_plan."id" and x."currency" = v_currency and x."status" = 'accrued'
    and date_trunc('month', x."occurred_on"::timestamp) = date_trunc('month', v_on::timestamp);
  v_amount := "better_supabase"."commission_amount"(v_plan."kind", v_plan."rate_bps", v_plan."tiers", v_prior, commission_accrue.basis);
  if v_amount <= 0 then
    return null;
  end if;
  v_tx := "better_supabase"."ledger_post"(commission_accrue.tenant, 'commission.accrual',
    jsonb_build_array(
      jsonb_build_object('account', "better_supabase"."ledger_account_for"(commission_accrue.tenant, 'expense', 'commissions:expense:' || v_currency::text, 'Commissions', v_currency::text, 0::smallint, null, null, null, true, 'commissions.read', 'commissions', null), 'amount', (-v_amount)::text),
      jsonb_build_object('account', "better_supabase"."ledger_account_for"(commission_accrue.tenant, 'payable', 'commissions:payable:' || commission_accrue.seller_id::text || ':' || v_currency::text, 'Commissions payable', v_currency::text, 0::smallint, null, null, commission_accrue.seller_id, true, 'commissions.read', 'commissions', null), 'amount', v_amount::text)),
    'commissions', commission_accrue.source_type || '/' || commission_accrue.source_id, null,
    'commission:' || commission_accrue.source_type || ':' || commission_accrue.source_id || ':' || commission_accrue.seller_id::text,
    v_on::timestamptz,
    jsonb_build_object('sellerId', commission_accrue.seller_id, 'planId', v_plan."id"));
  insert into "better_supabase"."commissions" ("tenant_id", "plan_id", "seller_id", "source_type", "source_id", "basis", "amount", "currency", "occurred_on", "ledger_transaction_id")
  values (commission_accrue.tenant, v_plan."id", commission_accrue.seller_id, commission_accrue.source_type, commission_accrue.source_id,
    commission_accrue.basis, v_amount, v_currency, v_on, v_tx)
  returning * into v_entry;
  perform "better_supabase".emit_event('commission.accrued', jsonb_build_object('organizationId', v_entry."tenant_id", 'id', v_entry."id", 'planId', v_entry."plan_id", 'sellerId', v_entry."seller_id", 'sourceType', v_entry."source_type", 'sourceId', v_entry."source_id", 'amount', v_entry."amount"::text, 'currency', v_entry."currency"), 'commissions/' || v_entry."id"::text, (v_entry."tenant_id")::text, null, 'better-supabase/commissions');
  perform better_supabase.audit_event(
    event_type => 'commission.accrued',
    category => 'billing',
    target_type => 'commission',
    record_id => v_entry."id"::text,
    summary => 'accrued a commission',
    tenant => (v_entry."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_entry."tenant_id", 'id', v_entry."id", 'planId', v_entry."plan_id", 'sellerId', v_entry."seller_id", 'sourceType', v_entry."source_type", 'sourceId', v_entry."source_id", 'amount', v_entry."amount"::text, 'currency', v_entry."currency")
  );
  return jsonb_build_object('id', v_entry."id", 'organizationId', v_entry."tenant_id", 'planId', v_entry."plan_id", 'sellerId', v_entry."seller_id", 'sourceType', v_entry."source_type", 'sourceId', v_entry."source_id", 'basis', v_entry."basis"::text, 'amount', v_entry."amount"::text, 'currency', v_entry."currency", 'occurredOn', v_entry."occurred_on", 'status', v_entry."status", 'statementId', v_entry."statement_id", 'ledgerTransactionId', v_entry."ledger_transaction_id", 'reversedAt', v_entry."reversed_at", 'createdAt', v_entry."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.commission_amount (
  kind     text,
  rate_bps integer,
  tiers    jsonb,
  prior    bigint,
  basis    bigint
)
  RETURNS bigint
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_tier jsonb;
  v_lower numeric := 0;
  v_upper numeric;
  v_before numeric := 0;
  v_after numeric := 0;
begin
  if commission_amount.kind = 'flat' then
    return round(commission_amount.basis * commission_amount.rate_bps / 10000.0)::bigint;
  end if;
  for v_tier in
    select t.value from jsonb_array_elements(commission_amount.tiers) with ordinality as t(value, n) order by t.n
  loop
    v_upper := (v_tier ->> 'upTo')::numeric;
    v_before := v_before + greatest(0, least(coalesce(v_upper, commission_amount.prior), commission_amount.prior) - v_lower) * (v_tier ->> 'bps')::numeric / 10000.0;
    v_after := v_after + greatest(0, least(coalesce(v_upper, commission_amount.prior + commission_amount.basis), commission_amount.prior + commission_amount.basis) - v_lower) * (v_tier ->> 'bps')::numeric / 10000.0;
    exit when v_upper is null;
    v_lower := v_upper;
  end loop;
  return round(v_after)::bigint - round(v_before)::bigint;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.commission_close_range (
  tenant    uuid,
  starts_on date,
  ends_on   date
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row record;
  v_id uuid;
begin
  for v_row in
    select distinct x."seller_id" as seller, x."currency" as currency from "better_supabase"."commissions" x
    where x."tenant_id" = commission_close_range.tenant and x."status" = 'accrued' and x."statement_id" is null
      and x."occurred_on" between commission_close_range.starts_on and commission_close_range.ends_on
  loop
    perform "better_supabase"."commission_statement_build"(commission_close_range.tenant, v_row.seller, v_row.currency, commission_close_range.starts_on, commission_close_range.ends_on);
  end loop;
  for v_id in
    select x."id" from "better_supabase"."commission_statements" x
    where x."tenant_id" = commission_close_range.tenant and x."status" = 'open'
      and x."starts_on" >= commission_close_range.starts_on and x."ends_on" <= commission_close_range.ends_on
  loop
    perform "better_supabase"."commission_statement_finalize"(v_id);
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.commission_payroll_lines (
  tenant    uuid,
  from_date date,
  to_date   date
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (commission_payroll_lines.tenant is not null and coalesce(better_supabase.can('tenant', commission_payroll_lines.tenant, 'commissions.read'), false))) then
    raise exception 'not allowed to read commission statements' using errcode = '42501', hint = 'COMMISSION_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('userId', y.seller, 'currency', y.currency, 'amount', y.amount::text, 'statementIds', y.ids) order by y.seller, y.currency)
    from (
      select x."seller_id" as seller, x."currency" as currency, sum(x."total") as amount, jsonb_agg(x."id" order by x."ends_on") as ids
      from "better_supabase"."commission_statements" x
      where x."tenant_id" = commission_payroll_lines.tenant and x."status" in ('finalized', 'paid')
        and x."ends_on" between commission_payroll_lines.from_date and commission_payroll_lines.to_date and x."total" > 0
      group by x."seller_id", x."currency"
    ) y
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.commission_plan_for (
  tenant       uuid,
  seller_id    uuid,
  subject_type text,
  subject_id   text,
  on_date      date
)
  RETURNS uuid
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select x."plan_id" from "better_supabase"."commission_assignments" x
  join "better_supabase"."commission_plans" y on y."id" = x."plan_id" and y."archived_at" is null
  where x."tenant_id" = commission_plan_for.tenant and x."seller_id" = commission_plan_for.seller_id
    and x."starts_on" <= commission_plan_for.on_date and (x."ends_on" is null or x."ends_on" >= commission_plan_for.on_date)
    and (x."subject_type" is null or (x."subject_type" = commission_plan_for.subject_type and x."subject_id" = commission_plan_for.subject_id))
  order by (x."subject_type" is not null) desc, x."starts_on" desc, x."created_at" desc
  limit 1
$function$;

CREATE OR REPLACE FUNCTION better_supabase.commission_statement_build (
  tenant    uuid,
  seller_id uuid,
  currency  text,
  starts_on date,
  ends_on   date
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_statement "better_supabase"."commission_statements";
begin
  select * into v_statement from "better_supabase"."commission_statements" x
  where x."tenant_id" = commission_statement_build.tenant and x."seller_id" = commission_statement_build.seller_id
    and x."currency" = commission_statement_build.currency and x."starts_on" = commission_statement_build.starts_on
  for update;
  if found and v_statement."status" <> 'open' then
    raise exception 'the statement of this range is no longer open' using errcode = '55000', hint = 'COMMISSION_STATEMENT_LOCKED';
  end if;
  if not found then
    insert into "better_supabase"."commission_statements" ("tenant_id", "seller_id", "currency", "starts_on", "ends_on")
    values (commission_statement_build.tenant, commission_statement_build.seller_id, commission_statement_build.currency,
      commission_statement_build.starts_on, commission_statement_build.ends_on)
    returning * into v_statement;
  end if;
  update "better_supabase"."commissions" x set "statement_id" = v_statement."id"
  where x."tenant_id" = commission_statement_build.tenant and x."seller_id" = commission_statement_build.seller_id
    and x."currency" = commission_statement_build.currency and x."status" = 'accrued' and x."statement_id" is null
    and x."occurred_on" between commission_statement_build.starts_on and commission_statement_build.ends_on;
  update "better_supabase"."commission_statements" x set "ends_on" = commission_statement_build.ends_on, "total" = coalesce((select sum(e."amount") from "better_supabase"."commissions" e where e."statement_id" = x."id" and e."status" = 'accrued'), 0)
  where x."id" = v_statement."id";
  return v_statement."id";
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.commission_statement_finalize (
  statement_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_statement "better_supabase"."commission_statements";
begin
  select * into v_statement from "better_supabase"."commission_statements" x where x."id" = commission_statement_finalize.statement_id for update;
  if not found then
    raise exception 'no such commission statement' using errcode = 'P0002', hint = 'COMMISSION_STATEMENT_NOT_FOUND';
  end if;
  if v_statement."status" <> 'open' then
    return jsonb_build_object('id', v_statement."id", 'organizationId', v_statement."tenant_id", 'sellerId', v_statement."seller_id", 'currency', v_statement."currency", 'startsOn', v_statement."starts_on", 'endsOn', v_statement."ends_on", 'status', v_statement."status", 'total', v_statement."total"::text, 'ledgerTransactionId', v_statement."ledger_transaction_id", 'finalizedAt', v_statement."finalized_at", 'paidAt', v_statement."paid_at", 'paidBy', v_statement."paid_by", 'createdAt', v_statement."created_at");
  end if;
  update "better_supabase"."commission_statements" x set "status" = 'finalized', "finalized_at" = now(), "total" = coalesce((select sum(e."amount") from "better_supabase"."commissions" e where e."statement_id" = x."id" and e."status" = 'accrued'), 0)
  where x."id" = v_statement."id" returning * into v_statement;
  perform "better_supabase".emit_event('commission_statement.finalized', jsonb_build_object('organizationId', v_statement."tenant_id", 'id', v_statement."id", 'sellerId', v_statement."seller_id", 'currency', v_statement."currency", 'startsOn', v_statement."starts_on", 'endsOn', v_statement."ends_on", 'total', v_statement."total"::text, 'status', v_statement."status"), 'commission-statements/' || v_statement."id"::text, (v_statement."tenant_id")::text, null, 'better-supabase/commissions');
  perform better_supabase.audit_event(
    event_type => 'commission_statement.finalized',
    category => 'billing',
    target_type => 'commission_statement',
    record_id => v_statement."id"::text,
    summary => 'finalized a commission statement',
    tenant => (v_statement."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_statement."tenant_id", 'id', v_statement."id", 'sellerId', v_statement."seller_id", 'currency', v_statement."currency", 'startsOn', v_statement."starts_on", 'endsOn', v_statement."ends_on", 'total', v_statement."total"::text, 'status', v_statement."status")
  );
  return jsonb_build_object('id', v_statement."id", 'organizationId', v_statement."tenant_id", 'sellerId', v_statement."seller_id", 'currency', v_statement."currency", 'startsOn', v_statement."starts_on", 'endsOn', v_statement."ends_on", 'status', v_statement."status", 'total', v_statement."total"::text, 'ledgerTransactionId', v_statement."ledger_transaction_id", 'finalizedAt', v_statement."finalized_at", 'paidAt', v_statement."paid_at", 'paidBy', v_statement."paid_by", 'createdAt', v_statement."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.commission_tiers_valid (
  tiers jsonb
)
  RETURNS boolean
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
declare
  v_tier jsonb;
  v_last numeric := 0;
  v_count integer;
  v_n integer := 0;
begin
  if jsonb_typeof(commission_tiers_valid.tiers) is distinct from 'array' then
    return false;
  end if;
  v_count := jsonb_array_length(commission_tiers_valid.tiers);
  if v_count = 0 or v_count > 50 then
    return false;
  end if;
  for v_tier in select t.value from jsonb_array_elements(commission_tiers_valid.tiers) with ordinality as t(value, n) order by t.n loop
    v_n := v_n + 1;
    if jsonb_typeof(v_tier) is distinct from 'object'
      or coalesce(v_tier ->> 'bps', '') !~ '^[0-9]{1,5}$' or (v_tier ->> 'bps')::integer > 10000 then
      return false;
    end if;
    if v_tier ->> 'upTo' is null then
      return v_n = v_count;
    end if;
    if v_tier ->> 'upTo' !~ '^[0-9]{1,18}$' or (v_tier ->> 'upTo')::numeric <= v_last then
      return false;
    end if;
    v_last := (v_tier ->> 'upTo')::numeric;
  end loop;
  return false;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.commit_reservation (
  reservation uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row record;
  v_movement uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" as tenant, x."variant_id" as variant, x."location_id" as location,
    x."quantity" as quantity, x."status" as status, x."expires_at" as expires_at,
    x."reference_type" as reference_type, x."reference_id" as reference_id
  into v_row from "better_supabase"."stock_reservations" x where x."id" = commit_reservation.reservation for update;
  if not found then
    raise exception 'reservation not found' using errcode = 'P0002', hint = 'INVENTORY_RESERVATION_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_row.tenant, 'inventory.reserve'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  if v_row.status <> 'active' then
    raise exception 'the reservation is no longer active' using errcode = '55000', hint = 'INVENTORY_RESERVATION_CLOSED';
  end if;
  if v_row.expires_at <= now() then
    raise exception 'the reservation has expired' using errcode = '55000', hint = 'INVENTORY_RESERVATION_EXPIRED';
  end if;
  update "better_supabase"."stock_levels" x set "reserved" = greatest(x."reserved" - v_row.quantity, 0), "updated_at" = now()
  where x."variant_id" = v_row.variant and x."location_id" = v_row.location;
  update "better_supabase"."stock_reservations" x set "status" = 'committed', "updated_at" = now()
  where x."id" = commit_reservation.reservation;
  v_movement := "better_supabase"."move_stock"(v_row.tenant, v_row.variant, v_row.location, -v_row.quantity, 'sale', v_row.reference_type, v_row.reference_id, null, null);
  perform "better_supabase".emit_event('reservation.committed', jsonb_build_object('organizationId', v_row.tenant, 'id', commit_reservation.reservation, 'variantId', v_row.variant, 'locationId', v_row.location, 'quantity', v_row.quantity::text), 'stock-reservations/' || commit_reservation.reservation::text, (v_row.tenant)::text, null, 'better-supabase/inventory');
  return jsonb_build_object('id', commit_reservation.reservation, 'movementId', v_movement);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.compact_document (
  document_id uuid,
  state       text,
  through_seq bigint
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_doc "better_supabase"."documents"%rowtype;
  v_current bigint;
  v_last bigint;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_doc from "better_supabase"."documents" d where d."id" = compact_document.document_id for update;
  if not found then
    raise exception 'document not found' using errcode = 'P0002', hint = 'DOCUMENT_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'documents.manage'), false)) then
    raise exception 'not allowed to compact this document' using errcode = '42501', hint = 'DOCUMENT_FORBIDDEN';
  end if;
  select x."seq" into v_current from "better_supabase"."document_snapshots" x where x."document_id" = v_doc."id";
  select max(x."seq") into v_last from "better_supabase"."document_updates" x where x."document_id" = v_doc."id";
  if compact_document.through_seq <= coalesce(v_current, 0) then
    return false;
  end if;
  if v_last is null or compact_document.through_seq > v_last then
    raise exception 'through_seq is past the last update' using errcode = '22023', hint = 'DOCUMENT_COMPACT_INVALID';
  end if;
  insert into "better_supabase"."document_snapshots" ("document_id", "tenant_id", "state", "seq")
  values (v_doc."id", v_doc."tenant_id", decode(compact_document.state, 'base64'), compact_document.through_seq)
  on conflict ("document_id") do update
    set "state" = excluded."state", "seq" = excluded."seq", "created_at" = now();
  delete from "better_supabase"."document_updates" x where x."document_id" = v_doc."id" and x."seq" <= compact_document.through_seq;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.company_people_of (
  company uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(to_jsonb(p) || jsonb_build_object('roles', p."roles", 'customer_terms_id', p."customer_terms_id", 'supplier_terms_id', p."supplier_terms_id", 'credit_currency', p."credit_currency", 'credit_limit', p."credit_limit"::text, 'credit_block', p."credit_block", 'supplier_status', p."supplier_status", 'language', p."language") || jsonb_build_object('role', l."role", 'is_primary', l."is_primary")
    order by l."is_primary" desc, lower(p."name"), p."id"), '[]'::jsonb)
  from "better_supabase"."company_people" l join "better_supabase"."people" p on p."id" = l."person_id"
  where l."company_id" = company_people_of.company and p."archived_at" is null
$function$;

CREATE OR REPLACE FUNCTION better_supabase.compare_eval_runs (
  base       uuid,
  candidate  uuid,
  score_drop numeric DEFAULT NULL::numeric
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_base "better_supabase"."eval_runs"%rowtype;
  v_candidate "better_supabase"."eval_runs"%rowtype;
  v_base_summary jsonb;
  v_candidate_summary jsonb;
begin
  select x.* into v_base from "better_supabase"."eval_runs" x where x."id" = compare_eval_runs.base;
  if not found then
    raise exception 'No eval run %', compare_eval_runs.base using errcode = 'P0002', hint = 'EVAL_RUN_NOT_FOUND';
  end if;
  select x.* into v_candidate from "better_supabase"."eval_runs" x where x."id" = compare_eval_runs.candidate;
  if not found then
    raise exception 'No eval run %', compare_eval_runs.candidate using errcode = 'P0002', hint = 'EVAL_RUN_NOT_FOUND';
  end if;
  if v_base."dataset_id" <> v_candidate."dataset_id" then
    raise exception 'Runs belong to different datasets' using errcode = '22023', hint = 'EVAL_RUN_MISMATCH';
  end if;
  v_base_summary := "better_supabase"."eval_run_summary"(compare_eval_runs.base);
  v_candidate_summary := "better_supabase"."eval_run_summary"(compare_eval_runs.candidate);
  return (
    with joined as materialized (
      select coalesce(b."item_id", c."item_id") as item,
        b."passed" as base_passed, c."passed" as candidate_passed,
        (select avg((e.value ->> 'score')::numeric) from jsonb_each(b."scores") e) as base_score, (select avg((e.value ->> 'score')::numeric) from jsonb_each(c."scores") e) as candidate_score,
        b."output" as base_output, c."output" as candidate_output
      from (select * from "better_supabase"."eval_results" where "run_id" = compare_eval_runs.base) b
      full join (select * from "better_supabase"."eval_results" where "run_id" = compare_eval_runs.candidate) c on c."item_id" = b."item_id"
    ), tagged as (
      select j.*, case
        when j.base_passed is null or j.candidate_passed is null then 'missing'
        when j.base_passed and not j.candidate_passed then 'regression'
        when not j.base_passed and j.candidate_passed then 'improvement'
        when compare_eval_runs.score_drop is not null and j.base_score - j.candidate_score > compare_eval_runs.score_drop then 'regression'
        when compare_eval_runs.score_drop is not null and j.candidate_score - j.base_score > compare_eval_runs.score_drop then 'improvement'
        else 'unchanged' end as kind
      from joined j
    )
    select jsonb_build_object(
      'base', v_base_summary,
      'candidate', v_candidate_summary,
      'pass_rate_delta', round(coalesce((v_candidate_summary ->> 'passRate')::numeric, 0) - coalesce((v_base_summary ->> 'passRate')::numeric, 0), 4),
      'regressions', coalesce(jsonb_agg(jsonb_build_object('item_id', t.item, 'base_score', t.base_score, 'candidate_score', t.candidate_score, 'base_output', t.base_output, 'candidate_output', t.candidate_output) order by t.item) filter (where t.kind = 'regression'), '[]'::jsonb),
      'improvements', coalesce(jsonb_agg(jsonb_build_object('item_id', t.item, 'base_score', t.base_score, 'candidate_score', t.candidate_score) order by t.item) filter (where t.kind = 'improvement'), '[]'::jsonb),
      'unchanged', count(*) filter (where t.kind = 'unchanged'),
      'missing', count(*) filter (where t.kind = 'missing')
    )
    from tagged t
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.compare_rfq (
  rfq_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."rfqs";
begin
  select * into v_row from "better_supabase"."rfqs" x where x."id" = compare_rfq.rfq_id;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'rfqs.read'), false))) then
    raise exception 'no such request for quotation' using errcode = 'P0002', hint = 'RFQ_NOT_FOUND';
  end if;
  return jsonb_build_object(
    'currency', v_row."currency", 'rfqId', v_row."id",
    'lines', coalesce((
      select jsonb_agg(jsonb_build_object(
        'lineId', ln."id", 'ordinal', ln."ordinal", 'description', ln."description", 'quantity', ln."quantity",
        'offers', coalesce((
          select jsonb_agg(jsonb_build_object(
            'quoteId', y."id", 'invitationId', y."invitation_id", 'unitAmount', z."unit_amount"::text,
            'lineTotal', round(z."unit_amount" * ln."quantity")::bigint::text,
            'leadTimeDays', coalesce(z."lead_time_days", y."lead_time_days"),
            'lowest', z."unit_amount" = (
              select min(z2."unit_amount") from "better_supabase"."rfq_quote_lines" z2 join "better_supabase"."rfq_quotes" y2 on y2."id" = z2."quote_id"
              where z2."line_id" = ln."id" and y2."status" in ('submitted', 'awarded')
            )
          ) order by z."unit_amount", y."submitted_at", y."id")
          from "better_supabase"."rfq_quote_lines" z join "better_supabase"."rfq_quotes" y on y."id" = z."quote_id"
          where z."line_id" = ln."id" and y."status" in ('submitted', 'awarded')
        ), '[]'::jsonb)
      ) order by ln."ordinal")
      from "better_supabase"."rfq_lines" ln where ln."rfq_id" = v_row."id"
    ), '[]'::jsonb),
    'quotes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'quoteId', c.id, 'invitationId', c.invitation_id, 'supplierType', c.supplier_type, 'supplierId', c.supplier_id,
        'status', c.status, 'total', c.total::text, 'leadTimeDays', c.lead_time_days, 'validUntil', c.valid_until,
        'complete', c.complete,
        'lowest', c.complete and c.total = c.best
      ) order by c.total, c.submitted_at, c.id)
      from (
        select d.*, min(d.total) filter (where d.complete) over () as best
        from (
        select y."id" as id, y."invitation_id" as invitation_id, i."supplier_type" as supplier_type,
          i."supplier_id" as supplier_id, y."status" as status, y."total_amount" as total,
          y."lead_time_days" as lead_time_days, y."valid_until" as valid_until, y."submitted_at" as submitted_at,
          (select count(*) from "better_supabase"."rfq_quote_lines" z where z."quote_id" = y."id")
            = (select count(*) from "better_supabase"."rfq_lines" ln where ln."rfq_id" = v_row."id") as complete
        from "better_supabase"."rfq_quotes" y join "better_supabase"."rfq_suppliers" i on i."id" = y."invitation_id"
        where y."rfq_id" = v_row."id" and y."status" in ('submitted', 'awarded')
        ) d
      ) c
    ), '[]'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_activity (
  activity uuid,
  done     boolean,
  outcome  text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_id uuid := complete_activity.activity;
  v_tenant uuid;
  v_type text;
  v_subjects jsonb := coalesce((select jsonb_agg(jsonb_build_object('type', sx."subject_type", 'id', sx."subject_id") order by sx."position") from "better_supabase"."activity_subjects" sx where sx."activity_id" = complete_activity.activity), '[]'::jsonb);
  v_first jsonb := v_subjects -> 0;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if exists (select 1 from "better_supabase"."activities" x where x."id" = v_id and (auth.role() = 'service_role' or x."created_by" = auth.uid() or x."owner_id" = auth.uid() or coalesce(better_supabase.can('tenant', x."tenant_id", 'activities.manage'), false)) and (x."locked_at" <= now() or x."marked_error_at" is not null)) then
    raise exception 'the activity is locked: add an addendum with amend_activity instead' using errcode = '55000', hint = 'ACTIVITY_LOCKED';
  end if;
  update "better_supabase"."activities" x set
    "done_at" = case when complete_activity.done then coalesce(x."done_at", now()) end,
    "outcome" = coalesce(complete_activity.outcome, x."outcome"),
    "updated_at" = now()
  where x."id" = v_id and (auth.role() = 'service_role' or x."created_by" = auth.uid() or x."owner_id" = auth.uid() or coalesce(better_supabase.can('tenant', x."tenant_id", 'activities.manage'), false))
  returning x."tenant_id", x."type" into v_tenant, v_type;
  if v_tenant is null then
    raise exception 'no such activity you can edit' using errcode = 'P0002', hint = 'ACTIVITY_NOT_FOUND';
  end if;
  if complete_activity.done then
    perform "better_supabase".emit_event('activity.completed', jsonb_build_object('organizationId', v_tenant, 'activityId', v_id, 'type', v_type, 'subjectType', v_first ->> 'type', 'subjectId', v_first ->> 'id', 'subjects', v_subjects), 'activities/' || v_id::text, (v_tenant::text)::text, null, 'better-supabase/activities');
  end if;
  return (select to_jsonb(x) || jsonb_build_object('subjects', coalesce((select jsonb_agg(jsonb_build_object('type', sx."subject_type", 'id', sx."subject_id") order by sx."position") from "better_supabase"."activity_subjects" sx where sx."activity_id" = x."id"), '[]'::jsonb), 'overdue', x."done_at" is null and x."due_at" < now()) from "better_supabase"."activities" x where x."id" = v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_checkout_session (
  session_id uuid,
  order_id   uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."checkout_sessions";
begin
  if not coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then
    raise exception 'only the service role completes checkout sessions' using errcode = '42501', hint = 'CHECKOUT_FORBIDDEN';
  end if;
  select * into v_row from "better_supabase"."checkout_sessions" x where x."id" = complete_checkout_session.session_id for update;
  if not found then
    raise exception 'no such checkout session' using errcode = 'P0002', hint = 'CHECKOUT_SESSION_NOT_FOUND';
  end if;
  if v_row."status" = 'completed' then
    if v_row."order_id" = complete_checkout_session.order_id then
      return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'cartId', v_row."cart_id", 'protocol', v_row."protocol", 'status', v_row."status", 'buyer', v_row."buyer", 'orderId', v_row."order_id", 'expiresAt', v_row."expires_at", 'expired', (v_row."status" in ('open', 'ready') and v_row."expires_at" is not null and v_row."expires_at" <= now()), 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
    end if;
    raise exception 'the session completed with another order' using errcode = '55000', hint = 'CHECKOUT_SESSION_FINAL';
  end if;
  if v_row."status" = 'canceled' then
    raise exception 'the session is canceled' using errcode = '55000', hint = 'CHECKOUT_SESSION_FINAL';
  end if;
  if complete_checkout_session.order_id is null then
    raise exception 'order_id is required' using errcode = '22023', hint = 'CHECKOUT_INVALID';
  end if;
  if not exists (
    select 1 from "better_supabase"."orders" o
    where o."id" = complete_checkout_session.order_id
      and o."cart_id" = v_row."cart_id"
      and o."tenant_id" = v_row."tenant_id"
  ) then
    raise exception 'the order is not the one placed from the session''s cart' using errcode = '22023', hint = 'CHECKOUT_INVALID';
  end if;
  update "better_supabase"."checkout_sessions" x set "status" = 'completed', "order_id" = complete_checkout_session.order_id, "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('checkout_session.completed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'cartId', v_row."cart_id", 'protocol', v_row."protocol", 'status', v_row."status", 'orderId', v_row."order_id"), 'checkout-sessions/' || v_row."id"::text, (v_row."tenant_id")::text, 'checkout_session.completed:' || v_row."id"::text || ':' || v_row."status", 'better-supabase/agent-checkout');
  perform better_supabase.audit_event(
    event_type => 'checkout_session.completed',
    category => 'data',
    target_type => 'checkout_session',
    record_id => v_row."id"::text,
    summary => 'checkout session completed',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'cartId', v_row."cart_id", 'protocol', v_row."protocol", 'status', v_row."status", 'orderId', v_row."order_id"),
    idempotency_key => 'checkout_session.completed:' || v_row."id"::text || ':' || v_row."status"
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'cartId', v_row."cart_id", 'protocol', v_row."protocol", 'status', v_row."status", 'buyer', v_row."buyer", 'orderId', v_row."order_id", 'expiresAt', v_row."expires_at", 'expired', (v_row."status" in ('open', 'ready') and v_row."expires_at" is not null and v_row."expires_at" <= now()), 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_course_lesson (
  lesson_id uuid,
  done      boolean DEFAULT true
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_lesson "better_supabase"."course_lessons";
  v_row "better_supabase"."enrollments";
  v_before timestamptz;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_lesson from "better_supabase"."course_lessons" x where x."id" = complete_course_lesson.lesson_id;
  if v_lesson."id" is null then
    raise exception 'course lesson not found' using errcode = 'P0002', hint = 'COURSE_LESSON_NOT_FOUND';
  end if;
  select * into v_row from "better_supabase"."enrollments" x
  where x."tenant_id" = v_lesson."tenant_id" and x."program" = ('course:' || v_lesson."course_id"::text)
    and x."subject_type" = 'user' and x."subject_id" = auth.uid()::text and x."status" <> 'cancelled'
  for update;
  if v_row."id" is null then
    raise exception 'you are not enrolled in this course' using errcode = 'P0002', hint = 'COURSE_NOT_ENROLLED';
  end if;
  if v_lesson."kind" = 'quiz' then
    raise exception 'a quiz lesson completes when you pass its quiz' using errcode = '22023', hint = 'COURSE_INVALID';
  end if;
  select x."completed_at" into v_before from "better_supabase"."course_lesson_progress" x
  where x."enrollment_id" = v_row."id" and x."lesson_id" = v_lesson."id";
  if complete_course_lesson.done then
    insert into "better_supabase"."course_lesson_progress" ("enrollment_id", "lesson_id", "tenant_id", "course_id", "user_id", "completed_at")
    values (v_row."id", v_lesson."id", v_lesson."tenant_id", v_lesson."course_id", auth.uid(), now())
    on conflict on constraint "course_lesson_progress_pkey" do update
    set "completed_at" = coalesce("better_supabase"."course_lesson_progress"."completed_at", now()), "updated_at" = now();
    perform "better_supabase"."course_lesson_done"(v_row."id", v_lesson."id", v_before is null);
  else
    update "better_supabase"."course_lesson_progress" x set "completed_at" = null, "updated_at" = now()
    where x."enrollment_id" = v_row."id" and x."lesson_id" = v_lesson."id";
    if v_lesson."required" then
      perform "better_supabase"."enrollment_ensure"(v_row."tenant_id", v_row."program", null, "better_supabase"."course_steps"(v_lesson."course_id"), 'user', v_row."subject_id", auth.uid());
      perform "better_supabase"."enrollment_mark"(v_row."id", v_lesson."id"::text, false, auth.uid());
    end if;
  end if;
  return "better_supabase"."course_learner_json"(v_row."id");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_data_export (
  id    uuid,
  files text[]
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."data_exports";
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'Only the service role runs exports' using errcode = '42501', hint = 'DATA_EXPORT_FORBIDDEN';
  end if;
  update "better_supabase"."data_exports" x set "status" = 'ready', "files" = complete_data_export.files,
    "completed_at" = now(), "expires_at" = now() + '7 days'::interval
  where x."id" = complete_data_export.id and x."status" = 'running'
  returning * into v_row;
  if v_row."id" is null then
    raise exception 'No running export has this id' using errcode = 'P0002', hint = 'DATA_EXPORT_NOT_FOUND';
  end if;
  delete from "better_supabase"."data_export_contents" c where c."export_id" = v_row."id";
  perform "better_supabase".emit_event('data_export.completed', jsonb_build_object('exportId', v_row."id", 'subject', v_row."subject", 'organizationId', v_row."tenant_id"::text, 'userId', v_row."user_id", 'requestedBy', v_row."requested_by", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'files', to_jsonb(v_row."files"), 'expiresAt', v_row."expires_at"), 'data-exports/' || v_row."id"::text, (v_row."tenant_id")::text, 'data_export.completed:' || v_row."id"::text || ':' || v_row."completed_at"::text, 'better-supabase/data-lifecycle');
  perform better_supabase.audit_event(
    event_type => 'data_export.completed',
    category => 'data',
    target_type => 'data_export',
    record_id => v_row."id"::text,
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('exportId', v_row."id", 'subject', v_row."subject", 'organizationId', v_row."tenant_id"::text, 'userId', v_row."user_id", 'requestedBy', v_row."requested_by", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'files', to_jsonb(v_row."files"), 'expiresAt', v_row."expires_at"),
    idempotency_key => 'data_export.completed:' || v_row."id"::text || ':' || v_row."completed_at"::text
  );
  return to_jsonb(v_row);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_enrollment_step (
  enrollment_id uuid,
  step          text
)
  RETURNS jsonb
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select "better_supabase"."enrollment_step"(complete_enrollment_step.enrollment_id, complete_enrollment_step.step, true)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_idempotent (
  scope       text,
  key         text,
  holder      uuid,
  status_code integer,
  response    jsonb
)
  RETURNS boolean
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  with done as (
    update "better_supabase"."idempotency_keys" k
    set "status" = 'completed', "status_code" = complete_idempotent.status_code,
        "response" = complete_idempotent.response, "lock_expires_at" = null, "holder" = null
    where k."scope" = complete_idempotent.scope and k."key" = complete_idempotent.key
      and k."status" = 'running' and k."holder" = complete_idempotent.holder
    returning 1
  )
  select exists (select 1 from done)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_import_chunk (
  run    uuid,
  entity text,
  chunk  integer,
  result jsonb
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
begin
  update "better_supabase"."import_chunks" x set "status" = 'done', "done_at" = now(), "result" = complete_import_chunk.result
  where x."run_id" = complete_import_chunk.run and x."entity" = complete_import_chunk.entity
    and x."chunk" = complete_import_chunk.chunk and x."status" = 'claimed';
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_inspection (
  inspection_id uuid,
  summary       text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."inspections";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."inspections" x where x."id" = complete_inspection.inspection_id for update;
  if not found then
    raise exception 'no such inspection' using errcode = 'P0002', hint = 'INSPECTION_NOT_FOUND';
  end if;
  if not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'inspections.manage'), false))) or (auth.uid() is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'inspections.write'), false) and coalesce("better_supabase"."inspection_role"(v_row."id") in ('lead'), false))) then
    raise exception 'not allowed to complete this inspection' using errcode = '42501', hint = 'INSPECTION_FORBIDDEN';
  end if;
  if v_row."status" <> 'in_progress' then
    raise exception 'the inspection can''t move from % to %', v_row."status", 'reporting' using errcode = '55000', hint = 'INSPECTION_STATUS_INVALID', detail = jsonb_build_object('from', v_row."status", 'to', 'reporting')::text;
  end if;
  if length(complete_inspection.summary) > 20000 then
    raise exception 'summary is at most 20000 characters' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  if v_row."checklist_form_id" is not null and not exists (
    select 1 from "better_supabase"."form_submissions" y
    where y."id" = v_row."checklist_submission_id" and y."status"::text in ('submitted', 'accepted')
  ) then
    raise exception 'submit the checklist before completing the inspection' using errcode = '55000', hint = 'INSPECTION_CHECKLIST_INCOMPLETE';
  end if;
  update "better_supabase"."inspections" x set
    "status" = 'reporting',
    "completed_at" = now(),
    "summary" = coalesce(nullif(trim(complete_inspection.summary), ''), x."summary"),
    "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('inspection.completed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'kind', v_row."kind", 'title', v_row."title", 'status', v_row."status"), 'inspections/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/inspections');
  perform better_supabase.audit_event(
    event_type => 'inspection.completed',
    category => 'data',
    target_type => 'inspection',
    record_id => v_row."id"::text,
    target_label => v_row."title",
    summary => 'inspection completed',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'kind', v_row."kind", 'title', v_row."title", 'status', v_row."status")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'programId', v_row."program_id", 'number', v_row."number", 'kind', v_row."kind", 'title', v_row."title", 'scope', v_row."scope", 'criteria', v_row."criteria", 'auditee', case when v_row."auditee_type" is null then null else jsonb_build_object('type', v_row."auditee_type", 'id', v_row."auditee_id") end, 'leadId', v_row."lead_id", 'plannedStart', v_row."planned_start", 'plannedEnd', v_row."planned_end", 'startedAt', v_row."started_at", 'completedAt', v_row."completed_at", 'closedAt', v_row."closed_at", 'status', v_row."status", 'checklistFormId', v_row."checklist_form_id", 'checklistSubmissionId', v_row."checklist_submission_id", 'summary', v_row."summary", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_job (
  queue   text,
  job_id  bigint,
  attempt integer
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  hit bigint;
begin
  execute format('select msg_id from pgmq.%I where msg_id = $1 and read_ct = $2 for update', 'q_' || queue)
    into hit using job_id, attempt;
  if hit is null then
    return false;
  end if;
  return pgmq.archive(queue, job_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_lease (
  scope        text,
  key          text,
  holder       uuid,
  keep_seconds integer DEFAULT 86400
)
  RETURNS boolean
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  with done as (
    update "better_supabase"."job_leases" l
    set "state" = 'completed',
        "expires_at" = now() + make_interval(secs => greatest(coalesce(complete_lease.keep_seconds, 86400), 1))
    where l."scope" = complete_lease.scope and l."key" = complete_lease.key
      and l."holder" = complete_lease.holder and l."state" = 'held'
    returning 1
  )
  select exists (select 1 from done)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_notification_delivery (
  delivery            uuid,
  status              text,
  provider            text    DEFAULT NULL::text,
  provider_message_id text    DEFAULT NULL::text,
  error               text    DEFAULT NULL::text,
  max_attempts        integer DEFAULT 5,
  template_key        text    DEFAULT NULL::text
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_status text := complete_notification_delivery.status;
begin
  if v_status is null or v_status not in ('sent', 'failed', 'skipped', 'pending') then
    raise exception 'status must be sent, failed, skipped or pending' using errcode = '22023', hint = 'NOTIFICATION_STATUS_UNKNOWN';
  end if;
  if v_status = 'pending' and exists (
    select 1 from "better_supabase"."notification_deliveries" d
    where d."id" = complete_notification_delivery.delivery
      and d."attempts" >= greatest(1, coalesce(complete_notification_delivery.max_attempts, 5))
  ) then
    v_status := 'failed';
  end if;
  update "better_supabase"."notification_deliveries" d
  set "status" = v_status,
    "provider" = coalesce(complete_notification_delivery.provider, d."provider"),
    "provider_message_id" = coalesce(complete_notification_delivery.provider_message_id, d."provider_message_id"),
    "error" = complete_notification_delivery.error,
    "template_key" = coalesce(complete_notification_delivery.template_key, d."template_key"),
    "delivered_at" = case when v_status = 'sent' then now() else d."delivered_at" end,
    "attempted_at" = case when v_status = 'pending' then null else d."attempted_at" end,
    "next_attempt_at" = case when v_status = 'pending' then now() + make_interval(secs => 1 + floor(random() * least(3600, 30 * power(2, greatest(d."attempts", 1) - 1)))) else d."next_attempt_at" end
  where d."id" = complete_notification_delivery.delivery;
  return v_status;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_notification_digest (
  digest              uuid,
  status              text,
  provider_message_id text    DEFAULT NULL::text,
  error               text    DEFAULT NULL::text,
  max_attempts        integer DEFAULT 5
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_outcome text := complete_notification_digest.status;
begin
  if v_outcome is null or v_outcome not in ('sent', 'failed', 'skipped', 'pending') then
    raise exception 'status must be sent, failed, skipped or pending' using errcode = '22023', hint = 'NOTIFICATION_STATUS_UNKNOWN';
  end if;
  if v_outcome = 'pending' and exists (
    select 1 from "better_supabase"."notification_digests" x
    where x."id" = complete_notification_digest.digest
      and x."attempts" >= greatest(1, coalesce(complete_notification_digest.max_attempts, 5))
  ) then
    v_outcome := 'failed';
  end if;
  update "better_supabase"."notification_digests" x set "status" = v_outcome,
    "provider_message_id" = coalesce(complete_notification_digest.provider_message_id, x."provider_message_id"),
    "error" = complete_notification_digest.error,
    "sent_at" = case when v_outcome = 'sent' then now() else x."sent_at" end,
    "attempted_at" = case when v_outcome = 'pending' then null else x."attempted_at" end
  where x."id" = complete_notification_digest.digest;
  return v_outcome;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_onboarding_step (
  checklist text,
  step      text,
  tenant    uuid DEFAULT NULL::uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_scope text;
begin
  v_scope := (select s.scope from (values ('getting-started', 'customer', 'organization'), ('getting-started', 'invite', 'organization'), ('getting-started', 'api-key', 'organization'), ('getting-started', 'plan', 'organization')) as s(checklist, step, scope) where s.checklist = complete_onboarding_step.checklist and (complete_onboarding_step.step is null or s.step = complete_onboarding_step.step) limit 1);
  if v_scope is null then
    raise exception 'Unknown onboarding step %.%', complete_onboarding_step.checklist, coalesce(complete_onboarding_step.step, '*') using errcode = '22023', hint = 'ONBOARDING_STEP_UNKNOWN';
  end if;
  if v_scope = 'organization' then
    if complete_onboarding_step.tenant is null then
      raise exception 'Checklist % belongs to an organization', complete_onboarding_step.checklist using errcode = '22023', hint = 'ONBOARDING_SCOPE';
    end if;
  elsif complete_onboarding_step.tenant is not null then
    raise exception 'Checklist % belongs to a user', complete_onboarding_step.checklist using errcode = '22023', hint = 'ONBOARDING_SCOPE';
  elsif auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501', hint = 'ONBOARDING_FORBIDDEN';
  end if;
  if v_scope = 'organization' and not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', complete_onboarding_step.tenant, 'onboarding.complete'), false)) then
    raise exception 'You may not complete this organization''s onboarding' using errcode = '42501', hint = 'ONBOARDING_FORBIDDEN';
  end if;
  return "better_supabase"."enrollment_mark"("better_supabase"."enrollment_ensure"(case when v_scope = 'organization' then complete_onboarding_step.tenant end, 'onboarding:' || complete_onboarding_step.checklist, null, (select c.steps from (values ('getting-started', 'organization', array['customer', 'invite', 'api-key', 'plan']::text[])) as c(checklist, scope, steps) where c.checklist = complete_onboarding_step.checklist), v_scope, case when v_scope = 'organization' then complete_onboarding_step.tenant::text else auth.uid()::text end, auth.uid()), complete_onboarding_step.step, true, auth.uid());
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_pick_list (
  pick_list_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_list "better_supabase"."pick_lists";
  v_wave "better_supabase"."pick_waves";
  v_short integer;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_list from "better_supabase"."pick_lists" x where x."id" = complete_pick_list.pick_list_id for update;
  if not found then
    raise exception 'no such pick list' using errcode = 'P0002', hint = 'WAREHOUSE_PICK_LIST_NOT_FOUND';
  end if;
  if not coalesce(((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_list."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_list."tenant_id", 'warehouse.manage'), false))) or ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_list."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_list."tenant_id", 'warehouse.pick'), false))) and coalesce(v_list."assignee_id" is null or v_list."assignee_id" = auth.uid(), false))), false) then
    raise exception 'not allowed to pick from this list' using errcode = '42501', hint = 'WAREHOUSE_FORBIDDEN';
  end if;
  if v_list."status" <> 'open' then
    raise exception 'only an open pick list is completed' using errcode = '55000', hint = 'WAREHOUSE_STATE';
  end if;
  if v_list."wave_id" is not null and (select x."status" from "better_supabase"."pick_waves" x where x."id" = v_list."wave_id") <> 'released' then
    raise exception 'the wave isn''t released yet' using errcode = '55000', hint = 'WAREHOUSE_STATE';
  end if;
  update "better_supabase"."pick_lines" y set "status" = case when y."picked" >= y."quantity" then 'picked' else 'short' end
  where y."pick_list_id" = v_list."id" and y."status" = 'open';
  select count(*) into v_short from "better_supabase"."pick_lines" y where y."pick_list_id" = v_list."id" and y."status" = 'short';
  update "better_supabase"."pick_lists" x set "status" = 'picked', "picked_at" = now()
  where x."id" = v_list."id"
  returning * into v_list;
  if v_list."task_id" is not null then
    update "better_supabase"."work_items" i set "state" = 'completed'
    where i."id" = v_list."task_id"
      and i."state" not in ('completed', 'canceled');
  end if;
  perform "better_supabase".emit_event('pick_list.picked', jsonb_build_object('organizationId', v_list."tenant_id", 'id', v_list."id", 'waveId', v_list."wave_id", 'locationId', v_list."location_id", 'documentType', v_list."document_type", 'documentId', v_list."document_id", 'status', v_list."status", 'short', v_short), 'pick-lists/' || v_list."id"::text, (v_list."tenant_id")::text, null, 'better-supabase/warehouse');
  perform better_supabase.audit_event(
    event_type => 'pick_list.picked',
    category => 'data',
    target_type => 'pick_list',
    record_id => v_list."id"::text,
    summary => 'pick list completed',
    tenant => (v_list."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_list."tenant_id", 'id', v_list."id", 'waveId', v_list."wave_id", 'locationId', v_list."location_id", 'documentType', v_list."document_type", 'documentId', v_list."document_id", 'status', v_list."status", 'short', v_short)
  );
  if v_list."wave_id" is not null and not exists (select 1 from "better_supabase"."pick_lists" x where x."wave_id" = v_list."wave_id" and x."status" = 'open') then
    update "better_supabase"."pick_waves" x set "status" = 'completed', "completed_at" = now()
    where x."id" = v_list."wave_id" and x."status" = 'released'
    returning * into v_wave;
    if v_wave."id" is not null then
      perform "better_supabase".emit_event('pick_wave.completed', jsonb_build_object('organizationId', v_wave."tenant_id", 'id', v_wave."id", 'name', v_wave."name", 'locationId', v_wave."location_id", 'status', v_wave."status"), 'pick-waves/' || v_wave."id"::text, (v_wave."tenant_id")::text, null, 'better-supabase/warehouse');
  perform better_supabase.audit_event(
    event_type => 'pick_wave.completed',
    category => 'data',
    target_type => 'pick_wave',
    record_id => v_wave."id"::text,
    target_label => v_wave."name",
    summary => 'pick wave completed',
    tenant => (v_wave."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_wave."tenant_id", 'id', v_wave."id", 'name', v_wave."name", 'locationId', v_wave."location_id", 'status', v_wave."status")
  );
    end if;
  end if;
  return "better_supabase"."pick_list_json"(v_list."id");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_production_order (
  order_id uuid,
  produced numeric,
  scrap    numeric DEFAULT 0,
  lot      jsonb   DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."production_orders";
  v_bom "better_supabase"."boms";
  v_component record;
  v_tracking text;
  v_item_currency text;
  v_currency text;
  v_lot uuid;
  v_material bigint;
  v_labor bigint;
  v_scrap numeric := coalesce(complete_production_order.scrap, 0);
  v_claims text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."production_orders" x where x."id" = complete_production_order.order_id for update;
  if not found then
    raise exception 'no such production order' using errcode = 'P0002', hint = 'PRODUCTION_ORDER_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'manufacturing.produce'), false))) then
    raise exception 'not allowed to complete production orders' using errcode = '42501', hint = 'MANUFACTURING_FORBIDDEN';
  end if;
  if v_row."status" not in ('released', 'in_progress') then
    raise exception 'the production order can''t move from % to %', v_row."status", 'done' using errcode = '55000', hint = 'PRODUCTION_ORDER_STATUS_INVALID', detail = jsonb_build_object('from', v_row."status", 'to', 'done')::text;
  end if;
  if complete_production_order.produced is null or complete_production_order.produced <= 0 or v_scrap < 0 then
    raise exception 'produced must be more than zero and scrap zero or more' using errcode = '22023', hint = 'PRODUCTION_ORDER_INVALID';
  end if;
  if complete_production_order.lot is not null and jsonb_typeof(complete_production_order.lot) <> 'object' then
    raise exception 'lot must be an object' using errcode = '22023', hint = 'PRODUCTION_ORDER_INVALID';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_production_order_complete"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  select * into v_bom from "better_supabase"."boms" x where x."id" = v_row."bom_id";
  for v_component in
    select y."variant_id" as variant,
      "better_supabase"."production_quantity"(y."variant_id", y."quantity" * (complete_production_order.produced + v_scrap) / v_bom."quantity" * (1 + y."scrap_bps" / 10000.0)) as quantity
    from "better_supabase"."bom_components" y where y."bom_id" = v_bom."id"
      and not exists (select 1 from "better_supabase"."production_consumptions" z where z."order_id" = v_row."id" and z."variant_id" = y."variant_id")
    order by y."position", y."id"
  loop
    perform "better_supabase"."production_consume"(v_row."id", v_component.variant, v_component.quantity, null);
  end loop;
  v_claims := current_setting('request.jwt.claims', true);
  perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
  perform "better_supabase"."release_allocations"(v_row."tenant_id", 'production_order', v_row."id"::text);
  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  update "better_supabase"."production_order_operations" x set "status" = 'done', "started_at" = coalesce(x."started_at", now()),
    "finished_at" = now(), "minutes" = coalesce(x."minutes", x."planned_minutes")
  where x."order_id" = v_row."id" and x."status" <> 'done';

  select x."tracking", x."currency" into v_tracking, v_item_currency
  from "better_supabase"."stock_items" x where x."variant_id" = v_row."variant_id";
  v_currency := coalesce(v_item_currency,
    (select min(z."currency") from "better_supabase"."production_consumptions" z where z."order_id" = v_row."id"),
    (select min(y."currency") from "better_supabase"."production_order_operations" x join "better_supabase"."work_centers" y on y."id" = x."work_center_id"
      where x."order_id" = v_row."id"));
  select coalesce(sum(z."cost"), 0) into v_material from "better_supabase"."production_consumptions" z
  where z."order_id" = v_row."id" and z."currency" is not distinct from v_currency;
  select coalesce(sum(round(x."minutes" * y."cost_rate" / 60.0)), 0)::bigint into v_labor
  from "better_supabase"."production_order_operations" x join "better_supabase"."work_centers" y on y."id" = x."work_center_id"
  where x."order_id" = v_row."id" and y."currency" = v_currency;

  v_lot := nullif(complete_production_order.lot ->> 'lotId', '')::uuid;
  if v_lot is null and (nullif(complete_production_order.lot ->> 'code', '') is not null or v_tracking = 'lot') then
    v_lot := "better_supabase"."stock_lot_for"(v_row."tenant_id", v_row."variant_id",
      coalesce(nullif(complete_production_order.lot ->> 'code', ''), v_row."number"),
      nullif(complete_production_order.lot ->> 'expiresOn', '')::date);
  end if;
  perform "better_supabase"."move_stock"(v_row."tenant_id", v_row."variant_id", v_row."location_id", complete_production_order.produced, 'production', 'production_order', v_row."id"::text, null, jsonb_strip_nulls(jsonb_build_object('lotId', v_lot, 'serials', complete_production_order.lot -> 'serials',
      'unitCost', round((v_material + v_labor)::numeric / complete_production_order.produced, 6)::text, 'currency', v_item_currency)));
  if v_lot is not null then
    insert into "better_supabase"."stock_lot_links" ("tenant_id", "parent_lot_id", "child_lot_id", "order_id", "quantity")
    select v_row."tenant_id", v_lot, z."lot_id", v_row."id", sum(z."quantity")
    from "better_supabase"."production_consumptions" z where z."order_id" = v_row."id" and z."lot_id" is not null and z."lot_id" <> v_lot
    group by z."lot_id";
  end if;
  update "better_supabase"."production_orders" x set "status" = 'done', "produced_quantity" = complete_production_order.produced, "scrap_quantity" = v_scrap,
    "output_lot_id" = v_lot, "material_cost" = v_material, "labor_cost" = v_labor, "currency" = v_currency,
    "started_at" = coalesce(x."started_at", now()), "completed_at" = now(), "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  if v_labor > 0 then
    if not better_supabase.import_run() is not null then
    perform "better_supabase"."accounting_post_source"('production_order', v_row."id"::text);
  end if;
  end if;
  perform "better_supabase".emit_event('production_order.completed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'variantId', v_row."variant_id", 'quantity', v_row."quantity"::text, 'status', v_row."status", 'producedQuantity', v_row."produced_quantity"::text, 'scrapQuantity', v_row."scrap_quantity"::text, 'outputLotId', v_row."output_lot_id"), 'production-orders/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/manufacturing');
  perform better_supabase.audit_event(
    event_type => 'production_order.completed',
    category => 'data',
    target_type => 'production_order',
    record_id => v_row."id"::text,
    target_label => v_row."number",
    summary => 'production order completed',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'variantId', v_row."variant_id", 'quantity', v_row."quantity"::text, 'status', v_row."status", 'producedQuantity', v_row."produced_quantity"::text, 'scrapQuantity', v_row."scrap_quantity"::text, 'outputLotId', v_row."output_lot_id")
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_production_order_complete"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return (jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'number', v_row."number", 'variantId', v_row."variant_id", 'bomId', v_row."bom_id", 'quantity', v_row."quantity"::text, 'locationId', v_row."location_id", 'dueOn', v_row."due_on", 'status', v_row."status", 'producedQuantity', v_row."produced_quantity"::text, 'scrapQuantity', v_row."scrap_quantity"::text, 'outputLotId', v_row."output_lot_id", 'materialCost', v_row."material_cost"::text, 'laborCost', v_row."labor_cost"::text, 'currency', v_row."currency", 'note', v_row."note", 'releasedAt', v_row."released_at", 'startedAt', v_row."started_at", 'completedAt', v_row."completed_at", 'canceledAt', v_row."canceled_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at") || jsonb_build_object(
    'operations', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'orderId', y."order_id", 'operationId', y."operation_id", 'sequence', y."sequence", 'workCenterId', y."work_center_id", 'title', y."title", 'plannedMinutes', y."planned_minutes"::text, 'status', y."status", 'startedAt', y."started_at", 'finishedAt', y."finished_at", 'operatorId', y."operator_id", 'minutes', y."minutes"::text, 'inspectionId', y."inspection_id") order by y."sequence")
      from "better_supabase"."production_order_operations" y where y."order_id" = v_row."id"), '[]'::jsonb),
    'components', coalesce((select jsonb_agg(jsonb_build_object('componentId', y."id", 'variantId', y."variant_id",
        'quantity', "better_supabase"."production_quantity"(y."variant_id", y."quantity" * v_row."quantity" / x."quantity" * (1 + y."scrap_bps" / 10000.0))::text,
        'allocated', coalesce(al."allocated", 0)::text, 'backordered', coalesce(al."backordered", 0)::text,
        'consumed', coalesce((select sum(z."quantity") from "better_supabase"."production_consumptions" z
          where z."order_id" = v_row."id" and z."variant_id" = y."variant_id"), 0)::text)
      order by y."position", y."id")
      from "better_supabase"."boms" x join "better_supabase"."bom_components" y on y."bom_id" = x."id"
      left join "better_supabase"."stock_allocations" al on al."tenant_id" = v_row."tenant_id"
        and al."document_type" = 'production_order' and al."document_id" = v_row."id"::text
        and al."line_id" = y."id"::text and al."status" = 'open'
      where x."id" = v_row."bom_id"), '[]'::jsonb),
    'consumptions', coalesce((select jsonb_agg(jsonb_build_object('id', z."id", 'variantId', z."variant_id", 'lotId', z."lot_id",
        'serial', z."serial", 'quantity', z."quantity"::text, 'cost', z."cost"::text, 'currency', z."currency",
        'movementId', z."movement_id", 'createdAt', z."created_at") order by z."created_at", z."id")
      from "better_supabase"."production_consumptions" z where z."order_id" = v_row."id"), '[]'::jsonb)));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_push_receipts (
  receipts jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
  v_events jsonb := '[]'::jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role reads push tickets' using errcode = '42501', hint = 'PUSH_FORBIDDEN';
  end if;
  if jsonb_typeof(complete_push_receipts.receipts) <> 'array' or jsonb_array_length(complete_push_receipts.receipts) > 1000 then
    raise exception 'pass at most 1000 receipts' using errcode = '22023', hint = 'PUSH_TOO_MANY';
  end if;
  -- The delivery's provider message id is Expo's first ticket id, so every
  -- receipt of the delivery records its event on that message, once per
  -- ticket. The events stored now come back for the client to emit.
  select coalesce(jsonb_agg(e.recorded || jsonb_build_object('provider_event_id', e.event_id)), '[]'::jsonb)
  into v_events
  from (
    select "better_supabase"."record_delivery_event"(
      'expo',
      d."provider_message_id",
      case when r ->> 'status' = 'ok' then 'delivered' else 'bounced' end,
      'expo-receipt:' || (r ->> 'id'),
      now(),
      jsonb_strip_nulls(jsonb_build_object('token', x."token", 'error', r ->> 'error', 'message', r ->> 'message')),
      false
    ) as recorded, 'expo-receipt:' || (r ->> 'id') as event_id
    from "better_supabase"."push_tickets" x
    join "better_supabase"."notification_deliveries" d on d."id" = x."delivery_id"
    cross join jsonb_array_elements(complete_push_receipts.receipts) r
    where x."ticket_id" = r ->> 'id'
      and x."checked_at" is null
      and d."provider_message_id" is not null
  ) e
  where coalesce((e.recorded ->> 'recorded')::boolean, false);
  update "better_supabase"."push_tickets" x set
    "status" = case when r ->> 'status' = 'ok' then 'ok' else 'error' end,
    "error" = case when r ->> 'status' = 'ok' then null else coalesce(r ->> 'error', 'Unknown') end,
    "checked_at" = now()
  from jsonb_array_elements(complete_push_receipts.receipts) r
  where x."ticket_id" = r ->> 'id'
    and x."checked_at" is null;
  get diagnostics v_count = row_count;
  return jsonb_build_object('updated', v_count, 'events', v_events);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_refund (
  refund             uuid,
  status             text,
  provider_reference text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_refund record;
  v_order record;
  v_total bigint;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'only the service role can do this' using errcode = '42501', hint = 'ORDERS_FORBIDDEN';
  end if;
  if complete_refund.status is null or complete_refund.status not in ('pending', 'succeeded', 'failed') then
    raise exception 'status is pending, succeeded or failed' using errcode = '22023', hint = 'ORDERS_REFUND_STATUS_INVALID';
  end if;
  select x."id" as id, x."order_id" as order_id, x."payment_id" as payment, x."amount" as amount,
    x."status" as status
  into v_refund from "better_supabase"."order_refunds" x
  where (complete_refund.refund is not null and x."id" = complete_refund.refund)
    or (complete_refund.refund is null and x."provider_reference" = complete_refund.provider_reference)
  for update;
  if not found then
    raise exception 'refund not found' using errcode = 'P0002', hint = 'ORDERS_REFUND_NOT_FOUND';
  end if;
  select x."id" as id, x."tenant_id" as tenant, x."number" as number, x."customer_id" as customer, x."status" as status, x."currency" as currency, x."total" as total, x."paid_total" as paid_total, x."refunded_total" as refunded_total, x."tax_total" as tax_total, x."tax_inclusive" as tax_inclusive, x."invoice_number" as invoice_number, x."placed_at" as placed_at into v_order from "better_supabase"."orders" x where x."id" = v_refund.order_id for update;
  if not found then
    raise exception 'order not found' using errcode = 'P0002', hint = 'ORDERS_ORDER_NOT_FOUND';
  end if;
  if v_refund.status = 'pending' and complete_refund.status = 'pending' then
    update "better_supabase"."order_refunds" x set "provider_reference" = coalesce(complete_refund.provider_reference, x."provider_reference")
    where x."id" = v_refund.id;
  elsif v_refund.status = 'pending' then
    update "better_supabase"."order_refunds" x set "status" = complete_refund.status, "completed_at" = now(),
      "provider_reference" = coalesce(complete_refund.provider_reference, x."provider_reference")
    where x."id" = v_refund.id;
    if complete_refund.status = 'succeeded' then
      update "better_supabase"."order_payments" x set "refunded" = x."refunded" + v_refund.amount, "updated_at" = now()
      where x."id" = v_refund.payment;
      update "better_supabase"."orders" x set "refunded_total" = x."refunded_total" + v_refund.amount, "updated_at" = now()
      where x."id" = v_order.id
      returning x."refunded_total" into v_total;
      if v_total >= v_order.paid_total and v_order.status in ('paid', 'fulfilled', 'completed') then
        perform "better_supabase"."order_transition"(v_order.id, 'refunded');
      end if;
      perform "better_supabase".emit_event('order.refunded', jsonb_build_object('organizationId', v_order.tenant, 'subjectType', 'order', 'subjectId', v_order.id::text, 'id', v_order.id, 'number', v_order.number, 'customerId', v_order.customer, 'currency', v_order.currency, 'amount', v_refund.amount::text, 'refundedTotal', v_total::text, 'status', (select x."status" from "better_supabase"."orders" x where x."id" = v_order.id)), 'orders/' || v_order.id::text, (v_order.tenant)::text, 'order.refunded:' || v_refund.id::text, 'better-supabase/orders');
    end if;
  end if;
  return (select jsonb_build_object('id', x."id", 'orderId', x."order_id", 'status', x."status",
      'amount', x."amount"::text, 'orderStatus', y."status", 'refundedTotal', y."refunded_total"::text)
    from "better_supabase"."order_refunds" x join "better_supabase"."orders" y on y."id" = x."order_id" where x."id" = v_refund.id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_sample (
  sample_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."lims_samples";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."lims_samples" x where x."id" = complete_sample.sample_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'lims.read'), false))) then
    raise exception 'no such sample' using errcode = 'P0002', hint = 'LIMS_SAMPLE_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'lims.write'), false))) then
    raise exception 'not allowed to complete samples' using errcode = '42501', hint = 'LIMS_FORBIDDEN';
  end if;
  if v_row."status" <> 'in_testing' then
    raise exception 'only a sample in testing can be completed' using errcode = '22023', hint = 'LIMS_INVALID';
  end if;
  update "better_supabase"."lims_samples" x set "status" = 'completed', "completed_at" = now(), "updated_at" = now()
  where x."id" = v_row."id" returning * into v_row;
  perform "better_supabase".emit_event('lims_sample.completed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'status', v_row."status"), 'lims-samples/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/lims');
  perform better_supabase.audit_event(
    event_type => 'lims_sample.completed',
    category => 'data',
    target_type => 'lims_sample',
    record_id => v_row."id"::text,
    target_label => v_row."number",
    summary => 'sample testing completed',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'status', v_row."status")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'number', v_row."number", 'title', v_row."title", 'kind', v_row."kind", 'lot', v_row."lot", 'receivedOn', v_row."received_on", 'status', v_row."status", 'notes', v_row."notes", 'rejectionReason', v_row."rejection_reason", 'completedAt', v_row."completed_at", 'releasedAt', v_row."released_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_saved_item (
  item      uuid,
  completed boolean DEFAULT true
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  update "better_supabase"."saved_items" s
    set "completed_at" = case when complete_saved_item.completed then coalesce(s."completed_at", now()) end
    where s."id" = complete_saved_item.item and s."user_id" = auth.uid();
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_webhook (
  inbox_id bigint,
  worker   text,
  attempt  integer DEFAULT NULL::integer
)
  RETURNS boolean
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  with done as (
    update better_supabase.webhook_inbox
    set status = 'processed', processed_at = now(), locked_by = null, lock_expires_at = null, last_error = null
    where id = inbox_id and locked_by = worker and status = 'processing'
      and (attempt is null or attempts = attempt)
    returning 1
  )
  select exists (select 1 from done)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.complete_webhook_delivery (
  delivery uuid,
  outcome  jsonb
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_status text := complete_webhook_delivery.outcome ->> 'status';
  v_attempt integer := (complete_webhook_delivery.outcome ->> 'attempt')::integer;
  v_endpoint uuid;
  v_tenant uuid;
  v_since timestamptz;
  v_result text := 'ok';
begin
  if v_status is null or v_status not in ('succeeded', 'retrying', 'dead', 'canceled') then
    raise exception 'status must be succeeded, retrying, dead or canceled' using errcode = '22023', hint = 'WEBHOOK_STATUS_UNKNOWN';
  end if;
  if v_attempt is null then
    raise exception 'outcome.attempt must be the attempt the claim returned' using errcode = '22023', hint = 'WEBHOOK_ATTEMPT_REQUIRED';
  end if;
  update "better_supabase"."webhook_deliveries" v
  set "status" = v_status,
    "attempt" = case when v_status = 'canceled' then greatest(v."attempt" - 1, 0) else v."attempt" end,
    "available_at" = case when v_status = 'retrying' then coalesce((complete_webhook_delivery.outcome ->> 'retry_at')::timestamptz, now()) else v."available_at" end,
    "lease_expires_at" = null,
    "response_status" = (complete_webhook_delivery.outcome ->> 'response_status')::integer,
    "response_body" = complete_webhook_delivery.outcome ->> 'response_body',
    "duration_ms" = (complete_webhook_delivery.outcome ->> 'duration_ms')::integer,
    "last_error" = complete_webhook_delivery.outcome ->> 'error',
    "processed_at" = case when v_status = 'retrying' then null else now() end,
    "updated_at" = now()
  where v."id" = complete_webhook_delivery.delivery
    and v."attempt" = v_attempt
    and v."status" = 'delivering'
  returning v."endpoint_id" into v_endpoint;
  if not found then
    if exists (select 1 from "better_supabase"."webhook_deliveries" v where v."id" = complete_webhook_delivery.delivery) then
      return 'stale';
    end if;
    raise exception 'Webhook delivery not found' using errcode = 'P0002', hint = 'WEBHOOK_DELIVERY_NOT_FOUND';
  end if;
  if v_status = 'succeeded' then
    update "better_supabase"."webhook_endpoints" d set "first_failed_at" = null
    where d."id" = v_endpoint and d."first_failed_at" is not null;
  elsif v_status in ('retrying', 'dead') then
    update "better_supabase"."webhook_endpoints" d set "first_failed_at" = coalesce(d."first_failed_at", now())
    where d."id" = v_endpoint
    returning d."first_failed_at", d."tenant_id" into v_since, v_tenant;
    if v_since <= now() - '5 days'::interval then
      update "better_supabase"."webhook_endpoints" d set "enabled" = false, "disabled_at" = now(), "disabled_reason" = format('Deliveries failed since %s', v_since), "updated_at" = now()
      where d."id" = v_endpoint and d."enabled";
      if found then
        v_result := 'disabled';
        perform "better_supabase".emit_event('webhook_endpoint.disabled', jsonb_build_object('endpointId', v_endpoint, 'organizationId', v_tenant::text, 'failingSince', v_since), 'webhooks/' || v_endpoint::text, (v_tenant::text)::text, 'webhook_endpoint.disabled:' || v_endpoint::text || ':' || v_since::text, 'better-supabase/webhooks-out');
  perform better_supabase.audit_event(
    event_type => 'webhook_endpoint.disabled',
    category => 'integration',
    target_type => 'webhook_endpoint',
    record_id => v_endpoint::text,
    tenant => (v_tenant::text)::uuid,
    metadata => jsonb_build_object('endpointId', v_endpoint, 'organizationId', v_tenant::text, 'failingSince', v_since),
    idempotency_key => 'webhook_endpoint.disabled:' || v_endpoint::text || ':' || v_since::text
  );
      end if;
    end if;
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_webhook_delivery"(uuid, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text)', v_hook::oid::regproc)
        using complete_webhook_delivery.delivery, v_status;
    end if;
  end;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.compute_deadline (
  tenant       uuid,
  subject_type text,
  subject_id   text,
  jurisdiction text,
  kind         text,
  rule_key     text,
  facts        jsonb DEFAULT '{}'::jsonb,
  as_of        date  DEFAULT CURRENT_DATE
)
  RETURNS jsonb
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select "better_supabase"."compute_deadlines"(tenant, subject_type, subject_id, jurisdiction, kind, facts, as_of, rule_key) -> 0
$function$;

CREATE OR REPLACE FUNCTION better_supabase.compute_deadlines (
  tenant       uuid,
  subject_type text,
  subject_id   text,
  jurisdiction text,
  kind         text,
  facts        jsonb DEFAULT '{}'::jsonb,
  as_of        date  DEFAULT CURRENT_DATE,
  group_key    text  DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_version jsonb;
  v_results jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (compute_deadlines.tenant is not null and coalesce(better_supabase.can('tenant', compute_deadlines.tenant, 'deadlines.write'), false))) then
    raise exception 'not allowed to compute deadlines' using errcode = '42501', hint = 'DEADLINE_FORBIDDEN';
  end if;
  if compute_deadlines.subject_type is null or compute_deadlines.subject_type !~ '^[a-z][a-z0-9_]{0,62}$'
    or compute_deadlines.subject_id is null or length(compute_deadlines.subject_id) not between 1 and 200
    or compute_deadlines.facts is null or jsonb_typeof(compute_deadlines.facts) <> 'object'
    or compute_deadlines.as_of is null then
    raise exception 'a deadline needs a subject type, a subject id, facts as an object and a date' using errcode = '22023', hint = 'DEADLINE_INVALID';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or "better_supabase"."deadline_subject_readable"(compute_deadlines.subject_type, compute_deadlines.subject_id, compute_deadlines.tenant)) then
    raise exception 'not allowed to compute deadlines for this subject' using errcode = '42501', hint = 'DEADLINE_FORBIDDEN';
  end if;
  v_version := "better_supabase"."rule_version_at"(compute_deadlines.jurisdiction, compute_deadlines.kind, compute_deadlines.as_of);
  if v_version is null then
    raise exception 'no approved rule set version applies' using errcode = 'P0002', hint = 'DEADLINE_RULES_NOT_FOUND';
  end if;
  if compute_deadlines.group_key is not null and not exists (
    select 1 from jsonb_array_elements(v_version -> 'groups') g(value) where g.value ->> 'key' = compute_deadlines.group_key
  ) then
    raise exception 'the rule set has no group with this key' using errcode = 'P0002', hint = 'DEADLINE_RULE_NOT_FOUND';
  end if;
  v_results := "better_supabase"."evaluate_deadlines"(
    jsonb_build_object('rules', v_version -> 'rules', 'groups', v_version -> 'groups', 'counting', v_version -> 'counting'),
    compute_deadlines.facts, compute_deadlines.as_of, compute_deadlines.group_key);
  return "better_supabase"."deadline_store"(compute_deadlines.tenant, compute_deadlines.subject_type, compute_deadlines.subject_id,
    compute_deadlines.jurisdiction, compute_deadlines.kind, (v_version ->> 'id')::uuid, compute_deadlines.facts, compute_deadlines.as_of,
    v_results, case when compute_deadlines.group_key is null
      then array(
        select g.value ->> 'key' from jsonb_array_elements(v_version -> 'groups') g(value)
        union
        select x."group_key" from "better_supabase"."deadlines" x
        where x."tenant_id" = compute_deadlines.tenant and x."subject_type" = compute_deadlines.subject_type
          and x."subject_id" = compute_deadlines.subject_id and x."jurisdiction" = compute_deadlines.jurisdiction
          and x."kind" = compute_deadlines.kind)
      else array[compute_deadlines.group_key] end) -> 'rows';
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.compute_document_tax (
  lines                  jsonb,
  on_date                date,
  prices_include_tax     boolean DEFAULT false,
  credit_restriction_bps integer DEFAULT 0
)
