    target_label => v_row."name",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'serverId', v_row."id", 'name', v_row."name")
  );
  return v_grants;
end;
$function$;

