CREATE OR REPLACE FUNCTION better_supabase.delete_work_items (
  ids uuid[]
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."work_items";
  v_ids uuid[] := '{}';
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  for v_row in
    with removed as (
      delete from "better_supabase"."work_items" x
      where x."id" = any (coalesce(delete_work_items.ids, '{}'))
        and ((auth.role() = 'service_role') or x."created_by" = auth.uid() or coalesce(better_supabase.can('tenant', x."tenant_id", 'tasks.manage'), false))
      returning x.*
    )
    select * from removed
  loop
    v_ids := array_append(v_ids, v_row."id");
    perform "better_supabase".emit_event('work_item.deleted', jsonb_build_object('organizationId', v_row."tenant_id", 'workItemId', v_row."id", 'subjectType', 'work_item', 'subjectId', v_row."id"::text, 'title', v_row."title"), 'work_items/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/tasks');
  end loop;
  return jsonb_build_object(
    'ids', to_jsonb(v_ids),
    'skipped', to_jsonb(array(select distinct i from unnest(coalesce(delete_work_items.ids, '{}')) i where i is not null and not (i = any (v_ids)))));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.deliver_fulfillment (
  fulfillment uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_fulfillment record;
  v_order record;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."id" as id, x."order_id" as order_id, x."status" as status into v_fulfillment
  from "better_supabase"."order_fulfillments" x where x."id" = deliver_fulfillment.fulfillment for update;
  if not found then
    raise exception 'fulfillment not found' using errcode = 'P0002', hint = 'ORDERS_FULFILLMENT_NOT_FOUND';
  end if;
  select x."id" as id, x."tenant_id" as tenant, x."number" as number, x."customer_id" as customer, x."status" as status, x."currency" as currency, x."total" as total, x."paid_total" as paid_total, x."refunded_total" as refunded_total, x."tax_total" as tax_total, x."tax_inclusive" as tax_inclusive, x."invoice_number" as invoice_number, x."placed_at" as placed_at into v_order from "better_supabase"."orders" x where x."id" = v_fulfillment.order_id for update;
  if not found then
    raise exception 'order not found' using errcode = 'P0002', hint = 'ORDERS_ORDER_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_order.tenant, 'orders.manage'), false)) then
    raise exception 'not allowed to manage these orders' using errcode = '42501', hint = 'ORDERS_FORBIDDEN';
  end if;
  if v_fulfillment.status = 'delivered' then
    return false;
  end if;
  if v_fulfillment.status <> 'shipped' then
    raise exception 'only a shipped fulfillment can be delivered' using errcode = '55000', hint = 'ORDERS_TRANSITION_INVALID';
  end if;
  update "better_supabase"."order_fulfillments" x set "status" = 'delivered', "delivered_at" = now() where x."id" = v_fulfillment.id;
  perform "better_supabase".emit_event('fulfillment.delivered', jsonb_build_object('organizationId', v_order.tenant, 'subjectType', 'order', 'subjectId', v_order.id::text, 'id', v_fulfillment.id, 'orderId', v_order.id, 'number', v_order.number), 'orders/' || v_order.id::text, (v_order.tenant)::text, null, 'better-supabase/orders');
  if v_order.status = 'fulfilled'
    and not exists (select 1 from "better_supabase"."order_fulfillments" x where x."order_id" = v_order.id and x."status" in ('pending', 'shipped')) then
    perform "better_supabase"."order_transition"(v_order.id, 'completed');
    perform "better_supabase".emit_event('order.completed', jsonb_build_object('organizationId', v_order.tenant, 'subjectType', 'order', 'subjectId', v_order.id::text, 'id', v_order.id, 'number', v_order.number, 'customerId', v_order.customer), 'orders/' || v_order.id::text, (v_order.tenant)::text, null, 'better-supabase/orders');
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.delivery_preference_write (
  tenant uuid,
  data   jsonb,
  id     uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."document_delivery_preferences";
begin
  if jsonb_typeof(delivery_preference_write.data) is distinct from 'object'
    or coalesce(delivery_preference_write.data ->> 'partyId', '') !~ '^[0-9a-fA-F-]{36}$'
    or length(coalesce(trim(delivery_preference_write.data ->> 'documentType'), '')) not between 1 and 100
    or coalesce(delivery_preference_write.data ->> 'channel', '') not in ('email', 'post', 'portal')
    or coalesce(delivery_preference_write.data ->> 'copies', '1') !~ '^[0-9]{1,2}$'
    or coalesce(nullif(delivery_preference_write.data ->> 'copies', '')::integer, 1) not between 1 and 20
    or (delivery_preference_write.data ->> 'email' is not null and lower(trim(delivery_preference_write.data ->> 'email')) !~ '^[^@[:space:]]+@[^@[:space:]]+$') then
    raise exception 'a delivery preference needs a party, a document type and a channel of email, post or portal' using errcode = '22023', hint = 'DELIVERY_PREFERENCE_INVALID';
  end if;
  insert into "better_supabase"."document_delivery_preferences" ("tenant_id", "party_id", "document_type", "channel", "copies", "email")
  values (delivery_preference_write.tenant, (delivery_preference_write.data ->> 'partyId')::uuid, trim(delivery_preference_write.data ->> 'documentType'),
    delivery_preference_write.data ->> 'channel', coalesce(nullif(delivery_preference_write.data ->> 'copies', '')::integer, 1),
    nullif(lower(trim(delivery_preference_write.data ->> 'email')), ''))
  on conflict ("tenant_id", "party_id", "document_type", "channel") do update
    set "copies" = excluded."copies", "email" = excluded."email", "updated_at" = now()
  returning * into v_row;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'partyId', v_row."party_id", 'documentType', v_row."document_type", 'channel', v_row."channel", 'copies', v_row."copies", 'email', v_row."email");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.deposit_till_cash (
  session_id uuid,
  input      jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_input jsonb := coalesce(deposit_till_cash.input, '{}'::jsonb);
  v_session "better_supabase"."till_sessions";
  v_till "better_supabase"."tills";
  v_count "better_supabase"."till_counts";
  v_amount bigint;
  v_on date;
  v_entry uuid;
  v_row "better_supabase"."till_deposits";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_session from "better_supabase"."till_sessions" x where x."id" = deposit_till_cash.session_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_session."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_session."tenant_id", 'tills.read'), false))) then
    raise exception 'no such till session' using errcode = 'P0002', hint = 'TILL_SESSION_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_session."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_session."tenant_id", 'tills.manage'), false))) then
    raise exception 'not allowed to deposit till cash' using errcode = '42501', hint = 'TILL_FORBIDDEN';
  end if;
  select * into v_count from "better_supabase"."till_counts" x where x."session_id" = v_session."id";
  if v_session."status" <> 'closed' or v_count."id" is null then
    raise exception 'cash can only be deposited from a closed, counted session' using errcode = '55000', hint = 'TILL_STATUS';
  end if;
  if coalesce(v_input ->> 'amount', '') !~ '^[0-9]{1,18}$' or (v_input ->> 'amount')::bigint = 0 then
    raise exception 'amount is above zero, in minor units' using errcode = '22023', hint = 'TILL_INVALID';
  end if;
  v_amount := (v_input ->> 'amount')::bigint;
  if coalesce(v_input ->> 'depositedOn', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
    v_on := (v_input ->> 'depositedOn')::date;
  elsif nullif(v_input ->> 'depositedOn', '') is null then
    v_on := (now() at time zone 'UTC')::date;
  else
    raise exception 'depositedOn is a date such as 2026-10-31' using errcode = '22023', hint = 'TILL_INVALID';
  end if;
  if v_amount + coalesce((select sum(y."amount") from "better_supabase"."till_deposits" y where y."session_id" = v_session."id"), 0) > v_count."counted_amount" then
    raise exception 'the deposits would exceed the counted cash of the session' using errcode = '22023', hint = 'TILL_INVALID';
  end if;
  select * into v_till from "better_supabase"."tills" x where x."id" = v_session."till_id";
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_till_deposit"(uuid, bigint)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::bigint)', v_hook::oid::regproc)
        using v_session."id", v_amount;
    end if;
  end;
  begin
    insert into "better_supabase"."till_deposits" ("tenant_id", "session_id", "amount", "deposited_on", "reference", "created_by")
    values (v_session."tenant_id", v_session."id", v_amount, v_on, nullif(trim(v_input ->> 'reference'), ''), auth.uid())
    returning * into v_row;
  exception when check_violation then
    raise exception 'a reference is up to 200 characters' using errcode = '22023', hint = 'TILL_INVALID';
  end;
  if not better_supabase.import_run() is not null then
    v_entry := "better_supabase"."accounting_post_source"('till_deposit', v_row."id"::text);
  end if;
  if v_entry is not null then
    update "better_supabase"."till_deposits" x set "entry_id" = v_entry where x."id" = v_row."id" returning * into v_row;
  end if;
  perform "better_supabase".emit_event('till_deposit.recorded', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'sessionId', v_row."session_id", 'amount', v_row."amount"::text, 'status', v_row."status", 'bankTransactionId', v_row."bank_transaction_id"), 'tills/' || v_till."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/tills');
  perform better_supabase.audit_event(
    event_type => 'till_deposit.recorded',
    category => 'data',
    target_type => 'till',
    record_id => v_till."id"::text,
    target_label => v_till."name",
    summary => 'cash deposit recorded',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'sessionId', v_row."session_id", 'amount', v_row."amount"::text, 'status', v_row."status", 'bankTransactionId', v_row."bank_transaction_id")
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_till_deposit"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return jsonb_build_object('id', v_row."id", 'currency', (select bt."currency" from "better_supabase"."tills" bt join "better_supabase"."till_sessions" bs on bs."till_id" = bt."id" where bs."id" = v_row."session_id"), 'sessionId', v_row."session_id", 'amount', v_row."amount"::text, 'depositedOn', v_row."deposited_on", 'reference', v_row."reference", 'status', v_row."status", 'entryId', v_row."entry_id", 'bankTransactionId', v_row."bank_transaction_id", 'reconciledAt', v_row."reconciled_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.descendants (
  tenant       uuid,
  kind         text,
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('type', w.type, 'id', w.id, 'depth', w.depth) order by w.depth, w.type, w.id), '[]'::jsonb)
  from "better_supabase"."relation_walk"(descendants.tenant, descendants.kind, descendants.subject_type, descendants.subject_id, false, null) w
$function$;

CREATE OR REPLACE FUNCTION better_supabase.detach_template_workflow (
  template_id uuid,
  definition  uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_tpl "better_supabase"."templates"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_tpl from "better_supabase"."templates" x where x."id" = detach_template_workflow.template_id;
  if not found then
    return false;
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_tpl."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_tpl."tenant_id", 'templates.manage'), false))) then
    raise exception 'You may not change this template' using errcode = '42501', hint = 'TEMPLATE_FORBIDDEN';
  end if;
  delete from "better_supabase"."template_workflows" w where w."template_id" = detach_template_workflow.template_id
    and w."definition_id" = detach_template_workflow.definition;
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.disable_service_principal (
  principal  uuid,
  created_by uuid DEFAULT NULL::uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."service_principals";
begin
  select * into v_row from "better_supabase"."service_principals" p where p."id" = disable_service_principal.principal and p."disabled_at" is null for update;
  if not found then
    return false;
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'Service principals are managed by the service' using errcode = '42501', hint = 'SERVICE_PRINCIPAL_FORBIDDEN';
  end if;
  if disable_service_principal.created_by is not null and not (
    coalesce(better_supabase.member_can(disable_service_principal.created_by, v_row."tenant_id", 'service_accounts.manage'), false)
    and coalesce(better_supabase.can_assign_as(disable_service_principal.created_by, v_row."tenant_id", v_row."role"), false)
  ) then
    raise exception 'You may not manage service principals with this role' using errcode = '42501', hint = 'SERVICE_PRINCIPAL_FORBIDDEN';
  end if;
  update "better_supabase"."service_principals" set "disabled_at" = now(), "is_default" = false where "id" = v_row."id";
  delete from "public"."memberships" where "organization_id" = v_row."tenant_id" and "user_id" = v_row."id";
  perform "better_supabase".emit_event('service_principal.disabled', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'id', v_row."id"), 'service-principals/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/service-accounts');
  perform better_supabase.audit_event(
    event_type => 'service_principal.disabled',
    category => 'access',
    target_type => 'service_principal',
    record_id => v_row."id"::text,
    target_label => v_row."name",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'id', v_row."id"),
    actor_id => coalesce(disable_service_principal.created_by, auth.uid())
  );
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.discard_inbox_draft (
  draft uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."inbox_drafts"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."inbox_drafts" where "id" = discard_inbox_draft.draft for update;
  if not found or v_row."status" <> 'draft' or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or ((v_row."author_id" = (select auth.uid()) or v_row."source" = 'ai') and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'inbox.reply'), false))) then
    raise exception 'draft not found' using errcode = 'P0002', hint = 'INBOX_DRAFT_NOT_FOUND';
  end if;
  update "better_supabase"."inbox_drafts" set "status" = 'discarded' where "id" = v_row."id";
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.disconnect_mail_account (
  account uuid,
  purge   boolean
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."mail_accounts";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."mail_accounts" x
  where x."id" = disconnect_mail_account.account
    and (x."user_id" = auth.uid() or coalesce(better_supabase.can('tenant', x."tenant_id", 'mail_sync.manage'), false));
  if v_row."id" is null then
    return false;
  end if;
  if coalesce(disconnect_mail_account.purge, false) then
    delete from "better_supabase"."mail_accounts" x where x."id" = v_row."id";
  else
    update "better_supabase"."mail_accounts" x set "status" = 'disconnected', "sync_cursor" = null, "updated_at" = now()
    where x."id" = v_row."id";
  end if;
  perform "better_supabase".emit_event('mail_account.disconnected', jsonb_build_object('organizationId', v_row."tenant_id", 'accountId', v_row."id", 'userId', v_row."user_id", 'provider', v_row."provider", 'address', v_row."address"), 'mail-accounts/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/mail-sync');
  perform better_supabase.audit_event(
    event_type => 'mail_account.disconnected',
    category => 'integration',
    target_type => 'mail_account',
    record_id => v_row."id"::text,
    target_label => v_row."address",
    tenant => (v_row."tenant_id"::text)::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'accountId', v_row."id", 'userId', v_row."user_id", 'provider', v_row."provider", 'address', v_row."address")
  );
  return true;
end;
$function$;

