CREATE OR REPLACE FUNCTION better_supabase.due_ai_batches (
  batch         integer DEFAULT 20,
  lease_seconds integer DEFAULT 300
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_rows jsonb;
begin
  with due as (
    select y."id" from "better_supabase"."ai_batches" y
    where (y."status" = 'pending' or not y."results_saved") and y."next_poll_at" <= now()
    order by y."next_poll_at"
    limit least(greatest(due_ai_batches.batch, 1), 200)
    for update skip locked
  ), claimed as (
    update "better_supabase"."ai_batches" x set
      "polls" = x."polls" + 1,
      "next_poll_at" = now() + make_interval(secs => greatest(due_ai_batches.lease_seconds, 1)),
      "updated_at" = now()
    from due where x."id" = due."id"
    returning x.*
  )
  select coalesce(jsonb_agg(jsonb_build_object('id', claimed."id", 'tenant_id', claimed."tenant_id", 'user_id', claimed."user_id", 'provider', claimed."provider", 'reference', claimed."reference", 'status', claimed."status", 'raw_status', claimed."raw_status", 'item_count', claimed."item_count", 'counts', claimed."counts", 'error', claimed."error", 'metadata', claimed."metadata", 'results_saved', claimed."results_saved", 'polls', claimed."polls", 'next_poll_at', claimed."next_poll_at", 'expires_at', claimed."expires_at", 'completed_at', claimed."completed_at", 'created_at', claimed."created_at", 'updated_at', claimed."updated_at")), '[]') into v_rows from claimed;
  return v_rows;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.due_care_plan_reviews()
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_plan "better_supabase"."care_plans"%rowtype;
  v_row "better_supabase"."care_plan_actions"%rowtype;
  v_due timestamptz;
  v_claims text;
  v_count integer := 0;
begin
  for v_plan in
    select * from "better_supabase"."care_plans" x
    where x."status" = 'active' and x."review_on" <= current_date
      and x."review_notified_for" is distinct from x."review_on"
    for update skip locked
  loop
    perform "better_supabase".emit_event('care_plan.review_date_reached', jsonb_build_object('organizationId', v_plan."tenant_id", 'id', v_plan."id", 'subjectType', v_plan."subject_type", 'subjectId', v_plan."subject_id", 'title', v_plan."title", 'status', v_plan."status", 'version', v_plan."version", 'ownerId', v_plan."owner_id", 'reviewOn', v_plan."review_on"), 'care-plans/' || v_plan."id"::text, (v_plan."tenant_id")::text, null, 'better-supabase/care-plans');
  perform better_supabase.audit_event(
    event_type => 'care_plan.review_date_reached',
    category => 'data',
    target_type => 'care_plan',
    record_id => v_plan."id"::text,
    target_label => v_plan."title",
    summary => 'care plan review due',
    tenant => (v_plan."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_plan."tenant_id", 'id', v_plan."id", 'subjectType', v_plan."subject_type", 'subjectId', v_plan."subject_id", 'title', v_plan."title", 'status', v_plan."status", 'version', v_plan."version", 'ownerId', v_plan."owner_id", 'reviewOn', v_plan."review_on")
  );
    if v_plan."owner_id" is not null then
      if better_supabase.import_run() is null then
        v_claims := current_setting('request.jwt.claims', true);
        perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
        perform "better_supabase"."notify"(jsonb_build_object(
        'type', 'care_plan.review_date_reached',
        'tenant', v_plan."tenant_id",
        'actor', null,
        'subject_type', 'care_plan',
        'subject_id', v_plan."id"::text,
        'summary', v_plan."title",
        'recipients', to_jsonb(array[v_plan."owner_id"]),
        'key', 'care_plan.review_date_reached:' || v_plan."id"::text || ':' || v_plan."review_on"::text,
        'data', jsonb_build_object('planId', v_plan."id", 'reviewOn', v_plan."review_on")
      ));
        perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
      end if;
    end if;
    update "better_supabase"."care_plans" x set "review_notified_for" = v_plan."review_on" where x."id" = v_plan."id";
    v_count := v_count + 1;
  end loop;
  for v_row in
    select w.* from "better_supabase"."care_plan_actions" w
    join "better_supabase"."care_plans" x on x."id" = w."plan_id" and x."status" = 'active'
    where w."status" = 'active' and w."review_every" is not null
      and coalesce(w."reviewed_at", w."started_at") + w."review_every" <= now()
      and w."review_notified_at" is distinct from coalesce(w."reviewed_at", w."started_at") + w."review_every"
    for update of w skip locked
  loop
    v_due := coalesce(v_row."reviewed_at", v_row."started_at") + v_row."review_every";
    select * into v_plan from "better_supabase"."care_plans" x where x."id" = v_row."plan_id";
    perform "better_supabase".emit_event('care_plan_action.review_date_reached', jsonb_build_object('organizationId', v_plan."tenant_id", 'planId', v_plan."id", 'subjectType', v_plan."subject_type", 'subjectId', v_plan."subject_id") || jsonb_build_object('actionId', v_row."id", 'kind', v_row."kind", 'title', v_row."title", 'ownerId', v_plan."owner_id", 'dueAt', v_due), 'care-plans/' || v_plan."id"::text, (v_plan."tenant_id")::text, null, 'better-supabase/care-plans');
  perform better_supabase.audit_event(
    event_type => 'care_plan_action.review_date_reached',
    category => 'data',
    target_type => 'care_plan',
    record_id => v_plan."id"::text,
    target_label => v_plan."title",
    summary => 'care plan action review due',
    tenant => (v_plan."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_plan."tenant_id", 'planId', v_plan."id", 'subjectType', v_plan."subject_type", 'subjectId', v_plan."subject_id") || jsonb_build_object('actionId', v_row."id", 'kind', v_row."kind", 'title', v_row."title", 'ownerId', v_plan."owner_id", 'dueAt', v_due)
  );
    if v_plan."owner_id" is not null then
      if better_supabase.import_run() is null then
        v_claims := current_setting('request.jwt.claims', true);
        perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
        perform "better_supabase"."notify"(jsonb_build_object(
        'type', 'care_plan_action.review_date_reached',
        'tenant', v_plan."tenant_id",
        'actor', null,
        'subject_type', 'care_plan',
        'subject_id', v_plan."id"::text,
        'summary', v_plan."title",
        'recipients', to_jsonb(array[v_plan."owner_id"]),
        'key', 'care_plan_action.review_date_reached:' || v_row."id"::text || ':' || v_due::text,
        'data', jsonb_build_object('planId', v_plan."id", 'actionId', v_row."id", 'dueAt', v_due)
      ));
        perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
      end if;
    end if;
    update "better_supabase"."care_plan_actions" w set "review_notified_at" = v_due where w."id" = v_row."id";
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.due_check_updated_at (
  subject_id text
)
  RETURNS timestamp WITH time zone
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select x."updated_at" from "better_supabase".asset_due_checks x where x."id"::text = due_check_updated_at.subject_id
$function$;

CREATE OR REPLACE FUNCTION better_supabase.due_mail_accounts (
  max_count   integer,
  stale_after interval
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role syncs mailboxes' using errcode = '42501', hint = 'MAIL_FORBIDDEN';
  end if;
  return (
    select coalesce(jsonb_agg(to_jsonb(p) order by p."last_synced_at" nulls first, p."id"), '[]'::jsonb)
    from (
      select * from "better_supabase"."mail_accounts" x
      where x."status" = 'active'
        and (x."last_synced_at" is null or x."last_synced_at" < now() - coalesce(due_mail_accounts.stale_after, interval '5 minutes'))
      order by x."last_synced_at" nulls first, x."id"
      limit least(greatest(coalesce(due_mail_accounts.max_count, 25), 1), 500)
    ) p
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.due_organization_deletions (
  max_rows integer DEFAULT 100
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(to_jsonb(x.*) order by x."purge_at"), '[]'::jsonb)
  from (
    select * from "better_supabase"."organization_deletions" y
    where y."purge_at" <= now() and y."cancelled_at" is null and y."purged_at" is null
    order by y."purge_at"
    limit greatest(1, least(due_organization_deletions.max_rows, 1000))
  ) x
$function$;

CREATE OR REPLACE FUNCTION better_supabase.due_pledge_installments (
  tenant   uuid,
  through  date    DEFAULT NULL::date,
  max_rows integer DEFAULT 500
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_through date := coalesce(due_pledge_installments.through, current_date);
  v_max integer := least(greatest(coalesce(due_pledge_installments.max_rows, 500), 1), 5000);
  v_row "better_supabase"."pledges"%rowtype;
  v_items jsonb := '[]'::jsonb;
  v_n integer;
  v_start date;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', due_pledge_installments.tenant, 'donations.manage'), false)) then
    raise exception 'not allowed to manage donations' using errcode = '42501', hint = 'DONATIONS_FORBIDDEN';
  end if;
  <<installments>>
  for v_row in
    select * from "better_supabase"."pledges" x
    where x."tenant_id" = due_pledge_installments.tenant and x."status" = 'active' and x."starts_on" <= v_through
    order by x."starts_on", x."id"
  loop
    v_n := 0;
    loop
      v_start := (v_row."starts_on" + v_n * (case v_row."frequency" when 'weekly' then interval '1 week' when 'monthly' then interval '1 month' when 'quarterly' then interval '3 months' else interval '1 year' end))::date;
      exit when v_start > v_through or (v_row."ends_on" is not null and v_start >= v_row."ends_on");
      if not exists (select 1 from "better_supabase"."donations" g where g."pledge_id" = v_row."id" and g."period_start" = v_start
        and not (g."status" = 'pending' and g."payment_reference" is null)) then
        exit installments when jsonb_array_length(v_items) >= v_max;
        v_items := v_items || jsonb_build_array(jsonb_build_object('periodStart', v_start, 'pledgeId', v_row."id",
          'donorType', v_row."donor_type", 'donorId', v_row."donor_id", 'fundId', v_row."fund_id",
          'amount', v_row."amount"::text, 'currency', v_row."currency",
          'provider', v_row."provider", 'providerCustomer', v_row."provider_customer"));
      end if;
      v_n := v_n + 1;
    end loop;
  end loop;
  return v_items;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.due_template_occurrences (
  range_start timestamp with time zone,
  range_end   timestamp with time zone
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return (
  select coalesce(jsonb_agg(jsonb_build_object('schedule', d.schedule, 'tenant', d.tenant, 'occurrenceAt', d.at) order by d.at, d.schedule), '[]'::jsonb)
  from (
    select x."id" as schedule, x."tenant_id" as tenant, o.at
    from "better_supabase"."template_schedules" x
    join "better_supabase"."recurrence_rules" u on u."tenant_id" = x."tenant_id"
      and u."subject_type" = 'template_schedule'
      and u."subject_id" = x."id"::text
    cross join lateral better_supabase.rrule_occurrences(u."rrule", u."dtstart", u."tzid", tstzrange(due_template_occurrences.range_start, due_template_occurrences.range_end, '[)')) o (at)
    where x."enabled" and u."rrule" is not null
      and not exists (
        select 1 from "better_supabase"."template_schedule_runs" y
        where y."schedule_id" = x."id" and y."occurrence_at" = o.at and y."application_id" is not null
      )
    order by o.at, x."id"
    limit 5000
  ) d
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.duplicate_view (
  view_id uuid,
  scope   text,
  name    text,
  team    text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."shared_views";
begin
  select * into v_row from "better_supabase"."shared_views" where "id" = duplicate_view.view_id;
  if not found or not (auth.role() = 'service_role'
    or (coalesce(better_supabase.can('tenant', v_row."tenant_id", 'saved_views.read'), false) and (
      (v_row."scope" = 'user' and coalesce(v_row."owner_id" = auth.uid(), false))
      or (v_row."scope" = 'team' and v_row."team_id" in (select t::text from "better_supabase"."team_ids_of"((select auth.uid())) t))
      or v_row."scope" = 'tenant'))) then
    raise exception 'saved view not found' using errcode = 'P0002', hint = 'SAVED_VIEW_NOT_FOUND';
  end if;
  return "better_supabase"."save_view"(v_row."tenant_id", v_row."list",
    coalesce(duplicate_view.name, v_row."name"), v_row."kind",
    coalesce(duplicate_view.scope, 'user'), duplicate_view.team, v_row."state", null);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.e_invoice_endpoints (
  invoice uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."invoices";
  v_seller jsonb;
  v_buyer jsonb;
begin
  select * into v_row from "better_supabase"."invoices" x where x."id" = e_invoice_endpoints.invoice and ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', x."tenant_id", 'invoices.read'), false));
  if v_row."id" is null then
    raise exception 'no such invoice you can read' using errcode = 'P0002', hint = 'INVOICE_NOT_FOUND';
  end if;
  select coalesce(
    (select jsonb_build_object('scheme', e."scheme", 'id', e."endpoint_id") from "better_supabase"."e_invoice_endpoints" e where e."tenant_id" = v_row."tenant_id" and e."party_kind" = 'legal_entity' and e."party_id" = v_row.legal_entity_id::text),
    (select jsonb_build_object('scheme', e."scheme", 'id', e."endpoint_id") from "better_supabase"."e_invoice_endpoints" e where e."tenant_id" = v_row."tenant_id" and e."party_kind" = 'organization' and e."party_id" = v_row."tenant_id"::text)
  ) into v_seller;
  select jsonb_build_object('scheme', e."scheme", 'id', e."endpoint_id") into v_buyer from "better_supabase"."e_invoice_endpoints" e
  where e."tenant_id" = v_row."tenant_id" and e."party_kind" = 'company' and e."party_id" = v_row."company_id"::text;
  return jsonb_build_object('seller', v_seller, 'buyer', v_buyer);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.edit_inbox_message (
  message uuid,
  body    text    DEFAULT NULL::text,
  remove  boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_msg "better_supabase"."messages"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select m.* into v_msg from "better_supabase"."messages" m
  join "better_supabase"."inbox_message_details" d on d."message_id" = m."id"
  where m."id" = edit_inbox_message.message
  for update of m;
  if not found then
    raise exception 'message not found' using errcode = 'P0002', hint = 'MESSAGE_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_msg."author_id" is not null and coalesce(v_msg."author_id" = (select auth.uid()), false))) then
    raise exception 'only the author edits a message' using errcode = '42501', hint = 'INBOX_FORBIDDEN';
  end if;
  if v_msg."archived_at" is not null then
    raise exception 'message is deleted' using errcode = '22023', hint = 'MESSAGE_DELETED';
  end if;
  if length(coalesce(edit_inbox_message.body, '')) > 20000 then
    raise exception 'a message is at most 20000 characters' using errcode = '22023', hint = 'INBOX_MESSAGE_TOO_LONG';
  end if;
  update "better_supabase"."messages" set
    "body" = case when coalesce(remove, false) then '' else coalesce(edit_inbox_message.body, "body") end,
    "archived_at" = case when coalesce(remove, false) then now() end,
    "edited_at" = case when coalesce(remove, false) then "edited_at" else now() end
  where "id" = v_msg."id";
  perform "better_supabase"."index_record_mentions"(v_msg."id");
  if coalesce(remove, false) then
    delete from "better_supabase"."attachments" x where x."subject_type" = 'message' and x."subject_id" = v_msg."id"::text;
  end if;
  return "better_supabase"."inbox_messages_json"(array[v_msg."id"]) -> 0;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.edit_message (
  message uuid,
  body    text,
  attrs   jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_msg "better_supabase"."messages";
  v_parsed jsonb := "better_supabase"."parse_mentions"(edit_message.body);
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_msg from "better_supabase"."messages" m
  where m."id" = edit_message.message and m."author_id" = auth.uid() and m."archived_at" is null
    and "better_supabase"."can_conversation"(m."conversation_id", 'read');
  if not found then
    raise exception 'no message of yours has this id' using errcode = 'P0002', hint = 'MESSAGING_NOT_FOUND';
  end if;
  if exists (
    select 1 from "better_supabase"."conversations" c
    where c."id" = v_msg."conversation_id"
      and c."access" = 'subject' and c."subject_type" in ('drive_node')
  ) and not "better_supabase"."can_conversation"(v_msg."conversation_id", 'send') then
    raise exception 'not allowed to comment on this record' using errcode = '42501', hint = 'MESSAGING_FORBIDDEN';
  end if;
  if v_msg."sent_at" is not null and not (true) then
    raise exception 'this message can no longer be edited' using errcode = '55000', hint = 'MESSAGING_EDIT_CLOSED';
  end if;
  if nullif(trim(coalesce(edit_message.body, '')), '') is null then
    raise exception 'a message needs a body' using errcode = '23502', hint = 'MESSAGING_BODY_REQUIRED';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_message_edit"(uuid, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text)', v_hook::oid::regproc)
        using edit_message.message, edit_message.body;
    end if;
  end;
  insert into "better_supabase"."message_edits" ("tenant_id", "message_id", "body", "document", "edited_by")
  values (v_msg."tenant_id", v_msg."id", v_msg."body", v_msg."document", auth.uid());
  begin
    update "better_supabase"."messages" m set
      "body" = edit_message.body,
      "document" = case when edit_message.attrs ? 'document' then edit_message.attrs -> 'document' else m."document" end,
      "mentions" = array(
        select distinct x from (
          select (jsonb_array_elements_text(coalesce(edit_message.attrs -> 'mentions', '[]'::jsonb)))::uuid as x
          union
          select (jsonb_array_elements_text(v_parsed -> 'users'))::uuid
        ) s
      ),
      "edited_at" = now()
    where m."id" = v_msg."id"
    returning * into v_msg;
  exception when check_violation or invalid_text_representation then
    raise exception 'a message field has an invalid value' using errcode = '22023', hint = 'MESSAGING_MESSAGE_INVALID';
  end;
  if v_msg."sent_at" is not null then
    perform "better_supabase"."index_record_mentions"(v_msg."id");
    perform "better_supabase".emit_event('message.edited', jsonb_build_object('organizationId', v_msg."tenant_id"::text, 'conversationId', v_msg."conversation_id", 'messageId', v_msg."id", 'authorId', v_msg."author_id", 'threadId', v_msg."thread_id", 'subjectType', 'message', 'subjectId', v_msg."id"::text)
      || coalesce((select jsonb_build_object('conversationKind', c."kind", 'recordType', c."subject_type", 'recordId', c."subject_id") from "better_supabase"."conversations" c where c."id" = v_msg."conversation_id"), '{}'::jsonb), 'messages/' || v_msg."id"::text, (v_msg."tenant_id"::text)::text, null, 'better-supabase/messaging');
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_message_edit"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_msg."id";
    end if;
  end;
  return "better_supabase"."messaging_messages_json"(array[v_msg."id"]) -> 0;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.emit_event (
  event_type text,
  payload    jsonb DEFAULT '{}'::jsonb,
  subject    text  DEFAULT NULL::text,
  tenant     text  DEFAULT NULL::text,
  key        text  DEFAULT NULL::text,
  source     text  DEFAULT NULL::text
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  found_id text;
  v_run uuid := better_supabase.import_run();
  v_mode text;
begin
  if event_type is null or btrim(event_type) = '' then
    raise exception 'An event needs a type' using errcode = '22023', hint = 'OUTBOX_TYPE_REQUIRED';
  end if;
  -- In import mode (ADR 0141) the run's imports.events policy decides: the
  -- event type's own entry, then the default, then skip.
  if v_run is not null then
    v_mode := coalesce(
      nullif(current_setting('better_supabase.import_events', true), '')::jsonb ->> event_type,
      nullif(current_setting('better_supabase.import_events', true), '')::jsonb ->> 'default',
      'skip'
    );
    if v_mode = 'skip' then
      return null;
    elsif v_mode = 'tag' then
      payload := coalesce(payload, '{}'::jsonb) || jsonb_build_object('importRunId', v_run);
    end if;
  end if;
  if key is not null then
    select e."id"::text into found_id from "better_supabase"."outbox_events" e
    where e."key" = key and e."tenant_id" is not distinct from tenant::uuid;
    if found_id is not null then
      return found_id;
    end if;
  end if;
  insert into "better_supabase"."outbox_events" ("type", "payload", "source", "subject", "tenant_id", "key", "actor_id")
  values (event_type, coalesce(payload, '{}'), source, coalesce(subject, payload ->> 'subject'), tenant::uuid, key, auth.uid())
  on conflict do nothing
  returning "id"::text into found_id;
  if found_id is null then
    -- Another transaction emitted the same key first.
    select e."id"::text into found_id from "better_supabase"."outbox_events" e
    where e."key" = key and e."tenant_id" is not distinct from tenant::uuid;
  end if;
  return found_id;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.employee_contracts (
  employee uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_employee "better_supabase"."employees";
begin
  select * into v_employee from "better_supabase"."employees" x where x."id" = employee_contracts.employee;
  if v_employee."id" is null or not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', v_employee."tenant_id", 'employees.read_sensitive'), false) or coalesce(v_employee."user_id" = auth.uid(), false)) then
    raise exception 'no such employee whose details you can see' using errcode = 'P0002', hint = 'EMPLOYEE_NOT_FOUND';
  end if;
  return (select coalesce(jsonb_agg(to_jsonb(x) || jsonb_build_object('salary', x."salary"::text) order by x."starts_on" desc), '[]'::jsonb)
    from "better_supabase"."employee_contracts" x where x."employee_id" = v_employee."id");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.employee_from_application (
  application uuid,
  attrs       jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_application "better_supabase"."applications";
  v_job "better_supabase"."job_openings";
  v_existing "better_supabase"."employees";
begin
  select * into v_application from "better_supabase"."applications" x where x."id" = employee_from_application.application;
  if v_application."id" is null or not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', v_application."tenant_id", 'employees.write'), false)) then
    raise exception 'no such application you can turn into an employee' using errcode = 'P0002', hint = 'EMPLOYEE_ORIGIN_NOT_FOUND';
  end if;
  select * into v_existing from "better_supabase"."employees" x
  where x."tenant_id" = v_application."tenant_id" and x."origin_type" = 'application' and x."origin_id" = v_application."id"::text;
  if v_existing."id" is not null then
    return to_jsonb(v_existing);
  end if;
  if v_application."state" <> 'hired' then
    raise exception 'only a hired application becomes an employee' using errcode = '55000', hint = 'EMPLOYEE_APPLICATION_NOT_HIRED';
  end if;
  select * into v_job from "better_supabase"."job_openings" x where x."id" = v_application."job_id";
  return "better_supabase"."create_employee"(v_application."tenant_id", jsonb_strip_nulls(jsonb_build_object(
      'name', (case v_application."candidate_type"
      when 'message' then (select s."body"::text from "better_supabase"."messages" s where s."id" = (v_application."candidate_id")::uuid)
      when 'conversation' then (select s."title"::text from "better_supabase"."conversations" s where s."id" = (v_application."candidate_id")::uuid)
      when 'channel' then (select s."name"::text from "better_supabase"."channels" s where s."id" = (v_application."candidate_id")::uuid)
      when 'company' then (select s."name"::text from "better_supabase"."companies" s where s."id" = (v_application."candidate_id")::uuid)
      when 'person' then (select s."name"::text from "better_supabase"."people" s where s."id" = (v_application."candidate_id")::uuid)
      when 'deal' then (select s."name"::text from "better_supabase"."deals" s where s."id" = (v_application."candidate_id")::uuid)
      when 'course' then (select s."title"::text from "better_supabase"."courses" s where s."id" = (v_application."candidate_id")::uuid)
      when 'post' then (select s."title"::text from "better_supabase"."posts" s where s."id" = (v_application."candidate_id")::uuid)
      when 'activity' then (select s."title"::text from "better_supabase"."activities" s where s."id" = (v_application."candidate_id")::uuid)
      when 'quote' then (select s."title"::text from "better_supabase"."quotes" s where s."id" = (v_application."candidate_id")::uuid)
      when 'work_item' then (select s."title"::text from "better_supabase"."work_items" s where s."id" = (v_application."candidate_id")::uuid)
      when 'employee' then (select s."name"::text from "better_supabase"."employees" s where s."id" = (v_application."candidate_id")::uuid)
      when 'ledger_account' then (select s."name"::text from "better_supabase"."ledger_accounts" s where s."id" = (v_application."candidate_id")::uuid)
      when 'invoice' then (select s."title"::text from "better_supabase"."invoices" s where s."id" = (v_application."candidate_id")::uuid)
      when 'product' then (select s."title"::text from "better_supabase"."products" s where s."id" = (v_application."candidate_id")::uuid)
      when 'product_variant' then (select s."sku"::text from "better_supabase"."product_variants" s where s."id" = (v_application."candidate_id")::uuid)
      when 'rfq' then (select s."title"::text from "better_supabase"."rfqs" s where s."id" = (v_application."candidate_id")::uuid)
      when 'till' then (select s."name"::text from "better_supabase"."tills" s where s."id" = (v_application."candidate_id")::uuid)
      when 'order' then (select s."number"::text from "better_supabase"."orders" s where s."id" = (v_application."candidate_id")::uuid)
      when 'calendar_event' then (select s."title"::text from "better_supabase"."calendar_events" s where s."id" = (v_application."candidate_id")::uuid)
      when 'booking' then (select s."customer_name"::text from "better_supabase"."bookings" s where s."id" = (v_application."candidate_id")::uuid)
      when 'asset' then (select s."name"::text from "better_supabase"."assets" s where s."id" = (v_application."candidate_id")::uuid)
      when 'asset_location' then (select s."name"::text from "better_supabase"."asset_locations" s where s."id" = (v_application."candidate_id")::uuid)
      when 'lease' then (select s."title"::text from "better_supabase"."leases" s where s."id" = (v_application."candidate_id")::uuid)
      when 'expense_report' then (select s."title"::text from "better_supabase"."expense_reports" s where s."id" = (v_application."candidate_id")::uuid)
      when 'expense_line' then (select s."description"::text from "better_supabase"."expense_lines" s where s."id" = (v_application."candidate_id")::uuid)
      when 'donation_fund' then (select s."name"::text from "better_supabase"."donation_funds" s where s."id" = (v_application."candidate_id")::uuid)
      when 'warranty_claim' then (select s."title"::text from "better_supabase"."warranty_claims" s where s."id" = (v_application."candidate_id")::uuid)
      when 'work_order' then (select s."title"::text from "better_supabase"."work_orders" s where s."id" = (v_application."candidate_id")::uuid)
      when 'shipment' then (select s."reference"::text from "better_supabase"."shipments" s where s."id" = (v_application."candidate_id")::uuid)
      when 'contract' then (select s."title"::text from "better_supabase"."contracts" s where s."id" = (v_application."candidate_id")::uuid)
      when 'control' then (select s."title"::text from "better_supabase"."controls" s where s."id" = (v_application."candidate_id")::uuid)
      when 'compliance_policy' then (select s."title"::text from "better_supabase"."compliance_policies" s where s."id" = (v_application."candidate_id")::uuid)
      when 'qualification_type' then (select s."name"::text from "better_supabase"."qualification_types" s where s."id" = (v_application."candidate_id")::uuid)
      when 'risk' then (select s."title"::text from "better_supabase"."risks" s where s."id" = (v_application."candidate_id")::uuid)
      when 'case' then (select s."title"::text from "better_supabase"."cases" s where s."id" = (v_application."candidate_id")::uuid)
      when 'inspection' then (select s."title"::text from "better_supabase"."inspections" s where s."id" = (v_application."candidate_id")::uuid)
      when 'inspection_program' then (select s."name"::text from "better_supabase"."inspection_programs" s where s."id" = (v_application."candidate_id")::uuid)
      when 'inspection_finding' then (select s."title"::text from "better_supabase"."inspection_findings" s where s."id" = (v_application."candidate_id")::uuid)
      when 'form' then (select s."title"::text from "better_supabase"."forms" s where s."id" = (v_application."candidate_id")::uuid)
      when 'meeting' then (select s."title"::text from "better_supabase"."meetings" s where s."id" = (v_application."candidate_id")::uuid)
      when 'meeting_decision' then (select s."title"::text from "better_supabase"."meeting_decisions" s where s."id" = (v_application."candidate_id")::uuid)
      when 'maintenance_plan' then (select s."title"::text from "better_supabase"."maintenance_plans" s where s."id" = (v_application."candidate_id")::uuid)
      when 'dam_usage_right' then (select s."licensee"::text from "better_supabase"."dam_usage_rights" s where s."id" = (v_application."candidate_id")::uuid)
      when 'lims_sample' then (select s."title"::text from "better_supabase"."lims_samples" s where s."id" = (v_application."candidate_id")::uuid)
      when 'tax_code' then (select s."name"::text from "better_supabase"."tax_codes" s where s."id" = (v_application."candidate_id")::uuid)
      when 'production_order' then (select s."number"::text from "better_supabase"."production_orders" s where s."id" = (v_application."candidate_id")::uuid)
      when 'work_center' then (select s."name"::text from "better_supabase"."work_centers" s where s."id" = (v_application."candidate_id")::uuid)
      when 'bank_account' then (select s."name"::text from "better_supabase"."bank_accounts" s where s."id" = (v_application."candidate_id")::uuid)
      when 'care_plan' then (select s."title"::text from "better_supabase"."care_plans" s where s."id" = (v_application."candidate_id")::uuid)
      when 'incident' then (select s."title"::text from "better_supabase"."incidents" s where s."id" = (v_application."candidate_id")::uuid)
      when 'content_entry' then (select s."title"::text from "better_supabase"."content_entries" s where s."id" = (v_application."candidate_id")::uuid)
      when 'document' then (select s."name"::text from "better_supabase"."documents" s where s."id" = (v_application."candidate_id")::uuid)
      when 'customer' then (select s."name"::text from "public"."customers" s where s."id" = (v_application."candidate_id")::uuid)
      when 'drive_node' then (select s."name"::text from "better_supabase"."drive_nodes" s where s."id" = (v_application."candidate_id")::uuid)
      when 'organization' then (select s."name"::text from "public"."organizations" s where s."id" = (v_application."candidate_id")::uuid)
      when 'change_request' then (select s."title"::text from "public"."change_requests" s where s."id" = (v_application."candidate_id")::uuid)
      when 'project' then (select s."name"::text from "public"."projects" s where s."id" = (v_application."candidate_id")::uuid)
      when 'task' then (select s."title"::text from "public"."tasks" s where s."id" = (v_application."candidate_id")::uuid)
      else null::text
    end),
      'jobTitle', v_job."title",
      'teamId', v_job."team_id",
      'employmentType', case when v_job."employment_type" = any (array['employee', 'contractor', 'intern', 'temporary']::text[]) then v_job."employment_type" end,
      'status', 'preboarding'))
    || coalesce(employee_from_application.attrs, '{}'::jsonb)
    || jsonb_build_object('origin', jsonb_build_object('type', 'application', 'id', v_application."id"::text)));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.employee_private_details (
  employee uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_employee "better_supabase"."employees";
  v_row "better_supabase"."employee_private_details";
begin
  select * into v_employee from "better_supabase"."employees" x where x."id" = employee_private_details.employee;
  if v_employee."id" is null or not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', v_employee."tenant_id", 'employees.read_sensitive'), false) or coalesce(v_employee."user_id" = auth.uid(), false)) then
    raise exception 'no such employee whose details you can see' using errcode = 'P0002', hint = 'EMPLOYEE_NOT_FOUND';
  end if;
  select * into v_row from "better_supabase"."employee_private_details" x where x."employee_id" = v_employee."id";
  if v_row."employee_id" is null then
    return null;
  end if;
  return to_jsonb(v_row);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.encrypt_field_definition (
  definition uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_type text;
  v_key text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select "tenant_id", "type" into v_tenant, v_type from "better_supabase"."field_definitions" where "id" = encrypt_field_definition.definition;
  if not found then
    raise exception 'field not found' using errcode = 'P0002', hint = 'FIELD_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'custom_fields.manage'), false)) then
    raise exception 'not allowed to manage custom fields' using errcode = '42501', hint = 'FIELD_FORBIDDEN';
  end if;
  if v_type not in ('text', 'email', 'url', 'bsn', 'iban', 'phone_e164') then
    raise exception 'only text fields can be encrypted' using errcode = '22023', hint = 'FIELD_NOT_ENCRYPTABLE';
  end if;
  v_key := "better_supabase"."field_key"('tenant:' || v_tenant::text, true);
  update "better_supabase"."field_definitions" set "encrypted" = true where "id" = encrypt_field_definition.definition;
  update "better_supabase"."field_values" set "value_text" = "better_supabase"."field_seal"(v_key, "value_text")
  where "definition_id" = encrypt_field_definition.definition
    and "value_text" is not null
    and left("value_text", 5) <> 'bsf1:';
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.end_access (
  request_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  SET "IntervalStyle" TO 'iso_8601'
  AS $function$
declare
  v_row "better_supabase"."access_requests"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."access_requests" r where r."id" = end_access.request_id for update;
  if not found then
    raise exception 'access request not found' using errcode = 'P0002', hint = 'ACCESS_REQUEST_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(v_row."user_id" = auth.uid(), false) or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'access_requests.manage'), false)) then
    raise exception 'not allowed to end this access' using errcode = '42501', hint = 'ACCESS_REQUEST_FORBIDDEN';
  end if;
  if v_row."granted_at" is null or v_row."ended_at" is not null then
    raise exception 'this access isn''t active' using errcode = '22023', hint = 'ACCESS_NOT_GRANTED';
  end if;
  if v_row."target" = 'record' then
    case v_row."subject_type"
    when 'drive_node' then
      perform "better_supabase"."drive_grant_access"(v_row."subject_id", v_row."user_id", v_row."action", now());
    else
      if v_row."member_id" is not null then
        perform "better_supabase"."close_subject_member"(v_row."member_id");
      end if;
    end case;
  else
    -- Only a role that is still the granted one goes back; a later change wins.
    if exists (
      select 1 from "public"."memberships" m
      where m."organization_id" = v_row."tenant_id" and m."user_id" = v_row."user_id"
        and (select r."key" from "better_supabase"."roles" r where r."id" = m."role") = v_row."role"
    ) then
      if v_row."previous_role" is null then
        delete from "public"."memberships" where "organization_id" = v_row."tenant_id" and "user_id" = v_row."user_id";
      else
        update "public"."memberships" set "role" = (select r."id" from "better_supabase"."roles" r where (r."id"::text = (v_row."previous_role")::text or r."key" = (v_row."previous_role")::text) order by (r."id"::text = (v_row."previous_role")::text) desc limit 1)
        where "organization_id" = v_row."tenant_id" and "user_id" = v_row."user_id";
      end if;
    end if;
  end if;
  update "better_supabase"."access_requests" r set "ended_at" = now() where r."id" = v_row."id" returning * into v_row;
  perform "better_supabase".emit_event('access_request.ended', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'userId', v_row."user_id", 'role', v_row."role", 'id', v_row."id", 'approvalId', v_row."approval_id", 'expiresAt', v_row."expires_at", 'target', v_row."target", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'action', v_row."action", 'reason', 'revoked'), 'access-requests/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/access-requests');
  perform better_supabase.audit_event(
    event_type => 'access_request.ended',
    category => 'membership',
    target_type => 'user',
    record_id => v_row."user_id"::text,
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'userId', v_row."user_id", 'role', v_row."role", 'id', v_row."id", 'approvalId', v_row."approval_id", 'expiresAt', v_row."expires_at", 'target', v_row."target", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'action', v_row."action", 'reason', 'revoked')
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'userId', v_row."user_id", 'role', v_row."role", 'target', v_row."target", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'action', v_row."action", 'emergency', v_row."emergency", 'review', case when v_row."reviewed_at" is null then null else jsonb_build_object('verdict', v_row."review_verdict", 'note', v_row."review_note", 'reviewedBy', v_row."reviewed_by", 'reviewedAt', v_row."reviewed_at") end, 'previousRole', v_row."previous_role", 'reason', v_row."reason", 'duration', v_row."duration"::text, 'status', 'ended', 'approvalId', v_row."approval_id", 'grantedAt', v_row."granted_at", 'expiresAt', v_row."expires_at", 'endedAt', v_row."ended_at", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.end_care_plan_action (
  action_id uuid,
  reason    text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."care_plan_actions";
  v_plan "better_supabase"."care_plans";
begin
  select * into v_row from "better_supabase"."care_plan_actions" w where w."id" = end_care_plan_action.action_id for update;
  if not found then
    raise exception 'no such action on a care plan' using errcode = 'P0002', hint = 'CARE_PLAN_NOT_FOUND';
  end if;
  select * into v_plan from "better_supabase"."care_plans" x where x."id" = v_row."plan_id" for update;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_plan."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_plan."tenant_id", 'care_plans.write'), false))) then
    raise exception 'not allowed to change this care plan' using errcode = '42501', hint = 'CARE_PLAN_FORBIDDEN';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce("better_supabase"."can_subject"(v_plan."subject_type", v_plan."subject_id", 'read'), false)) then
    raise exception 'not allowed to read this client' using errcode = '42501', hint = 'CARE_PLAN_FORBIDDEN';
  end if;
  if v_plan."status" = 'archived' then
    raise exception 'the care plan is archived' using errcode = '55000', hint = 'CARE_PLAN_ARCHIVED';
  end if;
  if v_row."status" = 'ended' then
    raise exception 'the action has already ended' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  if length(end_care_plan_action.reason) > 2000 then
    raise exception 'reason is at most 2000 characters' using errcode = '22023', hint = 'CARE_PLAN_INVALID';
  end if;
  perform "better_supabase"."care_plan_action_end"(v_row."id", nullif(trim(end_care_plan_action.reason), ''));
  select * into v_row from "better_supabase"."care_plan_actions" w where w."id" = v_row."id";
  return jsonb_build_object('id', v_row."id", 'planId', v_row."plan_id", 'goalId', v_row."goal_id", 'kind', v_row."kind", 'title', v_row."title", 'instructions', v_row."instructions", 'frequency', v_row."frequency", 'teamRole', v_row."team_role", 'measureKind', v_row."measure_kind", 'taskId', v_row."task_id", 'bookingSeriesId', v_row."booking_series_id", 'requiresApproval', v_row."requires_approval", 'approvalId', v_row."approval_id", 'reviewEvery', case when v_row."review_every" is null then null else format('P%sY%sM%sDT%sH%sM%sS', extract(year from v_row."review_every")::int, extract(month from v_row."review_every")::int, extract(day from v_row."review_every")::int, extract(hour from v_row."review_every")::int, extract(minute from v_row."review_every")::int, trim_scale(extract(second from v_row."review_every"))) end, 'reviewedAt', v_row."reviewed_at", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'status', v_row."status", 'startedAt', v_row."started_at", 'endedAt', v_row."ended_at", 'endReason', v_row."end_reason", 'rank', v_row."rank", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.end_commission_assignment (
  assignment_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."commission_assignments";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."commission_assignments" x where x."id" = end_commission_assignment.assignment_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'commissions.read'), false))) then
    raise exception 'no such assignment' using errcode = 'P0002', hint = 'COMMISSION_ASSIGNMENT_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'commissions.manage'), false))) then
    raise exception 'not allowed to assign commission plans' using errcode = '42501', hint = 'COMMISSION_FORBIDDEN';
  end if;
  update "better_supabase"."commission_assignments" x set "ends_on" = greatest(current_date, x."starts_on")
  where x."id" = v_row."id" and (x."ends_on" is null or x."ends_on" > current_date)
  returning * into v_row;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'planId', v_row."plan_id", 'sellerId', v_row."seller_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.end_funding_award (
  award_id uuid,
  ends_on  date    DEFAULT NULL::date,
  canceled boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."funding_awards"%rowtype;
  v_ends date;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."funding_awards" x where x."id" = end_funding_award.award_id for update;
  if not found then
    raise exception 'funding award not found' using errcode = 'P0002', hint = 'FUNDING_AWARD_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'funding.write'), false)) then
    raise exception 'not allowed to change funding awards' using errcode = '42501', hint = 'FUNDING_FORBIDDEN';
  end if;
  if v_row."status" in ('ended', 'canceled') then
    return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'funderId', v_row."funder_id", 'productId', v_row."product_id", 'units', v_row."units", 'period', v_row."period", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'reference', v_row."reference", 'status', v_row."status", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
  end if;
  v_ends := case
    when coalesce(end_funding_award.canceled, false) then coalesce(end_funding_award.ends_on, v_row."ends_on")
    else coalesce(end_funding_award.ends_on, least(current_date, coalesce(v_row."ends_on", current_date)))
  end;
  if v_ends is not null and v_ends < v_row."starts_on" then
    if coalesce(end_funding_award.canceled, false) then
      v_ends := null;
    else
      raise exception 'an award ends on or after its start date; cancel it instead' using errcode = '22023', hint = 'FUNDING_INVALID';
    end if;
  end if;
  update "better_supabase"."funding_awards" x set
    "status" = case when coalesce(end_funding_award.canceled, false) then 'canceled' else 'ended' end,
    "ends_on" = v_ends, "updated_at" = now()
  where x."id" = v_row."id"
  returning x.* into v_row;
  perform "better_supabase".emit_event('funding_award.ended', jsonb_build_object('organizationId', v_row."tenant_id", 'fundingAwardId', v_row."id", 'fundingProductId', v_row."product_id", 'funderId', v_row."funder_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'endsOn', v_row."ends_on"), 'funding-awards/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/funding');
  perform better_supabase.audit_event(
    event_type => 'funding_award.ended',
    category => 'data',
    target_type => 'funding_award',
    record_id => v_row."id"::text,
    summary => 'Funding award ended',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'fundingAwardId', v_row."id", 'fundingProductId', v_row."product_id", 'funderId', v_row."funder_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'endsOn', v_row."ends_on")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'funderId', v_row."funder_id", 'productId', v_row."product_id", 'units', v_row."units", 'period', v_row."period", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'reference', v_row."reference", 'status', v_row."status", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.end_my_session (
  session uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  delete from auth.sessions s
  where s.id = end_my_session.session
    and s.user_id = (select auth.uid());
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.end_sessions (
  p_user uuid
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  ended int;
begin
  with gone as (
    delete from auth.sessions s where s.user_id = end_sessions.p_user returning s.id
  )
  select count(*)::int into ended from gone;
  delete from auth.refresh_tokens t where t.user_id = end_sessions.p_user::text;
  return ended;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.end_subject_member (
  member_id uuid,
  ends_on   date DEFAULT CURRENT_DATE
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."subject_members";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."subject_members" m where m."id" = end_subject_member.member_id;
  if not found then
    raise exception 'record team member not found' using errcode = 'P0002', hint = 'SUBJECT_MEMBER_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')
      or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'subjects.manage'), false)
      or (v_row."subject_type" = any (array[]::text[]) and coalesce("better_supabase"."can_subject"(v_row."subject_type", v_row."subject_id", 'manage'), false))) then
    raise exception 'not allowed to manage this record''s team' using errcode = '42501', hint = 'SUBJECT_MEMBER_FORBIDDEN';
  end if;
  if end_subject_member.ends_on is null or end_subject_member.ends_on < v_row."starts_on" then
    raise exception 'ends_on is missing or before starts_on' using errcode = '22023', hint = 'SUBJECT_MEMBER_INVALID';
  end if;
  update "better_supabase"."subject_members" m set "ends_on" = end_subject_member.ends_on
  where m."id" = end_subject_member.member_id
  returning * into v_row;
  perform "better_supabase".emit_event('subject_member.ended', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'userId', v_row."user_id", 'teamId', v_row."team_id", 'role', v_row."role", 'endsOn', v_row."ends_on"), 'subjects/' || v_row."subject_type" || '/' || v_row."subject_id", (v_row."tenant_id")::text, null, 'better-supabase/subjects');
  perform better_supabase.audit_event(
    event_type => 'subject_member.ended',
    category => 'access',
    target_type => 'subject_member',
    record_id => v_row."id"::text,
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'userId', v_row."user_id", 'teamId', v_row."team_id", 'role', v_row."role", 'endsOn', v_row."ends_on")
  );
  return jsonb_build_object(
      'id', v_row."id", 'organizationId', v_row."tenant_id",
      'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id",
      'userId', v_row."user_id", 'teamId', v_row."team_id", 'role', v_row."role",
      'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'endsAt', v_row."ends_at",
      'emergency', v_row."emergency", 'reason', v_row."reason",
      'active', (v_row."starts_on" is null or v_row."starts_on" <= current_date)
        and (v_row."ends_on" is null or v_row."ends_on" >= current_date)
        and (v_row."ends_at" is null or v_row."ends_at" > now()),
      'createdBy', v_row."created_by", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enforce_slug()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  value text := to_jsonb(new) ->> coalesce(tg_argv[0], 'slug');
  problem text := better_supabase.slug_problem(value);
begin
  if problem = 'invalid' then
    raise exception 'Invalid slug "%"', value using errcode = '23514', hint = 'SLUG_INVALID';
  elsif problem = 'reserved' then
    raise exception 'The slug "%" is reserved', value using errcode = '23514', hint = 'SLUG_RESERVED';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enqueue_import_chunks (
  run    uuid,
  entity text,
  chunks integer
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_run "better_supabase"."import_runs";
  v_chunk integer;
begin
  select * into v_run from "better_supabase"."import_runs" r where r."id" = enqueue_import_chunks.run;
  if not found then
    raise exception 'import not found' using errcode = 'P0002', hint = 'IMPORT_NOT_FOUND';
  end if;
  if enqueue_import_chunks.chunks is null or enqueue_import_chunks.chunks < 1 then
    raise exception 'chunks must be at least 1' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  for v_chunk in 0 .. enqueue_import_chunks.chunks - 1 loop
    perform "better_supabase"."enqueue_job"(queue => 'imports', payload => jsonb_build_object('run', v_run."id", 'entity', enqueue_import_chunks.entity, 'chunk', v_chunk), dedupe_key => v_run."id"::text || ':' || enqueue_import_chunks.entity || ':' || v_chunk::text, dedupe_running => false);
  end loop;
  return enqueue_import_chunks.chunks;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enqueue_job (
  queue          text,
  payload        jsonb   DEFAULT '{}'::jsonb,
  delay          integer DEFAULT 0,
  max_attempts   integer DEFAULT 5,
  dedupe_key     text    DEFAULT NULL::text,
  dedupe_running boolean DEFAULT true
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  existing bigint;
begin
  perform better_supabase.ensure_job_queue(queue);
  if dedupe_key is not null then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(queue), pg_catalog.hashtext(dedupe_key));
    execute format('select msg_id from pgmq.%I where message ? ''dedupe_key'' and message ->> ''dedupe_key'' = $1 and ($2 or read_ct = 0) limit 1', 'q_' || queue)
      into existing using dedupe_key, dedupe_running;
    if existing is not null then
      -- A message nobody has read yet moves earlier when this enqueue is due
      -- sooner, never later.
      execute format('update pgmq.%I set vt = least(vt, clock_timestamp() + make_interval(secs => $2)) where msg_id = $1 and read_ct = 0', 'q_' || queue)
        using existing, greatest(delay, 0);
      return existing;
    end if;
  end if;
  return (
    select pgmq.send(
      queue,
      jsonb_build_object('payload', payload, 'max_attempts', max_attempts)
        || case when dedupe_key is null then '{}'::jsonb else jsonb_build_object('dedupe_key', dedupe_key) end,
      greatest(delay, 0)
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enqueue_job_once (
  queue        text,
  payload      jsonb,
  dedupe_key   text,
  delay        integer DEFAULT 0,
  max_attempts integer DEFAULT 5
)
  RETURNS TABLE (
    id        bigint,
    duplicate boolean
  )
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  existing bigint;
begin
  if dedupe_key is null then
    raise exception 'enqueue_job_once needs a dedupe_key' using errcode = '22004';
  end if;
  perform better_supabase.ensure_job_queue(queue);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext(queue), pg_catalog.hashtext(dedupe_key));
  execute format('select msg_id from pgmq.%I where message ? ''dedupe_key'' and message ->> ''dedupe_key'' = $1 union all select msg_id from pgmq.%I where message ? ''dedupe_key'' and message ->> ''dedupe_key'' = $1 limit 1', 'q_' || queue, 'a_' || queue)
    into existing using dedupe_key;
  if existing is not null then
    id := existing;
    duplicate := true;
  else
    id := better_supabase.enqueue_job(queue, payload, delay, max_attempts, dedupe_key);
    duplicate := false;
  end if;
  return next;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrichment_due (
  provider     text,
  max_count    integer  DEFAULT NULL::integer,
  stale_after  interval DEFAULT NULL::interval,
  subject_type text     DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(z.target order by z.fetched_at nulls first, z.id), '[]'::jsonb)
  from (
    select * from (
      select jsonb_build_object('kind', 'company', 'organizationId', x."tenant_id", 'subjectType', 'company', 'subjectId', x."id", 'name', x."name", 'domain', x."domain", 'website', x."website") as target, y."fetched_at" as fetched_at, x."id" as id
    from "better_supabase"."companies" x
    left join "better_supabase"."enrichments" y on y."company_id" = x."id" and y."provider" = enrichment_due.provider
    where x."archived_at" is null
      and (enrichment_due.subject_type is null or enrichment_due.subject_type = 'company')
      and (x."domain" is not null or x."website" is not null)
      and (y."fetched_at" is null or y."fetched_at" < now() - coalesce(enrichment_due.stale_after, interval '30 days'))
      union all
      select jsonb_build_object('kind', 'person', 'organizationId', x."tenant_id", 'subjectType', 'person', 'subjectId', x."id", 'name', x."name", 'email', x."email", 'phone', x."phone", 'title', x."title", 'companyDomain', (
    select c."domain" from "better_supabase"."company_people" l
    join "better_supabase"."companies" c on c."id" = l."company_id"
    where l."person_id" = x."id" and c."archived_at" is null
    order by l."is_primary" desc, l."created_at"
    limit 1)) as target, y."fetched_at" as fetched_at, x."id" as id
    from "better_supabase"."people" x
    left join "better_supabase"."enrichments" y on y."person_id" = x."id" and y."provider" = enrichment_due.provider
    where x."archived_at" is null
      and (enrichment_due.subject_type is null or enrichment_due.subject_type = 'person')
      and x."email" is not null
      and (y."fetched_at" is null or y."fetched_at" < now() - coalesce(enrichment_due.stale_after, interval '30 days'))
    ) w
    order by w.fetched_at nulls first, w.id
    limit least(greatest(coalesce(enrichment_due.max_count, 25), 1), 500)
  ) z
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrichment_target (
  subject_type text,
  subject_id   uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_target jsonb;
begin
  if enrichment_target.subject_type = 'company' then
    select jsonb_build_object('kind', 'company', 'organizationId', c."tenant_id", 'subjectType', 'company', 'subjectId', c."id", 'name', c."name", 'domain', c."domain", 'website', c."website") into v_target from "better_supabase"."companies" c
    where c."id" = enrichment_target.subject_id and c."archived_at" is null;
  elsif enrichment_target.subject_type = 'person' then
    select jsonb_build_object('kind', 'person', 'organizationId', p."tenant_id", 'subjectType', 'person', 'subjectId', p."id", 'name', p."name", 'email', p."email", 'phone', p."phone", 'title', p."title", 'companyDomain', (
    select c."domain" from "better_supabase"."company_people" l
    join "better_supabase"."companies" c on c."id" = l."company_id"
    where l."person_id" = p."id" and c."archived_at" is null
    order by l."is_primary" desc, l."created_at"
    limit 1)) into v_target from "better_supabase"."people" p
    where p."id" = enrichment_target.subject_id and p."archived_at" is null;
  else
    raise exception 'subject_type must be the company or the person type' using errcode = '22023', hint = 'ENRICHMENT_SUBJECT_UNKNOWN';
  end if;
  if v_target is null or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', (v_target ->> 'organizationId')::uuid, 'enrichment.run'), false)) then
    raise exception 'No company or person you can enrich has this id' using errcode = 'P0002', hint = 'ENRICHMENT_NOT_FOUND';
  end if;
  return v_target;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrichments_of (
  subject_type text,
  subject_id   uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'subjectType', case when x."company_id" is not null then 'company' else 'person' end, 'subjectId', coalesce(x."company_id", x."person_id"), 'provider', x."provider", 'status', x."status", 'data', x."data", 'filled', to_jsonb(x."filled"), 'fetchedAt', x."fetched_at", 'requestedBy', x."requested_by") order by x."fetched_at" desc, x."provider"), '[]'::jsonb)
  from "better_supabase"."enrichments" x
  where case
      when enrichments_of.subject_type = 'company' then x."company_id" = enrichments_of.subject_id
      when enrichments_of.subject_type = 'person' then x."person_id" = enrichments_of.subject_id
      else false
    end
    and coalesce(better_supabase.can('tenant', x."tenant_id", 'enrichment.read'), false)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enroll (
  tenant       uuid,
  program      text,
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_program "better_supabase"."enrollment_programs";
  v_row "better_supabase"."enrollments";
  v_id uuid;
  v_steps text[];
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (enroll.tenant is not null and coalesce(better_supabase.can('tenant', enroll.tenant, 'enrollments.enroll'), false))) then
    raise exception 'not allowed to enroll' using errcode = '42501', hint = 'ENROLLMENTS_FORBIDDEN';
  end if;
  select * into v_program from "better_supabase"."enrollment_programs" x
  where x."tenant_id" = enroll.tenant and x."key" = enroll.program;
  if v_program."id" is null then
    raise exception 'enrollment program not found' using errcode = 'P0002', hint = 'ENROLLMENTS_PROGRAM_NOT_FOUND';
  end if;
  if not v_program."enabled" then
    raise exception 'this program is turned off' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if enroll.subject_type is null or enroll.subject_type !~ '^[a-z][a-z0-9_-]{0,62}$' or enroll.subject_id is null or length(enroll.subject_id) not between 1 and 200 then
    raise exception 'an enrollment needs a subject type and id' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if cardinality(v_program."subject_types") > 0 and not (enroll.subject_type = any(v_program."subject_types")) then
    raise exception 'this program doesn''t enroll this subject type' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if enroll.subject_type = 'user' and enroll.subject_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'a user subject needs a user id' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  v_steps := array(select t.value ->> 'id' from jsonb_array_elements(v_program."steps") with ordinality as t(value, ord) order by t.ord);
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_enrollment_create"(uuid, text, text, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::text, $4::text)', v_hook::oid::regproc)
        using enroll.tenant, enroll.program, enroll.subject_type, enroll.subject_id;
    end if;
  end;
  select * into v_row from "better_supabase"."enrollments" x
  where x."tenant_id" = enroll.tenant and x."program" = enroll.program
    and x."subject_type" = enroll.subject_type and x."subject_id" = enroll.subject_id
  for update;
  if v_row."status" = 'cancelled' then
    update "better_supabase"."enrollments" x
    set "status" = 'active', "cancelled_at" = null, "enrolled_by" = auth.uid(), "enrolled_at" = now(),
      "steps" = v_steps, "program_version" = v_program."version"
    where x."id" = v_row."id";
    update "better_supabase"."enrollments" x
  set "completed_steps" = (select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null),
    "status" = case when x."status" = 'cancelled' then 'cancelled' when ((select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null) >= cardinality(x."steps") and cardinality(x."steps") > 0) then 'completed' else 'active' end,
    "completed_at" = case when x."status" <> 'cancelled' and ((select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null) >= cardinality(x."steps") and cardinality(x."steps") > 0) then coalesce(x."completed_at", now()) end,
    "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  if v_row."tenant_id" is not null then
    perform "better_supabase".emit_event('enrollment.created', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")), 'enrollments/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  end if;
    v_id := v_row."id";
  else
    v_id := "better_supabase"."enrollment_ensure"(enroll.tenant, enroll.program, v_program."version", v_steps, enroll.subject_type, enroll.subject_id, auth.uid());
  end if;
  perform "better_supabase"."enrollment_schedule"(v_id);
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_enrollment_create"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_id;
    end if;
  end;
  return "better_supabase"."enrollment_json"(v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enroll_in_course (
  course_id uuid,
  user_id   uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_course "better_supabase"."courses";
  v_row "better_supabase"."enrollments";
  v_user uuid := coalesce(enroll_in_course.user_id, auth.uid());
  v_enrollment record;
  v_id uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_course from "better_supabase"."courses" x where x."id" = enroll_in_course.course_id;
  if v_course."id" is null or not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_course."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_course."tenant_id", 'courses.manage'), false)))
    or (v_course."status" = 'published' and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_course."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_course."tenant_id", 'courses.read'), false))))
    or exists (select 1 from "better_supabase"."enrollments" y where y."tenant_id" = v_course."tenant_id" and y."program" = ('course:' || v_course."id"::text)
      and y."subject_type" = 'user' and y."subject_id" = auth.uid()::text and y."status" <> 'cancelled')) then
    raise exception 'course not found' using errcode = 'P0002', hint = 'COURSE_NOT_FOUND';
  end if;
  if v_user is null then
    raise exception 'sign in to enroll' using errcode = '42501', hint = 'COURSE_FORBIDDEN';
  end if;
  if v_user is distinct from auth.uid() and not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_course."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_course."tenant_id", 'courses.enroll'), false))) then
    raise exception 'not allowed to enroll others in courses' using errcode = '42501', hint = 'COURSE_FORBIDDEN';
  end if;
  if coalesce(v_user = auth.uid(), false) and not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_course."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_course."tenant_id", 'courses.read'), false))) or (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_course."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_course."tenant_id", 'courses.enroll'), false)))) then
    raise exception 'not allowed to enroll in courses' using errcode = '42501', hint = 'COURSE_FORBIDDEN';
  end if;
  if v_course."status" <> 'published' then
    raise exception 'only a published course takes enrollments' using errcode = '55000', hint = 'COURSE_NOT_PUBLISHED';
  end if;
  select * into v_row from "better_supabase"."enrollments" x
  where x."tenant_id" = v_course."tenant_id" and x."program" = ('course:' || v_course."id"::text)
    and x."subject_type" = 'user' and x."subject_id" = v_user::text
  for update;
  if v_row."id" is not null and v_row."status" <> 'cancelled' then
    return "better_supabase"."course_learner_json"(v_row."id");
  end if;
  if v_row."id" is not null then
    -- Clearing the steps makes enrollment_ensure take the current ones and
    -- recount the lessons completed before.
    update "better_supabase"."enrollments" x
    set "status" = 'active', "cancelled_at" = null, "enrolled_by" = auth.uid(), "enrolled_at" = now(), "steps" = '{}'
    where x."id" = v_row."id";
  end if;
  v_id := "better_supabase"."enrollment_ensure"(v_course."tenant_id", ('course:' || v_course."id"::text), null, "better_supabase"."course_steps"(v_course."id"), 'user', v_user::text, auth.uid());
  select * into v_row from "better_supabase"."enrollments" x where x."id" = v_id;
  select v_row."id" as id, v_row."tenant_id" as tenant, v_course."id" as course, v_row."user_id" as learner into v_enrollment;
  perform "better_supabase".emit_event('course.enrolled', jsonb_build_object('organizationId', v_enrollment.tenant, 'id', v_enrollment.course, 'userId', v_enrollment.learner, 'enrollmentId', v_enrollment.id), 'courses/' || v_enrollment.course::text, (v_enrollment.tenant)::text, null, 'better-supabase/courses');
  perform better_supabase.audit_event(
    event_type => 'course.enrolled',
    category => 'data',
    target_type => 'course',
    record_id => v_enrollment.course::text,
    target_label => v_enrollment.learner::text,
    summary => 'enrolled in a course',
    tenant => (v_enrollment.tenant)::uuid,
    metadata => jsonb_build_object('organizationId', v_enrollment.tenant, 'id', v_enrollment.course, 'userId', v_enrollment.learner, 'enrollmentId', v_enrollment.id)
  );
  perform "better_supabase"."course_finish"(v_id, 'active');
  return "better_supabase"."course_learner_json"(v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enroll_in_sequence (
  sequence_id  uuid,
  subject_type text,
  subject_id   text,
  attrs        jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_sequence "better_supabase"."sequences";
  v_row "better_supabase"."enrollments";
  v_attrs jsonb := coalesce(enroll_in_sequence.attrs, '{}'::jsonb);
  v_address text;
  v_name text;
  v_email text;
  v_label text;
  v_account uuid;
  v_owner uuid;
  v_variables jsonb;
  v_id uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_sequence from "better_supabase"."sequences" x where x."id" = enroll_in_sequence.sequence_id;
  if v_sequence."id" is null or not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_sequence."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_sequence."tenant_id", 'sequences.read'), false))) or (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_sequence."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_sequence."tenant_id", 'sequences.enroll'), false)))) then
    raise exception 'sequence not found' using errcode = 'P0002', hint = 'SEQUENCE_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_sequence."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_sequence."tenant_id", 'sequences.enroll'), false))) then
    raise exception 'not allowed to enroll in sequences' using errcode = '42501', hint = 'SEQUENCE_FORBIDDEN';
  end if;
  if v_sequence."status" <> 'active' then
    raise exception 'only an active sequence takes enrollments' using errcode = '55000', hint = 'SEQUENCE_NOT_ACTIVE';
  end if;
  if jsonb_typeof(v_attrs) <> 'object' then
    raise exception 'attrs must be an object' using errcode = '22023', hint = 'SEQUENCE_INVALID';
  end if;
  if enroll_in_sequence.subject_type is null or enroll_in_sequence.subject_type !~ '^[a-z][a-z0-9_-]{0,62}$' then
    raise exception 'subject_type: use lowercase letters, digits or _' using errcode = '22023', hint = 'SEQUENCE_INVALID';
  end if;
  if enroll_in_sequence.subject_id is null or length(enroll_in_sequence.subject_id) not between 1 and 200 then
    raise exception 'subject_id must be 1 to 200 characters' using errcode = '22023', hint = 'SEQUENCE_INVALID';
  end if;
  v_address := nullif(trim(v_attrs ->> 'address'), '');
  v_name := nullif(trim(v_attrs ->> 'name'), '');
  v_account := nullif(v_attrs ->> 'accountId', '')::uuid;
  v_variables := coalesce(v_attrs -> 'variables', '{}'::jsonb);
  if enroll_in_sequence.subject_type = 'person' then
    select y."email", y."name" into v_email, v_label
    from "better_supabase"."people" y
    where y."id"::text = enroll_in_sequence.subject_id and y."tenant_id" = v_sequence."tenant_id";
    if not found then
      raise exception 'no such person in this organization' using errcode = '22023', hint = 'SEQUENCE_INVALID';
    end if;
    v_address := coalesce(v_address, v_email);
    v_name := coalesce(v_name, v_label);
  end if;
  if v_address is not null and (length(v_address) > 320 or v_address !~ '^[^@[:space:]]+@[^@[:space:]]+$') then
    raise exception 'address must be an email address' using errcode = '22023', hint = 'SEQUENCE_INVALID';
  end if;
  if length(v_name) > 200 then
    raise exception 'name must be at most 200 characters' using errcode = '22023', hint = 'SEQUENCE_INVALID';
  end if;
  if jsonb_typeof(v_variables) <> 'object' or length(v_variables::text) > 10000 then
    raise exception 'variables must be an object of at most 10000 characters' using errcode = '22023', hint = 'SEQUENCE_INVALID';
  end if;
  if v_address is null and exists (select 1 from jsonb_array_elements(v_sequence."steps") t where t.value ->> 'kind' = 'email') then
    raise exception 'the recipient needs an email address for the sequence''s email steps' using errcode = '22023', hint = 'SEQUENCE_INVALID';
  end if;
  if v_account is null then
    v_account := coalesce(v_sequence."mail_account_id", (
      select k."id" from "better_supabase"."mail_accounts" k
      where k."tenant_id" = v_sequence."tenant_id" and k."user_id" = auth.uid() and k."status" = 'active'
      order by k."created_at", k."id"
      limit 1));
  else
    select k."user_id" into v_owner from "better_supabase"."mail_accounts" k
    where k."id" = v_account and k."tenant_id" = v_sequence."tenant_id" and k."status" <> 'disconnected';
    if not found then
      raise exception 'accountId must be a connected mailbox of this organization' using errcode = '22023', hint = 'SEQUENCE_INVALID';
    end if;
    if v_owner is distinct from auth.uid() and not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_sequence."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_sequence."tenant_id", 'sequences.manage'), false))) then
      raise exception 'only a sequence manager sends from another user''s mailbox' using errcode = '42501', hint = 'SEQUENCE_FORBIDDEN';
    end if;
  end if;
  if v_account is null and exists (select 1 from jsonb_array_elements(v_sequence."steps") t where t.value ->> 'kind' = 'email') then
    raise exception 'connect a mailbox or set one on the sequence to send its email steps' using errcode = '22023', hint = 'SEQUENCE_INVALID';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_sequence_enroll"(uuid, text, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::text)', v_hook::oid::regproc)
        using enroll_in_sequence.sequence_id, enroll_in_sequence.subject_type, enroll_in_sequence.subject_id;
    end if;
  end;
  select * into v_row from "better_supabase"."enrollments" x
  where x."tenant_id" = v_sequence."tenant_id" and x."program" = ('sequence:' || v_sequence."id"::text)
    and x."subject_type" = enroll_in_sequence.subject_type and x."subject_id" = enroll_in_sequence.subject_id
  for update;
  if v_row."id" is not null and v_row."status" = 'active' then
    return "better_supabase"."sequence_member_json"(v_row."id");
  end if;
  if v_row."id" is not null then
    -- Starting over: the run begins again with none of the steps done.
    perform "better_supabase"."enrollment_restart"(v_row."id", v_sequence."version", array(select t.value ->> 'id' from jsonb_array_elements(v_sequence."steps") with ordinality as t(value, ord) order by t.ord), auth.uid());
    v_id := v_row."id";
  else
    v_id := "better_supabase"."enrollment_ensure"(v_sequence."tenant_id", ('sequence:' || v_sequence."id"::text), v_sequence."version", array(select t.value ->> 'id' from jsonb_array_elements(v_sequence."steps") with ordinality as t(value, ord) order by t.ord),
      enroll_in_sequence.subject_type, enroll_in_sequence.subject_id, auth.uid());
  end if;
  update "better_supabase"."enrollments" x
  set "sequence_id" = v_sequence."id", "sequence_address" = v_address, "sequence_name" = v_name, "sequence_mail_account_id" = v_account,
    "sequence_mail_thread_id" = null, "sequence_variables" = v_variables, "sequence_attempts" = 0, "sequence_last_error" = null, "updated_at" = now()
  where x."id" = v_id;
  perform "better_supabase"."sequence_place"(v_id);
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_sequence_enroll"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_id;
    end if;
  end;
  return "better_supabase"."sequence_member_json"(v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment (
  tenant       uuid,
  program      text,
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_id uuid;
begin
  if not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (enrollment.tenant is not null and coalesce(better_supabase.can('tenant', enrollment.tenant, 'enrollments.read'), false))) or (enrollment.subject_type = 'user' and coalesce(enrollment.subject_id = auth.uid()::text, false))) then
    raise exception 'not allowed to read enrollments' using errcode = '42501', hint = 'ENROLLMENTS_FORBIDDEN';
  end if;
  select x."id" into v_id from "better_supabase"."enrollments" x
  where x."tenant_id" = enrollment.tenant and x."program" = enrollment.program
    and x."subject_type" = enrollment.subject_type and x."subject_id" = enrollment.subject_id;
  return case when v_id is null then null else "better_supabase"."enrollment_json"(v_id) end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_cancel (
  enrollment_id uuid,
  reason        text,
  actor         uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."enrollments";
begin
  select * into v_row from "better_supabase"."enrollments" x where x."id" = enrollment_cancel.enrollment_id for update;
  if v_row."id" is null then
    raise exception 'enrollment not found' using errcode = 'P0002', hint = 'ENROLLMENTS_NOT_FOUND';
  end if;
  if v_row."status" <> 'active' then
    return false;
  end if;
  delete from "better_supabase"."enrollment_steps" y where y."enrollment_id" = v_row."id" and y."completed_at" is null;
  update "better_supabase"."enrollments" x
  set "status" = 'cancelled', "cancelled_at" = now(), "paused_at" = null, "cancel_reason" = enrollment_cancel.reason, "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  if v_row."tenant_id" is not null then
    perform "better_supabase".emit_event('enrollment.cancelled', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps"), 'reason', enrollment_cancel.reason), 'enrollments/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  end if;
  if enrollment_cancel.actor is not null and v_row."tenant_id" is not null then
    perform better_supabase.audit_event(
    event_type => 'enrollment.cancelled',
    category => 'data',
    target_type => 'enrollment',
    record_id => v_row."id"::text,
    target_label => v_row."program",
    summary => 'cancelled an enrollment',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps"), 'reason', enrollment_cancel.reason),
    actor_id => enrollment_cancel.actor
  );
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_ensure (
  tenant          uuid,
  program         text,
  program_version integer,
  steps           text[],
  subject_type    text,
  subject_id      text,
  actor           uuid
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."enrollments";
  v_was text;
begin
  select * into v_row from "better_supabase"."enrollments" x
  where x."tenant_id" is not distinct from enrollment_ensure.tenant and x."program" = enrollment_ensure.program
    and x."subject_type" = enrollment_ensure.subject_type and x."subject_id" = enrollment_ensure.subject_id
  for update;
  if v_row."id" is null then
    insert into "better_supabase"."enrollments" ("tenant_id", "program", "program_version", "subject_type", "subject_id", "user_id", "steps", "enrolled_by")
    values (enrollment_ensure.tenant, enrollment_ensure.program, enrollment_ensure.program_version, enrollment_ensure.subject_type, enrollment_ensure.subject_id, case when enrollment_ensure.subject_type = 'user' then enrollment_ensure.subject_id::uuid end, enrollment_ensure.steps, enrollment_ensure.actor)
    on conflict do nothing
    returning * into v_row;
    if v_row."id" is null then
      select * into v_row from "better_supabase"."enrollments" x
      where x."tenant_id" is not distinct from enrollment_ensure.tenant and x."program" = enrollment_ensure.program
        and x."subject_type" = enrollment_ensure.subject_type and x."subject_id" = enrollment_ensure.subject_id;
      return v_row."id";
    end if;
  if v_row."tenant_id" is not null then
    perform "better_supabase".emit_event('enrollment.created', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")), 'enrollments/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  end if;
    return v_row."id";
  end if;
  if v_row."steps" is distinct from enrollment_ensure.steps or v_row."program_version" is distinct from enrollment_ensure.program_version then
    v_was := v_row."status";
    update "better_supabase"."enrollments" x set "steps" = enrollment_ensure.steps, "program_version" = enrollment_ensure.program_version
    where x."id" = v_row."id";
    update "better_supabase"."enrollments" x
  set "completed_steps" = (select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null),
    "status" = case when x."status" = 'cancelled' then 'cancelled' when ((select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null) >= cardinality(x."steps") and cardinality(x."steps") > 0) then 'completed' else 'active' end,
    "completed_at" = case when x."status" <> 'cancelled' and ((select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null) >= cardinality(x."steps") and cardinality(x."steps") > 0) then coalesce(x."completed_at", now()) end,
    "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
    -- Removing the steps that were left can complete the enrollment.
    if v_was <> 'completed' and v_row."status" = 'completed' then
  if v_row."tenant_id" is not null then
    perform "better_supabase".emit_event('enrollment.completed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")), 'enrollments/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  end if;
      null;
    end if;
  end if;
  return v_row."id";
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_json (
  enrollment_id uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'id', x."id", 'organizationId', x."tenant_id", 'program', x."program", 'programVersion', x."program_version",
    'subjectType', x."subject_type", 'subjectId', x."subject_id", 'status', x."status",
    'steps', to_jsonb(x."steps"), 'completedSteps', x."completed_steps", 'totalSteps', cardinality(x."steps"),
    'enrolledBy', x."enrolled_by", 'enrolledAt', x."enrolled_at", 'completedAt', x."completed_at",
    'cancelledAt', x."cancelled_at", 'pausedAt', x."paused_at", 'cancelReason', x."cancel_reason",
    'updatedAt', x."updated_at",
    'progress', coalesce((
      select jsonb_agg(jsonb_build_object('step', y."step", 'completedAt', y."completed_at", 'completedBy', y."completed_by") order by y."completed_at", array_position(x."steps", y."step"), y."step")
      from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."completed_at" is not null
    ), '[]'::jsonb),
    'startsAt', x."starts_at", 'endsAt', x."ends_at",
    'schedule', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('step', y."step", 'assignee', case when y."assignee_role" is not null then jsonb_build_object('role', y."assignee_role") when y."assignee_id" is not null then jsonb_build_object('userId', y."assignee_id") end, 'dueAt', y."due_at", 'completedAt', y."completed_at")) order by array_position(x."steps", y."step"), y."step")
      from "better_supabase"."enrollment_steps" y
      where y."enrollment_id" = x."id"
        and (y."assignee_role" is not null or y."assignee_id" is not null or y."due_at" is not null)
    ), '[]'::jsonb)
  )
  from "better_supabase"."enrollments" x
  where x."id" = enrollment_json.enrollment_id
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_mark (
  enrollment_id uuid,
  step          text,
  done          boolean,
  actor         uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."enrollments";
  v_was text;
  v_count integer;
begin
  select * into v_row from "better_supabase"."enrollments" x where x."id" = enrollment_mark.enrollment_id for update;
  if v_row."id" is null then
    raise exception 'enrollment not found' using errcode = 'P0002', hint = 'ENROLLMENTS_NOT_FOUND';
  end if;
  if enrollment_mark.step is null or not (enrollment_mark.step = any(v_row."steps")) then
    raise exception 'this step is not part of the program' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  if v_row."status" = 'cancelled' then
    raise exception 'the enrollment is cancelled' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  v_was := v_row."status";
  -- An open row of a step with a schedule is completed in place.
  if enrollment_mark.done then
    update "better_supabase"."enrollment_steps" y
    set "completed_by" = enrollment_mark.actor, "completed_at" = now()
    where y."enrollment_id" = v_row."id" and y."step" = enrollment_mark.step and y."completed_at" is null;
    get diagnostics v_count = row_count;
    if v_count = 0 then
      insert into "better_supabase"."enrollment_steps" ("enrollment_id", "tenant_id", "step", "completed_by", "completed_at")
      values (v_row."id", v_row."tenant_id", enrollment_mark.step, enrollment_mark.actor, now())
      on conflict do nothing;
      get diagnostics v_count = row_count;
    end if;
  else
    delete from "better_supabase"."enrollment_steps" x
    where x."enrollment_id" = v_row."id" and x."step" = enrollment_mark.step and x."completed_at" is not null;
    get diagnostics v_count = row_count;
  end if;
  if v_count = 0 then
    return false;
  end if;
  -- A reset step with a schedule gets its open row back.
  if not enrollment_mark.done then
    perform "better_supabase"."enrollment_schedule"(v_row."id");
  end if;
  update "better_supabase"."enrollments" x
  set "completed_steps" = (select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null),
    "status" = case when x."status" = 'cancelled' then 'cancelled' when ((select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null) >= cardinality(x."steps") and cardinality(x."steps") > 0) then 'completed' else 'active' end,
    "completed_at" = case when x."status" <> 'cancelled' and ((select count(*)::integer from "better_supabase"."enrollment_steps" y where y."enrollment_id" = x."id" and y."step" = any(x."steps") and y."completed_at" is not null) >= cardinality(x."steps") and cardinality(x."steps") > 0) then coalesce(x."completed_at", now()) end,
    "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  if enrollment_mark.done then
  if v_row."tenant_id" is not null then
    perform "better_supabase".emit_event('enrollment.step_completed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', enrollment_mark.step, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")), 'enrollments/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  end if;
    if v_was <> 'completed' and v_row."status" = 'completed' then
  if v_row."tenant_id" is not null then
    perform "better_supabase".emit_event('enrollment.completed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")), 'enrollments/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  end if;
      null;
    end if;
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_pause (
  enrollment_id uuid,
  paused        boolean,
  actor         uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."enrollments";
begin
  select * into v_row from "better_supabase"."enrollments" x where x."id" = enrollment_pause.enrollment_id for update;
  if v_row."id" is null then
    raise exception 'enrollment not found' using errcode = 'P0002', hint = 'ENROLLMENTS_NOT_FOUND';
  end if;
  if v_row."status" <> 'active' or (v_row."paused_at" is not null) = enrollment_pause.paused then
    return false;
  end if;
  update "better_supabase"."enrollments" x
  set "paused_at" = case when enrollment_pause.paused then now() end, "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  if enrollment_pause.paused then
  if v_row."tenant_id" is not null then
    perform "better_supabase".emit_event('enrollment.paused', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")), 'enrollments/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  end if;
  if enrollment_pause.actor is not null and v_row."tenant_id" is not null then
    perform better_supabase.audit_event(
    event_type => 'enrollment.paused',
    category => 'data',
    target_type => 'enrollment',
    record_id => v_row."id"::text,
    target_label => v_row."program",
    summary => 'paused an enrollment',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")),
    actor_id => enrollment_pause.actor
  );
  end if;
  else
  if v_row."tenant_id" is not null then
    perform "better_supabase".emit_event('enrollment.resumed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")), 'enrollments/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  end if;
  if enrollment_pause.actor is not null and v_row."tenant_id" is not null then
    perform better_supabase.audit_event(
    event_type => 'enrollment.resumed',
    category => 'data',
    target_type => 'enrollment',
    record_id => v_row."id"::text,
    target_label => v_row."program",
    summary => 'resumed an enrollment',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")),
    actor_id => enrollment_pause.actor
  );
  end if;
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_programs (
  tenant uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (enrollment_programs.tenant is not null and coalesce(better_supabase.can('tenant', enrollment_programs.tenant, 'enrollments.read'), false))) then
    raise exception 'not allowed to read enrollment programs' using errcode = '42501', hint = 'ENROLLMENTS_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'key', x."key", 'name', x."name", 'description', x."description", 'subjectTypes', to_jsonb(x."subject_types"), 'steps', x."steps", 'enabled', x."enabled", 'version', x."version", 'createdBy', x."created_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at") order by x."key")
    from "better_supabase"."enrollment_programs" x where x."tenant_id" = enrollment_programs.tenant
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_restart (
  enrollment_id   uuid,
  program_version integer,
  steps           text[],
  actor           uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."enrollments";
begin
  select * into v_row from "better_supabase"."enrollments" x where x."id" = enrollment_restart.enrollment_id for update;
  if v_row."id" is null then
    raise exception 'enrollment not found' using errcode = 'P0002', hint = 'ENROLLMENTS_NOT_FOUND';
  end if;
  delete from "better_supabase"."enrollment_steps" y where y."enrollment_id" = v_row."id";
  update "better_supabase"."enrollments" x
  set "status" = 'active', "steps" = enrollment_restart.steps, "program_version" = enrollment_restart.program_version, "completed_steps" = 0,
    "completed_at" = null, "cancelled_at" = null, "paused_at" = null, "cancel_reason" = null,
    "enrolled_by" = enrollment_restart.actor, "enrolled_at" = now(), "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  if v_row."tenant_id" is not null then
    perform "better_supabase".emit_event('enrollment.created', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'program', v_row."program", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'step', null::text, 'completedSteps', v_row."completed_steps", 'totalSteps', cardinality(v_row."steps")), 'enrollments/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/enrollments');
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_schedule (
  target uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."enrollments";
  v_program "better_supabase"."enrollment_programs";
  v_plan jsonb;
begin
  select * into v_row from "better_supabase"."enrollments" x where x."id" = enrollment_schedule.target;
  if v_row."id" is null or v_row."tenant_id" is null or position(':' in v_row."program") > 0 then
    return;
  end if;
  select * into v_program from "better_supabase"."enrollment_programs" x
  where x."tenant_id" = v_row."tenant_id" and x."key" = v_row."program";
  v_plan := coalesce((
    select jsonb_agg(jsonb_build_object(
      'step', t.value ->> 'id',
      'role', t.value -> 'assignee' ->> 'role',
      'userId', t.value -> 'assignee' ->> 'userId',
      'dueAt', case t.value -> 'due' ->> 'from'
        when 'start' then coalesce(v_row."starts_at", v_row."enrolled_at") + make_interval(days => (t.value -> 'due' ->> 'days')::integer)
        when 'end' then v_row."ends_at" + make_interval(days => (t.value -> 'due' ->> 'days')::integer)
      end
    ))
    from jsonb_array_elements(coalesce(v_program."steps", '[]'::jsonb)) as t(value)
    where t.value ->> 'id' = any(v_row."steps")
      and (jsonb_typeof(t.value -> 'assignee') = 'object' or jsonb_typeof(t.value -> 'due') = 'object')
  ), '[]'::jsonb);
  delete from "better_supabase"."enrollment_steps" y
  where y."enrollment_id" = v_row."id" and y."completed_at" is null and not exists (select 1 from jsonb_array_elements(v_plan) as z(value) where z.value ->> 'step' = y."step");
  update "better_supabase"."enrollment_steps" y
  set "assignee_role" = null, "assignee_id" = null, "due_at" = null
  where y."enrollment_id" = v_row."id" and not exists (select 1 from jsonb_array_elements(v_plan) as z(value) where z.value ->> 'step' = y."step")
    and (y."assignee_role" is not null or y."assignee_id" is not null or y."due_at" is not null);
  insert into "better_supabase"."enrollment_steps" as y ("enrollment_id", "tenant_id", "step", "assignee_role", "assignee_id", "due_at", "completed_by", "completed_at")
  select v_row."id", v_row."tenant_id", z.value ->> 'step', z.value ->> 'role', (z.value ->> 'userId')::uuid, (z.value ->> 'dueAt')::timestamptz, null, null
  from jsonb_array_elements(v_plan) as z(value)
  on conflict ("enrollment_id", "step") do update
  set "assignee_role" = excluded."assignee_role", "assignee_id" = excluded."assignee_id", "due_at" = excluded."due_at";
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.enrollment_step (
  enrollment_id uuid,
  step          text,
  done          boolean
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."enrollments";
begin
  select * into v_row from "better_supabase"."enrollments" x where x."id" = enrollment_step.enrollment_id;
  if v_row."id" is null or not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'enrollments.read'), false))) or (v_row."user_id" is not null and coalesce(v_row."user_id" = auth.uid(), false)) or exists (select 1 from "better_supabase"."enrollment_steps" a where a."enrollment_id" = v_row."id" and a."step" = enrollment_step.step and a."assignee_id" = auth.uid())) then
    raise exception 'enrollment not found' using errcode = 'P0002', hint = 'ENROLLMENTS_NOT_FOUND';
  end if;
  if not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'enrollments.enroll'), false))) or (v_row."user_id" is not null and coalesce(v_row."user_id" = auth.uid(), false)) or exists (select 1 from "better_supabase"."enrollment_steps" a where a."enrollment_id" = v_row."id" and a."step" = enrollment_step.step and a."assignee_id" = auth.uid())) then
    raise exception 'not allowed to change this enrollment' using errcode = '42501', hint = 'ENROLLMENTS_FORBIDDEN';
  end if;
  -- A course's steps follow its lessons, so they change only through courses.
  if v_row."program" like 'course:%' then
    raise exception 'this enrollment belongs to a course; complete its lessons through courses' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  -- A sequence's steps run on its schedule, so only its runner marks them.
  if v_row."program" like 'sequence:%' then
    raise exception 'this enrollment belongs to a sequence; its steps run on the sequence''s schedule' using errcode = '22023', hint = 'ENROLLMENTS_INVALID';
  end if;
  perform "better_supabase"."enrollment_mark"(v_row."id", enrollment_step.step, enrollment_step.done, auth.uid());
  return "better_supabase"."enrollment_json"(v_row."id");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ensure_case_kinds (
  tenant uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_kind record;
begin
  if not exists (select 1 from "better_supabase"."case_kinds" x where x."tenant_id" = ensure_case_kinds.tenant) then
    insert into "better_supabase"."case_kinds" ("tenant_id", "key", "name", "prefix", "effectiveness_after_days", "requires_root_cause", "requires_actions", "requires_effectiveness", "requires_revisions")
    select ensure_case_kinds.tenant, s.key, s.name, s.prefix, s.days, s.root_cause, s.actions, s.effectiveness, s.revisions
    from (values
      ('nonconformity', 'Nonconformity', 'NC', null::integer, true, true, false, false),
      ('complaint', 'Complaint', 'CMP', null::integer, true, true, false, false),
      ('incident', 'Incident', 'INC', null::integer, true, true, false, false),
      ('near_miss', 'Near miss', 'NM', null::integer, true, false, false, false),
      ('observation', 'Observation', 'OBS', null::integer, false, false, false, false),
      ('improvement', 'Improvement', 'IMP', null::integer, false, true, false, false),
      ('change', 'Change request', 'CHG', null::integer, false, true, false, true),
      ('finding', 'Audit finding', 'FND', null::integer, true, true, false, false)
    ) s(key, name, prefix, days, root_cause, actions, effectiveness, revisions)
    on conflict do nothing;
  end if;
  for v_kind in
    select x."id" as id from "better_supabase"."case_kinds" x
    where x."tenant_id" = ensure_case_kinds.tenant and x."pipeline_id" is null
    for update skip locked
  loop
    update "better_supabase"."case_kinds" x set "pipeline_id" = "better_supabase"."default_pipeline"(ensure_case_kinds.tenant, 'case', v_kind.id::text)
    where x."id" = v_kind.id;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ensure_import_periods (
  tenant           uuid,
  entry_date       date,
  start_month      integer,
  close_historical boolean
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_month integer := least(greatest(coalesce(ensure_import_periods.start_month, 1), 1), 12);
  v_year integer := extract(year from ensure_import_periods.entry_date)::integer;
  v_start date;
  v_index integer;
begin
  if extract(month from ensure_import_periods.entry_date) < v_month then
    v_year := v_year - 1;
  end if;
  v_start := make_date(v_year, v_month, 1);
  if not exists (select 1 from "better_supabase"."accounting_periods" y where y."tenant_id" = ensure_import_periods.tenant and y."fiscal_year" = v_year) then
    for v_index in 0..11 loop
      insert into "better_supabase"."accounting_periods" ("tenant_id", "fiscal_year", "number", "starts_on", "ends_on")
      values (ensure_import_periods.tenant, v_year, v_index + 1, (v_start + make_interval(months => v_index))::date,
        (v_start + make_interval(months => v_index + 1))::date - 1);
    end loop;
  end if;
  if ensure_import_periods.close_historical then
    update "better_supabase"."accounting_periods" y set "status" = 'closed', "closed_at" = now()
    where y."tenant_id" = ensure_import_periods.tenant and y."fiscal_year" < v_year and y."status" = 'open';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ensure_job_queue (
  queue text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if pg_catalog.to_regclass(format('pgmq.%I', 'q_' || queue)) is null then
    perform pgmq.create(queue);
    perform better_supabase.index_job_queue(queue);
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ensure_option_set (
  tenant       uuid,
  subject_type text,
  field        text,
  scope_id     text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_set uuid;
begin
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', ensure_option_set.tenant, 'option_sets.read'), false)) then
    raise exception 'not allowed to read option sets' using errcode = '42501', hint = 'OPTION_SET_FORBIDDEN';
  end if;
  v_set := "better_supabase"."default_option_set"(ensure_option_set.tenant, ensure_option_set.subject_type, ensure_option_set.field, ensure_option_set.scope_id);
  return (select to_jsonb(y) || jsonb_build_object('items', coalesce((
      select jsonb_agg(to_jsonb(z) order by z."rank" collate "C", z."id")
      from "better_supabase"."option_set_items" z
      where z."option_set_id" = y."id" and (false or z."archived_at" is null)
    ), '[]'::jsonb)) from "better_supabase"."option_sets" y where y."id" = v_set);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ensure_organization_owner()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  -- The row lock serializes concurrent demotions and leaves, so two
  -- transactions can't each remove a different last owner.
  perform 1 from "public"."organizations" o where o."id" = old."organization_id" for update;
  if found and not exists (
      select 1 from "public"."memberships" m where m."organization_id" = old."organization_id" and (select r."key" from "better_supabase"."roles" r where r."id" = m."role") = 'owner'
    ) then
    raise exception 'An organization needs an owner' using errcode = '23514', hint = 'ORGANIZATION_OWNER_REQUIRED';
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ensure_risk_matrix (
  tenant uuid
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_id uuid;
begin
  select x."id" into v_id from "better_supabase"."risk_matrices" x
  where x."tenant_id" = ensure_risk_matrix.tenant
  order by x."is_default" desc, x."created_at"
  limit 1;
  if v_id is not null then
    return v_id;
  end if;
  insert into "better_supabase"."risk_matrices" ("tenant_id", "key", "name", "likelihood_levels", "impact_levels", "bands", "scoring", "is_default")
  values (
    ensure_risk_matrix.tenant, 'default', 'Default 5x5',
    '[{"value":1,"label":"Rare"},{"value":2,"label":"Unlikely"},{"value":3,"label":"Possible"},{"value":4,"label":"Likely"},{"value":5,"label":"Almost certain"}]'::jsonb,
    '[{"value":1,"label":"Insignificant"},{"value":2,"label":"Minor"},{"value":3,"label":"Moderate"},{"value":4,"label":"Major"},{"value":5,"label":"Severe"}]'::jsonb,
    '[{"key":"low","label":"Low","min":1,"max":4},{"key":"medium","label":"Medium","min":5,"max":9},{"key":"high","label":"High","min":10,"max":16},{"key":"critical","label":"Critical","min":17,"max":25}]'::jsonb,
    'product', true
  )
  on conflict do nothing
  returning "id" into v_id;
  if v_id is null then
    select x."id" into v_id from "better_supabase"."risk_matrices" x
    where x."tenant_id" = ensure_risk_matrix.tenant
    order by x."is_default" desc, x."created_at"
    limit 1;
  end if;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.entitlement_value (
  tenant uuid,
  key    text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select case when better_supabase.has_organization_role(tenant) then better_supabase.tenant_entitlement_value(tenant, key) end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.escalate_approvals (
  max_requests integer DEFAULT 200
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_req "better_supabase"."approval_requests"%rowtype;
  v_count integer := 0;
begin
  for v_req in
    select * from "better_supabase"."approval_requests" r
    where r."status" = 'pending'
      and (r."expires_at" is null or r."expires_at" > now())
      and r."policy" -> 'steps' -> r."step" ? 'escalateAfter'
      and not coalesce((r."policy" -> 'steps' -> r."step" ->> 'escalated')::boolean, false)
      and coalesce((
        select max(x."created_at") from "better_supabase"."approval_decisions" x
        where x."request_id" = r."id" and x."step" = r."step" - 1
      ), r."created_at") + (r."policy" -> 'steps' -> r."step" ->> 'escalateAfter')::interval <= now()
    order by r."created_at"
    limit greatest(coalesce(escalate_approvals.max_requests, 200), 1)
    for update skip locked
  loop
    update "better_supabase"."approval_requests" r set "policy" = jsonb_set(r."policy", array['steps', (r."step")::text, 'escalated'], 'true'::jsonb)
    where r."id" = v_req."id"
    returning * into v_req;
    perform "better_supabase".emit_event('approval.escalated', jsonb_build_object('organizationId', v_req."tenant_id"::text, 'subjectType', v_req."subject_type", 'subjectId', v_req."subject_id", 'id', v_req."id", 'action', v_req."action", 'status', v_req."status", 'step', v_req."step"), 'approval-requests/' || v_req."id"::text, (v_req."tenant_id")::text, null, 'better-supabase/approvals');
  perform better_supabase.audit_event(
    event_type => 'approval.escalated',
    category => 'data',
    target_type => 'approval_request',
    record_id => v_req."id"::text,
    summary => 'escalated' || ' ' || v_req."action" || ' on ' || v_req."subject_type" || ' ' || v_req."subject_id",
    tenant => (v_req."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_req."tenant_id"::text, 'subjectType', v_req."subject_type", 'subjectId', v_req."subject_id", 'id', v_req."id", 'action', v_req."action", 'status', v_req."status", 'step', v_req."step")
  );
    perform "better_supabase"."approval_notify"(v_req."id", 'escalated');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.eval_run_summary (
  run uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'total', count(*),
    'passed', count(*) filter (where x."passed"),
    'failed', count(*) filter (where not x."passed" and x."error" is null),
    'errored', count(*) filter (where x."error" is not null),
    'passRate', coalesce(round(avg(case when x."passed" then 1 else 0 end), 4), 0),
    'scorers', coalesce((
      select jsonb_object_agg(t.name, jsonb_build_object('avg', t.mean, 'passRate', t.rate))
      from (
        select e.key as name, round(avg((e.value ->> 'score')::numeric), 4) as mean,
          round(avg(case when (e.value ->> 'passed') = 'true' then 1 else 0 end), 4) as rate
        from "better_supabase"."eval_results" y, jsonb_each(y."scores") e
        where y."run_id" = eval_run_summary.run
        group by e.key
      ) t
    ), '{}'::jsonb)
  )
  from "better_supabase"."eval_results" x where x."run_id" = eval_run_summary.run;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.evaluate_care_rules (
  tenant       uuid,
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_alerts jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (evaluate_care_rules.tenant is not null and coalesce(better_supabase.can('tenant', evaluate_care_rules.tenant, 'clinical_decision_support.write'), false))) then
    raise exception 'not allowed to evaluate care rules' using errcode = '42501', hint = 'CARE_ALERT_FORBIDDEN';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (case evaluate_care_rules.subject_type
      when 'message' then exists (select 1 from "better_supabase"."messages" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'conversation' then exists (select 1 from "better_supabase"."conversations" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'channel' then exists (select 1 from "better_supabase"."channels" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'company' then exists (select 1 from "better_supabase"."companies" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'person' then exists (select 1 from "better_supabase"."people" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'deal' then exists (select 1 from "better_supabase"."deals" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'course' then exists (select 1 from "better_supabase"."courses" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'post' then exists (select 1 from "better_supabase"."posts" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'activity' then exists (select 1 from "better_supabase"."activities" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'quote' then exists (select 1 from "better_supabase"."quotes" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'work_item' then exists (select 1 from "better_supabase"."work_items" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'employee' then exists (select 1 from "better_supabase"."employees" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'ledger_account' then exists (select 1 from "better_supabase"."ledger_accounts" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'invoice' then exists (select 1 from "better_supabase"."invoices" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'product' then exists (select 1 from "better_supabase"."products" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'product_variant' then exists (select 1 from "better_supabase"."product_variants" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'rfq' then exists (select 1 from "better_supabase"."rfqs" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'till' then exists (select 1 from "better_supabase"."tills" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'order' then exists (select 1 from "better_supabase"."orders" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'calendar_event' then exists (select 1 from "better_supabase"."calendar_events" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'booking' then exists (select 1 from "better_supabase"."bookings" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'asset' then exists (select 1 from "better_supabase"."assets" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'asset_location' then exists (select 1 from "better_supabase"."asset_locations" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'lease' then exists (select 1 from "better_supabase"."leases" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'expense_report' then exists (select 1 from "better_supabase"."expense_reports" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'expense_line' then exists (select 1 from "better_supabase"."expense_lines" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'donation_fund' then exists (select 1 from "better_supabase"."donation_funds" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'warranty_claim' then exists (select 1 from "better_supabase"."warranty_claims" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'work_order' then exists (select 1 from "better_supabase"."work_orders" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'shipment' then exists (select 1 from "better_supabase"."shipments" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'contract' then exists (select 1 from "better_supabase"."contracts" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'control' then exists (select 1 from "better_supabase"."controls" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'compliance_policy' then exists (select 1 from "better_supabase"."compliance_policies" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'qualification_type' then exists (select 1 from "better_supabase"."qualification_types" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'risk' then exists (select 1 from "better_supabase"."risks" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'case' then exists (select 1 from "better_supabase"."cases" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'inspection' then exists (select 1 from "better_supabase"."inspections" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'inspection_program' then exists (select 1 from "better_supabase"."inspection_programs" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'inspection_finding' then exists (select 1 from "better_supabase"."inspection_findings" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'form' then exists (select 1 from "better_supabase"."forms" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'meeting' then exists (select 1 from "better_supabase"."meetings" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'meeting_decision' then exists (select 1 from "better_supabase"."meeting_decisions" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'maintenance_plan' then exists (select 1 from "better_supabase"."maintenance_plans" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'dam_usage_right' then exists (select 1 from "better_supabase"."dam_usage_rights" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'lims_sample' then exists (select 1 from "better_supabase"."lims_samples" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'tax_code' then exists (select 1 from "better_supabase"."tax_codes" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'production_order' then exists (select 1 from "better_supabase"."production_orders" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'work_center' then exists (select 1 from "better_supabase"."work_centers" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'bank_account' then exists (select 1 from "better_supabase"."bank_accounts" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'care_plan' then exists (select 1 from "better_supabase"."care_plans" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'incident' then exists (select 1 from "better_supabase"."incidents" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'content_entry' then exists (select 1 from "better_supabase"."content_entries" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'document' then exists (select 1 from "better_supabase"."documents" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'customer' then exists (select 1 from "public"."customers" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."organization_id"::text = evaluate_care_rules.tenant::text)
      when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'organization' then exists (select 1 from "public"."organizations" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."id"::text = evaluate_care_rules.tenant::text)
      when 'application' then exists (select 1 from "better_supabase"."applications" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."tenant_id"::text = evaluate_care_rules.tenant::text)
      when 'change_request' then exists (select 1 from "public"."change_requests" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."organization_id"::text = evaluate_care_rules.tenant::text)
      when 'project' then exists (select 1 from "public"."projects" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."organization_id"::text = evaluate_care_rules.tenant::text)
      when 'task' then exists (select 1 from "public"."tasks" s where s."id" = (evaluate_care_rules.subject_id)::uuid and s."organization_id"::text = evaluate_care_rules.tenant::text)
      else false
    end and "better_supabase"."can_subject"(evaluate_care_rules.subject_type, evaluate_care_rules.subject_id, 'read'))) then
    raise exception 'evaluating needs a record of the organization' using errcode = '22023', hint = 'CARE_ALERT_SUBJECT_INVALID';
  end if;
  with active as (
    select o."id" as order_id, o."medication_id" as medication_id, o."dose" as dose, o."dose_unit" as unit, mx."name" as name,
      coalesce(
        case when o."schedule" ? 'times' then jsonb_array_length(o."schedule" -> 'times') * o."dose"
          when o."schedule" ? 'everyHours' then 24 / nullif((o."schedule" ->> 'everyHours')::numeric, 0) * o."dose" end,
        case when o."as_needed" then o."max_per_day" end) as per_day
    from "better_supabase"."medication_orders" o join "better_supabase"."medications" mx on mx."id" = o."medication_id" and mx."tenant_id" = o."tenant_id"
    where o."tenant_id" = evaluate_care_rules.tenant and o."subject_type" = evaluate_care_rules.subject_type and o."subject_id" = evaluate_care_rules.subject_id
      and o."status" = 'active' and o."starts_on" <= (now() at time zone 'UTC')::date and (o."ends_on" is null or o."ends_on" >= (now() at time zone 'UTC')::date)
  ), raised(alert) as (
      select jsonb_build_object(
        'kind', 'dose_range', 'severity', r."severity", 'ruleId', r."id",
        'orderIds', jsonb_build_array(d.order_id),
        'fingerprint', 'dose_range:' || r."id"::text || ':' || d.order_id::text || ':min',
        'message', coalesce(r."message", format('%s: a dose of %s %s is below the minimum of %s', d.name, d.dose, d.unit, r."min_dose")),
        'details', jsonb_build_object('medicationId', d.medication_id, 'limit', 'min', 'value', d.dose, 'unit', d.unit, 'bound', r."min_dose"))
      from active d join "better_supabase"."care_rules" r on r."medication_ids"[1] = d.medication_id
      where r."tenant_id" = evaluate_care_rules.tenant and r."active" and r."kind" = 'dose_range' and r."min_dose" is not null and d.dose < r."min_dose"
    union all 
      select jsonb_build_object(
        'kind', 'dose_range', 'severity', r."severity", 'ruleId', r."id",
        'orderIds', jsonb_build_array(d.order_id),
        'fingerprint', 'dose_range:' || r."id"::text || ':' || d.order_id::text || ':max',
        'message', coalesce(r."message", format('%s: a dose of %s %s is above the maximum of %s', d.name, d.dose, d.unit, r."max_dose")),
        'details', jsonb_build_object('medicationId', d.medication_id, 'limit', 'max', 'value', d.dose, 'unit', d.unit, 'bound', r."max_dose"))
      from active d join "better_supabase"."care_rules" r on r."medication_ids"[1] = d.medication_id
      where r."tenant_id" = evaluate_care_rules.tenant and r."active" and r."kind" = 'dose_range' and r."max_dose" is not null and d.dose > r."max_dose"
    union all 
      select jsonb_build_object(
        'kind', 'dose_range', 'severity', r."severity", 'ruleId', r."id",
        'orderIds', jsonb_build_array(d.order_id),
        'fingerprint', 'dose_range:' || r."id"::text || ':' || d.order_id::text || ':day',
        'message', coalesce(r."message", format('%s: %s %s a day is above the maximum of %s', d.name, d.per_day, d.unit, r."max_per_day")),
        'details', jsonb_build_object('medicationId', d.medication_id, 'limit', 'day', 'value', d.per_day, 'unit', d.unit, 'bound', r."max_per_day"))
      from active d join "better_supabase"."care_rules" r on r."medication_ids"[1] = d.medication_id
      where r."tenant_id" = evaluate_care_rules.tenant and r."active" and r."kind" = 'dose_range' and r."max_per_day" is not null and d.per_day > r."max_per_day"
    union all
      select jsonb_build_object(
        'kind', 'duplicate_therapy', 'severity', 'warning',
        'orderIds', to_jsonb(array_agg(d.order_id order by d.order_id)),
        'fingerprint', 'duplicate:' || d.medication_id::text,
        'message', format('%s is ordered more than once', min(d.name)),
        'details', jsonb_build_object('medicationId', d.medication_id))
      from active d group by d.medication_id having count(*) > 1
    union all
      select jsonb_build_object(
        'kind', 'duplicate_therapy', 'severity', r."severity", 'ruleId', r."id",
        'orderIds', to_jsonb(array_agg(d.order_id order by d.order_id)),
        'fingerprint', 'therapy_group:' || r."id"::text,
        'message', coalesce(r."message", format('%s are in the same therapy group', string_agg(distinct d.name, ', '))),
        'details', jsonb_build_object('medicationIds', to_jsonb(array_agg(distinct d.medication_id))))
      from "better_supabase"."care_rules" r join active d on d.medication_id = any(r."medication_ids")
      where r."tenant_id" = evaluate_care_rules.tenant and r."active" and r."kind" = 'duplicate_therapy'
      group by r."id" having count(distinct d.medication_id) > 1
    union all
      select jsonb_build_object(
        'kind', 'interaction', 'severity', r."severity", 'ruleId', r."id",
        'orderIds', (select to_jsonb(array_agg(d.order_id order by d.order_id)) from active d where d.medication_id = any(r."medication_ids")),
        'fingerprint', 'interaction:' || r."id"::text,
        'message', coalesce(r."message", format('%s interact', (select string_agg(distinct d.name, ' and ') from active d where d.medication_id = any(r."medication_ids")))),
        'details', jsonb_build_object('medicationIds', to_jsonb(r."medication_ids")))
      from "better_supabase"."care_rules" r
      where r."tenant_id" = evaluate_care_rules.tenant and r."active" and r."kind" = 'interaction'
        and (select count(distinct d.medication_id) from active d where d.medication_id = any(r."medication_ids")) = 2
  )
  select coalesce(jsonb_agg(raised.alert), '[]'::jsonb) into v_alerts from raised;
  return "better_supabase"."sync_care_alerts"(evaluate_care_rules.tenant, evaluate_care_rules.subject_type, evaluate_care_rules.subject_id, 'built-in', v_alerts);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.evaluate_deadline_rule (
  rule  jsonb,
  facts jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  IMMUTABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_rule jsonb := case when rule ? 'anchor' then "better_supabase"."deadline_rule_from_v1"(rule) else rule end;
  v_result jsonb;
begin
  v_result := "better_supabase"."evaluate_deadlines"(
    jsonb_build_object('rules', jsonb_build_array(v_rule),
      'groups', jsonb_build_array(jsonb_build_object('key', v_rule -> 'group', 'citation', v_rule -> 'citation'))),
    coalesce(facts, '{}'::jsonb), current_date) -> 0;
  if v_result ->> 'result' = 'due' then
    return jsonb_build_object('status', 'due', 'dueOn', v_result -> 'dueOn');
  end if;
  return jsonb_build_object('status', 'unknown', 'missing', v_result -> 'missing');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.evaluate_deadlines (
  content   jsonb,
  facts     jsonb,
  as_of     date  DEFAULT CURRENT_DATE,
  group_key text  DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  IMMUTABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_groups jsonb;
  v_results jsonb := '{}'::jsonb;
  v_group jsonb;
  v_facts jsonb := coalesce(facts, '{}'::jsonb);
begin
  if as_of is null then
    raise exception 'as_of is required' using errcode = '22023', hint = 'DEADLINE_INVALID';
  end if;
  with recursive wanted(key) as (
    select group_key where group_key is not null
    union
    select r.key from wanted w
    join jsonb_array_elements(content -> 'groups') g(value) on g.value ->> 'key' = w.key
    cross join jsonb_array_elements_text(coalesce(g.value -> 'requires', '[]'::jsonb)) r(key)
  )
  select coalesce(jsonb_agg(g.value order by g.ord), '[]'::jsonb) into v_groups
  from jsonb_array_elements(content -> 'groups') with ordinality g(value, ord)
  where group_key is null or g.value ->> 'key' in (select w.key from wanted w);
  for v_group in select e.value from jsonb_array_elements(v_groups) e(value) loop
    v_results := v_results || jsonb_build_object(v_group ->> 'key', "better_supabase"."deadline_group"(content, v_group, v_facts, as_of));
  end loop;
  v_results := "better_supabase"."deadline_cascade"(v_results, v_groups);
  return coalesce((
    select jsonb_agg(r.value order by g.ord, r.ord)
    from jsonb_array_elements(v_groups) with ordinality g(value, ord)
    cross join jsonb_array_elements(v_results -> (g.value ->> 'key')) with ordinality r(value, ord)
    where group_key is null or g.value ->> 'key' = group_key
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.evaluate_segment (
  segment uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."segments";
  v_fields jsonb;
  v_now timestamptz := now();
  v_ids text[];
  v_entered text[];
  v_left text[];
  v_id text;
begin
  select * into v_row from "better_supabase"."segments" x where x."id" = evaluate_segment.segment for update;
  if v_row."id" is null then
    return null;
  end if;
  v_fields := "better_supabase"."rule_field_map"(v_row."subject_type");
  if v_row."subject_type" = 'message' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."messages" s
      where s."tenant_id" = v_row."tenant_id" and s."archived_at" is null
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'conversation' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."conversations" s
