  elsif v_row."subject_type" = 'inspection_finding' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."inspection_findings" s
      where s."tenant_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'form' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."forms" s
      where s."tenant_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'meeting' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."meetings" s
      where s."tenant_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'meeting_decision' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."meeting_decisions" s
      where s."tenant_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'maintenance_plan' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."maintenance_plans" s
      where s."tenant_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'dam_usage_right' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."dam_usage_rights" s
      where s."tenant_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'lims_sample' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."lims_samples" s
      where s."tenant_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'tax_code' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."tax_codes" s
      where s."tenant_id" = v_row."tenant_id" and s."archived_at" is null
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'production_order' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."production_orders" s
      where s."tenant_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'work_center' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."work_centers" s
      where s."tenant_id" = v_row."tenant_id" and s."archived_at" is null
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'bank_account' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."bank_accounts" s
      where s."tenant_id" = v_row."tenant_id" and s."archived_at" is null
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'care_plan' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."care_plans" s
      where s."tenant_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'incident' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."incidents" s
      where s."tenant_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'content_entry' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."content_entries" s
      where s."tenant_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'document' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."documents" s
      where s."tenant_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'customer' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "public"."customers" s
      where s."organization_id" = v_row."tenant_id" and s."archived_at" is null
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'drive_node' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."drive_nodes" s
      where s."tenant_id" = v_row."tenant_id" and s."archived_at" is null
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'organization' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "public"."organizations" s
      where s."id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'application' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "better_supabase"."applications" s
      where s."tenant_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'change_request' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "public"."change_requests" s
      where s."organization_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'project' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "public"."projects" s
      where s."organization_id" = v_row."tenant_id" and s."deleted_at" is null
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  elsif v_row."subject_type" = 'task' then
    select coalesce(array_agg(x.id order by x.id), '{}') into v_ids from (
      select s."id"::text as id from "public"."tasks" s
      where s."organization_id" = v_row."tenant_id"
        and "better_supabase"."rule_matches"(v_row."conditions", to_jsonb(s), v_fields, 'UTC', v_now)
      limit 10001
    ) x;
  else
    raise exception 'The segment''s subject type is not registered in config.recordTypes' using errcode = '22023', hint = 'SEGMENT_SUBJECT_UNKNOWN';
  end if;
  if cardinality(v_ids) > 10000 then
    raise exception 'A segment holds at most 10000 records; narrow its conditions' using errcode = '54000', hint = 'SEGMENT_TOO_LARGE';
  end if;
  with gone as (
    delete from "better_supabase"."segment_members" y
    where y."segment_id" = v_row."id" and not (y."subject_id" = any (v_ids))
    returning y."subject_id" as id
  ), added as (
    insert into "better_supabase"."segment_members" ("segment_id", "tenant_id", "subject_id", "entered_at")
    select v_row."id", v_row."tenant_id", z, v_now from unnest(v_ids) z
    on conflict do nothing
    returning "subject_id" as id
  )
  select coalesce((select array_agg(g.id order by g.id) from gone g), '{}'),
    coalesce((select array_agg(a.id order by a.id) from added a), '{}')
  into v_left, v_entered;
  foreach v_id in array v_entered loop
    perform "better_supabase".emit_event('segment.entered', jsonb_build_object('organizationId', v_row."tenant_id", 'segmentId', v_row."id", 'subjectType', v_row."subject_type", 'subjectId', v_id), 'segments/' || v_row."id"::text, (v_row."tenant_id"::text)::text, 'segment.entered:' || v_row."id"::text || ':' || v_id || ':' || extract(epoch from v_now)::text, 'better-supabase/segments');
  end loop;
  foreach v_id in array v_left loop
    perform "better_supabase".emit_event('segment.left', jsonb_build_object('organizationId', v_row."tenant_id", 'segmentId', v_row."id", 'subjectType', v_row."subject_type", 'subjectId', v_id), 'segments/' || v_row."id"::text, (v_row."tenant_id"::text)::text, 'segment.left:' || v_row."id"::text || ':' || v_id || ':' || extract(epoch from v_now)::text, 'better-supabase/segments');
  end loop;
  update "better_supabase"."segments" x set "member_count" = cardinality(v_ids), "refreshed_at" = v_now
  where x."id" = v_row."id";
  return jsonb_build_object('entered', cardinality(v_entered), 'left', cardinality(v_left), 'memberCount', cardinality(v_ids));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expense_report_violations (
  report_id uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(q.v order by q.ord, q.at), '[]'::jsonb)
  from (
    select 1 as ord, min(l."created_at") as at, jsonb_build_object('kind', 'limit', 'categoryId', c."id", 'category', c."name",
        'limit', c."limit_amount"::text, 'total', sum(l."amount")::text, 'currency', c."currency") as v
      from "better_supabase"."expense_lines" l join "better_supabase"."expense_categories" c on c."id" = l."category_id"
      where l."report_id" = expense_report_violations.report_id and c."limit_amount" is not null
      group by c."id"
      having sum(l."amount") > c."limit_amount"
    union all
    select 2, l."created_at", jsonb_build_object('kind', 'receipt', 'lineId', l."id", 'categoryId', c."id", 'category', c."name",
        'receiptOver', c."receipt_over"::text, 'amount', l."amount"::text, 'currency', c."currency")
      from "better_supabase"."expense_lines" l join "better_supabase"."expense_categories" c on c."id" = l."category_id"
      where l."report_id" = expense_report_violations.report_id and c."receipt_over" is not null
        and l."amount" > c."receipt_over" and (select count(*) from "better_supabase"."attachments" t where t."subject_type" = 'expense_line' and t."subject_id" = l."id"::text and t."uploaded_at" is not null and t."status" <> 'infected') = 0
    union all
    select 3, min(l."created_at"), jsonb_build_object('kind', 'archived', 'categoryId', c."id", 'category', c."name")
      from "better_supabase"."expense_lines" l join "better_supabase"."expense_categories" c on c."id" = l."category_id"
      where l."report_id" = expense_report_violations.report_id and c."archived_at" is not null
      group by c."id"
  ) q;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expire_access_grants (
  max_grants integer DEFAULT 200
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."access_requests"%rowtype;
  v_count integer := 0;
begin
  for v_row in
    select * from "better_supabase"."access_requests" r
    where r."granted_at" is not null and r."ended_at" is null and r."expires_at" <= now()
    order by r."expires_at"
    limit greatest(coalesce(expire_access_grants.max_grants, 200), 1)
    for update skip locked
  loop
    if v_row."target" = 'role' then
      -- Only a role that is still the granted one goes back; a later change wins.
      if exists (
        select 1 from "public"."memberships" m
        where m."organization_id" = v_row."tenant_id" and m."user_id" = v_row."user_id"
          and (select r."key" from "better_supabase"."roles" r where r."id" = m."role") = v_row."role"
      ) then
        if v_row."previous_role" is null then
          delete from "public"."memberships" where "organization_id" = v_row."tenant_id" and "user_id" = v_row."user_id";
        else
          update "public"."memberships" set "role" = (select r."id" from "better_supabase"."roles" r where (r."id"::text = (v_row."previous_role")::text or r."key" = (v_row."previous_role")::text) order by (r."id"::text = (v_row."previous_role")::text) desc limit 1)
          where "organization_id" = v_row."tenant_id" and "user_id" = v_row."user_id";
        end if;
      end if;
    end if;
    update "better_supabase"."access_requests" r set "ended_at" = now() where r."id" = v_row."id" returning * into v_row;
    perform "better_supabase".emit_event('access_request.ended', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'userId', v_row."user_id", 'role', v_row."role", 'id', v_row."id", 'approvalId', v_row."approval_id", 'expiresAt', v_row."expires_at", 'target', v_row."target", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'action', v_row."action", 'reason', 'expired'), 'access-requests/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/access-requests');
  perform better_supabase.audit_event(
    event_type => 'access_request.ended',
    category => 'membership',
    target_type => 'user',
    record_id => v_row."user_id"::text,
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'userId', v_row."user_id", 'role', v_row."role", 'id', v_row."id", 'approvalId', v_row."approval_id", 'expiresAt', v_row."expires_at", 'target', v_row."target", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'action', v_row."action", 'reason', 'expired')
  );
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expire_approvals (
  max_requests integer DEFAULT 500
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_req "better_supabase"."approval_requests"%rowtype;
  v_count integer := 0;
begin
  for v_req in
    update "better_supabase"."approval_requests" r set "status" = 'expired', "decided_at" = now()
    where r."id" in (
      select x."id" from "better_supabase"."approval_requests" x
      where x."status" = 'pending' and x."expires_at" <= now()
      order by x."expires_at"
      limit greatest(coalesce(expire_approvals.max_requests, 500), 1)
      for update skip locked
    )
    returning r.*
  loop
    perform "better_supabase".emit_event('approval.expired', jsonb_build_object('organizationId', v_req."tenant_id"::text, 'subjectType', v_req."subject_type", 'subjectId', v_req."subject_id", 'id', v_req."id", 'action', v_req."action", 'status', v_req."status", 'step', v_req."step"), 'approval-requests/' || v_req."id"::text, (v_req."tenant_id")::text, null, 'better-supabase/approvals');
    perform "better_supabase"."approval_notify"(v_req."id", 'expired');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expire_booking_holds()
  RETURNS integer
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select "better_supabase"."expire_booking_holds_in"(null, null)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expire_booking_holds_in (
  resource uuid,
  during   tstzrange
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_booking "better_supabase"."bookings"%rowtype;
  v_count integer := 0;
begin
  for v_booking in
    update "better_supabase"."bookings" bk set "status" = 'cancelled', "hold_expires_at" = null, "cancelled_at" = now(), "cancel_reason" = 'expired', "updated_at" = now()
    where bk."status" = 'hold' and bk."hold_expires_at" <= now()
      and (expire_booking_holds_in.resource is null or bk."resource_id" = expire_booking_holds_in.resource)
      and (expire_booking_holds_in.during is null or bk."blocked" && expire_booking_holds_in.during)
    returning bk.*
  loop
    v_count := v_count + 1;
    perform "better_supabase".emit_event('booking.expired', jsonb_build_object('organizationId', v_booking."tenant_id", 'id', v_booking."id", 'resourceId', v_booking."resource_id", 'serviceId', v_booking."service_id"), 'bookings/' || v_booking."id"::text, (v_booking."tenant_id")::text, null, 'better-supabase/bookings');
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expire_consents()
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."consents";
  v_purpose "better_supabase"."consent_purposes";
  v_count integer := 0;
begin
  for v_row in
    update "better_supabase"."consents" x set "status" = 'expired'
    where x."status" = 'granted' and x."expires_at" <= now()
    returning x.*
  loop
    select * into v_purpose from "better_supabase"."consent_purposes" y where y."id" = v_row."purpose_id";
    perform "better_supabase".emit_event('consent.expired', jsonb_build_object('organizationId', v_row."tenant_id", 'consentId', v_row."id", 'purposeId', v_row."purpose_id", 'purposeKey', v_purpose."key", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'givenBy', v_row."given_by"), 'consents/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/consents');
  perform better_supabase.audit_event(
    event_type => 'consent.expired',
    category => 'data',
    target_type => 'consent',
    record_id => v_row."id"::text,
    target_label => v_purpose."title",
    summary => 'a consent expired',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'consentId', v_row."id", 'purposeId', v_row."purpose_id", 'purposeKey', v_purpose."key", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status", 'givenBy', v_row."given_by")
  );
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expire_ledger_holds (
  max_rows integer DEFAULT 500
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_id uuid;
  v_row "better_supabase"."ledger_holds"%rowtype;
  v_count integer := 0;
begin
  for v_id in
    select x."id" from "better_supabase"."ledger_holds" x
    where x."status" = 'active' and x."expires_at" <= now()
    order by x."expires_at"
    limit least(greatest(coalesce(expire_ledger_holds.max_rows, 500), 1), 5000)
    for update skip locked
  loop
    v_row := "better_supabase"."ledger_unhold"(v_id, 'expired');
    perform "better_supabase".emit_event('ledger_hold.released', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'accountId', v_row."account_id", 'amount', v_row."amount"::text, 'status', v_row."status", 'transactionId', v_row."transaction_id"), 'ledger-holds/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/ledger');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expire_lots (
  tenant uuid,
  as_of  date
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row record;
  v_count integer := 0;
begin
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', expire_lots.tenant, 'inventory.manage'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  for v_row in
    select y."variant_id" as variant, y."location_id" as location, y."bin_id" as bin, y."lot_id" as lot, y."on_hand" as on_hand,
      (select array_agg(z."serial") from "better_supabase"."stock_serials" z where z."variant_id" = y."variant_id" and z."lot_id" = y."lot_id"
        and z."location_id" = y."location_id" and z."bin_id" is not distinct from y."bin_id" and z."status" = 'in_stock') as serials
    from "better_supabase"."stock_buckets" y join "better_supabase"."stock_lots" lo on lo."id" = y."lot_id"
    where y."tenant_id" = expire_lots.tenant and y."on_hand" > 0 and lo."expires_on" < coalesce(expire_lots.as_of, current_date)
    order by lo."expires_on"
    for update of y
  loop
    perform "better_supabase"."move_stock"(expire_lots.tenant, v_row.variant, v_row.location, -v_row.on_hand, 'expired', 'stock_lot', v_row.lot::text, null, jsonb_strip_nulls(jsonb_build_object('binId', v_row.bin, 'lotId', v_row.lot, 'serials', to_jsonb(v_row.serials))));
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expire_orders (
  max_rows integer DEFAULT 100
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_id uuid;
  v_count integer := 0;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'only the service role can do this' using errcode = '42501', hint = 'ORDERS_FORBIDDEN';
  end if;
  for v_id in
    select x."id" from "better_supabase"."orders" x
    where x."status" = 'pending_payment' and x."placed_at" < now() - interval '30 minutes'
    order by x."placed_at"
    limit greatest(coalesce(expire_orders.max_rows, 100), 1)
    for update skip locked
  loop
    perform "better_supabase"."order_cancel"(v_id, 'payment_expired');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expire_quotes()
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."quotes";
  v_count integer := 0;
begin
  perform set_config('better_supabase.transition_actor', '', true);
  for v_row in
    update "better_supabase"."quotes" x set "status" = 'expired', "updated_at" = now()
    where x."status" in ('sent', 'viewed') and x."valid_until" < current_date
    returning *
  loop
    perform "better_supabase".emit_event('quote.expired', jsonb_build_object('organizationId', v_row."tenant_id", 'quoteId', v_row."id", 'subjectType', 'quote', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier"), 'quotes/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/quotes');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expire_reservations (
  max_rows integer
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row record;
  v_count integer := 0;
begin
  for v_row in
    select x."id" as id, x."tenant_id" as tenant, x."variant_id" as variant,
      x."location_id" as location, x."quantity" as quantity
    from "better_supabase"."stock_reservations" x
    where x."status" = 'active' and x."expires_at" <= now()
    order by x."expires_at"
    limit greatest(coalesce(expire_reservations.max_rows, 500), 1)
    for update skip locked
  loop
    update "better_supabase"."stock_reservations" x set "status" = 'expired', "updated_at" = now() where x."id" = v_row.id;
    update "better_supabase"."stock_levels" x set "reserved" = greatest(x."reserved" - v_row.quantity, 0), "updated_at" = now()
  where x."variant_id" = v_row.variant and x."location_id" = v_row.location;
    perform "better_supabase".emit_event('reservation.released', jsonb_build_object('organizationId', v_row.tenant, 'id', v_row.id, 'variantId', v_row.variant, 'locationId', v_row.location, 'quantity', v_row.quantity::text, 'reason', 'expired'), 'stock-reservations/' || v_row.id::text, (v_row.tenant)::text, null, 'better-supabase/inventory');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expired_data_exports (
  max_rows integer DEFAULT 100
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', x."id", 'bucket', x."bucket", 'files', to_jsonb(x."files")) order by x."expires_at"), '[]'::jsonb)
  from (
    select * from "better_supabase"."data_exports" y
    where y."expires_at" < now()
    order by y."expires_at"
    limit greatest(1, least(coalesce(max_rows, 100), 1000))
  ) x
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expiring_ai_provider_files (
  horizon interval DEFAULT '1 day'::interval,
  batch   integer  DEFAULT 100
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('file_id', p."file_id", 'provider', p."provider", 'reference', p."reference", 'expires_at', p."expires_at")), '[]'::jsonb)
  from (
    select * from "better_supabase"."ai_provider_files"
    where "expires_at" is not null and "expires_at" <= now() + coalesce(horizon, interval '1 day')
    order by "expires_at"
    limit greatest(coalesce(batch, 100), 1)
  ) p
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expiring_connector_grants (
  before   timestamp with time zone,
  max_rows integer                  DEFAULT 100
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', y."id", 'user_id', y."user_id", 'server_id', y."server_id", 'tenant_id', y."tenant_id", 'credential_ref', y."credential_ref", 'scopes', y."scopes", 'expires_at', y."expires_at", 'granted_at', y."granted_at", 'revoked_at', y."revoked_at") order by y."expires_at"), '[]')
  from (
    select * from "better_supabase"."connector_grants" y0
    where y0."revoked_at" is null and y0."expires_at" is not null and y0."expires_at" < expiring_connector_grants.before
    order by y0."expires_at"
    limit least(greatest(expiring_connector_grants.max_rows, 1), 1000)
  ) y
$function$;

CREATE OR REPLACE FUNCTION better_supabase.expiring_lots (
  tenant uuid,
  before date
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', expiring_lots.tenant, 'inventory.read'), false)) then
    raise exception 'not allowed to read this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('lotId', lo."id", 'code', lo."code", 'variantId', lo."variant_id",
      'locationId', y."location_id", 'binId', y."bin_id", 'expiresOn', lo."expires_on", 'onHand', y."on_hand"::text)
      order by lo."expires_on", lo."code", y."location_id")
    from "better_supabase"."stock_buckets" y join "better_supabase"."stock_lots" lo on lo."id" = y."lot_id"
    where y."tenant_id" = expiring_lots.tenant and y."on_hand" > 0
      and lo."expires_on" <= coalesce(expiring_lots.before, current_date)), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.explode_bom (
  variant_id uuid,
  quantity   numeric
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (select cv."tenant_id" from "better_supabase"."product_variants" cv where cv."id" = explode_bom.variant_id);
  v_lines jsonb;
begin
  if v_tenant is null or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_tenant is not null and coalesce(better_supabase.can('tenant', v_tenant, 'manufacturing.read'), false))) then
    raise exception 'no such bill of materials' using errcode = 'P0002', hint = 'BOM_NOT_FOUND';
  end if;
  if explode_bom.quantity is null or explode_bom.quantity <= 0 then
    raise exception 'the quantity must be more than zero' using errcode = '22023', hint = 'BOM_INVALID';
  end if;
  if not exists (select 1 from "better_supabase"."boms" x where x."variant_id" = explode_bom.variant_id and x."status" = 'active') then
    raise exception 'the variant has no active bill of materials' using errcode = '55000', hint = 'BOM_NOT_ACTIVE';
  end if;
  with recursive tree(variant, parent, bom, quantity, level, path) as (
    select y."variant_id", x."variant_id", x."id",
      explode_bom.quantity * y."quantity" / x."quantity" * (1 + y."scrap_bps" / 10000.0), 1,
      array[x."variant_id", y."variant_id"]
    from "better_supabase"."boms" x join "better_supabase"."bom_components" y on y."bom_id" = x."id"
    where x."variant_id" = explode_bom.variant_id and x."status" = 'active'
    union all
    select y."variant_id", x."variant_id", x."id",
      tree.quantity * y."quantity" / x."quantity" * (1 + y."scrap_bps" / 10000.0), tree.level + 1,
      tree.path || y."variant_id"
    from tree
    join "better_supabase"."boms" x on x."variant_id" = tree.variant and x."status" = 'active'
    join "better_supabase"."bom_components" y on y."bom_id" = x."id"
    where tree.level < 20 and not (y."variant_id" = any (tree.path))
  )
  select coalesce(jsonb_agg(jsonb_build_object('level', t.level, 'variantId', t.variant, 'parentVariantId', t.parent, 'bomId', t.bom,
      'quantity', "better_supabase"."production_quantity"(t.variant, t.quantity)::text,
      'made', exists (select 1 from "better_supabase"."boms" z where z."variant_id" = t.variant and z."status" = 'active'))
    order by t.path), '[]'::jsonb)
  into v_lines from tree t;
  return jsonb_build_object('variantId', explode_bom.variant_id, 'quantity', explode_bom.quantity::text, 'lines', v_lines,
    'materials', coalesce((select jsonb_agg(jsonb_build_object('variantId', m.variant, 'quantity', m.quantity::text) order by m.variant)
      from (select (e ->> 'variantId')::uuid as variant, sum((e ->> 'quantity')::numeric) as quantity
        from jsonb_array_elements(v_lines) e where not (e ->> 'made')::boolean group by 1) m), '[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.export_import_hashes (
  tenant uuid,
  source text,
  entity text DEFAULT NULL::text
)
  RETURNS SETOF jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object('entity', x."entity", 'scope', x."scope", 'key', x."external_key", 'role', x."role",
    'hash', x."content_hash", 'subjectType', x."subject_type", 'subjectId', x."subject_id")
  from "better_supabase"."import_records" x
  where x."tenant_id" = export_import_hashes.tenant and x."source" = export_import_hashes.source
    and (export_import_hashes.entity is null or x."entity" = export_import_hashes.entity)
  order by x."entity", x."scope", x."external_key", x."role"
$function$;

CREATE OR REPLACE FUNCTION better_supabase.export_oscal_assessment_results (
  framework_id uuid,
  title        text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_framework "better_supabase"."control_frameworks"%rowtype;
  v_now text := to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
  v_title text;
begin
  select * into v_framework from "better_supabase"."control_frameworks" x where x."id" = export_oscal_assessment_results.framework_id;
  if not found then
    raise exception 'framework not found' using errcode = 'P0002', hint = 'CONTROL_FRAMEWORK_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_framework."tenant_id", 'compliance.read'), false)) then
    raise exception 'not allowed to read controls' using errcode = '42501', hint = 'CONTROL_FORBIDDEN';
  end if;
  v_title := coalesce(nullif(trim(export_oscal_assessment_results.title), ''), v_framework."name" || ' assessment results');
  return jsonb_build_object('assessment-results', jsonb_build_object(
    'uuid', gen_random_uuid(),
    'metadata', jsonb_build_object(
      'title', v_title,
      'last-modified', v_now,
      'version', coalesce(v_framework."version", '1'),
      'oscal-version', '1.2.3'
    ),
    'import-ap', jsonb_build_object('href', 'urn:uuid:' || v_framework."id"::text),
    'results', jsonb_build_array(jsonb_build_object(
      'uuid', gen_random_uuid(),
      'title', v_title,
      'description', 'Evidence collected for the applicable controls of ' || v_framework."name" || '.',
      'start', v_now,
      'reviewed-controls', jsonb_build_object('control-selections', jsonb_build_array(jsonb_build_object(
        'include-controls', coalesce((
          select jsonb_agg(jsonb_build_object('control-id', c."code") order by c."code")
          from "better_supabase"."controls" c where c."framework_id" = v_framework."id" and c."applicable"
        ), '[]'::jsonb)
      ))),
      'observations', coalesce((
        select jsonb_agg(jsonb_build_object(
          'uuid', ev."id",
          'description', coalesce(ev."note", 'Evidence for control ' || c."code"),
          'methods', jsonb_build_array('EXAMINE'),
          'collected', to_char(ev."collected_at" at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
          'relevant-evidence', jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
            'description', coalesce(ev."note", 'Attachment'),
            'href', case when ev."attachment_id" is null then null else 'urn:uuid:' || ev."attachment_id"::text end
          )))
        ) order by c."code", ev."collected_at", ev."id")
        from "better_supabase"."control_evidence" ev
        join "better_supabase"."controls" c on c."id" = ev."control_id"
        where c."framework_id" = v_framework."id" and c."applicable"
      ), '[]'::jsonb),
      'findings', coalesce((
        select jsonb_agg(jsonb_build_object(
          'uuid', gen_random_uuid(),
          'title', c."code" || ' ' || c."title",
          'description', c."title",
          'target', jsonb_build_object(
            'type', 'objective-id',
            'target-id', c."code",
            'status', jsonb_build_object('state', case when exists (
              select 1 from "better_supabase"."control_evidence" ev where ev."control_id" = c."id" and (ev."valid_until" is null or ev."valid_until" >= current_date)
            ) then 'satisfied' else 'not-satisfied' end)
          ),
          'related-observations', coalesce((
            select jsonb_agg(jsonb_build_object('observation-uuid', ev."id") order by ev."collected_at", ev."id")
            from "better_supabase"."control_evidence" ev where ev."control_id" = c."id"
          ), '[]'::jsonb)
        ) order by c."code")
        from "better_supabase"."controls" c where c."framework_id" = v_framework."id" and c."applicable"
      ), '[]'::jsonb)
    ))
  ));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.extend_data_subject_request (
  id     uuid,
  reason text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."data_subject_requests";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."data_subject_requests" x where x."id" = extend_data_subject_request.id for update;
  if v_row."id" is null then
    raise exception 'request not found' using errcode = 'P0002', hint = 'DSAR_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'data_lifecycle.export'), false)) then
    raise exception 'You may not handle data subject requests here' using errcode = '42501', hint = 'DSAR_FORBIDDEN';
  end if;
  if v_row."closed_at" is not null then
    raise exception 'the request is already fulfilled or refused' using errcode = '55000', hint = 'DSAR_CLOSED';
  end if;
  if v_row."extended_at" is not null then
    raise exception 'the due date was already extended once' using errcode = '55000', hint = 'DSAR_EXTENDED';
  end if;
  if extend_data_subject_request.reason is null or length(trim(extend_data_subject_request.reason)) = 0 then
    raise exception 'reason is required' using errcode = '22023', hint = 'DSAR_INVALID';
  end if;
  update "better_supabase"."data_subject_requests" x set "due_at" = x."received_at" + interval '3 months', "extended_at" = now(), "extension_reason" = trim(extend_data_subject_request.reason)
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('data_subject_request.extended', jsonb_build_object('requestId', v_row."id", 'organizationId', v_row."tenant_id"::text, 'kind', v_row."kind"::text, 'status', v_row."status"::text, 'dueAt', v_row."due_at"), 'data-subject-requests/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/data-lifecycle');
  perform better_supabase.audit_event(
    event_type => 'data_subject_request.extended',
    category => 'data',
    target_type => 'data_subject_request',
    record_id => v_row."id"::text,
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('requestId', v_row."id", 'organizationId', v_row."tenant_id"::text, 'kind', v_row."kind"::text, 'status', v_row."status"::text, 'dueAt', v_row."due_at")
  );
  return to_jsonb(v_row);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.extend_idempotent (
  scope  text,
  key    text,
  holder uuid,
  lock   interval DEFAULT '00:01:00'::interval
)
  RETURNS boolean
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  with extended as (
    update "better_supabase"."idempotency_keys" k
    set "lock_expires_at" = now() + extend_idempotent.lock
    where k."scope" = extend_idempotent.scope and k."key" = extend_idempotent.key
      and k."status" = 'running' and k."holder" = extend_idempotent.holder
      and k."lock_expires_at" > now()
    returning 1
  )
  select exists (select 1 from extended)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.extend_job_lease (
  queue   text,
  job_id  bigint,
  attempt integer,
  lease   integer
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  hit bigint;
begin
  execute format('select msg_id from pgmq.%I where msg_id = $1 and read_ct = $2 for update', 'q_' || queue)
    into hit using job_id, attempt;
  if hit is null then
    return false;
  end if;
  perform pgmq.set_vt(queue, job_id, lease);
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.extend_lease (
  key     text,
  holder  uuid,
  seconds integer DEFAULT 60,
  scope   text    DEFAULT ''::text
)
  RETURNS boolean
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  with extended as (
    update "better_supabase"."idempotency_leases" l
    set "expires_at" = now() + make_interval(secs => greatest(extend_lease.seconds, 1))
    where l."scope" = extend_lease.scope and l."key" = extend_lease.key
      and l."holder" = extend_lease.holder and l."expires_at" > now()
    returning 1
  )
  select exists (select 1 from extended)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.extend_lease_claim (
  scope         text,
  key           text,
  holder        uuid,
  lease_seconds integer DEFAULT 60
)
  RETURNS boolean
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  with extended as (
    update "better_supabase"."job_leases" l
    set "expires_at" = now() + make_interval(secs => greatest(coalesce(extend_lease_claim.lease_seconds, 60), 1))
    where l."scope" = extend_lease_claim.scope and l."key" = extend_lease_claim.key
      and l."holder" = extend_lease_claim.holder and l."state" = 'held'
      and l."expires_at" > now()
    returning 1
  )
  select exists (select 1 from extended)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.extend_webhook (
  inbox_id bigint,
  worker   text,
  attempt  integer,
  lease    interval DEFAULT '00:05:00'::interval
)
  RETURNS double precision
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  update better_supabase.webhook_inbox
  set lock_expires_at = now() + lease
  where id = inbox_id and locked_by = worker and status = 'processing'
    and attempts = attempt
  returning extract(epoch from lease)::double precision
$function$;

CREATE OR REPLACE FUNCTION better_supabase.fail_activity_recording (
  recording uuid,
  error     text
)
  RETURNS boolean
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  with failed as (
    update "better_supabase"."activity_recordings" rx set "status" = 'failed', "error" = left(fail_activity_recording.error, 2000)
    where rx."id" = fail_activity_recording.recording and rx."status" <> 'transcribed'
    returning 1
  )
  select exists (select 1 from failed)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.fail_data_export (
  id    uuid,
  error text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."data_exports";
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'Only the service role runs exports' using errcode = '42501', hint = 'DATA_EXPORT_FORBIDDEN';
  end if;
  update "better_supabase"."data_exports" x set "status" = 'failed', "error" = fail_data_export.error, "completed_at" = now()
  where x."id" = fail_data_export.id and x."status" = 'running'
  returning * into v_row;
  if v_row."id" is null then
    return null;
  end if;
  perform "better_supabase".emit_event('data_export.failed', jsonb_build_object('exportId', v_row."id", 'subject', v_row."subject", 'organizationId', v_row."tenant_id"::text, 'userId', v_row."user_id", 'requestedBy', v_row."requested_by", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'error', v_row."error"), 'data-exports/' || v_row."id"::text, (v_row."tenant_id")::text, 'data_export.failed:' || v_row."id"::text || ':' || v_row."completed_at"::text, 'better-supabase/data-lifecycle');
  perform better_supabase.audit_event(
    event_type => 'data_export.failed',
    category => 'data',
    target_type => 'data_export',
    record_id => v_row."id"::text,
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('exportId', v_row."id", 'subject', v_row."subject", 'organizationId', v_row."tenant_id"::text, 'userId', v_row."user_id", 'requestedBy', v_row."requested_by", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'error', v_row."error"),
    idempotency_key => 'data_export.failed:' || v_row."id"::text || ':' || v_row."completed_at"::text
  );
  return to_jsonb(v_row);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.fail_import_chunk (
  run     uuid,
  entity  text,
  chunk   integer,
  message text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
begin
  update "better_supabase"."import_chunks" x set "status" = 'failed', "done_at" = now(),
    "result" = jsonb_build_object('failed', true, 'message', left(coalesce(fail_import_chunk.message, ''), 500))
  where x."run_id" = fail_import_chunk.run and x."entity" = fail_import_chunk.entity
    and x."chunk" = fail_import_chunk.chunk and x."status" in ('pending', 'claimed', 'failed');
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.fail_job (
  queue    text,
  job_id   bigint,
  attempt  integer,
  error    text,
  retry_in integer DEFAULT NULL::integer
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  msg jsonb;
begin
  execute format('select message from pgmq.%I where msg_id = $1 and read_ct = $2 for update', 'q_' || queue)
    into msg using job_id, attempt;
  if msg is null then
    return null;
  end if;
  if attempt >= coalesce((msg ->> 'max_attempts')::integer, 5) then
    execute format('update pgmq.%I set message = message || jsonb_build_object(''last_error'', $2::text, ''dead'', true) where msg_id = $1', 'q_' || queue)
      using job_id, left(error, 4000);
    perform pgmq.archive(queue, job_id);
    return 'dead';
  end if;
  execute format('update pgmq.%I set message = message || jsonb_build_object(''last_error'', $2::text), vt = clock_timestamp() + make_interval(secs => $3) where msg_id = $1', 'q_' || queue)
    using job_id, left(error, 4000), coalesce(retry_in, 1 + floor(random() * least(3600, 10 * power(2, attempt - 1)))::integer);
  return 'queued';
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.fail_knowledge_document (
  document_id uuid,
  error       text
)
  RETURNS boolean
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  update "better_supabase"."knowledge_documents" x set "status" = 'failed', "error" = left(fail_knowledge_document.error, 2000), "updated_at" = now()
  where x."id" = fail_knowledge_document.document_id
  returning true
$function$;

CREATE OR REPLACE FUNCTION better_supabase.fail_webhook (
  inbox_id  bigint,
  worker    text,
  error     text,
  retry_in  interval DEFAULT NULL::interval,
  attempt   integer  DEFAULT NULL::integer,
  permanent boolean  DEFAULT false
)
  RETURNS text
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  update better_supabase.webhook_inbox
  set status = case when permanent or attempts >= max_attempts then 'dead' else 'pending' end,
      available_at = now() + coalesce(retry_in, least(interval '1 hour', interval '1 second' * power(2, attempts))),
      last_error = left(error, 4000),
      locked_by = null,
      lock_expires_at = null
  where id = inbox_id and locked_by = worker and status = 'processing'
    and (attempt is null or attempts = attempt)
  returning status
$function$;

CREATE OR REPLACE FUNCTION better_supabase.feature_claims (
  user_id uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_object_agg(r.tenant, to_jsonb(r.keys)), '{}'::jsonb)
  from (
    select m."organization_id"::text as tenant, e.keys
    from "public"."memberships" m
    cross join lateral (select better_supabase.tenant_entitlements(m."organization_id") as keys) e
    where m."user_id" = feature_claims.user_id
      and cardinality(e.keys) > 0
    order by 1
  ) r
$function$;

CREATE OR REPLACE FUNCTION better_supabase.field_decrypt (
  owner text,
  value text
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if field_decrypt.value is null then
    return null;
  end if;
  return "better_supabase"."field_open"("better_supabase"."field_key"(field_decrypt.owner, false), field_decrypt.value);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.field_encrypt (
  owner text,
  value text
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if field_encrypt.value is null then
    return null;
  end if;
  return "better_supabase"."field_seal"("better_supabase"."field_key"(field_encrypt.owner, true), field_encrypt.value);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.field_hash (
  key   text,
  value text
)
  RETURNS bytea
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select case when field_hash.key is null or field_hash.value is null then null
    else extensions.hmac(convert_to(lower(regexp_replace(field_hash.value, '\s', '', 'g')), 'UTF8'), decode(field_hash.key, 'base64'), 'sha256')
  end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.field_history (
  subject_type text,
  subject_id   text,
  field        text    DEFAULT NULL::text,
  before       bigint  DEFAULT NULL::bigint,
  max_count    integer DEFAULT NULL::integer
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', z."id"::text,
    'organizationId', z."tenant_id",
    'subjectType', z."subject_type",
    'subjectId', z."subject_id",
    'field', z."field",
    'before', z."old_value",
    'after', z."new_value",
    'changedBy', z."changed_by",
    'changedAt', z."changed_at"
  ) order by z."id" desc), '[]'::jsonb)
  from (
    select x.* from "better_supabase"."field_changes" x
    where x."subject_type" = field_history.subject_type
      and x."subject_id" = field_history.subject_id
      and (field_history.field is null or x."field" = field_history.field)
      and (field_history.before is null or x."id" < field_history.before)
      and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (coalesce(better_supabase.can('tenant', x."tenant_id", 'field_history.read'), false) and coalesce("better_supabase"."can_subject"(field_history.subject_type, field_history.subject_id, 'read'), false)))
    order by x."id" desc
    limit least(greatest(coalesce(field_history.max_count, 50), 1), 500)
  ) z
$function$;

CREATE OR REPLACE FUNCTION better_supabase.field_key (
  owner text,
  make  boolean DEFAULT true
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_key text;
begin
  if field_key.owner is null or length(field_key.owner) = 0 then
    raise exception 'a field key needs an owner' using errcode = '22023', hint = 'FIELD_KEY_OWNER';
  end if;
  select ds.decrypted_secret into v_key from vault.decrypted_secrets ds
  where ds.name = 'bs:field-key:' || field_key.owner;
  if v_key is not null or not field_key.make then
    return v_key;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('bs:field-key:' || field_key.owner, 0));
  select ds.decrypted_secret into v_key from vault.decrypted_secrets ds
  where ds.name = 'bs:field-key:' || field_key.owner;
  if v_key is null then
    v_key := encode(extensions.gen_random_bytes(32), 'base64');
    perform vault.create_secret(v_key, 'bs:field-key:' || field_key.owner, 'better-supabase field encryption key');
  end if;
  return v_key;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.field_lookup (
  owner text,
  value text
)
  RETURNS bytea
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if field_lookup.value is null then
    return null;
  end if;
  return "better_supabase"."field_hash"("better_supabase"."field_lookup_key"(field_lookup.owner, false), field_lookup.value);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.field_lookup_key (
  owner text,
  make  boolean DEFAULT true
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_key text;
begin
  if field_lookup_key.owner is null or length(field_lookup_key.owner) = 0 then
    raise exception 'a field key needs an owner' using errcode = '22023', hint = 'FIELD_KEY_OWNER';
  end if;
  select ds.decrypted_secret into v_key from vault.decrypted_secrets ds
  where ds.name = 'bs:field-lookup-key:' || field_lookup_key.owner;
  if v_key is not null or not field_lookup_key.make then
    return v_key;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('bs:field-lookup-key:' || field_lookup_key.owner, 0));
  select ds.decrypted_secret into v_key from vault.decrypted_secrets ds
  where ds.name = 'bs:field-lookup-key:' || field_lookup_key.owner;
  if v_key is null then
    v_key := encode(extensions.gen_random_bytes(32), 'base64');
    perform vault.create_secret(v_key, 'bs:field-lookup-key:' || field_lookup_key.owner, 'better-supabase field lookup key');
  end if;
  return v_key;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.field_open (
  key   text,
  value text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select case
    when field_open.value is null then null
    when left(field_open.value, 5) <> 'bsf1:' then field_open.value
    when field_open.key is null then null
    else extensions.pgp_sym_decrypt(decode(substr(field_open.value, 6), 'base64'), field_open.key)
  end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.field_seal (
  key   text,
  value text
)
  RETURNS text
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  select case when field_seal.value is null then null
    when left(field_seal.value, 5) = 'bsf1:' then field_seal.value
    else 'bsf1:' || translate(encode(extensions.pgp_sym_encrypt(field_seal.value, field_seal.key, 'cipher-algo=aes256, s2k-mode=1'), 'base64'), E'\n', '')
  end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.file_appeal (
  statement_id uuid DEFAULT NULL::uuid,
  notice_id    uuid DEFAULT NULL::uuid,
  reasons      text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_me uuid := auth.uid();
  v_tenant uuid;
  v_row "better_supabase"."moderation_appeals";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if v_me is null then
    raise exception 'sign in to file an appeal' using errcode = '42501', hint = 'MODERATION_FORBIDDEN';
  end if;
  if (file_appeal.statement_id is null) = (file_appeal.notice_id is null) then
    raise exception 'an appeal names a statement or a notice' using errcode = '22023', hint = 'MODERATION_INVALID';
  end if;
  if file_appeal.reasons is null or length(trim(file_appeal.reasons)) = 0 or length(file_appeal.reasons) > 5000 then
    raise exception 'an appeal needs reasons of at most 5000 characters' using errcode = '22023', hint = 'MODERATION_INVALID';
  end if;
  if file_appeal.statement_id is not null then
    select s."tenant_id" into v_tenant
    from "better_supabase"."moderation_statements" s join "better_supabase"."moderation_items" x on x."id" = s."item_id"
    where s."id" = file_appeal.statement_id and x."author_id" = v_me;
  else
    select x."tenant_id" into v_tenant from "better_supabase"."moderation_notices" x
    where x."id" = file_appeal.notice_id and x."notifier_id" = v_me and x."status" = 'rejected';
  end if;
  if v_tenant is null then
    raise exception 'you can only appeal a decision that affects you' using errcode = '42501', hint = 'MODERATION_FORBIDDEN';
  end if;
  begin
    insert into "better_supabase"."moderation_appeals" ("tenant_id", "statement_id", "notice_id", "appellant_id", "reasons")
    values (v_tenant, file_appeal.statement_id, file_appeal.notice_id, v_me, trim(file_appeal.reasons))
    returning * into v_row;
  exception when unique_violation then
    raise exception 'an appeal is open for this decision already' using errcode = '22023', hint = 'MODERATION_INVALID';
  end;
  perform "better_supabase".emit_event('moderation_appeal.filed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'statementId', v_row."statement_id", 'noticeId', v_row."notice_id", 'appellantId', v_row."appellant_id"), 'moderation-appeals/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/moderation');
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'statementId', v_row."statement_id", 'noticeId', v_row."notice_id", 'appellantId', v_row."appellant_id", 'reasons', v_row."reasons", 'status', v_row."status", 'outcome', v_row."outcome", 'decidedBy', v_row."decided_by", 'decidedAt', v_row."decided_at", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.file_tax_return (
  return_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."tax_returns"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."tax_returns" y where y."id" = file_tax_return.return_id for update;
  if v_row."id" is null then
    raise exception 'no such tax return' using errcode = 'P0002', hint = 'TAX_RETURN_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'tax.manage'), false))) then
    raise exception 'not allowed to file tax returns' using errcode = '42501', hint = 'TAX_FORBIDDEN';
  end if;
  if v_row."status" = 'filed' then
    return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'legalEntityId', v_row."legal_entity_id", 'period', v_row."period", 'periodStart', v_row."period_start", 'periodEnd', v_row."period_end", 'status', v_row."status", 'currency', v_row."currency", 'boxes', v_row."boxes", 'euSalesList', coalesce((select jsonb_agg(jsonb_build_object('customerVatNumber', z."customer_vat_number", 'country', z."country", 'kind', z."kind", 'amount', z."amount"::text, 'currency', z."currency", 'invoiceCount', z."invoice_count") order by z."customer_vat_number", z."kind", z."currency") from "better_supabase"."eu_sales_list_lines" z where z."tax_return_id" = v_row."id"), '[]'::jsonb), 'preparedBy', v_row."prepared_by", 'preparedAt', v_row."prepared_at", 'filedAt', v_row."filed_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
  end if;
  update "better_supabase"."tax_returns" y set "status" = 'filed', "filed_at" = now(), "updated_at" = now()
  where y."id" = v_row."id"
  returning * into v_row;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'legalEntityId', v_row."legal_entity_id", 'period', v_row."period", 'periodStart', v_row."period_start", 'periodEnd', v_row."period_end", 'status', v_row."status", 'currency', v_row."currency", 'boxes', v_row."boxes", 'euSalesList', coalesce((select jsonb_agg(jsonb_build_object('customerVatNumber', z."customer_vat_number", 'country', z."country", 'kind', z."kind", 'amount', z."amount"::text, 'currency', z."currency", 'invoiceCount', z."invoice_count") order by z."customer_vat_number", z."kind", z."currency") from "better_supabase"."eu_sales_list_lines" z where z."tax_return_id" = v_row."id"), '[]'::jsonb), 'preparedBy', v_row."prepared_by", 'preparedAt', v_row."prepared_at", 'filedAt', v_row."filed_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.fill_asset_due_check()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if new."last_done_at" is not null then
    new."next_due_at" := new."last_done_at" + make_interval(days => new."interval_days");
  end if;
  new."updated_at" := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.fill_backorders (
  tenant   uuid,
  variant  uuid,
  location uuid
)
  RETURNS numeric
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row record;
  v_available numeric;
  v_take numeric;
  v_total numeric := 0;
begin
  select x."available" into v_available from "better_supabase"."stock_levels" x
  where x."variant_id" = fill_backorders.variant and x."location_id" = fill_backorders.location for update;
  if coalesce(v_available, 0) <= 0 then
    return 0;
  end if;
  for v_row in
    select x."id" as id, x."tenant_id" as tenant, x."variant_id" as variant, x."location_id" as location,
      x."document_type" as document_type, x."document_id" as document_id, x."backordered" as quantity
    from "better_supabase"."stock_allocations" x
    where x."variant_id" = fill_backorders.variant and x."location_id" = fill_backorders.location
      and x."status" = 'open' and x."backordered" > 0
    order by x."created_at", x."id"
    for update
  loop
    exit when v_available <= 0;
    v_take := least(v_available, v_row.quantity);
    update "better_supabase"."stock_allocations" x set "allocated" = x."allocated" + v_take, "updated_at" = now() where x."id" = v_row.id;
    v_available := v_available - v_take;
    v_total := v_total + v_take;
    perform "better_supabase".emit_event('allocation.filled', jsonb_build_object('organizationId', v_row.tenant, 'id', v_row.id, 'variantId', v_row.variant, 'locationId', v_row.location,
        'documentType', v_row.document_type, 'documentId', v_row.document_id, 'quantity', v_row.quantity::text, 'allocated', v_take::text), 'stock-allocations/' || v_row.id::text, (v_row.tenant)::text, null, 'better-supabase/inventory');
  end loop;
  if v_total > 0 then
    update "better_supabase"."stock_levels" x set "reserved" = greatest(x."reserved" + v_total, 0), "updated_at" = now()
    where x."variant_id" = fill_backorders.variant and x."location_id" = fill_backorders.location;
  end if;
  return v_total;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.finalize_commission_statement (
  statement_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_tenant uuid;
begin
  select x."tenant_id" into v_tenant from "better_supabase"."commission_statements" x where x."id" = finalize_commission_statement.statement_id;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_tenant is not null and coalesce(better_supabase.can('tenant', v_tenant, 'commissions.read'), false))) then
    raise exception 'no such commission statement' using errcode = 'P0002', hint = 'COMMISSION_STATEMENT_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_tenant is not null and coalesce(better_supabase.can('tenant', v_tenant, 'commissions.manage'), false))) then
    raise exception 'not allowed to finalize commission statements' using errcode = '42501', hint = 'COMMISSION_FORBIDDEN';
  end if;
  return "better_supabase"."commission_statement_finalize"(finalize_commission_statement.statement_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.find_channel (
  tenant uuid,
  name   text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select to_jsonb(x) || jsonb_build_object(
      'archivedAt', c."archived_at",
      'lastMessageAt', c."last_message_at",
      'role', (select k."role" from "better_supabase"."conversation_members" k where k."conversation_id" = c."id" and k."user_id" = auth.uid()),
      'memberCount', (select count(*) from "better_supabase"."conversation_members" k where k."conversation_id" = c."id")
    )
  from "better_supabase"."channels" x
  join "better_supabase"."conversations" c on c."id" = x."id"
  where x."tenant_id" = find_channel.tenant and x."name" = lower(trim(find_channel.name))
$function$;

CREATE OR REPLACE FUNCTION better_supabase.find_e_endpoint_party (
  tenant      uuid,
  scheme      text,
  endpoint_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', find_e_endpoint_party.tenant, 'invoices.read'), false)) then
    raise exception 'not allowed to read this organization''s invoices' using errcode = '42501', hint = 'INVOICE_FORBIDDEN';
  end if;
  return (
    select jsonb_build_object('partyKind', e."party_kind", 'partyId', e."party_id")
    from "better_supabase"."e_invoice_endpoints" e
    where e."tenant_id" = find_e_endpoint_party.tenant
      and e."scheme" = find_e_endpoint_party.scheme
      and lower(e."endpoint_id") = lower(find_e_endpoint_party.endpoint_id)
    order by case e."party_kind" when 'company' then 0 else 1 end, e."created_at"
    limit 1
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.find_person_by_identity (
  tenant  uuid,
  channel text,
  address text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select to_jsonb(p) || jsonb_build_object('roles', p."roles", 'customer_terms_id', p."customer_terms_id", 'supplier_terms_id', p."supplier_terms_id", 'credit_currency', p."credit_currency", 'credit_limit', p."credit_limit"::text, 'credit_block', p."credit_block", 'supplier_status', p."supplier_status", 'language', p."language") from "better_supabase"."person_identities" i
  join "better_supabase"."people" p on p."id" = i."person_id"
  where i."tenant_id" = find_person_by_identity.tenant
    and i."channel" = trim(find_person_by_identity.channel)
    and i."address" = trim(find_person_by_identity.address)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.find_variants_by_identifier (
  tenant uuid,
  value  text,
  type   text DEFAULT NULL::text,
  party  uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('identifierId', x."id", 'variantId', y."id", 'productId', y."product_id", 'sku', y."sku", 'type', x."type", 'value', x."value", 'partyId', x."party_id") order by y."sku", x."type"), '[]'::jsonb)
  from "better_supabase"."product_identifiers" x join "better_supabase"."product_variants" y on y."id" = x."variant_id"
  where x."tenant_id" = $1 and x."value" = btrim($2)
    and ($3 is null or x."type" = $3)
    and ($4 is null or x."party_id" = $4)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.finish_ai_sandbox_stop (
  id      uuid,
  stopped boolean,
  error   text    DEFAULT NULL::text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."ai_sandboxes"%rowtype;
begin
  update "better_supabase"."ai_sandboxes" x set
    "status" = case when finish_ai_sandbox_stop.stopped then 'stopped' else 'running' end,
    "stopped_at" = case when finish_ai_sandbox_stop.stopped then now() else null end,
    "error" = left(finish_ai_sandbox_stop.error, 4000),
    "updated_at" = now()
  where x."id" = finish_ai_sandbox_stop.id and x."status" = 'stopping'
  returning x.* into v_row;
  if not found then
    return false;
  end if;
  if finish_ai_sandbox_stop.stopped and v_row."harness_id" is not null then
    update "better_supabase"."ai_harness_sessions" z set "status" = 'stopped', "updated_at" = now()
    where z."chat_id" = v_row."chat_id" and z."harness_id" = v_row."harness_id"
      and z."status" in ('active', 'idle')
      and not exists (
        select 1 from "better_supabase"."ai_sandboxes" y
        where y."chat_id" = v_row."chat_id" and y."harness_id" = v_row."harness_id" and y."status" <> 'stopped'
      );
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.finish_ai_task_run (
  id        uuid,
  succeeded boolean,
  error     text    DEFAULT NULL::text,
  chat_id   uuid    DEFAULT NULL::uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_task uuid;
begin
  update "better_supabase"."ai_task_runs" y set
    "status" = case when finish_ai_task_run.succeeded then 'completed' else 'failed' end,
    "error" = left(finish_ai_task_run.error, 4000),
    "chat_id" = coalesce(finish_ai_task_run.chat_id, y."chat_id"),
    "finished_at" = now()
  where y."id" = finish_ai_task_run.id and y."status" = 'running'
  returning y."task_id" into v_task;
  if not found then
    return false;
  end if;
  if finish_ai_task_run.chat_id is not null then
    update "better_supabase"."ai_scheduled_tasks" x set "chat_id" = finish_ai_task_run.chat_id where x."id" = v_task and x."chat_id" is null;
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.finish_eval_run (
  run    uuid,
  status text DEFAULT 'completed'::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."eval_runs"%rowtype;
begin
  if finish_eval_run.status not in ('completed', 'failed', 'cancelled') then
    raise exception 'status must be completed, failed or cancelled' using errcode = '22023', hint = 'EVAL_INVALID';
  end if;
  update "better_supabase"."eval_runs" x set "status" = finish_eval_run.status, "summary" = "better_supabase"."eval_run_summary"(finish_eval_run.run), "finished_at" = now()
  where x."id" = finish_eval_run.run and x."status" = 'running'
  returning * into v_row;
  if not found then
    select x.* into v_row from "better_supabase"."eval_runs" x where x."id" = finish_eval_run.run;
    if not found then
      raise exception 'No eval run %', finish_eval_run.run using errcode = 'P0002', hint = 'EVAL_RUN_NOT_FOUND';
    end if;
  end if;
  return jsonb_build_object('id', v_row."id", 'dataset_id', v_row."dataset_id", 'tenant_id', v_row."tenant_id", 'prompt_name', v_row."prompt_name", 'prompt_version', v_row."prompt_version", 'model', v_row."model", 'scorers', v_row."scorers", 'status', v_row."status", 'summary', v_row."summary", 'created_at', v_row."created_at", 'finished_at', v_row."finished_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.finish_import (
  id     uuid,
  status text,
  count  integer,
  error  text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_tenant uuid;
  v_source text;
begin
  update "better_supabase"."import_runs" set "status" = finish_import.status,
    "finished_at" = now(),
    "counts" = case when finish_import.status = 'completed' then jsonb_build_object("source", jsonb_build_object('inserted', finish_import.count, 'updated', 0, 'unchanged', 0, 'conflicted', 0, 'missing', 0)) else "counts" end,
    "errors" = case when finish_import.error is null then "errors" else "errors" || jsonb_build_array(jsonb_build_object('entity', "source", 'key', null, 'code', 'IMPORT_ITEM_INVALID', 'message', finish_import.error)) end
  where "id" = finish_import.id
  returning "tenant_id", "source" into v_tenant, v_source;
  if not found then
    raise exception 'import not found' using errcode = 'P0002', hint = 'IMPORT_NOT_FOUND';
  end if;
  if finish_import.status = 'failed' then
    perform "better_supabase".emit_event('import.failed', jsonb_build_object('organizationId', v_tenant, 'id', finish_import.id, 'error', finish_import.error), 'imports/' || finish_import.id::text, (v_tenant)::text, null, 'better-supabase/imports');
  else
    perform "better_supabase".emit_event('import.completed', jsonb_build_object('organizationId', v_tenant, 'id', finish_import.id, 'count', finish_import.count), 'imports/' || finish_import.id::text, (v_tenant)::text, null, 'better-supabase/imports');
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.finish_import_run (
  run uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_run_id uuid := finish_import_run.run;
  v_run "better_supabase"."import_runs";
  v_entity text;
  v_missing integer;
  v_total integer := 0;
  v_counts jsonb;
  v_outcome text := 'completed';
  v_expected integer;
  v_applied integer;
begin
  select * into v_run from "better_supabase"."import_runs" r where r."id" = v_run_id for update;
  if not found then
    raise exception 'import not found' using errcode = 'P0002', hint = 'IMPORT_NOT_FOUND';
  end if;
  if v_run."status" <> 'running' then
    raise exception 'the import is not running' using errcode = '55000', hint = 'IMPORT_RUN_NOT_RUNNING';
  end if;
  v_counts := v_run."counts";

  if v_run."full" then
    for v_entity in select k.key from jsonb_object_keys(v_run."counts") k(key) loop
      select count(*)::integer into v_missing from "better_supabase"."import_records" x
      where x."tenant_id" = v_run."tenant_id" and x."source" = v_run."source" and x."entity" = v_entity
        and x."role" = 'primary' and x."last_run_id" <> v_run_id
        and x."scope" in (select y."scope" from "better_supabase"."import_records" y where y."tenant_id" = v_run."tenant_id" and y."source" = v_run."source" and y."entity" = v_entity and y."last_run_id" = v_run_id);
      if not v_run."dry_run" then
        update "better_supabase"."import_records" x set "went_missing_at" = coalesce(x."went_missing_at", now())
        where x."tenant_id" = v_run."tenant_id" and x."source" = v_run."source" and x."entity" = v_entity
          and x."last_run_id" <> v_run_id
          and x."scope" in (select y."scope" from "better_supabase"."import_records" y where y."tenant_id" = v_run."tenant_id" and y."source" = v_run."source" and y."entity" = v_entity and y."last_run_id" = v_run_id);
      end if;
      v_counts := jsonb_set(v_counts, array[v_entity, 'missing'], to_jsonb(v_missing));
    end loop;
  end if;

  if v_run."plan" is not null and jsonb_typeof(v_run."plan") = 'object' then
    for v_entity in select k.key from jsonb_object_keys(v_run."plan") k(key) loop
      v_expected := coalesce((v_run."plan" ->> v_entity)::integer, 0);
      v_applied := coalesce((v_counts -> v_entity ->> 'inserted')::integer, 0)
        + coalesce((v_counts -> v_entity ->> 'updated')::integer, 0)
        + coalesce((v_counts -> v_entity ->> 'unchanged')::integer, 0);
      if v_applied < v_expected then
        v_outcome := 'incomplete';
        v_counts := jsonb_set(coalesce(v_counts, '{}'::jsonb), array[v_entity, 'missing'], to_jsonb(v_expected - v_applied), true);
      end if;
    end loop;
  end if;
  if v_outcome = 'completed' and (
    jsonb_array_length(coalesce(v_run."errors", '[]'::jsonb)) > 0
    or exists (
      select 1 from jsonb_each(coalesce(v_counts, '{}'::jsonb)) v_entity_counts(key, value)
      where coalesce((v_entity_counts.value ->> 'conflicted')::integer, 0) > 0
    )
  ) then
    v_outcome := 'completed_with_issues';
  end if;

  update "better_supabase"."import_runs" r set "status" = 'completed', "outcome" = v_outcome, "finished_at" = now(), "counts" = v_counts
  where r."id" = v_run_id;

  if not v_run."dry_run" then
    for v_entity in select k.key from jsonb_object_keys(v_counts) k(key) loop
      v_total := v_total + coalesce((v_counts -> v_entity ->> 'inserted')::integer, 0) + coalesce((v_counts -> v_entity ->> 'updated')::integer, 0);
      perform "better_supabase".emit_event('import.entity_completed', jsonb_build_object('organizationId', v_run."tenant_id", 'id', v_run_id, 'entity', v_entity, 'counts', v_counts -> v_entity), 'imports/' || v_run_id::text, (v_run."tenant_id")::text, null, 'better-supabase/imports');
      if coalesce((v_counts -> v_entity ->> 'inserted')::integer, 0) + coalesce((v_counts -> v_entity ->> 'updated')::integer, 0) > 0 then
        perform better_supabase.audit_event(
    event_type => 'import.entity_completed',
    category => 'integration',
    target_type => 'import',
    record_id => v_run_id::text,
    target_label => v_entity,
    summary => 'imported ' || v_entity,
    tenant => (v_run."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_run."tenant_id", 'id', v_run_id, 'entity', v_entity, 'counts', v_counts -> v_entity),
    idempotency_key => 'import:' || v_run_id::text || ':' || v_entity,
    actor_kind => 'integration',
    correlation_id => 'import:' || v_run_id::text
  );
      end if;
    end loop;
    perform "better_supabase".emit_event('import.completed', jsonb_build_object('organizationId', v_run."tenant_id", 'id', v_run_id, 'count', v_total), 'imports/' || v_run_id::text, (v_run."tenant_id")::text, null, 'better-supabase/imports');
  end if;
  return v_counts;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.finish_production_operation (
  operation_id uuid,
  minutes      numeric DEFAULT NULL::numeric
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."production_order_operations";
  v_order "better_supabase"."production_orders";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."production_order_operations" x where x."id" = finish_production_operation.operation_id for update;
  if not found then
    raise exception 'no such production order operation' using errcode = 'P0002', hint = 'PRODUCTION_OPERATION_NOT_FOUND';
  end if;
  select * into v_order from "better_supabase"."production_orders" x where x."id" = v_row."order_id" for update;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_order."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_order."tenant_id", 'manufacturing.produce'), false))) then
    raise exception 'not allowed to run production operations' using errcode = '42501', hint = 'MANUFACTURING_FORBIDDEN';
  end if;
  if v_row."status" <> 'in_progress' then
    raise exception 'only a started operation finishes' using errcode = '22023', hint = 'PRODUCTION_ORDER_INVALID';
  end if;
  if finish_production_operation.minutes is not null and finish_production_operation.minutes < 0 then
    raise exception 'minutes can''t be negative' using errcode = '22023', hint = 'PRODUCTION_ORDER_INVALID';
  end if;
  update "better_supabase"."production_order_operations" x set "status" = 'done', "finished_at" = now(),
    "minutes" = round(coalesce(finish_production_operation.minutes, extract(epoch from now() - x."started_at") / 60), 2)
  where x."id" = v_row."id";
  return (jsonb_build_object('id', v_order."id", 'organizationId', v_order."tenant_id", 'number', v_order."number", 'variantId', v_order."variant_id", 'bomId', v_order."bom_id", 'quantity', v_order."quantity"::text, 'locationId', v_order."location_id", 'dueOn', v_order."due_on", 'status', v_order."status", 'producedQuantity', v_order."produced_quantity"::text, 'scrapQuantity', v_order."scrap_quantity"::text, 'outputLotId', v_order."output_lot_id", 'materialCost', v_order."material_cost"::text, 'laborCost', v_order."labor_cost"::text, 'currency', v_order."currency", 'note', v_order."note", 'releasedAt', v_order."released_at", 'startedAt', v_order."started_at", 'completedAt', v_order."completed_at", 'canceledAt', v_order."canceled_at", 'createdBy', v_order."created_by", 'createdAt', v_order."created_at", 'updatedAt', v_order."updated_at") || jsonb_build_object(
    'operations', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'orderId', y."order_id", 'operationId', y."operation_id", 'sequence', y."sequence", 'workCenterId', y."work_center_id", 'title', y."title", 'plannedMinutes', y."planned_minutes"::text, 'status', y."status", 'startedAt', y."started_at", 'finishedAt', y."finished_at", 'operatorId', y."operator_id", 'minutes', y."minutes"::text, 'inspectionId', y."inspection_id") order by y."sequence")
      from "better_supabase"."production_order_operations" y where y."order_id" = v_order."id"), '[]'::jsonb),
    'components', coalesce((select jsonb_agg(jsonb_build_object('componentId', y."id", 'variantId', y."variant_id",
        'quantity', "better_supabase"."production_quantity"(y."variant_id", y."quantity" * v_order."quantity" / x."quantity" * (1 + y."scrap_bps" / 10000.0))::text,
        'allocated', coalesce(al."allocated", 0)::text, 'backordered', coalesce(al."backordered", 0)::text,
        'consumed', coalesce((select sum(z."quantity") from "better_supabase"."production_consumptions" z
          where z."order_id" = v_order."id" and z."variant_id" = y."variant_id"), 0)::text)
      order by y."position", y."id")
      from "better_supabase"."boms" x join "better_supabase"."bom_components" y on y."bom_id" = x."id"
      left join "better_supabase"."stock_allocations" al on al."tenant_id" = v_order."tenant_id"
        and al."document_type" = 'production_order' and al."document_id" = v_order."id"::text
        and al."line_id" = y."id"::text and al."status" = 'open'
      where x."id" = v_order."bom_id"), '[]'::jsonb),
    'consumptions', coalesce((select jsonb_agg(jsonb_build_object('id', z."id", 'variantId', z."variant_id", 'lotId', z."lot_id",
        'serial', z."serial", 'quantity', z."quantity"::text, 'cost', z."cost"::text, 'currency', z."currency",
        'movementId', z."movement_id", 'createdAt', z."created_at") order by z."created_at", z."id")
      from "better_supabase"."production_consumptions" z where z."order_id" = v_order."id"), '[]'::jsonb)));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.finish_template_occurrence (
  schedule_id    uuid,
  occurrence_at  timestamp with time zone,
  application_id uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
begin
  update "better_supabase"."template_schedule_runs" y set "application_id" = finish_template_occurrence.application_id
  where y."schedule_id" = finish_template_occurrence.schedule_id
    and y."occurrence_at" = finish_template_occurrence.occurrence_at
    and y."application_id" is null;
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.flag_bucket (
  flag   text,
  target text
)
  RETURNS integer
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select (('x' || substr(encode(extensions.digest(flag || '.' || target, 'sha256'), 'hex'), 1, 8))::bit(32)::bigint % 10000)::integer
$function$;

CREATE OR REPLACE FUNCTION better_supabase.flag_condition_matches (
  condition      jsonb,
  tenant         text,
  member         text,
  role           text,
  plans          text[],
  context_values jsonb
)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select (not condition ? 'tenants' or condition -> 'tenants' ? coalesce(tenant, ''))
    and (not condition ? 'users' or condition -> 'users' ? coalesce(member, ''))
    and (not condition ? 'roles' or condition -> 'roles' ? coalesce(role, ''))
    and (not condition ? 'plans' or condition -> 'plans' ?| coalesce(plans, '{}'))
    and (not condition ? 'contexts' or not exists (
      select 1 from jsonb_each(condition -> 'contexts') c(name, keys)
      where not (c.keys ? coalesce(context_values ->> c.name, ''))
    ))
$function$;

CREATE OR REPLACE FUNCTION better_supabase.flag_definitions()
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'key', x."key",
    'type', x."type",
    'description', x."description",
    'variants', x."variants",
    'default_variant', x."default_variant",
    'enabled', x."enabled",
    'archived', x."archived",
    'rules', x."rules",
    'rollout_percentage', x."rollout_percentage",
    'rollout_variants', x."rollout_variants",
    'rollout_schedule', x."rollout_schedule",
    'segments', case when x."rules" @? '$[*].segments' then (
      select coalesce(jsonb_object_agg(g."name", g."rules"), '{}'::jsonb)
      from "better_supabase"."flag_segments" g
      where g."name" in (select jsonb_array_elements_text(e.value -> 'segments') from jsonb_array_elements(x."rules") e where jsonb_typeof(e.value -> 'segments') = 'array')
    ) else '{}'::jsonb end,
    'created_at', x."created_at",
    'updated_at', x."updated_at",
    'overrides', coalesce((
      select jsonb_agg(jsonb_build_object('organization_id', v."tenant_id", 'user_id', v."user_id", 'context', v."context", 'context_key', v."context_key", 'variant', v."variant")
        order by (v."user_id" is not null) desc, (v."tenant_id" is not null) desc,
          array_position(array[]::text[], v."context") nulls last, v."context")
      from "better_supabase"."flag_overrides" v where v."flag_key" = x."key"
    ), '[]'::jsonb)
  ) order by x."key"), '[]'::jsonb)
  from "better_supabase"."flags" x
$function$;

CREATE OR REPLACE FUNCTION better_supabase.flag_enabled (
  key    text,
  tenant uuid DEFAULT NULL::uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(("better_supabase"."flag_evaluation"(key, tenant) -> 'value') = 'true'::jsonb, false)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.flag_evaluation (
  key      text,
  tenant   uuid  DEFAULT NULL::uuid,
  member   uuid  DEFAULT auth.uid(),
  contexts jsonb DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  flag "better_supabase"."flags";
  chosen text;
  reason text := 'DEFAULT';
  rule jsonb;
  role text;
  tenant_plans text[];
  target text := coalesce(member::text, tenant::text);
  context_values jsonb := case when jsonb_typeof(contexts) = 'object' then contexts else '{}'::jsonb end;
  segment_rules jsonb := '{}'::jsonb;
  conditions jsonb;
begin
  select * into flag from "better_supabase"."flags" x where x."key" = flag_evaluation.key;
  if flag."key" is null then
    return null;
  end if;
  if not flag."enabled" or flag."archived" then
    return jsonb_build_object('value', flag."variants" -> flag."default_variant", 'variant', flag."default_variant", 'reason', 'DISABLED');
  end if;
  if flag."rules" @? '$[*].segments' then
    select coalesce(jsonb_object_agg(g."name", g."rules"), '{}'::jsonb) into segment_rules
    from "better_supabase"."flag_segments" g
    where g."name" in (select jsonb_array_elements_text(e.value -> 'segments') from jsonb_array_elements(flag."rules") e where jsonb_typeof(e.value -> 'segments') = 'array');
  end if;
  -- The rules and the segments they name, for the lookups below.
  conditions := flag."rules" || coalesce((select jsonb_agg(v) from jsonb_each(segment_rules) as e(k, v)), '[]'::jsonb);
  select x."variant" into chosen from "better_supabase"."flag_overrides" x
  where x."flag_key" = flag."key"
    and ((member is not null and x."user_id" = member)
      or (tenant is not null and x."tenant_id" = tenant)
      or (x."context" is not null and x."context_key" = context_values ->> x."context"))
  order by (x."user_id" is not null) desc, (x."tenant_id" is not null) desc,
    array_position(array[]::text[], x."context") nulls last, x."context"
  limit 1;
  if chosen is not null then
    reason := 'TARGETING_MATCH';
  else
    -- The role and plan lookups run only for flags with rules that read them.
    if tenant is not null and conditions @? '$[*].roles' then
      role := better_supabase.organization_member_role(tenant, member);
    end if;
    if tenant is not null and conditions @? '$[*].plans' then
      tenant_plans := better_supabase.tenant_entitlements(tenant);
    end if;
    for rule in select * from jsonb_array_elements(flag."rules") loop
      if "better_supabase"."flag_condition_matches"(rule, tenant::text, member::text, role, tenant_plans, context_values)
        and (not rule ? 'segments' or exists (
          select 1 from jsonb_array_elements_text(case when jsonb_typeof(rule -> 'segments') = 'array' then rule -> 'segments' else '[]'::jsonb end) n(name)
          where segment_rules ? n.name
            and "better_supabase"."flag_condition_matches"(segment_rules -> n.name, tenant::text, member::text, role, tenant_plans, context_values)
        ))
      then
        chosen := rule ->> 'variant';
        reason := 'TARGETING_MATCH';
        exit;
      end if;
    end loop;
  end if;
  if chosen is null and jsonb_array_length(flag."rollout_variants") > 0 and target is not null
    and "better_supabase"."flag_bucket"(flag."key", target) < "better_supabase"."flag_rollout_percentage"(flag."rollout_percentage", flag."rollout_schedule", now()) * 100 then
    -- A second bucket, so growing the rollout never moves a target between
    -- variants.
    select w.split ->> 'variant' into chosen
    from (
      select e.split, e.i, sum(coalesce((e.split ->> 'weight')::numeric, 0) * 100) over (order by e.i) as edge
      from jsonb_array_elements(flag."rollout_variants") with ordinality as e(split, i)
    ) w
    where "better_supabase"."flag_bucket"(flag."key" || '/split', target) < w.edge
    order by w.i
    limit 1;
    reason := 'SPLIT';
  end if;
  if chosen is null or not flag."variants" ? chosen then
    chosen := flag."default_variant";
    reason := 'DEFAULT';
  end if;
  return jsonb_build_object('value', flag."variants" -> chosen, 'variant', chosen, 'reason', reason);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.flag_history (
  key text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (select coalesce(better_supabase.is_platform('flags.manage'), false))) then
    raise exception 'Not allowed to manage feature flags' using errcode = '42501', hint = 'FLAGS_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('revision', h."revision", 'definition', h."definition", 'message', h."message", 'changed_by', h."changed_by", 'changed_at', h."changed_at") order by h."revision" desc)
    from "better_supabase"."flag_revisions" h where h."flag_key" = flag_history.key
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.flag_rollout_percentage (
  percentage numeric,
  schedule   jsonb,
  at         timestamp with time zone DEFAULT now()
)
  RETURNS numeric
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
declare
  start timestamptz;
  elapsed numeric;
  step jsonb;
begin
  if schedule is null or jsonb_typeof(schedule) <> 'object' then
    return percentage;
  end if;
  begin
    start := (schedule ->> 'startAt')::timestamptz;
  exception when others then
    return 0;
  end;
  if start is null or at < start then
    return 0;
  end if;
  elapsed := extract(epoch from at - start);
  for step in select * from jsonb_array_elements(case when jsonb_typeof(schedule -> 'steps') = 'array' then schedule -> 'steps' else '[]'::jsonb end) loop
    if elapsed < coalesce((step ->> 'durationSeconds')::numeric, 0) then
      return coalesce((step ->> 'percentage')::numeric, 0);
    end if;
    elapsed := elapsed - coalesce((step ->> 'durationSeconds')::numeric, 0);
  end loop;
  return coalesce((schedule ->> 'finalPercentage')::numeric, (schedule -> 'steps' -> -1 ->> 'percentage')::numeric, 0);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.follow (
  target_type text,
  target_id   uuid,
  following   boolean DEFAULT true
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_type text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if follow.target_type = 'conversation' then
    select c."tenant_id" into v_tenant from "better_supabase"."conversations" c
    where c."id" = follow.target_id and "better_supabase"."can_conversation"(c."id", 'read');
    v_type := 'conversation';
  elsif follow.target_type = 'thread' then
    select m."tenant_id" into v_tenant from "better_supabase"."messages" m
    where m."id" = follow.target_id and m."thread_id" is null and "better_supabase"."can_conversation"(m."conversation_id", 'read');
    v_type := 'message';
  else
    raise exception 'follow a conversation or a thread' using errcode = '22023', hint = 'MESSAGING_FOLLOW_TARGET';
  end if;
  if v_tenant is null then
    raise exception 'no such conversation or thread you can read' using errcode = 'P0002', hint = 'MESSAGING_NOT_FOUND';
  end if;
  insert into "better_supabase"."notification_subscriptions" ("tenant_id", "user_id", "subject_type", "subject_id", "level")
  values (v_tenant, auth.uid(), v_type, follow.target_id::text, case when follow.following then 'all' else 'ignore' end)
  on conflict ("tenant_id", "user_id", "subject_type", "subject_id") do update set "level" = excluded."level";
  return follow.following;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.forecast_changes (
  from_snapshot uuid,
  to_snapshot   uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_from "better_supabase"."forecast_snapshots";
  v_to "better_supabase"."forecast_snapshots";
begin
  select * into v_from from "better_supabase"."forecast_snapshots" x where x."id" = forecast_changes.from_snapshot;
  select * into v_to from "better_supabase"."forecast_snapshots" x where x."id" = forecast_changes.to_snapshot;
  if v_from."id" is null or v_to."id" is null
    or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_from."tenant_id", 'forecasts.read'), false)) or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_to."tenant_id", 'forecasts.read'), false)) then
    raise exception 'No forecast snapshot you can read has this id' using errcode = 'P0002', hint = 'FORECAST_NOT_FOUND';
  end if;
  if v_from."tenant_id" <> v_to."tenant_id" or v_from."currency" <> v_to."currency" then
    raise exception 'Both snapshots must be of one organization and currency' using errcode = '22023', hint = 'FORECAST_MISMATCH';
  end if;
  return jsonb_build_object(
    'from', jsonb_build_object('id', v_from."id", 'organizationId', v_from."tenant_id", 'pipelineId', v_from."pipeline_id", 'since', v_from."period_start", 'until', v_from."period_end", 'currency', v_from."currency", 'target', v_from."target"::text, 'totals', v_from."totals", 'dealCount', v_from."deal_count", 'takenBy', v_from."taken_by", 'takenAt', v_from."taken_at"),
    'to', jsonb_build_object('id', v_to."id", 'organizationId', v_to."tenant_id", 'pipelineId', v_to."pipeline_id", 'since', v_to."period_start", 'until', v_to."period_end", 'currency', v_to."currency", 'target', v_to."target"::text, 'totals', v_to."totals", 'dealCount', v_to."deal_count", 'takenBy', v_to."taken_by", 'takenAt', v_to."taken_at"),
    'deals', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'dealId', coalesce(b."deal_id", a."deal_id"),
        'name', coalesce(b."name", a."name"),
        'change', case
      when a."deal_id" is null then 'added'
      when b."deal_id" is null then 'removed'
      when a."outcome" = 'open' and b."outcome" = 'won' then 'won'
      when a."outcome" = 'open' and b."outcome" = 'lost' then 'lost'
      else 'changed'
    end,
        'before', case when a."deal_id" is null then null else jsonb_build_object('dealId', a."deal_id", 'name', a."name", 'ownerId', a."owner_id", 'stageId', a."stage_id", 'forecast', a."forecast_category"::text, 'outcome', a."outcome"::text, 'amount', a."amount"::text, 'closeOn', a."expected_close_on", 'closedAt', a."closed_at") end,
        'after', case when b."deal_id" is null then null else jsonb_build_object('dealId', b."deal_id", 'name', b."name", 'ownerId', b."owner_id", 'stageId', b."stage_id", 'forecast', b."forecast_category"::text, 'outcome', b."outcome"::text, 'amount', b."amount"::text, 'closeOn', b."expected_close_on", 'closedAt', b."closed_at") end
      ) order by coalesce(b."amount", a."amount") desc, coalesce(b."deal_id", a."deal_id")), '[]'::jsonb)
      from (select * from "better_supabase"."forecast_snapshot_deals" where "snapshot_id" = v_from."id") a
      full join (select * from "better_supabase"."forecast_snapshot_deals" where "snapshot_id" = v_to."id") b on b."deal_id" = a."deal_id"
      where a."deal_id" is null or b."deal_id" is null
      or a."amount" <> b."amount"
      or a."outcome" <> b."outcome"
      or a."forecast_category" is distinct from b."forecast_category"
      or a."stage_id" is distinct from b."stage_id"
      or a."expected_close_on" is distinct from b."expected_close_on"
      or a."owner_id" is distinct from b."owner_id"
    ));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.forecast_snapshot (
  snapshot uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."forecast_snapshots";
begin
  select * into v_row from "better_supabase"."forecast_snapshots" x where x."id" = forecast_snapshot.snapshot;
  if v_row."id" is null or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'forecasts.read'), false)) then
    raise exception 'No forecast snapshot you can read has this id' using errcode = 'P0002', hint = 'FORECAST_NOT_FOUND';
  end if;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'pipelineId', v_row."pipeline_id", 'since', v_row."period_start", 'until', v_row."period_end", 'currency', v_row."currency", 'target', v_row."target"::text, 'totals', v_row."totals", 'dealCount', v_row."deal_count", 'takenBy', v_row."taken_by", 'takenAt', v_row."taken_at") || jsonb_build_object('deals', (
    select coalesce(jsonb_agg(jsonb_build_object('dealId', y."deal_id", 'name', y."name", 'ownerId', y."owner_id", 'stageId', y."stage_id", 'forecast', y."forecast_category"::text, 'outcome', y."outcome"::text, 'amount', y."amount"::text, 'closeOn', y."expected_close_on", 'closedAt', y."closed_at") order by y."amount" desc, y."deal_id"), '[]'::jsonb)
    from "better_supabase"."forecast_snapshot_deals" y where y."snapshot_id" = v_row."id"
  ));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.forecast_snapshots (
  tenant    uuid,
  pipeline  uuid    DEFAULT NULL::uuid,
  since     date    DEFAULT NULL::date,
  until     date    DEFAULT NULL::date,
  max_count integer DEFAULT NULL::integer
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(z.item order by z.taken_at desc, z.id), '[]'::jsonb)
  from (
    select jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'pipelineId', x."pipeline_id", 'since', x."period_start", 'until', x."period_end", 'currency', x."currency", 'target', x."target"::text, 'totals', x."totals", 'dealCount', x."deal_count", 'takenBy', x."taken_by", 'takenAt', x."taken_at") as item, x."taken_at" as taken_at, x."id" as id
    from "better_supabase"."forecast_snapshots" x
    where x."tenant_id" = forecast_snapshots.tenant
      and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', x."tenant_id", 'forecasts.read'), false))
      and (forecast_snapshots.pipeline is null or x."pipeline_id" = forecast_snapshots.pipeline)
      and (forecast_snapshots.since is null or x."period_start" = forecast_snapshots.since)
      and (forecast_snapshots.until is null or x."period_end" = forecast_snapshots.until)
    order by x."taken_at" desc, x."id"
    limit least(greatest(coalesce(forecast_snapshots.max_count, 50), 1), 200)
  ) z
$function$;

CREATE OR REPLACE FUNCTION better_supabase.forget_data_exports (
  ids uuid[]
)
  RETURNS integer
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  with removed as (
    delete from "better_supabase"."data_exports" x where x."id" = any (forget_data_exports.ids) and x."expires_at" < now() returning 1
  )
  select count(*)::integer from removed
$function$;

CREATE OR REPLACE FUNCTION better_supabase.forget_ssf_received (
  issuer text,
  jti    text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role manages shared signals streams' using errcode = '42501', hint = 'SSF_FORBIDDEN';
  end if;
  delete from "better_supabase"."ssf_received" x where x."issuer" = forget_ssf_received.issuer and x."jti" = forget_ssf_received.jti;
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.fork_template (
  source uuid,
  tenant uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_src "better_supabase"."templates"%rowtype;
  v_version "better_supabase"."template_versions"%rowtype;
  v_row "better_supabase"."templates"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_src from "better_supabase"."templates" x where x."id" = fork_template.source;
  if not found or not (v_src."scope" = 'system' or v_src."tenant_id" = fork_template.tenant or (v_src."scope" = 'brand' and v_src."brand" = "better_supabase"."template_brand"(fork_template.tenant))) then
    raise exception 'No such template' using errcode = 'P0002', hint = 'TEMPLATE_NOT_FOUND';
  end if;
  if fork_template.tenant is null or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (fork_template.tenant is not null and coalesce(better_supabase.can('tenant', fork_template.tenant, 'templates.manage'), false))) then
    raise exception 'You may not create templates here' using errcode = '42501', hint = 'TEMPLATE_FORBIDDEN';
  end if;
  select * into v_version from "better_supabase"."template_versions" y
  where y."template_id" = fork_template.source and y."published_at" is not null
  order by y."version" desc limit 1;
  if not found then
    raise exception 'This template has no published version' using errcode = 'P0002', hint = 'TEMPLATE_NOT_PUBLISHED';
  end if;
  insert into "better_supabase"."templates" ("tenant_id", "scope", "type", "name", "language", "settings", "forked_from", "forked_from_version", "created_by")
  values (fork_template.tenant, 'tenant', v_src."type", v_src."name", v_src."language", v_src."settings", v_src."id", v_version."version", (select auth.uid()))
  returning * into v_row;
  insert into "better_supabase"."template_versions" ("template_id", "version", "body", "hash", "published_at", "created_by")
  values (v_row."id", 1, v_version."body", v_version."hash", now(), (select auth.uid()));
  insert into "better_supabase"."template_workflows" ("template_id", "definition_id", "inputs", "enabled", "created_by")
  select v_row."id", w."definition_id", w."inputs", w."enabled", (select auth.uid())
  from "better_supabase"."template_workflows" w where w."template_id" = v_src."id";

  return jsonb_build_object(
    'id', v_row."id",
    'tenant', v_row."tenant_id",
    'scope', v_row."scope",
    'brand', v_row."brand",
    'key', v_row."key",
    'type', v_row."type",
    'name', v_row."name",
    'language', v_row."language",
    'isDefault', v_row."is_default",
    'settings', v_row."settings",
    'forkedFrom', v_row."forked_from",
    'forkedFromVersion', v_row."forked_from_version",
    'publishedVersion', (select y."version" from "better_supabase"."template_versions" y where y."template_id" = v_row."id" and y."published_at" is not null order by y."version" desc limit 1),
    'upstreamVersion', case when v_row."forked_from" is not null then (select y."version" from "better_supabase"."template_versions" y where y."template_id" = v_row."forked_from" and y."published_at" is not null order by y."version" desc limit 1) end,
    'createdBy', v_row."created_by",
    'createdAt', v_row."created_at",
    'updatedAt', v_row."updated_at"
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.fork_workflow_definition (
  source uuid,
  tenant uuid,
  slug   text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_src "better_supabase"."workflow_definitions"%rowtype;
  v_version "better_supabase"."workflow_versions"%rowtype;
  v_row "better_supabase"."workflow_definitions"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_src from "better_supabase"."workflow_definitions" x where x."id" = source;
  if not found or not (v_src."scope" = 'system' or v_src."tenant_id" is not distinct from tenant) then
    raise exception 'No such workflow' using errcode = 'P0002', hint = 'WORKFLOW_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (tenant is not null and coalesce(better_supabase.can('tenant', tenant, 'workflow_editor.write'), false))) then
    raise exception 'You may not edit workflows here' using errcode = '42501', hint = 'WORKFLOW_FORBIDDEN';
  end if;
  if v_src."scope" = 'tenant' and not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')
      or not coalesce((select z."restricted" from "better_supabase"."workflow_definitions" z where z."id" = source), false)
      or (tenant is not null and coalesce(better_supabase.can('tenant', tenant, 'workflow_editor.manage'), false))
      or exists (
        select 1 from "better_supabase"."workflow_definition_grants" gr
        where gr."definition_id" = source
          and gr."action" in ('edit')
          and ((gr."principal_kind" = 'user' and gr."principal_id" = (select auth.uid())::text)
        or (gr."principal_kind" = 'team' and exists (select 1 from "better_supabase"."team_members" tm where tm."team_id"::text = gr."principal_id" and tm."user_id" = (select auth.uid())))
        or (gr."principal_kind" = 'role' and exists (select 1 from "public"."memberships" mr where mr."organization_id" = tenant and mr."user_id" = (select auth.uid()) and mr."role"::text = gr."principal_id")))
      )) then
    raise exception 'You may not fork this workflow' using errcode = '42501', hint = 'WORKFLOW_FORBIDDEN';
  end if;
  select * into v_version from "better_supabase"."workflow_versions" x where x."definition_id" = source and x."status" = 'published';
  if not found then
    raise exception 'This workflow has no published version' using errcode = 'P0002', hint = 'WORKFLOW_NOT_PUBLISHED';
  end if;
  insert into "better_supabase"."workflow_definitions" ("tenant_id", "slug", "name", "description", "subject_types", "forked_from", "forked_from_version", "created_by")
  values (tenant, slug, v_src."name", v_src."description", v_src."subject_types", v_src."id", v_version."version", (select auth.uid()))
  returning * into v_row;
  insert into "better_supabase"."workflow_versions" ("definition_id", "version", "graph", "input_schema", "created_by")
  values (v_row."id", 1, v_version."graph", v_version."input_schema", (select auth.uid()));
  return jsonb_build_object(
    'id', v_row."id",
    'tenant', v_row."tenant_id",
    'slug', v_row."slug",
    'name', v_row."name",
    'description', v_row."description",
    'subjectTypes', to_jsonb(v_row."subject_types"),
    'scope', v_row."scope",
    'forkedFrom', v_row."forked_from",
    'forkedFromVersion', v_row."forked_from_version",
    'restricted', v_row."restricted",
    'purpose', v_row."purpose",
    'isDefault', v_row."is_default",
    'createdBy', v_row."created_by",
    'createdAt', v_row."created_at",
    'updatedAt', v_row."updated_at"
  ) || jsonb_build_object('draft', true, 'upstreamVersion', v_version."version", 'behind', false);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.form_answer_matches (
  type    text,
  answer  jsonb,
  correct jsonb
)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select case
    when type in ('text', 'textarea', 'email', 'url') then jsonb_typeof(answer) = 'string' and jsonb_typeof(correct) = 'string'
      and lower(btrim(answer #>> '{}', ' ')) = lower(btrim(correct #>> '{}', ' '))
    when type = 'multi' then jsonb_typeof(answer) = 'array' and jsonb_typeof(correct) = 'array'
      and answer @> correct and correct @> answer
    else coalesce(answer = correct, false)
  end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.form_answer_merge (
  definition jsonb,
  answer_key jsonb
)
  RETURNS jsonb
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select case when answer_key is null or answer_key = '{}'::jsonb then definition
  else jsonb_set(definition, '{steps}', coalesce((
    select jsonb_agg(jsonb_set(s.step, '{fields}', (
      select jsonb_agg(case when answer_key ? (f.field ->> 'key') then f.field || jsonb_build_object('correct', answer_key -> (f.field ->> 'key')) else f.field end order by f.ord)
      from jsonb_array_elements(s.step -> 'fields') with ordinality as f(field, ord))) order by s.ord)
    from jsonb_array_elements(definition -> 'steps') with ordinality as s(step, ord)), '[]'::jsonb))
  end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.form_answer_split (
  definition jsonb
)
  RETURNS jsonb
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'definition', jsonb_set(definition, '{steps}', coalesce((
      select jsonb_agg(jsonb_set(s.step, '{fields}', (
        select jsonb_agg(f.field - 'correct' order by f.ord)
        from jsonb_array_elements(s.step -> 'fields') with ordinality as f(field, ord))) order by s.ord)
      from jsonb_array_elements(definition -> 'steps') with ordinality as s(step, ord)), '[]'::jsonb)),
    'key', coalesce((
      select jsonb_object_agg(f.field ->> 'key', f.field -> 'correct')
      from jsonb_array_elements(definition -> 'steps') s(step)
      cross join lateral jsonb_array_elements(s.step -> 'fields') f(field)
      where f.field ? 'correct'), '{}'::jsonb))
$function$;

CREATE OR REPLACE FUNCTION better_supabase.form_condition_holds (
  condition jsonb,
  answers   jsonb
)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select case
    when not answers ? (condition ->> 'field') then false
    when condition ? 'equals' then answers -> (condition ->> 'field') = condition -> 'equals'
    when condition ? 'in' then exists (select 1 from jsonb_array_elements(condition -> 'in') x where x = answers -> (condition ->> 'field'))
    else not (answers -> (condition ->> 'field') in ('null'::jsonb, '""'::jsonb, '[]'::jsonb))
  end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.form_condition_schema (
  condition jsonb
)
  RETURNS jsonb
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'properties', jsonb_build_object(condition ->> 'field',
      case
        when condition ? 'equals' then jsonb_build_object('const', condition -> 'equals')
        when condition ? 'in' then jsonb_build_object('enum', condition -> 'in')
        else '{"not": {"enum": [null, "", []]}}'::jsonb
      end),
    'required', jsonb_build_array(condition ->> 'field'))
$function$;

CREATE OR REPLACE FUNCTION better_supabase.form_correct_fits (
  field jsonb
)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select case field ->> 'type'
    when 'text' then jsonb_typeof(field -> 'correct') = 'string'
    when 'textarea' then jsonb_typeof(field -> 'correct') = 'string'
    when 'email' then jsonb_typeof(field -> 'correct') = 'string'
    when 'url' then jsonb_typeof(field -> 'correct') = 'string'
    when 'date' then jsonb_typeof(field -> 'correct') = 'string'
    when 'number' then jsonb_typeof(field -> 'correct') = 'number'
    when 'integer' then case when jsonb_typeof(field -> 'correct') = 'number'
      then (field ->> 'correct')::numeric = trunc((field ->> 'correct')::numeric) else false end
    when 'bool' then jsonb_typeof(field -> 'correct') = 'boolean'
    when 'option' then jsonb_typeof(field -> 'correct') = 'string'
      and exists (select 1 from jsonb_array_elements(coalesce(field -> 'options', '[]'::jsonb)) o where o -> 'value' = field -> 'correct')
    when 'multi' then jsonb_typeof(field -> 'correct') = 'array'
      and jsonb_array_length(field -> 'correct') > 0
      and not exists (
        select 1 from jsonb_array_elements(field -> 'correct') v
        where jsonb_typeof(v) <> 'string'
          or not exists (select 1 from jsonb_array_elements(coalesce(field -> 'options', '[]'::jsonb)) o where o -> 'value' = v))
    else false
  end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.form_field_schema (
  field jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
declare
  v_type text := field ->> 'type';
  -- required only asks for the key, so an empty answer needs its own floor.
  v_floor jsonb := case when field -> 'required' = 'true'::jsonb then '1'::jsonb end;
  v_values jsonb;
  v_out jsonb;
begin
  select coalesce(jsonb_agg(o.value -> 'value' order by o.ord), '[]'::jsonb) into v_values
    from jsonb_array_elements(coalesce(field -> 'options', '[]'::jsonb)) with ordinality as o(value, ord);
  v_out := case v_type
    when 'text' then jsonb_build_object('type', 'string', 'maxLength', coalesce(field -> 'maxLength', '500'::jsonb))
      || jsonb_strip_nulls(jsonb_build_object('minLength', coalesce(field -> 'minLength', v_floor), 'pattern', field -> 'pattern'))
    when 'textarea' then jsonb_build_object('type', 'string', 'maxLength', coalesce(field -> 'maxLength', '10000'::jsonb))
      || jsonb_strip_nulls(jsonb_build_object('minLength', coalesce(field -> 'minLength', v_floor), 'pattern', field -> 'pattern'))
    when 'email' then jsonb_build_object('type', 'string', 'format', 'email', 'maxLength', 320)
    when 'url' then jsonb_build_object('type', 'string', 'format', 'uri', 'maxLength', 2000)
    when 'number' then jsonb_build_object('type', 'number') || jsonb_strip_nulls(jsonb_build_object('minimum', field -> 'min', 'maximum', field -> 'max'))
    when 'integer' then jsonb_build_object('type', 'integer') || jsonb_strip_nulls(jsonb_build_object('minimum', field -> 'min', 'maximum', field -> 'max'))
    when 'date' then '{"type": "string", "format": "date"}'::jsonb
    when 'bool' then '{"type": "boolean"}'::jsonb
    when 'consent' then '{"type": "boolean", "const": true}'::jsonb
    when 'option' then jsonb_build_object('type', 'string', 'enum', v_values)
    when 'multi' then jsonb_build_object('type', 'array', 'items', jsonb_build_object('type', 'string', 'enum', v_values), 'uniqueItems', true)
      || jsonb_strip_nulls(jsonb_build_object('minItems', coalesce(field -> 'min', v_floor), 'maxItems', field -> 'max'))
    when 'nps' then '{"type": "integer", "minimum": 0, "maximum": 10}'::jsonb
    else '{}'::jsonb
  end;
  return v_out || jsonb_strip_nulls(jsonb_build_object('title', field -> 'label', 'description', field -> 'help'));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.form_nps (
  form_id uuid,
  field   text                     DEFAULT NULL::text,
  since   timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  until   timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  bucket  text                     DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_form "better_supabase"."forms"%rowtype;
  v_field text := form_nps.field;
  v_total jsonb;
  v_periods jsonb;
begin
  select * into v_form from "better_supabase"."forms" x where x."id" = form_nps.form_id;
  if not found then
    raise exception 'form not found' using errcode = 'P0002', hint = 'FORM_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_form."tenant_id", 'forms.review'), false)) then
    raise exception 'not allowed to read this form''s results' using errcode = '42501', hint = 'FORM_FORBIDDEN';
  end if;
  if form_nps.bucket is not null and form_nps.bucket not in ('day', 'week', 'month', 'quarter', 'year') then
    raise exception 'bucket is day, week, month, quarter, year' using errcode = '22023', hint = 'FORM_NPS_BUCKET_INVALID';
  end if;
  if v_field is null then
    select q.field ->> 'key' into v_field
    from "better_supabase"."form_versions" x
    cross join lateral jsonb_array_elements(x."definition" -> 'steps') with ordinality as p(step, step_ord)
    cross join lateral jsonb_array_elements(p.step -> 'fields') with ordinality as q(field, field_ord)
    where x."id" = v_form."current_version_id" and q.field ->> 'type' = 'nps'
    order by p.step_ord, q.field_ord
    limit 1;
    if v_field is null then
      raise exception 'the form has no nps field' using errcode = '22023', hint = 'FORM_NPS_FIELD_MISSING';
    end if;
  end if;
  with answered as (
    select r.answer, r.answered_at from (
      select case when jsonb_typeof(x."answers" -> v_field) = 'number' then (x."answers" ->> v_field)::numeric end as answer,
        x."submitted_at" as answered_at
      from "better_supabase"."form_submissions" x
      where x."form_id" = form_nps.form_id
        and x."status" in ('submitted', 'accepted')
        and (form_nps.since is null or x."submitted_at" >= form_nps.since)
        and (form_nps.until is null or x."submitted_at" < form_nps.until)
    ) r
    where r.answer between 0 and 10
  )
  select jsonb_build_object('responses', count(*), 'promoters', count(*) filter (where a.answer >= 9), 'passives', count(*) filter (where a.answer >= 7 and a.answer < 9), 'detractors', count(*) filter (where a.answer < 7), 'score', case when count(*) = 0 then null else round((count(*) filter (where a.answer >= 9) - count(*) filter (where a.answer < 7)) * 100.0 / count(*), 1) end),
    case when form_nps.bucket is null then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object('start', g.start) || g.counts order by g.start)
      from (
        select date_trunc(form_nps.bucket, b.answered_at, 'UTC') as start, jsonb_build_object('responses', count(*), 'promoters', count(*) filter (where b.answer >= 9), 'passives', count(*) filter (where b.answer >= 7 and b.answer < 9), 'detractors', count(*) filter (where b.answer < 7), 'score', case when count(*) = 0 then null else round((count(*) filter (where b.answer >= 9) - count(*) filter (where b.answer < 7)) * 100.0 / count(*), 1) end) as counts
        from answered b
        group by 1
      ) g), '[]'::jsonb) end
  into v_total, v_periods
  from answered a;
  return jsonb_build_object('field', v_field) || v_total || jsonb_build_object('periods', v_periods);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.form_resolve (
  tenant     uuid,
  definition jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_errors text[];
  v_problem text;
  v_steps jsonb := '[]'::jsonb;
  v_fields jsonb;
  v_step jsonb;
  v_field jsonb;
  v_custom jsonb;
  v_options jsonb;
  v_step_keys text[] := '{}';
  v_keys text[] := '{}';
  v_scored boolean := false;
begin
  v_errors := extensions.jsonschema_validation_errors('{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","required":["steps"],"additionalProperties":false,"properties":{"steps":{"type":"array","minItems":1,"maxItems":50,"items":{"type":"object","required":["key","fields"],"additionalProperties":false,"properties":{"key":{"type":"string","pattern":"^[a-z][a-zA-Z0-9_]{0,62}$"},"title":{"type":"string","maxLength":200},"description":{"type":"string","maxLength":2000},"showIf":{"type":"object","required":["field"],"minProperties":2,"maxProperties":2,"additionalProperties":false,"properties":{"field":{"type":"string","pattern":"^[a-z][a-zA-Z0-9_]{0,62}$"},"equals":{},"in":{"type":"array","minItems":1,"maxItems":500},"filled":{"const":true}}},"fields":{"type":"array","minItems":1,"maxItems":200,"items":{"type":"object","required":["key"],"additionalProperties":false,"properties":{"key":{"type":"string","pattern":"^[a-z][a-zA-Z0-9_]{0,62}$"},"label":{"type":"string","minLength":1,"maxLength":200},"type":{"enum":["text","textarea","email","url","number","integer","date","bool","consent","option","multi","json","nps"]},"required":{"type":"boolean"},"help":{"type":"string","maxLength":1000},"placeholder":{"type":"string","maxLength":200},"options":{"type":"array","minItems":1,"maxItems":500,"items":{"type":"object","required":["value","label"],"additionalProperties":false,"properties":{"value":{"type":"string","minLength":1,"maxLength":200},"label":{"type":"string","minLength":1,"maxLength":200}}}},"min":{"type":"number"},"max":{"type":"number"},"minLength":{"type":"integer","minimum":0},"maxLength":{"type":"integer","minimum":1},"pattern":{"type":"string","maxLength":500},"showIf":{"type":"object","required":["field"],"minProperties":2,"maxProperties":2,"additionalProperties":false,"properties":{"field":{"type":"string","pattern":"^[a-z][a-zA-Z0-9_]{0,62}$"},"equals":{},"in":{"type":"array","minItems":1,"maxItems":500},"filled":{"const":true}}},"customField":{"type":"string","pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$"},"correct":{},"points":{"type":"number","minimum":0,"maximum":10000},"meta":{"type":"object","maxProperties":20}}}}}}},"scoring":{"type":"object","additionalProperties":false,"properties":{"passMark":{"type":"number","minimum":0,"maximum":100}}}}}'::json, definition::json);
  if cardinality(v_errors) > 0 then
    raise exception 'the form definition is invalid: %', array_to_string(v_errors, '; ')
      using errcode = '22023', detail = to_jsonb(v_errors)::text, hint = 'FORM_DEFINITION_INVALID';
  end if;
  <<steps>>
  for v_step in select x from jsonb_array_elements(definition -> 'steps') x loop
    if (v_step ->> 'key') = any (v_step_keys) then
      v_problem := format('step %s is listed twice', v_step ->> 'key');
      exit;
    end if;
    v_step_keys := v_step_keys || (v_step ->> 'key');
    if v_step ? 'showIf' and not ((v_step -> 'showIf' ->> 'field') = any (v_keys)) then
      v_problem := format('step %s: showIf names %s, which isn''t an earlier field', v_step ->> 'key', v_step -> 'showIf' ->> 'field');
      exit;
    end if;
    v_fields := '[]'::jsonb;
    for v_field in select x from jsonb_array_elements(v_step -> 'fields') x loop
      if (v_field ->> 'key') = any (v_keys) then
        v_problem := format('field %s is listed twice', v_field ->> 'key');
        exit steps;
      end if;
      if v_field ? 'showIf' and not ((v_field -> 'showIf' ->> 'field') = any (v_keys)) then
        v_problem := format('field %s: showIf names %s, which isn''t an earlier field', v_field ->> 'key', v_field -> 'showIf' ->> 'field');
        exit steps;
      end if;
      v_keys := v_keys || (v_field ->> 'key');
      v_custom := null;
      if v_field ? 'customField' then
        select jsonb_strip_nulls(jsonb_build_object('label', d."label", 'type', case d."type" when 'multi_option' then 'multi' when 'user' then 'text' when 'rating' then 'integer' when 'currency' then 'integer' when 'bsn' then 'text' when 'iban' then 'text' when 'phone_e164' then 'text' else d."type" end, 'required', d."required"))
            || case when d."type" = 'rating' then jsonb_build_object('min', 1, 'max', 5) else '{}'::jsonb end
          into v_custom
          from "better_supabase"."field_definitions" d
          where d."id" = (v_field ->> 'customField')::uuid and d."tenant_id" = form_resolve.tenant;
        if v_custom is null then
          v_problem := format('field %s: customField %s is not a field definition in this organization', v_field ->> 'key', v_field ->> 'customField');
        exit steps;
        end if;
        if v_custom ->> 'type' in ('option', 'multi') and not v_field ? 'options' and to_regclass('"better_supabase"."field_options"') is not null then
          execute format('select jsonb_agg(jsonb_build_object(''value'', o."value", ''label'', o."label") order by o."value") from %s o where o."definition_id" = $1', to_regclass('"better_supabase"."field_options"'))
            into v_options using (v_field ->> 'customField')::uuid;
          v_custom := v_custom || jsonb_strip_nulls(jsonb_build_object('options', v_options));
        end if;
        v_field := v_custom || v_field;
      end if;
      if not (v_field ? 'label' and v_field ? 'type') then
        v_problem := format('field %s needs a label and a type, or a customField', v_field ->> 'key');
        exit steps;
      end if;
      if (v_field ->> 'type') in ('option', 'multi') and coalesce(jsonb_array_length(v_field -> 'options'), 0) = 0 then
        v_problem := format('field %s needs options', v_field ->> 'key');
        exit steps;
      end if;
      if v_field ? 'pattern' then
        begin
          perform '' ~ (v_field ->> 'pattern');
        exception when invalid_regular_expression then
          v_problem := format('field %s: pattern is not a valid regular expression', v_field ->> 'key');
        end;
        exit steps when v_problem is not null;
      end if;
      if v_field ? 'correct' then
        v_scored := true;
        if v_field -> 'correct' = 'null'::jsonb then
          v_problem := format('field %s: correct can''t be null', v_field ->> 'key');
          exit steps;
        end if;
        if (v_field ->> 'type') in ('consent', 'json', 'nps') then
          v_problem := format('field %s: a %s field can''t have a correct answer', v_field ->> 'key', v_field ->> 'type');
          exit steps;
        end if;
        if not "better_supabase"."form_correct_fits"(v_field) then
          v_problem := format('field %s: correct isn''t an answer the field takes', v_field ->> 'key');
          exit steps;
        end if;
      elsif v_field ? 'points' then
        v_problem := format('field %s: points need a correct answer', v_field ->> 'key');
        exit steps;
      end if;
      v_fields := v_fields || jsonb_build_array(v_field);
    end loop;
    v_steps := v_steps || jsonb_build_array(jsonb_set(v_step, '{fields}', v_fields));
  end loop;
  if v_problem is null and definition ? 'scoring' and not v_scored then
    v_problem := 'scoring needs a field with a correct answer';
  end if;
  if v_problem is not null then
    v_errors := array[v_problem];
    raise exception 'the form definition is invalid: %', array_to_string(v_errors, '; ')
      using errcode = '22023', detail = to_jsonb(v_errors)::text, hint = 'FORM_DEFINITION_INVALID';
  end if;
  return jsonb_build_object('steps', v_steps)
    || case when definition ? 'scoring' then jsonb_build_object('scoring', definition -> 'scoring') else '{}'::jsonb end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.form_schema (
  definition jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
declare
  v_properties jsonb := '{}'::jsonb;
  v_required jsonb := '[]'::jsonb;
  v_conditional jsonb := '[]'::jsonb;
  v_conditions jsonb;
  v_step jsonb;
  v_field jsonb;
begin
  for v_step in select x from jsonb_array_elements(definition -> 'steps') x loop
    for v_field in select x from jsonb_array_elements(v_step -> 'fields') x loop
      v_properties := v_properties || jsonb_build_object(v_field ->> 'key', "better_supabase"."form_field_schema"(v_field));
      continue when coalesce((v_field ->> 'required')::boolean, false) is false;
      v_conditions := '[]'::jsonb;
      if v_step ? 'showIf' then
        v_conditions := v_conditions || jsonb_build_array("better_supabase"."form_condition_schema"(v_step -> 'showIf'));
      end if;
      if v_field ? 'showIf' then
        v_conditions := v_conditions || jsonb_build_array("better_supabase"."form_condition_schema"(v_field -> 'showIf'));
      end if;
      if jsonb_array_length(v_conditions) = 0 then
        v_required := v_required || jsonb_build_array(v_field ->> 'key');
      else
        v_conditional := v_conditional || jsonb_build_array(jsonb_build_object(
          'if', case when jsonb_array_length(v_conditions) = 1 then v_conditions -> 0 else jsonb_build_object('allOf', v_conditions) end,
          'then', jsonb_build_object('required', jsonb_build_array(v_field ->> 'key'))));
      end if;
    end loop;
  end loop;
  return jsonb_build_object('$schema', 'https://json-schema.org/draft/2020-12/schema', 'type', 'object', 'properties', v_properties, 'additionalProperties', false)
    || case when jsonb_array_length(v_required) > 0 then jsonb_build_object('required', v_required) else '{}'::jsonb end
    || case when jsonb_array_length(v_conditional) > 0 then jsonb_build_object('allOf', v_conditional) else '{}'::jsonb end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.form_score (
  definition jsonb,
  answer_key jsonb,
  answers    jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
declare
  v_step jsonb;
  v_field jsonb;
  v_points numeric;
  v_score numeric := 0;
  v_max numeric := 0;
  v_pass numeric := (definition -> 'scoring' ->> 'passMark')::numeric;
begin
  if answer_key is null or answer_key = '{}'::jsonb then
    return null;
  end if;
  for v_step in select x from jsonb_array_elements(definition -> 'steps') x loop
    continue when v_step ? 'showIf' and not "better_supabase"."form_condition_holds"(v_step -> 'showIf', answers);
    for v_field in select x from jsonb_array_elements(v_step -> 'fields') x loop
      continue when not answer_key ? (v_field ->> 'key');
      continue when v_field ? 'showIf' and not "better_supabase"."form_condition_holds"(v_field -> 'showIf', answers);
      v_points := coalesce((v_field ->> 'points')::numeric, 1);
      v_max := v_max + v_points;
      if answers ? (v_field ->> 'key')
        and "better_supabase"."form_answer_matches"(v_field ->> 'type', answers -> (v_field ->> 'key'), answer_key -> (v_field ->> 'key')) then
        v_score := v_score + v_points;
      end if;
    end loop;
  end loop;
  return jsonb_build_object('score', v_score, 'maxScore', v_max,
    'passed', case when v_pass is null then null else v_score * 100 >= v_pass * v_max end);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.form_submission_save (
  form_id       uuid,
  answers       jsonb,
  subject_type  text,
  subject_id    text,
  respondent    uuid,
  source        text,
  draft         boolean,
  submission_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_form "better_supabase"."forms"%rowtype;
  v_schema jsonb;
  v_definition jsonb;
  v_grade jsonb;
  v_errors text[];
  v_row "better_supabase"."form_submissions"%rowtype;
  v_link jsonb;
begin
  select * into v_form from "better_supabase"."forms" x where x."id" = form_submission_save.form_id;
  if not found then
    raise exception 'form not found' using errcode = 'P0002', hint = 'FORM_NOT_FOUND';
  end if;
  if v_form."status" <> 'open' then
    raise exception 'this form isn''t taking submissions' using errcode = '55000', hint = 'FORM_CLOSED';
  end if;
  if jsonb_typeof(form_submission_save.answers) is distinct from 'object' then
    raise exception 'answers must be an object' using errcode = '22023', hint = 'FORM_ANSWERS_INVALID';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_form_submission"(uuid, jsonb)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::jsonb)', v_hook::oid::regproc)
        using form_submission_save.form_id, form_submission_save.answers;
    end if;
  end;
  if not form_submission_save.draft then
    select x."schema", x."definition" into v_schema, v_definition from "better_supabase"."form_versions" x where x."id" = v_form."current_version_id";
    v_errors := extensions.jsonschema_validation_errors(v_schema::json, form_submission_save.answers::json);
    if cardinality(v_errors) > 0 then
      raise exception '%.answers does not match its JSON Schema: %', 'form_submissions', array_to_string(v_errors, '; ')
      using errcode = '23514', column = 'answers', detail = to_jsonb(v_errors)::text, hint = 'JSON_SCHEMA_INVALID';
    end if;
    v_grade := "better_supabase"."form_score"(v_definition, (select a."answers" from "better_supabase"."form_answer_keys" a where a."version_id" = v_form."current_version_id"), form_submission_save.answers);
  end if;
  if form_submission_save.submission_id is not null then
    select * into v_row from "better_supabase"."form_submissions" x where x."id" = form_submission_save.submission_id for update;
    if not found or v_row."form_id" <> form_submission_save.form_id or v_row."respondent_id" is distinct from form_submission_save.respondent then
      raise exception 'submission not found' using errcode = 'P0002', hint = 'FORM_SUBMISSION_NOT_FOUND';
    end if;
    if v_row."status" <> 'draft' then
      raise exception 'only a draft submission can change' using errcode = '55000', hint = 'FORM_SUBMISSION_LOCKED';
    end if;
    update "better_supabase"."form_submissions" x set
      "version_id" = v_form."current_version_id",
      "answers" = form_submission_save.answers,
      "status" = case when form_submission_save.draft then 'draft' else 'submitted' end,
      "submitted_at" = case when form_submission_save.draft then null else now() end,
      "subject_type" = coalesce(form_submission_save.subject_type, x."subject_type"),
      "subject_id" = coalesce(form_submission_save.subject_id, x."subject_id"),
      "score" = (v_grade ->> 'score')::numeric,
      "max_score" = (v_grade ->> 'maxScore')::numeric,
      "passed" = (v_grade ->> 'passed')::boolean,
      "updated_at" = now()
    where x."id" = form_submission_save.submission_id
    returning * into v_row;
  else
    insert into "better_supabase"."form_submissions" ("tenant_id", "form_id", "version_id", "subject_type", "subject_id", "respondent_id", "answers", "status", "source", "submitted_at", "score", "max_score", "passed")
    values (v_form."tenant_id", v_form."id", v_form."current_version_id", form_submission_save.subject_type, form_submission_save.subject_id, form_submission_save.respondent, form_submission_save.answers,
      case when form_submission_save.draft then 'draft' else 'submitted' end, form_submission_save.source,
      case when form_submission_save.draft then null else now() end, (v_grade ->> 'score')::numeric, (v_grade ->> 'maxScore')::numeric, (v_grade ->> 'passed')::boolean)
    returning * into v_row;
  end if;
  if not form_submission_save.draft then
    perform "better_supabase".emit_event('form_submission.submitted', jsonb_build_object('organizationId', v_row."tenant_id", 'subjectType', coalesce(v_row."subject_type", 'form'), 'subjectId', coalesce(v_row."subject_id", v_row."form_id"::text), 'id', v_row."id", 'formId', v_row."form_id", 'versionId', v_row."version_id", 'source', v_row."source", 'score', v_row."score", 'maxScore', v_row."max_score", 'passed', v_row."passed"), 'form-submissions/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/forms');
    declare
    v_hook regprocedure := to_regprocedure('"public"."after_form_submission"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  end if;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'formId', v_row."form_id", 'versionId', v_row."version_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'respondentId', v_row."respondent_id", 'answers', v_row."answers", 'status', v_row."status", 'source', v_row."source", 'reviewedBy', v_row."reviewed_by", 'reviewedAt', v_row."reviewed_at", 'createdAt', v_row."created_at", 'submittedAt', v_row."submitted_at", 'updatedAt', v_row."updated_at", 'score', v_row."score", 'maxScore', v_row."max_score", 'passed', v_row."passed");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.format_assigned_number (
  template text,
  n        bigint,
  at       timestamp with time zone
)
  RETURNS text
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
declare
  v text := template;
  width text[];
begin
  v := replace(v, '{yyyy}', to_char(at at time zone 'utc', 'YYYY'));
  v := replace(v, '{yy}', to_char(at at time zone 'utc', 'YY'));
  v := replace(v, '{mm}', to_char(at at time zone 'utc', 'MM'));
  v := replace(v, '{dd}', to_char(at at time zone 'utc', 'DD'));
  while v ~ '\{n:[0-9]+\}' loop
    width := regexp_match(v, '\{n:([0-9]+)\}');
    v := regexp_replace(v, '\{n:[0-9]+\}', lpad(n::text, width[1]::int, '0'));
  end loop;
  return replace(v, '{n}', n::text);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.freeze_document (
  tenant        uuid,
  document_type text,
  document_id   uuid,
  language      text DEFAULT NULL::text,
  template_name text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', freeze_document.tenant, 'document_templates.manage'), false)) then
    raise exception 'not allowed to manage document templates' using errcode = '42501', hint = 'DOCUMENT_TEMPLATE_FORBIDDEN';
  end if;
  if freeze_document.document_type is null or freeze_document.document_type not in ('invoice', 'credit_note', 'quote', 'order', 'dunning_letter', 'delivery_note', 'statement', 'purchase_order') then
    raise exception 'the document type is invoice, credit_note, quote, order, dunning_letter, delivery_note, statement, purchase_order' using errcode = '22023', hint = 'DOCUMENT_TYPE_INVALID';
  end if;
  return "better_supabase"."document_freeze"(freeze_document.tenant, freeze_document.document_type, freeze_document.document_id, freeze_document.language, freeze_document.template_name);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.freeze_issued_invoice()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if better_supabase.import_run() is not null then
    return null;
  end if;
  begin
    perform "better_supabase"."document_freeze"(new."tenant_id", case when new."kind" = 'credit_note' then 'credit_note' else 'invoice' end, new."id", null, null);
  exception when others then
    raise warning 'the document snapshot of invoice % was skipped: %', new."id", sqlerrm;
  end;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.fulfil_data_subject_request (
  id         uuid,
  resolution text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."data_subject_requests";
  v_export jsonb;
  v_export_id uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."data_subject_requests" x where x."id" = fulfil_data_subject_request.id for update;
  if v_row."id" is null then
    raise exception 'request not found' using errcode = 'P0002', hint = 'DSAR_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'data_lifecycle.export'), false)) then
    raise exception 'You may not handle data subject requests here' using errcode = '42501', hint = 'DSAR_FORBIDDEN';
  end if;
  if v_row."closed_at" is not null then
    raise exception 'the request is already fulfilled or refused' using errcode = '55000', hint = 'DSAR_CLOSED';
  end if;
  if v_row."verified_at" is null then
    raise exception 'verify the requester''s identity first' using errcode = '55000', hint = 'DSAR_UNVERIFIED';
  end if;
  if v_row."kind" in ('access', 'portability') then
    if v_row."subject_type" is null then
      raise exception 'an access or portability request names the record to export' using errcode = '22023', hint = 'DSAR_INVALID';
    end if;
    v_export := "better_supabase"."request_subject_export"(v_row."subject_type", v_row."subject_id", 'ndjson');
    v_export_id := (v_export ->> 'id')::uuid;
  else
    if fulfil_data_subject_request.resolution is null or length(trim(fulfil_data_subject_request.resolution)) = 0 then
      raise exception 'resolution is required' using errcode = '22023', hint = 'DSAR_INVALID';
    end if;
    if v_row."kind" = 'erasure' and "better_supabase"."is_held"('data_subject_request', v_row."tenant_id"::text) then
      raise exception 'a legal hold stops the erasure; refuse the request with its reason' using errcode = '55000', hint = 'DSAR_HELD';
    end if;
  end if;
  update "better_supabase"."data_subject_requests" x set "status" = 'fulfilled', "closed_at" = now(), "closed_by" = auth.uid(), "export_id" = v_export_id, "resolution" = nullif(trim(fulfil_data_subject_request.resolution), '')
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('data_subject_request.fulfilled', jsonb_build_object('requestId', v_row."id", 'organizationId', v_row."tenant_id"::text, 'kind', v_row."kind"::text, 'status', v_row."status"::text, 'dueAt', v_row."due_at"), 'data-subject-requests/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/data-lifecycle');
  perform better_supabase.audit_event(
    event_type => 'data_subject_request.fulfilled',
    category => 'data',
    target_type => 'data_subject_request',
    record_id => v_row."id"::text,
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('requestId', v_row."id", 'organizationId', v_row."tenant_id"::text, 'kind', v_row."kind"::text, 'status', v_row."status"::text, 'dueAt', v_row."due_at")
  );
  return to_jsonb(v_row);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.fulfill_allocation (
  allocation uuid,
  quantity   numeric,
  detail     jsonb   DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row record;
begin
  select x."id" as id, x."tenant_id" as tenant, x."variant_id" as variant, x."location_id" as location,
    x."document_type" as document_type, x."document_id" as document_id, x."quantity" as quantity,
    x."allocated" as allocated, x."fulfilled" as fulfilled, x."status" as status
  into v_row from "better_supabase"."stock_allocations" x where x."id" = fulfill_allocation.allocation for update;
  if not found then
    raise exception 'allocation not found' using errcode = 'P0002', hint = 'INVENTORY_ALLOCATION_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_row.tenant, 'inventory.reserve'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  return "better_supabase"."take_allocation"(fulfill_allocation.allocation, fulfill_allocation.quantity, 'sale', fulfill_allocation.detail);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.function_writes (
  target regclass
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  execute format('revoke insert, update, delete, truncate on %s from public, anon, authenticated', target);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.funding_award_usage (
  award_id uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'awardId', a."id",
    'units', a."units",
    'period', a."period",
    'periods', coalesce((
      select jsonb_agg(jsonb_build_object(
        'start', s.start,
        'end', nullif(s.finish, 'infinity'::date) - 1,
        'awarded', a."units",
        'used', s.used,
        'over', greatest(s.used - a."units", 0),
        'under', greatest(a."units" - s.used, 0)
      ) order by s.start)
      from (
        select g.start, (case a."period" when 'week' then (g.start + 7) when 'month' then (g.start + interval '1 month')::date else coalesce(a."ends_on" + 1, 'infinity'::date) end) as finish, (
          select coalesce(sum(x."units"), 0) from "better_supabase"."funding_deliveries" x
          where x."tenant_id" = a."tenant_id" and x."award_id" = a."id" and x."status" <> 'rejected'
            and x."delivered_on" >= g.start and x."delivered_on" < (case a."period" when 'week' then (g.start + 7) when 'month' then (g.start + interval '1 month')::date else coalesce(a."ends_on" + 1, 'infinity'::date) end)
        ) as used
        from (
          select pg_catalog.generate_series(
            (case a."period" when 'week' then date_trunc('week', a."starts_on")::date when 'month' then date_trunc('month', a."starts_on")::date else a."starts_on" end)::timestamp,
            coalesce(a."ends_on", current_date)::timestamp,
            case a."period" when 'week' then interval '1 week' else interval '1 month' end
          )::date as start
          where a."period" <> 'total'
          union all
          select a."starts_on" where a."period" = 'total'
        ) g
      ) s
    ), '[]'::jsonb)
  )
  from "better_supabase"."funding_awards" a
  where a."id" = funding_award_usage.award_id
$function$;

CREATE OR REPLACE FUNCTION better_supabase.funding_subject_merge (
  subject_table text,
  keep          text,
  drop          text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_type text;
  v_keep text := keep;
  v_drop text := drop;
begin
  for v_type in select unnest(case subject_table when 'better_supabase.messages' then array['message'] when 'better_supabase.conversations' then array['conversation'] when 'better_supabase.channels' then array['channel'] when 'better_supabase.companies' then array['company'] when 'better_supabase.people' then array['person'] when 'better_supabase.deals' then array['deal'] when 'better_supabase.courses' then array['course'] when 'better_supabase.posts' then array['post'] when 'better_supabase.activities' then array['activity'] when 'better_supabase.quotes' then array['quote'] when 'better_supabase.work_items' then array['work_item'] when 'better_supabase.employees' then array['employee'] when 'better_supabase.ledger_accounts' then array['ledger_account'] when 'better_supabase.invoices' then array['invoice'] when 'better_supabase.products' then array['product'] when 'better_supabase.product_variants' then array['product_variant'] when 'better_supabase.rfqs' then array['rfq'] when 'better_supabase.tills' then array['till'] when 'better_supabase.orders' then array['order'] when 'better_supabase.calendar_events' then array['calendar_event'] when 'better_supabase.bookings' then array['booking'] when 'better_supabase.assets' then array['asset'] when 'better_supabase.asset_locations' then array['asset_location'] when 'better_supabase.leases' then array['lease'] when 'better_supabase.expense_reports' then array['expense_report'] when 'better_supabase.expense_lines' then array['expense_line'] when 'better_supabase.donation_funds' then array['donation_fund'] when 'better_supabase.warranty_claims' then array['warranty_claim'] when 'better_supabase.work_orders' then array['work_order'] when 'better_supabase.shipments' then array['shipment'] when 'better_supabase.contracts' then array['contract'] when 'better_supabase.controls' then array['control'] when 'better_supabase.compliance_policies' then array['compliance_policy'] when 'better_supabase.qualification_types' then array['qualification_type'] when 'better_supabase.risks' then array['risk'] when 'better_supabase.cases' then array['case'] when 'better_supabase.inspections' then array['inspection'] when 'better_supabase.inspection_programs' then array['inspection_program'] when 'better_supabase.inspection_findings' then array['inspection_finding'] when 'better_supabase.forms' then array['form'] when 'better_supabase.meetings' then array['meeting'] when 'better_supabase.meeting_decisions' then array['meeting_decision'] when 'better_supabase.maintenance_plans' then array['maintenance_plan'] when 'better_supabase.dam_usage_rights' then array['dam_usage_right'] when 'better_supabase.lims_samples' then array['lims_sample'] when 'better_supabase.tax_codes' then array['tax_code'] when 'better_supabase.production_orders' then array['production_order'] when 'better_supabase.work_centers' then array['work_center'] when 'better_supabase.bank_accounts' then array['bank_account'] when 'better_supabase.care_plans' then array['care_plan'] when 'better_supabase.incidents' then array['incident'] when 'better_supabase.content_entries' then array['content_entry'] when 'better_supabase.documents' then array['document'] when 'public.customers' then array['customer'] when 'better_supabase.drive_nodes' then array['drive_node'] when 'public.organizations' then array['organization'] when 'better_supabase.applications' then array['application'] when 'public.change_requests' then array['change_request'] when 'public.projects' then array['project'] when 'public.tasks' then array['task'] else '{}'::text[] end) loop
    update "better_supabase"."funding_awards" x set "subject_id" = v_keep where x."subject_type" = v_type and x."subject_id" = v_drop;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.generate_maintenance_work_orders (
  tenant uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_plan "better_supabase"."maintenance_plans";
  v_view jsonb;
  v_order jsonb;
  v_part record;
  v_made jsonb := '[]'::jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (generate_maintenance_work_orders.tenant is not null and coalesce(better_supabase.can('tenant', generate_maintenance_work_orders.tenant, 'maintenance.manage'), false))) then
    raise exception 'not allowed to manage maintenance plans' using errcode = '42501', hint = 'MAINTENANCE_FORBIDDEN';
  end if;
  for v_plan in
    select * from "better_supabase"."maintenance_plans" x
    where x."tenant_id" = generate_maintenance_work_orders.tenant and x."status" = 'active' and x."work_order_id" is null
    order by x."next_due_at" nulls last, x."id"
    for update
  loop
    v_view := jsonb_build_object('id', v_plan."id", 'organizationId', v_plan."tenant_id", 'title', v_plan."title", 'kind', v_plan."kind", 'assetId', v_plan."asset_id", 'everyDays', v_plan."every_days", 'meterId', v_plan."meter_id", 'everyValue', v_plan."every_value"::text, 'priority', v_plan."priority", 'status', v_plan."status", 'lastDoneAt', v_plan."last_done_at", 'lastDoneValue', v_plan."last_done_value"::text, 'nextDueAt', v_plan."next_due_at", 'workOrderId', v_plan."work_order_id", 'rrule', v_plan."rrule", 'dtstart', v_plan."dtstart", 'tz', v_plan."tz", 'requiredQualifications', to_jsonb(v_plan."required_qualifications"), 'createdAt', v_plan."created_at", 'updatedAt', v_plan."updated_at") || jsonb_build_object(
    'due', v_plan."status" = 'active' and v_plan."work_order_id" is null and (
      (v_plan."kind" in ('time', 'rrule') and v_plan."next_due_at" <= now())
      or (v_plan."kind" = 'meter' and exists (
        select 1 from "better_supabase"."maintenance_meters" z
        where z."id" = v_plan."meter_id" and z."reading" >= coalesce(v_plan."last_done_value", 0) + v_plan."every_value"
      ))
    ),
    'parts', coalesce((
      select jsonb_agg(jsonb_build_object('id', y."id", 'name', y."name", 'quantity', y."quantity"::text, 'variantId', y."variant_id") order by y."name", y."id")
      from "better_supabase"."maintenance_plan_parts" y where y."plan_id" = v_plan."id"
    ), '[]'::jsonb));
    continue when not (v_view ->> 'due')::boolean;
    v_order := "better_supabase"."create_work_order"(
      tenant => v_plan."tenant_id",
      title => v_plan."title",
      priority => v_plan."priority",
      asset_id => v_plan."asset_id");
    for v_part in
      select y."name" as name, y."quantity" as quantity, y."variant_id" as variant
      from "better_supabase"."maintenance_plan_parts" y where y."plan_id" = v_plan."id" order by y."name", y."id"
    loop
      perform "better_supabase"."record_work_order_part"(
        work_order_id => (v_order ->> 'id')::uuid,
        name => v_part.name,
        quantity => v_part.quantity,
        asset_id => v_plan."asset_id",
        variant_id => v_part.variant);
    end loop;
    update "better_supabase"."maintenance_plans" x set "work_order_id" = (v_order ->> 'id')::uuid, "updated_at" = now()
    where x."id" = v_plan."id"
    returning * into v_plan;
    perform "better_supabase".emit_event('maintenance_plan.triggered', jsonb_build_object('organizationId', v_plan."tenant_id", 'id', v_plan."id", 'title', v_plan."title", 'kind', v_plan."kind", 'status', v_plan."status", 'workOrderId', v_plan."work_order_id"), 'maintenance-plans/' || v_plan."id"::text, (v_plan."tenant_id")::text, null, 'better-supabase/maintenance');
  perform better_supabase.audit_event(
    event_type => 'maintenance_plan.triggered',
    category => 'data',
    target_type => 'maintenance_plan',
    record_id => v_plan."id"::text,
    target_label => v_plan."title",
    summary => 'maintenance work order opened',
    tenant => (v_plan."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_plan."tenant_id", 'id', v_plan."id", 'title', v_plan."title", 'kind', v_plan."kind", 'status', v_plan."status", 'workOrderId', v_plan."work_order_id")
  );
    v_made := v_made || jsonb_build_array(jsonb_build_object('planId', v_plan."id", 'workOrderId', v_plan."work_order_id"));
  end loop;
  return v_made;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.generate_shifts (
  tenant      uuid,
  template_id uuid,
  from_date   date,
  until_date  date
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_template "better_supabase"."shift_templates"%rowtype;
  v_row "better_supabase"."shifts"%rowtype;
  v_day date;
  v_starts timestamptz;
  v_ends timestamptz;
  v_created jsonb := '[]'::jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', generate_shifts.tenant, 'shifts.write'), false)) then
    raise exception 'not allowed to plan shifts' using errcode = '42501', hint = 'SHIFT_FORBIDDEN';
  end if;
  select * into v_template from "better_supabase"."shift_templates" x
  where x."id" = generate_shifts.template_id and x."tenant_id" = generate_shifts.tenant and x."archived_at" is null;
  if not found then
    raise exception 'shift template not found' using errcode = 'P0002', hint = 'SHIFT_TEMPLATE_NOT_FOUND';
  end if;
  if generate_shifts.from_date is null or generate_shifts.until_date is null or generate_shifts.until_date < generate_shifts.from_date then
    raise exception 'until_date is on or after from_date' using errcode = '22023', hint = 'SHIFT_INVALID';
  end if;
  if generate_shifts.until_date - generate_shifts.from_date >= 92 then
    raise exception 'generate_shifts covers at most 92 days' using errcode = '22023', hint = 'SHIFT_INVALID';
  end if;
  for v_day in select d::date from generate_series(generate_shifts.from_date::timestamp, generate_shifts.until_date::timestamp, interval '1 day') d loop
    continue when not (extract(isodow from v_day)::integer = any(v_template."weekdays"));
    v_starts := (v_day + v_template."starts_time") at time zone 'UTC';
    v_ends := (v_day + v_template."ends_time" + case when v_template."ends_time" <= v_template."starts_time" then interval '1 day' else interval '0' end) at time zone 'UTC';
    continue when exists (
      select 1 from "better_supabase"."shifts" x
      where x."tenant_id" = v_template."tenant_id" and x."template_id" = v_template."id" and x."starts_at" = v_starts
    );
    insert into "better_supabase"."shifts" ("tenant_id", "template_id", "team_id", "location_id", "starts_at", "ends_at", "break_minutes", "headcount", "required_qualifications", "created_by")
    values (v_template."tenant_id", v_template."id", v_template."team_id", v_template."location_id", v_starts, v_ends, v_template."break_minutes", v_template."headcount", v_template."required_qualifications", (select auth.uid()))
    returning * into v_row;
    perform "better_supabase".emit_event('shift.created', jsonb_build_object('organizationId', v_row."tenant_id", 'shiftId', v_row."id", 'teamId', v_row."team_id", 'startsAt', v_row."starts_at", 'endsAt', v_row."ends_at", 'status', v_row."status"), 'shifts/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/shifts');
  perform better_supabase.audit_event(
    event_type => 'shift.created',
    category => 'data',
    target_type => 'shift',
    record_id => v_row."id"::text,
    summary => 'Shift created',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'shiftId', v_row."id", 'teamId', v_row."team_id", 'startsAt', v_row."starts_at", 'endsAt', v_row."ends_at", 'status', v_row."status")
  );
    v_created := v_created || jsonb_build_array(jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'templateId', v_row."template_id", 'teamId', v_row."team_id", 'locationId', v_row."location_id", 'startsAt', v_row."starts_at", 'endsAt', v_row."ends_at", 'breakMinutes', v_row."break_minutes", 'headcount', v_row."headcount", 'requiredQualifications', to_jsonb(v_row."required_qualifications"), 'status', v_row."status", 'note', v_row."note", 'publishedAt', v_row."published_at", 'canceledAt', v_row."canceled_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at"));
  end loop;
  return v_created;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.get_access_request (
  request_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  SET "IntervalStyle" TO 'iso_8601'
  AS $function$
declare
  v_row "better_supabase"."access_requests"%rowtype;
  v_approval "better_supabase"."approval_requests"%rowtype;
begin
  select * into v_row from "better_supabase"."access_requests" r where r."id" = get_access_request.request_id;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(v_row."user_id" = auth.uid(), false) or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'access_requests.read'), false)) then
    raise exception 'access request not found' using errcode = 'P0002', hint = 'ACCESS_REQUEST_NOT_FOUND';
  end if;
  select * into v_approval from "better_supabase"."approval_requests" x where x."id" = v_row."approval_id";
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'userId', v_row."user_id", 'role', v_row."role", 'target', v_row."target", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'action', v_row."action", 'emergency', v_row."emergency", 'review', case when v_row."reviewed_at" is null then null else jsonb_build_object('verdict', v_row."review_verdict", 'note', v_row."review_note", 'reviewedBy', v_row."reviewed_by", 'reviewedAt', v_row."reviewed_at") end, 'previousRole', v_row."previous_role", 'reason', v_row."reason", 'duration', v_row."duration"::text, 'status', case when v_row."ended_at" is not null then 'ended' when v_row."granted_at" is not null then 'granted' else coalesce(v_approval."status", 'pending') end, 'approvalId', v_row."approval_id", 'grantedAt', v_row."granted_at", 'expiresAt', v_row."expires_at", 'endedAt', v_row."ended_at", 'createdAt', v_row."created_at");
end;
$function$;

