CREATE OR REPLACE FUNCTION better_supabase.get_production_order (
  order_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."production_orders";
begin
  select * into v_row from "better_supabase"."production_orders" x where x."id" = get_production_order.order_id;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'manufacturing.read'), false))) then
    raise exception 'no such production order' using errcode = 'P0002', hint = 'PRODUCTION_ORDER_NOT_FOUND';
  end if;
  return (jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'number', v_row."number", 'variantId', v_row."variant_id", 'bomId', v_row."bom_id", 'quantity', v_row."quantity"::text, 'locationId', v_row."location_id", 'dueOn', v_row."due_on", 'status', v_row."status", 'producedQuantity', v_row."produced_quantity"::text, 'scrapQuantity', v_row."scrap_quantity"::text, 'outputLotId', v_row."output_lot_id", 'materialCost', v_row."material_cost"::text, 'laborCost', v_row."labor_cost"::text, 'currency', v_row."currency", 'note', v_row."note", 'releasedAt', v_row."released_at", 'startedAt', v_row."started_at", 'completedAt', v_row."completed_at", 'canceledAt', v_row."canceled_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at") || jsonb_build_object(
    'operations', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'orderId', y."order_id", 'operationId', y."operation_id", 'sequence', y."sequence", 'workCenterId', y."work_center_id", 'title', y."title", 'plannedMinutes', y."planned_minutes"::text, 'status', y."status", 'startedAt', y."started_at", 'finishedAt', y."finished_at", 'operatorId', y."operator_id", 'minutes', y."minutes"::text, 'inspectionId', y."inspection_id") order by y."sequence")
      from "better_supabase"."production_order_operations" y where y."order_id" = v_row."id"), '[]'::jsonb),
    'components', coalesce((select jsonb_agg(jsonb_build_object('componentId', y."id", 'variantId', y."variant_id",
        'quantity', "better_supabase"."production_quantity"(y."variant_id", y."quantity" * v_row."quantity" / x."quantity" * (1 + y."scrap_bps" / 10000.0))::text,
        'allocated', coalesce(al."allocated", 0)::text, 'backordered', coalesce(al."backordered", 0)::text,
        'consumed', coalesce((select sum(z."quantity") from "better_supabase"."production_consumptions" z
          where z."order_id" = v_row."id" and z."variant_id" = y."variant_id"), 0)::text)
      order by y."position", y."id")
      from "better_supabase"."boms" x join "better_supabase"."bom_components" y on y."bom_id" = x."id"
      left join "better_supabase"."stock_allocations" al on al."tenant_id" = v_row."tenant_id"
        and al."document_type" = 'production_order' and al."document_id" = v_row."id"::text
        and al."line_id" = y."id"::text and al."status" = 'open'
      where x."id" = v_row."bom_id"), '[]'::jsonb),
    'consumptions', coalesce((select jsonb_agg(jsonb_build_object('id', z."id", 'variantId', z."variant_id", 'lotId', z."lot_id",
        'serial', z."serial", 'quantity', z."quantity"::text, 'cost', z."cost"::text, 'currency', z."currency",
        'movementId', z."movement_id", 'createdAt', z."created_at") order by z."created_at", z."id")
      from "better_supabase"."production_consumptions" z where z."order_id" = v_row."id"), '[]'::jsonb)));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.get_prompt (
  name    text,
  label   text    DEFAULT 'production'::text,
  version integer DEFAULT NULL::integer,
  tenant  uuid    DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."prompt_versions"%rowtype;
begin
  select x.* into v_row from "better_supabase"."prompt_versions" x
  where x."name" = get_prompt.name
    and (x."tenant_id" is null or x."tenant_id" = get_prompt.tenant)
    and (
      (get_prompt.version is not null and x."version" = get_prompt.version)
      or (get_prompt.version is null and exists (
        select 1 from "better_supabase"."prompt_labels" y
        where coalesce(y."tenant_id"::text, '') = coalesce(x."tenant_id"::text, '')
          and y."name" = x."name"
          and y."label" = get_prompt.label
          and y."version" = x."version"
      ))
    )
  order by (x."tenant_id" is null), x."version" desc
  limit 1;
  if not found then
    return null;
  end if;
  return jsonb_build_object('id', v_row."id", 'tenant_id', v_row."tenant_id", 'name', v_row."name", 'version', v_row."version", 'template', v_row."template", 'variables', v_row."variables", 'created_at', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.get_public_form (
  token text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_form_id uuid;
  v_row "better_supabase"."forms"%rowtype;
  v_version "better_supabase"."form_versions"%rowtype;
begin
  select x."id" into v_form_id
  from "better_supabase"."share_links" k
  join "better_supabase"."forms" x on x."id"::text = k."subject_id" and x."tenant_id" = k."tenant_id"
  where k."token_hash" = encode(extensions.digest(convert_to(get_public_form.token, 'utf8'), 'sha256'), 'hex')
    and k."subject_type" = 'form'
    and k."revoked_at" is null
    and (k."expires_at" is null or k."expires_at" > now())
    and (k."max_uses" is null or k."use_count" < k."max_uses")
    and k."password_hash" is null
    and k."role" = 'respond';
  if v_form_id is null then
    raise exception 'this form link isn''t valid' using errcode = 'P0002', hint = 'FORM_LINK_INVALID';
  end if;
  select * into v_row from "better_supabase"."forms" x where x."id" = v_form_id;
  if v_row."status" <> 'open' then
    raise exception 'this form isn''t taking submissions' using errcode = '55000', hint = 'FORM_CLOSED';
  end if;
  select * into v_version from "better_supabase"."form_versions" x where x."id" = v_row."current_version_id";
  return jsonb_build_object('id', v_row."id", 'title', v_row."title", 'description', v_row."description", 'version', jsonb_build_object('id', v_version."id", 'formId', v_version."form_id", 'number', v_version."number", 'definition', v_version."definition", 'schema', v_version."schema", 'createdBy', v_version."created_by", 'createdAt', v_version."created_at") - 'createdBy');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.get_purchase_requisition (
  requisition uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."purchase_requisitions";
begin
  select * into v_row from "better_supabase"."purchase_requisitions" x where x."id" = get_purchase_requisition.requisition;
  if not found then
    raise exception 'purchase requisition not found' using errcode = 'P0002', hint = 'INVENTORY_REQUISITION_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'inventory.read'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'locationId', v_row."location_id",
      'supplierType', v_row."supplier_type", 'supplierId', v_row."supplier_id", 'currency', v_row."currency",
      'status', v_row."status", 'reason', v_row."reason", 'requestedBy', v_row."requested_by",
      'decidedBy', v_row."decided_by", 'decidedAt', v_row."decided_at", 'approvalId', v_row."approval_id",
      'createdAt', v_row."created_at",
      'purchaseOrderId', v_row."purchase_order_id",
      'lines', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'variantId', y."variant_id", 'quantity', y."quantity"::text,
        'unitCost', y."unit_cost"::text) order by y."variant_id") from "better_supabase"."purchase_requisition_lines" y where y."requisition_id" = v_row."id"), '[]'::jsonb));
end;
$function$;

