CREATE OR REPLACE FUNCTION better_supabase.get_risk (
  risk_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."risks";
  v_matrix "better_supabase"."risk_matrices";
begin
  select * into v_row from "better_supabase"."risks" x where x."id" = get_risk.risk_id;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'risks.read'), false))) then
    raise exception 'no such risk' using errcode = 'P0002', hint = 'RISK_NOT_FOUND';
  end if;
  select * into v_matrix from "better_supabase"."risk_matrices" x where x."id" = v_row."matrix_id";
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'number', v_row."number", 'matrixId', v_row."matrix_id", 'title', v_row."title", 'description', v_row."description", 'category', v_row."category", 'cause', v_row."cause", 'consequence', v_row."consequence", 'ownerId', v_row."owner_id", 'status', v_row."status", 'treatment', v_row."treatment", 'reviewIntervalMonths', v_row."review_interval_months", 'nextReviewOn', v_row."next_review_on", 'reviewedAt', v_row."reviewed_at", 'inherent', case when v_row."inherent_score" is null then null else jsonb_build_object('likelihood', v_row."inherent_likelihood", 'impact', v_row."inherent_impact", 'score', v_row."inherent_score", 'band', v_row."inherent_band") end, 'residual', case when v_row."residual_score" is null then null else jsonb_build_object('likelihood', v_row."residual_likelihood", 'impact', v_row."residual_impact", 'score', v_row."residual_score", 'band', v_row."residual_band") end, 'currentAssessmentId', v_row."current_assessment_id", 'closedAt', v_row."closed_at", 'archivedAt', v_row."archived_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at") || jsonb_build_object(
    'matrix', jsonb_build_object('id', v_matrix."id", 'organizationId', v_matrix."tenant_id", 'key', v_matrix."key", 'name', v_matrix."name", 'likelihoodLevels', v_matrix."likelihood_levels", 'impactLevels', v_matrix."impact_levels", 'bands', v_matrix."bands", 'scoring', v_matrix."scoring", 'isDefault', v_matrix."is_default", 'createdAt', v_matrix."created_at", 'updatedAt', v_matrix."updated_at"),
    'assessments', coalesce((
      select jsonb_agg(jsonb_build_object('id', y."id", 'organizationId', y."tenant_id", 'riskId', y."risk_id", 'inherent', jsonb_build_object('likelihood', y."inherent_likelihood", 'impact', y."inherent_impact", 'score', y."inherent_score", 'band', y."inherent_band"), 'residual', jsonb_build_object('likelihood', y."residual_likelihood", 'impact', y."residual_impact", 'score', y."residual_score", 'band', y."residual_band"), 'rationale', y."rationale", 'versionId', y."version_id", 'assessedBy', y."assessed_by", 'assessedAt', y."assessed_at") order by y."assessed_at" desc)
      from "better_supabase"."risk_assessments" y where y."tenant_id" = v_row."tenant_id" and y."risk_id" = v_row."id"
    ), '[]'::jsonb),
    'barriers', coalesce((
      select jsonb_agg(jsonb_build_object('linkId', l."id", 'type', l."target_type", 'id', l."target_id", 'title', "better_supabase"."subject_title"(l."target_type", l."target_id")) order by l."created_at")
      from "better_supabase"."relations" l
      where l."tenant_id" = v_row."tenant_id" and l."kind" = 'mitigated_by'
        and l."source_type" = 'risk' and l."source_id" = v_row."id"::text
    ), '[]'::jsonb),
    'cases', coalesce((
      select jsonb_agg(jsonb_build_object('linkId', l."id", 'type', l."target_type", 'id', l."target_id", 'title', "better_supabase"."subject_title"(l."target_type", l."target_id")) order by l."created_at")
      from "better_supabase"."relations" l
      where l."tenant_id" = v_row."tenant_id" and l."kind" = 'materialized_as'
        and l."source_type" = 'risk' and l."source_id" = v_row."id"::text
    ), '[]'::jsonb)
  );
end;
$function$;

