                v_out := v_results[v_i];
                if jsonb_typeof(v_out) = 'object' and v_out ? 'error' then
                  raise exception '%', coalesce(v_out -> 'error' ->> 'message', 'the import target refused the item')
                    using hint = coalesce(v_out -> 'error' ->> 'code', 'IMPORT_ITEM_INVALID');
                end if;
              end if;
              v_subjects := case jsonb_typeof(v_out) when 'array' then v_out else jsonb_build_array(v_out) end;
  if not exists (
    select 1 from jsonb_array_elements(v_subjects) s
    where coalesce(s.value ->> 'role', 'primary') = 'primary' and nullif(s.value ->> 'subjectId', '') is not null
  ) then
    raise exception 'the import target returned no primary subject' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;

  for v_subject in select s.value from jsonb_array_elements(v_subjects) s loop
    if jsonb_typeof(v_subject -> 'warnings') = 'array' then
      v_warnings := v_warnings || (select coalesce(jsonb_agg(w.value || jsonb_build_object('entity', v_entity, 'key', v_key)), '[]'::jsonb) from jsonb_array_elements(v_subject -> 'warnings') w);
    end if;
    insert into "better_supabase"."import_records" ("tenant_id", "source", "scope", "entity", "external_key", "role", "subject_type", "subject_id", "content_hash", "first_run_id", "last_run_id", "subject_imported_updated_at", "source_updated_at", "went_missing_at")
    values (
      v_run."tenant_id", v_run."source", v_scope, v_entity, v_key,
      coalesce(v_subject ->> 'role', 'primary'),
      coalesce(v_subject ->> 'subjectType', v_subject_type),
      v_subject ->> 'subjectId',
      v_hash, v_run_id, v_run_id,
      coalesce((v_subject ->> 'updatedAt')::timestamptz, now()),
      v_source_at,
      null
    )
    on conflict ("tenant_id", "source", "scope", "entity", "external_key", "role") do update set
      "subject_type" = excluded."subject_type",
      "subject_id" = excluded."subject_id",
      "content_hash" = excluded."content_hash",
      "last_run_id" = excluded."last_run_id",
      "subject_imported_updated_at" = excluded."subject_imported_updated_at",
      "source_updated_at" = coalesce(excluded."source_updated_at", "better_supabase"."import_records"."source_updated_at"),
      "went_missing_at" = null;
  end loop;

  if v_found then
    v_updated := v_updated + 1;
  else
    v_inserted := v_inserted + 1;
  end if;
  
            exception when others then
              get stacked diagnostics v_message = message_text, v_hint = pg_exception_hint;
              v_errors := v_errors || jsonb_build_array(jsonb_build_object('entity', v_entity, 'key', v_key, 'code', coalesce(nullif(v_hint, ''), 'IMPORT_ITEM_INVALID'), 'message', v_message));
            end;
          end loop;
          v_pending := '{}';
          v_calls := '{}';
          v_pending_keys := '{}';
        end if;

  perform "better_supabase"."import_note_warnings"(v_run_id, v_entity, v_warnings);

  return jsonb_build_object('inserted', v_inserted, 'updated', v_updated, 'unchanged', v_unchanged, 'conflicted', v_conflicted, 'errors', v_errors) || case when jsonb_array_length(v_conflict_keys) > 0 then jsonb_build_object('conflictKeys', v_conflict_keys) else '{}'::jsonb end || case when jsonb_array_length(v_diff) > 0 then jsonb_build_object('diff', v_diff) else '{}'::jsonb end || case when jsonb_array_length(v_warnings) > 0 then jsonb_build_object('warnings', v_warnings) else '{}'::jsonb end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_asset (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_data jsonb := import_asset.item -> 'data';
  v_tenant uuid := (import_asset.item ->> 'tenant')::uuid;
  v_id uuid := nullif(import_asset.subject_id, '')::uuid;
  v_updated timestamptz;
begin
  if jsonb_typeof(v_data) is distinct from 'object' or nullif(btrim(v_data ->> 'name'), '') is null then
    raise exception 'an asset needs a name' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_id is null then
    insert into "better_supabase"."assets" ("tenant_id", "kind", "name", "make", "model", "ownership")
    values (v_tenant, coalesce(nullif(v_data ->> 'kind', ''), 'asset'), btrim(v_data ->> 'name'), nullif(btrim(v_data ->> 'make'), ''), nullif(btrim(v_data ->> 'model'), ''), nullif(v_data ->> 'ownership', ''))
    returning "id", "updated_at" into v_id, v_updated;
  else
    update "better_supabase"."assets" x set "name" = btrim(v_data ->> 'name'), "make" = coalesce(nullif(btrim(v_data ->> 'make'), ''), x."make"), "model" = coalesce(nullif(btrim(v_data ->> 'model'), ''), x."model"), "ownership" = coalesce(nullif(v_data ->> 'ownership', ''), x."ownership"), "updated_at" = now()
    where x."id" = v_id and x."tenant_id" = v_tenant
    returning x."updated_at" into v_updated;
  end if;
  return jsonb_build_object('subjectId', v_id, 'updatedAt', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_asset_identifier (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_data jsonb := import_asset_identifier.item -> 'data';
  v_asset uuid := nullif(coalesce(import_asset_identifier.item -> 'resolved' ->> 'asset', v_data ->> 'assetId'), '')::uuid;
  v_id uuid;
  v_updated timestamptz;
begin
  if v_asset is null or nullif(btrim(v_data ->> 'type'), '') is null or nullif(btrim(v_data ->> 'value'), '') is null then
    raise exception 'an identifier needs an asset, a type and a value' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  insert into "better_supabase".asset_identifiers ("tenant_id", "asset_id", "type", "value")
  values ((import_asset_identifier.item ->> 'tenant')::uuid, v_asset, btrim(v_data ->> 'type'), btrim(v_data ->> 'value'))
  on conflict ("tenant_id", "type", "value") do update set "asset_id" = excluded."asset_id", "updated_at" = now()
  returning "id", "updated_at" into v_id, v_updated;
  return jsonb_build_object('subjectId', v_id, 'updatedAt', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_attachment (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_tenant uuid := (import_attachment.item ->> 'tenant')::uuid;
  v_scope text := coalesce(import_attachment.item ->> 'scope', '');
  v_key text := import_attachment.item ->> 'key';
  v_data jsonb := import_attachment.item -> 'data';
  v_reference jsonb := v_data -> 'subject';
  v_type text := nullif(v_data ->> 'subjectType', '');
  v_subject text := nullif(v_data ->> 'subjectId', '');
  v_source text;
  v_status text := coalesce(v_data ->> 'status', 'pending_upload');
  v_document uuid;
  v_size bigint;
  v_id uuid;
  v_metadata jsonb := coalesce(v_data -> 'metadata', '{}'::jsonb);
begin
  select u."source" into v_source from "better_supabase"."import_runs" u where u."id" = import_attachment.run;
  if v_status not in ('pending_upload', 'missing') then
    raise exception 'an imported attachment is pending_upload or missing' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if jsonb_typeof(v_metadata) is distinct from 'object' then
    raise exception 'metadata must be an object' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_data ->> 'name' is null then
    raise exception 'an attachment needs a name' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  begin
    v_size := coalesce((v_data ->> 'size')::bigint, 0);
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'size must be a whole number of bytes' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  if v_reference is not null then
    if jsonb_typeof(v_reference) is distinct from 'object' then
      raise exception 'subject is { entity, key }' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
    select x."subject_type", x."subject_id" into v_type, v_subject
    from "better_supabase"."import_records" x
    where x."tenant_id" = v_tenant and x."source" = v_source and x."scope" = v_scope
      and x."entity" = v_reference ->> 'entity' and x."external_key" = v_reference ->> 'key'
      and x."role" = 'primary';
    if not found then
      raise exception 'the record isn''t in the import record map; import it first' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  if (v_type is null) <> (v_subject is null) then
    raise exception 'an attachment names a subject with both subjectType and subjectId, or none' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_data ->> 'documentType' is not null then
    select y."id" into v_document from "better_supabase"."attachment_document_types" y
    where y."tenant_id" = v_tenant and y."key" = v_data ->> 'documentType';
    if not found then
      raise exception 'the document type doesn''t exist in this organization' using errcode = '22022', hint = 'ATTACHMENT_DOCUMENT_TYPE_UNKNOWN';
    end if;
  end if;

  select a."id" into v_id from "better_supabase"."attachments" a
  where a."tenant_id" = v_tenant and a."source" = v_source and a."external_id" = v_key;
  if found then
    update "better_supabase"."attachments" a set
      "name" = v_data ->> 'name',
      "mime_type" = case when a."uploaded_at" is null then lower(coalesce(v_data ->> 'mimeType', a."mime_type")) else a."mime_type" end,
      "size" = case when a."uploaded_at" is null then v_size else a."size" end,
      "subject_type" = v_type,
      "subject_id" = v_subject,
      "document_type_id" = v_document,
      "metadata" = v_metadata,
      "source_path" = v_data ->> 'sourcePath',
      "storage_status" = case when a."uploaded_at" is null then v_status else a."storage_status" end
    where a."id" = v_id;
  else
    insert into "better_supabase"."attachments" ("tenant_id", "name", "mime_type", "size", "subject_type", "subject_id", "document_type_id", "metadata", "source", "external_id", "source_path", "storage_status", "uploaded_by")
    values (v_tenant, v_data ->> 'name', lower(coalesce(v_data ->> 'mimeType', 'application/octet-stream')), v_size, v_type, v_subject, v_document, v_metadata, v_source, v_key, v_data ->> 'sourcePath', v_status, null)
    returning "id" into v_id;
  end if;
  return jsonb_build_object('subjectId', v_id::text, 'subjectType', 'attachment');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_bank_statement (
  account_id uuid,
  statement  jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_account "better_supabase"."bank_accounts"%rowtype;
  v_statement "better_supabase"."bank_statements"%rowtype;
  v_reference text;
  v_format text;
  v_item record;
  v_amount text;
  v_currency text;
  v_external text;
  v_imported integer := 0;
  v_total integer := 0;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_account from "better_supabase"."bank_accounts" x where x."id" = import_bank_statement.account_id for update;
  if not found then
    raise exception 'no such bank account' using errcode = 'P0002', hint = 'BANK_ACCOUNT_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_account."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_account."tenant_id", 'banking.import'), false))) then
    raise exception 'not allowed to do this with bank accounts' using errcode = '42501', hint = 'BANKING_FORBIDDEN';
  end if;
  if v_account."archived_at" is not null then
    raise exception 'an archived bank account takes no statements' using errcode = '22023', hint = 'BANK_STATEMENT_INVALID';
  end if;
  if jsonb_typeof(import_bank_statement.statement) is distinct from 'object'
    or jsonb_typeof(import_bank_statement.statement -> 'transactions') is distinct from 'array' then
    raise exception 'a statement is an object with a transactions array' using errcode = '22023', hint = 'BANK_STATEMENT_INVALID';
  end if;
  v_format := coalesce(import_bank_statement.statement ->> 'format', 'feed');
  if v_format not in ('camt053', 'mt940', 'csv', 'feed') then
    raise exception 'a statement''s format is camt053, mt940, csv or feed' using errcode = '22023', hint = 'BANK_STATEMENT_INVALID';
  end if;
  if coalesce(import_bank_statement.statement ->> 'openingBalance', '0') !~ '^-?[0-9]{1,18}$'
    or coalesce(import_bank_statement.statement ->> 'closingBalance', '0') !~ '^-?[0-9]{1,18}$'
    or coalesce(import_bank_statement.statement ->> 'fromOn', '2000-01-01') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    or coalesce(import_bank_statement.statement ->> 'untilOn', '2000-01-01') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
    raise exception 'balances are integers of minor units and dates are YYYY-MM-DD' using errcode = '22023', hint = 'BANK_STATEMENT_INVALID';
  end if;
  v_reference := left(nullif(trim(import_bank_statement.statement ->> 'reference'), ''), 200);
  if v_reference is not null then
    select * into v_statement from "better_supabase"."bank_statements" x
    where x."account_id" = v_account."id" and x."reference" = v_reference;
  end if;
  if v_statement."id" is null then
    insert into "better_supabase"."bank_statements" ("tenant_id", "account_id", "reference", "from_on", "until_on",
      "opening_balance", "closing_balance", "format", "attachment_id", "imported_by")
    values (v_account."tenant_id", v_account."id", v_reference,
      (import_bank_statement.statement ->> 'fromOn')::date, (import_bank_statement.statement ->> 'untilOn')::date,
      (import_bank_statement.statement ->> 'openingBalance')::bigint, (import_bank_statement.statement ->> 'closingBalance')::bigint,
      v_format, nullif(import_bank_statement.statement ->> 'attachmentId', '')::uuid, auth.uid())
    returning * into v_statement;
  end if;
  for v_item in
    select e.value as tx, e.ordinality as n
    from jsonb_array_elements(import_bank_statement.statement -> 'transactions') with ordinality e
  loop
    v_total := v_total + 1;
    v_amount := v_item.tx ->> 'amount';
    v_currency := upper(coalesce(v_item.tx ->> 'currency', v_account."currency"));
    if jsonb_typeof(v_item.tx) is distinct from 'object'
      or coalesce(v_amount, '') !~ '^-?[0-9]{1,18}$' or v_amount ~ '^-?0+$'
      or coalesce(v_item.tx ->> 'bookedOn', '') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      or coalesce(v_item.tx ->> 'valueOn', '2000-01-01') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
      raise exception 'each transaction has a bookedOn date and a nonzero amount of minor units' using errcode = '22023', hint = 'BANK_STATEMENT_INVALID';
    end if;
    if v_currency <> v_account."currency" then
      raise exception 'a transaction is in its bank account''s currency' using errcode = '22023', hint = 'BANK_STATEMENT_INVALID';
    end if;
    v_external := coalesce(
      left(nullif(trim(v_item.tx ->> 'externalId'), ''), 200),
      md5(concat_ws('|', v_item.tx ->> 'bookedOn', v_amount, v_item.tx ->> 'counterpartyIban', v_item.tx ->> 'remittance',
        v_item.tx ->> 'structuredReference', v_item.tx ->> 'endToEndId', v_reference, v_item.n::text)));
    insert into "better_supabase"."bank_transactions" ("tenant_id", "account_id", "statement_id", "booked_on", "value_on", "amount",
      "currency", "counterparty_name", "counterparty_iban", "remittance", "structured_reference",
      "end_to_end_id", "external_id")
    values (v_account."tenant_id", v_account."id", v_statement."id", (v_item.tx ->> 'bookedOn')::date,
      (v_item.tx ->> 'valueOn')::date, v_amount::bigint, v_currency,
      left(nullif(trim(v_item.tx ->> 'counterpartyName'), ''), 500),
      left(nullif(upper(regexp_replace(coalesce(v_item.tx ->> 'counterpartyIban', ''), '\s', '', 'g')), ''), 34),
      left(nullif(trim(v_item.tx ->> 'remittance'), ''), 2000),
      left(nullif(trim(v_item.tx ->> 'structuredReference'), ''), 100),
      left(nullif(trim(v_item.tx ->> 'endToEndId'), ''), 100),
      v_external)
    on conflict ("account_id", "external_id") do nothing;
    if found then
      v_imported := v_imported + 1;
    end if;
  end loop;
  perform "better_supabase".emit_event('bank_statement.imported', jsonb_build_object('organizationId', v_statement."tenant_id", 'id', v_statement."id", 'accountId', v_statement."account_id", 'reference', v_statement."reference", 'imported', v_imported), 'bank-statements/' || v_statement."id"::text, (v_statement."tenant_id")::text, null, 'better-supabase/banking');
  perform better_supabase.audit_event(
    event_type => 'bank_statement.imported',
    category => 'billing',
    target_type => 'bank_statement',
    record_id => v_statement."id"::text,
    target_label => coalesce(v_statement."reference", v_account."name"),
    summary => 'imported a bank statement',
    tenant => (v_statement."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_statement."tenant_id", 'id', v_statement."id", 'accountId', v_statement."account_id", 'reference', v_statement."reference", 'imported', v_imported)
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_bank_statement_import"(uuid, integer)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::integer)', v_hook::oid::regproc)
        using v_statement."id", v_imported;
    end if;
  end;
  return jsonb_build_object('statement', jsonb_build_object('id', v_statement."id", 'organizationId', v_statement."tenant_id", 'accountId', v_statement."account_id", 'reference', v_statement."reference", 'fromOn', v_statement."from_on", 'untilOn', v_statement."until_on", 'openingBalance', v_statement."opening_balance"::text, 'closingBalance', v_statement."closing_balance"::text, 'currency', (select z."currency" from "better_supabase"."bank_accounts" z where z."id" = v_statement."account_id"), 'format', v_statement."format", 'attachmentId', v_statement."attachment_id", 'importedBy', v_statement."imported_by", 'createdAt', v_statement."created_at"), 'imported', v_imported, 'skipped', v_total - v_imported);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_calendar_events (
  calendar_id uuid,
  source      jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_item jsonb;
  v_id uuid;
  v_master uuid;
  v_created integer := 0;
  v_updated integer := 0;
  v_skipped integer := 0;
begin
  for v_item in
    select value from jsonb_array_elements(coalesce(import_calendar_events.source -> 'events', '[]'::jsonb))
    order by value ? 'originalStart', value ->> 'uid'
  loop
    v_id := null;
    if v_item ->> 'originalStart' is null then
      select "id" into v_id from "better_supabase"."calendar_events"
        where "calendar_id" = import_calendar_events.calendar_id and "uid" = v_item ->> 'uid' and "original_starts_at" is null;
    else
      select "id" into v_master from "better_supabase"."calendar_events"
        where "calendar_id" = import_calendar_events.calendar_id and "uid" = v_item ->> 'uid' and "original_starts_at" is null and "rrule" is not null;
      if v_master is null then
        v_skipped := v_skipped + 1;
        continue;
      end if;
      select "id" into v_id from "better_supabase"."calendar_events"
        where "calendar_id" = import_calendar_events.calendar_id and "uid" = v_item ->> 'uid'
          and "original_starts_at" = (v_item ->> 'originalStart')::timestamptz;
      v_item := v_item || jsonb_build_object('recurrenceId', v_master);
    end if;
    if v_id is null then
      perform "better_supabase"."save_calendar_event"(import_calendar_events.calendar_id, v_item - 'id');
      v_created := v_created + 1;
    else
      perform "better_supabase"."save_calendar_event"(import_calendar_events.calendar_id, (v_item - 'recurrenceId' - 'originalStart') || jsonb_build_object('id', v_id));
      v_updated := v_updated + 1;
    end if;
  end loop;
  return jsonb_build_object('created', v_created, 'updated', v_updated, 'skipped', v_skipped);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_chunk_progress (
  run uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'pending', count(*) filter (where x."status" = 'pending'),
    'claimed', count(*) filter (where x."status" = 'claimed'),
    'done', count(*) filter (where x."status" = 'done'),
    'failed', count(*) filter (where x."status" = 'failed')
  )
  from "better_supabase"."import_chunks" x
  where x."run_id" = import_chunk_progress.run
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_clear_issues (
  run    uuid,
  entity text,
  key    text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_source text;
begin
  select r."tenant_id", r."source" into v_tenant, v_source
  from "better_supabase"."import_runs" r where r."id" = import_clear_issues.run;
  if v_tenant is null then
    return;
  end if;
  update "better_supabase".import_run_issues i set "resolved_at" = now()
  where i."tenant_id" = v_tenant and i."source" = v_source
    and i."entity" = import_clear_issues.entity and i."key" = import_clear_issues.key
    and i."resolved_at" is null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_contact_method (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_data jsonb := import_contact_method.item -> 'data';
  v_party uuid := nullif(coalesce(import_contact_method.item -> 'resolved' ->> 'party', v_data ->> 'partyId'), '')::uuid;
  v_kind text := coalesce(nullif(v_data ->> 'partyKind', ''), 'person');
  v_channel text := nullif(v_data ->> 'channel', '');
  v_address text := nullif(btrim(v_data ->> 'address'), '');
  v_id uuid;
  v_updated timestamptz;
begin
  if v_channel in ('email') then
    v_address := nullif(lower(v_address), '');
  elsif v_channel in ('phone', 'mobile', 'fax', 'whatsapp') then
    v_address := nullif(better_supabase.normalize_phone(v_address, v_data ->> 'region'), '');
  end if;
  if v_party is null or v_kind not in ('person', 'company') or v_channel not in ('email', 'phone', 'mobile', 'fax', 'whatsapp') or v_address is null then
    raise exception 'a contact method needs a party, a channel and an address' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  select x."id", x."updated_at" into v_id, v_updated from "better_supabase"."party_channels" x
  where x."tenant_id" = (import_contact_method.item ->> 'tenant')::uuid
    and x."party_id" = v_party and x."channel" = v_channel and x."address" = v_address
    and x."label" is not distinct from nullif(btrim(v_data ->> 'label'), '')
    and x."is_primary" is not distinct from coalesce((v_data ->> 'isPrimary')::boolean, false);
  if v_id is not null then
    return jsonb_build_object('subjectId', v_id, 'updatedAt', v_updated);
  end if;
  insert into "better_supabase"."party_channels" ("tenant_id", "party_id", "party_kind", "channel", "label", "address", "is_primary")
  values ((import_contact_method.item ->> 'tenant')::uuid, v_party, v_kind, v_channel, nullif(btrim(v_data ->> 'label'), ''), v_address, coalesce((v_data ->> 'isPrimary')::boolean, false))
  on conflict ("tenant_id", "party_id", "channel", "address") do update
    set "label" = excluded."label", "is_primary" = excluded."is_primary", "updated_at" = now()
  returning "id", "updated_at" into v_id, v_updated;
  return jsonb_build_object('subjectId', v_id, 'updatedAt', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_credit_note (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select "better_supabase"."import_invoice_document"(import_credit_note.item, import_credit_note.subject_id, true)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_discount_group (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_discount_group.item ->> 'tenant')::uuid;
  v_data jsonb := import_discount_group.item -> 'data';
  v_kind text := v_data ->> 'kind';
  v_code text := btrim(v_data ->> 'code');
  v_name text := btrim(coalesce(v_data ->> 'name', v_data ->> 'code'));
  v_id uuid;
  v_updated timestamptz;
begin
  if v_kind is null or v_kind not in ('customer', 'product') or v_code is null or length(v_code) not between 1 and 50 or length(v_name) not between 1 and 200 then
    raise exception 'a discount group needs a kind (customer or product), a code and a name' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_data ? 'parties' and (v_kind <> 'customer' or jsonb_typeof(v_data -> 'parties') <> 'array') then
    raise exception 'parties is a list on a customer group' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if import_discount_group.subject_id is null then
    insert into "better_supabase"."discount_groups" as x ("tenant_id", "kind", "code", "name")
    values (v_tenant, v_kind, v_code, v_name)
    on conflict ("tenant_id", "kind", "code") do update set "name" = excluded."name", "updated_at" = now()
    returning x."id", x."updated_at" into v_id, v_updated;
  else
    begin
      update "better_supabase"."discount_groups" x set "kind" = v_kind, "code" = v_code, "name" = v_name, "updated_at" = now()
      where x."id" = import_discount_group.subject_id::uuid and x."tenant_id" = v_tenant
      returning x."id", x."updated_at" into v_id, v_updated;
    exception when unique_violation then
      raise exception 'another group of this kind has this code' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end;
    if v_id is null then
      raise exception 'the discount group no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  if v_data ? 'parties' then
    delete from "better_supabase"."discount_group_parties" x where x."group_id" = v_id and x."party_id" not in (select jsonb_array_elements_text(v_data -> 'parties'));
    insert into "better_supabase"."discount_group_parties" as x ("tenant_id", "group_id", "party_id")
    select v_tenant, v_id, btrim(p) from jsonb_array_elements_text(v_data -> 'parties') p where length(btrim(p)) between 1 and 200
    on conflict ("tenant_id", "party_id") do update set "group_id" = excluded."group_id";
  end if;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_discount_rule (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_discount_rule.item ->> 'tenant')::uuid;
  v_data jsonb := import_discount_rule.item -> 'data';
  v_customer_id uuid;
  v_product_id uuid;
  v_customer_code text := nullif(btrim(v_data ->> 'customerGroup'), '');
  v_product_code text := nullif(btrim(v_data ->> 'productGroup'), '');
  v_customer uuid;
  v_product uuid;
  v_attrs jsonb;
  v_id uuid;
  v_updated timestamptz;
begin
  begin
    v_customer_id := nullif(v_data ->> 'customerGroupId', '')::uuid;
    v_product_id := nullif(v_data ->> 'productGroupId', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'group ids are uuids' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  v_customer := (select y."id" from "better_supabase"."discount_groups" y
      where y."tenant_id" = v_tenant and y."kind" = 'customer'
        and ((v_customer_id is not null and y."id" = v_customer_id) or (v_customer_id is null and v_customer_code is not null and y."code" = v_customer_code)));
  v_product := (select y."id" from "better_supabase"."discount_groups" y
      where y."tenant_id" = v_tenant and y."kind" = 'product'
        and ((v_product_id is not null and y."id" = v_product_id) or (v_product_id is null and v_product_code is not null and y."code" = v_product_code)));
  if (v_customer_id is not null or v_customer_code is not null) and v_customer is null then
    raise exception 'the customer group isn''t in this organization; import the groups first' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if (v_product_id is not null or v_product_code is not null) and v_product is null then
    raise exception 'the product group isn''t in this organization; import the groups first' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  v_attrs := jsonb_strip_nulls(jsonb_build_object('customerGroupId', v_customer, 'productGroupId', v_product, 'validFrom', v_data -> 'validFrom', 'validTo', v_data -> 'validTo',
    'minQuantity', v_data -> 'minQuantity', 'discountBps', v_data -> 'discountBps', 'fixedPrice', v_data -> 'fixedPrice', 'currency', v_data -> 'currency'));
  begin
    perform "better_supabase"."discount_rule_check"(v_tenant, v_attrs);
  exception when sqlstate '22023' or sqlstate 'P0002' then
    raise exception 'the rule isn''t valid: check the groups, dates, discountBps, minQuantity and fixed price' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  if import_discount_rule.subject_id is null then
    insert into "better_supabase"."discount_rules" as x ("tenant_id", "customer_group_id", "product_group_id", "valid_from", "valid_to", "min_quantity", "discount_bps", "fixed_price", "currency")
    values (v_tenant, v_customer, v_product, (v_attrs ->> 'validFrom')::date, (v_attrs ->> 'validTo')::date, coalesce((v_attrs ->> 'minQuantity')::numeric, 0),
      coalesce((v_attrs ->> 'discountBps')::integer, 0), (v_attrs ->> 'fixedPrice')::bigint, v_attrs ->> 'currency')
    on conflict ("tenant_id", coalesce("customer_group_id", '00000000-0000-4000-8000-000000000000'::uuid), coalesce("product_group_id", '00000000-0000-4000-8000-000000000000'::uuid), coalesce("valid_from", date '0001-01-01'), "min_quantity") do update set
      "valid_to" = excluded."valid_to", "discount_bps" = excluded."discount_bps", "fixed_price" = excluded."fixed_price",
      "currency" = excluded."currency", "updated_at" = now()
    returning x."id", x."updated_at" into v_id, v_updated;
  else
    begin
      update "better_supabase"."discount_rules" x set "customer_group_id" = v_customer, "product_group_id" = v_product, "valid_from" = (v_attrs ->> 'validFrom')::date, "valid_to" = (v_attrs ->> 'validTo')::date,
        "min_quantity" = coalesce((v_attrs ->> 'minQuantity')::numeric, 0), "discount_bps" = coalesce((v_attrs ->> 'discountBps')::integer, 0),
        "fixed_price" = (v_attrs ->> 'fixedPrice')::bigint, "currency" = v_attrs ->> 'currency', "updated_at" = now()
      where x."id" = import_discount_rule.subject_id::uuid and x."tenant_id" = v_tenant
      returning x."id", x."updated_at" into v_id, v_updated;
    exception when unique_violation then
      raise exception 'another rule has the same groups, start date and minimum quantity' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end;
    if v_id is null then
      raise exception 'the discount rule no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_document_delivery_preference (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row jsonb;
begin
  if jsonb_typeof(import_document_delivery_preference.item -> 'data') is distinct from 'object' then
    raise exception 'a delivery preference item needs data' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  v_row := "better_supabase"."delivery_preference_write"((import_document_delivery_preference.item ->> 'tenant')::uuid, import_document_delivery_preference.item -> 'data', import_document_delivery_preference.subject_id::uuid);
  return jsonb_build_object('subjectId', v_row ->> 'id', 'updatedAt', v_row ->> 'updatedAt');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_document_template (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_document_template.item ->> 'tenant')::uuid;
  v_data jsonb := import_document_template.item -> 'data';
  v_entity uuid;
  v_saved jsonb;
begin
  if jsonb_typeof(v_data) is distinct from 'object' then
    raise exception 'a template item is an object' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if nullif(v_data ->> 'legalEntityId', '') is not null then
    v_entity := (v_data ->> 'legalEntityId')::uuid;
  elsif nullif(v_data ->> 'legalEntity', '') is not null then
    select x."id" into v_entity from "better_supabase"."legal_entities" x
      where x."tenant_id" = v_tenant and x."code" = v_data ->> 'legalEntity';
    if v_entity is null then
      raise exception 'the legal entity code is unknown' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  v_saved := "better_supabase"."save_document_template"(v_tenant, v_data ->> 'documentType', v_data ->> 'body', v_data ->> 'language',
    coalesce(nullif(v_data ->> 'name', ''), 'default'), v_entity, coalesce((v_data ->> 'active')::boolean, true));
  return jsonb_build_object('subjectId', v_saved ->> 'id', 'updatedAt', v_saved -> 'updatedAt');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_document_text_block (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_document_text_block.item ->> 'tenant')::uuid;
  v_data jsonb := import_document_text_block.item -> 'data';
  v_entity uuid;
  v_saved jsonb;
begin
  if jsonb_typeof(v_data) is distinct from 'object' then
    raise exception 'a text block item is an object' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if nullif(v_data ->> 'legalEntityId', '') is not null then
    v_entity := (v_data ->> 'legalEntityId')::uuid;
  elsif nullif(v_data ->> 'legalEntity', '') is not null then
    select x."id" into v_entity from "better_supabase"."legal_entities" x
      where x."tenant_id" = v_tenant and x."code" = v_data ->> 'legalEntity';
    if v_entity is null then
      raise exception 'the legal entity code is unknown' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  v_saved := "better_supabase"."save_document_text_block"(v_tenant, v_data ->> 'key', v_data ->> 'body', v_data ->> 'language', v_entity);
  return jsonb_build_object('subjectId', v_saved ->> 'id', 'updatedAt', v_saved -> 'updatedAt');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_due_check (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_due_check.item ->> 'tenant')::uuid;
  v_data jsonb := import_due_check.item -> 'data';
  v_asset uuid;
  v_days integer;
  v_done timestamptz;
  v_id uuid;
  v_updated timestamptz;
begin
  begin
    v_asset := nullif(v_data ->> 'assetId', '')::uuid;
    v_days := (v_data ->> 'intervalDays')::integer;
    v_done := nullif(v_data ->> 'lastDoneAt', '')::timestamptz;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'assetId is a uuid, intervalDays is a whole number and lastDoneAt is a timestamp' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  if v_asset is null or nullif(v_data ->> 'checkType', '') is null or v_days is null or v_days < 1 then
    raise exception 'a due check needs an assetId, a checkType and an intervalDays of 1 or more' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if not exists (select 1 from "better_supabase"."assets" a where a."id" = v_asset and a."tenant_id" = v_tenant) then
    raise exception 'the asset is not in this organization' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  insert into "better_supabase".asset_due_checks ("tenant_id", "asset_id", "check_type", "interval_days", "last_done_at", "result")
  values (v_tenant, v_asset, v_data ->> 'checkType', v_days, v_done, nullif(v_data ->> 'result', ''))
  on conflict ("tenant_id", "asset_id", "check_type") do update set
    "interval_days" = excluded."interval_days",
    "last_done_at" = coalesce(excluded."last_done_at", "better_supabase".asset_due_checks."last_done_at"),
    "result" = coalesce(excluded."result", "better_supabase".asset_due_checks."result")
  returning "id", "updated_at" into v_id, v_updated;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_ensure_ref (
  tenant   uuid,
  kind     text,
  key      text,
  defaults jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_id uuid;
  v_created boolean := false;
begin
  if not (auth.role() = 'service_role') then
    raise exception 'only the service role can ensure an import ref' using errcode = '42501', hint = 'IMPORT_FORBIDDEN';
  end if;
  if import_ensure_ref.kind is null or import_ensure_ref.key is null or import_ensure_ref.key = '' then
    raise exception 'a ref needs a kind and a key' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  select r."id" into v_id from "better_supabase".import_refs r
  where r."tenant_id" = import_ensure_ref.tenant and r."kind" = import_ensure_ref.kind and lower(r."key") = lower(import_ensure_ref.key);
  if v_id is null then
    insert into "better_supabase".import_refs ("tenant_id", "kind", "key", "payload")
    values (import_ensure_ref.tenant, import_ensure_ref.kind, import_ensure_ref.key, coalesce(import_ensure_ref.defaults, '{}'::jsonb))
    on conflict ("tenant_id", "kind", "key") do nothing
    returning "id" into v_id;
    v_created := v_id is not null;
    if v_id is null then
      select r."id" into v_id from "better_supabase".import_refs r
      where r."tenant_id" = import_ensure_ref.tenant and r."kind" = import_ensure_ref.kind and lower(r."key") = lower(import_ensure_ref.key);
    end if;
  end if;
  return jsonb_build_object(
    'id', v_id,
    'created', v_created,
    'warnings', case when v_created then jsonb_build_array(jsonb_build_object('code', 'IMPORT_REF_CREATED', 'kind', import_ensure_ref.kind, 'key', import_ensure_ref.key)) else '[]'::jsonb end
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_entities()
  RETURNS text[]
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$ select array['organization_profile', 'attachment', 'data_lifecycle_row', 'field_value', 'supplier_item', 'product_identifier', 'discount_group', 'discount_rule', 'party_discount_group', 'product', 'product_category', 'stock_count', 'stock_allocation', 'order', 'payment_term', 'document_delivery_preference', 'party', 'party_contact', 'contact_method', 'party_location', 'party_bank_account', 'quote', 'invoice', 'credit_note', 'open_item', 'invoice_allocation', 'meter_reading', 'due_check', 'asset', 'asset_identifier', 'accounting_account', 'accounting_journal', 'accounting_entry', 'accounting_opening_balance', 'tax_code', 'tax_rate', 'document_template', 'document_text_block', 'customer', 'customer_row']::text[] $function$;

CREATE OR REPLACE FUNCTION better_supabase.import_field_value (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_tenant uuid := (import_field_value.item ->> 'tenant')::uuid;
  v_scope text := coalesce(import_field_value.item ->> 'scope', '');
  v_data jsonb := import_field_value.item -> 'data';
  v_reference jsonb := v_data -> 'subject';
  v_type text := nullif(v_data ->> 'subjectType', '');
  v_subject text := nullif(v_data ->> 'subjectId', '');
  v_field text := v_data ->> 'field';
  v_value text;
  v_definition uuid;
  v_field_type text;
  v_entity uuid;
  v_row uuid;
begin
  if jsonb_typeof(v_data -> 'value') in ('object', 'array', 'null') or (v_data -> 'value') is null then
    raise exception 'a field value needs a value of text, a number or a boolean' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  v_value := v_data ->> 'value';
  if v_field is null or v_field = '' then
    raise exception 'a field value needs the key of its field' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  begin
    v_entity := nullif(v_data ->> 'legalEntityId', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'legalEntityId must be a uuid' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  if v_reference is not null then
    if jsonb_typeof(v_reference) is distinct from 'object' then
      raise exception 'subject is { entity, key }' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
    select x."subject_type", x."subject_id" into v_type, v_subject
    from "better_supabase"."import_records" x
    join "better_supabase"."import_runs" u on u."id" = import_field_value.run
    where x."tenant_id" = v_tenant and x."source" = u."source"
      and x."scope" = v_scope
      and x."entity" = v_reference ->> 'entity' and x."external_key" = v_reference ->> 'key'
      and x."role" = 'primary';
    if not found then
      raise exception 'the record isn''t in the import record map; import it first' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  if v_type is null or v_subject is null then
    raise exception 'a field value needs a subject: { entity, key }, or subjectType and subjectId' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_type is null or v_type <> all (array['message', 'conversation', 'channel', 'company', 'person', 'deal', 'course', 'post', 'activity', 'quote', 'work_item', 'employee', 'ledger_account', 'invoice', 'product', 'product_variant', 'rfq', 'till', 'order', 'calendar_event', 'booking', 'asset', 'asset_location', 'lease', 'expense_report', 'expense_line', 'donation_fund', 'warranty_claim', 'work_order', 'shipment', 'contract', 'control', 'compliance_policy', 'qualification_type', 'risk', 'case', 'inspection', 'inspection_program', 'inspection_finding', 'form', 'meeting', 'meeting_decision', 'maintenance_plan', 'dam_usage_right', 'lims_sample', 'tax_code', 'production_order', 'work_center', 'bank_account', 'care_plan', 'incident', 'content_entry', 'document', 'customer', 'drive_node', 'organization', 'application', 'change_request', 'project', 'task']::text[]) then
    raise exception 'the entity is not a registered subject type' using errcode = '22023', hint = 'FIELD_ENTITY_UNKNOWN';
  end if;
  select d."id", d."type" into v_definition, v_field_type
  from "better_supabase"."field_definitions" d
  where d."tenant_id" = v_tenant and d."entity" = v_type and d."key" = v_field;
  if not found then
    raise exception 'no field definition with this key on the subject type' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if not (case v_field_type when 'bsn' then "better_supabase"."bsb_valid_bsn"(v_value) when 'iban' then "better_supabase"."bsb_valid_iban"(v_value) when 'phone_e164' then v_value ~* '^\+[1-9][0-9]{1,14}$' else true end) then
    raise exception 'the value doesn''t match the field''s format' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;

  select y."id" into v_row from "better_supabase"."field_values" y
  where y."tenant_id" = v_tenant and y."subject_type" = v_type and y."subject_id" = v_subject and y."definition_id" = v_definition
    and coalesce(y.legal_entity_id, '00000000-0000-0000-0000-000000000000'::uuid) = coalesce(v_entity, '00000000-0000-0000-0000-000000000000'::uuid);
  if found then
    update "better_supabase"."field_values" set "value_text" = case when exists (select 1 from "better_supabase"."field_definitions" d where d."id" = v_definition and d."encrypted") then "better_supabase"."field_encrypt"('tenant:' || v_tenant::text, v_value) else v_value end where "id" = v_row;
  else
    insert into "better_supabase"."field_values" ("tenant_id", "definition_id", "subject_type", "subject_id", "value_text", legal_entity_id)
    values (v_tenant, v_definition, v_type, v_subject, case when exists (select 1 from "better_supabase"."field_definitions" d where d."id" = v_definition and d."encrypted") then "better_supabase"."field_encrypt"('tenant:' || v_tenant::text, v_value) else v_value end, v_entity)
    returning "id" into v_row;
  end if;
  perform "better_supabase".emit_event('field_value.set', jsonb_build_object('organizationId', v_tenant, 'id', v_row, 'subjectType', v_type, 'subjectId', v_subject), 'field-values/' || v_row::text, (v_tenant)::text, null, 'better-supabase/custom-fields');
  return jsonb_build_object('subjectId', v_row::text, 'subjectType', 'field_value');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_integrity (
  tenant uuid,
  source text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_checks jsonb := '[]'::jsonb;
  v_name text;
  v_severity text;
  v_count integer;
  v_ids jsonb;
begin
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', import_integrity.tenant, 'imports.manage'), false)) then
    raise exception 'not allowed to check this import' using errcode = '42501', hint = 'IMPORT_FORBIDDEN';
  end if;
  for v_name, v_severity, v_count, v_ids in
    select 'duplicate_keys', 'error', count(*)::integer, coalesce(jsonb_agg(sample), '[]'::jsonb) from (
      select min(d."id"::text) as sample from "better_supabase"."import_records" d
      where d."tenant_id" = import_integrity.tenant
        and (import_integrity.source is null or d."source" = import_integrity.source)
      group by d."entity", d."external_key"
      having count(distinct d."subject_id") > 1
    ) q
    union all
    select 'unbalanced_ledger', 'error', count(*)::integer, coalesce(jsonb_agg(sample), '[]'::jsonb) from (
      select e."transaction_id"::text as sample from "better_supabase"."ledger_entries" e
      join "better_supabase"."ledger_transactions" y on y."id" = e."transaction_id"
      where y."tenant_id" = import_integrity.tenant
      group by e."transaction_id"
      having sum(e."amount") <> 0
    ) q
    union all
    select 'negative_invoice', 'warning', count(*)::integer, coalesce(jsonb_agg("id"::text), '[]'::jsonb) from "better_supabase"."invoices" where "tenant_id" = import_integrity.tenant and "total" < 0 and "kind"::text is distinct from 'credit_note'
    union all
    select 'issued_without_number', 'warning', count(*)::integer, coalesce(jsonb_agg("id"::text), '[]'::jsonb) from "better_supabase"."invoices" where "tenant_id" = import_integrity.tenant and "status"::text in ('issued', 'partially_paid', 'paid') and nullif("identifier"::text, '') is null
    union all
    select 'archived_without_date', 'warning', count(*)::integer, coalesce(jsonb_agg("id"::text), '[]'::jsonb) from "better_supabase"."companies" where "tenant_id" = import_integrity.tenant and "lifecycle"::text = 'archived' and "archived_at" is null
  loop
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'name', v_name, 'severity', v_severity, 'count', v_count, 'ids', coalesce(v_ids, '[]'::jsonb)));
  end loop;
  return jsonb_build_object('checks', v_checks);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_invoice (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select "better_supabase"."import_invoice_document"(import_invoice.item, import_invoice.subject_id, false)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_invoice_document (
  item       jsonb,
  subject_id text,
  v_credit   boolean
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_invoice_document.item ->> 'tenant')::uuid;
  v_data jsonb := import_invoice_document.item -> 'data';
  v_status text := case when v_credit then 'issued' else coalesce(v_data ->> 'status', 'issued') end;
  v_number text := nullif(btrim(v_data ->> 'number'), '');
  v_issued_on date;
  v_due_on date;
  v_original uuid;
  v_made jsonb;
  v_id uuid;
  v_row "better_supabase"."invoices";
  v_warnings jsonb := '[]'::jsonb;
  v_computed jsonb;
  v_given jsonb;
  v_pay jsonb;
  v_index integer := 0;
begin
  if import_invoice_document.subject_id is not null then
    select * into v_row from "better_supabase"."invoices" x where x."id" = import_invoice_document.subject_id::uuid and x."tenant_id" = v_tenant;
    if not found then
      raise exception 'the invoice no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
    if coalesce(v_data ->> 'update', 'keep') is distinct from 'apply' then
      return jsonb_build_object('subjectId', v_row."id"::text, 'updatedAt', v_row."updated_at", 'warnings', jsonb_build_array(jsonb_build_object('code', 'IMPORT_DOCUMENT_CHANGED', 'message', 'the source document changed after it was imported; an imported document is kept as imported, so void or credit it and import the correction as a new document')));
    end if;
    v_id := v_row."id";
    update "better_supabase"."invoices" x set
      "status" = case when v_row."status"::text in ('void', 'paid') and coalesce((v_data ->> 'repost')::boolean, false) = false then v_row."status" else coalesce(nullif(v_data ->> 'status', ''), v_row."status"::text) end,
      "title" = coalesce(nullif(v_data ->> 'title', ''), x."title"),
      "currency" = coalesce(nullif(v_data ->> 'currency', ''), x."currency"),
      "terms_days" = coalesce((v_data ->> 'termsDays')::integer, x."terms_days"),
      "issued_on" = coalesce(nullif(v_data ->> 'issuedOn', '')::date, x."issued_on"),
      "due_on" = coalesce(nullif(v_data ->> 'dueOn', '')::date, x."due_on"),
      "company_id" = coalesce(nullif(v_data ->> 'companyId', ''), x."company_id"),
      "subtotal" = coalesce((v_data -> 'totals' ->> 'subtotal')::bigint, x."subtotal"),
      "tax_total" = coalesce((v_data -> 'totals' ->> 'tax')::bigint, x."tax_total"),
      "total" = coalesce((v_data -> 'totals' ->> 'total')::bigint, x."total")
    where x."id" = v_id;
    if coalesce((v_data ->> 'repost')::boolean, false) or v_row."status"::text not in ('void', 'paid') then
      if (select count(*) from "better_supabase"."invoice_lines" l where l."parent_id" = v_id) = jsonb_array_length(coalesce(v_data -> 'lines', '[]'::jsonb)) then
        update "better_supabase"."invoice_lines" l set
          "description" = coalesce(nullif(e.l ->> 'title', ''), nullif(e.l ->> 'description', ''), l."description"),
          "tax_rate_bps" = coalesce((e.l ->> 'taxRateBps')::integer, l."tax_rate_bps"),
          "tax_code" = coalesce(nullif(e.l ->> 'taxCode', ''), l."tax_code")
        from jsonb_array_elements(v_data -> 'lines') with ordinality as e(l, n)
        where l."parent_id" = v_id and l."position" = e.n::integer;
      elsif jsonb_typeof(v_data -> 'lines') = 'array' then
        perform "better_supabase"."set_invoice_lines"(v_id, v_data -> 'lines');
      end if;
    end if;
    select * into v_row from "better_supabase"."invoices" x where x."id" = v_id;
    return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_row."updated_at", 'warnings', v_warnings);
  end if;
  if not v_credit and coalesce((v_data -> 'totals' ->> 'total')::bigint, 0) < 0 then
    if coalesce(nullif(v_data ->> 'originalId', ''), nullif(import_invoice_document.item -> 'resolved' ->> 'original', '')) is not null then
      v_credit := true;
    else
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_CREDIT_WITHOUT_ORIGINAL', 'message', 'a negative total has no original invoice, so it stays an invoice'));
    end if;
  end if;

  if v_status not in ('draft', 'issued', 'partially_paid', 'paid', 'void', 'uncollectible') then
    raise exception 'status is draft, issued, partially_paid, paid, void or uncollectible' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if jsonb_typeof(v_data -> 'lines') is distinct from 'array' or jsonb_array_length(v_data -> 'lines') = 0 then
    raise exception 'a document needs at least one line' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_status <> 'draft' and v_number is null then
    raise exception 'an issued document needs its number' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  begin
    v_issued_on := coalesce(nullif(v_data ->> 'issuedOn', '')::date, nullif(v_data ->> 'suppliedOn', '')::date);
    v_due_on := nullif(v_data ->> 'dueOn', '')::date;
  exception when others then
    raise exception 'issuedOn and dueOn are dates' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  if v_status <> 'draft' and v_issued_on is null then
    raise exception 'an issued document needs its issue date' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;

  if coalesce(v_data ->> 'onTaken', 'fail') not in ('fail', 'next_free') then
    raise exception 'onTaken is fail or next_free' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_data ->> 'onTaken' = 'next_free' and v_number is not null and exists (select 1 from "better_supabase"."invoices" x where x."tenant_id" = v_tenant and x."identifier" = v_number) then
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_NUMBER_REASSIGNED', 'message', 'number ' || v_number || ' was taken; the next free number was issued'));
    v_number := null;
  end if;

  if v_credit then
    v_original := coalesce(
      nullif(v_data ->> 'originalId', '')::uuid,
      nullif(import_invoice_document.item -> 'resolved' ->> 'original', '')::uuid,
      (select x."id" from "better_supabase"."invoices" x where x."tenant_id" = v_tenant and x."identifier" = v_data ->> 'original' limit 1)
    );
    if v_original is null and coalesce(v_data ->> 'settlement', 'payments') = 'row' then
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_CREDIT_WITHOUT_ORIGINAL', 'message', 'a credit note has no original invoice, so no posting was made'));
      v_credit := false;
    elsif v_original is null then
      raise exception 'a credit note names the invoice it credits (originalId or original)' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  if v_credit then
    v_made := "better_supabase"."credit_invoice"(v_original, v_data -> 'lines', nullif(v_data ->> 'note', ''), v_number, v_issued_on);
    v_id := (v_made ->> 'id')::uuid;
  else
    v_made := "better_supabase"."create_invoice"(v_tenant, coalesce(v_data -> 'attrs', '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
      'title', coalesce(nullif(v_data ->> 'title', ''), replace('Invoice {number}', '{number}', coalesce(v_number, 'draft'))),
      'currency', v_data -> 'currency',
      'termsDays', v_data -> 'termsDays',
      'note', v_data -> 'note',
      'company', v_data -> 'company',
      'contact', v_data -> 'contact',
      'origin', v_data -> 'origin',
      'direction', v_data -> 'direction',
      'pricesIncludeTax', v_data -> 'pricesIncludeTax',
      'discountBps', v_data -> 'discountBps',
      'discountAmount', v_data -> 'discountAmount')), v_data -> 'lines');
    v_id := (v_made ->> 'id')::uuid;
  end if;
  update "better_supabase"."invoices" x set legal_entity_id = case when v_credit then x.legal_entity_id else nullif(v_data ->> 'legalEntityId', '')::uuid end,
    "buyer" = case when jsonb_typeof(v_data -> 'buyer') = 'object' then v_data -> 'buyer' else x."buyer" end,
    "created_at" = coalesce(nullif(v_data ->> 'createdAt', '')::timestamptz, x."created_at")
  where x."id" = v_id;
  update "better_supabase"."invoices" x set "supplied_on" = coalesce(nullif(v_data ->> 'suppliedOn', '')::date, v_issued_on)
  where x."id" = v_id;
  update "better_supabase"."invoice_lines" l set "product_type" = 'product'
  where l."parent_id" = v_id and l."product_id" is not null and l."product_type" is distinct from 'product';
  if v_status <> 'draft' and not v_credit then
    perform "better_supabase"."issue_invoice"(v_id, v_issued_on, v_due_on, null, v_number);
  end if;
  if jsonb_typeof(v_data -> 'taxLines') = 'array' then
    v_computed := coalesce((
      select jsonb_object_agg(k.key, jsonb_build_object('net', k.net, 'tax', k.tax))
      from (select coalesce(y."tax_code", '') || ':' || y."tax_rate_bps"::text as key, sum(y."net") as net, sum(y."tax") as tax
        from "better_supabase"."invoice_tax_lines" y where y."invoice_id" = v_id group by 1) k
    ), '{}'::jsonb);
    v_given := coalesce((
      select jsonb_object_agg(k.key, jsonb_build_object('net', k.net, 'tax', k.tax))
      from (select coalesce(g.value ->> 'taxCode', '') || ':' || coalesce((g.value ->> 'taxRateBps')::integer, 0)::text as key,
          sum((g.value ->> 'net')::bigint) as net, sum((g.value ->> 'tax')::bigint) as tax
        from jsonb_array_elements(v_data -> 'taxLines') g group by 1) k
    ), '{}'::jsonb);
    if v_computed <> v_given then
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_TAX_MISMATCH', 'message', 'the stored tax per code differs from the tax computed from the lines; the stored amounts were kept', 'computed', v_computed, 'given', v_given));
    end if;
    delete from "better_supabase"."invoice_tax_lines" y where y."invoice_id" = v_id;
    insert into "better_supabase"."invoice_tax_lines" ("tenant_id", "invoice_id", "tax_rate_bps", "tax_code", "tax_code_id", "net", "tax", "gross", "discount", "show_tax")
    select v_tenant, v_id, coalesce((g.value ->> 'taxRateBps')::integer, 0), nullif(g.value ->> 'taxCode', ''), nullif(g.value ->> 'taxCodeId', '')::uuid,
      (g.value ->> 'net')::bigint, (g.value ->> 'tax')::bigint,
      coalesce((g.value ->> 'gross')::bigint, (g.value ->> 'net')::bigint + (g.value ->> 'tax')::bigint),
      coalesce((g.value ->> 'discount')::bigint, 0), coalesce((g.value ->> 'showTax')::boolean, true)
    from jsonb_array_elements(v_data -> 'taxLines') g;
  end if;
  if jsonb_typeof(v_data -> 'totals') = 'object' then
    select * into v_row from "better_supabase"."invoices" x where x."id" = v_id;
    if (v_data -> 'totals' ->> 'subtotal' is not null and (v_data -> 'totals' ->> 'subtotal')::bigint <> v_row."subtotal")
      or (v_data -> 'totals' ->> 'tax' is not null and (v_data -> 'totals' ->> 'tax')::bigint <> v_row."tax_total")
      or (v_data -> 'totals' ->> 'total' is not null and (v_data -> 'totals' ->> 'total')::bigint <> v_row."total") then
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_TOTALS_MISMATCH', 'message', 'the stored totals differ from the totals computed from the lines; the stored totals were kept',
        'computed', jsonb_build_object('subtotal', v_row."subtotal"::text, 'tax', v_row."tax_total"::text, 'total', v_row."total"::text),
        'given', v_data -> 'totals'));
    end if;
    update "better_supabase"."invoices" x set
      "subtotal" = coalesce((v_data -> 'totals' ->> 'subtotal')::bigint, x."subtotal"),
      "tax_total" = coalesce((v_data -> 'totals' ->> 'tax')::bigint, x."tax_total"),
      "total" = coalesce((v_data -> 'totals' ->> 'total')::bigint, x."total")
    where x."id" = v_id;
  end if;
  if coalesce(v_data ->> 'settlement', 'payments') = 'row' then
    update "better_supabase"."invoices" x set
      "paid_total" = coalesce((v_data -> 'settlement' ->> 'paidCents')::bigint, x."paid_total"),
      "paid_at" = coalesce((v_data -> 'settlement' ->> 'paidOn')::timestamptz, x."paid_at"),
      "status" = case v_data -> 'settlement' ->> 'state'
        when 'paid' then 'paid'
        when 'partially_paid' then 'partially_paid'
        when 'open' then 'issued'
        else x."status"
      end
    where x."id" = v_id;
  elsif jsonb_typeof(v_data -> 'payments') = 'array' and jsonb_array_length(v_data -> 'payments') > 0 then
    if v_credit or v_status = 'draft' then
      raise exception 'only an issued invoice takes payments' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
    select * into v_row from "better_supabase"."invoices" x where x."id" = v_id;
    for v_pay in select p.value from jsonb_array_elements(v_data -> 'payments') p loop
      v_index := v_index + 1;
      perform "better_supabase"."record_invoice_payment"(
        v_id, (v_pay ->> 'amount')::bigint, upper(coalesce(v_pay ->> 'currency', v_row."currency")),
        (v_pay ->> 'paidAt')::timestamptz, coalesce(nullif(v_pay ->> 'method', ''), 'import'),
        coalesce(nullif(v_pay ->> 'reference', ''), import_invoice_document.item ->> 'key' || ':payment:' || v_index::text),
        nullif(v_pay ->> 'note', ''), null, null);
    end loop;
    update "better_supabase"."invoices" x set "paid_at" = (select max((p.value ->> 'paidAt')::timestamptz) from jsonb_array_elements(v_data -> 'payments') p)
    where x."id" = v_id and x."paid_at" is not null and jsonb_typeof(v_data -> 'payments') = 'array';
  end if;
  if nullif(v_data ->> 'paymentTermCode', '') is not null then
    update "better_supabase"."invoices" x set "payment_terms_id" = (
      select z."id" from "better_supabase"."payment_terms" z
      where z."tenant_id" = v_tenant and z."code" = v_data ->> 'paymentTermCode'
      limit 1
    )
    where x."id" = v_id;
  end if;
  update "better_supabase"."invoice_lines" l set "tax_code" = (
    select min(c."code") from "better_supabase"."tax_codes" c
    join "better_supabase"."tax_rates" r on r."tax_code_id" = c."id"
    where c."tenant_id" = v_tenant and r."rate_bps" = l."tax_rate_bps"
    having count(distinct c."id") = 1
  )
  where l."parent_id" = v_id and l."tax_code" is null;
  if exists (
    select 1 from "better_supabase"."invoice_lines" l
    where l."parent_id" = v_id and l."tax_code" is null and l."tax_rate_bps" is not null
      and (
        select count(distinct c."id") from "better_supabase"."tax_codes" c
        join "better_supabase"."tax_rates" r on r."tax_code_id" = c."id"
        where c."tenant_id" = v_tenant and r."rate_bps" = l."tax_rate_bps"
      ) > 1
  ) then
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_TAX_CODE_AMBIGUOUS', 'message', 'a tax rate matches more than one tax code'));
  end if;
  if v_status = 'void' then
    perform "better_supabase"."void_invoice"(v_id, coalesce(nullif(v_data ->> 'voidReason', ''), 'imported as void'));
  elsif v_status = 'uncollectible' then
    perform "better_supabase"."write_off_invoice"(v_id, nullif(v_data ->> 'writeOffReason', ''));
  end if;
  select * into v_row from "better_supabase"."invoices" x where x."id" = v_id;
  if v_status in ('partially_paid', 'paid') and v_row."status"::text <> v_status then
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_STATUS_MISMATCH', 'message', 'the payments give the status ' || v_row."status"::text || ', not ' || v_status, 'status', v_row."status"::text));
  end if;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_row."updated_at", 'warnings', v_warnings);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_medication (
  tenant uuid,
  item   jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_medication "better_supabase"."medications"%rowtype;
  v_name text;
  v_med_unit text;
  v_system text;
  v_code text;
  v_form text;
  v_strength text;
  v_high_risk boolean;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', import_medication.tenant, 'medications.prescribe'), false)) then
    raise exception 'not allowed to change the medication catalog' using errcode = '42501', hint = 'MEDICATION_FORBIDDEN';
  end if;
  if import_medication.item is null or jsonb_typeof(import_medication.item) <> 'object' then
    raise exception 'a catalog item is an object' using errcode = '22023', hint = 'MEDICATION_INVALID';
  end if;
  v_name := nullif(trim(import_medication.item ->> 'name'), '');
  v_med_unit := nullif(trim(import_medication.item ->> 'unit'), '');
  v_system := coalesce(nullif(trim(import_medication.item ->> 'codeSystem'), ''), 'custom');
  v_code := nullif(trim(import_medication.item ->> 'code'), '');
  v_form := nullif(trim(import_medication.item ->> 'form'), '');
  v_strength := nullif(trim(import_medication.item ->> 'strength'), '');
  v_high_risk := coalesce((import_medication.item ->> 'highRisk')::boolean, false);
  if v_name is null or length(v_name) > 300 then
    raise exception 'a medication needs a name of at most 300 characters' using errcode = '22023', hint = 'MEDICATION_INVALID';
  end if;
  if v_med_unit is null or length(v_med_unit) > 50 then
    raise exception 'a medication needs a unit of at most 50 characters' using errcode = '22023', hint = 'MEDICATION_INVALID';
  end if;
  if v_system is null or v_system not in ('gtin', 'hpk', 'atc', 'rxnorm', 'custom') then
    raise exception 'code_system is gtin, hpk, atc, rxnorm or custom' using errcode = '22023', hint = 'MEDICATION_INVALID';
  end if;
  if v_code is not null and length(v_code) > 100 then
    raise exception 'a code is at most 100 characters' using errcode = '22023', hint = 'MEDICATION_INVALID';
  end if;
  if v_system <> 'custom' and v_code is null then
    raise exception 'a medication from a catalog needs its code' using errcode = '22023', hint = 'MEDICATION_INVALID';
  end if;
  if coalesce(length(v_form), 0) > 100 or coalesce(length(v_strength), 0) > 100 then
    raise exception 'form and strength are at most 100 characters' using errcode = '22023', hint = 'MEDICATION_INVALID';
  end if;
  select * into v_medication from "better_supabase"."medications" x
  where x."tenant_id" = import_medication.tenant and x."code_system" = v_system and x."code" = v_code
  for update;
  if found then
    update "better_supabase"."medications" x set
    "name" = v_name,
    "code_system" = v_system,
    "code" = v_code,
    "form" = v_form,
    "strength" = v_strength,
    "unit" = v_med_unit,
    "high_risk" = v_high_risk,
    "updated_at" = now()
    where x."id" = v_medication."id"
    returning x.* into v_medication;
  else
    insert into "better_supabase"."medications" ("tenant_id", "name", "code_system", "code", "form", "strength", "unit", "high_risk")
    values (import_medication.tenant, v_name, v_system, v_code, v_form, v_strength, v_med_unit, v_high_risk)
    returning * into v_medication;
  end if;
  return jsonb_build_object('id', v_medication."id", 'organizationId', v_medication."tenant_id", 'name', v_medication."name", 'codeSystem', v_medication."code_system", 'code', v_medication."code", 'form', v_medication."form", 'strength', v_medication."strength", 'unit', v_medication."unit", 'highRisk', v_medication."high_risk", 'archivedAt', v_medication."archived_at", 'createdAt', v_medication."created_at", 'updatedAt', v_medication."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_medication_orders (
  tenant uuid,
  items  jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."medication_orders"%rowtype;
  v_medication "better_supabase"."medications"%rowtype;
  v_item jsonb;
  v_external text;
  v_created jsonb := '[]'::jsonb;
  v_skipped integer := 0;
  v_name text;
  v_med_unit text;
  v_system text;
  v_code text;
  v_form text;
  v_strength text;
  v_high_risk boolean;
  v_dose numeric;
  v_unit text;
  v_route text;
  v_schedule jsonb;
  v_as_needed boolean;
  v_as_needed_reason text;
  v_max numeric;
  v_starts date;
  v_ends date;
  v_prescriber text;
  v_double boolean;
begin
  if import_medication_orders.items is null or jsonb_typeof(import_medication_orders.items) <> 'array' then
    raise exception 'items is an array' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
  end if;
  for v_item in select value from jsonb_array_elements(import_medication_orders.items) loop
    if jsonb_typeof(v_item) <> 'object' then
      raise exception 'each item is an object' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
    end if;
    v_external := nullif(trim(v_item ->> 'externalId'), '');
    if v_external is null then
      raise exception 'each imported order needs an externalId' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
    end if;
    if exists (select 1 from "better_supabase"."medication_orders" x where x."tenant_id" = import_medication_orders.tenant and x."external_id" = v_external) then
      v_skipped := v_skipped + 1;
      continue;
    end if;
    if not (case (v_item ->> 'subjectType')
      when 'message' then exists (select 1 from "better_supabase"."messages" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'conversation' then exists (select 1 from "better_supabase"."conversations" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'channel' then exists (select 1 from "better_supabase"."channels" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'company' then exists (select 1 from "better_supabase"."companies" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'person' then exists (select 1 from "better_supabase"."people" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'deal' then exists (select 1 from "better_supabase"."deals" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'course' then exists (select 1 from "better_supabase"."courses" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'post' then exists (select 1 from "better_supabase"."posts" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'activity' then exists (select 1 from "better_supabase"."activities" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'quote' then exists (select 1 from "better_supabase"."quotes" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'work_item' then exists (select 1 from "better_supabase"."work_items" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'employee' then exists (select 1 from "better_supabase"."employees" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'ledger_account' then exists (select 1 from "better_supabase"."ledger_accounts" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'invoice' then exists (select 1 from "better_supabase"."invoices" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'product' then exists (select 1 from "better_supabase"."products" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'product_variant' then exists (select 1 from "better_supabase"."product_variants" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'rfq' then exists (select 1 from "better_supabase"."rfqs" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'till' then exists (select 1 from "better_supabase"."tills" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'order' then exists (select 1 from "better_supabase"."orders" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'calendar_event' then exists (select 1 from "better_supabase"."calendar_events" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'booking' then exists (select 1 from "better_supabase"."bookings" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'asset' then exists (select 1 from "better_supabase"."assets" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'asset_location' then exists (select 1 from "better_supabase"."asset_locations" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'lease' then exists (select 1 from "better_supabase"."leases" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'expense_report' then exists (select 1 from "better_supabase"."expense_reports" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'expense_line' then exists (select 1 from "better_supabase"."expense_lines" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'donation_fund' then exists (select 1 from "better_supabase"."donation_funds" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'warranty_claim' then exists (select 1 from "better_supabase"."warranty_claims" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'work_order' then exists (select 1 from "better_supabase"."work_orders" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'shipment' then exists (select 1 from "better_supabase"."shipments" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'contract' then exists (select 1 from "better_supabase"."contracts" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'control' then exists (select 1 from "better_supabase"."controls" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'compliance_policy' then exists (select 1 from "better_supabase"."compliance_policies" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'qualification_type' then exists (select 1 from "better_supabase"."qualification_types" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'risk' then exists (select 1 from "better_supabase"."risks" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'case' then exists (select 1 from "better_supabase"."cases" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'inspection' then exists (select 1 from "better_supabase"."inspections" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'inspection_program' then exists (select 1 from "better_supabase"."inspection_programs" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'inspection_finding' then exists (select 1 from "better_supabase"."inspection_findings" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'form' then exists (select 1 from "better_supabase"."forms" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'meeting' then exists (select 1 from "better_supabase"."meetings" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'meeting_decision' then exists (select 1 from "better_supabase"."meeting_decisions" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'maintenance_plan' then exists (select 1 from "better_supabase"."maintenance_plans" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'dam_usage_right' then exists (select 1 from "better_supabase"."dam_usage_rights" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'lims_sample' then exists (select 1 from "better_supabase"."lims_samples" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'tax_code' then exists (select 1 from "better_supabase"."tax_codes" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'production_order' then exists (select 1 from "better_supabase"."production_orders" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'work_center' then exists (select 1 from "better_supabase"."work_centers" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'bank_account' then exists (select 1 from "better_supabase"."bank_accounts" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'care_plan' then exists (select 1 from "better_supabase"."care_plans" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'incident' then exists (select 1 from "better_supabase"."incidents" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'content_entry' then exists (select 1 from "better_supabase"."content_entries" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'document' then exists (select 1 from "better_supabase"."documents" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'customer' then exists (select 1 from "public"."customers" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."organization_id"::text = import_medication_orders.tenant::text)
      when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'organization' then exists (select 1 from "public"."organizations" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."id"::text = import_medication_orders.tenant::text)
      when 'application' then exists (select 1 from "better_supabase"."applications" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."tenant_id"::text = import_medication_orders.tenant::text)
      when 'change_request' then exists (select 1 from "public"."change_requests" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."organization_id"::text = import_medication_orders.tenant::text)
      when 'project' then exists (select 1 from "public"."projects" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."organization_id"::text = import_medication_orders.tenant::text)
      when 'task' then exists (select 1 from "public"."tasks" s where s."id" = ((v_item ->> 'subjectId'))::uuid and s."organization_id"::text = import_medication_orders.tenant::text)
      else false
    end and "better_supabase"."can_subject"((v_item ->> 'subjectType'), (v_item ->> 'subjectId'), 'read')) then
      raise exception 'the record isn''t in this organization' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
    end if;
    if jsonb_typeof(v_item -> 'medication') = 'object' then
      v_name := nullif(trim((v_item -> 'medication') ->> 'name'), '');
  v_med_unit := nullif(trim((v_item -> 'medication') ->> 'unit'), '');
  v_system := coalesce(nullif(trim((v_item -> 'medication') ->> 'codeSystem'), ''), 'custom');
  v_code := nullif(trim((v_item -> 'medication') ->> 'code'), '');
  v_form := nullif(trim((v_item -> 'medication') ->> 'form'), '');
  v_strength := nullif(trim((v_item -> 'medication') ->> 'strength'), '');
  v_high_risk := coalesce(((v_item -> 'medication') ->> 'highRisk')::boolean, false);
  if v_name is null or length(v_name) > 300 then
    raise exception 'a medication needs a name of at most 300 characters' using errcode = '22023', hint = 'MEDICATION_INVALID';
  end if;
  if v_med_unit is null or length(v_med_unit) > 50 then
    raise exception 'a medication needs a unit of at most 50 characters' using errcode = '22023', hint = 'MEDICATION_INVALID';
  end if;
  if v_system is null or v_system not in ('gtin', 'hpk', 'atc', 'rxnorm', 'custom') then
    raise exception 'code_system is gtin, hpk, atc, rxnorm or custom' using errcode = '22023', hint = 'MEDICATION_INVALID';
  end if;
  if v_code is not null and length(v_code) > 100 then
    raise exception 'a code is at most 100 characters' using errcode = '22023', hint = 'MEDICATION_INVALID';
  end if;
  if v_system <> 'custom' and v_code is null then
    raise exception 'a medication from a catalog needs its code' using errcode = '22023', hint = 'MEDICATION_INVALID';
  end if;
  if coalesce(length(v_form), 0) > 100 or coalesce(length(v_strength), 0) > 100 then
    raise exception 'form and strength are at most 100 characters' using errcode = '22023', hint = 'MEDICATION_INVALID';
  end if;
  select * into v_medication from "better_supabase"."medications" x
  where x."tenant_id" = import_medication_orders.tenant and x."code_system" = v_system and x."code" = v_code
  for update;
  if found then
    update "better_supabase"."medications" x set
    "name" = v_name,
    "code_system" = v_system,
    "code" = v_code,
    "form" = v_form,
    "strength" = v_strength,
    "unit" = v_med_unit,
    "high_risk" = v_high_risk,
    "updated_at" = now()
    where x."id" = v_medication."id"
    returning x.* into v_medication;
  else
    insert into "better_supabase"."medications" ("tenant_id", "name", "code_system", "code", "form", "strength", "unit", "high_risk")
    values (import_medication_orders.tenant, v_name, v_system, v_code, v_form, v_strength, v_med_unit, v_high_risk)
    returning * into v_medication;
  end if;
    else
      select * into v_medication from "better_supabase"."medications" x
      where x."id" = (v_item ->> 'medicationId')::uuid and x."tenant_id" = import_medication_orders.tenant;
      if not found then
        raise exception 'medication not found' using errcode = 'P0002', hint = 'MEDICATION_NOT_FOUND';
      end if;
    end if;
    v_dose := case when v_item ? 'dose' then ((v_item -> 'dose') #>> '{}')::numeric else null end;
  v_unit := case when v_item ? 'doseUnit' then nullif(trim((v_item -> 'doseUnit') #>> '{}'), '') else v_medication."unit" end;
  v_route := case when v_item ? 'route' then nullif(trim((v_item -> 'route') #>> '{}'), '') else null end;
  v_schedule := case when v_item ? 'schedule' then nullif((v_item -> 'schedule'), 'null'::jsonb) else null end;
  v_as_needed := coalesce(case when v_item ? 'asNeeded' then ((v_item -> 'asNeeded') #>> '{}')::boolean else null end, false);
  v_as_needed_reason := case when v_item ? 'asNeededReason' then nullif(trim((v_item -> 'asNeededReason') #>> '{}'), '') else null end;
  v_max := case when v_item ? 'maxPerDay' then ((v_item -> 'maxPerDay') #>> '{}')::numeric else null end;
  v_starts := case when v_item ? 'startsOn' then ((v_item -> 'startsOn') #>> '{}')::date else (now() at time zone 'UTC')::date end;
  v_ends := case when v_item ? 'endsOn' then ((v_item -> 'endsOn') #>> '{}')::date else null end;
  v_prescriber := case when v_item ? 'prescriber' then nullif(trim((v_item -> 'prescriber') #>> '{}'), '') else null end;
  v_double := coalesce(case when v_item ? 'requiresDoubleCheck' then ((v_item -> 'requiresDoubleCheck') #>> '{}')::boolean else null end, false);
    if v_dose is null or v_dose <= 0 then
    raise exception 'an order needs a dose above zero' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
  end if;
  if v_unit is null or length(v_unit) > 50 then
    raise exception 'an order needs a dose unit of at most 50 characters' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
  end if;
  if v_route is not null and length(v_route) > 100 then
    raise exception 'route is at most 100 characters' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
  end if;
  if not v_as_needed and v_schedule is null then
    raise exception 'an order needs a schedule unless it is given as needed' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
  end if;
  if v_schedule is not null then
    if jsonb_typeof(v_schedule) <> 'object' or not (v_schedule ? 'times' or v_schedule ? 'everyHours') then
      raise exception 'a schedule is an object with times or everyHours' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
    end if;
    if v_schedule ? 'times' and (jsonb_typeof(v_schedule -> 'times') <> 'array' or jsonb_array_length(v_schedule -> 'times') = 0 or exists (
      select 1 from jsonb_array_elements(v_schedule -> 'times') t
      where jsonb_typeof(t) <> 'string' or (t #>> '{}') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    )) then
      raise exception 'schedule times are HH:MM strings' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
    end if;
    if v_schedule ? 'everyHours' and (jsonb_typeof(v_schedule -> 'everyHours') <> 'number' or (v_schedule ->> 'everyHours') !~ '^[0-9]+$' or (v_schedule ->> 'everyHours')::integer not between 1 and 24) then
      raise exception 'schedule everyHours is a whole number of hours from 1 to 24' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
    end if;
    if v_schedule ? 'startTime' and (jsonb_typeof(v_schedule -> 'startTime') <> 'string' or (v_schedule ->> 'startTime') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$') then
      raise exception 'schedule startTime is an HH:MM string' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
    end if;
    if v_schedule ? 'weekdays' and (jsonb_typeof(v_schedule -> 'weekdays') <> 'array' or exists (
      select 1 from jsonb_array_elements(v_schedule -> 'weekdays') d
      where jsonb_typeof(d) <> 'number' or (d #>> '{}') !~ '^[1-7]$'
    )) then
      raise exception 'schedule weekdays are 1 (Monday) to 7 (Sunday)' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
    end if;
  end if;
  if v_as_needed_reason is not null and length(v_as_needed_reason) > 500 then
    raise exception 'asNeededReason is at most 500 characters' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
  end if;
  if v_max is not null and v_max <= 0 then
    raise exception 'maxPerDay is above zero' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
  end if;
  if v_starts is null then
    raise exception 'an order needs a start date' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
  end if;
  if v_ends is not null and v_ends < v_starts then
    raise exception 'an order ends on or after its start date' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
  end if;
  if v_prescriber is not null and length(v_prescriber) > 300 then
    raise exception 'prescriber is at most 300 characters' using errcode = '22023', hint = 'MEDICATION_ORDER_INVALID';
  end if;
    
    insert into "better_supabase"."medication_orders" ("tenant_id", "subject_type", "subject_id", "medication_id", "dose", "dose_unit", "route", "schedule", "as_needed", "as_needed_reason", "max_per_day", "starts_on", "ends_on", "prescriber", "source", "external_id", "requires_double_check", "created_by")
    values (import_medication_orders.tenant, v_item ->> 'subjectType', v_item ->> 'subjectId', v_medication."id", v_dose, v_unit, v_route, v_schedule, v_as_needed, v_as_needed_reason, v_max, v_starts, v_ends, v_prescriber, coalesce(nullif(v_item ->> 'source', ''), 'import'), v_external, v_double, (select auth.uid()))
    returning * into v_row;
    perform "better_supabase".emit_event('medication_order.created', jsonb_build_object('organizationId', v_row."tenant_id", 'medicationOrderId', v_row."id", 'medicationId', v_row."medication_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status"), 'medication-orders/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/medications');
  perform better_supabase.audit_event(
    event_type => 'medication_order.created',
    category => 'data',
    target_type => 'medication_order',
    record_id => v_row."id"::text,
    summary => 'Medication prescribed',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'medicationOrderId', v_row."id", 'medicationId', v_row."medication_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status")
  );
    v_created := v_created || jsonb_build_array(jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'medicationId', v_row."medication_id", 'dose', v_row."dose", 'doseUnit', v_row."dose_unit", 'route', v_row."route", 'schedule', v_row."schedule", 'asNeeded', v_row."as_needed", 'asNeededReason', v_row."as_needed_reason", 'maxPerDay', v_row."max_per_day", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'prescriber', v_row."prescriber", 'source', v_row."source", 'externalId', v_row."external_id", 'requiresDoubleCheck', v_row."requires_double_check", 'status', v_row."status", 'stoppedReason', v_row."stopped_reason", 'signatureId', v_row."signature_id", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at"));
  end loop;
  return jsonb_build_object('created', v_created, 'skipped', v_skipped);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_meter_reading (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_meter_reading.item ->> 'tenant')::uuid;
  v_data jsonb := import_meter_reading.item -> 'data';
  v_asset uuid;
  v_value numeric;
  v_at timestamptz;
  v_previous numeric;
  v_reason text;
  v_id uuid;
  v_warning boolean := false;
begin
  begin
    v_asset := nullif(v_data ->> 'assetId', '')::uuid;
    v_value := (v_data ->> 'value')::numeric;
    v_at := coalesce((v_data ->> 'readAt')::timestamptz, (v_data ->> 'orderBy')::timestamptz, now());
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'assetId is a uuid and value is a number' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  if v_asset is null or v_value is null or nullif(v_data ->> 'unit', '') is null then
    raise exception 'a meter reading needs an assetId, a unit and a value' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if not exists (select 1 from "better_supabase"."assets" a where a."id" = v_asset and a."tenant_id" = v_tenant) then
    raise exception 'the asset is not in this organization' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  select r."value" into v_previous from "better_supabase".asset_meter_readings r
  where r."tenant_id" = v_tenant and r."asset_id" = v_asset and r."unit" = v_data ->> 'unit' and r."read_at" < v_at
  order by r."read_at" desc limit 1;
  v_reason := nullif(v_data ->> 'reason', '');
  if v_previous is not null and v_value < v_previous then
    v_reason := coalesce(v_reason, 'import');
    v_warning := true;
  end if;
  if import_meter_reading.subject_id is null then
    insert into "better_supabase".asset_meter_readings ("tenant_id", "asset_id", "unit", "value", "read_at", "reason")
    values (v_tenant, v_asset, v_data ->> 'unit', v_value, v_at, v_reason)
    returning "id" into v_id;
  else
    update "better_supabase".asset_meter_readings r set "value" = v_value, "read_at" = v_at, "reason" = v_reason
    where r."id" = import_meter_reading.subject_id::uuid and r."tenant_id" = v_tenant
    returning r."id" into v_id;
    if v_id is null then
      raise exception 'the meter reading no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  return jsonb_build_object(
    'subjectId', v_id::text,
    'updatedAt', now(),
    'warnings', case when v_warning then jsonb_build_array(jsonb_build_object(
      'code', 'IMPORT_SERIES_DECREASE',
      'message', 'the reading is below the previous one and was stored with reason import'
    )) else '[]'::jsonb end
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_note_issue (
  run     uuid,
  entity  text,
  key     text,
  kind    text,
  code    text,
  message text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_source text;
begin
  select r."tenant_id", r."source" into v_tenant, v_source
  from "better_supabase"."import_runs" r where r."id" = import_note_issue.run;
  if v_tenant is null or import_note_issue.key is null or import_note_issue.key = '' then
    return;
  end if;
  insert into "better_supabase".import_run_issues ("run_id", "tenant_id", "source", "entity", "key", "kind", "code", "message")
  values (import_note_issue.run, v_tenant, v_source, import_note_issue.entity, import_note_issue.key, import_note_issue.kind, import_note_issue.code, import_note_issue.message);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_note_warnings (
  run      uuid,
  entity   text,
  warnings jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_warning jsonb;
begin
  if jsonb_typeof(import_note_warnings.warnings) is distinct from 'array' then
    return;
  end if;
  for v_warning in select value from jsonb_array_elements(import_note_warnings.warnings) loop
    perform "better_supabase"."import_note_issue"(
      import_note_warnings.run,
      import_note_warnings.entity,
      coalesce(v_warning ->> 'key', ''),
      'warning',
      coalesce(v_warning ->> 'code', 'IMPORT_WARNING'),
      coalesce(v_warning ->> 'message', '')
    );
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_open_item (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_data jsonb := import_open_item.item -> 'data';
  v_balance bigint;
begin
  if jsonb_typeof(v_data) is distinct from 'object' or coalesce(v_data ->> 'balance', '') !~ '^[0-9]{1,18}$' or (v_data ->> 'balance')::bigint = 0 then
    raise exception 'an open item has a positive integer balance in minor units' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if coalesce(v_data ->> 'side', 'customer') not in ('customer', 'supplier') then
    raise exception 'side is customer or supplier' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  v_balance := (v_data ->> 'balance')::bigint;
  return "better_supabase"."import_invoice_document"(jsonb_set(import_open_item.item, '{data}', jsonb_strip_nulls(jsonb_build_object(
    'number', v_data -> 'number', 'status', 'issued', 'issuedOn', v_data -> 'issuedOn', 'dueOn', v_data -> 'dueOn',
    'currency', v_data -> 'currency', 'company', v_data -> 'company', 'contact', v_data -> 'contact',
    'legalEntityId', v_data -> 'legalEntityId',
    'direction', case when v_data ->> 'side' = 'supplier' then 'purchase' else 'sales' end,
    'title', coalesce(nullif(v_data ->> 'title', ''), replace('Opening balance {number}', '{number}', coalesce(v_data ->> 'number', ''))),
    'lines', jsonb_build_array(jsonb_build_object('description', replace('Opening balance {number}', '{number}', coalesce(v_data ->> 'number', '')),
      'quantity', 1, 'unitAmount', v_balance, 'taxRateBps', 0)),
    'totals', jsonb_build_object('subtotal', v_balance, 'tax', 0, 'total', v_balance)))),
    import_open_item.subject_id, false);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_order (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_order.item ->> 'tenant')::uuid;
  v_data jsonb := import_order.item -> 'data';
  v_number text := nullif(btrim(v_data ->> 'number'), '');
  v_seq bigint;
  v_id uuid;
  v_inclusive boolean := coalesce((v_data ->> 'taxInclusive')::boolean, false);
  v_subtotal bigint;
  v_discount bigint;
  v_tax bigint;
  v_shipping bigint;
  v_total bigint;
  v_paid bigint := 0;
  v_paid_at timestamptz;
  v_given jsonb := v_data -> 'totals';
  v_warnings jsonb := '[]'::jsonb;
  v_updated timestamptz;
  v_pay jsonb;
  v_index integer := 0;
begin
  if import_order.subject_id is not null then
    select x."updated_at" into v_updated from "better_supabase"."orders" x where x."id" = import_order.subject_id::uuid and x."tenant_id" = v_tenant;
    if not found then
      raise exception 'the order no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
    if coalesce(v_data ->> 'update', 'keep') is distinct from 'apply' then
      return jsonb_build_object('subjectId', import_order.subject_id, 'updatedAt', v_updated, 'warnings', jsonb_build_array(jsonb_build_object('code', 'IMPORT_DOCUMENT_CHANGED', 'message', 'the source order changed after it was imported; an imported order is kept as imported')));
    end if;
    v_id := import_order.subject_id::uuid;
    update "better_supabase"."orders" x set
      "status" = case when x."status"::text in ('cancelled', 'paid') and coalesce((v_data ->> 'repost')::boolean, false) = false then x."status" else coalesce(nullif(v_data ->> 'status', ''), x."status"::text) end,
      "customer_id" = coalesce(nullif(v_data ->> 'customerId', '')::uuid, x."customer_id"),
      "currency" = coalesce(nullif(upper(v_data ->> 'currency'), ''), x."currency"),
      "placed_at" = coalesce(nullif(v_data ->> 'placedAt', '')::timestamptz, x."placed_at"),
      "subtotal" = coalesce((v_data -> 'totals' ->> 'subtotal')::bigint, x."subtotal"),
      "tax_total" = coalesce((v_data -> 'totals' ->> 'taxTotal')::bigint, x."tax_total"),
      "total" = coalesce((v_data -> 'totals' ->> 'total')::bigint, x."total")
    where x."id" = v_id;
    if coalesce((v_data ->> 'repost')::boolean, false) or (select x."status"::text from "better_supabase"."orders" x where x."id" = v_id) not in ('cancelled', 'paid') then
      if (select count(*) from "better_supabase"."order_lines" l where l."order_id" = v_id) = jsonb_array_length(coalesce(v_data -> 'lines', '[]'::jsonb)) then
        update "better_supabase"."order_lines" l set
          "title" = coalesce(nullif(e.l ->> 'title', ''), l."title"),
          "tax" = coalesce((e.l ->> 'tax')::bigint, l."tax")
        from jsonb_array_elements(v_data -> 'lines') with ordinality as e(l, n)
        where l."order_id" = v_id and l."position" = e.n::integer;
      elsif jsonb_typeof(v_data -> 'lines') = 'array' then
        delete from "better_supabase"."order_lines" l where l."order_id" = v_id;
        insert into "better_supabase"."order_lines" ("tenant_id", "order_id", "position", "variant_id", "product_id", "sku", "title", "quantity", "unit_amount", "subtotal", "discount", "tax", "total", "requires_shipping", "location_id", "tax_code_id", "unit_cost", "cost_source", "bin_id", "billing_party", "billing_party_id", "billing_account_id")
        select v_tenant, v_id, e.n::integer, nullif(e.l ->> 'variantId', '')::uuid, nullif(e.l ->> 'productId', '')::uuid, coalesce(e.l ->> 'sku', ''), e.l ->> 'title', (e.l ->> 'quantity')::integer, (e.l ->> 'unitAmount')::bigint, coalesce((e.l ->> 'subtotal')::bigint, (e.l ->> 'unitAmount')::bigint * (e.l ->> 'quantity')::bigint), coalesce((e.l ->> 'discount')::bigint, 0), coalesce((e.l ->> 'tax')::bigint, 0), coalesce((e.l ->> 'total')::bigint, (e.l ->> 'unitAmount')::bigint * (e.l ->> 'quantity')::bigint - coalesce((e.l ->> 'discount')::bigint, 0)), coalesce((e.l ->> 'requiresShipping')::boolean, false), nullif(e.l ->> 'locationId', '')::uuid, nullif(e.l ->> 'taxCodeId', '')::uuid, (e.l ->> 'unitCost')::bigint, nullif(e.l ->> 'costSource', ''), nullif(e.l ->> 'binId', '')::uuid, coalesce(nullif(e.l ->> 'billingParty', ''), 'customer'), nullif(e.l ->> 'billingPartyId', ''), nullif(e.l ->> 'billingAccountId', '')::uuid
        from jsonb_array_elements(v_data -> 'lines') with ordinality as e(l, n);
      end if;
    end if;
    select x."updated_at" into v_updated from "better_supabase"."orders" x where x."id" = v_id;
    return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_updated, 'warnings', v_warnings);
  end if;
  if v_number is null then
    raise exception 'an order needs its number' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if coalesce(v_data ->> 'currency', '') !~ '^[A-Za-z]{3}$' then
    raise exception 'currency is an ISO 4217 code' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if jsonb_typeof(v_data -> 'lines') is distinct from 'array' or jsonb_array_length(v_data -> 'lines') = 0 then
    raise exception 'an order needs at least one line' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_data -> 'lines') l
    where coalesce(l.value ->> 'title', '') = '' or coalesce(l.value ->> 'quantity', '') !~ '^[1-9][0-9]{0,8}$' or coalesce(l.value ->> 'unitAmount', '') !~ '^[0-9]{1,18}$'
  ) then
    raise exception 'a line needs a title, a whole quantity above zero and a unitAmount' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_data -> 'lines') l
    where l.value ->> 'billingParty' is not null and l.value ->> 'billingParty' not in ('customer', 'internal', 'own_warranty', 'supplier_warranty', 'cost_account')
      or l.value ->> 'costSource' is not null and l.value ->> 'costSource' not in ('catalog', 'average', 'manual', 'imported')
  ) then
    raise exception 'a line''s billingParty or costSource is not a known value' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;

  select coalesce(sum((l.value ->> 'unitAmount')::bigint * (l.value ->> 'quantity')::bigint), 0),
    coalesce(sum(coalesce((l.value ->> 'discount')::bigint, 0)), 0),
    coalesce(sum(coalesce((l.value ->> 'tax')::bigint, 0)), 0)
  into v_subtotal, v_discount, v_tax
  from jsonb_array_elements(v_data -> 'lines') l;
  v_shipping := coalesce((v_given ->> 'shippingTotal')::bigint, 0);
  v_total := v_subtotal - v_discount + v_shipping + case when v_inclusive then 0 else v_tax end;
  if jsonb_typeof(v_given) = 'object' then
    if coalesce((v_given ->> 'subtotal')::bigint, v_subtotal) <> v_subtotal
      or coalesce((v_given ->> 'discountTotal')::bigint, v_discount) <> v_discount
      or coalesce((v_given ->> 'taxTotal')::bigint, v_tax) <> v_tax
      or coalesce((v_given ->> 'total')::bigint, v_total) <> v_total then
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_TOTALS_MISMATCH', 'message', 'the stored totals differ from the totals computed from the lines; the stored totals were kept',
        'computed', jsonb_build_object('subtotal', v_subtotal::text, 'discountTotal', v_discount::text, 'taxTotal', v_tax::text, 'total', v_total::text),
        'given', v_given));
    end if;
    v_subtotal := coalesce((v_given ->> 'subtotal')::bigint, v_subtotal);
    v_discount := coalesce((v_given ->> 'discountTotal')::bigint, v_discount);
    v_tax := coalesce((v_given ->> 'taxTotal')::bigint, v_tax);
    v_total := coalesce((v_given ->> 'total')::bigint, v_total);
  end if;
  if jsonb_typeof(v_data -> 'payments') = 'array' then
    select coalesce(sum((p.value ->> 'amount')::bigint), 0), max((p.value ->> 'paidAt')::timestamptz)
    into v_paid, v_paid_at from jsonb_array_elements(v_data -> 'payments') p;
  end if;

  if nullif(btrim(v_data ->> 'number'), '') is not null then
    perform set_config('better_supabase.fixed_number', 'order' || chr(31) || btrim(v_data ->> 'number'), true);
  end if;
  if (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'order' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end) is not null then
    v_number := (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'order' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end);
    if better_supabase.import_run() is null then
      raise exception 'a fixed number is only accepted during an import' using errcode = '42501', hint = 'NUMBER_FIXED_FORBIDDEN';
    end if;
    v_seq := coalesce(substring(v_number from '([0-9]+)$')::bigint, 0);
    perform set_config('better_supabase.fixed_number', '', true);
  else
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_tenant::text || ':commerce:order', 0));
  select coalesce(max(x."sequence"), 0) + 1 into v_seq from "better_supabase"."orders" x where x."tenant_id" = v_tenant;
  v_number := v_seq::text;
  end if;
  insert into "better_supabase"."orders" ("tenant_id", "number", "sequence", "customer_id", "email", "status", "currency", "subtotal", "discount_total", "shipping_total", "tax_total", "total", "paid_total", "tax_inclusive", "shipping_address", "billing_address", "tax", "invoice_number", "invoice_sequence", "invoiced_at", "placed_at", "paid_at", "fulfilled_at", "completed_at", "cancelled_at", "cancel_reason", "buyer", legal_entity_id)
  values (v_tenant, v_number, v_seq, nullif(v_data ->> 'customerId', '')::uuid, v_data ->> 'email', coalesce(v_data ->> 'status', 'confirmed'), upper(v_data ->> 'currency'), v_subtotal, v_discount, v_shipping, v_tax, v_total, v_paid, v_inclusive, v_data -> 'shippingAddress', v_data -> 'billingAddress', v_data -> 'taxLines', nullif(v_data ->> 'invoiceNumber', ''), substring(nullif(v_data ->> 'invoiceNumber', '') from '([0-9]+)$')::bigint, nullif(v_data ->> 'invoicedAt', '')::timestamptz, coalesce(nullif(v_data ->> 'placedAt', '')::timestamptz, now()), coalesce(nullif(v_data ->> 'paidAt', '')::timestamptz, v_paid_at), nullif(v_data ->> 'fulfilledAt', '')::timestamptz, nullif(v_data ->> 'completedAt', '')::timestamptz, nullif(v_data ->> 'cancelledAt', '')::timestamptz, nullif(v_data ->> 'cancelReason', ''), case when jsonb_typeof(v_data -> 'buyer') = 'object' then v_data -> 'buyer' end, nullif(v_data ->> 'legalEntityId', '')::uuid)
  returning "id", "updated_at" into v_id, v_updated;

  insert into "better_supabase"."order_lines" ("tenant_id", "order_id", "position", "variant_id", "product_id", "sku", "title", "quantity", "unit_amount", "subtotal", "discount", "tax", "total", "requires_shipping", "location_id", "tax_code_id", "unit_cost", "cost_source", "bin_id", "billing_party", "billing_party_id", "billing_account_id")
  select v_tenant, v_id, e.n::integer, nullif(e.l ->> 'variantId', '')::uuid, nullif(e.l ->> 'productId', '')::uuid, coalesce(e.l ->> 'sku', ''), e.l ->> 'title', (e.l ->> 'quantity')::integer, (e.l ->> 'unitAmount')::bigint, coalesce((e.l ->> 'subtotal')::bigint, (e.l ->> 'unitAmount')::bigint * (e.l ->> 'quantity')::bigint), coalesce((e.l ->> 'discount')::bigint, 0), coalesce((e.l ->> 'tax')::bigint, 0), coalesce((e.l ->> 'total')::bigint, (e.l ->> 'unitAmount')::bigint * (e.l ->> 'quantity')::bigint - coalesce((e.l ->> 'discount')::bigint, 0)), coalesce((e.l ->> 'requiresShipping')::boolean, false), nullif(e.l ->> 'locationId', '')::uuid, nullif(e.l ->> 'taxCodeId', '')::uuid, (e.l ->> 'unitCost')::bigint, nullif(e.l ->> 'costSource', ''), nullif(e.l ->> 'binId', '')::uuid, coalesce(nullif(e.l ->> 'billingParty', ''), 'customer'), nullif(e.l ->> 'billingPartyId', ''), nullif(e.l ->> 'billingAccountId', '')::uuid
  from jsonb_array_elements(v_data -> 'lines') with ordinality as e(l, n);

  if jsonb_typeof(v_data -> 'payments') = 'array' then
    for v_pay in select e.value from jsonb_array_elements(v_data -> 'payments') e loop
      v_index := v_index + 1;
      insert into "better_supabase"."order_payments" ("tenant_id", "order_id", "provider", "reference", "status", "currency", "amount", "captured", "refunded", "created_at", "updated_at")
      values (v_tenant, v_id, coalesce(nullif(v_pay ->> 'provider', ''), 'import'),
        coalesce(nullif(v_pay ->> 'reference', ''), import_order.item ->> 'key' || ':payment:' || v_index::text),
        'succeeded', upper(v_data ->> 'currency'), (v_pay ->> 'amount')::bigint, (v_pay ->> 'amount')::bigint, 0,
        coalesce(nullif(v_pay ->> 'paidAt', '')::timestamptz, now()), coalesce(nullif(v_pay ->> 'paidAt', '')::timestamptz, now()));
    end loop;
  end if;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_updated, 'warnings', v_warnings);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_organization_profile (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_data jsonb := import_organization_profile.item -> 'data';
  v_tenant uuid := (import_organization_profile.item ->> 'tenant')::uuid;
  v_vat text := nullif(upper(btrim(v_data ->> 'vatId')), '');
  v_warnings jsonb := '[]'::jsonb;
  v_account jsonb;
  v_iban text;
  v_primary boolean;
  v_id uuid;
  v_updated timestamptz;
begin
  if jsonb_typeof(v_data) is distinct from 'object' then
    raise exception 'an organization profile needs data' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_vat ~ '^[A-Z]{2}$' then
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_VAT_PREFIX', 'message', 'a VAT number that is only a country prefix was skipped'));
    v_vat := null;
  end if;
  insert into "better_supabase"."organization_profiles" ("tenant_id") values (v_tenant) on conflict ("tenant_id") do nothing;
  if exists (
    select 1 from "better_supabase"."organization_profiles" x
    where x."tenant_id" = v_tenant
      and (v_vat is null or x."vat_id" is not distinct from v_vat)
      and (v_data ->> 'registrationId' is null or x."registration_id" is not distinct from nullif(btrim(v_data ->> 'registrationId'), ''))
      and (v_data ->> 'defaultRate' is null or x."default_rate" is not distinct from (v_data ->> 'defaultRate')::numeric)
      and (v_data ->> 'currency' is null or x."currency" is not distinct from nullif(btrim(v_data ->> 'currency'), ''))
  ) then
    v_updated := (select x."updated_at" from "better_supabase"."organization_profiles" x where x."tenant_id" = v_tenant);
  else
    update "better_supabase"."organization_profiles" x set
      "vat_id" = coalesce(v_vat, x."vat_id"),
      "registration_id" = coalesce(nullif(btrim(v_data ->> 'registrationId'), ''), x."registration_id"),
      "default_rate" = coalesce((v_data ->> 'defaultRate')::numeric, x."default_rate"),
      "currency" = coalesce(nullif(btrim(v_data ->> 'currency'), ''), x."currency"),
      "updated_at" = now()
    where x."tenant_id" = v_tenant
    returning x."updated_at" into v_updated;
  end if;
  if jsonb_typeof(v_data -> 'accounts') = 'array' then
    for v_account in select value from jsonb_array_elements(v_data -> 'accounts') loop
      v_iban := upper(regexp_replace(coalesce(v_account ->> 'iban', ''), '\s', '', 'g'));
      if not better_supabase.validate_iban(v_iban) then
        raise exception 'a payment account needs a valid IBAN' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
      end if;
      v_primary := case when v_account ? 'isPrimary' then (v_account ->> 'isPrimary')::boolean else null end;
      select x."id" into v_id from "better_supabase"."organization_payment_accounts" x
      where x."tenant_id" = v_tenant and x."iban" = v_iban
        and x."bic" is not distinct from coalesce(nullif(upper(btrim(v_account ->> 'bic')), ''), x."bic")
        and x."holder" is not distinct from coalesce(nullif(btrim(v_account ->> 'holder'), ''), x."holder")
        and x."label" is not distinct from coalesce(nullif(btrim(v_account ->> 'label'), ''), x."label")
        and (v_primary is null or x."is_primary" = v_primary);
      if v_id is null then
        if v_primary is true then
          update "better_supabase"."organization_payment_accounts" x set "is_primary" = false where x."tenant_id" = v_tenant and x."iban" <> v_iban;
        end if;
        insert into "better_supabase"."organization_payment_accounts" ("tenant_id", "iban", "bic", "holder", "label", "is_primary")
        values (v_tenant, v_iban, nullif(upper(btrim(v_account ->> 'bic')), ''), nullif(btrim(v_account ->> 'holder'), ''),
          nullif(btrim(v_account ->> 'label'), ''), coalesce(v_primary, false))
        on conflict ("tenant_id", "iban") do update set
          "bic" = coalesce(excluded."bic", "better_supabase"."organization_payment_accounts"."bic"),
          "holder" = coalesce(excluded."holder", "better_supabase"."organization_payment_accounts"."holder"),
          "label" = coalesce(excluded."label", "better_supabase"."organization_payment_accounts"."label"),
          "is_primary" = case when v_primary is true then true else "better_supabase"."organization_payment_accounts"."is_primary" end,
          "updated_at" = now();
      end if;
    end loop;
  end if;
  return jsonb_build_object('subjectId', v_tenant, 'updatedAt', coalesce(v_updated, now()), 'warnings', v_warnings);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_oscal_catalog (
  tenant   uuid,
  document jsonb,
  key      text  DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_tenant uuid := import_oscal_catalog.tenant;
  v_catalog jsonb;
  v_key text;
  v_title text;
  v_version text;
  v_framework "better_supabase"."control_frameworks"%rowtype;
  v_ctl jsonb;
  v_code text;
  v_ctl_title text;
  v_prose text;
  v_count integer := 0;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_tenant, 'compliance.manage'), false)) then
    raise exception 'not allowed to manage controls' using errcode = '42501', hint = 'CONTROL_FORBIDDEN';
  end if;
  if import_oscal_catalog.document is null or jsonb_typeof(import_oscal_catalog.document -> 'catalog') is distinct from 'object' then
    raise exception 'the document needs a catalog object' using errcode = '22023', hint = 'OSCAL_INVALID';
  end if;
  v_catalog := import_oscal_catalog.document -> 'catalog';
  v_title := nullif(trim(v_catalog #>> '{metadata,title}'), '');
  if v_title is null then
    raise exception 'the catalog needs a metadata title' using errcode = '22023', hint = 'OSCAL_INVALID';
  end if;
  v_version := nullif(trim(v_catalog #>> '{metadata,version}'), '');
  v_key := coalesce(nullif(trim(import_oscal_catalog.key), ''), 'oscal-' || lower(left(replace(coalesce(v_catalog ->> 'uuid', ''), '-', ''), 12)));
  if v_key !~ '^[a-z0-9][a-z0-9_.-]{0,62}$' then
    raise exception 'key must be lowercase letters, digits, dots, dashes or underscores' using errcode = '22023', hint = 'OSCAL_INVALID';
  end if;
  insert into "better_supabase"."control_frameworks" ("tenant_id", "key", "name", "kind", "version")
  values (v_tenant, v_key, v_title, 'standard', v_version)
  on conflict ("tenant_id", "key") do update set "name" = excluded."name", "version" = excluded."version", "updated_at" = now()
  returning * into v_framework;
  for v_ctl in
    select c from jsonb_path_query(v_catalog, 'strict $.**.controls[*]') c
  loop
    v_code := left(trim(v_ctl ->> 'id'), 50);
    v_ctl_title := left(trim(v_ctl ->> 'title'), 200);
    if v_code is null or v_code = '' or v_ctl_title is null or v_ctl_title = '' then
      raise exception 'every control needs an id and a title' using errcode = '22023', hint = 'OSCAL_INVALID';
    end if;
    v_prose := left(nullif(trim(jsonb_path_query_first(v_ctl, 'lax $.parts[*] ? (@.name == "statement").prose') #>> '{}'), ''), 10000);
    insert into "better_supabase"."controls" ("tenant_id", "framework_id", "code", "title", "description", "source")
    values (v_tenant, v_framework."id", v_code, v_ctl_title, v_prose, 'oscal')
    on conflict ("framework_id", "code") do update set "title" = excluded."title", "description" = excluded."description", "updated_at" = now();
    v_count := v_count + 1;
  end loop;
  perform "better_supabase".emit_event('control_framework.imported', jsonb_build_object('organizationId', v_framework."tenant_id"::text, 'frameworkId', v_framework."id", 'format', 'oscal-catalog', 'controls', v_count), 'controls/' || v_framework."id"::text, (v_framework."tenant_id")::text, null, 'better-supabase/compliance');
  perform better_supabase.audit_event(
    event_type => 'control_framework.imported',
    category => 'data',
    target_type => 'control_framework',
    record_id => v_framework."id"::text,
    tenant => (v_framework."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_framework."tenant_id"::text, 'frameworkId', v_framework."id", 'format', 'oscal-catalog', 'controls', v_count)
  );
  return jsonb_build_object('frameworkId', v_framework."id", 'key', v_framework."key", 'controls', v_count);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_party (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_data jsonb := import_party.item -> 'data';
  v_tenant uuid := (import_party.item ->> 'tenant')::uuid;
  v_display text := nullif(btrim(v_data ->> 'displayName'), '');
  v_legal text := nullif(btrim(v_data ->> 'legalName'), '');
  v_person text := nullif(btrim(concat_ws(' ', v_data ->> 'givenName', v_data ->> 'infix', v_data ->> 'lastName')), '');
  v_number text := nullif(btrim(v_data ->> 'number'), '');
  v_name text := coalesce(v_display, v_legal, v_person, v_number);
  v_kind text := coalesce(nullif(v_data ->> 'kind', ''), 'auto');
  v_warnings jsonb := '[]'::jsonb;
  v_id uuid;
  v_updated timestamptz;
  v_same boolean;
begin
  if jsonb_typeof(v_data) is distinct from 'object' or v_name is null then
    raise exception 'a party needs a display name, a legal name, a person name or a number' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_display is null then
    v_warnings := jsonb_build_array(jsonb_build_object('code', 'IMPORT_NAME_FALLBACK', 'message', 'the party name came from a fallback'));
  end if;
  if v_kind = 'auto' then
    v_kind := case when v_name ~* '\m(b\.?v\.?|n\.?v\.?|gmbh|ltd\.?|llc|inc\.?|bvba|vof|stichting|holding)\M' then 'company' else 'person' end;
  end if;
  if v_kind = 'company' then
    if import_party.subject_id is not null then
      select x."id", x."updated_at", x."name" is not distinct from v_name and x."legal_name" is not distinct from coalesce(v_legal, v_name) and x."vat_id" is not distinct from nullif(btrim(v_data ->> 'vatId'), '') and x."registration_id" is not distinct from nullif(btrim(v_data ->> 'registrationId'), '') and x."phone" is not distinct from better_supabase.normalize_phone(v_data ->> 'phone', v_data ->> 'region') and x."billing_email" is not distinct from nullif(lower(btrim(v_data ->> 'billingEmail')), '') and x."bill_to_id" is not distinct from nullif(coalesce(import_party.item -> 'resolved' ->> 'billTo', v_data ->> 'billToId'), '')::uuid and x."lifecycle" is not distinct from coalesce(nullif(v_data ->> 'lifecycle', ''), ('{lead,prospect,customer,churned}'::text[])[1]) and x."language" is not distinct from nullif(btrim(v_data ->> 'language'), '') and x."roles" is not distinct from case when jsonb_typeof(v_data -> 'roles') = 'array' then (select coalesce(array_agg(r), '{}'::text[]) from jsonb_array_elements_text(v_data -> 'roles') r) else null end and x."customer_terms_id" is not distinct from (select p."id" from "better_supabase"."payment_terms" p where p."tenant_id" = v_tenant and p."code" = nullif(btrim(v_data ->> 'termsCode'), '')) and x."archived_at" is not distinct from nullif(v_data ->> 'archivedAt', '')::timestamptz into v_id, v_updated, v_same
      from "better_supabase"."companies" x
      where x."id" = import_party.subject_id::uuid and x."tenant_id" = v_tenant;
      if v_id is not null and v_same then
        return jsonb_build_object('subjectId', v_id, 'updatedAt', v_updated, 'warnings', v_warnings);
      end if;
      update "better_supabase"."companies" x set "name" = v_name, "legal_name" = coalesce(v_legal, v_name), "vat_id" = nullif(btrim(v_data ->> 'vatId'), ''), "registration_id" = nullif(btrim(v_data ->> 'registrationId'), ''), "phone" = better_supabase.normalize_phone(v_data ->> 'phone', v_data ->> 'region'), "billing_email" = nullif(lower(btrim(v_data ->> 'billingEmail')), ''), "bill_to_id" = nullif(coalesce(import_party.item -> 'resolved' ->> 'billTo', v_data ->> 'billToId'), '')::uuid, "lifecycle" = coalesce(nullif(v_data ->> 'lifecycle', ''), ('{lead,prospect,customer,churned}'::text[])[1]), "language" = nullif(btrim(v_data ->> 'language'), ''), "roles" = case when jsonb_typeof(v_data -> 'roles') = 'array' then (select coalesce(array_agg(r), '{}'::text[]) from jsonb_array_elements_text(v_data -> 'roles') r) else null end, "customer_terms_id" = (select p."id" from "better_supabase"."payment_terms" p where p."tenant_id" = v_tenant and p."code" = nullif(btrim(v_data ->> 'termsCode'), '')), "archived_at" = nullif(v_data ->> 'archivedAt', '')::timestamptz, "updated_at" = now()
      where x."id" = import_party.subject_id::uuid and x."tenant_id" = v_tenant
      returning x."id", x."updated_at" into v_id, v_updated;
    end if;
    if v_id is null then
      insert into "better_supabase"."companies" ("tenant_id", "name", "legal_name", "vat_id", "registration_id", "phone", "billing_email", "bill_to_id", "lifecycle", "language", "roles", "customer_terms_id", "archived_at")
      values (v_tenant, v_name, coalesce(v_legal, v_name), nullif(btrim(v_data ->> 'vatId'), ''), nullif(btrim(v_data ->> 'registrationId'), ''), better_supabase.normalize_phone(v_data ->> 'phone', v_data ->> 'region'), nullif(lower(btrim(v_data ->> 'billingEmail')), ''), nullif(coalesce(import_party.item -> 'resolved' ->> 'billTo', v_data ->> 'billToId'), '')::uuid, coalesce(nullif(v_data ->> 'lifecycle', ''), ('{lead,prospect,customer,churned}'::text[])[1]), nullif(btrim(v_data ->> 'language'), ''), case when jsonb_typeof(v_data -> 'roles') = 'array' then (select coalesce(array_agg(r), '{}'::text[]) from jsonb_array_elements_text(v_data -> 'roles') r) else null end, (select p."id" from "better_supabase"."payment_terms" p where p."tenant_id" = v_tenant and p."code" = nullif(btrim(v_data ->> 'termsCode'), '')), nullif(v_data ->> 'archivedAt', '')::timestamptz)
      returning "id", "updated_at" into v_id, v_updated;
    end if;
  elsif v_kind = 'person' then
    if import_party.subject_id is not null then
      select x."id", x."updated_at", x."name" is not distinct from v_name and x."given_name" is not distinct from nullif(btrim(v_data ->> 'givenName'), '') and x."last_name" is not distinct from nullif(btrim(v_data ->> 'lastName'), '') and x."initials" is not distinct from nullif(btrim(v_data ->> 'initials'), '') and x."infix" is not distinct from nullif(btrim(v_data ->> 'infix'), '') and x."email" is not distinct from nullif(lower(btrim(v_data ->> 'email')), '') and x."phone" is not distinct from better_supabase.normalize_phone(v_data ->> 'phone', v_data ->> 'region') and x."lifecycle" is not distinct from coalesce(nullif(v_data ->> 'lifecycle', ''), ('{lead,mql,sql,opportunity,customer}'::text[])[1]) and x."language" is not distinct from nullif(btrim(v_data ->> 'language'), '') and x."roles" is not distinct from case when jsonb_typeof(v_data -> 'roles') = 'array' then (select coalesce(array_agg(r), '{}'::text[]) from jsonb_array_elements_text(v_data -> 'roles') r) else null end and x."archived_at" is not distinct from nullif(v_data ->> 'archivedAt', '')::timestamptz into v_id, v_updated, v_same
      from "better_supabase"."people" x
      where x."id" = import_party.subject_id::uuid and x."tenant_id" = v_tenant;
      if v_id is not null and v_same then
        return jsonb_build_object('subjectId', v_id, 'updatedAt', v_updated, 'warnings', v_warnings);
      end if;
      update "better_supabase"."people" x set "name" = v_name, "given_name" = nullif(btrim(v_data ->> 'givenName'), ''), "last_name" = nullif(btrim(v_data ->> 'lastName'), ''), "initials" = nullif(btrim(v_data ->> 'initials'), ''), "infix" = nullif(btrim(v_data ->> 'infix'), ''), "email" = nullif(lower(btrim(v_data ->> 'email')), ''), "phone" = better_supabase.normalize_phone(v_data ->> 'phone', v_data ->> 'region'), "lifecycle" = coalesce(nullif(v_data ->> 'lifecycle', ''), ('{lead,mql,sql,opportunity,customer}'::text[])[1]), "language" = nullif(btrim(v_data ->> 'language'), ''), "roles" = case when jsonb_typeof(v_data -> 'roles') = 'array' then (select coalesce(array_agg(r), '{}'::text[]) from jsonb_array_elements_text(v_data -> 'roles') r) else null end, "archived_at" = nullif(v_data ->> 'archivedAt', '')::timestamptz, "updated_at" = now()
      where x."id" = import_party.subject_id::uuid and x."tenant_id" = v_tenant
      returning x."id", x."updated_at" into v_id, v_updated;
    end if;
    if v_id is null then
      insert into "better_supabase"."people" ("tenant_id", "name", "given_name", "last_name", "initials", "infix", "email", "phone", "lifecycle", "language", "roles", "archived_at")
      values (v_tenant, v_name, nullif(btrim(v_data ->> 'givenName'), ''), nullif(btrim(v_data ->> 'lastName'), ''), nullif(btrim(v_data ->> 'initials'), ''), nullif(btrim(v_data ->> 'infix'), ''), nullif(lower(btrim(v_data ->> 'email')), ''), better_supabase.normalize_phone(v_data ->> 'phone', v_data ->> 'region'), coalesce(nullif(v_data ->> 'lifecycle', ''), ('{lead,mql,sql,opportunity,customer}'::text[])[1]), nullif(btrim(v_data ->> 'language'), ''), case when jsonb_typeof(v_data -> 'roles') = 'array' then (select coalesce(array_agg(r), '{}'::text[]) from jsonb_array_elements_text(v_data -> 'roles') r) else null end, nullif(v_data ->> 'archivedAt', '')::timestamptz)
      returning "id", "updated_at" into v_id, v_updated;
    end if;
  else
    raise exception 'kind is person, company or auto' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  return jsonb_build_object('subjectId', v_id, 'updatedAt', v_updated, 'warnings', v_warnings);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_party_bank_account (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_data jsonb := import_party_bank_account.item -> 'data';
  v_party uuid := nullif(coalesce(import_party_bank_account.item -> 'resolved' ->> 'party', v_data ->> 'partyId'), '')::uuid;
  v_iban text := upper(regexp_replace(coalesce(v_data ->> 'iban', ''), '\s', '', 'g'));
  v_id uuid;
  v_updated timestamptz;
begin
  if v_party is null or not better_supabase.validate_iban(v_iban) then
    raise exception 'a bank account needs a party and a valid IBAN' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  select x."id", x."updated_at" into v_id, v_updated from "better_supabase"."party_bank_accounts" x
  where x."tenant_id" = (import_party_bank_account.item ->> 'tenant')::uuid and x."iban" = v_iban
    and x."bic" is not distinct from nullif(upper(btrim(v_data ->> 'bic')), '')
    and x."holder" is not distinct from nullif(btrim(v_data ->> 'holder'), '')
    and x."is_primary" is not distinct from coalesce((v_data ->> 'isPrimary')::boolean, x."is_primary");
  if v_id is not null then
    return jsonb_build_object('subjectId', v_id, 'updatedAt', v_updated);
  end if;
  insert into "better_supabase"."party_bank_accounts" ("tenant_id", "party_id", "iban", "bic", "holder", "is_primary")
  values ((import_party_bank_account.item ->> 'tenant')::uuid, v_party, v_iban,
    nullif(upper(btrim(v_data ->> 'bic')), ''), nullif(btrim(v_data ->> 'holder'), ''), coalesce((v_data ->> 'isPrimary')::boolean, false))
  on conflict ("tenant_id", "iban") do update
    set "bic" = excluded."bic", "holder" = excluded."holder",
      "is_primary" = coalesce((v_data ->> 'isPrimary')::boolean, "better_supabase"."party_bank_accounts"."is_primary"),
      "updated_at" = now()
  returning "id", "updated_at" into v_id, v_updated;
  return jsonb_build_object('subjectId', v_id, 'updatedAt', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_party_contact (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_data jsonb := import_party_contact.item -> 'data';
  v_company uuid := nullif(coalesce(import_party_contact.item -> 'resolved' ->> 'company', v_data ->> 'companyId'), '')::uuid;
  v_person uuid := nullif(coalesce(import_party_contact.item -> 'resolved' ->> 'person', v_data ->> 'personId'), '')::uuid;
  v_primary boolean := coalesce((v_data ->> 'isPrimary')::boolean, false);
begin
  if v_company is null or v_person is null then
    raise exception 'a party contact needs a company and a person' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if exists (
    select 1 from "better_supabase"."company_people" x
    where x."company_id" = v_company and x."person_id" = v_person
      and x."is_primary" is not distinct from v_primary
      and x."role" is not distinct from nullif(btrim(v_data ->> 'role'), '')
  ) then
    return jsonb_build_object('subjectId', v_company::text || ':' || v_person::text, 'updatedAt',
      (select x."created_at" from "better_supabase"."company_people" x where x."company_id" = v_company and x."person_id" = v_person));
  end if;
  insert into "better_supabase"."company_people" ("tenant_id", "company_id", "person_id", "is_primary", "role")
  values ((import_party_contact.item ->> 'tenant')::uuid, v_company, v_person, v_primary, nullif(btrim(v_data ->> 'role'), ''))
  on conflict ("company_id", "person_id") do update
    set "is_primary" = excluded."is_primary", "role" = nullif(btrim(v_data ->> 'role'), '');
  return jsonb_build_object('subjectId', v_company::text || ':' || v_person::text, 'updatedAt', now());
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_party_discount_group (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_party_discount_group.item ->> 'tenant')::uuid;
  v_data jsonb := import_party_discount_group.item -> 'data';
  v_party text := btrim(coalesce(nullif(v_data ->> 'party', ''), import_party_discount_group.subject_id));
  v_group uuid := nullif(v_data ->> 'groupId', '')::uuid;
  v_code text := nullif(btrim(v_data ->> 'groupCode'), '');
begin
  if v_party is null or length(v_party) not between 1 and 200 then
    raise exception 'a party discount group names the party' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_group is null and v_code is not null then
    select x."id" into v_group
    from "better_supabase"."discount_groups" x
    where x."tenant_id" = v_tenant and x."kind" = 'customer' and x."code" = v_code;
  end if;
  if v_group is null and v_code is not null then
    raise exception 'no customer discount group has this code' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  perform "better_supabase"."set_party_discount_group"(v_tenant, v_party, v_group);
  return jsonb_build_object(
    'subjectId', v_party,
    'updatedAt', (select x."created_at" from "better_supabase"."discount_group_parties" x where x."tenant_id" = v_tenant and x."party_id" = v_party)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_party_location (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_data jsonb := import_party_location.item -> 'data';
  v_party uuid := nullif(coalesce(import_party_location.item -> 'resolved' ->> 'party', v_data ->> 'partyId'), '')::uuid;
  v_id uuid;
  v_updated timestamptz;
  v_same boolean;
begin
  if v_party is null then
    raise exception 'a location needs a party' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if import_party_location.subject_id is not null then
    select x."id", x."updated_at", x."party_id" is not distinct from v_party and x."kind" is not distinct from coalesce(nullif(v_data ->> 'kind', ''), 'other') and x."line1" is not distinct from nullif(btrim(v_data ->> 'line1'), '') and x."line2" is not distinct from nullif(btrim(v_data ->> 'line2'), '') and x."postal_code" is not distinct from nullif(btrim(v_data ->> 'postalCode'), '') and x."city" is not distinct from nullif(btrim(v_data ->> 'city'), '') and x."country" is not distinct from nullif(btrim(v_data ->> 'country'), '') and x."latitude" is not distinct from nullif(v_data ->> 'latitude', '')::double precision and x."longitude" is not distinct from nullif(v_data ->> 'longitude', '')::double precision and x."is_primary" is not distinct from coalesce((v_data ->> 'isPrimary')::boolean, false) into v_id, v_updated, v_same
    from "better_supabase"."party_locations" x
    where x."id" = import_party_location.subject_id::uuid and x."tenant_id" = (import_party_location.item ->> 'tenant')::uuid;
    if v_id is not null and v_same then
      return jsonb_build_object('subjectId', v_id, 'updatedAt', v_updated);
    end if;
    update "better_supabase"."party_locations" x set "party_id" = v_party, "kind" = coalesce(nullif(v_data ->> 'kind', ''), 'other'), "line1" = nullif(btrim(v_data ->> 'line1'), ''), "line2" = nullif(btrim(v_data ->> 'line2'), ''), "postal_code" = nullif(btrim(v_data ->> 'postalCode'), ''), "city" = nullif(btrim(v_data ->> 'city'), ''), "country" = nullif(btrim(v_data ->> 'country'), ''), "latitude" = nullif(v_data ->> 'latitude', '')::double precision, "longitude" = nullif(v_data ->> 'longitude', '')::double precision, "is_primary" = coalesce((v_data ->> 'isPrimary')::boolean, false), "updated_at" = now()
    where x."id" = import_party_location.subject_id::uuid
    returning x."id", x."updated_at" into v_id, v_updated;
  end if;
  if v_id is null then
    insert into "better_supabase"."party_locations" ("tenant_id", "party_id", "kind", "line1", "line2", "postal_code", "city", "country", "latitude", "longitude", "is_primary")
    values ((import_party_location.item ->> 'tenant')::uuid, v_party, coalesce(nullif(v_data ->> 'kind', ''), 'other'), nullif(btrim(v_data ->> 'line1'), ''), nullif(btrim(v_data ->> 'line2'), ''), nullif(btrim(v_data ->> 'postalCode'), ''), nullif(btrim(v_data ->> 'city'), ''), nullif(btrim(v_data ->> 'country'), ''), nullif(v_data ->> 'latitude', '')::double precision, nullif(v_data ->> 'longitude', '')::double precision, coalesce((v_data ->> 'isPrimary')::boolean, false))
    returning "id", "updated_at" into v_id, v_updated;
  end if;
  return jsonb_build_object('subjectId', v_id, 'updatedAt', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_payment_term (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row jsonb;
begin
  if jsonb_typeof(import_payment_term.item -> 'data') is distinct from 'object' then
    raise exception 'a payment terms item needs data' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  v_row := "better_supabase"."payment_term_write"((import_payment_term.item ->> 'tenant')::uuid, import_payment_term.item -> 'data', import_payment_term.subject_id::uuid);
  return jsonb_build_object('subjectId', v_row ->> 'id', 'updatedAt', v_row ->> 'updatedAt');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_product (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_data jsonb := import_product.item -> 'data';
  v_tenant uuid := (import_product.item ->> 'tenant')::uuid;
  v_raw text := coalesce(v_data ->> 'name', v_data ->> 'title', '');
  v_name text;
  v_slug text;
  v_sku text := nullif(btrim(v_data ->> 'sku'), '');
  v_price bigint;
  v_id uuid := nullif(import_product.subject_id, '')::uuid;
  v_updated timestamptz;
  v_fallback boolean := coalesce((import_product.item -> 'options' ->> 'priceFallback')::boolean, false);
begin
  if length(regexp_replace(v_raw, '[[:cntrl:][:space:]]', '', 'g')) * 2 < length(regexp_replace(coalesce(v_raw, ''), '[[:space:]]', '', 'g')) then
    raise exception 'a product name is mostly control characters' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  v_name := btrim(regexp_replace(regexp_replace(v_raw, '[[:cntrl:]]', '', 'g'), U&'[\+00E000-\+00F8FF]', '', 'g'));
  if v_name is null or length(v_name) = 0 then
    raise exception 'a product needs a name' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  v_price := coalesce(
    nullif(v_data ->> 'price', '')::bigint,
    nullif(v_data ->> 'listPrice', '')::bigint,
    case when v_fallback then round(nullif(v_data ->> 'lastPurchasePrice', '')::numeric * coalesce(nullif(v_data ->> 'markup', '')::numeric, 1))::bigint end);
  v_slug := trim(both '-' from lower(regexp_replace(coalesce(nullif(v_data ->> 'slug', ''), v_name), '[^a-zA-Z0-9]+', '-', 'g')));
  if v_id is not null and exists (
    select 1 from "better_supabase"."products" x
    where x."id" = v_id and x."tenant_id" = v_tenant and x."title" is not distinct from v_name
      and x."slug" is not distinct from v_slug
      
  ) and (v_sku is null or exists (
    select 1 from "better_supabase"."product_variants" y where y."product_id" = v_id and y."sku" is not distinct from v_sku
  )) then
    return jsonb_build_object('subjectId', v_id, 'updatedAt', (select x."updated_at" from "better_supabase"."products" x where x."id" = v_id));
  end if;
  if v_sku is not null and exists (
    select 1 from "better_supabase"."product_variants" y where y."tenant_id" = v_tenant and y."sku" = v_sku and y."product_id" is distinct from v_id
  ) then
    raise exception 'a sku is already used by another product' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if exists (select 1 from "better_supabase"."products" x where x."tenant_id" = v_tenant and x."slug" = v_slug and x."id" is distinct from v_id) then
    v_slug := left(v_slug, 40) || '-' || left(coalesce(import_product.item ->> 'key', 'item'), 8);
  end if;
  if v_id is null then
    insert into "better_supabase"."products" ("tenant_id", "title", "slug", "manufacturer", "model", "tax_code")
    values (v_tenant, v_name, v_slug, nullif(btrim(v_data ->> 'manufacturer'), ''), nullif(btrim(v_data ->> 'model'), ''), nullif(coalesce(import_product.item -> 'resolved' ->> 'tax', v_data ->> 'taxCode'), ''))
    returning "id", "updated_at" into v_id, v_updated;
  else
    update "better_supabase"."products" x set "title" = v_name, "slug" = v_slug, "updated_at" = now(), "manufacturer" = coalesce(nullif(btrim(v_data ->> 'manufacturer'), ''), x."manufacturer"), "model" = coalesce(nullif(btrim(v_data ->> 'model'), ''), x."model"), "tax_code" = coalesce(nullif(coalesce(import_product.item -> 'resolved' ->> 'tax', v_data ->> 'taxCode'), ''), x."tax_code")
    where x."id" = v_id and x."tenant_id" = v_tenant
    returning x."updated_at" into v_updated;
  end if;
  if not exists (select 1 from "better_supabase"."product_variants" y where y."product_id" = v_id) then
    insert into "better_supabase"."product_variants" ("tenant_id", "product_id", "sku", "barcode")
    values (v_tenant, v_id, coalesce(v_sku, v_slug), nullif(btrim(v_data ->> 'ean'), ''));
  elsif v_sku is not null then
    update "better_supabase"."product_variants" y set "sku" = v_sku, "barcode" = coalesce(nullif(btrim(v_data ->> 'ean'), ''), y."barcode")
    where y."id" = (select y2."id" from "better_supabase"."product_variants" y2 where y2."product_id" = v_id order by y2."created_at" limit 1);
  end if;
  return jsonb_build_object('subjectId', v_id, 'updatedAt', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_product_category (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_data jsonb := import_product_category.item -> 'data';
  v_product uuid := nullif(coalesce(import_product_category.item -> 'resolved' ->> 'product', v_data ->> 'productId'), '')::uuid;
  v_category uuid := nullif(coalesce(import_product_category.item -> 'resolved' ->> 'category', v_data ->> 'categoryId'), '')::uuid;
begin
  if v_category is null and nullif(btrim(v_data ->> 'name'), '') is not null then
    select x."id" into v_category from "better_supabase"."catalog_categories" x
    where x."tenant_id" = (import_product_category.item ->> 'tenant')::uuid and x."name" = btrim(v_data ->> 'name');
  end if;
  if v_product is null or v_category is null then
    raise exception 'a product category needs a product and a category' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  insert into "better_supabase"."product_categories" ("tenant_id", "product_id", "category_id")
  values ((import_product_category.item ->> 'tenant')::uuid, v_product, v_category)
  on conflict do nothing;
  return jsonb_build_object('subjectId', v_product::text || ':' || v_category::text, 'updatedAt', now());
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_product_identifier (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_product_identifier.item ->> 'tenant')::uuid;
  v_data jsonb := import_product_identifier.item -> 'data';
  v_variant uuid;
  v_type text := v_data ->> 'type';
  v_value text := btrim(v_data ->> 'value');
  v_party uuid;
  v_id uuid;
  v_updated timestamptz;
begin
  begin
    v_variant := nullif(v_data ->> 'variantId', '')::uuid;
    v_party := nullif(v_data ->> 'partyId', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'variantId and partyId must be uuids' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  if v_variant is null and nullif(v_data ->> 'sku', '') is not null then
    select y."id" into v_variant from "better_supabase"."product_variants" y where y."tenant_id" = v_tenant and y."sku" = v_data ->> 'sku';
  end if;
  if v_variant is null or not exists (select 1 from "better_supabase"."product_variants" y where y."id" = v_variant and y."tenant_id" = v_tenant) then
    raise exception 'the variant isn''t in this organization; name it with sku or variantId' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_type is null or v_type not in ('ean', 'supplier', 'manufacturer', 'other') then
    raise exception 'the type must be one of ean, supplier, manufacturer, other' using errcode = '22023', hint = 'CATALOG_IDENTIFIER_TYPE_INVALID';
  end if;
  if v_value is null or length(v_value) not between 1 and 100 then
    raise exception 'the value must be 1 to 100 characters' using errcode = '22023', hint = 'CATALOG_IDENTIFIER_INVALID';
  end if;
  if v_type = 'ean' and v_value !~ '^([0-9]{8}|[0-9]{12,14})$' then
    raise exception 'an EAN has 8, 12, 13 or 14 digits' using errcode = '22023', hint = 'CATALOG_IDENTIFIER_INVALID';
  end if;
  if import_product_identifier.subject_id is null then
    insert into "better_supabase"."product_identifiers" as x ("tenant_id", "variant_id", "type", "value", "party_id")
    values (v_tenant, v_variant, v_type, v_value, v_party)
    on conflict ("variant_id", "type", "value", coalesce("party_id", '00000000-0000-0000-0000-000000000000'::uuid)) do update set "updated_at" = now()
    returning x."id", x."updated_at" into v_id, v_updated;
  else
    update "better_supabase"."product_identifiers" x set "variant_id" = v_variant, "type" = v_type, "value" = v_value, "party_id" = v_party, "updated_at" = now()
    where x."id" = import_product_identifier.subject_id::uuid and x."tenant_id" = v_tenant
    returning x."id", x."updated_at" into v_id, v_updated;
    if not found then
      raise exception 'the identifier no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_quote (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_quote.item ->> 'tenant')::uuid;
  v_data jsonb := import_quote.item -> 'data';
  v_number text := nullif(btrim(v_data ->> 'number'), '');
  v_made jsonb;
  v_id uuid;
  v_row "better_supabase"."quotes";
  v_warnings jsonb := '[]'::jsonb;
  v_computed jsonb;
  v_given jsonb;
  v_same boolean;
begin
  if import_quote.subject_id is not null then
    select * into v_row from "better_supabase"."quotes" y where y."id" = import_quote.subject_id::uuid and y."tenant_id" = v_tenant;
    if not found then
      raise exception 'the quote no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
    if coalesce(v_data ->> 'update', 'keep') is distinct from 'apply' then
      return jsonb_build_object('subjectId', v_row."id"::text, 'updatedAt', v_row."updated_at", 'warnings', jsonb_build_array(jsonb_build_object('code', 'IMPORT_DOCUMENT_CHANGED', 'message', 'the source quote changed after it was imported; an imported quote is kept as imported, so import the correction as a new quote')));
    end if;
    v_id := v_row."id";
    v_same := (select count(*) from "better_supabase"."quote_lines" l where l."parent_id" = v_id) = jsonb_array_length(coalesce(v_data -> 'lines', '[]'::jsonb));
    -- A quote that was sent or decided can't change its lines. The import
    -- reopens it for the replacement, then the update below restores the
    -- status it had, so a historical quote keeps its decided state.
    if not v_same and jsonb_typeof(v_data -> 'lines') = 'array' then
      update "better_supabase"."quotes" y set "status" = 'draft' where y."id" = v_id;
      perform "better_supabase"."set_quote_lines"(v_id, v_data -> 'lines');
    end if;
    update "better_supabase"."quotes" y set
      "status" = coalesce(v_data ->> 'status', 'draft'),
      "created_at" = coalesce(nullif(v_data ->> 'createdAt', '')::timestamptz, y."created_at"),
      "sent_at" = nullif(v_data ->> 'sentAt', '')::timestamptz,
      "viewed_at" = nullif(v_data ->> 'viewedAt', '')::timestamptz,
      "decided_at" = nullif(v_data ->> 'decidedAt', '')::timestamptz,
      "decided_by" = nullif(v_data ->> 'decidedBy', ''),
      "decision_note" = nullif(v_data ->> 'decisionNote', ''),
      "buyer" = case when jsonb_typeof(v_data -> 'buyer') = 'object' then v_data -> 'buyer' end,
      legal_entity_id = nullif(v_data ->> 'legalEntityId', '')::uuid,
      "updated_at" = now(),
      "title" = coalesce(nullif(v_data ->> 'title', ''), y."title"),
      "currency" = coalesce(nullif(v_data ->> 'currency', ''), y."currency"),
      "valid_until" = coalesce(nullif(v_data ->> 'validUntil', '')::date, y."valid_until"),
      "company_id" = coalesce(nullif(v_data ->> 'companyId', ''), y."company_id")
    where y."id" = v_id;
    if v_same then
      update "better_supabase"."quote_lines" l set
        "description" = coalesce(nullif(e.l ->> 'title', ''), nullif(e.l ->> 'description', ''), l."description"),
        "tax_rate_bps" = coalesce((e.l ->> 'taxRateBps')::integer, l."tax_rate_bps"),
        "tax_code" = coalesce(nullif(e.l ->> 'taxCode', ''), l."tax_code")
      from jsonb_array_elements(v_data -> 'lines') with ordinality as e(l, n)
      where l."parent_id" = v_id and l."position" = e.n::integer;
    end if;
  if jsonb_typeof(v_data -> 'taxLines') = 'array' then
    v_computed := coalesce((
      select jsonb_object_agg(k.key, jsonb_build_object('net', k.net, 'tax', k.tax))
      from (select coalesce(z."tax_code", '') || ':' || z."tax_rate_bps"::text as key, sum(z."net") as net, sum(z."tax") as tax
        from "better_supabase"."quote_tax_lines" z where z."parent_id" = v_id group by 1) k
    ), '{}'::jsonb);
    v_given := coalesce((
      select jsonb_object_agg(k.key, jsonb_build_object('net', k.net, 'tax', k.tax))
      from (select coalesce(g.value ->> 'taxCode', '') || ':' || coalesce((g.value ->> 'taxRateBps')::integer, 0)::text as key,
          sum((g.value ->> 'net')::bigint) as net, sum((g.value ->> 'tax')::bigint) as tax
        from jsonb_array_elements(v_data -> 'taxLines') g group by 1) k
    ), '{}'::jsonb);
    if v_computed <> v_given then
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_TAX_MISMATCH', 'message', 'the stored tax per code differs from the tax computed from the lines; the stored amounts were kept', 'computed', v_computed, 'given', v_given));
    end if;
    delete from "better_supabase"."quote_tax_lines" z where z."parent_id" = v_id;
    insert into "better_supabase"."quote_tax_lines" ("tenant_id", "parent_id", "tax_rate_bps", "tax_code", "net", "tax", "gross", "discount")
    select v_tenant, v_id, coalesce((g.value ->> 'taxRateBps')::integer, 0), nullif(g.value ->> 'taxCode', ''), (g.value ->> 'net')::bigint, (g.value ->> 'tax')::bigint,
      coalesce((g.value ->> 'gross')::bigint, (g.value ->> 'net')::bigint + (g.value ->> 'tax')::bigint), coalesce((g.value ->> 'discount')::bigint, 0)
    from jsonb_array_elements(v_data -> 'taxLines') g;
  end if;
  if jsonb_typeof(v_data -> 'totals') = 'object' then
    select * into v_row from "better_supabase"."quotes" y where y."id" = v_id;
    if (v_data -> 'totals' ->> 'subtotal' is not null and (v_data -> 'totals' ->> 'subtotal')::bigint <> v_row."subtotal")
      or (v_data -> 'totals' ->> 'tax' is not null and (v_data -> 'totals' ->> 'tax')::bigint <> v_row."tax_total")
      or (v_data -> 'totals' ->> 'total' is not null and (v_data -> 'totals' ->> 'total')::bigint <> v_row."total") then
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_TOTALS_MISMATCH', 'message', 'the stored totals differ from the totals computed from the lines; the stored totals were kept',
        'computed', jsonb_build_object('subtotal', v_row."subtotal"::text, 'tax', v_row."tax_total"::text, 'total', v_row."total"::text),
        'given', v_data -> 'totals'));
    end if;
    update "better_supabase"."quotes" y set
      "subtotal" = coalesce((v_data -> 'totals' ->> 'subtotal')::bigint, y."subtotal"),
      "tax_total" = coalesce((v_data -> 'totals' ->> 'tax')::bigint, y."tax_total"),
      "total" = coalesce((v_data -> 'totals' ->> 'total')::bigint, y."total")
    where y."id" = v_id;
  end if;
    select * into v_row from "better_supabase"."quotes" y where y."id" = v_id;
    return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_row."updated_at", 'warnings', v_warnings);
  end if;
  if v_number is null then
    raise exception 'a quote needs its number' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if coalesce(v_data ->> 'status', 'draft') not in ('draft', 'sent', 'viewed', 'accepted', 'rejected', 'changes_requested', 'expired', 'withdrawn') then
    raise exception 'status is draft, sent, viewed, accepted, rejected, changes_requested, expired or withdrawn' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if jsonb_typeof(v_data -> 'lines') is distinct from 'array' or jsonb_array_length(v_data -> 'lines') = 0 then
    raise exception 'a quote needs at least one line' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if coalesce(v_data ->> 'onTaken', 'fail') not in ('fail', 'next_free') then
    raise exception 'onTaken is fail or next_free' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_data ->> 'onTaken' = 'next_free' and exists (select 1 from "better_supabase"."quotes" y where y."tenant_id" = v_tenant and y."identifier" = v_number) then
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_NUMBER_REASSIGNED', 'message', 'number ' || v_number || ' was taken; the next free number was issued'));
    v_number := null;
  end if;
  if v_number is not null then
    perform set_config('better_supabase.fixed_number', 'quote' || chr(31) || v_number, true);
  end if;
  v_made := "better_supabase"."create_quote"(v_tenant, coalesce(v_data -> 'attrs', '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
    'title', coalesce(nullif(v_data ->> 'title', ''), replace('Quote {number}', '{number}', coalesce(v_number, ''))),
    'currency', v_data -> 'currency',
    'validUntil', v_data -> 'validUntil',
    'terms', v_data -> 'terms',
    'note', v_data -> 'note',
    'company', v_data -> 'company',
    'contact', v_data -> 'contact',
    'origin', v_data -> 'origin',
    'pricesIncludeTax', v_data -> 'pricesIncludeTax',
    'discountBps', v_data -> 'discountBps',
    'discountAmount', v_data -> 'discountAmount',
    'depositBps', v_data -> 'depositBps',
    'depositAmount', v_data -> 'depositAmount')), v_data -> 'lines');
  perform set_config('better_supabase.fixed_number', '', true);
  v_id := (v_made ->> 'id')::uuid;
  update "better_supabase"."quotes" y set
    "status" = coalesce(v_data ->> 'status', 'draft'),
    "created_at" = coalesce(nullif(v_data ->> 'createdAt', '')::timestamptz, y."created_at"),
    "sent_at" = nullif(v_data ->> 'sentAt', '')::timestamptz,
    "viewed_at" = nullif(v_data ->> 'viewedAt', '')::timestamptz,
    "decided_at" = nullif(v_data ->> 'decidedAt', '')::timestamptz,
    "decided_by" = nullif(v_data ->> 'decidedBy', ''),
    "decision_note" = nullif(v_data ->> 'decisionNote', ''),
    "buyer" = case when jsonb_typeof(v_data -> 'buyer') = 'object' then v_data -> 'buyer' end,
    legal_entity_id = nullif(v_data ->> 'legalEntityId', '')::uuid,
    "updated_at" = now()
  where y."id" = v_id;
  if jsonb_typeof(v_data -> 'taxLines') = 'array' then
    v_computed := coalesce((
      select jsonb_object_agg(k.key, jsonb_build_object('net', k.net, 'tax', k.tax))
      from (select coalesce(z."tax_code", '') || ':' || z."tax_rate_bps"::text as key, sum(z."net") as net, sum(z."tax") as tax
        from "better_supabase"."quote_tax_lines" z where z."parent_id" = v_id group by 1) k
    ), '{}'::jsonb);
    v_given := coalesce((
      select jsonb_object_agg(k.key, jsonb_build_object('net', k.net, 'tax', k.tax))
      from (select coalesce(g.value ->> 'taxCode', '') || ':' || coalesce((g.value ->> 'taxRateBps')::integer, 0)::text as key,
          sum((g.value ->> 'net')::bigint) as net, sum((g.value ->> 'tax')::bigint) as tax
        from jsonb_array_elements(v_data -> 'taxLines') g group by 1) k
    ), '{}'::jsonb);
    if v_computed <> v_given then
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_TAX_MISMATCH', 'message', 'the stored tax per code differs from the tax computed from the lines; the stored amounts were kept', 'computed', v_computed, 'given', v_given));
    end if;
    delete from "better_supabase"."quote_tax_lines" z where z."parent_id" = v_id;
    insert into "better_supabase"."quote_tax_lines" ("tenant_id", "parent_id", "tax_rate_bps", "tax_code", "net", "tax", "gross", "discount")
    select v_tenant, v_id, coalesce((g.value ->> 'taxRateBps')::integer, 0), nullif(g.value ->> 'taxCode', ''), (g.value ->> 'net')::bigint, (g.value ->> 'tax')::bigint,
      coalesce((g.value ->> 'gross')::bigint, (g.value ->> 'net')::bigint + (g.value ->> 'tax')::bigint), coalesce((g.value ->> 'discount')::bigint, 0)
    from jsonb_array_elements(v_data -> 'taxLines') g;
  end if;
  if jsonb_typeof(v_data -> 'totals') = 'object' then
    select * into v_row from "better_supabase"."quotes" y where y."id" = v_id;
    if (v_data -> 'totals' ->> 'subtotal' is not null and (v_data -> 'totals' ->> 'subtotal')::bigint <> v_row."subtotal")
      or (v_data -> 'totals' ->> 'tax' is not null and (v_data -> 'totals' ->> 'tax')::bigint <> v_row."tax_total")
      or (v_data -> 'totals' ->> 'total' is not null and (v_data -> 'totals' ->> 'total')::bigint <> v_row."total") then
      v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'IMPORT_TOTALS_MISMATCH', 'message', 'the stored totals differ from the totals computed from the lines; the stored totals were kept',
        'computed', jsonb_build_object('subtotal', v_row."subtotal"::text, 'tax', v_row."tax_total"::text, 'total', v_row."total"::text),
        'given', v_data -> 'totals'));
    end if;
    update "better_supabase"."quotes" y set
      "subtotal" = coalesce((v_data -> 'totals' ->> 'subtotal')::bigint, y."subtotal"),
      "tax_total" = coalesce((v_data -> 'totals' ->> 'tax')::bigint, y."tax_total"),
      "total" = coalesce((v_data -> 'totals' ->> 'total')::bigint, y."total")
    where y."id" = v_id;
  end if;
  select * into v_row from "better_supabase"."quotes" y where y."id" = v_id;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_row."updated_at", 'warnings', v_warnings);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_resolve (
  run    uuid,
  entity text,
  keys   jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_run "better_supabase"."import_runs";
begin
  select * into v_run from "better_supabase"."import_runs" r where r."id" = import_resolve.run;
  if not found then
    raise exception 'import not found' using errcode = 'P0002', hint = 'IMPORT_NOT_FOUND';
  end if;
  if jsonb_typeof(import_resolve.keys) <> 'array' then
    raise exception 'keys must be an array' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('key', q.key, 'scope', q.scope, 'role', q.role, 'subjectType', m."subject_type", 'subjectId', m."subject_id") order by q.ord)
    from (
      select k.ord,
        case when jsonb_typeof(k.value) = 'string' then k.value #>> '{}' else k.value ->> 'key' end as key,
        case when jsonb_typeof(k.value) = 'string' then '' else coalesce(k.value ->> 'scope', '') end as scope,
        case when jsonb_typeof(k.value) = 'string' then 'primary' else coalesce(k.value ->> 'role', 'primary') end as role
      from jsonb_array_elements(import_resolve.keys) with ordinality k(value, ord)
    ) q
    join lateral (
      select x."subject_type", x."subject_id"
      from "better_supabase"."import_records" x
      where x."tenant_id" = v_run."tenant_id" and x."source" = v_run."source"
        and x."entity" = import_resolve.entity and x."external_key" = q.key and x."role" = q.role
        and (x."scope" = q.scope or x."scope" in (
          select a."of" from jsonb_to_recordset(v_run."scope_aliases") as a(scope text, "of" text, entities jsonb)
          where a.scope = q.scope
            and (a.entities is null or jsonb_typeof(a.entities) <> 'array' or jsonb_array_length(a.entities) = 0 or a.entities ? import_resolve.entity)
        ))
      order by (x."scope" = q.scope) desc
      limit 1
    ) m on true
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_run()
  RETURNS uuid
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select case
    when nullif(current_setting('better_supabase.import_run', true), '') is not null and coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')
    then nullif(current_setting('better_supabase.import_run', true), '')::uuid
  end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_stock_allocation (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_stock_allocation.item ->> 'tenant')::uuid;
  v_data jsonb := import_stock_allocation.item -> 'data';
  v_variant uuid;
  v_location uuid;
  v_quantity numeric;
  v_allocated numeric;
  v_fulfilled numeric;
  v_status text := coalesce(nullif(v_data ->> 'status', ''), 'open');
  v_row record;
  v_id uuid;
  v_updated timestamptz;
begin
  begin
    v_variant := nullif(v_data ->> 'variantId', '')::uuid;
    v_location := nullif(v_data ->> 'locationId', '')::uuid;
    v_quantity := (v_data ->> 'quantity')::numeric;
    v_allocated := coalesce((v_data ->> 'allocated')::numeric, 0);
    v_fulfilled := coalesce((v_data ->> 'fulfilled')::numeric, 0);
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'ids are uuids and quantity, allocated and fulfilled are numbers' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  if v_status not in ('open', 'fulfilled', 'released') then
    raise exception 'status is open, fulfilled or released' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_quantity is null or v_quantity <= 0 or v_allocated < 0 or v_fulfilled < 0 or v_allocated + v_fulfilled > v_quantity then
    raise exception 'quantity is above zero and allocated plus fulfilled isn''t more than the quantity' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if coalesce(v_data ->> 'documentType', '') !~ '^[a-z][a-z0-9_]{0,62}$' or length(coalesce(v_data ->> 'documentId', '')) not between 1 and 200 then
    raise exception 'an allocation names its document type (lower case, with underscores) and its document id' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_variant is null then
    select y."id" into v_variant from "better_supabase"."product_variants" y where y."tenant_id" = v_tenant and y."sku" = v_data ->> 'sku';
  end if;
  if v_variant is null or not exists (select 1 from "better_supabase"."product_variants" y where y."id" = v_variant and y."tenant_id" = v_tenant) then
    raise exception 'the allocation''s variant isn''t in this organization' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_location is null then
    select x."id" into v_location from "better_supabase"."inventory_locations" x where x."tenant_id" = v_tenant and x."code" = v_data ->> 'location';
  elsif not exists (select 1 from "better_supabase"."inventory_locations" x where x."id" = v_location and x."tenant_id" = v_tenant) then
    v_location := null;
  end if;
  if v_location is null then
    raise exception 'the allocation''s location isn''t in this organization' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_status <> 'open' then
    v_allocated := 0;
  end if;
  if v_status = 'fulfilled' then
    v_fulfilled := v_quantity;
  end if;
  insert into "better_supabase"."stock_levels" ("tenant_id", "variant_id", "location_id")
  values (v_tenant, v_variant, v_location)
  on conflict ("variant_id", "location_id") do nothing;
  if import_stock_allocation.subject_id is not null then
    select x."id" as id, x."variant_id" as variant, x."location_id" as location, x."allocated" as allocated,
      x."status" as status, x."updated_at" as updated_at
    into v_row from "better_supabase"."stock_allocations" x
    where x."id" = import_stock_allocation.subject_id::uuid and x."tenant_id" = v_tenant for update;
    if v_row.id is null then
      raise exception 'the stock allocation no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
    if v_row.status <> 'open' then
      return jsonb_build_object('subjectId', v_row.id::text, 'updatedAt', v_row.updated_at, 'warnings', jsonb_build_array(jsonb_build_object(
        'code', 'IMPORT_DOCUMENT_CHANGED', 'message', 'a fulfilled or released stock allocation is kept as imported')));
    end if;
    update "better_supabase"."stock_levels" x set "reserved" = greatest(x."reserved" - v_row.allocated, 0), "updated_at" = now()
    where x."variant_id" = v_row.variant and x."location_id" = v_row.location;
    update "better_supabase"."stock_allocations" x set "variant_id" = v_variant, "location_id" = v_location, "document_type" = v_data ->> 'documentType',
      "document_id" = v_data ->> 'documentId', "line_id" = nullif(v_data ->> 'lineId', ''), "quantity" = v_quantity,
      "allocated" = v_allocated, "fulfilled" = v_fulfilled, "status" = v_status, "updated_at" = now()
    where x."id" = v_row.id returning x."id", x."updated_at" into v_id, v_updated;
  else
    insert into "better_supabase"."stock_allocations" as x ("tenant_id", "variant_id", "location_id", "document_type", "document_id", "line_id",
      "quantity", "allocated", "fulfilled", "status")
    values (v_tenant, v_variant, v_location, v_data ->> 'documentType', v_data ->> 'documentId', nullif(v_data ->> 'lineId', ''),
      v_quantity, v_allocated, v_fulfilled, v_status)
    returning x."id", x."updated_at" into v_id, v_updated;
  end if;
  update "better_supabase"."stock_levels" x set "reserved" = x."reserved" + v_allocated, "updated_at" = now()
  where x."variant_id" = v_variant and x."location_id" = v_location;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_stock_count (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_stock_count.item ->> 'tenant')::uuid;
  v_data jsonb := import_stock_count.item -> 'data';
  v_location uuid;
  v_id uuid;
  v_status text;
  v_updated timestamptz;
  v_entry jsonb;
  v_variant uuid;
  v_bin uuid;
  v_lot uuid;
  v_serial text;
  v_counted numeric;
  v_expected numeric;
begin
  if jsonb_typeof(v_data -> 'lines') is distinct from 'array' then
    raise exception 'a stock count needs a list of lines' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  begin
    v_location := nullif(v_data ->> 'locationId', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'locationId is a uuid' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  if v_location is null then
    select x."id" into v_location from "better_supabase"."inventory_locations" x where x."tenant_id" = v_tenant and x."code" = v_data ->> 'location';
  elsif not exists (select 1 from "better_supabase"."inventory_locations" x where x."id" = v_location and x."tenant_id" = v_tenant) then
    v_location := null;
  end if;
  if v_location is null then
    raise exception 'the count''s location isn''t in this organization' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if import_stock_count.subject_id is null then
    insert into "better_supabase"."stock_counts" as x ("tenant_id", "location_id", "note")
    values (v_tenant, v_location, nullif(btrim(v_data ->> 'note'), ''))
    returning x."id", x."updated_at" into v_id, v_updated;
  else
    select x."id", x."status" into v_id, v_status from "better_supabase"."stock_counts" x
    where x."id" = import_stock_count.subject_id::uuid and x."tenant_id" = v_tenant for update;
    if v_id is null then
      raise exception 'the stock count no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
    if v_status <> 'open' then
      raise exception 'a posted or cancelled count can''t be imported again' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
    update "better_supabase"."stock_counts" x set "location_id" = v_location, "note" = nullif(btrim(v_data ->> 'note'), ''), "updated_at" = now()
    where x."id" = v_id returning x."updated_at" into v_updated;
    delete from "better_supabase"."stock_count_lines" y where y."count_id" = v_id and y."movement_id" is null;
  end if;
  for v_entry in select e from jsonb_array_elements(v_data -> 'lines') e loop
    begin
      v_variant := nullif(v_entry ->> 'variantId', '')::uuid;
      v_bin := nullif(v_entry ->> 'binId', '')::uuid;
      v_lot := nullif(v_entry ->> 'lotId', '')::uuid;
      v_counted := (v_entry ->> 'counted')::numeric;
      v_expected := (v_entry ->> 'expected')::numeric;
    exception when invalid_text_representation or numeric_value_out_of_range then
      raise exception 'ids are uuids and counted and expected are numbers' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end;
    if v_variant is null then
      select y."id" into v_variant from "better_supabase"."product_variants" y where y."tenant_id" = v_tenant and y."sku" = v_entry ->> 'sku';
    end if;
    if v_variant is null or not exists (select 1 from "better_supabase"."product_variants" y where y."id" = v_variant and y."tenant_id" = v_tenant) then
      raise exception 'a line''s variant isn''t in this organization' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
    if v_bin is null and nullif(v_entry ->> 'bin', '') is not null then
      select y."id" into v_bin from "better_supabase"."stock_bins" y where y."tenant_id" = v_tenant and y."location_id" = v_location and y."code" = v_entry ->> 'bin';
      if v_bin is null then
        raise exception 'a line''s bin isn''t at the location' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
      end if;
    end if;
    if v_lot is null and nullif(v_entry ->> 'lot', '') is not null then
      select y."id" into v_lot from "better_supabase"."stock_lots" y where y."tenant_id" = v_tenant and y."variant_id" = v_variant and y."code" = v_entry ->> 'lot';
      if v_lot is null then
        raise exception 'a line''s lot isn''t a lot of its variant' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
      end if;
    end if;
    v_serial := nullif(btrim(v_entry ->> 'serial'), '');
    if v_counted is null or v_counted < 0 or (v_serial is not null and (v_counted not in (0, 1) or v_bin is not null or v_lot is not null)) then
      raise exception 'a line needs a counted quantity of zero or more, and a serial is counted 0 or 1' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
    insert into "better_supabase"."stock_count_lines" as x ("tenant_id", "count_id", "variant_id", "bin_id", "lot_id", "serial", "expected", "counted")
    values (v_tenant, v_id, v_variant, v_bin, v_lot, v_serial,
      coalesce(v_expected, "better_supabase"."count_expected"(v_variant, v_location, v_bin, v_lot, v_serial)), v_counted)
    on conflict ("count_id", "variant_id", coalesce("bin_id", '00000000-0000-4000-8000-000000000000'::uuid), coalesce("lot_id", '00000000-0000-4000-8000-000000000000'::uuid), coalesce("serial", '')) do update
      set "counted" = excluded."counted", "expected" = excluded."expected", "updated_at" = now();
  end loop;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_supplier_item (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_supplier_item.item ->> 'tenant')::uuid;
  v_data jsonb := import_supplier_item.item -> 'data';
  v_supplier uuid;
  v_merged jsonb;
  v_code text;
  v_price text;
  v_id uuid;
  v_updated timestamptz;
begin
  begin
    v_supplier := nullif(v_data ->> 'supplierId', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'supplierId must be a uuid' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  if v_supplier is null then
    raise exception 'a supplier item needs a supplierId' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  v_merged := (case when jsonb_typeof(v_data -> 'row') = 'object' then "better_supabase"."supplier_item_from_row"(v_tenant, v_supplier, v_data -> 'row') else '{}'::jsonb end) || (v_data - 'row' - 'supplierId');
  v_code := nullif(btrim(v_merged ->> 'code'), '');
  v_price := v_merged ->> 'price';
  if v_code is null or length(v_code) > 100 then
    raise exception 'a supplier item needs a code of up to 100 characters' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_price is not null and v_price !~ '^[0-9]{1,18}$' then
    raise exception 'price is a whole number of minor units' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if v_merged ->> 'currency' is not null and "better_supabase"."currency_minor_units"(upper(v_merged ->> 'currency')) is null then
    raise exception 'not an ISO 4217 currency code' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  if import_supplier_item.subject_id is null then
    insert into "better_supabase"."supplier_items" as x ("tenant_id", "supplier_id", "code", "description", "price", "currency", "unit", "keywords_text")
    values (v_tenant, v_supplier, v_code, v_merged ->> 'description', v_price::bigint, upper(v_merged ->> 'currency'), v_merged ->> 'unit', v_merged ->> 'keywords')
    on conflict ("tenant_id", "supplier_id", "code") do update set "description" = excluded."description", "price" = excluded."price",
      "currency" = excluded."currency", "unit" = excluded."unit", "keywords_text" = excluded."keywords_text", "updated_at" = now()
    returning x."id", x."updated_at" into v_id, v_updated;
  else
    update "better_supabase"."supplier_items" x set "supplier_id" = v_supplier, "code" = v_code, "description" = v_merged ->> 'description', "price" = v_price::bigint,
      "currency" = upper(v_merged ->> 'currency'), "unit" = v_merged ->> 'unit', "keywords_text" = v_merged ->> 'keywords', "updated_at" = now()
    where x."id" = import_supplier_item.subject_id::uuid and x."tenant_id" = v_tenant
    returning x."id", x."updated_at" into v_id, v_updated;
    if not found then
      raise exception 'the supplier item no longer exists' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
    end if;
  end if;
  return jsonb_build_object('subjectId', v_id::text, 'updatedAt', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_tax_code (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_tax_code.item ->> 'tenant')::uuid;
  v_row jsonb;
begin
  if jsonb_typeof(import_tax_code.item -> 'data') is distinct from 'object' then
    raise exception 'a tax code item needs data' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  v_row := "better_supabase"."tax_code_write"(v_tenant, import_tax_code.item -> 'data', import_tax_code.subject_id::uuid);
  return jsonb_build_object('subjectId', v_row ->> 'id', 'updatedAt', v_row ->> 'updatedAt');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_tax_rate (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid := (import_tax_rate.item ->> 'tenant')::uuid;
  v_data jsonb := import_tax_rate.item -> 'data';
  v_code uuid;
  v_row jsonb;
begin
  if jsonb_typeof(v_data) is distinct from 'object' then
    raise exception 'a tax rate item needs data' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  begin
    v_code := coalesce(nullif(v_data ->> 'taxCodeId', '')::uuid, "better_supabase"."resolve_tax_code"(v_tenant, v_data ->> 'taxCode'));
    v_row := "better_supabase"."tax_rate_write"(v_tenant, v_code, (v_data ->> 'rateBps')::integer, nullif(v_data ->> 'validFrom', '')::date, nullif(v_data ->> 'validTo', '')::date);
  exception
    when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
      raise exception 'a tax rate needs a tax code, a rate in basis points and valid dates' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end;
  return jsonb_build_object('subjectId', v_row ->> 'id');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.import_upsert_batch (
  run    uuid,
  entity text,
  items  jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_run_id uuid := import_upsert_batch.run;
  v_entity text := import_upsert_batch.entity;
  v_run "better_supabase"."import_runs";
  v_result jsonb;
  v_name text;
  v_previous jsonb := '{}'::jsonb;
begin
  -- No row lock here: two batches of one run write at the same time, and the
  -- counts update at the end is the only statement that locks the run row.
  select * into v_run from "better_supabase"."import_runs" r where r."id" = v_run_id;
  if not found then
    raise exception 'import not found' using errcode = 'P0002', hint = 'IMPORT_NOT_FOUND';
  end if;
  if v_run."status" <> 'running' then
    raise exception 'the import is not running' using errcode = '55000', hint = 'IMPORT_RUN_NOT_RUNNING';
  end if;
  if coalesce((v_run."plan" ->> 'unordered')::boolean, false) is distinct from true
    and jsonb_typeof(v_run."plan" -> 'waves') = 'array'
    and exists (
      select 1 from jsonb_array_elements(v_run."plan" -> 'waves') with ordinality as w(wave, n)
      where w.wave ? v_entity and exists (
        select 1 from jsonb_array_elements(v_run."plan" -> 'waves') with ordinality as earlier(wave, n)
        cross join lateral jsonb_array_elements_text(earlier.wave) dep(entity)
        join "better_supabase"."import_chunks" c on c."run_id" = v_run_id
          and c."entity" = dep.entity and c."status" <> 'done'
        where earlier.n < w.n)) then
    raise exception 'an earlier import wave still has open chunks' using errcode = '55000', hint = 'IMPORT_DEPENDENCY_OPEN';
  end if;

  foreach v_name in array array['better_supabase.import_run', 'better_supabase.correlation_id', 'better_supabase.import_events', 'better_supabase.import_audit', 'better_supabase.search_deferred'] loop
    v_previous := v_previous || jsonb_build_object(v_name, coalesce(current_setting(v_name, true), ''));
  end loop;
  perform "better_supabase"."begin_import_session"(v_run_id);
  perform set_config('better_supabase.search_deferred', 'on', true);

  if v_run."dry_run" then
    begin
      v_result := "better_supabase"."import_apply_batch"(v_run_id, v_entity, import_upsert_batch.items);
      raise exception 'dry run' using errcode = 'BSDRY';
    exception when sqlstate 'BSDRY' then
      null;
    end;
  else
    v_result := "better_supabase"."import_apply_batch"(v_run_id, v_entity, import_upsert_batch.items);
    perform "better_supabase"."search_refresh_dirty"();
  end if;

  foreach v_name in array array['better_supabase.import_run', 'better_supabase.correlation_id', 'better_supabase.import_events', 'better_supabase.import_audit', 'better_supabase.search_deferred'] loop
    perform set_config(v_name, v_previous ->> v_name, true);
  end loop;

  update "better_supabase"."import_runs" r set
    "counts" = jsonb_set(r."counts", array[v_entity], jsonb_build_object(
      'inserted', coalesce(r."counts" -> v_entity ->> 'inserted', '0')::integer + coalesce((v_result ->> 'inserted')::integer, 0),
      'updated', coalesce(r."counts" -> v_entity ->> 'updated', '0')::integer + coalesce((v_result ->> 'updated')::integer, 0),
      'unchanged', coalesce(r."counts" -> v_entity ->> 'unchanged', '0')::integer + coalesce((v_result ->> 'unchanged')::integer, 0),
      'conflicted', coalesce(r."counts" -> v_entity ->> 'conflicted', '0')::integer + coalesce((v_result ->> 'conflicted')::integer, 0),
      'missing', coalesce((r."counts" -> v_entity ->> 'missing')::integer, 0)
    )),
    "errors" = r."errors" || coalesce(v_result -> 'errors', '[]'::jsonb),
    "diff" = (select coalesce(jsonb_agg(d.value), '[]'::jsonb) from (
      select value from jsonb_array_elements(r."diff" || coalesce(v_result -> 'diff', '[]'::jsonb)) value limit 100
    ) d)
  where r."id" = v_run_id;
  return v_result || jsonb_build_object('dryRun', v_run."dry_run");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.importing()
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select better_supabase.import_run() is not null;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_add_message (
  conversation uuid,
  input        jsonb,
  author_type  text,
  author       uuid,
  direction    text
)
  RETURNS uuid
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_conv "better_supabase"."inbox_conversations"%rowtype;
  v_inbox "better_supabase"."inboxes"%rowtype;
  v_id uuid;
  v_at timestamptz := clock_timestamp();
  v_kind text := coalesce(input ->> 'kind', 'message');
  v_body text := coalesce(input ->> 'body', '');
  v_mentions uuid[];
  v_uploads uuid[];
  v_file jsonb;
  v_moved integer;
  v_reopened boolean := false;
  v_claims text;
begin
  select * into v_conv from "better_supabase"."inbox_conversations" where "id" = inbox_add_message.conversation for update;
  select * into v_inbox from "better_supabase"."inboxes" where "id" = v_conv."inbox_id";
  if input ? 'external_id' then
    select d."message_id" into v_id from "better_supabase"."inbox_message_details" d
    where d."conversation_id" = v_conv."id" and d."external_id" = input ->> 'external_id';
    if found then
      return v_id;
    end if;
  end if;
  if v_kind not in ('message', 'note') then
    raise exception 'kind is message or note' using errcode = '22023', hint = 'INBOX_KIND_INVALID';
  end if;
  v_uploads := array(select distinct x::uuid from jsonb_array_elements_text(coalesce(input -> 'attachments', '[]'::jsonb)) x);
  if length(btrim(v_body)) = 0 and cardinality(v_uploads) = 0 and coalesce(jsonb_array_length(input -> 'files'), 0) = 0 then
    raise exception 'a message needs a body or an attachment' using errcode = '22023', hint = 'INBOX_MESSAGE_EMPTY';
  end if;
  if length(v_body) > 20000 then
    raise exception 'a message is at most 20000 characters' using errcode = '22023', hint = 'INBOX_MESSAGE_TOO_LONG';
  end if;
  select coalesce(array_agg(distinct x), '{}') into v_mentions
  from jsonb_array_elements_text(coalesce(input -> 'mentions', '[]'::jsonb)) e(raw)
  cross join lateral (select e.raw::uuid as x) u
  where coalesce(better_supabase.can_user(u.x, 'tenant', v_conv."tenant_id", 'inbox.read'), false);
  insert into "better_supabase"."messages" ("tenant_id", "conversation_id", "author_id", "kind", "body", "mentions", "sent_at", "created_at")
  values (v_conv."tenant_id", v_conv."id", inbox_add_message.author, v_kind, v_body, v_mentions, v_at, v_at)
  returning "id" into v_id;
  perform "better_supabase"."index_record_mentions"(v_id);
  insert into "better_supabase"."inbox_message_details" ("message_id", "tenant_id", "conversation_id", "direction", "author_type", "format", "external_id", "reply_to", "metadata")
  values (
    v_id, v_conv."tenant_id", v_conv."id", inbox_add_message.direction, inbox_add_message.author_type,
    coalesce(input ->> 'format', 'text'), input ->> 'external_id', (input ->> 'reply_to')::uuid, coalesce(input -> 'metadata', '{}'::jsonb)
  );
  if cardinality(v_uploads) > 0 then
    update "better_supabase"."attachments" x set "subject_type" = 'message', "subject_id" = v_id::text
    where x."id" = any (v_uploads)
      and x."tenant_id" = v_conv."tenant_id"
      and x."subject_type" = 'conversation' and x."subject_id" = v_conv."id"::text
      and x."status" <> 'infected'
      and (inbox_add_message.author is null or x."uploaded_by" = inbox_add_message.author);
    get diagnostics v_moved = row_count;
    if v_moved <> cardinality(v_uploads) then
      raise exception 'attachments must be your uploads to this conversation' using errcode = '22023', hint = 'INBOX_ATTACHMENT_INVALID';
    end if;
  end if;
  for v_file in select f from jsonb_array_elements(coalesce(input -> 'files', '[]'::jsonb)) f loop
    insert into "better_supabase"."attachments" ("tenant_id", "subject_type", "subject_id", "name", "mime_type", "size", "uploaded_by", "scan_detail")
    values (
      v_conv."tenant_id", 'message', v_id::text,
      left(coalesce(nullif(v_file ->> 'name', ''), 'file'), 255),
      lower(coalesce(nullif(v_file ->> 'content_type', ''), 'application/octet-stream')),
      coalesce((v_file ->> 'size')::bigint, 0),
      null,
      jsonb_build_object('source', v_file)::text
    );
  end loop;
  if inbox_add_message.author is not null then
    insert into "better_supabase"."conversation_members" ("conversation_id", "tenant_id", "user_id")
    values (v_conv."id", v_conv."tenant_id", inbox_add_message.author)
    on conflict do nothing;
  end if;
  if v_kind = 'message' then
    v_reopened := inbox_add_message.direction = 'inbound' and v_conv."status" in ('resolved', 'snoozed');
    update "better_supabase"."inbox_conversations" set
      "last_message_at" = v_at,
      "last_inbound_at" = case when inbox_add_message.direction = 'inbound' then v_at else "last_inbound_at" end,
      "last_message_preview" = left(v_body, 140),
      "first_response_at" = case
        when "first_response_at" is null and inbox_add_message.direction = 'outbound' and inbox_add_message.author_type in ('agent', 'bot') then v_at
        else "first_response_at" end,
      "status" = case when v_reopened then 'open' else "status" end,
      "snooze_expires_at" = case when v_reopened then null else "snooze_expires_at" end,
      "resolved_at" = case when v_reopened then null else "resolved_at" end
    where "id" = v_conv."id"
    returning * into v_conv;
    if v_reopened then
      insert into "better_supabase"."inbox_conversation_events" ("tenant_id", "conversation_id", "type", "actor_id", "data")
  values (v_conv."tenant_id", v_conv."id", 'reopened', (select auth.uid()), jsonb_build_object('by', 'contact'));
      perform "better_supabase".emit_event('inbox_conversation.reopened', jsonb_build_object('conversationId', v_conv."id", 'organizationId', v_conv."tenant_id"::text, 'inboxId', v_conv."inbox_id", 'contactId', v_conv."contact_id", 'assigneeId', v_conv."assignee_id", 'status', v_conv."status"), 'conversations/' || v_conv."id"::text, (v_conv."tenant_id")::text, null, 'better-supabase/inbox');
    end if;
  end if;
  if v_kind = 'message' and inbox_add_message.direction = 'inbound' then
    perform "better_supabase".emit_event('inbox_message.received', jsonb_build_object('conversationId', v_conv."id", 'organizationId', v_conv."tenant_id"::text, 'messageId', v_id, 'inboxId', v_conv."inbox_id", 'contactId', v_conv."contact_id"), 'conversations/' || v_conv."id"::text, (v_conv."tenant_id")::text, 'inbox_message.received:' || v_id::text, 'better-supabase/inbox');
    if v_conv."bot_mode" = 'bot' then
      perform "better_supabase"."enqueue_job"(queue => 'inbox_bot', payload => jsonb_build_object('conversation_id', v_conv."id", 'message_id', v_id, 'thread_id', v_conv."thread_id", 'inbox_id', v_conv."inbox_id"), dedupe_key => 'inbox:' || v_conv."id"::text, dedupe_running => false);
    end if;
  if better_supabase.import_run() is null then
    v_claims := current_setting('request.jwt.claims', true);
    perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
    perform "better_supabase"."notify"(jsonb_build_object(
      'type', 'inbox.message',
      'tenant', v_conv."tenant_id",
      'subject_type', 'conversation',
      'subject_id', v_conv."id"::text,
      'summary', left(v_body, 140),
      'recipients', case when v_conv."assignee_id" is not null then to_jsonb(array[v_conv."assignee_id"])
    else coalesce((select jsonb_agg(m."user_id") from "better_supabase"."inbox_members" m where m."inbox_id" = v_conv."inbox_id"), '[]'::jsonb) end,
      'key', 'inbox.message:' || v_id::text,
      'data', jsonb_build_object('conversationId', v_conv."id", 'messageId', v_id)
    ));
    perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  end if;
  end if;
  if v_kind = 'message' and inbox_add_message.direction = 'outbound' and v_inbox."channel" <> 'in_app' then
    insert into "better_supabase"."inbox_message_deliveries" ("tenant_id", "message_id", "channel")
    values (v_conv."tenant_id", v_id, v_inbox."channel")
    on conflict do nothing;
    if not coalesce((input ->> 'delivered_by_caller')::boolean, false) then
      perform "better_supabase"."enqueue_job"(queue => 'inbox_outbound', payload => jsonb_build_object('message_id', v_id, 'conversation_id', v_conv."id", 'inbox_id', v_conv."inbox_id"), dedupe_key => 'inbox-out:' || v_id::text, dedupe_running => false);
    end if;
  end if;
  if cardinality(v_mentions) > 0 then
  if better_supabase.import_run() is null then
    v_claims := current_setting('request.jwt.claims', true);
    perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
    perform "better_supabase"."notify"(jsonb_build_object(
      'type', 'inbox.mention',
      'tenant', v_conv."tenant_id",
      'actor', inbox_add_message.author,
      'subject_type', 'conversation',
      'subject_id', v_conv."id"::text,
      'summary', left(v_body, 140),
      'recipients', to_jsonb(v_mentions),
      'key', 'inbox.mention:' || v_id::text,
      'data', jsonb_build_object('conversationId', v_conv."id", 'messageId', v_id)
    ));
    perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  end if;
  end if;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_can_conversation (
  conversation uuid,
  action       text
)
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  case inbox_can_conversation.action
    when 'read' then
      return "better_supabase"."inbox_conversation_allowed"(inbox_can_conversation.conversation::text);
    when 'send' then
      return "better_supabase"."inbox_conversation_allowed"(inbox_can_conversation.conversation::text, true);
    when 'moderate' then
      return exists (
        select 1 from "better_supabase"."inbox_conversations" v
        where v."id" = inbox_can_conversation.conversation and coalesce(better_supabase.can('tenant', v."tenant_id", 'inbox.manage'), false)
      );
    else
      return false;
  end case;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_contact_ids()
  RETURNS SETOF uuid
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return query select p."id" from "better_supabase"."people" p where p."user_id" = (select auth.uid());
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_contact_json (
  conversation uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not "better_supabase"."inbox_conversation_allowed"(conversation::text) then
    return null;
  end if;
  return (
    select jsonb_build_object('id', p."id", 'name', p."name", 'email', p."email", 'phone', p."phone", 'avatar_url', p."avatar_url", 'user_id', p."user_id")
    from "better_supabase"."inbox_conversations" v
    join "better_supabase"."people" p on p."id" = v."contact_id"
    where v."id" = inbox_contact_json.conversation
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_contact_read_at (
  conversation uuid
)
  RETURNS timestamp WITH time zone
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return (
    select k."last_read_at"
    from "better_supabase"."inbox_conversations" v
    join "better_supabase"."people" p on p."id" = v."contact_id"
    join "better_supabase"."conversation_members" k on k."conversation_id" = v."id" and k."user_id" = p."user_id"
    where v."id" = inbox_contact_read_at.conversation
      and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v."tenant_id", 'inbox.read'), false))
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_contacts_json (
  ids    uuid[] DEFAULT NULL::uuid[],
  tenant uuid   DEFAULT NULL::uuid,
  term   text   DEFAULT NULL::text
)
  RETURNS TABLE (
    conversation    uuid,
    contact         jsonb,
    contact_read_at timestamp with time zone
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return query
  with c as (
    select v."id" as id, v."tenant_id" as scope, v."contact_id" as person
    from "better_supabase"."inbox_conversations" v
    where (inbox_contacts_json.ids is not null or inbox_contacts_json.term is not null)
      and (inbox_contacts_json.ids is null or v."id" = any (inbox_contacts_json.ids))
      and (inbox_contacts_json.tenant is null or v."tenant_id" = inbox_contacts_json.tenant)
  ), staff as (
    select t.scope, (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(coalesce(better_supabase.can('tenant', t.scope, 'inbox.read'), false), false)) as ok
    from (select distinct c.scope from c) t
  )
  select c.id,
    case when s.ok or p."user_id" = (select auth.uid()) then
      jsonb_build_object('id', p."id", 'name', p."name", 'email', p."email", 'phone', p."phone", 'avatar_url', p."avatar_url", 'user_id', p."user_id")
    end,
    case when s.ok then (
      select k."last_read_at" from "better_supabase"."conversation_members" k
      where k."conversation_id" = c.id and k."user_id" = p."user_id"
    ) end
  from c
  join staff s on s.scope = c.scope
  join "better_supabase"."people" p on p."id" = c.person
  where inbox_contacts_json.term is null
    or ((s.ok or p."user_id" = (select auth.uid())) and (p."name" ilike '%' || inbox_contacts_json.term || '%'
      or p."email" ilike '%' || inbox_contacts_json.term || '%'));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_conversation_allowed (
  conversation text,
  write        boolean DEFAULT false
)
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce((
    select (case when write then coalesce(better_supabase.can('tenant', v."tenant_id", 'inbox.reply'), false) else coalesce(better_supabase.can('tenant', v."tenant_id", 'inbox.read'), false) end)
      or exists (select 1 from "better_supabase"."people" p where p."id" = v."contact_id" and p."user_id" = (select auth.uid()))
    from "better_supabase"."inbox_conversations" v
    where v."id"::text = inbox_conversation_allowed.conversation
  ), false);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_conversation_broadcast()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_payload jsonb := jsonb_build_object('conversation_id', new."id");
begin
  if to_regprocedure('realtime.send(jsonb, text, text, boolean)') is not null then
    perform realtime.send(v_payload, 'conversation', 'messages:' || new."id"::text, true);
    perform realtime.send(v_payload, 'conversation', 'inbox:org:' || new."tenant_id"::text, true);
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_conversation_json (
  conversation uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
begin
  return (
    select to_jsonb(v) || jsonb_build_object(
      'contact', "better_supabase"."inbox_contact_json"(v."id"),
      'inbox', (select jsonb_build_object('id', i."id", 'name', i."name", 'channel', i."channel") from "better_supabase"."inboxes" i where i."id" = v."inbox_id"),
      'last_read_at', (select k."last_read_at" from "better_supabase"."conversation_members" k where k."conversation_id" = v."id" and k."user_id" = (select auth.uid())),
      'contact_read_at', "better_supabase"."inbox_contact_read_at"(v."id")
    )
    from "better_supabase"."inbox_conversations" v
    where v."id" = inbox_conversation_json.conversation
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_counts (
  tenant uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
begin
  return (
    select jsonb_build_object(
      'open', count(*),
      'mine', count(*) filter (where v."assignee_id" = (select auth.uid())),
      'unassigned', count(*) filter (where v."assignee_id" is null),
      'unread', count(*) filter (where v."last_message_at" > coalesce(k."last_read_at", '-infinity'::timestamptz)
        and (v."assignee_id" is null or v."assignee_id" = (select auth.uid())))
    )
    from "better_supabase"."inbox_conversations" v
    left join "better_supabase"."conversation_members" k on k."conversation_id" = v."id" and k."user_id" = (select auth.uid())
    where v."tenant_id" = inbox_counts.tenant and v."status" = 'open'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_delivery_broadcast()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if to_regprocedure('realtime.send(jsonb, text, text, boolean)') is not null then
    perform realtime.send(
      jsonb_build_object('conversation_id', d."conversation_id", 'message_id', new."message_id", 'status', new."status"),
      'delivery',
      'inbox:org:' || new."tenant_id"::text,
      true
    )
    from "better_supabase"."inbox_message_details" d where d."message_id" = new."message_id";
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_event_broadcast()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_payload jsonb := jsonb_build_object('conversation_id', new."conversation_id", 'event_id', new."id", 'type', new."type");
begin
  if to_regprocedure('realtime.send(jsonb, text, text, boolean)') is not null then
    perform realtime.send(v_payload, 'event.created', 'messages:' || new."conversation_id"::text, true);
    perform realtime.send(v_payload, 'event.created', 'inbox:org:' || new."tenant_id"::text, true);
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_file_allowed (
  bucket      text,
  object_name text
)
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return exists (
    select 1 from "better_supabase"."attachments" a
    join "better_supabase"."messages" m on a."subject_type" = 'message' and m."id"::text = a."subject_id"
    join "better_supabase"."inbox_message_details" d on d."message_id" = m."id"
    where a."bucket" = inbox_file_allowed.bucket and a."object_path" = inbox_file_allowed.object_name
      and a."status" = 'clean'
      and m."archived_at" is null
      and "better_supabase"."inbox_conversation_allowed"(d."conversation_id"::text)
      and (m."kind" = 'message' or "better_supabase"."inbox_note_readable"(d."conversation_id"))
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_file_failed (
  attachment uuid,
  detail     text DEFAULT NULL::text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  update "better_supabase"."attachments" x set
    "status" = 'failed',
    "scan_detail" = coalesce(inbox_file_failed.detail, 'import failed'),
    "scanned_at" = now()
  where x."id" = inbox_file_failed.attachment and x."status" = 'pending' and x."uploaded_at" is null;
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_message_broadcast()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant text;
begin
  if not to_regprocedure('realtime.send(jsonb, text, text, boolean)') is not null or new."sent_at" is null then
    return null;
  end if;
  select v."tenant_id"::text into v_tenant from "better_supabase"."inbox_conversations" v where v."id" = new."conversation_id";
  if v_tenant is not null then
    perform realtime.send(jsonb_build_object('conversation_id', new."conversation_id", 'message_id', new."id", 'kind', new."kind"), case when tg_op = 'INSERT' or old."sent_at" is null then 'message' else 'message_updated' end, 'inbox:org:' || v_tenant::text, true);
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_messages_json (
  ids uuid[]
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_ids uuid[];
begin
  select array_agg(m."id") into v_ids
  from "better_supabase"."messages" m
  join "better_supabase"."inbox_message_details" d on d."message_id" = m."id"
  where m."id" = any (inbox_messages_json.ids)
    and m."sent_at" is not null
    and "better_supabase"."inbox_conversation_allowed"(d."conversation_id"::text)
    and (m."kind" = 'message' or "better_supabase"."inbox_note_readable"(d."conversation_id"));
  if v_ids is null then
    return '[]'::jsonb;
  end if;
  return (
    select coalesce(jsonb_agg(x.item || to_jsonb(d) || jsonb_build_object('delivery', case when "better_supabase"."inbox_note_readable"(d."conversation_id") then (
      select jsonb_build_object('status', l."status", 'channel', l."channel", 'error', l."error", 'updated_at', l."updated_at", 'delivered_at', l."delivered_at", 'read_at', l."read_at", 'failed_at', l."failed_at")
      from "better_supabase"."inbox_message_deliveries" l where l."message_id" = d."message_id"
      order by l."created_at" limit 1
    ) end) order by x.n), '[]'::jsonb)
    from jsonb_array_elements("better_supabase"."messaging_messages_json"(v_ids)) with ordinality as x (item, n)
    join "better_supabase"."inbox_message_details" d on d."message_id" = (x.item ->> 'id')::uuid
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inbox_note_readable (
  conversation uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or exists (
    select 1 from "better_supabase"."inbox_conversations" v
    where v."id" = inbox_note_readable.conversation and coalesce(better_supabase.can('tenant', v."tenant_id", 'inbox.read'), false)
  );
$function$;

CREATE OR REPLACE FUNCTION better_supabase.incident_apply_impacts (
  incident_id uuid,
  impacts     jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."incidents"%rowtype;
  v_before uuid[];
  v_item jsonb;
  v_component uuid;
begin
  select * into v_row from "better_supabase"."incidents" x where x."id" = incident_apply_impacts.incident_id;
  if jsonb_typeof(coalesce(incident_apply_impacts.impacts, '[]'::jsonb)) <> 'array' then
    raise exception 'impacts must be an array' using errcode = '22023', hint = 'INCIDENTS_INVALID';
  end if;
  select coalesce(array_agg(x."component_id"), '{}') into v_before
    from "better_supabase"."incident_impacts" x where x."incident_id" = v_row."id";
  delete from "better_supabase"."incident_impacts" x where x."incident_id" = v_row."id";
  for v_item in select value from jsonb_array_elements(coalesce(incident_apply_impacts.impacts, '[]'::jsonb))
  loop
    v_component := nullif(v_item ->> 'componentId', '')::uuid;
    if not exists (
      select 1 from "better_supabase"."incident_status_components" x where x."id" = v_component and x."tenant_id" = v_row."tenant_id"
    ) then
      raise exception 'status component not found' using errcode = 'P0002', hint = 'STATUS_COMPONENT_NOT_FOUND';
    end if;
    if coalesce(v_item ->> 'impact', '') not in ('maintenance', 'degraded', 'partial_outage', 'major_outage') then
      raise exception 'impact must be degraded, partial_outage, major_outage or maintenance' using errcode = '22023', hint = 'INCIDENTS_INVALID';
    end if;
    insert into "better_supabase"."incident_impacts" ("tenant_id", "incident_id", "component_id", "impact")
    values (v_row."tenant_id", v_row."id", v_component, v_item ->> 'impact')
    on conflict ("incident_id", "component_id") do update set "impact" = excluded."impact";
  end loop;
  perform "better_supabase"."incident_refresh_components"(
    v_before || array(select x."component_id" from "better_supabase"."incident_impacts" x where x."incident_id" = v_row."id")
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.incident_postmortem_action_list (
  postmortem_id uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', x."id", 'postmortemId', x."postmortem_id", 'taskId', x."task_id", 'title', k."title", 'state', k."state", 'dueAt', k."due_at", 'closedAt', k."closed_at", 'createdAt', x."created_at") order by x."created_at", k."number"), '[]'::jsonb)
  from "better_supabase"."incident_postmortem_actions" x
  join "better_supabase"."work_items" k on k."id" = x."task_id"
  where x."postmortem_id" = incident_postmortem_action_list.postmortem_id
    and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', x."tenant_id", 'incidents.read'), false))
$function$;

CREATE OR REPLACE FUNCTION better_supabase.incident_refresh_components (
  component_ids uuid[]
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_component "better_supabase"."incident_status_components"%rowtype;
  v_status text;
begin
  for v_component in
    select * from "better_supabase"."incident_status_components" x where x."id" = any(incident_refresh_components.component_ids) for update
  loop
    select coalesce(
      (array['operational', 'maintenance', 'degraded', 'partial_outage', 'major_outage'])[max(array_position(array['operational', 'maintenance', 'degraded', 'partial_outage', 'major_outage'], im."impact"))],
      'operational'
    ) into v_status
    from "better_supabase"."incident_impacts" im
    join "better_supabase"."incidents" ii on ii."id" = im."incident_id"
    where im."component_id" = v_component."id" and ii."status" <> 'resolved';
    continue when v_status = v_component."status";
    update "better_supabase"."incident_status_components" x set "status" = v_status, "updated_at" = now()
      where x."id" = v_component."id";
    update "better_supabase"."incident_status_component_history" x set "ended_at" = now()
      where x."component_id" = v_component."id" and x."ended_at" is null;
    insert into "better_supabase"."incident_status_component_history" ("tenant_id", "component_id", "status")
    values (v_component."tenant_id", v_component."id", v_status);
    perform "better_supabase".emit_event('status_component.changed', jsonb_build_object('organizationId', v_component."tenant_id", 'statusComponentId', v_component."id", 'status', v_status, 'previousStatus', v_component."status"), 'status-components/' || v_component."id"::text, (v_component."tenant_id")::text, null, 'better-supabase/incidents');
  perform better_supabase.audit_event(
    event_type => 'status_component.changed',
    category => 'data',
    target_type => 'status_component',
    record_id => v_component."id"::text,
    summary => 'status of ' || v_component."name" || ' changed to ' || v_status,
    tenant => (v_component."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_component."tenant_id", 'statusComponentId', v_component."id", 'status', v_status, 'previousStatus', v_component."status")
  );
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.incoming_webhook_by_token (
  token text
)
  RETURNS TABLE (
    id               uuid,
    tenant           text,
    enabled          boolean,
    verify           text,
    secret           text,
    signature_header text,
    max_body_bytes   integer,
    previous_secret  text,
    metadata         jsonb
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select e."id", e."tenant"::text, e."enabled", e."verify", coalesce(ds.decrypted_secret, e."secret"), e."signature_header", e."max_body_bytes",
    case when e."previous_secret_expires_at" > now() then coalesce(dp.decrypted_secret, e."previous_secret") end, e."metadata"
  from "better_supabase"."incoming_webhooks" e
  left join vault.decrypted_secrets ds on ds.id = e."secret_id"
  left join vault.decrypted_secrets dp on dp.id = e."previous_secret_id"
  where e."token_hash" = encode(extensions.digest(incoming_webhook_by_token.token, 'sha256'), 'hex')
$function$;

CREATE OR REPLACE FUNCTION better_supabase.incoming_webhook_subject_readable (
  subject_type text,
  subject_id   text,
  tenant       uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select subject_type is null or true
$function$;

CREATE OR REPLACE FUNCTION better_supabase.incoming_webhook_tenant_ids()
  RETURNS SETOF uuid
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return query select better_supabase.tenant_ids_with('webhooks.read');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.index_job_queue (
  queue text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  execute format(
    'create index if not exists %I on pgmq.%I ((message ->> ''dedupe_key'')) where message ? ''dedupe_key''',
    'q_' || queue || '_dedupe_idx',
    'q_' || queue
  );
  execute format(
    'create index if not exists %I on pgmq.%I ((message ->> ''dedupe_key'')) where message ? ''dedupe_key''',
    'a_' || queue || '_dedupe_idx',
    'a_' || queue
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.index_record_mentions (
  message uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  delete from "better_supabase"."message_record_mentions" x where x."message_id" = index_record_mentions.message;
  insert into "better_supabase"."message_record_mentions" ("tenant_id", "message_id", "conversation_id", "subject_type", "subject_id", "created_at")
  select m."tenant_id", m."id", m."conversation_id", r.subject_type, r.subject_id, m."sent_at"
  from "better_supabase"."messages" m
  cross join lateral (
    select s ->> 'type' as subject_type, s ->> 'id' as subject_id
    from jsonb_array_elements("better_supabase"."parse_mentions"(m."body") -> 'subjects') s
    where s ->> 'type' = any ("better_supabase"."subject_types"())
    limit 20
  ) r
  where m."id" = index_record_mentions.message
    and m."sent_at" is not null and m."archived_at" is null
  on conflict do nothing;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ingest_mail (
  account     uuid,
  messages    jsonb,
  next_cursor text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_account record;
  v_item jsonb;
  v_stored jsonb;
  v_new jsonb := '[]'::jsonb;
  v_threads uuid[] := '{}';
  v_thread uuid;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role syncs mailboxes' using errcode = '42501', hint = 'MAIL_FORBIDDEN';
  end if;
  select k."id" as id, k."tenant_id" as tenant, k."user_id" as owner into v_account
  from "better_supabase"."mail_accounts" k where k."id" = ingest_mail.account and k."status" <> 'disconnected';
  if v_account.id is null then
    raise exception 'no such connected mailbox' using errcode = 'P0002', hint = 'MAIL_ACCOUNT_NOT_FOUND';
  end if;
  if jsonb_typeof(coalesce(ingest_mail.messages, '[]')) <> 'array' then
    raise exception 'messages is a list' using errcode = '22023', hint = 'MAIL_MESSAGE_INVALID';
  end if;
  if jsonb_array_length(coalesce(ingest_mail.messages, '[]')) > 500 then
    raise exception 'at most 500 messages per call' using errcode = '22023', hint = 'MAIL_BATCH_TOO_LARGE';
  end if;
  for v_item in select value from jsonb_array_elements(coalesce(ingest_mail.messages, '[]')) loop
    v_stored := "better_supabase"."store_mail_message"(v_account.id, v_item);
    if not ((v_stored ->> 'threadId')::uuid = any (v_threads)) then
      v_threads := v_threads || (v_stored ->> 'threadId')::uuid;
    end if;
    if (v_stored ->> 'created')::boolean then
      v_new := v_new || jsonb_build_array(v_stored || jsonb_build_object('fromAddress', lower(coalesce(v_item -> 'from' ->> 'address', v_item ->> 'from'))));
    end if;
  end loop;
  foreach v_thread in array v_threads loop
    perform "better_supabase"."match_mail_thread"(v_thread);
    perform "better_supabase"."log_mail_thread"(v_thread);
  end loop;
  for v_stored in select value from jsonb_array_elements(v_new) loop
    if v_stored ->> 'direction' = 'outbound' then
      perform "better_supabase".emit_event('mail_message.sent', jsonb_build_object('organizationId', v_account.tenant, 'accountId', v_account.id, 'userId', v_account.owner, 'threadId', v_stored ->> 'threadId', 'messageId', v_stored ->> 'id', 'direction', v_stored ->> 'direction', 'fromAddress', v_stored ->> 'fromAddress', 'subjects', coalesce((select jsonb_agg(jsonb_build_object('type', s."subject_type", 'id', s."subject_id") order by s."created_at", s."subject_type", s."subject_id") from "better_supabase"."mail_thread_subjects" s where s."thread_id" = (v_stored ->> 'threadId')::uuid), '[]'::jsonb)), 'mail-messages/' || (v_stored ->> 'id'), (v_account.tenant::text)::text, 'mail_message:' || (v_stored ->> 'id'), 'better-supabase/mail-sync');
    else
      perform "better_supabase".emit_event('mail_message.received', jsonb_build_object('organizationId', v_account.tenant, 'accountId', v_account.id, 'userId', v_account.owner, 'threadId', v_stored ->> 'threadId', 'messageId', v_stored ->> 'id', 'direction', v_stored ->> 'direction', 'fromAddress', v_stored ->> 'fromAddress', 'subjects', coalesce((select jsonb_agg(jsonb_build_object('type', s."subject_type", 'id', s."subject_id") order by s."created_at", s."subject_type", s."subject_id") from "better_supabase"."mail_thread_subjects" s where s."thread_id" = (v_stored ->> 'threadId')::uuid), '[]'::jsonb)), 'mail-messages/' || (v_stored ->> 'id'), (v_account.tenant::text)::text, 'mail_message:' || (v_stored ->> 'id'), 'better-supabase/mail-sync');
    end if;
  end loop;
  update "better_supabase"."mail_accounts" x set
    "sync_cursor" = coalesce(ingest_mail.next_cursor, x."sync_cursor"),
    "last_synced_at" = now(),
    "status" = case when x."status" = 'error' then 'active' else x."status" end,
    "last_error" = null,
    "updated_at" = now()
  where x."id" = v_account.id;
  return jsonb_build_object('stored', jsonb_array_length(v_new), 'threads', coalesce(array_length(v_threads, 1), 0));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ingest_observations (
  tenant uuid,
  items  jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_item jsonb;
  v_row "better_supabase"."observations"%rowtype;
  v_external text;
  v_source text;
  v_ids jsonb := '[]'::jsonb;
  v_skipped integer := 0;
begin
  if not coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then
    raise exception 'only the service role ingests observations' using errcode = '42501', hint = 'OBSERVATION_FORBIDDEN';
  end if;
  if jsonb_typeof(ingest_observations.items) is distinct from 'array' or jsonb_array_length(ingest_observations.items) not between 1 and 500 then
    raise exception 'items is an array of 1 to 500 observations' using errcode = '22023', hint = 'OBSERVATION_INVALID';
  end if;
  for v_item in select i from jsonb_array_elements(ingest_observations.items) i loop
    if jsonb_typeof(v_item) <> 'object' or nullif(v_item ->> 'subjectType', '') is null or nullif(v_item ->> 'subjectId', '') is null or nullif(v_item ->> 'definitionKey', '') is null then
      raise exception 'each item has a subjectType, a subjectId, a definitionKey and a value' using errcode = '22023', hint = 'OBSERVATION_INVALID';
    end if;
    v_external := nullif(trim(v_item ->> 'externalId'), '');
    if v_external is null or length(v_external) > 200 then
      raise exception 'each ingested item has an externalId of at most 200 characters' using errcode = '22023', hint = 'OBSERVATION_INVALID';
    end if;
    v_source := coalesce(v_item ->> 'source', 'device');
    if v_source not in ('device', 'import') then
      raise exception 'source is device or import' using errcode = '22023', hint = 'OBSERVATION_INVALID';
    end if;
    if not (case when coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then coalesce((case v_item ->> 'subjectType'
      when 'message' then (select s."tenant_id"::text from "better_supabase"."messages" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'conversation' then (select s."tenant_id"::text from "better_supabase"."conversations" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'channel' then (select s."tenant_id"::text from "better_supabase"."channels" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'company' then (select s."tenant_id"::text from "better_supabase"."companies" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'person' then (select s."tenant_id"::text from "better_supabase"."people" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'deal' then (select s."tenant_id"::text from "better_supabase"."deals" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'course' then (select s."tenant_id"::text from "better_supabase"."courses" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'post' then (select s."tenant_id"::text from "better_supabase"."posts" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'activity' then (select s."tenant_id"::text from "better_supabase"."activities" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'quote' then (select s."tenant_id"::text from "better_supabase"."quotes" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'work_item' then (select s."tenant_id"::text from "better_supabase"."work_items" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'employee' then (select s."tenant_id"::text from "better_supabase"."employees" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'ledger_account' then (select s."tenant_id"::text from "better_supabase"."ledger_accounts" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'invoice' then (select s."tenant_id"::text from "better_supabase"."invoices" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'product' then (select s."tenant_id"::text from "better_supabase"."products" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'product_variant' then (select s."tenant_id"::text from "better_supabase"."product_variants" s where s."id" = (v_item ->> 'subjectId')::uuid)
      when 'rfq' then (select s."tenant_id"::text from "better_supabase"."rfqs" s where s."id" = (v_item ->> 'subjectId')::uuid)
