    end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('bsb_observations_ingest:' || ingest_observations.tenant::text || ':' || v_external, 0));
    if exists (select 1 from "better_supabase"."observations" x where x."tenant_id" = ingest_observations.tenant and x."external_id" = v_external) then
      v_skipped := v_skipped + 1;
      continue;
    end if;
    select * into v_row from "better_supabase"."observation_insert"(ingest_observations.tenant, "better_supabase"."observation_definition_id"(ingest_observations.tenant, v_item ->> 'definitionKey'), v_item ->> 'subjectType', v_item ->> 'subjectId', v_item -> 'value', (v_item ->> 'observedAt')::timestamptz, v_item -> 'details', v_source, v_external, null, null, null, v_item -> 'fields');
    v_ids := v_ids || jsonb_build_array(v_row."id");
  end loop;
  return jsonb_build_object('inserted', jsonb_array_length(v_ids), 'skipped', v_skipped, 'ids', v_ids);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ingest_tracking_events (
  carrier         text,
  tracking_number text,
  events          jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_ship "better_supabase"."shipments"%rowtype;
  v_count integer;
  v_status text;
  v_at timestamptz;
  v_from text;
begin
  select * into v_ship from "better_supabase"."shipments" x
    where x."carrier" = ingest_tracking_events.carrier
      and x."tracking_number" = ingest_tracking_events.tracking_number
    for update;
  if not found then
    return null;
  end if;
  if jsonb_typeof(ingest_tracking_events.events) is distinct from 'array' or jsonb_array_length(ingest_tracking_events.events) > 500 then
    raise exception 'pass the tracking events as an array of at most 500' using errcode = '22023', hint = 'SHIPMENT_TRACKING_INVALID';
  end if;
  begin
    with inserted as (
      insert into "better_supabase"."shipment_tracking_events" ("tenant_id", "shipment_id", "external_id", "status", "occurred_at", "description", "location", "source")
      select v_ship."tenant_id", v_ship."id", i ->> 'id', i ->> 'status', (i ->> 'occurredAt')::timestamptz, nullif(i ->> 'description', ''), nullif(i ->> 'location', ''), 'webhook'
      from jsonb_array_elements(ingest_tracking_events.events) i
      on conflict ("shipment_id", "external_id") do nothing
      returning 1
    )
    select count(*)::integer into v_count from inserted;
  exception when check_violation or not_null_violation or invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
    raise exception 'each tracking event needs an id, a known status and an ISO 8601 occurredAt' using errcode = '22023', hint = 'SHIPMENT_TRACKING_INVALID';
  end;
  select t."status", t."occurred_at" into v_status, v_at
    from "better_supabase"."shipment_tracking_events" t
    where t."shipment_id" = v_ship."id"
    order by t."occurred_at" desc, array_position(array['label_created', 'in_transit', 'out_for_delivery', 'delivered', 'exception', 'returned']::text[], t."status") desc
    limit 1;
  if v_status is not null and v_ship."status" <> 'cancelled' and v_status <> v_ship."status" then
    v_from := v_ship."status";
    update "better_supabase"."shipments" x set
      "status" = v_status,
      "delivered_at" = case when v_status = 'delivered' then v_at end,
      "updated_at" = now()
    where x."id" = v_ship."id"
    returning * into v_ship;
    perform "better_supabase".emit_event('shipment.status_changed', jsonb_build_object('organizationId', v_ship."tenant_id"::text, 'id', v_ship."id", 'from', v_from, 'to', v_ship."status", 'trackingNumber', v_ship."tracking_number"), 'shipments/' || v_ship."id"::text, (v_ship."tenant_id")::text, null, 'better-supabase/shipments');
  end if;
  return jsonb_build_object('id', v_ship."id", 'organizationId', v_ship."tenant_id"::text, 'status', v_ship."status", 'recorded', v_count);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inspection_assignment_notice()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."inspections"%rowtype;
  v_claims text;
begin
  if new."user_id" is not distinct from auth.uid() then
    return new;
  end if;
  select * into v_row from "better_supabase"."inspections" x where x."id" = new."inspection_id";
  if not found or v_row."status" not in ('planned', 'in_progress') then
    return new;
  end if;
  if better_supabase.import_run() is null then
    v_claims := current_setting('request.jwt.claims', true);
    perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
    perform "better_supabase"."notify"(jsonb_build_object(
      'type', 'inspection.assigned',
      'tenant', v_row."tenant_id",
      'actor', auth.uid(),
      'subject_type', 'inspection',
      'subject_id', v_row."id"::text,
      'summary', v_row."number" || ' ' || v_row."title",
      'recipients', to_jsonb(array[new."user_id"]),
      'key', 'inspection.assigned:' || v_row."id"::text || ':' || new."user_id"::text,
      'data', jsonb_build_object('inspectionId', v_row."id", 'role', new."role")
    ));
    perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inspection_calendar_mirror()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_calendar uuid;
begin
  select y."id" into v_calendar from "better_supabase"."calendars" y
  where y."tenant_id" = new."tenant_id" and y."name" = 'Audits'
  order by y."created_at"
  limit 1;
  if v_calendar is null then
    return new;
  end if;
  if new."planned_start" is null or new."status" not in ('planned', 'in_progress') then
    delete from "better_supabase"."calendar_events" x where x."calendar_id" = v_calendar and x."uid" = 'inspection-' || new."id"::text;
    return new;
  end if;
  insert into "better_supabase"."calendar_events" ("tenant_id", "calendar_id", "uid", "title", "starts_at", "ends_at", "all_day", "tz", "status", "subject_type", "subject_id")
  values (new."tenant_id", v_calendar, 'inspection-' || new."id"::text, new."number" || ' ' || new."title",
    (new."planned_start"::timestamp at time zone 'UTC'),
    (coalesce(new."planned_end", new."planned_start") + 1)::timestamp at time zone 'UTC', true, 'UTC', 'confirmed', 'inspection', new."id"::text)
  on conflict ("calendar_id", "uid", "original_starts_at") do update set
    "title" = excluded."title", "starts_at" = excluded."starts_at",
    "ends_at" = excluded."ends_at", "updated_at" = now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inspection_role (
  inspection_id uuid
)
  RETURNS text
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select x."role" from "better_supabase"."inspection_members" x
  where x."inspection_id" = inspection_role.inspection_id and x."user_id" = auth.uid();
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inspection_set_team (
  inspection_id uuid,
  tenant        uuid,
  team          jsonb
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_team jsonb := coalesce(inspection_set_team.team, '[]'::jsonb);
begin
  if jsonb_typeof(v_team) is distinct from 'array' then
    raise exception 'members must be a list' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_team) e
    where jsonb_typeof(e) <> 'object' or coalesce(e ->> 'userId', '') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      or coalesce(e ->> 'role', '') not in ('lead', 'auditor', 'observer', 'auditee')
  ) then
    raise exception 'each member needs a userId and a role of lead, auditor, observer or auditee' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  if (select count(distinct e ->> 'userId') from jsonb_array_elements(v_team) e) <> jsonb_array_length(v_team) then
    raise exception 'a user is listed twice' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  if (select count(*) from jsonb_array_elements(v_team) e where e ->> 'role' = 'lead') > 1 then
    raise exception 'an inspection has one lead' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_team) e
    where not exists (
      select 1 from "public"."memberships" y
      where y."organization_id" = inspection_set_team.tenant
        and y."user_id" = (e ->> 'userId')::uuid
    )
  ) then
    raise exception 'every member must belong to the organization' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  delete from "better_supabase"."inspection_members" x where x."inspection_id" = inspection_set_team.inspection_id;
  insert into "better_supabase"."inspection_members" ("inspection_id", "tenant_id", "user_id", "role")
  select inspection_set_team.inspection_id, inspection_set_team.tenant, (e ->> 'userId')::uuid, e ->> 'role'
  from jsonb_array_elements(v_team) e;
  return (select (e ->> 'userId')::uuid from jsonb_array_elements(v_team) e where e ->> 'role' = 'lead');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inspection_team_with_lead (
  team    jsonb,
  lead_id uuid
)
  RETURNS jsonb
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select case when inspection_team_with_lead.lead_id is null then coalesce(inspection_team_with_lead.team, '[]'::jsonb)
  else coalesce((
    select jsonb_agg(case when e ->> 'role' = 'lead' then e || '{"role": "auditor"}'::jsonb else e end)
    from jsonb_array_elements(coalesce(inspection_team_with_lead.team, '[]'::jsonb)) e
    where jsonb_typeof(e) <> 'object' or e ->> 'userId' is distinct from inspection_team_with_lead.lead_id::text
  ), '[]'::jsonb) || jsonb_build_array(jsonb_build_object('userId', inspection_team_with_lead.lead_id, 'role', 'lead')) end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.install_agent (
  tenant    uuid,
  agent_id  uuid,
  installed boolean DEFAULT true
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if auth.uid() is null or not coalesce(better_supabase.can('tenant', install_agent.tenant, 'agents.read'), false) then
    raise exception 'you may not use agents here' using errcode = '42501', hint = 'AGENT_FORBIDDEN';
  end if;
  if not install_agent.installed then
    delete from "better_supabase"."agent_installs" n where n."agent_id" = install_agent.agent_id and n."user_id" = auth.uid() and n."tenant_id" = install_agent.tenant;
    get diagnostics v_count = row_count;
    update "better_supabase"."agents" x set "install_count" = greatest(x."install_count" - v_count, 0) where x."id" = install_agent.agent_id;
    if v_count > 0 then
      perform "better_supabase".emit_event('agent.uninstalled', jsonb_build_object('organizationId', install_agent.tenant::text, 'agentId', install_agent.agent_id, 'userId', auth.uid()), 'organizations/' || install_agent.tenant::text || '/agents/' || install_agent.agent_id::text, (install_agent.tenant)::text, null, 'better-supabase/agents');
  perform better_supabase.audit_event(
    event_type => 'agent.uninstalled',
    category => 'ai',
    target_type => 'agent',
    record_id => install_agent.agent_id::text,
    tenant => (install_agent.tenant)::uuid,
    metadata => jsonb_build_object('organizationId', install_agent.tenant::text, 'agentId', install_agent.agent_id, 'userId', auth.uid())
  );
    end if;
    return v_count > 0;
  end if;
  if not exists (select 1 from "better_supabase"."agents" x where x."id" = install_agent.agent_id and (x."owner_id" = (select auth.uid()) or (x."published_at" is not null and (x."visibility" = 'public' or (x."visibility" = 'organization' and x."tenant_id" in (select better_supabase.tenant_ids_with('agents.read'))))) or x."tenant_id" in (select better_supabase.tenant_ids_with('agents.moderate')))) then
    raise exception 'agent % not found', install_agent.agent_id using errcode = 'P0002', hint = 'AGENT_NOT_FOUND';
  end if;
  insert into "better_supabase"."agent_installs" ("agent_id", "user_id", "tenant_id") values (install_agent.agent_id, auth.uid(), install_agent.tenant)
  on conflict do nothing;
  get diagnostics v_count = row_count;
  update "better_supabase"."agents" x set "install_count" = x."install_count" + v_count where x."id" = install_agent.agent_id;
  if v_count > 0 then
    perform "better_supabase".emit_event('agent.installed', jsonb_build_object('organizationId', install_agent.tenant::text, 'agentId', install_agent.agent_id, 'userId', auth.uid()), 'organizations/' || install_agent.tenant::text || '/agents/' || install_agent.agent_id::text, (install_agent.tenant)::text, null, 'better-supabase/agents');
  perform better_supabase.audit_event(
    event_type => 'agent.installed',
    category => 'ai',
    target_type => 'agent',
    record_id => install_agent.agent_id::text,
    tenant => (install_agent.tenant)::uuid,
    metadata => jsonb_build_object('organizationId', install_agent.tenant::text, 'agentId', install_agent.agent_id, 'userId', auth.uid())
  );
  end if;
  return v_count > 0;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.install_default_rules (
  tenant uuid
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  insert into "better_supabase"."automations" ("tenant_id", "subject_type", "trigger", "name", "description", "conditions", "actions", "enabled", "default_key", "created_by", "updated_by")
  select install_default_rules.tenant, x."subject_type", x."trigger", x."name", x."description", x."conditions", x."actions", x."enabled", x."key", null, null
  from "better_supabase"."automation_defaults" x
  where not exists (
    select 1 from "better_supabase"."automations" y where y."tenant_id" = install_default_rules.tenant and y."default_key" = x."key"
  )
  on conflict do nothing;
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.install_field_pack (
  tenant uuid,
  pack   jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_key text := install_field_pack.pack ->> 'key';
  v_version integer;
  v_entity text;
  v_fields jsonb;
  v_field jsonb;
  v_field_key text;
  v_label text;
  v_type text;
  v_required boolean;
  v_sensitive boolean;
  v_permission text;
  v_row record;
  v_id uuid;
  v_last text;
  v_rank text;
  v_created integer := 0;
  v_updated integer := 0;
  v_unchanged integer := 0;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', install_field_pack.tenant, 'custom_fields.manage'), false)) then
    raise exception 'not allowed to manage custom fields' using errcode = '42501', hint = 'FIELD_FORBIDDEN';
  end if;
  if jsonb_typeof(install_field_pack.pack) is distinct from 'object' or install_field_pack.pack ->> 'apiVersion' is distinct from '1' then
    raise exception 'a field pack is an object with apiVersion 1' using errcode = '22023', hint = 'FIELD_PACK_INVALID';
  end if;
  if v_key is null or v_key !~ '^[a-z][a-z0-9_.-]{0,62}$' then
    raise exception 'a field pack needs a key in lower case' using errcode = '22023', hint = 'FIELD_PACK_INVALID';
  end if;
  begin
    v_version := (install_field_pack.pack ->> 'version')::integer;
  exception when invalid_text_representation or numeric_value_out_of_range then
    v_version := null;
  end;
  if v_version is null or v_version < 1 then
    raise exception 'a field pack needs a version of 1 or more' using errcode = '22023', hint = 'FIELD_PACK_INVALID';
  end if;
  if jsonb_typeof(install_field_pack.pack -> 'subjects') is distinct from 'object' then
    raise exception 'a field pack needs subjects: { <type>: fields }' using errcode = '22023', hint = 'FIELD_PACK_INVALID';
  end if;

  for v_entity, v_fields in select s.key, s.value from jsonb_each(install_field_pack.pack -> 'subjects') s order by s.key loop
    if v_entity is null or v_entity <> all (array['message', 'conversation', 'channel', 'company', 'person', 'deal', 'course', 'post', 'activity', 'quote', 'work_item', 'employee', 'ledger_account', 'invoice', 'product', 'product_variant', 'rfq', 'till', 'order', 'calendar_event', 'booking', 'asset', 'asset_location', 'lease', 'expense_report', 'expense_line', 'donation_fund', 'warranty_claim', 'work_order', 'shipment', 'contract', 'control', 'compliance_policy', 'qualification_type', 'risk', 'case', 'inspection', 'inspection_program', 'inspection_finding', 'form', 'meeting', 'meeting_decision', 'maintenance_plan', 'dam_usage_right', 'lims_sample', 'tax_code', 'production_order', 'work_center', 'bank_account', 'care_plan', 'incident', 'content_entry', 'document', 'customer', 'drive_node', 'organization', 'application', 'change_request', 'project', 'task']::text[]) then
    raise exception 'the entity is not a registered subject type' using errcode = '22023', hint = 'FIELD_ENTITY_UNKNOWN';
  end if;
    if jsonb_typeof(v_fields) is distinct from 'array' then
      raise exception 'the fields of a subject type are a list' using errcode = '22023', hint = 'FIELD_PACK_INVALID';
    end if;
    for v_field in select f.value from jsonb_array_elements(v_fields) f loop
      if jsonb_typeof(v_field) is distinct from 'object' then
        raise exception 'a field is an object of key, label and type' using errcode = '22023', hint = 'FIELD_PACK_INVALID';
      end if;
      v_field_key := v_field ->> 'key';
      v_label := v_field ->> 'label';
      v_type := v_field ->> 'type';
      v_permission := nullif(v_field ->> 'permission', '');
      if v_field_key is null or v_field_key !~ '^[a-z][a-z0-9_.-]{0,62}$' or v_label is null or btrim(v_label) = '' then
        raise exception 'a field needs a key in lower case and a label' using errcode = '22023', hint = 'FIELD_PACK_INVALID';
      end if;
      if v_type is null or v_type not in ('text', 'number', 'date', 'bool', 'option', 'json', 'email', 'url', 'multi_option', 'user', 'rating', 'currency', 'bsn', 'iban', 'phone_e164') then
        raise exception 'a field needs one of the custom field types' using errcode = '22023', hint = 'FIELD_PACK_INVALID';
      end if;
      if (v_field ? 'required' and jsonb_typeof(v_field -> 'required') <> 'boolean') or (v_field ? 'sensitive' and jsonb_typeof(v_field -> 'sensitive') <> 'boolean') then
        raise exception 'required and sensitive are booleans' using errcode = '22023', hint = 'FIELD_PACK_INVALID';
      end if;
      v_required := coalesce((v_field ->> 'required')::boolean, false);
      v_sensitive := coalesce((v_field ->> 'sensitive')::boolean, false);

      select d."id" as id, d."pack" as pack, d."pack_version" as version, d."label" as label, d."type" as type,
        d."required" as required, d."sensitive" as sensitive, d."permission" as permission
      into v_row
      from "better_supabase"."field_definitions" d
      where d."tenant_id" = install_field_pack.tenant and d."entity" = v_entity and d."key" = v_field_key;

      if not found then
        select max(d."rank" collate "C") into v_last from "better_supabase"."field_definitions" d
        where d."tenant_id" = install_field_pack.tenant and d."entity" = v_entity;
        v_rank := case
    when v_last is null then 'V'
    when length(substring(v_last from '^z*')) = length(v_last) then v_last || 'V'
    else left(v_last, length(substring(v_last from '^z*'))) || substr('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', (strpos('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', substr(v_last, length(substring(v_last from '^z*')) + 1, 1)) - 1 + 62) / 2 + 1, 1)
  end;
        insert into "better_supabase"."field_definitions" ("tenant_id", "entity", "key", "label", "type", "required", "sensitive", "permission", "pack", "pack_version", "rank")
        values (install_field_pack.tenant, v_entity, v_field_key, v_label, v_type, v_required, v_sensitive, v_permission, v_key, v_version, v_rank)
        returning "id" into v_id;
        v_created := v_created + 1;
        perform "better_supabase".emit_event('field_definition.created', jsonb_build_object('organizationId', install_field_pack.tenant, 'id', v_id, 'entity', v_entity), 'custom-fields/' || v_id::text, (install_field_pack.tenant)::text, null, 'better-supabase/custom-fields');
      elsif v_row.pack is distinct from v_key then
        raise exception 'the field already exists and doesn''t belong to this pack' using errcode = '23505', hint = 'FIELD_PACK_CONFLICT';
      elsif v_row.label = v_label and v_row.type = v_type and v_row.required = v_required and v_row.sensitive = v_sensitive
        and v_row.permission is not distinct from v_permission and v_row.version is not distinct from v_version then
        v_unchanged := v_unchanged + 1;
      else
        update "better_supabase"."field_definitions" set "label" = v_label, "type" = v_type, "required" = v_required, "sensitive" = v_sensitive,
          "permission" = v_permission, "pack_version" = v_version
        where "id" = v_row.id;
        v_updated := v_updated + 1;
        perform "better_supabase".emit_event('field_definition.updated', jsonb_build_object('organizationId', install_field_pack.tenant, 'id', v_row.id, 'entity', v_entity), 'custom-fields/' || v_row.id::text, (install_field_pack.tenant)::text, null, 'better-supabase/custom-fields');
      end if;
    end loop;
  end loop;
  return jsonb_build_object('pack', v_key, 'version', v_version, 'created', v_created, 'updated', v_updated, 'unchanged', v_unchanged);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.instrument_status (
  tenant   uuid,
  asset_id uuid,
  on_date  date DEFAULT CURRENT_DATE
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (instrument_status.tenant is not null and coalesce(better_supabase.can('tenant', instrument_status.tenant, 'lims.read'), false))) then
    raise exception 'not allowed to read instruments' using errcode = '42501', hint = 'LIMS_FORBIDDEN';
  end if;
  return jsonb_build_object('instrumentId', instrument_status.asset_id, 'required', true,
    'qualified', "better_supabase"."qualified_holders"(instrument_status.tenant, 'calibration', 'asset', coalesce(instrument_status.on_date, current_date)) @> to_jsonb(instrument_status.asset_id::text));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.interactive_only (
  permission text
)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select coalesce(permission = any (array['organization.delete', 'organization.transfer_ownership', 'platform.invite', 'sso.manage']::text[]), false)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.interactive_only_role (
  role text
)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select coalesce(role = 'owner', false)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.interactive_session()
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select auth.jwt() is null
    or (auth.jwt() -> 'api_key' is null
      and coalesce(auth.jwt() ->> 'client_id', '') = ''
      and auth.jwt() -> 'act' is null)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inventory_levels (
  tenant      uuid,
  variant_ids uuid[] DEFAULT NULL::uuid[],
  location_id uuid   DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'variantId', y."variant_id",
    'locationId', y."location_id",
    'onHand', y."on_hand"::text,
    'allocated', y."reserved"::text,
    'available', y."available"::text,
    'incoming', y."incoming"::text,
    'reorderPoint', y."reorder_point"::text,
    'status', case
      when y."available" <= 0 then 'out'
      when y."reorder_point" is not null and y."available" <= y."reorder_point" then 'low'
      else 'in_stock'
    end
  )), '[]'::jsonb)
  from "better_supabase"."stock_levels" y
  where y."tenant_id" = inventory_levels.tenant
    and (inventory_levels.variant_ids is null or y."variant_id" = any (inventory_levels.variant_ids))
    and (inventory_levels.location_id is null or y."location_id" = inventory_levels.location_id)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inventory_overview (
  tenant      uuid,
  row_limit   integer DEFAULT 20,
  expiry_days integer DEFAULT 30
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  v_low jsonb;
  v_low_count integer;
  v_level_count integer;
  v_expiring jsonb;
begin
  select count(*)::integer into v_level_count
  from "better_supabase"."stock_levels" y where y."tenant_id" = inventory_overview.tenant;

  select count(*)::integer into v_low_count
  from "better_supabase"."stock_levels" y
  where y."tenant_id" = inventory_overview.tenant
    and y."reorder_point" is not null and y."available" <= y."reorder_point";

  select coalesce(jsonb_agg(jsonb_build_object(
      'variantId', x."variant_id", 'locationId', x."location_id",
      'onHand', x."on_hand"::text, 'available', x."available"::text,
      'reorderPoint', x."reorder_point"::text)
    order by x."available" - x."reorder_point", x."variant_id", x."location_id"), '[]'::jsonb)
  into v_low
  from (
    select * from "better_supabase"."stock_levels" y
    where y."tenant_id" = inventory_overview.tenant
      and y."reorder_point" is not null and y."available" <= y."reorder_point"
    order by y."available" - y."reorder_point", y."variant_id", y."location_id"
    limit greatest(coalesce(inventory_overview.row_limit, 20), 0)
  ) x;

  select coalesce(jsonb_agg(jsonb_build_object(
      'lotId', e ->> 'lotId', 'code', e ->> 'code', 'variantId', e ->> 'variantId',
      'locationId', e ->> 'locationId', 'expiresOn', e ->> 'expiresOn', 'onHand', e ->> 'onHand')), '[]'::jsonb)
  into v_expiring
  from jsonb_array_elements("better_supabase"."expiring_lots"(inventory_overview.tenant,
    current_date + greatest(coalesce(inventory_overview.expiry_days, 30), 0))) e;

  return jsonb_build_object('levelCount', v_level_count, 'lowStockCount', v_low_count,
    'lowStock', v_low, 'expiring', v_expiring);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.inventory_status_counts (
  tenant uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'inStock', count(*) filter (where y."available" > 0 and (y."reorder_point" is null or y."available" > y."reorder_point")),
    'low', count(*) filter (where y."reorder_point" is not null and y."available" <= y."reorder_point" and y."available" > 0),
    'out', count(*) filter (where y."available" <= 0)
  )
  from "better_supabase"."stock_levels" y
  where y."tenant_id" = inventory_status_counts.tenant
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invitation_extra (
  invitation uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  hook regprocedure := to_regprocedure('"public"."invitation_preview_extra"(uuid)');
  extra jsonb;
begin
  if hook is null or invitation is null then
    return '{}'::jsonb;
  end if;
  -- Not a literal name, so plpgsql_check passes without the hook.
  execute format('select %s($1)', hook::oid::regproc) into extra using invitation;
  return coalesce(extra, '{}'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invitation_preview (
  token text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  preview jsonb;
  invitation uuid;
begin
  select jsonb_build_object(
    'status', case
    when i."accepted_at" is not null then 'accepted'
    when i."declined_at" is not null then 'declined'
    when i."revoked_at" is not null then 'revoked'
    when i."expires_at" < now() then 'expired'
    else 'pending'
  end,
    'email', i."email",
    'role', i."role",
    'tenant', i."tenant_id",
    'expires_at', i."expires_at",
    'organization', (select jsonb_build_object('id', o."id", 'name', o."name")
      from "public"."organizations" o where o."id" = i."tenant_id"),
    'prefill', '{}'::jsonb
  ), i."id"
  into preview, invitation
  from "better_supabase"."invitations" i
  where i."token_hash" = encode(extensions.digest(invitation_preview.token, 'sha256'), 'hex');
  if preview is null then
    select jsonb_build_object(
    'status', case
    when i."accepted_at" is not null then 'accepted'
    when i."declined_at" is not null then 'declined'
    when i."revoked_at" is not null then 'revoked'
    when i."expires_at" < now() then 'expired'
    else 'pending'
  end,
    'email', i."email",
    'role', i."role",
    'tenant', null,
    'expires_at', i."expires_at",
    'organization', null,
    'prefill', '{}'::jsonb
  ), i."id"
    into preview, invitation
    from "better_supabase"."platform_invitations" i
    where i."token_hash" = encode(extensions.digest(invitation_preview.token, 'sha256'), 'hex');
  end if;
  if preview is not null then
    preview := preview || "better_supabase"."invitation_extra"(invitation);
  end if;
  return preview;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invitation_tenant_ids()
  RETURNS SETOF uuid
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return query select better_supabase.tenant_ids_with('members.invite');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invite_guest (
  tenant     uuid,
  email      text,
  name       text                     DEFAULT NULL::text,
  party_type text                     DEFAULT NULL::text,
  party_id   text                     DEFAULT NULL::text,
  expires_at timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."guests"%rowtype;
  v_token text;
  v_email text := lower(btrim(invite_guest.email));
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', invite_guest.tenant, 'guests.manage'), false)) then
    raise exception 'not allowed to manage guests' using errcode = '42501', hint = 'GUEST_FORBIDDEN';
  end if;
  if (invite_guest.party_type is null) <> (invite_guest.party_id is null) then
    raise exception 'pass party_type and party_id together' using errcode = '22023', hint = 'GUEST_PARTY_INVALID';
  end if;
  if invite_guest.party_type is not null
    and (case invite_guest.party_type
      when 'message' then (select s."tenant_id"::text from "better_supabase"."messages" s where s."id" = (invite_guest.party_id)::uuid)
      when 'conversation' then (select s."tenant_id"::text from "better_supabase"."conversations" s where s."id" = (invite_guest.party_id)::uuid)
      when 'channel' then (select s."tenant_id"::text from "better_supabase"."channels" s where s."id" = (invite_guest.party_id)::uuid)
      when 'company' then (select s."tenant_id"::text from "better_supabase"."companies" s where s."id" = (invite_guest.party_id)::uuid)
      when 'person' then (select s."tenant_id"::text from "better_supabase"."people" s where s."id" = (invite_guest.party_id)::uuid)
      when 'deal' then (select s."tenant_id"::text from "better_supabase"."deals" s where s."id" = (invite_guest.party_id)::uuid)
      when 'course' then (select s."tenant_id"::text from "better_supabase"."courses" s where s."id" = (invite_guest.party_id)::uuid)
      when 'post' then (select s."tenant_id"::text from "better_supabase"."posts" s where s."id" = (invite_guest.party_id)::uuid)
      when 'activity' then (select s."tenant_id"::text from "better_supabase"."activities" s where s."id" = (invite_guest.party_id)::uuid)
      when 'quote' then (select s."tenant_id"::text from "better_supabase"."quotes" s where s."id" = (invite_guest.party_id)::uuid)
      when 'work_item' then (select s."tenant_id"::text from "better_supabase"."work_items" s where s."id" = (invite_guest.party_id)::uuid)
      when 'employee' then (select s."tenant_id"::text from "better_supabase"."employees" s where s."id" = (invite_guest.party_id)::uuid)
      when 'ledger_account' then (select s."tenant_id"::text from "better_supabase"."ledger_accounts" s where s."id" = (invite_guest.party_id)::uuid)
      when 'invoice' then (select s."tenant_id"::text from "better_supabase"."invoices" s where s."id" = (invite_guest.party_id)::uuid)
      when 'product' then (select s."tenant_id"::text from "better_supabase"."products" s where s."id" = (invite_guest.party_id)::uuid)
      when 'product_variant' then (select s."tenant_id"::text from "better_supabase"."product_variants" s where s."id" = (invite_guest.party_id)::uuid)
      when 'rfq' then (select s."tenant_id"::text from "better_supabase"."rfqs" s where s."id" = (invite_guest.party_id)::uuid)
      when 'till' then (select s."tenant_id"::text from "better_supabase"."tills" s where s."id" = (invite_guest.party_id)::uuid)
      when 'order' then (select s."tenant_id"::text from "better_supabase"."orders" s where s."id" = (invite_guest.party_id)::uuid)
      when 'calendar_event' then (select s."tenant_id"::text from "better_supabase"."calendar_events" s where s."id" = (invite_guest.party_id)::uuid)
      when 'booking' then (select s."tenant_id"::text from "better_supabase"."bookings" s where s."id" = (invite_guest.party_id)::uuid)
      when 'asset' then (select s."tenant_id"::text from "better_supabase"."assets" s where s."id" = (invite_guest.party_id)::uuid)
      when 'asset_location' then (select s."tenant_id"::text from "better_supabase"."asset_locations" s where s."id" = (invite_guest.party_id)::uuid)
      when 'lease' then (select s."tenant_id"::text from "better_supabase"."leases" s where s."id" = (invite_guest.party_id)::uuid)
      when 'expense_report' then (select s."tenant_id"::text from "better_supabase"."expense_reports" s where s."id" = (invite_guest.party_id)::uuid)
      when 'expense_line' then (select s."tenant_id"::text from "better_supabase"."expense_lines" s where s."id" = (invite_guest.party_id)::uuid)
      when 'donation_fund' then (select s."tenant_id"::text from "better_supabase"."donation_funds" s where s."id" = (invite_guest.party_id)::uuid)
      when 'warranty_claim' then (select s."tenant_id"::text from "better_supabase"."warranty_claims" s where s."id" = (invite_guest.party_id)::uuid)
      when 'work_order' then (select s."tenant_id"::text from "better_supabase"."work_orders" s where s."id" = (invite_guest.party_id)::uuid)
      when 'shipment' then (select s."tenant_id"::text from "better_supabase"."shipments" s where s."id" = (invite_guest.party_id)::uuid)
      when 'contract' then (select s."tenant_id"::text from "better_supabase"."contracts" s where s."id" = (invite_guest.party_id)::uuid)
      when 'control' then (select s."tenant_id"::text from "better_supabase"."controls" s where s."id" = (invite_guest.party_id)::uuid)
      when 'compliance_policy' then (select s."tenant_id"::text from "better_supabase"."compliance_policies" s where s."id" = (invite_guest.party_id)::uuid)
      when 'qualification_type' then (select s."tenant_id"::text from "better_supabase"."qualification_types" s where s."id" = (invite_guest.party_id)::uuid)
      when 'risk' then (select s."tenant_id"::text from "better_supabase"."risks" s where s."id" = (invite_guest.party_id)::uuid)
      when 'case' then (select s."tenant_id"::text from "better_supabase"."cases" s where s."id" = (invite_guest.party_id)::uuid)
      when 'inspection' then (select s."tenant_id"::text from "better_supabase"."inspections" s where s."id" = (invite_guest.party_id)::uuid)
      when 'inspection_program' then (select s."tenant_id"::text from "better_supabase"."inspection_programs" s where s."id" = (invite_guest.party_id)::uuid)
      when 'inspection_finding' then (select s."tenant_id"::text from "better_supabase"."inspection_findings" s where s."id" = (invite_guest.party_id)::uuid)
      when 'form' then (select s."tenant_id"::text from "better_supabase"."forms" s where s."id" = (invite_guest.party_id)::uuid)
      when 'meeting' then (select s."tenant_id"::text from "better_supabase"."meetings" s where s."id" = (invite_guest.party_id)::uuid)
      when 'meeting_decision' then (select s."tenant_id"::text from "better_supabase"."meeting_decisions" s where s."id" = (invite_guest.party_id)::uuid)
      when 'maintenance_plan' then (select s."tenant_id"::text from "better_supabase"."maintenance_plans" s where s."id" = (invite_guest.party_id)::uuid)
      when 'dam_usage_right' then (select s."tenant_id"::text from "better_supabase"."dam_usage_rights" s where s."id" = (invite_guest.party_id)::uuid)
      when 'lims_sample' then (select s."tenant_id"::text from "better_supabase"."lims_samples" s where s."id" = (invite_guest.party_id)::uuid)
      when 'tax_code' then (select s."tenant_id"::text from "better_supabase"."tax_codes" s where s."id" = (invite_guest.party_id)::uuid)
      when 'production_order' then (select s."tenant_id"::text from "better_supabase"."production_orders" s where s."id" = (invite_guest.party_id)::uuid)
      when 'work_center' then (select s."tenant_id"::text from "better_supabase"."work_centers" s where s."id" = (invite_guest.party_id)::uuid)
      when 'bank_account' then (select s."tenant_id"::text from "better_supabase"."bank_accounts" s where s."id" = (invite_guest.party_id)::uuid)
      when 'care_plan' then (select s."tenant_id"::text from "better_supabase"."care_plans" s where s."id" = (invite_guest.party_id)::uuid)
      when 'incident' then (select s."tenant_id"::text from "better_supabase"."incidents" s where s."id" = (invite_guest.party_id)::uuid)
      when 'content_entry' then (select s."tenant_id"::text from "better_supabase"."content_entries" s where s."id" = (invite_guest.party_id)::uuid)
      when 'document' then (select s."tenant_id"::text from "better_supabase"."documents" s where s."id" = (invite_guest.party_id)::uuid)
      when 'customer' then (select s."organization_id"::text from "public"."customers" s where s."id" = (invite_guest.party_id)::uuid)
      when 'drive_node' then (select s."tenant_id"::text from "better_supabase"."drive_nodes" s where s."id" = (invite_guest.party_id)::uuid)
      when 'organization' then (select s."id"::text from "public"."organizations" s where s."id" = (invite_guest.party_id)::uuid)
      when 'application' then (select s."tenant_id"::text from "better_supabase"."applications" s where s."id" = (invite_guest.party_id)::uuid)
      when 'change_request' then (select s."organization_id"::text from "public"."change_requests" s where s."id" = (invite_guest.party_id)::uuid)
      when 'project' then (select s."organization_id"::text from "public"."projects" s where s."id" = (invite_guest.party_id)::uuid)
      when 'task' then (select s."organization_id"::text from "public"."tasks" s where s."id" = (invite_guest.party_id)::uuid)
      else null::text
    end) is distinct from invite_guest.tenant::text then
    raise exception 'the party does not exist in this organization' using errcode = 'P0002', hint = 'GUEST_PARTY_NOT_FOUND';
  end if;
  if invite_guest.expires_at is not null and invite_guest.expires_at <= now() then
    raise exception 'expires_at must be in the future' using errcode = '22023', hint = 'GUEST_EXPIRES_IN_PAST';
  end if;
  select * into v_row from "better_supabase"."guests" x
    where x."tenant_id" = invite_guest.tenant and lower(x."email") = v_email
    for update;
  if found and v_row."status" = 'active' then
    update "better_supabase"."guests" x set
      "name" = coalesce(invite_guest.name, x."name"),
      "party_type" = coalesce(invite_guest.party_type, x."party_type"),
      "party_id" = coalesce(invite_guest.party_id, x."party_id"),
      "updated_at" = now()
      where x."id" = v_row."id"
      returning * into v_row;
    return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id"::text, 'email', v_row."email", 'name', v_row."name", 'userId', v_row."user_id", 'partyType', v_row."party_type", 'partyId', v_row."party_id", 'status', v_row."status", 'invitedBy', v_row."invited_by", 'expiresAt', v_row."expires_at", 'acceptedAt', v_row."accepted_at", 'revokedAt', v_row."revoked_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at") || jsonb_build_object('token', null);
  end if;
  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  if found then
    update "better_supabase"."guests" x set
      "name" = coalesce(invite_guest.name, x."name"),
      "party_type" = coalesce(invite_guest.party_type, x."party_type"),
      "party_id" = coalesce(invite_guest.party_id, x."party_id"),
      "status" = 'invited',
      "user_id" = null,
      "token_hash" = encode(extensions.digest(convert_to(v_token, 'utf8'), 'sha256'), 'hex'),
      "invited_by" = auth.uid(),
      "expires_at" = invite_guest.expires_at,
      "revoked_at" = null,
      "updated_at" = now()
      where x."id" = v_row."id"
      returning * into v_row;
  else
    insert into "better_supabase"."guests" ("tenant_id", "email", "name", "party_type", "party_id", "token_hash", "invited_by", "expires_at")
    values (invite_guest.tenant, v_email, invite_guest.name, invite_guest.party_type, invite_guest.party_id, encode(extensions.digest(convert_to(v_token, 'utf8'), 'sha256'), 'hex'), auth.uid(), invite_guest.expires_at)
    returning * into v_row;
  end if;
  perform "better_supabase".emit_event('guest.invited', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'id', v_row."id", 'email', v_row."email", 'partyType', v_row."party_type", 'partyId', v_row."party_id"), 'guests/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/guests');
  perform better_supabase.audit_event(
    event_type => 'guest.invited',
    category => 'access',
    target_type => 'guest',
    record_id => v_row."id"::text,
    target_label => v_row."email",
    summary => 'invited guest ' || v_row."email",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'id', v_row."id", 'email', v_row."email", 'partyType', v_row."party_type", 'partyId', v_row."party_id")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id"::text, 'email', v_row."email", 'name', v_row."name", 'userId', v_row."user_id", 'partyType', v_row."party_type", 'partyId', v_row."party_id", 'status', v_row."status", 'invitedBy', v_row."invited_by", 'expiresAt', v_row."expires_at", 'acceptedAt', v_row."accepted_at", 'revokedAt', v_row."revoked_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at") || jsonb_build_object('token', v_token);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invite_member (
  tenant        uuid,
  invitee_email text,
  invitee_role  text,
  valid_for     interval DEFAULT '7 days'::interval,
  prefill       jsonb    DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  service boolean := coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin');
  token text := encode(extensions.gen_random_bytes(24), 'hex');
  created "better_supabase"."invitations";
  platform_created "better_supabase"."platform_invitations";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if valid_for is null or valid_for <= interval '0' or valid_for > '30 days'::interval then
    raise exception 'An invitation is valid for at most %', '30 days' using errcode = '22023', hint = 'INVITATION_VALIDITY';
  end if;
  if tenant is null then
    if not service and not (select coalesce(better_supabase.is_platform('platform.invite'), false)) then
      raise exception 'Not allowed to invite platform users' using errcode = '42501', hint = 'INVITATION_FORBIDDEN';
    end if;
    if (select r."id" from "better_supabase"."roles" r where (r."id"::text = (invitee_role)::text or r."key" = (invitee_role)::text) and r."scope"::text = 'platform' order by (r."id"::text = (invitee_role)::text) desc limit 1) is null then
      raise exception 'Unknown platform role %', invitee_role using errcode = '23514', hint = 'INVITATION_ROLE_UNKNOWN';
    end if;
    if not service and not better_supabase.platform_can_assign(auth.uid(), ((select r."id" from "better_supabase"."roles" r where (r."id"::text = (invitee_role)::text or r."key" = (invitee_role)::text) and r."scope"::text = 'platform' order by (r."id"::text = (invitee_role)::text) desc limit 1))::text) then
      raise exception 'That role is above your own' using errcode = '42501', hint = 'INVITATION_ROLE_FORBIDDEN';
    end if;
    declare
    v_hook regprocedure := to_regprocedure('"public"."before_invitation_create"(uuid, text, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::text)', v_hook::oid::regproc)
        using tenant, invitee_email, invitee_role;
    end if;
  end;
    delete from "better_supabase"."platform_invitations" i
    where lower(i."email") = lower(btrim(invitee_email)) and i."accepted_at" is null and i."declined_at" is null and i."revoked_at" is null;
    insert into "better_supabase"."platform_invitations" ("email", "role", "token_hash", "invited_by", "expires_at")
    values (lower(btrim(invitee_email)), (select r."id" from "better_supabase"."roles" r where (r."id"::text = (invitee_role)::text or r."key" = (invitee_role)::text) and r."scope"::text = 'platform' order by (r."id"::text = (invitee_role)::text) desc limit 1), encode(extensions.digest(token, 'sha256'), 'hex'), auth.uid(), now() + valid_for)
    returning * into platform_created;
    perform "better_supabase".emit_event('invitation.created', jsonb_build_object('invitationId', platform_created."id", 'organizationId', null, 'email', platform_created."email", 'role', platform_created."role"), 'invitations/' || platform_created."id"::text, null, null, 'better-supabase/invitations');
  perform better_supabase.audit_event(
    event_type => 'invitation.created',
    category => 'membership',
    target_type => 'invitation',
    record_id => platform_created."id"::text,
    metadata => jsonb_build_object('invitationId', platform_created."id", 'organizationId', null, 'email', platform_created."email", 'role', platform_created."role")
  );
    return (jsonb_build_object(
    'id', platform_created."id",
    'tenant', null,
    'email', platform_created."email",
    'role', platform_created."role",
    'expires_at', platform_created."expires_at",
    'created_at', platform_created."created_at",
    'invited_by', platform_created."invited_by",
    'organization', null,
    'prefill', '{}'::jsonb,
    'inviter', (select jsonb_build_object('id', pr."id", 'username', pr."username", 'fullName', pr."full_name", 'firstName', pr."first_name", 'lastName', pr."last_name", 'avatar', pr."avatar_url")
      from "better_supabase"."profiles" pr where pr."id" = platform_created."invited_by"),
    'token', token
  ) || "better_supabase"."invitation_extra"(platform_created."id"));
  end if;
  invitee_role := coalesce(invitee_role, 'member');
  if not service and not coalesce(better_supabase.member_can(auth.uid(), tenant, 'members.invite'), false) then
    raise exception 'Not allowed to invite members' using errcode = '42501', hint = 'INVITATION_FORBIDDEN';
  end if;
  if better_supabase.tenant_disabled(tenant) or not exists (select 1 from "public"."organizations" o where o."id" = tenant) then
    raise exception 'The organization is not active' using errcode = 'P0002', hint = 'INVITATION_INVALID';
  end if;
  if (select r."id" from "better_supabase"."roles" r where (r."id"::text = (invitee_role)::text or r."key" = (invitee_role)::text) and r."scope"::text = 'tenant' order by (r."id"::text = (invitee_role)::text) desc limit 1) is null then
    raise exception 'Unknown role %', invitee_role using errcode = '23514', hint = 'INVITATION_ROLE_UNKNOWN';
  end if;
  if not service and not better_supabase.can_assign(tenant, ((select r."id" from "better_supabase"."roles" r where (r."id"::text = (invitee_role)::text or r."key" = (invitee_role)::text) and r."scope"::text = 'tenant' order by (r."id"::text = (invitee_role)::text) desc limit 1))::text) then
    raise exception 'That role is above your own' using errcode = '42501', hint = 'INVITATION_ROLE_FORBIDDEN';
  end if;
  if exists (
    select 1 from "public"."memberships" m join auth.users u on u.id = m."user_id"
    where m."organization_id" = tenant and lower(u.email) = lower(btrim(invitee_email))
  ) then
    raise exception '% is already a member', invitee_email using errcode = '23505', hint = 'INVITATION_ALREADY_MEMBER';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_invitation_create"(uuid, text, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::text)', v_hook::oid::regproc)
        using tenant, invitee_email, invitee_role;
    end if;
  end;
  delete from "better_supabase"."invitations" i
  where i."tenant_id" = tenant
    and lower(i."email") = lower(btrim(invitee_email))
    and i."accepted_at" is null and i."declined_at" is null and i."revoked_at" is null;
  insert into "better_supabase"."invitations" ("tenant_id", "email", "role", "token_hash", "invited_by", "expires_at")
  values (tenant, lower(btrim(invitee_email)), (select r."id" from "better_supabase"."roles" r where (r."id"::text = (invitee_role)::text or r."key" = (invitee_role)::text) and r."scope"::text = 'tenant' order by (r."id"::text = (invitee_role)::text) desc limit 1), encode(extensions.digest(token, 'sha256'), 'hex'), auth.uid(), now() + valid_for)
  returning * into created;
  perform "better_supabase".emit_event('invitation.created', jsonb_build_object('invitationId', created."id", 'organizationId', tenant::text, 'email', created."email", 'role', created."role"), 'invitations/' || created."id"::text, (tenant)::text, null, 'better-supabase/invitations');
  perform better_supabase.audit_event(
    event_type => 'invitation.created',
    category => 'membership',
    target_type => 'invitation',
    record_id => created."id"::text,
    tenant => (tenant)::uuid,
    metadata => jsonb_build_object('invitationId', created."id", 'organizationId', tenant::text, 'email', created."email", 'role', created."role")
  );
  return (jsonb_build_object(
    'id', created."id",
    'tenant', created."tenant_id",
    'email', created."email",
    'role', created."role",
    'expires_at', created."expires_at",
    'created_at', created."created_at",
    'invited_by', created."invited_by",
    'organization', (select jsonb_build_object('id', o."id", 'name', o."name")
      from "public"."organizations" o where o."id" = created."tenant_id"),
    'prefill', '{}'::jsonb,
    'inviter', (select jsonb_build_object('id', pr."id", 'username', pr."username", 'fullName', pr."full_name", 'firstName', pr."first_name", 'lastName', pr."last_name", 'avatar', pr."avatar_url")
      from "better_supabase"."profiles" pr where pr."id" = created."invited_by"),
    'token', token
  ) || "better_supabase"."invitation_extra"(created."id"));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invite_rfq_supplier (
  rfq_id        uuid,
  supplier_type text,
  supplier_id   text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."rfqs";
  v_invitation "better_supabase"."rfq_suppliers";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."rfqs" x where x."id" = invite_rfq_supplier.rfq_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'rfqs.read'), false))) then
    raise exception 'no such request for quotation' using errcode = 'P0002', hint = 'RFQ_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'rfqs.write'), false))) then
    raise exception 'not allowed to invite suppliers' using errcode = '42501', hint = 'RFQ_FORBIDDEN';
  end if;
  if v_row."status" not in ('draft', 'open') then
    raise exception 'suppliers can only be invited while the request is a draft or open' using errcode = '55000', hint = 'RFQ_STATUS';
  end if;
  if coalesce(trim(invite_rfq_supplier.supplier_type), '') = '' or coalesce(trim(invite_rfq_supplier.supplier_id), '') = '' then
    raise exception 'a supplier needs a type and an id' using errcode = '22023', hint = 'RFQ_INVALID';
  end if;
  if not exists (select 1 from (select p."roles", p."supplier_status" from "better_supabase"."companies" p where p."id"::text = invite_rfq_supplier.supplier_id and p."tenant_id" = v_row."tenant_id" and p."merged_into" is null union all select p."roles", p."supplier_status" from "better_supabase"."people" p where p."id"::text = invite_rfq_supplier.supplier_id and p."tenant_id" = v_row."tenant_id" and p."merged_into" is null) s(roles, status) where (s.roles is null or cardinality(s.roles) = 0 or 'supplier' = any(s.roles)) and s.status is distinct from 'blocked') then
    raise exception 'the supplier is not an active supplier in contacts' using errcode = '22023', hint = 'RFQ_SUPPLIER_INVALID';
  end if;
  begin
    insert into "better_supabase"."rfq_suppliers" ("tenant_id", "rfq_id", "supplier_type", "supplier_id")
    values (v_row."tenant_id", v_row."id", trim(invite_rfq_supplier.supplier_type), trim(invite_rfq_supplier.supplier_id))
    returning * into v_invitation;
  exception when unique_violation then
    raise exception 'this supplier is already invited' using errcode = '22023', hint = 'RFQ_INVALID';
  when check_violation then
    raise exception 'a supplier needs a type of up to 100 and an id of up to 200 characters' using errcode = '22023', hint = 'RFQ_INVALID';
  end;
  return jsonb_build_object('id', v_invitation."id", 'rfqId', v_invitation."rfq_id", 'supplierType', v_invitation."supplier_type", 'supplierId', v_invitation."supplier_id", 'status', v_invitation."status", 'invitedAt', v_invitation."invited_at", 'respondedAt', v_invitation."responded_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invite_to_channel (
  channel uuid,
  users   uuid[]
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not exists (select 1 from "better_supabase"."channels" x where x."id" = invite_to_channel.channel) then
    raise exception 'no such channel you can read' using errcode = 'P0002', hint = 'CHANNELS_NOT_FOUND';
  end if;
  return "better_supabase"."add_conversation_members"(invite_to_channel.channel, invite_to_channel.users);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invoice_aging (
  tenant    uuid,
  currency  text,
  as_of     date,
  direction text DEFAULT 'sales'::text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with open as (
    select (x."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = x."id"), 0) - x."credited_total" - x."paid_total") as balance, coalesce(invoice_aging.as_of, current_date) - x."due_on" as late
    from "better_supabase"."invoices" x
    where x."tenant_id" = invoice_aging.tenant and x."currency" = upper(invoice_aging.currency)
      and x."kind" = 'invoice' and x."status" in ('issued', 'partially_paid') and x."direction" = coalesce(invoice_aging.direction, 'sales')
  )
  select jsonb_build_object(
    'currency', upper(invoice_aging.currency),
    'current', coalesce(sum(balance) filter (where late <= 0), 0)::text,
    'days1To30', coalesce(sum(balance) filter (where late between 1 and 30), 0)::text,
    'days31To60', coalesce(sum(balance) filter (where late between 31 and 60), 0)::text,
    'days61To90', coalesce(sum(balance) filter (where late between 61 and 90), 0)::text,
    'over90', coalesce(sum(balance) filter (where late > 90), 0)::text,
    'outstanding', coalesce(sum(balance), 0)::text,
    'overdueCount', count(*) filter (where late > 0)
  )
  from open
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invoice_approval_state (
  invoice uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."invoices";
  v_entity uuid;
  v_scoped boolean;
  v_required jsonb;
  v_approved jsonb;
  v_pending jsonb;
  v_status text;
begin
  select * into v_row from "better_supabase"."invoices" x where x."id" = invoice_approval_state.invoice;
  if not found then
    return null;
  end if;
  if v_row."direction" <> 'purchase' or v_row."kind" <> 'invoice' then
    return jsonb_build_object('status', 'not_required', 'required', '[]'::jsonb, 'approved', '[]'::jsonb, 'pending', '[]'::jsonb);
  end if;
  v_entity := v_row.legal_entity_id;
  v_scoped := v_entity is not null and exists (
    select 1 from "better_supabase"."invoice_approval_levels" l where l."tenant_id" = v_row."tenant_id" and l."legal_entity_id" = v_entity
  );
  select coalesce(jsonb_agg(l."level" order by l."level"), '[]'::jsonb),
    coalesce(jsonb_agg(l."level" order by l."level") filter (where a."id" is not null), '[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object('level', l."level", 'approverId', l."approver_id", 'minAmount', l."min_amount"::text) order by l."level") filter (where a."id" is null), '[]'::jsonb)
  into v_required, v_approved, v_pending
  from "better_supabase"."invoice_approval_levels" l
  left join "better_supabase"."invoice_approvals" a on a."invoice_id" = v_row."id" and a."level" = l."level"
  where l."tenant_id" = v_row."tenant_id"
    and l."legal_entity_id" is not distinct from (case when v_scoped then v_entity end)
    and l."min_amount" <= v_row."total"
    and (l."currency" is null or l."currency" = v_row."currency"::text);
  v_status := case when jsonb_array_length(v_required) = 0 then 'not_required'
    when jsonb_array_length(v_pending) = 0 then 'approved' else 'pending' end;
  return jsonb_build_object('status', v_status, 'required', v_required, 'approved', v_approved, 'pending', v_pending);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invoice_from_quote (
  quote               uuid,
  deposit_bps         integer,
  deposit_amount      bigint  DEFAULT NULL::bigint,
  deposit_description text    DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_quote "better_supabase"."quotes";
  v_row "better_supabase"."invoices";
  v_lines jsonb;
  v_header jsonb := '{}'::jsonb;
begin
  select * into v_quote from "better_supabase"."quotes" x where x."id" = invoice_from_quote.quote;
  if v_quote."id" is null or not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', v_quote."tenant_id", 'invoices.write'), false)) then
    raise exception 'no such quote you can invoice' using errcode = 'P0002', hint = 'INVOICE_ORIGIN_NOT_FOUND';
  end if;
  if v_quote."status" <> 'accepted' then
    raise exception 'only an accepted quote is invoiced' using errcode = '55000', hint = 'INVOICE_QUOTE_NOT_ACCEPTED';
  end if;
  if (v_quote."variant_of" is not null or exists (select 1 from "better_supabase"."quotes" s where s."variant_of" = v_quote."id"))
    and not v_quote."is_selected" then
    raise exception 'this quote is one of several variants; select a variant first' using errcode = '55000', hint = 'QUOTE_VARIANT_NOT_SELECTED';
  end if;
  if invoice_from_quote.deposit_bps is not null and (invoice_from_quote.deposit_bps <= 0 or invoice_from_quote.deposit_bps >= 10000) then
    raise exception 'a deposit is between 0 and 100 percent' using errcode = '22023', hint = 'INVOICE_DEPOSIT_INVALID';
  end if;
  if invoice_from_quote.deposit_bps is not null and invoice_from_quote.deposit_amount is not null then
    raise exception 'a deposit is a share (deposit_bps) or an amount (deposit_amount), not both' using errcode = '22023', hint = 'INVOICE_DEPOSIT_INVALID';
  end if;
  if invoice_from_quote.deposit_amount is not null and (invoice_from_quote.deposit_amount <= 0 or invoice_from_quote.deposit_amount > v_quote."total") then
    raise exception 'a deposit amount is positive and at most the quote''s total' using errcode = '22023', hint = 'INVOICE_DEPOSIT_INVALID';
  end if;
  if invoice_from_quote.deposit_bps is null and invoice_from_quote.deposit_amount is null then
    select * into v_row from "better_supabase"."invoices" x
    where x."origin_type" = 'quote' and x."origin_id"::text = v_quote."id"::text
      and x."deposit_bps" is null and x."deposit_amount" is null and x."status" <> 'void' and x."kind" = 'invoice' and not (x."total" > 0 and x."credited_total" >= x."total")
    limit 1;
    if v_row."id" is not null then
      return to_jsonb(v_row) || jsonb_build_object('number', v_row."number"::text, 'paid_total', v_row."paid_total"::text, 'credited_total', v_row."credited_total"::text, 'list_total', v_row."list_total"::text, 'discount_total', v_row."discount_total"::text, 'subtotal', v_row."subtotal"::text, 'tax_total', v_row."tax_total"::text, 'total', v_row."total"::text, 'deposit_amount', v_row."deposit_amount"::text, 'discount_amount', v_row."discount_amount"::text, 'discount_amount_early', v_row."discount_amount_early"::text) || jsonb_build_object(
      'balance', (v_row."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), 0) - v_row."credited_total" - v_row."paid_total")::text,
      'charged_total', coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), 0)::text,
      'charges', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'amount', y."amount"::text, 'description', y."description", 'createdAt', y."created_at") order by y."created_at") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), '[]'::jsonb),
      'overdue', v_row."status" in ('issued', 'partially_paid') and v_row."due_on" < current_date,
      'lines', coalesce((select jsonb_agg(jsonb_build_object('description', il."description", 'quantity', il."quantity", 'unitAmount', il."unit_amount"::text, 'discountBps', il."discount_bps", 'taxRateBps', il."tax_rate_bps", 'taxCode', il."tax_code", 'taxCodeId', il."tax_code_id", 'unitCost', il."unit_cost"::text, 'dimensions', il."dimensions") order by il."position") from "better_supabase"."invoice_lines" il where il."parent_id" = v_row."id"), '[]'::jsonb),
      'payments', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'amount', (-e."amount")::text, 'paidAt', y."effective_at", 'method', y."metadata" ->> 'method', 'reference', y."metadata" ->> 'reference', 'note', y."metadata" ->> 'note', 'recordedBy', y."actor_id") order by y."effective_at", y."created_at")
        from "better_supabase"."ledger_entries" e join "better_supabase"."ledger_transactions" y on y."id" = e."transaction_id"
        where e."account_id" = (select a."id" from "better_supabase"."ledger_accounts" a where a."tenant_id" = v_row."tenant_id" and a."code" = 'invoice:' || v_row."id"::text)), '[]'::jsonb));
    end if;
    select coalesce(jsonb_agg(jsonb_build_object('description', x."description", 'quantity', x."quantity" * coalesce(x."periods", 1), 'unitAmount', x."unit_amount"::text,
        'discountBps', x."discount_bps", 'taxRateBps', x."tax_rate_bps", 'taxCode', x."tax_code",
        'discountAmount', x."discount_amount", 'taxCodeId', x."tax_code_id", 'unitCost', x."unit_cost", 'costSource', x."cost_source", 'locationId', x."location_id", 'binId', x."bin_id", 'billingParty', x."billing_party", 'billingPartyId', x."billing_party_id", 'billingAccountId', x."billing_account_id",
        'product', case when x."product_type" is null then null else jsonb_build_object('type', x."product_type", 'id', x."product_id") end
      ) order by x."position"), '[]'::jsonb) into v_lines
    from "better_supabase"."quote_lines" x where x."parent_id" = v_quote."id" and (not x."optional" or x."selected");
    if not exists (select 1 from "better_supabase"."invoices" d where d."origin_type" = 'quote' and d."origin_id"::text = v_quote."id"::text and (d."deposit_bps" is not null or d."deposit_amount" is not null) and d."status" not in ('draft', 'void') and not (d."total" > 0 and d."credited_total" >= d."total")) then
      v_header := jsonb_build_object('discountBps', v_quote."discount_bps", 'discountAmount', v_quote."discount_amount"::text);
    else
      select v_lines || coalesce(jsonb_agg(jsonb_build_object('description', 'Discount', 'quantity', 1, 'unitAmount', (-x."discount")::text,
          'taxRateBps', x."tax_rate_bps", 'taxCode', x."tax_code") order by x."tax_rate_bps"), '[]'::jsonb)
        into v_lines
      from "better_supabase"."quote_tax_lines" x where x."parent_id" = v_quote."id" and x."discount" <> 0;
    end if;
    select v_lines || coalesce(jsonb_agg(jsonb_build_object('description', replace(coalesce(nullif(trim(invoice_from_quote.deposit_description), ''), 'Deposit {identifier}'), '{identifier}', d."identifier"), 'quantity', 1, 'unitAmount', (-(case when d."prices_include_tax" = v_quote."prices_include_tax" then y.amount when d."prices_include_tax" then round(y.amount * 10000.0 / (10000 + y.rate))::bigint else round(y.amount * (10000 + y.rate) / 10000.0)::bigint end))::text,
        'taxRateBps', y.rate) order by d."identifier", y.rate), '[]'::jsonb)
      into v_lines
    from "better_supabase"."invoices" d
    cross join lateral (
      select dl."tax_rate_bps" as rate, sum(round(dl."quantity" * dl."unit_amount") - (round(round(dl."quantity" * dl."unit_amount") * dl."discount_bps" / 10000.0) + least(coalesce(dl."discount_amount", 0), greatest(round(dl."quantity" * dl."unit_amount") - round(round(dl."quantity" * dl."unit_amount") * dl."discount_bps" / 10000.0), 0))))::bigint as amount
      from "better_supabase"."invoice_lines" dl where dl."parent_id" = d."id" and true
      group by 1
    ) y
    where d."origin_type" = 'quote' and d."origin_id"::text = v_quote."id"::text and (d."deposit_bps" is not null or d."deposit_amount" is not null) and d."status" not in ('draft', 'void') and not (d."total" > 0 and d."credited_total" >= d."total") and y.amount <> 0;
  elsif invoice_from_quote.deposit_amount is not null then
    v_lines := jsonb_build_array(jsonb_build_object(
      'description', 'Deposit of ' || v_quote."identifier",
      'quantity', 1,
      'unitAmount', (case when v_quote."prices_include_tax" or v_quote."total" = 0 then invoice_from_quote.deposit_amount
        else round(invoice_from_quote.deposit_amount::numeric * v_quote."subtotal" / v_quote."total")::bigint end)::text,
      'taxRateBps', case when v_quote."subtotal" = 0 then 0 else round(v_quote."tax_total" * 10000.0 / v_quote."subtotal")::integer end));
  else
    v_lines := jsonb_build_array(jsonb_build_object(
      'description', 'Deposit ' || (invoice_from_quote.deposit_bps / 100.0)::text || '% of ' || v_quote."identifier",
      'quantity', 1,
      'unitAmount', round(case when v_quote."prices_include_tax" then v_quote."total" else v_quote."subtotal" end::numeric * invoice_from_quote.deposit_bps / 10000)::bigint::text,
      'taxRateBps', case when v_quote."subtotal" = 0 then 0 else round(v_quote."tax_total" * 10000.0 / v_quote."subtotal")::integer end));
  end if;
  v_row := null;
  return "better_supabase"."create_invoice"(v_quote."tenant_id", jsonb_build_object(
    'title', v_quote."title", 'currency', v_quote."currency", 'depositBps', invoice_from_quote.deposit_bps, 'depositAmount', invoice_from_quote.deposit_amount::text, 'pricesIncludeTax', v_quote."prices_include_tax",
    'company', case when v_quote."company_id" is null then null else jsonb_build_object('type', v_quote."company_type", 'id', v_quote."company_id") end,
    'contact', case when v_quote."contact_id" is null then null else jsonb_build_object('type', v_quote."contact_type", 'id', v_quote."contact_id") end,
    'origin', jsonb_build_object('type', 'quote', 'id', v_quote."id"::text)) || v_header, v_lines);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invoice_from_sources (
  tenant      uuid,
  party       jsonb,
  source_refs jsonb,
  options     jsonb DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_refs jsonb := invoice_from_sources.source_refs;
  v_options jsonb := coalesce(invoice_from_sources.options, '{}'::jsonb);
  v_cand jsonb := '[]'::jsonb;
  v_time jsonb;
  v_time_seen integer := 0;
  v_time_ids jsonb;
  v_claimed jsonb;
  v_ref jsonb;
  v_group record;
  v_group_rows jsonb;
  v_lines jsonb;
  v_attrs jsonb;
  v_company jsonb;
  v_invoice jsonb;
  v_invoices jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if better_supabase.import_run() is not null then
    raise exception 'sources are not invoiced in import mode; import the invoices instead' using errcode = '55000', hint = 'INVOICE_SOURCES_IMPORTING';
  end if;
  if not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', invoice_from_sources.tenant, 'invoices.write'), false)) then
    raise exception 'not allowed to change invoices' using errcode = '42501', hint = 'INVOICE_FORBIDDEN';
  end if;
  if jsonb_typeof(invoice_from_sources.party) is distinct from 'object' or nullif(trim(invoice_from_sources.party ->> 'type'), '') is null
    or nullif(trim(invoice_from_sources.party ->> 'id'), '') is null then
    raise exception 'party is { type, id }' using errcode = '22023', hint = 'INVOICE_SOURCE_INVALID';
  end if;
  if jsonb_typeof(v_refs) is distinct from 'array' or jsonb_array_length(v_refs) not between 1 and 200 then
    raise exception 'source_refs is a list of 1 to 200 sources' using errcode = '22023', hint = 'INVOICE_SOURCE_INVALID';
  end if;
  if jsonb_typeof(v_options) is distinct from 'object' then
    raise exception 'options is an object' using errcode = '22023', hint = 'INVOICE_SOURCE_INVALID';
  end if;
  for v_ref in select e.value from jsonb_array_elements(v_refs) e loop
    if jsonb_typeof(v_ref) is distinct from 'object' or (v_ref ->> 'type') is null or (v_ref ->> 'type') not in ('order', 'shipment', 'time') then
      raise exception 'each source is an object with a type of order, shipment or time' using errcode = '22023', hint = 'INVOICE_SOURCE_INVALID';
    end if;
    if (v_ref ->> 'type') = 'time' then
      null;
    elsif (v_ref ->> 'id') is null or (v_ref ->> 'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'an order or shipment source needs an id' using errcode = '22023', hint = 'INVOICE_SOURCE_INVALID';
    elsif (v_ref ->> 'type') = 'shipment' and false then
      raise exception 'this layout has no shipments with a subject to invoice' using errcode = '22023', hint = 'INVOICE_SOURCE_UNSUPPORTED';
    elsif v_ref -> 'lines' is not null and (jsonb_typeof(v_ref -> 'lines') is distinct from 'array' or (v_ref ->> 'type') <> 'order'
      or exists (select 1 from jsonb_array_elements(v_ref -> 'lines') w where jsonb_typeof(w) is distinct from 'object' or (w ->> 'id') is null
        or (w ->> 'quantity') is null or (w ->> 'quantity') !~ '^[0-9]{1,10}$' or (w ->> 'quantity')::numeric <= 0)) then
      raise exception 'lines is a list of { id, quantity } with a whole positive quantity, on an order source' using errcode = '22023', hint = 'INVOICE_SOURCE_INVALID';
    end if;
  end loop;
  perform pg_advisory_xact_lock(hashtextextended('invoice_sources:' || invoice_from_sources.tenant::text, 0));
  for v_ref in select e.value from jsonb_array_elements(v_refs) e where e.value ->> 'type' in ('order', 'shipment') loop
    if (v_ref ->> 'type') = 'order' then
      if not exists (select 1 from "better_supabase"."orders" o where o."id" = (v_ref ->> 'id')::uuid and o."tenant_id" = invoice_from_sources.tenant) then
        raise exception 'no such order in this organization' using errcode = 'P0002', hint = 'INVOICE_SOURCE_NOT_FOUND';
      end if;
      if not exists (select 1 from "better_supabase"."orders" o where o."id" = (v_ref ->> 'id')::uuid and o."status" in ('confirmed', 'paid', 'fulfilled', 'completed') and o."invoiced_at" is null and o."is_selected") then
        raise exception 'an order is invoiced once it is confirmed or paid and wasn''t invoiced at checkout' using errcode = '55000', hint = 'INVOICE_SOURCE_NOT_READY';
      end if;
    else
      if not exists (select 1 from "better_supabase"."shipments" sh where sh."id" = (v_ref ->> 'id')::uuid and sh."tenant_id" = invoice_from_sources.tenant) then
        raise exception 'no such shipment in this organization' using errcode = 'P0002', hint = 'INVOICE_SOURCE_NOT_FOUND';
      end if;
      if not exists (select 1 from "better_supabase"."shipments" sh where sh."id" = (v_ref ->> 'id')::uuid
        and sh."status" = 'delivered' and sh."subject_type" = 'order') then
        raise exception 'a shipment is invoiced once it is delivered and belongs to an order' using errcode = '55000', hint = 'INVOICE_SOURCE_NOT_READY';
      end if;
      null;
    end if;
  end loop;
  select coalesce(jsonb_agg(to_jsonb(c) order by c."sourceType", c.ref, c."sourceId", c.pos), '[]'::jsonb) into v_cand
  from (
  select r.source_type as "sourceType", r.source_id as "sourceId", r.source_line as "sourceLine", r.order_line as "orderLine",
    r.ref, r.pos, r.title || ' (' || r.ref || ')' as description, q.qty, r.avail, r.requested,
    r.unit_amount as "unitAmount",
    (round(r.discount::numeric * (r.done + q.qty) / r.order_quantity) - round(r.discount::numeric * r.done / r.order_quantity))::bigint as "discountAmount",
    case when n.net > 0 then round(r.tax * 10000.0 / n.net)::integer else 0 end as "taxRateBps",
    r.tax_code_id as "taxCodeId", r.variant, r.billing_party as "billingParty", r.billing_party_id as "billingPartyId",
    r.billing_account_id as "billingAccountId", r.unit_cost as "unitCost", r.currency, r.tax_inclusive as "taxInclusive", r.buyer
  from (
    select 'order'::text as source_type, o."id" as source_id, l."id" as source_line, l."id" as order_line,
      o."number"::text as ref, l."position" as pos, l."title" as title,
      greatest(case when l."requires_shipping" then l."quantity_fulfilled" else l."quantity" end - l."quantity_returned", 0)::numeric - d.done as avail,
      want.qty as requested, d.done, l."quantity"::numeric as order_quantity, l."unit_amount" as unit_amount,
      l."discount" as discount, l."total" as total, l."tax" as tax, o."tax_inclusive" as tax_inclusive,
      l."tax_code_id" as tax_code_id, l."variant_id" as variant,
      l."billing_party" as billing_party,
      l."billing_party_id" as billing_party_id,
      l."billing_account_id" as billing_account_id,
      l."unit_cost" as unit_cost,
      o."currency"::text as currency, o."buyer" as buyer
    from jsonb_array_elements(v_refs) r0(ref)
    join "better_supabase"."orders" o on r0.ref ->> 'type' = 'order' and o."id" = (r0.ref ->> 'id')::uuid and o."tenant_id" = invoice_from_sources.tenant and o."status" in ('confirmed', 'paid', 'fulfilled', 'completed') and o."invoiced_at" is null and o."is_selected"
    join "better_supabase"."order_lines" l on l."order_id" = o."id"
    left join lateral (select (w ->> 'quantity')::numeric as qty from jsonb_array_elements(r0.ref -> 'lines') w
      where (w ->> 'id')::uuid = l."id" limit 1) want on true
    cross join lateral (select coalesce((select sum(z."quantity") from "better_supabase"."invoice_line_sources" z join "better_supabase"."invoices" zi on zi."id" = z."invoice_id"
      where z."order_line_id" = l."id" and zi."status" <> 'void'), 0)::numeric as done) d
    where r0.ref -> 'lines' is null or want.qty is not null
    union all
    select 'shipment'::text, sh."id", sl."id", l."id",
      coalesce(sh."reference", sh."id"::text), l."position", l."title",
      least(sl."quantity"::numeric - coalesce((select sum(z."quantity") from "better_supabase"."invoice_line_sources" z join "better_supabase"."invoices" zi on zi."id" = z."invoice_id"
        where z."source" = 'shipment' and z."source_line_id" = sl."id" and zi."status" <> 'void'), 0),
        greatest(l."quantity" - l."quantity_returned", 0)::numeric - d.done),
      null::numeric, d.done, l."quantity"::numeric, l."unit_amount",
      l."discount", l."total", l."tax", o."tax_inclusive",
      l."tax_code_id", l."variant_id",
      l."billing_party",
      l."billing_party_id",
      l."billing_account_id",
      l."unit_cost",
      o."currency"::text, o."buyer"
    from jsonb_array_elements(v_refs) r0(ref)
    join "better_supabase"."shipments" sh on r0.ref ->> 'type' = 'shipment' and sh."id" = (r0.ref ->> 'id')::uuid and sh."tenant_id" = invoice_from_sources.tenant
      and sh."status" = 'delivered' and sh."subject_type" = 'order'
    join "better_supabase"."shipment_lines" sl on sl."shipment_id" = sh."id" and sl."direction" = 'outbound'
    join "better_supabase"."orders" o on o."id"::text = sh."subject_id" and o."tenant_id" = sh."tenant_id" and o."status" in ('confirmed', 'paid', 'fulfilled', 'completed') and o."invoiced_at" is null and o."is_selected"
    join lateral (select x.* from "better_supabase"."order_lines" x where x."order_id" = o."id" and x."variant_id" = sl."variant_id"
      order by x."position", x."id" limit 1) l on true
    left join lateral (select null::numeric as qty) want on true
    cross join lateral (select coalesce((select sum(z."quantity") from "better_supabase"."invoice_line_sources" z join "better_supabase"."invoices" zi on zi."id" = z."invoice_id"
      where z."order_line_id" = l."id" and zi."status" <> 'void'), 0)::numeric as done) d) r
  cross join lateral (select case when r.requested is null then r.avail else least(r.requested, r.avail) end as qty) q
  cross join lateral (select case when r.tax_inclusive then r.total - r.tax else r.total end as net) n
  where q.qty > 0 or r.avail <= 0 or r.requested is not null) c;
  for v_ref in select e.value from jsonb_array_elements(v_refs) e where e.value ->> 'type' = 'time' loop
    v_time := "better_supabase"."time_lines_for_invoice"(invoice_from_sources.tenant, coalesce(v_ref -> 'scope', '{}'::jsonb), coalesce(coalesce(v_ref -> 'scope', '{}'::jsonb) ->> 'groupBy', 'subject'));
    v_cand := v_cand || coalesce((select jsonb_agg(jsonb_build_object(
        'sourceType', 'time', 'sourceId', null, 'description', x.value ->> 'description', 'qty', (x.value ->> 'quantity')::numeric,
        'avail', (x.value ->> 'quantity')::numeric, 'unitAmount', (x.value ->> 'unitAmount')::bigint, 'discountAmount', 0, 'taxRateBps', 0,
        'billingParty', 'customer', 'currency', x.value ->> 'currency', 'taxInclusive', false, 'entryIds', x.value -> 'entryIds')
        order by x.ordinality) from jsonb_array_elements(v_time) with ordinality x(value, ordinality)), '[]'::jsonb);
    v_time_seen := v_time_seen + 1;
  end loop;
  if exists (select 1 from jsonb_array_elements(v_cand) e where e.value ->> 'requested' is not null
    and (e.value ->> 'requested')::numeric > (e.value ->> 'avail')::numeric and (e.value ->> 'avail')::numeric > 0) then
    raise exception 'a line is invoiced for more than is delivered and not yet invoiced' using errcode = '22023', hint = 'INVOICE_SOURCE_QUANTITY';
  end if;
  if exists (select 1 from jsonb_array_elements(v_cand) e where jsonb_typeof(e.value -> 'buyer') = 'object' and e.value -> 'buyer' ->> 'id' is not null
    and (e.value -> 'buyer' ->> 'id') is distinct from (invoice_from_sources.party ->> 'id')
    and (e.value ->> 'qty')::numeric > 0) then
    raise exception 'an order was placed by another buyer than the party' using errcode = '22023', hint = 'INVOICE_SOURCE_PARTY';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('type', r.value ->> 'type', 'id', r.value ->> 'id', 'reason', 'invoiced')), '[]'::jsonb) into v_skipped
  from jsonb_array_elements(v_refs) r
  where r.value ->> 'type' in ('order', 'shipment') and not exists (
    select 1 from jsonb_array_elements(v_cand) e where e.value ->> 'sourceId' = r.value ->> 'id' and (e.value ->> 'qty')::numeric > 0);
  for v_group in
    select distinct e.value ->> 'billingParty' as billing_party, e.value ->> 'billingPartyId' as billing_party_id,
      e.value ->> 'currency' as currency, (e.value ->> 'taxInclusive')::boolean as tax_inclusive
    from jsonb_array_elements(v_cand) e where (e.value ->> 'qty')::numeric > 0
    order by 1, 2 nulls first, 3, 4
  loop
    select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'description', e.value ->> 'description', 'quantity', (e.value ->> 'qty')::numeric,
        'unitAmount', (e.value ->> 'unitAmount'), 'discountAmount', (e.value ->> 'discountAmount'),
        'taxRateBps', (e.value ->> 'taxRateBps')::integer, 'taxCodeId', e.value ->> 'taxCodeId',
        'billingParty', e.value ->> 'billingParty', 'billingPartyId', e.value ->> 'billingPartyId',
        'billingAccountId', e.value ->> 'billingAccountId', 'unitCost', e.value ->> 'unitCost',
        'product', case when e.value ->> 'variant' is null then null else jsonb_build_object('type', 'product_variant', 'id', e.value ->> 'variant') end)) order by e.ordinality), jsonb_agg(e.value order by e.ordinality),
      coalesce(jsonb_agg(e.value -> 'entryIds') filter (where e.value ->> 'sourceType' = 'time'), '[]'::jsonb)
      into v_lines, v_group_rows, v_time_ids
    from jsonb_array_elements(v_cand) with ordinality e(value, ordinality)
    where (e.value ->> 'qty')::numeric > 0 and e.value ->> 'billingParty' = v_group.billing_party
      and e.value ->> 'billingPartyId' is not distinct from v_group.billing_party_id
      and e.value ->> 'currency' = v_group.currency and (e.value ->> 'taxInclusive')::boolean = v_group.tax_inclusive;
    select coalesce(jsonb_agg(z.id), '[]'::jsonb) into v_time_ids from (
      select distinct x.value as id from jsonb_array_elements(v_time_ids) g, jsonb_array_elements(g.value) x(value)) z;
    v_company := case when v_group.billing_party <> 'customer' and v_group.billing_party_id is not null
      then jsonb_build_object('type', invoice_from_sources.party ->> 'type', 'id', v_group.billing_party_id)
      else jsonb_build_object('type', invoice_from_sources.party ->> 'type', 'id', invoice_from_sources.party ->> 'id') end;
    v_attrs := (coalesce(v_options -> 'attrs', '{}'::jsonb) - 'origin' - 'currency' - 'company' - 'pricesIncludeTax')
      || jsonb_build_object('company', v_company, 'currency', v_group.currency,
        'title', coalesce(nullif(trim(v_options ->> 'title'), ''), nullif(trim(v_options -> 'attrs' ->> 'title'), ''), 'Delivered goods and services'))
      || case when v_group.tax_inclusive then jsonb_build_object('pricesIncludeTax', true) else '{}'::jsonb end;
    v_invoice := "better_supabase"."create_invoice"(invoice_from_sources.tenant, v_attrs, v_lines);
    insert into "better_supabase"."invoice_line_sources" ("tenant_id", "invoice_id", "position", "source", "source_id", "source_line_id", "order_line_id", "quantity")
    select invoice_from_sources.tenant, (v_invoice ->> 'id')::uuid, g.ordinality, g.value ->> 'sourceType', (g.value ->> 'sourceId')::uuid, (g.value ->> 'sourceLine')::uuid, (g.value ->> 'orderLine')::uuid, (g.value ->> 'qty')::numeric
    from jsonb_array_elements(v_group_rows) with ordinality g(value, ordinality)
    where g.value ->> 'sourceType' <> 'time';
    if jsonb_array_length(v_time_ids) > 0 then
      v_claimed := "better_supabase"."claim_time_for_invoice"(invoice_from_sources.tenant, (v_invoice ->> 'id')::uuid, v_time_ids);
      insert into "better_supabase"."invoice_line_sources" ("tenant_id", "invoice_id", "position", "source", "source_id", "quantity")
      select invoice_from_sources.tenant, (v_invoice ->> 'id')::uuid, g.ordinality, 'time', (x.value)::uuid,
        greatest(round(((c.value ->> 'seconds')::numeric) / 3600.0, 4), 0.0001)
      from jsonb_array_elements(v_group_rows) with ordinality g(value, ordinality)
      cross join lateral jsonb_array_elements_text(coalesce(g.value -> 'entryIds', '[]'::jsonb)) x(value)
      join jsonb_array_elements(v_claimed) c(value) on c.value ->> 'entryId' = x.value
      where g.value ->> 'sourceType' = 'time';
    end if;
    v_invoices := v_invoices || jsonb_build_array(v_invoice);
  end loop;
  return jsonb_build_object('invoices', v_invoices, 'skipped', v_skipped);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invoice_from_time (
  tenant   uuid,
  attrs    jsonb,
  scope    jsonb DEFAULT NULL::jsonb,
  group_by text  DEFAULT 'subject'::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_scope jsonb := coalesce(invoice_from_time.scope, '{}'::jsonb);
  v_currency text := upper(invoice_from_time.attrs ->> 'currency');
  v_currencies text[];
  v_unrated integer;
  v_lines jsonb;
  v_entries jsonb;
  v_total bigint;
  v_invoice jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', invoice_from_time.tenant, 'billable_time.invoice'), false)) then
    raise exception 'not allowed to invoice time' using errcode = '42501', hint = 'BILLABLE_TIME_FORBIDDEN';
  end if;
  if invoice_from_time.group_by not in ('subject', 'member', 'entry') then
    raise exception 'group_by is subject, member or entry' using errcode = '22023', hint = 'BILLABLE_TIME_GROUPING_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('billable_time:' || invoice_from_time.tenant::text, 0));
  select count(*) filter (where u.rate is null), array_agg(distinct u.currency) filter (where u.rate is not null)
    into v_unrated, v_currencies
  from (
    select x."id" as id, x."user_id" as user_id, x."subject_type" as subject_type, x."subject_id" as subject_id,
      x."started_at" as started_at, x."note" as note, extract(epoch from x."ended_at" - x."started_at") as seconds,
      coalesce(x."rate", card.rate) as rate, coalesce(x."rate_currency", card.currency) as currency
    from "better_supabase"."time_entries" x
    left join lateral (
      select c."rate" as rate, c."currency"::text as currency
      from "better_supabase"."time_rates" c
      where c."tenant_id" = x."tenant_id"
        and (c."user_id" is null or c."user_id" = x."user_id")
        and (c."subject_type" is null or (c."subject_type" = x."subject_type" and c."subject_id" = x."subject_id"))
        and c."effective_from" <= (x."started_at" at time zone 'UTC')::date
      order by (c."subject_type" is not null) desc, (c."user_id" is not null) desc, c."effective_from" desc
      limit 1
    ) card on x."rate" is null
    where x."tenant_id" = invoice_from_time.tenant
      and x."billable" and x."ended_at" is not null
      and not exists (select 1 from "better_supabase"."time_invoice_entries" d where d."entry_id" = x."id")
      and (v_scope -> 'subject' is null or (x."subject_type" = v_scope -> 'subject' ->> 'type' and x."subject_id" = v_scope -> 'subject' ->> 'id'))
      and (v_scope ->> 'userId' is null or x."user_id" = (v_scope ->> 'userId')::uuid)
      and (v_scope ->> 'starts' is null or x."started_at" >= (v_scope ->> 'starts')::timestamptz)
      and (v_scope ->> 'ends' is null or x."started_at" < (v_scope ->> 'ends')::timestamptz)
      and (v_scope -> 'entryIds' is null or x."id"::text in (select jsonb_array_elements_text(v_scope -> 'entryIds')))) u;
  if v_unrated > 0 then
    raise exception 'some billable entries have no rate; set one on the entry or the rate card' using errcode = '22023', hint = 'TIME_RATE_MISSING';
  end if;
  if v_currency is null then
    if coalesce(array_length(v_currencies, 1), 0) > 1 then
      raise exception 'the entries are billed in several currencies; name one' using errcode = '22023', hint = 'BILLABLE_TIME_CURRENCIES';
    end if;
    v_currency := v_currencies[1];
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('description', l.description, 'quantity', l.quantity, 'unitAmount', l.rate::text) order by l.first_at), '[]'::jsonb),
    coalesce(jsonb_agg(l.entry_ids), '[]'::jsonb),
    coalesce(sum(round(l.quantity * l.rate)), 0)::bigint
    into v_lines, v_entries, v_total
  from (
    select min(u.started_at) as first_at, u.currency, u.rate,
      round(sum(u.seconds) / 3600.0, 4) as quantity,
      jsonb_agg(u.id order by u.started_at, u.id) as entry_ids,
      case when invoice_from_time.group_by = 'entry' then min(u.user_id::text) end as user_text,
      case when invoice_from_time.group_by = 'member' then min(u.user_id::text) end as member_text,
      min(u.subject_type) as subject_type, min(u.subject_id) as subject_id,
      case
        when invoice_from_time.group_by = 'entry' then coalesce(min(u.note), 'Time on ' || to_char(min(u.started_at) at time zone 'UTC', 'YYYY-MM-DD'))
        when min(u.subject_type) is null then 'Time'
        else 'Time on ' || min(u.subject_type) || ' ' || min(u.subject_id)
      end as description
    from (
    select x."id" as id, x."user_id" as user_id, x."subject_type" as subject_type, x."subject_id" as subject_id,
      x."started_at" as started_at, x."note" as note, extract(epoch from x."ended_at" - x."started_at") as seconds,
      coalesce(x."rate", card.rate) as rate, coalesce(x."rate_currency", card.currency) as currency
    from "better_supabase"."time_entries" x
    left join lateral (
      select c."rate" as rate, c."currency"::text as currency
      from "better_supabase"."time_rates" c
      where c."tenant_id" = x."tenant_id"
        and (c."user_id" is null or c."user_id" = x."user_id")
        and (c."subject_type" is null or (c."subject_type" = x."subject_type" and c."subject_id" = x."subject_id"))
        and c."effective_from" <= (x."started_at" at time zone 'UTC')::date
      order by (c."subject_type" is not null) desc, (c."user_id" is not null) desc, c."effective_from" desc
      limit 1
    ) card on x."rate" is null
    where x."tenant_id" = invoice_from_time.tenant
      and x."billable" and x."ended_at" is not null
      and not exists (select 1 from "better_supabase"."time_invoice_entries" d where d."entry_id" = x."id")
      and (v_scope -> 'subject' is null or (x."subject_type" = v_scope -> 'subject' ->> 'type' and x."subject_id" = v_scope -> 'subject' ->> 'id'))
      and (v_scope ->> 'userId' is null or x."user_id" = (v_scope ->> 'userId')::uuid)
      and (v_scope ->> 'starts' is null or x."started_at" >= (v_scope ->> 'starts')::timestamptz)
      and (v_scope ->> 'ends' is null or x."started_at" < (v_scope ->> 'ends')::timestamptz)
      and (v_scope -> 'entryIds' is null or x."id"::text in (select jsonb_array_elements_text(v_scope -> 'entryIds')))) u
    where u.rate is not null
    group by u.currency, u.rate, u.subject_type, u.subject_id,
      case when invoice_from_time.group_by in ('member', 'entry') then u.user_id end,
      case when invoice_from_time.group_by = 'entry' then u.id end
    having round(sum(u.seconds) / 3600.0, 4) > 0) l
  where l.currency = v_currency;
  if jsonb_array_length(v_lines) = 0 then
    raise exception 'no unbilled billable time matches' using errcode = 'P0002', hint = 'BILLABLE_TIME_EMPTY';
  end if;
  select coalesce(jsonb_agg(x.value order by x.value), '[]'::jsonb) into v_entries
  from jsonb_array_elements(v_entries) g, jsonb_array_elements(g.value) x;
  v_invoice := "better_supabase"."create_invoice"(invoice_from_time.tenant,
    (coalesce(invoice_from_time.attrs, '{}'::jsonb) - 'origin') || jsonb_build_object('currency', v_currency,
      'title', coalesce(nullif(trim(invoice_from_time.attrs ->> 'title'), ''), 'Time')), v_lines);
  insert into "better_supabase"."time_invoice_entries" ("entry_id", "tenant_id", "invoice_id", "rate", "currency", "seconds")
  select u.id, invoice_from_time.tenant, (v_invoice ->> 'id')::uuid, u.rate, u.currency, round(u.seconds)::bigint
  from (
    select x."id" as id, x."user_id" as user_id, x."subject_type" as subject_type, x."subject_id" as subject_id,
      x."started_at" as started_at, x."note" as note, extract(epoch from x."ended_at" - x."started_at") as seconds,
      coalesce(x."rate", card.rate) as rate, coalesce(x."rate_currency", card.currency) as currency
    from "better_supabase"."time_entries" x
    left join lateral (
      select c."rate" as rate, c."currency"::text as currency
      from "better_supabase"."time_rates" c
      where c."tenant_id" = x."tenant_id"
        and (c."user_id" is null or c."user_id" = x."user_id")
        and (c."subject_type" is null or (c."subject_type" = x."subject_type" and c."subject_id" = x."subject_id"))
        and c."effective_from" <= (x."started_at" at time zone 'UTC')::date
      order by (c."subject_type" is not null) desc, (c."user_id" is not null) desc, c."effective_from" desc
      limit 1
    ) card on x."rate" is null
    where x."tenant_id" = invoice_from_time.tenant
      and x."billable" and x."ended_at" is not null
      and not exists (select 1 from "better_supabase"."time_invoice_entries" d where d."entry_id" = x."id")
      and (v_scope -> 'subject' is null or (x."subject_type" = v_scope -> 'subject' ->> 'type' and x."subject_id" = v_scope -> 'subject' ->> 'id'))
      and (v_scope ->> 'userId' is null or x."user_id" = (v_scope ->> 'userId')::uuid)
      and (v_scope ->> 'starts' is null or x."started_at" >= (v_scope ->> 'starts')::timestamptz)
      and (v_scope ->> 'ends' is null or x."started_at" < (v_scope ->> 'ends')::timestamptz)
      and (v_scope -> 'entryIds' is null or x."id"::text in (select jsonb_array_elements_text(v_scope -> 'entryIds')))) u
  where u.id::text in (select jsonb_array_elements_text(v_entries));
  perform "better_supabase".emit_event('time_entry.invoiced', jsonb_build_object('organizationId', invoice_from_time.tenant, 'invoiceId', v_invoice ->> 'id', 'entryIds', v_entries, 'currency', v_currency, 'total', v_total::text), 'invoices/' || (v_invoice ->> 'id'), (invoice_from_time.tenant::text)::text, null, 'better-supabase/billable-time');
  perform better_supabase.audit_event(
    event_type => 'time_entry.invoiced',
    category => 'billing',
    target_type => 'invoice',
    record_id => v_invoice ->> 'id',
    summary => 'invoiced time',
    tenant => (invoice_from_time.tenant::text)::uuid,
    metadata => jsonb_build_object('organizationId', invoice_from_time.tenant, 'invoiceId', v_invoice ->> 'id', 'entryIds', v_entries, 'currency', v_currency, 'total', v_total::text)
  );
  return jsonb_build_object('invoiceId', v_invoice ->> 'id', 'currency', v_currency, 'total', v_total::text, 'entryIds', v_entries);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invoice_funding_claim (
  claim_id uuid,
  attrs    jsonb DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_claim "better_supabase"."funding_claims"%rowtype;
  v_party jsonb;
  v_lines jsonb;
  v_invoice jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_claim from "better_supabase"."funding_claims" x where x."id" = invoice_funding_claim.claim_id for update;
  if not found then
    raise exception 'funding claim not found' using errcode = 'P0002', hint = 'FUNDING_CLAIM_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_claim."tenant_id", 'funding.claim'), false)) then
    raise exception 'not allowed to claim funding' using errcode = '42501', hint = 'FUNDING_FORBIDDEN';
  end if;
  if v_claim."status" not in ('accepted', 'partially_accepted') then
    raise exception 'only a claim the funder accepted is invoiced' using errcode = '22023', hint = 'FUNDING_CLAIM_STATUS_INVALID';
  end if;
  if v_claim."invoice_id" is not null then
    raise exception 'the funding claim is invoiced already' using errcode = '22023', hint = 'FUNDING_INVALID';
  end if;
  v_party := case
    when exists (select 1 from "better_supabase"."companies" x where x."id" = v_claim."funder_id")
      then jsonb_build_object('company', jsonb_build_object('id', v_claim."funder_id"))
    else jsonb_build_object('contact', jsonb_build_object('id', v_claim."funder_id"))
  end;
  select coalesce(jsonb_agg(jsonb_build_object(
    'description', y."code" || ' ' || y."title",
    'quantity', z."units",
    'unitAmount', y."rate"::text
  ) order by y."code", z."id"), '[]'::jsonb) into v_lines
  from "better_supabase"."funding_claim_lines" z
  join "better_supabase"."funding_products" y on y."tenant_id" = z."tenant_id" and y."id" = z."product_id"
  where z."tenant_id" = v_claim."tenant_id" and z."claim_id" = v_claim."id" and z."status" = 'accepted';
  v_invoice := "better_supabase"."create_invoice"(v_claim."tenant_id",
    v_party || (coalesce(invoice_funding_claim.attrs, '{}'::jsonb) - 'origin' - 'company' - 'contact') || jsonb_build_object('currency', v_claim."currency",
      'title', coalesce(nullif(trim(invoice_funding_claim.attrs ->> 'title'), ''), 'Funding claim ' || v_claim."number")),
    v_lines);
  update "better_supabase"."funding_claims" x set "invoice_id" = (v_invoice ->> 'id')::uuid, "updated_at" = now()
  where x."id" = v_claim."id"
  returning x.* into v_claim;
  return jsonb_build_object('claim', jsonb_build_object('id', v_claim."id", 'organizationId', v_claim."tenant_id", 'funderId', v_claim."funder_id", 'number', v_claim."number", 'periodStart', v_claim."period_start", 'periodEnd', v_claim."period_end", 'format', v_claim."format", 'status', v_claim."status", 'externalRef', v_claim."external_ref", 'sentAt', v_claim."sent_at", 'payloadSha256', v_claim."payload_sha256", 'response', v_claim."response", 'total', v_claim."total"::text, 'currency', v_claim."currency", 'invoiceId', v_claim."invoice_id", 'createdBy', v_claim."created_by", 'createdAt', v_claim."created_at", 'updatedAt', v_claim."updated_at"), 'invoice', v_invoice);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invoice_match_result (
  invoice uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."invoices";
  v_result jsonb;
begin
  select * into v_row from "better_supabase"."invoices" x where x."id" = invoice_match_result.invoice;
  if v_row."purchase_order_id" is null then
    return jsonb_build_object('invoiceId', v_row."id", 'currency', v_row."currency", 'purchaseOrderId', null, 'status', 'not_applicable', 'lines', '[]'::jsonb);
  end if;
  with billed as (
    select il."parent_id" as bill, (il."product_id")::text as variant, sum(il."quantity") as quantity,
      sum(case when b."prices_include_tax" then round((round(il."quantity" * il."unit_amount") - (round(round(il."quantity" * il."unit_amount") * il."discount_bps" / 10000.0) + least(coalesce(il."discount_amount", 0), greatest(round(il."quantity" * il."unit_amount") - round(round(il."quantity" * il."unit_amount") * il."discount_bps" / 10000.0), 0)))) * 10000.0 / (10000 + il."tax_rate_bps")) else round(il."quantity" * il."unit_amount") - (round(round(il."quantity" * il."unit_amount") * il."discount_bps" / 10000.0) + least(coalesce(il."discount_amount", 0), greatest(round(il."quantity" * il."unit_amount") - round(round(il."quantity" * il."unit_amount") * il."discount_bps" / 10000.0), 0))) end) as net
    from "better_supabase"."invoice_lines" il join "better_supabase"."invoices" b on b."id" = il."parent_id"
    where b."purchase_order_id" = v_row."purchase_order_id" and b."direction" = 'purchase'
      and b."kind" = 'invoice' and (b."id" = v_row."id" or b."status" in ('issued', 'partially_paid', 'paid'))
      and il."product_id" is not null
    group by 1, 2
  ),
  ordered as (
    select y."variant_id"::text as variant, sum(y."quantity_ordered") as ordered, sum(y."quantity_received") as received,
      sum(y."quantity_ordered" * y."unit_cost") / nullif(sum(y."quantity_ordered"), 0) as unit_cost
    from "better_supabase"."purchase_order_lines" y where y."purchase_order_id" = v_row."purchase_order_id"
    group by 1
  ),
  checked as (
    select x.variant, x.quantity, x.net, coalesce(o.ordered, 0) as ordered, coalesce(o.received, 0) as received,
      round(x.quantity * coalesce(o.unit_cost, 0)) as expected,
      (select coalesce(sum(e.quantity), 0) from billed e where e.variant = x.variant) as billed_total
    from billed x left join ordered o on o.variant = x.variant
    where x.bill = v_row."id"
  ),
  rated as (
    select c.*, case
      when c.received <= 0 then 'not_received'
      when c.billed_total > c.received then 'quantity_variance'
      when abs(c.net - c.expected) > greatest(round(c.expected * 100 / 10000.0), 500) then 'price_variance'
      else 'matched' end as status
    from checked c
  )
  select jsonb_build_object('invoiceId', v_row."id", 'currency', v_row."currency", 'purchaseOrderId', v_row."purchase_order_id",
    'status', coalesce((select r.status from rated r order by array_position(array['not_received', 'quantity_variance', 'price_variance', 'matched'], r.status) limit 1), 'matched'),
    'lines', coalesce((select jsonb_agg(jsonb_build_object('variantId', r.variant, 'quantity', r.quantity::text, 'billedQuantity', r.billed_total::text,
      'orderedQuantity', r.ordered::text, 'receivedQuantity', r.received::text, 'amount', r.net::bigint::text, 'expectedAmount', r.expected::bigint::text, 'status', r.status) order by r.variant) from rated r), '[]'::jsonb))
  into v_result;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.invoice_updated_at (
  subject_id text
)
  RETURNS timestamp WITH time zone
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select x."updated_at" from "better_supabase"."invoices" x where x."id" = $1::uuid
$function$;

CREATE OR REPLACE FUNCTION better_supabase.is_approved (
  subject_type text,
  subject_id   text,
  action       text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce((
    select x."status"::text in ('approved', 'consumed') from "better_supabase"."approval_requests" x
    where x."subject_type" = is_approved.subject_type and x."subject_id" = is_approved.subject_id and x."action" = is_approved.action
    order by x."created_at" desc limit 1
  ), false)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.is_conversation_member (
  conversation uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from "better_supabase"."conversation_members" m
    where m."conversation_id" = is_conversation_member.conversation and m."user_id" = auth.uid()
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.is_held (
  kind   text,
  tenant text DEFAULT NULL::text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from "better_supabase"."legal_holds" x
    where x."released_at" is null
      and (x."kind" is null or x."kind" = is_held.kind)
      and (x."tenant_id" is null or x."tenant_id"::text = is_held.tenant)
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.is_held_memo (
  kind   text,
  tenant text DEFAULT NULL::text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_key text := 'ih' || md5(statement_timestamp()::text || is_held_memo.kind || coalesce(is_held_memo.tenant, ''));
  v_memo text := better_supabase.memo_slot_get(v_key);
  v_held boolean;
begin
  if v_memo is not null then
    return v_memo = 't';
  end if;
  v_held := "better_supabase"."is_held"(is_held_memo.kind, is_held_memo.tenant);
  perform better_supabase.memo_slot_set(v_key, case when v_held then 't' else 'f' end);
  return v_held;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.is_platform (
  permission text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(better_supabase.platform_can(auth.uid(), is_platform.permission), false)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.is_subject_member (
  subject_type text,
  subject_id   text
)
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if auth.uid() is null then
    return false;
  end if;
  return exists (
    select 1 from "better_supabase"."subject_members" m
    where m."subject_type" = is_subject_member.subject_type
      and m."subject_id" = is_subject_member.subject_id
      and (m."user_id" = auth.uid() or (m."team_id" is not null and m."team_id" in (select "better_supabase"."team_ids_of"(auth.uid()))))
        and (m."starts_on" is null or m."starts_on" <= current_date)
        and (m."ends_on" is null or m."ends_on" >= current_date)
        and (m."ends_at" is null or m."ends_at" > now())
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.is_trashed (
  subject_type text,
  subject_id   text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from "better_supabase"."trash_items"
    where "subject_type" = is_trashed.subject_type and "subject_id" = is_trashed.subject_id
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.issue_consent_receipt (
  consent_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."consents";
  v_purpose "better_supabase"."consent_purposes";
  v_receipt "better_supabase"."consent_receipts";
  v_id uuid := gen_random_uuid();
  v_issued timestamptz := now();
  v_doc jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."consents" x where x."id" = issue_consent_receipt.consent_id;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')
      or (coalesce(better_supabase.can('tenant', v_row."tenant_id", 'consents.read'), false) and coalesce("better_supabase"."can_subject"(v_row."subject_type", v_row."subject_id", 'read'), false))
      or ((v_row."tenant_id")::text, (v_row."subject_type")::text, (v_row."subject_id")::text) in (select g.tenant, g.subject_type, g.subject_id from better_supabase.portal_subjects('read') g)
      or ((v_row."tenant_id")::text, (v_row."subject_type")::text, (v_row."subject_id")::text) in (select g.tenant, g.party_type, g.party_id from better_supabase.portal_parties() g)
      or exists (select 1 from "better_supabase"."relations" r
      where r."kind" = 'represents' and r."source_type" = 'person'
        and r."tenant_id"::text = (v_row."tenant_id")::text
        and r."target_type" = v_row."subject_type" and r."target_id" = (v_row."subject_id")::text
        and r."data" ->> 'authority' in ('inform', 'act')
        and (case when r."data" ->> 'valid_from' is null then true
      when pg_input_is_valid(r."data" ->> 'valid_from', 'date') then (r."data" ->> 'valid_from')::date <= current_date
      else false end) and (case when r."data" ->> 'valid_until' is null then true
      when pg_input_is_valid(r."data" ->> 'valid_until', 'date') then (r."data" ->> 'valid_until')::date >= current_date
      else false end)
        and ((v_row."tenant_id")::text, ('person')::text, (r."source_id")::text) in (select g.tenant, g.party_type, g.party_id from better_supabase.portal_parties() g))) then
    raise exception 'no such consent' using errcode = 'P0002', hint = 'CONSENT_NOT_FOUND';
  end if;
  select * into v_receipt from "better_supabase"."consent_receipts" x where x."consent_id" = v_row."id" and x."status" = v_row."status";
  if found then
    return (v_receipt."receipt" || jsonb_build_object('digest', v_receipt."digest"));
  end if;
  select * into v_purpose from "better_supabase"."consent_purposes" x where x."id" = v_row."purpose_id";
  v_doc := jsonb_build_object(
    'format', 'better-supabase/consent-receipt@1',
    'receiptId', v_id,
    'issuedAt', v_issued,
    'organizationId', v_row."tenant_id",
    'subject', jsonb_build_object('type', v_row."subject_type", 'id', v_row."subject_id"),
    'purpose', jsonb_build_object('key', v_purpose."key", 'title', v_purpose."title", 'version', v_purpose."version", 'legalBasis', v_purpose."legal_basis"),
    'consent', jsonb_build_object('id', v_row."id", 'status', v_row."status", 'givenBy', v_row."given_by", 'grantedAt', v_row."granted_at", 'validUntil', v_row."expires_at", 'withdrawnAt', v_row."withdrawn_at", 'scope', coalesce(v_row."scope", '{}'::jsonb)),
    'evidence', jsonb_build_object(
      'signatureId', v_row."signature_id",
      'submissionId', v_row."submission_id",
      'attachmentId', v_row."attachment_id",
      'signals', (select coalesce(jsonb_agg(jsonb_build_object('id', y."id", 'kind', y."kind", 'receivedAt', y."received_at") order by y."received_at", y."id"), '[]'::jsonb) from "better_supabase"."consent_signals" y where v_row."id" = any(y."consent_ids"))
    )
  );
  insert into "better_supabase"."consent_receipts" ("id", "tenant_id", "subject_type", "subject_id", "consent_id", "status", "receipt", "digest", "issued_at")
  values (v_id, v_row."tenant_id", v_row."subject_type", v_row."subject_id", v_row."id", v_row."status", v_doc, encode(sha256(convert_to(v_doc::text, 'UTF8')), 'hex'), v_issued)
  returning * into v_receipt;
  perform "better_supabase".emit_event('consent_receipt.issued', jsonb_build_object('organizationId', v_receipt."tenant_id", 'receiptId', v_receipt."id", 'consentId', v_receipt."consent_id", 'status', v_receipt."status", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id"), 'consent-receipts/' || v_receipt."id"::text, (v_receipt."tenant_id")::text, null, 'better-supabase/consents');
  return (v_receipt."receipt" || jsonb_build_object('digest', v_receipt."digest"));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.issue_gift_receipt (
  gift_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."donations"%rowtype;
  v_receipt "better_supabase"."donation_receipts"%rowtype;
  v_seq bigint;
  v_number text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."donations" x where x."id" = issue_gift_receipt.gift_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'donations.manage'), false)) then
    raise exception 'no such gift you can read' using errcode = 'P0002', hint = 'DONATION_NOT_FOUND';
  end if;
  if v_row."status" <> 'posted' then
    raise exception 'only a posted gift gets a receipt' using errcode = '55000', hint = 'DONATION_STATUS_INVALID';
  end if;
  if v_row."receipt_id" is not null then
    select * into v_receipt from "better_supabase"."donation_receipts" x where x."id" = v_row."receipt_id";
    return jsonb_build_object('id', v_receipt."id", 'organizationId', v_receipt."tenant_id", 'donorType', v_receipt."donor_type", 'donorId', v_receipt."donor_id", 'sequence', v_receipt."sequence"::text, 'number', v_receipt."number", 'kind', v_receipt."kind", 'year', v_receipt."year", 'amount', v_receipt."amount"::text, 'currency', v_receipt."currency", 'issuedAt', v_receipt."issued_at", 'voidedAt', v_receipt."voided_at", 'voidReason', v_receipt."void_reason");
  end if;
  if (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'donation_receipt' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end) is not null then
    v_number := (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'donation_receipt' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end);
    v_seq := "better_supabase"."register_fixed_number"(v_row."tenant_id", 'donation_receipt', v_number, now(), '');
    perform set_config('better_supabase.fixed_number', '', true);
  else
    v_seq := "better_supabase"."next_number"(v_row."tenant_id", 'donation_receipt', now(), '');
  v_number := better_supabase.format_assigned_number('R-{n}', v_seq, now());
  end if;
  insert into "better_supabase"."donation_receipts" ("tenant_id", "donor_type", "donor_id", "sequence", "number", "kind", "year", "amount", "currency")
  values (v_row."tenant_id", v_row."donor_type", v_row."donor_id", v_seq, v_number, 'gift', extract(year from v_row."received_on")::integer,
    v_row."amount", v_row."currency")
  returning * into v_receipt;
  update "better_supabase"."donations" x set "receipt_id" = v_receipt."id", "updated_at" = now() where x."id" = v_row."id";
  perform "better_supabase".emit_event('donation_receipt.issued', jsonb_build_object('organizationId', v_receipt."tenant_id", 'id', v_receipt."id", 'number', v_receipt."number", 'kind', v_receipt."kind", 'donorType', v_receipt."donor_type", 'donorId', v_receipt."donor_id", 'amount', v_receipt."amount"::text, 'currency', v_receipt."currency"), 'donation-receipts/' || v_receipt."id"::text, (v_receipt."tenant_id")::text, null, 'better-supabase/donations');
  perform better_supabase.audit_event(
    event_type => 'donation_receipt.issued',
    category => 'billing',
    target_type => 'donation_receipt',
    record_id => v_receipt."id"::text,
    target_label => v_receipt."number",
    summary => 'issued a gift receipt',
    tenant => (v_receipt."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_receipt."tenant_id", 'id', v_receipt."id", 'number', v_receipt."number", 'kind', v_receipt."kind", 'donorType', v_receipt."donor_type", 'donorId', v_receipt."donor_id", 'amount', v_receipt."amount"::text, 'currency', v_receipt."currency")
  );
  return jsonb_build_object('id', v_receipt."id", 'organizationId', v_receipt."tenant_id", 'donorType', v_receipt."donor_type", 'donorId', v_receipt."donor_id", 'sequence', v_receipt."sequence"::text, 'number', v_receipt."number", 'kind', v_receipt."kind", 'year', v_receipt."year", 'amount', v_receipt."amount"::text, 'currency', v_receipt."currency", 'issuedAt', v_receipt."issued_at", 'voidedAt', v_receipt."voided_at", 'voidReason', v_receipt."void_reason");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.issue_invoice (
  invoice      uuid,
  issued_on    date,
  due_on       date  DEFAULT NULL::date,
  actor        jsonb DEFAULT NULL::jsonb,
  fixed_number text  DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."invoices";
  v_original "better_supabase"."invoices";
  v_seq bigint;
  v_identifier text;
  v_issued_on date := coalesce(issue_invoice.issued_on, current_date);
  v_warnings jsonb;
  v_early_bps integer;
  v_early_days integer;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."invoices" x where x."id" = issue_invoice.invoice and ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', x."tenant_id", case when x."direction" = 'purchase' then 'invoices.purchase' else 'invoices.write' end), false)) for update;
  if v_row."id" is null then
    raise exception 'no such invoice you can edit' using errcode = 'P0002', hint = 'INVOICE_NOT_FOUND';
  end if;
  
  if v_row."status" <> 'draft' then
    raise exception 'the invoice was already issued' using errcode = '55000', hint = 'INVOICE_NOT_DRAFT';
  end if;
  if not exists (select 1 from "better_supabase"."invoice_lines" x where x."parent_id" = v_row."id") then
    raise exception 'an invoice needs a line before it is issued' using errcode = '23514', hint = 'INVOICE_EMPTY';
  end if;
  if issue_invoice.due_on < v_issued_on then
    raise exception 'an invoice falls due on or after its issue date' using errcode = '22023', hint = 'INVOICE_DUE_INVALID';
  end if;
  if issue_invoice.actor is not null then
    if jsonb_typeof(issue_invoice.actor) <> 'object' then
      raise exception 'actor must be an object of id, name, email, ip and userAgent' using errcode = '22023', hint = 'INVOICE_ACTOR_INVALID';
    end if;
    begin
      perform nullif(issue_invoice.actor ->> 'ip', '')::inet, nullif(issue_invoice.actor ->> 'id', '')::uuid;
    exception when invalid_text_representation then
      raise exception 'actor.ip must be an IP address and actor.id a user id' using errcode = '22023', hint = 'INVOICE_ACTOR_INVALID';
    end;
  end if;
  perform set_config('better_supabase.transition_actor', coalesce(issue_invoice.actor::text, ''), true);
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_invoice_issue"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  perform "better_supabase"."issue_invoice_tax"(v_row."id", v_issued_on);
  select z."discount_bps", z."discount_days" into v_early_bps, v_early_days
  from "better_supabase"."payment_terms" z where z."id" = v_row."payment_terms_id";
  if v_row."kind" = 'credit_note' then
    select * into v_original from "better_supabase"."invoices" x where x."id" = v_row."original_id" for update;
    if v_row."total" > v_original."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_original."id"), 0) - v_original."credited_total" then
      raise exception 'a credit note can''t exceed the invoice''s total less its earlier credits' using errcode = '23514', hint = 'INVOICE_CREDIT_TOO_LARGE';
    end if;
    if v_row."direction" = 'purchase' then
      if coalesce(issue_invoice.fixed_number, (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'purchase_credit_note' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end)) is not null then
    v_identifier := coalesce(issue_invoice.fixed_number, (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'purchase_credit_note' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end));
    if better_supabase.import_run() is null then
      raise exception 'a fixed number is only accepted during an import' using errcode = '42501', hint = 'NUMBER_FIXED_FORBIDDEN';
    end if;
    v_seq := coalesce(substring(v_identifier from '([0-9]+)$')::bigint, 0);
    perform set_config('better_supabase.fixed_number', '', true);
  else
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_row."tenant_id"::text || ':purchase_credit_note' || ':' || "better_supabase"."number_scope"(v_row."tenant_id", v_row.legal_entity_id), 0));
  select coalesce(max(x."number"), 0) + 1 into v_seq from (select * from "better_supabase"."invoices" k where k."direction" = 'purchase' and k."kind" = 'credit_note') x where x."tenant_id" = v_row."tenant_id" and "better_supabase"."number_scope"(x."tenant_id", x.legal_entity_id) = "better_supabase"."number_scope"(v_row."tenant_id", v_row.legal_entity_id);
  v_identifier := 'BCN-' || v_seq::text;
  end if;
    else
      if coalesce(issue_invoice.fixed_number, (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'credit_note' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end)) is not null then
    v_identifier := coalesce(issue_invoice.fixed_number, (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'credit_note' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end));
    if better_supabase.import_run() is null then
      raise exception 'a fixed number is only accepted during an import' using errcode = '42501', hint = 'NUMBER_FIXED_FORBIDDEN';
    end if;
    v_seq := coalesce(substring(v_identifier from '([0-9]+)$')::bigint, 0);
    perform set_config('better_supabase.fixed_number', '', true);
  else
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_row."tenant_id"::text || ':credit_note' || ':' || "better_supabase"."number_scope"(v_row."tenant_id", v_row.legal_entity_id), 0));
  select coalesce(max(x."number"), 0) + 1 into v_seq from (select * from "better_supabase"."invoices" k where k."direction" = 'sales' and k."kind" = 'credit_note') x where x."tenant_id" = v_row."tenant_id" and "better_supabase"."number_scope"(x."tenant_id", x.legal_entity_id) = "better_supabase"."number_scope"(v_row."tenant_id", v_row.legal_entity_id);
  v_identifier := 'CN-' || v_seq::text;
  end if;
    end if;
  else
    if v_row."direction" = 'purchase' then
      if coalesce(issue_invoice.fixed_number, (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'purchase_bill' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end)) is not null then
    v_identifier := coalesce(issue_invoice.fixed_number, (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'purchase_bill' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end));
    if better_supabase.import_run() is null then
      raise exception 'a fixed number is only accepted during an import' using errcode = '42501', hint = 'NUMBER_FIXED_FORBIDDEN';
    end if;
    v_seq := coalesce(substring(v_identifier from '([0-9]+)$')::bigint, 0);
    perform set_config('better_supabase.fixed_number', '', true);
  else
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_row."tenant_id"::text || ':purchase_bill' || ':' || "better_supabase"."number_scope"(v_row."tenant_id", v_row.legal_entity_id), 0));
  select coalesce(max(x."number"), 0) + 1 into v_seq from (select * from "better_supabase"."invoices" k where k."direction" = 'purchase' and k."kind" = 'invoice') x where x."tenant_id" = v_row."tenant_id" and "better_supabase"."number_scope"(x."tenant_id", x.legal_entity_id) = "better_supabase"."number_scope"(v_row."tenant_id", v_row.legal_entity_id);
  v_identifier := 'BILL-' || v_seq::text;
  end if;
    else
      if coalesce(issue_invoice.fixed_number, (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'invoice' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end)) is not null then
    v_identifier := coalesce(issue_invoice.fixed_number, (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'invoice' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end));
    if better_supabase.import_run() is null then
      raise exception 'a fixed number is only accepted during an import' using errcode = '42501', hint = 'NUMBER_FIXED_FORBIDDEN';
    end if;
    v_seq := coalesce(substring(v_identifier from '([0-9]+)$')::bigint, 0);
    perform set_config('better_supabase.fixed_number', '', true);
  else
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_row."tenant_id"::text || ':invoice' || ':' || "better_supabase"."number_scope"(v_row."tenant_id", v_row.legal_entity_id), 0));
  select coalesce(max(x."number"), 0) + 1 into v_seq from (select * from "better_supabase"."invoices" k where k."direction" = 'sales' and k."kind" = 'invoice') x where x."tenant_id" = v_row."tenant_id" and "better_supabase"."number_scope"(x."tenant_id", x.legal_entity_id) = "better_supabase"."number_scope"(v_row."tenant_id", v_row.legal_entity_id);
  v_identifier := 'INV-' || v_seq::text;
  end if;
    end if;
  end if;
  if v_row."kind" = 'invoice' and not v_row."direction" = 'purchase' and coalesce(v_row."company_id"::text, v_row."contact_id"::text) is not null then
    declare
      v_limit bigint;
      v_block text;
    begin
      select s.credit_limit, s.credit_block into v_limit, v_block from (select p."credit_limit", p."credit_currency", p."credit_block" from "better_supabase"."companies" p where p."id"::text = coalesce(v_row."company_id"::text, v_row."contact_id"::text) and p."tenant_id" = v_row."tenant_id" and p."merged_into" is null union all select p."credit_limit", p."credit_currency", p."credit_block" from "better_supabase"."people" p where p."id"::text = coalesce(v_row."company_id"::text, v_row."contact_id"::text) and p."tenant_id" = v_row."tenant_id" and p."merged_into" is null) s(credit_limit, credit_currency, credit_block)
      where s.credit_limit is not null and coalesce(s.credit_currency, v_row."currency") = v_row."currency"
      order by s.credit_limit limit 1;
      if v_limit is not null and v_block is distinct from 'none' and (select coalesce(sum((o."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = o."id"), 0) - o."credited_total" - o."paid_total")), 0) from "better_supabase"."invoices" o
        where o."tenant_id" = v_row."tenant_id" and o."id" <> v_row."id" and o."currency" = v_row."currency"
          and coalesce(o."company_id"::text, o."contact_id"::text) = coalesce(v_row."company_id"::text, v_row."contact_id"::text) and not o."direction" = 'purchase'
          and o."kind" = 'invoice' and o."status" in ('issued', 'partially_paid')) + v_row."total" > v_limit and not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'orders.override_credit'), false)) then
        if v_block = 'soft' then
          v_warnings := coalesce(v_warnings, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
            'code', 'INVOICE_CREDIT_LIMIT_EXCEEDED', 'message', 'this invoice takes the customer over their credit limit', 'limit', v_limit::text));
        else
          raise exception 'this invoice takes the customer over their credit limit' using errcode = '55000', hint = 'INVOICE_CREDIT_LIMIT_EXCEEDED';
        end if;
      end if;
    end;
  end if;
  update "better_supabase"."invoices" x set "status" = 'issued', "number" = v_seq, "identifier" = v_identifier,
    "issued_on" = v_issued_on,
    "due_on" = coalesce(issue_invoice.due_on, v_issued_on + x."terms_days"),
    "discount_due_on" = case when coalesce(v_early_bps, 0) > 0 and x."kind" = 'invoice' then v_issued_on + v_early_days end,
    "discount_amount_early" = case when coalesce(v_early_bps, 0) > 0 and x."kind" = 'invoice'
      then ((x."total"::numeric * v_early_bps + 5000) / 10000)::bigint end,
    "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('invoice.issued', jsonb_build_object('organizationId', v_row."tenant_id", 'invoiceId', v_row."id", 'subjectType', 'invoice', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier", 'total', v_row."total"::text, 'currency', v_row."currency", 'dueOn', v_row."due_on"), 'invoices/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/invoices');
  if v_row."kind" = 'credit_note' then
    update "better_supabase"."invoices" x set "credited_total" = x."credited_total" + v_row."total", "updated_at" = now()
    where x."id" = v_original."id"
    returning * into v_original;
  update "better_supabase"."invoices" x set
    "paid_total" = coalesce(-(select sum(e."amount") from "better_supabase"."ledger_entries" e where e."account_id" = (select a."id" from "better_supabase"."ledger_accounts" a where a."tenant_id" = x."tenant_id" and a."code" = 'invoice:' || x."id"::text)), 0),
    "updated_at" = now()
  where x."id" = v_original."id"
  returning * into v_original;
  update "better_supabase"."invoices" x set
    "status" = case
      when (x."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = x."id"), 0) - x."credited_total" - x."paid_total") <= 0 then 'paid'
      when x."paid_total" > 0 or x."credited_total" > 0 then 'partially_paid'
      else 'issued' end,
    "paid_at" = case when (x."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = x."id"), 0) - x."credited_total" - x."paid_total") <= 0 then coalesce(x."paid_at", now()) end
  where x."id" = v_original."id" and x."status" in ('issued', 'partially_paid', 'paid')
  returning * into v_original;
    perform "better_supabase".emit_event('invoice.credited', jsonb_build_object('organizationId', v_original."tenant_id", 'invoiceId', v_original."id", 'subjectType', 'invoice', 'subjectId', v_original."id"::text, 'identifier', v_original."identifier", 'creditNoteId', v_row."id", 'amount', v_row."total"::text), 'invoices/' || v_original."id"::text, (v_original."tenant_id"::text)::text, null, 'better-supabase/invoices');
    if v_original."status" = 'paid' then
      perform "better_supabase".emit_event('invoice.paid', jsonb_build_object('organizationId', v_original."tenant_id", 'invoiceId', v_original."id", 'subjectType', 'invoice', 'subjectId', v_original."id"::text, 'identifier', v_original."identifier", 'total', v_original."total"::text), 'invoices/' || v_original."id"::text, (v_original."tenant_id"::text)::text, null, 'better-supabase/invoices');
    end if;
  end if;
  if not better_supabase.import_run() is not null then
    perform "better_supabase"."accounting_post_source"('invoice', v_row."id"::text);
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_invoice_issue"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return to_jsonb(v_row) || jsonb_build_object('number', v_row."number"::text, 'paid_total', v_row."paid_total"::text, 'credited_total', v_row."credited_total"::text, 'list_total', v_row."list_total"::text, 'discount_total', v_row."discount_total"::text, 'subtotal', v_row."subtotal"::text, 'tax_total', v_row."tax_total"::text, 'total', v_row."total"::text, 'deposit_amount', v_row."deposit_amount"::text, 'discount_amount', v_row."discount_amount"::text, 'discount_amount_early', v_row."discount_amount_early"::text) || jsonb_build_object(
      'balance', (v_row."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), 0) - v_row."credited_total" - v_row."paid_total")::text,
      'charged_total', coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), 0)::text,
      'charges', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'amount', y."amount"::text, 'description', y."description", 'createdAt', y."created_at") order by y."created_at") from "better_supabase"."invoice_charges" y where y."invoice_id" = v_row."id"), '[]'::jsonb),
      'overdue', v_row."status" in ('issued', 'partially_paid') and v_row."due_on" < current_date,
      'lines', coalesce((select jsonb_agg(jsonb_build_object('description', il."description", 'quantity', il."quantity", 'unitAmount', il."unit_amount"::text, 'discountBps', il."discount_bps", 'taxRateBps', il."tax_rate_bps", 'taxCode', il."tax_code", 'taxCodeId', il."tax_code_id", 'unitCost', il."unit_cost"::text, 'dimensions', il."dimensions") order by il."position") from "better_supabase"."invoice_lines" il where il."parent_id" = v_row."id"), '[]'::jsonb),
      'payments', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'amount', (-e."amount")::text, 'paidAt', y."effective_at", 'method', y."metadata" ->> 'method', 'reference', y."metadata" ->> 'reference', 'note', y."metadata" ->> 'note', 'recordedBy', y."actor_id") order by y."effective_at", y."created_at")
        from "better_supabase"."ledger_entries" e join "better_supabase"."ledger_transactions" y on y."id" = e."transaction_id"
        where e."account_id" = (select a."id" from "better_supabase"."ledger_accounts" a where a."tenant_id" = v_row."tenant_id" and a."code" = 'invoice:' || v_row."id"::text)), '[]'::jsonb))|| case when v_warnings is null then '{}'::jsonb else jsonb_build_object('warnings', v_warnings) end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.issue_invoice_tax (
  invoice uuid,
  on_date date
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_inv "better_supabase"."invoices"%rowtype;
  v_result jsonb;
begin
  select * into v_inv from "better_supabase"."invoices" x where x."id" = issue_invoice_tax.invoice;
  if not found then
    return;
  end if;
  -- A line that names a code by text takes the code's id and keeps its rate.
  update "better_supabase"."invoice_lines" x set "tax_code_id" = "better_supabase"."resolve_tax_code"(v_inv."tenant_id", x."tax_code", v_inv.legal_entity_id)
  where x."parent_id" = v_inv."id" and x."tax_code_id" is null and x."tax_code" is not null
    and "better_supabase"."resolve_tax_code"(v_inv."tenant_id", x."tax_code", v_inv.legal_entity_id) is not null;
  -- A line that names a code by id takes the code's text and its rate on the
  -- issue date; a margin scheme line charges nothing on top of its price.
  update "better_supabase"."invoice_lines" x set
    "tax_code" = y."code",
    "tax_rate_bps" = case when y."type" = 'margin' then 0 else coalesce("better_supabase"."tax_rate_on"(y."id", issue_invoice_tax.on_date), x."tax_rate_bps") end
  from "better_supabase"."tax_codes" y
  where x."parent_id" = v_inv."id" and x."tax_code_id" = y."id";
  select "better_supabase"."tax_compute_lines"(
    coalesce((select jsonb_agg(jsonb_build_object('quantity', x."quantity", 'unitAmount', x."unit_amount"::text, 'discountBps', x."discount_bps", 'discountAmount', x."discount_amount"::text, 'taxRateBps', x."tax_rate_bps", 'taxCodeId', x."tax_code_id", 'unitCost', x."unit_cost"::text) order by x."position") from "better_supabase"."invoice_lines" x
      where x."parent_id" = v_inv."id" and true), '[]'::jsonb),
    issue_invoice_tax.on_date, v_inv."prices_include_tax", coalesce((select z."credit_restriction_bps" from "better_supabase"."payment_terms" z where z."id" = v_inv."payment_terms_id"), 0),
    v_inv."discount_bps", v_inv."discount_amount")
  into v_result;
  delete from "better_supabase"."invoice_tax_lines" x where x."invoice_id" = v_inv."id";
  insert into "better_supabase"."invoice_tax_lines" ("tenant_id", "invoice_id", "tax_rate_bps", "tax_code", "tax_code_id", "net", "tax", "gross", "discount", "customer_vat_number", "show_tax")
  select v_inv."tenant_id", v_inv."id", g."rateBps", g.code, g."taxCodeId", g.net, g.tax, g.gross, g.discount, (select nullif(trim(z."vat_id"), '') from "better_supabase"."companies" z where z."id"::text = v_inv."company_id"::text), g."showTax"
  from jsonb_to_recordset(v_result -> 'groups') g("rateBps" integer, code text, "taxCodeId" uuid, net bigint, tax bigint, gross bigint, discount bigint, "showTax" boolean);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.issue_pass (
  tenant       uuid,
  kind         text                     DEFAULT 'ticket'::text,
  holder_user  uuid                     DEFAULT NULL::uuid,
  holder_name  text                     DEFAULT NULL::text,
  holder_email text                     DEFAULT NULL::text,
  subject_type text                     DEFAULT NULL::text,
  subject_id   text                     DEFAULT NULL::text,
  booking_id   uuid                     DEFAULT NULL::uuid,
  resource_id  uuid                     DEFAULT NULL::uuid,
  uses_allowed integer                  DEFAULT NULL::integer,
  starts_at    timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  expires_at   timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."passes"%rowtype;
  v_resource uuid := issue_pass.resource_id;
  v_until timestamptz := issue_pass.expires_at;
  v_booking "better_supabase"."bookings"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', issue_pass.tenant, 'passes.manage'), false)) then
    raise exception 'not allowed to issue passes' using errcode = '42501', hint = 'PASS_FORBIDDEN';
  end if;
  if (issue_pass.subject_type is null) <> (issue_pass.subject_id is null) then
    raise exception 'pass both subject_type and subject_id, or neither' using errcode = '22023', hint = 'PASS_SUBJECT_INVALID';
  end if;
  if issue_pass.subject_type is not null
    and (case issue_pass.subject_type
      when 'message' then (select s."tenant_id"::text from "better_supabase"."messages" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'conversation' then (select s."tenant_id"::text from "better_supabase"."conversations" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'channel' then (select s."tenant_id"::text from "better_supabase"."channels" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'company' then (select s."tenant_id"::text from "better_supabase"."companies" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'person' then (select s."tenant_id"::text from "better_supabase"."people" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'deal' then (select s."tenant_id"::text from "better_supabase"."deals" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'course' then (select s."tenant_id"::text from "better_supabase"."courses" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'post' then (select s."tenant_id"::text from "better_supabase"."posts" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'activity' then (select s."tenant_id"::text from "better_supabase"."activities" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'quote' then (select s."tenant_id"::text from "better_supabase"."quotes" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'work_item' then (select s."tenant_id"::text from "better_supabase"."work_items" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'employee' then (select s."tenant_id"::text from "better_supabase"."employees" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'ledger_account' then (select s."tenant_id"::text from "better_supabase"."ledger_accounts" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'invoice' then (select s."tenant_id"::text from "better_supabase"."invoices" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'product' then (select s."tenant_id"::text from "better_supabase"."products" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'product_variant' then (select s."tenant_id"::text from "better_supabase"."product_variants" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'rfq' then (select s."tenant_id"::text from "better_supabase"."rfqs" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'till' then (select s."tenant_id"::text from "better_supabase"."tills" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'order' then (select s."tenant_id"::text from "better_supabase"."orders" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'calendar_event' then (select s."tenant_id"::text from "better_supabase"."calendar_events" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'booking' then (select s."tenant_id"::text from "better_supabase"."bookings" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'asset' then (select s."tenant_id"::text from "better_supabase"."assets" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'asset_location' then (select s."tenant_id"::text from "better_supabase"."asset_locations" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'lease' then (select s."tenant_id"::text from "better_supabase"."leases" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'expense_report' then (select s."tenant_id"::text from "better_supabase"."expense_reports" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'expense_line' then (select s."tenant_id"::text from "better_supabase"."expense_lines" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'donation_fund' then (select s."tenant_id"::text from "better_supabase"."donation_funds" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'warranty_claim' then (select s."tenant_id"::text from "better_supabase"."warranty_claims" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'work_order' then (select s."tenant_id"::text from "better_supabase"."work_orders" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'shipment' then (select s."tenant_id"::text from "better_supabase"."shipments" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'contract' then (select s."tenant_id"::text from "better_supabase"."contracts" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'control' then (select s."tenant_id"::text from "better_supabase"."controls" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'compliance_policy' then (select s."tenant_id"::text from "better_supabase"."compliance_policies" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'qualification_type' then (select s."tenant_id"::text from "better_supabase"."qualification_types" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'risk' then (select s."tenant_id"::text from "better_supabase"."risks" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'case' then (select s."tenant_id"::text from "better_supabase"."cases" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'inspection' then (select s."tenant_id"::text from "better_supabase"."inspections" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'inspection_program' then (select s."tenant_id"::text from "better_supabase"."inspection_programs" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'inspection_finding' then (select s."tenant_id"::text from "better_supabase"."inspection_findings" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'form' then (select s."tenant_id"::text from "better_supabase"."forms" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'meeting' then (select s."tenant_id"::text from "better_supabase"."meetings" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'meeting_decision' then (select s."tenant_id"::text from "better_supabase"."meeting_decisions" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'maintenance_plan' then (select s."tenant_id"::text from "better_supabase"."maintenance_plans" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'dam_usage_right' then (select s."tenant_id"::text from "better_supabase"."dam_usage_rights" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'lims_sample' then (select s."tenant_id"::text from "better_supabase"."lims_samples" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'tax_code' then (select s."tenant_id"::text from "better_supabase"."tax_codes" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'production_order' then (select s."tenant_id"::text from "better_supabase"."production_orders" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'work_center' then (select s."tenant_id"::text from "better_supabase"."work_centers" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'bank_account' then (select s."tenant_id"::text from "better_supabase"."bank_accounts" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'care_plan' then (select s."tenant_id"::text from "better_supabase"."care_plans" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'incident' then (select s."tenant_id"::text from "better_supabase"."incidents" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'content_entry' then (select s."tenant_id"::text from "better_supabase"."content_entries" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'document' then (select s."tenant_id"::text from "better_supabase"."documents" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'customer' then (select s."organization_id"::text from "public"."customers" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'drive_node' then (select s."tenant_id"::text from "better_supabase"."drive_nodes" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'organization' then (select s."id"::text from "public"."organizations" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'application' then (select s."tenant_id"::text from "better_supabase"."applications" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'change_request' then (select s."organization_id"::text from "public"."change_requests" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'project' then (select s."organization_id"::text from "public"."projects" s where s."id" = (issue_pass.subject_id)::uuid)
      when 'task' then (select s."organization_id"::text from "public"."tasks" s where s."id" = (issue_pass.subject_id)::uuid)
      else null::text
    end) is distinct from issue_pass.tenant::text then
    raise exception 'the record does not exist in this organization' using errcode = 'P0002', hint = 'PASS_SUBJECT_NOT_FOUND';
  end if;
  if issue_pass.holder_user is not null and not exists (select 1 from auth.users u where u.id = issue_pass.holder_user) then
    raise exception 'the holder does not exist' using errcode = 'P0002', hint = 'PASS_HOLDER_NOT_FOUND';
  end if;
  if issue_pass.booking_id is not null then
    select * into v_booking from "better_supabase"."bookings" bk
      where bk."id" = issue_pass.booking_id and bk."tenant_id" = issue_pass.tenant;
    if not found then
      raise exception 'the booking does not exist in this organization' using errcode = 'P0002', hint = 'PASS_BOOKING_NOT_FOUND';
    end if;
    if v_booking."status" = 'cancelled' then
      raise exception 'the booking is cancelled' using errcode = '55000', hint = 'PASS_BOOKING_CANCELLED';
    end if;
    if issue_pass.resource_id is not null and issue_pass.resource_id <> v_booking."resource_id" then
      raise exception 'the booking is for another resource' using errcode = '22023', hint = 'PASS_RESOURCE_MISMATCH';
    end if;
    v_resource := v_booking."resource_id";
    v_until := coalesce(v_until, upper(v_booking."during"));
  elsif issue_pass.resource_id is not null then
    if not exists (
      select 1 from "better_supabase"."booking_resources" rs
      where rs."id" = issue_pass.resource_id and rs."tenant_id" = issue_pass.tenant
    ) then
      raise exception 'the resource does not exist in this organization' using errcode = 'P0002', hint = 'PASS_RESOURCE_NOT_FOUND';
    end if;
  end if;
  if v_until is not null and v_until <= coalesce(issue_pass.starts_at, now()) then
    raise exception 'expires_at must be after starts_at and in the future' using errcode = '22023', hint = 'PASS_VALIDITY_INVALID';
  end if;
  insert into "better_supabase"."passes" ("tenant_id", "kind", "holder_id", "holder_name", "holder_email", "subject_type", "subject_id", "booking_id", "resource_id", "uses_allowed", "starts_at", "expires_at", "nonce", "issued_by")
  values (issue_pass.tenant, coalesce(issue_pass.kind, 'ticket'), issue_pass.holder_user, issue_pass.holder_name, lower(btrim(issue_pass.holder_email)),
    issue_pass.subject_type, issue_pass.subject_id, issue_pass.booking_id, v_resource,
    case when issue_pass.booking_id is not null then coalesce(issue_pass.uses_allowed, 1) else issue_pass.uses_allowed end,
    coalesce(issue_pass.starts_at, now()), v_until, encode(extensions.gen_random_bytes(16), 'hex'), auth.uid())
  returning * into v_row;
  perform "better_supabase".emit_event('pass.issued', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'id', v_row."id", 'kind', v_row."kind", 'holderUserId', v_row."holder_id", 'bookingId', v_row."booking_id"), 'passes/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/passes');
  perform better_supabase.audit_event(
    event_type => 'pass.issued',
    category => 'access',
    target_type => 'pass',
    record_id => v_row."id"::text,
    summary => 'issued pass ' || v_row."kind",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'id', v_row."id", 'kind', v_row."kind", 'holderUserId', v_row."holder_id", 'bookingId', v_row."booking_id")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id"::text, 'kind', v_row."kind", 'holderUserId', v_row."holder_id", 'holderName', v_row."holder_name", 'holderEmail', v_row."holder_email", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'bookingId', v_row."booking_id", 'resourceId', v_row."resource_id", 'usesAllowed', v_row."uses_allowed", 'uses', v_row."uses", 'validFrom', v_row."starts_at", 'validUntil', v_row."expires_at", 'status', v_row."status", 'issuedBy', v_row."issued_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at", 'revokedAt', v_row."revoked_at") || jsonb_build_object('nonce', v_row."nonce");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.issue_statement (
  item_id             uuid,
  restriction         text,
  facts               text,
  legal_ground        text    DEFAULT NULL::text,
  terms_ground        text    DEFAULT NULL::text,
  automated_detection boolean DEFAULT false,
  automated_decision  boolean DEFAULT false,
  redress             text[]  DEFAULT NULL::text[]
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_item "better_supabase"."moderation_items";
  v_row "better_supabase"."moderation_statements";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_item from "better_supabase"."moderation_items" x where x."id" = issue_statement.item_id;
  if v_item."id" is null then
    raise exception 'moderation item not found' using errcode = 'P0002', hint = 'MODERATION_ITEM_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_item."tenant_id", 'moderation.manage'), false)) then
    raise exception 'not allowed to issue statements of reasons' using errcode = '42501', hint = 'MODERATION_FORBIDDEN';
  end if;
  if issue_statement.restriction is null or issue_statement.restriction not in ('removal', 'disabled_access', 'demotion', 'visibility_suspension', 'monetary_suspension', 'service_suspension', 'service_termination', 'account_suspension', 'account_termination') then
    raise exception 'restriction must be one of the Article 17 restrictions' using errcode = '22023', hint = 'MODERATION_INVALID';
  end if;
  if issue_statement.facts is null or length(trim(issue_statement.facts)) = 0 or length(issue_statement.facts) > 5000 then
    raise exception 'a statement needs facts and circumstances of at most 5000 characters' using errcode = '22023', hint = 'MODERATION_INVALID';
  end if;
  if nullif(trim(issue_statement.legal_ground), '') is null and nullif(trim(issue_statement.terms_ground), '') is null then
    raise exception 'a statement needs a legal ground or a terms ground' using errcode = '22023', hint = 'MODERATION_INVALID';
  end if;
  insert into "better_supabase"."moderation_statements" ("tenant_id", "item_id", "restriction", "facts", "legal_ground", "terms_ground", "automated_detection", "automated_decision", "redress", "issued_by")
  values (v_item."tenant_id", v_item."id", issue_statement.restriction, trim(issue_statement.facts), nullif(trim(issue_statement.legal_ground), ''), nullif(trim(issue_statement.terms_ground), ''),
    coalesce(issue_statement.automated_detection, false), coalesce(issue_statement.automated_decision, false),
    coalesce(issue_statement.redress, array['internal_complaint', 'out_of_court', 'judicial']), auth.uid())
  returning * into v_row;
  perform "better_supabase".emit_event('moderation_statement.issued', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'itemId', v_row."item_id", 'restriction', v_row."restriction", 'authorId', v_item."author_id"), 'moderation-statements/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/moderation');
  perform better_supabase.audit_event(
    event_type => 'moderation_statement.issued',
    category => 'data',
    target_type => 'moderation_statement',
    record_id => v_row."id"::text,
    summary => 'statement of reasons: ' || v_row."restriction",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'itemId', v_row."item_id", 'restriction', v_row."restriction", 'authorId', v_item."author_id")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'itemId', v_row."item_id", 'restriction', v_row."restriction", 'facts', v_row."facts", 'legalGround', v_row."legal_ground", 'termsGround', v_row."terms_ground", 'automatedDetection', v_row."automated_detection", 'automatedDecision', v_row."automated_decision", 'redress', to_jsonb(v_row."redress"), 'issuedBy', v_row."issued_by", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.issue_yearly_receipt (
  tenant     uuid,
  donor_type text,
  donor_id   text,
  year       integer,
  currency   text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_receipt "better_supabase"."donation_receipts"%rowtype;
  v_amount bigint;
  v_seq bigint;
  v_number text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', issue_yearly_receipt.tenant, 'donations.manage'), false)) then
    raise exception 'not allowed to manage donations' using errcode = '42501', hint = 'DONATIONS_FORBIDDEN';
  end if;
  if issue_yearly_receipt.year is null or issue_yearly_receipt.currency is null then
    raise exception 'a yearly receipt needs a year and a currency' using errcode = '22023', hint = 'DONATION_RECEIPT_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('donations.yearly:' || issue_yearly_receipt.tenant::text || ':' || issue_yearly_receipt.donor_type
    || ':' || issue_yearly_receipt.donor_id || ':' || issue_yearly_receipt.year::text || ':' || issue_yearly_receipt.currency, 0));
  select * into v_receipt from "better_supabase"."donation_receipts" x
    where x."tenant_id" = issue_yearly_receipt.tenant and x."donor_type" = issue_yearly_receipt.donor_type
      and x."donor_id" = issue_yearly_receipt.donor_id and x."year" = issue_yearly_receipt.year
      and x."currency" = issue_yearly_receipt.currency and x."kind" = 'yearly' and x."voided_at" is null;
  if found then
    return jsonb_build_object('id', v_receipt."id", 'organizationId', v_receipt."tenant_id", 'donorType', v_receipt."donor_type", 'donorId', v_receipt."donor_id", 'sequence', v_receipt."sequence"::text, 'number', v_receipt."number", 'kind', v_receipt."kind", 'year', v_receipt."year", 'amount', v_receipt."amount"::text, 'currency', v_receipt."currency", 'issuedAt', v_receipt."issued_at", 'voidedAt', v_receipt."voided_at", 'voidReason', v_receipt."void_reason");
  end if;
  select coalesce(sum(g."amount"), 0) into v_amount from "better_supabase"."donations" g
    where g."tenant_id" = issue_yearly_receipt.tenant and g."donor_type" = issue_yearly_receipt.donor_type
      and g."donor_id" = issue_yearly_receipt.donor_id and g."currency" = issue_yearly_receipt.currency
      and g."status" = 'posted' and extract(year from g."received_on")::integer = issue_yearly_receipt.year;
  if v_amount <= 0 then
    raise exception 'the donor has no posted gifts in this year and currency' using errcode = '22023', hint = 'DONATION_RECEIPT_EMPTY';
  end if;
  if (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'donation_receipt' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end) is not null then
    v_number := (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'donation_receipt' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end);
    v_seq := "better_supabase"."register_fixed_number"(issue_yearly_receipt.tenant, 'donation_receipt', v_number, now(), '');
    perform set_config('better_supabase.fixed_number', '', true);
  else
    v_seq := "better_supabase"."next_number"(issue_yearly_receipt.tenant, 'donation_receipt', now(), '');
  v_number := better_supabase.format_assigned_number('R-{n}', v_seq, now());
  end if;
  insert into "better_supabase"."donation_receipts" ("tenant_id", "donor_type", "donor_id", "sequence", "number", "kind", "year", "amount", "currency")
  values (issue_yearly_receipt.tenant, issue_yearly_receipt.donor_type, issue_yearly_receipt.donor_id, v_seq, v_number, 'yearly',
    issue_yearly_receipt.year, v_amount, issue_yearly_receipt.currency)
  returning * into v_receipt;
  perform "better_supabase".emit_event('donation_receipt.issued', jsonb_build_object('organizationId', v_receipt."tenant_id", 'id', v_receipt."id", 'number', v_receipt."number", 'kind', v_receipt."kind", 'donorType', v_receipt."donor_type", 'donorId', v_receipt."donor_id", 'amount', v_receipt."amount"::text, 'currency', v_receipt."currency"), 'donation-receipts/' || v_receipt."id"::text, (v_receipt."tenant_id")::text, null, 'better-supabase/donations');
  perform better_supabase.audit_event(
    event_type => 'donation_receipt.issued',
    category => 'billing',
    target_type => 'donation_receipt',
    record_id => v_receipt."id"::text,
    target_label => v_receipt."number",
    summary => 'issued a yearly receipt',
    tenant => (v_receipt."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_receipt."tenant_id", 'id', v_receipt."id", 'number', v_receipt."number", 'kind', v_receipt."kind", 'donorType', v_receipt."donor_type", 'donorId', v_receipt."donor_id", 'amount', v_receipt."amount"::text, 'currency', v_receipt."currency")
  );
  return jsonb_build_object('id', v_receipt."id", 'organizationId', v_receipt."tenant_id", 'donorType', v_receipt."donor_type", 'donorId', v_receipt."donor_id", 'sequence', v_receipt."sequence"::text, 'number', v_receipt."number", 'kind', v_receipt."kind", 'year', v_receipt."year", 'amount', v_receipt."amount"::text, 'currency', v_receipt."currency", 'issuedAt', v_receipt."issued_at", 'voidedAt', v_receipt."voided_at", 'voidReason', v_receipt."void_reason");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.job_queue_stats (
  queue text
)
  RETURNS TABLE (
    ready              bigint,
    in_flight          bigint,
    delayed            bigint,
    dead               bigint,
    oldest_age_seconds double precision
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if pg_catalog.to_regclass(format('pgmq.%I', 'q_' || queue)) is null then
    return query select 0::bigint, 0::bigint, 0::bigint, 0::bigint, null::double precision;
    return;
  end if;
  return query execute format(
    'select count(*) filter (where q.vt <= clock_timestamp()),
       count(*) filter (where q.vt > clock_timestamp() and q.read_ct > 0),
       count(*) filter (where q.vt > clock_timestamp() and q.read_ct = 0),
       (select count(*) from pgmq.%2$I a where a.message ? ''dead''),
       extract(epoch from clock_timestamp() - min(q.enqueued_at))::double precision
     from pgmq.%1$I q',
    'q_' || queue, 'a_' || queue
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.join_channel (
  channel uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if auth.uid() is null or not exists (select 1 from "better_supabase"."channels" x where x."id" = join_channel.channel) then
    raise exception 'no such channel you can read' using errcode = 'P0002', hint = 'CHANNELS_NOT_FOUND';
  end if;
  perform "better_supabase"."add_conversation_members"(join_channel.channel, array[auth.uid()]);
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.join_waitlist (
  email    text,
  referrer text  DEFAULT NULL::text,
  metadata jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_email text := lower(trim(join_waitlist.email));
  v_row "better_supabase"."waitlist_entries";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+$' then
    raise exception 'Not an email address' using errcode = '22023', hint = 'WAITLIST_EMAIL_INVALID';
  end if;
  insert into "better_supabase"."waitlist_entries" as x ("email", "referrer", "metadata")
  values (v_email, join_waitlist.referrer, coalesce(join_waitlist.metadata, '{}'::jsonb))
  on conflict ("email") do update set "email" = x."email"
  returning * into v_row;
  if coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then
    return jsonb_build_object(
      'position', case when v_row."status" = 'waiting' then (
        select count(*) from "better_supabase"."waitlist_entries" w where w."status" = 'waiting' and w."position" <= v_row."position"
      ) end,
      'status', case when v_row."status" = 'rejected' then 'waiting' else v_row."status" end
    );
  end if;
  return jsonb_build_object(
    'position', case when v_row."status" = 'waiting' then (
      select count(*) from "better_supabase"."waitlist_entries" w where w."status" = 'waiting' and w."position" <= v_row."position"
    ) else (
      select count(*) + 1 from "better_supabase"."waitlist_entries" w where w."status" = 'waiting'
    ) end,
    'status', 'waiting'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.kitchen_queue (
  tenant    uuid,
  station   uuid,
  states    text[],
  page_size integer
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(ticket order by ticket ->> 'sentAt', ticket ->> 'orderId'), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'orderId', o."id",
      'number', o."number",
      'sentAt', min(p."queued_at"),
      'lines', jsonb_agg(jsonb_build_object('lineId', p."order_line_id", 'orderId', p."order_id", 'stationId', p."station_id", 'title', l."title", 'sku', l."sku", 'quantity', l."quantity", 'position', l."position", 'state', p."state", 'note', p."note", 'queuedAt', p."queued_at", 'startedAt', p."started_at", 'readyAt', p."ready_at", 'servedAt', p."served_at") order by l."position", l."id")
    ) as ticket
    from "better_supabase"."order_line_preparations" p
    join "better_supabase"."order_lines" l on l."id" = p."order_line_id"
    join "better_supabase"."orders" o on o."id" = p."order_id"
    where p."tenant_id" = kitchen_queue.tenant
      and (kitchen_queue.station is null or p."station_id" = kitchen_queue.station)
      and p."state" = any (coalesce(kitchen_queue.states, array['queued', 'preparing', 'ready']))
    group by o."id", o."number"
    order by min(p."queued_at"), o."id"
    limit least(greatest(coalesce(kitchen_queue.page_size, 100), 1), 500)
  ) tickets
$function$;

CREATE OR REPLACE FUNCTION better_supabase.kitchen_stations (
  tenant uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', s."id", 'organizationId', s."tenant_id", 'key', s."key", 'name', s."name", 'position', s."position", 'isDefault', s."is_default", 'active', s."active", 'productIds', coalesce((select jsonb_agg(r."product_id" order by r."product_id") from "better_supabase"."order_kitchen_routes" r where r."station_id" = s."id"), '[]'::jsonb), 'createdAt', s."created_at", 'updatedAt', s."updated_at") order by s."position", s."name"), '[]'::jsonb)
  from "better_supabase"."order_kitchen_stations" s
  where s."tenant_id" = kitchen_stations.tenant
$function$;

CREATE OR REPLACE FUNCTION better_supabase.knowledge_collection_readable (
  collection_id uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from "better_supabase"."knowledge_collections" c
    where c."id" = knowledge_collection_readable.collection_id
      and (c."tenant_id" is null or coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', c."tenant_id", 'knowledge.read'), false))
      and (c."visibility" = 'automatic'
        or (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (c."tenant_id" is not null and coalesce(better_supabase.can('tenant', c."tenant_id", 'knowledge.manage'), false)))
        or exists (
          select 1 from "better_supabase"."knowledge_collection_grants" x
          where x."collection_id" = c."id" and (x."user_id" = auth.uid() or (x."team_id" is not null and exists (select 1 from "better_supabase"."team_members" tm where tm."team_id" = x."team_id" and tm."user_id" = auth.uid())))
        ))
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.knowledge_search (
  tenant          uuid,
  query_embedding extensions.vector DEFAULT NULL::extensions.vector,
  query_text      text              DEFAULT NULL::text,
  scopes          jsonb             DEFAULT NULL::jsonb,
  k               integer           DEFAULT 8,
  filter          jsonb             DEFAULT NULL::jsonb,
  collections     uuid[]            DEFAULT NULL::uuid[],
  priority_order  boolean           DEFAULT true
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  SET plan_cache_mode TO 'force_custom_plan'
  AS $function$
declare
  previous_scan text := current_setting('hnsw.iterative_scan', true);
  v_candidates integer := least(greatest(knowledge_search.k, 1) * 4, 400);
  v_scopes jsonb := case when jsonb_typeof(knowledge_search.scopes) = 'object' then knowledge_search.scopes -> 'items' else knowledge_search.scopes end;
  v_rows jsonb;
begin
  perform set_config('hnsw.iterative_scan', 'relaxed_order', true);
  with docs as materialized (
    select x."id" as id, x."tenant_id" as doc_tenant, x."title" as title, coalesce((select kc."priority" from "better_supabase"."knowledge_collections" kc where kc."id" = x."collection_id"), 0) as priority from "better_supabase"."knowledge_documents" x
    where (x."tenant_id" = knowledge_search.tenant or x."tenant_id" is null)
      and (x."collection_id" is null or exists (select 1 from "better_supabase"."knowledge_collections" kc where kc."id" = x."collection_id" and kc."visibility" <> 'disabled'))
      and (knowledge_search.collections is null or x."collection_id" = any(knowledge_search.collections))
      and (v_scopes is null or exists (
        select 1 from jsonb_array_elements(v_scopes) s
        where s.value ->> 'scope' = x."scope"
          and (s.value ->> 'scope' = 'subject' or s.value ->> 'id' is null or (s.value ->> 'id')::uuid = x."scope_id")
          and (s.value ->> 'scope' <> 'subject' or ((s.value ->> 'type' is null or s.value ->> 'type' = x."subject_type") and (s.value ->> 'id' is null or s.value ->> 'id' = x."subject_id")))
      ))
      and (knowledge_search.filter is null or x."metadata" @> knowledge_search.filter)
  ),
  vector_hits as materialized (
    select t."document_id" as document_id, t."idx" as idx, t."embedding" operator(extensions.<=>) knowledge_search.query_embedding as distance
    from "better_supabase"."knowledge_chunks" t
    where knowledge_search.query_embedding is not null and t."embedding" is not null
      and t."document_id" in (select docs.id from docs)
    order by t."embedding" operator(extensions.<=>) knowledge_search.query_embedding
    limit v_candidates
  ),
  vector_ranked as (
    select h.document_id, h.idx, row_number() over (order by h.distance) as rank from vector_hits h
  ),
  text_hits as materialized (
    select t."document_id" as document_id, t."idx" as idx, ts_rank_cd(t."tsv", q) as text_score
    from "better_supabase"."knowledge_chunks" t, websearch_to_tsquery('simple'::regconfig, knowledge_search.query_text) q
    where knowledge_search.query_text is not null and t."tsv" @@ q
      and t."document_id" in (select docs.id from docs)
    order by text_score desc
    limit v_candidates
  ),
  text_ranked as (
    select x.document_id, x.idx, row_number() over (order by x.text_score desc) as rank from text_hits x
  ),
  fused as (
    select coalesce(v.document_id, x.document_id) as document_id, coalesce(v.idx, x.idx) as idx,
      coalesce(1.0 / (60 + v.rank), 0) + coalesce(1.0 / (60 + x.rank), 0) as score
    from vector_ranked v full join text_ranked x on x.document_id = v.document_id and x.idx = v.idx
  )
  select coalesce(jsonb_agg(jsonb_build_object('document_id', r.document_id, 'idx', r.idx, 'chunk_id', r.document_id::text || '#' || r.idx::text, 'organization_id', r.doc_tenant, 'content', r.content, 'metadata', r.metadata, 'title', r.title, 'score', r.score) order by r.rank_priority desc, r.score desc, r.document_id, r.idx), '[]')
  into v_rows
  from (
    select f.document_id, f.idx, t."content" as content, t."metadata" as metadata, docs.title, docs.doc_tenant,
      case when knowledge_search.priority_order then docs.priority else 0 end as rank_priority, f.score
    from fused f
    join "better_supabase"."knowledge_chunks" t on t."document_id" = f.document_id and t."idx" = f.idx
    join docs on docs.id = f.document_id
    order by rank_priority desc, f.score desc, f.document_id, f.idx
    limit least(greatest(knowledge_search.k, 1), 100)
  ) r;
  perform set_config('hnsw.iterative_scan', coalesce(previous_scan, 'off'), true);
  return v_rows;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.knowledge_subject_readable (
  subject_type text,
  subject_id   text
)
  RETURNS boolean
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
begin
  return coalesce("better_supabase"."can_subject"(knowledge_subject_readable.subject_type, knowledge_subject_readable.subject_id, 'read'), false);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.label_version (
  version_id uuid,
  label      text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_subject_type text;
  v_subject_id text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select "tenant_id", "subject_type", "subject_id" into v_tenant, v_subject_type, v_subject_id
    from "better_supabase"."versions" where "id" = label_version.version_id;
  if v_subject_type is null then
    raise exception 'version not found' using errcode = 'P0002', hint = 'VERSION_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (coalesce(better_supabase.can('tenant', v_tenant, 'versions.create'), false) and case v_subject_type
    when 'project' then exists (select 1 from "public"."projects" s where s."id" = (v_subject_id)::uuid and s."organization_id" = v_tenant)
    when 'customer' then exists (select 1 from "public"."customers" s where s."id" = (v_subject_id)::uuid and s."organization_id" = v_tenant) and coalesce(better_supabase.can('tenant', v_tenant, 'customers.read'), false)
    else false
  end and v_subject_type <> 'ai_document')) then
    raise exception 'not allowed to label this version' using errcode = '42501', hint = 'VERSION_FORBIDDEN';
  end if;
  update "better_supabase"."versions" set "label" = nullif(trim(label_version.label), '')
    where "id" = label_version.version_id and not "frozen";
  if not found then
    raise exception 'a frozen version keeps its label' using errcode = '55000', hint = 'VERSION_FROZEN';
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.last_sign_ins (
  p_users uuid[]
)
  RETURNS TABLE (
    user_id         uuid,
    last_sign_in_at timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select u.id, u.last_sign_in_at
  from auth.users u
  where u.id = any(p_users)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.latest_observations (
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_object_agg(r.key, r.item), '{}'::jsonb)
  from (
    select distinct on (y."key") y."key" as key, jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'definitionId', x."definition_id", 'definitionKey', y."key", 'title', y."title", 'valueType', y."value_type", 'unit', y."unit", 'subjectType', x."subject_type", 'subjectId', x."subject_id", 'observedAt', x."observed_at", 'value', case y."value_type"
      when 'boolean' then to_jsonb(x."value_code" = 'true')
      when 'code' then to_jsonb(x."value_code")
      when 'text' then to_jsonb(x."value_text")
      when 'components' then x."components"
      else to_jsonb(x."value_number")
    end, 'flag', x."flag", 'status', x."status", 'replacesId', x."replaces_id", 'reason', x."reason", 'method', x."method", 'device', x."device", 'source', x."source", 'externalId', x."external_id", 'submissionId', x."submission_id", 'performerId', x."performer_id", 'note', x."note", 'createdAt', x."created_at") as item
    from "better_supabase"."observations" x
    join "better_supabase"."observation_definitions" y on y."id" = x."definition_id"
    where x."subject_type" = latest_observations.subject_type
      and x."subject_id" = latest_observations.subject_id
      and x."status" = 'final'
    order by y."key", x."observed_at" desc, x."created_at" desc
  ) r
$function$;

CREATE OR REPLACE FUNCTION better_supabase.lead_fields (
  tenant       uuid,
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_id uuid;
  v_row jsonb;
  v_tenant uuid;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (lead_fields.tenant is not null and coalesce(better_supabase.can('tenant', lead_fields.tenant, 'scores.compute'), false))) then
    raise exception 'not allowed to score leads' using errcode = '42501', hint = 'LEAD_SCORING_FORBIDDEN';
  end if;
  begin
    v_id := lead_fields.subject_id::uuid;
  exception when invalid_text_representation then
    return null;
  end;
  if lead_fields.subject_type = 'person' then
    select to_jsonb(x), x."tenant_id" into v_row, v_tenant from "better_supabase"."people" x where x."id" = v_id;
    if v_row is null or v_tenant is distinct from lead_fields.tenant then
      return null;
    end if;
    return v_row || jsonb_build_object(
      'segments', (select coalesce(jsonb_agg(x."segment_id"::text order by x."segment_id"), '[]'::jsonb)
    from "better_supabase"."segment_members" x
    join "better_supabase"."segments" g on g."id" = x."segment_id"
    where g."subject_type" = lead_fields.subject_type and x."subject_id" = lead_fields.subject_id),
      'mail', (select jsonb_build_object(
      'sent', count(*) filter (where y."direction" = 'outbound'),
      'opened', count(*) filter (where y."direction" = 'outbound' and y."opened_at" is not null),
      'clicked', count(*) filter (where y."direction" = 'outbound' and y."clicked_at" is not null),
      'replied', count(*) filter (where y."direction" = 'inbound'),
      'lastSentAt', max(y."sent_at") filter (where y."direction" = 'outbound'),
      'lastRepliedAt', max(y."sent_at") filter (where y."direction" = 'inbound')
    )
    from "better_supabase"."mail_thread_subjects" k
    join "better_supabase"."mail_messages" y on y."thread_id" = k."thread_id"
    where k."subject_type" = lead_fields.subject_type and k."subject_id" = lead_fields.subject_id),
      'enrichment', (select jsonb_build_object('status', x."status", 'provider', x."provider", 'fetchedAt', x."fetched_at")
    from "better_supabase"."enrichments" x
    where x."person_id" = v_id
    order by x."fetched_at" desc nulls last
    limit 1)
    );
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.lead_mail_changed()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  insert into "better_supabase"."lead_score_checks" ("tenant_id", "subject_type", "subject_id")
  select k."tenant_id", k."subject_type", k."subject_id"
  from "better_supabase"."mail_thread_subjects" k
  where k."thread_id" = new."thread_id" and k."subject_type" in ('person')
  on conflict ("subject_type", "subject_id") do update set "stale" = true;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.lead_mail_linked()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if new."subject_type" in ('person') then
    insert into "better_supabase"."lead_score_checks" ("tenant_id", "subject_type", "subject_id")
  values (new."tenant_id", new."subject_type", new."subject_id")
  on conflict ("subject_type", "subject_id") do update set "stale" = true;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.lead_person_changed()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  insert into "better_supabase"."lead_score_checks" ("tenant_id", "subject_type", "subject_id")
  values (new."tenant_id", 'person', new."id"::text)
  on conflict ("subject_type", "subject_id") do update set "stale" = true;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.lead_segment_changed()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if tg_op = 'DELETE' then
    insert into "better_supabase"."lead_score_checks" ("tenant_id", "subject_type", "subject_id")
  select old."tenant_id", g."subject_type", old."subject_id"
  from "better_supabase"."segments" g
  where g."id" = old."segment_id" and g."subject_type" in ('person')
  on conflict ("subject_type", "subject_id") do update set "stale" = true;
  else
    insert into "better_supabase"."lead_score_checks" ("tenant_id", "subject_type", "subject_id")
  select new."tenant_id", g."subject_type", new."subject_id"
  from "better_supabase"."segments" g
  where g."id" = new."segment_id" and g."subject_type" in ('person')
  on conflict ("subject_type", "subject_id") do update set "stale" = true;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.leases_subject_merge (
  subject_table text,
  keep          text,
  drop          text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_type text;
  v_keep text := keep;
  v_drop text := drop;
begin
  for v_type in select unnest(case subject_table when 'better_supabase.messages' then array['message'] when 'better_supabase.conversations' then array['conversation'] when 'better_supabase.channels' then array['channel'] when 'better_supabase.companies' then array['company'] when 'better_supabase.people' then array['person'] when 'better_supabase.deals' then array['deal'] when 'better_supabase.courses' then array['course'] when 'better_supabase.posts' then array['post'] when 'better_supabase.activities' then array['activity'] when 'better_supabase.quotes' then array['quote'] when 'better_supabase.work_items' then array['work_item'] when 'better_supabase.employees' then array['employee'] when 'better_supabase.ledger_accounts' then array['ledger_account'] when 'better_supabase.invoices' then array['invoice'] when 'better_supabase.products' then array['product'] when 'better_supabase.product_variants' then array['product_variant'] when 'better_supabase.rfqs' then array['rfq'] when 'better_supabase.tills' then array['till'] when 'better_supabase.orders' then array['order'] when 'better_supabase.calendar_events' then array['calendar_event'] when 'better_supabase.bookings' then array['booking'] when 'better_supabase.assets' then array['asset'] when 'better_supabase.asset_locations' then array['asset_location'] when 'better_supabase.leases' then array['lease'] when 'better_supabase.expense_reports' then array['expense_report'] when 'better_supabase.expense_lines' then array['expense_line'] when 'better_supabase.donation_funds' then array['donation_fund'] when 'better_supabase.warranty_claims' then array['warranty_claim'] when 'better_supabase.work_orders' then array['work_order'] when 'better_supabase.shipments' then array['shipment'] when 'better_supabase.contracts' then array['contract'] when 'better_supabase.controls' then array['control'] when 'better_supabase.compliance_policies' then array['compliance_policy'] when 'better_supabase.qualification_types' then array['qualification_type'] when 'better_supabase.risks' then array['risk'] when 'better_supabase.cases' then array['case'] when 'better_supabase.inspections' then array['inspection'] when 'better_supabase.inspection_programs' then array['inspection_program'] when 'better_supabase.inspection_findings' then array['inspection_finding'] when 'better_supabase.forms' then array['form'] when 'better_supabase.meetings' then array['meeting'] when 'better_supabase.meeting_decisions' then array['meeting_decision'] when 'better_supabase.maintenance_plans' then array['maintenance_plan'] when 'better_supabase.dam_usage_rights' then array['dam_usage_right'] when 'better_supabase.lims_samples' then array['lims_sample'] when 'better_supabase.tax_codes' then array['tax_code'] when 'better_supabase.production_orders' then array['production_order'] when 'better_supabase.work_centers' then array['work_center'] when 'better_supabase.bank_accounts' then array['bank_account'] when 'better_supabase.care_plans' then array['care_plan'] when 'better_supabase.incidents' then array['incident'] when 'better_supabase.content_entries' then array['content_entry'] when 'better_supabase.documents' then array['document'] when 'public.customers' then array['customer'] when 'better_supabase.drive_nodes' then array['drive_node'] when 'public.organizations' then array['organization'] when 'better_supabase.applications' then array['application'] when 'public.change_requests' then array['change_request'] when 'public.projects' then array['project'] when 'public.tasks' then array['task'] else '{}'::text[] end) loop
    update "better_supabase"."leases" x set "party_id" = v_keep where x."party_type" = v_type and x."party_id" = v_drop;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.leave_available (
  tenant  uuid,
  user_id uuid,
  type_id uuid,
  period  integer
)
  RETURNS numeric
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce((select b."balance"::numeric / 100 from "better_supabase"."ledger_accounts" x join "better_supabase"."ledger_balances" b on b."account_id" = x."id"
      where x."tenant_id" = leave_available.tenant and x."code" = 'leave:' || leave_available.type_id::text || ':' || leave_available.user_id::text || ':' || leave_available.period::text), 0)
    - coalesce((select sum(r."amount") from "better_supabase"."leave_requests" r
      left join "better_supabase"."approval_requests" p on p."id" = r."approval_id"
      where r."tenant_id" = leave_available.tenant and r."user_id" = leave_available.user_id
        and r."type_id" = leave_available.type_id and extract(year from r."starts_on")::integer = leave_available.period
        and r."cancelled_at" is null and r."approved_at" is null and p."status" = 'pending'), 0)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.leave_balances (
  tenant  uuid,
  user_id uuid    DEFAULT NULL::uuid,
  period  integer DEFAULT NULL::integer
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_user uuid := coalesce(leave_balances.user_id, auth.uid());
  v_period integer := coalesce(leave_balances.period, extract(year from current_date)::integer);
  v_rows jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', leave_balances.tenant, 'leave.read'), false)
    or (coalesce(v_user = auth.uid(), false) and coalesce(better_supabase.can('tenant', leave_balances.tenant, 'leave.request'), false))) then
    raise exception 'not allowed to read this member''s leave balance' using errcode = '42501', hint = 'LEAVE_FORBIDDEN';
  end if;
  if v_user is null then
    raise exception 'name user_id' using errcode = '22023', hint = 'LEAVE_INVALID';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'typeId', t."id", 'key', t."key", 'name', t."name", 'unit', t."unit",
      'userId', v_user, 'period', v_period,
      'granted', (coalesce(b.granted, 0)::numeric / 100)::numeric(10, 2)::text,
      'taken', (coalesce(b.taken, 0)::numeric / 100)::numeric(10, 2)::text,
      'pending', w.pending::numeric(10, 2)::text,
      'available', (coalesce(b.total, 0)::numeric / 100 - w.pending)::numeric(10, 2)::text
    ) order by t."name"), '[]'::jsonb) into v_rows
  from "better_supabase"."leave_types" t
  left join lateral (
    select sum(y."amount") filter (where r."kind" <> 'leave.taken') as granted,
      -sum(y."amount") filter (where r."kind" = 'leave.taken') as taken,
      sum(y."amount") as total
    from "better_supabase"."ledger_entries" y
    join "better_supabase"."ledger_accounts" x on x."id" = y."account_id" and x."managed_by" = 'leave' and x."kind" = 'leave'
    join "better_supabase"."ledger_transactions" r on r."id" = y."transaction_id"
    where x."tenant_id" = leave_balances.tenant and x."code" = 'leave:' || t."id"::text || ':' || v_user::text || ':' || v_period::text
  ) b on true
  cross join lateral (
    select coalesce((select sum(r."amount") from "better_supabase"."leave_requests" r
      left join "better_supabase"."approval_requests" p on p."id" = r."approval_id"
      where r."tenant_id" = leave_balances.tenant and r."user_id" = v_user
        and r."type_id" = t."id" and extract(year from r."starts_on")::integer = v_period
        and r."cancelled_at" is null and r."approved_at" is null and p."status" = 'pending'), 0) as pending
  ) w
  where t."tenant_id" = leave_balances.tenant and t."tracked" and t."archived_at" is null;
  return v_rows;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.leave_channel (
  channel uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if auth.uid() is null or not exists (select 1 from "better_supabase"."channels" x where x."id" = leave_channel.channel) then
    raise exception 'no such channel you can read' using errcode = 'P0002', hint = 'CHANNELS_NOT_FOUND';
  end if;
  return "better_supabase"."remove_conversation_member"(leave_channel.channel, auth.uid());
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.leave_close_range (
  tenant    uuid,
  starts_on date,
  ends_on   date
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  perform "better_supabase"."close_leave_year"(leave_close_range.tenant, extract(year from leave_close_range.starts_on)::integer);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.leave_feed (
  token text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_link uuid;
  v_tenant uuid;
  v_creator uuid;
  v_team text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if leave_feed.token is null or length(leave_feed.token) < 32 then
    return null;
  end if;
  select l."id", l."tenant_id", l."created_by", case when l."subject_type" = 'leave_team_feed' then l."subject_id" end
  into v_link, v_tenant, v_creator, v_team
  from "better_supabase"."share_links" l
  where l."token_hash" = encode(extensions.digest(convert_to(leave_feed.token, 'utf8'), 'sha256'), 'hex')
    and l."subject_type" = any (array['leave_feed'])
    and l."revoked_at" is null
    and (l."expires_at" is null or l."expires_at" > now())
    and (l."max_uses" is null or l."use_count" < l."max_uses")
    and l."password_hash" is null
    and (l."subject_type" <> 'leave_feed' or l."subject_id" = l."tenant_id"::text)
  for update;
  if v_tenant is null or v_creator is null or not coalesce(better_supabase.can_user(v_creator, 'tenant', v_tenant, 'leave.read'), false) then
    return null;
  end if;
  update "better_supabase"."share_links" set "use_count" = "use_count" + 1, "last_used_at" = now() where "id" = v_link;
  return jsonb_build_object(
    'organizationId', v_tenant,
    'requests', coalesce((
      select jsonb_agg(x.item order by x.starts_on, x.id)
      from (
        select jsonb_build_object('id', r."id", 'userId', r."user_id", 'typeId', r."type_id", 'type', t."name", 'unit', t."unit",
          'startsOn', r."starts_on", 'endsOn', r."ends_on", 'partial', r."partial", 'startPart', (case r."partial" when 'afternoon' then 'afternoon' when 'hours' then 'hours' else 'full' end), 'endPart', (case r."partial" when 'morning' then 'morning' when 'hours' then 'hours' else 'full' end), 'amount', r."amount"::text, 'approvedAt', r."approved_at", 'updatedAt', r."updated_at") as item,
          r."starts_on" as starts_on, r."id" as id
        from "better_supabase"."leave_requests" r
        join "better_supabase"."leave_types" t on t."id" = r."type_id"
        where r."tenant_id" = v_tenant and r."approved_at" is not null and r."cancelled_at" is null
          and r."ends_on" >= current_date - 366
        order by r."starts_on", r."id"
        limit 5000
      ) x
    ), '[]'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.leave_ledger_entries (
  tenant  uuid,
  user_id uuid    DEFAULT NULL::uuid,
  period  integer DEFAULT NULL::integer,
  type_id uuid    DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_user uuid := coalesce(leave_ledger_entries.user_id, auth.uid());
  v_rows jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', leave_ledger_entries.tenant, 'leave.read'), false)
    or (coalesce(v_user = auth.uid(), false) and coalesce(better_supabase.can('tenant', leave_ledger_entries.tenant, 'leave.request'), false))) then
    raise exception 'not allowed to read this member''s leave balance' using errcode = '42501', hint = 'LEAVE_FORBIDDEN';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', y."id", 'organizationId', x."tenant_id", 'userId', x."owner_id",
      'typeId', (x."metadata" ->> 'typeId')::uuid, 'kind', substr(r."kind", 7), 'amount', (y."amount"::numeric / 100)::numeric(10, 2)::text,
      'period', (x."metadata" ->> 'period')::integer,
      'requestId', case when r."reference_type" = 'leave-requests' then r."reference_id"::uuid end,
      'note', r."memo", 'createdAt', y."created_at") order by y."created_at" desc, y."id" desc), '[]'::jsonb) into v_rows
  from "better_supabase"."ledger_entries" y
    join "better_supabase"."ledger_accounts" x on x."id" = y."account_id" and x."managed_by" = 'leave' and x."kind" = 'leave'
    join "better_supabase"."ledger_transactions" r on r."id" = y."transaction_id"
  where x."tenant_id" = leave_ledger_entries.tenant and x."owner_id" = v_user
    and (leave_ledger_entries.period is null or (x."metadata" ->> 'period')::integer = leave_ledger_entries.period)
    and (leave_ledger_entries.type_id is null or x."holder_id" = leave_ledger_entries.type_id::text);
  return v_rows;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.leave_organization (
  organization uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  me uuid := auth.uid();
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  delete from "public"."memberships" where "organization_id" = organization and "user_id" = me;
  if not found then
    raise exception 'Not a member' using errcode = 'P0002', hint = 'ORGANIZATION_NOT_MEMBER';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_member_change"(uuid, uuid, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::uuid, $3::text)', v_hook::oid::regproc)
        using organization, me, 'left';
    end if;
  end;
  perform "better_supabase".emit_event('organization.member_left', jsonb_build_object('organizationId', organization::text, 'userId', me), 'organizations/' || organization::text, (organization)::text, null, 'better-supabase/organizations');
  perform better_supabase.audit_event(
    event_type => 'organization.member_left',
    category => 'membership',
    target_type => 'user',
    record_id => me::text,
    tenant => (organization)::uuid,
    metadata => jsonb_build_object('organizationId', organization::text, 'userId', me)
  );
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.leave_post (
  tenant     uuid,
  user_id    uuid,
  type_id    uuid,
  kind       text,
  amount     numeric,
  period     integer,
  request_id uuid    DEFAULT NULL::uuid,
  note       text    DEFAULT NULL::text,
  key        text    DEFAULT NULL::text,
  to_period  integer DEFAULT NULL::integer
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_unit text;
  v_account uuid;
  v_counter uuid;
  v_amount bigint := round(leave_post.amount * 100);
begin
  select t."unit" into v_unit from "better_supabase"."leave_types" t where t."id" = leave_post.type_id;
  v_account := "better_supabase"."ledger_account_for"(leave_post.tenant, 'leave', 'leave:' || leave_post.type_id::text || ':' || leave_post.user_id::text || ':' || leave_post.period::text, 'Leave', v_unit, 2::smallint,
    'leave-types', leave_post.type_id::text, leave_post.user_id, true, 'leave.read', 'leave',
    jsonb_build_object('userId', leave_post.user_id, 'typeId', leave_post.type_id, 'period', leave_post.period));
  v_counter := case
    when leave_post.to_period is not null then
      "better_supabase"."ledger_account_for"(leave_post.tenant, 'leave', 'leave:' || leave_post.type_id::text || ':' || leave_post.user_id::text || ':' || leave_post.to_period::text, 'Leave', v_unit, 2::smallint,
    'leave-types', leave_post.type_id::text, leave_post.user_id, true, 'leave.read', 'leave',
    jsonb_build_object('userId', leave_post.user_id, 'typeId', leave_post.type_id, 'period', leave_post.to_period))
    else "better_supabase"."ledger_account_for"(leave_post.tenant, 'leave_pool',
      'leave:' || leave_post.type_id::text || case when leave_post.kind = 'taken' then ':taken' else ':pool' end,
      case when leave_post.kind = 'taken' then 'Leave taken' else 'Leave pool' end, v_unit, 2::smallint,
      'leave-types', leave_post.type_id::text, null, true, 'leave.read', 'leave', null)
  end;
  return "better_supabase"."ledger_post"(leave_post.tenant, 'leave.' || leave_post.kind,
    jsonb_build_array(
      jsonb_build_object('account', v_account, 'amount', v_amount),
      jsonb_build_object('account', v_counter, 'amount', -v_amount)),
    case when leave_post.request_id is not null then 'leave-requests' end, leave_post.request_id::text,
    nullif(trim(leave_post.note), ''),
    case when leave_post.key is not null then 'leave:' || leave_post.user_id::text || ':' || leave_post.type_id::text || ':' || leave_post.key end,
    null,
    jsonb_build_object('userId', leave_post.user_id, 'typeId', leave_post.type_id, 'period', leave_post.period, 'kind', leave_post.kind));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.leave_posted (
  tenant  uuid,
  user_id uuid,
  type_id uuid,
  key     text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (select 1 from "better_supabase"."ledger_transactions" r where r."tenant_id" = leave_posted.tenant
    and r."idempotency_key" = 'leave:' || leave_posted.user_id::text || ':' || leave_posted.type_id::text || ':' || leave_posted.key)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.leave_range_close_blockers (
  tenant    uuid,
  starts_on date,
  ends_on   date
)
  RETURNS text[]
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select case when exists (
    select 1 from "better_supabase"."leave_requests" r
    left join "better_supabase"."approval_requests" ap on ap."id" = r."approval_id"
    where r."tenant_id" = leave_range_close_blockers.tenant
      and r."starts_on" between leave_range_close_blockers.starts_on and leave_range_close_blockers.ends_on
      and r."cancelled_at" is null and r."approved_at" is null and ap."status" = 'pending'
  ) then array['pending_requests']::text[] else '{}'::text[] end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.leave_working_days (
  starts_on date,
  ends_on   date
)
  RETURNS integer
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select count(*)::integer
  from generate_series(leave_working_days.starts_on, leave_working_days.ends_on, interval '1 day') d
  where extract(isodow from d)::integer = any (array[1, 2, 3, 4, 5])
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ledger_account_entries (
  account_id uuid,
  before     timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  page_size  integer                  DEFAULT 50
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_account "better_supabase"."ledger_accounts"%rowtype;
  v_rows jsonb;
begin
  select * into v_account from "better_supabase"."ledger_accounts" x where x."id" = ledger_account_entries.account_id;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_account."tenant_id", 'ledger.read'), false) or coalesce(v_account."owner_id" = auth.uid(), false) or (v_account."read_permission" is not null and coalesce(better_supabase.can('tenant', v_account."tenant_id", v_account."read_permission"), false))) then
    raise exception 'ledger account not found' using errcode = 'P0002', hint = 'LEDGER_ACCOUNT_NOT_FOUND';
  end if;
  select coalesce(jsonb_agg(z.item order by z.created desc, z.id desc), '[]'::jsonb) into v_rows
  from (
    select jsonb_build_object('id', y."id", 'accountId', y."account_id", 'amount', y."amount"::text, 'unit', y."unit",
        'transactionId', r."id", 'kind', r."kind", 'referenceType', r."reference_type", 'referenceId', r."reference_id",
        'memo', r."memo", 'reverses', r."reverses", 'metadata', r."metadata", 'effectiveAt', r."effective_at", 'actorId', r."actor_id", 'createdAt', y."created_at") as item,
      y."created_at" as created, y."id" as id
    from "better_supabase"."ledger_entries" y
    join "better_supabase"."ledger_transactions" r on r."id" = y."transaction_id"
    where y."account_id" = v_account."id"
      and (ledger_account_entries.before is null or y."created_at" < ledger_account_entries.before)
    order by y."created_at" desc, y."id" desc
    limit least(greatest(coalesce(ledger_account_entries.page_size, 50), 1), 500)
  ) z;
  return v_rows;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ledger_account_for (
  tenant          uuid,
  kind            text,
  code            text,
  name            text,
  unit            text,
  scale           smallint DEFAULT 0,
  holder_type     text     DEFAULT NULL::text,
  holder_id       text     DEFAULT NULL::text,
  owner_id        uuid     DEFAULT NULL::uuid,
  allow_negative  boolean  DEFAULT false,
  read_permission text     DEFAULT NULL::text,
  managed_by      text     DEFAULT NULL::text,
  metadata        jsonb    DEFAULT NULL::jsonb
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_id uuid;
begin
  select x."id" into v_id from "better_supabase"."ledger_accounts" x
    where x."tenant_id" = ledger_account_for.tenant and x."code" = ledger_account_for.code;
  if found then
    return v_id;
  end if;
  insert into "better_supabase"."ledger_accounts" ("tenant_id", "kind", "code", "name", "unit", "scale", "holder_type", "holder_id", "owner_id", "allow_negative", "read_permission", "managed_by", "metadata")
  values (ledger_account_for.tenant, ledger_account_for.kind, ledger_account_for.code, ledger_account_for.name, ledger_account_for.unit,
    coalesce(ledger_account_for.scale, 0), ledger_account_for.holder_type, ledger_account_for.holder_id, ledger_account_for.owner_id,
    coalesce(ledger_account_for.allow_negative, false), ledger_account_for.read_permission, ledger_account_for.managed_by,
    coalesce(ledger_account_for.metadata, '{}'::jsonb))
  on conflict ("tenant_id", "code") do nothing
  returning "id" into v_id;
  if v_id is null then
    select x."id" into v_id from "better_supabase"."ledger_accounts" x
      where x."tenant_id" = ledger_account_for.tenant and x."code" = ledger_account_for.code;
  end if;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ledger_append_only()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if tg_op = 'DELETE' and current_setting('better_supabase.purge_tenant', true) = to_jsonb(old) ->> tg_argv[0] then
    if coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') and exists (
      select 1 from "better_supabase"."organization_deletions" x
      where x."tenant_id"::text = to_jsonb(old) ->> tg_argv[0]
        and x."cancelled_at" is null and x."purged_at" is null and x."purge_at" <= now()
    ) then
      return old;
    end if;
  end if;
  raise exception 'ledger entries and transactions can''t be changed or deleted; post a reversal' using errcode = '55000', hint = 'LEDGER_APPEND_ONLY';
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ledger_apply_entry()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_available bigint;
begin
  insert into "better_supabase"."ledger_balances" as x ("account_id", "tenant_id", "balance")
  values (new."account_id", new."tenant_id", new."amount")
  on conflict ("account_id") do update set "balance" = x."balance" + excluded."balance", "updated_at" = now()
  returning x."balance" - x."held" into v_available;
  if new."amount" < 0 and v_available < 0 and not exists (
    select 1 from "better_supabase"."ledger_accounts" y where y."id" = new."account_id" and y."allow_negative"
  ) then
    raise exception 'the account doesn''t have enough available' using errcode = '23514', hint = 'LEDGER_INSUFFICIENT';
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ledger_capture (
  hold_id    uuid,
  to_account uuid,
  amount     bigint DEFAULT NULL::bigint,
  kind       text   DEFAULT 'ledger.capture'::text,
  memo       text   DEFAULT NULL::text
)
  RETURNS better_supabase.ledger_holds
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."ledger_holds"%rowtype;
  v_amount bigint;
begin
  select * into v_row from "better_supabase"."ledger_holds" x where x."id" = ledger_capture.hold_id;
  if not found then
    raise exception 'ledger hold not found' using errcode = 'P0002', hint = 'LEDGER_HOLD_NOT_FOUND';
  end if;
  v_amount := coalesce(ledger_capture.amount, v_row."amount");
  if v_amount <= 0 or v_amount > v_row."amount" then
    raise exception 'a capture takes more than zero and at most the held amount' using errcode = '22023', hint = 'LEDGER_LINES_INVALID';
  end if;
  v_row := "better_supabase"."ledger_unhold"(v_row."id", 'captured');
  update "better_supabase"."ledger_holds" x set "transaction_id" = "better_supabase"."ledger_post"(v_row."tenant_id", coalesce(ledger_capture.kind, 'ledger.capture'),
      jsonb_build_array(
        jsonb_build_object('account', v_row."account_id", 'amount', (-v_amount)::text),
        jsonb_build_object('account', ledger_capture.to_account, 'amount', v_amount::text)),
      v_row."reference_type", v_row."reference_id", ledger_capture.memo)
    where x."id" = v_row."id"
    returning * into v_row;
  perform "better_supabase".emit_event('ledger_hold.captured', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'accountId', v_row."account_id", 'amount', v_row."amount"::text, 'status', v_row."status", 'transactionId', v_row."transaction_id"), 'ledger-holds/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/ledger');
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ledger_check_balanced()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if exists (
    select 1 from "better_supabase"."ledger_entries" y where y."transaction_id" = new."transaction_id"
    group by y."unit" having sum(y."amount") <> 0
  ) then
    raise exception 'the entries of a ledger transaction must sum to zero per unit' using errcode = '23514', hint = 'LEDGER_UNBALANCED';
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ledger_hold (
  account_id     uuid,
  amount         bigint,
  reference_type text                     DEFAULT NULL::text,
  reference_id   text                     DEFAULT NULL::text,
  expires_at     timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS better_supabase.ledger_holds
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_account "better_supabase"."ledger_accounts"%rowtype;
  v_balance "better_supabase"."ledger_balances"%rowtype;
  v_row "better_supabase"."ledger_holds"%rowtype;
begin
  select * into v_account from "better_supabase"."ledger_accounts" x where x."id" = ledger_hold.account_id;
  if not found or v_account."closed_at" is not null then
    raise exception 'ledger account not found' using errcode = 'P0002', hint = 'LEDGER_ACCOUNT_NOT_FOUND';
  end if;
  if ledger_hold.amount is null or ledger_hold.amount <= 0 then
    raise exception 'a hold needs an amount greater than zero' using errcode = '22023', hint = 'LEDGER_LINES_INVALID';
  end if;
  insert into "better_supabase"."ledger_balances" ("account_id", "tenant_id") values (v_account."id", v_account."tenant_id")
    on conflict ("account_id") do nothing;
  select * into v_balance from "better_supabase"."ledger_balances" x where x."account_id" = v_account."id" for update;
  if not v_account."allow_negative" and v_balance."balance" - v_balance."held" < ledger_hold.amount then
    raise exception 'the account doesn''t have enough available' using errcode = '23514', hint = 'LEDGER_INSUFFICIENT';
  end if;
  update "better_supabase"."ledger_balances" x set "held" = x."held" + ledger_hold.amount, "updated_at" = now()
    where x."account_id" = v_account."id";
  insert into "better_supabase"."ledger_holds" ("tenant_id", "account_id", "amount", "reference_type", "reference_id", "expires_at", "created_by")
  values (v_account."tenant_id", v_account."id", ledger_hold.amount, ledger_hold.reference_type, ledger_hold.reference_id, ledger_hold.expires_at, auth.uid())
  returning * into v_row;
  perform "better_supabase".emit_event('ledger_hold.placed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'accountId', v_row."account_id", 'amount', v_row."amount"::text, 'status', v_row."status", 'transactionId', v_row."transaction_id"), 'ledger-holds/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/ledger');
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ledger_post (
  tenant          uuid,
  kind            text,
  lines           jsonb,
  reference_type  text                     DEFAULT NULL::text,
  reference_id    text                     DEFAULT NULL::text,
  memo            text                     DEFAULT NULL::text,
  idempotency_key text                     DEFAULT NULL::text,
  effective_at    timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  metadata        jsonb                    DEFAULT NULL::jsonb,
  reverses        uuid                     DEFAULT NULL::uuid
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_id uuid;
  v_row "better_supabase"."ledger_transactions"%rowtype;
begin
  if ledger_post.idempotency_key is not null then
    select x."id" into v_id from "better_supabase"."ledger_transactions" x
      where x."tenant_id" = ledger_post.tenant and x."idempotency_key" = ledger_post.idempotency_key;
    if found then
      return v_id;
    end if;
  end if;
  if ledger_post.kind is null or ledger_post.kind !~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*$' then
    raise exception 'kind must be lowercase words joined by dots, such as credit.grant' using errcode = '22023', hint = 'LEDGER_KIND_INVALID';
  end if;
  if jsonb_typeof(ledger_post.lines) is distinct from 'array' or jsonb_array_length(ledger_post.lines) < 2 then
    raise exception 'a transaction needs at least two lines' using errcode = '22023', hint = 'LEDGER_LINES_INVALID';
  end if;
  if exists (
    select 1 from jsonb_array_elements(ledger_post.lines) l
    where jsonb_typeof(l.value) is distinct from 'object'
      or coalesce(l.value ->> 'account', '') !~ '^[0-9a-fA-F-]{36}$'
      or coalesce(l.value ->> 'amount', '') !~ '^-?[0-9]{1,18}$'
      or (l.value ->> 'amount')::bigint = 0
  ) then
    raise exception 'every line needs an account id and a non-zero integer amount' using errcode = '22023', hint = 'LEDGER_LINES_INVALID';
  end if;
  if exists (
    select 1 from jsonb_array_elements(ledger_post.lines) l
    left join "better_supabase"."ledger_accounts" x on x."id" = (l.value ->> 'account')::uuid
      and x."tenant_id" = ledger_post.tenant and x."closed_at" is null
    where x."id" is null
  ) then
    raise exception 'an account of the transaction doesn''t exist here or is closed' using errcode = 'P0002', hint = 'LEDGER_ACCOUNT_NOT_FOUND';
  end if;
  if exists (
    select 1 from jsonb_array_elements(ledger_post.lines) l
    join "better_supabase"."ledger_accounts" x on x."id" = (l.value ->> 'account')::uuid
    group by x."unit" having sum((l.value ->> 'amount')::bigint) <> 0
  ) then
    raise exception 'the lines of a ledger transaction must sum to zero per unit' using errcode = '23514', hint = 'LEDGER_UNBALANCED';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_ledger_transaction_post"(uuid, text, jsonb)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::jsonb)', v_hook::oid::regproc)
        using ledger_post.tenant, ledger_post.kind, ledger_post.lines;
    end if;
  end;
  insert into "better_supabase"."ledger_transactions" ("tenant_id", "kind", "reference_type", "reference_id", "memo", "idempotency_key", "reverses", "metadata", "effective_at", "actor_id")
  values (ledger_post.tenant, ledger_post.kind, ledger_post.reference_type, ledger_post.reference_id, nullif(trim(ledger_post.memo), ''),
    ledger_post.idempotency_key, ledger_post.reverses, coalesce(ledger_post.metadata, '{}'::jsonb), coalesce(ledger_post.effective_at, now()), auth.uid())
  returning * into v_row;
  insert into "better_supabase"."ledger_entries" ("tenant_id", "transaction_id", "account_id", "amount", "unit", "effective_at")
  select ledger_post.tenant, v_row."id", x."id", (l.value ->> 'amount')::bigint, x."unit", v_row."effective_at"
  from jsonb_array_elements(ledger_post.lines) with ordinality as l(value, n)
  join "better_supabase"."ledger_accounts" x on x."id" = (l.value ->> 'account')::uuid
  order by l.n;
  perform "better_supabase".emit_event('ledger_transaction.posted', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'kind', v_row."kind", 'referenceType', v_row."reference_type", 'referenceId', v_row."reference_id", 'reverses', v_row."reverses", 'entries', (select count(*)::integer from "better_supabase"."ledger_entries" y where y."transaction_id" = v_row."id")), 'ledger-transactions/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/ledger');
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_ledger_transaction_post"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return v_row."id";
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ledger_read_grants()
  RETURNS TABLE (
    tenant     uuid,
    permission text
  )
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return query
  select p.tenant, p.permission from (
    select distinct x."tenant_id" as tenant, x."read_permission" as permission
    from "better_supabase"."ledger_accounts" x
    where x."read_permission" is not null and x."tenant_id" in (select better_supabase.member_organization_ids())
  ) p
  where coalesce(better_supabase.can('tenant', p.tenant, p.permission), false);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ledger_release (
  hold_id uuid
)
  RETURNS better_supabase.ledger_holds
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."ledger_holds"%rowtype;
begin
  v_row := "better_supabase"."ledger_unhold"(ledger_release.hold_id, 'released');
  perform "better_supabase".emit_event('ledger_hold.released', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'accountId', v_row."account_id", 'amount', v_row."amount"::text, 'status', v_row."status", 'transactionId', v_row."transaction_id"), 'ledger-holds/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/ledger');
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.ledger_unhold (
  hold_id uuid,
  status  text
)
  RETURNS better_supabase.ledger_holds
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."ledger_holds"%rowtype;
begin
  select * into v_row from "better_supabase"."ledger_holds" x where x."id" = ledger_unhold.hold_id for update;
  if not found then
    raise exception 'ledger hold not found' using errcode = 'P0002', hint = 'LEDGER_HOLD_NOT_FOUND';
  end if;
  if v_row."status" <> 'active' then
    raise exception 'this hold is no longer active' using errcode = '55000', hint = 'LEDGER_HOLD_CLOSED';
  end if;
  update "better_supabase"."ledger_balances" x set "held" = x."held" - v_row."amount", "updated_at" = now()
    where x."account_id" = v_row."account_id";
  update "better_supabase"."ledger_holds" x set "status" = ledger_unhold.status, "updated_at" = now()
    where x."id" = v_row."id"
    returning * into v_row;
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.legal_entities_disable_check (
  tenant uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_collisions jsonb;
  v_defaults jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', legal_entities_disable_check.tenant, 'legal_entities.manage'), false)) then
    raise exception 'not allowed to manage legal entities' using errcode = '42501', hint = 'LEGAL_ENTITY_FORBIDDEN';
  end if;
  v_collisions := coalesce((select jsonb_agg(jsonb_build_object('kind', q.kind, 'column', q."column", 'value', q.value, 'documents', q.documents, 'legalEntityIds', q.entities) order by q.kind, q."column", q.value) from (
    select 'invoices' as kind, 'number' as "column", x."number"::text as value,
      count(*) as documents, jsonb_agg(distinct coalesce(x.legal_entity_id, (select d."id" from "better_supabase"."legal_entities" d where d."tenant_id" = x."tenant_id" and d."is_default"))) as entities
    from "better_supabase"."invoices" x
    where x."tenant_id" = legal_entities_disable_check.tenant and x."number" is not null
    group by x."number", x."direction", x."kind"
    having count(*) > 1
    union all
    select 'invoices' as kind, 'identifier' as "column", x."identifier"::text as value,
      count(*) as documents, jsonb_agg(distinct coalesce(x.legal_entity_id, (select d."id" from "better_supabase"."legal_entities" d where d."tenant_id" = x."tenant_id" and d."is_default"))) as entities
    from "better_supabase"."invoices" x
    where x."tenant_id" = legal_entities_disable_check.tenant and x."identifier" is not null
    group by x."identifier", x."direction", x."kind"
    having count(*) > 1
    union all
    select 'quotes' as kind, 'number' as "column", x."number"::text as value,
      count(*) as documents, jsonb_agg(distinct coalesce(x.legal_entity_id, (select d."id" from "better_supabase"."legal_entities" d where d."tenant_id" = x."tenant_id" and d."is_default"))) as entities
    from "better_supabase"."quotes" x
    where x."tenant_id" = legal_entities_disable_check.tenant and x."number" is not null
    group by x."number", x."revision"
    having count(*) > 1
    union all
    select 'orders' as kind, 'number' as "column", x."number"::text as value,
      count(*) as documents, jsonb_agg(distinct coalesce(x.legal_entity_id, (select d."id" from "better_supabase"."legal_entities" d where d."tenant_id" = x."tenant_id" and d."is_default"))) as entities
    from "better_supabase"."orders" x
    where x."tenant_id" = legal_entities_disable_check.tenant and x."number" is not null
    group by x."number"
    having count(*) > 1
    union all
    select 'orders' as kind, 'invoiceNumber' as "column", x."invoice_number"::text as value,
      count(*) as documents, jsonb_agg(distinct coalesce(x.legal_entity_id, (select d."id" from "better_supabase"."legal_entities" d where d."tenant_id" = x."tenant_id" and d."is_default"))) as entities
    from "better_supabase"."orders" x
    where x."tenant_id" = legal_entities_disable_check.tenant and x."invoice_number" is not null
    group by x."invoice_number"
    having count(*) > 1
  ) q), '[]'::jsonb);
  v_defaults := coalesce((select jsonb_agg(jsonb_build_object('kind', q.kind, 'column', q."column", 'value', q.value, 'documents', q.documents) order by q.kind, q."column", q.value) from (
    select 'invoices' as kind, 'number' as "column", x."number"::text as value, count(*) as documents
    from "better_supabase"."invoices" x
    where x."tenant_id" = legal_entities_disable_check.tenant and x."number" is not null
      and (x.legal_entity_id is null or x.legal_entity_id = (select d."id" from "better_supabase"."legal_entities" d where d."tenant_id" = x."tenant_id" and d."is_default"))
    group by x."number", x."direction", x."kind"
    having count(*) > 1
    union all
    select 'invoices' as kind, 'identifier' as "column", x."identifier"::text as value, count(*) as documents
    from "better_supabase"."invoices" x
    where x."tenant_id" = legal_entities_disable_check.tenant and x."identifier" is not null
      and (x.legal_entity_id is null or x.legal_entity_id = (select d."id" from "better_supabase"."legal_entities" d where d."tenant_id" = x."tenant_id" and d."is_default"))
    group by x."identifier", x."direction", x."kind"
    having count(*) > 1
    union all
    select 'quotes' as kind, 'number' as "column", x."number"::text as value, count(*) as documents
    from "better_supabase"."quotes" x
    where x."tenant_id" = legal_entities_disable_check.tenant and x."number" is not null
      and (x.legal_entity_id is null or x.legal_entity_id = (select d."id" from "better_supabase"."legal_entities" d where d."tenant_id" = x."tenant_id" and d."is_default"))
    group by x."number", x."revision"
    having count(*) > 1
    union all
    select 'orders' as kind, 'number' as "column", x."number"::text as value, count(*) as documents
    from "better_supabase"."orders" x
    where x."tenant_id" = legal_entities_disable_check.tenant and x."number" is not null
      and (x.legal_entity_id is null or x.legal_entity_id = (select d."id" from "better_supabase"."legal_entities" d where d."tenant_id" = x."tenant_id" and d."is_default"))
    group by x."number"
    having count(*) > 1
    union all
    select 'orders' as kind, 'invoiceNumber' as "column", x."invoice_number"::text as value, count(*) as documents
    from "better_supabase"."orders" x
    where x."tenant_id" = legal_entities_disable_check.tenant and x."invoice_number" is not null
      and (x.legal_entity_id is null or x.legal_entity_id = (select d."id" from "better_supabase"."legal_entities" d where d."tenant_id" = x."tenant_id" and d."is_default"))
    group by x."invoice_number"
    having count(*) > 1
  ) q), '[]'::jsonb);
  return jsonb_build_object('ok', jsonb_array_length(v_collisions) = 0, 'collisions', v_collisions, 'defaultCollisions', v_defaults);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.legal_entity_default_guard()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_number text;
begin
  select x."number"::text into v_number
  from "better_supabase"."invoices" x
  where x."tenant_id" = new."tenant_id" and x."number" is not null
    and (x.legal_entity_id is null or x.legal_entity_id = new."id")
  group by x."number", x."direction", x."kind" having count(*) > 1
  limit 1;
  if v_number is not null then
    raise exception 'can not make this legal entity the default: % % exists for it and for documents without a legal entity', 'invoices', v_number
      using errcode = '23505', hint = 'LEGAL_ENTITY_DEFAULT_NUMBER_CONFLICT';
  end if;
  select x."identifier"::text into v_number
  from "better_supabase"."invoices" x
  where x."tenant_id" = new."tenant_id" and x."identifier" is not null
    and (x.legal_entity_id is null or x.legal_entity_id = new."id")
  group by x."identifier", x."direction", x."kind" having count(*) > 1
  limit 1;
  if v_number is not null then
    raise exception 'can not make this legal entity the default: % % exists for it and for documents without a legal entity', 'invoices', v_number
      using errcode = '23505', hint = 'LEGAL_ENTITY_DEFAULT_NUMBER_CONFLICT';
  end if;
  select x."number"::text into v_number
  from "better_supabase"."quotes" x
  where x."tenant_id" = new."tenant_id" and x."number" is not null
    and (x.legal_entity_id is null or x.legal_entity_id = new."id")
  group by x."number", x."revision" having count(*) > 1
  limit 1;
  if v_number is not null then
    raise exception 'can not make this legal entity the default: % % exists for it and for documents without a legal entity', 'quotes', v_number
      using errcode = '23505', hint = 'LEGAL_ENTITY_DEFAULT_NUMBER_CONFLICT';
  end if;
  select x."number"::text into v_number
  from "better_supabase"."orders" x
  where x."tenant_id" = new."tenant_id" and x."number" is not null
    and (x.legal_entity_id is null or x.legal_entity_id = new."id")
  group by x."number" having count(*) > 1
  limit 1;
  if v_number is not null then
    raise exception 'can not make this legal entity the default: % % exists for it and for documents without a legal entity', 'orders', v_number
      using errcode = '23505', hint = 'LEGAL_ENTITY_DEFAULT_NUMBER_CONFLICT';
  end if;
  select x."invoice_number"::text into v_number
  from "better_supabase"."orders" x
  where x."tenant_id" = new."tenant_id" and x."invoice_number" is not null
    and (x.legal_entity_id is null or x.legal_entity_id = new."id")
  group by x."invoice_number" having count(*) > 1
  limit 1;
  if v_number is not null then
    raise exception 'can not make this legal entity the default: % % exists for it and for documents without a legal entity', 'orders', v_number
      using errcode = '23505', hint = 'LEGAL_ENTITY_DEFAULT_NUMBER_CONFLICT';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.legal_entity_fiscal (
  fiscal jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
declare
  v_month text;
  v_period text;
begin
  if legal_entity_fiscal.fiscal is null or jsonb_typeof(legal_entity_fiscal.fiscal) <> 'object' then
    raise exception 'fiscal must be an object' using errcode = '22023', hint = 'LEGAL_ENTITY_INVALID';
  end if;
  v_month := coalesce(legal_entity_fiscal.fiscal ->> 'fiscalYearStartMonth', '1');
  v_period := coalesce(legal_entity_fiscal.fiscal ->> 'taxPeriod', 'quarterly');
  if v_month !~ '^[0-9]{1,2}$' or v_month::integer < 1 or v_month::integer > 12 then
    raise exception 'fiscalYearStartMonth must be a month from 1 to 12' using errcode = '22023', hint = 'LEGAL_ENTITY_INVALID';
  end if;
  if v_period not in ('monthly', 'quarterly') then
    raise exception 'taxPeriod must be monthly or quarterly' using errcode = '22023', hint = 'LEGAL_ENTITY_INVALID';
  end if;
  return jsonb_build_object('fiscalYearStartMonth', v_month::integer, 'taxPeriod', v_period);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.legal_entity_of (
  tenant uuid,
  id     uuid DEFAULT NULL::uuid
)
  RETURNS uuid
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  v_id uuid;
begin
  if legal_entity_of.id is not null then
    select x."id" into v_id from "better_supabase"."legal_entities" x
      where x."id" = legal_entity_of.id and x."tenant_id" = legal_entity_of.tenant;
    if v_id is null then
      raise exception 'legal entity not found' using errcode = 'P0002', hint = 'LEGAL_ENTITY_NOT_FOUND';
    end if;
    return v_id;
  end if;
  select x."id" into v_id from "better_supabase"."legal_entities" x
    where x."tenant_id" = legal_entity_of.tenant and x."is_default";
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.lifecycle_graph (
  version_id uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  with recursive g as (
    select (select v."graph" from "better_supabase"."workflow_versions" v where v."id" = lifecycle_graph.version_id) as graph
  ),
  nodes as (
    select n.value ->> 'id' as id, n.value ->> 'kind' as kind,
      case when jsonb_typeof(n.value -> 'config' -> 'stage') = 'string' then n.value -> 'config' ->> 'stage' end as stage,
      case when jsonb_typeof(n.value -> 'config' -> 'returnsTo') = 'array' then n.value -> 'config' -> 'returnsTo' else '[]'::jsonb end as back,
      n.ord
    from g, jsonb_array_elements(case when jsonb_typeof(g.graph -> 'nodes') = 'array' then g.graph -> 'nodes' else '[]'::jsonb end) with ordinality n (value, ord)
  ),
  edges as (
    select e.value ->> 'source' as source, e.value ->> 'target' as target
    from g, jsonb_array_elements(case when jsonb_typeof(g.graph -> 'edges') = 'array' then g.graph -> 'edges' else '[]'::jsonb end) e (value)
  ),
  walk (origin, node, depth) as (
    select o.id, e.target, 1
    from nodes o join edges e on e.source = o.id
    where o.stage is not null or o.kind = 'trigger'
    union
    select w.origin, e.target, w.depth + 1
    from walk w
    join nodes m on m.id = w.node and m.stage is null
    join edges e on e.source = w.node
    where w.depth < 100
  ),
  reached as (
    select o.kind as origin_kind, o.stage as from_stage, t.stage as to_stage, min(w.depth) as depth, min(t.ord) as ord
    from walk w
    join nodes o on o.id = w.origin
    join nodes t on t.id = w.node
    where t.stage is not null
    group by o.kind, o.stage, t.stage
  ),
  stages as (
    select n.stage, min(n.ord) as ord from nodes n where n.stage is not null group by n.stage
  ),
  moves as (
    select r.from_stage, r.to_stage from reached r
    where r.from_stage is not null and r.from_stage <> r.to_stage
    union
    select n.stage, b.value #>> '{}'
    from nodes n, jsonb_array_elements(n.back) b (value)
    where n.stage is not null and jsonb_typeof(b.value) = 'string'
      and b.value #>> '{}' <> n.stage
      and exists (select 1 from stages s where s.stage = b.value #>> '{}')
  )
  select jsonb_build_object(
    'initial', coalesce(
      (select n.stage from nodes n where n.kind = 'trigger' and n.stage is not null order by n.ord limit 1),
      (select r.to_stage from reached r where r.origin_kind = 'trigger' and r.from_stage is null order by r.depth, r.ord limit 1),
      (select s.stage from stages s order by s.ord limit 1)),
    'order', coalesce((select jsonb_agg(s.stage order by s.ord) from stages s), '[]'::jsonb),
    'transitions', coalesce((select jsonb_object_agg(m.from_stage, m.targets)
      from (select x.from_stage, jsonb_agg(distinct x.to_stage order by x.to_stage) as targets from moves x group by x.from_stage) m), '{}'::jsonb))
  from g
  where g.graph is not null
$function$;

CREATE OR REPLACE FUNCTION better_supabase.link (
  tenant      uuid,
  kind        text,
  source_type text,
  source_id   text,
  target_type text,
  target_id   text,
  data        jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_kind text;
  v_inverted boolean;
  v_acyclic boolean;
  v_single boolean;
  v_symmetric boolean;
  v_source_type text;
  v_source_id text;
  v_target_type text;
  v_target_id text;
  v_id uuid;
  v_created boolean := false;
  v_previous jsonb;
  v_replaced jsonb;
  v_old "better_supabase"."relations";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', link.tenant, 'relations.manage'), false)) then
    raise exception 'not allowed to link records' using errcode = '42501', hint = 'RELATION_FORBIDDEN';
  end if;
  if link.data is not null and jsonb_typeof(link.data) <> 'object' then
    raise exception 'data must be an object' using errcode = '22023', hint = 'RELATION_INVALID';
  end if;
  if link.source_type = link.target_type and link.source_id = link.target_id then
    raise exception 'a record can''t link to itself' using errcode = '22023', hint = 'RELATION_SELF';
  end if;

  select k.canonical, k.inverted, k.acyclic, k.single, k.both_ways
    into v_kind, v_inverted, v_acyclic, v_single, v_symmetric
    from (values ('blocks', 'blocks', false, true, false, false, 'blocked_by'), ('blocked_by', 'blocks', true, true, false, false, 'blocks'), ('parent', 'parent', false, true, true, false, 'children'), ('children', 'parent', true, true, true, false, 'parent'), ('relates', 'relates', false, false, false, true, 'relates'), ('created_from', 'created_from', false, true, true, false, 'converted_to'), ('converted_to', 'created_from', true, true, true, false, 'created_from'), ('variant_of', 'variant_of', false, true, true, false, 'variants'), ('variants', 'variant_of', true, true, true, false, 'variant_of'), ('represents', 'represents', false, false, false, false, 'represented_by'), ('represented_by', 'represents', true, false, false, false, 'represents'), ('mitigated_by', 'mitigated_by', false, false, false, false, 'mitigates'), ('mitigates', 'mitigated_by', true, false, false, false, 'mitigated_by'), ('materialized_as', 'materialized_as', false, false, false, false, 'materializes'), ('materializes', 'materialized_as', true, false, false, false, 'materialized_as'), ('affects', 'affects', false, false, false, false, 'affected_by'), ('affected_by', 'affects', true, false, false, false, 'affects'), ('assesses', 'assesses', false, false, false, false, 'assessed_by'), ('assessed_by', 'assesses', true, false, false, false, 'assesses')) as k(name, canonical, inverted, acyclic, single, both_ways, opposite) where k.name = link.kind;
  if v_kind is null then
    raise exception 'unknown relation kind' using errcode = '22023', hint = 'RELATION_KIND_UNKNOWN';
  end if;
  if v_inverted then
    v_source_type := link.target_type; v_source_id := link.target_id;
    v_target_type := link.source_type; v_target_id := link.source_id;
  else
    v_source_type := link.source_type; v_source_id := link.source_id;
    v_target_type := link.target_type; v_target_id := link.target_id;
  end if;
  if v_symmetric and (v_source_type, v_source_id) > (v_target_type, v_target_id) then
    select v_target_type, v_target_id, v_source_type, v_source_id
      into v_source_type, v_source_id, v_target_type, v_target_id;
  end if;
  if v_kind = 'variant_of' and not (v_source_type in ('drive_node') and v_target_type in ('drive_node')) then
    raise exception 'this kind of link doesn''t accept these record types' using errcode = '22023', hint = 'RELATION_TYPE_NOT_ALLOWED';
  end if;
  if v_kind = 'represents' and not (v_source_type in ('person') and v_target_type in ('customer', 'drive_node')) then
    raise exception 'this kind of link doesn''t accept these record types' using errcode = '22023', hint = 'RELATION_TYPE_NOT_ALLOWED';
  end if;
  if v_kind = 'mitigated_by' and not (v_source_type in ('risk') and v_target_type in ('control', 'work_item', 'drive_node')) then
    raise exception 'this kind of link doesn''t accept these record types' using errcode = '22023', hint = 'RELATION_TYPE_NOT_ALLOWED';
  end if;
  if v_kind = 'materialized_as' and not (v_source_type in ('risk') and v_target_type in ('case')) then
    raise exception 'this kind of link doesn''t accept these record types' using errcode = '22023', hint = 'RELATION_TYPE_NOT_ALLOWED';
  end if;
  if v_kind = 'affects' and not (v_source_type in ('case')) then
    raise exception 'this kind of link doesn''t accept these record types' using errcode = '22023', hint = 'RELATION_TYPE_NOT_ALLOWED';
  end if;
  if v_kind = 'assesses' and not (v_source_type in ('inspection') and v_target_type in ('control')) then
    raise exception 'this kind of link doesn''t accept these record types' using errcode = '22023', hint = 'RELATION_TYPE_NOT_ALLOWED';
  end if;
  if not (case link.source_type
    when 'message' then exists (select 1 from "better_supabase"."messages" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'messages.read'), false)
    when 'conversation' then exists (select 1 from "better_supabase"."conversations" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'messages.read'), false)
    when 'channel' then exists (select 1 from "better_supabase"."channels" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'messages.read'), false)
    when 'company' then exists (select 1 from "better_supabase"."companies" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'contacts.read'), false)
    when 'person' then exists (select 1 from "better_supabase"."people" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'contacts.read'), false)
    when 'deal' then exists (select 1 from "better_supabase"."deals" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'deals.read'), false)
    when 'course' then exists (select 1 from "better_supabase"."courses" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'courses.read'), false)
    when 'post' then exists (select 1 from "better_supabase"."posts" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'posts.read'), false)
    when 'activity' then exists (select 1 from "better_supabase"."activities" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'activities.read'), false)
    when 'quote' then exists (select 1 from "better_supabase"."quotes" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'quotes.read'), false)
    when 'work_item' then exists (select 1 from "better_supabase"."work_items" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'tasks.read'), false)
    when 'employee' then exists (select 1 from "better_supabase"."employees" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'employees.read'), false)
    when 'ledger_account' then exists (select 1 from "better_supabase"."ledger_accounts" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'ledger.read'), false)
    when 'invoice' then exists (select 1 from "better_supabase"."invoices" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'invoices.read'), false)
    when 'product' then exists (select 1 from "better_supabase"."products" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'catalog.read'), false)
    when 'product_variant' then exists (select 1 from "better_supabase"."product_variants" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'catalog.read'), false)
    when 'rfq' then exists (select 1 from "better_supabase"."rfqs" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'rfqs.read'), false)
    when 'till' then exists (select 1 from "better_supabase"."tills" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'tills.read'), false)
    when 'order' then exists (select 1 from "better_supabase"."orders" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'orders.read'), false)
    when 'calendar_event' then exists (select 1 from "better_supabase"."calendar_events" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'calendar.read'), false)
    when 'booking' then exists (select 1 from "better_supabase"."bookings" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'bookings.read'), false)
    when 'asset' then exists (select 1 from "better_supabase"."assets" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'assets.read'), false)
    when 'asset_location' then exists (select 1 from "better_supabase"."asset_locations" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'assets.read'), false)
    when 'lease' then exists (select 1 from "better_supabase"."leases" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'leases.read'), false)
    when 'expense_report' then exists (select 1 from "better_supabase"."expense_reports" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'expenses.read'), false)
    when 'expense_line' then exists (select 1 from "better_supabase"."expense_lines" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'expenses.read'), false)
    when 'donation_fund' then exists (select 1 from "better_supabase"."donation_funds" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'donations.read'), false)
    when 'warranty_claim' then exists (select 1 from "better_supabase"."warranty_claims" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'warranty.read'), false)
    when 'work_order' then exists (select 1 from "better_supabase"."work_orders" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'dispatch.read'), false)
    when 'shipment' then exists (select 1 from "better_supabase"."shipments" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'shipments.read'), false)
    when 'contract' then exists (select 1 from "better_supabase"."contracts" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'contracts.read'), false)
    when 'control' then exists (select 1 from "better_supabase"."controls" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'compliance.read'), false)
    when 'compliance_policy' then exists (select 1 from "better_supabase"."compliance_policies" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'compliance.read'), false)
    when 'qualification_type' then exists (select 1 from "better_supabase"."qualification_types" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'qualifications.read'), false)
    when 'risk' then exists (select 1 from "better_supabase"."risks" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'risks.read'), false)
    when 'case' then exists (select 1 from "better_supabase"."cases" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'cases.read'), false)
    when 'inspection' then exists (select 1 from "better_supabase"."inspections" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'inspections.read'), false)
    when 'inspection_program' then exists (select 1 from "better_supabase"."inspection_programs" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'inspections.read'), false)
    when 'inspection_finding' then exists (select 1 from "better_supabase"."inspection_findings" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'inspections.read'), false)
    when 'form' then exists (select 1 from "better_supabase"."forms" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'forms.read'), false)
    when 'meeting' then exists (select 1 from "better_supabase"."meetings" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'meetings.read'), false)
    when 'meeting_decision' then exists (select 1 from "better_supabase"."meeting_decisions" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'meetings.read'), false)
    when 'maintenance_plan' then exists (select 1 from "better_supabase"."maintenance_plans" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'maintenance.read'), false)
    when 'dam_usage_right' then exists (select 1 from "better_supabase"."dam_usage_rights" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'dam.read'), false)
    when 'lims_sample' then exists (select 1 from "better_supabase"."lims_samples" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'lims.read'), false)
    when 'tax_code' then exists (select 1 from "better_supabase"."tax_codes" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'tax.read'), false)
    when 'production_order' then exists (select 1 from "better_supabase"."production_orders" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'manufacturing.read'), false)
    when 'work_center' then exists (select 1 from "better_supabase"."work_centers" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'manufacturing.read'), false)
    when 'bank_account' then exists (select 1 from "better_supabase"."bank_accounts" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'banking.read'), false)
    when 'care_plan' then exists (select 1 from "better_supabase"."care_plans" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'care_plans.read'), false)
    when 'incident' then exists (select 1 from "better_supabase"."incidents" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'incidents.read'), false)
    when 'content_entry' then exists (select 1 from "better_supabase"."content_entries" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'content.read'), false)
    when 'document' then exists (select 1 from "better_supabase"."documents" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'documents.read'), false)
    when 'customer' then exists (select 1 from "public"."customers" s where s."id" = (link.source_id)::uuid and s."organization_id" = link.tenant) and coalesce(better_supabase.can('tenant', link.tenant, 'customers.read'), false)
    when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = (link.source_id)::uuid and s."tenant_id" = link.tenant and (coalesce(better_supabase.can('tenant', link.tenant, 'drive.read'), false) and coalesce("better_supabase"."drive_node_readable"(s."id"), false)))
