CREATE OR REPLACE FUNCTION better_supabase.list_bank_statements (
  account_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_account "better_supabase"."bank_accounts"%rowtype;
begin
  select * into v_account from "better_supabase"."bank_accounts" x where x."id" = list_bank_statements.account_id;
  if not found then
    raise exception 'no such bank account' using errcode = 'P0002', hint = 'BANK_ACCOUNT_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_account."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_account."tenant_id", 'banking.read'), false))) then
    raise exception 'not allowed to do this with bank accounts' using errcode = '42501', hint = 'BANKING_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'accountId', x."account_id", 'reference', x."reference", 'fromOn', x."from_on", 'untilOn', x."until_on", 'openingBalance', x."opening_balance"::text, 'closingBalance', x."closing_balance"::text, 'currency', (select z."currency" from "better_supabase"."bank_accounts" z where z."id" = x."account_id"), 'format', x."format", 'attachmentId', x."attachment_id", 'importedBy', x."imported_by", 'createdAt', x."created_at") order by x."until_on" desc nulls last, x."created_at" desc)
    from "better_supabase"."bank_statements" x where x."account_id" = v_account."id"
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_bank_transactions (
  account_id uuid,
  filter     jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_account "better_supabase"."bank_accounts"%rowtype;
  v_filter jsonb := coalesce(list_bank_transactions.filter, '{}'::jsonb);
begin
  select * into v_account from "better_supabase"."bank_accounts" x where x."id" = list_bank_transactions.account_id;
  if not found then
    raise exception 'no such bank account' using errcode = 'P0002', hint = 'BANK_ACCOUNT_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_account."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_account."tenant_id", 'banking.read'), false))) then
    raise exception 'not allowed to do this with bank accounts' using errcode = '42501', hint = 'BANKING_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'accountId', x."account_id", 'statementId', x."statement_id", 'bookedOn', x."booked_on", 'valueOn', x."value_on", 'amount', x."amount"::text, 'currency', x."currency", 'counterpartyName', x."counterparty_name", 'counterpartyIban', x."counterparty_iban", 'remittance', x."remittance", 'structuredReference', x."structured_reference", 'endToEndId', x."end_to_end_id", 'externalId', x."external_id", 'status', x."status", 'ruleId', x."rule_id", 'matchedAt', x."matched_at", 'matchedBy', x."matched_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at", 'matches', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'transactionId', y."transaction_id", 'targetType', y."target_type", 'targetId', y."target_id", 'amount', y."amount"::text, 'createdBy', y."created_by", 'createdAt', y."created_at") order by y."created_at", y."id") from "better_supabase"."bank_matches" y where y."transaction_id" = x."id"), '[]'::jsonb)) order by x."booked_on" desc, x."created_at" desc, x."id")
    from (
      select * from "better_supabase"."bank_transactions" y
      where y."account_id" = v_account."id"
        and (v_filter ->> 'status' is null or y."status" = v_filter ->> 'status')
        and (v_filter ->> 'since' is null or y."booked_on" >= (v_filter ->> 'since')::date)
        and (v_filter ->> 'until' is null or y."booked_on" <= (v_filter ->> 'until')::date)
      order by y."booked_on" desc, y."created_at" desc, y."id"
      limit least(greatest(coalesce((v_filter ->> 'limit')::integer, 100), 1), 500)
      offset greatest(coalesce((v_filter ->> 'offset')::integer, 0), 0)
    ) x
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_bans (
  tenant    uuid,
  active    boolean DEFAULT true,
  page_size integer DEFAULT 50
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_rows jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', list_bans.tenant, 'moderation.read'), false)) then
    raise exception 'not allowed to read bans' using errcode = '42501', hint = 'MODERATION_FORBIDDEN';
  end if;
  select coalesce(jsonb_agg(q.item order by q.created desc, q.id desc), '[]'::jsonb) into v_rows
  from (
    select jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'userId', x."user_id", 'reason', x."reason", 'bannedBy', x."banned_by", 'expiresAt', x."expires_at", 'liftedBy', x."lifted_by", 'liftedAt', x."lifted_at", 'createdAt', x."created_at") as item, x."created_at" as created, x."id" as id
    from "better_supabase"."moderation_bans" x
    where x."tenant_id" = list_bans.tenant
      and (not coalesce(list_bans.active, false) or (x."lifted_at" is null and (x."expires_at" is null or x."expires_at" > now())))
    order by x."created_at" desc, x."id" desc
    limit least(greatest(coalesce(list_bans.page_size, 50), 1), 200)
  ) q;
  return v_rows;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_bin_slots (
  tenant  uuid,
  filters jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_location uuid;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (list_bin_slots.tenant is not null and coalesce(better_supabase.can('tenant', list_bin_slots.tenant, 'warehouse.read'), false))) then
    raise exception 'not allowed to read bin slots' using errcode = '42501', hint = 'WAREHOUSE_FORBIDDEN';
  end if;
  begin
    v_location := (list_bin_slots.filters ->> 'locationId')::uuid;
  exception when invalid_text_representation then
    raise exception 'locationId is a uuid' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end;
  if v_location is null then
    raise exception 'filters needs a locationId' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('binId', y.bin, 'code', y.code, 'locationId', v_location, 'hold', y.hold,
      'active', y.active, 'walkRank', y.walk_rank, 'capacity', y.capacity::text, 'used', y.used::text)
      order by y.walk_rank nulls last, y.code)
    from (
      select x."id" as bin, x."code" as code, x."hold" as hold, x."active" as active,
        sl."walk_rank" as walk_rank, sl."capacity" as capacity,
        coalesce((
          select sum(c."on_hand" * coalesce(sz."size", 1))
          from "better_supabase"."stock_buckets" c left join "better_supabase"."variant_sizes" sz on sz."variant_id" = c."variant_id"
          where c."bin_id" = x."id"
        ), 0) as used
      from "better_supabase"."stock_bins" x left join "better_supabase"."bin_slots" sl on sl."bin_id" = x."id"
      where x."tenant_id" = list_bin_slots.tenant and x."location_id" = v_location
      order by sl."walk_rank" nulls last, x."code"
      limit 1000
    ) y
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_boms (
  tenant  uuid,
  variant uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (list_boms.tenant is not null and coalesce(better_supabase.can('tenant', list_boms.tenant, 'manufacturing.read'), false))) then
    raise exception 'not allowed to read bills of materials' using errcode = '42501', hint = 'MANUFACTURING_FORBIDDEN';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'variantId', x."variant_id", 'version', x."version", 'status', x."status", 'quantity', x."quantity"::text, 'note', x."note", 'activatedAt', x."activated_at", 'createdAt', x."created_at", 'updatedAt', x."updated_at") order by x."variant_id", x."version" desc)
    from "better_supabase"."boms" x where x."tenant_id" = list_boms.tenant
      and (list_boms.variant is null or x."variant_id" = list_boms.variant)), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_booking_resources (
  tenant           uuid,
  include_inactive boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', rs."id", 'name', rs."name", 'kind', rs."kind",
    'capacity', rs."capacity", 'tz', rs."tz", 'active', rs."active",
    'calendarId', rs."calendar_id",
    'hostUserId', rs."host_id"
  ) order by rs."name", rs."id"), '[]'::jsonb)
  from "better_supabase"."booking_resources" rs
  where rs."tenant_id" = list_booking_resources.tenant
    and (list_booking_resources.include_inactive or rs."active")
$function$;

