CREATE OR REPLACE FUNCTION better_supabase.list_case_kinds (
  tenant           uuid,
  include_archived boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (list_case_kinds.tenant is not null and coalesce(better_supabase.can('tenant', list_case_kinds.tenant, 'cases.read'), false))) then
    raise exception 'not allowed to read cases' using errcode = '42501', hint = 'CASE_FORBIDDEN';
  end if;
  perform "better_supabase"."ensure_case_kinds"(list_case_kinds.tenant);
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'key', x."key", 'name', x."name", 'prefix', x."prefix", 'pipelineId', x."pipeline_id", 'investigationFormId', x."investigation_form_id", 'effectivenessFormId', x."effectiveness_form_id", 'effectivenessAfterDays', x."effectiveness_after_days", 'requiresRootCause', x."requires_root_cause", 'requiresActions', x."requires_actions", 'requiresEffectiveness', x."requires_effectiveness", 'requiresRevisions', x."requires_revisions", 'archivedAt', x."archived_at", 'createdAt', x."created_at", 'updatedAt', x."updated_at") order by x."name")
    from "better_supabase"."case_kinds" x
    where x."tenant_id" = list_case_kinds.tenant
      and (coalesce(list_case_kinds.include_archived, false) or x."archived_at" is null)
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_cases (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_filters jsonb := coalesce(list_cases.filters, '{}'::jsonb);
  v_search text := case when nullif(trim(v_filters ->> 'search'), '') is null then null
    else '%' || replace(replace(replace(trim(v_filters ->> 'search'), '\', '\\'), '%', '\%'), '_', '\_') || '%' end;
  v_limit integer := least(greatest(coalesce((v_filters ->> 'limit')::integer, 50), 1), 200);
  v_after_at timestamptz;
  v_after_id uuid;
  v_items jsonb;
  v_count integer;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (list_cases.tenant is not null and coalesce(better_supabase.can('tenant', list_cases.tenant, 'cases.read'), false))) then
    raise exception 'not allowed to read cases' using errcode = '42501', hint = 'CASE_FORBIDDEN';
  end if;
  if jsonb_typeof(v_filters) <> 'object' then
    raise exception 'filters must be an object' using errcode = '22023', hint = 'CASE_INVALID';
  end if;
  if nullif(v_filters ->> 'cursor', '') is not null then
    begin
      v_after_at := split_part(v_filters ->> 'cursor', '|', 1)::timestamptz;
      v_after_id := split_part(v_filters ->> 'cursor', '|', 2)::uuid;
    exception when others then
      raise exception 'cursor is not a nextCursor of list_cases' using errcode = '22023', hint = 'CASE_INVALID';
    end;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'kindId', x."kind_id", 'number', x."number", 'title', x."title", 'description', x."description", 'severity', x."severity", 'source', x."source", 'reporterId', x."reporter_id", 'reporterContact', x."reporter_contact", 'ownerId', x."owner_id", 'occurredAt', x."occurred_at", 'detectedAt', x."detected_at", 'dueOn', x."due_on", 'pipelineId', x."pipeline_id", 'stageId', x."stage_id", 'stageEnteredAt', x."stage_entered_at", 'status', x."status", 'rootCause', x."root_cause", 'rootCauseSubmissionId', x."root_cause_submission_id", 'effective', x."effective", 'effectivenessDueOn', x."effectiveness_due_on", 'effectivenessNote', x."effectiveness_note", 'effectivenessSubmissionId', x."effectiveness_submission_id", 'closedAt', x."closed_at", 'closedBy', x."closed_by", 'closeNote', x."close_note", 'rank', x."rank", 'archivedAt', x."archived_at", 'createdBy', x."created_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at") order by x."created_at" desc, x."id" desc), '[]'::jsonb), count(*)
  into v_items, v_count
  from (
    select * from "better_supabase"."cases" x
    where x."tenant_id" = list_cases.tenant
      and x."archived_at" is null
      and (not v_filters ? 'kind' or x."kind_id" = (select y."id" from "better_supabase"."case_kinds" y where y."tenant_id" = list_cases.tenant and y."key" = v_filters ->> 'kind'))
      and (not v_filters ? 'status' or x."status" = v_filters ->> 'status')
      and (not v_filters ? 'severity' or x."severity" = v_filters ->> 'severity')
      and (not v_filters ? 'source' or x."source" = v_filters ->> 'source')
      and (not v_filters ? 'owner' or x."owner_id" = (v_filters ->> 'owner')::uuid)
      and (not v_filters ? 'stage' or x."stage_id" = (v_filters ->> 'stage')::uuid)
      and (coalesce((v_filters ->> 'overdue')::boolean, false) is false or (x."status" = 'open' and x."due_on" < current_date))
      and (v_search is null or x."title" ilike v_search or x."number" ilike v_search or x."description" ilike v_search or x."root_cause" ilike v_search)
      and (v_after_at is null or (x."created_at", x."id") < (v_after_at, v_after_id))
    order by x."created_at" desc, x."id" desc
    limit v_limit
  ) x;
  return jsonb_build_object(
    'items', v_items,
    'nextCursor', case when v_count = v_limit
      then (v_items -> -1 ->> 'createdAt') || '|' || (v_items -> -1 ->> 'id')
      else null end);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_chain_checkpoints (
  target   regclass,
  tenant   text     DEFAULT NULL::text,
  max_rows integer  DEFAULT 100
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_rows jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'Only the service role lists checkpoints' using errcode = '42501', hint = 'CHAIN_FORBIDDEN';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', k.id::text, 'tenant', k.tenant, 'seq', k.chain_seq, 'hash', encode(k.row_hash, 'hex'),
    'keyId', k.key_id, 'signature', k.signature, 'createdAt', k.created_at
  ) order by k.chain_seq desc), '[]'::jsonb) into v_rows
  from (
    select * from better_supabase.chain_checkpoints x
    where x.table_name = target::text and x.tenant is not distinct from list_chain_checkpoints.tenant
    order by x.chain_seq desc limit max_rows
  ) k;
  return v_rows;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_channels (
  tenant           uuid,
  browse           boolean DEFAULT false,
  include_archived boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(to_jsonb(x) || jsonb_build_object(
      'archivedAt', c."archived_at",
      'lastMessageAt', c."last_message_at",
      'role', (select k."role" from "better_supabase"."conversation_members" k where k."conversation_id" = c."id" and k."user_id" = auth.uid()),
      'memberCount', (select count(*) from "better_supabase"."conversation_members" k where k."conversation_id" = c."id")
    ) order by x."name"), '[]'::jsonb)
  from "better_supabase"."channels" x
  join "better_supabase"."conversations" c on c."id" = x."id"
  where x."tenant_id" = list_channels.tenant
    and (list_channels.include_archived or c."archived_at" is null)
    and (list_channels.browse or exists (
      select 1 from "better_supabase"."conversation_members" k where k."conversation_id" = x."id" and k."user_id" = auth.uid()
    ))
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_chat_installations (
  tenant              uuid    DEFAULT NULL::uuid,
  adapter             text    DEFAULT NULL::text,
  include_uninstalled boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(to_jsonb(i) order by i."installed_at" desc), '[]'::jsonb)
  from "better_supabase"."chat_installations" i
  where (list_chat_installations.tenant is null or i."tenant_id" = list_chat_installations.tenant)
    and (list_chat_installations.adapter is null or i."adapter" = list_chat_installations.adapter)
    and (coalesce(include_uninstalled, false) or i."uninstalled_at" is null);
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_checkout_sessions (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_filters jsonb := coalesce(list_checkout_sessions.filters, '{}'::jsonb);
  v_limit integer := least(greatest(coalesce((v_filters ->> 'limit')::integer, 50), 1), 200);
  v_offset integer := greatest(coalesce((v_filters ->> 'offset')::integer, 0), 0);
  v_after jsonb := v_filters -> 'after';
  v_paged boolean := coalesce((v_filters ->> 'paged')::boolean, false);
  v_total_cap integer := least(greatest(coalesce((v_filters ->> 'totalCap')::integer, 10000), 1), 100000);
  v_items jsonb;
  v_more boolean;
  v_next jsonb;
  v_total integer;
  v_status text := nullif(v_filters ->> 'status', '');
  v_protocol text := nullif(v_filters ->> 'protocol', '');
  v_cart text := nullif(v_filters ->> 'cartId', '');
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (list_checkout_sessions.tenant is not null and coalesce(better_supabase.can('tenant', list_checkout_sessions.tenant, 'agent_checkout.read'), false))) then
    raise exception 'not allowed to read checkout sessions' using errcode = '42501', hint = 'CHECKOUT_FORBIDDEN';
  end if;
  if v_filters ? 'after' and v_filters ? 'offset' then
    raise exception 'after and offset are two ways to page; pass one' using errcode = '22023', hint = 'CHECKOUT_INVALID';
  end if;
  if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 2) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'CHECKOUT_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'cartId', x."cart_id", 'protocol', x."protocol", 'status', x."status", 'buyer', x."buyer", 'orderId', x."order_id", 'expiresAt', x."expires_at", 'expired', (x."status" in ('open', 'ready') and x."expires_at" is not null and x."expires_at" <= now()), 'createdBy', x."created_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at") as j, jsonb_build_array((x."created_at")::text, (x."id")::text) as k
    from (
      select * from "better_supabase"."checkout_sessions" x
      where x."tenant_id" = list_checkout_sessions.tenant
        and (v_status is null or x."status" = v_status)
        and (v_protocol is null or x."protocol" = v_protocol)
        and (v_cart is null or x."cart_id"::text = v_cart)
        and (v_after is null or (x."created_at" <= (v_after ->> 0)::timestamptz and ((x."created_at" < (v_after ->> 0)::timestamptz) or (x."created_at" = (v_after ->> 0)::timestamptz and x."id" > (v_after ->> 1)::uuid))))
      order by x."created_at" desc, x."id" asc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  if not v_paged then
    return v_items;
  end if;
  if coalesce((v_filters ->> 'total')::boolean, false) then
    select count(*) into v_total from (
      select 1 from "better_supabase"."checkout_sessions" x
      where x."tenant_id" = list_checkout_sessions.tenant
        and (v_status is null or x."status" = v_status)
        and (v_protocol is null or x."protocol" = v_protocol)
        and (v_cart is null or x."cart_id"::text = v_cart)
      limit v_total_cap + 1
    ) c;
  end if;
  return jsonb_build_object('items', v_items, 'hasMore', v_more, 'nextCursor', case when v_more then v_next end)
    || case when v_total is null then '{}'::jsonb
      else jsonb_build_object('total', least(v_total, v_total_cap), 'totalCapped', v_total > v_total_cap) end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_collections (
  tenant           uuid,
  subject_type     text,
  include_archived boolean
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', x."id",
    'organizationId', x."tenant_id",
    'subjectType', x."subject_type",
    'scope', x."scope",
    'ownerId', x."owner_id",
    'teamId', x."team_id",
    'name', x."name",
    'description', x."description",
    'archivedAt', x."archived_at",
    'createdBy', x."created_by",
    'createdAt', x."created_at",
    'updatedAt', x."updated_at") order by lower(x."name"), x."id"), '[]'::jsonb)
  from "better_supabase"."subject_collections" x
  where x."tenant_id" = list_collections.tenant
    and (list_collections.subject_type is null or x."subject_type" = list_collections.subject_type)
    and (coalesce(list_collections.include_archived, false) or x."archived_at" is null)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_comments (
  tenant          uuid,
  subject_type    text,
  subject_id      text,
  after           timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  max_rows        integer                  DEFAULT 100,
  skip            integer                  DEFAULT 0,
  after_id        uuid                     DEFAULT NULL::uuid,
  include_deleted boolean                  DEFAULT true
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_conv uuid := "better_supabase"."comment_conversation"(list_comments.tenant, list_comments.subject_type, list_comments.subject_id);
begin
  if v_conv is null then
    return '[]'::jsonb;
  end if;
  perform "better_supabase"."record_subject_read"(list_comments.subject_type, list_comments.subject_id, null, 'comments', 'list_comments');
  return "better_supabase"."comments_json"("better_supabase"."comment_page"(v_conv, list_comments.after, list_comments.max_rows, list_comments.skip, list_comments.after_id, list_comments.include_deleted));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_comments_unchecked (
  tenant          uuid,
  subject_type    text,
  subject_id      text,
  after           timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  max_rows        integer                  DEFAULT 100,
  skip            integer                  DEFAULT 0,
  after_id        uuid                     DEFAULT NULL::uuid,
  include_deleted boolean                  DEFAULT true
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_conv uuid;
  v_ids uuid[];
begin
  select c."id" into v_conv from "better_supabase"."conversations" c
  where c."tenant_id" = list_comments_unchecked.tenant and c."kind" = 'subject'
    and c."subject_type" = list_comments_unchecked.subject_type and c."subject_id" = list_comments_unchecked.subject_id;
  if v_conv is null then
    return '[]'::jsonb;
  end if;
  perform "better_supabase"."record_subject_read"(list_comments_unchecked.subject_type, list_comments_unchecked.subject_id, null, 'comments', 'list_comments_unchecked');
  v_ids := array(
    select x."id" from "better_supabase"."messages" x
    where x."conversation_id" = v_conv and x."sent_at" is not null
      and (coalesce(list_comments_unchecked.include_deleted, true) or x."archived_at" is null)
      and (list_comments_unchecked.after is null
        or (x."sent_at", x."id") > (list_comments_unchecked.after, coalesce(list_comments_unchecked.after_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
    order by x."sent_at", x."id"
    limit least(greatest(coalesce(list_comments_unchecked.max_rows, 100), 1), 500)
    offset greatest(coalesce(list_comments_unchecked.skip, 0), 0)
  );
  return (
    with e as materialized (
      select x.row, x.n from jsonb_array_elements("better_supabase"."messaging_messages_json_unchecked"(v_ids)) with ordinality x(row, n)
    ),
    c as materialized (
      select c."id" as id, c."subject_type" as subject_type, c."subject_id" as subject_id
      from "better_supabase"."conversations" c
      where c."id" = any (array(select distinct (e.row ->> 'conversation_id')::uuid from e))
    ),
    t as materialized (
      select t."message_id" as message, t."task_id" as task from "better_supabase"."comment_tasks" t
      where t."message_id" = any (v_ids)
    )
    select coalesce(jsonb_agg(e.row || jsonb_build_object(
      'subject_type', c.subject_type,
      'subject_id', c.subject_id,
      'task_id', t.task
    ) order by e.n), '[]'::jsonb)
    from e
    join c on c.id = (e.row ->> 'conversation_id')::uuid
    left join t on t.message = (e.row ->> 'id')::uuid
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_commission_plans (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_filters jsonb := coalesce(list_commission_plans.filters, '{}'::jsonb);
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (list_commission_plans.tenant is not null and coalesce(better_supabase.can('tenant', list_commission_plans.tenant, 'commissions.read'), false))) then
    raise exception 'not allowed to read commission plans' using errcode = '42501', hint = 'COMMISSION_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', y."id", 'organizationId', y."tenant_id", 'name', y."name", 'kind', y."kind", 'rateBps', y."rate_bps", 'tiers', y."tiers", 'archivedAt', y."archived_at", 'createdAt', y."created_at", 'updatedAt', y."updated_at") || jsonb_build_object('assignments', coalesce((
        select jsonb_agg(jsonb_build_object('id', a."id", 'organizationId', a."tenant_id", 'planId', a."plan_id", 'sellerId', a."seller_id", 'subjectType', a."subject_type", 'subjectId', a."subject_id", 'startsOn', a."starts_on", 'endsOn', a."ends_on", 'createdAt', a."created_at") order by a."starts_on" desc, a."created_at" desc)
        from "better_supabase"."commission_assignments" a where a."plan_id" = y."id"
      ), '[]'::jsonb)) order by y."created_at" desc)
    from (
      select * from "better_supabase"."commission_plans" z
      where z."tenant_id" = list_commission_plans.tenant
        and (coalesce((v_filters ->> 'archived')::boolean, false) or z."archived_at" is null)
      order by z."created_at" desc
      limit least(greatest(coalesce((v_filters ->> 'limit')::integer, 100), 1), 500)
    ) y
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_commission_statements (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_filters jsonb := coalesce(list_commission_statements.filters, '{}'::jsonb);
  v_all boolean := (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (list_commission_statements.tenant is not null and coalesce(better_supabase.can('tenant', list_commission_statements.tenant, 'commissions.read'), false)));
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', y."id", 'organizationId', y."tenant_id", 'sellerId', y."seller_id", 'currency', y."currency", 'startsOn', y."starts_on", 'endsOn', y."ends_on", 'status', y."status", 'total', y."total"::text, 'ledgerTransactionId', y."ledger_transaction_id", 'finalizedAt', y."finalized_at", 'paidAt', y."paid_at", 'paidBy', y."paid_by", 'createdAt', y."created_at") order by y."ends_on" desc, y."created_at" desc)
    from (
      select * from "better_supabase"."commission_statements" z
      where z."tenant_id" = list_commission_statements.tenant
        and (v_all or z."seller_id" = (select auth.uid()))
        and (not v_filters ? 'seller' or z."seller_id" = (v_filters ->> 'seller')::uuid)
        and (not v_filters ? 'status' or z."status" = v_filters ->> 'status')
      order by z."ends_on" desc, z."created_at" desc
      limit least(greatest(coalesce((v_filters ->> 'limit')::integer, 100), 1), 500)
    ) y
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_commissions (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
