CREATE OR REPLACE FUNCTION better_supabase.list_inbox_conversations (
  tenant uuid  DEFAULT NULL::uuid,
  filter jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
begin
  return (
    with page as materialized (
      select v."id" as id, v."inbox_id" as inbox, v."last_message_at" as last_message_at, to_jsonb(v) as body
      from "better_supabase"."inbox_conversations" v
      where (list_inbox_conversations.tenant is null or v."tenant_id" = list_inbox_conversations.tenant)
        and (filter ->> 'inbox_id' is null or v."inbox_id" = (filter ->> 'inbox_id')::uuid)
        and (coalesce(filter ->> 'status', 'open') = 'all' or v."status" = coalesce(filter ->> 'status', 'open'))
        and (case filter ->> 'assignee'
          when 'me' then v."assignee_id" = (select auth.uid())
          when 'unassigned' then v."assignee_id" is null
          else filter ->> 'assignee' is null or v."assignee_id" = (filter ->> 'assignee')::uuid end)
        and (filter ->> 'team_id' is null or v."team_id" = (filter ->> 'team_id')::uuid)
        and (filter ->> 'contact_id' is null or v."contact_id" = (filter ->> 'contact_id')::uuid)
        and (nullif(filter ->> 'search', '') is null
          or v."subject" ilike '%' || (filter ->> 'search') || '%'
          or v."last_message_preview" ilike '%' || (filter ->> 'search') || '%'
          or v."id" in (select m.conversation from "better_supabase"."inbox_contacts_json"(null, list_inbox_conversations.tenant, filter ->> 'search') m))
        and (filter -> 'before' is null
          or (v."last_message_at", v."id") < ((filter -> 'before' ->> 'last_message_at')::timestamptz, (filter -> 'before' ->> 'id')::uuid))
      order by v."last_message_at" desc, v."id" desc
      limit least(greatest(coalesce((filter ->> 'limit')::integer, 50), 1), 200)
    ), contacts as materialized (
      select c.conversation, c.contact, c.contact_read_at
      from "better_supabase"."inbox_contacts_json"((select coalesce(array_agg(page.id), '{}') from page)) c
    )
    select coalesce(jsonb_agg(
      page.body || jsonb_build_object(
        'contact', contacts.contact,
        'inbox', box.item,
        'last_read_at', seen.at,
        'contact_read_at', contacts.contact_read_at,
        'unread', page.last_message_at > coalesce(seen.at, '-infinity'::timestamptz))
      order by page.last_message_at desc, page.id desc), '[]'::jsonb)
    from page
    left join contacts on contacts.conversation = page.id
    left join lateral (
      select jsonb_build_object('id', i."id", 'name', i."name", 'channel', i."channel") as item
      from "better_supabase"."inboxes" i where i."id" = page.inbox
    ) box on true
    left join lateral (
      select k."last_read_at" as at
      from "better_supabase"."conversation_members" k
      where k."conversation_id" = page.id and k."user_id" = (select auth.uid())
    ) seen on true
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_inbox_drafts (
  conversation uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(to_jsonb(d) order by d."updated_at" desc, d."id"), '[]'::jsonb)
  from "better_supabase"."inbox_drafts" d
  where d."status" = 'draft'
    and (list_inbox_drafts.conversation is null or d."conversation_id" = list_inbox_drafts.conversation);
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_inbox_messages (
  conversation uuid,
  before       timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  max          integer                  DEFAULT 50,
  after        timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not "better_supabase"."inbox_conversation_allowed"(list_inbox_messages.conversation::text) then
    return '[]'::jsonb;
  end if;
  return "better_supabase"."inbox_messages_json"(array(
    select m."id" from "better_supabase"."messages" m
    where m."conversation_id" = list_inbox_messages.conversation
      and m."sent_at" is not null
      and (list_inbox_messages.before is null or m."sent_at" < list_inbox_messages.before)
      and (list_inbox_messages.after is null or m."sent_at" > list_inbox_messages.after)
      and (m."kind" = 'message' or "better_supabase"."inbox_note_readable"(list_inbox_messages.conversation))
    order by
      case when list_inbox_messages.after is null then m."sent_at" end desc,
      case when list_inbox_messages.after is null then m."id" end desc,
      m."sent_at", m."id"
    limit least(greatest(coalesce(list_inbox_messages.max, 50), 1), 200)
  ));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_incident_filings (
  tenant  uuid,
  pending boolean DEFAULT true
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', list_incident_filings.tenant, 'incidents.read'), false)) then
    raise exception 'not allowed to read incident filings' using errcode = '42501', hint = 'INCIDENTS_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'incidentId', x."incident_id", 'regime', x."regime", 'stage', x."stage", 'dueAt', x."due_at", 'submittedAt', x."submitted_at", 'submittedBy', x."submitted_by", 'reference', x."reference", 'notes', x."notes", 'createdAt', x."created_at") order by x."due_at" nulls last, x."id")
    from "better_supabase"."incident_regulatory_filings" x
    where x."tenant_id" = list_incident_filings.tenant
      and (coalesce(list_incident_filings.pending, true) is false or x."submitted_at" is null)
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_incidents (
  tenant       uuid,
  status       text                     DEFAULT NULL::text,
  severity     text                     DEFAULT NULL::text,
  component_id uuid                     DEFAULT NULL::uuid,
  before       timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  page_size    integer                  DEFAULT 50
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(row_json order by started desc, id desc), '[]'::jsonb)
  from (
    select jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'title', x."title", 'description', x."description", 'severity', x."severity", 'status', x."status", 'public', x."public", 'commanderId', x."commander_id", 'startedAt', x."started_at", 'resolvedAt', x."resolved_at", 'createdBy', x."created_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at", 'impacts', (select coalesce(jsonb_agg(jsonb_build_object('componentId', im."component_id", 'name', ic."name", 'impact', im."impact") order by ic."position", ic."name"), '[]'::jsonb) from "better_supabase"."incident_impacts" im join "better_supabase"."incident_status_components" ic on ic."id" = im."component_id" where im."incident_id" = x."id")) as row_json, x."started_at" as started, x."id" as id
    from "better_supabase"."incidents" x
    where x."tenant_id" = list_incidents.tenant
      and (list_incidents.status is null
        or (list_incidents.status = 'open' and x."status" <> 'resolved')
        or (list_incidents.status = 'resolved' and x."status" = 'resolved'))
      and (list_incidents.severity is null or x."severity" = list_incidents.severity)
      and (list_incidents.component_id is null or exists (
        select 1 from "better_supabase"."incident_impacts" y where y."incident_id" = x."id" and y."component_id" = list_incidents.component_id
      ))
      and (list_incidents.before is null or x."started_at" < list_incidents.before)
    order by x."started_at" desc, x."id" desc
    limit least(greatest(coalesce(list_incidents.page_size, 50), 1), 200)
  ) page
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_incoming_webhooks (
  tenant       uuid,
  subject_type text    DEFAULT NULL::text,
  subject_id   text    DEFAULT NULL::text,
  page_size    integer DEFAULT NULL::integer,
  skip         integer DEFAULT 0,
  newest_first boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(page.item order by page.n), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'id', e."id",
      'tenant', e."tenant",
      'name', e."name",
      'verify', e."verify",
      'signature_header', e."signature_header",
      'enabled', e."enabled",
      'max_body_bytes', e."max_body_bytes",
      'receive_count', e."receive_count",
      'last_received_at', e."last_received_at",
      'last_status', e."last_status",
      'metadata', e."metadata",
      'subject_type', e."subject_type",
      'subject_id', e."subject_id",
      'created_by', e."created_by",
      'created_at', e."created_at"
    ) as item, row_number() over (order by case when list_incoming_webhooks.newest_first then e."created_at" end desc, case when list_incoming_webhooks.newest_first then e."id" end desc, e."created_at", e."id") as n
    from "better_supabase"."incoming_webhooks" e
    where e."tenant" = list_incoming_webhooks.tenant
    and (list_incoming_webhooks.subject_type is null or e."subject_type" = list_incoming_webhooks.subject_type)
    and (list_incoming_webhooks.subject_id is null or e."subject_id" = list_incoming_webhooks.subject_id)
    order by case when list_incoming_webhooks.newest_first then e."created_at" end desc, case when list_incoming_webhooks.newest_first then e."id" end desc, e."created_at", e."id"
    limit case when list_incoming_webhooks.page_size is null then null else least(greatest(coalesce(list_incoming_webhooks.page_size, 50), 1), 500) end
    offset greatest(coalesce(list_incoming_webhooks.skip, 0), 0)
  ) page
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_inspection_programs (
  tenant uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (list_inspection_programs.tenant is not null and coalesce(better_supabase.can('tenant', list_inspection_programs.tenant, 'inspections.read'), false))) then
    raise exception 'not allowed to read inspections' using errcode = '42501', hint = 'INSPECTION_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'name', x."name", 'periodStart', x."period_start", 'periodEnd', x."period_end", 'ownerId', x."owner_id", 'status', x."status", 'notes', x."notes", 'archivedAt', x."archived_at", 'createdAt', x."created_at", 'updatedAt', x."updated_at") order by x."period_start" desc, x."name")
    from "better_supabase"."inspection_programs" x
    where x."tenant_id" = list_inspection_programs.tenant and x."archived_at" is null
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_inspections (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_filters jsonb := coalesce(list_inspections.filters, '{}'::jsonb);
  v_search text := case when nullif(trim(v_filters ->> 'search'), '') is null then null
    else '%' || replace(replace(replace(trim(v_filters ->> 'search'), '\', '\\'), '%', '\%'), '_', '\_') || '%' end;
  v_limit integer := least(greatest(coalesce((v_filters ->> 'limit')::integer, 50), 1), 200);
  v_offset integer := greatest(coalesce((v_filters ->> 'offset')::integer, 0), 0);
  v_after jsonb := v_filters -> 'after';
  v_paged boolean := coalesce((v_filters ->> 'paged')::boolean, false);
  v_total_cap integer := least(greatest(coalesce((v_filters ->> 'totalCap')::integer, 10000), 1), 100000);
  v_items jsonb;
  v_more boolean;
  v_next jsonb;
  v_total integer;
  v_all boolean := (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (list_inspections.tenant is not null and coalesce(better_supabase.can('tenant', list_inspections.tenant, 'inspections.read'), false)));
begin
  if jsonb_typeof(v_filters) <> 'object' then
    raise exception 'filters must be an object' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  if not v_all and auth.uid() is null then
    raise exception 'not allowed to read inspections' using errcode = '42501', hint = 'INSPECTION_FORBIDDEN';
  end if;
  if v_filters ? 'after' and v_filters ? 'offset' then
    raise exception 'after and offset are two ways to page; pass one' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  if v_after is not null and (jsonb_typeof(v_after) <> 'array' or jsonb_array_length(v_after) <> 3) then
    raise exception 'after is the nextCursor of the previous page' using errcode = '22023', hint = 'INSPECTION_INVALID';
  end if;
  select coalesce(jsonb_agg(p.j order by p.n) filter (where p.n <= v_limit), '[]'::jsonb),
    count(*) > v_limit,
    (array_agg(p.k order by p.n) filter (where p.n = v_limit))[1]
  into v_items, v_more, v_next
  from (
    select row_number() over () as n, jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'programId', x."program_id", 'number', x."number", 'kind', x."kind", 'title', x."title", 'scope', x."scope", 'criteria', x."criteria", 'auditee', case when x."auditee_type" is null then null else jsonb_build_object('type', x."auditee_type", 'id', x."auditee_id") end, 'leadId', x."lead_id", 'plannedStart', x."planned_start", 'plannedEnd', x."planned_end", 'startedAt', x."started_at", 'completedAt', x."completed_at", 'closedAt', x."closed_at", 'status', x."status", 'checklistFormId', x."checklist_form_id", 'checklistSubmissionId', x."checklist_submission_id", 'summary', x."summary", 'createdBy', x."created_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at") as j, jsonb_build_array((coalesce(x."planned_start", '-infinity'::date))::text, (x."sequence")::text, (x."id")::text) as k
    from (
      select * from "better_supabase"."inspections" x
      where x."tenant_id" = list_inspections.tenant
        and (v_all or exists (
          select 1 from "better_supabase"."inspection_members" y where y."inspection_id" = x."id" and y."user_id" = auth.uid()
        ))
        and (not v_filters ? 'programId' or x."program_id" = (v_filters ->> 'programId')::uuid)
        and (not v_filters ? 'kind' or x."kind" = v_filters ->> 'kind')
        and (not v_filters ? 'status' or x."status" = v_filters ->> 'status')
        and (not v_filters ? 'leadId' or x."lead_id" = (v_filters ->> 'leadId')::uuid)
        and (not v_filters ? 'from' or x."planned_start" >= (v_filters ->> 'from')::date)
        and (not v_filters ? 'to' or x."planned_start" <= (v_filters ->> 'to')::date)
        and (not v_filters ? 'auditeeType' or x."auditee_type" = v_filters ->> 'auditeeType')
        and (not v_filters ? 'auditeeId' or x."auditee_id" = v_filters ->> 'auditeeId')
        and (v_search is null or x."title" ilike v_search or x."number" ilike v_search or x."scope" ilike v_search or x."summary" ilike v_search)
        and (v_after is null or (coalesce(x."planned_start", '-infinity'::date) <= (v_after ->> 0)::date and ((coalesce(x."planned_start", '-infinity'::date) < (v_after ->> 0)::date) or (coalesce(x."planned_start", '-infinity'::date) = (v_after ->> 0)::date and x."sequence" < (v_after ->> 1)::bigint) or (coalesce(x."planned_start", '-infinity'::date) = (v_after ->> 0)::date and x."sequence" = (v_after ->> 1)::bigint and x."id" > (v_after ->> 2)::uuid))))
      order by coalesce(x."planned_start", '-infinity'::date) desc, x."sequence" desc, x."id" asc
      limit v_limit + 1 offset v_offset
    ) x
  ) p;
  if not v_paged then
    return v_items;
  end if;
  if coalesce((v_filters ->> 'total')::boolean, false) then
    select count(*) into v_total from (
      select 1 from "better_supabase"."inspections" x
      where x."tenant_id" = list_inspections.tenant
        and (v_all or exists (
          select 1 from "better_supabase"."inspection_members" y where y."inspection_id" = x."id" and y."user_id" = auth.uid()
        ))
        and (not v_filters ? 'programId' or x."program_id" = (v_filters ->> 'programId')::uuid)
        and (not v_filters ? 'kind' or x."kind" = v_filters ->> 'kind')
        and (not v_filters ? 'status' or x."status" = v_filters ->> 'status')
        and (not v_filters ? 'leadId' or x."lead_id" = (v_filters ->> 'leadId')::uuid)
        and (not v_filters ? 'from' or x."planned_start" >= (v_filters ->> 'from')::date)
        and (not v_filters ? 'to' or x."planned_start" <= (v_filters ->> 'to')::date)
        and (not v_filters ? 'auditeeType' or x."auditee_type" = v_filters ->> 'auditeeType')
        and (not v_filters ? 'auditeeId' or x."auditee_id" = v_filters ->> 'auditeeId')
        and (v_search is null or x."title" ilike v_search or x."number" ilike v_search or x."scope" ilike v_search or x."summary" ilike v_search)
      limit v_total_cap + 1
    ) c;
  end if;
  return jsonb_build_object('items', v_items, 'hasMore', v_more, 'nextCursor', case when v_more then v_next end)
    || case when v_total is null then '{}'::jsonb
      else jsonb_build_object('total', least(v_total, v_total_cap), 'totalCapped', v_total > v_total_cap) end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_inventory_movements (
  tenant        uuid,
  variant       uuid    DEFAULT NULL::uuid,
  location      uuid    DEFAULT NULL::uuid,
  bin           uuid    DEFAULT NULL::uuid,
  lot           uuid    DEFAULT NULL::uuid,
  document_type text    DEFAULT NULL::text,
  document_id   text    DEFAULT NULL::text,
  row_limit     integer DEFAULT 50,
  row_offset    integer DEFAULT 0
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', x."id",
    'kind', x."kind",
    'variantId', x."metadata" ->> 'variantId',
    'locationId', x."metadata" ->> 'locationId',
    'binId', x."metadata" ->> 'binId',
    'lotId', x."metadata" ->> 'lotId',
    'quantity', x."metadata" ->> 'quantity',
    'documentType', x."reference_type",
    'documentId', x."reference_id",
    'effectiveAt', x."effective_at"
  )), '[]'::jsonb)
  from (
    select *
    from "better_supabase"."ledger_transactions" y
    where y."tenant_id" = list_inventory_movements.tenant
      and y."kind" like 'stock.%'
      and (list_inventory_movements.variant is null or y."metadata" ->> 'variantId' = list_inventory_movements.variant::text)
      and (list_inventory_movements.location is null or y."metadata" ->> 'locationId' = list_inventory_movements.location::text)
      and (list_inventory_movements.bin is null or y."metadata" ->> 'binId' = list_inventory_movements.bin::text)
      and (list_inventory_movements.lot is null or y."metadata" ->> 'lotId' = list_inventory_movements.lot::text)
      and (list_inventory_movements.document_type is null or y."reference_type" = list_inventory_movements.document_type)
      and (list_inventory_movements.document_id is null or y."reference_id" = list_inventory_movements.document_id)
    order by y."effective_at" desc, y."id"
    limit least(greatest(coalesce(list_inventory_movements.row_limit, 50), 0), 200)
    offset greatest(coalesce(list_inventory_movements.row_offset, 0), 0)
  ) x
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_invite_codes (
  tenant uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (select coalesce(better_supabase.is_platform('waitlist.manage'), false))) or (list_invite_codes.tenant is not null and coalesce(better_supabase.can('tenant', list_invite_codes.tenant, 'waitlist.invite'), false))) then
    raise exception 'You may not see these invite codes' using errcode = '42501', hint = 'WAITLIST_FORBIDDEN';
  end if;
  return (
    select coalesce(jsonb_agg(to_jsonb(x) - 'code_hash' order by x."created_at" desc), '[]'::jsonb)
    from "better_supabase"."invite_codes" x
    where x."tenant_id" is not distinct from list_invite_codes.tenant
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_invoice_allocations (
  tenant     uuid,
  reference  text DEFAULT NULL::text,
  invoice_id uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', list_invoice_allocations.tenant, 'invoices.read'), false)) then
    raise exception 'not allowed to read this organization''s invoices' using errcode = '42501', hint = 'INVOICE_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('currency', (select x."currency"::text from "better_supabase"."invoices" x where x."id" = b."invoice_id"), 'reference', b."reference", 'partyId', b."party_id", 'invoiceId', b."invoice_id",
        'source', b."source", 'amount', b."amount"::text, 'discount', b."discount"::text,
        'paymentId', b."payment_id", 'discountPaymentId', b."discount_payment_id",
        'allocatedOn', b."allocated_on", 'unallocatedAt', b."unallocated_at") order by b."created_at", b."id")
    from "better_supabase"."invoice_allocations" b
    where b."tenant_id" = list_invoice_allocations.tenant
      and (list_invoice_allocations.reference is null or b."reference" = list_invoice_allocations.reference)
      and (list_invoice_allocations.invoice_id is null or b."invoice_id" = list_invoice_allocations.invoice_id)
  ), '[]'::jsonb);
end;
$function$;

