CREATE OR REPLACE FUNCTION better_supabase.list_quote_variants (
  quote uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_src "better_supabase"."quotes";
begin
  select * into v_src from "better_supabase"."quotes" x where x."id" = list_quote_variants.quote;
  if v_src."id" is null or not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', v_src."tenant_id", 'quotes.read'), false)) then
    raise exception 'no such quote you can read' using errcode = 'P0002', hint = 'QUOTE_NOT_FOUND';
  end if;
  return (select coalesce(jsonb_agg(jsonb_build_object(
      'id', x."id", 'identifier', x."identifier", 'variantLabel', x."variant_label",
      'isSelected', x."is_selected", 'status', x."status",
      'currency', x."currency", 'total', x."total"::text, 'isRoot', x."variant_of" is null)
      order by (x."variant_of" is not null), x."number"), '[]'::jsonb)
    from "better_supabase"."quotes" x where (x."id" = coalesce(v_src."variant_of", v_src."id") or x."variant_of" = coalesce(v_src."variant_of", v_src."id")));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_record_access_requests (
  subject_type text,
  subject_id   text,
  status       text    DEFAULT NULL::text,
  page_size    integer DEFAULT NULL::integer
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  SET "IntervalStyle" TO 'iso_8601'
  AS $function$
#variable_conflict use_column
declare
  v_tenant uuid;
  v_all boolean;
begin
  v_tenant := "better_supabase"."record_team_tenant"(list_record_access_requests.subject_type, list_record_access_requests.subject_id);
  if v_tenant is null then
    return '[]'::jsonb;
  end if;
  v_all := coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_tenant, 'access_requests.read'), false)
    or coalesce(auth.uid() = any ("better_supabase"."record_team_leads"(list_record_access_requests.subject_type, list_record_access_requests.subject_id)), false)
    or coalesce(auth.uid() = any (case list_record_access_requests.subject_type
      when 'drive_node' then "better_supabase"."drive_access_approvers"(list_record_access_requests.subject_id)
      end), false);
  return (
    select coalesce(jsonb_agg(item order by created desc), '[]'::jsonb)
    from (
      select jsonb_build_object('id', r."id", 'organizationId', r."tenant_id", 'userId', r."user_id", 'role', r."role", 'target', r."target", 'subjectType', r."subject_type", 'subjectId', r."subject_id", 'action', r."action", 'emergency', r."emergency", 'review', case when r."reviewed_at" is null then null else jsonb_build_object('verdict', r."review_verdict", 'note', r."review_note", 'reviewedBy', r."reviewed_by", 'reviewedAt', r."reviewed_at") end, 'previousRole', r."previous_role", 'reason', r."reason", 'duration', r."duration"::text, 'status', case when r."ended_at" is not null then 'ended' when r."granted_at" is not null then 'granted' else coalesce(x."status", 'pending') end, 'approvalId', r."approval_id", 'grantedAt', r."granted_at", 'expiresAt', r."expires_at", 'endedAt', r."ended_at", 'createdAt', r."created_at") as item, r."created_at" as created
      from "better_supabase"."access_requests" r
      left join "better_supabase"."approval_requests" x on x."id" = r."approval_id"
      where r."tenant_id" = v_tenant and r."target" = 'record'
        and r."subject_type" = list_record_access_requests.subject_type and r."subject_id" = list_record_access_requests.subject_id
        and (v_all or r."user_id" = auth.uid())
        and (list_record_access_requests.status is null or case when r."ended_at" is not null then 'ended' when r."granted_at" is not null then 'granted' else coalesce(x."status", 'pending') end = list_record_access_requests.status)
      order by r."created_at" desc
      limit least(greatest(coalesce(list_record_access_requests.page_size, 50), 1), 200)
    ) items
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_record_mentions (
  subject_type text,
  subject_id   text,
  before       timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  before_id    uuid                     DEFAULT NULL::uuid,
  max_rows     integer                  DEFAULT NULL::integer
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select case when not coalesce("better_supabase"."can_subject"(list_record_mentions.subject_type, list_record_mentions.subject_id, 'read'), false)
    then '[]'::jsonb
    else coalesce((
      with p as materialized (
        select x."message_id" as message, x."conversation_id" as conversation, x."created_at" as created_at
        from "better_supabase"."message_record_mentions" x
        where x."subject_type" = list_record_mentions.subject_type and x."subject_id" = list_record_mentions.subject_id
          and (list_record_mentions.before is null
            or (x."created_at", x."message_id") < (list_record_mentions.before, coalesce(list_record_mentions.before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
        order by x."created_at" desc, x."message_id" desc
        limit least(greatest(coalesce(list_record_mentions.max_rows, 20), 1), 100)
      ),
      j as materialized (
        select e.row from jsonb_array_elements("better_supabase"."messaging_messages_json"(array(select p.message from p))) e(row)
      )
      select jsonb_agg(jsonb_build_object(
        'message', j.row,
        'conversation', jsonb_build_object('id', c."id", 'kind', c."kind", 'title', c."title", 'subject_type', c."subject_type", 'subject_id', c."subject_id")
      ) order by p.created_at desc, p.message desc)
      from p
      join "better_supabase"."conversations" c on c."id" = p.conversation
      left join j on (j.row ->> 'id')::uuid = p.message
    ), '[]'::jsonb)
  end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_referral_codes (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_filters jsonb := coalesce(list_referral_codes.filters, '{}'::jsonb);
  v_all boolean := (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (list_referral_codes.tenant is not null and coalesce(better_supabase.can('tenant', list_referral_codes.tenant, 'referrals.read'), false)));
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', y."id", 'organizationId', y."tenant_id", 'code', y."code", 'referrerId', y."referrer_id", 'invitationId', y."invitation_id", 'rewardAmount', y."reward_amount"::text, 'rewardUnit', y."reward_unit", 'maxUses', y."max_uses", 'uses', y."uses", 'active', y."active", 'expiresAt', y."expires_at", 'createdAt', y."created_at") order by y."created_at" desc)
    from (
      select * from "better_supabase"."referral_codes" z
      where z."tenant_id" = list_referral_codes.tenant
        and (v_all or z."referrer_id" = (select auth.uid()))
        and (not v_filters ? 'referrer' or z."referrer_id" = (v_filters ->> 'referrer')::uuid)
      order by z."created_at" desc
      limit least(greatest(coalesce((v_filters ->> 'limit')::integer, 100), 1), 500)
    ) y
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_referrals (
  tenant  uuid,
  filters jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_filters jsonb := coalesce(list_referrals.filters, '{}'::jsonb);
  v_all boolean := (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (list_referrals.tenant is not null and coalesce(better_supabase.can('tenant', list_referrals.tenant, 'referrals.read'), false)));
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', y."id", 'organizationId', y."tenant_id", 'codeId', y."code_id", 'referrerId', y."referrer_id", 'referredUserId', y."referred_id", 'referredOrganizationId', y."referred_organization_id", 'referredEmail', y."referred_email", 'status', y."status", 'rewardAmount', y."reward_amount"::text, 'rewardUnit', y."reward_unit", 'qualifiedAt', y."qualified_at", 'rewardedAt', y."rewarded_at", 'ledgerTransactionId', y."ledger_transaction_id", 'createdAt', y."created_at") order by y."created_at" desc)
    from (
      select * from "better_supabase"."referrals" z
      where z."tenant_id" = list_referrals.tenant
        and (v_all or z."referrer_id" = (select auth.uid()))
        and (not v_filters ? 'referrer' or z."referrer_id" = (v_filters ->> 'referrer')::uuid)
        and (not v_filters ? 'status' or z."status" = v_filters ->> 'status')
      order by z."created_at" desc
      limit least(greatest(coalesce((v_filters ->> 'limit')::integer, 100), 1), 500)
    ) y
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_reminder_schedule()
  RETURNS TABLE (
    reminder       uuid,
    dtstart        timestamp with time zone,
    tzid           text,
    rrule          text,
    offset_minutes integer,
    tenant         uuid,
    subject_type   text,
    subject_id     text,
    user_id        uuid
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select r."id",
    u."dtstart",
    u."tzid",
    u."rrule",
    r."offset_minutes",
    r."tenant_id",
    r."subject_type",
    r."subject_id",
    r."user_id"
  from "better_supabase"."reminders" r
  join "better_supabase"."recurrence_rules" u
    on u."tenant_id" = r."tenant_id"
   and u."subject_type" = r."subject_type"
   and u."subject_id" = r."subject_id"
  where r."remind_at" is null
  union all
  select r."id", r."remind_at", 'UTC'::text, 'FREQ=DAILY;COUNT=1'::text, 0,
    r."tenant_id", r."subject_type",
    r."subject_id", r."user_id"
  from "better_supabase"."reminders" r
  where r."remind_at" is not null;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.list_renditions (
  tenant  uuid,
  node_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (list_renditions.tenant is not null and coalesce(better_supabase.can('tenant', list_renditions.tenant, 'dam.read'), false))) then
    raise exception 'not allowed to read renditions' using errcode = '42501', hint = 'DAM_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'nodeId', x."node_id", 'kind', x."kind", 'status', x."status", 'format', x."format", 'width', x."width", 'height', x."height", 'sizeBytes', x."size_bytes", 'path', x."path", 'error', x."error", 'createdAt', x."created_at", 'updatedAt', x."updated_at") order by x."kind")
    from "better_supabase"."dam_renditions" x
    where x."tenant_id" = list_renditions.tenant and x."node_id" = list_renditions.node_id
