    when 'inspection_finding' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'inspections.write'), false)
    when 'form' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'forms.manage'), false)
    when 'meeting' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'meetings.write'), false)
    when 'meeting_decision' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'meetings.write'), false)
    when 'maintenance_plan' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'maintenance.manage'), false)
    when 'dam_usage_right' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'dam.write'), false)
    when 'lims_sample' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'lims.write'), false)
    when 'tax_code' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'tax.manage'), false)
    when 'production_order' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'manufacturing.write'), false)
    when 'work_center' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'manufacturing.manage'), false)
    when 'bank_account' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'banking.manage'), false)
    when 'care_plan' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'care_plans.write'), false)
    when 'incident' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'incidents.write'), false)
    when 'content_entry' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'content.write'), false)
    when 'document' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'documents.write'), false)
    when 'customer' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'customers.write'), false)
    when 'drive_node' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'drive.manage'), false)
    when 'application' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'hiring.write'), false)
    else true
  end)) then
    raise exception 'not allowed to name versions of this document' using errcode = '42501', hint = 'DOCUMENT_FORBIDDEN';
  end if;
  select x."frozen" into v_frozen from "better_supabase"."versions" x
  where x."id" = name_document_version.version_id
    and x."subject_type" = 'document' and x."subject_id" = v_doc."id"::text
  for update;
  if v_frozen is null then
    raise exception 'version not found' using errcode = 'P0002', hint = 'DOCUMENT_VERSION_NOT_FOUND';
  end if;
  if v_frozen then
    raise exception 'a frozen version keeps its name' using errcode = '55000', hint = 'DOCUMENT_VERSION_FROZEN';
  end if;
  update "better_supabase"."versions" x set "label" = nullif(trim(name_document_version.label), '')
  where x."id" = name_document_version.version_id;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.next_activity (
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select to_jsonb(x) || jsonb_build_object('subjects', coalesce((select jsonb_agg(jsonb_build_object('type', sx."subject_type", 'id', sx."subject_id") order by sx."position") from "better_supabase"."activity_subjects" sx where sx."activity_id" = x."id"), '[]'::jsonb), 'overdue', x."done_at" is null and x."due_at" < now())
  from "better_supabase"."activities" x
  join "better_supabase"."activity_subjects" k on k."activity_id" = x."id"
  where k."subject_type" = next_activity.subject_type and k."subject_id" = next_activity.subject_id
    and x."done_at" is null and x."due_at" is not null
  order by x."due_at", x."id"
  limit 1
$function$;

CREATE OR REPLACE FUNCTION better_supabase.next_number (
  tenant   uuid,
  p_entity text,
  at       timestamp with time zone DEFAULT now(),
  p_scope  text                     DEFAULT ''::text
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_period text;
  v_n bigint;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  v_period := case p_entity
    when 'drive_document' then ''
    when 'drive_document_sop' then ''
    when 'donation_receipt' then ''
    when 'risk' then ''
    when 'case' then to_char(next_number.at at time zone 'utc', 'YYYY')
    when 'inspection' then to_char(next_number.at at time zone 'utc', 'YYYY')
    when 'production_order' then to_char(next_number.at at time zone 'utc', 'YYYY')
    else null
  end;
  if v_period is null then
    raise exception 'unknown number sequence' using errcode = '22023', hint = 'NUMBER_ENTITY_UNKNOWN';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_number_assign"(uuid, text, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::text)', v_hook::oid::regproc)
        using next_number.tenant, p_entity, v_period;
    end if;
  end;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(next_number.tenant::text || ':' || p_entity || ':' || coalesce(p_scope, '') || ':' || v_period, 0));
  insert into "better_supabase"."number_sequences" ("tenant_id", "entity", "scope", "period", "last_number")
  values (next_number.tenant, p_entity, coalesce(p_scope, ''), v_period, 1)
  on conflict ("tenant_id", "entity", "scope", "period")
  do update set "last_number" = "better_supabase"."number_sequences"."last_number" + 1, "updated_at" = now()
  returning "last_number" into v_n;
  perform "better_supabase".emit_event('number.assigned', jsonb_build_object('organizationId', next_number.tenant, 'entity', p_entity, 'period', v_period, 'number', v_n), 'number-sequences/' || p_entity, (next_number.tenant)::text, null, 'better-supabase/numbering');
  perform better_supabase.audit_event(
    event_type => 'number.assigned',
    category => 'data',
    target_type => 'number_sequence',
    record_id => p_entity,
    summary => 'assigned ' || v_n::text,
    tenant => (next_number.tenant)::uuid,
    metadata => jsonb_build_object('organizationId', next_number.tenant, 'entity', p_entity, 'period', v_period, 'number', v_n)
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_number_assign"(uuid, text, bigint)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::bigint)', v_hook::oid::regproc)
        using next_number.tenant, p_entity, v_n;
    end if;
  end;
  return v_n;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.normalize_phone (
  value  text,
  region text DEFAULT NULL::text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select case
    when compact like '00%' then '+' || regexp_replace(substring(compact from 3), '\D', '', 'g')
    when compact like '+%' then '+' || regexp_replace(substring(compact from 2), '\D', '', 'g')
    when upper(region) = 'NL' and digits like '0%' then '+31' || substring(digits from 2)
    when upper(region) = 'DE' and digits like '0%' then '+49' || substring(digits from 2)
    when upper(region) = 'FR' and digits like '0%' then '+33' || substring(digits from 2)
    when upper(region) = 'GB' and digits like '0%' then '+44' || substring(digits from 2)
    when upper(region) = 'US' then '+1' || digits
    else digits
  end
  from (
    select regexp_replace(coalesce(value, ''), '[\s().-]', '', 'g') as compact
  ) raw,
  lateral (
    select case when compact like '00%' then substring(compact from 3) else compact end as body
  ) body,
  lateral (
    select regexp_replace(body, '\D', '', 'g') as digits
  ) digits
$function$;

CREATE OR REPLACE FUNCTION better_supabase.note_signing_key_exp (
  kid text,
  exp timestamp with time zone
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role manages signing keys' using errcode = '42501', hint = 'SIGNING_KEYS_FORBIDDEN';
  end if;
  update "better_supabase"."signing_keys" k set "publish_expires_at" = note_signing_key_exp.exp
  where k."kid" = note_signing_key_exp.kid
    and (k."publish_expires_at" is null or k."publish_expires_at" < note_signing_key_exp.exp);
  return exists (select 1 from "better_supabase"."signing_keys" k where k."kid" = note_signing_key_exp.kid);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.note_ssf_verification (
  stream_id    uuid,
  min_interval interval
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_noted boolean;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role manages shared signals streams' using errcode = '42501', hint = 'SSF_FORBIDDEN';
  end if;
  if not exists (select 1 from "better_supabase"."ssf_streams" s where s."id" = note_ssf_verification.stream_id) then
    raise exception 'stream not found' using errcode = 'P0002', hint = 'SSF_STREAM_NOT_FOUND';
  end if;
  update "better_supabase"."ssf_streams" s set "verified_at" = now()
  where s."id" = note_ssf_verification.stream_id
    and (s."verified_at" is null or s."verified_at" + coalesce(note_ssf_verification.min_interval, '0 seconds') <= now())
  returning true into v_noted;
  return coalesce(v_noted, false);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.notification_actors (
  ids uuid[]
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_object_agg(pr."id"::text, jsonb_build_object('id', pr."id", 'username', pr."username", 'fullName', pr."full_name", 'firstName', pr."first_name", 'lastName', pr."last_name", 'avatar', pr."avatar_url", 'avatarPath', pr."avatar_path")), '{}')
  from "better_supabase"."profiles" pr
  where pr."id" = any(notification_actors.ids)
    and exists (
      select 1 from "better_supabase"."notification_recipients" rc
      join "better_supabase"."notification_events" ev on ev."id" = rc."event_id"
      where rc."user_id" = auth.uid() and ev."actor_id" = pr."id"
    )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.notification_cadence (
  member  uuid,
  tenant  uuid,
  type    text,
  channel text
)
  RETURNS text
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce((
    select p."cadence" from "better_supabase"."notification_preferences" p
    where p."user_id" = notification_cadence.member
      and p."channel" = notification_cadence.channel
      and (p."type" = notification_cadence.type or p."type" = '*')
      and (p."tenant_id" is null or p."tenant_id" = notification_cadence.tenant)
    order by p."tenant_id" is null, p."type" = '*'
    limit 1
  ), 'immediate')
$function$;

CREATE OR REPLACE FUNCTION better_supabase.notification_counts (
  tenant     uuid    DEFAULT NULL::uuid,
  actionable text[]  DEFAULT NULL::text[],
  cap        integer DEFAULT 100
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'unread', (
      select count(*) from (
        select 1 from "better_supabase"."notification_recipients" rc
        where rc."user_id" = auth.uid()
          and rc."read_at" is null
          and rc."dismissed_at" is null
          and (notification_counts.tenant is null or rc."tenant_id" = notification_counts.tenant)
        limit notification_counts.cap
      ) u
    ),
    'actionable', coalesce(act.rows, 0),
    'actionable_subjects', coalesce(act.subjects, 0)
  )
  from (select 1) one
  left join lateral (
    select count(*) as rows, count(distinct a.subject_key) as subjects
    from (
      select case when ev."subject_type" is not null and ev."subject_id" is not null then jsonb_build_array(ev."tenant_id", ev."subject_type", ev."subject_id")::text else rc."id"::text end as subject_key
      from "better_supabase"."notification_recipients" rc
      join "better_supabase"."notification_events" ev on ev."id" = rc."event_id"
      where cardinality(coalesce(notification_counts.actionable, '{}')) > 0
        and rc."user_id" = auth.uid()
        and rc."dismissed_at" is null
        and rc."resolved_at" is null and ev."type" = any(coalesce(notification_counts.actionable, '{}'))
        and (notification_counts.tenant is null or rc."tenant_id" = notification_counts.tenant)
      limit notification_counts.cap
    ) a
  ) act on true
$function$;

CREATE OR REPLACE FUNCTION better_supabase.notification_enabled (
  member  uuid,
  tenant  uuid,
  type    text,
  channel text
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce((
    select p."enabled" and p."cadence" is distinct from 'off'
    from "better_supabase"."notification_preferences" p
    where p."user_id" = notification_enabled.member
      and p."channel" = notification_enabled.channel
      and (p."type" = notification_enabled.type or p."type" = '*')
      and (p."tenant_id" is null or p."tenant_id" = notification_enabled.tenant)
    order by p."tenant_id" is null, p."type" = '*'
    limit 1
  ), case notification_enabled.channel when 'in_app' then true else false end)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.notification_page (
  tenant        uuid                     DEFAULT NULL::uuid,
  status        text                     DEFAULT 'all'::text,
  types         text[]                   DEFAULT NULL::text[],
  subject_types text[]                   DEFAULT NULL::text[],
  search        text                     DEFAULT NULL::text,
  max_items     integer                  DEFAULT 50,
  skip          integer                  DEFAULT 0,
  read          boolean                  DEFAULT NULL::boolean,
  resolved      boolean                  DEFAULT NULL::boolean,
  dismissed     boolean                  DEFAULT false,
  before        timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  before_id     uuid                     DEFAULT NULL::uuid,
  total_cap     integer                  DEFAULT 10000,
  exclude_types text[]                   DEFAULT NULL::text[],
  subject_ids   text[]                   DEFAULT NULL::text[],
  any_of        jsonb                    DEFAULT NULL::jsonb,
  order_by      text                     DEFAULT 'newest'::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_where text;
  v_any text;
  v_limit integer := least(greatest(coalesce(notification_page.max_items, 50), 1), 500);
  v_order text;
  v_items jsonb;
  v_total bigint;
  v_args_cap integer := notification_page.total_cap;
begin
  v_order := case coalesce(notification_page.order_by, 'newest')
    when 'newest' then 'rc."created_at" desc, rc."id" desc'
    when 'oldest' then 'rc."created_at", rc."id"'
    when 'type' then 'ev."type" collate "C", rc."created_at" desc, rc."id" desc'
    when 'type_desc' then 'ev."type" collate "C" desc, rc."created_at" desc, rc."id" desc'
    when 'subject' then 'lower(coalesce(ev."subject_label", '''')) collate "C", rc."created_at" desc, rc."id" desc'
    when 'subject_desc' then 'lower(coalesce(ev."subject_label", '''')) collate "C" desc, rc."created_at" desc, rc."id" desc'
    when 'status' then 'case when rc."resolved_at" is not null then 2 when rc."read_at" is null then 0 else 1 end, rc."created_at" desc, rc."id" desc'
    when 'status_desc' then 'case when rc."resolved_at" is not null then 2 when rc."read_at" is null then 0 else 1 end desc, rc."created_at" desc, rc."id" desc'
  end;
  if v_order is null then
    raise exception 'order_by is one of newest, oldest, type, type_desc, subject, subject_desc, status, status_desc, not %', notification_page.order_by using errcode = '22023';
  end if;
  if notification_page.before is not null and coalesce(notification_page.order_by, 'newest') <> 'newest' then
    raise exception 'before pages the newest order; page another order with skip' using errcode = '22023';
  end if;
  v_where := $q$rc."user_id" = $1$q$;
  if coalesce(notification_page.status, 'all') = 'settled' then
    v_where := v_where || $q$ and (rc."resolved_at" is not null or rc."dismissed_at" is not null)$q$;
  elsif notification_page.dismissed is not null then
    v_where := v_where || case when notification_page.dismissed
      then $q$ and rc."dismissed_at" is not null$q$
      else $q$ and rc."dismissed_at" is null$q$ end;
  end if;
  if notification_page.read is not null then
    v_where := v_where || case when notification_page.read
      then $q$ and rc."read_at" is not null$q$
      else $q$ and rc."read_at" is null$q$ end;
  end if;
  if notification_page.resolved is not null then
    v_where := v_where || case when notification_page.resolved
      then $q$ and rc."resolved_at" is not null$q$
      else $q$ and rc."resolved_at" is null$q$ end;
  end if;
  if notification_page.tenant is not null then
    v_where := v_where || $q$ and rc."tenant_id" = $2$q$;
  end if;
  if notification_page.types is not null then
    v_where := v_where || $q$ and ev."type" = any($3)$q$;
  end if;
  if notification_page.subject_types is not null then
    v_where := v_where || $q$ and ev."subject_type" = any($4)$q$;
  end if;
  if btrim(coalesce(notification_page.search, '')) <> '' then
    v_where := v_where || $q$ and (concat_ws(' ', ev."summary", ev."subject_label", ev."type") ilike $5 or exists (select 1 from "better_supabase"."profiles" pr where pr."id" = ev."actor_id" and concat_ws(' ', pr."username", pr."full_name", pr."first_name", pr."last_name") ilike $5))$q$;
  end if;
  case coalesce(notification_page.status, 'all')
    when 'unread' then v_where := v_where || $q$ and rc."read_at" is null$q$;
    when 'read' then v_where := v_where || $q$ and rc."read_at" is not null$q$;
    when 'unresolved' then v_where := v_where || $q$ and rc."resolved_at" is null$q$;
    else null;
  end case;
  if notification_page.before is not null then
    v_where := v_where || $q$ and (rc."created_at", rc."id") < ($9, $10)$q$;
  end if;
  if notification_page.exclude_types is not null then
    v_where := v_where || $q$ and ev."type" <> all($11)$q$;
  end if;
  if notification_page.subject_ids is not null then
    v_where := v_where || $q$ and ev."subject_id" = any($12)$q$;
  end if;
  if notification_page.any_of is not null then
    if jsonb_typeof(notification_page.any_of) <> 'array'
      or exists (select 1 from jsonb_array_elements(notification_page.any_of) g where jsonb_typeof(g) <> 'object') then
      raise exception 'any_of is an array of filter objects' using errcode = '22023';
    end if;
    select coalesce(string_agg('(' || concat_ws(' and ', 'true', case when g ? 'types' then format('ev."type" = any(%L::text[])', array(select jsonb_array_elements_text(g -> 'types'))) end, case when g ? 'exclude_types' then format('ev."type" <> all(%L::text[])', array(select jsonb_array_elements_text(g -> 'exclude_types'))) end, case when g ? 'subject_types' then format('ev."subject_type" = any(%L::text[])', array(select jsonb_array_elements_text(g -> 'subject_types'))) end, case (g ->> 'read')::boolean when true then 'rc."read_at" is not null' when false then 'rc."read_at" is null' end, case (g ->> 'resolved')::boolean when true then 'rc."resolved_at" is not null' when false then 'rc."resolved_at" is null' end) || ')', ' or '), 'false')
    into v_any
    from jsonb_array_elements(notification_page.any_of) g;
    v_where := v_where || ' and (' || v_any || ')';
  end if;
  -- One row more than the page says whether another page exists, and the
  -- total stops counting at total_cap (null counts every row), so a large
  -- inbox never counts all of it. Pass before and before_id to page by key
  -- instead of skip.
  execute $q$select coalesce(jsonb_agg(p.item order by p.n), '[]')
  from (
    select row_number() over () as n, q.item
    from (
      select jsonb_build_object('id', rc."id", 'event_id', ev."id", 'type', ev."type", 'data', ev."data", 'created_at', rc."created_at", 'read_at', rc."read_at", 'tenant', ev."tenant_id", 'actor_id', ev."actor_id", 'subject_type', ev."subject_type", 'subject_id', ev."subject_id", 'subject_label', ev."subject_label", 'summary', ev."summary", 'action_path', ev."action_path", 'actions', ev."actions", 'priority', ev."priority", 'resolved_at', rc."resolved_at", 'resolution', rc."resolution") as item
      from "better_supabase"."notification_recipients" rc
      join "better_supabase"."notification_events" ev on ev."id" = rc."event_id"
      where $q$ || v_where || $q$
      order by $q$ || v_order || $q$
      offset $13
      limit $14 + 1
    ) q
  ) p$q$
  into v_items
  using auth.uid(), notification_page.tenant, notification_page.types, notification_page.subject_types,
    case when btrim(coalesce(notification_page.search, '')) = '' then null else '%' || replace(replace(replace(btrim(notification_page.search), chr(92), chr(92) || chr(92)), '%', chr(92) || '%'), '_', chr(92) || '_') || '%' end, notification_page.read, notification_page.resolved, notification_page.dismissed,
    notification_page.before, coalesce(notification_page.before_id, '00000000-0000-0000-0000-000000000000'::uuid),
    notification_page.exclude_types, notification_page.subject_ids,
    greatest(coalesce(notification_page.skip, 0), 0), v_limit;
  execute $q$select count(*) from (
    select 1 from "better_supabase"."notification_recipients" rc
    join "better_supabase"."notification_events" ev on ev."id" = rc."event_id"
    where $q$ || v_where || case when v_args_cap is null then '' else format(' limit %s', greatest(v_args_cap, 1)) end || $q$
  ) c$q$
  into v_total
  using auth.uid(), notification_page.tenant, notification_page.types, notification_page.subject_types,
    case when btrim(coalesce(notification_page.search, '')) = '' then null else '%' || replace(replace(replace(btrim(notification_page.search), chr(92), chr(92) || chr(92)), '%', chr(92) || '%'), '_', chr(92) || '_') || '%' end, notification_page.read, notification_page.resolved, notification_page.dismissed,
    notification_page.before, coalesce(notification_page.before_id, '00000000-0000-0000-0000-000000000000'::uuid),
    notification_page.exclude_types, notification_page.subject_ids;
  return jsonb_build_object(
    'items', coalesce((select jsonb_agg(x.value order by x.ordinality) from jsonb_array_elements(v_items) with ordinality x(value, ordinality) where x.ordinality <= v_limit), '[]'),
    'hasMore', jsonb_array_length(v_items) > v_limit,
    'limit', v_limit,
    'total', v_total,
    'totalCapped', v_args_cap is not null and v_total >= v_args_cap
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.notifications_subject_deleted_change_request()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_type text := 'change_request';
  v_id text := old."id"::text;
  v_tenant text := old."organization_id"::text;
begin
  if v_tenant is null then
    delete from "better_supabase"."notification_events" x where x."subject_type" = v_type and x."subject_id" = v_id;
    delete from "better_supabase"."notification_subscriptions" x where x."subject_type" = v_type and x."subject_id" = v_id;
  else
    delete from "better_supabase"."notification_events" x where x."tenant_id" = v_tenant::uuid and x."subject_type" = v_type and x."subject_id" = v_id;
    delete from "better_supabase"."notification_subscriptions" x where x."tenant_id" = v_tenant::uuid and x."subject_type" = v_type and x."subject_id" = v_id;
  end if;
  return null;
end;
$function$;

