CREATE OR REPLACE FUNCTION better_supabase.organization_slug_problem (
  value               text,
  except_organization uuid DEFAULT NULL::uuid
)
  RETURNS text
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select case
    when value is null then null
    when length(value) < 2 or length(value) > 48 or value !~ '^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$' then 'invalid'
    when exists (select 1 from "better_supabase"."reserved_slugs" r where r."slug" = lower(value)) then 'reserved'
    when exists (
      select 1 from "public"."organizations" o
      where lower(o."slug"::text) = lower(value)
        and o."id" is distinct from except_organization
    ) then 'taken'
  end
$function$;

CREATE OR REPLACE FUNCTION better_supabase.outbox_ack (
  consumer text,
  owner    text,
  upto     bigint DEFAULT NULL::bigint
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
begin
  update "better_supabase"."outbox_consumers" k
  set ("cursor_xid", "cursor_position") = (
      select e."xid", e."position" from "better_supabase"."outbox_events" e where e."position" = upto
    ),
    "attempts" = 0, "last_error" = null, "retry_at" = null,
    "lease_owner" = null, "lease_expires_at" = null, "updated_at" = now()
  where k."name" = consumer and k."lease_owner" = owner
    and upto is not null
    and exists (select 1 from "better_supabase"."outbox_events" e where e."position" = upto and (e."xid", e."position") > (k."cursor_xid", k."cursor_position"));
  if found then
    return true;
  end if;
  update "better_supabase"."outbox_consumers" k
  set "lease_owner" = null, "lease_expires_at" = null, "updated_at" = now()
  where k."name" = consumer and k."lease_owner" = owner;
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.outbox_claim (
  consumer   text,
  owner      text,
  max_events integer  DEFAULT 100,
  lease      interval DEFAULT '00:01:00'::interval
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  c "better_supabase"."outbox_consumers";
  events jsonb;
begin
  update "better_supabase"."outbox_consumers" k
  set "lease_owner" = owner, "lease_expires_at" = now() + lease, "updated_at" = now()
  where k."name" = consumer
    and (k."lease_expires_at" is null or k."lease_expires_at" < now() or k."lease_owner" = owner)
    and (k."retry_at" is null or k."retry_at" <= now())
  returning k.* into c;
  if not found then
    if not exists (select 1 from "better_supabase"."outbox_consumers" k where k."name" = consumer) then
      raise exception 'Unknown outbox consumer %', consumer using errcode = 'P0002', hint = 'OUTBOX_UNKNOWN_CONSUMER';
    end if;
    return '[]';
  end if;
  select jsonb_agg(x.event order by x.n) into events
  from (
    select jsonb_build_object(
    'position', e."position",
    'id', e."id",
    'type', e."type",
    'payload', e."payload",
    'created_at', e."created_at",
    'source', e."source",
    'subject', e."subject",
    'tenant', e."tenant_id",
    'key', e."key",
    'actor_id', e."actor_id"
  ) as event, row_number() over (order by e."xid", e."position") as n
    from "better_supabase"."outbox_events" e
    where (e."xid", e."position") > (c."cursor_xid", c."cursor_position")
      and e."xid" < pg_snapshot_xmin(pg_current_snapshot())
      and (c."types" is null or exists (
        select 1 from unnest(c."types") p
        where p = '*' or p = e."type"
          or (right(p, 2) = '.*' and starts_with(e."type", left(p, -1)))
      ))
    order by e."xid", e."position"
    limit case when c."attempts" > 0 then 1 else max_events end
  ) x;
  if events is null then
    update "better_supabase"."outbox_consumers" k
    set ("cursor_xid", "cursor_position") = (
      select e."xid", e."position" from "better_supabase"."outbox_events" e
      where (e."xid", e."position") > (c."cursor_xid", c."cursor_position") and e."xid" < pg_snapshot_xmin(pg_current_snapshot())
      order by e."xid" desc, e."position" desc
      limit 1
    )
    where k."name" = consumer
      and exists (select 1 from "better_supabase"."outbox_events" e where (e."xid", e."position") > (c."cursor_xid", c."cursor_position") and e."xid" < pg_snapshot_xmin(pg_current_snapshot()));
  end if;
  return coalesce(events, '[]');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.outbox_dead_letters (
  consumer text,
  max_rows integer DEFAULT 100
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'consumer', x."consumer",
    'position', x."position",
    'event', x."event",
    'attempts', x."attempts",
    'error', x."error",
    'dead_at', x."dead_at"
  ) order by x."dead_at" desc, x."position" desc), '[]')
  from (
    select * from "better_supabase"."outbox_dead_letters" d
    where d."consumer" = outbox_dead_letters.consumer
    order by d."dead_at" desc, d."position" desc
    limit least(greatest(coalesce(max_rows, 100), 1), 1000)
  ) x
$function$;

CREATE OR REPLACE FUNCTION better_supabase.outbox_fail (
  consumer     text,
  owner        text,
  failed       bigint   DEFAULT NULL::bigint,
  error        text     DEFAULT NULL::text,
  max_attempts integer  DEFAULT 10,
  max_backoff  interval DEFAULT '00:10:00'::interval
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  c "better_supabase"."outbox_consumers";
begin
  update "better_supabase"."outbox_consumers" k
  set "attempts" = k."attempts" + 1, "last_error" = left(error, 4000),
    "lease_owner" = null, "lease_expires_at" = null, "updated_at" = now()
  where k."name" = consumer and k."lease_owner" = owner
  returning k.* into c;
  if not found then
    return null;
  end if;
  if failed is not null and c."attempts" >= greatest(coalesce(max_attempts, 10), 1) then
    insert into "better_supabase"."outbox_dead_letters" ("consumer", "position", "event_id", "type", "event", "attempts", "error")
    select consumer, e."position", e."id"::text, e."type", jsonb_build_object(
    'position', e."position",
    'id', e."id",
    'type', e."type",
    'payload', e."payload",
    'created_at', e."created_at",
    'source', e."source",
    'subject', e."subject",
    'tenant', e."tenant_id",
    'key', e."key",
    'actor_id', e."actor_id"
  ), c."attempts", c."last_error"
    from "better_supabase"."outbox_events" e
    where e."position" = failed and (e."xid", e."position") > (c."cursor_xid", c."cursor_position")
    on conflict do nothing;
    update "better_supabase"."outbox_consumers" k
    set ("cursor_xid", "cursor_position") = (
        select e."xid", e."position" from "better_supabase"."outbox_events" e where e."position" = failed
      ),
      "attempts" = 0, "retry_at" = null
    where k."name" = consumer
      and exists (select 1 from "better_supabase"."outbox_events" e where e."position" = failed and (e."xid", e."position") > (k."cursor_xid", k."cursor_position"));
    if found then
      return 'dead';
    end if;
  end if;
  update "better_supabase"."outbox_consumers" k
  set "retry_at" = now() + least(
    coalesce(max_backoff, '10 minutes'),
    interval '1 second' * power(2, least(c."attempts", 20))
  )
  where k."name" = consumer;
  return 'retrying';
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.outbox_has_work()
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from "better_supabase"."outbox_consumers" c
    where (c."retry_at" is null or c."retry_at" <= now())
      and exists (select 1 from "better_supabase"."outbox_events" e where (e."xid", e."position") > (c."cursor_xid", c."cursor_position"))
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.outbox_history (
  subject    text    DEFAULT NULL::text,
  event_type text    DEFAULT NULL::text,
  after      bigint  DEFAULT 0,
  max_events integer DEFAULT 100
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(x.event order by x.position), '[]')
  from (
    select jsonb_build_object(
    'position', e."position",
    'id', e."id",
    'type', e."type",
    'payload', e."payload",
    'created_at', e."created_at",
    'source', e."source",
    'subject', e."subject",
    'tenant', e."tenant_id",
    'key', e."key",
    'actor_id', e."actor_id"
  ) as event, e."position" as position
    from "better_supabase"."outbox_events" e
    where e."position" > "outbox_history".after
      and ("outbox_history".subject is null or e."subject" = "outbox_history".subject)
      and ("outbox_history".event_type is null or e."type" = "outbox_history".event_type)
    order by e."position"
    limit "outbox_history".max_events
  ) x
$function$;

CREATE OR REPLACE FUNCTION better_supabase.outbox_register (
  consumer   text,
  types      text[]  DEFAULT NULL::text[],
  from_start boolean DEFAULT false
)
  RETURNS bigint
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  insert into "better_supabase"."outbox_consumers" ("name", "cursor_xid", "cursor_position", "types")
  select consumer, coalesce(latest.xid, '0'), coalesce(latest.position, 0), types
  from (select 1) one
  left join lateral (
    select e."xid" as xid, e."position" as position from "better_supabase"."outbox_events" e
    where not from_start
    order by e."xid" desc, e."position" desc
    limit 1
  ) latest on true
  on conflict ("name") do update set "types" = excluded."types", "updated_at" = now()
  returning "cursor_position"
$function$;

CREATE OR REPLACE FUNCTION better_supabase.outbox_row_event()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  row_data jsonb := to_jsonb(case when tg_op = 'DELETE' then old else new end);
  prefix text := coalesce(nullif(tg_argv[0], ''), tg_table_name);
  tenant_column text := nullif(tg_argv[1], '');
begin
  perform "better_supabase"."emit_event"(
    prefix || '.' || case tg_op when 'INSERT' then 'created' when 'UPDATE' then 'updated' else 'deleted' end,
    jsonb_build_object('table', tg_table_schema || '.' || tg_table_name, 'row', row_data),
    tg_table_name || '/' || coalesce(row_data ->> 'id', ''),
    case when tenant_column is null then null else row_data ->> tenant_column end,
    null,
    'better-supabase/track_events'
  );
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.outbox_unregister (
  consumer text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
begin
  delete from "better_supabase"."outbox_consumers" k where k."name" = consumer;
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.parse_gpp_string (
  gpp_string text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
declare
  v_header text := split_part(coalesce(gpp_string, ''), '~', 1);
  v_bits text := '';
  i integer;
  v_sections jsonb;
begin
  if v_header !~ '^[A-Za-z0-9_-]{4,}$' then
    raise exception 'a GPP string starts with a base64url header' using errcode = '22023', hint = 'CONSENT_SIGNAL_INVALID';
  end if;
  for i in 1 .. length(v_header) loop
    v_bits := v_bits || (strpos('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_', substr(v_header, i, 1)) - 1)::bit(6)::text;
  end loop;
  if length(v_bits) < 12 or substring(v_bits from 1 for 6)::bit(6)::int <> 3 then
    raise exception 'the GPP header has type 3' using errcode = '22023', hint = 'CONSENT_SIGNAL_INVALID';
  end if;
  select coalesce(jsonb_agg(s order by n), '[]'::jsonb) into v_sections
  from unnest(string_to_array(gpp_string, '~')) with ordinality as t(s, n)
  where n > 1;
  return jsonb_build_object(
    'type', substring(v_bits from 1 for 6)::bit(6)::int,
    'version', substring(v_bits from 7 for 6)::bit(6)::int,
    'sections', v_sections
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.parse_mentions (
  body text
)
  RETURNS jsonb
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'users', coalesce((
      select jsonb_agg(distinct lower(m[1]))
      from regexp_matches(parse_mentions.body, '@\[[^\]\n]{1,100}\]\((?:user:)?([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\)', 'gi') m
    ), '[]'::jsonb),
    'subjects', coalesce((
      select jsonb_agg(distinct jsonb_build_object('type', m[1], 'id', m[2]))
      from regexp_matches(parse_mentions.body, '@\[[^\]\n]{1,100}\]\(subject:([a-z][a-z0-9_-]{0,62})/([^)\s]{1,200})\)', 'g') m
    ), '[]'::jsonb),
    'scope', case
      when parse_mentions.body ~ '(^|[^\w@])@channel\M' then 'channel'
      when parse_mentions.body ~ '(^|[^\w@])@here\M' then 'here'
    end
  )
$function$;

CREATE OR REPLACE FUNCTION better_supabase.parse_tc_string (
  tc_string text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
declare
  v_core text := split_part(coalesce(tc_string, ''), '.', 1);
  v_bits text := '';
  i integer;
begin
  if v_core !~ '^[A-Za-z0-9_-]{36,}$' then
    raise exception 'a TC string is base64url text of at least 36 characters' using errcode = '22023', hint = 'CONSENT_SIGNAL_INVALID';
  end if;
  for i in 1 .. length(v_core) loop
    v_bits := v_bits || (strpos('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_', substr(v_core, i, 1)) - 1)::bit(6)::text;
  end loop;
  if length(v_bits) < 213 then
    raise exception 'the TC string is shorter than a core segment' using errcode = '22023', hint = 'CONSENT_SIGNAL_INVALID';
  end if;
  if substring(v_bits from 1 for 6)::bit(6)::bigint <> 2 then
    raise exception 'only TCF v2 TC strings are supported' using errcode = '22023', hint = 'CONSENT_SIGNAL_INVALID';
  end if;
  return jsonb_build_object(
    'version', substring(v_bits from 1 for 6)::bit(6)::bigint,
    'created', to_jsonb(to_timestamp(substring(v_bits from 7 for 36)::bit(36)::bigint / 10.0)),
    'lastUpdated', to_jsonb(to_timestamp(substring(v_bits from 43 for 36)::bit(36)::bigint / 10.0)),
    'cmpId', substring(v_bits from 79 for 12)::bit(12)::bigint,
    'cmpVersion', substring(v_bits from 91 for 12)::bit(12)::bigint,
    'consentScreen', substring(v_bits from 103 for 6)::bit(6)::bigint,
    'consentLanguage', chr(65 + (substring(v_bits from 109 for 6)::bit(6)::int)) || chr(65 + (substring(v_bits from 115 for 6)::bit(6)::int)),
    'vendorListVersion', substring(v_bits from 121 for 12)::bit(12)::bigint,
    'tcfPolicyVersion', substring(v_bits from 133 for 6)::bit(6)::bigint,
    'tcfV22', substring(v_bits from 133 for 6)::bit(6)::bigint >= 4,
    'isServiceSpecific', substring(v_bits from 139 for 1) = '1',
    'useNonStandardTexts', substring(v_bits from 140 for 1) = '1',
    'specialFeatureOptIns', (select coalesce(jsonb_agg(k order by k), '[]'::jsonb) from generate_series(1, 12) k where substring(v_bits from 140 + k for 1) = '1'),
    'purposesConsent', (select coalesce(jsonb_agg(k order by k), '[]'::jsonb) from generate_series(1, 24) k where substring(v_bits from 152 + k for 1) = '1'),
    'purposesLiTransparency', (select coalesce(jsonb_agg(k order by k), '[]'::jsonb) from generate_series(1, 24) k where substring(v_bits from 176 + k for 1) = '1'),
    'purposeOneTreatment', substring(v_bits from 201 for 1) = '1',
    'publisherCc', chr(65 + (substring(v_bits from 202 for 6)::bit(6)::int)) || chr(65 + (substring(v_bits from 208 for 6)::bit(6)::int))
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.party_bank_account_id (
