    when 'meeting' then exists (select 1 from "better_supabase"."meetings" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'meetings.read'), false)
    when 'meeting_decision' then exists (select 1 from "better_supabase"."meeting_decisions" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'meetings.read'), false)
    when 'maintenance_plan' then exists (select 1 from "better_supabase"."maintenance_plans" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'maintenance.read'), false)
    when 'dam_usage_right' then exists (select 1 from "better_supabase"."dam_usage_rights" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'dam.read'), false)
    when 'lims_sample' then exists (select 1 from "better_supabase"."lims_samples" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'lims.read'), false)
    when 'tax_code' then exists (select 1 from "better_supabase"."tax_codes" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'tax.read'), false)
    when 'production_order' then exists (select 1 from "better_supabase"."production_orders" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'manufacturing.read'), false)
    when 'work_center' then exists (select 1 from "better_supabase"."work_centers" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'manufacturing.read'), false)
    when 'bank_account' then exists (select 1 from "better_supabase"."bank_accounts" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'banking.read'), false)
    when 'care_plan' then exists (select 1 from "better_supabase"."care_plans" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'care_plans.read'), false)
    when 'incident' then exists (select 1 from "better_supabase"."incidents" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'incidents.read'), false)
    when 'content_entry' then exists (select 1 from "better_supabase"."content_entries" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'content.read'), false)
    when 'document' then exists (select 1 from "better_supabase"."documents" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'documents.read'), false)
    when 'customer' then exists (select 1 from "public"."customers" s where s."id" = (v_doc."subject_id")::uuid and s."organization_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'customers.read'), false)
    when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id" and (coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'drive.read'), false) and coalesce("better_supabase"."drive_node_readable"(s."id"), false)))
    when 'organization' then exists (select 1 from "public"."organizations" s where s."id" = (v_doc."subject_id")::uuid and s."id" = v_doc."tenant_id")
    when 'application' then exists (select 1 from "better_supabase"."applications" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'hiring.read'), false)
    when 'change_request' then exists (select 1 from "public"."change_requests" s where s."id" = (v_doc."subject_id")::uuid and s."organization_id" = v_doc."tenant_id")
    when 'project' then exists (select 1 from "public"."projects" s where s."id" = (v_doc."subject_id")::uuid and s."organization_id" = v_doc."tenant_id")
    when 'task' then exists (select 1 from "public"."tasks" s where s."id" = (v_doc."subject_id")::uuid and s."organization_id" = v_doc."tenant_id")
    else false
  end)) then
    raise exception 'document not found' using errcode = 'P0002', hint = 'DOCUMENT_NOT_FOUND';
  end if;
  select * into v_snapshot from "better_supabase"."document_snapshots" x where x."document_id" = v_doc."id";
  if v_snapshot."document_id" is not null and pull_document_updates.after_seq < v_snapshot."seq" then
    return jsonb_build_object(
      'snapshot', replace(encode(v_snapshot."state", 'base64'), E'\n', ''),
      'snapshotSeq', v_snapshot."seq",
      'updates', "better_supabase"."document_updates_after"(v_doc."id", v_snapshot."seq")
    );
  end if;
  return jsonb_build_object('updates', "better_supabase"."document_updates_after"(v_doc."id", pull_document_updates.after_seq));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purchase_bill_match (
  invoice uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."invoices";
  v_result jsonb;
begin
  select * into v_row from "better_supabase"."invoices" x
  where x."id" = purchase_bill_match.invoice and ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', x."tenant_id", 'invoices.read'), false));
  if v_row."id" is null then
    raise exception 'no such invoice you can read' using errcode = 'P0002', hint = 'INVOICE_NOT_FOUND';
  end if;
  if v_row."direction" <> 'purchase' or (v_row."kind" = 'invoice') is not true then
    raise exception 'only a purchase bill is matched' using errcode = '22023', hint = 'INVOICE_NOT_PURCHASE_BILL';
  end if;
  v_result := "better_supabase"."invoice_match_result"(v_row."id");
  perform "better_supabase".emit_event('invoice.match_checked', jsonb_build_object('organizationId', v_row."tenant_id", 'invoiceId', v_row."id", 'subjectType', 'invoice', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier", 'purchaseOrderId', v_row."purchase_order_id", 'status', v_result ->> 'status'), 'invoices/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/invoices');
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purchase_invoice_approval_status (
  invoice uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."invoices";
begin
  select * into v_row from "better_supabase"."invoices" x where x."id" = purchase_invoice_approval_status.invoice and ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', x."tenant_id", 'invoices.read'), false));
  if v_row."id" is null then
    raise exception 'no such invoice you can read' using errcode = 'P0002', hint = 'INVOICE_NOT_FOUND';
  end if;
  return "better_supabase"."invoice_approval_state"(v_row."id");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purchase_invoice_approval_statuses (
  invoice_ids uuid[]
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  return (
    select coalesce(jsonb_object_agg(x."id", "better_supabase"."invoice_approval_state"(x."id")), '{}'::jsonb)
    from "better_supabase"."invoices" x
    where x."id" = any (purchase_invoice_approval_statuses.invoice_ids) and ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', x."tenant_id", 'invoices.read'), false))
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purchase_order_from_order (
  order_id      uuid,
  supplier_id   text,
  supplier_type text DEFAULT 'company'::text,
  location      uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_order record;
  v_location uuid := purchase_order_from_order.location;
  v_lines jsonb;
  v_purchase jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."id" as id, x."tenant_id" as tenant, x."currency" as currency, x."shipping_address" as ship_to
  into v_order from "better_supabase"."orders" x where x."id" = purchase_order_from_order.order_id;
  if not found or not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_order.tenant, 'orders.read'), false)) then
    raise exception 'order not found' using errcode = 'P0002', hint = 'ORDERS_ORDER_NOT_FOUND';
  end if;
  if purchase_order_from_order.supplier_id is null then
    raise exception 'a drop-ship purchase order names its supplier' using errcode = '22023', hint = 'INVENTORY_SUPPLIER_INVALID';
  end if;
  v_location := coalesce(v_location, (select l."location_id" from "better_supabase"."order_lines" l where l."order_id" = v_order.id and l."location_id" is not null limit 1), (select y."id" from "better_supabase"."inventory_locations" y
    where y."tenant_id" = v_order.tenant and y."active" order by y."code" limit 1));
  select jsonb_agg(jsonb_build_object('variantId', g.variant, 'quantity', g.quantity::text, 'unitCost', g.unit_cost::text)) into v_lines
  from (
    select l."variant_id" as variant, sum(l."quantity") as quantity, max(coalesce((select round(y."average_cost")::bigint from "better_supabase"."stock_items" y where y."variant_id" = l."variant_id" and y."currency" = v_order.currency), 0)) as unit_cost
    from "better_supabase"."order_lines" l where l."order_id" = v_order.id and l."variant_id" is not null
    group by 1
  ) g;
  if v_lines is null then
    raise exception 'the order has no catalog lines to buy' using errcode = '55000', hint = 'ORDERS_CART_EMPTY';
  end if;
  v_purchase := "better_supabase"."save_purchase_order"(v_order.tenant, null, v_location, purchase_order_from_order.supplier_type,
    purchase_order_from_order.supplier_id, v_order.currency, null, v_lines, 'Drop ship');
  update "better_supabase"."purchase_orders" x set "ship_to" = v_order.ship_to, "origin_type" = 'order', "origin_id" = v_order.id::text
  where x."id" = (v_purchase ->> 'id')::uuid;
  return v_purchase || jsonb_build_object('orderId', v_order.id, 'shipTo', v_order.ship_to);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purchase_order_from_requisitions (
  requisitions  uuid[],
  supplier_type text   DEFAULT NULL::text,
  supplier_id   text   DEFAULT NULL::text,
  currency      text   DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_location uuid;
  v_supplier_type text := purchase_order_from_requisitions.supplier_type;
  v_supplier_id text := purchase_order_from_requisitions.supplier_id;
  v_currency text := upper(purchase_order_from_requisitions.currency);
  v_lines jsonb;
  v_order jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if coalesce(cardinality(purchase_order_from_requisitions.requisitions), 0) = 0 then
    raise exception 'name at least one requisition' using errcode = '22023', hint = 'INVENTORY_REQUISITION_NOT_FOUND';
  end if;
  perform 1 from "better_supabase"."purchase_requisitions" x where x."id" = any (purchase_order_from_requisitions.requisitions) for update;
  if (select count(*) from "better_supabase"."purchase_requisitions" x where x."id" = any (purchase_order_from_requisitions.requisitions))
    <> (select count(distinct r) from unnest(purchase_order_from_requisitions.requisitions) r) then
    raise exception 'purchase requisition not found' using errcode = 'P0002', hint = 'INVENTORY_REQUISITION_NOT_FOUND';
  end if;
  if (select count(distinct x."tenant_id") + count(distinct x."location_id") from "better_supabase"."purchase_requisitions" x where x."id" = any (purchase_order_from_requisitions.requisitions)) <> 2 then
    raise exception 'requisitions on one purchase order share an organization and a location' using errcode = '22023', hint = 'INVENTORY_REQUISITION_MIXED';
  end if;
  select x."tenant_id", x."location_id" into v_tenant, v_location
  from "better_supabase"."purchase_requisitions" x where x."id" = purchase_order_from_requisitions.requisitions[1];
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'inventory.purchase'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  if exists (select 1 from "better_supabase"."purchase_requisitions" x where x."id" = any (purchase_order_from_requisitions.requisitions) and x."status" <> 'approved') then
    raise exception 'only approved requisitions become a purchase order' using errcode = '55000', hint = 'INVENTORY_REQUISITION_STATUS';
  end if;
  if v_supplier_id is null then
    select min(x."supplier_type"), min(x."supplier_id") into v_supplier_type, v_supplier_id
    from "better_supabase"."purchase_requisitions" x where x."id" = any (purchase_order_from_requisitions.requisitions)
    having count(distinct coalesce(x."supplier_type", '') || ':' || coalesce(x."supplier_id", '')) = 1;
  end if;
  if v_currency is null then
    select min(x."currency") into v_currency
    from "better_supabase"."purchase_requisitions" x where x."id" = any (purchase_order_from_requisitions.requisitions)
    having count(distinct x."currency") = 1;
  end if;
  select jsonb_agg(jsonb_build_object('variantId', y.variant, 'quantity', y.quantity::text, 'unitCost', y.unit_cost::text)) into v_lines
  from (
    select l."variant_id" as variant, sum(l."quantity") as quantity, coalesce(max(l."unit_cost"), 0) as unit_cost
    from "better_supabase"."purchase_requisition_lines" l where l."requisition_id" = any (purchase_order_from_requisitions.requisitions)
    group by 1
  ) y;
  v_order := "better_supabase"."save_purchase_order"(v_tenant, null, v_location, v_supplier_type, v_supplier_id, v_currency, null, v_lines, null);
  update "better_supabase"."purchase_requisitions" x set "status" = 'ordered', "purchase_order_id" = (v_order ->> 'id')::uuid, "updated_at" = now()
  where x."id" = any (purchase_order_from_requisitions.requisitions);
  return v_order;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purchase_order_tax_lines (
  purchase_order uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row record;
begin
  select x."tenant_id" as tenant, x."currency" as currency into v_row
  from "better_supabase"."purchase_orders" x where x."id" = purchase_order_tax_lines.purchase_order;
  if not found or not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_row.tenant, 'inventory.read'), false)) then
    raise exception 'purchase order not found' using errcode = 'P0002', hint = 'INVENTORY_PURCHASE_ORDER_NOT_FOUND';
  end if;
  return jsonb_build_object('currency', v_row.currency::text, 'lines', coalesce((
    select jsonb_agg(jsonb_build_object('taxCode', z."tax_code", 'taxRateBps', z."tax_rate_bps",
      'net', z."net"::text, 'tax', z."tax"::text, 'gross', z."gross"::text) order by z."tax_rate_bps", z."tax_code")
    from "better_supabase"."purchase_order_tax_lines" z where z."purchase_order_id" = purchase_order_tax_lines.purchase_order), '[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purchase_requisition_decided (
  requisition uuid,
  approved    boolean
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."purchase_requisitions";
begin
  update "better_supabase"."purchase_requisitions" x set "status" = case when purchase_requisition_decided.approved then 'approved' else 'rejected' end,
    "decided_by" = auth.uid(), "decided_at" = now(), "updated_at" = now()
  where x."id" = purchase_requisition_decided.requisition and x."status" = 'pending'
  returning * into v_row;
  if found and purchase_requisition_decided.approved then
    perform "better_supabase".emit_event('purchase_requisition.approved', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'locationId', v_row."location_id", 'status', v_row."status", 'supplierType', v_row."supplier_type", 'supplierId', v_row."supplier_id"), 'purchase-requisitions/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/inventory');
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_ai_cache (
  batch integer DEFAULT 5000
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  delete from "better_supabase"."ai_cache_entries" x
  where x."key" in (
    select y."key" from "better_supabase"."ai_cache_entries" y
    where y."expires_at" <= now()
    order by y."expires_at"
    limit least(greatest(purge_ai_cache.batch, 1), 50000)
    for update skip locked
  );
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_ai_chats (
  batch integer DEFAULT 1000
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  if not coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then
    raise exception 'Only the server records this' using errcode = '42501', hint = 'AI_CHAT_FORBIDDEN';
  end if;
  with doomed as (
    select x."id" from "better_supabase"."ai_chats" x
    where x."is_temporary" and x."expires_at" <= now()
      and not "better_supabase"."is_held_memo"('ai_chats', (x."tenant_id")::text)
    limit greatest(coalesce(purge_ai_chats.batch, 1000), 1)
  )
  delete from "better_supabase"."ai_chats" c using doomed where c."id" = doomed."id";
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_ai_files (
  older_than interval DEFAULT '1 day'::interval,
  batch      integer  DEFAULT 500
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_removed jsonb;
begin
  with doomed as (
    select x."id" from "better_supabase"."ai_files" x
    where (x."status" = 'pending' and x."created_at" <= now() - coalesce(older_than, interval '1 day'))
      or x."expires_at" <= now()
      or (x."chat_id" is not null and not exists (select 1 from "better_supabase"."ai_chats" ch where ch."id" = x."chat_id"))
    limit greatest(coalesce(batch, 500), 1)
  ),
  gone as (
    delete from "better_supabase"."ai_files" x using doomed where x."id" = doomed."id"
    returning x."bucket" as bucket, x."path" as path
  )
  select coalesce(jsonb_agg(jsonb_build_object('bucket', gone.bucket, 'path', gone.path)), '[]'::jsonb) into v_removed from gone;
  return v_removed;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_audit_log (
  older_than interval DEFAULT '1 year'::interval,
  batch      integer  DEFAULT 10000,
  tenant     uuid     DEFAULT NULL::uuid,
  for_tenant boolean  DEFAULT false
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  purged integer := 0;
  gone integer;
  v_tenant uuid;
  v_older interval;
begin
  perform set_config('better_supabase.audit_purge', 'on', true);
  if not for_tenant and to_regprocedure('"public"."audit_retention"(uuid)') is not null then
    -- One delete per tenant with that tenant's interval as a constant, so
    -- each runs on the (tenant, occurred_at) index. The tenants come from a
    -- skip scan of that index, not a scan of the log.
    for v_tenant in
      with recursive t (v) as (
        (select l."tenant_id" from "better_supabase"."audit_events" l where l."tenant_id" is not null order by l."tenant_id" limit 1)
        union all
        select (select l."tenant_id" from "better_supabase"."audit_events" l where l."tenant_id" > t.v order by l."tenant_id" limit 1)
        from t where t.v is not null
      )
      select t.v from t where t.v is not null
    loop
      exit when purged >= batch;
      continue when "better_supabase"."is_held_memo"('audit', (v_tenant)::text);
      -- Not a literal name, so plpgsql_check passes without the hook.
      execute format('select %s($1)', to_regprocedure('"public"."audit_retention"(uuid)')::oid::regproc)
        into v_older using v_tenant;
      v_older := coalesce(v_older, coalesce("better_supabase"."retention_for_memo"('audit', (v_tenant)::text), older_than));
      with deleted as (
        delete from "better_supabase"."audit_events"
        where "id" in (
          select l."id" from "better_supabase"."audit_events" l
          where l."tenant_id" = v_tenant and l."occurred_at" < now() - v_older
          order by l."occurred_at"
          limit batch - purged
        )
        returning 1
      )
      select count(*)::integer into gone from deleted;
      purged := purged + gone;
    end loop;
    if purged < batch then
      with deleted as (
        delete from "better_supabase"."audit_events"
        where "id" in (
          select l."id" from "better_supabase"."audit_events" l
          where l."tenant_id" is null and (l."occurred_at" < now() - least(older_than, "better_supabase"."retention_floor"('audit'))
      and l."occurred_at" < now() - coalesce("better_supabase"."retention_for_memo"('audit', (null)::text), older_than)
      and not "better_supabase"."is_held_memo"('audit', (null)::text))
          order by l."occurred_at"
          limit batch - purged
        )
        returning 1
      )
      select count(*)::integer into gone from deleted;
      purged := purged + gone;
    end if;
  else
    with deleted as (
      delete from "better_supabase"."audit_events"
      where "id" in (
        select l."id" from "better_supabase"."audit_events" l
        where (l."occurred_at" < now() - least(older_than, "better_supabase"."retention_floor"('audit'))
      and l."occurred_at" < now() - coalesce("better_supabase"."retention_for_memo"('audit', (l."tenant_id")::text), older_than)
      and not "better_supabase"."is_held_memo"('audit', (l."tenant_id")::text))
          and (not for_tenant or l."tenant_id" is not distinct from purge_audit_log.tenant)
        order by l."occurred_at"
        limit greatest(batch - purged, 0)
      )
      returning 1
    )
    select purged + count(*)::integer into purged from deleted;
  end if;
  perform set_config('better_supabase.audit_purge', 'off', true);
  return purged;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_chat_state (
  batch integer DEFAULT 5000
)
  RETURNS integer
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_limit integer := greatest(coalesce(batch, 5000), 1);
  v_count integer := 0;
  v_rows integer;
begin
  delete from "better_supabase"."chat_state_locks" l where ctid in (select ctid from "better_supabase"."chat_state_locks" where "expires_at" <= clock_timestamp() limit v_limit);
  get diagnostics v_rows = row_count;
  v_count := v_count + v_rows;
  delete from "better_supabase"."chat_state_cache" c where ctid in (select ctid from "better_supabase"."chat_state_cache" where "expires_at" <= clock_timestamp() limit v_limit);
  get diagnostics v_rows = row_count;
  v_count := v_count + v_rows;
  delete from "better_supabase"."chat_state_lists" l where l."id" in (select "id" from "better_supabase"."chat_state_lists" where "expires_at" <= clock_timestamp() limit v_limit);
  get diagnostics v_rows = row_count;
  v_count := v_count + v_rows;
  delete from "better_supabase"."chat_state_queues" q where q."id" in (select "id" from "better_supabase"."chat_state_queues" where "expires_at" <= clock_timestamp() limit v_limit);
  get diagnostics v_rows = row_count;
  return v_count + v_rows;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_connector_sessions()
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  delete from "better_supabase"."connector_sessions" z where z."expires_at" < now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_contact (
  contact uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_ids uuid[];
  v_messages integer;
  v_paths jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select p."tenant_id" into v_tenant from "better_supabase"."people" p where p."id" = purge_contact.contact;
  if not found then
    raise exception 'contact not found' using errcode = 'P0002', hint = 'CONTACT_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_tenant, 'inbox.manage'), false)) then
    raise exception 'not allowed to erase contacts' using errcode = '42501', hint = 'INBOX_FORBIDDEN';
  end if;
  v_ids := array(select v."id" from "better_supabase"."inbox_conversations" v where v."contact_id" = purge_contact.contact);
  select count(*)::integer into v_messages from "better_supabase"."messages" m where m."conversation_id" = any (v_ids);
  with gone as (
    delete from "better_supabase"."attachments" x
    where (x."subject_type" = 'conversation' and x."subject_id" = any (array(select i::text from unnest(v_ids) i)))
      or (x."subject_type" = 'message' and x."subject_id" in (
        select m."id"::text from "better_supabase"."messages" m where m."conversation_id" = any (v_ids)))
    returning x."bucket" as bucket, x."object_path" as path, x."uploaded_at" as uploaded_at
  )
  select coalesce(jsonb_agg(jsonb_build_object('bucket', g.bucket, 'path', g.path)) filter (where g.uploaded_at is not null), '[]'::jsonb)
  into v_paths from gone g;
  delete from "better_supabase"."conversations" k where k."id" = any (v_ids);
  delete from "better_supabase"."person_identities" i where i."person_id" = purge_contact.contact;
  update "better_supabase"."people" p set "merged_into" = null where p."merged_into" = purge_contact.contact;
  delete from "better_supabase"."people" p where p."id" = purge_contact.contact;
  return jsonb_build_object('conversations', cardinality(v_ids), 'messages', v_messages, 'attachments', v_paths);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_expired_trash (
  max_batches integer DEFAULT 100
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_batch uuid;
  v_count integer := 0;
begin
  for v_batch in
    select t."batch_id" from "better_supabase"."trash_items" t
    where t."depth" = 0 and t."purge_at" <= now()
      and not "better_supabase"."is_held_memo"('trash', (t."tenant_id")::text)
    order by t."purge_at"
    limit greatest(coalesce(purge_expired_trash.max_batches, 100), 1)
  loop
    v_count := v_count + "better_supabase"."trash_purge_batch"(v_batch);
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_guardrail_decisions()
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  delete from "better_supabase"."guardrail_decisions" x where x."created_at" < now() - interval '90 days';
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_idempotency_keys()
  RETURNS integer
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  with purged as (
    delete from "better_supabase"."idempotency_keys" k where k."expires_at" < now() returning 1
  )
  select count(*)::integer from purged
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_inbound_events (
  older_than interval DEFAULT '30 days'::interval,
  batch      integer  DEFAULT 1000
)
  RETURNS integer
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  delete from "better_supabase"."inbox_inbound_events" e where e."id" in (
    select x."id" from "better_supabase"."inbox_inbound_events" x
    where (x."received_at" < now() - least(coalesce(older_than, interval '30 days'), "better_supabase"."retention_floor"('inbound_events'))
      and x."received_at" < now() - coalesce("better_supabase"."retention_for_memo"('inbound_events', (x."tenant_id")::text), coalesce(older_than, interval '30 days'))
      and not "better_supabase"."is_held_memo"('inbound_events', (x."tenant_id")::text))
      and x."status" in ('processed', 'ignored')
    limit greatest(coalesce(batch, 1000), 1)
  );
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_job_archive (
  queue           text,
  older_than      interval DEFAULT '7 days'::interval,
  batch           integer  DEFAULT 10000,
  dead_older_than interval DEFAULT '30 days'::interval
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  purged integer;
begin
  if "better_supabase"."is_held_memo"('job_archive', (null)::text) then
    return 0;
  end if;
  older_than := coalesce("better_supabase"."retention_for_memo"('job_archive', (null)::text), older_than);
  dead_older_than := coalesce("better_supabase"."retention_for_memo"('job_archive', (null)::text), dead_older_than);
  execute format(
    'with purged as (delete from pgmq.%1$I where msg_id in (select a.msg_id from pgmq.%1$I a where a.archived_at < now() - case when a.message ? ''dead'' then $3 else $1 end order by a.msg_id limit $2) returning 1) select count(*)::integer from purged',
    'a_' || queue
  ) into purged using older_than, batch, dead_older_than;
  return purged;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_memories (
  retention_days integer DEFAULT 30,
  batch          integer DEFAULT 1000,
  tenant         uuid    DEFAULT NULL::uuid
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  delete from "better_supabase"."memories" x
  where x."id" in (
    select y."id" from "better_supabase"."memories" y
    where (purge_memories.tenant is null or y."tenant_id" = purge_memories.tenant)
      and (y."archived_at" < now() - make_interval(days => greatest(purge_memories.retention_days, 0)) or y."expires_at" < now())
    limit least(greatest(purge_memories.batch, 1), 10000)
  );
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_memory_documents (
  batch integer DEFAULT 1000
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  delete from "better_supabase"."memory_documents" x
  where (x."scope_key", x."path") in (
    select y."scope_key", y."path" from "better_supabase"."memory_documents" y
    where y."expires_at" <= now()
    limit least(greatest(purge_memory_documents.batch, 1), 10000)
  );
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_notifications (
  older_than interval DEFAULT '90 days'::interval,
  batch      integer  DEFAULT 10000
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare v_purged integer;
begin
  delete from "better_supabase"."notification_events"
  where "id" in (
    select ev."id" from "better_supabase"."notification_events" ev
    where (ev."created_at" < now() - least(coalesce(older_than, '90 days'), "better_supabase"."retention_floor"('notifications'))
      and ev."created_at" < now() - coalesce("better_supabase"."retention_for_memo"('notifications', (ev."tenant_id")::text), coalesce(older_than, '90 days'))
      and not "better_supabase"."is_held_memo"('notifications', (ev."tenant_id")::text))
    order by ev."created_at"
    limit coalesce(batch, 10000)
  );
  get diagnostics v_purged = row_count;
  return v_purged;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_organization (
  tenant uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."organization_deletions";
  v_table record;
  v_type text;
  v_count bigint;
  v_deleted jsonb := '{}'::jsonb;
  v_pending text[];
  v_left text[];
  v_name text;
  v_pass integer;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'Only the service role purges organizations' using errcode = '42501', hint = 'ORGANIZATION_DELETION_FORBIDDEN';
  end if;
  select * into v_row from "better_supabase"."organization_deletions" x
  where x."tenant_id" = purge_organization.tenant and x."cancelled_at" is null and x."purged_at" is null
  for update;
  if v_row."tenant_id" is null or v_row."purge_at" > now() then
    raise exception 'No due deletion for this organization' using errcode = 'P0002', hint = 'ORGANIZATION_DELETION_NOT_DUE';
  end if;
  if exists (
    select 1 from "better_supabase"."legal_holds" x
    where x."released_at" is null
      and (x."tenant_id" is null or x."tenant_id" = purge_organization.tenant)
  ) then
    raise exception 'A legal hold covers this organization, so it can''t be purged' using errcode = 'P0001', hint = 'ORGANIZATION_LEGAL_HOLD';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."on_organization_purge"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using purge_organization.tenant;
    end if;
  end;
  -- Tables go in reverse order; a table whose rows another table still
  -- references (a restricting foreign key) waits for a later pass.
  v_pending := array(
    select t.name from "better_supabase"."data_lifecycle_tables"() t
    where t.subject = 'organization' and t.purge and to_regclass(t.tbl) is not null
      and to_regclass(t.tbl) <> to_regclass('"better_supabase"."organization_deletions"') and to_regclass(t.tbl) is distinct from to_regclass('"public"."organizations"')
    order by (row_number() over ()) desc
  );
  perform set_config('better_supabase.purge_tenant', purge_organization.tenant::text, true);
  for v_pass in 1..10 loop
    exit when cardinality(v_pending) = 0;
    v_left := '{}';
    foreach v_name in array v_pending loop
      select * into v_table from "better_supabase"."data_lifecycle_tables"() t
      where t.subject = 'organization' and t.name = v_name;
      select pg_catalog.format_type(a.atttypid, a.atttypmod) into v_type
      from pg_catalog.pg_attribute a
      where a.attrelid = to_regclass(v_table.tbl) and a.attname = v_table.col and not a.attisdropped;
      begin
        execute format('delete from %s t where t.%I = $1::%s', v_table.tbl, v_table.col, v_type)
          using purge_organization.tenant::text;
        get diagnostics v_count = row_count;
        v_deleted := v_deleted || jsonb_build_object(v_name, coalesce((v_deleted ->> v_name)::bigint, 0) + v_count);
      exception when foreign_key_violation or restrict_violation or check_violation then
        -- Another table's rows still point here (or a set null action breaks
        -- a check on them): try again after the other tables.
        v_left := v_left || v_name;
      end;
    end loop;
    if v_left = v_pending then
      raise exception 'Rows in % still have references the purge does not delete', array_to_string(v_left, ', ')
        using errcode = '23503', hint = 'ORGANIZATION_PURGE_BLOCKED';
    end if;
    v_pending := v_left;
  end loop;
  perform set_config('better_supabase.purge_tenant', '', true);
  update "better_supabase"."organization_deletions" x set "purged_at" = now() where x."tenant_id" = v_row."tenant_id" returning * into v_row;
  begin
    delete from "public"."organizations" where "id" = purge_organization.tenant;
  exception when foreign_key_violation or restrict_violation then
    raise exception 'Rows still reference the organization: %', sqlerrm
      using errcode = '23503', hint = 'ORGANIZATION_PURGE_BLOCKED';
  end;
  perform "better_supabase".emit_event('organization.purged', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'userId', null::uuid, 'purgeAfter', v_row."purge_at"), 'organizations/' || v_row."tenant_id"::text, (null)::text, 'organization.purged:' || v_row."tenant_id"::text, 'better-supabase/data-lifecycle');
  perform better_supabase.audit_event(
    event_type => 'organization.purged',
    category => 'data',
    target_type => 'organization',
    record_id => v_row."tenant_id"::text,
    tenant => (null)::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'userId', null::uuid, 'purgeAfter', v_row."purge_at"),
    idempotency_key => 'organization.purged:' || v_row."tenant_id"::text
  );
  return jsonb_build_object('organizationId', v_row."tenant_id"::text, 'deleted', v_deleted);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_outbox (
  older_than  interval DEFAULT '30 days'::interval,
  batch       integer  DEFAULT 10000,
  ignore_idle interval DEFAULT NULL::interval
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_purged integer;
begin
  with active as (
    select k."cursor_xid", k."cursor_position" from "better_supabase"."outbox_consumers" k
    where ignore_idle is null or k."updated_at" >= now() - ignore_idle
  ),
  letters as (
    delete from "better_supabase"."outbox_dead_letters" x
    where (x."dead_at" < now() - least(coalesce(older_than, '30 days'::interval), "better_supabase"."retention_floor"('outbox'))
      and x."dead_at" < now() - coalesce("better_supabase"."retention_for_memo"('outbox', (null)::text), coalesce(older_than, '30 days'::interval))
      and not "better_supabase"."is_held_memo"('outbox', (null)::text))
  ),
  gone as (
    delete from "better_supabase"."outbox_events" e
    where e."id" in (
      select d."id" from "better_supabase"."outbox_events" d
      where (d."created_at" < now() - least(coalesce(older_than, '30 days'::interval), "better_supabase"."retention_floor"('outbox'))
      and d."created_at" < now() - coalesce("better_supabase"."retention_for_memo"('outbox', (d."tenant_id")::text), coalesce(older_than, '30 days'::interval))
      and not "better_supabase"."is_held_memo"('outbox', (d."tenant_id")::text))
        and (
          not exists (select 1 from active)
          or (d."xid", d."position") <= (
            select a."cursor_xid", a."cursor_position" from active a
            order by a."cursor_xid", a."cursor_position"
            limit 1
          )
        )
      order by d."created_at"
      limit coalesce(batch, 10000)
    )
    returning 1
  )
  select count(*)::integer into v_purged from gone;
  return v_purged;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_rate_limits (
  batch integer DEFAULT 10000
)
  RETURNS integer
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  with expired as (
    select l."scope", l."key" from "better_supabase"."rate_limits" l
    left join "better_supabase"."rate_limit_rules" r on r."scope" = l."scope" and r."tenant_id" is null
    where l."window_started_at" + coalesce(l."period", r."period", interval '1 day') <= now()
    limit batch
  ),
  purged as (
    delete from "better_supabase"."rate_limits" l
    using expired e
    where l."scope" = e.scope and l."key" = e.key
    returning 1
  )
  select count(*)::integer from purged
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_shared_signals (
  older_than interval DEFAULT NULL::interval
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_cutoff timestamptz := now() - coalesce(purge_shared_signals.older_than, '7 days'::interval);
  v_received integer;
  v_events integer;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role manages shared signals streams' using errcode = '42501', hint = 'SSF_FORBIDDEN';
  end if;
  delete from "better_supabase"."ssf_received" x where x."received_at" < v_cutoff;
  get diagnostics v_received = row_count;
  delete from "better_supabase"."ssf_events" q where q."created_at" < v_cutoff;
  get diagnostics v_events = row_count;
  return v_received + v_events;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_signing_keys (
  grace interval DEFAULT NULL::interval
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role manages signing keys' using errcode = '42501', hint = 'SIGNING_KEYS_FORBIDDEN';
  end if;
  delete from "better_supabase"."signing_keys" k
  where k."state" = 'retired' and not (k."state" = 'active' or k."publish_expires_at" + coalesce(grace, '5 minutes'::interval) > now());
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_streams (
  older_than interval DEFAULT '1 day'::interval,
  batch      integer  DEFAULT 1000
)
  RETURNS integer
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_count integer;
begin
  with doomed as (
    select "id" from "better_supabase"."streams"
    where "expires_at" <= now()
      or "closed_at" <= now() - coalesce(older_than, interval '1 day')
    limit greatest(coalesce(batch, 1000), 1)
  )
  delete from "better_supabase"."streams" st using doomed where st."id" = doomed."id";
  get diagnostics v_count = row_count;
  delete from "better_supabase"."stream_entries" where "expires_at" <= now();
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_trash (
  item_id uuid
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_batch uuid;
begin
  select "tenant_id", "batch_id" into v_tenant, v_batch from "better_supabase"."trash_items" where "id" = purge_trash.item_id;
  if v_batch is null then
    raise exception 'trash item not found' using errcode = 'P0002', hint = 'TRASH_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_tenant, 'trash.manage'), false)) then
    raise exception 'not allowed to empty the trash' using errcode = '42501', hint = 'TRASH_FORBIDDEN';
  end if;
  return "better_supabase"."trash_purge_batch"(v_batch);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_usage_events (
  older_than interval DEFAULT '30 days'::interval,
  batch      integer  DEFAULT 10000
)
  RETURNS integer
  LANGUAGE sql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  with gone as (
    delete from "better_supabase"."usage_events" x
    where (x."tenant_id", x."meter", x."idempotency_key") in (
      select e."tenant_id", e."meter", e."idempotency_key" from "better_supabase"."usage_events" e
      where e."recorded_at" < now() - coalesce(older_than, '30 days')
      order by e."recorded_at" limit coalesce(batch, 10000)
    )
    returning 1
  )
  select count(*)::integer from gone
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_usage_history (
  older_than interval DEFAULT '400 days'::interval,
  batch      integer  DEFAULT 10000
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  purged integer;
begin
  with gone as (
    delete from "better_supabase"."usage_history" where "id" in (
      select h."id" from "better_supabase"."usage_history" h
      where (h."recorded_at" < now() - least(older_than, "better_supabase"."retention_floor"('usage'))
      and h."recorded_at" < now() - coalesce("better_supabase"."retention_for_memo"('usage', (h."tenant_id")::text), older_than)
      and not "better_supabase"."is_held_memo"('usage', (h."tenant_id")::text))
      order by h."id" limit batch
    )
    returning 1
  )
  select count(*)::integer into purged from gone;
  return purged;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_webhook_deliveries (
  older_than   interval DEFAULT '30 days'::interval,
  include_dead boolean  DEFAULT false,
  batch        integer  DEFAULT 10000
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_purged integer;
begin
  with purged as (
    delete from "better_supabase"."webhook_deliveries"
    where "id" in (
      select v."id" from "better_supabase"."webhook_deliveries" v
      where (v."created_at" < now() - least(purge_webhook_deliveries.older_than, "better_supabase"."retention_floor"('webhook_deliveries'))
      and v."created_at" < now() - coalesce("better_supabase"."retention_for_memo"('webhook_deliveries', (v."tenant_id")::text), purge_webhook_deliveries.older_than)
      and not "better_supabase"."is_held_memo"('webhook_deliveries', (v."tenant_id")::text))
        and (
          v."status" in ('succeeded', 'canceled')
          or (purge_webhook_deliveries.include_dead and v."status" = 'dead')
        )
      limit purge_webhook_deliveries.batch
    )
    returning 1
  )
  select count(*)::integer into v_purged from purged;
  return v_purged;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_webhooks (
  older_than   interval DEFAULT '30 days'::interval,
  include_dead boolean  DEFAULT false,
  batch        integer  DEFAULT 10000,
  for_tenant   text     DEFAULT NULL::text
)
  RETURNS integer
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_purged integer;
begin
  with purged as (
    delete from better_supabase.webhook_inbox
    where id in (
      select w.id from better_supabase.webhook_inbox w
      where ((w.status = 'processed' and (w.processed_at < now() - least(older_than, "better_supabase"."retention_floor"('webhooks'))
      and w.processed_at < now() - coalesce("better_supabase"."retention_for_memo"('webhooks', (w.tenant)::text), older_than)
      and not "better_supabase"."is_held_memo"('webhooks', (w.tenant)::text)))
        or (include_dead and w.status = 'dead' and (w.received_at < now() - least(older_than, "better_supabase"."retention_floor"('webhooks'))
      and w.received_at < now() - coalesce("better_supabase"."retention_for_memo"('webhooks', (w.tenant)::text), older_than)
      and not "better_supabase"."is_held_memo"('webhooks', (w.tenant)::text))))
        and (for_tenant is null or w.tenant = for_tenant)
      order by w.id
      limit batch
    )
    returning 1
  )
  select count(*)::integer into v_purged from purged;
  return v_purged;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.purge_workflow_runs (
  older_than interval DEFAULT '30 days'::interval,
  batch      integer  DEFAULT 1000
)
  RETURNS integer
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_runs integer;
begin
  with doomed as (
    select "id" from "better_supabase"."workflow_runs"
    where "status" in ('completed', 'failed', 'cancelled')
      and (coalesce("completed_at", "updated_at") < now() - least(coalesce(older_than, interval '30 days'), "better_supabase"."retention_floor"('workflow_runs'))
      and coalesce("completed_at", "updated_at") < now() - coalesce("better_supabase"."retention_for_memo"('workflow_runs', ("tenant_id")::text), coalesce(older_than, interval '30 days'))
      and not "better_supabase"."is_held_memo"('workflow_runs', ("tenant_id")::text))
    limit greatest(coalesce(batch, 1000), 1)
  )
  delete from "better_supabase"."workflow_runs" x using doomed where x."id" = doomed."id";
  get diagnostics v_runs = row_count;
  with doomed as (
    select "id" from "better_supabase"."workflow_start_requests"
    where "status" <> 'pending'
      and "created_at" < now() - coalesce(older_than, interval '30 days')
    limit greatest(coalesce(batch, 1000), 1)
  )
  delete from "better_supabase"."workflow_start_requests" x using doomed where x."id" = doomed."id";
  delete from "better_supabase"."workflow_semaphores" where "expires_at" < now();
  return v_runs;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.push_document_update (
  document_id uuid,
  payload     text
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_doc "better_supabase"."documents"%rowtype;
  v_bytes bytea;
  v_seq bigint;
  v_since bigint;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_doc from "better_supabase"."documents" d where d."id" = push_document_update.document_id;
  if not found then
    raise exception 'document not found' using errcode = 'P0002', hint = 'DOCUMENT_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'documents.write'), false) and case v_doc."subject_type"
    when 'message' then exists (select 1 from "better_supabase"."messages" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'messages.read'), false)
    when 'conversation' then exists (select 1 from "better_supabase"."conversations" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'messages.read'), false)
    when 'channel' then exists (select 1 from "better_supabase"."channels" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'messages.read'), false)
    when 'company' then exists (select 1 from "better_supabase"."companies" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'contacts.read'), false)
    when 'person' then exists (select 1 from "better_supabase"."people" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'contacts.read'), false)
    when 'deal' then exists (select 1 from "better_supabase"."deals" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'deals.read'), false)
    when 'course' then exists (select 1 from "better_supabase"."courses" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'courses.read'), false)
    when 'post' then exists (select 1 from "better_supabase"."posts" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'posts.read'), false)
    when 'activity' then exists (select 1 from "better_supabase"."activities" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'activities.read'), false)
    when 'quote' then exists (select 1 from "better_supabase"."quotes" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'quotes.read'), false)
    when 'work_item' then exists (select 1 from "better_supabase"."work_items" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'tasks.read'), false)
    when 'employee' then exists (select 1 from "better_supabase"."employees" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'employees.read'), false)
    when 'ledger_account' then exists (select 1 from "better_supabase"."ledger_accounts" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'ledger.read'), false)
    when 'invoice' then exists (select 1 from "better_supabase"."invoices" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'invoices.read'), false)
    when 'product' then exists (select 1 from "better_supabase"."products" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'catalog.read'), false)
    when 'product_variant' then exists (select 1 from "better_supabase"."product_variants" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'catalog.read'), false)
    when 'rfq' then exists (select 1 from "better_supabase"."rfqs" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'rfqs.read'), false)
    when 'till' then exists (select 1 from "better_supabase"."tills" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'tills.read'), false)
    when 'order' then exists (select 1 from "better_supabase"."orders" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'orders.read'), false)
    when 'calendar_event' then exists (select 1 from "better_supabase"."calendar_events" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'calendar.read'), false)
    when 'booking' then exists (select 1 from "better_supabase"."bookings" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'bookings.read'), false)
    when 'asset' then exists (select 1 from "better_supabase"."assets" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'assets.read'), false)
    when 'asset_location' then exists (select 1 from "better_supabase"."asset_locations" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'assets.read'), false)
    when 'lease' then exists (select 1 from "better_supabase"."leases" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'leases.read'), false)
    when 'expense_report' then exists (select 1 from "better_supabase"."expense_reports" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'expenses.read'), false)
    when 'expense_line' then exists (select 1 from "better_supabase"."expense_lines" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'expenses.read'), false)
    when 'donation_fund' then exists (select 1 from "better_supabase"."donation_funds" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'donations.read'), false)
    when 'warranty_claim' then exists (select 1 from "better_supabase"."warranty_claims" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'warranty.read'), false)
    when 'work_order' then exists (select 1 from "better_supabase"."work_orders" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'dispatch.read'), false)
    when 'shipment' then exists (select 1 from "better_supabase"."shipments" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'shipments.read'), false)
    when 'contract' then exists (select 1 from "better_supabase"."contracts" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'contracts.read'), false)
    when 'control' then exists (select 1 from "better_supabase"."controls" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'compliance.read'), false)
    when 'compliance_policy' then exists (select 1 from "better_supabase"."compliance_policies" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'compliance.read'), false)
    when 'qualification_type' then exists (select 1 from "better_supabase"."qualification_types" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'qualifications.read'), false)
    when 'risk' then exists (select 1 from "better_supabase"."risks" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'risks.read'), false)
    when 'case' then exists (select 1 from "better_supabase"."cases" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'cases.read'), false)
    when 'inspection' then exists (select 1 from "better_supabase"."inspections" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'inspections.read'), false)
    when 'inspection_program' then exists (select 1 from "better_supabase"."inspection_programs" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'inspections.read'), false)
    when 'inspection_finding' then exists (select 1 from "better_supabase"."inspection_findings" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'inspections.read'), false)
    when 'form' then exists (select 1 from "better_supabase"."forms" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'forms.read'), false)
    when 'meeting' then exists (select 1 from "better_supabase"."meetings" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'meetings.read'), false)
    when 'meeting_decision' then exists (select 1 from "better_supabase"."meeting_decisions" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'meetings.read'), false)
    when 'maintenance_plan' then exists (select 1 from "better_supabase"."maintenance_plans" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'maintenance.read'), false)
    when 'dam_usage_right' then exists (select 1 from "better_supabase"."dam_usage_rights" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'dam.read'), false)
    when 'lims_sample' then exists (select 1 from "better_supabase"."lims_samples" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'lims.read'), false)
    when 'tax_code' then exists (select 1 from "better_supabase"."tax_codes" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'tax.read'), false)
    when 'production_order' then exists (select 1 from "better_supabase"."production_orders" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'manufacturing.read'), false)
    when 'work_center' then exists (select 1 from "better_supabase"."work_centers" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'manufacturing.read'), false)
    when 'bank_account' then exists (select 1 from "better_supabase"."bank_accounts" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'banking.read'), false)
    when 'care_plan' then exists (select 1 from "better_supabase"."care_plans" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'care_plans.read'), false)
    when 'incident' then exists (select 1 from "better_supabase"."incidents" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'incidents.read'), false)
    when 'content_entry' then exists (select 1 from "better_supabase"."content_entries" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'content.read'), false)
    when 'document' then exists (select 1 from "better_supabase"."documents" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'documents.read'), false)
    when 'customer' then exists (select 1 from "public"."customers" s where s."id" = (v_doc."subject_id")::uuid and s."organization_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'customers.read'), false)
    when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id" and (coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'drive.read'), false) and coalesce("better_supabase"."drive_node_readable"(s."id"), false)))
    when 'organization' then exists (select 1 from "public"."organizations" s where s."id" = (v_doc."subject_id")::uuid and s."id" = v_doc."tenant_id")
    when 'application' then exists (select 1 from "better_supabase"."applications" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'hiring.read'), false)
    when 'change_request' then exists (select 1 from "public"."change_requests" s where s."id" = (v_doc."subject_id")::uuid and s."organization_id" = v_doc."tenant_id")
    when 'project' then exists (select 1 from "public"."projects" s where s."id" = (v_doc."subject_id")::uuid and s."organization_id" = v_doc."tenant_id")
    when 'task' then exists (select 1 from "public"."tasks" s where s."id" = (v_doc."subject_id")::uuid and s."organization_id" = v_doc."tenant_id")
    else false
  end and case v_doc."subject_type"
    when 'message' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'messages.send'), false)
    when 'conversation' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'messages.send'), false)
    when 'channel' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'channels.manage'), false)
    when 'company' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'contacts.write'), false)
    when 'person' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'contacts.write'), false)
    when 'deal' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'deals.write'), false)
    when 'course' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'courses.manage'), false)
    when 'post' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'posts.write'), false)
    when 'activity' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'activities.write'), false)
    when 'quote' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'quotes.write'), false)
    when 'work_item' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'tasks.write'), false)
    when 'employee' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'employees.write'), false)
    when 'ledger_account' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'ledger.manage'), false)
    when 'invoice' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'invoices.write'), false)
    when 'product' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'catalog.manage'), false)
    when 'product_variant' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'catalog.manage'), false)
    when 'rfq' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'rfqs.write'), false)
    when 'till' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'tills.write'), false)
    when 'order' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'orders.manage'), false)
    when 'calendar_event' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'calendar.write'), false)
    when 'booking' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'bookings.manage'), false)
    when 'asset' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'assets.manage'), false)
    when 'asset_location' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'assets.manage'), false)
    when 'lease' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'leases.manage'), false)
    when 'expense_report' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'expenses.manage'), false)
    when 'expense_line' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'expenses.manage'), false)
    when 'donation_fund' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'donations.manage'), false)
    when 'warranty_claim' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'warranty.write'), false)
    when 'work_order' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'dispatch.manage'), false)
    when 'shipment' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'shipments.manage'), false)
    when 'contract' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'contracts.write'), false)
    when 'control' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'compliance.manage'), false)
    when 'compliance_policy' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'compliance.manage'), false)
    when 'qualification_type' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'qualifications.manage'), false)
    when 'risk' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'risks.write'), false)
    when 'case' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'cases.write'), false)
    when 'inspection' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'inspections.write'), false)
    when 'inspection_program' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'inspections.manage'), false)
    when 'inspection_finding' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'inspections.write'), false)
    when 'form' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'forms.manage'), false)
    when 'meeting' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'meetings.write'), false)
    when 'meeting_decision' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'meetings.write'), false)
    when 'maintenance_plan' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'maintenance.manage'), false)
    when 'dam_usage_right' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'dam.write'), false)
    when 'lims_sample' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'lims.write'), false)
    when 'tax_code' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'tax.manage'), false)
    when 'production_order' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'manufacturing.write'), false)
    when 'work_center' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'manufacturing.manage'), false)
    when 'bank_account' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'banking.manage'), false)
    when 'care_plan' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'care_plans.write'), false)
    when 'incident' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'incidents.write'), false)
    when 'content_entry' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'content.write'), false)
    when 'document' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'documents.write'), false)
    when 'customer' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'customers.write'), false)
    when 'drive_node' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'drive.manage'), false)
    when 'application' then coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'hiring.write'), false)
    else true
  end)) then
    raise exception 'not allowed to edit this document' using errcode = '42501', hint = 'DOCUMENT_FORBIDDEN';
  end if;
  begin
    v_bytes := decode(push_document_update.payload, 'base64');
  exception when others then
    raise exception 'the update must be base64' using errcode = '22023', hint = 'DOCUMENT_UPDATE_INVALID';
  end;
  if v_bytes is null or length(v_bytes) = 0 then
    raise exception 'the update is empty' using errcode = '22023', hint = 'DOCUMENT_UPDATE_INVALID';
  end if;
  if length(v_bytes) > 1048576 then
    raise exception 'an update can be at most 1048576 bytes' using errcode = '54000', hint = 'DOCUMENT_UPDATE_TOO_LARGE';
  end if;
  insert into "better_supabase"."document_updates" ("document_id", "tenant_id", "payload", "actor")
  values (v_doc."id", v_doc."tenant_id", v_bytes, auth.uid())
  returning "seq" into v_seq;
  update "better_supabase"."documents" d set "updated_at" = now() where d."id" = v_doc."id";
  select count(*) into v_since from "better_supabase"."document_updates" x
  where x."document_id" = v_doc."id"
    and x."seq" > coalesce((select y."seq" from "better_supabase"."document_snapshots" y where y."document_id" = v_doc."id"), 0);
  if v_since = 200 then
    perform "better_supabase"."enqueue_job"(queue => 'documents.compact', payload => jsonb_build_object('documentId', v_doc."id"), dedupe_key => 'documents.compact:' || v_doc."id"::text, dedupe_running => false);
  end if;
  return v_seq;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.push_tickets_for (
  delivery uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role reads push tickets' using errcode = '42501', hint = 'PUSH_FORBIDDEN';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'token', x."token",
      'id', x."ticket_id",
      'error', x."error"
    )) order by x."created_at", x."token"), '[]'::jsonb)
    from "better_supabase"."push_tickets" x
    where x."delivery_id" = push_tickets_for.delivery
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.push_tokens_for (
  users uuid[]
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role reads push tokens' using errcode = '42501', hint = 'PUSH_FORBIDDEN';
  end if;
  if push_tokens_for.users is null or cardinality(push_tokens_for.users) > 1000 then
    raise exception 'pass at most 1000 values' using errcode = '22023', hint = 'PUSH_TOO_MANY';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'userId', x."user_id",
      'token', x."token",
      'platform', x."platform",
      'provider', x."provider"
    ) order by x."user_id", x."last_seen_at" desc), '[]'::jsonb)
    from "better_supabase"."push_devices" x
    where x."user_id" = any (push_tokens_for.users)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.putaway_plan (
  plan_tenant   uuid,
  plan_location uuid,
  plan_variant  uuid,
  plan_quantity numeric
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_left numeric := plan_quantity;
  v_size numeric;
  v_room numeric;
  v_take numeric;
  v_placements jsonb := '[]'::jsonb;
  rec record;
begin
  select coalesce((select x."size" from "better_supabase"."variant_sizes" x where x."variant_id" = plan_variant), 1) into v_size;
  for rec in
    with held as (
      select c."bin_id" as bin,
        coalesce(sum(c."on_hand") filter (where c."variant_id" = plan_variant), 0) as of_variant,
        sum(c."on_hand" * coalesce(sz."size", 1)) as used
      from "better_supabase"."stock_buckets" c left join "better_supabase"."variant_sizes" sz on sz."variant_id" = c."variant_id"
      where c."tenant_id" = plan_tenant and c."location_id" = plan_location and c."bin_id" is not null
      group by c."bin_id"
    ),
    cand as (
      select distinct on (y.bin) y.bin, y.tier, y.rank, y.rule_id, y.max_quantity
      from (
        select x."bin_id" as bin, case when x."variant_id" is null then 1 else 0 end as tier,
          x."priority" as rank, x."id" as rule_id, x."max_quantity" as max_quantity
        from "better_supabase"."putaway_rules" x
        where x."tenant_id" = plan_tenant and x."location_id" = plan_location and x."active"
          and (x."variant_id" is null or x."variant_id" = plan_variant)
        union all
        select h.bin, 2, 0, null::uuid, null::numeric from held h where h.of_variant > 0
        union all
        select x."id", 3, coalesce(sl."walk_rank", 100001), null::uuid, null::numeric
        from "better_supabase"."stock_bins" x left join "better_supabase"."bin_slots" sl on sl."bin_id" = x."id"
        where x."tenant_id" = plan_tenant and x."location_id" = plan_location
      ) y
      order by y.bin, y.tier, y.rank
    )
    select c.bin, bn."code" as code, c.tier, c.rank, c.rule_id, c.max_quantity,
      coalesce(h.of_variant, 0) as of_variant, coalesce(h.used, 0) as used, sl."capacity" as capacity
    from cand c
    join "better_supabase"."stock_bins" bn on bn."id" = c.bin
    left join held h on h.bin = c.bin
    left join "better_supabase"."bin_slots" sl on sl."bin_id" = c.bin
    where bn."active" and not bn."hold" and bn."location_id" = plan_location and bn."tenant_id" = plan_tenant
    order by c.tier, c.rank, case when c.tier = 2 then -coalesce(h.of_variant, 0) else coalesce(h.used, 0) end, bn."code"
  loop
    exit when v_left <= 0;
    v_room := least(
      case when rec.max_quantity is null then 'Infinity'::numeric else rec.max_quantity - rec.of_variant end,
      case when rec.capacity is null then 'Infinity'::numeric else (rec.capacity - rec.used) / v_size end
    );
    continue when v_room <= 0;
    v_take := least(v_left, trunc(v_room, 6));
    continue when v_take <= 0;
    v_placements := v_placements || jsonb_build_object('binId', rec.bin, 'binCode', rec.code,
      'quantity', v_take::text, 'source', case when rec.tier < 2 then 'rule' when rec.tier = 2 then 'stock' else 'free' end,
      'ruleId', rec.rule_id);
    v_left := v_left - v_take;
  end loop;
  return jsonb_build_object('locationId', plan_location, 'variantId', plan_variant, 'quantity', plan_quantity::text,
    'placements', v_placements, 'unassigned', v_left::text);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.putaway_rule_json (
  rule_id uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'locationId', x."location_id",
    'binId', x."bin_id", 'variantId', x."variant_id", 'priority', x."priority",
    'maxQuantity', x."max_quantity"::text, 'active', x."active", 'createdAt', x."created_at")
  from "better_supabase"."putaway_rules" x where x."id" = putaway_rule_json.rule_id
$function$;

CREATE OR REPLACE FUNCTION better_supabase.qualification_course_certificate()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_type "better_supabase"."qualification_types"%rowtype;
  v_row "better_supabase"."qualifications"%rowtype;
  v_on date;
begin
  if tg_op = 'INSERT' then
    if new."revoked_at" is not null then
      return null;
    end if;
    v_on := coalesce(new."issued_at", now())::date;
    for v_type in
      select * from "better_supabase"."qualification_types" y
      where y."tenant_id" = new."tenant_id" and y."course_id" = new."course_id"
        and y."archived_at" is null and 'member' = any(y."holder_types")
    loop
      if not exists (select 1 from "better_supabase"."qualifications" x where x."type_id" = v_type."id" and x."source" = 'course' and x."source_id" = new."id"::text) then
        insert into "better_supabase"."qualifications" ("tenant_id", "type_id", "holder_type", "holder_id", "granted_on", "expires_on", "source", "source_id")
        values (new."tenant_id", v_type."id", 'member', new."user_id"::text, v_on, greatest(v_on, coalesce(case when v_type."valid_for_months" is null then null else (v_on + make_interval(months => v_type."valid_for_months"))::date end, new."expires_at"::date)), 'course', new."id"::text)
        returning * into v_row;
        perform "better_supabase".emit_event('qualification.granted', jsonb_build_object('organizationId', v_row."tenant_id", 'qualificationId', v_row."id", 'qualificationTypeId', v_row."type_id", 'typeKey', v_type."key", 'holderType', v_row."holder_type", 'holderId', v_row."holder_id", 'grantedOn', v_row."granted_on", 'expiresOn', v_row."expires_on", 'source', v_row."source"), 'qualifications/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/qualifications');
  perform better_supabase.audit_event(
    event_type => 'qualification.granted',
    category => 'data',
    target_type => 'qualification',
    record_id => v_row."id"::text,
    target_label => v_type."name",
    summary => 'Qualification granted from a course certificate',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'qualificationId', v_row."id", 'qualificationTypeId', v_row."type_id", 'typeKey', v_type."key", 'holderType', v_row."holder_type", 'holderId', v_row."holder_id", 'grantedOn', v_row."granted_on", 'expiresOn', v_row."expires_on", 'source', v_row."source")
  );
      end if;
    end loop;
  elsif new."revoked_at" is not null and old."revoked_at" is null then
    for v_row in
      update "better_supabase"."qualifications" x set "revoked_at" = now(), "revoke_reason" = 'The course certificate was revoked', "updated_at" = now()
      where x."source" = 'course' and x."source_id" = new."id"::text and x."revoked_at" is null
      returning x.*
    loop
      select * into v_type from "better_supabase"."qualification_types" y where y."id" = v_row."type_id";
      perform "better_supabase".emit_event('qualification.revoked', jsonb_build_object('organizationId', v_row."tenant_id", 'qualificationId', v_row."id", 'qualificationTypeId', v_row."type_id", 'typeKey', v_type."key", 'holderType', v_row."holder_type", 'holderId', v_row."holder_id", 'reason', 'The course certificate was revoked'), 'qualifications/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/qualifications');
  perform better_supabase.audit_event(
    event_type => 'qualification.revoked',
    category => 'data',
    target_type => 'qualification',
    record_id => v_row."id"::text,
    target_label => v_type."name",
    summary => 'Qualification revoked with its course certificate',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'qualificationId', v_row."id", 'qualificationTypeId', v_row."type_id", 'typeKey', v_type."key", 'holderType', v_row."holder_type", 'holderId', v_row."holder_id", 'reason', 'The course certificate was revoked')
  );
    end loop;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.qualification_gaps (
  tenant      uuid,
  holder_type text  DEFAULT 'member'::text,
  filters     jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_filters jsonb := coalesce(qualification_gaps.filters, '{}'::jsonb);
  v_holder text := nullif(v_filters ->> 'holderId', '');
  v_team text := nullif(v_filters ->> 'teamId', '');
  v_type_key text := nullif(v_filters ->> 'typeKey', '');
  v_status text := nullif(v_filters ->> 'status', '');
  v_result jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', qualification_gaps.tenant, 'qualifications.read'), false)
    or (qualification_gaps.holder_type = 'member' and v_holder is not null and v_holder = (select auth.uid())::text and exists (select 1 from "public"."memberships" mm where mm."organization_id" = qualification_gaps.tenant and mm."user_id" = (select auth.uid())))) then
    raise exception 'not allowed to read qualifications' using errcode = '42501', hint = 'QUALIFICATION_FORBIDDEN';
  end if;
  if v_status is not null and v_status not in ('missing', 'expired', 'expiring') then
    raise exception 'status is missing, expired or expiring' using errcode = '22023', hint = 'QUALIFICATION_INVALID';
  end if;
  with holders as (
      select h.id, coalesce((select e."name" from "better_supabase"."employees" e where e."tenant_id" = qualification_gaps.tenant and e."user_id"::text = h.id limit 1), (select u.email::text from auth.users u where u.id::text = h.id), h.id) as title from (select ms."user_id"::text as id from "public"."memberships" ms where ms."organization_id" = qualification_gaps.tenant) h where qualification_gaps.holder_type = 'member'
      union all
      select h.id, coalesce((select c."name"::text from "better_supabase"."companies" c where c."id"::text = h.id), h.id) as title from (select cs."id"::text as id from "better_supabase"."companies" cs where cs."tenant_id" = qualification_gaps.tenant and cs."archived_at" is null and cs."merged_into" is null) h where qualification_gaps.holder_type = 'company'
      union all
      select h.id, coalesce((select a."name"::text from "better_supabase"."assets" a where a."id"::text = h.id), h.id) as title from (select s."id"::text as id from "better_supabase"."assets" s where s."tenant_id" = qualification_gaps.tenant and s."retired_at" is null) h where qualification_gaps.holder_type = 'asset'
  ), required as (
    select distinct h.id as holder_id, h.title, y."id" as type_id, y."key" as type_key, y."name" as type_name
    from holders h
    join "better_supabase"."qualification_types" y on y."tenant_id" = qualification_gaps.tenant and y."archived_at" is null and qualification_gaps.holder_type = any(y."holder_types")
      and (v_type_key is null or y."key" = v_type_key)
    join "better_supabase"."qualification_requirements" rq on rq."type_id" = y."id"
    where (v_holder is null or h.id = v_holder) and (v_team is null or (qualification_gaps.holder_type = 'member' and exists (select 1 from "better_supabase"."team_members" tm where tm."team_id"::text = v_team and tm."user_id"::text = h.id)))
      and case rq."target_type"::text
        when 'holder' then rq."target_value" = h.id
        when 'role' then qualification_gaps.holder_type = 'member' and exists (select 1 from "public"."memberships" m2 where m2."organization_id" = qualification_gaps.tenant and m2."user_id"::text = h.id and (select r."key" from "better_supabase"."roles" r where r."id" = m2."role")::text = rq."target_value")
        when 'team' then qualification_gaps.holder_type = 'member' and exists (select 1 from "better_supabase"."team_members" tq where tq."team_id"::text = rq."target_value" and tq."user_id"::text = h.id)
        when 'job_title' then qualification_gaps.holder_type = 'member' and exists (select 1 from "better_supabase"."employees" eq where eq."tenant_id" = qualification_gaps.tenant and eq."user_id"::text = h.id and lower(eq."job_title") = lower(rq."target_value"))
        when 'asset_kind' then qualification_gaps.holder_type = 'asset' and exists (select 1 from "better_supabase"."assets" aq where aq."id"::text = h.id and aq."kind"::text = rq."target_value")
        when 'segment' then qualification_gaps.holder_type = 'company' and exists (select 1 from "better_supabase"."segment_members" sq where sq."segment_id"::text = rq."target_value" and sq."subject_id"::text = h.id)
        else false
      end
  ), rated as (
    select rq.*, s.valid_until from required rq
    left join lateral (
      select max(coalesce(x."expires_on", 'infinity'::date)) as valid_until
      from "better_supabase"."qualifications" x
      where x."type_id" = rq.type_id and x."holder_type" = qualification_gaps.holder_type and x."holder_id" = rq.holder_id
        and x."revoked_at" is null and x."granted_on" <= current_date
    ) s on true
  ), gaps as (
    select rt.*, case
      when rt.valid_until is null then 'missing'
      when rt.valid_until < current_date then 'expired'
      when rt.valid_until <= current_date + 30 then 'expiring'
    end as status
    from rated rt
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'holderType', qualification_gaps.holder_type,
    'holderId', g.holder_id,
    'holderTitle', g.title,
    'typeKey', g.type_key,
    'typeName', g.type_name,
    'status', g.status,
    'expiresOn', case when g.status = 'missing' then null else g.valid_until end
  ) order by g.title, g.holder_id, g.type_name), '[]'::jsonb)
  into v_result
  from gaps g
  where g.status is not null and (v_status is null or g.status = v_status);
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.qualifications_of (
  holder_type text,
  holder_id   text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'qualificationTypeId', x."type_id", 'typeKey', y."key", 'typeName', y."name", 'holderType', x."holder_type", 'holderId', x."holder_id", 'grantedOn', x."granted_on", 'expiresOn', x."expires_on", 'revokedAt', x."revoked_at", 'revokeReason', x."revoke_reason", 'evidenceAttachmentId', x."evidence_attachment_id", 'evidenceNote', x."evidence_note", 'source', x."source", 'sourceId', x."source_id", 'grantedBy', x."granted_by", 'status', case
    when x."revoked_at" is not null then 'revoked'
    when x."expires_on" is not null and x."expires_on" < current_date then 'expired'
    when x."expires_on" is not null and x."expires_on" <= current_date + 30 then 'expiring'
    else 'valid'
  end, 'createdAt', x."created_at", 'updatedAt', x."updated_at") order by x."granted_on" desc, y."name"), '[]'::jsonb)
  from "better_supabase"."qualifications" x
  join "better_supabase"."qualification_types" y on y."id" = x."type_id"
  where x."holder_type" = qualifications_of.holder_type and x."holder_id" = qualifications_of.holder_id
$function$;

CREATE OR REPLACE FUNCTION better_supabase.qualified_holders (
  tenant      uuid,
  type_key    text,
  holder_type text DEFAULT 'member'::text,
  on_date     date DEFAULT CURRENT_DATE
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_on date := coalesce(qualified_holders.on_date, current_date);
  v_result jsonb;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', qualified_holders.tenant, 'qualifications.read'), false) or exists (select 1 from "public"."memberships" mm where mm."organization_id" = qualified_holders.tenant and mm."user_id" = (select auth.uid()))) then
    raise exception 'not allowed to read qualifications' using errcode = '42501', hint = 'QUALIFICATION_FORBIDDEN';
  end if;
  select coalesce(jsonb_agg(distinct x."holder_id" order by x."holder_id"), '[]'::jsonb)
  into v_result
  from "better_supabase"."qualifications" x
  join "better_supabase"."qualification_types" y on y."id" = x."type_id"
  where y."tenant_id" = qualified_holders.tenant and y."key" = qualified_holders.type_key
    and x."holder_type" = qualified_holders.holder_type
    and x."granted_on" <= v_on
    and (x."expires_on" is null or x."expires_on" >= v_on)
    and (x."revoked_at" is null or x."revoked_at"::date > v_on)
    and case x."holder_type"
      when 'member' then exists (select 1 from "public"."memberships" mh where mh."organization_id" = qualified_holders.tenant and mh."user_id"::text = x."holder_id")
      when 'company' then exists (select 1 from "better_supabase"."companies" c where c."tenant_id" = qualified_holders.tenant and c."id"::text = x."holder_id" and c."archived_at" is null and c."merged_into" is null)
      when 'asset' then exists (select 1 from "better_supabase"."assets" a where a."tenant_id" = qualified_holders.tenant and a."id"::text = x."holder_id")
      else false
    end;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.qualify_referral (
  tenant        uuid,
  referred_user uuid DEFAULT NULL::uuid,
  referred_org  uuid DEFAULT NULL::uuid,
  source        text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_ref "better_supabase"."referrals";
  v_tx uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (qualify_referral.tenant is not null and coalesce(better_supabase.can('tenant', qualify_referral.tenant, 'referrals.manage'), false))) then
    raise exception 'not allowed to qualify referrals' using errcode = '42501', hint = 'REFERRAL_FORBIDDEN';
  end if;
  select * into v_ref from "better_supabase"."referrals" x
  where x."tenant_id" = qualify_referral.tenant
    and ((qualify_referral.referred_user is not null and x."referred_id" = qualify_referral.referred_user)
      or (qualify_referral.referred_org is not null and x."referred_organization_id" = qualify_referral.referred_org))
  for update;
  if not found then
    return null;
  end if;
  if v_ref."status" <> 'attributed' then
    return jsonb_build_object('id', v_ref."id", 'organizationId', v_ref."tenant_id", 'codeId', v_ref."code_id", 'referrerId', v_ref."referrer_id", 'referredUserId', v_ref."referred_id", 'referredOrganizationId', v_ref."referred_organization_id", 'referredEmail', v_ref."referred_email", 'status', v_ref."status", 'rewardAmount', v_ref."reward_amount"::text, 'rewardUnit', v_ref."reward_unit", 'qualifiedAt', v_ref."qualified_at", 'rewardedAt', v_ref."rewarded_at", 'ledgerTransactionId', v_ref."ledger_transaction_id", 'createdAt', v_ref."created_at");
  end if;
  update "better_supabase"."referrals" x set "status" = 'qualified', "qualified_at" = now(), "qualified_by" = left(qualify_referral.source, 200)
  where x."id" = v_ref."id" returning * into v_ref;
  perform "better_supabase".emit_event('referral.qualified', jsonb_build_object('organizationId', v_ref."tenant_id", 'id', v_ref."id", 'codeId', v_ref."code_id", 'referrerId', v_ref."referrer_id", 'referredUserId', v_ref."referred_id", 'referredOrganizationId', v_ref."referred_organization_id", 'status', v_ref."status"), 'referrals/' || v_ref."id"::text, (v_ref."tenant_id")::text, null, 'better-supabase/referrals');
  perform better_supabase.audit_event(
    event_type => 'referral.qualified',
    category => 'data',
    target_type => 'referral',
    record_id => v_ref."id"::text,
    summary => 'referral qualified',
    tenant => (v_ref."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_ref."tenant_id", 'id', v_ref."id", 'codeId', v_ref."code_id", 'referrerId', v_ref."referrer_id", 'referredUserId', v_ref."referred_id", 'referredOrganizationId', v_ref."referred_organization_id", 'status', v_ref."status")
  );
  if v_ref."reward_amount" > 0 then
    v_tx := "better_supabase"."ledger_post"(v_ref."tenant_id", 'referral.reward',
      jsonb_build_array(
        jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_ref."tenant_id", 'expense', 'referrals:expense:' || v_ref."reward_unit", 'Referral rewards', v_ref."reward_unit", 0::smallint, null, null, null, true, 'referrals.read', 'referrals', null), 'amount', (-v_ref."reward_amount")::text),
        jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_ref."tenant_id", 'payable', 'referrals:rewards:' || v_ref."referrer_id"::text || ':' || v_ref."reward_unit", 'Referral rewards payable', v_ref."reward_unit", 0::smallint, null, null, v_ref."referrer_id", true, 'referrals.read', 'referrals', null), 'amount', v_ref."reward_amount"::text)),
      'referrals', v_ref."id"::text, null, 'referral:' || v_ref."id"::text, null,
      jsonb_build_object('referrerId', v_ref."referrer_id"));
    update "better_supabase"."referrals" x set "status" = 'rewarded', "rewarded_at" = now(), "ledger_transaction_id" = v_tx
    where x."id" = v_ref."id" returning * into v_ref;
    perform "better_supabase".emit_event('referral.rewarded', jsonb_build_object('organizationId', v_ref."tenant_id", 'id', v_ref."id", 'codeId', v_ref."code_id", 'referrerId', v_ref."referrer_id", 'referredUserId', v_ref."referred_id", 'referredOrganizationId', v_ref."referred_organization_id", 'status', v_ref."status", 'amount', v_ref."reward_amount"::text, 'unit', v_ref."reward_unit"), 'referrals/' || v_ref."id"::text, (v_ref."tenant_id")::text, null, 'better-supabase/referrals');
  perform better_supabase.audit_event(
    event_type => 'referral.rewarded',
    category => 'data',
    target_type => 'referral',
    record_id => v_ref."id"::text,
    summary => 'referral rewarded',
    tenant => (v_ref."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_ref."tenant_id", 'id', v_ref."id", 'codeId', v_ref."code_id", 'referrerId', v_ref."referrer_id", 'referredUserId', v_ref."referred_id", 'referredOrganizationId', v_ref."referred_organization_id", 'status', v_ref."status", 'amount', v_ref."reward_amount"::text, 'unit', v_ref."reward_unit")
  );
  end if;
  return jsonb_build_object('id', v_ref."id", 'organizationId', v_ref."tenant_id", 'codeId', v_ref."code_id", 'referrerId', v_ref."referrer_id", 'referredUserId', v_ref."referred_id", 'referredOrganizationId', v_ref."referred_organization_id", 'referredEmail', v_ref."referred_email", 'status', v_ref."status", 'rewardAmount', v_ref."reward_amount"::text, 'rewardUnit', v_ref."reward_unit", 'qualifiedAt', v_ref."qualified_at", 'rewardedAt', v_ref."rewarded_at", 'ledgerTransactionId', v_ref."ledger_transaction_id", 'createdAt', v_ref."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.queue_knowledge_file (
  tenant   uuid,
  file_id  uuid,
  title    text  DEFAULT NULL::text,
  scope    text  DEFAULT 'user'::text,
  scope_id uuid  DEFAULT NULL::uuid,
  source   text  DEFAULT NULL::text,
  metadata jsonb DEFAULT '{}'::jsonb,
  owner    uuid  DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_name text;
  v_document jsonb;
begin
  select x."filename" into v_name from "better_supabase"."ai_files" x
  where x."id" = queue_knowledge_file.file_id and x."tenant_id" = queue_knowledge_file.tenant;
  if not found then
    raise exception 'file % not found', queue_knowledge_file.file_id using errcode = 'P0002', hint = 'AI_FILE_NOT_FOUND';
  end if;
  v_document := "better_supabase"."create_knowledge_document"(queue_knowledge_file.tenant, coalesce(queue_knowledge_file.title, v_name), queue_knowledge_file.scope, queue_knowledge_file.scope_id, queue_knowledge_file.file_id, coalesce(queue_knowledge_file.source, v_name), queue_knowledge_file.metadata, queue_knowledge_file.owner);
  perform "better_supabase"."enqueue_job"(queue => 'knowledge_ingest', payload => jsonb_build_object('document_id', v_document ->> 'id'), dedupe_key => 'knowledge-ingest:' || (v_document ->> 'id'), dedupe_running => false);
  return v_document;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.queue_ssf_set (
  stream_id uuid,
  jti       text,
  token     text
)
  RETURNS text
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."ssf_streams";
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role manages shared signals streams' using errcode = '42501', hint = 'SSF_FORBIDDEN';
  end if;
  select * into v_row from "better_supabase"."ssf_streams" s where s."id" = queue_ssf_set.stream_id for update;
  if not found then
    raise exception 'stream not found' using errcode = 'P0002', hint = 'SSF_STREAM_NOT_FOUND';
  end if;
  if v_row."status" = 'disabled' then
    return 'dropped';
  end if;
  if v_row."delivery_method" = 'urn:ietf:rfc:8935' and v_row."status" = 'enabled' and exists (select 1 from "better_supabase"."webhook_endpoints" we where we."id" = v_row."endpoint_id" and we."enabled") then
    perform "better_supabase"."dispatch_webhook"(v_row."endpoint_id", 'ssf.set', jsonb_build_object('set', queue_ssf_set.token), null, queue_ssf_set.jti);
    return 'dispatched';
  end if;
  insert into "better_supabase"."ssf_events" ("stream_id", "jti", "token")
  values (v_row."id", queue_ssf_set.jti, queue_ssf_set.token)
  on conflict do nothing;
  return case when v_row."delivery_method" = 'urn:ietf:rfc:8936' and v_row."status" = 'enabled' then 'queued' else 'held' end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.quote_from_deal (
  deal uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_deal "better_supabase"."deals";
  v_row "better_supabase"."quotes";
  v_contact record;
  v_lines jsonb;
begin
  select * into v_deal from "better_supabase"."deals" x where x."id" = quote_from_deal.deal;
  if v_deal."id" is null or not ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', v_deal."tenant_id", 'quotes.write'), false)) then
    raise exception 'no such deal you can quote' using errcode = 'P0002', hint = 'QUOTE_ORIGIN_NOT_FOUND';
  end if;
  select * into v_row from "better_supabase"."quotes" x
  where x."origin_type" = 'deal' and x."origin_id" = v_deal."id"::text
  order by x."created_at" limit 1;
  if v_row."id" is not null then
    return (to_jsonb(v_row) - 'token_hash') || jsonb_build_object('number', v_row."number"::text, 'list_total', v_row."list_total"::text, 'discount_total', v_row."discount_total"::text, 'subtotal', v_row."subtotal"::text, 'tax_total', v_row."tax_total"::text, 'total', v_row."total"::text, 'discount_amount', v_row."discount_amount"::text, 'deposit_due', v_row."deposit_due"::text) || jsonb_build_object('lines', coalesce((select jsonb_agg(jsonb_build_object('position', ql."position", 'description', ql."description", 'quantity', ql."quantity", 'unitAmount', ql."unit_amount"::text, 'discountBps', ql."discount_bps", 'taxRateBps', ql."tax_rate_bps", 'taxCode', ql."tax_code", 'section', ql."section", 'optional', ql."optional", 'selected', ql."selected", 'periods', ql."periods", 'unit', ql."unit", 'discountKind', ql."discount_kind", 'product', case when ql."product_type" is null then null else jsonb_build_object('type', ql."product_type", 'id', ql."product_id") end) order by ql."position") from "better_supabase"."quote_lines" ql where ql."parent_id" = v_row."id"), '[]'::jsonb), 'taxLines', coalesce((select jsonb_agg(jsonb_build_object('taxRateBps', tl."tax_rate_bps", 'taxCode', tl."tax_code", 'net', tl."net"::text, 'tax', tl."tax"::text, 'gross', tl."gross"::text, 'discount', tl."discount"::text) order by tl."tax_rate_bps", tl."tax_code" nulls first) from "better_supabase"."quote_tax_lines" tl where tl."parent_id" = v_row."id"), '[]'::jsonb));
  end if;
  select x."contact_type" as type, x."contact_id" as id into v_contact
  from "better_supabase"."deal_contacts" x where x."deal_id" = v_deal."id" order by x."is_primary" desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('description', x."description", 'quantity', x."quantity", 'unitAmount', x."unit_amount"::text,
      'discountBps', x."discount_bps", 'taxRateBps', x."tax_rate_bps", 'taxCode', x."tax_code",
      'product', case when x."product_type" is null then null else jsonb_build_object('type', x."product_type", 'id', x."product_id") end
    ) order by x."position"), '[]'::jsonb) into v_lines
  from "better_supabase"."deal_lines" x where x."parent_id" = v_deal."id";
  if jsonb_array_length(v_lines) = 0 and v_deal."amount" > 0 then
    v_lines := jsonb_build_array(jsonb_build_object('description', v_deal."name", 'quantity', 1, 'unitAmount', v_deal."amount"::text));
  end if;
  return "better_supabase"."create_quote"(v_deal."tenant_id", jsonb_build_object(
    'title', v_deal."name", 'currency', v_deal."currency", 'ownerId', v_deal."owner_id",
    'company', case when v_deal."company_id" is null then null else jsonb_build_object('type', v_deal."company_type", 'id', v_deal."company_id") end,
    'contact', case when v_contact.id is null then null else jsonb_build_object('type', v_contact.type, 'id', v_contact.id) end,
    'origin', jsonb_build_object('type', 'deal', 'id', v_deal."id"::text)), v_lines);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.quote_totals_by_billing_party (
  quote uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(g.row order by g.party, g.party_id, g.account_id), '[]'::jsonb)
  from (
    select l."billing_party" as party, l."billing_party_id" as party_id, l."billing_account_id"::text as account_id,
      jsonb_build_object(
        'billingParty', l."billing_party", 'billingPartyId', l."billing_party_id", 'billingAccountId', l."billing_account_id"::text,
        'lines', count(*), 'net', sum((round(l."quantity" * coalesce(l."periods", 1) * l."unit_amount") - (round(round(l."quantity" * coalesce(l."periods", 1) * l."unit_amount") * l."discount_bps" / 10000.0) + least(coalesce(l."discount_amount", 0), greatest(round(l."quantity" * coalesce(l."periods", 1) * l."unit_amount") - round(round(l."quantity" * coalesce(l."periods", 1) * l."unit_amount") * l."discount_bps" / 10000.0), 0)))))::text, 'cost', sum(round(l."quantity" * l."unit_cost"))::text
      ) as row
    from "better_supabase"."quote_lines" l
    where l."parent_id" = quote and (not l."optional" or l."selected")
    group by 1, 2, 3
  ) g
$function$;

CREATE OR REPLACE FUNCTION better_supabase.quote_updated_at (
  subject_id text
)
  RETURNS timestamp WITH time zone
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
