  perform better_supabase.audit_event(
    event_type => 'prescription.dispensed',
    category => 'data',
    target_type => 'prescription',
    record_id => v_row."id"::text,
    target_label => v_row."status",
    summary => 'prescription dispensed',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'orderId', v_row."order_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'status', v_row."status")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'orderId', v_row."order_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'prescriberId', v_row."prescriber_id", 'prescriberName', v_row."prescriber_name", 'status', v_row."status", 'order', v_row."snapshot", 'signedBy', v_row."signed_by", 'signedAt', v_row."signed_at", 'gateway', v_row."gateway", 'gatewayReference', v_row."gateway_reference", 'sentAt', v_row."sent_at", 'deliveryError', v_row."delivery_error", 'dispensedAt', v_row."dispensed_at", 'cancelledAt', v_row."cancelled_at", 'cancelReason', v_row."cancel_reason", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_production_consumption (
  order_id uuid,
  variant  uuid,
  quantity numeric,
  detail   jsonb   DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."production_orders";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."production_orders" x where x."id" = record_production_consumption.order_id for update;
  if not found then
    raise exception 'no such production order' using errcode = 'P0002', hint = 'PRODUCTION_ORDER_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'manufacturing.produce'), false))) then
    raise exception 'not allowed to record production consumption' using errcode = '42501', hint = 'MANUFACTURING_FORBIDDEN';
  end if;
  if v_row."status" not in ('released', 'in_progress') then
    raise exception 'the production order can''t move from % to %', v_row."status", 'in_progress' using errcode = '55000', hint = 'PRODUCTION_ORDER_STATUS_INVALID', detail = jsonb_build_object('from', v_row."status", 'to', 'in_progress')::text;
  end if;
  if record_production_consumption.variant is null or not exists (select 1 from "better_supabase"."product_variants" cv where cv."id" = record_production_consumption.variant and cv."tenant_id" = v_row."tenant_id") then
    raise exception 'the variant isn''t a variant of this organization' using errcode = '22023', hint = 'PRODUCTION_ORDER_INVALID';
  end if;
  if record_production_consumption.quantity is null or record_production_consumption.quantity <= 0 then
    raise exception 'the quantity must be more than zero' using errcode = '22023', hint = 'PRODUCTION_ORDER_INVALID';
  end if;
  perform "better_supabase"."production_consume"(v_row."id", record_production_consumption.variant, record_production_consumption.quantity, record_production_consumption.detail);
  update "better_supabase"."production_orders" x set "status" = 'in_progress', "started_at" = coalesce(x."started_at", now()), "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  return (jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'number', v_row."number", 'variantId', v_row."variant_id", 'bomId', v_row."bom_id", 'quantity', v_row."quantity"::text, 'locationId', v_row."location_id", 'dueOn', v_row."due_on", 'status', v_row."status", 'producedQuantity', v_row."produced_quantity"::text, 'scrapQuantity', v_row."scrap_quantity"::text, 'outputLotId', v_row."output_lot_id", 'materialCost', v_row."material_cost"::text, 'laborCost', v_row."labor_cost"::text, 'currency', v_row."currency", 'note', v_row."note", 'releasedAt', v_row."released_at", 'startedAt', v_row."started_at", 'completedAt', v_row."completed_at", 'canceledAt', v_row."canceled_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at") || jsonb_build_object(
    'operations', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'orderId', y."order_id", 'operationId', y."operation_id", 'sequence', y."sequence", 'workCenterId', y."work_center_id", 'title', y."title", 'plannedMinutes', y."planned_minutes"::text, 'status', y."status", 'startedAt', y."started_at", 'finishedAt', y."finished_at", 'operatorId', y."operator_id", 'minutes', y."minutes"::text, 'inspectionId', y."inspection_id") order by y."sequence")
      from "better_supabase"."production_order_operations" y where y."order_id" = v_row."id"), '[]'::jsonb),
    'components', coalesce((select jsonb_agg(jsonb_build_object('componentId', y."id", 'variantId', y."variant_id",
        'quantity', "better_supabase"."production_quantity"(y."variant_id", y."quantity" * v_row."quantity" / x."quantity" * (1 + y."scrap_bps" / 10000.0))::text,
        'allocated', coalesce(al."allocated", 0)::text, 'backordered', coalesce(al."backordered", 0)::text,
        'consumed', coalesce((select sum(z."quantity") from "better_supabase"."production_consumptions" z
          where z."order_id" = v_row."id" and z."variant_id" = y."variant_id"), 0)::text)
      order by y."position", y."id")
      from "better_supabase"."boms" x join "better_supabase"."bom_components" y on y."bom_id" = x."id"
      left join "better_supabase"."stock_allocations" al on al."tenant_id" = v_row."tenant_id"
        and al."document_type" = 'production_order' and al."document_id" = v_row."id"::text
        and al."line_id" = y."id"::text and al."status" = 'open'
      where x."id" = v_row."bom_id"), '[]'::jsonb),
    'consumptions', coalesce((select jsonb_agg(jsonb_build_object('id', z."id", 'variantId', z."variant_id", 'lotId', z."lot_id",
        'serial', z."serial", 'quantity', z."quantity"::text, 'cost', z."cost"::text, 'currency', z."currency",
        'movementId', z."movement_id", 'createdAt', z."created_at") order by z."created_at", z."id")
      from "better_supabase"."production_consumptions" z where z."order_id" = v_row."id"), '[]'::jsonb)));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_push_tickets (
  delivery uuid,
  tickets  jsonb
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role reads push tickets' using errcode = '42501', hint = 'PUSH_FORBIDDEN';
  end if;
  if jsonb_typeof(record_push_tickets.tickets) <> 'array' or jsonb_array_length(record_push_tickets.tickets) > 1000 then
    raise exception 'pass at most 1000 tickets' using errcode = '22023', hint = 'PUSH_TOO_MANY';
  end if;
  insert into "better_supabase"."push_tickets" as x ("delivery_id", "token", "ticket_id", "status", "error")
  select record_push_tickets.delivery, e ->> 'token', e ->> 'id',
    case when e ->> 'id' is null then 'error' else 'pending' end,
    e ->> 'error'
  from jsonb_array_elements(record_push_tickets.tickets) e
  where e ->> 'token' is not null
  on conflict ("delivery_id", "token") do update set
    "ticket_id" = coalesce(excluded."ticket_id", x."ticket_id"),
    "status" = case when x."ticket_id" is not null then x."status" else excluded."status" end,
    "error" = case
      when x."ticket_id" is not null then x."error"
      when excluded."ticket_id" is not null then null
      else excluded."error"
    end;
  get diagnostics v_count = row_count;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_rendition (
  tenant  uuid,
  node_id uuid,
  kind    text,
  input   jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."dam_renditions";
  v_input jsonb := coalesce(record_rendition.input, '{}'::jsonb);
  v_status text := coalesce(nullif(v_input ->> 'status', ''), 'ready');
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (record_rendition.tenant is not null and coalesce(better_supabase.can('tenant', record_rendition.tenant, 'dam.write'), false))) then
    raise exception 'not allowed to record renditions' using errcode = '42501', hint = 'DAM_FORBIDDEN';
  end if;
  if jsonb_typeof(v_input) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'DAM_INVALID';
  end if;
  if record_rendition.kind is null or record_rendition.kind !~ '^[a-z][a-z0-9_]{0,40}$' then
    raise exception 'a rendition kind is lowercase letters, digits and underscores, up to 41 characters' using errcode = '22023', hint = 'DAM_INVALID';
  end if;
  if v_status not in ('pending', 'ready', 'failed') then
    raise exception 'the status is pending, ready or failed' using errcode = '22023', hint = 'DAM_INVALID';
  end if;
  begin
    insert into "better_supabase"."dam_renditions" ("tenant_id", "node_id", "kind", "status", "format", "width", "height", "size_bytes", "path", "error")
    values (record_rendition.tenant, record_rendition.node_id, record_rendition.kind, v_status,
      nullif(v_input ->> 'format', ''), (v_input ->> 'width')::integer, (v_input ->> 'height')::integer,
      (v_input ->> 'sizeBytes')::bigint, nullif(v_input ->> 'path', ''), nullif(v_input ->> 'error', ''))
    on conflict ("tenant_id", "node_id", "kind") do update set
      "status" = excluded."status", "format" = excluded."format", "width" = excluded."width",
      "height" = excluded."height", "size_bytes" = excluded."size_bytes", "path" = excluded."path",
      "error" = excluded."error", "updated_at" = now()
    returning * into v_row;
  exception when check_violation or not_null_violation or invalid_text_representation or numeric_value_out_of_range then
    raise exception 'a rendition has a format of up to 20 characters, a width and height above 0, a size of 0 or more and a path of up to 1000 characters' using errcode = '22023', hint = 'DAM_INVALID';
  end;
  perform "better_supabase".emit_event('dam_rendition.recorded', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'nodeId', v_row."node_id", 'kind', v_row."kind", 'status', v_row."status"), 'dam-renditions/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/dam');
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'nodeId', v_row."node_id", 'kind', v_row."kind", 'status', v_row."status", 'format', v_row."format", 'width', v_row."width", 'height', v_row."height", 'sizeBytes', v_row."size_bytes", 'path', v_row."path", 'error', v_row."error", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_rent_payment (
  lease_id  uuid,
  amount    bigint,
  paid_at   timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  reference text                     DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."leases"%rowtype;
  v_key text;
  v_tx uuid;
begin
  select * into v_row from "better_supabase"."leases" x where x."id" = record_rent_payment.lease_id;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'leases.manage'), false)) then
    raise exception 'no such lease you can read' using errcode = 'P0002', hint = 'LEASE_NOT_FOUND';
  end if;
  if v_row."status" = 'draft' then
    raise exception 'a draft lease takes no payments' using errcode = '55000', hint = 'LEASE_STATUS_INVALID';
  end if;
  if record_rent_payment.amount is null or record_rent_payment.amount <= 0 then
    raise exception 'a payment is more than zero minor units' using errcode = '22023', hint = 'LEASE_PAYMENT_INVALID';
  end if;
  v_key := case when nullif(trim(record_rent_payment.reference), '') is not null
    then 'leases.payment:' || v_row."id"::text || ':' || trim(record_rent_payment.reference) end;
  select x."id" into v_tx from "better_supabase"."ledger_transactions" x
    where x."tenant_id" = v_row."tenant_id" and x."idempotency_key" = v_key;
  if v_tx is null then
    v_tx := "better_supabase"."ledger_post"(v_row."tenant_id", 'lease.payment',
      jsonb_build_array(
        jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_row."tenant_id", 'rent_receivable', 'leases.rent:' || v_row."id"::text, 'Rent ' || v_row."title",
      v_row."currency"::text, 0::smallint, 'lease', v_row."id"::text, null, true, 'leases.read', 'leases',
      jsonb_build_object('leaseId', v_row."id")), 'amount', -record_rent_payment.amount),
        jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_row."tenant_id", 'rent_cash', 'leases.cash:' || v_row."currency", 'Rent received ' || v_row."currency",
      v_row."currency"::text, 0::smallint, null, null, null, true, 'leases.read', 'leases', null), 'amount', record_rent_payment.amount)),
      'leases', v_row."id"::text, 'Rent payment', v_key, record_rent_payment.paid_at,
      jsonb_strip_nulls(jsonb_build_object('leaseId', v_row."id", 'reference', nullif(trim(record_rent_payment.reference), ''))));
    if not better_supabase.import_run() is not null then
    perform "better_supabase"."accounting_post_source"('lease_payment', v_tx::text);
  end if;
    perform "better_supabase".emit_event('lease.paid', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'transactionId', v_tx, 'amount', record_rent_payment.amount::text, 'currency', v_row."currency"), 'leases/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/leases');
  perform better_supabase.audit_event(
    event_type => 'lease.paid',
    category => 'billing',
    target_type => 'lease',
    record_id => v_row."id"::text,
    target_label => v_row."title",
    summary => 'recorded a rent payment',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'transactionId', v_tx, 'amount', record_rent_payment.amount::text, 'currency', v_row."currency")
  );
  end if;
  return jsonb_build_object('transactionId', v_tx, 'leaseId', v_row."id", 'amount', record_rent_payment.amount::text,
    'currency', v_row."currency", 'balanceDue', coalesce((select y."balance" from "better_supabase"."ledger_accounts" x join "better_supabase"."ledger_balances" y on y."account_id" = x."id"
      where x."tenant_id" = v_row."tenant_id" and x."code" = 'leases.rent:' || v_row."id"::text), 0)::text);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_rfq_quote (
  rfq_id        uuid,
  invitation_id uuid,
  input         jsonb,
  lines         jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."rfqs";
  v_invitation "better_supabase"."rfq_suppliers";
  v_quote "better_supabase"."rfq_quotes";
  v_input jsonb := coalesce(record_rfq_quote.input, '{}'::jsonb);
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."rfqs" x where x."id" = record_rfq_quote.rfq_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'rfqs.read'), false))) then
    raise exception 'no such request for quotation' using errcode = 'P0002', hint = 'RFQ_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'rfqs.write'), false))) then
    raise exception 'not allowed to record quotes' using errcode = '42501', hint = 'RFQ_FORBIDDEN';
  end if;
  if v_row."status" <> 'open' then
    raise exception 'quotes can only be recorded on an open request' using errcode = '55000', hint = 'RFQ_STATUS';
  end if;
  select * into v_invitation from "better_supabase"."rfq_suppliers" y
  where y."id" = record_rfq_quote.invitation_id and y."rfq_id" = v_row."id" for update;
  if not found then
    raise exception 'no such invited supplier' using errcode = 'P0002', hint = 'RFQ_SUPPLIER_NOT_FOUND';
  end if;
  if v_invitation."status" = 'declined' then
    raise exception 'this supplier declined to quote' using errcode = '55000', hint = 'RFQ_STATUS';
  end if;
  if jsonb_typeof(v_input) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'RFQ_INVALID';
  end if;
  if jsonb_typeof(record_rfq_quote.lines) is distinct from 'array' or jsonb_array_length(record_rfq_quote.lines) = 0
    or exists (
      select 1 from jsonb_array_elements(record_rfq_quote.lines) e
      where jsonb_typeof(e) is distinct from 'object'
        or coalesce(e ->> 'lineId', '') !~ '^[0-9a-fA-F-]{36}$'
        or coalesce(e ->> 'unitAmount', '') !~ '^[0-9]{1,18}$'
    )
    or (select count(distinct e ->> 'lineId') from jsonb_array_elements(record_rfq_quote.lines) e) <> jsonb_array_length(record_rfq_quote.lines) then
    raise exception 'lines must be a non-empty list with a unique lineId and a unitAmount in minor units each' using errcode = '22023', hint = 'RFQ_INVALID';
  end if;
  if exists (
    select 1 from jsonb_array_elements(record_rfq_quote.lines) e
    where not exists (select 1 from "better_supabase"."rfq_lines" y where y."id" = (e ->> 'lineId')::uuid and y."rfq_id" = v_row."id")
  ) then
    raise exception 'a lineId is not a line of this request' using errcode = '22023', hint = 'RFQ_INVALID';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_rfq_quote_record"(uuid, jsonb)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::jsonb)', v_hook::oid::regproc)
        using record_rfq_quote.rfq_id, record_rfq_quote.input;
    end if;
  end;
  begin
    select * into v_quote from "better_supabase"."rfq_quotes" y
    where y."rfq_id" = v_row."id" and y."invitation_id" = v_invitation."id" for update;
    if found then
      delete from "better_supabase"."rfq_quote_lines" z where z."quote_id" = v_quote."id";
      update "better_supabase"."rfq_quotes" y set "status" = 'submitted', "total_amount" = 0,
        "lead_time_days" = (v_input ->> 'leadTimeDays')::integer, "valid_until" = (v_input ->> 'validUntil')::date,
        "notes" = nullif(trim(v_input ->> 'notes'), ''), "revision" = y."revision" + 1,
        "submitted_by" = auth.uid(), "submitted_at" = now(), "updated_at" = now()
      where y."id" = v_quote."id" returning * into v_quote;
    else
      insert into "better_supabase"."rfq_quotes" ("tenant_id", "rfq_id", "invitation_id", "total_amount", "lead_time_days", "valid_until", "notes", "submitted_by")
      values (v_row."tenant_id", v_row."id", v_invitation."id", 0, (v_input ->> 'leadTimeDays')::integer,
        (v_input ->> 'validUntil')::date, nullif(trim(v_input ->> 'notes'), ''), auth.uid())
      returning * into v_quote;
    end if;
    insert into "better_supabase"."rfq_quote_lines" ("tenant_id", "quote_id", "line_id", "unit_amount", "lead_time_days")
    select v_row."tenant_id", v_quote."id", (e ->> 'lineId')::uuid, (e ->> 'unitAmount')::bigint, (e ->> 'leadTimeDays')::integer
    from jsonb_array_elements(record_rfq_quote.lines) e;
    update "better_supabase"."rfq_quotes" y set "total_amount" = coalesce((
      select round(sum(z."unit_amount" * ln."quantity"))::bigint
      from "better_supabase"."rfq_quote_lines" z join "better_supabase"."rfq_lines" ln on ln."id" = z."line_id" where z."quote_id" = y."id"
    ), 0)
    where y."id" = v_quote."id" returning * into v_quote;
  exception when check_violation or invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then
    raise exception 'a quote needs a leadTimeDays of zero or more, a valid validUntil, notes of up to 4000 and unit amounts in minor units' using errcode = '22023', hint = 'RFQ_INVALID';
  end;
  update "better_supabase"."rfq_suppliers" y set "status" = 'quoted', "responded_at" = now() where y."id" = v_invitation."id";
  perform "better_supabase".emit_event('rfq_quote.submitted', jsonb_build_object('organizationId', v_quote."tenant_id", 'id', v_quote."id", 'rfqId', v_quote."rfq_id", 'invitationId', v_quote."invitation_id", 'total', v_quote."total_amount"::text), 'rfqs/' || v_quote."rfq_id"::text, (v_quote."tenant_id")::text, null, 'better-supabase/rfqs');
  perform better_supabase.audit_event(
    event_type => 'rfq_quote.submitted',
    category => 'data',
    target_type => 'rfq',
    record_id => v_quote."rfq_id"::text,
    target_label => v_row."number",
    summary => 'quote recorded',
    tenant => (v_quote."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_quote."tenant_id", 'id', v_quote."id", 'rfqId', v_quote."rfq_id", 'invitationId', v_quote."invitation_id", 'total', v_quote."total_amount"::text)
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_rfq_quote_record"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_quote."id";
    end if;
  end;
  return jsonb_build_object('id', v_quote."id", 'rfqId', v_quote."rfq_id", 'invitationId', v_quote."invitation_id", 'status', v_quote."status", 'currency', (select x."currency" from "better_supabase"."rfqs" x where x."id" = v_quote."rfq_id"), 'total', v_quote."total_amount"::text, 'leadTimeDays', v_quote."lead_time_days", 'validUntil', v_quote."valid_until", 'notes', v_quote."notes", 'revision', v_quote."revision", 'submittedBy', v_quote."submitted_by", 'submittedAt', v_quote."submitted_at", 'updatedAt', v_quote."updated_at") || jsonb_build_object('lines', coalesce((
    select jsonb_agg(jsonb_build_object('id', z."id", 'quoteId', z."quote_id", 'lineId', z."line_id", 'unitAmount', z."unit_amount"::text, 'leadTimeDays', z."lead_time_days") order by z."id") from "better_supabase"."rfq_quote_lines" z where z."quote_id" = v_quote."id"
  ), '[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_rule_evaluation (
  rule       uuid,
  subject_id text,
  matched    boolean,
  results    jsonb   DEFAULT '{}'::jsonb,
  mode       text    DEFAULT 'live'::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_rule "better_supabase"."automations";
  v_row "better_supabase"."automation_evaluations";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_rule from "better_supabase"."automations" x where x."id" = record_rule_evaluation.rule;
  if v_rule."id" is null then
    raise exception 'No rule has this id' using errcode = 'P0002', hint = 'AUTOMATION_NOT_FOUND';
  end if;
  if coalesce(record_rule_evaluation.mode, 'live') not in ('live', 'test') then
    raise exception 'mode is live or test' using errcode = '22023', hint = 'AUTOMATION_INVALID';
  end if;
  if coalesce(record_rule_evaluation.mode, 'live') = 'live' and not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'Only the service role records live evaluations' using errcode = '42501', hint = 'AUTOMATION_FORBIDDEN';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_rule."tenant_id", 'automations.write'), false)) then
    raise exception 'Testing rules needs the edit permission' using errcode = '42501', hint = 'AUTOMATION_FORBIDDEN';
  end if;
  insert into "better_supabase"."automation_evaluations" ("tenant_id", "rule_id", "version", "subject_type", "subject_id", "trigger", "matched", "results", "mode", "evaluated_by")
  values (v_rule."tenant_id", v_rule."id", v_rule."version", v_rule."subject_type", record_rule_evaluation.subject_id, v_rule."trigger",
    coalesce(record_rule_evaluation.matched, false), coalesce(record_rule_evaluation.results, '{}'::jsonb), coalesce(record_rule_evaluation.mode, 'live'), auth.uid())
  returning * into v_row;
  if v_row."mode" = 'live' and v_row."matched" then
    perform "better_supabase".emit_event('automation.matched', jsonb_build_object('organizationId', v_rule."tenant_id"::text, 'ruleId', v_rule."id"::text, 'version', v_rule."version", 'subjectType', v_rule."subject_type", 'subjectId', record_rule_evaluation.subject_id, 'trigger', v_rule."trigger"), 'rules/' || v_rule."id"::text, (v_rule."tenant_id")::text, null, 'better-supabase/automations');
  end if;
  return jsonb_build_object('id', v_row."id"::text, 'organizationId', v_row."tenant_id", 'ruleId', v_row."rule_id", 'version', v_row."version", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'trigger', v_row."trigger", 'matched', v_row."matched", 'results', v_row."results", 'mode', v_row."mode", 'evaluatedBy', v_row."evaluated_by", 'evaluatedAt', v_row."evaluated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_sent_mail (
  account uuid,
  message jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_account record;
  v_stored jsonb;
  v_thread uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select k."id" as id, k."tenant_id" as tenant, k."user_id" as owner into v_account
  from "better_supabase"."mail_accounts" k
  where k."id" = record_sent_mail.account and (k."user_id" = auth.uid() or coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) and k."status" <> 'disconnected';
  if v_account.id is null then
    raise exception 'no such mailbox of yours' using errcode = 'P0002', hint = 'MAIL_ACCOUNT_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) and not coalesce(better_supabase.can('tenant', v_account.tenant, 'mail_sync.send'), false) then
    raise exception 'not allowed to send mail' using errcode = '42501', hint = 'MAIL_FORBIDDEN';
  end if;
  v_stored := "better_supabase"."store_mail_message"(v_account.id, coalesce(record_sent_mail.message, '{}'::jsonb) || '{"direction": "outbound"}'::jsonb);
  v_thread := (v_stored ->> 'threadId')::uuid;
  perform "better_supabase"."match_mail_thread"(v_thread);
  perform "better_supabase"."log_mail_thread"(v_thread);
  if (v_stored ->> 'created')::boolean then
    if jsonb_typeof(record_sent_mail.message -> 'trackedLinks') = 'array' then
      insert into "better_supabase"."mail_tracked_links" ("tenant_id", "message_id", "position", "url")
      select v_account.tenant, (v_stored ->> 'id')::uuid, (u.ord - 1)::integer, u.value #>> '{}'
      from jsonb_array_elements(record_sent_mail.message -> 'trackedLinks') with ordinality u (value, ord);
    end if;
    v_stored := v_stored || jsonb_build_object('fromAddress', (select k."address" from "better_supabase"."mail_accounts" k where k."id" = v_account.id));
    perform "better_supabase".emit_event('mail_message.sent', jsonb_build_object('organizationId', v_account.tenant, 'accountId', v_account.id, 'userId', v_account.owner, 'threadId', v_stored ->> 'threadId', 'messageId', v_stored ->> 'id', 'direction', v_stored ->> 'direction', 'fromAddress', v_stored ->> 'fromAddress', 'subjects', coalesce((select jsonb_agg(jsonb_build_object('type', s."subject_type", 'id', s."subject_id") order by s."created_at", s."subject_type", s."subject_id") from "better_supabase"."mail_thread_subjects" s where s."thread_id" = (v_stored ->> 'threadId')::uuid), '[]'::jsonb)), 'mail-messages/' || (v_stored ->> 'id'), (v_account.tenant::text)::text, 'mail_message:' || (v_stored ->> 'id'), 'better-supabase/mail-sync');
  end if;
  return (select to_jsonb(y) from "better_supabase"."mail_messages" y where y."id" = (v_stored ->> 'id')::uuid);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_skill_sync (
  skill_id     uuid,
  provider     text,
  reference    jsonb,
  content_hash text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."agent_skills"%rowtype;
begin
  update "better_supabase"."agent_skills" k
  set "provider_refs" = k."provider_refs" || jsonb_build_object(record_skill_sync.provider, jsonb_build_object('reference', record_skill_sync.reference, 'content_hash', record_skill_sync.content_hash)),
      "content_hash" = record_skill_sync.content_hash
  where k."id" = record_skill_sync.skill_id
  returning * into v_row;
  if not found then
    raise exception 'agent % not found', record_skill_sync.skill_id using errcode = 'P0002', hint = 'AGENT_NOT_FOUND';
  end if;
  return v_row."provider_refs";
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_sla_event (
  subject_type text,
  subject_id   text,
  event        text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant text := (case record_sla_event.subject_type
      when 'message' then (select s."tenant_id"::text from "better_supabase"."messages" s where s."id" = (record_sla_event.subject_id)::uuid)
      when 'conversation' then (select s."tenant_id"::text from "better_supabase"."conversations" s where s."id" = (record_sla_event.subject_id)::uuid)
      when 'channel' then (select s."tenant_id"::text from "better_supabase"."channels" s where s."id" = (record_sla_event.subject_id)::uuid)
      when 'company' then (select s."tenant_id"::text from "better_supabase"."companies" s where s."id" = (record_sla_event.subject_id)::uuid)
