      when 'project' then exists (select 1 from "public"."projects" s where s."id" = (record_sla_event.subject_id)::uuid and s."organization_id"::text = v_tenant::text)
      when 'task' then exists (select 1 from "public"."tasks" s where s."id" = (record_sla_event.subject_id)::uuid and s."organization_id"::text = v_tenant::text)
      else false
    end and "better_supabase"."can_subject"(record_sla_event.subject_type, record_sla_event.subject_id, 'read'))) then
    raise exception 'not allowed to move clocks on this record' using errcode = '42501', hint = 'SLA_FORBIDDEN';
  end if;
  case record_sla_event.event
    when 'responded' then v_meet := array['first_response', 'next_response'];
    when 'resolved' then v_meet := array['first_response', 'next_response', 'resolution'];
    when 'paused' then
      update "better_supabase"."sla_clocks" x set "paused_at" = now()
      where x."subject_type" = record_sla_event.subject_type and x."subject_id" = record_sla_event.subject_id
        and x."met_at" is null and x."paused_at" is null;
      return "better_supabase"."sla_clocks_of"(record_sla_event.subject_type, record_sla_event.subject_id);
    when 'resumed' then
      update "better_supabase"."sla_clocks" x set
        "due_at" = x."due_at" + (now() - x."paused_at"),
        "paused_seconds" = x."paused_seconds" + extract(epoch from now() - x."paused_at")::integer,
        "paused_at" = null
      where x."subject_type" = record_sla_event.subject_type and x."subject_id" = record_sla_event.subject_id
        and x."met_at" is null and x."paused_at" is not null;
      return "better_supabase"."sla_clocks_of"(record_sla_event.subject_type, record_sla_event.subject_id);
    when 'reopened' then v_meet := array[]::text[];
    else
      raise exception 'event is responded, resolved, reopened, paused or resumed' using errcode = '22023', hint = 'SLA_EVENT_INVALID';
  end case;
  for v_clock in
    update "better_supabase"."sla_clocks" x set "met_at" = now(), "paused_at" = null
    where x."subject_type" = record_sla_event.subject_type and x."subject_id" = record_sla_event.subject_id
      and x."met_at" is null and x."metric" = any (v_meet)
    returning *
  loop
    perform "better_supabase".emit_event('sla.completed', jsonb_build_object('organizationId', v_clock."tenant_id", 'clockId', v_clock."id", 'subjectType', v_clock."subject_type", 'subjectId', v_clock."subject_id", 'metric', v_clock."metric", 'dueAt', v_clock."due_at", 'late', v_clock."met_at" > v_clock."due_at"), 'sla-clocks/' || v_clock."id"::text, (v_clock."tenant_id"::text)::text, null, 'better-supabase/sla');
  end loop;
  select x.* into v_policy from "better_supabase"."sla_clocks" c join "better_supabase"."sla_policies" x on x."id" = c."policy_id"
  where c."subject_type" = record_sla_event.subject_type and c."subject_id" = record_sla_event.subject_id
  order by c."created_at" desc limit 1;
  if v_policy."id" is not null then
    if record_sla_event.event = 'responded' and v_policy."next_response_minutes" is not null
      and exists (select 1 from "better_supabase"."sla_clocks" x where x."subject_type" = record_sla_event.subject_type and x."subject_id" = record_sla_event.subject_id and x."metric" = 'resolution' and x."met_at" is null) then
      insert into "better_supabase"."sla_clocks" ("tenant_id", "subject_type", "subject_id", "policy_id", "metric", "started_at", "due_at")
      values (v_policy."tenant_id", record_sla_event.subject_type, record_sla_event.subject_id, v_policy."id", 'next_response', now(),
        "better_supabase"."sla_due_at"(now(), v_policy."next_response_minutes", v_policy."business_hours"))
      on conflict do nothing;
    elsif record_sla_event.event = 'reopened' and v_policy."resolution_minutes" is not null then
      insert into "better_supabase"."sla_clocks" ("tenant_id", "subject_type", "subject_id", "policy_id", "metric", "started_at", "due_at")
      values (v_policy."tenant_id", record_sla_event.subject_type, record_sla_event.subject_id, v_policy."id", 'resolution', now(),
        "better_supabase"."sla_due_at"(now(), v_policy."resolution_minutes", v_policy."business_hours"))
      on conflict do nothing;
    end if;
  end if;
  return "better_supabase"."sla_clocks_of"(record_sla_event.subject_type, record_sla_event.subject_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_ssf_received (
  issuer text,
  jti    text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_new boolean;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role manages shared signals streams' using errcode = '42501', hint = 'SSF_FORBIDDEN';
  end if;
  insert into "better_supabase"."ssf_received" ("issuer", "jti")
  values (record_ssf_received.issuer, record_ssf_received.jti)
  on conflict do nothing
  returning true into v_new;
  return coalesce(v_new, false);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_subject_read (
  subject_type  text,
  subject_id    text,
  purpose       text DEFAULT NULL::text,
  block_name    text DEFAULT NULL::text,
  function_name text DEFAULT NULL::text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_emergency boolean;
  v_purpose text := nullif(btrim(record_subject_read.purpose), '');
begin
  if auth.uid() is null or not (record_subject_read.subject_type = any ('{customer}'::text[])) then
    return;
  end if;
  if length(v_purpose) > 500 then
    raise exception 'purpose takes at most 500 characters' using errcode = '22023', hint = 'SUBJECT_READ_INVALID';
  end if;
  begin
  case record_subject_read.subject_type
    when 'customer' then
      select s."organization_id" into v_tenant from "public"."customers" s
      where s."id" = (record_subject_read.subject_id)::uuid and s."archived_at" is null;
    else
      v_tenant := null;
  end case;
  exception
    when invalid_text_representation then
      return;
  end;
  if v_tenant is null
    or not coalesce("better_supabase"."can_subject"(record_subject_read.subject_type, record_subject_read.subject_id, 'read'), false) then
    return;
  end if;
  v_emergency := exists (
    select 1 from "better_supabase"."subject_members" m
    where m."subject_type" = record_subject_read.subject_type
        and m."subject_id" = record_subject_read.subject_id
        and m."tenant_id" = v_tenant
      and m."emergency"
      and (m."user_id" = auth.uid() or (m."team_id" is not null and exists (
          select 1 from "better_supabase"."team_members" tm
          where tm."team_id" = m."team_id"
            and tm."user_id" = auth.uid())))
        and (m."starts_on" is null or m."starts_on" <= current_date)
        and (m."ends_on" is null or m."ends_on" >= current_date)
        and (m."ends_at" is null or m."ends_at" > now())
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('better_supabase.record_subject_read'),
    pg_catalog.hashtext(auth.uid()::text || ':' || record_subject_read.subject_type || ':' || record_subject_read.subject_id));
  if exists (
    select 1 from "better_supabase"."audit_events" l
    where l."table_name" is null
        and l."record_id" = record_subject_read.subject_id
        and l."event_type" = 'subject.accessed'
        and l."tenant_id" = v_tenant
        and l."metadata" ->> 'subjectType' = record_subject_read.subject_type
      and l."actor_id" = auth.uid()
      and l."occurred_at" > now() - make_interval(secs => 60)
      and coalesce((l."metadata" ->> 'emergency')::boolean, false) = v_emergency
      and l."metadata" ->> 'purpose' is not distinct from v_purpose
  ) then
    return;
  end if;
  perform better_supabase.audit_event(
    event_type => 'subject.accessed',
    category => 'read',
    target_type => 'subject',
    record_id => record_subject_read.subject_id,
    summary => 'Read ' || record_subject_read.subject_type || ' ' || record_subject_read.subject_id,
    tenant => (v_tenant)::uuid,
    metadata => jsonb_build_object('organizationId', v_tenant, 'subjectType', record_subject_read.subject_type, 'subjectId', record_subject_read.subject_id, 'purpose', v_purpose, 'emergency', v_emergency, 'block', record_subject_read.block_name, 'function', record_subject_read.function_name)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_summary (
  subject_type text,
  subject_id   text,
  sections     text[],
  seen_at      timestamp with time zone DEFAULT NULL::timestamp WITH time zone
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_counts jsonb := '{}'::jsonb;
  v_unread jsonb := '{}'::jsonb;
  v_count bigint;
  v_latest timestamptz;
  v_seen timestamptz;
begin
  if coalesce(cardinality(record_summary.sections), 0) > 20 then
    raise exception 'record_summary takes at most 20 sections'
      using errcode = '22023', hint = 'RECORD_SECTIONS_TOO_MANY';
  end if;
  if not "better_supabase"."can_subject"(record_summary.subject_type, record_summary.subject_id, 'read') then
    return null;
  end if;
  perform "better_supabase"."record_subject_read"(record_summary.subject_type, record_summary.subject_id, null, 'subjects', 'record_summary');
  if 'comments' = any (record_summary.sections) then
    select count(*), max(x."sent_at")
      into v_count, v_latest
      from "better_supabase"."messages" x
      join "better_supabase"."conversations" c on c."id" = x."conversation_id"
        and c."kind" = 'subject'
      where c."subject_type"::text = record_summary.subject_type
        and c."subject_id"::text = record_summary.subject_id
        and x."sent_at" is not null and x."archived_at" is null;
    v_seen := coalesce((select "better_supabase"."conversation_read_at"(c."id") from "better_supabase"."conversations" c
        where c."kind" = 'subject'
          and c."subject_type" = record_summary.subject_type
          and c."subject_id" = record_summary.subject_id), record_summary.seen_at);
    v_counts := v_counts || jsonb_build_object('comments', v_count);
    v_unread := v_unread || jsonb_build_object('comments',
      v_seen is not null and v_latest is not null and v_latest > v_seen);
  end if;
  if 'attachments' = any (record_summary.sections) then
    select count(*), max(x."uploaded_at")
      into v_count, v_latest
      from "better_supabase"."attachments" x
      where x."subject_type"::text = record_summary.subject_type
        and x."subject_id"::text = record_summary.subject_id
        and x."uploaded_at" is not null and x."status" <> 'infected';
    v_seen := record_summary.seen_at;
    v_counts := v_counts || jsonb_build_object('attachments', v_count);
    v_unread := v_unread || jsonb_build_object('attachments',
      v_seen is not null and v_latest is not null and v_latest > v_seen);
  end if;
  return jsonb_build_object(
    'type', record_summary.subject_type,
    'id', record_summary.subject_id,
    'title', "better_supabase"."subject_title"(record_summary.subject_type, record_summary.subject_id),
    'url', "better_supabase"."subject_url"(record_summary.subject_type, record_summary.subject_id),
    'counts', v_counts,
    'unread', v_unread);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_team_leads (
  subject_type text,
  subject_id   text
)
  RETURNS uuid[]
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(array_agg(distinct l.id), '{}'::uuid[])
  from (
    select m."user_id" as id from "better_supabase"."subject_members" m
    where m."subject_type" = record_team_leads.subject_type
      and m."subject_id" = record_team_leads.subject_id
      and m."role" = 'lead' and m."user_id" is not null
      and (m."starts_on" is null or m."starts_on" <= current_date)
        and (m."ends_on" is null or m."ends_on" >= current_date)
        and (m."ends_at" is null or m."ends_at" > now())
    union
    select tm."user_id" from "better_supabase"."subject_members" m
    join "better_supabase"."team_members" tm on tm."team_id" = m."team_id"
    where m."subject_type" = record_team_leads.subject_type
      and m."subject_id" = record_team_leads.subject_id
      and m."role" = 'lead' and (m."starts_on" is null or m."starts_on" <= current_date)
        and (m."ends_on" is null or m."ends_on" >= current_date)
        and (m."ends_at" is null or m."ends_at" > now())
  ) l;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_team_tenant (
  subject_type text,
  subject_id   text
)
  RETURNS uuid
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
begin
  case record_team_tenant.subject_type
    when 'customer' then
      select s."organization_id" into v_tenant from "public"."customers" s
      where s."id" = (record_team_tenant.subject_id)::uuid and s."archived_at" is null;
    when 'drive_node' then
      select s."tenant_id" into v_tenant from "better_supabase"."drive_nodes" s
      where s."id" = (record_team_tenant.subject_id)::uuid and s."archived_at" is null;
    else
      v_tenant := null;
  end case;
  return v_tenant;
exception
  when invalid_text_representation then
    return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_template_application (
  template_id  uuid,
  version_id   uuid,
  tenant       uuid,
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_tpl "better_supabase"."templates"%rowtype;
  v_row "better_supabase"."template_applications"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if record_template_application.tenant is null then
    raise exception 'Applying a template needs a tenant' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', record_template_application.tenant, 'templates.apply'), false)) then
    raise exception 'You may not apply templates here' using errcode = '42501', hint = 'TEMPLATE_FORBIDDEN';
  end if;
  select * into v_tpl from "better_supabase"."templates" x where x."id" = record_template_application.template_id;
  if not found or not (v_tpl."scope" = 'system' or v_tpl."tenant_id" = record_template_application.tenant or (v_tpl."scope" = 'brand' and v_tpl."brand" = "better_supabase"."template_brand"(record_template_application.tenant))) then
    raise exception 'No such template' using errcode = 'P0002', hint = 'TEMPLATE_NOT_FOUND';
  end if;
  if not exists (select 1 from "better_supabase"."template_versions" y where y."id" = record_template_application.version_id
      and y."template_id" = v_tpl."id" and y."published_at" is not null) then
    raise exception 'Not a published version of this template' using errcode = 'P0002', hint = 'TEMPLATE_NOT_PUBLISHED';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_template_apply"(uuid, uuid, text, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::uuid, $3::text, $4::text)', v_hook::oid::regproc)
        using record_template_application.tenant, v_tpl."id", record_template_application.subject_type, record_template_application.subject_id;
    end if;
  end;
  insert into "better_supabase"."template_applications" ("template_id", "version_id", "tenant_id", "subject_type", "subject_id", "applied_by")
  values (v_tpl."id", record_template_application.version_id, record_template_application.tenant,
    record_template_application.subject_type, record_template_application.subject_id, (select auth.uid()))
  returning * into v_row;
  perform "better_supabase".emit_event('template.applied', jsonb_build_object('organizationId', v_row."tenant_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'id', v_row."id", 'templateId', v_row."template_id", 'versionId', v_row."version_id"), 'template-applications/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/templates');
  perform better_supabase.audit_event(
    event_type => 'template.applied',
    category => 'data',
    target_type => 'template_application',
    record_id => v_row."id"::text,
    target_label => v_tpl."name",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'id', v_row."id", 'templateId', v_row."template_id", 'versionId', v_row."version_id")
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_template_apply"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return jsonb_build_object(
    'id', v_row."id",
    'template', v_row."template_id",
    'version', v_row."version_id",
    'tenant', v_row."tenant_id",
    'subjectType', v_row."subject_type",
    'subjectId', v_row."subject_id",
    'appliedBy', v_row."applied_by",
    'appliedAt', v_row."applied_at"
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_till_movement (
  session_id uuid,
  kind       text,
  amount     bigint,
  reason     text   DEFAULT NULL::text,
  reference  text   DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_session "better_supabase"."till_sessions";
  v_till "better_supabase"."tills";
  v_row "better_supabase"."till_movements";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_session from "better_supabase"."till_sessions" x where x."id" = record_till_movement.session_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_session."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_session."tenant_id", 'tills.read'), false))) then
    raise exception 'no such till session' using errcode = 'P0002', hint = 'TILL_SESSION_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_session."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_session."tenant_id", 'tills.write'), false))) then
    raise exception 'not allowed to record cash movements' using errcode = '42501', hint = 'TILL_FORBIDDEN';
  end if;
  if v_session."status" <> 'open' then
    raise exception 'cash can only be recorded on an open session' using errcode = '55000', hint = 'TILL_STATUS';
  end if;
  if record_till_movement.kind is null or record_till_movement.kind not in ('cash_sale', 'cash_refund', 'cash_in', 'cash_out') then
    raise exception 'kind is one of cash_sale, cash_refund, cash_in, cash_out' using errcode = '22023', hint = 'TILL_INVALID';
  end if;
  if record_till_movement.amount is null or record_till_movement.amount <= 0 then
    raise exception 'the amount is above zero' using errcode = '22023', hint = 'TILL_INVALID';
  end if;
  if record_till_movement.kind in ('cash_refund', 'cash_out') and record_till_movement.amount > (v_session."opening_float" + coalesce((select sum(case when bm."kind" in ('cash_sale', 'cash_in') then bm."amount" else -bm."amount" end) from "better_supabase"."till_movements" bm where bm."session_id" = v_session."id"), 0)) then
    raise exception 'the drawer does not hold that much cash' using errcode = '22023', hint = 'TILL_INVALID';
  end if;
  begin
    insert into "better_supabase"."till_movements" ("tenant_id", "session_id", "kind", "amount", "reason", "reference", "created_by")
    values (v_session."tenant_id", v_session."id", record_till_movement.kind, record_till_movement.amount,
      nullif(trim(record_till_movement.reason), ''), nullif(trim(record_till_movement.reference), ''), auth.uid())
    returning * into v_row;
  exception when check_violation then
    raise exception 'a reason is up to 500 and a reference up to 200 characters' using errcode = '22023', hint = 'TILL_INVALID';
  end;
  select * into v_till from "better_supabase"."tills" x where x."id" = v_session."till_id";
  perform "better_supabase".emit_event('till_movement.recorded', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'sessionId', v_row."session_id", 'kind', v_row."kind", 'amount', v_row."amount"::text), 'tills/' || v_till."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/tills');
  perform better_supabase.audit_event(
    event_type => 'till_movement.recorded',
    category => 'data',
    target_type => 'till',
    record_id => v_till."id"::text,
    target_label => v_till."name",
    summary => 'cash movement recorded',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'sessionId', v_row."session_id", 'kind', v_row."kind", 'amount', v_row."amount"::text)
  );
  return jsonb_build_object('id', v_row."id", 'currency', (select bt."currency" from "better_supabase"."tills" bt join "better_supabase"."till_sessions" bs on bs."till_id" = bt."id" where bs."id" = v_row."session_id"), 'sessionId', v_row."session_id", 'kind', v_row."kind", 'amount', v_row."amount"::text, 'reason', v_row."reason", 'reference', v_row."reference", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_tracking_events (
  shipment_id uuid,
  events      jsonb,
  source      text  DEFAULT 'manual'::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_ship "better_supabase"."shipments"%rowtype;
  v_count integer;
  v_status text;
  v_at timestamptz;
  v_from text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_ship from "better_supabase"."shipments" x where x."id" = record_tracking_events.shipment_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_ship."tenant_id", 'shipments.manage'), false)) then
    raise exception 'shipment not found' using errcode = 'P0002', hint = 'SHIPMENT_NOT_FOUND';
  end if;
  if v_ship."tracking_number" is null then
    raise exception 'a shipment gets tracking events once it has a label' using errcode = '55000', hint = 'SHIPMENT_NOT_LABELED';
  end if;
  if record_tracking_events.source is null or record_tracking_events.source not in ('carrier', 'manual') then
    raise exception 'the source is carrier or manual' using errcode = '22023', hint = 'SHIPMENT_TRACKING_INVALID';
  end if;
  if jsonb_typeof(record_tracking_events.events) is distinct from 'array' or jsonb_array_length(record_tracking_events.events) > 500 then
    raise exception 'pass the tracking events as an array of at most 500' using errcode = '22023', hint = 'SHIPMENT_TRACKING_INVALID';
  end if;
  begin
    with inserted as (
      insert into "better_supabase"."shipment_tracking_events" ("tenant_id", "shipment_id", "external_id", "status", "occurred_at", "description", "location", "source")
      select v_ship."tenant_id", v_ship."id", i ->> 'id', i ->> 'status', (i ->> 'occurredAt')::timestamptz, nullif(i ->> 'description', ''), nullif(i ->> 'location', ''), record_tracking_events.source
      from jsonb_array_elements(record_tracking_events.events) i
      on conflict ("shipment_id", "external_id") do nothing
      returning 1
    )
    select count(*)::integer into v_count from inserted;
  exception when check_violation or not_null_violation or invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
    raise exception 'each tracking event needs an id, a known status and an ISO 8601 occurredAt' using errcode = '22023', hint = 'SHIPMENT_TRACKING_INVALID';
  end;
  select t."status", t."occurred_at" into v_status, v_at
    from "better_supabase"."shipment_tracking_events" t
    where t."shipment_id" = v_ship."id"
    order by t."occurred_at" desc, array_position(array['label_created', 'in_transit', 'out_for_delivery', 'delivered', 'exception', 'returned']::text[], t."status") desc
    limit 1;
  if v_status is not null and v_ship."status" <> 'cancelled' and v_status <> v_ship."status" then
    v_from := v_ship."status";
    update "better_supabase"."shipments" x set
      "status" = v_status,
      "delivered_at" = case when v_status = 'delivered' then v_at end,
      "updated_at" = now()
    where x."id" = v_ship."id"
    returning * into v_ship;
    perform "better_supabase".emit_event('shipment.status_changed', jsonb_build_object('organizationId', v_ship."tenant_id"::text, 'id', v_ship."id", 'from', v_from, 'to', v_ship."status", 'trackingNumber', v_ship."tracking_number"), 'shipments/' || v_ship."id"::text, (v_ship."tenant_id")::text, null, 'better-supabase/shipments');
  end if;
  return jsonb_build_object('recorded', v_count, 'shipment', jsonb_build_object('id', v_ship."id", 'organizationId', v_ship."tenant_id"::text, 'reference', v_ship."reference", 'status', v_ship."status", 'from', v_ship."from_address", 'to', v_ship."to_address", 'direction', v_ship."direction", 'fromLocationId', v_ship."from_location_id", 'subjectType', v_ship."subject_type", 'subjectId', v_ship."subject_id", 'carrier', v_ship."carrier", 'service', v_ship."service", 'trackingNumber', v_ship."tracking_number", 'trackingUrl', v_ship."tracking_url", 'labelId', v_ship."label_id", 'labelUrl', v_ship."label_url", 'labelFormat', v_ship."label_format", 'labelCost', v_ship."label_cost"::text, 'currency', v_ship."currency", 'labeledAt', v_ship."labeled_at", 'deliveredAt', v_ship."delivered_at", 'deliveredTo', v_ship."delivered_to", 'proofReference', v_ship."proof_reference", 'proofAttachmentId', v_ship."proof_attachment_id", 'proofRecordedAt', v_ship."proof_recorded_at", 'cancelledAt', v_ship."cancelled_at", 'createdBy', v_ship."created_by", 'createdAt', v_ship."created_at", 'updatedAt', v_ship."updated_at", 'packages', (select coalesce(jsonb_agg(jsonb_build_object('id', pk."id", 'position', pk."position", 'weightGrams', pk."weight_grams", 'lengthMm', pk."length_mm", 'widthMm', pk."width_mm", 'heightMm', pk."height_mm", 'reference', pk."reference") order by pk."position"), '[]'::jsonb) from "better_supabase"."shipment_packages" pk where pk."shipment_id" = v_ship."id"), 'lines', (select coalesce(jsonb_agg(jsonb_build_object('id', sl."id", 'position', sl."position", 'direction', sl."direction",
    'variantId', sl."variant_id", 'locationId', sl."location_id", 'quantity', sl."quantity"::text, 'allocationId', sl."allocation_id",
    'detail', sl."detail", 'disposition', sl."disposition", 'movementId', sl."movement_id", 'movedAt', sl."moved_at")
    order by sl."position"), '[]'::jsonb) from "better_supabase"."shipment_lines" sl where sl."shipment_id" = v_ship."id")));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_usage (
  tenant          uuid,
  meter           text,
  quantity        numeric DEFAULT 1,
  idempotency_key text    DEFAULT NULL::text,
  source          text    DEFAULT NULL::text,
  metadata        jsonb   DEFAULT NULL::jsonb,
  actor           uuid    DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  today date := (now() at time zone 'utc')::date;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', tenant, 'usage.record'), false)) then
    raise exception 'Not allowed to record usage in this tenant' using errcode = '42501', hint = 'USAGE_FORBIDDEN';
  end if;
  if quantity is null or quantity < 0 then
    raise exception 'quantity must be zero or more' using errcode = '22023', hint = 'USAGE_QUANTITY';
  end if;
  if idempotency_key is not null then
    insert into "better_supabase"."usage_events" ("tenant_id", "meter", "idempotency_key", "quantity")
    values (tenant, meter, idempotency_key, quantity)
    on conflict do nothing;
    if not found then
      return jsonb_build_object('recorded', false, 'used', "better_supabase"."usage_used"(tenant, meter, coalesce((select q.period from "better_supabase"."usage_quota"(tenant, meter) q), 'month')), 'today', "better_supabase"."usage_used"(tenant, meter, 'day'));
    end if;
  end if;
  insert into "better_supabase"."usage_counters" as c ("tenant_id", "meter", "day", "value")
  values (tenant, meter, today, quantity)
  on conflict ("tenant_id", "meter", "day") do update
    set "value" = c."value" + excluded."value", "updated_at" = now();
  insert into "better_supabase"."usage_history" ("tenant_id", "meter", "quantity", "actor_id", "source", "metadata")
  values (tenant, meter, quantity,
    case when coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then coalesce(record_usage.actor, auth.uid()) else auth.uid() end,
    record_usage.source, coalesce(record_usage.metadata, '{}'));
  return jsonb_build_object('recorded', true, 'used', "better_supabase"."usage_used"(tenant, meter, coalesce((select q.period from "better_supabase"."usage_quota"(tenant, meter) q), 'month')), 'today', "better_supabase"."usage_used"(tenant, meter, 'day'));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_usage_batch (
  tenant          uuid,
  entries         jsonb,
  idempotency_key text  DEFAULT NULL::text,
  "check" boolean DEFAULT false,
  source          text  DEFAULT NULL::text,
  metadata        jsonb DEFAULT NULL::jsonb,
  actor           uuid  DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  entry jsonb;
  outcome jsonb;
  recorded boolean := false;
  used jsonb := '{}';
  today_used jsonb := '{}';
begin
  -- A JSON text of the array, as a transport that sends arrays as text passes it.
  if jsonb_typeof(entries) = 'string' then
    entries := (entries #>> '{}')::jsonb;
  end if;
  if jsonb_typeof(entries) <> 'array' or jsonb_array_length(entries) = 0 then
    raise exception 'entries must be a non-empty array of { meter, quantity }' using errcode = '22023', hint = 'USAGE_ENTRIES';
  end if;
  for entry in select value from jsonb_array_elements(entries) loop
    if jsonb_typeof(entry -> 'meter') <> 'string' then
      raise exception 'Every entry needs a meter' using errcode = '22023', hint = 'USAGE_ENTRIES';
    end if;
    if record_usage_batch."check" then
      outcome := "better_supabase"."consume_quota"(tenant, entry ->> 'meter', coalesce((entry ->> 'quantity')::numeric, 1),
        case when idempotency_key is null then null else idempotency_key || ':' || (entry ->> 'meter') end,
        source, metadata, actor);
    else
      outcome := "better_supabase"."record_usage"(tenant, entry ->> 'meter', coalesce((entry ->> 'quantity')::numeric, 1),
        case when idempotency_key is null then null else idempotency_key || ':' || (entry ->> 'meter') end,
        source, metadata, actor);
    end if;
    recorded := recorded or (outcome ->> 'recorded')::boolean;
    used := used || jsonb_build_object(entry ->> 'meter', outcome -> 'used');
    today_used := today_used || jsonb_build_object(entry ->> 'meter', outcome -> 'today');
  end loop;
  return jsonb_build_object('recorded', recorded, 'used', used, 'today', today_used);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_view (
  tenant       uuid,
  subject_type text,
  subject_id   text,
  viewer_kind  text,
  viewer       text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (auth.role() = 'service_role' or record_view.tenant in (select better_supabase.member_organization_ids())) then
    raise exception 'not a member of this organization' using errcode = '42501', hint = 'SHARE_FORBIDDEN';
  end if;
  insert into "better_supabase"."subject_views" ("tenant_id", "subject_type", "subject_id", "viewer_kind", "viewer")
  values (record_view.tenant, record_view.subject_type, record_view.subject_id, record_view.viewer_kind, record_view.viewer)
  on conflict ("tenant_id", "subject_type", "subject_id", "viewer_kind", "viewer")
  do update set "last_viewed_at" = now(), "view_count" = "better_supabase"."subject_views"."view_count" + 1;
  perform "better_supabase".emit_event('subject.viewed', jsonb_build_object('organizationId', record_view.tenant, 'subjectType', record_view.subject_type, 'subjectId', record_view.subject_id), 'views/' || record_view.subject_type || '/' || record_view.subject_id, (record_view.tenant)::text, null, 'better-supabase/share-links');
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_work_order_part (
  work_order_id uuid,
  name          text,
  quantity      numeric DEFAULT 1,
  unit          text    DEFAULT NULL::text,
  asset_id      uuid    DEFAULT NULL::uuid,
  variant_id    uuid    DEFAULT NULL::uuid,
  location_id   uuid    DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_order "better_supabase"."work_orders"%rowtype;
  v_row "better_supabase"."work_order_parts"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_order from "better_supabase"."work_orders" x where x."id" = record_work_order_part.work_order_id;
  if not found or not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_order."tenant_id", 'dispatch.manage'), false)) or (coalesce(v_order."technician_id" = auth.uid(), false) and coalesce(better_supabase.can('tenant', v_order."tenant_id", 'dispatch.work'), false))) then
    raise exception 'work order not found' using errcode = 'P0002', hint = 'DISPATCH_NOT_FOUND';
  end if;
  if v_order."status" = 'cancelled' then
    raise exception 'a cancelled work order takes no parts' using errcode = '55000', hint = 'DISPATCH_STATUS_INVALID';
  end if;
  if record_work_order_part.asset_id is not null and not exists (
    select 1 from "better_supabase"."assets" a
    where a."id" = record_work_order_part.asset_id and a."tenant_id" = v_order."tenant_id"
  ) then
    raise exception 'the asset does not exist in this organization' using errcode = 'P0002', hint = 'DISPATCH_ASSET_NOT_FOUND';
  end if;
  if record_work_order_part.variant_id is not null and not exists (
    select 1 from "better_supabase"."product_variants" v
    where v."id" = record_work_order_part.variant_id and v."tenant_id" = v_order."tenant_id"
  ) then
    raise exception 'the product variant does not exist in this organization' using errcode = 'P0002', hint = 'DISPATCH_VARIANT_NOT_FOUND';
  end if;
  if record_work_order_part.location_id is not null and not exists (
    select 1 from "better_supabase"."inventory_locations" il
    where il."id" = record_work_order_part.location_id and il."tenant_id" = v_order."tenant_id"
  ) then
    raise exception 'the inventory location does not exist in this organization' using errcode = 'P0002', hint = 'DISPATCH_INVENTORY_LOCATION_NOT_FOUND';
  end if;
  begin
    insert into "better_supabase"."work_order_parts" ("tenant_id", "work_order_id", "name", "quantity", "unit", "asset_id", "variant_id", "location_id", "recorded_by")
    values (v_order."tenant_id", v_order."id", btrim(record_work_order_part.name), coalesce(record_work_order_part.quantity, 1),
      record_work_order_part.unit, record_work_order_part.asset_id, record_work_order_part.variant_id, record_work_order_part.location_id, auth.uid())
    returning * into v_row;
  exception when check_violation or not_null_violation or numeric_value_out_of_range then
    raise exception 'a part needs a name of 1 to 200 characters and a positive quantity' using errcode = '22023', hint = 'DISPATCH_PART_INVALID';
  end;
  perform "better_supabase".emit_event('work_order.part_used', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'id', v_row."work_order_id", 'partId', v_row."id", 'assetId', v_row."asset_id", 'variantId', v_row."variant_id", 'quantity', v_row."quantity"::text), 'work-orders/' || v_row."work_order_id"::text, (v_row."tenant_id")::text, null, 'better-supabase/dispatch');
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id"::text, 'workOrderId', v_row."work_order_id", 'name', v_row."name", 'quantity', v_row."quantity"::text, 'unit', v_row."unit", 'assetId', v_row."asset_id", 'variantId', v_row."variant_id", 'locationId', v_row."location_id", 'recordedBy', v_row."recorded_by", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_workflow_node_run (
  run     text,
  node    text,
  status  text,
  attempt integer DEFAULT NULL::integer,
  output  jsonb   DEFAULT NULL::jsonb,
  error   text    DEFAULT NULL::text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_run uuid;
  v_ended boolean := status in ('completed', 'failed', 'skipped');
begin
  select x."id" into v_run from "better_supabase"."workflow_runs" x
  where x."id"::text = run or x."external_id" = run
  order by x."id"::text = run desc
  limit 1;
  if not found then
    return false;
  end if;
  insert into "better_supabase"."workflow_node_runs" as x ("run_id", "node_id", "status", "attempts", "output", "error", "started_at", "ended_at")
  values (v_run, node, status, coalesce(attempt, 0), output, left(error, 4000), now(), case when v_ended then now() end)
  on conflict ("run_id", "node_id") do update set
    "status" = excluded."status",
    "attempts" = greatest(x."attempts", excluded."attempts"),
    "output" = coalesce(excluded."output", x."output"),
    "error" = excluded."error",
    "started_at" = coalesce(x."started_at", excluded."started_at"),
    "ended_at" = excluded."ended_at";
  if to_regprocedure('realtime.send(jsonb, text, text, boolean)') is not null then
    perform realtime.send(jsonb_build_object('id', v_run, 'node', node, 'status', status), 'node', 'workflow-run:' || v_run::text, true);
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.record_workflow_run (
  engine          text,
  external_id     text,
  definition      text,
  status          text,
  tenant          uuid                     DEFAULT NULL::uuid,
  actor           uuid                     DEFAULT NULL::uuid,
  attributes      jsonb                    DEFAULT '{}'::jsonb,
  error           text                     DEFAULT NULL::text,
  started_at      timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  completed_at    timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  subject_type    text                     DEFAULT NULL::text,
  subject_id      text                     DEFAULT NULL::text,
  principal_kind  text                     DEFAULT NULL::text,
  principal_id    text                     DEFAULT NULL::text,
  mode            text                     DEFAULT NULL::text,
  trigger_node    text                     DEFAULT NULL::text,
  idempotency_key text                     DEFAULT NULL::text
)
  RETURNS uuid
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_id uuid;
begin
  if idempotency_key is not null then
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('workflow_run_key'), pg_catalog.hashtext(coalesce(tenant::text, '') || ':' || idempotency_key));
    select x."id" into v_id from "better_supabase"."workflow_runs" x
    where x."tenant_id" is not distinct from tenant
      and x."idempotency_key" = idempotency_key
      and not (x."engine" = engine and x."external_id" = external_id);
    if found then
      return v_id;
    end if;
  end if;
  insert into "better_supabase"."workflow_runs" as x ("engine", "external_id", "definition", "status", "tenant_id", "actor_id", "attributes", "error", "started_at", "completed_at", "subject_type", "subject_id", "principal_kind", "principal_id", "mode", "trigger_node", "idempotency_key")
  values (engine, external_id, definition, status, tenant, actor, coalesce(attributes, '{}'::jsonb), left(error, 4000), started_at, completed_at, subject_type, subject_id, principal_kind, principal_id, coalesce(mode, 'live'), trigger_node, idempotency_key)
  on conflict on constraint workflow_runs_engine_external_key do update set
    "definition" = excluded."definition",
    "status" = excluded."status",
    "tenant_id" = coalesce(x."tenant_id", excluded."tenant_id"),
    "actor_id" = coalesce(x."actor_id", excluded."actor_id"),
    "attributes" = x."attributes" || excluded."attributes",
    "error" = coalesce(excluded."error", x."error"),
    "started_at" = coalesce(x."started_at", excluded."started_at"),
    "completed_at" = coalesce(excluded."completed_at", x."completed_at"),
    "subject_type" = case when x."subject_type" is null then excluded."subject_type" else x."subject_type" end,
    "subject_id" = case when x."subject_type" is null then excluded."subject_id" else x."subject_id" end,
    "principal_kind" = case when x."principal_kind" is null then excluded."principal_kind" else x."principal_kind" end,
    "principal_id" = case when x."principal_kind" is null then excluded."principal_id" else x."principal_id" end,
    "trigger_node" = coalesce(x."trigger_node", excluded."trigger_node"),
    "idempotency_key" = coalesce(x."idempotency_key", excluded."idempotency_key"),
    "updated_at" = now()
  returning x."id" into v_id;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.redeem_for (
  code   text,
  member uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_code "better_supabase"."invite_codes";
  v_role text;
  v_added boolean;
begin
  select * into v_code from "better_supabase"."invite_codes" x
  where x."code_hash" = encode(extensions.digest(upper(trim(redeem_for.code)), 'sha256'), 'hex')
  for update;
  if v_code."id" is null or not (v_code."revoked_at" is null
      and (v_code."expires_at" is null or v_code."expires_at" > now())
      and (v_code."max_uses" is null or v_code."uses" < v_code."max_uses")) then
    raise exception 'This invite code is not valid' using errcode = '22023', hint = 'WAITLIST_CODE_INVALID';
  end if;
  insert into "better_supabase"."invite_code_redemptions" ("code_id", "user_id") values (v_code."id", redeem_for.member)
  on conflict do nothing;
  if not found then
    raise exception 'You already used this invite code' using errcode = '23505', hint = 'WAITLIST_CODE_USED';
  end if;
  update "better_supabase"."invite_codes" x set "uses" = x."uses" + 1 where x."id" = v_code."id";
  if v_code."tenant_id" is not null then
    v_role := coalesce(v_code."role", 'member');
    insert into "public"."memberships" ("organization_id", "user_id", "role")
    values (v_code."tenant_id", redeem_for.member, (select r."id" from "better_supabase"."roles" r where (r."id"::text = (v_role)::text or r."key" = (v_role)::text) order by (r."id"::text = (v_role)::text) desc limit 1))
    on conflict do nothing;
    v_added := found;
    if v_added then
      perform "better_supabase".emit_event('organization.member_added', jsonb_build_object('organizationId', v_code."tenant_id"::text, 'userId', redeem_for.member, 'role', v_role), 'organizations/' || v_code."tenant_id"::text, (v_code."tenant_id")::text, null, 'better-supabase/waitlist');
  perform better_supabase.audit_event(
    event_type => 'organization.member_added',
    category => 'membership',
    target_type => 'user',
    record_id => redeem_for.member::text,
    tenant => (v_code."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_code."tenant_id"::text, 'userId', redeem_for.member, 'role', v_role)
  );
    else
      v_role := null;
    end if;
  end if;
  return jsonb_build_object('organizationId', v_code."tenant_id", 'role', v_role);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.redeem_invite_code (
  code text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501', hint = 'WAITLIST_FORBIDDEN';
  end if;
  return "better_supabase"."redeem_for"(redeem_invite_code.code, auth.uid());
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.redeem_promotions (
  p_order   uuid,
  p_applied jsonb
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_order record;
  v_entry jsonb;
  v_promo record;
  v_code record;
  v_id uuid;
  v_count integer := 0;
begin
  select x."id" as id, x."tenant_id" as tenant, x."customer_id" as customer, x."email" as email,
    x."currency" as currency
  into v_order from "better_supabase"."orders" x where x."id" = p_order;
  for v_entry in select e from jsonb_array_elements(coalesce(p_applied, '[]'::jsonb)) e loop
    select x."id" as id, x."usage_limit" as usage_limit, x."per_customer_limit" as per_customer_limit,
      x."redemptions" as used
    into v_promo from "better_supabase"."promotions" x where x."id" = (v_entry ->> 'promotionId')::uuid for update;
    if not found or (v_promo.usage_limit is not null and v_promo.used >= v_promo.usage_limit)
      or (v_promo.per_customer_limit is not null
        and (select count(*) from "better_supabase"."promotion_redemptions" y where y."promotion_id" = v_promo.id and y."status" = 'redeemed'
      and (y."customer_id" = v_order.customer or (v_order.email is not null and lower(y."email") = lower(v_order.email)))) >= v_promo.per_customer_limit) then
      raise exception 'a promotion on this cart reached its usage limit' using errcode = '55000', hint = 'PROMOTIONS_LIMIT_REACHED';
    end if;
    if v_entry ->> 'codeId' is not null then
      select x."usage_limit" as usage_limit, x."redemptions" as used
      into v_code from "better_supabase"."promotion_codes" x where x."id" = (v_entry ->> 'codeId')::uuid for update;
      if not found or (v_code.usage_limit is not null and v_code.used >= v_code.usage_limit) then
        raise exception 'a code on this cart was used up' using errcode = '55000', hint = 'PROMOTIONS_LIMIT_REACHED';
      end if;
      update "better_supabase"."promotion_codes" x set "redemptions" = x."redemptions" + 1 where x."id" = (v_entry ->> 'codeId')::uuid;
    end if;
    update "better_supabase"."promotions" x set "redemptions" = x."redemptions" + 1 where x."id" = v_promo.id;
    insert into "better_supabase"."promotion_redemptions" ("tenant_id", "promotion_id", "code_id", "order_id", "customer_id",
      "email", "currency", "amount")
    values (v_order.tenant, v_promo.id, (v_entry ->> 'codeId')::uuid, v_order.id, v_order.customer, v_order.email,
      v_order.currency, (v_entry ->> 'amount')::bigint)
    returning "id" into v_id;
    perform "better_supabase".emit_event('promotion.redeemed', jsonb_build_object('organizationId', v_order.tenant, 'id', v_id, 'promotionId', v_promo.id, 'code', v_entry ->> 'code', 'orderId', v_order.id, 'currency', v_order.currency, 'amount', v_entry ->> 'amount'), 'promotion-redemptions/' || v_id::text, (v_order.tenant)::text, null, 'better-supabase/promotions');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.redeliver_webhook (
  delivery uuid
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_endpoint uuid;
  v_status text;
  v_tenant uuid;
  v_enabled boolean;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select v."endpoint_id", v."status" into v_endpoint, v_status
  from "better_supabase"."webhook_deliveries" v where v."id" = redeliver_webhook.delivery;
  if not found then
    raise exception 'Webhook delivery not found' using errcode = 'P0002', hint = 'WEBHOOK_DELIVERY_NOT_FOUND';
  end if;
  select d."tenant_id", d."enabled" into v_tenant, v_enabled
  from "better_supabase"."webhook_endpoints" d where d."id" = v_endpoint;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) and not coalesce(better_supabase.can('tenant', v_tenant, 'webhooks.manage'), false) then
    raise exception 'Not allowed to manage this webhook endpoint' using errcode = '42501', hint = 'WEBHOOK_FORBIDDEN';
  end if;
  if v_status in ('pending', 'delivering') then
    raise exception 'The delivery is still in progress' using errcode = '55000', hint = 'WEBHOOK_DELIVERY_IN_PROGRESS';
  end if;
  if not v_enabled then
    raise exception 'Webhook endpoint is disabled' using errcode = '55000', hint = 'WEBHOOK_ENDPOINT_DISABLED';
  end if;
  update "better_supabase"."webhook_deliveries" v
  set "status" = 'pending', "attempt" = 0, "available_at" = now(), "lease_expires_at" = null, "processed_at" = null, "last_error" = null, "updated_at" = now()
  where v."id" = redeliver_webhook.delivery;
  return redeliver_webhook.delivery;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.reembed_knowledge (
  tenant uuid DEFAULT NULL::uuid,
  model  text DEFAULT NULL::text
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_id uuid;
  v_count integer := 0;
begin
  for v_id in
    update "better_supabase"."knowledge_documents" x set "status" = 'pending', "updated_at" = now()
    where (reembed_knowledge.tenant is null or x."tenant_id" = reembed_knowledge.tenant)
      and (reembed_knowledge.model is null or x."embedding_model" is distinct from reembed_knowledge.model)
      and x."chunk_count" > 0
    returning x."id"
  loop
    update "better_supabase"."knowledge_chunks" t set "embedding" = null, "embedding_hash" = null where t."document_id" = v_id;
  perform "better_supabase"."enqueue_job"(queue => 'knowledge_embed', payload => jsonb_build_object('document_id', v_id), dedupe_key => 'knowledge:' || v_id::text, dedupe_running => false);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.referral_attribute (
  tenant         uuid,
  code           text,
  referred_user  uuid DEFAULT NULL::uuid,
  referred_org   uuid DEFAULT NULL::uuid,
  referred_email text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_code "better_supabase"."referral_codes";
  v_ref "better_supabase"."referrals";
begin
  if referral_attribute.referred_user is null and referral_attribute.referred_org is null and nullif(trim(referral_attribute.referred_email), '') is null then
    raise exception 'name the referred user, organization or email' using errcode = '22023', hint = 'REFERRAL_INVALID';
  end if;
  select * into v_ref from "better_supabase"."referrals" x
  where x."tenant_id" = referral_attribute.tenant
    and ((referral_attribute.referred_user is not null and x."referred_id" = referral_attribute.referred_user)
      or (referral_attribute.referred_org is not null and x."referred_organization_id" = referral_attribute.referred_org));
  if found then
    return jsonb_build_object('id', v_ref."id", 'organizationId', v_ref."tenant_id", 'codeId', v_ref."code_id", 'referrerId', v_ref."referrer_id", 'referredUserId', v_ref."referred_id", 'referredOrganizationId', v_ref."referred_organization_id", 'referredEmail', v_ref."referred_email", 'status', v_ref."status", 'rewardAmount', v_ref."reward_amount"::text, 'rewardUnit', v_ref."reward_unit", 'qualifiedAt', v_ref."qualified_at", 'rewardedAt', v_ref."rewarded_at", 'ledgerTransactionId', v_ref."ledger_transaction_id", 'createdAt', v_ref."created_at");
  end if;
  select * into v_code from "better_supabase"."referral_codes" x
  where x."tenant_id" = referral_attribute.tenant and x."code" = upper(trim(referral_attribute.code)) for update;
  if not found or not v_code."active" or (v_code."expires_at" is not null and v_code."expires_at" < now())
    or (v_code."max_uses" is not null and v_code."uses" >= v_code."max_uses") then
    raise exception 'the referral code is unknown, expired or used up' using errcode = 'P0002', hint = 'REFERRAL_CODE_INVALID';
  end if;
  if referral_attribute.referred_user = v_code."referrer_id" then
    raise exception 'a member can''t refer themselves' using errcode = '22023', hint = 'REFERRAL_SELF';
  end if;
  insert into "better_supabase"."referrals" ("tenant_id", "code_id", "referrer_id", "referred_id", "referred_organization_id", "referred_email", "reward_amount", "reward_unit")
  values (referral_attribute.tenant, v_code."id", v_code."referrer_id", referral_attribute.referred_user, referral_attribute.referred_org,
    lower(nullif(trim(referral_attribute.referred_email), '')), v_code."reward_amount", v_code."reward_unit")
  returning * into v_ref;
  update "better_supabase"."referral_codes" x set "uses" = x."uses" + 1 where x."id" = v_code."id";
  perform "better_supabase".emit_event('referral.attributed', jsonb_build_object('organizationId', v_ref."tenant_id", 'id', v_ref."id", 'codeId', v_ref."code_id", 'referrerId', v_ref."referrer_id", 'referredUserId', v_ref."referred_id", 'referredOrganizationId', v_ref."referred_organization_id", 'status', v_ref."status"), 'referrals/' || v_ref."id"::text, (v_ref."tenant_id")::text, null, 'better-supabase/referrals');
  perform better_supabase.audit_event(
    event_type => 'referral.attributed',
    category => 'data',
    target_type => 'referral',
    record_id => v_ref."id"::text,
    summary => 'referral attributed',
    tenant => (v_ref."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_ref."tenant_id", 'id', v_ref."id", 'codeId', v_ref."code_id", 'referrerId', v_ref."referrer_id", 'referredUserId', v_ref."referred_id", 'referredOrganizationId', v_ref."referred_organization_id", 'status', v_ref."status")
  );
  return jsonb_build_object('id', v_ref."id", 'organizationId', v_ref."tenant_id", 'codeId', v_ref."code_id", 'referrerId', v_ref."referrer_id", 'referredUserId', v_ref."referred_id", 'referredOrganizationId', v_ref."referred_organization_id", 'referredEmail', v_ref."referred_email", 'status', v_ref."status", 'rewardAmount', v_ref."reward_amount"::text, 'rewardUnit', v_ref."reward_unit", 'qualifiedAt', v_ref."qualified_at", 'rewardedAt', v_ref."rewarded_at", 'ledgerTransactionId', v_ref."ledger_transaction_id", 'createdAt', v_ref."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.refresh_due_segments (
  max_count   integer  DEFAULT NULL::integer,
  stale_after interval DEFAULT NULL::interval
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_segment uuid;
  v_result jsonb;
  v_count integer := 0;
  v_entered integer := 0;
  v_left integer := 0;
begin
  for v_segment in
    select x."id" from "better_supabase"."segments" x
    where x."refreshed_at" is null
      or x."refreshed_at" < now() - coalesce(refresh_due_segments.stale_after, interval '1 hour')
    order by x."refreshed_at" nulls first, x."id"
    limit least(greatest(coalesce(refresh_due_segments.max_count, 25), 1), 500)
  loop
    v_result := "better_supabase"."evaluate_segment"(v_segment);
    v_count := v_count + 1;
    v_entered := v_entered + (v_result ->> 'entered')::integer;
    v_left := v_left + (v_result ->> 'left')::integer;
  end loop;
  return jsonb_build_object('segments', v_count, 'entered', v_entered, 'left', v_left);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.refresh_open_item()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_balance bigint;
begin
  v_balance := (new."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = new."id"), 0) - new."credited_total" - new."paid_total");
  delete from "better_supabase"."invoice_open_items" x
  where x."document_id" = new."id" and x."document_type" = 'invoice';
  if new."status"::text in ('issued', 'partially_paid', 'paid') and v_balance <> 0 and new."issued_on" <= current_date then
    insert into "better_supabase"."invoice_open_items" ("tenant_id", "party_id", "side", "document_type", "document_id", "currency", "due_on", "issued_on", "gross", "balance")
    values (new."tenant_id", coalesce(new."company_id"::text, new."contact_id"::text), case when new."direction" = 'purchase' then 'supplier' else 'customer' end, 'invoice', new."id", new."currency"::text,
      new."due_on", new."issued_on", (new."total" + coalesce((select sum(y."amount") from "better_supabase"."invoice_charges" y where y."invoice_id" = new."id"), 0) - new."credited_total")::bigint, v_balance);
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.refresh_payroll_run (
  run_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_run "better_supabase"."payroll_runs"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_run from "better_supabase"."payroll_runs" x where x."id" = refresh_payroll_run.run_id for update;
  if not found then
    raise exception 'no such payroll run' using errcode = 'P0002', hint = 'PAYROLL_RUN_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_run."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_run."tenant_id", 'payroll_export.export'), false))) then
    raise exception 'not allowed to do this with payroll runs' using errcode = '42501', hint = 'PAYROLL_FORBIDDEN';
  end if;
  if v_run."status" <> 'draft' then
    raise exception 'an exported payroll run can''t be refreshed' using errcode = '55000', hint = 'PAYROLL_RUN_EXPORTED';
  end if;
  perform "better_supabase"."collect_payroll_lines"(v_run."id");
  update "better_supabase"."payroll_runs" x set "updated_at" = now() where x."id" = v_run."id" returning * into v_run;
  return jsonb_build_object('id', v_run."id", 'organizationId', v_run."tenant_id", 'periodFrom', v_run."period_from", 'periodTo', v_run."period_to", 'label', v_run."label", 'status', v_run."status", 'format', v_run."format", 'checksum', v_run."checksum", 'exportedAt', v_run."exported_at", 'exportedBy', v_run."exported_by", 'createdBy', v_run."created_by", 'createdAt', v_run."created_at", 'updatedAt', v_run."updated_at", 'lineCount', (select count(*) from "better_supabase"."payroll_lines" y where y."run_id" = v_run."id"), 'lines', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'userId', y."user_id", 'employeeId', y."employee_id", 'employeeName', y."employee_name", 'kind', y."kind", 'code', y."code", 'paid', y."paid", 'unit', y."unit", 'quantity', y."quantity"::text, 'sourceCount', y."source_count") order by y."employee_name" nulls last, coalesce(y."user_id", y."employee_id"), y."kind", y."code" nulls first) from "better_supabase"."payroll_lines" y where y."run_id" = v_run."id"), '[]'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.refresh_segment (
  segment uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
begin
  select x."tenant_id" into v_tenant from "better_supabase"."segments" x where x."id" = refresh_segment.segment;
  if v_tenant is null then
    raise exception 'No segment has this id' using errcode = 'P0002', hint = 'SEGMENT_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_tenant, 'segments.write'), false)) then
    raise exception 'You need segments.edit to refresh a segment' using errcode = '42501', hint = 'SEGMENT_FORBIDDEN';
  end if;
  return "better_supabase"."evaluate_segment"(refresh_segment.segment);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.refund_pass_credit()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_spent record;
  v_entry uuid;
begin
  if new."status" <> 'cancelled' or old."status" = 'cancelled'
    or new."cancel_reason" is not distinct from 'bs:moving'
    or now() > lower(new."during") - '12 hours'::interval then
    return null;
  end if;
  for v_spent in
    select r."tenant_id" as tenant, (r."metadata" ->> 'passId')::uuid as pass, x."holder_id" as holder
    from "better_supabase"."ledger_transactions" r
    join "better_supabase"."passes" x on x."id" = (r."metadata" ->> 'passId')::uuid
    where r."tenant_id" = new."tenant_id" and r."idempotency_key" = 'pass-credit:' || new."id"::text || ':booking'
      and not exists (select 1 from "better_supabase"."ledger_transactions" d where d."tenant_id" = r."tenant_id" and d."idempotency_key" = 'pass-credit:' || new."id"::text || ':refund')
  loop
    v_entry := "better_supabase"."ledger_post"(v_spent.tenant, 'pass.credit_refunded',
      jsonb_build_array(
        jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_spent.tenant, 'pass_credits', 'pass:' || v_spent.pass::text, 'Pass credits', 'credit', 0::smallint,
    'passes', v_spent.pass::text, v_spent.holder, true, 'passes.read', 'passes', jsonb_build_object('passId', v_spent.pass)), 'amount', 1),
        jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_spent.tenant, 'pass_credits_pool', 'pass-credits:pool', 'Pass credits pool', 'credit', 0::smallint,
    null, null, null, true, 'passes.read', 'passes', null), 'amount', -1)),
      'bookings', new."id"::text, null, 'pass-credit:' || new."id"::text || ':refund', clock_timestamp(),
      jsonb_build_object('passId', v_spent.pass, 'reason', 'refund'));
    update "better_supabase"."passes" x set "uses" = greatest(x."uses" - 1, 0), "updated_at" = now()
    where x."id" = v_spent.pass;
    perform "better_supabase".emit_event('pass.credit_refunded', jsonb_build_object('organizationId', v_spent.tenant::text, 'id', v_spent.pass, 'entryId', v_entry, 'bookingId', new."id"), 'passes/' || v_spent.pass::text, (v_spent.tenant)::text, null, 'better-supabase/passes');
  perform better_supabase.audit_event(
    event_type => 'pass.credit_refunded',
    category => 'access',
    target_type => 'pass',
    record_id => v_spent.pass::text,
    summary => 'refunded a credit to pass',
    tenant => (v_spent.tenant)::uuid,
    metadata => jsonb_build_object('organizationId', v_spent.tenant::text, 'id', v_spent.pass, 'entryId', v_entry, 'bookingId', new."id")
  );
  end loop;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.refuse_data_subject_request (
  id     uuid,
  reason text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."data_subject_requests";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."data_subject_requests" x where x."id" = refuse_data_subject_request.id for update;
  if v_row."id" is null then
    raise exception 'request not found' using errcode = 'P0002', hint = 'DSAR_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'data_lifecycle.export'), false)) then
    raise exception 'You may not handle data subject requests here' using errcode = '42501', hint = 'DSAR_FORBIDDEN';
  end if;
  if v_row."closed_at" is not null then
    raise exception 'the request is already fulfilled or refused' using errcode = '55000', hint = 'DSAR_CLOSED';
  end if;
  if refuse_data_subject_request.reason is null or length(trim(refuse_data_subject_request.reason)) = 0 then
    raise exception 'reason is required' using errcode = '22023', hint = 'DSAR_INVALID';
  end if;
  update "better_supabase"."data_subject_requests" x set "status" = 'refused', "closed_at" = now(), "closed_by" = auth.uid(), "resolution" = trim(refuse_data_subject_request.reason)
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('data_subject_request.refused', jsonb_build_object('requestId', v_row."id", 'organizationId', v_row."tenant_id"::text, 'kind', v_row."kind"::text, 'status', v_row."status"::text, 'dueAt', v_row."due_at"), 'data-subject-requests/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/data-lifecycle');
  perform better_supabase.audit_event(
    event_type => 'data_subject_request.refused',
    category => 'data',
    target_type => 'data_subject_request',
    record_id => v_row."id"::text,
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('requestId', v_row."id", 'organizationId', v_row."tenant_id"::text, 'kind', v_row."kind"::text, 'status', v_row."status"::text, 'dueAt', v_row."due_at")
  );
  return to_jsonb(v_row);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.register_ai_sandbox (
  tenant     uuid,
  provider   text,
  sandbox_id text,
  fields     jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."ai_sandboxes"%rowtype;
  v_fields jsonb := coalesce(register_ai_sandbox.fields, '{}');
begin
  insert into "better_supabase"."ai_sandboxes" as cur ("tenant_id", "user_id", "chat_id", "harness_id", "provider", "sandbox_id", "container_id", "metadata", "idle_seconds", "expires_at")
  values (
    register_ai_sandbox.tenant,
    (v_fields ->> 'user_id')::uuid,
    (v_fields ->> 'chat_id')::uuid,
    v_fields ->> 'harness_id',
    register_ai_sandbox.provider,
    register_ai_sandbox.sandbox_id,
    v_fields ->> 'container_id',
    coalesce(v_fields -> 'metadata', '{}'),
    coalesce((v_fields ->> 'idle_seconds')::integer, 600),
    (v_fields ->> 'expires_at')::timestamptz
  )
  on conflict ("provider", "sandbox_id") do update set
    "container_id" = coalesce(excluded."container_id", cur."container_id"),
    "chat_id" = coalesce(excluded."chat_id", cur."chat_id"),
    "harness_id" = coalesce(excluded."harness_id", cur."harness_id"),
    "metadata" = cur."metadata" || excluded."metadata",
    "idle_seconds" = excluded."idle_seconds",
    "expires_at" = coalesce(excluded."expires_at", cur."expires_at"),
    "status" = 'running',
    "error" = null,
    "stopped_at" = null,
    "last_used_at" = now(),
    "updated_at" = now()
  where cur."tenant_id" is not distinct from excluded."tenant_id"
  returning * into v_row;
  if not found then
    raise exception 'sandbox % belongs to another tenant', register_ai_sandbox.sandbox_id using errcode = '42501', hint = 'AI_SANDBOX_FORBIDDEN';
  end if;
  return jsonb_build_object('id', v_row."id", 'organization_id', v_row."tenant_id", 'user_id', v_row."user_id", 'chat_id', v_row."chat_id", 'harness_id', v_row."harness_id", 'provider', v_row."provider", 'sandbox_id', v_row."sandbox_id", 'container_id', v_row."container_id", 'status', v_row."status", 'metadata', v_row."metadata", 'idle_seconds', v_row."idle_seconds", 'error', v_row."error", 'last_used_at', v_row."last_used_at", 'expires_at', v_row."expires_at", 'stopped_at', v_row."stopped_at", 'created_at', v_row."created_at", 'updated_at', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.register_fixed_number (
  p_tenant uuid,
  p_entity text,
  p_number text,
  p_at     timestamp with time zone DEFAULT now(),
  p_scope  text                     DEFAULT ''::text
)
  RETURNS bigint
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_format text;
  v_period text;
  v_parts text[];
  v_n bigint;
begin
  if better_supabase.import_run() is null then
    raise exception 'a fixed number is only accepted during an import' using errcode = '42501', hint = 'NUMBER_FIXED_FORBIDDEN';
  end if;
  if nullif(btrim(p_number), '') is null or length(p_number) > 200 then
    raise exception 'a fixed number is 1 to 200 characters' using errcode = '22023', hint = 'NUMBER_FIXED_INVALID';
  end if;
  v_format := "better_supabase"."number_format"(p_tenant, p_entity);
  v_period := case p_entity
    when 'drive_document' then ''
    when 'drive_document_sop' then ''
    when 'donation_receipt' then ''
    when 'risk' then ''
    when 'case' then to_char(p_at at time zone 'utc', 'YYYY')
    when 'inspection' then to_char(p_at at time zone 'utc', 'YYYY')
    when 'production_order' then to_char(p_at at time zone 'utc', 'YYYY')
    else null
  end;
  if v_format is null or v_period is null then
    raise exception 'unknown number sequence' using errcode = '22023', hint = 'NUMBER_ENTITY_UNKNOWN';
  end if;
  v_parts := regexp_match(p_number, better_supabase.number_format_pattern(v_format));
  if v_parts is null or v_parts[1] is null or length(v_parts[1]) > 18 then
    return case
      when p_number ~ '[0-9]{1,18}$' then substring(p_number from '([0-9]{1,18})$')::bigint
      else 0
    end;
  end if;
  v_n := v_parts[1]::bigint;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_tenant::text || ':' || p_entity || ':' || coalesce(p_scope, '') || ':' || v_period, 0));
  insert into "better_supabase"."number_sequences" ("tenant_id", "entity", "scope", "period", "last_number")
  values (p_tenant, p_entity, coalesce(p_scope, ''), v_period, v_n)
  on conflict ("tenant_id", "entity", "scope", "period")
  do update set "last_number" = greatest("better_supabase"."number_sequences"."last_number", excluded."last_number"), "updated_at" = now();
  return v_n;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.register_funding_deliveries_from_time (
  tenant uuid,
  since  date,
  until  date
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_entry record;
  v_awards uuid[];
  v_units numeric;
  v_award uuid;
  v_unit text;
  v_delivery jsonb;
  v_registered jsonb := '[]'::jsonb;
  v_unmatched jsonb := '[]'::jsonb;
begin
  if register_funding_deliveries_from_time.since is null or register_funding_deliveries_from_time.until is null
    or register_funding_deliveries_from_time.until < register_funding_deliveries_from_time.since then
    raise exception 'since and until are days, until on or after since' using errcode = '22023', hint = 'FUNDING_INVALID';
  end if;
  for v_entry in
    select x."id"::text as id, x."subject_type" as subject_type, x."subject_id"::text as subject_id,
      (x."started_at" at time zone 'UTC')::date as day,
      extract(epoch from x."ended_at" - x."started_at") as seconds,
      x."user_id" as performer, null::text as category
    from "better_supabase"."time_entries" x
    where x."tenant_id" = register_funding_deliveries_from_time.tenant
      and x."ended_at" is not null
      and x."subject_type" is not null
      and x."started_at" >= (register_funding_deliveries_from_time.since::timestamp at time zone 'UTC')
      and x."started_at" < ((register_funding_deliveries_from_time.until + 1)::timestamp at time zone 'UTC')
      and exists (
        select 1 from "better_supabase"."timesheets" s
        where s."tenant_id" = x."tenant_id" and s."user_id" = x."user_id"
          and s."week" = "better_supabase"."time_week"(x."started_at") and s."approved_at" is not null
      )
      and not exists (
        select 1 from "better_supabase"."funding_deliveries" z
        where z."tenant_id" = x."tenant_id" and z."source_type" = 'time_entry' and z."source_id" = x."id"::text
      )
    order by x."started_at", x."id"
  loop
    select array_agg(a."id" order by a."id"), min(y."unit") into v_awards, v_unit
    from "better_supabase"."funding_awards" a
    join "better_supabase"."funding_products" y on y."tenant_id" = a."tenant_id" and y."id" = a."product_id"
    where a."tenant_id" = register_funding_deliveries_from_time.tenant
      and a."subject_type" = v_entry.subject_type and a."subject_id" = v_entry.subject_id
      and a."status" = 'active'
      and v_entry.day >= a."starts_on" and v_entry.day <= coalesce(a."ends_on", v_entry.day)
      and (y."valid_from" is null or v_entry.day >= y."valid_from")
      and (y."valid_until" is null or v_entry.day <= y."valid_until");
    if coalesce(cardinality(v_awards), 0) <> 1 then
      v_unmatched := v_unmatched || jsonb_build_array(jsonb_build_object(
        'entryId', v_entry.id,
        'subjectType', v_entry.subject_type,
        'subjectId', v_entry.subject_id,
        'deliveredOn', v_entry.day,
        'reason', case when coalesce(cardinality(v_awards), 0) = 0 then 'no_award' else 'several_awards' end
      ));
      continue;
    end if;
    v_award := v_awards[1];
    v_units := case v_unit
      when 'minute' then round(v_entry.seconds / 60, 2)
      when 'hour' then round(v_entry.seconds / 3600, 4)
      else 1
    end;
    if v_units <= 0 then
      v_unmatched := v_unmatched || jsonb_build_array(jsonb_build_object(
        'entryId', v_entry.id,
        'subjectType', v_entry.subject_type,
        'subjectId', v_entry.subject_id,
        'deliveredOn', v_entry.day,
        'reason', 'no_duration'
      ));
      continue;
    end if;
    v_delivery := "better_supabase"."register_funding_delivery"(v_award, v_entry.day, v_units, 'time_entry', v_entry.id, v_entry.performer, null);
    v_registered := v_registered || jsonb_build_array(v_delivery);
  end loop;
  return jsonb_build_object('registered', v_registered, 'unmatched', v_unmatched);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.register_funding_delivery (
  award_id     uuid,
  delivered_on date,
  units        numeric,
  source_type  text    DEFAULT 'manual'::text,
  source_id    text    DEFAULT NULL::text,
  performer_id uuid    DEFAULT NULL::uuid,
  note         text    DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."funding_deliveries"%rowtype;
  v_award "better_supabase"."funding_awards"%rowtype;
  v_product "better_supabase"."funding_products"%rowtype;
  v_source text := coalesce(nullif(trim(register_funding_delivery.source_type), ''), 'manual');
  v_source_id text := nullif(trim(register_funding_delivery.source_id), '');
  v_note text := nullif(trim(register_funding_delivery.note), '');
  v_start date;
  v_used numeric;
  v_claims text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_award from "better_supabase"."funding_awards" x where x."id" = register_funding_delivery.award_id;
  if not found then
    raise exception 'funding award not found' using errcode = 'P0002', hint = 'FUNDING_AWARD_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_award."tenant_id", 'funding.register'), false)) then
    raise exception 'not allowed to register funded care' using errcode = '42501', hint = 'FUNDING_FORBIDDEN';
  end if;
  if v_source not in ('time_entry', 'booking', 'manual') then
    raise exception 'source_type is time_entry, booking or manual' using errcode = '22023', hint = 'FUNDING_INVALID';
  end if;
  if v_source <> 'manual' and v_source_id is null then
    raise exception 'a delivery from a time entry or booking needs its source_id' using errcode = '22023', hint = 'FUNDING_INVALID';
  end if;
  if v_source_id is not null then
    select * into v_row from "better_supabase"."funding_deliveries" x
    where x."tenant_id" = v_award."tenant_id" and x."source_type" = v_source and x."source_id" = v_source_id;
    if found then
      return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'awardId', v_row."award_id", 'sourceType', v_row."source_type", 'sourceId', v_row."source_id", 'deliveredOn', v_row."delivered_on", 'units', v_row."units", 'performerId', v_row."performer_id", 'status', v_row."status", 'claimLineId', v_row."claim_line_id", 'note', v_row."note", 'createdAt', v_row."created_at");
    end if;
  end if;
  if register_funding_delivery.delivered_on is null then
    raise exception 'a delivery needs the day it was delivered' using errcode = '22023', hint = 'FUNDING_INVALID';
  end if;
  if register_funding_delivery.units is null or register_funding_delivery.units <= 0 then
    raise exception 'a delivery needs units above zero' using errcode = '22023', hint = 'FUNDING_INVALID';
  end if;
  if v_note is not null and length(v_note) > 2000 then
    raise exception 'a note is at most 2000 characters' using errcode = '22023', hint = 'FUNDING_INVALID';
  end if;
  if v_award."status" <> 'active'
    or register_funding_delivery.delivered_on < v_award."starts_on"
    or register_funding_delivery.delivered_on > coalesce(v_award."ends_on", register_funding_delivery.delivered_on) then
    raise exception 'the funding award isn''t active on that day' using errcode = '22023', hint = 'FUNDING_AWARD_INACTIVE';
  end if;
  select * into v_product from "better_supabase"."funding_products" x where x."tenant_id" = v_award."tenant_id" and x."id" = v_award."product_id";
  if (v_product."valid_from" is not null and register_funding_delivery.delivered_on < v_product."valid_from")
    or (v_product."valid_until" is not null and register_funding_delivery.delivered_on > v_product."valid_until") then
    raise exception 'the funding product isn''t valid on that day' using errcode = '22023', hint = 'FUNDING_INVALID';
  end if;
  if v_source = 'time_entry' and not exists (
    select 1 from "better_supabase"."time_entries" x
    where x."id"::text = v_source_id and x."tenant_id" = v_award."tenant_id"
  ) then
    raise exception 'the time entry isn''t in this organization' using errcode = '22023', hint = 'FUNDING_INVALID';
  end if;
  if v_source = 'booking' and not exists (
    select 1 from "better_supabase"."bookings" x
    where x."id"::text = v_source_id and x."tenant_id" = v_award."tenant_id"
  ) then
    raise exception 'the booking isn''t in this organization' using errcode = '22023', hint = 'FUNDING_INVALID';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_funding_delivery_register"(uuid, date, numeric)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::date, $3::numeric)', v_hook::oid::regproc)
        using v_award."id", register_funding_delivery.delivered_on, register_funding_delivery.units;
    end if;
  end;
  insert into "better_supabase"."funding_deliveries" ("tenant_id", "award_id", "source_type", "source_id", "delivered_on", "units", "performer_id", "note")
  values (v_award."tenant_id", v_award."id", v_source, v_source_id, register_funding_delivery.delivered_on, register_funding_delivery.units, coalesce(register_funding_delivery.performer_id, (select auth.uid())), v_note)
  returning * into v_row;
  perform "better_supabase".emit_event('funding_delivery.registered', jsonb_build_object('organizationId', v_row."tenant_id", 'fundingAwardId', v_row."award_id", 'fundingDeliveryId', v_row."id", 'subjectType', v_award."subject_type", 'subjectId', v_award."subject_id", 'sourceType', v_row."source_type", 'sourceId', v_row."source_id", 'deliveredOn', v_row."delivered_on", 'units', v_row."units"), 'funding-awards/' || v_row."award_id"::text, (v_row."tenant_id")::text, null, 'better-supabase/funding');
  perform better_supabase.audit_event(
    event_type => 'funding_delivery.registered',
    category => 'data',
    target_type => 'funding_delivery',
    record_id => v_row."id"::text,
    summary => 'Funded care registered',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'fundingAwardId', v_row."award_id", 'fundingDeliveryId', v_row."id", 'subjectType', v_award."subject_type", 'subjectId', v_award."subject_id", 'sourceType', v_row."source_type", 'sourceId', v_row."source_id", 'deliveredOn', v_row."delivered_on", 'units', v_row."units")
  );
  v_start := (case v_award."period" when 'week' then date_trunc('week', v_row."delivered_on")::date when 'month' then date_trunc('month', v_row."delivered_on")::date else v_award."starts_on" end);
  select coalesce(sum(x."units"), 0) into v_used from "better_supabase"."funding_deliveries" x
  where x."tenant_id" = v_award."tenant_id" and x."award_id" = v_award."id" and x."status" <> 'rejected'
    and x."delivered_on" >= v_start and x."delivered_on" < (case v_award."period" when 'week' then (v_start + 7) when 'month' then (v_start + interval '1 month')::date else coalesce(v_award."ends_on" + 1, 'infinity'::date) end);
  if v_used > v_award."units" and v_used - v_row."units" <= v_award."units" then
    perform "better_supabase".emit_event('funding_award.exceeded', jsonb_build_object('organizationId', v_award."tenant_id", 'fundingAwardId', v_award."id", 'fundingProductId', v_award."product_id", 'funderId', v_award."funder_id", 'subjectType', v_award."subject_type", 'subjectId', v_award."subject_id", 'status', v_award."status", 'periodStart', v_start, 'awarded', v_award."units", 'used', v_used), 'funding-awards/' || v_award."id"::text, (v_award."tenant_id")::text, null, 'better-supabase/funding');
  perform better_supabase.audit_event(
    event_type => 'funding_award.exceeded',
    category => 'data',
    target_type => 'funding_award',
    record_id => v_award."id"::text,
    summary => 'Funding award exceeded',
    tenant => (v_award."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_award."tenant_id", 'fundingAwardId', v_award."id", 'fundingProductId', v_award."product_id", 'funderId', v_award."funder_id", 'subjectType', v_award."subject_type", 'subjectId', v_award."subject_id", 'status', v_award."status", 'periodStart', v_start, 'awarded', v_award."units", 'used', v_used)
  );
    if better_supabase.import_run() is null then
      v_claims := current_setting('request.jwt.claims', true);
      perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
      perform "better_supabase"."notify"(jsonb_build_object(
      'type', 'funding_award.exceeded',
      'tenant', v_award."tenant_id",
      'actor', (select auth.uid()),
      'subject_type', v_award."subject_type",
      'subject_id', v_award."subject_id"::text,
      'summary', 'A funding award went over its units',
      'permission', 'funding.manage',
      'watchers', false,
      'key', 'funding-exceeded:' || v_award."id"::text || ':' || v_start::text,
      'data', jsonb_build_object('awardId', v_award."id", 'periodStart', v_start, 'awarded', v_award."units", 'used', v_used)
    ));
      perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
    end if;
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_funding_delivery_register"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'awardId', v_row."award_id", 'sourceType', v_row."source_type", 'sourceId', v_row."source_id", 'deliveredOn', v_row."delivered_on", 'units', v_row."units", 'performerId', v_row."performer_id", 'status', v_row."status", 'claimLineId', v_row."claim_line_id", 'note', v_row."note", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.register_import_source (
  id              text,
  label_key       text,
  description_key text,
  file_types      text[],
  entities        text[],
  docs_link       text   DEFAULT NULL::text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'not allowed to register an import source' using errcode = '42501', hint = 'IMPORT_FORBIDDEN';
  end if;
  insert into "better_supabase".import_sources ("id", "label_key", "description_key", "file_types", "entities", "docs_link")
  values (register_import_source.id, register_import_source.label_key, register_import_source.description_key,
    coalesce(register_import_source.file_types, '{}'), coalesce(register_import_source.entities, '{}'), register_import_source.docs_link)
  on conflict ("id") do update set
    "label_key" = excluded."label_key",
    "description_key" = excluded."description_key",
    "file_types" = excluded."file_types",
    "entities" = excluded."entities",
    "docs_link" = excluded."docs_link";
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.register_push_device (
  token       text,
  platform    text,
  provider    text DEFAULT 'expo'::text,
  device_name text DEFAULT NULL::text,
  app_version text DEFAULT NULL::text
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_user uuid := auth.uid();
  v_id uuid;
  v_new boolean;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if v_user is null then
    raise exception 'Sign in first' using errcode = '42501', hint = 'PUSH_FORBIDDEN';
  end if;
  if register_push_device.platform is null or register_push_device.platform not in ('ios', 'android', 'web') then
    raise exception 'Unknown push platform %', register_push_device.platform using errcode = '22023', hint = 'PUSH_PLATFORM';
  end if;
  if register_push_device.provider is null or register_push_device.provider not in ('expo', 'fcm', 'apns', 'webpush') then
    raise exception 'Unknown push provider %', register_push_device.provider using errcode = '22023', hint = 'PUSH_PROVIDER';
  end if;
  if register_push_device.token is null or length(register_push_device.token) not between 1 and 4096 then
    raise exception 'A push token is 1 to 4096 characters' using errcode = '22023', hint = 'PUSH_TOKEN';
  end if;
  insert into "better_supabase"."push_devices" as x ("user_id", "token", "platform", "provider", "device_name", "app_version")
  values (
    v_user,
    register_push_device.token,
    register_push_device.platform,
    register_push_device.provider,
    left(register_push_device.device_name, 200),
    left(register_push_device.app_version, 50)
  )
  on conflict ("token") do update set
    "user_id" = excluded."user_id",
    "platform" = excluded."platform",
    "provider" = excluded."provider",
    "device_name" = coalesce(excluded."device_name", x."device_name"),
    "app_version" = coalesce(excluded."app_version", x."app_version"),
    "last_seen_at" = now()
  returning x."id", (x.xmax = 0) into v_id, v_new;
  if v_new then
    perform "better_supabase".emit_event('push.device_registered', jsonb_build_object('deviceId', v_id::text, 'userId', v_user::text, 'platform', register_push_device.platform, 'provider', register_push_device.provider), 'push-devices/' || v_id::text, null, null, 'better-supabase/push');
  perform better_supabase.audit_event(
    event_type => 'push.device_registered',
    category => 'security',
    target_type => 'push_device',
    record_id => v_id::text,
    metadata => jsonb_build_object('deviceId', v_id::text, 'userId', v_user::text, 'platform', register_push_device.platform, 'provider', register_push_device.provider)
  );
  end if;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.register_sample (
  tenant uuid,
  input  jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."lims_samples";
  v_seq bigint;
  v_number text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (register_sample.tenant is not null and coalesce(better_supabase.can('tenant', register_sample.tenant, 'lims.write'), false))) then
    raise exception 'not allowed to register samples' using errcode = '42501', hint = 'LIMS_FORBIDDEN';
  end if;
  if jsonb_typeof(register_sample.input) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'LIMS_INVALID';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_lims_sample_register"(uuid, jsonb)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::jsonb)', v_hook::oid::regproc)
        using register_sample.tenant, register_sample.input;
    end if;
  end;
  if (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'lims_sample' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end) is not null then
    v_number := (case when split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 1) = 'lims_sample' then nullif(split_part(coalesce(current_setting('better_supabase.fixed_number', true), ''), chr(31), 2), '') end);
    if better_supabase.import_run() is null then
      raise exception 'a fixed number is only accepted during an import' using errcode = '42501', hint = 'NUMBER_FIXED_FORBIDDEN';
    end if;
    v_seq := coalesce(substring(v_number from '([0-9]+)$')::bigint, 0);
    perform set_config('better_supabase.fixed_number', '', true);
  else
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(register_sample.tenant::text || ':lims_sample', 0));
  select coalesce(max(x."sequence"), 0) + 1 into v_seq from "better_supabase"."lims_samples" x where x."tenant_id" = register_sample.tenant;
  v_number := 'SMP-' || v_seq::text;
  end if;
  begin
    insert into "better_supabase"."lims_samples" ("tenant_id", "number", "sequence", "title", "kind", "lot", "received_on", "notes", "created_by")
    values (register_sample.tenant, v_number, v_seq, trim(register_sample.input ->> 'title'),
      nullif(trim(register_sample.input ->> 'kind'), ''), nullif(trim(register_sample.input ->> 'lot'), ''),
      coalesce((register_sample.input ->> 'receivedOn')::date, current_date),
      nullif(trim(register_sample.input ->> 'notes'), ''), auth.uid())
    returning * into v_row;
  exception when check_violation or not_null_violation or invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
    raise exception 'a sample needs a title of 1 to 200 characters, a kind and lot of up to 100 and notes of up to 4000' using errcode = '22023', hint = 'LIMS_INVALID';
  end;
  perform "better_supabase".emit_event('lims_sample.registered', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'status', v_row."status"), 'lims-samples/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/lims');
  perform better_supabase.audit_event(
    event_type => 'lims_sample.registered',
    category => 'data',
    target_type => 'lims_sample',
    record_id => v_row."id"::text,
    target_label => v_row."number",
    summary => 'sample registered',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'status', v_row."status")
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_lims_sample_register"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'number', v_row."number", 'title', v_row."title", 'kind', v_row."kind", 'lot', v_row."lot", 'receivedOn', v_row."received_on", 'status', v_row."status", 'notes', v_row."notes", 'rejectionReason', v_row."rejection_reason", 'completedAt', v_row."completed_at", 'releasedAt', v_row."released_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.register_service_principal (
  principal  uuid,
  tenant     uuid,
  name       text,
  role       text,
  is_default boolean DEFAULT false,
  created_by uuid    DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'Service principals are managed by the service' using errcode = '42501', hint = 'SERVICE_PRINCIPAL_FORBIDDEN';
  end if;
  if register_service_principal.created_by is not null and not (
    coalesce(better_supabase.member_can(register_service_principal.created_by, register_service_principal.tenant, 'service_accounts.manage'), false)
    and coalesce(better_supabase.can_assign_as(register_service_principal.created_by, register_service_principal.tenant, register_service_principal.role), false)
  ) then
    raise exception 'You may not manage service principals with this role' using errcode = '42501', hint = 'SERVICE_PRINCIPAL_FORBIDDEN';
  end if;
  if not exists (
    select 1 from auth.users u
    where u.id = register_service_principal.principal
      and coalesce((u.raw_app_meta_data ->> 'bsb_service_principal')::boolean, false)
      and u.banned_until > now() + interval '50 years'
  ) then
    raise exception 'The user is not a service principal: create it with createServiceAccounts().create' using errcode = '22023', hint = 'SERVICE_PRINCIPAL_USER';
  end if;
  if not ((select r."id" from "better_supabase"."roles" r where (r."id"::text = (register_service_principal.role)::text or r."key" = (register_service_principal.role)::text) order by (r."id"::text = (register_service_principal.role)::text) desc limit 1) is not null) then
    raise exception 'Unknown role %', register_service_principal.role using errcode = '22023', hint = 'ORGANIZATION_ROLE_UNKNOWN';
  end if;
  if register_service_principal.is_default then
    update "better_supabase"."service_principals" set "is_default" = false
    where "tenant_id" = register_service_principal.tenant and "is_default";
  end if;
  insert into "better_supabase"."service_principals" ("id", "tenant_id", "name", "role", "is_default", "created_by")
  values (register_service_principal.principal, register_service_principal.tenant, register_service_principal.name,
    register_service_principal.role, coalesce(register_service_principal.is_default, false), register_service_principal.created_by);
  insert into "public"."memberships" ("organization_id", "user_id", "role")
  values (register_service_principal.tenant, register_service_principal.principal, (select r."id" from "better_supabase"."roles" r where (r."id"::text = (register_service_principal.role)::text or r."key" = (register_service_principal.role)::text) order by (r."id"::text = (register_service_principal.role)::text) desc limit 1));
  perform "better_supabase".emit_event('service_principal.created', jsonb_build_object('organizationId', register_service_principal.tenant::text, 'id', register_service_principal.principal, 'name', register_service_principal.name, 'role', register_service_principal.role), 'service-principals/' || register_service_principal.principal::text, (register_service_principal.tenant)::text, null, 'better-supabase/service-accounts');
  perform better_supabase.audit_event(
    event_type => 'service_principal.created',
    category => 'access',
    target_type => 'service_principal',
    record_id => register_service_principal.principal::text,
    target_label => register_service_principal.name,
    tenant => (register_service_principal.tenant)::uuid,
    metadata => jsonb_build_object('organizationId', register_service_principal.tenant::text, 'id', register_service_principal.principal, 'name', register_service_principal.name, 'role', register_service_principal.role),
    actor_id => coalesce(register_service_principal.created_by, auth.uid())
  );
  return jsonb_build_object('id', register_service_principal.principal, 'tenant', register_service_principal.tenant,
    'name', register_service_principal.name, 'role', register_service_principal.role,
    'isDefault', coalesce(register_service_principal.is_default, false));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.register_sso_provider (
  tenant       uuid,
  provider     uuid,
  domains      text[],
  metadata_url text   DEFAULT NULL::text,
  actor        uuid   DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."sso_providers";
begin
  perform "better_supabase"."check_sso_provider"(register_sso_provider.tenant, register_sso_provider.domains, register_sso_provider.actor);
  insert into "better_supabase"."sso_providers" as x ("id", "tenant_id", "metadata_url", "domains")
  values (register_sso_provider.provider, register_sso_provider.tenant, register_sso_provider.metadata_url,
    (select array_agg(distinct lower(w.domain) order by lower(w.domain)) from unnest(register_sso_provider.domains) as w(domain)))
  on conflict ("id") do update set "metadata_url" = excluded."metadata_url", "domains" = excluded."domains"
  where x."tenant_id" = excluded."tenant_id"
  returning * into v_row;
  if v_row."id" is null then
    raise exception 'The provider belongs to another organization' using errcode = '42501', hint = 'SSO_FORBIDDEN';
  end if;
  perform "better_supabase".emit_event('sso_provider.registered', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'providerId', v_row."id", 'domains', to_jsonb(v_row."domains"), 'userId', register_sso_provider.actor), 'organizations/' || v_row."tenant_id"::text, (v_row."tenant_id")::text, null, 'better-supabase/sso');
  perform better_supabase.audit_event(
    event_type => 'sso_provider.registered',
    category => 'security',
    target_type => 'sso_provider',
    record_id => v_row."id"::text,
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'providerId', v_row."id", 'domains', to_jsonb(v_row."domains"), 'userId', register_sso_provider.actor),
    actor_id => register_sso_provider.actor
  );
  return to_jsonb(v_row);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.reimburse_expense_report (
  report_id uuid,
  paid_at   timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  reference text                     DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."expense_reports"%rowtype;
  v_approval "better_supabase"."approval_requests"%rowtype;
  v_tx uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."expense_reports" x where x."id" = reimburse_expense_report.report_id for update;
  if not found then
    raise exception 'no such expense report' using errcode = 'P0002', hint = 'EXPENSE_REPORT_NOT_FOUND';
  end if;
  select * into v_approval from "better_supabase"."approval_requests" p where p."id" = v_row."approval_id";
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'expenses.manage'), false)) then
    raise exception 'not allowed to reimburse expenses' using errcode = '42501', hint = 'EXPENSES_FORBIDDEN';
  end if;
  if (case when v_row."cancelled_at" is not null then 'cancelled' when v_row."reimbursed_at" is not null then 'reimbursed' when v_row."approved_at" is not null then 'approved' when v_approval."status" = 'pending' then 'submitted' when v_approval."status" in ('rejected', 'expired') then 'rejected' else 'draft' end) <> 'approved' then
    raise exception 'only an approved report can be reimbursed' using errcode = '55000', hint = 'EXPENSE_REPORT_LOCKED';
  end if;
  v_tx := "better_supabase"."ledger_post"(v_row."tenant_id", 'expense.reimbursed',
    jsonb_build_array(
      jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_row."tenant_id", 'expense_payable', 'expenses:payable:' || v_row."user_id"::text || ':' || v_row."currency", 'Expenses owed ' || v_row."currency", v_row."currency"::text, 0::smallint, 'users', v_row."user_id"::text, v_row."user_id", true, 'expenses.read', 'expenses', null), 'amount', coalesce((select sum(y."amount") from "better_supabase"."expense_lines" y where y."report_id" = v_row."id"), 0)),
      jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_row."tenant_id", 'expense_cash', 'expenses:cash:' || v_row."currency", 'Expenses paid ' || v_row."currency", v_row."currency"::text, 0::smallint, null, null, null, true, 'expenses.read', 'expenses', null), 'amount', -coalesce((select sum(y."amount") from "better_supabase"."expense_lines" y where y."report_id" = v_row."id"), 0))),
    'expenses', v_row."id"::text, left('Reimbursed: ' || v_row."title", 500), 'expense:' || v_row."id"::text || ':reimbursed',
    reimburse_expense_report.paid_at,
    jsonb_strip_nulls(jsonb_build_object('reportId', v_row."id", 'reference', nullif(trim(reimburse_expense_report.reference), ''))));
  update "better_supabase"."expense_reports" x set "reimbursed_at" = coalesce(reimburse_expense_report.paid_at, now()), "reimbursement_transaction_id" = v_tx, "updated_at" = now()
    where x."id" = v_row."id"
    returning * into v_row;
  if not better_supabase.import_run() is not null then
    perform "better_supabase"."accounting_post_source"('expense_reimbursement', v_row."id"::text);
  end if;
  perform "better_supabase".emit_event('expense_report.reimbursed', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'userId', v_row."user_id", 'status', (case when v_row."cancelled_at" is not null then 'cancelled' when v_row."reimbursed_at" is not null then 'reimbursed' when v_row."approved_at" is not null then 'approved' when v_approval."status" = 'pending' then 'submitted' when v_approval."status" in ('rejected', 'expired') then 'rejected' else 'draft' end), 'total', coalesce((select sum(y."amount") from "better_supabase"."expense_lines" y where y."report_id" = v_row."id"), 0)::text, 'currency', v_row."currency", 'transactionId', v_tx), 'expense-reports/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/expenses');
  perform better_supabase.audit_event(
    event_type => 'expense_report.reimbursed',
    category => 'billing',
    target_type => 'expense_report',
    record_id => v_row."id"::text,
    target_label => v_row."title",
    summary => 'reimbursed an expense report',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'userId', v_row."user_id", 'status', (case when v_row."cancelled_at" is not null then 'cancelled' when v_row."reimbursed_at" is not null then 'reimbursed' when v_row."approved_at" is not null then 'approved' when v_approval."status" = 'pending' then 'submitted' when v_approval."status" in ('rejected', 'expired') then 'rejected' else 'draft' end), 'total', coalesce((select sum(y."amount") from "better_supabase"."expense_lines" y where y."report_id" = v_row."id"), 0)::text, 'currency', v_row."currency", 'transactionId', v_tx)
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'userId', v_row."user_id", 'title', v_row."title", 'currency', v_row."currency", 'note', v_row."note", 'status', (case when v_row."cancelled_at" is not null then 'cancelled' when v_row."reimbursed_at" is not null then 'reimbursed' when v_row."approved_at" is not null then 'approved' when v_approval."status" = 'pending' then 'submitted' when v_approval."status" in ('rejected', 'expired') then 'rejected' else 'draft' end), 'total', coalesce((select sum(y."amount") from "better_supabase"."expense_lines" y where y."report_id" = v_row."id"), 0)::text, 'approvalId', v_row."approval_id", 'submittedAt', v_row."submitted_at", 'approvedAt', v_row."approved_at", 'approvalTransactionId', v_row."approval_transaction_id", 'reimbursedAt', v_row."reimbursed_at", 'reimbursementTransactionId', v_row."reimbursement_transaction_id", 'cancelledAt', v_row."cancelled_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at",
      'lines', (select coalesce(jsonb_agg(jsonb_build_object('id', l."id", 'reportId', l."report_id", 'categoryId', l."category_id", 'spentOn', l."spent_on", 'description', l."description", 'merchant', l."merchant", 'dimensions', l."dimensions", 'amount', l."amount"::text, 'currency', (select rc."currency" from "better_supabase"."expense_reports" rc where rc."id" = l."report_id"), 'receipts', (select count(*) from "better_supabase"."attachments" t where t."subject_type" = 'expense_line' and t."subject_id" = l."id"::text and t."uploaded_at" is not null and t."status" <> 'infected'), 'createdAt', l."created_at", 'updatedAt', l."updated_at") order by l."spent_on", l."created_at"), '[]'::jsonb) from "better_supabase"."expense_lines" l where l."report_id" = v_row."id"));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.reject_return (
  return_id uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_return record;
  v_order record;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."id" as id, x."order_id" as order_id, x."status" as status into v_return
  from "better_supabase"."order_returns" x where x."id" = reject_return.return_id for update;
  if not found then
    raise exception 'return not found' using errcode = 'P0002', hint = 'ORDERS_RETURN_NOT_FOUND';
  end if;
  select x."id" as id, x."tenant_id" as tenant, x."number" as number, x."customer_id" as customer, x."status" as status, x."currency" as currency, x."total" as total, x."paid_total" as paid_total, x."refunded_total" as refunded_total, x."tax_total" as tax_total, x."tax_inclusive" as tax_inclusive, x."invoice_number" as invoice_number, x."placed_at" as placed_at into v_order from "better_supabase"."orders" x where x."id" = v_return.order_id for update;
  if not found then
    raise exception 'order not found' using errcode = 'P0002', hint = 'ORDERS_ORDER_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_order.tenant, 'orders.manage'), false)) then
    raise exception 'not allowed to manage these orders' using errcode = '42501', hint = 'ORDERS_FORBIDDEN';
  end if;
  if v_return.status <> 'requested' then
    raise exception 'only a requested return can be rejected' using errcode = '55000', hint = 'ORDERS_TRANSITION_INVALID';
  end if;
  update "better_supabase"."order_returns" x set "status" = 'rejected' where x."id" = v_return.id;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.reject_review (
  review_id uuid,
  reason    text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."reviews"%rowtype;
begin
  select * into v_row from "better_supabase"."reviews" x where x."id" = reject_review.review_id for update;
  if not found then
    raise exception 'review not found' using errcode = 'P0002', hint = 'REVIEW_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'reviews.manage'), false)) then
    raise exception 'not allowed to moderate reviews' using errcode = '42501', hint = 'REVIEW_FORBIDDEN';
  end if;
  perform "better_supabase"."moderation_apply"("better_supabase"."review_moderation_item"(v_row."id"), 'hide', reject_review.reason, false);
  select * into v_row from "better_supabase"."reviews" x where x."id" = reject_review.review_id;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'authorId', v_row."author_id", 'authorName', v_row."author_name", 'mine', coalesce(v_row."author_id" = auth.uid(), false), 'rating', v_row."rating", 'title', v_row."title", 'body', v_row."body", 'status', v_row."status", 'verified', v_row."verified", 'rejectionReason', v_row."rejection_reason", 'reply', v_row."reply", 'repliedAt', v_row."replied_at", 'publishedAt', v_row."published_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.reject_sample (
  sample_id uuid,
  reason    text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."lims_samples";
  v_reason text := trim(reject_sample.reason);
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."lims_samples" x where x."id" = reject_sample.sample_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'lims.read'), false))) then
    raise exception 'no such sample' using errcode = 'P0002', hint = 'LIMS_SAMPLE_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'lims.manage'), false))) then
    raise exception 'not allowed to reject samples' using errcode = '42501', hint = 'LIMS_FORBIDDEN';
  end if;
  if v_reason is null or length(v_reason) not between 1 and 500 then
    raise exception 'a rejection needs a reason of 1 to 500 characters' using errcode = '22023', hint = 'LIMS_INVALID';
  end if;
  if v_row."status" not in ('registered', 'in_testing', 'completed') then
    raise exception 'a released or rejected sample cannot be rejected' using errcode = '22023', hint = 'LIMS_INVALID';
  end if;
  update "better_supabase"."lims_samples" x set "status" = 'rejected', "rejection_reason" = v_reason, "updated_at" = now()
  where x."id" = v_row."id" returning * into v_row;
  perform "better_supabase".emit_event('lims_sample.rejected', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'status', v_row."status"), 'lims-samples/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/lims');
  perform better_supabase.audit_event(
    event_type => 'lims_sample.rejected',
    category => 'data',
    target_type => 'lims_sample',
    record_id => v_row."id"::text,
    target_label => v_row."number",
    summary => 'sample rejected',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'status', v_row."status")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'number', v_row."number", 'title', v_row."title", 'kind', v_row."kind", 'lot', v_row."lot", 'receivedOn', v_row."received_on", 'status', v_row."status", 'notes', v_row."notes", 'rejectionReason', v_row."rejection_reason", 'completedAt', v_row."completed_at", 'releasedAt', v_row."released_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.relation_rollup (
  tenant       uuid,
  kind         text,
  subject_type text,
  subject_id   text,
  of_type      text,
  column_name  text,
  agg          text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  v_table text;
  v_id_col text;
  v_tenant_col text;
  v_ids text[];
  v_result jsonb;
begin
  if relation_rollup.agg is null or relation_rollup.agg not in ('count', 'sum', 'avg', 'min', 'max') then
    raise exception 'agg must be count, sum, avg, min or max' using errcode = '22023', hint = 'RELATION_ROLLUP_INVALID';
  end if;
  if relation_rollup.agg <> 'count' and relation_rollup.column_name is null then
    raise exception 'this aggregate needs a column' using errcode = '22023', hint = 'RELATION_ROLLUP_INVALID';
  end if;
  case relation_rollup.of_type
    when 'message' then v_table := '"better_supabase"."messages"'; v_id_col := 'id'; v_tenant_col := 'tenant_id';
    when 'conversation' then v_table := '"better_supabase"."conversations"'; v_id_col := 'id'; v_tenant_col := 'tenant_id';
    when 'channel' then v_table := '"better_supabase"."channels"'; v_id_col := 'id'; v_tenant_col := 'tenant_id';
    when 'company' then v_table := '"better_supabase"."companies"'; v_id_col := 'id'; v_tenant_col := 'tenant_id';
