CREATE OR REPLACE FUNCTION better_supabase.relations_subject_merge (
  subject_table text,
  keep          text,
  drop          text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_type text;
  v_keep text := keep;
  v_drop text := drop;
begin
  for v_type in select unnest(case subject_table when 'better_supabase.messages' then array['message'] when 'better_supabase.conversations' then array['conversation'] when 'better_supabase.channels' then array['channel'] when 'better_supabase.companies' then array['company'] when 'better_supabase.people' then array['person'] when 'better_supabase.deals' then array['deal'] when 'better_supabase.courses' then array['course'] when 'better_supabase.posts' then array['post'] when 'better_supabase.activities' then array['activity'] when 'better_supabase.quotes' then array['quote'] when 'better_supabase.work_items' then array['work_item'] when 'better_supabase.employees' then array['employee'] when 'better_supabase.ledger_accounts' then array['ledger_account'] when 'better_supabase.invoices' then array['invoice'] when 'better_supabase.products' then array['product'] when 'better_supabase.product_variants' then array['product_variant'] when 'better_supabase.rfqs' then array['rfq'] when 'better_supabase.tills' then array['till'] when 'better_supabase.orders' then array['order'] when 'better_supabase.calendar_events' then array['calendar_event'] when 'better_supabase.bookings' then array['booking'] when 'better_supabase.assets' then array['asset'] when 'better_supabase.asset_locations' then array['asset_location'] when 'better_supabase.leases' then array['lease'] when 'better_supabase.expense_reports' then array['expense_report'] when 'better_supabase.expense_lines' then array['expense_line'] when 'better_supabase.donation_funds' then array['donation_fund'] when 'better_supabase.warranty_claims' then array['warranty_claim'] when 'better_supabase.work_orders' then array['work_order'] when 'better_supabase.shipments' then array['shipment'] when 'better_supabase.contracts' then array['contract'] when 'better_supabase.controls' then array['control'] when 'better_supabase.compliance_policies' then array['compliance_policy'] when 'better_supabase.qualification_types' then array['qualification_type'] when 'better_supabase.risks' then array['risk'] when 'better_supabase.cases' then array['case'] when 'better_supabase.inspections' then array['inspection'] when 'better_supabase.inspection_programs' then array['inspection_program'] when 'better_supabase.inspection_findings' then array['inspection_finding'] when 'better_supabase.forms' then array['form'] when 'better_supabase.meetings' then array['meeting'] when 'better_supabase.meeting_decisions' then array['meeting_decision'] when 'better_supabase.maintenance_plans' then array['maintenance_plan'] when 'better_supabase.dam_usage_rights' then array['dam_usage_right'] when 'better_supabase.lims_samples' then array['lims_sample'] when 'better_supabase.tax_codes' then array['tax_code'] when 'better_supabase.production_orders' then array['production_order'] when 'better_supabase.work_centers' then array['work_center'] when 'better_supabase.bank_accounts' then array['bank_account'] when 'better_supabase.care_plans' then array['care_plan'] when 'better_supabase.incidents' then array['incident'] when 'better_supabase.content_entries' then array['content_entry'] when 'better_supabase.documents' then array['document'] when 'public.customers' then array['customer'] when 'better_supabase.drive_nodes' then array['drive_node'] when 'public.organizations' then array['organization'] when 'better_supabase.applications' then array['application'] when 'public.change_requests' then array['change_request'] when 'public.projects' then array['project'] when 'public.tasks' then array['task'] else '{}'::text[] end) loop
    declare
      v_row record;
      v_st text; v_si text; v_tt text; v_ti text;
    begin
      for v_row in
        select x."id" as id, x."tenant_id"::text as tenant, x."kind" as kind, x."source_type" as st, x."source_id" as si, x."target_type" as tt, x."target_id" as ti
        from "better_supabase"."relations" x
        where (x."source_type" = v_type and x."source_id" = v_drop) or (x."target_type" = v_type and x."target_id" = v_drop)
        for update
      loop
        v_st := v_row.st; v_tt := v_row.tt;
        v_si := case when v_row.st = v_type and v_row.si = v_drop then v_keep else v_row.si end;
        v_ti := case when v_row.tt = v_type and v_row.ti = v_drop then v_keep else v_row.ti end;
        if v_row.kind in ('relates') and (v_st, v_si) > (v_tt, v_ti) then
          select v_tt, v_ti, v_st, v_si into v_st, v_si, v_tt, v_ti;
        end if;
        if (v_st = v_tt and v_si = v_ti) or exists (
          select 1 from "better_supabase"."relations" y
          where y."id" <> v_row.id and y."tenant_id"::text = v_row.tenant and y."kind" = v_row.kind
            and y."source_type" = v_st and y."source_id" = v_si and y."target_type" = v_tt and y."target_id" = v_ti
        ) then
          delete from "better_supabase"."relations" y where y."id" = v_row.id;
        else
          update "better_supabase"."relations" y set "source_type" = v_st, "source_id" = v_si, "target_type" = v_tt, "target_id" = v_ti
          where y."id" = v_row.id;
        end if;
      end loop;
    end;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_ai_chat_stream (
  chat           uuid,
  stream         text,
  status         text   DEFAULT 'completed'::text,
  usage          jsonb  DEFAULT NULL::jsonb,
  generation_id  text   DEFAULT NULL::text,
  error          text   DEFAULT NULL::text,
  cost_micro_usd bigint DEFAULT NULL::bigint
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_status text := coalesce(release_ai_chat_stream.status, 'completed');
  v_found boolean := false;
  v_run uuid;
  v_usage jsonb;
  v_owner uuid;
  v_tenant uuid;
begin
  if not coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then
    raise exception 'Only the server saves replies' using errcode = '42501', hint = 'AI_CHAT_FORBIDDEN';
  end if;
  if v_status not in ('completed', 'failed', 'cancelled') then
    raise exception 'A run ends completed, failed or cancelled, not %', v_status using errcode = '22023', hint = 'AI_RUN_INVALID';
  end if;
  update "better_supabase"."ai_runs" x set
    "status" = v_status,
    "usage" = coalesce(release_ai_chat_stream.usage, x."usage"),
    "provider_generation_id" = coalesce(release_ai_chat_stream.generation_id, x."provider_generation_id"),
    "error" = release_ai_chat_stream.error,
    "cost_micro_usd" = coalesce(release_ai_chat_stream.cost_micro_usd, x."cost_micro_usd"),
    "ended_at" = coalesce(x."ended_at", now())
  where x."chat_id" = release_ai_chat_stream.chat and x."stream_id" = release_ai_chat_stream.stream
  returning x."id", x."usage", x."owner_id" into v_run, v_usage, v_owner;
  if v_run is not null and jsonb_typeof(v_usage) = 'object' then
    select x."tenant_id" into v_tenant from "better_supabase"."ai_chats" x where x."id" = release_ai_chat_stream.chat;
    if v_tenant is not null then
    if jsonb_typeof(v_usage -> 'inputTokens') = 'number' and (v_usage -> 'inputTokens')::numeric > 0 then
      perform "better_supabase"."record_usage"(v_tenant, 'ai.input_tokens', (v_usage -> 'inputTokens')::numeric, 'ai_run:' || v_run || ':' || 'inputTokens', 'ai-chat', jsonb_build_object('chatId', release_ai_chat_stream.chat, 'runId', v_run), v_owner);
    end if;
    if jsonb_typeof(v_usage -> 'outputTokens') = 'number' and (v_usage -> 'outputTokens')::numeric > 0 then
      perform "better_supabase"."record_usage"(v_tenant, 'ai.output_tokens', (v_usage -> 'outputTokens')::numeric, 'ai_run:' || v_run || ':' || 'outputTokens', 'ai-chat', jsonb_build_object('chatId', release_ai_chat_stream.chat, 'runId', v_run), v_owner);
    end if;
    end if;
  end if;
  update "better_supabase"."ai_chats" x set "active_stream_id" = null, "active_run_id" = null, "updated_at" = now()
  where x."id" = release_ai_chat_stream.chat and x."active_stream_id" = release_ai_chat_stream.stream
  returning true into v_found;
  if coalesce(v_found, false) then
    perform "better_supabase"."ai_chat_notify"(release_ai_chat_stream.chat, null, 'stream.ended', jsonb_build_object('streamId', release_ai_chat_stream.stream, 'status', v_status), false);
  end if;
  return coalesce(v_found, false);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_allocation (
  allocation uuid,
  quantity   numeric DEFAULT NULL::numeric
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row record;
  v_left numeric;
  v_backorder numeric;
  v_held numeric;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."id" as id, x."tenant_id" as tenant, x."variant_id" as variant, x."location_id" as location,
    x."document_type" as document_type, x."document_id" as document_id, x."quantity" as quantity,
    x."allocated" as allocated, x."fulfilled" as fulfilled, x."status" as status
  into v_row from "better_supabase"."stock_allocations" x where x."id" = release_allocation.allocation for update;
  if not found then
    raise exception 'allocation not found' using errcode = 'P0002', hint = 'INVENTORY_ALLOCATION_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_row.tenant, 'inventory.reserve'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  if v_row.status <> 'open' then
    raise exception 'the allocation is no longer open' using errcode = '55000', hint = 'INVENTORY_ALLOCATION_CLOSED';
  end if;
  v_left := v_row.quantity - v_row.fulfilled;
  if release_allocation.quantity is not null
    and (release_allocation.quantity <= 0 or release_allocation.quantity > v_left) then
    raise exception 'the quantity must be more than zero and at most what the allocation has left' using errcode = '22023', hint = 'INVENTORY_QUANTITY_INVALID';
  end if;
  if release_allocation.quantity is null or release_allocation.quantity = v_left then
    v_held := v_row.allocated;
    if v_held > 0 then
      update "better_supabase"."stock_levels" x set "reserved" = greatest(x."reserved" + -v_held, 0), "updated_at" = now()
    where x."variant_id" = v_row.variant and x."location_id" = v_row.location;
    end if;
    update "better_supabase"."stock_allocations" x set "allocated" = 0, "status" = 'released', "updated_at" = now() where x."id" = v_row.id;
  else
    v_backorder := v_left - v_row.allocated;
    v_held := greatest(release_allocation.quantity - v_backorder, 0);
    if v_held > 0 then
      update "better_supabase"."stock_levels" x set "reserved" = greatest(x."reserved" + -v_held, 0), "updated_at" = now()
    where x."variant_id" = v_row.variant and x."location_id" = v_row.location;
    end if;
    update "better_supabase"."stock_allocations" x set "allocated" = x."allocated" - v_held,
      "quantity" = x."quantity" - release_allocation.quantity, "updated_at" = now()
    where x."id" = v_row.id;
  end if;
  perform "better_supabase".emit_event('allocation.released', jsonb_build_object('organizationId', v_row.tenant, 'id', v_row.id, 'variantId', v_row.variant, 'locationId', v_row.location,
        'documentType', v_row.document_type, 'documentId', v_row.document_id, 'quantity', v_row.quantity::text, 'released', coalesce(release_allocation.quantity, v_left)::text), 'stock-allocations/' || v_row.id::text, (v_row.tenant)::text, null, 'better-supabase/inventory');
  if v_held > 0 then
    perform "better_supabase"."fill_backorders"(v_row.tenant, v_row.variant, v_row.location);
  end if;
  return (select jsonb_build_object('id', x."id", 'variantId', x."variant_id", 'locationId', x."location_id",
    'documentType', x."document_type", 'documentId', x."document_id", 'lineId', x."line_id",
    'quantity', x."quantity"::text, 'allocated', x."allocated"::text, 'fulfilled', x."fulfilled"::text,
    'backordered', x."backordered"::text, 'status', x."status", 'createdAt', x."created_at") from "better_supabase"."stock_allocations" x where x."id" = v_row.id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_allocations (
  tenant        uuid,
  document_type text,
  document_id   text
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row record;
  v_count integer := 0;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', release_allocations.tenant, 'inventory.reserve'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  for v_row in
    select x."id" as id, x."tenant_id" as tenant, x."variant_id" as variant, x."location_id" as location,
      x."document_type" as document_type, x."document_id" as document_id, x."quantity" as quantity, x."allocated" as allocated
    from "better_supabase"."stock_allocations" x
    where x."tenant_id" = release_allocations.tenant and x."document_type" = release_allocations.document_type
      and x."document_id" = release_allocations.document_id and x."status" = 'open'
    order by x."created_at"
    for update
  loop
    if v_row.allocated > 0 then
      update "better_supabase"."stock_levels" x set "reserved" = greatest(x."reserved" + -v_row.allocated, 0), "updated_at" = now()
    where x."variant_id" = v_row.variant and x."location_id" = v_row.location;
    end if;
    update "better_supabase"."stock_allocations" x set "allocated" = 0, "status" = 'released', "updated_at" = now() where x."id" = v_row.id;
    perform "better_supabase".emit_event('allocation.released', jsonb_build_object('organizationId', v_row.tenant, 'id', v_row.id, 'variantId', v_row.variant, 'locationId', v_row.location,
        'documentType', v_row.document_type, 'documentId', v_row.document_id, 'quantity', v_row.quantity::text), 'stock-allocations/' || v_row.id::text, (v_row.tenant)::text, null, 'better-supabase/inventory');
    if v_row.allocated > 0 then
      perform "better_supabase"."fill_backorders"(v_row.tenant, v_row.variant, v_row.location);
    end if;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_asset (
  asset_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."assets"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."assets" x where x."id" = release_asset.asset_id for update;
  if not found or not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'assets.read'), false)) or (v_row."assignee_type" = 'member' and coalesce(v_row."assignee_id" = auth.uid()::text, false))) then
    raise exception 'asset not found' using errcode = 'P0002', hint = 'ASSETS_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'assets.assign'), false)) then
    raise exception 'not allowed to assign assets' using errcode = '42501', hint = 'ASSETS_FORBIDDEN';
  end if;
  if v_row."assignee_type" is not null then
    update "better_supabase"."asset_assignments" y set "released_at" = now()
    where y."asset_id" = v_row."id" and y."released_at" is null;
    update "better_supabase"."assets" x set "assignee_type" = null, "assignee_id" = null, "updated_at" = now()
      where x."id" = v_row."id"
      returning * into v_row;
    perform "better_supabase".emit_event('asset.released', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'kind', v_row."kind", 'name', v_row."name", 'status', v_row."status", 'locationId', v_row."location_id", 'assigneeType', v_row."assignee_type", 'assigneeId', v_row."assignee_id"), 'assets/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/assets');
  perform better_supabase.audit_event(
    event_type => 'asset.released',
    category => 'data',
    target_type => 'asset',
    record_id => v_row."id"::text,
    target_label => v_row."name",
    summary => 'released asset',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'kind', v_row."kind", 'name', v_row."name", 'status', v_row."status", 'locationId', v_row."location_id", 'assigneeType', v_row."assignee_type", 'assigneeId', v_row."assignee_id")
  );
  end if;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'locationId', v_row."location_id", 'kind', v_row."kind", 'name', v_row."name", 'tag', v_row."tag", 'serialNumber', v_row."serial_number", 'status', v_row."status", 'assigneeType', v_row."assignee_type", 'assigneeId', v_row."assignee_id", 'latitude', v_row."latitude", 'longitude', v_row."longitude", 'metadata', v_row."metadata", 'retiredAt', v_row."retired_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at") || jsonb_build_object('acquisitionCost', v_row."acquisition_cost"::text, 'currency', v_row."currency", 'acquiredOn', v_row."acquired_on", 'usefulLifeMonths', v_row."useful_life_months", 'residualValue', v_row."residual_value"::text, 'depreciationMethod', v_row."depreciation_method", 'depreciationRateBps', v_row."depreciation_rate_bps", 'disposedOn', v_row."disposed_on", 'disposalAmount', v_row."disposal_amount"::text);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_idempotent (
  scope  text,
  key    text,
  holder uuid
)
  RETURNS boolean
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  with released as (
    delete from "better_supabase"."idempotency_keys" k
    where k."scope" = release_idempotent.scope and k."key" = release_idempotent.key
      and k."status" = 'running' and k."holder" = release_idempotent.holder
    returning 1
  )
  select exists (select 1 from released)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_lease (
  key    text,
  holder uuid,
  scope  text DEFAULT ''::text
)
  RETURNS boolean
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  with released as (
    delete from "better_supabase"."idempotency_leases" l
    where l."scope" = release_lease.scope and l."key" = release_lease.key and l."holder" = release_lease.holder
    returning 1
  )
  select exists (select 1 from released)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_lease_claim (
  scope  text,
  key    text,
  holder uuid
)
  RETURNS boolean
  LANGUAGE sql
  SET search_path TO ''
  AS $function$
  with released as (
    delete from "better_supabase"."job_leases" l
    where l."scope" = release_lease_claim.scope and l."key" = release_lease_claim.key
      and l."holder" = release_lease_claim.holder and l."state" = 'held'
    returning 1
  )
  select exists (select 1 from released)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_ledger_hold (
  hold_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."ledger_holds"%rowtype;
begin
  select * into v_row from "better_supabase"."ledger_holds" x where x."id" = release_ledger_hold.hold_id;
  if not found then
    raise exception 'ledger hold not found' using errcode = 'P0002', hint = 'LEDGER_HOLD_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'ledger.post'), false)) then
    raise exception 'not allowed to post ledger transactions' using errcode = '42501', hint = 'LEDGER_FORBIDDEN';
  end if;
  v_row := "better_supabase"."ledger_release"(v_row."id");
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'accountId', v_row."account_id", 'amount', v_row."amount"::text, 'status', v_row."status", 'referenceType', v_row."reference_type", 'referenceId', v_row."reference_id", 'expiresAt', v_row."expires_at", 'transactionId', v_row."transaction_id", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_legal_hold (
  id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."legal_holds";
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'Only the service role releases legal holds' using errcode = '42501', hint = 'LEGAL_HOLD_FORBIDDEN';
  end if;
  update "better_supabase"."legal_holds" x set "released_at" = now(), "released_by" = auth.uid()
  where x."id" = release_legal_hold.id and x."released_at" is null
  returning * into v_row;
  if v_row."id" is null then
    return null;
  end if;
  perform "better_supabase".emit_event('legal_hold.released', jsonb_build_object('holdId', v_row."id", 'organizationId', v_row."tenant_id"::text, 'kind', v_row."kind", 'reason', v_row."reason"), 'legal-holds/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/data-lifecycle');
  perform better_supabase.audit_event(
    event_type => 'legal_hold.released',
    category => 'data',
    target_type => 'legal_hold',
    record_id => v_row."id"::text,
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('holdId', v_row."id", 'organizationId', v_row."tenant_id"::text, 'kind', v_row."kind", 'reason', v_row."reason")
  );
  return to_jsonb(v_row);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_order_hold (
  order_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_order record;
  v_target text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."id" as id, x."tenant_id" as tenant, x."number" as number, x."customer_id" as customer, x."status" as status, x."currency" as currency, x."total" as total, x."paid_total" as paid_total, x."refunded_total" as refunded_total, x."tax_total" as tax_total, x."tax_inclusive" as tax_inclusive, x."invoice_number" as invoice_number, x."placed_at" as placed_at into v_order from "better_supabase"."orders" x where x."id" = release_order_hold.order_id for update;
  if not found then
    raise exception 'order not found' using errcode = 'P0002', hint = 'ORDERS_ORDER_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_order.tenant, 'orders.manage'), false)) then
    raise exception 'not allowed to manage these orders' using errcode = '42501', hint = 'ORDERS_FORBIDDEN';
  end if;
  if v_order.status::text <> 'on_hold' then
    raise exception 'the order isn''t on hold' using errcode = '55000', hint = 'ORDERS_TRANSITION_INVALID';
  end if;
  select coalesce(x."held_from", 'confirmed') into v_target from "better_supabase"."orders" x where x."id" = v_order.id;
  perform "better_supabase"."order_transition"(v_order.id, v_target);
  update "better_supabase"."orders" x set "held_from" = null, "held_at" = null, "hold_reason" = null, "updated_at" = now()
  where x."id" = v_order.id;
  perform "better_supabase".emit_event('order.hold_released', jsonb_build_object('organizationId', v_order.tenant, 'subjectType', 'order', 'subjectId', v_order.id::text, 'id', v_order.id, 'number', v_order.number, 'customerId', v_order.customer, 'status', v_target), 'orders/' || v_order.id::text, (v_order.tenant)::text, null, 'better-supabase/orders');
  return "better_supabase"."order_json"(v_order.id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_pick_wave (
  wave_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."pick_waves";
  v_list uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."pick_waves" x where x."id" = release_pick_wave.wave_id for update;
  if not found then
    raise exception 'no such pick wave' using errcode = 'P0002', hint = 'WAREHOUSE_WAVE_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'warehouse.manage'), false))) then
    raise exception 'not allowed to manage pick waves' using errcode = '42501', hint = 'WAREHOUSE_FORBIDDEN';
  end if;
  if v_row."status" <> 'draft' then
    raise exception 'only a draft wave is released' using errcode = '55000', hint = 'WAREHOUSE_STATE';
  end if;
  if not exists (select 1 from "better_supabase"."pick_lists" x where x."wave_id" = v_row."id" and x."status" = 'open') then
    raise exception 'a wave needs a pick list before it is released' using errcode = '55000', hint = 'WAREHOUSE_STATE';
  end if;
  for v_list in select x."id" from "better_supabase"."pick_lists" x where x."wave_id" = v_row."id" and x."status" = 'open' order by x."created_at", x."id" loop
    perform "better_supabase"."pick_list_task"(v_list);
  end loop;
  update "better_supabase"."pick_waves" x set "status" = 'released', "released_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('pick_wave.released', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'name', v_row."name", 'locationId', v_row."location_id", 'status', v_row."status"), 'pick-waves/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/warehouse');
  perform better_supabase.audit_event(
    event_type => 'pick_wave.released',
    category => 'data',
    target_type => 'pick_wave',
    record_id => v_row."id"::text,
    target_label => v_row."name",
    summary => 'pick wave released',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'name', v_row."name", 'locationId', v_row."location_id", 'status', v_row."status")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'name', v_row."name", 'locationId', v_row."location_id", 'status', v_row."status", 'releasedAt', v_row."released_at", 'completedAt', v_row."completed_at", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_production_order (
  order_id       uuid,
  allow_shortage boolean DEFAULT false
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."production_orders";
  v_bom "better_supabase"."boms";
  v_component record;
  v_allocation jsonb;
  v_shortages jsonb := '[]'::jsonb;
  v_claims text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."production_orders" x where x."id" = release_production_order.order_id for update;
  if not found then
    raise exception 'no such production order' using errcode = 'P0002', hint = 'PRODUCTION_ORDER_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'manufacturing.write'), false))) then
    raise exception 'not allowed to release production orders' using errcode = '42501', hint = 'MANUFACTURING_FORBIDDEN';
  end if;
  if v_row."status" <> 'draft' then
    raise exception 'the production order can''t move from % to %', v_row."status", 'released' using errcode = '55000', hint = 'PRODUCTION_ORDER_STATUS_INVALID', detail = jsonb_build_object('from', v_row."status", 'to', 'released')::text;
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_production_order_release"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  select * into v_bom from "better_supabase"."boms" x where x."id" = v_row."bom_id";
  insert into "better_supabase"."production_order_operations" ("tenant_id", "order_id", "operation_id", "sequence", "work_center_id", "title", "planned_minutes")
  select v_row."tenant_id", v_row."id", y."id", y."sequence", y."work_center_id", y."title",
    round(y."setup_minutes" + y."run_minutes_per_unit" * v_row."quantity", 2)
  from "better_supabase"."bom_operations" y where y."bom_id" = v_bom."id";
  for v_component in
    select y."id" as id, y."variant_id" as variant,
      "better_supabase"."production_quantity"(y."variant_id", y."quantity" * v_row."quantity" / v_bom."quantity" * (1 + y."scrap_bps" / 10000.0)) as quantity
    from "better_supabase"."bom_components" y where y."bom_id" = v_bom."id"
    order by y."position", y."id"
  loop
    v_claims := current_setting('request.jwt.claims', true);
  perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
  v_allocation := "better_supabase"."allocate_stock"(v_row."tenant_id", v_component.variant, v_row."location_id", v_component.quantity,
      'production_order', v_row."id"::text, v_component.id::text, true);
  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
    if (v_allocation ->> 'backordered')::numeric > 0 then
      v_shortages := v_shortages || jsonb_build_array(jsonb_build_object('variantId', v_component.variant,
        'quantity', v_component.quantity::text, 'backordered', v_allocation ->> 'backordered'));
    end if;
  end loop;
  if jsonb_array_length(v_shortages) > 0 and not coalesce(release_production_order.allow_shortage, false) then
    raise exception 'not enough stock for the production order''s components' using errcode = '23514',
      hint = 'PRODUCTION_ORDER_SHORTAGE', detail = jsonb_build_object('shortages', v_shortages)::text;
  end if;
  update "better_supabase"."production_orders" x set "status" = 'released', "released_at" = now(), "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('production_order.released', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'variantId', v_row."variant_id", 'quantity', v_row."quantity"::text, 'status', v_row."status"), 'production-orders/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/manufacturing');
  perform better_supabase.audit_event(
    event_type => 'production_order.released',
    category => 'data',
    target_type => 'production_order',
    record_id => v_row."id"::text,
    target_label => v_row."number",
    summary => 'production order released',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'variantId', v_row."variant_id", 'quantity', v_row."quantity"::text, 'status', v_row."status")
  );
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_production_order_release"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return (jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'number', v_row."number", 'variantId', v_row."variant_id", 'bomId', v_row."bom_id", 'quantity', v_row."quantity"::text, 'locationId', v_row."location_id", 'dueOn', v_row."due_on", 'status', v_row."status", 'producedQuantity', v_row."produced_quantity"::text, 'scrapQuantity', v_row."scrap_quantity"::text, 'outputLotId', v_row."output_lot_id", 'materialCost', v_row."material_cost"::text, 'laborCost', v_row."labor_cost"::text, 'currency', v_row."currency", 'note', v_row."note", 'releasedAt', v_row."released_at", 'startedAt', v_row."started_at", 'completedAt', v_row."completed_at", 'canceledAt', v_row."canceled_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at") || jsonb_build_object(
    'operations', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'orderId', y."order_id", 'operationId', y."operation_id", 'sequence', y."sequence", 'workCenterId', y."work_center_id", 'title', y."title", 'plannedMinutes', y."planned_minutes"::text, 'status', y."status", 'startedAt', y."started_at", 'finishedAt', y."finished_at", 'operatorId', y."operator_id", 'minutes', y."minutes"::text, 'inspectionId', y."inspection_id") order by y."sequence")
      from "better_supabase"."production_order_operations" y where y."order_id" = v_row."id"), '[]'::jsonb),
    'components', coalesce((select jsonb_agg(jsonb_build_object('componentId', y."id", 'variantId', y."variant_id",
        'quantity', "better_supabase"."production_quantity"(y."variant_id", y."quantity" * v_row."quantity" / x."quantity" * (1 + y."scrap_bps" / 10000.0))::text,
        'allocated', coalesce(al."allocated", 0)::text, 'backordered', coalesce(al."backordered", 0)::text,
        'consumed', coalesce((select sum(z."quantity") from "better_supabase"."production_consumptions" z
          where z."order_id" = v_row."id" and z."variant_id" = y."variant_id"), 0)::text)
      order by y."position", y."id")
      from "better_supabase"."boms" x join "better_supabase"."bom_components" y on y."bom_id" = x."id"
      left join "better_supabase"."stock_allocations" al on al."tenant_id" = v_row."tenant_id"
        and al."document_type" = 'production_order' and al."document_id" = v_row."id"::text
        and al."line_id" = y."id"::text and al."status" = 'open'
      where x."id" = v_row."bom_id"), '[]'::jsonb),
    'consumptions', coalesce((select jsonb_agg(jsonb_build_object('id', z."id", 'variantId', z."variant_id", 'lotId', z."lot_id",
        'serial', z."serial", 'quantity', z."quantity"::text, 'cost', z."cost"::text, 'currency', z."currency",
        'movementId', z."movement_id", 'createdAt', z."created_at") order by z."created_at", z."id")
      from "better_supabase"."production_consumptions" z where z."order_id" = v_row."id"), '[]'::jsonb)));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_promotions (
  p_order uuid
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row record;
  v_count integer := 0;
begin
  for v_row in
    update "better_supabase"."promotion_redemptions" x set "status" = 'released', "released_at" = now()
    where x."order_id" = p_order and x."status" = 'redeemed'
    returning x."promotion_id" as promotion, x."code_id" as code
  loop
    update "better_supabase"."promotions" x set "redemptions" = greatest(x."redemptions" - 1, 0) where x."id" = v_row.promotion;
    if v_row.code is not null then
      update "better_supabase"."promotion_codes" x set "redemptions" = greatest(x."redemptions" - 1, 0) where x."id" = v_row.code;
    end if;
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_reservation (
  reservation uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row record;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."id" as id, x."tenant_id" as tenant, x."variant_id" as variant, x."location_id" as location,
    x."quantity" as quantity, x."status" as status
  into v_row from "better_supabase"."stock_reservations" x where x."id" = release_reservation.reservation for update;
  if not found then
    return false;
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_row.tenant, 'inventory.reserve'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  if v_row.status <> 'active' then
    return false;
  end if;
  update "better_supabase"."stock_levels" x set "reserved" = greatest(x."reserved" - v_row.quantity, 0), "updated_at" = now()
  where x."variant_id" = v_row.variant and x."location_id" = v_row.location;
  update "better_supabase"."stock_reservations" x set "status" = 'released', "updated_at" = now()
  where x."id" = release_reservation.reservation;
  perform "better_supabase".emit_event('reservation.released', jsonb_build_object('organizationId', v_row.tenant, 'id', v_row.id, 'variantId', v_row.variant, 'locationId', v_row.location, 'quantity', v_row.quantity::text, 'reason', 'released'), 'stock-reservations/' || v_row.id::text, (v_row.tenant)::text, null, 'better-supabase/inventory');
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_sample (
  sample_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."lims_samples";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."lims_samples" x where x."id" = release_sample.sample_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'lims.read'), false))) then
    raise exception 'no such sample' using errcode = 'P0002', hint = 'LIMS_SAMPLE_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_row."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'lims.manage'), false))) then
    raise exception 'not allowed to release samples' using errcode = '42501', hint = 'LIMS_FORBIDDEN';
  end if;
  if v_row."status" <> 'completed' then
    raise exception 'only a completed sample can be released' using errcode = '22023', hint = 'LIMS_INVALID';
  end if;
  if exists (
    select 1 from (
      select distinct on (y."method_id") y."outcome" as outcome
      from "better_supabase"."lims_results" y where y."sample_id" = v_row."id"
      order by y."method_id", y."tested_at" desc, y."id" desc
    ) latest where latest.outcome = 'out_of_spec'
  ) then
    raise exception 'a method has an out of specification result; record a passing retest first' using errcode = '22023', hint = 'LIMS_INVALID';
  end if;
  update "better_supabase"."lims_samples" x set "status" = 'released', "released_at" = now(), "updated_at" = now()
  where x."id" = v_row."id" returning * into v_row;
  perform "better_supabase".emit_event('lims_sample.released', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'status', v_row."status"), 'lims-samples/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/lims');
  perform better_supabase.audit_event(
    event_type => 'lims_sample.released',
    category => 'data',
    target_type => 'lims_sample',
    record_id => v_row."id"::text,
    target_label => v_row."number",
    summary => 'sample released',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'number', v_row."number", 'status', v_row."status")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'number', v_row."number", 'title', v_row."title", 'kind', v_row."kind", 'lot', v_row."lot", 'receivedOn', v_row."received_on", 'status', v_row."status", 'notes', v_row."notes", 'rejectionReason', v_row."rejection_reason", 'completedAt', v_row."completed_at", 'releasedAt', v_row."released_at", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.release_workflow_semaphore (
  key    text,
  holder text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
begin
  delete from "better_supabase"."workflow_semaphores" x where x."key" = key and x."holder" = holder;
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.remind_approvals (
  after        interval DEFAULT '1 day'::interval,
  max_requests integer  DEFAULT 200
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_id uuid;
  v_count integer := 0;
begin
  for v_id in
    update "better_supabase"."approval_requests" r set "reminded_at" = now()
    where r."id" in (
      select x."id" from "better_supabase"."approval_requests" x
      where x."status" = 'pending'
        and (x."expires_at" is null or x."expires_at" > now())
        and x."created_at" <= now() - remind_approvals.after
        and (x."reminded_at" is null or x."reminded_at" <= now() - remind_approvals.after)
      order by x."created_at"
      limit greatest(coalesce(remind_approvals.max_requests, 200), 1)
      for update skip locked
    )
    returning r."id"
  loop
    perform "better_supabase"."approval_notify"(v_id, 'reminder');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.remind_due_saved_items (
  max_rows integer DEFAULT NULL::integer
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."saved_items"%rowtype;
  v_out jsonb := '[]'::jsonb;
begin
  if not auth.role() = 'service_role' then
    raise exception 'only the service role sends saved item reminders' using errcode = '42501', hint = 'SAVED_ITEM_FORBIDDEN';
  end if;
  for v_row in
    update "better_supabase"."saved_items" s set "reminded_at" = now()
    where s."id" in (
      select d."id" from "better_supabase"."saved_items" d
      where d."remind_at" <= now() and d."reminded_at" is null and d."completed_at" is null
      order by d."remind_at", d."id"
      limit least(greatest(coalesce(remind_due_saved_items.max_rows, 100), 1), 500)
      for update skip locked
    )
    returning s.*
  loop
    perform "better_supabase".emit_event('saved_item.reminded', jsonb_strip_nulls(jsonb_build_object('organizationId', v_row."tenant_id", 'savedItemId', v_row."id", 'userId', v_row."user_id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'note', v_row."note", 'remindAt', v_row."remind_at")), 'saved-items/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/collections');
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'id', v_row."id",
      'organizationId', v_row."tenant_id",
      'userId', v_row."user_id",
      'subjectType', v_row."subject_type",
      'subjectId', v_row."subject_id",
      'note', v_row."note",
      'remindAt', v_row."remind_at",
      'remindedAt', v_row."reminded_at",
      'completedAt', v_row."completed_at",
      'createdAt', v_row."created_at"));
  end loop;
  return v_out;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.remove_ai_chat_participant (
  chat        uuid,
  participant uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_owner uuid;
  v_count integer;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."owner_id" into v_owner from "better_supabase"."ai_chats" x where x."id" = remove_ai_chat_participant.chat;
  if not found or not (
    coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')
    or coalesce(v_owner = (select auth.uid()), false)
    or coalesce(remove_ai_chat_participant.participant = (select auth.uid()), false)
  ) then
    raise exception 'No chat %', remove_ai_chat_participant.chat using errcode = 'P0002', hint = 'AI_CHAT_NOT_FOUND';
  end if;
  delete from "better_supabase"."ai_chat_participants" x
  where x."chat_id" = remove_ai_chat_participant.chat and x."user_id" = remove_ai_chat_participant.participant and x."kind"::text = 'user';
  get diagnostics v_count = row_count;
  if v_count > 0 then
    perform "better_supabase"."ai_chat_notify"(remove_ai_chat_participant.chat, remove_ai_chat_participant.participant, 'participant.removed', jsonb_build_object('userId', remove_ai_chat_participant.participant), true);
  end if;
  return v_count > 0;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.remove_ai_chat_party (
  chat       uuid,
  party_kind text,
  party      text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_chat record;
  v_count integer;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."id" as id, x."owner_id" as owner, x."tenant_id" as tenant into v_chat
  from "better_supabase"."ai_chats" x where x."id" = remove_ai_chat_party.chat for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(v_chat.owner = (select auth.uid()), false)) then
    raise exception 'No chat %', remove_ai_chat_party.chat using errcode = 'P0002', hint = 'AI_CHAT_NOT_FOUND';
  end if;
  delete from "better_supabase"."ai_chat_participants" x
  where x."chat_id" = v_chat.id and x."kind"::text = remove_ai_chat_party.party_kind
    and ((remove_ai_chat_party.party_kind = 'team' and x."team_id" = remove_ai_chat_party.party::uuid) or (remove_ai_chat_party.party_kind = 'customer' and x."customer_id" = remove_ai_chat_party.party::uuid) or (remove_ai_chat_party.party_kind = 'external' and lower(x."email") = lower(btrim(remove_ai_chat_party.party))));
  get diagnostics v_count = row_count;
  if v_count > 0 then
    perform "better_supabase"."ai_chat_notify"(v_chat.id, v_chat.owner, 'participant.removed', jsonb_build_object('kind', remove_ai_chat_party.party_kind), true);
  end if;
  return v_count > 0;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.remove_approval_policy (
  policy_id uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."approval_policies"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."approval_policies" x where x."id" = remove_approval_policy.policy_id;
  if not found then
    return false;
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'approvals.manage'), false)) then
    raise exception 'managing approval policies needs approvals.manage' using errcode = '42501', hint = 'APPROVAL_FORBIDDEN';
  end if;
  delete from "better_supabase"."approval_policies" x where x."id" = v_row."id";
  perform "better_supabase".emit_event('approval_policy.deleted', jsonb_build_object('organizationId', v_row."tenant_id"::text, 'id', v_row."id", 'subjectType', v_row."subject_type", 'action', v_row."action"), 'approval-policies/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/approvals');
  perform better_supabase.audit_event(
    event_type => 'approval_policy.deleted',
    category => 'configuration',
    target_type => 'approval_policy',
    record_id => v_row."id"::text,
    summary => 'removed approval policy ' || v_row."name",
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id"::text, 'id', v_row."id", 'subjectType', v_row."subject_type", 'action', v_row."action")
  );
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.remove_assignment_queue (
  queue uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" into v_tenant from "better_supabase"."assignment_queues" x where x."id" = remove_assignment_queue.queue;
  if v_tenant is null then
    return false;
  end if;
  if not coalesce(better_supabase.can('tenant', v_tenant, 'assignment.manage'), false) then
    raise exception 'You need assignment.manage to remove an assignment queue' using errcode = '42501', hint = 'ASSIGNMENT_FORBIDDEN';
  end if;
  delete from "better_supabase"."assignment_queues" x where x."id" = remove_assignment_queue.queue;
  return true;
end;
$function$;

