CREATE OR REPLACE FUNCTION better_supabase.reset_webhook_endpoint()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if new."enabled" and not old."enabled" then
    new."first_failed_at" := null;
    new."disabled_at" := null;
    new."disabled_reason" := null;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_ai_suggestion (
  suggestion_id uuid,
  accepted      boolean
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."ai_suggestions"%rowtype;
  v_doc "better_supabase"."ai_documents"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."ai_suggestions" x where x."id" = resolve_ai_suggestion.suggestion_id for update;
  if found then
    select * into v_doc from "better_supabase"."ai_documents" x where x."id" = v_row."document_id";
  end if;
  if v_doc."id" is null or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(v_doc."owner_id" = auth.uid(), false) or coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'ai_files.manage'), false)) then
    raise exception 'suggestion % not found', suggestion_id using errcode = 'P0002', hint = 'AI_SUGGESTION_NOT_FOUND';
  end if;
  update "better_supabase"."ai_suggestions" x set "resolved_at" = now(), "accepted" = resolve_ai_suggestion.accepted
  where x."id" = v_row."id"
  returning * into v_row;
  return jsonb_build_object('id', v_row."id", 'document_id', v_row."document_id", 'version', v_row."version", 'original_text', v_row."original_text", 'suggested_text', v_row."suggested_text", 'description', v_row."description", 'created_by', v_row."created_by", 'created_at', v_row."created_at", 'resolved_at', v_row."resolved_at", 'accepted', v_row."accepted");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_document_blocks (
  tenant          uuid,
  keys            text[],
  legal_entity_id uuid   DEFAULT NULL::uuid,
  language        text   DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_entity uuid;
  v_language text := lower(nullif(btrim(resolve_document_blocks.language), ''));
  v_result jsonb;
begin
  v_entity := "better_supabase"."legal_entity_of"(resolve_document_blocks.tenant, resolve_document_blocks.legal_entity_id);
  select coalesce(jsonb_object_agg(f.key, f.body), '{}'::jsonb) into v_result
  from (
    select distinct on (b."key") b."key" as key, b."body" as body
    from "better_supabase"."document_text_blocks" b
    where b."tenant_id" = resolve_document_blocks.tenant
      and b."key" = any (coalesce(resolve_document_blocks.keys, '{}'::text[]))
      and (b."legal_entity_id" is null or b."legal_entity_id" = v_entity)
    order by b."key", "better_supabase"."document_slot_rank"(b."legal_entity_id", v_entity, b."language", v_language), b."updated_at" desc
  ) f;
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_document_template (
  tenant          uuid,
  document_type   text,
  legal_entity_id uuid DEFAULT NULL::uuid,
  language        text DEFAULT NULL::text,
  name            text DEFAULT 'default'::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_entity uuid;
  v_language text := lower(nullif(btrim(resolve_document_template.language), ''));
  v_row "better_supabase"."document_templates"%rowtype;
  v_rank integer;
begin
  v_entity := "better_supabase"."legal_entity_of"(resolve_document_template.tenant, resolve_document_template.legal_entity_id);
  select * into v_row
  from "better_supabase"."document_templates" t
  where t."tenant_id" = resolve_document_template.tenant
    and t."document_type" = resolve_document_template.document_type
    and t."name" = coalesce(resolve_document_template.name, 'default')
    and t."active"
    and (t."legal_entity_id" is null or t."legal_entity_id" = v_entity)
  order by "better_supabase"."document_slot_rank"(t."legal_entity_id", v_entity, t."language", v_language), t."updated_at" desc
  limit 1;
  if not found then
    return null;
  end if;
  v_rank := "better_supabase"."document_slot_rank"(v_row."legal_entity_id", v_entity, v_row."language", v_language);
  return jsonb_build_object(
    'id', v_row."id",
    'name', v_row."name",
    'documentType', v_row."document_type",
    'legalEntityId', v_row."legal_entity_id",
    'language', v_row."language",
    'version', v_row."version",
    'body', v_row."body",
    'source', case v_rank
      when 0 then 'entity_language'
      when 1 then 'entity_language'
      when 2 then 'entity'
      when 3 then 'organization_language'
      when 4 then 'organization_language'
      when 5 then 'organization'
      when 6 then 'entity_other_language'
      else 'organization_other_language' end
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_hostname (
  hostname text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'organizationId', x."tenant_id",
    'hostname', x."hostname",
    'primary', x."is_primary",
    'primaryHostname', (
      select p."hostname" from "better_supabase"."hostnames" p
      where p."tenant_id" = x."tenant_id" and p."is_primary"
    )
  )
  from "better_supabase"."hostnames" x
  where x."hostname" = lower(trim(trailing '.' from trim(resolve_hostname.hostname)))
    and x."verified_at" is not null
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_import_conflict (
  tenant uuid,
  source text,
  entity text,
  key    text,
  action text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_resolved integer;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', resolve_import_conflict.tenant, 'imports.manage'), false)) then
    raise exception 'not allowed to resolve an import conflict' using errcode = '42501', hint = 'IMPORT_FORBIDDEN';
  end if;
  if resolve_import_conflict.action = 'keep' then
    update "better_supabase"."import_records" x set "subject_imported_updated_at" = now()
    where x."tenant_id" = resolve_import_conflict.tenant
      and x."source" = resolve_import_conflict.source
      and x."entity" = resolve_import_conflict.entity
      and x."external_key" = resolve_import_conflict.key;
  elsif resolve_import_conflict.action = 'overwrite' then
    update "better_supabase"."import_records" x set "subject_imported_updated_at" = null, "owned_hash" = null
    where x."tenant_id" = resolve_import_conflict.tenant
      and x."source" = resolve_import_conflict.source
      and x."entity" = resolve_import_conflict.entity
      and x."external_key" = resolve_import_conflict.key;
  else
    raise exception 'action must be keep or overwrite' using errcode = '22023', hint = 'IMPORT_ITEM_INVALID';
  end if;
  update "better_supabase".import_run_issues i set "resolved_at" = now()
  where i."tenant_id" = resolve_import_conflict.tenant
    and i."source" = resolve_import_conflict.source
    and i."entity" = resolve_import_conflict.entity
    and i."key" = resolve_import_conflict.key
    and i."kind" = 'conflict'
    and i."resolved_at" is null;
  get diagnostics v_resolved = row_count;
  return jsonb_build_object('action', resolve_import_conflict.action, 'resolved', v_resolved);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_line_discount (
  tenant   uuid,
  party    text,
  product  uuid,
  quantity numeric,
  "on"     date,
  currency text    DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  with scope as (
    select (select x."group_id" from "better_supabase"."discount_group_parties" x where x."tenant_id" = $1 and x."party_id" = $2) as customer_group,
      (select y."discount_group_id" from "better_supabase"."product_variants" y where y."id" = $3 and y."tenant_id" = $1) as item_group
  ),
  matched as (
    select r."id" as id, r."discount_bps" as discount_bps, r."fixed_price" as fixed_price, r."currency" as currency
    from "better_supabase"."discount_rules" r cross join scope s
    where r."tenant_id" = $1
      and (r."customer_group_id" is null or r."customer_group_id" = s.customer_group)
      and (r."product_group_id" is null or r."product_group_id" = s.item_group)
      and (r."valid_from" is null or r."valid_from" <= coalesce($5, current_date))
      and (r."valid_to" is null or r."valid_to" >= coalesce($5, current_date))
      and r."min_quantity" <= coalesce($4, 1)
      and (r."fixed_price" is null or $6 is null or r."currency" = upper($6))
    order by (case when r."customer_group_id" is not null then 2 else 0 end) + (case when r."product_group_id" is not null then 1 else 0 end) desc,
      r."min_quantity" desc, r."valid_from" desc nulls last, r."created_at", r."id"
    limit 1
  )
  select coalesce((select jsonb_build_object('discountBps', m.discount_bps, 'fixedPrice', m.fixed_price::text, 'currency', m.currency, 'ruleId', m.id) from matched m),
    jsonb_build_object('discountBps', 0, 'fixedPrice', null, 'currency', null, 'ruleId', null))
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_message (
  message  uuid,
  resolved boolean DEFAULT true
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_msg "better_supabase"."messages";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_msg from "better_supabase"."messages" m
  where m."id" = resolve_message.message and m."thread_id" is null and m."archived_at" is null and m."sent_at" is not null;
  if not found or not "better_supabase"."can_conversation"(v_msg."conversation_id", 'send') then
    raise exception 'no such thread you can resolve' using errcode = 'P0002', hint = 'MESSAGING_NOT_FOUND';
  end if;
  update "better_supabase"."messages" m
  set "resolved_at" = case when resolve_message.resolved then coalesce(m."resolved_at", now()) end,
    "resolved_by" = case when resolve_message.resolved then coalesce(m."resolved_by", auth.uid()) end
  where m."id" = v_msg."id"
  returning * into v_msg;
  perform "better_supabase".emit_event('message.resolved', jsonb_build_object('organizationId', v_msg."tenant_id"::text, 'conversationId', v_msg."conversation_id", 'messageId', v_msg."id", 'authorId', v_msg."author_id", 'threadId', v_msg."thread_id", 'subjectType', 'message', 'subjectId', v_msg."id"::text, 'resolved', resolve_message.resolved)
      || coalesce((select jsonb_build_object('conversationKind', c."kind", 'recordType', c."subject_type", 'recordId', c."subject_id") from "better_supabase"."conversations" c where c."id" = v_msg."conversation_id"), '{}'::jsonb), 'messages/' || v_msg."id"::text, (v_msg."tenant_id"::text)::text, null, 'better-supabase/messaging');
  return "better_supabase"."messaging_messages_json"(array[v_msg."id"]) -> 0;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_notifications (
  type         text,
  subject_type text,
  subject_id   text,
  tenant       uuid  DEFAULT NULL::uuid,
  resolution   jsonb DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_changed jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) or coalesce(better_supabase.member_can(auth.uid(), resolve_notifications.tenant, 'notifications.send'), false)) then
    raise exception 'Not allowed to resolve notifications here' using errcode = '42501', hint = 'NOTIFICATION_FORBIDDEN';
  end if;
  if resolve_notifications.resolution is not null and jsonb_typeof(resolve_notifications.resolution) <> 'object' then
    raise exception 'resolution must be a JSON object' using errcode = '22023', hint = 'NOTIFICATION_RESOLUTION_INVALID';
  end if;
  with rc as (
    update "better_supabase"."notification_recipients" rc
    set "resolved_at" = now(), "read_at" = coalesce(rc."read_at", now()), "resolution" = resolve_notifications.resolution
    from "better_supabase"."notification_events" ev
    where ev."id" = rc."event_id"
      and ev."type" = resolve_notifications.type
      and ev."subject_type" = resolve_notifications.subject_type
      and ev."subject_id" = resolve_notifications.subject_id
      and ev."tenant_id" is not distinct from resolve_notifications.tenant
      and rc."resolved_at" is null
      and rc."dismissed_at" is null
    returning rc.*
  )
  select jsonb_build_object(
    'count', count(*),
    'items', coalesce(jsonb_agg(jsonb_build_object('id', rc."id", 'event_id', ev."id", 'type', ev."type", 'data', ev."data", 'created_at', rc."created_at", 'read_at', rc."read_at", 'tenant', ev."tenant_id", 'actor_id', ev."actor_id", 'subject_type', ev."subject_type", 'subject_id', ev."subject_id", 'subject_label', ev."subject_label", 'summary', ev."summary", 'action_path', ev."action_path", 'actions', ev."actions", 'priority', ev."priority", 'resolved_at', rc."resolved_at", 'resolution', rc."resolution") order by rc."created_at" desc, rc."id" desc) filter (where rc."user_id" = auth.uid()), '[]')
  )
  from rc
  join "better_supabase"."notification_events" ev on ev."id" = rc."event_id" into v_changed;
  return v_changed;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_payment_terms (
  tenant    uuid,
  terms_id  uuid,
  party     text,
  direction text DEFAULT 'sales'::text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object('id', z."id", 'days', z."days", 'discountBps', z."discount_bps", 'discountDays', z."discount_days", 'creditRestrictionBps', z."credit_restriction_bps")
  from "better_supabase"."payment_terms" z
  where z."tenant_id" = resolve_payment_terms.tenant
    and z."id" = coalesce(resolve_payment_terms.terms_id, (select o.id from (select case when resolve_payment_terms.direction = 'purchase' then p."supplier_terms_id" else p."customer_terms_id" end as id
      from "better_supabase"."companies" p where p."id"::text = resolve_payment_terms.party and p."tenant_id" = resolve_payment_terms.tenant
      union all
      select case when resolve_payment_terms.direction = 'purchase' then p."supplier_terms_id" else p."customer_terms_id" end as id
      from "better_supabase"."people" p where p."id"::text = resolve_payment_terms.party and p."tenant_id" = resolve_payment_terms.tenant) o where o.id is not null limit 1))
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_person (
  tenant uuid,
  input  jsonb
)
  RETURNS uuid
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_person uuid;
  v_identity jsonb := input -> 'identity';
  v_channel text := nullif(trim(v_identity ->> 'channel'), '');
  v_address text := nullif(trim(coalesce(v_identity ->> 'address', v_identity ->> 'external_id')), '');
  v_email text := lower(nullif(trim(input ->> 'email'), ''));
  v_name text;
begin
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+$' then
    v_email := null;
  end if;
  if nullif(trim(input ->> 'id'), '') is not null then
    select p."id" into v_person from "better_supabase"."people" p
    where p."id" = nullif(trim(input ->> 'id'), '')::uuid and p."tenant_id" = resolve_person.tenant;
    if v_person is null then
      raise exception 'contact not found' using errcode = 'P0002', hint = 'CONTACT_NOT_FOUND';
    end if;
  end if;
  if v_person is null and v_channel is not null and v_address is not null then
    select i."person_id" into v_person from "better_supabase"."person_identities" i
    where i."tenant_id" = resolve_person.tenant and i."channel" = v_channel and i."address" = v_address;
  end if;
  if v_person is null and nullif(trim(input ->> 'user_id'), '') is not null then
    select p."id" into v_person from "better_supabase"."people" p
    where p."tenant_id" = resolve_person.tenant and p."user_id" = nullif(trim(input ->> 'user_id'), '')::uuid
    order by p."archived_at" nulls first, p."created_at", p."id" limit 1;
  end if;
  if v_person is null and v_email is not null then
    select p."id" into v_person from "better_supabase"."people" p
    where p."tenant_id" = resolve_person.tenant and p."email" = v_email and p."archived_at" is null;
  end if;
  if v_person is not null then
    select coalesce(p."merged_into", p."id") into v_person from "better_supabase"."people" p where p."id" = v_person;
    update "better_supabase"."people" p set
      "email" = coalesce(p."email", case when not exists (select 1 from "better_supabase"."people" o where o."tenant_id" = p."tenant_id" and o."email" = v_email and o."archived_at" is null and o."id" <> p."id") then v_email end),
      "phone" = coalesce(p."phone", nullif(trim(input ->> 'phone'), '')),
      "user_id" = coalesce(p."user_id", nullif(trim(input ->> 'user_id'), '')::uuid),
      "avatar_url" = coalesce(nullif(trim(input ->> 'avatar_url'), ''), p."avatar_url"),
      "metadata" = p."metadata" || case when jsonb_typeof(input -> 'metadata') = 'object' then input -> 'metadata' else '{}'::jsonb end,
      "updated_at" = now()
    where p."id" = v_person
      and (p."email", p."phone", p."user_id", p."avatar_url", p."metadata") is distinct from (coalesce(p."email", case when not exists (select 1 from "better_supabase"."people" o where o."tenant_id" = p."tenant_id" and o."email" = v_email and o."archived_at" is null and o."id" <> p."id") then v_email end), coalesce(p."phone", nullif(trim(input ->> 'phone'), '')), coalesce(p."user_id", nullif(trim(input ->> 'user_id'), '')::uuid), coalesce(nullif(trim(input ->> 'avatar_url'), ''), p."avatar_url"), p."metadata" || case when jsonb_typeof(input -> 'metadata') = 'object' then input -> 'metadata' else '{}'::jsonb end);
  else
    v_name := left(coalesce(nullif(trim(input ->> 'name'), ''), v_email, nullif(trim(input ->> 'phone'), ''), v_address, 'Unknown contact'), 300);
    begin
      insert into "better_supabase"."people" ("tenant_id", "name", "email", "phone", "lifecycle", "user_id", "avatar_url", "metadata", "created_by")
      values (resolve_person.tenant, v_name, v_email, nullif(trim(input ->> 'phone'), ''), ('{lead,mql,sql,opportunity,customer}'::text[])[1], nullif(trim(input ->> 'user_id'), '')::uuid, nullif(trim(input ->> 'avatar_url'), ''), case when jsonb_typeof(input -> 'metadata') = 'object' then input -> 'metadata' else '{}'::jsonb end || case when v_email is null and nullif(trim(input ->> 'email'), '') is not null then jsonb_build_object('email', nullif(trim(input ->> 'email'), '')) else '{}'::jsonb end, auth.uid())
      returning "id" into v_person;
      perform "better_supabase".emit_event('person.created', jsonb_build_object('organizationId', resolve_person.tenant, 'personId', v_person, 'name', v_name), 'persons/' || v_person::text, (resolve_person.tenant::text)::text, null, 'better-supabase/contacts');
    exception when unique_violation then
      select p."id" into v_person from "better_supabase"."people" p
      where p."tenant_id" = resolve_person.tenant and p."email" = v_email and p."archived_at" is null;
      if v_person is null then
        raise;
      end if;
    end;
  end if;
  if v_channel is not null and v_address is not null then
    insert into "better_supabase"."person_identities" ("tenant_id", "person_id", "channel", "address")
    values (resolve_person.tenant, v_person, v_channel, v_address)
    on conflict do nothing;
  end if;
  return v_person;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_setting (
  tenant       uuid,
  key          text,
  legal_entity uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_entity uuid;
  v_value jsonb;
begin
  v_entity := "better_supabase"."legal_entity_of"(resolve_setting.tenant, resolve_setting.legal_entity);
  if v_entity is not null then
    select s."value" into v_value from "better_supabase"."legal_entity_settings" s
      where s."legal_entity_id" = v_entity and s."key" = resolve_setting.key;
    if found then
      return jsonb_build_object('value', v_value, 'source', 'legal_entity', 'legalEntityId', v_entity);
    end if;
  end if;
  select s."value" into v_value from "better_supabase"."organization_settings" s
    where s."tenant_id" = resolve_setting.tenant and s."key" = resolve_setting.key;
  if found then
    return jsonb_build_object('value', v_value, 'source', 'organization', 'legalEntityId', v_entity);
  end if;
  return jsonb_build_object('value', null, 'source', 'default', 'legalEntityId', v_entity);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_share_link (
  token    text,
  password text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_link "better_supabase"."share_links"%rowtype;
  v_retry integer;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_link
  from "better_supabase"."share_links" l
  where l."token_hash" = encode(extensions.digest(convert_to(resolve_share_link.token, 'utf8'), 'sha256'), 'hex')
    and l."revoked_at" is null
    and (l."expires_at" is null or l."expires_at" > now())
    and (l."max_uses" is null or l."use_count" < l."max_uses")
  for update;
  if not found then
    return null;
  end if;
  if v_link."password_hash" is not null then
    if resolve_share_link.password is null then
      return jsonb_build_object('passwordRequired', true);
    end if;
    select greatest(1, ceil(extract(epoch from k."window_started_at" + k."period" - now()))::integer) into v_retry
    from "better_supabase"."rate_limits" k
    where k."scope" = 'share_link_password' and k."key" = v_link."id"::text
      and k."window_started_at" + k."period" > now()
      and k."hits" >= coalesce((select q."max_requests" from "better_supabase"."rate_limit_rules" q where q."scope" = 'share_link_password'), 10);
    if v_retry is not null then
      raise exception 'too many wrong passwords for this link' using errcode = 'BS429', hint = 'SHARE_LINK_RATE_LIMITED', detail = 'retry after ' || v_retry;
    end if;
    if extensions.crypt(resolve_share_link.password, v_link."password_hash") <> v_link."password_hash" then
      perform 1 from "better_supabase"."hit_rate_limit"('share_link_password', v_link."id"::text, case when exists (select 1 from "better_supabase"."rate_limit_rules" q where q."scope" = 'share_link_password') then null else 10 end, case when exists (select 1 from "better_supabase"."rate_limit_rules" q where q."scope" = 'share_link_password') then null else interval '15 minutes' end);
      return jsonb_build_object('passwordRequired', true);
    end if;
  end if;
  update "better_supabase"."share_links" set "use_count" = "use_count" + 1, "last_used_at" = now() where "id" = v_link."id";
  return jsonb_build_object('id', v_link."id", 'organizationId', v_link."tenant_id", 'subjectType', v_link."subject_type", 'subjectId', v_link."subject_id", 'role', v_link."role", 'versionId', v_link."version_id", 'expiresAt', v_link."expires_at", 'maxUses', v_link."max_uses", 'downloadAllowed', v_link."download_allowed", 'passwordRequired', v_link."password_hash" is not null);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_tax_code (
  tenant       uuid,
  code         text,
  legal_entity uuid DEFAULT NULL::uuid
)
  RETURNS uuid
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select x."id" from "better_supabase"."tax_codes" x
  where x."tenant_id" = resolve_tax_code.tenant and x."code" = resolve_tax_code.code
    and x."archived_at" is null
    and (x."legal_entity_id" is null or x."legal_entity_id" = resolve_tax_code.legal_entity)
  order by (x."legal_entity_id" is null), x."id" limit 1
$function$;

CREATE OR REPLACE FUNCTION better_supabase.resolve_workflow_definition (
  tenant       uuid,
  purpose      text DEFAULT 'lifecycle'::text,
  subject_type text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object('definition', jsonb_build_object(
    'id', x."id",
    'tenant', x."tenant_id",
    'slug', x."slug",
    'name', x."name",
    'description', x."description",
    'subjectTypes', to_jsonb(x."subject_types"),
    'scope', x."scope",
    'forkedFrom', x."forked_from",
    'forkedFromVersion', x."forked_from_version",
    'restricted', x."restricted",
    'purpose', x."purpose",
    'isDefault', x."is_default",
    'createdBy', x."created_by",
    'createdAt', x."created_at",
    'updatedAt', x."updated_at"
  ), 'version', jsonb_build_object(
    'id', y."id",
    'definition', y."definition_id",
    'version', y."version",
    'status', y."status",
    'createdBy', y."created_by",
    'createdAt', y."created_at",
    'publishedAt', y."published_at",
    'publishedBy', y."published_by",
    'owner', y."owner_kind",
    'permissions', to_jsonb(y."permissions")
  ))
  from "better_supabase"."workflow_definitions" x
  join "better_supabase"."workflow_versions" y on y."definition_id" = x."id" and y."status" = 'published'
  where x."is_default"
    and x."purpose" = resolve_workflow_definition.purpose
    and (resolve_workflow_definition.subject_type is null or resolve_workflow_definition.subject_type = any (x."subject_types"))
    and (x."tenant_id" = resolve_workflow_definition.tenant
      or (x."scope" = 'system' and not exists (select 1 from "better_supabase"."workflow_opt_outs" oo where oo."tenant_id" = resolve_workflow_definition.tenant and oo."definition_id" = x."id")))
  order by (x."tenant_id" is null), x."updated_at" desc
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.respond_calendar_event (
  event_id uuid,
  response text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if respond_calendar_event.response not in ('needs-action', 'accepted', 'declined', 'tentative') then
    raise exception 'response must be needs-action, accepted, declined or tentative' using errcode = '22023', hint = 'CALENDAR_RESPONSE_INVALID';
  end if;
  update "better_supabase"."calendar_attendees" set "response" = respond_calendar_event.response,
    "user_id" = coalesce("user_id", auth.uid())
  where "event_id" = respond_calendar_event.event_id
    and ("user_id" = auth.uid() or ("user_id" is null and "email" = lower(auth.email())));
  if not found then
    raise exception 'you are not invited to this event' using errcode = 'P0002', hint = 'CALENDAR_ATTENDEE_NOT_FOUND';
  end if;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.respond_to_portal_quote (
  quote    uuid,
  decision text,
  name     text,
  note     text,
  selected jsonb DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."quotes";
  v_headers jsonb := nullif(current_setting('request.headers', true), '')::jsonb;
  v_ip inet;
  v_claims text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."quotes" x where x."id" = respond_to_portal_quote.quote and (x."status" <> 'draft' and (((x."tenant_id")::text, ('quote')::text, (x."id"::text)::text) in (select g.tenant, g.subject_type, g.subject_id from better_supabase.portal_subjects('read') g) or ((x."tenant_id")::text, (x."company_type")::text, (x."company_id")::text) in (select g.tenant, g.party_type, g.party_id from better_supabase.portal_parties() g) or ((x."tenant_id")::text, (x."contact_type")::text, (x."contact_id")::text) in (select g.tenant, g.party_type, g.party_id from better_supabase.portal_parties() g))) for update;
  if v_row."id" is null then
    raise exception 'no such quote shared with you' using errcode = 'P0002', hint = 'QUOTE_NOT_FOUND';
  end if;
  if respond_to_portal_quote.decision not in ('accepted', 'rejected', 'changes_requested') then
    raise exception 'answer accepted, rejected or changes_requested' using errcode = '22023', hint = 'QUOTE_DECISION_INVALID';
  end if;
  if v_row."status" not in ('sent', 'viewed') then
    raise exception 'this quote no longer takes an answer' using errcode = '55000', hint = 'QUOTE_NOT_OPEN';
  end if;
  begin
    v_ip := left(nullif(trim(reverse(split_part(reverse(v_headers ->> 'x-forwarded-for'), ',', 1))), ''), 64)::inet;
  exception when invalid_text_representation then
    v_ip := null;
  end;
  perform set_config('better_supabase.transition_actor', jsonb_strip_nulls(jsonb_build_object('name', nullif(trim(coalesce(nullif(trim(respond_to_portal_quote.name), ''), auth.jwt() ->> 'email')), ''), 'email', auth.jwt() ->> 'email', 'ip', v_ip::text, 'userAgent', left(v_headers ->> 'user-agent', 512)))::text, true);
  if (true) and v_row."valid_until" < current_date then
    update "better_supabase"."quotes" x set "status" = 'expired', "updated_at" = now() where x."id" = v_row."id"
    returning * into v_row;
    perform "better_supabase".emit_event('quote.expired', jsonb_build_object('organizationId', v_row."tenant_id", 'quoteId', v_row."id", 'subjectType', 'quote', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier"), 'quotes/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/quotes');
    return jsonb_build_object('status', 'expired');
  end if;
  if nullif(trim(coalesce(nullif(trim(respond_to_portal_quote.name), ''), auth.jwt() ->> 'email')), '') is null then
    raise exception 'say who answers' using errcode = '23502', hint = 'QUOTE_NAME_REQUIRED';
  end if;
  if respond_to_portal_quote.decision = 'accepted' then
    if v_row."deposit_required" and v_row."deposit_due" > 0 then
      raise exception 'pay the deposit before accepting; the app records the acceptance once it is paid' using errcode = '55000', hint = 'QUOTE_DEPOSIT_REQUIRED';
    end if;
    if respond_to_portal_quote.selected is not null then
      if jsonb_typeof(respond_to_portal_quote.selected) <> 'array' or exists (
        select 1 from jsonb_array_elements(respond_to_portal_quote.selected) e
        where jsonb_typeof(e.value) not in ('number') or not exists (
          select 1 from "better_supabase"."quote_lines" ql
          where ql."parent_id" = v_row."id" and ql."optional" and ql."position" = (e.value #>> '{}')::numeric
        )
      ) then
        raise exception 'pick optional lines of this quote by position' using errcode = '22023', hint = 'QUOTE_SELECTION_INVALID';
      end if;
      update "better_supabase"."quote_lines" ql set "selected" = ql."position" in (select ((e.value #>> '{}')::numeric)::integer from jsonb_array_elements(respond_to_portal_quote.selected) e)
      where ql."parent_id" = v_row."id" and ql."optional";
    end if;
    declare
    v_hook regprocedure := to_regprocedure('"public"."before_quote_accept"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  end if;
  update "better_supabase"."quotes" x set "status" = respond_to_portal_quote.decision, "decided_at" = now(), "decided_by" = nullif(trim(coalesce(nullif(trim(respond_to_portal_quote.name), ''), auth.jwt() ->> 'email')), ''),
    "decision_note" = nullif(trim(respond_to_portal_quote.note), ''), "decider_id" = auth.uid(), "decided_ip" = left(nullif(trim(reverse(split_part(reverse(v_headers ->> 'x-forwarded-for'), ',', 1))), ''), 64), "decided_user_agent" = left(v_headers ->> 'user-agent', 512), "updated_at" = now()
  where x."id" = v_row."id"
  returning * into v_row;
  case respond_to_portal_quote.decision
    when 'accepted' then
      perform "better_supabase".emit_event('quote.accepted', jsonb_build_object('organizationId', v_row."tenant_id", 'quoteId', v_row."id", 'subjectType', 'quote', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier", 'total', v_row."total"::text, 'currency', v_row."currency", 'byName', v_row."decided_by", 'revision', v_row."revision", 'depositDue', v_row."deposit_due"::text), 'quotes/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/quotes');
    when 'rejected' then
      perform "better_supabase".emit_event('quote.rejected', jsonb_build_object('organizationId', v_row."tenant_id", 'quoteId', v_row."id", 'subjectType', 'quote', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier", 'note', v_row."decision_note"), 'quotes/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/quotes');
    else
      perform "better_supabase".emit_event('quote.changes_requested', jsonb_build_object('organizationId', v_row."tenant_id", 'quoteId', v_row."id", 'subjectType', 'quote', 'subjectId', v_row."id"::text, 'identifier', v_row."identifier", 'note', v_row."decision_note"), 'quotes/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/quotes');
  end case;
  if v_row."owner_id" is not null then
    if better_supabase.import_run() is null then
      v_claims := current_setting('request.jwt.claims', true);
      perform set_config('request.jwt.claims', '{"role": "service_role"}', true);
      perform "better_supabase"."notify"(jsonb_build_object(
      'type', 'quote.decided',
      'tenant', v_row."tenant_id",
      'subject_type', 'quote',
      'subject_id', v_row."id"::text,
      'subject_label', v_row."identifier" || ' ' || v_row."title",
      'summary', v_row."identifier" || ' ' || v_row."title",
      'recipients', jsonb_build_array(v_row."owner_id"),
      'key', 'quote.decided:' || v_row."id"::text,
      'data', jsonb_build_object('quoteId', v_row."id", 'status', v_row."status")
    ));
      perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
    end if;
  end if;
  if respond_to_portal_quote.decision = 'accepted' then
    declare
    v_hook regprocedure := to_regprocedure('"public"."after_quote_accept"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  end if;
  return jsonb_build_object('status', v_row."status", 'identifier', v_row."identifier", 'revision', v_row."revision");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.respond_to_quote (
  token    text,
  decision text,
  name     text,
  note     text,
  selected jsonb DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
