  tenant       uuid,
  subject_type text,
  subject_id   text,
  attrs        jsonb,
  award_id     uuid  DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."funding_awards"%rowtype;
  v_attrs jsonb := coalesce(save_funding_award.attrs, '{}'::jsonb);
  v_funder uuid;
