$function$;

CREATE OR REPLACE FUNCTION better_supabase.save_template (
  template_id uuid,
  tenant      uuid,
  type        text,
  name        text,
  language    text,
  settings    jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."templates"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if save_template.settings is not null and jsonb_typeof(save_template.settings) <> 'object' then
    raise exception 'settings must be an object' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  if save_template.template_id is not null then
    select * into v_row from "better_supabase"."templates" x where x."id" = save_template.template_id for update;
    if not found or v_row."tenant_id" is distinct from save_template.tenant then
      raise exception 'No such template' using errcode = 'P0002', hint = 'TEMPLATE_NOT_FOUND';
    end if;
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (save_template.tenant is not null and coalesce(better_supabase.can('tenant', save_template.tenant, 'templates.manage'), false))) then
    raise exception 'You may not change templates here' using errcode = '42501', hint = 'TEMPLATE_FORBIDDEN';
  end if;
  if save_template.template_id is null and (save_template.type is null or save_template.type !~ '^[a-z][a-z0-9_.-]{0,63}$') then
    raise exception 'type must be lower-case letters, digits, dots, dashes or underscores' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  if save_template.template_id is null and save_template.name is null then
    raise exception 'A template needs a name' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_template_save"(uuid, text, jsonb)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::jsonb)', v_hook::oid::regproc)
        using save_template.tenant, coalesce(save_template.type, v_row."type"), save_template.settings;
    end if;
  end;
  if save_template.template_id is null then
    insert into "better_supabase"."templates" ("tenant_id", "scope", "type", "name", "language", "settings", "created_by")
    values (
      save_template.tenant,
      case when save_template.tenant is null then 'system' else 'tenant' end,
      save_template.type,
      save_template.name,
      coalesce(save_template.language, 'en'),
      coalesce(save_template.settings, '{}'::jsonb),
      (select auth.uid())
    )
    returning * into v_row;
  else
    update "better_supabase"."templates" x set
      "name" = coalesce(save_template.name, x."name"),
      "language" = coalesce(save_template.language, x."language"),
      "settings" = coalesce(save_template.settings, x."settings"),
      "is_default" = x."is_default" and coalesce(save_template.language, x."language") = x."language",
      "updated_at" = now()
    where x."id" = save_template.template_id
    returning * into v_row;
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_template_save"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_row."id";
    end if;
  end;
  return jsonb_build_object(
    'id', v_row."id",
    'tenant', v_row."tenant_id",
    'scope', v_row."scope",
    'brand', v_row."brand",
    'key', v_row."key",
    'type', v_row."type",
    'name', v_row."name",
    'language', v_row."language",
    'isDefault', v_row."is_default",
    'settings', v_row."settings",
    'forkedFrom', v_row."forked_from",
    'forkedFromVersion', v_row."forked_from_version",
    'publishedVersion', (select y."version" from "better_supabase"."template_versions" y where y."template_id" = v_row."id" and y."published_at" is not null order by y."version" desc limit 1),
    'upstreamVersion', case when v_row."forked_from" is not null then (select y."version" from "better_supabase"."template_versions" y where y."template_id" = v_row."forked_from" and y."published_at" is not null order by y."version" desc limit 1) end,
    'createdBy', v_row."created_by",
    'createdAt', v_row."created_at",
    'updatedAt', v_row."updated_at"
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.save_template_draft (
  template_id uuid,
  body        jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_tpl "better_supabase"."templates"%rowtype;
  v_row "better_supabase"."template_versions"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_tpl from "better_supabase"."templates" x where x."id" = save_template_draft.template_id for update;
  if not found then
    raise exception 'No such template' using errcode = 'P0002', hint = 'TEMPLATE_NOT_FOUND';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_tpl."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_tpl."tenant_id", 'templates.manage'), false))) then
    raise exception 'You may not edit this template' using errcode = '42501', hint = 'TEMPLATE_FORBIDDEN';
  end if;
  if save_template_draft.body is null then
    raise exception 'A template version needs a body' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  update "better_supabase"."template_versions" x set
    "body" = save_template_draft.body,
    "hash" = encode(extensions.digest(save_template_draft.body::text, 'sha256'), 'hex')
  where x."template_id" = save_template_draft.template_id and x."published_at" is null
  returning * into v_row;
  if not found then
    insert into "better_supabase"."template_versions" ("template_id", "version", "body", "hash", "created_by")
    values (
      save_template_draft.template_id,
      coalesce((select max(y."version") from "better_supabase"."template_versions" y where y."template_id" = save_template_draft.template_id), 0) + 1,
      save_template_draft.body,
      encode(extensions.digest(save_template_draft.body::text, 'sha256'), 'hex'),
      (select auth.uid())
    )
    returning * into v_row;
  end if;
  update "better_supabase"."templates" x set "updated_at" = now() where x."id" = save_template_draft.template_id;
  return jsonb_build_object(
    'id', v_row."id",
    'template', v_row."template_id",
    'version', v_row."version",
    'hash', v_row."hash",
    'publishedAt', v_row."published_at",
    'createdBy', v_row."created_by",
    'createdAt', v_row."created_at",
    'body', v_row."body"
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.save_template_schedule (
  schedule_id uuid,
  template_id uuid,
  tenant      uuid,
  dtstart     timestamp with time zone,
  tzid        text,
  rrule       text,
  input       jsonb,
  enabled     boolean
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_tpl "better_supabase"."templates"%rowtype;
  v_row "better_supabase"."template_schedules"%rowtype;
  v_rule "better_supabase"."recurrence_rules"%rowtype;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if save_template_schedule.tenant is null then
    raise exception 'A schedule needs a tenant' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (save_template_schedule.tenant is not null and coalesce(better_supabase.can('tenant', save_template_schedule.tenant, 'templates.manage'), false))) then
    raise exception 'You may not schedule templates here' using errcode = '42501', hint = 'TEMPLATE_FORBIDDEN';
  end if;
  if save_template_schedule.dtstart is null or coalesce(length(save_template_schedule.rrule), 0) not between 1 and 1000 then
    raise exception 'A schedule needs a start and a rule' using errcode = '22023', hint = 'TEMPLATE_SCHEDULE_INVALID';
  end if;
  if not exists (select 1 from pg_catalog.pg_timezone_names z where z.name = coalesce(save_template_schedule.tzid, 'UTC')) then
    raise exception 'tzid must be an IANA time zone' using errcode = '22023', hint = 'TEMPLATE_SCHEDULE_INVALID';
  end if;
  if save_template_schedule.input is not null and jsonb_typeof(save_template_schedule.input) <> 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  select * into v_tpl from "better_supabase"."templates" x where x."id" = save_template_schedule.template_id;
  if not found or not (v_tpl."scope" = 'system' or v_tpl."tenant_id" = save_template_schedule.tenant or (v_tpl."scope" = 'brand' and v_tpl."brand" = "better_supabase"."template_brand"(save_template_schedule.tenant))) then
    raise exception 'No such template' using errcode = 'P0002', hint = 'TEMPLATE_NOT_FOUND';
  end if;
  if save_template_schedule.schedule_id is null then
    insert into "better_supabase"."template_schedules" ("template_id", "tenant_id", "input", "enabled", "created_by")
    values (v_tpl."id", save_template_schedule.tenant, coalesce(save_template_schedule.input, '{}'::jsonb),
      coalesce(save_template_schedule.enabled, true), (select auth.uid()))
    returning * into v_row;
  else
    update "better_supabase"."template_schedules" x set
      "template_id" = v_tpl."id",
      "input" = coalesce(save_template_schedule.input, x."input"),
      "enabled" = coalesce(save_template_schedule.enabled, x."enabled"),
      "updated_at" = now()
    where x."id" = save_template_schedule.schedule_id and x."tenant_id" = save_template_schedule.tenant
    returning * into v_row;
    if not found then
      raise exception 'No such schedule' using errcode = 'P0002', hint = 'TEMPLATE_SCHEDULE_NOT_FOUND';
    end if;
  end if;
  update "better_supabase"."recurrence_rules" u set
    "dtstart" = save_template_schedule.dtstart,
    "tzid" = coalesce(save_template_schedule.tzid, 'UTC'),
    "rrule" = save_template_schedule.rrule
  where u."tenant_id" = v_row."tenant_id"
      and u."subject_type" = 'template_schedule'
      and u."subject_id" = v_row."id"::text
  returning * into v_rule;
  if not found then
    insert into "better_supabase"."recurrence_rules" ("tenant_id", "subject_type", "subject_id", "dtstart", "tzid", "rrule")
    values (v_row."tenant_id", 'template_schedule', v_row."id"::text, save_template_schedule.dtstart,
      coalesce(save_template_schedule.tzid, 'UTC'), save_template_schedule.rrule)
    returning * into v_rule;
  end if;
  return jsonb_build_object(
    'id', v_row."id",
    'template', v_row."template_id",
    'tenant', v_row."tenant_id",
    'input', v_row."input",
    'enabled', v_row."enabled",
    'dtstart', v_rule."dtstart",
    'tzid', v_rule."tzid",
    'rrule', v_rule."rrule",
    'createdBy', v_row."created_by",
    'createdAt', v_row."created_at",
    'updatedAt', v_row."updated_at"
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.save_thread_summary (
  conversation uuid,
  thread       uuid,
  summary      text,
  attrs        jsonb DEFAULT '{}'::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_conversation uuid;
  v_tenant uuid;
  v_count integer;
begin
  if not coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') then
    raise exception 'save_thread_summary runs as the service role' using errcode = '42501', hint = 'MESSAGING_FORBIDDEN';
  end if;
  if save_thread_summary.thread is null then
    select c."id", c."tenant_id" into v_conversation, v_tenant
    from "better_supabase"."conversations" c where c."id" = save_thread_summary.conversation;
  else
    select m."conversation_id", m."tenant_id" into v_conversation, v_tenant
    from "better_supabase"."messages" m
    where m."id" = save_thread_summary.thread and m."thread_id" is null and m."sent_at" is not null
      and (save_thread_summary.conversation is null or m."conversation_id" = save_thread_summary.conversation);
  end if;
  if v_conversation is null then
    raise exception 'no such conversation or thread root' using errcode = 'P0002', hint = 'MESSAGING_NOT_FOUND';
  end if;
  begin
    v_count := coalesce((save_thread_summary.attrs ->> 'messageCount')::integer, 0);
  exception when invalid_text_representation or numeric_value_out_of_range then
    v_count := -1;
  end;
  if char_length(btrim(coalesce(save_thread_summary.summary, ''))) not between 1 and 20000
    or char_length(save_thread_summary.attrs ->> 'model') > 200
    or v_count < 0
    or save_thread_summary.attrs ->> 'throughAt' is null then
    raise exception 'a summary needs 1 to 20000 characters, a message count and throughAt' using errcode = '22023', hint = 'MESSAGING_SUMMARY_INVALID';
  end if;
  insert into "better_supabase"."thread_summaries" ("tenant_id", "conversation_id", "thread_id", "summary", "model", "message_count", "through_at")
  values (v_tenant, v_conversation, save_thread_summary.thread, btrim(save_thread_summary.summary),
    save_thread_summary.attrs ->> 'model', v_count, (save_thread_summary.attrs ->> 'throughAt')::timestamptz)
  on conflict ("conversation_id", "thread_id") do update
  set "summary" = excluded."summary",
    "model" = excluded."model",
    "message_count" = excluded."message_count",
    "through_at" = excluded."through_at",
    "updated_at" = now();
  return "better_supabase"."thread_summary"(v_conversation, save_thread_summary.thread);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.save_variant (
  product         uuid,
  variant         uuid,
  sku             text,
  option_values   uuid[],
  title           text,
  barcode         text,
  weight_grams    integer,
  track_inventory boolean,
  allow_backorder boolean,
  clear           text[]  DEFAULT NULL::text[]
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_id uuid := save_variant.variant;
  v_created boolean := save_variant.variant is null;
  v_wanted uuid[];
  v_last text;
  v_rank text;
  v_sku text := save_variant.sku;
  v_defaults jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."tenant_id" into v_tenant from "better_supabase"."products" x where x."id" = save_variant.product for update;
  if v_tenant is null then
    raise exception 'product not found' using errcode = 'P0002', hint = 'CATALOG_PRODUCT_NOT_FOUND';
  end if;
  if v_created then
    if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  else
    if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'catalog.manage'), false)) then
    raise exception 'not allowed to manage the catalog' using errcode = '42501', hint = 'CATALOG_FORBIDDEN';
  end if;
  end if;
  if exists (select 1 from unnest(coalesce(save_variant.clear, '{}'::text[])) c where c <> all ('{sku,title,barcode,weight}'::text[])) then
    raise exception 'clear names only sku, title, barcode, weight' using errcode = '22023', hint = 'CATALOG_CLEAR_INVALID';
  end if;
  if v_created or save_variant.option_values is not null then
  v_wanted := coalesce((select array_agg(distinct x order by x) from unnest(save_variant.option_values) x), '{}'::uuid[]);
  if cardinality(v_wanted) <> coalesce(cardinality(save_variant.option_values), 0)
    or exists (
      select 1 from unnest(v_wanted) x
      where not exists (
        select 1 from "better_supabase"."product_option_values" ov join "better_supabase"."product_options" o on o."id" = ov."option_id"
        where ov."id" = x and o."product_id" = save_variant.product
      )
    )
    or (select count(distinct ov."option_id") from "better_supabase"."product_option_values" ov where ov."id" = any (v_wanted)) <> cardinality(v_wanted)
    or (select count(*) from "better_supabase"."product_options" o where o."product_id" = save_variant.product) <> cardinality(v_wanted) then
    raise exception 'a variant needs exactly one value of each product option' using errcode = '22023', hint = 'CATALOG_VARIANT_OPTIONS';
  end if;
  if exists (
    select 1 from "better_supabase"."product_variants" x
    where x."product_id" = save_variant.product
      and x."id" is distinct from save_variant.variant
      and coalesce((select array_agg(y."option_value_id" order by y."option_value_id") from "better_supabase"."product_variant_values" y where y."variant_id" = x."id"), '{}'::uuid[]) = v_wanted
  ) then
    raise exception 'another variant has these option values' using errcode = '23505', hint = 'CATALOG_VARIANT_DUPLICATE';
  end if;
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_variant_save"(uuid, uuid, text, uuid[])');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::uuid, $3::text, $4::uuid[])', v_hook::oid::regproc)
        using save_variant.product, save_variant.variant, save_variant.sku, v_wanted;
    end if;
  end;
  begin
    if v_created then
      select max(x."rank" collate "C") into v_last from "better_supabase"."product_variants" x where x."product_id" = save_variant.product;
      v_rank := case
    when v_last is null then 'V'
    when length(substring(v_last from '^z*')) = length(v_last) then v_last || 'V'
    else left(v_last, length(substring(v_last from '^z*'))) || substr('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', (strpos('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', substr(v_last, length(substring(v_last from '^z*')) + 1, 1)) - 1 + 62) / 2 + 1, 1)
  end;
      execute coalesce((select 'select jsonb_build_object(' || string_agg(pg_catalog.quote_literal(a.attname) || ', ' || pg_catalog.pg_get_expr(d.adbin, d.adrelid), ', ') || ')'
    from pg_catalog.pg_attrdef d join pg_catalog.pg_attribute a on a.attrelid = d.adrelid and a.attnum = d.adnum
    where d.adrelid = '"better_supabase"."product_variants"'::regclass and a.attname = any (array[case when save_variant.sku is null then 'sku' end, case when save_variant.title is null then 'title' end, case when save_variant.barcode is null then 'barcode' end, case when save_variant.weight_grams is null then 'weight_grams' end]::text[])), 'select ''{}''::jsonb') into v_defaults;
      insert into "better_supabase"."product_variants" as x ("tenant_id", "product_id", "sku", "title", "barcode", "weight_grams", "track_inventory", "allow_backorder", "rank")
      values (v_tenant, save_variant.product, coalesce(save_variant.sku, (jsonb_populate_record(null::"better_supabase"."product_variants", v_defaults))."sku"), coalesce(save_variant.title, (jsonb_populate_record(null::"better_supabase"."product_variants", v_defaults))."title"), coalesce(save_variant.barcode, (jsonb_populate_record(null::"better_supabase"."product_variants", v_defaults))."barcode"), coalesce(save_variant.weight_grams, (jsonb_populate_record(null::"better_supabase"."product_variants", v_defaults))."weight_grams"), coalesce(save_variant.track_inventory, true), coalesce(save_variant.allow_backorder, false), v_rank)
      returning x."id", x."sku" into v_id, v_sku;
    else
      update "better_supabase"."product_variants" x set "sku" = case when 'sku' = any (coalesce(save_variant.clear, '{}'::text[])) then null else coalesce(save_variant.sku, x."sku") end, "title" = case when 'title' = any (coalesce(save_variant.clear, '{}'::text[])) then null else coalesce(save_variant.title, x."title") end, "barcode" = case when 'barcode' = any (coalesce(save_variant.clear, '{}'::text[])) then null else coalesce(save_variant.barcode, x."barcode") end, "weight_grams" = case when 'weight' = any (coalesce(save_variant.clear, '{}'::text[])) then null else coalesce(save_variant.weight_grams, x."weight_grams") end, "track_inventory" = coalesce(save_variant.track_inventory, x."track_inventory"), "allow_backorder" = coalesce(save_variant.allow_backorder, x."allow_backorder"), "updated_at" = now()
      where x."id" = save_variant.variant and x."product_id" = save_variant.product
      returning x."rank", x."sku" into v_rank, v_sku;
      if not found then
        raise exception 'variant not found' using errcode = 'P0002', hint = 'CATALOG_VARIANT_NOT_FOUND';
      end if;
    end if;
  exception when unique_violation then
    declare
      v_constraint text;
    begin
      get stacked diagnostics v_constraint = constraint_name;
      if exists (
        select 1 from pg_catalog.pg_index i
        join pg_catalog.pg_class c on c.oid = i.indexrelid
        where i.indrelid = '"better_supabase"."product_variants"'::regclass and c.relname = v_constraint
          and (exists (select 1 from pg_catalog.pg_attribute a where a.attrelid = i.indrelid and a.attnum = any (i.indkey) and a.attname = 'sku')
            or coalesce(pg_catalog.pg_get_expr(i.indexprs, i.indrelid), '') ~ ('\m' || 'sku' || '\M'))
      ) then
        raise exception 'another variant has this SKU' using errcode = '23505', hint = 'CATALOG_SKU_TAKEN';
      end if;
      raise;
    end;
  end;
  if v_wanted is not null then
  delete from "better_supabase"."product_variant_values" x where x."variant_id" = v_id and not (x."option_value_id" = any (v_wanted));
  insert into "better_supabase"."product_variant_values" ("tenant_id", "variant_id", "option_value_id")
  select v_tenant, v_id, x from unnest(v_wanted) x
  on conflict do nothing;
  end if;
  if v_created then
    perform "better_supabase".emit_event('product_variant.created', jsonb_build_object('organizationId', v_tenant, 'id', v_id, 'productId', save_variant.product, 'sku', v_sku), 'variants/' || v_id::text, (v_tenant)::text, null, 'better-supabase/catalog');
  else
    perform "better_supabase".emit_event('product_variant.updated', jsonb_build_object('organizationId', v_tenant, 'id', v_id, 'productId', save_variant.product, 'sku', v_sku), 'variants/' || v_id::text, (v_tenant)::text, null, 'better-supabase/catalog');
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_variant_save"(uuid, boolean)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::boolean)', v_hook::oid::regproc)
        using v_id, v_created;
    end if;
  end;
  return jsonb_build_object('id', v_id, 'sku', v_sku, 'rank', v_rank);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.save_variant_size (
  tenant uuid,
  input  jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_variant uuid;
  v_size numeric;
  v_row "better_supabase"."variant_sizes";
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (save_variant_size.tenant is not null and coalesce(better_supabase.can('tenant', save_variant_size.tenant, 'warehouse.manage'), false))) then
    raise exception 'not allowed to manage variant sizes' using errcode = '42501', hint = 'WAREHOUSE_FORBIDDEN';
  end if;
  if jsonb_typeof(save_variant_size.input) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  begin
    v_variant := (save_variant_size.input ->> 'variantId')::uuid;
    v_size := (save_variant_size.input ->> 'size')::numeric;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'variantId is a uuid and size a number' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end;
  if v_size is null or v_size <= 0 then
    raise exception 'size is more than 0' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  if not exists (select 1 from "better_supabase"."product_variants" x where x."id" = v_variant and x."tenant_id" = save_variant_size.tenant) then
    raise exception 'no such variant in this organization' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  insert into "better_supabase"."variant_sizes" ("tenant_id", "variant_id", "size")
  values (save_variant_size.tenant, v_variant, v_size)
  on conflict ("variant_id") do update set "size" = excluded."size", "updated_at" = now()
  returning * into v_row;
  return jsonb_build_object('variantId', v_row."variant_id", 'size', v_row."size"::text);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.save_view (
  tenant  uuid,
  list    text,
  name    text,
  kind    text,
  scope   text,
  team    text,
  state   jsonb,
  view_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_id uuid := save_view.view_id;
  v_inserted boolean := save_view.view_id is null;
  v_row "better_supabase"."shared_views";
  v_last text;
  v_rank text;
  v_service boolean := auth.role() = 'service_role';
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if save_view.scope is null or save_view.scope not in ('user', 'team', 'tenant') then
    raise exception 'scope must be user, team or tenant' using errcode = '22023', hint = 'SAVED_VIEW_INVALID';
  end if;
  if save_view.kind is null or save_view.kind not in ('table', 'board', 'calendar', 'timeline', 'gantt') then
    raise exception 'unknown view kind' using errcode = '22023', hint = 'SAVED_VIEW_INVALID';
  end if;
  if save_view.state is null or jsonb_typeof(save_view.state) <> 'object' then
    raise exception 'state must be an object' using errcode = '22023', hint = 'SAVED_VIEW_INVALID';
  end if;
  if not (v_service or coalesce(better_supabase.can('tenant', save_view.tenant, 'saved_views.read'), false)) then
    raise exception 'not allowed to save views' using errcode = '42501', hint = 'SAVED_VIEW_FORBIDDEN';
  end if;
  if save_view.state ? 'collectionId' and (
    jsonb_typeof(save_view.state -> 'collectionId') <> 'string'
    or (save_view.state ->> 'collectionId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or not exists (
      select 1 from "better_supabase"."subject_collections" c
      where c."id" = (save_view.state ->> 'collectionId')::uuid
        and c."tenant_id" = save_view.tenant
        and (v_service or c."scope" <> 'user' or c."owner_id" = auth.uid())
    )) then
    raise exception 'the view''s collection is not found' using errcode = 'P0002', hint = 'SAVED_VIEW_COLLECTION_NOT_FOUND';
  end if;
  if save_view.scope = 'user' and auth.uid() is null then
    raise exception 'a personal view needs a signed-in user' using errcode = '22023', hint = 'SAVED_VIEW_INVALID';
  end if;
  if save_view.scope <> 'user' and not (v_service or coalesce(better_supabase.can('tenant', save_view.tenant, 'saved_views.share'), false)) then
    raise exception 'not allowed to share views' using errcode = '42501', hint = 'SAVED_VIEW_FORBIDDEN';
  end if;
  if save_view.scope = 'team' then
    if save_view.team is null then
      raise exception 'a team view needs a team' using errcode = '22023', hint = 'SAVED_VIEW_INVALID';
    end if;
    if not (v_service or save_view.team in (select t::text from "better_supabase"."team_ids_of"((select auth.uid())) t)) then
      raise exception 'not a member of this team' using errcode = '42501', hint = 'SAVED_VIEW_FORBIDDEN';
    end if;
  end if;
  if v_id is not null then
    select * into v_row from "better_supabase"."shared_views" where "id" = v_id and "tenant_id" = save_view.tenant for update;
    if not found then
      raise exception 'saved view not found' using errcode = 'P0002', hint = 'SAVED_VIEW_NOT_FOUND';
    end if;
    if not (auth.role() = 'service_role'
    or (v_row."scope" = 'user' and coalesce(v_row."owner_id" = auth.uid(), false))
    or (v_row."scope" <> 'user' and coalesce(better_supabase.can('tenant', v_row."tenant_id", 'saved_views.share'), false))) then
      raise exception 'not allowed to change this view' using errcode = '42501', hint = 'SAVED_VIEW_FORBIDDEN';
    end if;
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_view_save"(uuid, text, text, jsonb)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::text, $4::jsonb)', v_hook::oid::regproc)
        using save_view.tenant, save_view.list, save_view.scope, save_view.state;
    end if;
  end;
  if v_id is null then
    select max(v."rank" collate "C") into v_last from "better_supabase"."shared_views" v
      where v."tenant_id" = save_view.tenant and v."list" = save_view.list;
    v_rank := case
    when v_last is null then 'V'
    when length(substring(v_last from '^z*')) = length(v_last) then v_last || 'V'
    else left(v_last, length(substring(v_last from '^z*'))) || substr('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', (strpos('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', substr(v_last, length(substring(v_last from '^z*')) + 1, 1)) - 1 + 62) / 2 + 1, 1)
  end;
    insert into "better_supabase"."shared_views" ("tenant_id", "list", "scope", "owner_id", "team_id", "name", "kind", "state", "rank")
    values (save_view.tenant, save_view.list, save_view.scope, auth.uid(),
      case when save_view.scope = 'team' then save_view.team end,
      save_view.name, save_view.kind, save_view.state, v_rank)
    returning "id" into v_id;
  else
    update "better_supabase"."shared_views" set
      "list" = save_view.list,
      "scope" = save_view.scope,
      "team_id" = case when save_view.scope = 'team' then save_view.team end,
      "owner_id" = coalesce("owner_id", auth.uid()),
      "name" = save_view.name,
      "kind" = save_view.kind,
      "state" = save_view.state,
      -- The default is per list, scope and team; moving the view drops it.
      "is_default" = case
        when "scope" = save_view.scope and "list" = save_view.list
          and "team_id" is not distinct from case when save_view.scope = 'team' then save_view.team end
        then "is_default" else false end,
      "updated_at" = now()
    where "id" = v_id
    returning "rank" into v_rank;
  end if;
  if v_inserted then
    perform "better_supabase".emit_event('saved_view.created', jsonb_build_object('organizationId', save_view.tenant, 'id', v_id, 'kind', save_view.kind, 'name', save_view.name), 'saved-views/' || v_id::text, (save_view.tenant)::text, null, 'better-supabase/saved-views');
  else
    perform "better_supabase".emit_event('saved_view.updated', jsonb_build_object('organizationId', save_view.tenant, 'id', v_id, 'kind', save_view.kind, 'name', save_view.name), 'saved-views/' || v_id::text, (save_view.tenant)::text, null, 'better-supabase/saved-views');
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_view_save"(uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid)', v_hook::oid::regproc)
        using v_id;
    end if;
  end;
  return jsonb_build_object('id', v_id, 'rank', v_rank);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.save_work_center (
  tenant         uuid,
  input          jsonb,
  work_center_id uuid  DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."work_centers";
  v_asset uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (save_work_center.tenant is not null and coalesce(better_supabase.can('tenant', save_work_center.tenant, 'manufacturing.manage'), false))) then
    raise exception 'not allowed to change work centers' using errcode = '42501', hint = 'MANUFACTURING_FORBIDDEN';
  end if;
  if jsonb_typeof(save_work_center.input) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'BOM_INVALID';
  end if;
  if save_work_center.work_center_id is not null then
    select * into v_row from "better_supabase"."work_centers" x
    where x."id" = save_work_center.work_center_id and x."tenant_id" = save_work_center.tenant for update;
    if not found then
      raise exception 'no such work center in this organization' using errcode = 'P0002', hint = 'WORK_CENTER_NOT_FOUND';
    end if;
  end if;
  v_asset := case when save_work_center.input ? 'assetId' then nullif(save_work_center.input ->> 'assetId', '')::uuid else v_row."asset_id" end;
  if v_asset is not null and not exists (select 1 from "better_supabase"."assets" a where a."id" = v_asset and a."tenant_id" = save_work_center.tenant) then
    raise exception 'the asset isn''t an asset of this organization' using errcode = '22023', hint = 'BOM_INVALID';
  end if;
  if save_work_center.work_center_id is null then
    insert into "better_supabase"."work_centers" ("tenant_id", "name", "asset_id", "hours_per_day", "cost_rate", "currency")
    values (save_work_center.tenant, trim(save_work_center.input ->> 'name'), v_asset,
      coalesce(nullif(save_work_center.input ->> 'hoursPerDay', '')::numeric, 8),
      coalesce(nullif(save_work_center.input ->> 'costRate', '')::bigint, 0),
      upper(nullif(save_work_center.input ->> 'currency', '')))
    returning * into v_row;
  else
    update "better_supabase"."work_centers" x set
      "name" = case when save_work_center.input ? 'name' then trim(save_work_center.input ->> 'name') else x."name" end,
      "asset_id" = v_asset,
      "hours_per_day" = coalesce(nullif(save_work_center.input ->> 'hoursPerDay', '')::numeric, x."hours_per_day"),
      "cost_rate" = coalesce(nullif(save_work_center.input ->> 'costRate', '')::bigint, x."cost_rate"),
      "currency" = case when save_work_center.input ? 'currency' then upper(nullif(save_work_center.input ->> 'currency', '')) else x."currency" end,
      "archived_at" = case when not save_work_center.input ? 'archived' then x."archived_at"
        when (save_work_center.input ->> 'archived')::boolean then coalesce(x."archived_at", now()) else null end,
      "updated_at" = now()
    where x."id" = v_row."id"
    returning * into v_row;
  end if;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'name', v_row."name", 'assetId', v_row."asset_id", 'hoursPerDay', v_row."hours_per_day"::text, 'costRate', v_row."cost_rate"::text, 'currency', v_row."currency", 'archivedAt', v_row."archived_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.save_work_item_checklist_item (
  task           uuid,
  checklist_item uuid,
  attrs          jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."work_items";
  v_id uuid := save_work_item_checklist_item.checklist_item;
  v_last text;
  v_done boolean := (save_work_item_checklist_item.attrs ->> 'done')::boolean;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."work_items" x where x."id" = save_work_item_checklist_item.task and ((auth.role() = 'service_role') or coalesce(better_supabase.can('tenant', x."tenant_id", 'tasks.write'), false)) and x."archived_at" is null;
  if v_row."id" is null then
    raise exception 'no such work item you can edit' using errcode = 'P0002', hint = 'TASK_NOT_FOUND';
  end if;
  begin
    if v_id is null then
      select max(y."rank") into v_last from "better_supabase"."work_item_checklist_items" y where y."work_item_id" = v_row."id";
      insert into "better_supabase"."work_item_checklist_items" ("tenant_id", "work_item_id", "title", "done", "done_at", "done_by", "rank", "created_by")
      values (v_row."tenant_id", v_row."id", trim(save_work_item_checklist_item.attrs ->> 'title'), coalesce(v_done, false),
        case when v_done then now() end, case when v_done then auth.uid() end,
        coalesce(save_work_item_checklist_item.attrs ->> 'rank', case
    when v_last is null then 'V'
    when length(substring(v_last from '^z*')) = length(v_last) then v_last || 'V'
    else left(v_last, length(substring(v_last from '^z*'))) || substr('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', (strpos('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz', substr(v_last, length(substring(v_last from '^z*')) + 1, 1)) - 1 + 62) / 2 + 1, 1)
  end), auth.uid())
      returning "id" into v_id;
    else
      update "better_supabase"."work_item_checklist_items" y set
        "title" = coalesce(trim(save_work_item_checklist_item.attrs ->> 'title'), y."title"),
        "rank" = coalesce(save_work_item_checklist_item.attrs ->> 'rank', y."rank"),
        "done" = coalesce(v_done, y."done"),
        "done_at" = case when v_done is null then y."done_at" when v_done then coalesce(y."done_at", now()) end,
        "done_by" = case when v_done is null then y."done_by" when v_done then coalesce(y."done_by", auth.uid()) end
      where y."id" = v_id and y."work_item_id" = v_row."id";
      if not found then
        raise exception 'no such checklist item on this work item' using errcode = 'P0002', hint = 'TASK_CHECKLIST_ITEM_NOT_FOUND';
      end if;
    end if;
  exception when check_violation or not_null_violation or invalid_text_representation then
    raise exception 'a checklist item needs a title of 1 to 500 characters and a valid rank' using errcode = '22023', hint = 'TASK_CHECKLIST_ITEM_INVALID';
  end;
  perform "better_supabase".emit_event('work_item.updated', jsonb_build_object('organizationId', v_row."tenant_id", 'workItemId', v_row."id", 'subjectType', 'work_item', 'subjectId', v_row."id"::text, 'title', v_row."title", 'fields', jsonb_build_array('checklist')), 'work_items/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/tasks');
  return (select jsonb_build_object('id', y."id", 'workItemId', y."work_item_id", 'title', y."title", 'done', y."done", 'doneAt', y."done_at", 'doneBy', y."done_by", 'rank', y."rank", 'createdAt', y."created_at") from "better_supabase"."work_item_checklist_items" y where y."id" = v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.save_work_item_material_line (
  task    uuid,
  line_id uuid,
  attrs   jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
