$function$;

CREATE OR REPLACE FUNCTION better_supabase.scim_save_group (
  tenant  uuid,
  id      uuid,
  data    jsonb,
  version integer DEFAULT NULL::integer
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."scim_groups";
  v_name text := scim_save_group.data ->> 'displayName';
  v_members uuid[];
  v_before uuid[] := '{}';
  v_member uuid;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'Only the service role serves SCIM' using errcode = '42501', hint = 'SSO_FORBIDDEN';
  end if;
  if v_name is null or length(trim(v_name)) = 0 then
    raise exception 'displayName is required' using errcode = '22023', hint = 'SCIM_INVALID';
  end if;
  begin
    select coalesce(array_agg(distinct (w.value)::uuid), '{}') into v_members
    from jsonb_array_elements_text(coalesce(scim_save_group.data -> 'members', '[]'::jsonb)) w;
  exception when invalid_text_representation then
    raise exception 'members must be SCIM user ids' using errcode = '22023', hint = 'SCIM_INVALID';
  end;
  if exists (
    select 1 from unnest(v_members) w(member)
    where not exists (select 1 from "better_supabase"."scim_users" x where x."tenant_id" = scim_save_group.tenant and x."id" = w.member)
  ) then
    raise exception 'members must be SCIM users of the organization' using errcode = '22023', hint = 'SCIM_INVALID';
  end if;
  if scim_save_group.id is null then
    insert into "better_supabase"."scim_groups" ("tenant_id", "display_name", "external_id", "role")
    values (scim_save_group.tenant, v_name, scim_save_group.data ->> 'externalId', "better_supabase"."scim_group_role"(v_name))
    returning * into v_row;
  else
    select * into v_row from "better_supabase"."scim_groups" x where x."tenant_id" = scim_save_group.tenant and x."id" = scim_save_group.id for update;
    if v_row."id" is null then
      raise exception 'No SCIM group has this id' using errcode = 'P0002', hint = 'SCIM_NOT_FOUND';
    end if;
    if scim_save_group.version is not null and scim_save_group.version <> v_row."version" then
      raise exception 'The group changed since version %', scim_save_group.version using errcode = 'P0001', hint = 'SCIM_PRECONDITION';
    end if;
    select coalesce(array_agg(sm."scim_user_id"), '{}') into v_before from "better_supabase"."scim_group_members" sm where sm."group_id" = v_row."id";
    update "better_supabase"."scim_groups" x set
      "display_name" = v_name,
      "external_id" = scim_save_group.data ->> 'externalId',
      "role" = "better_supabase"."scim_group_role"(v_name),
      "version" = x."version" + 1,
      "updated_at" = now()
    where x."id" = v_row."id"
    returning * into v_row;
    delete from "better_supabase"."scim_group_members" sm where sm."group_id" = v_row."id" and not (sm."scim_user_id" = any (v_members));
  end if;
  insert into "better_supabase"."scim_group_members" ("group_id", "scim_user_id")
  select v_row."id", w.member from unnest(v_members) w(member)
  on conflict do nothing;
  for v_member in select distinct w.member from unnest(v_before || v_members) w(member) loop
    perform "better_supabase"."scim_sync_member"(v_member);
  end loop;
  if scim_save_group.id is null then
    perform "better_supabase".emit_event('scim_group.created', jsonb_build_object('organizationId', scim_save_group.tenant::text, 'scimGroupId', v_row."id"), 'organizations/' || scim_save_group.tenant::text, (scim_save_group.tenant)::text, null, 'better-supabase/sso');
  perform better_supabase.audit_event(
    event_type => 'scim_group.created',
    category => 'security',
    target_type => 'scim_group',
    record_id => v_row."id"::text,
    tenant => (scim_save_group.tenant)::uuid,
    metadata => jsonb_build_object('organizationId', scim_save_group.tenant::text, 'scimGroupId', v_row."id")
  );
  else
    perform "better_supabase".emit_event('scim_group.updated', jsonb_build_object('organizationId', scim_save_group.tenant::text, 'scimGroupId', v_row."id"), 'organizations/' || scim_save_group.tenant::text, (scim_save_group.tenant)::text, null, 'better-supabase/sso');
  perform better_supabase.audit_event(
    event_type => 'scim_group.updated',
    category => 'security',
    target_type => 'scim_group',
    record_id => v_row."id"::text,
    tenant => (scim_save_group.tenant)::uuid,
    metadata => jsonb_build_object('organizationId', scim_save_group.tenant::text, 'scimGroupId', v_row."id")
  );
  end if;
  return (select to_jsonb(x.*) || jsonb_build_object('members', (
      select coalesce(jsonb_agg(jsonb_build_object('value', su."id", 'display', coalesce(su."display_name", su."user_name")) order by su."user_name"), '[]'::jsonb)
      from "better_supabase"."scim_group_members" sm join "better_supabase"."scim_users" su on su."id" = sm."scim_user_id"
      where sm."group_id" = x."id"
    )) from "better_supabase"."scim_groups" x where x."id" = v_row."id");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.scim_save_user (
  tenant  uuid,
  id      uuid,
  data    jsonb,
  version integer DEFAULT NULL::integer
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."scim_users";
  v_emails jsonb := coalesce(scim_save_user.data -> 'emails', '[]'::jsonb);
  v_name text := scim_save_user.data ->> 'userName';
  v_email text;
  v_user uuid;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'Only the service role serves SCIM' using errcode = '42501', hint = 'SSO_FORBIDDEN';
  end if;
  if v_name is null or length(trim(v_name)) = 0 then
    raise exception 'userName is required' using errcode = '22023', hint = 'SCIM_INVALID';
  end if;
  if jsonb_typeof(v_emails) <> 'array' then
    raise exception 'emails must be an array' using errcode = '22023', hint = 'SCIM_INVALID';
  end if;
  v_email := lower(coalesce(
    (select e ->> 'value' from jsonb_array_elements(v_emails) e where (e ->> 'primary')::boolean limit 1),
    v_emails -> 0 ->> 'value',
    case when v_name like '%@%' then v_name end
  ));
  if scim_save_user.id is null then
    insert into "better_supabase"."scim_users" ("tenant_id", "external_id", "user_name", "display_name", "given_name", "family_name", "email", "emails", "active")
    values (scim_save_user.tenant, scim_save_user.data ->> 'externalId', v_name, scim_save_user.data ->> 'displayName',
      scim_save_user.data ->> 'givenName', scim_save_user.data ->> 'familyName', v_email, v_emails,
      coalesce((scim_save_user.data ->> 'active')::boolean, true))
    returning * into v_row;
  else
    select * into v_row from "better_supabase"."scim_users" x where x."tenant_id" = scim_save_user.tenant and x."id" = scim_save_user.id for update;
    if v_row."id" is null then
      raise exception 'No SCIM user has this id' using errcode = 'P0002', hint = 'SCIM_NOT_FOUND';
    end if;
    if scim_save_user.version is not null and scim_save_user.version <> v_row."version" then
      raise exception 'The user changed since version %', scim_save_user.version using errcode = 'P0001', hint = 'SCIM_PRECONDITION';
    end if;
    update "better_supabase"."scim_users" x set
      "external_id" = scim_save_user.data ->> 'externalId',
      "user_name" = v_name,
      "display_name" = scim_save_user.data ->> 'displayName',
      "given_name" = scim_save_user.data ->> 'givenName',
      "family_name" = scim_save_user.data ->> 'familyName',
      "email" = v_email,
      "emails" = v_emails,
      "active" = coalesce((scim_save_user.data ->> 'active')::boolean, true),
      "version" = x."version" + 1,
      "updated_at" = now()
    where x."id" = v_row."id"
    returning * into v_row;
  end if;
  if v_row."user_id" is null and v_email is not null and exists (select 1 from "better_supabase"."sso_domains" vd where vd."tenant_id" = scim_save_user.tenant and vd."verified_at" is not null and vd."domain" = lower(split_part(v_email, '@', 2))) then
    select au.id into v_user from auth.users au
    where lower(au.email) = v_email and au.email_confirmed_at is not null
      and not exists (select 1 from "better_supabase"."scim_users" y where y."tenant_id" = scim_save_user.tenant and y."user_id" = au.id)
    limit 1;
    if v_user is not null then
      update "better_supabase"."scim_users" x set "user_id" = v_user where x."id" = v_row."id" returning * into v_row;
    end if;
  end if;
  perform "better_supabase"."scim_sync_member"(v_row."id");
  if scim_save_user.id is null then
    perform "better_supabase".emit_event('scim_user.created', jsonb_build_object('organizationId', scim_save_user.tenant::text, 'scimUserId', v_row."id"), 'organizations/' || scim_save_user.tenant::text, (scim_save_user.tenant)::text, null, 'better-supabase/sso');
  perform better_supabase.audit_event(
    event_type => 'scim_user.created',
    category => 'security',
    target_type => 'scim_user',
    record_id => v_row."id"::text,
    tenant => (scim_save_user.tenant)::uuid,
    metadata => jsonb_build_object('organizationId', scim_save_user.tenant::text, 'scimUserId', v_row."id")
  );
  else
    perform "better_supabase".emit_event('scim_user.updated', jsonb_build_object('organizationId', scim_save_user.tenant::text, 'scimUserId', v_row."id"), 'organizations/' || scim_save_user.tenant::text, (scim_save_user.tenant)::text, null, 'better-supabase/sso');
  perform better_supabase.audit_event(
    event_type => 'scim_user.updated',
    category => 'security',
    target_type => 'scim_user',
    record_id => v_row."id"::text,
    tenant => (scim_save_user.tenant)::uuid,
    metadata => jsonb_build_object('organizationId', scim_save_user.tenant::text, 'scimUserId', v_row."id")
  );
  end if;
  return (select to_jsonb(x.*) || jsonb_build_object('groups', (
      select coalesce(jsonb_agg(jsonb_build_object('value', sg."id", 'display', sg."display_name") order by sg."display_name"), '[]'::jsonb)
      from "better_supabase"."scim_group_members" sm join "better_supabase"."scim_groups" sg on sg."id" = sm."group_id"
      where sm."scim_user_id" = x."id"
    )) from "better_supabase"."scim_users" x where x."id" = v_row."id");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.scim_sync_member (
  scim_user uuid
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."scim_users";
  v_tenant uuid;
  v_user uuid;
  v_current text;
  v_role text;
begin
  select * into v_row from "better_supabase"."scim_users" x where x."id" = scim_sync_member.scim_user;
  if v_row."user_id" is null then
    return;
  end if;
  v_tenant := v_row."tenant_id";
  v_user := v_row."user_id";
  select (select r."key" from "better_supabase"."roles" r where r."id" = mm."role") into v_current from "public"."memberships" mm where mm."organization_id" = v_tenant and mm."user_id" = v_user;
  if v_current = 'owner' then
    return;
  end if;
  if not v_row."active" then
    delete from "public"."memberships" mm where mm."organization_id" = v_tenant and mm."user_id" = v_user;
    if found then
      perform "better_supabase".emit_event('organization.member_removed', jsonb_build_object('organizationId', v_tenant::text, 'userId', v_user), 'organizations/' || v_tenant::text, (v_tenant)::text, null, 'better-supabase/sso');
  perform better_supabase.audit_event(
    event_type => 'organization.member_removed',
    category => 'membership',
    target_type => 'user',
    record_id => v_user::text,
    tenant => (v_tenant)::uuid,
    metadata => jsonb_build_object('organizationId', v_tenant::text, 'userId', v_user)
  );
    end if;
    return;
  end if;
  select coalesce((
    select sg."role" from "better_supabase"."scim_group_members" sm join "better_supabase"."scim_groups" sg on sg."id" = sm."group_id"
    where sm."scim_user_id" = v_row."id" and sg."role" is not null
    order by array_position(array['admin', 'member', 'viewer']::text[], sg."role")
    limit 1
  ), 'member') into v_role;
  if v_current is null then
    insert into "public"."memberships" ("organization_id", "user_id", "role") values (v_tenant, v_user, (select r."id" from "better_supabase"."roles" r where (r."id"::text = (v_role)::text or r."key" = (v_role)::text) order by (r."id"::text = (v_role)::text) desc limit 1));
    perform "better_supabase".emit_event('organization.member_added', jsonb_build_object('organizationId', v_tenant::text, 'userId', v_user, 'role', v_role), 'organizations/' || v_tenant::text, (v_tenant)::text, null, 'better-supabase/sso');
  perform better_supabase.audit_event(
    event_type => 'organization.member_added',
    category => 'membership',
    target_type => 'user',
    record_id => v_user::text,
    tenant => (v_tenant)::uuid,
    metadata => jsonb_build_object('organizationId', v_tenant::text, 'userId', v_user, 'role', v_role)
  );
  elsif v_current is distinct from v_role then
    update "public"."memberships" mm set "role" = (select r."id" from "better_supabase"."roles" r where (r."id"::text = (v_role)::text or r."key" = (v_role)::text) order by (r."id"::text = (v_role)::text) desc limit 1) where mm."organization_id" = v_tenant and mm."user_id" = v_user;
    perform "better_supabase".emit_event('organization.role_changed', jsonb_build_object('organizationId', v_tenant::text, 'userId', v_user, 'role', v_role, 'previousRole', v_current), 'organizations/' || v_tenant::text, (v_tenant)::text, null, 'better-supabase/sso');
  perform better_supabase.audit_event(
    event_type => 'organization.role_changed',
    category => 'membership',
    target_type => 'user',
    record_id => v_user::text,
    tenant => (v_tenant)::uuid,
    metadata => jsonb_build_object('organizationId', v_tenant::text, 'userId', v_user, 'role', v_role, 'previousRole', v_current)
  );
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.scope_permissions (
  scope text
)
  RETURNS text[]
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO ''
  AS $function$
  select array[scope]
$function$;

CREATE OR REPLACE FUNCTION better_supabase.score_history (
  tenant       uuid,
  model_key    text,
  subject_type text,
  subject_id   text,
  page_size    integer DEFAULT 50
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', score_history.tenant, 'scores.read'), false)) then
    raise exception 'not allowed to read scores' using errcode = '42501', hint = 'SCORES_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', z."id", 'organizationId', z."tenant_id", 'modelId', z."model_id", 'modelKey', z.model_key, 'modelVersion', z."model_version", 'subjectType', z."subject_type", 'subjectId', z."subject_id", 'score', z."score", 'band', z."band", 'breakdown', z."breakdown", 'current', z."is_current", 'computedAt', z."computed_at") order by z."computed_at" desc, z."id" desc)
    from (
      select x.*, y."key" as model_key
      from "better_supabase"."scores" x join "better_supabase"."score_models" y on y."id" = x."model_id"
      where x."tenant_id" = score_history.tenant and y."key" = score_history.model_key
        and x."subject_type" = score_history.subject_type and x."subject_id" = score_history.subject_id
      order by x."computed_at" desc, x."id" desc
      limit least(greatest(coalesce(score_history.page_size, 50), 1), 200)
    ) z
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.score_lead (
  tenant       uuid,
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_fields jsonb;
  v_result jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (score_lead.tenant is not null and coalesce(better_supabase.can('tenant', score_lead.tenant, 'scores.compute'), false))) then
    raise exception 'not allowed to score leads' using errcode = '42501', hint = 'LEAD_SCORING_FORBIDDEN';
  end if;
  if score_lead.subject_type not in ('person') then
    raise exception 'lead scoring doesn''t score this subject type' using errcode = '22023', hint = 'LEAD_SCORING_SUBJECT';
  end if;
  v_fields := "better_supabase"."lead_fields"(score_lead.tenant, score_lead.subject_type, score_lead.subject_id);
  if v_fields is null then
    raise exception 'no such record' using errcode = 'P0002', hint = 'LEAD_SCORING_NOT_FOUND';
  end if;
  v_result := "better_supabase"."compute_score"(score_lead.tenant, 'lead', score_lead.subject_type, score_lead.subject_id, v_fields);
  insert into "better_supabase"."lead_score_checks" ("tenant_id", "subject_type", "subject_id", "stale", "checked_at")
  values (score_lead.tenant, score_lead.subject_type, score_lead.subject_id, false, now())
  on conflict on constraint "lead_score_checks_pkey" do update
    set "stale" = false, "checked_at" = now();
  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.score_leads_due (
  max_count integer DEFAULT 100
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_check "better_supabase"."lead_score_checks";
  v_count integer := 0;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'not allowed to score leads' using errcode = '42501', hint = 'LEAD_SCORING_FORBIDDEN';
  end if;
  insert into "better_supabase"."lead_score_checks" ("tenant_id", "subject_type", "subject_id")
  select x."tenant_id", 'person', x."id"::text
  from "better_supabase"."people" x
  where x."archived_at" is null
    and not exists (select 1 from "better_supabase"."lead_score_checks" k where k."subject_type" = 'person' and k."subject_id" = x."id"::text)
  limit least(greatest(coalesce(max_count, 100), 1), 1000)
  on conflict do nothing;
  for v_check in
    select k.* from "better_supabase"."lead_score_checks" k
    where (k."stale" or k."checked_at" < now() - interval '24 hours')
      and exists (
        select 1 from "better_supabase"."score_models" m
        where m."tenant_id" = k."tenant_id" and m."key" = 'lead'
          and m."subject_type" = k."subject_type" and m."enabled"
      )
    order by k."checked_at" nulls first
    limit least(greatest(coalesce(max_count, 100), 1), 1000)
    for update of k skip locked
  loop
    if "better_supabase"."lead_fields"(v_check."tenant_id", v_check."subject_type", v_check."subject_id") is null then
      delete from "better_supabase"."lead_score_checks" k where k."subject_type" = v_check."subject_type" and k."subject_id" = v_check."subject_id";
      continue;
    end if;
    perform "better_supabase"."score_lead"(v_check."tenant_id", v_check."subject_type", v_check."subject_id");
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.search (
  q           text,
  types       text[]  DEFAULT NULL::text[],
  tenant      uuid    DEFAULT NULL::uuid,
  max_results integer DEFAULT 20
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  v_q text := btrim(coalesce(search.q, ''));
  v_norm text;
  v_web tsquery;
  v_prefix tsquery;
  v_limit integer := least(greatest(coalesce(search.max_results, 20), 1), 100);
  v_pool integer;
begin
  if length(v_q) > 256 then
    raise exception 'a search query is at most 256 characters' using errcode = '22023', hint = 'SEARCH_QUERY_TOO_LONG';
  end if;
  if v_q = '' then
    return '[]'::jsonb;
  end if;
  v_pool := v_limit * 5;
  v_norm := "better_supabase"."search_normalize"(v_q);
  v_web := websearch_to_tsquery('simple', v_norm);
  select to_tsquery('simple', string_agg(quote_literal(w) || ':*', ' & '))
    into v_prefix
    from regexp_split_to_table(v_norm, '[^[:alnum:]]+') w
    where w <> '';
  return coalesce((
    with text_hits as materialized (
      select h.subject_type, h.subject_id, h.score,
        row_number() over (order by h.score desc) as rank
      from (
        select d."subject_type" as subject_type, d."subject_id" as subject_id,
          2 * coalesce(ts_rank_cd(d."tsv", v_web), 0)
            + coalesce(ts_rank_cd(d."tsv", v_prefix), 0)
            + extensions.similarity(d."title_search", v_norm) as score
        from "better_supabase"."search_documents" d
        where (search.types is null or d."subject_type" = any (search.types))
          and (search.tenant is null or d."tenant_id" = search.tenant)
          and (d."tsv" @@ v_web
            or (v_prefix is not null and d."tsv" @@ v_prefix)
            or d."title_search" operator(extensions.%) v_norm)
        order by score desc
        limit v_pool
      ) h
    ),
    fused as (
      select t.subject_type, t.subject_id, t.score from text_hits t
    ),
    visible as (
      select d."tenant_id" as tenant, d."subject_type" as subject_type, d."subject_id" as subject_id,
        d."title" as title, d."url" as url, d."body" as body, f.score
      from fused f
      join "better_supabase"."search_documents" d on d."subject_type" = f.subject_type and d."subject_id" = f.subject_id
      where "better_supabase"."can_subject"(f.subject_type, f.subject_id, 'read')
      order by f.score desc, f.subject_type, f.subject_id
      limit v_limit
    )
    select jsonb_agg(jsonb_build_object(
      'organizationId', v.tenant,
      'subjectType', v.subject_type,
      'subjectId', v.subject_id,
      'title', v.title,
      'url', v.url,
      'snippet', case when v.body is null then null
        else ts_headline('simple', v.body, coalesce(v_prefix, v_web), 'StartSel="", StopSel="", MaxWords=20, MinWords=8, MaxFragments=1')
      end,
      'score', round(v.score::numeric, 6)
    ) order by v.score desc, v.subject_type, v.subject_id)
    from visible v
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.search_enqueue (
  subject_type text,
  subject_id   text
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_key text := search_enqueue.subject_type || E'\x1f' || search_enqueue.subject_id;
  v_name text := 'better_supabase.search_dirty_' || (hashtext(v_key) & 255)::text;
  v_dirty text;
begin
  if coalesce(current_setting('better_supabase.search_deferred', true), '') = 'on' then
    v_dirty := coalesce(current_setting(v_name, true), '');
    if position(E'\n' || v_key || E'\n' in E'\n' || v_dirty) = 0 then
      perform set_config(v_name, v_dirty || v_key || E'\n', true);
    end if;
  else
    perform "better_supabase"."search_refresh"(search_enqueue.subject_type, search_enqueue.subject_id);
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.search_favorites (
  max_results integer DEFAULT 10,
  types       text[]  DEFAULT NULL::text[]
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(x.item order by x.at desc), '[]'::jsonb)
  from (
    select s.starred_at as at, jsonb_build_object(
      'subjectType', s.subject_type,
      'subjectId', s.subject_id,
      'title', "better_supabase"."subject_title"(s.subject_type, s.subject_id),
      'url', "better_supabase"."subject_url"(s.subject_type, s.subject_id),
      'openedAt', s.opened_at,
      'starredAt', s.starred_at
    ) as item
    from "better_supabase"."search_user_state"() s
    where s.starred_at is not null
      and (search_favorites.types is null or s.subject_type = any (search_favorites.types))
      and "better_supabase"."can_subject"(s.subject_type, s.subject_id, 'read')
    order by s.starred_at desc
    limit least(greatest(coalesce(search_favorites.max_results, 10), 1), 100)
  ) x
$function$;

CREATE OR REPLACE FUNCTION better_supabase.search_index_row()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_old text := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) ->> tg_argv[1] end;
  v_new text := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) ->> tg_argv[1] end;
begin
  if v_old is not null and v_old is distinct from v_new then
    perform "better_supabase"."search_enqueue"(tg_argv[0], v_old);
  end if;
  if v_new is not null then
    perform "better_supabase"."search_enqueue"(tg_argv[0], v_new);
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.search_normalize (
  value text
)
  RETURNS text
  LANGUAGE sql
  IMMUTABLE
  PARALLEL SAFE
  SET search_path TO ''
  AS $function$
  select lower(extensions.unaccent('extensions.unaccent'::regdictionary, coalesce(value, '')))
$function$;

CREATE OR REPLACE FUNCTION better_supabase.search_recents (
  max_results integer DEFAULT 10,
  types       text[]  DEFAULT NULL::text[]
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(x.item order by x.at desc), '[]'::jsonb)
  from (
    select s.opened_at as at, jsonb_build_object(
      'subjectType', s.subject_type,
      'subjectId', s.subject_id,
      'title', "better_supabase"."subject_title"(s.subject_type, s.subject_id),
      'url', "better_supabase"."subject_url"(s.subject_type, s.subject_id),
      'openedAt', s.opened_at,
      'starredAt', s.starred_at
    ) as item
    from "better_supabase"."search_user_state"() s
    where s.opened_at is not null
      and (search_recents.types is null or s.subject_type = any (search_recents.types))
      and "better_supabase"."can_subject"(s.subject_type, s.subject_id, 'read')
    order by s.opened_at desc
    limit least(greatest(coalesce(search_recents.max_results, 10), 1), 100)
  ) x
$function$;

CREATE OR REPLACE FUNCTION better_supabase.search_refresh (
  subject_type text,
  subject_id   text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_tenant uuid;
  v_title text;
  v_body text;
  v_url text;
  v_found boolean := false;
  v_hash text;
begin
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_search_document_index"(text, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::text, $2::text)', v_hook::oid::regproc)
        using search_refresh.subject_type, search_refresh.subject_id;
    end if;
  end;
  case search_refresh.subject_type
    when 'message' then
      select s."tenant_id", s."body"::text, null, null
        into v_tenant, v_title, v_body, v_url
        from "better_supabase"."messages" s
        where s."id" = (search_refresh.subject_id)::uuid
        and s."archived_at" is null;
      v_found := found;
    when 'channel' then
      select s."tenant_id", s."name"::text, nullif(concat_ws(E'\n', s."topic"::text, s."purpose"::text), ''), null
        into v_tenant, v_title, v_body, v_url
        from "better_supabase"."channels" s
        where s."id" = (search_refresh.subject_id)::uuid;
      v_found := found;
    when 'company' then
      select s."tenant_id", s."name"::text, nullif(concat_ws(E'\n', s."domain"::text), ''), '/crm/contacts/' || s."id"::text
        into v_tenant, v_title, v_body, v_url
        from "better_supabase"."companies" s
        where s."id" = (search_refresh.subject_id)::uuid;
      v_found := found;
    when 'person' then
      select s."tenant_id", s."name"::text, nullif(concat_ws(E'\n', s."email"::text, s."title"::text), ''), '/crm/contacts/' || s."id"::text
        into v_tenant, v_title, v_body, v_url
        from "better_supabase"."people" s
        where s."id" = (search_refresh.subject_id)::uuid;
      v_found := found;
    when 'deal' then
      select s."tenant_id", s."name"::text, nullif(concat_ws(E'\n', s."identifier"::text, s."note"::text), ''), '/crm/deals'
        into v_tenant, v_title, v_body, v_url
        from "better_supabase"."deals" s
        where s."id" = (search_refresh.subject_id)::uuid
        and s."archived_at" is null;
      v_found := found;
    when 'course' then
      select s."tenant_id", s."title"::text, nullif(concat_ws(E'\n', s."summary"::text), ''), null
        into v_tenant, v_title, v_body, v_url
        from "better_supabase"."courses" s
        where s."id" = (search_refresh.subject_id)::uuid;
      v_found := found;
    when 'post' then
      select s."tenant_id", s."title"::text, nullif(concat_ws(E'\n', s."body"::text), ''), null
        into v_tenant, v_title, v_body, v_url
        from "better_supabase"."posts" s
        where s."id" = (search_refresh.subject_id)::uuid;
      v_found := found;
    when 'activity' then
      select s."tenant_id", s."title"::text, nullif(concat_ws(E'\n', s."body"::text, s."outcome"::text), ''), null
        into v_tenant, v_title, v_body, v_url
        from "better_supabase"."activities" s
        where s."id" = (search_refresh.subject_id)::uuid;
      v_found := found;
    when 'quote' then
      select s."tenant_id", s."title"::text, null, '/crm/quotes/' || s."id"::text
        into v_tenant, v_title, v_body, v_url
        from "better_supabase"."quotes" s
        where s."id" = (search_refresh.subject_id)::uuid;
      v_found := found;
    when 'work_item' then
      select s."tenant_id", s."title"::text, nullif(concat_ws(E'\n', s."identifier"::text, s."body"::text), ''), '/work'
        into v_tenant, v_title, v_body, v_url
        from "better_supabase"."work_items" s
        where s."id" = (search_refresh.subject_id)::uuid
        and s."archived_at" is null;
      v_found := found;
    when 'employee' then
      select s."tenant_id", s."name"::text, nullif(concat_ws(E'\n', s."email"::text, s."job_title"::text), ''), '/people/' || s."id"::text
        into v_tenant, v_title, v_body, v_url
        from "better_supabase"."employees" s
        where s."id" = (search_refresh.subject_id)::uuid;
      v_found := found;
    when 'ledger_account' then
      select s."tenant_id", s."name"::text, null, '/finance'
        into v_tenant, v_title, v_body, v_url
        from "better_supabase"."ledger_accounts" s
        where s."id" = (search_refresh.subject_id)::uuid;
      v_found := found;
    when 'invoice' then
      select s."tenant_id", s."title"::text, null, '/finance/payables'
        into v_tenant, v_title, v_body, v_url
        from "better_supabase"."invoices" s
        where s."id" = (search_refresh.subject_id)::uuid;
      v_found := found;
    when 'product' then
      select s."tenant_id", s."title"::text, nullif(concat_ws(E'\n', s."description"::text, s."slug"::text), ''), '/shop'
        into v_tenant, v_title, v_body, v_url
