CREATE OR REPLACE FUNCTION better_supabase.search_remove (
  subject_type text,
  subject_id   text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
begin
  delete from "better_supabase"."search_documents"
  where "subject_type" = search_remove.subject_type and "subject_id" = search_remove.subject_id;
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.search_star (
  subject_type text,
  subject_id   text,
  starred      boolean
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if auth.uid() is null then
    raise exception 'sign in to keep favorites' using errcode = '42501', hint = 'SEARCH_SIGNED_OUT';
  end if;
  insert into "better_supabase"."subject_user_state" as st ("subject_type", "subject_id", "user_id", "starred_at") values (search_star.subject_type, search_star.subject_id, auth.uid(), case when search_star.starred then now() end)
  on conflict ("subject_type", "subject_id", "user_id") do update set "starred_at" = case when search_star.starred then coalesce(st."starred_at", now()) end;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.search_supplier_items (
  tenant    uuid,
  query     text,
  supplier  uuid    DEFAULT NULL::uuid,
  row_limit integer DEFAULT 25
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(r.item order by r.rank desc, r.code), '[]'::jsonb)
  from (
    select x."code" as code,
      ts_rank(x."keywords", websearch_to_tsquery('simple', $2)) + case when x."code" ilike replace(replace($2, '%', ''), '_', '') || '%' then 1 else 0 end as rank,
      jsonb_build_object('id', x."id", 'supplierId', x."supplier_id", 'code', x."code", 'description', x."description", 'price', x."price", 'currency', x."currency", 'unit', x."unit", 'variantId', x."variant_id") as item
    from "better_supabase"."supplier_items" x
    where x."tenant_id" = $1 and ($3 is null or x."supplier_id" = $3)
      and (x."keywords" @@ websearch_to_tsquery('simple', $2) or x."code" ilike replace(replace($2, '%', ''), '_', '') || '%')
    order by 2 desc, 1
    limit least(greatest(coalesce($4, 25), 1), 200)
  ) r
$function$;

CREATE OR REPLACE FUNCTION better_supabase.search_touch (
  subject_type text,
  subject_id   text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if auth.uid() is null then
    raise exception 'sign in to keep recents' using errcode = '42501', hint = 'SEARCH_SIGNED_OUT';
  end if;
  insert into "better_supabase"."subject_user_state" as st ("subject_type", "subject_id", "user_id", "last_opened_at") values (search_touch.subject_type, search_touch.subject_id, auth.uid(), now())
  on conflict ("subject_type", "subject_id", "user_id") do update set "last_opened_at" = now();
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.search_user_state()
  RETURNS TABLE (
    subject_type text,
    subject_id   text,
    starred_at   timestamp with time zone,
    opened_at    timestamp with time zone
  )
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select s."subject_type", s."subject_id", s."starred_at", s."last_opened_at"
  from "better_supabase"."subject_user_state" s
  where s."user_id" = auth.uid()
$function$;

CREATE OR REPLACE FUNCTION better_supabase.search_watch_drive_node_0()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_id text;
begin
  if tg_op in ('UPDATE', 'DELETE') and old."node_id" is not null then
    perform "better_supabase"."search_enqueue"('drive_node', old."node_id"::text);
  end if;
  if tg_op in ('INSERT', 'UPDATE') and new."node_id" is not null then
    perform "better_supabase"."search_enqueue"('drive_node', new."node_id"::text);
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.seed_accounting_defaults (
  p_tenant  uuid,
  p_variant text DEFAULT NULL::text,
  p_locale  text DEFAULT 'en'::text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  insert into "better_supabase"."accounting_dimensions" ("tenant_id", "key", "name")
  select p_tenant, 'cost_center', 'Cost center'
  where not exists (select 1 from "better_supabase"."accounting_dimensions" x where x."tenant_id" = p_tenant and x."key" is not distinct from 'cost_center');
