CREATE OR REPLACE FUNCTION better_supabase.seed_pipelines_defaults (
  p_tenant  uuid,
  p_variant text DEFAULT NULL::text,
  p_locale  text DEFAULT 'en'::text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if (p_variant is null or p_variant = 'b2b-sales') then
    insert into "better_supabase"."pipelines" ("tenant_id", "subject_type", "scope_id", "key", "name", "is_default")
    select p_tenant, 'deal', null, 'default', 'Default', (not exists (select 1 from "better_supabase"."pipelines" d where d."tenant_id" = p_tenant and d."subject_type" = 'deal' and d."scope_id" is null and d."is_default" and d."archived_at" is null))
    where not exists (select 1 from "better_supabase"."pipelines" x where x."tenant_id" = p_tenant and x."subject_type" is not distinct from 'deal' and x."scope_id" is not distinct from null and x."key" is not distinct from 'default');
  end if;
  if (p_variant is null or p_variant = 'b2b-sales') then
    insert into "better_supabase"."pipeline_stages" ("tenant_id", "pipeline_id", "key", "name", "category", "outcome", "rank", "system_key", "probability")
    select p_tenant, (select x."id" from "better_supabase"."pipelines" x where x."tenant_id" = p_tenant and x."subject_type" = 'deal' and x."scope_id" is null and x."key" = 'default' limit 1), 'qualified', 'Qualified', ('open'), ('open'), '8', 'qualified', 20
    where not exists (select 1 from "better_supabase"."pipeline_stages" x where x."tenant_id" = p_tenant and x."pipeline_id" is not distinct from (select x."id" from "better_supabase"."pipelines" x where x."tenant_id" = p_tenant and x."subject_type" = 'deal' and x."scope_id" is null and x."key" = 'default' limit 1) and x."system_key" is not distinct from 'qualified');
    insert into "better_supabase"."pipeline_stages" ("tenant_id", "pipeline_id", "key", "name", "category", "outcome", "rank", "system_key", "probability")
    select p_tenant, (select x."id" from "better_supabase"."pipelines" x where x."tenant_id" = p_tenant and x."subject_type" = 'deal' and x."scope_id" is null and x."key" = 'default' limit 1), 'discovery', 'Discovery', ('open'), ('open'), 'G', 'discovery', 35
    where not exists (select 1 from "better_supabase"."pipeline_stages" x where x."tenant_id" = p_tenant and x."pipeline_id" is not distinct from (select x."id" from "better_supabase"."pipelines" x where x."tenant_id" = p_tenant and x."subject_type" = 'deal' and x."scope_id" is null and x."key" = 'default' limit 1) and x."system_key" is not distinct from 'discovery');
    insert into "better_supabase"."pipeline_stages" ("tenant_id", "pipeline_id", "key", "name", "category", "outcome", "rank", "system_key", "probability")
    select p_tenant, (select x."id" from "better_supabase"."pipelines" x where x."tenant_id" = p_tenant and x."subject_type" = 'deal' and x."scope_id" is null and x."key" = 'default' limit 1), 'proposal', 'Proposal', ('open'), ('open'), 'O', 'proposal', 55
    where not exists (select 1 from "better_supabase"."pipeline_stages" x where x."tenant_id" = p_tenant and x."pipeline_id" is not distinct from (select x."id" from "better_supabase"."pipelines" x where x."tenant_id" = p_tenant and x."subject_type" = 'deal' and x."scope_id" is null and x."key" = 'default' limit 1) and x."system_key" is not distinct from 'proposal');
    insert into "better_supabase"."pipeline_stages" ("tenant_id", "pipeline_id", "key", "name", "category", "outcome", "rank", "system_key", "probability")
    select p_tenant, (select x."id" from "better_supabase"."pipelines" x where x."tenant_id" = p_tenant and x."subject_type" = 'deal' and x."scope_id" is null and x."key" = 'default' limit 1), 'negotiation', 'Negotiation', ('open'), ('open'), 'W', 'negotiation', 75
    where not exists (select 1 from "better_supabase"."pipeline_stages" x where x."tenant_id" = p_tenant and x."pipeline_id" is not distinct from (select x."id" from "better_supabase"."pipelines" x where x."tenant_id" = p_tenant and x."subject_type" = 'deal' and x."scope_id" is null and x."key" = 'default' limit 1) and x."system_key" is not distinct from 'negotiation');
    insert into "better_supabase"."pipeline_stages" ("tenant_id", "pipeline_id", "key", "name", "category", "outcome", "rank", "system_key", "probability")
    select p_tenant, (select x."id" from "better_supabase"."pipelines" x where x."tenant_id" = p_tenant and x."subject_type" = 'deal' and x."scope_id" is null and x."key" = 'default' limit 1), 'closed_won', 'Closed won', ('won'), ('success'), 'e', 'closed_won', 100
    where not exists (select 1 from "better_supabase"."pipeline_stages" x where x."tenant_id" = p_tenant and x."pipeline_id" is not distinct from (select x."id" from "better_supabase"."pipelines" x where x."tenant_id" = p_tenant and x."subject_type" = 'deal' and x."scope_id" is null and x."key" = 'default' limit 1) and x."system_key" is not distinct from 'closed_won');
    insert into "better_supabase"."pipeline_stages" ("tenant_id", "pipeline_id", "key", "name", "category", "outcome", "rank", "system_key", "probability")
    select p_tenant, (select x."id" from "better_supabase"."pipelines" x where x."tenant_id" = p_tenant and x."subject_type" = 'deal' and x."scope_id" is null and x."key" = 'default' limit 1), 'closed_lost', 'Closed lost', ('lost'), ('failure'), 'm', 'closed_lost', 0
    where not exists (select 1 from "better_supabase"."pipeline_stages" x where x."tenant_id" = p_tenant and x."pipeline_id" is not distinct from (select x."id" from "better_supabase"."pipelines" x where x."tenant_id" = p_tenant and x."subject_type" = 'deal' and x."scope_id" is null and x."key" = 'default' limit 1) and x."system_key" is not distinct from 'closed_lost');
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.seed_risks_defaults (
  p_tenant  uuid,
  p_variant text DEFAULT NULL::text,
  p_locale  text DEFAULT 'en'::text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  insert into "better_supabase"."risk_matrices" ("tenant_id", "key", "name", "likelihood_levels", "impact_levels", "bands", "scoring", "is_default")
  select p_tenant, 'default', 'Default 5x5', '[{"value":1,"label":"Rare"},{"value":2,"label":"Unlikely"},{"value":3,"label":"Possible"},{"value":4,"label":"Likely"},{"value":5,"label":"Almost certain"}]'::jsonb, '[{"value":1,"label":"Insignificant"},{"value":2,"label":"Minor"},{"value":3,"label":"Moderate"},{"value":4,"label":"Major"},{"value":5,"label":"Severe"}]'::jsonb, '[{"key":"low","label":"Low","min":1,"max":4},{"key":"medium","label":"Medium","min":5,"max":9},{"key":"high","label":"High","min":10,"max":16},{"key":"critical","label":"Critical","min":17,"max":25}]'::jsonb, 'product', (not exists (select 1 from "better_supabase"."risk_matrices" d where d."tenant_id" = p_tenant and d."is_default"))
  where not exists (select 1 from "better_supabase"."risk_matrices" x where x."tenant_id" = p_tenant and x."key" is not distinct from 'default');
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.seed_tax_defaults (
  p_tenant  uuid,
  p_variant text DEFAULT NULL::text,
  p_locale  text DEFAULT 'en'::text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if p_locale = any (array['nl']) then
    insert into "better_supabase"."tax_codes" ("tenant_id", "code", "name", "type")
    select p_tenant, 'NL21', 'BTW hoog 21%', 'sales'
    where not exists (select 1 from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" is not distinct from 'NL21');
    insert into "better_supabase"."tax_codes" ("tenant_id", "code", "name", "type")
    select p_tenant, 'NL9', 'BTW laag 9%', 'sales'
    where not exists (select 1 from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" is not distinct from 'NL9');
    insert into "better_supabase"."tax_codes" ("tenant_id", "code", "name", "type")
    select p_tenant, 'NL0', 'BTW 0%', 'zero'
    where not exists (select 1 from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" is not distinct from 'NL0');
    insert into "better_supabase"."tax_codes" ("tenant_id", "code", "name", "type")
    select p_tenant, 'NLVRIJ', 'Vrijgesteld van BTW', 'exempt'
    where not exists (select 1 from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" is not distinct from 'NLVRIJ');
  end if;
  if p_locale = any (array['nl']) then
    insert into "better_supabase"."tax_rates" ("tenant_id", "tax_code_id", "rate_bps")
    select p_tenant, (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'NL21' limit 1), 2100
    where not exists (select 1 from "better_supabase"."tax_rates" x where x."tenant_id" = p_tenant and x."tax_code_id" is not distinct from (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'NL21' limit 1));
    insert into "better_supabase"."tax_rates" ("tenant_id", "tax_code_id", "rate_bps")
    select p_tenant, (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'NL9' limit 1), 900
    where not exists (select 1 from "better_supabase"."tax_rates" x where x."tenant_id" = p_tenant and x."tax_code_id" is not distinct from (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'NL9' limit 1));
  end if;
  if p_locale = any (array['de']) then
    insert into "better_supabase"."tax_codes" ("tenant_id", "code", "name", "type")
    select p_tenant, 'DE19', 'Umsatzsteuer 19%', 'sales'
    where not exists (select 1 from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" is not distinct from 'DE19');
    insert into "better_supabase"."tax_codes" ("tenant_id", "code", "name", "type")
    select p_tenant, 'DE7', 'Umsatzsteuer 7%', 'sales'
    where not exists (select 1 from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" is not distinct from 'DE7');
    insert into "better_supabase"."tax_codes" ("tenant_id", "code", "name", "type")
    select p_tenant, 'DE0', 'Umsatzsteuer 0%', 'zero'
    where not exists (select 1 from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" is not distinct from 'DE0');
  end if;
  if p_locale = any (array['de']) then
    insert into "better_supabase"."tax_rates" ("tenant_id", "tax_code_id", "rate_bps")
    select p_tenant, (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'DE19' limit 1), 1900
    where not exists (select 1 from "better_supabase"."tax_rates" x where x."tenant_id" = p_tenant and x."tax_code_id" is not distinct from (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'DE19' limit 1));
    insert into "better_supabase"."tax_rates" ("tenant_id", "tax_code_id", "rate_bps")
    select p_tenant, (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'DE7' limit 1), 700
    where not exists (select 1 from "better_supabase"."tax_rates" x where x."tenant_id" = p_tenant and x."tax_code_id" is not distinct from (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'DE7' limit 1));
  end if;
  if p_locale = any (array['fr']) then
    insert into "better_supabase"."tax_codes" ("tenant_id", "code", "name", "type")
    select p_tenant, 'FR20', 'TVA 20%', 'sales'
    where not exists (select 1 from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" is not distinct from 'FR20');
    insert into "better_supabase"."tax_codes" ("tenant_id", "code", "name", "type")
    select p_tenant, 'FR10', 'TVA 10%', 'sales'
    where not exists (select 1 from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" is not distinct from 'FR10');
    insert into "better_supabase"."tax_codes" ("tenant_id", "code", "name", "type")
    select p_tenant, 'FR55', 'TVA 5,5%', 'sales'
    where not exists (select 1 from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" is not distinct from 'FR55');
    insert into "better_supabase"."tax_codes" ("tenant_id", "code", "name", "type")
    select p_tenant, 'FR0', 'TVA 0%', 'zero'
    where not exists (select 1 from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" is not distinct from 'FR0');
  end if;
  if p_locale = any (array['fr']) then
    insert into "better_supabase"."tax_rates" ("tenant_id", "tax_code_id", "rate_bps")
    select p_tenant, (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'FR20' limit 1), 2000
    where not exists (select 1 from "better_supabase"."tax_rates" x where x."tenant_id" = p_tenant and x."tax_code_id" is not distinct from (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'FR20' limit 1));
    insert into "better_supabase"."tax_rates" ("tenant_id", "tax_code_id", "rate_bps")
    select p_tenant, (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'FR10' limit 1), 1000
    where not exists (select 1 from "better_supabase"."tax_rates" x where x."tenant_id" = p_tenant and x."tax_code_id" is not distinct from (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'FR10' limit 1));
    insert into "better_supabase"."tax_rates" ("tenant_id", "tax_code_id", "rate_bps")
    select p_tenant, (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'FR55' limit 1), 550
    where not exists (select 1 from "better_supabase"."tax_rates" x where x."tenant_id" = p_tenant and x."tax_code_id" is not distinct from (select x."id" from "better_supabase"."tax_codes" x where x."tenant_id" = p_tenant and x."code" = 'FR55' limit 1));
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.seed_tenant_defaults (
  p_tenant   uuid,
  p_variants jsonb DEFAULT '{}'::jsonb,
  p_locale   text  DEFAULT 'en'::text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  perform "better_supabase"."seed_attachments_defaults"(p_tenant, p_variants ->> 'attachments', p_locale);
  perform "better_supabase"."seed_inbox_defaults"(p_tenant, p_variants ->> 'inbox', p_locale);
  perform "better_supabase"."seed_calendar_defaults"(p_tenant, p_variants ->> 'calendar', p_locale);
  perform "better_supabase"."seed_cases_defaults"(p_tenant, p_variants ->> 'cases', p_locale);
  perform "better_supabase"."seed_pipelines_defaults"(p_tenant, p_variants ->> 'pipelines', p_locale);
  perform "better_supabase"."seed_leave_defaults"(p_tenant, p_variants ->> 'leave', p_locale);
  perform "better_supabase"."seed_risks_defaults"(p_tenant, p_variants ->> 'risks', p_locale);
  perform "better_supabase"."seed_tax_defaults"(p_tenant, p_variants ->> 'tax', p_locale);
  perform "better_supabase"."seed_accounting_defaults"(p_tenant, p_variants ->> 'accounting', p_locale);
  perform "better_supabase"."seed_document_templates_defaults"(p_tenant, p_variants ->> 'document-templates', p_locale);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.segment_get (
  segment uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'name', x."name", 'description', x."description", 'subjectType', x."subject_type", 'conditions', x."conditions", 'memberCount', x."member_count", 'refreshedAt', x."refreshed_at", 'createdBy', x."created_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at") from "better_supabase"."segments" x
  where x."id" = segment_get.segment and coalesce(better_supabase.can('tenant', x."tenant_id", 'segments.read'), false)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.segments_list (
  tenant       uuid,
  subject_type text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not coalesce(better_supabase.can('tenant', segments_list.tenant, 'segments.read'), false) then
    raise exception 'You need segments.read to list segments' using errcode = '42501', hint = 'SEGMENT_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', x."id", 'organizationId', x."tenant_id", 'name', x."name", 'description', x."description", 'subjectType', x."subject_type", 'conditions', x."conditions", 'memberCount', x."member_count", 'refreshedAt', x."refreshed_at", 'createdBy', x."created_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at") order by x."name")
    from "better_supabase"."segments" x
    where x."tenant_id" = segments_list.tenant
      and (segments_list.subject_type is null or x."subject_type" = segments_list.subject_type)
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.segments_of (
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object('id', x."id", 'name', x."name", 'enteredAt', y."entered_at") order by x."name"), '[]'::jsonb)
  from "better_supabase"."segment_members" y
  join "better_supabase"."segments" x on x."id" = y."segment_id"
  where x."subject_type" = segments_of.subject_type and y."subject_id" = segments_of.subject_id
    and coalesce(better_supabase.can('tenant', x."tenant_id", 'segments.read'), false)
    and (case x."subject_type"
    when 'message' then coalesce(better_supabase.can('tenant', x."tenant_id", 'messages.read'), false)
