    when 'rfq' then exists (select 1 from "better_supabase"."rfqs" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'rfqs.read'), false)
    when 'till' then exists (select 1 from "better_supabase"."tills" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'tills.read'), false)
    when 'order' then exists (select 1 from "better_supabase"."orders" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'orders.read'), false)
    when 'calendar_event' then exists (select 1 from "better_supabase"."calendar_events" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'calendar.read'), false)
    when 'booking' then exists (select 1 from "better_supabase"."bookings" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'bookings.read'), false)
    when 'asset' then exists (select 1 from "better_supabase"."assets" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'assets.read'), false)
    when 'asset_location' then exists (select 1 from "better_supabase"."asset_locations" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'assets.read'), false)
    when 'lease' then exists (select 1 from "better_supabase"."leases" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'leases.read'), false)
    when 'expense_report' then exists (select 1 from "better_supabase"."expense_reports" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'expenses.read'), false)
    when 'expense_line' then exists (select 1 from "better_supabase"."expense_lines" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'expenses.read'), false)
    when 'donation_fund' then exists (select 1 from "better_supabase"."donation_funds" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'donations.read'), false)
    when 'warranty_claim' then exists (select 1 from "better_supabase"."warranty_claims" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'warranty.read'), false)
    when 'work_order' then exists (select 1 from "better_supabase"."work_orders" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'dispatch.read'), false)
    when 'shipment' then exists (select 1 from "better_supabase"."shipments" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'shipments.read'), false)
    when 'contract' then exists (select 1 from "better_supabase"."contracts" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'contracts.read'), false)
    when 'control' then exists (select 1 from "better_supabase"."controls" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'compliance.read'), false)
    when 'compliance_policy' then exists (select 1 from "better_supabase"."compliance_policies" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'compliance.read'), false)
    when 'qualification_type' then exists (select 1 from "better_supabase"."qualification_types" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'qualifications.read'), false)
    when 'risk' then exists (select 1 from "better_supabase"."risks" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'risks.read'), false)
    when 'case' then exists (select 1 from "better_supabase"."cases" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'cases.read'), false)
    when 'inspection' then exists (select 1 from "better_supabase"."inspections" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'inspections.read'), false)
    when 'inspection_program' then exists (select 1 from "better_supabase"."inspection_programs" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'inspections.read'), false)
    when 'inspection_finding' then exists (select 1 from "better_supabase"."inspection_findings" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'inspections.read'), false)
    when 'form' then exists (select 1 from "better_supabase"."forms" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'forms.read'), false)
    when 'meeting' then exists (select 1 from "better_supabase"."meetings" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'meetings.read'), false)
    when 'meeting_decision' then exists (select 1 from "better_supabase"."meeting_decisions" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'meetings.read'), false)
    when 'maintenance_plan' then exists (select 1 from "better_supabase"."maintenance_plans" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'maintenance.read'), false)
    when 'dam_usage_right' then exists (select 1 from "better_supabase"."dam_usage_rights" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'dam.read'), false)
    when 'lims_sample' then exists (select 1 from "better_supabase"."lims_samples" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'lims.read'), false)
    when 'tax_code' then exists (select 1 from "better_supabase"."tax_codes" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'tax.read'), false)
    when 'production_order' then exists (select 1 from "better_supabase"."production_orders" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'manufacturing.read'), false)
    when 'work_center' then exists (select 1 from "better_supabase"."work_centers" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'manufacturing.read'), false)
    when 'bank_account' then exists (select 1 from "better_supabase"."bank_accounts" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'banking.read'), false)
    when 'care_plan' then exists (select 1 from "better_supabase"."care_plans" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'care_plans.read'), false)
    when 'incident' then exists (select 1 from "better_supabase"."incidents" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'incidents.read'), false)
    when 'content_entry' then exists (select 1 from "better_supabase"."content_entries" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'content.read'), false)
    when 'document' then exists (select 1 from "better_supabase"."documents" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'documents.read'), false)
    when 'customer' then exists (select 1 from "public"."customers" s where s."id" = (v_doc."subject_id")::uuid and s."organization_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'customers.read'), false)
    when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id" and (coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'drive.read'), false) and coalesce("better_supabase"."drive_node_readable"(s."id"), false)))
    when 'organization' then exists (select 1 from "public"."organizations" s where s."id" = (v_doc."subject_id")::uuid and s."id" = v_doc."tenant_id")
    when 'application' then exists (select 1 from "better_supabase"."applications" s where s."id" = (v_doc."subject_id")::uuid and s."tenant_id" = v_doc."tenant_id") and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'hiring.read'), false)
    when 'change_request' then exists (select 1 from "public"."change_requests" s where s."id" = (v_doc."subject_id")::uuid and s."organization_id" = v_doc."tenant_id")
    when 'project' then exists (select 1 from "public"."projects" s where s."id" = (v_doc."subject_id")::uuid and s."organization_id" = v_doc."tenant_id")
    when 'task' then exists (select 1 from "public"."tasks" s where s."id" = (v_doc."subject_id")::uuid and s."organization_id" = v_doc."tenant_id")
    else false
  end) and coalesce(better_supabase.can('tenant', v_doc."tenant_id", 'documents.suggest'), false)))) then
    raise exception 'not allowed to suggest changes to this document' using errcode = '42501', hint = 'DOCUMENT_FORBIDDEN';
  end if;
  begin
    v_bytes := decode(suggest_document_change.payload, 'base64');
  exception when others then
    raise exception 'the update must be base64' using errcode = '22023', hint = 'DOCUMENT_UPDATE_INVALID';
  end;
  if v_bytes is null or length(v_bytes) = 0 then
    raise exception 'the update is empty' using errcode = '22023', hint = 'DOCUMENT_UPDATE_INVALID';
  end if;
  if length(v_bytes) > 1048576 then
    raise exception 'an update can be at most 1048576 bytes' using errcode = '54000', hint = 'DOCUMENT_UPDATE_TOO_LARGE';
  end if;
  insert into "better_supabase"."document_suggestions" ("document_id", "tenant_id", "payload", "summary", "status", "created_by")
  values (v_doc."id", v_doc."tenant_id", v_bytes, nullif(trim(suggest_document_change.summary), ''), 'open', auth.uid())
  returning * into v_suggestion;
  perform "better_supabase".emit_event('document.suggested', jsonb_build_object('organizationId', v_doc."tenant_id"::text, 'subjectType', v_doc."subject_type", 'subjectId', v_doc."subject_id", 'id', v_doc."id", 'name', v_doc."name", 'suggestionId', v_suggestion."id", 'authorId', v_suggestion."created_by", 'status', v_suggestion."status"), 'documents/' || v_doc."id"::text, (v_doc."tenant_id")::text, null, 'better-supabase/documents');
  return jsonb_build_object('id', v_suggestion."id", 'documentId', v_suggestion."document_id", 'summary', v_suggestion."summary", 'status', v_suggestion."status", 'createdBy', v_suggestion."created_by", 'createdAt', v_suggestion."created_at", 'decidedBy', v_suggestion."decided_by", 'decidedAt', v_suggestion."decided_at", 'note', v_suggestion."note", 'update', replace(encode(v_suggestion."payload", 'base64'), E'\n', ''));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.suggest_inbox_draft (
  conversation uuid,
  input        jsonb,
  metadata     jsonb DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_conv "better_supabase"."inbox_conversations"%rowtype;
  v_row "better_supabase"."inbox_drafts"%rowtype;
  v_input jsonb := coalesce(input, '{}'::jsonb) - 'files' - 'external_id' - 'author_type' - 'delivered_by_caller';
  v_metadata jsonb := suggest_inbox_draft.metadata;
begin
  select * into v_conv from "better_supabase"."inbox_conversations" where "id" = suggest_inbox_draft.conversation;
  if not found then
    raise exception 'conversation not found' using errcode = 'P0002', hint = 'CONVERSATION_NOT_FOUND';
  end if;
  if length(coalesce(v_input ->> 'body', '')) > 20000 then
    raise exception 'a message is at most 20000 characters' using errcode = '22023', hint = 'INBOX_MESSAGE_TOO_LONG';
  end if;
  if v_metadata is not null and jsonb_typeof(v_metadata) <> 'object' then
    raise exception 'metadata must be an object' using errcode = '22023', hint = 'INBOX_DRAFT_METADATA';
  end if;
  insert into "better_supabase"."inbox_drafts" ("tenant_id", "conversation_id", "author_id", "source", "input", "metadata")
  values (v_conv."tenant_id", v_conv."id", null, 'ai', v_input, coalesce(v_metadata, '{}'::jsonb))
  returning * into v_row;
  return to_jsonb(v_row);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.suggest_putaway (
  tenant uuid,
  input  jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_location uuid;
  v_variant uuid;
  v_quantity numeric;
begin
  if not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (suggest_putaway.tenant is not null and coalesce(better_supabase.can('tenant', suggest_putaway.tenant, 'warehouse.read'), false))) or (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (suggest_putaway.tenant is not null and coalesce(better_supabase.can('tenant', suggest_putaway.tenant, 'warehouse.pick'), false)))) then
    raise exception 'not allowed to read putaway suggestions' using errcode = '42501', hint = 'WAREHOUSE_FORBIDDEN';
  end if;
  if jsonb_typeof(suggest_putaway.input) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  begin
    v_location := (suggest_putaway.input ->> 'locationId')::uuid;
    v_variant := (suggest_putaway.input ->> 'variantId')::uuid;
    v_quantity := (suggest_putaway.input ->> 'quantity')::numeric;
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'locationId and variantId are uuids and quantity is a number' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end;
  if v_quantity is null or v_quantity <= 0 then
    raise exception 'quantity is more than 0' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  if not exists (select 1 from "better_supabase"."inventory_locations" x where x."id" = v_location and x."tenant_id" = suggest_putaway.tenant) then
    raise exception 'no such location in this organization' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  if not exists (select 1 from "better_supabase"."product_variants" x where x."id" = v_variant and x."tenant_id" = suggest_putaway.tenant) then
    raise exception 'no such variant in this organization' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  return "better_supabase"."putaway_plan"(suggest_putaway.tenant, v_location, v_variant, v_quantity);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.suggest_receipt_putaway (
  receipt_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_receipt "better_supabase"."inventory_receipts";
  v_out jsonb := '[]'::jsonb;
  rec record;
begin
  select * into v_receipt from "better_supabase"."inventory_receipts" x where x."id" = suggest_receipt_putaway.receipt_id;
  if not found then
    raise exception 'no such goods receipt' using errcode = 'P0002', hint = 'WAREHOUSE_RECEIPT_NOT_FOUND';
  end if;
  if not ((coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_receipt."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_receipt."tenant_id", 'warehouse.read'), false))) or (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (v_receipt."tenant_id" is not null and coalesce(better_supabase.can('tenant', v_receipt."tenant_id", 'warehouse.pick'), false)))) then
    raise exception 'not allowed to read putaway suggestions' using errcode = '42501', hint = 'WAREHOUSE_FORBIDDEN';
  end if;
  if v_receipt."location_id" is null then
    raise exception 'the receipt has no location' using errcode = '55000', hint = 'WAREHOUSE_STATE';
  end if;
  for rec in
    select x."variant_id" as variant, sum(x."quantity") as quantity
    from "better_supabase"."inventory_receipt_lines" x
    where x."receipt_id" = v_receipt."id" and x."quantity" > 0
    group by x."variant_id"
    order by x."variant_id"
  loop
    v_out := v_out || "better_supabase"."putaway_plan"(v_receipt."tenant_id", v_receipt."location_id", rec.variant, rec.quantity);
  end loop;
  return v_out;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.suggest_slotting (
  tenant uuid,
  input  jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_location uuid;
  v_days integer;
  v_limit integer;
  v_taken uuid[] := '{}';
  v_bin uuid;
  v_rank integer;
  v_current_rank integer;
  v_action text;
  v_suggested uuid;
  v_out jsonb := '[]'::jsonb;
  rec record;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (suggest_slotting.tenant is not null and coalesce(better_supabase.can('tenant', suggest_slotting.tenant, 'warehouse.read'), false))) then
    raise exception 'not allowed to read slotting suggestions' using errcode = '42501', hint = 'WAREHOUSE_FORBIDDEN';
  end if;
  if jsonb_typeof(suggest_slotting.input) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  begin
    v_location := (suggest_slotting.input ->> 'locationId')::uuid;
    v_days := coalesce((suggest_slotting.input ->> 'days')::integer, 30);
    v_limit := coalesce((suggest_slotting.input ->> 'limit')::integer, 50);
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'locationId is a uuid, days and limit are integers' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end;
  if v_days not between 1 and 365 or v_limit not between 1 and 500 then
    raise exception 'days is between 1 and 365 and limit between 1 and 500' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  if not exists (select 1 from "better_supabase"."inventory_locations" x where x."id" = v_location and x."tenant_id" = suggest_slotting.tenant) then
    raise exception 'no such location in this organization' using errcode = '22023', hint = 'WAREHOUSE_INVALID';
  end if;
  for rec in
    with moves as (
      select y."variant_id" as variant, sum(y."picked") as velocity, count(*) as picks
      from "better_supabase"."pick_lines" y join "better_supabase"."pick_lists" x on x."id" = y."pick_list_id"
      where x."tenant_id" = suggest_slotting.tenant and x."location_id" = v_location
        and y."picked" > 0 and y."picked_at" >= now() - make_interval(days => v_days)
      group by y."variant_id"
      order by sum(y."picked") desc, y."variant_id"
      limit v_limit
    )
    select m.variant, m.velocity, m.picks,
      coalesce((select sum(c."on_hand") from "better_supabase"."stock_buckets" c
        where c."tenant_id" = suggest_slotting.tenant and c."location_id" = v_location
          and c."variant_id" = m.variant and c."bin_id" is not null), 0) as on_hand,
      (select c."bin_id" from "better_supabase"."stock_buckets" c
        where c."tenant_id" = suggest_slotting.tenant and c."location_id" = v_location
          and c."variant_id" = m.variant and c."bin_id" is not null
        order by c."on_hand" desc, c."bin_id" limit 1) as current_bin,
      coalesce((select sz."size" from "better_supabase"."variant_sizes" sz where sz."variant_id" = m.variant), 1) as size
    from moves m
    order by m.velocity desc, m.variant
  loop
    v_current_rank := (select sl."walk_rank" from "better_supabase"."bin_slots" sl where sl."bin_id" = rec.current_bin);
    v_bin := null;
    v_rank := null;
    select x."id", sl."walk_rank" into v_bin, v_rank
    from "better_supabase"."stock_bins" x join "better_supabase"."bin_slots" sl on sl."bin_id" = x."id"
    where x."tenant_id" = suggest_slotting.tenant and x."location_id" = v_location
      and x."active" and not x."hold" and not (x."id" = any(v_taken))
      and (sl."capacity" is null or sl."capacity" >= rec.on_hand * rec.size)
    order by sl."walk_rank", x."code"
    limit 1;
    if v_bin is null or (v_current_rank is not null and v_current_rank <= v_rank) or v_bin = rec.current_bin then
      v_action := 'keep';
      v_suggested := rec.current_bin;
    else
      v_action := 'move';
      v_suggested := v_bin;
    end if;
    if v_suggested is not null then
      v_taken := v_taken || v_suggested;
    end if;
    v_out := v_out || jsonb_build_object('variantId', rec.variant, 'velocity', rec.velocity::text, 'picks', rec.picks,
      'onHand', rec.on_hand::text, 'currentBinId', rec.current_bin, 'suggestedBinId', v_suggested, 'action', v_action);
  end loop;
  return v_out;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.supplier_item_from_row (
  tenant   uuid,
  supplier uuid,
  source   jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  v_columns jsonb;
  v_defaults jsonb;
  v_code text;
  v_description text;
  v_unit text;
  v_currency text;
  v_price text;
  v_amount bigint;
  v_scale integer;
  v_keywords text;
  v_source jsonb;
begin
  select x."columns", x."defaults" into v_columns, v_defaults
  from "better_supabase"."supplier_item_mappings" x where x."tenant_id" = supplier_item_from_row.tenant and x."supplier_id" = supplier_item_from_row.supplier;
  if v_columns is null then
    raise exception 'this supplier has no column mapping' using errcode = 'P0002', hint = 'CATALOG_SUPPLIER_MAPPING_NOT_FOUND';
  end if;
  if jsonb_typeof(supplier_item_from_row.source) is distinct from 'object' then
    raise exception 'a row is an object of source columns' using errcode = '22023', hint = 'CATALOG_SUPPLIER_ROW_INVALID';
  end if;
  v_code := nullif(btrim(supplier_item_from_row.source ->> (v_columns ->> 'code')), '');
  v_description := nullif(btrim(supplier_item_from_row.source ->> (v_columns ->> 'description')), '');
  v_unit := coalesce(nullif(btrim(supplier_item_from_row.source ->> (v_columns ->> 'unit')), ''), v_defaults ->> 'unit');
  v_currency := upper(coalesce(nullif(btrim(supplier_item_from_row.source ->> (v_columns ->> 'currency')), ''), v_defaults ->> 'currency'));
  v_price := nullif(btrim(supplier_item_from_row.source ->> (v_columns ->> 'price')), '');
  if v_currency is not null and "better_supabase"."currency_minor_units"(v_currency) is null then
    raise exception 'not an ISO 4217 currency code' using errcode = '22023', hint = 'CATALOG_CURRENCY_INVALID';
  end if;
  if v_price is not null then
    v_price := regexp_replace(v_price, '[^0-9.,-]', '', 'g');
    if position(',' in v_price) > 0 and position('.' in v_price) > 0 then
      -- The separator that comes last is the decimal one.
      if length(v_price) - length(regexp_replace(v_price, '^.*,', '')) > length(v_price) - length(regexp_replace(v_price, '^.*\.', '')) then
        v_price := replace(replace(v_price, '.', ''), ',', '.');
      else
        v_price := replace(v_price, ',', '');
      end if;
    else
      v_price := replace(v_price, ',', '.');
    end if;
    v_scale := coalesce("better_supabase"."currency_minor_units"(v_currency), 2);
    begin
      v_amount := round(v_price::numeric * power(10::numeric, v_scale))::bigint;
    exception when others then
      raise exception 'the price is not a number' using errcode = '22023', hint = 'CATALOG_SUPPLIER_PRICE_INVALID';
    end;
    if v_amount < 0 then
      raise exception 'the price can''t be negative' using errcode = '22023', hint = 'CATALOG_SUPPLIER_PRICE_INVALID';
    end if;
  end if;
  v_source := case jsonb_typeof(v_columns -> 'keywords') when 'array' then v_columns -> 'keywords' when 'string' then jsonb_build_array(v_columns -> 'keywords') else '[]'::jsonb end;
  select nullif(string_agg(btrim(supplier_item_from_row.source ->> (a.value #>> '{}')), ' ') filter (where nullif(btrim(supplier_item_from_row.source ->> (a.value #>> '{}')), '') is not null), '')
  into v_keywords from jsonb_array_elements(v_source) a;
  return jsonb_strip_nulls(jsonb_build_object('code', v_code, 'description', v_description, 'price', v_amount, 'currency', v_currency, 'unit', v_unit, 'keywords', v_keywords));
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.supplier_item_mapping (
  tenant   uuid,
  supplier uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object('supplierId', x."supplier_id", 'columns', x."columns", 'defaults', x."defaults")
  from "better_supabase"."supplier_item_mappings" x where x."tenant_id" = $1 and x."supplier_id" = $2
$function$;

CREATE OR REPLACE FUNCTION better_supabase.supplier_item_updated_at (
  subject_id text
)
  RETURNS timestamp WITH time zone
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select x."updated_at" from "better_supabase"."supplier_items" x where x."id" = $1::uuid
$function$;

CREATE OR REPLACE FUNCTION better_supabase.supplier_status_from_qualifications (
  party uuid
)
  RETURNS text
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_tenant uuid;
  v_gaps jsonb;
begin
  select x."tenant_id" into v_tenant from "better_supabase"."companies" x
  where x."id" = supplier_status_from_qualifications.party and x."merged_into" is null;
  if v_tenant is null then
    raise exception 'company not found' using errcode = 'P0002', hint = 'PARTY_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_tenant, 'contacts.read'), false)) then
    raise exception 'not allowed to read companies and people' using errcode = '42501', hint = 'PARTY_FORBIDDEN';
  end if;
  v_gaps := "better_supabase"."qualification_gaps"(v_tenant, 'company', jsonb_build_object('holderId', supplier_status_from_qualifications.party::text));
  return case when exists (
    select 1 from jsonb_array_elements(v_gaps) g where g ->> 'status' in ('missing', 'expired')
  ) then 'conditional' else 'approved' end;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.suppress_notification_address (
  address           text,
  reason            text,
  channel           text  DEFAULT 'email'::text,
  provider          text  DEFAULT NULL::text,
  provider_event_id text  DEFAULT NULL::text,
  detail            jsonb DEFAULT '{}'::jsonb
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_address text := lower(btrim(suppress_notification_address.address));
begin
  if v_address is null or v_address = '' then
    raise exception 'address is required' using errcode = '22023', hint = 'NOTIFICATION_SUPPRESSION_ADDRESS';
  end if;
  if suppress_notification_address.reason is null or suppress_notification_address.reason not in ('bounce', 'complaint', 'manual') then
    raise exception 'reason must be bounce, complaint or manual' using errcode = '22023', hint = 'NOTIFICATION_SUPPRESSION_REASON';
  end if;
  insert into "better_supabase"."notification_suppressions" ("channel", "address", "user_id", "reason", "provider", "provider_event_id", "detail")
  values (
    coalesce(suppress_notification_address.channel, 'email'),
    v_address,
    (select u.id from auth.users u where lower(u.email) = v_address order by u.created_at limit 1),
    suppress_notification_address.reason,
    suppress_notification_address.provider,
    suppress_notification_address.provider_event_id,
    coalesce(suppress_notification_address.detail, '{}')
  )
  on conflict ("channel", "address") do nothing;
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.switch_ai_branch (
  chat       uuid,
  message_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_chat "better_supabase"."ai_chats";
  v_leaf text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_chat from "better_supabase"."ai_chats" x where x."id" = switch_ai_branch.chat for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(v_chat."owner_id" = (select auth.uid()), false) or (v_chat."visibility" <> 'private' and exists (select 1 from "better_supabase"."ai_chat_participants" pa where pa."chat_id" = v_chat."id" and pa."role"::text in ('editor') and ((((pa."kind"::text = 'user' and pa."user_id" = (select auth.uid())) or (pa."kind"::text = 'team' and exists (select 1 from "better_supabase"."team_members" tm where tm."team_id"::text = pa."team_id"::text and tm."user_id" = (select auth.uid())))) and (v_chat."tenant_id" is null or v_chat."tenant_id" in (select better_supabase.member_organization_ids()))) or (pa."kind"::text = 'customer' and pa."customer_id" = (select auth.uid()) and ((v_chat."tenant_id")::text, ('ai-chat')::text, (v_chat."id"::text)::text) in (select g.tenant, g.subject_type, g.subject_id from better_supabase.portal_subjects('read') g)))))) then
    raise exception 'No chat %', switch_ai_branch.chat using errcode = 'P0002', hint = 'AI_CHAT_NOT_FOUND';
  end if;
  if not exists (select 1 from "better_supabase"."ai_messages" x where x."chat_id" = switch_ai_branch.chat and x."id" = switch_ai_branch.message_id) then
    raise exception 'No message %', switch_ai_branch.message_id using errcode = 'P0002', hint = 'AI_MESSAGE_NOT_FOUND';
  end if;
  with recursive down as (
    select switch_ai_branch.message_id as id, 0 as depth
    union all
    select (
      select c."id" from "better_supabase"."ai_messages" c
      where c."chat_id" = switch_ai_branch.chat and c."parent_id" = down.id
      order by c."seq" desc limit 1
    ), down.depth + 1
    from down
    where down.id is not null and down.depth < 10000
  )
  select d.id into v_leaf from down d where d.id is not null order by d.depth desc limit 1;
  update "better_supabase"."ai_chats" x set "current_leaf_id" = v_leaf, "updated_at" = now() where x."id" = switch_ai_branch.chat;
  perform "better_supabase"."ai_chat_notify"(switch_ai_branch.chat, null, 'leaf.changed', jsonb_build_object('leafId', v_leaf), false);
  return jsonb_build_object('leaf_id', v_leaf);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.switch_organization (
  organization uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  me uuid := auth.uid();
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if me is null or not exists (select 1 from "public"."memberships" m where m."organization_id" = organization and m."user_id" = me) then
    raise exception 'Not a member' using errcode = 'P0002', hint = 'ORGANIZATION_NOT_MEMBER';
  end if;
  if not (exists (select 1 from "public"."organizations" o where o."id" = organization) and not better_supabase.tenant_disabled(organization)) then
    raise exception 'The organization is unavailable' using errcode = '42501', hint = 'ORGANIZATION_DISABLED';
  end if;
  update auth.users
  set raw_app_meta_data = coalesce(raw_app_meta_data, '{}') || jsonb_build_object('tenant_id', organization::text)
  where id = me;
  update "public"."memberships" set "last_used_at" = now() where "organization_id" = organization and "user_id" = me;
  perform "better_supabase".emit_event('organization.switched', jsonb_build_object('organizationId', organization::text, 'userId', me), 'organizations/' || organization::text, (organization)::text, null, 'better-supabase/organizations');
  return jsonb_build_object('organization_id', organization, 'refresh', true);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.sync_care_alerts (
  tenant       uuid,
  subject_type text,
  subject_id   text,
  source       text,
  alerts       jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_item jsonb;
  v_row "better_supabase"."care_alerts";
  v_seen text[] := '{}';
  v_kind text;
  v_severity text;
  v_message text;
  v_fingerprint text;
  v_rule uuid;
  v_orders uuid[];
  v_details jsonb;
begin
  if jsonb_typeof(sync_care_alerts.alerts) is distinct from 'array' then
    raise exception 'alerts is an array' using errcode = '22023', hint = 'CARE_ALERT_INVALID';
  end if;
  for v_item in select e.value from jsonb_array_elements(sync_care_alerts.alerts) e loop
    v_kind := coalesce(nullif(v_item ->> 'kind', ''), 'other');
    v_severity := coalesce(nullif(v_item ->> 'severity', ''), 'warning');
    v_message := nullif(trim(v_item ->> 'message'), '');
    if v_kind not in ('dose_range', 'duplicate_therapy', 'interaction', 'allergy', 'other') then
      raise exception 'kind is dose_range, duplicate_therapy, interaction, allergy or other' using errcode = '22023', hint = 'CARE_ALERT_INVALID';
    end if;
    if v_severity not in ('info', 'warning', 'critical') then
      raise exception 'severity is info, warning or critical' using errcode = '22023', hint = 'CARE_ALERT_INVALID';
    end if;
    if v_message is null or length(v_message) > 1000 then
      raise exception 'an alert needs a message of up to 1000 characters' using errcode = '22023', hint = 'CARE_ALERT_INVALID';
    end if;
    v_fingerprint := coalesce(nullif(trim(v_item ->> 'fingerprint'), ''), md5(v_kind || '|' || v_message));
    if length(v_fingerprint) > 200 then
      raise exception 'a fingerprint is up to 200 characters' using errcode = '22023', hint = 'CARE_ALERT_INVALID';
    end if;
    v_details := case when jsonb_typeof(v_item -> 'details') = 'object' then v_item -> 'details' else null end;
    begin
      v_rule := nullif(v_item ->> 'ruleId', '')::uuid;
      v_orders := coalesce((select array_agg(e.value::uuid) from jsonb_array_elements_text(case when jsonb_typeof(v_item -> 'orderIds') = 'array' then v_item -> 'orderIds' else '[]'::jsonb end) e), '{}');
    exception when invalid_text_representation then
      raise exception 'ruleId and orderIds are uuids' using errcode = '22023', hint = 'CARE_ALERT_INVALID';
    end;
    select * into v_row from "better_supabase"."care_alerts" x
    where x."tenant_id" = sync_care_alerts.tenant and x."subject_type" = sync_care_alerts.subject_type and x."subject_id" = sync_care_alerts.subject_id
      and x."fingerprint" = v_fingerprint and x."status" <> 'resolved'
    for update;
    if found then
      update "better_supabase"."care_alerts" x set "kind" = v_kind, "severity" = v_severity, "message" = v_message, "rule_id" = v_rule,
        "order_ids" = v_orders, "details" = v_details, "updated_at" = now()
      where x."id" = v_row."id";
    else
      insert into "better_supabase"."care_alerts" ("tenant_id", "subject_type", "subject_id", "kind", "severity", "source", "rule_id", "order_ids", "message", "details", "fingerprint")
      values (sync_care_alerts.tenant, sync_care_alerts.subject_type, sync_care_alerts.subject_id, v_kind, v_severity, sync_care_alerts.source, v_rule, v_orders, v_message, v_details, v_fingerprint)
      returning * into v_row;
      perform "better_supabase".emit_event('care_alert.raised', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'kind', v_row."kind", 'severity', v_row."severity", 'source', v_row."source", 'status', v_row."status"), 'care-alerts/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/clinical-decision-support');
  perform better_supabase.audit_event(
    event_type => 'care_alert.raised',
    category => 'data',
    target_type => 'care_alert',
    record_id => v_row."id"::text,
    target_label => v_row."kind",
    summary => 'care alert raised',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'kind', v_row."kind", 'severity', v_row."severity", 'source', v_row."source", 'status', v_row."status")
  );
    end if;
    v_seen := array_append(v_seen, v_fingerprint);
  end loop;
  for v_row in
    update "better_supabase"."care_alerts" x set "status" = 'resolved', "updated_at" = now()
    where x."tenant_id" = sync_care_alerts.tenant and x."subject_type" = sync_care_alerts.subject_type and x."subject_id" = sync_care_alerts.subject_id
      and x."source" = sync_care_alerts.source and x."status" <> 'resolved' and not (x."fingerprint" = any(v_seen))
    returning x.*
  loop
    perform "better_supabase".emit_event('care_alert.resolved', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'kind', v_row."kind", 'severity', v_row."severity", 'source', v_row."source", 'status', v_row."status"), 'care-alerts/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/clinical-decision-support');
  perform better_supabase.audit_event(
    event_type => 'care_alert.resolved',
    category => 'data',
    target_type => 'care_alert',
    record_id => v_row."id"::text,
    target_label => v_row."kind",
    summary => 'care alert resolved',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'subjectType', v_row."subject_type", 'subjectId', v_row."subject_id", 'kind', v_row."kind", 'severity', v_row."severity", 'source', v_row."source", 'status', v_row."status")
  );
  end loop;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', y."id", 'organizationId', y."tenant_id", 'subjectType', y."subject_type", 'subjectId', y."subject_id", 'kind', y."kind", 'severity', y."severity", 'source', y."source", 'ruleId', y."rule_id", 'orderIds', to_jsonb(y."order_ids"), 'message', y."message", 'details', y."details", 'fingerprint', y."fingerprint", 'status', y."status", 'decidedBy', y."decided_by", 'decidedAt', y."decided_at", 'decisionReason', y."decision_reason", 'createdAt', y."created_at", 'updatedAt', y."updated_at") order by case y."severity" when 'critical' then 0 when 'warning' then 1 else 2 end, y."created_at", y."id")
    from "better_supabase"."care_alerts" y
    where y."tenant_id" = sync_care_alerts.tenant and y."subject_type" = sync_care_alerts.subject_type and y."subject_id" = sync_care_alerts.subject_id and y."status" <> 'resolved'
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.sync_number_sequences (
  p_tenant uuid DEFAULT NULL::uuid,
  p_entity text DEFAULT NULL::text,
  p_scope  text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_rows integer := 0;
  v_count integer;
  v_bad jsonb := '[]'::jsonb;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if p_entity is not null and not (false) then
    raise exception 'no numbered table for this sequence' using errcode = '22023', hint = 'NUMBER_ENTITY_UNKNOWN';
  end if;

  if better_supabase.import_run() is not null and jsonb_array_length(v_bad) > 0 then
    update "better_supabase"."import_runs" r
    set "errors" = r."errors" || (
      select jsonb_agg(jsonb_build_object('entity', b ->> 'entity', 'key', b ->> 'number', 'code', 'NUMBER_FORMAT_MISMATCH', 'severity', 'warning', 'message', 'the number does not match the current format of ' || (b ->> 'entity')))
      from jsonb_array_elements(v_bad) b
    )
    where r."id" = better_supabase.import_run();
  end if;
  return jsonb_build_object('synced', v_rows, 'mismatched', v_bad);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.sync_profile (
  user_id uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  u auth.users;
  meta jsonb;
  created boolean := false;
  attempt integer := 0;
begin
  select * into u from auth.users where id = user_id;
  if not found then
    return false;
  end if;
  meta := coalesce(u.raw_user_meta_data, '{}');
  if not exists (select 1 from "better_supabase"."profiles" p where p."id" = user_id) then
    loop
      begin
        insert into "better_supabase"."profiles" ("id", "full_name", "first_name", "last_name", "avatar_url", "email", "username")
        values (user_id, coalesce(nullif(btrim(coalesce(meta ->> 'full_name', meta ->> 'name')), ''), nullif(concat_ws(' ', nullif(btrim(coalesce(meta ->> 'first_name', meta ->> 'given_name')), ''), nullif(btrim(coalesce(meta ->> 'last_name', meta ->> 'family_name')), '')), '')), coalesce(nullif(btrim(coalesce(meta ->> 'first_name', meta ->> 'given_name')), ''), nullif(split_part(nullif(btrim(coalesce(meta ->> 'full_name', meta ->> 'name')), ''), ' ', 1), '')), coalesce(nullif(btrim(coalesce(meta ->> 'last_name', meta ->> 'family_name')), ''), nullif(btrim(substr(nullif(btrim(coalesce(meta ->> 'full_name', meta ->> 'name')), ''), length(split_part(nullif(btrim(coalesce(meta ->> 'full_name', meta ->> 'name')), ''), ' ', 1)) + 1)), '')), nullif(btrim(coalesce(meta ->> 'avatar_url', meta ->> 'picture')), ''), lower(u.email), "better_supabase"."allocate_username"(coalesce(nullif(btrim(coalesce(meta ->> 'user_name', meta ->> 'preferred_username', meta ->> 'username')), ''), split_part(u.email, '@', 1)), user_id));
        created := true;
        exit;
      exception when unique_violation then
        -- Another sign-up took the username between allocation and insert.
        attempt := attempt + 1;
        if attempt >= 3 or exists (select 1 from "better_supabase"."profiles" p where p."id" = user_id) then
          exit;
        end if;
      end;
    end loop;
  end if;
  if created then
    declare
      v_hook regprocedure := to_regprocedure('"public"."after_profile_sync"(uuid)');
    begin
      if v_hook is not null then
        execute format('select %s($1::uuid)', v_hook::oid::regproc)
          using user_id;
      end if;
    end;
  end if;
  return created;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.sync_rule_fields (
  subject_type text,
  fields       jsonb
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_count integer;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'Only the service role syncs rule fields' using errcode = '42501', hint = 'AUTOMATION_FORBIDDEN';
  end if;
  if jsonb_typeof(fields) is distinct from 'array' then
    raise exception 'fields must be an array' using errcode = '22023', hint = 'AUTOMATION_FIELDS_INVALID';
  end if;
  insert into "better_supabase"."automation_fields" ("subject_type", "field_id", "label", "description", "type", "path", "column_type", "nullable", "options", "operators", "position")
  select sync_rule_fields.subject_type, x.value ->> 'id', coalesce(x.value ->> 'label', x.value ->> 'id'), x.value ->> 'description',
    x.value ->> 'type', coalesce(x.value ->> 'column', x.value ->> 'id'), coalesce(x.value ->> 'columnType', 'text'),
    coalesce((x.value ->> 'nullable')::boolean, true), x.value -> 'options', x.value -> 'operators', x.n::integer
  from jsonb_array_elements(fields) with ordinality x(value, n)
  on conflict ("subject_type", "field_id") do update set
    "label" = excluded."label",
    "description" = excluded."description",
    "type" = excluded."type",
    "path" = excluded."path",
    "column_type" = excluded."column_type",
    "nullable" = excluded."nullable",
    "options" = excluded."options",
    "operators" = excluded."operators",
    "position" = excluded."position",
    "updated_at" = now();
  delete from "better_supabase"."automation_fields" x
  where x."subject_type" = sync_rule_fields.subject_type
    and not exists (select 1 from jsonb_array_elements(fields) y where y.value ->> 'id' = x."field_id");
  select count(*) into v_count from "better_supabase"."automation_fields" x where x."subject_type" = sync_rule_fields.subject_type;
  return v_count;
exception when check_violation or not_null_violation then
  raise exception 'A rule field has an invalid id, type, column or column type' using errcode = '22023', hint = 'AUTOMATION_FIELDS_INVALID';
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.sync_templates (
  starters jsonb
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_starter jsonb;
  v_row "better_supabase"."templates"%rowtype;
  v_hash text;
  v_version "better_supabase"."template_versions"%rowtype;
  v_count integer := 0;
begin
  if jsonb_typeof(sync_templates.starters) <> 'array' then
    raise exception 'starters must be an array' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  for v_starter in select value from jsonb_array_elements(sync_templates.starters) loop
    if coalesce(v_starter ->> 'key', '') !~ '^[a-z0-9][a-z0-9_.-]{0,99}$' or not (v_starter ? 'body') then
      raise exception 'Each starter needs a key and a body' using errcode = '22023', hint = 'TEMPLATE_INVALID';
    end if;
    select * into v_row from "better_supabase"."templates" x where x."tenant_id" is null and x."brand" is not distinct from nullif(v_starter ->> 'brand', '') and x."key" = v_starter ->> 'key' for update;
    if not found then
      insert into "better_supabase"."templates" ("tenant_id", "scope", "brand", "key", "type", "name", "language", "settings")
      values (null, case when nullif(v_starter ->> 'brand', '') is null then 'system' else 'brand' end, nullif(v_starter ->> 'brand', ''), v_starter ->> 'key', v_starter ->> 'type', v_starter ->> 'name',
        coalesce(v_starter ->> 'language', 'en'), coalesce(v_starter -> 'settings', '{}'::jsonb))
      returning * into v_row;
    else
      update "better_supabase"."templates" x set
        "type" = coalesce(v_starter ->> 'type', x."type"),
        "name" = coalesce(v_starter ->> 'name', x."name"),
        "language" = coalesce(v_starter ->> 'language', x."language"),
        "settings" = coalesce(v_starter -> 'settings', x."settings"),
        "updated_at" = now()
      where x."id" = v_row."id"
      returning * into v_row;
    end if;
    v_hash := encode(extensions.digest((v_starter -> 'body')::text, 'sha256'), 'hex');
    if v_hash is distinct from (select y."hash" from "better_supabase"."template_versions" y
        where y."template_id" = v_row."id" and y."published_at" is not null
        order by y."version" desc limit 1) then
      delete from "better_supabase"."template_versions" y where y."template_id" = v_row."id" and y."published_at" is null;
      insert into "better_supabase"."template_versions" ("template_id", "version", "body", "hash", "published_at")
      values (
        v_row."id",
        coalesce((select max(y."version") from "better_supabase"."template_versions" y where y."template_id" = v_row."id"), 0) + 1,
        v_starter -> 'body',
        v_hash,
        now()
      )
      returning * into v_version;
      v_count := v_count + 1;
      perform "better_supabase".emit_event('template.published', jsonb_build_object('organizationId', null, 'id', v_row."id", 'versionId', v_version."id", 'version', v_version."version", 'type', v_row."type"), 'templates/' || v_row."id"::text, null, null, 'better-supabase/templates');
    end if;
  end loop;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.sync_workflow_node_kinds (
  kinds jsonb
)
  RETURNS integer
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  if jsonb_typeof(coalesce(kinds, '{}'::jsonb)) <> 'object' then
    raise exception 'kinds is an object keyed by kind' using errcode = '42501', hint = 'WORKFLOW_NODE_KINDS';
  end if;
  insert into "better_supabase"."workflow_node_kinds" ("kind", "title", "description", "branches", "config_schema")
  select e.key, coalesce(e.value ->> 'title', e.key), e.value ->> 'description',
    coalesce((e.value ->> 'branches')::boolean, false), coalesce(e.value -> 'configSchema', '{}'::jsonb)
  from jsonb_each(coalesce(kinds, '{}'::jsonb)) e
  on conflict ("kind") do update set
    "title" = excluded."title",
    "description" = excluded."description",
    "branches" = excluded."branches",
    "config_schema" = excluded."config_schema",
    "updated_at" = now();
  delete from "better_supabase"."workflow_node_kinds" x
  where not exists (
    select 1 from jsonb_each(coalesce(kinds, '{}'::jsonb)) e where e.key = x."kind"
  );
  select count(*) into v_count from "better_supabase"."workflow_node_kinds";
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.sync_workflow_steps (
  steps jsonb
)
  RETURNS integer
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_count integer;
begin
  insert into "better_supabase"."workflow_step_templates" ("name", "title", "description", "input_schema", "output_schema", "credential_kind", "operation")
  select e.key, coalesce(e.value ->> 'title', e.key), e.value ->> 'description',
    coalesce(e.value -> 'inputSchema', '{}'::jsonb), coalesce(e.value -> 'outputSchema', '{}'::jsonb), e.value ->> 'credentialKind',
    nullif(e.value ->> 'operation', '')
  from jsonb_each(coalesce(steps, '{}'::jsonb)) e
  on conflict ("name") do update set
    "title" = excluded."title",
    "description" = excluded."description",
    "input_schema" = excluded."input_schema",
    "output_schema" = excluded."output_schema",
    "credential_kind" = excluded."credential_kind",
    "operation" = excluded."operation",
    "updated_at" = now();
  delete from "better_supabase"."workflow_step_templates" x
  where not exists (
    select 1 from jsonb_each(coalesce(steps, '{}'::jsonb)) e where e.key = x."name"
  );
  select count(*) into v_count from "better_supabase"."workflow_step_templates";
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.tag (
  tenant       uuid,
  subject_type text,
  subject_id   text,
  tag_id       uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_kind text;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', tag.tenant, 'tags.apply'), false) or coalesce(better_supabase.can('tenant', tag.tenant, 'tags.manage'), false)) then
    raise exception 'not allowed to apply tags' using errcode = '42501', hint = 'TAG_FORBIDDEN';
  end if;
  if not ((case when tag.subject_type = 'drive_node' then coalesce(case when tag.subject_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then "better_supabase"."drive_can"((tag.subject_id)::uuid, 'editor') end, false) else case tag.subject_type
    when 'message' then exists (select 1 from "better_supabase"."messages" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'messages.read'), false)
    when 'conversation' then exists (select 1 from "better_supabase"."conversations" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'messages.read'), false)
    when 'channel' then exists (select 1 from "better_supabase"."channels" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'messages.read'), false)
    when 'company' then exists (select 1 from "better_supabase"."companies" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'contacts.read'), false)
    when 'person' then exists (select 1 from "better_supabase"."people" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'contacts.read'), false)
    when 'deal' then exists (select 1 from "better_supabase"."deals" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'deals.read'), false)
    when 'course' then exists (select 1 from "better_supabase"."courses" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'courses.read'), false)
    when 'post' then exists (select 1 from "better_supabase"."posts" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'posts.read'), false)
    when 'activity' then exists (select 1 from "better_supabase"."activities" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'activities.read'), false)
    when 'quote' then exists (select 1 from "better_supabase"."quotes" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'quotes.read'), false)
    when 'work_item' then exists (select 1 from "better_supabase"."work_items" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'tasks.read'), false)
    when 'employee' then exists (select 1 from "better_supabase"."employees" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'employees.read'), false)
    when 'ledger_account' then exists (select 1 from "better_supabase"."ledger_accounts" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'ledger.read'), false)
    when 'invoice' then exists (select 1 from "better_supabase"."invoices" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'invoices.read'), false)
    when 'product' then exists (select 1 from "better_supabase"."products" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'catalog.read'), false)
    when 'product_variant' then exists (select 1 from "better_supabase"."product_variants" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'catalog.read'), false)
    when 'rfq' then exists (select 1 from "better_supabase"."rfqs" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'rfqs.read'), false)
    when 'till' then exists (select 1 from "better_supabase"."tills" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'tills.read'), false)
    when 'order' then exists (select 1 from "better_supabase"."orders" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'orders.read'), false)
    when 'calendar_event' then exists (select 1 from "better_supabase"."calendar_events" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'calendar.read'), false)
    when 'booking' then exists (select 1 from "better_supabase"."bookings" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'bookings.read'), false)
    when 'asset' then exists (select 1 from "better_supabase"."assets" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'assets.read'), false)
    when 'asset_location' then exists (select 1 from "better_supabase"."asset_locations" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'assets.read'), false)
    when 'lease' then exists (select 1 from "better_supabase"."leases" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'leases.read'), false)
    when 'expense_report' then exists (select 1 from "better_supabase"."expense_reports" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'expenses.read'), false)
    when 'expense_line' then exists (select 1 from "better_supabase"."expense_lines" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'expenses.read'), false)
    when 'donation_fund' then exists (select 1 from "better_supabase"."donation_funds" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'donations.read'), false)
    when 'warranty_claim' then exists (select 1 from "better_supabase"."warranty_claims" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'warranty.read'), false)
    when 'work_order' then exists (select 1 from "better_supabase"."work_orders" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'dispatch.read'), false)
    when 'shipment' then exists (select 1 from "better_supabase"."shipments" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'shipments.read'), false)
    when 'contract' then exists (select 1 from "better_supabase"."contracts" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'contracts.read'), false)
    when 'control' then exists (select 1 from "better_supabase"."controls" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'compliance.read'), false)
    when 'compliance_policy' then exists (select 1 from "better_supabase"."compliance_policies" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'compliance.read'), false)
    when 'qualification_type' then exists (select 1 from "better_supabase"."qualification_types" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'qualifications.read'), false)
    when 'risk' then exists (select 1 from "better_supabase"."risks" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'risks.read'), false)
    when 'case' then exists (select 1 from "better_supabase"."cases" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'cases.read'), false)
    when 'inspection' then exists (select 1 from "better_supabase"."inspections" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'inspections.read'), false)
    when 'inspection_program' then exists (select 1 from "better_supabase"."inspection_programs" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'inspections.read'), false)
    when 'inspection_finding' then exists (select 1 from "better_supabase"."inspection_findings" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'inspections.read'), false)
    when 'form' then exists (select 1 from "better_supabase"."forms" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'forms.read'), false)
    when 'meeting' then exists (select 1 from "better_supabase"."meetings" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'meetings.read'), false)
    when 'meeting_decision' then exists (select 1 from "better_supabase"."meeting_decisions" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'meetings.read'), false)
    when 'maintenance_plan' then exists (select 1 from "better_supabase"."maintenance_plans" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'maintenance.read'), false)
    when 'dam_usage_right' then exists (select 1 from "better_supabase"."dam_usage_rights" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'dam.read'), false)
    when 'lims_sample' then exists (select 1 from "better_supabase"."lims_samples" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'lims.read'), false)
    when 'tax_code' then exists (select 1 from "better_supabase"."tax_codes" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'tax.read'), false)
    when 'production_order' then exists (select 1 from "better_supabase"."production_orders" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'manufacturing.read'), false)
    when 'work_center' then exists (select 1 from "better_supabase"."work_centers" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'manufacturing.read'), false)
    when 'bank_account' then exists (select 1 from "better_supabase"."bank_accounts" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'banking.read'), false)
    when 'care_plan' then exists (select 1 from "better_supabase"."care_plans" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'care_plans.read'), false)
    when 'incident' then exists (select 1 from "better_supabase"."incidents" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'incidents.read'), false)
    when 'content_entry' then exists (select 1 from "better_supabase"."content_entries" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'content.read'), false)
    when 'document' then exists (select 1 from "better_supabase"."documents" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'documents.read'), false)
    when 'customer' then exists (select 1 from "public"."customers" s where s."id" = (tag.subject_id)::uuid and s."organization_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'customers.read'), false)
    when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant and (coalesce(better_supabase.can('tenant', tag.tenant, 'drive.read'), false) and coalesce("better_supabase"."drive_node_readable"(s."id"), false)))
    when 'organization' then exists (select 1 from "public"."organizations" s where s."id" = (tag.subject_id)::uuid and s."id" = tag.tenant)
    when 'application' then exists (select 1 from "better_supabase"."applications" s where s."id" = (tag.subject_id)::uuid and s."tenant_id" = tag.tenant) and coalesce(better_supabase.can('tenant', tag.tenant, 'hiring.read'), false)
    when 'change_request' then exists (select 1 from "public"."change_requests" s where s."id" = (tag.subject_id)::uuid and s."organization_id" = tag.tenant)
    when 'project' then exists (select 1 from "public"."projects" s where s."id" = (tag.subject_id)::uuid and s."organization_id" = tag.tenant)
    when 'task' then exists (select 1 from "public"."tasks" s where s."id" = (tag.subject_id)::uuid and s."organization_id" = tag.tenant)
    else false
  end end)) then
    raise exception 'not allowed to tag this record' using errcode = '42501', hint = 'TAG_SUBJECT_FORBIDDEN';
  end if;
  select "kind" into v_kind from "better_supabase"."tags" where "id" = tag.tag_id and "tenant_id" = tag.tenant;
  if v_kind is null then
    raise exception 'tag not found' using errcode = 'P0002', hint = 'TAG_NOT_FOUND';
  end if;
  if not (case tag.subject_type
    when 'message' then true
    when 'conversation' then true
    when 'channel' then true
    when 'company' then true
    when 'person' then true
    when 'deal' then true
    when 'course' then true
    when 'post' then true
    when 'activity' then true
    when 'quote' then true
    when 'work_item' then true
    when 'employee' then true
    when 'ledger_account' then true
    when 'invoice' then true
    when 'product' then true
    when 'product_variant' then true
    when 'rfq' then true
    when 'till' then true
    when 'order' then true
    when 'calendar_event' then true
    when 'booking' then true
    when 'asset' then true
    when 'asset_location' then true
    when 'lease' then true
    when 'expense_report' then true
    when 'expense_line' then true
    when 'donation_fund' then true
    when 'warranty_claim' then true
    when 'work_order' then true
    when 'shipment' then true
    when 'contract' then true
    when 'control' then true
    when 'compliance_policy' then true
    when 'qualification_type' then true
    when 'risk' then true
    when 'case' then true
    when 'inspection' then true
    when 'inspection_program' then true
    when 'inspection_finding' then true
    when 'form' then true
    when 'meeting' then true
    when 'meeting_decision' then true
    when 'maintenance_plan' then true
    when 'dam_usage_right' then true
    when 'lims_sample' then true
    when 'tax_code' then true
    when 'production_order' then true
    when 'work_center' then true
    when 'bank_account' then true
    when 'care_plan' then true
    when 'incident' then true
    when 'content_entry' then true
    when 'document' then true
    when 'customer' then true
    when 'drive_node' then true
    when 'organization' then true
    when 'application' then true
    when 'change_request' then true
    when 'project' then true
    when 'task' then true
    else true
  end) then
    raise exception 'tag kind is not allowed on this subject' using errcode = '22023', hint = 'TAG_KIND_MISMATCH';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_tag_apply"(uuid, text, text, uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::text, $4::uuid)', v_hook::oid::regproc)
        using tag.tenant, tag.subject_type, tag.subject_id, tag.tag_id;
    end if;
  end;
  case tag.subject_type
    when '' then null;
    else
      insert into "better_supabase"."taggings" ("tenant_id", "tag_id", "subject_type", "subject_id")
      values (tag.tenant, tag.tag_id, tag.subject_type, tag.subject_id)
      on conflict do nothing;
  end case;
  perform "better_supabase".emit_event('subject.tagged', jsonb_build_object('organizationId', tag.tenant, 'subjectType', tag.subject_type, 'subjectId', tag.subject_id, 'id', tag.tag_id), 'subjects/' || tag.subject_type || '/' || tag.subject_id, (tag.tenant)::text, null, 'better-supabase/tags');
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_tag_apply"(uuid, text, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::text)', v_hook::oid::regproc)
        using tag.tag_id, tag.subject_type, tag.subject_id;
    end if;
  end;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.tags_subject_merge (
  subject_table text,
  keep          text,
  drop          text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_type text;
  v_keep text := keep;
  v_drop text := drop;
begin
  for v_type in select unnest(case subject_table when 'better_supabase.messages' then array['message'] when 'better_supabase.conversations' then array['conversation'] when 'better_supabase.channels' then array['channel'] when 'better_supabase.companies' then array['company'] when 'better_supabase.people' then array['person'] when 'better_supabase.deals' then array['deal'] when 'better_supabase.courses' then array['course'] when 'better_supabase.posts' then array['post'] when 'better_supabase.activities' then array['activity'] when 'better_supabase.quotes' then array['quote'] when 'better_supabase.work_items' then array['work_item'] when 'better_supabase.employees' then array['employee'] when 'better_supabase.ledger_accounts' then array['ledger_account'] when 'better_supabase.invoices' then array['invoice'] when 'better_supabase.products' then array['product'] when 'better_supabase.product_variants' then array['product_variant'] when 'better_supabase.rfqs' then array['rfq'] when 'better_supabase.tills' then array['till'] when 'better_supabase.orders' then array['order'] when 'better_supabase.calendar_events' then array['calendar_event'] when 'better_supabase.bookings' then array['booking'] when 'better_supabase.assets' then array['asset'] when 'better_supabase.asset_locations' then array['asset_location'] when 'better_supabase.leases' then array['lease'] when 'better_supabase.expense_reports' then array['expense_report'] when 'better_supabase.expense_lines' then array['expense_line'] when 'better_supabase.donation_funds' then array['donation_fund'] when 'better_supabase.warranty_claims' then array['warranty_claim'] when 'better_supabase.work_orders' then array['work_order'] when 'better_supabase.shipments' then array['shipment'] when 'better_supabase.contracts' then array['contract'] when 'better_supabase.controls' then array['control'] when 'better_supabase.compliance_policies' then array['compliance_policy'] when 'better_supabase.qualification_types' then array['qualification_type'] when 'better_supabase.risks' then array['risk'] when 'better_supabase.cases' then array['case'] when 'better_supabase.inspections' then array['inspection'] when 'better_supabase.inspection_programs' then array['inspection_program'] when 'better_supabase.inspection_findings' then array['inspection_finding'] when 'better_supabase.forms' then array['form'] when 'better_supabase.meetings' then array['meeting'] when 'better_supabase.meeting_decisions' then array['meeting_decision'] when 'better_supabase.maintenance_plans' then array['maintenance_plan'] when 'better_supabase.dam_usage_rights' then array['dam_usage_right'] when 'better_supabase.lims_samples' then array['lims_sample'] when 'better_supabase.tax_codes' then array['tax_code'] when 'better_supabase.production_orders' then array['production_order'] when 'better_supabase.work_centers' then array['work_center'] when 'better_supabase.bank_accounts' then array['bank_account'] when 'better_supabase.care_plans' then array['care_plan'] when 'better_supabase.incidents' then array['incident'] when 'better_supabase.content_entries' then array['content_entry'] when 'better_supabase.documents' then array['document'] when 'public.customers' then array['customer'] when 'better_supabase.drive_nodes' then array['drive_node'] when 'public.organizations' then array['organization'] when 'better_supabase.applications' then array['application'] when 'public.change_requests' then array['change_request'] when 'public.projects' then array['project'] when 'public.tasks' then array['task'] else '{}'::text[] end) loop
    delete from "better_supabase"."taggings" x where x."subject_type" = v_type and x."subject_id" = v_drop and exists (select 1 from "better_supabase"."taggings" y where y."subject_type" = v_type and y."subject_id" = v_keep and y."tag_id" is not distinct from x."tag_id");
    update "better_supabase"."taggings" x set "subject_id" = v_keep where x."subject_type" = v_type and x."subject_id" = v_drop;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.take_allocation (
  allocation uuid,
  quantity   numeric,
  reason     text,
  detail     jsonb   DEFAULT NULL::jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row record;
  v_from_held numeric;
  v_movement uuid;
begin
  select x."id" as id, x."tenant_id" as tenant, x."variant_id" as variant, x."location_id" as location,
    x."document_type" as document_type, x."document_id" as document_id, x."quantity" as quantity,
    x."allocated" as allocated, x."fulfilled" as fulfilled, x."status" as status
  into v_row from "better_supabase"."stock_allocations" x where x."id" = take_allocation.allocation for update;
  if not found then
    raise exception 'allocation not found' using errcode = 'P0002', hint = 'INVENTORY_ALLOCATION_NOT_FOUND';
  end if;
  if v_row.status <> 'open' then
    raise exception 'the allocation is no longer open' using errcode = '55000', hint = 'INVENTORY_ALLOCATION_CLOSED';
  end if;
  if take_allocation.quantity is null or take_allocation.quantity <= 0
    or take_allocation.quantity > v_row.quantity - v_row.fulfilled then
    raise exception 'the quantity must be more than zero and at most what the allocation has left' using errcode = '22023', hint = 'INVENTORY_QUANTITY_INVALID';
  end if;
  v_from_held := least(take_allocation.quantity, v_row.allocated);
  update "better_supabase"."stock_levels" x set "reserved" = greatest(x."reserved" + -v_from_held, 0), "updated_at" = now()
    where x."variant_id" = v_row.variant and x."location_id" = v_row.location;
  update "better_supabase"."stock_allocations" x set "allocated" = x."allocated" - v_from_held,
    "fulfilled" = x."fulfilled" + take_allocation.quantity,
    "status" = case when x."fulfilled" + take_allocation.quantity >= x."quantity" then 'fulfilled' else 'open' end,
    "updated_at" = now()
  where x."id" = v_row.id;
  v_movement := "better_supabase"."move_stock"(v_row.tenant, v_row.variant, v_row.location, -take_allocation.quantity, take_allocation.reason, v_row.document_type, v_row.document_id, null, take_allocation.detail);
  return (select jsonb_build_object('id', x."id", 'variantId', x."variant_id", 'locationId', x."location_id",
    'documentType', x."document_type", 'documentId', x."document_id", 'lineId', x."line_id",
    'quantity', x."quantity"::text, 'allocated', x."allocated"::text, 'fulfilled', x."fulfilled"::text,
    'backordered', x."backordered"::text, 'status', x."status", 'createdAt', x."created_at") || jsonb_build_object('movementId', v_movement) from "better_supabase"."stock_allocations" x where x."id" = v_row.id);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.take_forecast_snapshot (
  tenant   uuid,
  pipeline uuid,
  since    date,
  until    date,
  currency text,
  target   bigint DEFAULT NULL::bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."forecast_snapshots";
  v_currency text := upper(take_forecast_snapshot.currency);
  v_count integer;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', take_forecast_snapshot.tenant, 'forecasts.snapshot'), false)) then
    raise exception 'Taking a forecast snapshot needs the forecasts.snapshot permission' using errcode = '42501', hint = 'FORECAST_FORBIDDEN';
  end if;
  if take_forecast_snapshot.since is null or take_forecast_snapshot.until is null
    or take_forecast_snapshot.until < take_forecast_snapshot.since
    or take_forecast_snapshot.until - take_forecast_snapshot.since > 366 then
    raise exception 'until must be on or after since, at most a year later' using errcode = '22023', hint = 'FORECAST_INVALID';
  end if;
  if v_currency is null or v_currency !~ '^[A-Z]{3}$' then
    raise exception 'currency must be a three-letter code' using errcode = '22023', hint = 'FORECAST_INVALID';
  end if;
  if take_forecast_snapshot.target < 0 then
    raise exception 'target must not be negative' using errcode = '22023', hint = 'FORECAST_INVALID';
  end if;
  if take_forecast_snapshot.pipeline is not null and not exists (
    select 1 from "better_supabase"."pipelines" x
    where x."id" = take_forecast_snapshot.pipeline and x."tenant_id" = take_forecast_snapshot.tenant
  ) then
    raise exception 'The organization has no pipeline with this id' using errcode = 'P0002', hint = 'FORECAST_PIPELINE_UNKNOWN';
  end if;
  insert into "better_supabase"."forecast_snapshots" ("tenant_id", "pipeline_id", "period_start", "period_end", "currency", "target", "totals", "taken_by")
  values (take_forecast_snapshot.tenant, take_forecast_snapshot.pipeline, take_forecast_snapshot.since, take_forecast_snapshot.until, v_currency, take_forecast_snapshot.target, "better_supabase"."deal_forecast"(take_forecast_snapshot.tenant, take_forecast_snapshot.pipeline, take_forecast_snapshot.since, take_forecast_snapshot.until, v_currency, take_forecast_snapshot.target, null), auth.uid())
  returning * into v_row;
  insert into "better_supabase"."forecast_snapshot_deals" ("snapshot_id", "tenant_id", "deal_id", "name", "owner_id", "stage_id", "forecast_category", "outcome", "amount", "expected_close_on", "closed_at")
  select v_row."id", x."tenant_id", x."id", x."name", x."owner_id", x."stage_id", x."forecast_category"::text, x."outcome"::text, x."amount", x."expected_close_on", x."closed_at"
  from "better_supabase"."deals" x
  where x."tenant_id" = take_forecast_snapshot.tenant
    and x."currency" = v_currency
    and x."archived_at" is null
    and (take_forecast_snapshot.pipeline is null or x."pipeline_id" = take_forecast_snapshot.pipeline)
    and (
      (x."outcome" = 'open' and x."expected_close_on" between take_forecast_snapshot.since and take_forecast_snapshot.until)
      or (x."outcome" <> 'open' and x."closed_at"::date between take_forecast_snapshot.since and take_forecast_snapshot.until)
    );
  get diagnostics v_count = row_count;
  update "better_supabase"."forecast_snapshots" x set "deal_count" = v_count
  where x."id" = v_row."id"
  returning * into v_row;
  perform "better_supabase".emit_event('forecast_snapshot.created', jsonb_build_object('organizationId', v_row."tenant_id", 'snapshotId', v_row."id", 'pipelineId', v_row."pipeline_id", 'since', v_row."period_start", 'until', v_row."period_end", 'currency', v_row."currency", 'dealCount', v_row."deal_count"), 'forecast-snapshots/' || v_row."id"::text, (v_row."tenant_id"::text)::text, null, 'better-supabase/forecasts');
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'pipelineId', v_row."pipeline_id", 'since', v_row."period_start", 'until', v_row."period_end", 'currency', v_row."currency", 'target', v_row."target"::text, 'totals', v_row."totals", 'dealCount', v_row."deal_count", 'takenBy', v_row."taken_by", 'takenAt', v_row."taken_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.tasks_emit_event()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row jsonb;
  v_changed text[];
begin
  if tg_op = 'INSERT' then
    v_row := to_jsonb(new);
    perform "better_supabase".emit_event('task.created', jsonb_build_object('id', v_row -> 'id', 'organizationId', v_row -> 'organization_id', 'subjectType', 'task', 'subjectId', v_row ->> 'id', 'status', v_row -> 'status', 'project_id', v_row -> 'project_id'), 'tasks/' || (v_row ->> 'id'), (v_row ->> 'organization_id')::text, null, 'better-supabase/app-tables');
  end if;
  if tg_op = 'UPDATE' then
    v_row := to_jsonb(new);
    select coalesce(array_agg(n.key order by n.key), array[]::text[]) into v_changed
      from jsonb_each(v_row) n
      join jsonb_each(to_jsonb(old)) o on o.key = n.key
     where n.value is distinct from o.value and n.key <> 'updated_at';
    if cardinality(v_changed) > 0 then
      perform "better_supabase".emit_event('task.updated', jsonb_build_object('id', v_row -> 'id', 'organizationId', v_row -> 'organization_id', 'subjectType', 'task', 'subjectId', v_row ->> 'id', 'status', v_row -> 'status', 'project_id', v_row -> 'project_id', 'changed', to_jsonb(v_changed)), 'tasks/' || (v_row ->> 'id'), (v_row ->> 'organization_id')::text, null, 'better-supabase/app-tables');
    end if;
  end if;
  if tg_op = 'DELETE' then
    v_row := to_jsonb(old);
    perform "better_supabase".emit_event('task.deleted', jsonb_build_object('id', v_row -> 'id', 'organizationId', v_row -> 'organization_id', 'subjectType', 'task', 'subjectId', v_row ->> 'id', 'status', v_row -> 'status', 'project_id', v_row -> 'project_id'), 'tasks/' || (v_row ->> 'id'), (v_row ->> 'organization_id')::text, null, 'better-supabase/app-tables');
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.tax_code_updated_at (
  subject_id text
)
  RETURNS timestamp WITH time zone
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select x."updated_at" from "better_supabase"."tax_codes" x where x."id"::text = tax_code_updated_at.subject_id
$function$;

CREATE OR REPLACE FUNCTION better_supabase.tax_code_write (
  tenant  uuid,
  input   jsonb,
  code_id uuid  DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."tax_codes"%rowtype;
  v_created boolean := false;
  v_type text;
  v_entity uuid;
  v_sales uuid;
  v_purchase uuid;
  v_boxes text[];
  v_rate integer;
  v_from date;
begin
  if jsonb_typeof(tax_code_write.input) is distinct from 'object' then
    raise exception 'input must be an object' using errcode = '22023', hint = 'TAX_CODE_INVALID';
  end if;
  if tax_code_write.code_id is not null then
    select * into v_row from "better_supabase"."tax_codes" x
    where x."id" = tax_code_write.code_id and x."tenant_id" = tax_code_write.tenant for update;
    if not found then
      raise exception 'no such tax code' using errcode = 'P0002', hint = 'TAX_CODE_NOT_FOUND';
    end if;
  end if;
  v_type := coalesce(tax_code_write.input ->> 'type', v_row."type");
  if v_type is null or v_type not in ('sales', 'purchase', 'exempt', 'zero', 'reverse_charge', 'intra_eu_goods', 'intra_eu_services', 'export', 'margin') then
    raise exception 'a tax code''s type is sales, purchase, exempt, zero, reverse_charge, intra_eu_goods, intra_eu_services, export or margin' using errcode = '22023', hint = 'TAX_CODE_INVALID';
  end if;
  v_entity := case when tax_code_write.input ? 'legalEntityId'
    then nullif(tax_code_write.input ->> 'legalEntityId', '')::uuid else v_row."legal_entity_id" end;
  if v_entity is not null and not exists (
    select 1 from "better_supabase"."legal_entities" y
    where y."id" = v_entity and y."tenant_id" = tax_code_write.tenant
  ) then
    raise exception 'a tax code''s legal entity must be a legal entity of the organization' using errcode = '22023', hint = 'TAX_CODE_INVALID';
  end if;
  v_sales := case when tax_code_write.input ? 'salesAccountId'
    then nullif(tax_code_write.input ->> 'salesAccountId', '')::uuid else v_row."sales_account_id" end;
  if v_sales is not null and not exists (
    select 1 from "better_supabase"."accounting_accounts" y
    where y."id" = v_sales and y."tenant_id" = tax_code_write.tenant
  ) then
    raise exception 'a tax code''s account must be an account of the organization' using errcode = '22023', hint = 'TAX_CODE_INVALID';
  end if;
  v_purchase := case when tax_code_write.input ? 'purchaseAccountId'
    then nullif(tax_code_write.input ->> 'purchaseAccountId', '')::uuid else v_row."purchase_account_id" end;
  if v_purchase is not null and not exists (
    select 1 from "better_supabase"."accounting_accounts" y
    where y."id" = v_purchase and y."tenant_id" = tax_code_write.tenant
  ) then
    raise exception 'a tax code''s account must be an account of the organization' using errcode = '22023', hint = 'TAX_CODE_INVALID';
  end if;
  if tax_code_write.input ? 'returnBoxes' then
    if jsonb_typeof(tax_code_write.input -> 'returnBoxes') is distinct from 'array' then
      raise exception 'returnBoxes must be a list of box names' using errcode = '22023', hint = 'TAX_CODE_INVALID';
    end if;
    select coalesce(array_agg(trim(b.value) order by b.ordinality), '{}') into v_boxes
    from jsonb_array_elements_text(tax_code_write.input -> 'returnBoxes') with ordinality b;
  else
    v_boxes := coalesce(v_row."return_boxes", '{}');
  end if;
  if v_row."id" is null then
    v_created := true;
    insert into "better_supabase"."tax_codes" ("tenant_id", "legal_entity_id", "code", "name", "type", "sales_account_id", "purchase_account_id", "return_boxes", "archived_at")
    values (tax_code_write.tenant, v_entity, trim(tax_code_write.input ->> 'code'), trim(tax_code_write.input ->> 'name'), v_type, v_sales, v_purchase, v_boxes,
      case when coalesce((tax_code_write.input ->> 'archived')::boolean, false) then now() end)
    returning * into v_row;
  else
    update "better_supabase"."tax_codes" x set
      "legal_entity_id" = v_entity,
      "code" = coalesce(trim(tax_code_write.input ->> 'code'), x."code"),
      "name" = coalesce(trim(tax_code_write.input ->> 'name'), x."name"),
      "type" = v_type,
      "sales_account_id" = v_sales,
      "purchase_account_id" = v_purchase,
      "return_boxes" = v_boxes,
      "archived_at" = case when tax_code_write.input ? 'archived'
        then case when (tax_code_write.input ->> 'archived')::boolean then coalesce(x."archived_at", now()) end
        else x."archived_at" end,
      "updated_at" = now()
    where x."id" = v_row."id"
    returning * into v_row;
  end if;
  if tax_code_write.input ? 'rateBps' and tax_code_write.input -> 'rateBps' <> 'null'::jsonb then
    v_rate := (tax_code_write.input ->> 'rateBps')::integer;
    v_from := coalesce(nullif(tax_code_write.input ->> 'validFrom', '')::date, case when v_created then date '1970-01-01' else current_date end);
    perform "better_supabase"."tax_rate_write"(tax_code_write.tenant, v_row."id", v_rate, v_from, null);
    select * into v_row from "better_supabase"."tax_codes" x where x."id" = v_row."id";
  end if;
  if v_created then
    perform "better_supabase".emit_event('tax_code.created', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'code', v_row."code", 'type', v_row."type", 'legalEntityId', v_row."legal_entity_id"), 'tax-codes/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/tax');
  perform better_supabase.audit_event(
    event_type => 'tax_code.created',
    category => 'billing',
    target_type => 'tax_code',
    record_id => v_row."id"::text,
    target_label => v_row."code",
    summary => 'Created a tax code',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'code', v_row."code", 'type', v_row."type", 'legalEntityId', v_row."legal_entity_id")
  );
  else
    perform "better_supabase".emit_event('tax_code.updated', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'code', v_row."code", 'type', v_row."type", 'legalEntityId', v_row."legal_entity_id"), 'tax-codes/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/tax');
  perform better_supabase.audit_event(
    event_type => 'tax_code.updated',
    category => 'billing',
    target_type => 'tax_code',
    record_id => v_row."id"::text,
    target_label => v_row."code",
    summary => 'Changed a tax code',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'code', v_row."code", 'type', v_row."type", 'legalEntityId', v_row."legal_entity_id")
  );
  end if;
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'legalEntityId', v_row."legal_entity_id", 'code', v_row."code", 'name', v_row."name", 'type', v_row."type", 'salesAccountId', v_row."sales_account_id", 'purchaseAccountId', v_row."purchase_account_id", 'returnBoxes', to_jsonb(v_row."return_boxes"), 'archivedAt', v_row."archived_at", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at", 'rates', coalesce((select jsonb_agg(jsonb_build_object('id', y."id", 'organizationId', y."tenant_id", 'taxCodeId', y."tax_code_id", 'rateBps', y."rate_bps", 'validFrom', y."valid_from", 'validTo', y."valid_to", 'createdAt', y."created_at") order by y."valid_from") from "better_supabase"."tax_rates" y where y."tax_code_id" = v_row."id"), '[]'::jsonb));
exception
  when check_violation or not_null_violation then
    raise exception 'a tax code has a code of 1 to 50 characters and a name of 1 to 200' using errcode = '22023', hint = 'TAX_CODE_INVALID';
  when unique_violation then
    raise exception 'the organization already has a tax code with this code' using errcode = '22023', hint = 'TAX_CODE_INVALID';
  when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then
    raise exception 'ids must be uuids, rateBps an integer and validFrom a date' using errcode = '22023', hint = 'TAX_CODE_INVALID';
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.tax_compute_lines (
  lines                  jsonb,
  on_date                date,
  prices_include_tax     boolean,
  credit_restriction_bps integer,
  discount_bps           integer,
  discount_amount        bigint
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  v_inclusive boolean := coalesce(tax_compute_lines.prices_include_tax, false);
  v_restriction integer := coalesce(tax_compute_lines.credit_restriction_bps, 0);
  v_on date := coalesce(tax_compute_lines.on_date, current_date);
  v_bps integer := coalesce(tax_compute_lines.discount_bps, 0);
  v_amount bigint := coalesce(tax_compute_lines.discount_amount, 0);
  v_lines jsonb;
  v_groups jsonb;
  v_net bigint;
  v_line_discount bigint;
  v_record_discount bigint;
begin
  if jsonb_typeof(tax_compute_lines.lines) is distinct from 'array' then
    raise exception 'lines must be a list' using errcode = '22023', hint = 'TAX_COMPUTE_INVALID';
  end if;
  if v_restriction < 0 or v_restriction > 10000 then
    raise exception 'a credit restriction is 0 to 10000 basis points' using errcode = '22023', hint = 'TAX_COMPUTE_INVALID';
  end if;
  if exists (select 1 from jsonb_array_elements(tax_compute_lines.lines) x where jsonb_typeof(x.value) <> 'object') then
    raise exception 'every line must be an object' using errcode = '22023', hint = 'TAX_COMPUTE_INVALID';
  end if;
  if exists (
    select 1 from jsonb_array_elements(tax_compute_lines.lines) x
    where x.value ->> 'taxCodeId' is not null
      and not exists (select 1 from "better_supabase"."tax_codes" y where y."id"::text = x.value ->> 'taxCodeId')
  ) then
    raise exception 'no such tax code' using errcode = 'P0002', hint = 'TAX_CODE_NOT_FOUND';
  end if;
  if exists (
    select 1 from jsonb_array_elements(tax_compute_lines.lines) x
    join "better_supabase"."tax_codes" y on y."id"::text = x.value ->> 'taxCodeId'
    where y."type" = 'margin' and x.value ->> 'unitCost' is null
  ) then
    raise exception 'a margin scheme line needs the unitCost of what it was bought for' using errcode = '22023', hint = 'TAX_MARGIN_COST_REQUIRED';
  end if;
  with src as (
    select x.ordinality as pos,
      coalesce((x.value ->> 'quantity')::numeric, 1) as qty,
      (x.value ->> 'unitAmount')::bigint as unit,
      coalesce((x.value ->> 'discountBps')::integer, 0) as disc_bps,
      coalesce((x.value ->> 'discountAmount')::bigint, 0) as disc_amount,
      coalesce((x.value ->> 'unitCost')::bigint, 0) as unit_cost,
      y."id" as code_id,
      y."code" as code,
      coalesce(y."type", 'sales') as type,
      case
        when y."id" is null then coalesce((x.value ->> 'taxRateBps')::integer, 0)
        when y."type" not in ('sales', 'purchase', 'margin') then 0
        else coalesce("better_supabase"."tax_rate_on"(y."id", v_on), (x.value ->> 'taxRateBps')::integer, -1)
      end as rate
    from jsonb_array_elements(tax_compute_lines.lines) with ordinality x
    left join "better_supabase"."tax_codes" y on y."id"::text = x.value ->> 'taxCodeId'
  ), priced as (
    select s.*, round(s.qty * s.unit) as amount from src s
  ), discounted as (
    select p.*, least(p.amount, round(p.amount * p.disc_bps / 10000.0) + p.disc_amount) as disc from priced p
  ), counted as (
    select d.*, d.amount - d.disc as after, round(d.qty * d.unit_cost) as cost from discounted d
  ), taxed as (
    select n.pos, n.rate, n.code_id, n.code, n.type, n.after, n.disc,
      case
        when n.rate <= 0 then 0
        when n.type = 'margin' then round(greatest(n.after - n.cost, 0) * n.rate / (10000.0 + n.rate))
        else round(n.after * (10000 - v_restriction) * n.rate / (10000.0 * (case when v_inclusive then 10000.0 + n.rate else 10000.0 end)))
      end as tax
    from counted n
  )
  select coalesce(jsonb_agg(jsonb_build_object('pos', t.pos, 'rate', t.rate, 'codeId', t.code_id, 'code', t.code, 'type', t.type,
      'after', t.after::bigint, 'disc', t.disc::bigint, 'tax', t.tax::bigint) order by t.pos), '[]'::jsonb)
    into v_lines
  from taxed t;
  if exists (select 1 from jsonb_to_recordset(v_lines) r(rate integer) where r.rate < 0) then
    raise exception 'no rate of a line''s tax code covers the date, and the line gives no taxRateBps' using errcode = '22023', hint = 'TAX_RATE_INVALID';
  end if;
  select coalesce(sum(r.after), 0), coalesce(sum(r.disc), 0) into v_net, v_line_discount
  from jsonb_to_recordset(v_lines) r(after bigint, disc bigint);
  v_record_discount := case
    when v_net > 0 then least(v_net, round(v_net * v_bps / 10000.0)::bigint + v_amount)
    else 0
  end;
  with grouped as (
    select r.rate, r."codeId" as code_id, r.code, r.type, sum(r.after) as amount, sum(r.tax) as tax
    from jsonb_to_recordset(v_lines) r(rate integer, "codeId" uuid, code text, type text, after bigint, tax bigint)
    group by 1, 2, 3, 4
  ), shared as (
    select g.rate, g.code_id, g.code, g.type, g.amount, g.tax,
      case when v_net > 0
        then round(v_record_discount * sum(g.amount) over w / v_net) - round(v_record_discount * (sum(g.amount) over w - g.amount) / v_net)
        else 0
      end as share
    from grouped g
    window w as (order by g.rate, g.code nulls first, g.code_id nulls first rows between unbounded preceding and current row)
  ), reduced as (
    select s.rate, s.code_id, s.code, s.type, s.share, s.amount - s.share as amount,
      s.tax - case
        when s.rate <= 0 then 0
        when s.type = 'margin' then round(s.share * s.rate / (10000.0 + s.rate))
        else round(s.share * (10000 - v_restriction) * s.rate / (10000.0 * (case when v_inclusive then 10000.0 + s.rate else 10000.0 end)))
      end as tax
    from shared s
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'taxCodeId', x.code_id,
      'code', x.code,
      'type', x.type,
      'rateBps', x.rate,
      'net', (case when v_inclusive or x.type = 'margin' then x.amount - x.tax else x.amount end)::text,
      'tax', x.tax::text,
      'gross', (case when v_inclusive or x.type = 'margin' then x.amount else x.amount + x.tax end)::text,
      'discount', x.share::text,
      'showTax', x.type <> 'margin'
    ) order by x.rate, x.code nulls first, x.code_id nulls first), '[]'::jsonb)
    into v_groups
  from reduced x;
  return jsonb_build_object(
    'groups', v_groups,
    'subtotal', (select coalesce(sum((g ->> 'net')::bigint), 0) from jsonb_array_elements(v_groups) g)::text,
    'taxTotal', (select coalesce(sum((g ->> 'tax')::bigint), 0) from jsonb_array_elements(v_groups) g)::text,
    'total', (select coalesce(sum((g ->> 'gross')::bigint), 0) from jsonb_array_elements(v_groups) g)::text,
    'discountTotal', (v_line_discount + v_record_discount)::text,
    'showTaxAmount', not exists (select 1 from jsonb_array_elements(v_groups) g where g ->> 'type' = 'margin')
  );
exception
  when invalid_text_representation or numeric_value_out_of_range or datatype_mismatch then
    raise exception 'quantity, unitAmount, discountBps, unitCost and taxRateBps must be numbers and taxCodeId a uuid' using errcode = '22023', hint = 'TAX_COMPUTE_INVALID';
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.tax_rate_on (
  code_id uuid,
  on_date date
)
  RETURNS integer
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select case
    when x."type" not in ('sales', 'purchase', 'margin') then 0
    else (
      select y."rate_bps" from "better_supabase"."tax_rates" y
      where y."tax_code_id" = x."id" and y."valid_from" <= tax_rate_on.on_date
        and (y."valid_to" is null or y."valid_to" >= tax_rate_on.on_date)
      order by y."valid_from" desc limit 1
    )
  end
  from "better_supabase"."tax_codes" x where x."id" = tax_rate_on.code_id
$function$;

CREATE OR REPLACE FUNCTION better_supabase.tax_rate_write (
  tenant     uuid,
  tax_code   uuid,
  rate_bps   integer,
  valid_from date    DEFAULT NULL::date,
  valid_to   date    DEFAULT NULL::date
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_code "better_supabase"."tax_codes"%rowtype;
  v_from date := coalesce(tax_rate_write.valid_from, date '1970-01-01');
  v_to date := tax_rate_write.valid_to;
  v_row "better_supabase"."tax_rates"%rowtype;
begin
  select * into v_code from "better_supabase"."tax_codes" x
  where x."id" = tax_rate_write.tax_code and x."tenant_id" = tax_rate_write.tenant for update;
  if not found then
    raise exception 'no such tax code' using errcode = 'P0002', hint = 'TAX_CODE_NOT_FOUND';
  end if;
  if v_code."type" not in ('sales', 'purchase', 'margin') then
    raise exception 'only a sales, purchase or margin code has a rate' using errcode = '22023', hint = 'TAX_RATE_INVALID';
  end if;
  if tax_rate_write.rate_bps is null or tax_rate_write.rate_bps < 0 or tax_rate_write.rate_bps > 100000 then
    raise exception 'a rate is 0 to 100000 basis points' using errcode = '22023', hint = 'TAX_RATE_INVALID';
  end if;
  if v_to is not null and v_to < v_from then
    raise exception 'a rate can''t end before it starts' using errcode = '22023', hint = 'TAX_RATE_INVALID';
  end if;
  if v_to is null then
    select min(y."valid_from") - 1 into v_to from "better_supabase"."tax_rates" y
    where y."tax_code_id" = v_code."id" and y."valid_from" > v_from;
  end if;
  if v_to is not null and exists (
    select 1 from "better_supabase"."tax_rates" y
    where y."tax_code_id" = v_code."id" and y."valid_from" > v_from and y."valid_from" <= v_to
  ) then
    raise exception 'the rate would overlap a later rate of the code' using errcode = '22023', hint = 'TAX_RATE_INVALID';
  end if;
  update "better_supabase"."tax_rates" y set "valid_to" = v_from - 1
  where y."tax_code_id" = v_code."id" and y."valid_from" < v_from
    and (y."valid_to" is null or y."valid_to" >= v_from);
  insert into "better_supabase"."tax_rates" ("tenant_id", "tax_code_id", "rate_bps", "valid_from", "valid_to")
  values (tax_rate_write.tenant, v_code."id", tax_rate_write.rate_bps, v_from, v_to)
  on conflict ("tax_code_id", "valid_from") do update
    set "rate_bps" = excluded."rate_bps", "valid_to" = excluded."valid_to"
  returning * into v_row;
  update "better_supabase"."tax_codes" x set "updated_at" = now() where x."id" = v_code."id";
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'taxCodeId', v_row."tax_code_id", 'rateBps', v_row."rate_bps", 'validFrom', v_row."valid_from", 'validTo', v_row."valid_to", 'createdAt', v_row."created_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.tax_return_source (
  tenant          uuid,
  since           date,
  until           date,
  legal_entity_id uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'currency', x."currency", 'sign', case when x."kind"::text = 'credit_note' then -1 else 1 end,
    'direction', coalesce(x."direction"::text, 'sales'), 'invoiceId', x."id", 'codeType', y."type",
    'boxes', coalesce(to_jsonb(y."return_boxes"), '[]'::jsonb), 'net', z."net", 'tax', z."tax",
    'vat', z."customer_vat_number")), '[]'::jsonb)
  from "better_supabase"."invoice_tax_lines" z
  join "better_supabase"."invoices" x on x."id" = z."invoice_id"
  left join "better_supabase"."tax_codes" y on y."id" = z."tax_code_id"
  where z."tenant_id" = tax_return_source.tenant
    and x."status"::text not in ('draft', 'void')
    and x."issued_on" >= tax_return_source.since and x."issued_on" <= tax_return_source.until
    and (tax_return_source.legal_entity_id is null or x.legal_entity_id = tax_return_source.legal_entity_id)
$function$;

CREATE OR REPLACE FUNCTION better_supabase.team_ids_of (
  member uuid
)
  RETURNS SETOF uuid
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if team_ids_of.member is distinct from (select auth.uid())
    and coalesce((select auth.jwt() ->> 'role'), 'service_role') <> 'service_role' then
    raise exception 'team_ids_of reads only the caller''s teams' using errcode = '42501', hint = 'TEAM_FORBIDDEN';
  end if;
  return query select "team_id" from "better_supabase"."team_members" where "user_id" = team_ids_of.member;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.technician_day (
  tenant     uuid,
  day        date,
  technician uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_technician uuid := coalesce(technician_day.technician, auth.uid());
  v_route "better_supabase"."dispatch_routes"%rowtype;
begin
  if v_technician is null or not (
    (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', technician_day.tenant, 'dispatch.read'), false))
    or (coalesce(v_technician = auth.uid(), false) and coalesce(better_supabase.can('tenant', technician_day.tenant, 'dispatch.work'), false))
  ) then
    raise exception 'not allowed to read this technician''s day' using errcode = '42501', hint = 'DISPATCH_FORBIDDEN';
  end if;
  select * into v_route from "better_supabase"."dispatch_routes" rt
    where rt."tenant_id" = technician_day.tenant and rt."technician_id" = v_technician and rt."route_date" = technician_day.day;
  return jsonb_build_object(
    'technicianId', v_technician,
    'date', technician_day.day,
    'routeId', v_route."id",
    'stops', (
      select coalesce(jsonb_agg(jsonb_build_object('position', z.position, 'workOrder', z.item) order by z.position), '[]'::jsonb)
      from (
        select row_number() over (order by y.planned nulls last, y.starts, y.id) as position, y.item
        from (
          select jsonb_build_object('id', x."id", 'organizationId', x."tenant_id"::text, 'title', x."title", 'description', x."description", 'priority', x."priority", 'status', x."status", 'technicianId', x."technician_id", 'startsAt', x."starts_at", 'endsAt', x."ends_at", 'day', (x."starts_at" at time zone 'UTC')::date, 'locationId', x."location_id", 'assetId', x."asset_id", 'bookingId', x."booking_id", 'subjectType', x."subject_type", 'subjectId', x."subject_id", 'address', x."address", 'enRouteAt', x."en_route_at", 'arrivedAt', x."arrived_at", 'completedAt', x."completed_at", 'cancelledAt', x."cancelled_at", 'cancelReason', x."cancel_reason", 'completionNote', x."completion_note", 'createdBy', x."created_by", 'createdAt', x."created_at", 'updatedAt', x."updated_at") as item, st."position" as planned, x."starts_at" as starts, x."id" as id
          from "better_supabase"."work_orders" x
          left join "better_supabase"."dispatch_route_stops" st on st."work_order_id" = x."id" and st."route_id" = v_route."id"
          where x."tenant_id" = technician_day.tenant
            and (st."id" is not null or (
              x."technician_id" = v_technician and x."status" <> 'cancelled'
              and x."starts_at" >= (technician_day.day::timestamp at time zone 'UTC')
              and x."starts_at" < ((technician_day.day + 1)::timestamp at time zone 'UTC')
            ))
        ) y
      ) z
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.template_applications_list (
  tenant       uuid,
  template_id  uuid,
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(r.value order by r.at desc, r.id), '[]'::jsonb)
  from (
    select jsonb_build_object(
    'id', a."id",
    'template', a."template_id",
    'version', a."version_id",
    'tenant', a."tenant_id",
    'subjectType', a."subject_type",
    'subjectId', a."subject_id",
    'appliedBy', a."applied_by",
    'appliedAt', a."applied_at"
  ) as value, a."applied_at" as at, a."id" as id
    from "better_supabase"."template_applications" a
    where a."tenant_id" = template_applications_list.tenant
      and (template_applications_list.template_id is null or a."template_id" = template_applications_list.template_id)
      and (template_applications_list.subject_type is null or a."subject_type" = template_applications_list.subject_type)
      and (template_applications_list.subject_id is null or a."subject_id" = template_applications_list.subject_id)
    order by a."applied_at" desc, a."id"
    limit 200
  ) r
$function$;

CREATE OR REPLACE FUNCTION better_supabase.template_apply_target (
  template_id uuid,
  tenant      uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_tpl "better_supabase"."templates"%rowtype;
  v_version "better_supabase"."template_versions"%rowtype;
  v_workflows jsonb := '[]'::jsonb;
begin
  if template_apply_target.tenant is null then
    raise exception 'Applying a template needs a tenant' using errcode = '22023', hint = 'TEMPLATE_INVALID';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', template_apply_target.tenant, 'templates.apply'), false)) then
    raise exception 'You may not apply templates here' using errcode = '42501', hint = 'TEMPLATE_FORBIDDEN';
  end if;
  select * into v_tpl from "better_supabase"."templates" x where x."id" = template_apply_target.template_id;
  if not found or not (v_tpl."scope" = 'system' or v_tpl."tenant_id" = template_apply_target.tenant or (v_tpl."scope" = 'brand' and v_tpl."brand" = "better_supabase"."template_brand"(template_apply_target.tenant))) then
    raise exception 'No such template' using errcode = 'P0002', hint = 'TEMPLATE_NOT_FOUND';
  end if;
  select * into v_version from "better_supabase"."template_versions" y
  where y."template_id" = v_tpl."id" and y."published_at" is not null
  order by y."version" desc limit 1;
  if not found then
    raise exception 'This template has no published version' using errcode = 'P0002', hint = 'TEMPLATE_NOT_PUBLISHED';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'definition', w."definition_id",
      'inputs', w."inputs",
      'errors', to_jsonb("better_supabase"."template_workflow_input_errors"(w."definition_id", w."inputs")))
    order by w."created_at", w."id"), '[]'::jsonb)
  into v_workflows
  from "better_supabase"."template_workflows" w where w."template_id" = v_tpl."id" and w."enabled";
  if exists (select 1 from jsonb_array_elements(v_workflows) e where jsonb_array_length(e.value -> 'errors') > 0) then
    raise exception 'A workflow input does not match its input schema: %',
      (select string_agg(e.value ->> 'definition' || ': ' || (e.value -> 'errors' ->> 0), '; ')
        from jsonb_array_elements(v_workflows) e where jsonb_array_length(e.value -> 'errors') > 0)
      using errcode = '22023', hint = 'TEMPLATE_WORKFLOW_INPUT_INVALID';
  end if;
  select coalesce(jsonb_agg(e.value - 'errors'), '[]'::jsonb) into v_workflows from jsonb_array_elements(v_workflows) e;

  return jsonb_build_object(
    'template', jsonb_build_object(
    'id', v_tpl."id",
    'tenant', v_tpl."tenant_id",
    'scope', v_tpl."scope",
    'brand', v_tpl."brand",
    'key', v_tpl."key",
    'type', v_tpl."type",
    'name', v_tpl."name",
    'language', v_tpl."language",
    'isDefault', v_tpl."is_default",
    'settings', v_tpl."settings",
    'forkedFrom', v_tpl."forked_from",
    'forkedFromVersion', v_tpl."forked_from_version",
    'publishedVersion', (select y."version" from "better_supabase"."template_versions" y where y."template_id" = v_tpl."id" and y."published_at" is not null order by y."version" desc limit 1),
    'upstreamVersion', case when v_tpl."forked_from" is not null then (select y."version" from "better_supabase"."template_versions" y where y."template_id" = v_tpl."forked_from" and y."published_at" is not null order by y."version" desc limit 1) end,
    'createdBy', v_tpl."created_by",
    'createdAt', v_tpl."created_at",
    'updatedAt', v_tpl."updated_at"
  ),
    'version', jsonb_build_object(
    'id', v_version."id",
    'template', v_version."template_id",
    'version', v_version."version",
    'hash', v_version."hash",
    'publishedAt', v_version."published_at",
    'createdBy', v_version."created_by",
    'createdAt', v_version."created_at",
    'body', v_version."body"
  ),
    'workflows', v_workflows
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.template_brand (
  tenant uuid
)
  RETURNS text
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select b."brand"::text from "public"."organizations" b
  where b."id" = template_brand.tenant
    and (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', template_brand.tenant, 'templates.read'), false))
  limit 1
$function$;

CREATE OR REPLACE FUNCTION better_supabase.template_get (
  template_id uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select jsonb_build_object(
    'id', x."id",
    'tenant', x."tenant_id",
    'scope', x."scope",
    'brand', x."brand",
    'key', x."key",
    'type', x."type",
    'name', x."name",
    'language', x."language",
    'isDefault', x."is_default",
    'settings', x."settings",
    'forkedFrom', x."forked_from",
    'forkedFromVersion', x."forked_from_version",
    'publishedVersion', (select y."version" from "better_supabase"."template_versions" y where y."template_id" = x."id" and y."published_at" is not null order by y."version" desc limit 1),
    'upstreamVersion', case when x."forked_from" is not null then (select y."version" from "better_supabase"."template_versions" y where y."template_id" = x."forked_from" and y."published_at" is not null order by y."version" desc limit 1) end,
    'createdBy', x."created_by",
    'createdAt', x."created_at",
    'updatedAt', x."updated_at"
  ) || jsonb_build_object(
    'published', (select jsonb_build_object(
    'id', y."id",
    'template', y."template_id",
    'version', y."version",
    'hash', y."hash",
    'publishedAt', y."published_at",
    'createdBy', y."created_by",
    'createdAt', y."created_at",
    'body', y."body"
  ) from "better_supabase"."template_versions" y
      where y."template_id" = x."id" and y."published_at" is not null
      order by y."version" desc limit 1),
    'draft', (select jsonb_build_object(
    'id', y."id",
    'template', y."template_id",
    'version', y."version",
    'hash', y."hash",
    'publishedAt', y."published_at",
    'createdBy', y."created_by",
    'createdAt', y."created_at",
    'body', y."body"
  ) from "better_supabase"."template_versions" y
      where y."template_id" = x."id" and y."published_at" is null))
  from "better_supabase"."templates" x
  where x."id" = template_get.template_id
$function$;

CREATE OR REPLACE FUNCTION better_supabase.template_row_guard()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  if new.template_id is distinct from old.template_id then
    raise exception 'A row cannot change between a template and a live record' using errcode = '23514', hint = 'TEMPLATE_IMMUTABLE';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.template_schedule_removed()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  delete from "better_supabase"."recurrence_rules" u where u."tenant_id" = old."tenant_id"
      and u."subject_type" = 'template_schedule'
      and u."subject_id" = old."id"::text;
  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.template_schedules_list (
  tenant      uuid,
  template_id uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', template_schedules_list.tenant, 'templates.read'), false)) then
    raise exception 'You may not read schedules here' using errcode = '42501', hint = 'TEMPLATE_FORBIDDEN';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
    'id', x."id",
    'template', x."template_id",
    'tenant', x."tenant_id",
    'input', x."input",
    'enabled', x."enabled",
    'dtstart', u."dtstart",
    'tzid', u."tzid",
    'rrule', u."rrule",
    'createdBy', x."created_by",
    'createdAt', x."created_at",
    'updatedAt', x."updated_at"
  ) order by x."created_at", x."id"), '[]'::jsonb)
    from "better_supabase"."template_schedules" x
    left join "better_supabase"."recurrence_rules" u on u."tenant_id" = x."tenant_id"
      and u."subject_type" = 'template_schedule'
      and u."subject_id" = x."id"::text
    where x."tenant_id" = template_schedules_list.tenant
      and (template_schedules_list.template_id is null or x."template_id" = template_schedules_list.template_id)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.template_table (
  target regclass
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  execute format('alter table %s add column if not exists template_id uuid unique references "better_supabase"."templates" (id) on delete cascade', target);
  execute format('alter table %s add column if not exists source_template_id uuid references "better_supabase"."templates" (id) on delete set null', target);
  execute format('drop trigger if exists bsb_template_row on %s', target);
  execute format('create trigger bsb_template_row before update of template_id on %s for each row execute function "better_supabase"."template_row_guard"()', target);
end;
$function$;

