CREATE OR REPLACE FUNCTION better_supabase.tenant_entitlement_value (
  tenant uuid,
  key    text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(to_jsonb(f."value"), 'true'::jsonb)
    from "public"."subscriptions" s
    join "public"."plan_features" f on f."plan_key"::text = s."plan_key"::text
    where s."organization_id" = tenant_entitlement_value.tenant
      and s."status"::text = any (array['active', 'trialing']::text[])
      and f."included"
      and f."feature_key"::text = tenant_entitlement_value.key
    order by case when jsonb_typeof(to_jsonb(f."value")) = 'number' then (to_jsonb(f."value") #>> '{}')::numeric end desc nulls last,
      s."plan_key"::text
    limit 1
$function$;

CREATE OR REPLACE FUNCTION better_supabase.tenant_entitlements (
  tenant uuid
)
  RETURNS text[]
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(array_agg(distinct f."feature_key"::text order by f."feature_key"::text), '{}')
    from "public"."subscriptions" s
    join "public"."plan_features" f on f."plan_key"::text = s."plan_key"::text
    where s."organization_id" = tenant_entitlements.tenant
      and s."status"::text = any (array['active', 'trialing']::text[])
      and f."included"
      and f."feature_key" is not null
$function$;

CREATE OR REPLACE FUNCTION better_supabase.tenant_ids_with (
  permission text
)
  RETURNS SETOF uuid
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  ROWS 1
  SET search_path TO ''
  AS $function$
  select m."organization_id"
  from "public"."memberships" m
  where m."user_id" = (select auth.uid())
    and not better_supabase.user_disabled(auth.uid())
    and not better_supabase.tenant_disabled(m."organization_id")
    and better_supabase.cap_allows(tenant_ids_with.permission)
    and exists (select 1 from "better_supabase"."permissions" p where p."key" = tenant_ids_with.permission and coalesce(
      (select bool_and(o."granted") from "better_supabase"."permission_overrides" o
        where o."tenant_id" = m."organization_id"
          and o."role_id" = m."role"
          and o."permission_id" = p."id"),
      exists (select 1 from "better_supabase"."role_permissions" rp where rp."role_id" = m."role" and rp."permission_id" = p."id")
    ))
$function$;

