CREATE OR REPLACE FUNCTION better_supabase.terminate_lease (
  lease_id          uuid,
  terminates_on     date   DEFAULT NULL::date,
  reason            text   DEFAULT NULL::text,
  deposit_deduction bigint DEFAULT 0
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row "better_supabase"."leases"%rowtype;
  v_on date := coalesce(terminate_lease.terminates_on, current_date);
  v_deduction bigint := coalesce(terminate_lease.deposit_deduction, 0);
  v_held bigint;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select * into v_row from "better_supabase"."leases" x where x."id" = terminate_lease.lease_id for update;
  if not found or not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", 'leases.manage'), false)) then
    raise exception 'no such lease you can read' using errcode = 'P0002', hint = 'LEASE_NOT_FOUND';
  end if;
  if v_row."status" not in ('draft', 'active') then
    raise exception 'this lease has already ended' using errcode = '55000', hint = 'LEASE_STATUS_INVALID';
  end if;
  if v_on < v_row."starts_on" and v_row."status" = 'active' then
    raise exception 'a lease can''t end before it starts' using errcode = '22023', hint = 'LEASE_TERMS_INVALID';
  end if;
  if exists (select 1 from "better_supabase"."lease_charges" y where y."lease_id" = v_row."id" and y."period_start" >= v_on) then
    raise exception 'rent is already posted for a period from this date; pick a later date' using errcode = '22023', hint = 'LEASE_TERMS_INVALID';
  end if;
  v_held := coalesce((select h."amount" from "better_supabase"."ledger_holds" h where h."id" = v_row."deposit_hold_id" and h."status" = 'active'), 0);
  if v_deduction < 0 or v_deduction > v_held then
    raise exception 'a deduction is zero or more and at most the deposit held' using errcode = '22023', hint = 'LEASE_DEPOSIT_INVALID';
  end if;
  if v_held > 0 then
    if v_deduction > 0 then
      perform "better_supabase"."ledger_capture"(v_row."deposit_hold_id", "better_supabase"."ledger_account_for"(v_row."tenant_id", 'rent_income', 'leases.income:' || v_row."currency", 'Rent income ' || v_row."currency",
      v_row."currency"::text, 0::smallint, null, null, null, true, 'leases.read', 'leases', null), v_deduction, 'lease.deposit_deduction', 'Deposit deduction');
    else
      perform "better_supabase"."ledger_release"(v_row."deposit_hold_id");
    end if;
    if v_held - v_deduction > 0 then
      perform "better_supabase"."ledger_post"(v_row."tenant_id", 'lease.deposit_refund',
        jsonb_build_array(
          jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_row."tenant_id", 'rent_deposit', 'leases.deposit:' || v_row."id"::text, 'Deposit ' || v_row."title",
      v_row."currency"::text, 0::smallint, 'lease', v_row."id"::text, null, false, 'leases.read', 'leases',
      jsonb_build_object('leaseId', v_row."id")), 'amount', -(v_held - v_deduction)),
          jsonb_build_object('account', "better_supabase"."ledger_account_for"(v_row."tenant_id", 'rent_cash', 'leases.cash:' || v_row."currency", 'Rent received ' || v_row."currency",
      v_row."currency"::text, 0::smallint, null, null, null, true, 'leases.read', 'leases', null), 'amount', v_held - v_deduction)),
        'leases', v_row."id"::text, 'Deposit refunded', 'leases.deposit_refund:' || v_row."id"::text, null,
        jsonb_build_object('leaseId', v_row."id"));
    end if;
  end if;
  update "better_supabase"."leases" x set
      "status" = case when x."status" = 'active' and x."ends_on" is not null and v_on >= x."ends_on" then 'ended' else 'terminated' end,
      "terminated_on" = v_on, "termination_reason" = nullif(trim(terminate_lease.reason), ''), "updated_at" = now()
    where x."id" = v_row."id"
    returning * into v_row;
  perform "better_supabase".emit_event('lease.terminated', jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'unitId', v_row."unit_id", 'partyType', v_row."party_type", 'partyId', v_row."party_id", 'status', v_row."status", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'rent', v_row."rent"::text, 'currency', v_row."currency"), 'leases/' || v_row."id"::text, (v_row."tenant_id")::text, null, 'better-supabase/leases');
  perform better_supabase.audit_event(
    event_type => 'lease.terminated',
    category => 'billing',
    target_type => 'lease',
    record_id => v_row."id"::text,
    target_label => v_row."title",
    summary => 'ended a lease',
    tenant => (v_row."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_row."tenant_id", 'id', v_row."id", 'unitId', v_row."unit_id", 'partyType', v_row."party_type", 'partyId', v_row."party_id", 'status', v_row."status", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'rent', v_row."rent"::text, 'currency', v_row."currency")
  );
  return jsonb_build_object('id', v_row."id", 'organizationId', v_row."tenant_id", 'unitId', v_row."unit_id", 'partyType', v_row."party_type", 'partyId', v_row."party_id", 'title', v_row."title", 'status', v_row."status", 'startsOn', v_row."starts_on", 'endsOn', v_row."ends_on", 'rent', v_row."rent"::text, 'currency', v_row."currency", 'frequency', v_row."frequency", 'deposit', v_row."deposit"::text, 'depositHoldId', v_row."deposit_hold_id", 'depositHeld', coalesce((select h."amount" from "better_supabase"."ledger_holds" h where h."id" = v_row."deposit_hold_id" and h."status" = 'active'), 0)::text, 'balanceDue', coalesce((select y."balance" from "better_supabase"."ledger_accounts" x join "better_supabase"."ledger_balances" y on y."account_id" = x."id"
      where x."tenant_id" = v_row."tenant_id" and x."code" = 'leases.rent:' || v_row."id"::text), 0)::text, 'renewedAt', v_row."renewed_at", 'terminatedOn', v_row."terminated_on", 'terminationReason', v_row."termination_reason", 'metadata', v_row."metadata", 'createdBy', v_row."created_by", 'createdAt', v_row."created_at", 'updatedAt', v_row."updated_at");
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.thread_summary (
  conversation uuid DEFAULT NULL::uuid,
  thread       uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select to_jsonb(s) || jsonb_build_object(
    'stale', exists (
      select 1 from "better_supabase"."messages" m
      where m."conversation_id" = s."conversation_id"
        and m."kind" = 'message' and m."sent_at" is not null
        and case when s."thread_id" is null then m."thread_id" is null
          else m."id" = s."thread_id" or m."thread_id" = s."thread_id" end
        and (m."sent_at" > s."through_at"
          or m."edited_at" > s."updated_at"
          or m."archived_at" > s."updated_at")
    )
  )
  from "better_supabase"."thread_summaries" s
  where s."conversation_id" = coalesce(thread_summary.conversation,
      (select m."conversation_id" from "better_supabase"."messages" m where m."id" = thread_summary.thread))
    and s."thread_id" is not distinct from thread_summary.thread
$function$;

CREATE OR REPLACE FUNCTION better_supabase.time_entry_guard()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  -- Only a change to logged time (options.lockedColumns) touches the week.
  if tg_op = 'UPDATE' and (new."started_at", new."ended_at", new."subject_type", new."subject_id", new."user_id", new."rate", new."rate_currency") is not distinct from (old."started_at", old."ended_at", old."subject_type", old."subject_id", old."user_id", old."rate", old."rate_currency") then
    return new;
  end if;
  if tg_op in ('UPDATE', 'DELETE') and "better_supabase"."time_week_locked"(old."tenant_id", old."user_id", old."started_at") then
    raise exception 'this week''s timesheet is submitted or approved' using errcode = '55000', hint = 'TIME_PERIOD_LOCKED';
  end if;
  if tg_op in ('INSERT', 'UPDATE') and "better_supabase"."time_week_locked"(new."tenant_id", new."user_id", new."started_at") then
    raise exception 'this week''s timesheet is submitted or approved' using errcode = '55000', hint = 'TIME_PERIOD_LOCKED';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.time_lines_for_invoice (
  tenant   uuid,
  scope    jsonb,
  group_by text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_scope jsonb := coalesce(time_lines_for_invoice.scope, '{}'::jsonb);
  v_group text := coalesce(time_lines_for_invoice.group_by, 'subject');
begin
  if v_group not in ('subject', 'member', 'entry') then
    raise exception 'group_by is subject, member or entry' using errcode = '22023', hint = 'BILLABLE_TIME_GROUPING_INVALID';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('description', l.description, 'quantity', l.quantity::text, 'unitAmount', l.rate::text,
      'currency', l.currency, 'entryIds', l.entry_ids) order by l.first_at)
    from (
    select min(u.started_at) as first_at, u.currency, u.rate,
      round(sum(u.seconds) / 3600.0, 4) as quantity,
      jsonb_agg(u.id order by u.started_at, u.id) as entry_ids,
      case when v_group = 'entry' then min(u.user_id::text) end as user_text,
      case when v_group = 'member' then min(u.user_id::text) end as member_text,
      min(u.subject_type) as subject_type, min(u.subject_id) as subject_id,
      case
        when v_group = 'entry' then coalesce(min(u.note), 'Time on ' || to_char(min(u.started_at) at time zone 'UTC', 'YYYY-MM-DD'))
        when min(u.subject_type) is null then 'Time'
        else 'Time on ' || min(u.subject_type) || ' ' || min(u.subject_id)
      end as description
    from (
    select x."id" as id, x."user_id" as user_id, x."subject_type" as subject_type, x."subject_id" as subject_id,
      x."started_at" as started_at, x."note" as note, extract(epoch from x."ended_at" - x."started_at") as seconds,
      coalesce(x."rate", card.rate) as rate, coalesce(x."rate_currency", card.currency) as currency
    from "better_supabase"."time_entries" x
    left join lateral (
      select c."rate" as rate, c."currency"::text as currency
      from "better_supabase"."time_rates" c
      where c."tenant_id" = x."tenant_id"
        and (c."user_id" is null or c."user_id" = x."user_id")
        and (c."subject_type" is null or (c."subject_type" = x."subject_type" and c."subject_id" = x."subject_id"))
        and c."effective_from" <= (x."started_at" at time zone 'UTC')::date
      order by (c."subject_type" is not null) desc, (c."user_id" is not null) desc, c."effective_from" desc
      limit 1
    ) card on x."rate" is null
    where x."tenant_id" = time_lines_for_invoice.tenant
      and x."billable" and x."ended_at" is not null
      and not exists (select 1 from "better_supabase"."time_invoice_entries" d where d."entry_id" = x."id")
      and (v_scope -> 'subject' is null or (x."subject_type" = v_scope -> 'subject' ->> 'type' and x."subject_id" = v_scope -> 'subject' ->> 'id'))
      and (v_scope ->> 'userId' is null or x."user_id" = (v_scope ->> 'userId')::uuid)
      and (v_scope ->> 'starts' is null or x."started_at" >= (v_scope ->> 'starts')::timestamptz)
      and (v_scope ->> 'ends' is null or x."started_at" < (v_scope ->> 'ends')::timestamptz)
      and (v_scope -> 'entryIds' is null or x."id"::text in (select jsonb_array_elements_text(v_scope -> 'entryIds')))) u
    where u.rate is not null
    group by u.currency, u.rate, u.subject_type, u.subject_id,
      case when v_group in ('member', 'entry') then u.user_id end,
      case when v_group = 'entry' then u.id end
    having round(sum(u.seconds) / 3600.0, 4) > 0) l), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.time_rate (
  tenant       uuid,
  user_id      uuid DEFAULT NULL::uuid,
  subject_type text DEFAULT NULL::text,
  subject_id   text DEFAULT NULL::text,
  on_day       date DEFAULT NULL::date
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', time_rate.tenant, 'billable_time.read'), false)) then
    raise exception 'not allowed to read the rate card' using errcode = '42501', hint = 'BILLABLE_TIME_FORBIDDEN';
  end if;
  return (
    select jsonb_build_object('id', c."id", 'organizationId', c."tenant_id", 'userId', c."user_id", 'subjectType', c."subject_type", 'subjectId', c."subject_id", 'rate', c."rate"::text, 'currency', c."currency", 'effectiveFrom', c."effective_from", 'cost', c."cost_amount"::text, 'createdBy', c."created_by", 'createdAt', c."created_at") from "better_supabase"."time_rates" c
    where c."tenant_id" = time_rate.tenant
      and (c."user_id" is null or c."user_id" = time_rate.user_id)
      and (c."subject_type" is null or (c."subject_type" = time_rate.subject_type and c."subject_id" = time_rate.subject_id))
      and c."effective_from" <= coalesce(time_rate.on_day, current_date)
    order by (c."subject_type" is not null) desc, (c."user_id" is not null) desc, c."effective_from" desc
    limit 1
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.time_week (
  at timestamp with time zone
)
  RETURNS date
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select (date_trunc('week', time_week.at at time zone 'UTC'))::date;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.time_week_approved (
  tenant  uuid,
  user_id uuid,
  at      timestamp with time zone
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from "better_supabase"."timesheets" s
    where s."tenant_id" = time_week_approved.tenant and s."user_id" = time_week_approved.user_id
      and s."week" = "better_supabase"."time_week"(time_week_approved.at)
      and s."approved_at" is not null
  );
$function$;

CREATE OR REPLACE FUNCTION better_supabase.time_week_locked (
  tenant  uuid,
  user_id uuid,
  at      timestamp with time zone
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1 from "better_supabase"."timesheets" s
    left join "better_supabase"."approval_requests" x on x."id" = s."approval_id"
    where s."tenant_id" = time_week_locked.tenant and s."user_id" = time_week_locked.user_id
      and s."week" = "better_supabase"."time_week"(time_week_locked.at)
      and (s."approved_at" is not null or x."status" = 'pending')
  );
$function$;

CREATE OR REPLACE FUNCTION better_supabase.top_scores (
  tenant    uuid,
  model_key text,
  band      text    DEFAULT NULL::text,
  min_score numeric DEFAULT NULL::numeric,
  page_size integer DEFAULT 50
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', top_scores.tenant, 'scores.read'), false)) then
    raise exception 'not allowed to read scores' using errcode = '42501', hint = 'SCORES_FORBIDDEN';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', z."id", 'organizationId', z."tenant_id", 'modelId', z."model_id", 'modelKey', top_scores.model_key, 'modelVersion', z."model_version", 'subjectType', z."subject_type", 'subjectId', z."subject_id", 'score', z."score", 'band', z."band", 'breakdown', z."breakdown", 'current', z."is_current", 'computedAt', z."computed_at") order by z."score" desc, z."computed_at" desc)
    from (
      select x.*
      from "better_supabase"."scores" x join "better_supabase"."score_models" y on y."id" = x."model_id"
      where x."tenant_id" = top_scores.tenant and y."key" = top_scores.model_key and x."is_current"
        and (top_scores.band is null or x."band" = top_scores.band)
        and (top_scores.min_score is null or x."score" >= top_scores.min_score)
      order by x."score" desc, x."computed_at" desc
      limit least(greatest(coalesce(top_scores.page_size, 50), 1), 200)
    ) z
  ), '[]'::jsonb);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.touch_ai_sandbox (
  id uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  update "better_supabase"."ai_sandboxes" x set "last_used_at" = now(), "updated_at" = now()
  where x."id" = touch_ai_sandbox.id and x."status" = 'running';
  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.track_events (
  target        regclass,
  type_prefix   text     DEFAULT NULL::text,
  tenant_column text     DEFAULT NULL::text
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  execute format('drop trigger if exists "bsb_outbox_events" on %s', target);
  execute format('drop trigger if exists "bsb_outbox_events_update" on %s', target);
  execute format(
    'create trigger "bsb_outbox_events" after insert or delete on %s for each row execute function "better_supabase"."outbox_row_event"(%L, %L)',
    target, coalesce(type_prefix, ''), coalesce(tenant_column, '')
  );
  -- jsonb, not the row: a row comparison fails on columns without equality (json).
  execute format(
    'create trigger "bsb_outbox_events_update" after update on %s for each row when (to_jsonb(old) is distinct from to_jsonb(new)) execute function "better_supabase"."outbox_row_event"(%L, %L)',
    target, coalesce(type_prefix, ''), coalesce(tenant_column, '')
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.track_mail (
  hash       text,
  kind       text,
  link       integer,
  user_agent text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_message record;
  v_url text;
  v_event uuid;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) then
    raise exception 'only the service role records tracking' using errcode = '42501', hint = 'MAIL_FORBIDDEN';
  end if;
  if track_mail.kind is null or track_mail.kind not in ('open', 'click') then
    raise exception 'kind is open or click' using errcode = '22023', hint = 'MAIL_TRACKING_INVALID';
  end if;
  select y."id" as id, y."tenant_id" as tenant, y."account_id" as account, y."thread_id" as thread,
    y."template_version_id" as template, y."opened_at" as opened, x."user_id" as owner
  into v_message
  from "better_supabase"."mail_messages" y join "better_supabase"."mail_accounts" x on x."id" = y."account_id"
  where y."tracking_hash" = lower(track_mail.hash) and y."direction" = 'outbound';
  if v_message.id is null then
    return null;
  end if;
  if track_mail.kind = 'click' then
    update "better_supabase"."mail_tracked_links" u set "click_count" = u."click_count" + 1
    where u."message_id" = v_message.id and u."position" = track_mail.link
    returning u."url" into v_url;
    if v_url is null then
      return null;
    end if;
  end if;
  insert into "better_supabase"."mail_tracking_events" ("tenant_id", "message_id", "kind", "position", "user_agent")
  values (v_message.tenant, v_message.id, track_mail.kind, case when track_mail.kind = 'click' then track_mail.link end, left(track_mail.user_agent, 300))
  returning "id" into v_event;
  update "better_supabase"."mail_messages" y set
    "opened_at" = coalesce(y."opened_at", now()),
    "open_count" = y."open_count" + case when track_mail.kind = 'open' then 1 else 0 end,
    "clicked_at" = case when track_mail.kind = 'click' then coalesce(y."clicked_at", now()) else y."clicked_at" end,
    "click_count" = y."click_count" + case when track_mail.kind = 'click' then 1 else 0 end
  where y."id" = v_message.id;
  if track_mail.kind = 'click' then
    perform "better_supabase".emit_event('mail_message.clicked', jsonb_build_object('organizationId', v_message.tenant, 'accountId', v_message.account, 'userId', v_message.owner, 'threadId', v_message.thread, 'messageId', v_message.id, 'templateVersionId', v_message.template, 'url', v_url, 'subjects', coalesce((select jsonb_agg(jsonb_build_object('type', s."subject_type", 'id', s."subject_id") order by s."created_at", s."subject_type", s."subject_id") from "better_supabase"."mail_thread_subjects" s where s."thread_id" = v_message.thread), '[]'::jsonb)), 'mail-messages/' || v_message.id, (v_message.tenant::text)::text, 'mail_message_clicked:' || v_event, 'better-supabase/mail-sync');
  elsif v_message.opened is null then
    perform "better_supabase".emit_event('mail_message.opened', jsonb_build_object('organizationId', v_message.tenant, 'accountId', v_message.account, 'userId', v_message.owner, 'threadId', v_message.thread, 'messageId', v_message.id, 'templateVersionId', v_message.template, 'url', null::text, 'subjects', coalesce((select jsonb_agg(jsonb_build_object('type', s."subject_type", 'id', s."subject_id") order by s."created_at", s."subject_type", s."subject_id") from "better_supabase"."mail_thread_subjects" s where s."thread_id" = v_message.thread), '[]'::jsonb)), 'mail-messages/' || v_message.id, (v_message.tenant::text)::text, 'mail_message_opened:' || v_message.id, 'better-supabase/mail-sync');
  end if;
  return jsonb_build_object('messageId', v_message.id, 'url', v_url);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.track_realtime (
  target        regclass,
  tenant_column text     DEFAULT NULL::text,
  user_column   text     DEFAULT NULL::text
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  scope_column text := coalesce(user_column, tenant_column);
  scope_kind text := case when user_column is null then 'tenant' else 'user' end;
begin
  if scope_column is not null and not exists (
    select 1 from pg_catalog.pg_attribute a
    where a.attrelid = target and a.attname = scope_column and a.attnum > 0 and not a.attisdropped
  ) then
    raise exception '% has no column %', target, scope_column
      using errcode = '42703',
        hint = case when user_column is null
          then 'Add the tenant column, or list the table in realtime.global to broadcast it to every signed-in user'
          else 'Check the column in realtime.users' end;
  end if;
  execute format('drop trigger if exists bsb_realtime on %s', target);
  execute format('drop trigger if exists bsb_realtime_insert on %s', target);
  execute format('drop trigger if exists bsb_realtime_update on %s', target);
  execute format('drop trigger if exists bsb_realtime_delete on %s', target);
  if scope_column is null then
    execute format(
      'create trigger bsb_realtime after insert or update or delete on %s for each statement execute function better_supabase.broadcast_changes()',
      target
    );
    return;
  end if;
  execute format(
    'create trigger bsb_realtime_insert after insert on %s referencing new table as new_rows for each statement execute function better_supabase.broadcast_changes(%L, %L)',
    target, scope_column, scope_kind
  );
  execute format(
    'create trigger bsb_realtime_update after update on %s referencing old table as old_rows new table as new_rows for each statement execute function better_supabase.broadcast_changes(%L, %L)',
    target, scope_column, scope_kind
  );
  execute format(
    'create trigger bsb_realtime_delete after delete on %s referencing old table as old_rows for each statement execute function better_supabase.broadcast_changes(%L, %L)',
    target, scope_column, scope_kind
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.track_slug (
  target      regclass,
  column_name text     DEFAULT 'slug'::text
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  execute format('drop trigger if exists bsb_slug on %s', target);
  execute format(
    'create trigger bsb_slug before insert or update of %I on %s for each row execute function better_supabase.enforce_slug(%L)',
    column_name,
    target,
    column_name
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.track_updated_at (
  target          regclass,
  column_name     text     DEFAULT 'updated_at'::text,
  replace_trigger boolean  DEFAULT false
)
  RETURNS void
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
begin
  perform better_supabase.replace_equivalent_triggers(
    target, 'bsb_updated_at', 'updated_at|moddatetime|touch', replace_trigger
  );
  execute format('drop trigger if exists bsb_updated_at on %s', target);
  execute format(
    'create trigger bsb_updated_at before update on %s for each row execute function better_supabase.set_updated_at(%L)',
    target,
    column_name
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.transfer_allocation (
  allocation    uuid,
  document_type text,
  document_id   text,
  line_id       text    DEFAULT NULL::text,
  quantity      numeric DEFAULT NULL::numeric
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_row record;
  v_left numeric;
  v_held numeric;
  v_new uuid;
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  select x."id" as id, x."tenant_id" as tenant, x."variant_id" as variant, x."location_id" as location,
    x."document_type" as document_type, x."document_id" as document_id, x."quantity" as quantity,
    x."allocated" as allocated, x."fulfilled" as fulfilled, x."status" as status
  into v_row from "better_supabase"."stock_allocations" x where x."id" = transfer_allocation.allocation for update;
  if not found then
    raise exception 'allocation not found' using errcode = 'P0002', hint = 'INVENTORY_ALLOCATION_NOT_FOUND';
  end if;
  if not (auth.role() = 'service_role' or coalesce(better_supabase.can('tenant', v_row.tenant, 'inventory.reserve'), false)) then
    raise exception 'not allowed to change this inventory' using errcode = '42501', hint = 'INVENTORY_FORBIDDEN';
  end if;
  if v_row.status <> 'open' then
    raise exception 'the allocation is no longer open' using errcode = '55000', hint = 'INVENTORY_ALLOCATION_CLOSED';
  end if;
  if transfer_allocation.document_type is null or transfer_allocation.document_id is null then
    raise exception 'an allocation names its document type and id' using errcode = '22023', hint = 'INVENTORY_DOCUMENT_INVALID';
  end if;
  v_left := v_row.quantity - v_row.fulfilled;
  if transfer_allocation.quantity is not null
    and (transfer_allocation.quantity <= 0 or transfer_allocation.quantity > v_left) then
    raise exception 'the quantity must be more than zero and at most what the allocation has left' using errcode = '22023', hint = 'INVENTORY_QUANTITY_INVALID';
  end if;
  if transfer_allocation.quantity is null or transfer_allocation.quantity = v_left then
    update "better_supabase"."stock_allocations" x set "document_type" = transfer_allocation.document_type, "document_id" = transfer_allocation.document_id,
      "line_id" = transfer_allocation.line_id, "updated_at" = now()
    where x."id" = v_row.id;
    v_new := v_row.id;
  else
    v_held := least(transfer_allocation.quantity, v_row.allocated);
    update "better_supabase"."stock_allocations" x set "allocated" = x."allocated" - v_held,
      "quantity" = x."quantity" - transfer_allocation.quantity, "updated_at" = now()
    where x."id" = v_row.id;
    insert into "better_supabase"."stock_allocations" ("tenant_id", "variant_id", "location_id", "document_type", "document_id", "line_id", "quantity", "allocated")
    values (v_row.tenant, v_row.variant, v_row.location, transfer_allocation.document_type, transfer_allocation.document_id,
      transfer_allocation.line_id, transfer_allocation.quantity, v_held)
    returning "id" into v_new;
  end if;
  perform "better_supabase".emit_event('allocation.transferred', jsonb_build_object('organizationId', v_row.tenant, 'id', v_row.id, 'variantId', v_row.variant, 'locationId', v_row.location,
        'documentType', v_row.document_type, 'documentId', v_row.document_id, 'quantity', v_row.quantity::text, 'toDocumentType', transfer_allocation.document_type, 'toDocumentId', transfer_allocation.document_id, 'transferred', coalesce(transfer_allocation.quantity, v_left)::text), 'stock-allocations/' || v_row.id::text, (v_row.tenant)::text, null, 'better-supabase/inventory');
  return (select jsonb_build_object('id', x."id", 'variantId', x."variant_id", 'locationId', x."location_id",
    'documentType', x."document_type", 'documentId', x."document_id", 'lineId', x."line_id",
    'quantity', x."quantity"::text, 'allocated', x."allocated"::text, 'fulfilled', x."fulfilled"::text,
    'backordered', x."backordered"::text, 'status', x."status", 'createdAt', x."created_at") from "better_supabase"."stock_allocations" x where x."id" = v_new);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.transfer_ownership (
  organization uuid,
  new_owner    uuid,
  former_role  text DEFAULT 'admin'::text
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  me uuid := auth.uid();
begin
  if not (better_supabase.actor_may_write()) then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.member_can(auth.uid(), organization, 'organization.transfer_ownership'), false)) then
    raise exception 'Not allowed to transfer ownership' using errcode = '42501', hint = 'ORGANIZATION_FORBIDDEN';
  end if;
  -- Only an owner hands ownership on, so the permission alone can't make its
  -- holder an owner.
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin')) and not exists (
    select 1 from "public"."memberships" m where m."organization_id" = organization and m."user_id" = me and (select r."key" from "better_supabase"."roles" r where r."id" = m."role") = 'owner'
  ) then
    raise exception 'Only an owner can transfer ownership' using errcode = '42501', hint = 'ORGANIZATION_FORBIDDEN';
  end if;
  if not (exists (select 1 from "public"."organizations" o where o."id" = organization) and not better_supabase.tenant_disabled(organization)) then
    raise exception 'The organization is unavailable' using errcode = '42501', hint = 'ORGANIZATION_DISABLED';
  end if;
  if not ((select r."id" from "better_supabase"."roles" r where (r."id"::text = (former_role)::text or r."key" = (former_role)::text) order by (r."id"::text = (former_role)::text) desc limit 1) is not null) then
    raise exception 'Unknown role %', former_role using errcode = '22023', hint = 'ORGANIZATION_ROLE_UNKNOWN';
  end if;
  if not exists (select 1 from "public"."memberships" m where m."organization_id" = organization and m."user_id" = new_owner) then
    raise exception 'The new owner must be a member' using errcode = 'P0002', hint = 'ORGANIZATION_NOT_MEMBER';
  end if;
  if better_supabase.user_disabled(new_owner) then
    raise exception 'The new owner is disabled' using errcode = '42501', hint = 'ORGANIZATION_FORBIDDEN';
  end if;
  -- One statement for both rows, so a statement-level guard on the number of
  -- owners sees the transfer as a whole.
  update "public"."memberships" m set "role" = case
      when m."user_id" = new_owner then (select r."id" from "better_supabase"."roles" r where (r."id"::text = ('owner')::text or r."key" = ('owner')::text) order by (r."id"::text = ('owner')::text) desc limit 1)
      else (select r."id" from "better_supabase"."roles" r where (r."id"::text = (former_role)::text or r."key" = (former_role)::text) order by (r."id"::text = (former_role)::text) desc limit 1)
    end
  where m."organization_id" = organization
    and (m."user_id" = new_owner
      or (me is not null and me <> new_owner and m."user_id" = me and (select r."key" from "better_supabase"."roles" r where r."id" = m."role") = 'owner'));
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_member_change"(uuid, uuid, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::uuid, $3::text)', v_hook::oid::regproc)
        using organization, new_owner, 'owner';
    end if;
  end;
  perform "better_supabase".emit_event('organization.ownership_transferred', jsonb_build_object('organizationId', organization::text, 'userId', new_owner, 'role', 'owner'), 'organizations/' || organization::text, (organization)::text, null, 'better-supabase/organizations');
  perform better_supabase.audit_event(
    event_type => 'organization.ownership_transferred',
    category => 'membership',
    target_type => 'user',
    record_id => new_owner::text,
    tenant => (organization)::uuid,
    metadata => jsonb_build_object('organizationId', organization::text, 'userId', new_owner, 'role', 'owner')
  );
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.transition (
  subject_type text,
  subject_id   text,
  to_status    text,
  reason       text  DEFAULT NULL::text,
  actor        jsonb DEFAULT NULL::jsonb
)
  RETURNS boolean
  LANGUAGE plpgsql
  SET search_path TO ''
  AS $function$
declare
  v_found boolean;
begin
  perform set_config('better_supabase.transition_reason', coalesce(transition.reason, ''), true);
  if transition.actor is not null then
    if jsonb_typeof(transition.actor) <> 'object' then
      raise exception 'actor must be an object of id, name, email, ip and userAgent' using errcode = '22023', hint = 'STATE_ACTOR_INVALID';
    end if;
    begin
      perform nullif(transition.actor ->> 'ip', '')::inet, nullif(transition.actor ->> 'id', '')::uuid;
    exception when invalid_text_representation then
      raise exception 'actor.ip must be an IP address and actor.id a user id' using errcode = '22023', hint = 'STATE_ACTOR_INVALID';
    end;
  end if;
  perform set_config('better_supabase.transition_actor', coalesce(transition.actor::text, ''), true);
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_status_transition"(text, text, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::text, $2::text, $3::text)', v_hook::oid::regproc)
        using transition.subject_type, transition.subject_id, transition.to_status;
    end if;
  end;
  case transition.subject_type
    when 'work_item' then
      update "better_supabase"."work_items" s set "state" = better_supabase.as_column_type(transition.to_status, (null::"better_supabase"."work_items")."state")
      where s."id" = (transition.subject_id)::uuid;
    when 'change_request' then
      update "public"."change_requests" s set "status" = better_supabase.as_column_type(transition.to_status, (null::"public"."change_requests")."status")
      where s."id" = (transition.subject_id)::uuid;
    when 'drive_node' then
      update "better_supabase"."drive_nodes" s set "document_status" = better_supabase.as_column_type(transition.to_status, (null::"better_supabase"."drive_nodes")."document_status")
      where s."id" = (transition.subject_id)::uuid;
    when 'warranty_claim' then
      update "better_supabase"."warranty_claims" s set "status" = better_supabase.as_column_type(transition.to_status, (null::"better_supabase"."warranty_claims")."status")
      where s."id" = (transition.subject_id)::uuid;
    else
      raise exception 'unknown subject' using errcode = '22023', hint = 'STATE_MACHINE_UNKNOWN';
  end case;
  v_found := found;
  perform set_config('better_supabase.transition_reason', '', true);
  perform set_config('better_supabase.transition_actor', '', true);
  if not v_found then
    raise exception 'no such record, or the caller can''t see it' using errcode = 'P0002', hint = 'STATE_SUBJECT_NOT_FOUND';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_status_transition"(text, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::text, $2::text)', v_hook::oid::regproc)
        using transition.subject_type, transition.to_status;
    end if;
  end;
  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.transition_contract (
  contract_id uuid,
  action      text,
  reason      text DEFAULT NULL::text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_row "better_supabase"."contracts"%rowtype;
  v_from text[];
  v_to text;
begin
  select * into v_row from "better_supabase"."contracts" x where x."id" = transition_contract.contract_id;
  if not found then
    raise exception 'contract not found' using errcode = 'P0002', hint = 'CONTRACT_NOT_FOUND';
  end if;
  case transition_contract.action
    when 'submit' then v_from := array['draft']; v_to := 'in_review';
    when 'return' then v_from := array['in_review']; v_to := 'draft';
    when 'activate' then v_from := array['in_review']; v_to := 'active';
    when 'recall' then v_from := array['out_for_signature']; v_to := 'in_review';
    when 'terminate' then v_from := array['draft', 'in_review', 'out_for_signature', 'active']; v_to := 'terminated';
    else
      raise exception 'action must be submit, return, activate, recall or terminate' using errcode = '22023', hint = 'CONTRACT_INVALID';
  end case;
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', v_row."tenant_id", case when transition_contract.action in ('submit', 'return') then 'contracts.write' else 'contracts.manage' end), false)) then
    raise exception 'not allowed to move this contract' using errcode = '42501', hint = 'CONTRACT_FORBIDDEN';
  end if;
  if not (v_row."status" = any (v_from)) then
    raise exception 'the contract can''t take this step from its status' using errcode = '55000', hint = 'CONTRACT_TRANSITION_INVALID';
  end if;
  if v_row."status" = 'out_for_signature' and v_row."signature_request_id" is not null then
    -- The signatures trigger moves a recalled contract back to review.
    perform "better_supabase"."cancel_signature_request"(v_row."signature_request_id");
    if transition_contract.action = 'recall' then
      return "better_supabase"."get_contract"(v_row."id");
    end if;
  end if;
  return "better_supabase"."contract_apply_status"(v_row."id", v_to, transition_contract.reason);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.transparency_report (
  tenant       uuid,
  period_start timestamp with time zone,
  period_end   timestamp with time zone
)
  RETURNS text
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_csv text;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or coalesce(better_supabase.can('tenant', transparency_report.tenant, 'moderation.read'), false)) then
    raise exception 'not allowed to read the transparency report' using errcode = '42501', hint = 'MODERATION_FORBIDDEN';
  end if;
  if transparency_report.period_start is null or transparency_report.period_end is null or transparency_report.period_end <= transparency_report.period_start then
    raise exception 'the period needs a start before its end' using errcode = '22023', hint = 'MODERATION_INVALID';
  end if;
  with rows (metric, dimension, value, sort) as (
    select 'notices', 'received', count(*), 10 from "better_supabase"."moderation_notices" x
    where x."tenant_id" = transparency_report.tenant and x."created_at" >= transparency_report.period_start and x."created_at" < transparency_report.period_end
    union all
    select 'notices', 'trusted_flagger', count(*), 11 from "better_supabase"."moderation_notices" x
    where x."tenant_id" = transparency_report.tenant and x."trusted" and x."created_at" >= transparency_report.period_start and x."created_at" < transparency_report.period_end
    union all
    select 'notices', x."status", count(*), 12 from "better_supabase"."moderation_notices" x
    where x."tenant_id" = transparency_report.tenant and x."created_at" >= transparency_report.period_start and x."created_at" < transparency_report.period_end
    group by x."status"
    union all
    select 'statements', x."restriction", count(*), 20 from "better_supabase"."moderation_statements" x
    where x."tenant_id" = transparency_report.tenant and x."created_at" >= transparency_report.period_start and x."created_at" < transparency_report.period_end
    group by x."restriction"
    union all
    select 'statements', 'automated_detection', count(*), 21 from "better_supabase"."moderation_statements" x
    where x."tenant_id" = transparency_report.tenant and x."automated_detection" and x."created_at" >= transparency_report.period_start and x."created_at" < transparency_report.period_end
    union all
    select 'statements', 'automated_decision', count(*), 22 from "better_supabase"."moderation_statements" x
    where x."tenant_id" = transparency_report.tenant and x."automated_decision" and x."created_at" >= transparency_report.period_start and x."created_at" < transparency_report.period_end
    union all
    select 'appeals', 'received', count(*), 30 from "better_supabase"."moderation_appeals" x
    where x."tenant_id" = transparency_report.tenant and x."created_at" >= transparency_report.period_start and x."created_at" < transparency_report.period_end
    union all
    select 'appeals', x."status", count(*), 31 from "better_supabase"."moderation_appeals" x
    where x."tenant_id" = transparency_report.tenant and x."created_at" >= transparency_report.period_start and x."created_at" < transparency_report.period_end
    group by x."status"
    union all
    select 'decisions', x."action"::text, count(*), 40 from "better_supabase"."moderation_actions" x
    where x."tenant_id" = transparency_report.tenant and x."created_at" >= transparency_report.period_start and x."created_at" < transparency_report.period_end
    group by x."action"
    union all
    select 'reports', 'received', count(*), 50 from "better_supabase"."moderation_reports" x
    where x."tenant_id" = transparency_report.tenant and x."created_at" >= transparency_report.period_start and x."created_at" < transparency_report.period_end
  )
  select 'metric,dimension,value' || coalesce(E'\n' || string_agg(r.metric || ',' || r.dimension || ',' || r.value::text, E'\n' order by r.sort, r.dimension), '')
  into v_csv from rows r;
  return v_csv;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.trash (
  tenant       uuid,
  subject_type text,
  subject_id   text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_batch uuid := gen_random_uuid();
  v_count integer;
  v_id uuid;
begin
  if not (coalesce(nullif((select auth.jwt()) ->> 'role', ''), session_user::text) in ('service_role', 'postgres', 'supabase_admin') or (coalesce(better_supabase.can('tenant', trash.tenant, 'trash.create'), false) and case trash.subject_type
    when 'message' then exists (select 1 from "better_supabase"."messages" s where s."id" = (trash.subject_id)::uuid and s."tenant_id" = trash.tenant) and coalesce(better_supabase.can('tenant', trash.tenant, 'messages.read'), false)
    when 'conversation' then exists (select 1 from "better_supabase"."conversations" s where s."id" = (trash.subject_id)::uuid and s."tenant_id" = trash.tenant) and coalesce(better_supabase.can('tenant', trash.tenant, 'messages.read'), false)
    when 'deal' then exists (select 1 from "better_supabase"."deals" s where s."id" = (trash.subject_id)::uuid and s."tenant_id" = trash.tenant) and coalesce(better_supabase.can('tenant', trash.tenant, 'deals.read'), false)
    when 'work_item' then exists (select 1 from "better_supabase"."work_items" s where s."id" = (trash.subject_id)::uuid and s."tenant_id" = trash.tenant) and coalesce(better_supabase.can('tenant', trash.tenant, 'tasks.read'), false)
    when 'risk' then exists (select 1 from "better_supabase"."risks" s where s."id" = (trash.subject_id)::uuid and s."tenant_id" = trash.tenant) and coalesce(better_supabase.can('tenant', trash.tenant, 'risks.read'), false)
    when 'case' then exists (select 1 from "better_supabase"."cases" s where s."id" = (trash.subject_id)::uuid and s."tenant_id" = trash.tenant) and coalesce(better_supabase.can('tenant', trash.tenant, 'cases.read'), false)
    when 'inspection_program' then exists (select 1 from "better_supabase"."inspection_programs" s where s."id" = (trash.subject_id)::uuid and s."tenant_id" = trash.tenant) and coalesce(better_supabase.can('tenant', trash.tenant, 'inspections.read'), false)
    when 'tax_code' then exists (select 1 from "better_supabase"."tax_codes" s where s."id" = (trash.subject_id)::uuid and s."tenant_id" = trash.tenant) and coalesce(better_supabase.can('tenant', trash.tenant, 'tax.read'), false)
    when 'work_center' then exists (select 1 from "better_supabase"."work_centers" s where s."id" = (trash.subject_id)::uuid and s."tenant_id" = trash.tenant) and coalesce(better_supabase.can('tenant', trash.tenant, 'manufacturing.read'), false)
    when 'bank_account' then exists (select 1 from "better_supabase"."bank_accounts" s where s."id" = (trash.subject_id)::uuid and s."tenant_id" = trash.tenant) and coalesce(better_supabase.can('tenant', trash.tenant, 'banking.read'), false)
    when 'customer' then exists (select 1 from "public"."customers" s where s."id" = (trash.subject_id)::uuid and s."organization_id" = trash.tenant) and coalesce(better_supabase.can('tenant', trash.tenant, 'customers.read'), false)
    when 'drive_node' then exists (select 1 from "better_supabase"."drive_nodes" s where s."id" = (trash.subject_id)::uuid and s."tenant_id" = trash.tenant and (coalesce(better_supabase.can('tenant', trash.tenant, 'drive.read'), false) and coalesce("better_supabase"."drive_node_readable"(s."id"), false)))
    when 'project' then exists (select 1 from "public"."projects" s where s."id" = (trash.subject_id)::uuid and s."organization_id" = trash.tenant)
    else false
  end and case trash.subject_type
    when 'message' then coalesce(better_supabase.can('tenant', trash.tenant, 'messages.send'), false)
    when 'conversation' then coalesce(better_supabase.can('tenant', trash.tenant, 'messages.send'), false)
    when 'deal' then coalesce(better_supabase.can('tenant', trash.tenant, 'deals.write'), false)
    when 'work_item' then coalesce(better_supabase.can('tenant', trash.tenant, 'tasks.write'), false)
    when 'risk' then coalesce(better_supabase.can('tenant', trash.tenant, 'risks.write'), false)
    when 'case' then coalesce(better_supabase.can('tenant', trash.tenant, 'cases.write'), false)
    when 'inspection_program' then coalesce(better_supabase.can('tenant', trash.tenant, 'inspections.manage'), false)
    when 'tax_code' then coalesce(better_supabase.can('tenant', trash.tenant, 'tax.manage'), false)
    when 'work_center' then coalesce(better_supabase.can('tenant', trash.tenant, 'manufacturing.manage'), false)
    when 'bank_account' then coalesce(better_supabase.can('tenant', trash.tenant, 'banking.manage'), false)
    when 'customer' then coalesce(better_supabase.can('tenant', trash.tenant, 'customers.write'), false)
    when 'drive_node' then coalesce(better_supabase.can('tenant', trash.tenant, 'drive.manage'), false)
    else true
  end)) then
    raise exception 'not allowed to trash this record' using errcode = '42501', hint = 'TRASH_FORBIDDEN';
  end if;
  declare
    v_hook regprocedure := to_regprocedure('"public"."before_trash"(uuid, text, text)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::text, $3::text)', v_hook::oid::regproc)
        using trash.tenant, trash.subject_type, trash.subject_id;
    end if;
  end;
  v_count := "better_supabase"."trash_cascade"(trash.tenant, trash.subject_type, trash.subject_id, v_batch, 0, auth.uid());
  if v_count = 0 then
    raise exception 'no live record to trash' using errcode = 'P0002', hint = 'TRASH_NOT_FOUND';
  end if;
  select i."id" into v_id from "better_supabase"."trash_items" i
    where i."subject_type" = trash.subject_type and i."subject_id" = trash.subject_id;
  declare
    v_hook regprocedure := to_regprocedure('"public"."after_trash"(uuid, uuid)');
  begin
    if v_hook is not null then
      execute format('select %s($1::uuid, $2::uuid)', v_hook::oid::regproc)
        using v_id, v_batch;
    end if;
  end;
  return jsonb_build_object('id', v_id, 'batchId', v_batch, 'count', v_count);
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.trash_cascade (
  tenant       uuid,
  subject_type text,
  subject_id   text,
  batch        uuid,
  depth        integer,
  actor        uuid
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_title text;
  v_count integer := 1;
  v_child text;
  v_item "better_supabase"."trash_items"%rowtype;
begin
  case trash_cascade.subject_type
    when 'message' then
      update "better_supabase"."messages" s set "archived_at" = now()
        where s."id" = (trash_cascade.subject_id)::uuid
          and s."tenant_id" = trash_cascade.tenant
          and s."archived_at" is null
        returning s."body"::text into v_title;
    when 'conversation' then
      update "better_supabase"."conversations" s set "archived_at" = now()
        where s."id" = (trash_cascade.subject_id)::uuid
          and s."tenant_id" = trash_cascade.tenant
          and s."archived_at" is null
        returning s."title"::text into v_title;
    when 'deal' then
      update "better_supabase"."deals" s set "archived_at" = now()
        where s."id" = (trash_cascade.subject_id)::uuid
          and s."tenant_id" = trash_cascade.tenant
          and s."archived_at" is null
        returning s."name"::text into v_title;
    when 'work_item' then
      update "better_supabase"."work_items" s set "archived_at" = now()
        where s."id" = (trash_cascade.subject_id)::uuid
          and s."tenant_id" = trash_cascade.tenant
          and s."archived_at" is null
        returning s."title"::text into v_title;
    when 'risk' then
      update "better_supabase"."risks" s set "archived_at" = now()
        where s."id" = (trash_cascade.subject_id)::uuid
          and s."tenant_id" = trash_cascade.tenant
          and s."archived_at" is null
        returning s."title"::text into v_title;
    when 'case' then
      update "better_supabase"."cases" s set "archived_at" = now()
        where s."id" = (trash_cascade.subject_id)::uuid
          and s."tenant_id" = trash_cascade.tenant
          and s."archived_at" is null
        returning s."title"::text into v_title;
    when 'inspection_program' then
      update "better_supabase"."inspection_programs" s set "archived_at" = now()
        where s."id" = (trash_cascade.subject_id)::uuid
          and s."tenant_id" = trash_cascade.tenant
          and s."archived_at" is null
        returning s."name"::text into v_title;
    when 'tax_code' then
      update "better_supabase"."tax_codes" s set "archived_at" = now()
        where s."id" = (trash_cascade.subject_id)::uuid
          and s."tenant_id" = trash_cascade.tenant
          and s."archived_at" is null
        returning s."name"::text into v_title;
    when 'work_center' then
      update "better_supabase"."work_centers" s set "archived_at" = now()
        where s."id" = (trash_cascade.subject_id)::uuid
          and s."tenant_id" = trash_cascade.tenant
          and s."archived_at" is null
        returning s."name"::text into v_title;
    when 'bank_account' then
      update "better_supabase"."bank_accounts" s set "archived_at" = now()
        where s."id" = (trash_cascade.subject_id)::uuid
          and s."tenant_id" = trash_cascade.tenant
          and s."archived_at" is null
        returning s."name"::text into v_title;
    when 'customer' then
      update "public"."customers" s set "archived_at" = now()
        where s."id" = (trash_cascade.subject_id)::uuid
          and s."organization_id" = trash_cascade.tenant
          and s."archived_at" is null
        returning s."name"::text into v_title;
    when 'drive_node' then
      update "better_supabase"."drive_nodes" s set "archived_at" = now()
        where s."id" = (trash_cascade.subject_id)::uuid
          and s."tenant_id" = trash_cascade.tenant
          and s."archived_at" is null
        returning s."name"::text into v_title;
    when 'project' then
      update "public"."projects" s set "deleted_at" = now()
        where s."id" = (trash_cascade.subject_id)::uuid
          and s."organization_id" = trash_cascade.tenant
          and s."deleted_at" is null
        returning s."name"::text into v_title;
    else
      raise exception 'this subject type has no deletedAt column' using errcode = '22023', hint = 'TRASH_UNSUPPORTED';
  end case;
  if not found then
    return 0;
  end if;
  delete from "better_supabase"."trash_items" i
    where i."subject_type" = trash_cascade.subject_type and i."subject_id" = trash_cascade.subject_id;
  insert into "better_supabase"."trash_items" ("tenant_id", "subject_type", "subject_id", "title", "batch_id", "depth", "trashed_by", "trashed_at", "purge_at")
  values (trash_cascade.tenant, trash_cascade.subject_type, trash_cascade.subject_id, v_title, trash_cascade.batch, trash_cascade.depth, trash_cascade.actor, now(), now() + make_interval(days => 30))
  returning * into v_item;
  perform "better_supabase".emit_event('subject.trashed', jsonb_build_object('organizationId', v_item."tenant_id", 'subjectType', v_item."subject_type", 'subjectId', v_item."subject_id", 'id', v_item."id", 'batchId', v_item."batch_id"), 'trash-items/' || v_item."id"::text, (v_item."tenant_id")::text, null, 'better-supabase/trash');
  perform better_supabase.audit_event(
    event_type => 'subject.trashed',
    category => 'data',
    target_type => 'trash_item',
    record_id => v_item."id"::text,
    summary => 'trashed' || ' ' || v_item."subject_type" || ' ' || v_item."subject_id",
    tenant => (v_item."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_item."tenant_id", 'subjectType', v_item."subject_type", 'subjectId', v_item."subject_id", 'id', v_item."id", 'batchId', v_item."batch_id")
  );
  
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.trash_purge_batch (
  batch uuid
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_item "better_supabase"."trash_items"%rowtype;
  v_count integer := 0;
begin
  for v_item in select * from "better_supabase"."trash_items" where "batch_id" = trash_purge_batch.batch order by "depth" desc loop
    if (false) then
      raise exception 'a record in this batch is under a legal hold' using errcode = '42501', hint = 'TRASH_HELD';
    end if;
    case v_item.subject_type
    when 'message' then
      delete from "better_supabase"."messages" s
        where s."id" = (v_item.subject_id)::uuid;
    when 'conversation' then
      delete from "better_supabase"."conversations" s
        where s."id" = (v_item.subject_id)::uuid;
    when 'deal' then
      delete from "better_supabase"."deals" s
        where s."id" = (v_item.subject_id)::uuid;
    when 'work_item' then
      delete from "better_supabase"."work_items" s
        where s."id" = (v_item.subject_id)::uuid;
    when 'risk' then
      delete from "better_supabase"."risks" s
        where s."id" = (v_item.subject_id)::uuid;
    when 'case' then
      delete from "better_supabase"."cases" s
        where s."id" = (v_item.subject_id)::uuid;
    when 'inspection_program' then
      delete from "better_supabase"."inspection_programs" s
        where s."id" = (v_item.subject_id)::uuid;
    when 'tax_code' then
      delete from "better_supabase"."tax_codes" s
        where s."id" = (v_item.subject_id)::uuid;
    when 'work_center' then
      delete from "better_supabase"."work_centers" s
        where s."id" = (v_item.subject_id)::uuid;
    when 'bank_account' then
      delete from "better_supabase"."bank_accounts" s
        where s."id" = (v_item.subject_id)::uuid;
    when 'customer' then
      delete from "public"."customers" s
        where s."id" = (v_item.subject_id)::uuid;
    when 'drive_node' then
      delete from "better_supabase"."drive_nodes" s
        where s."id" = (v_item.subject_id)::uuid;
    when 'project' then
      delete from "public"."projects" s
        where s."id" = (v_item.subject_id)::uuid;
    else null;
  end case;
    perform "better_supabase".emit_event('subject.purged', jsonb_build_object('organizationId', v_item."tenant_id", 'subjectType', v_item."subject_type", 'subjectId', v_item."subject_id", 'id', v_item."id", 'batchId', v_item."batch_id"), 'trash-items/' || v_item."id"::text, (v_item."tenant_id")::text, null, 'better-supabase/trash');
  perform better_supabase.audit_event(
    event_type => 'subject.purged',
    category => 'data',
    target_type => 'trash_item',
    record_id => v_item."id"::text,
    summary => 'purged' || ' ' || v_item."subject_type" || ' ' || v_item."subject_id",
    tenant => (v_item."tenant_id")::uuid,
    metadata => jsonb_build_object('organizationId', v_item."tenant_id", 'subjectType', v_item."subject_type", 'subjectId', v_item."subject_id", 'id', v_item."id", 'batchId', v_item."batch_id")
  );
    v_count := v_count + 1;
  end loop;
  delete from "better_supabase"."trash_items" where "batch_id" = trash_purge_batch.batch;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.trash_restore_batch (
  batch uuid
)
  RETURNS integer
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_item "better_supabase"."trash_items"%rowtype;
  v_count integer := 0;
begin
  for v_item in select * from "better_supabase"."trash_items" where "batch_id" = trash_restore_batch.batch order by "depth" loop
    case v_item.subject_type
    when 'message' then
      update "better_supabase"."messages" s set "archived_at" = null
        where s."id" = (v_item.subject_id)::uuid;
    when 'conversation' then
      update "better_supabase"."conversations" s set "archived_at" = null
