  order by x."id"::text = workflow_run_get.run desc
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.workflow_run_principal (
  version uuid,
  tenant  uuid DEFAULT NULL::uuid
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
#variable_conflict use_variable
declare
  v_row "better_supabase"."workflow_versions"%rowtype;
  v_tenant uuid;
  v_publisher uuid;
  v_missing text;
begin
  select * into v_row from "better_supabase"."workflow_versions" x where x."id" = version;
  if not found then
    raise exception 'No such workflow version' using errcode = 'P0002', hint = 'WORKFLOW_NOT_FOUND';
  end if;
  if v_row."status" = 'draft' then
    raise exception 'This workflow version was never published' using errcode = 'P0002', hint = 'WORKFLOW_NOT_PUBLISHED';
  end if;
  select case when x."scope" = 'system' then tenant else x."tenant_id" end into v_tenant
  from "better_supabase"."workflow_definitions" x where x."id" = v_row."definition_id";
  if v_row."owner_kind" is null then
    raise exception 'This workflow version was published before publishers were recorded; publish it again'
        using errcode = '42501', hint = 'WORKFLOW_PUBLISHER_REVOKED';
  end if;
  if v_row."owner_kind" = 'user' then
    if v_row."published_by" is null then
      raise exception 'The user who published this workflow no longer exists'
        using errcode = '42501', hint = 'WORKFLOW_PUBLISHER_REVOKED';
    end if;
    select string_agg(p, ', ' order by p) into v_missing
    from unnest(array_append(v_row."permissions", 'workflow_editor.publish')) p
    where not coalesce(better_supabase.can_user(v_row."published_by", 'tenant', v_tenant, p), false);
    if v_missing is not null then
      raise exception 'The user who published this workflow no longer holds %', v_missing
        using errcode = '42501', hint = 'WORKFLOW_PUBLISHER_REVOKED';
    end if;
  end if;
  if v_row."owner_kind" <> 'user' then
    v_publisher := "better_supabase"."default_service_principal"(v_tenant);
    if v_publisher is null then
      raise exception 'This organization has no default service principal'
        using errcode = '42501', hint = 'WORKFLOW_PUBLISHER_REVOKED';
    end if;
    select string_agg(p, ', ' order by p) into v_missing
    from unnest(v_row."permissions") p
    where not coalesce(better_supabase.can_user(v_publisher, 'tenant', v_tenant, p), false);
    if v_missing is not null then
      raise exception 'The service principal no longer holds %', v_missing
        using errcode = '42501', hint = 'WORKFLOW_PUBLISHER_REVOKED';
    end if;
  end if;
  return jsonb_build_object(
    'publisher', coalesce(v_publisher, v_row."published_by"),
    'tenant', v_tenant,
    'owner', v_row."owner_kind",
    'permissions', to_jsonb(v_row."permissions")
  );
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.workflow_runs_alert()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_run "better_supabase"."workflow_runs"%rowtype := new;
  v_alert "better_supabase"."workflow_alerts"%rowtype;
  v_fired integer := 0;
begin
  if new."mode" = 'test' or new."status" <> 'failed' or (tg_op = 'UPDATE' and old."status" = 'failed') then
    return null;
  end if;
  for v_alert in
    select * from "better_supabase"."workflow_alerts" x
    where x."on_event" = 'failed' and x."definition_id"::text = new."attributes" ->> 'bsb.definition'
  loop
    insert into "better_supabase"."workflow_alert_fires" ("alert_id", "run_id") values (v_alert."id", v_run."id")
      on conflict do nothing;
      if found then
        v_fired := v_fired + 1;
        perform "better_supabase".emit_event('workflow_alert.triggered', jsonb_build_object('alertId', v_alert."id", 'organizationId', v_run."tenant_id"::text, 'definition', v_alert."definition_id", 'onEvent', v_alert."on_event", 'channel', v_alert."channel", 'runId', v_run."id", 'status', v_run."status", 'error', v_run."error"), 'workflow-runs/' || v_run."id", (v_run."tenant_id")::text, 'workflow_alert.triggered:' || v_alert."id" || ':' || v_run."id", 'better-supabase/workflow-editor');
      end if;
  end loop;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.workflow_runs_changed()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
begin
  if tg_op = 'UPDATE' and old."status" = new."status" then
    return null;
  end if;
  if to_regprocedure('realtime.send(jsonb, text, text, boolean)') is not null then
    perform realtime.send(jsonb_build_object('id', new."id", 'status', new."status"), 'status', 'workflow-run:' || new."id"::text, true);
    if new."tenant_id" is not null then
      perform realtime.send(jsonb_build_object('id', new."id", 'status', new."status"), 'status', 'workflow-runs:' || new."tenant_id"::text, true);
    end if;
  end if;
  if new."mode" = 'test' then
    return null;
  end if;
  case new."status"
    when 'completed' then
      perform "better_supabase".emit_event('workflow_run.completed', jsonb_build_object('runId', new."id", 'organizationId', new."tenant_id"::text, 'engine', new."engine", 'externalId', new."external_id", 'definition', new."definition", 'status', new."status", 'error', new."error", 'subjectType', new."subject_type", 'subjectId', new."subject_id"), 'workflow-runs/' || new."id", (new."tenant_id")::text, 'workflow_run.completed:' || new."id", 'better-supabase/workflows');
    when 'failed' then
      perform "better_supabase".emit_event('workflow_run.failed', jsonb_build_object('runId', new."id", 'organizationId', new."tenant_id"::text, 'engine', new."engine", 'externalId', new."external_id", 'definition', new."definition", 'status', new."status", 'error', new."error", 'subjectType', new."subject_type", 'subjectId', new."subject_id"), 'workflow-runs/' || new."id", (new."tenant_id")::text, 'workflow_run.failed:' || new."id", 'better-supabase/workflows');
    when 'cancelled' then
      perform "better_supabase".emit_event('workflow_run.cancelled', jsonb_build_object('runId', new."id", 'organizationId', new."tenant_id"::text, 'engine', new."engine", 'externalId', new."external_id", 'definition', new."definition", 'status', new."status", 'error', new."error", 'subjectType', new."subject_type", 'subjectId', new."subject_id"), 'workflow-runs/' || new."id", (new."tenant_id")::text, 'workflow_run.cancelled:' || new."id", 'better-supabase/workflows');
    else null;
  end case;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.workflow_runs_list (
  tenant       uuid                     DEFAULT NULL::uuid,
  definition   text                     DEFAULT NULL::text,
  status       text                     DEFAULT NULL::text,
  max          integer                  DEFAULT 50,
  before       timestamp with time zone DEFAULT NULL::timestamp WITH time zone,
  subject_type text                     DEFAULT NULL::text,
  subject_id   text                     DEFAULT NULL::text,
  mode         text                     DEFAULT 'live'::text
)
  RETURNS jsonb
  LANGUAGE sql
  STABLE
  SET search_path TO ''
  AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', x."id",
    'engine', x."engine",
    'externalId', x."external_id",
    'definition', x."definition",
    'tenant', x."tenant_id",
    'actor', x."actor_id",
    'status', x."status",
    'attributes', x."attributes",
    'error', x."error",
    'createdAt', x."created_at",
    'updatedAt', x."updated_at",
    'startedAt', x."started_at",
    'completedAt', x."completed_at",
    'cancelRequestedAt', x."cancel_requested_at",
    'subjectType', x."subject_type",
    'subjectId', x."subject_id",
    'principalKind', x."principal_kind",
    'principalId', x."principal_id",
    'mode', x."mode",
    'triggerNode', x."trigger_node",
    'idempotencyKey', x."idempotency_key"
  ) order by x."created_at" desc), '[]'::jsonb)
  from (
    select * from "better_supabase"."workflow_runs" y
    where (workflow_runs_list.tenant is null or y."tenant_id" = workflow_runs_list.tenant)
      and (workflow_runs_list.definition is null or y."definition" = workflow_runs_list.definition)
      and (workflow_runs_list.status is null or y."status" = workflow_runs_list.status)
      and (workflow_runs_list.before is null or y."created_at" < workflow_runs_list.before)
      and (workflow_runs_list.subject_type is null or y."subject_type" = workflow_runs_list.subject_type)
      and (workflow_runs_list.subject_id is null or y."subject_id" = workflow_runs_list.subject_id)
      and (workflow_runs_list.mode is null or y."mode" = workflow_runs_list.mode)
    order by y."created_at" desc
    limit least(greatest(coalesce(workflow_runs_list.max, 50), 1), 500)
  ) x;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.workflow_schedules_list (
  tenant uuid DEFAULT NULL::uuid
