CREATE OR REPLACE FUNCTION public.import_customer (
  run        uuid,
  item       jsonb,
  subject_id text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_id uuid;
begin
  if subject_id is null then
    insert into public.customers (organization_id, name, kvk, status)
    values (
      (item ->> 'tenant')::uuid,
      item -> 'data' ->> 'name',
      item -> 'data' ->> 'kvk',
      coalesce(item -> 'data' ->> 'status', 'lead')
    )
    returning id into v_id;
  else
    update public.customers c
    set name = item -> 'data' ->> 'name',
        kvk = item -> 'data' ->> 'kvk',
        status = coalesce(item -> 'data' ->> 'status', c.status)
    where c.id = subject_id::uuid
    returning c.id into v_id;
  end if;

  return jsonb_build_object(
    'subjectId', v_id::text,
    'updatedAt', (select c.updated_at from public.customers c where c.id = v_id)
  );
end;
$function$;

REVOKE ALL ON FUNCTION "public"."import_customer"(uuid, jsonb, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.import_customer_batch (
  run   uuid,
  items jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_out jsonb;
begin
  with src as (
    select
      e.ordinality::int as i,
      e.value as item,
      coalesce(e.value ->> 'subjectId', gen_random_uuid()::text)::uuid as id,
      (e.value ->> 'subjectId') is null as is_new
    from jsonb_array_elements(items) with ordinality e(value, ordinality)
  ),
  ins as (
    insert into public.customers (id, organization_id, name, kvk, status)
    select
      s.id,
      (s.item ->> 'tenant')::uuid,
      s.item -> 'data' ->> 'name',
      s.item -> 'data' ->> 'kvk',
      coalesce(s.item -> 'data' ->> 'status', 'lead')
    from src s
    where s.is_new
    returning id, updated_at
  ),
  upd as (
    update public.customers c
    set name = s.item -> 'data' ->> 'name',
        kvk = s.item -> 'data' ->> 'kvk',
        status = coalesce(s.item -> 'data' ->> 'status', c.status)
    from src s
    where not s.is_new and c.id = s.id
    returning c.id, c.updated_at
  ),
  written as (
    select id, updated_at from ins
    union all
    select id, updated_at from upd
  )
  select coalesce(jsonb_agg(
    case when w.id is null
      then jsonb_build_object('error', jsonb_build_object('code', 'IMPORT_ITEM_INVALID', 'message', 'the customer no longer exists'))
      else jsonb_build_object('subjectId', s.id::text, 'updatedAt', w.updated_at)
    end order by s.i), '[]'::jsonb)
  into v_out
  from src s
  left join written w on w.id = s.id;

  return v_out;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."import_customer_batch"(uuid, jsonb) FROM PUBLIC, "anon", "authenticated";

