CREATE OR REPLACE FUNCTION public.work_bulk_state (
  tenant       uuid,
  subject_type text,
  subject_id   text,
  args         jsonb
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
declare
  v_to text := work_bulk_state.args ->> 'to';
begin
  if not better_supabase.actor_may_write() then
    raise exception 'This session is read-only' using errcode = '42501', hint = 'ACTOR_READ_ONLY';
  end if;
  if not (
    ((select auth.jwt() ->> 'role') = 'service_role')
    or coalesce(better_supabase.can('tenant', work_bulk_state.tenant, 'tasks.write'), false)
  ) then
    raise exception 'not allowed to change work items' using errcode = '42501', hint = 'TASK_FORBIDDEN';
  end if;
  if v_to is null then
    raise exception 'args.to is required' using errcode = '22023', hint = 'BULK_STATE_ARGS';
  end if;
  perform set_config('better_supabase.transition_reason', coalesce(work_bulk_state.args ->> 'reason', ''), true);
  update better_supabase.work_items x
  set state = v_to
  where x.id = work_bulk_state.subject_id::uuid
    and x.tenant_id = work_bulk_state.tenant
    and x.archived_at is null;
  if not found then
    perform set_config('better_supabase.transition_reason', '', true);
    raise exception 'no such work item you can edit' using errcode = 'P0002', hint = 'TASK_NOT_FOUND';
  end if;
  perform set_config('better_supabase.transition_reason', '', true);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."work_bulk_state"(uuid, text, text, jsonb) FROM PUBLIC, "anon";

CREATE OR REPLACE FUNCTION rbac.authorize (
  requested_permission rbac.app_permission
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select exists (
    select 1
    from rbac.role_permissions rp
    where rp.permission = requested_permission
      and rp.role::text = coalesce(
        auth.jwt() ->> 'user_role',
        auth.jwt() -> 'app_metadata' ->> 'user_role'
      )
  )
$function$;

CREATE OR REPLACE FUNCTION rbac.compact_permission_keys (
  granted text[]
)
  RETURNS text[]
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
  select coalesce(array_agg(k order by k), '{}'::text[])
  from (
    select c.resource || '.*' as k
    from (
      select split_part(p.key, '.', 1) as resource,
        bool_and(p.key = any(granted)) as every
      from better_supabase.permissions p
      group by 1
    ) c
    where c.every
    union all
    select g
    from unnest(granted) g
    where exists (
      select 1 from better_supabase.permissions p
      where split_part(p.key, '.', 1) = split_part(g, '.', 1)
        and not p.key = any(granted)
    )
    or not exists (
      select 1 from better_supabase.permissions p
      where split_part(p.key, '.', 1) = split_part(g, '.', 1)
    )
  ) keys
$function$;

CREATE OR REPLACE FUNCTION rbac.custom_access_token_hook (
  event jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SET search_path TO ''
  AS $function$
declare
  claims jsonb := event -> 'claims';
  user_role rbac.app_role;
  active_tenant text := claims -> 'app_metadata' ->> 'tenant_id';
  permission_keys jsonb := '{}'::jsonb;
  plan text := better_supabase.hook_plan(event);
begin
  -- blocks['sessions'].options.hook: an OAuth client token carries none of
  -- the claims below, and a refresh whose authz_ver is still current keeps
  -- the claims it already has, so neither reads memberships or permissions.
  if plan in ('slim', 'reuse') then
    return event;
  end if;

  select ur.role into user_role
  from rbac.user_roles ur
  where ur.user_id = (event ->> 'user_id')::uuid;

  if user_role is not null then
    claims := jsonb_set(claims, '{user_role}', to_jsonb(user_role));
  end if;

  -- The version SessionProvider and `subscribeAuthzVersions` watch
  -- (blocks['sessions'].options.authzVersions).
  claims := jsonb_set(claims, '{authz_ver}', to_jsonb(better_supabase.authz_version((event ->> 'user_id')::uuid)));

  -- Every organization the user belongs to, and each one's plan features
  -- (supabase/schemas/045_access_contract.sql and the entitlements module).
  claims := jsonb_set(claims, '{memberships}', better_supabase.membership_claims((event ->> 'user_id')::uuid));
  claims := jsonb_set(claims, '{features}', better_supabase.feature_claims((event ->> 'user_id')::uuid));

  -- The permission keys for the active organization only, which
  -- `permissionsOf()` and `permissionsAuthorizer()` read. Past the budget the
  -- token says so, and the app reads `my_permissions()` instead.
  if active_tenant ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    permission_keys := better_supabase.permission_claims((event ->> 'user_id')::uuid, active_tenant::uuid);
  end if;

  if permission_keys ? active_tenant then
    permission_keys := jsonb_build_object(active_tenant, to_jsonb(rbac.compact_permission_keys(
      array(select jsonb_array_elements_text(permission_keys -> active_tenant))
    )));
  end if;

  if octet_length(permission_keys::text) > 2048 then
    claims := jsonb_set(claims, '{permissions}', '{}'::jsonb);
    claims := jsonb_set(claims, '{permissions_truncated}', 'true'::jsonb);
  else
    claims := jsonb_set(claims, '{permissions}', permission_keys);
    claims := claims - 'permissions_truncated';
  end if;

  return jsonb_set(event, '{claims}', claims);
end;
$function$;

