CREATE VIEW "api"."notification_preferences" WITH (security_invoker=true) AS  SELECT id,
    user_id,
    tenant_id,
    type,
    channel,
    enabled,
    cadence,
    created_at,
    updated_at
   FROM better_supabase.notification_preferences;

CREATE VIEW "api"."notification_recipients" WITH (security_invoker=true) AS  SELECT id,
    event_id,
    tenant_id,
    user_id,
    read_at,
    dismissed_at,
    resolved_at,
    resolution,
    delivered_at,
    created_at
   FROM better_supabase.notification_recipients;

CREATE VIEW "better_supabase"."drive_node_search" WITH (security_invoker=true) AS  SELECT s.id,
    s.name,
    "left"(t.content, 100000) AS content
   FROM (better_supabase.drive_nodes s
     LEFT JOIN better_supabase.drive_node_texts t ON ((t.node_id = s.id)));

CREATE VIEW "better_supabase"."maintenance_jobs" WITH (security_invoker=true) AS  SELECT j.job,
    j.fn AS function,
    j.every_interval AS every,
    s.last_run_at,
    s.last_status,
    s.last_error,
    COALESCE(s.runs, (0)::bigint) AS runs,
    ((s.last_run_at IS NULL) OR ((s.last_run_at + j.every_interval) <= now())) AS due
   FROM (( VALUES ('digest_run'::text,'"better_supabase"."run_notification_digests"'::text,'01:00:00'::interval), ('expire_approvals'::text,'"better_supabase"."expire_approvals"'::text,'00:15:00'::interval), ('purge_chat_state'::text,'"better_supabase"."purge_chat_state"'::text,'00:15:00'::interval), ('purge_expired_trash'::text,'"better_supabase"."purge_expired_trash"'::text,'1 day'::interval), ('purge_idempotency_keys'::text,'better_supabase.purge_idempotency_keys'::text,'01:00:00'::interval), ('purge_rate_limits'::text,'better_supabase.purge_rate_limits'::text,'00:15:00'::interval), ('purge_usage_events'::text,'"better_supabase"."purge_usage_events"'::text,'1 day'::interval), ('purge_webhook_deliveries'::text,'"better_supabase"."purge_webhook_deliveries"'::text,'1 day'::interval), ('purge_webhooks'::text,'better_supabase.purge_webhooks'::text,'1 day'::interval)) j(job, fn, every_interval)
     LEFT JOIN better_supabase.maintenance_state s ON ((s.job = j.job)));

CREATE VIEW "public"."customers_with_owner" WITH (security_invoker=true) AS  SELECT c.id,
    c.organization_id,
    c.name,
    c.status,
    c.owner_team_id,
    t.name AS owner_team_name
   FROM (public.customers c
     LEFT JOIN better_supabase.teams t ON (((t.id = c.owner_team_id) AND (t.tenant_id = c.organization_id))))
  WHERE (c.archived_at IS NULL);

REVOKE ALL ON TABLE "public"."customers_with_owner" FROM "anon";

CREATE VIEW "public"."projects_view" WITH (security_invoker=true) AS  SELECT t.id,
    t.organization_id,
    t.created_at,
    t.updated_at,
    t.name,
    t.budget_minor,
    t.currency,
    t.lead_id,
    t.label_id,
    t.deleted_at,
    r0.value AS open_tasks,
    r1.value AS done_tasks,
    r2.value AS next_due_on
   FROM (((public.projects t
     LEFT JOIN LATERAL ( SELECT count(*) AS value
           FROM public.tasks c
          WHERE ((c.project_id = t.id) AND (c.status = 'todo'::text))) r0 ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS value
           FROM public.tasks c
          WHERE ((c.project_id = t.id) AND (c.status = 'done'::text))) r1 ON (true))
     LEFT JOIN LATERAL ( SELECT min(c.due_on) AS value
           FROM public.tasks c
          WHERE (c.project_id = t.id)) r2 ON (true));

REVOKE ALL ON TABLE "public"."projects_view" FROM "anon";

CREATE VIEW "public"."tasks_view" WITH (security_invoker=true) AS  SELECT t.id,
    t.organization_id,
    t.created_at,
    t.updated_at,
    t.title,
    t.status,
    t.starts_on,
    t.due_on,
    t.assignee_id,
    t.project_id,
    t.rank,
    l0.value AS project_name
   FROM (public.tasks t
     LEFT JOIN LATERAL ( SELECT r.name AS value
           FROM public.projects r
          WHERE (r.id = t.project_id)) l0 ON (true));

REVOKE ALL ON TABLE "public"."tasks_view" FROM "anon";

