  FOR SELECT
  TO "authenticated"
  USING (((tenant_id IN ( SELECT better_supabase.tenant_ids_with('access_requests.read'::text) AS tenant_ids_with)) OR (user_id = ( SELECT auth.uid() AS uid))));

