      WHERE ((s.id = (consents.subject_id)::uuid) AND (s.tenant_id = consents.tenant_id)))) AND
        (tenant_id IN ( SELECT better_supabase.tenant_ids_with('leases.read'::text) AS tenant_ids_with)))
