    WHEN 'task'::text THEN (EXISTS ( SELECT 1
       FROM public.tasks s
      WHERE ((s.id = (deadlines.subject_id)::uuid) AND (s.organization_id = deadlines.tenant_id))))
    ELSE better_supabase.deadline_subject_readable(subject_type, subject_id, tenant_id)
END)));

