    WHEN 'organization'::text THEN (EXISTS ( SELECT 1
       FROM public.organizations s
      WHERE ((s.id = (field_changes.subject_id)::uuid) AND (s.id = field_changes.tenant_id))))
    WHEN 'application'::text THEN ((EXISTS ( SELECT 1
