        ((tenant_id IN ( SELECT better_supabase.tenant_ids_with('customers.read'::text) AS tenant_ids_with)) OR better_supabase.is_subject_member('customer'::text, subject_id)))
    WHEN 'drive_node'::text THEN (EXISTS ( SELECT 1
