CREATE POLICY "bsb_subject_collection_entries_read" ON "better_supabase"."subject_collection_entries"
  FOR SELECT
  TO "authenticated"
  USING (((tenant_id IN ( SELECT better_supabase.tenant_ids_with('collections.read'::text) AS tenant_ids_with)) AND (EXISTS ( SELECT 1
   FROM better_supabase.subject_collections c
  WHERE (c.id = subject_collection_entries.collection_id))) AND better_supabase.can_subject(subject_type, subject_id, 'read'::text)));

CREATE POLICY "bsb_tenant_scope_delete" ON "better_supabase"."subject_collection_entries"
  AS RESTRICTIVE
  FOR DELETE
  TO PUBLIC
  USING ((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)));

