  AS RESTRICTIVE
  FOR SELECT
  TO PUBLIC
  USING
    (((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)) OR ((tenant_id IN ( SELECT
    better_supabase.tenant_ids_with('collections.read'::text) AS tenant_ids_with)) AND (EXISTS ( SELECT 1
   FROM better_supabase.subject_collections c
  WHERE (c.id = subject_collection_entries.collection_id))) AND better_supabase.can_subject(subject_type, subject_id, 'read'::text))));

CREATE POLICY "bsb_tenant_scope_update" ON "better_supabase"."subject_collection_entries"
  AS RESTRICTIVE
  FOR UPDATE
  TO PUBLIC
  USING ((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)))
  WITH CHECK ((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)));

CREATE POLICY "bsb_subject_collections_read" ON "better_supabase"."subject_collections"
  FOR SELECT
  TO "authenticated"
  USING
    (((tenant_id IN ( SELECT better_supabase.tenant_ids_with('collections.read'::text) AS tenant_ids_with)) AND (((scope = 'user'::text) AND (owner_id = ( SELECT auth.uid() AS
    uid))) OR ((scope = 'team'::text) AND (team_id IN ( SELECT (t.t)::text AS t
   FROM better_supabase.team_ids_of(( SELECT auth.uid() AS uid)) t(t)))) OR (scope = 'tenant'::text))));

CREATE POLICY "bsb_tenant_scope_delete" ON "better_supabase"."subject_collections"
  AS RESTRICTIVE
  FOR DELETE
  TO PUBLIC
  USING ((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)));

