  AS RESTRICTIVE
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)));

CREATE POLICY "bsb_tenant_scope_select" ON "better_supabase"."subject_collections"
  AS RESTRICTIVE
  FOR SELECT
  TO PUBLIC
  USING
    (((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)) OR ((tenant_id IN ( SELECT
    better_supabase.tenant_ids_with('collections.read'::text) AS tenant_ids_with)) AND
    (((scope = 'user'::text) AND (owner_id = ( SELECT auth.uid() AS uid))) OR ((scope = 'team'::text) AND (team_id IN ( SELECT (t.t)::text AS t
   FROM better_supabase.team_ids_of(( SELECT auth.uid() AS uid)) t(t)))) OR (scope = 'tenant'::text)))));

CREATE POLICY "bsb_tenant_scope_update" ON "better_supabase"."subject_collections"
  AS RESTRICTIVE
  FOR UPDATE
  TO PUBLIC
  USING ((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)))
  WITH CHECK ((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)));

CREATE POLICY "bsb_subject_lifecycles_read" ON "better_supabase"."subject_lifecycles"
  FOR SELECT
  TO "authenticated"
  USING (
CASE subject_type
    WHEN 'work_item'::text THEN (EXISTS ( SELECT 1
       FROM better_supabase.work_items s
      WHERE (s.id = (subject_lifecycles.subject_id)::uuid)))
    WHEN 'change_request'::text THEN (EXISTS ( SELECT 1
       FROM public.change_requests s
      WHERE (s.id = (subject_lifecycles.subject_id)::uuid)))
    WHEN 'drive_node'::text THEN (EXISTS ( SELECT 1
       FROM better_supabase.drive_nodes s
      WHERE (s.id = (subject_lifecycles.subject_id)::uuid)))
    WHEN 'warranty_claim'::text THEN better_supabase.bsb_record_visible('"better_supabase"."warranty_claims"'::text, 'id'::text, subject_id)
    ELSE false
END);

CREATE POLICY "bsb_tenant_scope_delete" ON "better_supabase"."subject_lifecycles"
  AS RESTRICTIVE
  FOR DELETE
  TO PUBLIC
  USING ((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)));

