CREATE POLICY "bsb_drive_objects_delete" ON "storage"."objects"
  AS RESTRICTIVE
  FOR DELETE
  TO "authenticated"
  USING ((better_supabase.drive_object_allowed(bucket_id, name, 'delete'::text) AND ( SELECT better_supabase.actor_may_write() AS actor_may_write)));

