  AS RESTRICTIVE
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((better_supabase.drive_object_allowed(bucket_id, name, 'insert'::text) AND ( SELECT better_supabase.actor_may_write() AS actor_may_write)));

