CREATE POLICY "bsb_comment_tasks_insert" ON "better_supabase"."comment_tasks"
  FOR INSERT
  TO "authenticated"
  WITH
    CHECK
    (((created_by = ( SELECT auth.uid() AS uid)) AND better_supabase.comment_message_readable(message_id, tenant_id) AND ( SELECT better_supabase.actor_may_write() AS
    actor_may_write)));

CREATE POLICY "bsb_tenant_scope_insert" ON "better_supabase"."comment_tasks"
  AS RESTRICTIVE
  FOR INSERT
  TO PUBLIC
  WITH
    CHECK
    (((tenant_id IN ( SELECT better_supabase.member_organization_ids() AS member_organization_ids)) OR ((created_by = ( SELECT auth.uid() AS uid)) AND
    better_supabase.comment_message_readable(message_id, tenant_id))));

